CREATE OR REPLACE FUNCTION "academy_private"."admin_story_reset"("p_from" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  order_list constant text[] := array['prologue','first_star','library_questions','dorm_first_plan','post_first_letter','sky_first_light','library_reading'];
  pos int;
  chapters text[];
  n_chapters int := 0; n_other int := 0; n int;
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode='42501'; end if;
  if not exists(select 1 from public.profiles where id=u and role='admin') then raise exception '관리자만 이야기를 다시 실행할 수 있어요.' using errcode='42501'; end if;
  pos := array_position(order_list, p_from);
  if pos is null then raise exception '다시 시작할 장을 골라 주세요.'; end if;
  chapters := order_list[greatest(pos, 2):7];
  perform pg_advisory_xact_lock(hashtextextended('academy-story-reset:'||u::text,0));
  delete from public.academy_chapters where user_id=u and chapter = any(chapters);
  get diagnostics n_chapters = row_count;
  if pos <= 3 then -- 제2장(도서관)까지 거슬러 가면 도서관 퀘스트 진행도 처음으로
    delete from public.academy_game_progress where user_id=u; get diagnostics n = row_count; n_other := n_other + n;
  end if;
  if pos <= 2 then -- 제1장부터면 튜토리얼도
    delete from public.academy_tutorials where user_id=u; get diagnostics n = row_count; n_other := n_other + n;
  end if;
  if pos = 1 then
    delete from public.academy_prologues where user_id=u; get diagnostics n = row_count; n_other := n_other + n;
  end if;
  return jsonb_build_object('from', p_from, 'chapters', n_chapters, 'other', n_other);
end $$;


ALTER FUNCTION "academy_private"."admin_story_reset"("p_from" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."are_friends"("a" "uuid", "b" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select a is not null and b is not null and a<>b and exists(
    select 1 from public.academy_friendships f
    where f.status='accepted' and least(f.requester_id,f.addressee_id)=least(a,b) and greatest(f.requester_id,f.addressee_id)=greatest(a,b));
$$;


ALTER FUNCTION "academy_private"."are_friends"("a" "uuid", "b" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."award_chapter_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare awarded integer;
begin
 if new.completed_at is null or not exists(select 1 from public.profiles where id=new.user_id and role in ('student','teacher','admin')) then return new; end if;
 insert into public.academy_chapter_rewards(user_id,chapter,amount) values(new.user_id,new.chapter,economy_private.num('academy.chapter_reward'))
 on conflict(user_id,chapter) do nothing returning amount into awarded;
 if awarded is not null then
   insert into public.academy_user_stats(user_id) values(new.user_id) on conflict(user_id) do nothing;
   update public.academy_user_stats set coins=coins+awarded,updated_at=now() where user_id=new.user_id;
 end if;
 return new;
end $$;


ALTER FUNCTION "academy_private"."award_chapter_completion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."chapter_read"("p_student_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare u uuid:=auth.uid(); actor text; code text; c public.academy_chapters;

begin

 select role,academy_private.player_code(u) into actor,code from public.profiles where id=u;

 if u is null or actor is null or actor not in ('student','teacher','admin') then raise exception '학생 또는 관리자만 이야기를 열 수 있어요.' using errcode='42501'; end if;

 if p_student_code is not null then

   if actor<>'admin' then raise exception '다른 학생의 이야기는 열 수 없어요.' using errcode='42501'; end if;

   select id,split_part(email,'@',1) into u,code from public.profiles where role='student' and split_part(email,'@',1)=p_student_code order by id limit 1;

   if u is null then raise exception '학생 계정을 확인해 주세요.'; end if;

 end if;

 select * into c from public.academy_chapters where user_id=u and chapter='first_star';

 return jsonb_build_object('chapter',case when c.user_id is null then null else (to_jsonb(c)||jsonb_build_object('design_id',case when c.trial_design_id is not null then 'trial:'||c.trial_design_id::text else c.design_id::text end)) end,

 'library',(select to_jsonb(l) from public.academy_chapters l where l.user_id=u and l.chapter='library_questions'),

 

 'dorm',(select to_jsonb(x) from public.academy_chapters x where x.user_id=u and x.chapter='dorm_first_plan'),

 'dormGoals',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'title',g.title)) from public.academy_user_goals g join public.academy_chapters x on x.user_id=g.user_id and x.chapter='dorm_first_plan' where g.user_id=u and g.created_at>=x.started_at and not g.is_archived and char_length(btrim(coalesce(g.description,'')))>0),'[]'::jsonb),

 'dormPlans',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title)) from public.academy_tasks t join public.academy_chapters x on x.user_id=t.user_id and x.chapter='dorm_first_plan' where t.user_id=u and t.created_at>=x.started_at and t.related_goal_id=x.goal_id and t.start_time is not null and t.end_time is not null),'[]'::jsonb),

 
 'post',(select to_jsonb(x) from public.academy_chapters x where x.user_id=u and x.chapter='post_first_letter'),
 'postLetter',(select jsonb_build_object('id',n.id,'title',n.title) from public.ai_news n where n.id=coalesce((select news_id from public.academy_chapters where user_id=u and chapter='post_first_letter'),academy_private.latest_chapter_letter()) and n.keep),
 'postNoteReady',exists(select 1 from public.academy_chapters x join public.world_news_inquiries i on i.user_id=x.user_id and i.news_id=x.news_id where x.user_id=u and x.chapter='post_first_letter' and x.read_at is not null and i.updated_at>=x.read_at and char_length(btrim(i.question))>0),
 
 'skyEligibility',academy_private.sky_eligibility(u),
 'reading',(select to_jsonb(r) from public.academy_chapters r where r.user_id=u and r.chapter='library_reading'),
 'readingCards',coalesce((select jsonb_agg(to_jsonb(k) order by k.updated_at desc) from (select * from public.academy_reading_cards k where k.user_id=u order by k.updated_at desc limit 30) k),'[]'::jsonb),
 'sky',(select to_jsonb(x) from public.academy_chapters x where x.user_id=u and x.chapter='sky_first_light'),
 'skyDormPracticed',exists(select 1 from public.academy_chapters dorm_chapter join public.academy_tasks t on t.id=dorm_chapter.task_id and t.user_id=u where dorm_chapter.user_id=u and dorm_chapter.chapter='dorm_first_plan' and t.completed),
 'designs',case when code like 'experience:%' then coalesce((select jsonb_agg(jsonb_build_object('id','trial:'||r.id::text,'title',r.data->>'title')) from public.academy_experience_records r where r.owner_id=u and r.kind='design' and r.data->>'status' in ('saved','observed') and r.created_at>=c.started_at and char_length(btrim(r.data->>'student_rationale'))>=10),'[]'::jsonb) else coalesce((select jsonb_agg(to_jsonb(d)) from (select id,title from public.student_inquiry_designs where student_id=code and status in ('saved','observed') and created_at>=c.started_at and char_length(btrim(student_rationale))>=10 order by created_at desc limit 20) d),'[]'::jsonb) end);

end $$;


ALTER FUNCTION "academy_private"."chapter_read"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."chapter_write"("p_action" "text", "p_revision" integer, "p_design" "uuid" DEFAULT NULL::"uuid", "p_has_stars" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare u uuid:=auth.uid(); code text; c public.academy_chapters; d public.student_inquiry_designs;

begin

 select academy_private.player_code(u) into code;

 if u is null or code is null then raise exception '학생 본인만 챕터를 진행할 수 있어요.' using errcode='42501'; end if;

 if p_revision is null or p_revision<0 or p_action is null or p_action not in ('next','arrive','observe','desk','design') then raise exception '이야기의 다음 행동을 확인해 주세요.'; end if;

 insert into public.academy_chapters(user_id) values(u) on conflict do nothing;

 select * into strict c from public.academy_chapters where user_id=u and chapter='first_star' for update;

 if c.revision<>p_revision or c.step=16 then return (to_jsonb(c)||jsonb_build_object('design_id',case when c.trial_design_id is not null then 'trial:'||c.trial_design_id::text else c.design_id::text end)); end if;

 if p_action='next' and c.step in (2,6,10,11) then raise exception '망원경과 연구대에서 실제 행동을 마친 뒤 이야기를 이어가세요.'; end if;

 if (p_action='arrive' and c.step<>2) or (p_action='observe' and c.step<>6) or (p_action='desk' and c.step<>10) or (p_action='design' and c.step<>11) then raise exception '현재 장면에서 다음 행동을 이어가세요.'; end if;

 if p_action='observe' and p_has_stars is null then raise exception '별자리를 살펴본 뒤 알려 주세요.'; end if;

 if p_action='design' then

   select * into d from academy_private.player_design(p_design,code);

   if not found or d.status not in ('saved','observed') or d.created_at<c.started_at or coalesce(char_length(btrim(d.student_rationale)),0)<10 then

     raise exception '이 챕터에서 내 이유와 함께 확정한 탐구 설계를 선택해 주세요.';

   end if;

 end if;

 update public.academy_chapters set step=step+1,revision=revision+1,updated_at=now(),

   has_stars=case when p_action='observe' then p_has_stars else has_stars end,

   trial_design_id=case when p_action='design' and code like 'experience:%' then d.id else trial_design_id end,
   design_id=case when p_action='design' and code not like 'experience:%' then d.id else design_id end,

   design_title=case when p_action='design' then d.title else design_title end,

   completed_at=case when step=15 then now() else completed_at end

 where user_id=u and chapter='first_star' returning * into c;

 return (to_jsonb(c)||jsonb_build_object('design_id',case when c.trial_design_id is not null then 'trial:'||c.trial_design_id::text else c.design_id::text end));

end $$;


ALTER FUNCTION "academy_private"."chapter_write"("p_action" "text", "p_revision" integer, "p_design" "uuid", "p_has_stars" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."constellation_edge_props"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_strip_nulls(jsonb_build_object('layer',
    case when jsonb_typeof(n->'layer')='string' then n->'layer' when jsonb_typeof(n->'source')='string' then n->'source' end))
  from (select case when jsonb_typeof(p->'properties')='object' then (p-'properties')||(p->'properties') else coalesce(p,'{}'::jsonb) end n) x;
$$;


ALTER FUNCTION "academy_private"."constellation_edge_props"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."constellation_props"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'field', case when jsonb_typeof(n->'field')='string' then n->'field' end,
    'grade', (select min(g) from (
        select nullif(left(regexp_replace(s->>'grade','[^0-9]','','g'),2),'')::int g
          from jsonb_array_elements(case when jsonb_typeof(n->'sources')='array' then n->'sources' else '[]'::jsonb end) s
         where jsonb_typeof(s)='object'
        union all select nullif(left(regexp_replace(n->'source'->>'grade','[^0-9]','','g'),2),'')::int where jsonb_typeof(n->'source')='object'
        union all select nullif(left(regexp_replace(n->>'grade','[^0-9]','','g'),2),'')::int where jsonb_typeof(n->'grade') in ('string','number')
      ) t where g between 1 and 6)))
  from (select case when jsonb_typeof(p->'properties')='object' then (p-'properties')||(p->'properties') else coalesce(p,'{}'::jsonb) end n) x;
$$;


ALTER FUNCTION "academy_private"."constellation_props"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."dorm_chapter_write"("p_action" "text", "p_revision" integer, "p_record" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare u uuid:=auth.uid(); c public.academy_chapters; g public.academy_user_goals; t public.academy_tasks;

begin

 if u is null or not exists(select 1 from public.profiles where id=u and role in ('student','teacher','admin')) then raise exception '학생 본인만 챕터를 진행할 수 있어요.' using errcode='42501'; end if;

 if p_action is null or p_action not in ('start','next','arrive','goal','plan') or p_revision is null or p_revision<0 then raise exception '다음 행동을 확인해 주세요.'; end if;

 if not exists(select 1 from public.academy_chapters where user_id=u and chapter='library_questions' and completed_at is not null) then raise exception '제2장을 마친 뒤 루온과 기숙사로 향해 주세요.'; end if;

 perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));

 if p_action='start' then insert into public.academy_chapters(user_id,chapter) values(u,'dorm_first_plan') on conflict do nothing; end if;

 select * into c from public.academy_chapters where user_id=u and chapter='dorm_first_plan' for update;

 if not found then raise exception '광장에서 루온과 이야기를 시작해 주세요.'; end if;

 if p_action='start' or c.revision<>p_revision or c.step=36 then return to_jsonb(c); end if;

 if (p_action='next' and c.step in (6,20,26)) or (p_action='arrive' and c.step<>6) or (p_action='goal' and c.step<>20) or (p_action='plan' and c.step<>26) then raise exception '지금 안내받은 행동을 마친 뒤 이야기를 이어가세요.'; end if;

 if p_action='goal' then

   select * into g from public.academy_user_goals where id=p_record and user_id=u for share;

   if not found or g.created_at<c.started_at or g.is_archived or char_length(btrim(coalesce(g.description,'')))=0 then raise exception '이 장에서 목표와 그 목표를 세운 이유를 함께 적어 주세요.'; end if;

 end if;

 if p_action='plan' then

   select * into t from public.academy_tasks where id=p_record and user_id=u for share;

   if not found or t.created_at<c.started_at or c.goal_id is null or t.related_goal_id is distinct from c.goal_id or t.start_time is null or t.end_time is null then raise exception '방금 세운 목표에 연결해 중요한 일과 시작·마침 시간을 정한 계획을 적어 주세요.'; end if; update public.academy_tasks set priority='high',updated_at=now() where id=t.id and priority is distinct from 'high';

 end if;

 update public.academy_chapters set step=step+1,revision=revision+1,updated_at=now(),

 goal_id=case when p_action='goal' then g.id else goal_id end,

 goal_title=case when p_action='goal' then g.title else goal_title end,

 task_id=case when p_action='plan' then t.id else task_id end,

 task_title=case when p_action='plan' then t.title else task_title end,

 completed_at=case when step=35 then now() else completed_at end

 where user_id=u and chapter='dorm_first_plan' returning * into c;

 return to_jsonb(c);

end $$;


ALTER FUNCTION "academy_private"."dorm_chapter_write"("p_action" "text", "p_revision" integer, "p_record" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."dormitory_read"("p_date" "date", "p_student_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare u uuid:=auth.uid(); actor_role text;

begin

 select role into actor_role from public.profiles where id=u;

 if u is null or actor_role not in ('student','teacher','admin') or actor_role is null then raise exception '학생 또는 관리자만 열 수 있어요.' using errcode='42501'; end if;

 if p_student_code is not null then

  if actor_role<>'admin' then raise exception '다른 학생의 기록을 열 수 없어요.' using errcode='42501'; end if;

  select p.id into u from public.profiles p where p.role='student' and split_part(p.email,'@',1)=p_student_code and exists(select 1 from public.student_basic_info s where s.id=p_student_code) order by p.id limit 1;

 end if;

 if p_date is null then raise exception '날짜가 필요해요.'; end if;

 return jsonb_build_object(

 'tasks',coalesce((select jsonb_agg(to_jsonb(t)||jsonb_build_object('feedback',(select f.comment from public.academy_task_feedback f where f.task_id=t.id and f.user_id=u order by f.created_at desc,f.id desc limit 1)) order by start_time nulls last,created_at) from public.academy_tasks t where user_id=u and task_date between p_date-3 and p_date+3),'[]'::jsonb),

 'plans',academy_private.sky_plans(u),'sky_regions',coalesce((select jsonb_agg(jsonb_build_object('region',r.region,'name',r.name,'revision',r.revision) order by r.region) from public.academy_sky_regions r where r.user_id=u),'[]'::jsonb),'goals',coalesce((select jsonb_agg(to_jsonb(g) order by created_at desc) from public.academy_user_goals g where user_id=u),'[]'::jsonb),

 'items',coalesce((select jsonb_agg(to_jsonb(i)) from public.academy_user_items i where user_id=u),'[]'::jsonb),

 'catalog',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('is_commissioner',coalesce(i.academy_owner=u,false)) order by price,id) from public.academy_shop_items i where academy_owner is null or is_active or academy_owner=u or exists(select 1 from public.academy_user_items owned where owned.user_id=u and owned.item_id=i.id)),'[]'::jsonb),

 'coins',coalesce((select coins from public.academy_user_stats where user_id=u),case when u is null then 0 else 100 end),

 'rewarded_today',exists(select 1 from public.academy_planning_rewards where user_id=u and reward_date=(now() at time zone 'Asia/Seoul')::date));

end $$;


ALTER FUNCTION "academy_private"."dormitory_read"("p_date" "date", "p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."dormitory_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare u uuid:=auth.uid(); t public.academy_tasks; g public.academy_user_goals; g_horizon text; g_parent uuid;

 i public.academy_shop_items; balance integer; goal uuid; task_day date;

 start_at text; end_at text; reward_count integer:=0; result jsonb;

begin

 if u is null or not exists(select 1 from public.profiles where id=u and role in ('student','teacher','admin')) then

   raise exception '학생 본인만 기록할 수 있어요.' using errcode='42501'; end if;

 if p_action='purchase' then return academy_private.purchase_item((p_payload->>'item_id')::integer,(p_payload->>'expected_price')::integer); end if;

 -- Serialize all wallet/equipment/plan actions for one user, including first entry.

 perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));

 if p_action in ('purchase','equip','unequip','complete') then

   insert into public.academy_user_stats(user_id) values(u) on conflict(user_id) do nothing;

 end if;

 if p_action='save_task' then return academy_private.plan_write(p_payload); elsif p_action='archive_goal' then update public.academy_user_goals set is_archived=coalesce((p_payload->>'archived')::boolean,true),updated_at=now() where id=(p_payload->>'id')::uuid and user_id=u; if not found then raise exception '목표를 찾을 수 없어요.' using errcode='42501'; end if; elsif p_action='delete_task' then

   delete from public.academy_tasks where id=(p_payload->>'id')::uuid and user_id=u returning * into t;

   if not found then raise exception '계획을 찾을 수 없어요.' using errcode='42501'; end if;

 elsif p_action='complete' then

   update public.academy_tasks set completed=coalesce((p_payload->>'completed')::boolean,true),updated_at=now() where id=(p_payload->>'id')::uuid and user_id=u returning * into t;

   if not found then raise exception '계획을 찾을 수 없어요.' using errcode='42501'; end if;

   if t.completed and t.task_date=(now() at time zone 'Asia/Seoul')::date then

     insert into public.academy_planning_rewards(user_id,reward_date) values(u,t.task_date) on conflict do nothing;

     get diagnostics reward_count=row_count;

     if reward_count=1 then update public.academy_user_stats set coins=coins+economy_private.num('academy.planning_reward'),updated_at=now() where user_id=u;
       -- 2026-10-21 플래너 «한 주에 N일» — «오늘 완료»가 그 주 N번째로 찍힌 순간 한 번(원장 유일 키 = 주 시작일)
       if (select count(*) from public.academy_planning_rewards r where r.user_id=u
             and r.reward_date >= date_trunc('week',t.task_date::timestamp)::date and r.reward_date < date_trunc('week',t.task_date::timestamp)::date+7)
          = economy_private.num('planner.week_days') then
         perform wallet_private.apply(u,economy_private.num('planner.week_reward'),'planner_week','planner',date_trunc('week',t.task_date::timestamp)::date::text,false,'플래너 한 주 꾸준함');
       end if;
     end if;
     -- 2026-10-21 «미리 세운 계획» — 전날까지 적어 둔 계획을 그날 완료하면 계획마다 한 번, 하루 N개까지(원장 유일 키 = 계획 id)
     if (t.created_at at time zone 'Asia/Seoul')::date < t.task_date
        and (select count(*) from public.wallet_ledger l where l.user_id=u and l.kind='planner_ahead' and l.earned_on=t.task_date) < economy_private.num('planner.ahead_cap') then
       perform wallet_private.apply(u,economy_private.num('planner.ahead_reward'),'planner_ahead','planner',t.id::text,false,'미리 세운 계획 완료');
     end if;

   end if;

 

 elsif p_action='complete_goal' then

   update public.academy_user_goals set is_completed=coalesce((p_payload->>'completed')::boolean,true),

     completed_at=case when coalesce((p_payload->>'completed')::boolean,true) then coalesce(completed_at,now()) else null end,

     updated_at=now()

   where id=(p_payload->>'id')::uuid and user_id=u returning * into g;

   if not found then raise exception '목표를 찾을 수 없어요.' using errcode='42501'; end if;

 elsif p_action='delete_goal' then

   perform id from public.academy_user_goals where id=(p_payload->>'id')::uuid and user_id=u for update;

   if not found then raise exception '목표를 찾을 수 없어요.' using errcode='42501'; end if;

   update public.academy_chapters set step=20,revision=revision+1,goal_id=null,goal_title=null,updated_at=now()

   where user_id=u and chapter='dorm_first_plan' and goal_id=(p_payload->>'id')::uuid and step between 21 and 26;

   update public.academy_tasks set related_goal_id=null,updated_at=now() where related_goal_id=(p_payload->>'id')::uuid and user_id=u;

   delete from public.academy_user_goals where id=(p_payload->>'id')::uuid and user_id=u;

 elsif p_action='save_feedback' then

   perform id from public.academy_tasks where id=(p_payload->>'id')::uuid and user_id=u for update;

   if not found then raise exception '계획을 찾을 수 없어요.' using errcode='42501'; end if;

   if char_length(coalesce(p_payload->>'comment',''))>2000 then raise exception '피드백은 2,000자 이내로 적어 주세요.'; end if;

   -- Preserve prior feedback fields and history; edit only the latest own comment.

   update public.academy_task_feedback set comment=btrim(coalesce(p_payload->>'comment','')),updated_at=now()

   where id=(select f.id from public.academy_task_feedback f where f.task_id=(p_payload->>'id')::uuid and f.user_id=u order by f.created_at desc,f.id desc limit 1);

   if not found then insert into public.academy_task_feedback(user_id,task_id,comment) values(u,(p_payload->>'id')::uuid,btrim(coalesce(p_payload->>'comment',''))); end if;

 elsif p_action='save_goal' then
   if length(btrim(coalesce(p_payload->>'title',''))) not between 1 and 200 or length(coalesce(p_payload->>'description',''))>2000 then raise exception '목표 제목과 설명 길이를 확인해 주세요.'; end if;
   -- 장기·단기 목표(2026-10-03): 고칠 때 payload 에 없는 칸은 지금 값을 지킨다.
   if nullif(p_payload->>'id','') is not null then
     select * into g from public.academy_user_goals where id=(p_payload->>'id')::uuid and user_id=u for update;
     if not found then raise exception '목표를 찾을 수 없어요.' using errcode='42501'; end if;
   end if;
   g_horizon := case when p_payload ? 'horizon' then (case when p_payload->>'horizon'='long' then 'long' else 'short' end) else coalesce(g.horizon,'short') end;
   g_parent := case when p_payload ? 'parent_goal_id' then nullif(p_payload->>'parent_goal_id','')::uuid else g.parent_goal_id end;
   if g_horizon='long' then g_parent := null; end if;
   if g_parent is not null and (g_parent is not distinct from g.id or not exists(select 1 from public.academy_user_goals where id=g_parent and user_id=u and horizon='long' and not is_archived)) then
     raise exception '단기 목표를 묶을 나의 장기 목표를 골라 주세요.' using errcode='42501';
   end if;
   if g.id is not null and g_horizon='short' and exists(select 1 from public.academy_user_goals where parent_goal_id=g.id and user_id=u) then
     raise exception '이 장기 목표에 묶인 단기 목표가 있어요. 단기 목표를 먼저 다른 곳으로 옮겨 주세요.';
   end if;
   if g.id is null then
     insert into public.academy_user_goals(user_id,title,description,horizon,parent_goal_id) values(u,btrim(p_payload->>'title'),p_payload->>'description',g_horizon,g_parent) returning * into g;
   else
     update public.academy_user_goals set title=btrim(p_payload->>'title'),description=p_payload->>'description',is_completed=coalesce((p_payload->>'is_completed')::boolean,false),completed_at=case when (p_payload->>'is_completed')::boolean then coalesce(completed_at,now()) else null end,horizon=g_horizon,parent_goal_id=g_parent,updated_at=now() where id=g.id and user_id=u returning * into g;
   end if;
   return to_jsonb(g);

 elsif p_action in ('equip','unequip') then

   select * into i from public.academy_shop_items where id=(p_payload->>'item_id')::integer and academy_slot is not null;

   if not found then raise exception '이 상품은 아카데미에서 사용할 수 없어요.'; end if;

     if not exists(select 1 from public.academy_user_items where user_id=u and item_id=i.id) then raise exception '보유한 물건만 사용할 수 있어요.' using errcode='42501'; end if;

     if p_action='equip' then

       update public.academy_user_items a set is_equipped=false from public.academy_shop_items b where a.item_id=b.id and a.user_id=u and b.academy_slot=i.academy_slot;

     end if;

     update public.academy_user_items set is_equipped=(p_action='equip') where user_id=u and item_id=i.id;

 else raise exception '알 수 없는 행동이에요.'; end if;

 return jsonb_build_object('ok',true,'reward',reward_count*5);

end $$;


ALTER FUNCTION "academy_private"."dormitory_write"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."encouragement_read"("p_student_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); actor text;
begin
 select role into actor from public.profiles where id=u;
 if u is null or actor is null or actor not in ('student','teacher','admin') then raise exception 'Student or administrator required' using errcode='42501'; end if;
 if p_student_code is not null then
  if actor<>'admin' then raise exception 'Cannot preview another student' using errcode='42501'; end if;
  select p.id into u from public.profiles p where p.role='student' and split_part(p.email,'@',1)=p_student_code and exists(select 1 from public.student_basic_info s where s.id=p_student_code) order by p.id limit 1;
 end if;
 return jsonb_build_object('day',(now() at time zone 'Asia/Seoul')::date,'entries',coalesce((select jsonb_agg(to_jsonb(x)-'lease_token' order by day desc) from (select * from public.academy_luon_encouragements where user_id=u order by day desc limit 30) x),'[]'::jsonb));
end $$;


