CREATE OR REPLACE FUNCTION "academy_private"."friend_code_for"("p_user" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c text; alphabet constant text:='ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; b bytea; i int;
begin
  select friend_code into c from public.academy_friend_profiles where user_id=p_user;
  if c is not null then return c; end if;
  loop
    b:=extensions.gen_random_bytes(8); c:='';
    for i in 0..7 loop c:=c||substr(alphabet,(get_byte(b,i)%32)+1,1); end loop;
    begin
      insert into public.academy_friend_profiles(user_id,friend_code) values(p_user,c);
      return c;
    exception when unique_violation then
      select friend_code into c from public.academy_friend_profiles where user_id=p_user;
      if c is not null then return c; end if; -- 같은 사람이 동시에 만든 경우
    end;
  end loop;
end $$;


ALTER FUNCTION "academy_private"."friend_code_for"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."friend_constellation"("p_friend" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); code text; v uuid; vno int; engine text;
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode='42501'; end if;
  if not (academy_private.friend_student(u) and academy_private.are_friends(u,p_friend)) then
    raise exception '친구의 망원경만 구경할 수 있어요.' using errcode='42501';
  end if;
  if not coalesce((select share_telescope from public.academy_friend_profiles where user_id=p_friend),false) then
    raise exception '친구가 아직 망원경을 열어 두지 않았어요.' using errcode='42501';
  end if;
  select split_part(email,'@',1) into code from public.profiles where id=p_friend;
  select id,version,left(kg_json->'source_stats'->>'extraction_engine',80) into v,vno,engine
    from public.student_kg_versions where student_id=code order by version desc limit 1;
  if v is null then return jsonb_build_object('version_id',null,'version',null,'engine',null,'entities','[]'::jsonb,'relations','[]'::jsonb); end if;
  return jsonb_build_object('version_id',v,'version',vno,'engine',engine,
    'entities',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'entity_id',e.entity_id,'label',e.label,'type',e.type,'properties',academy_private.constellation_props(e.properties)))
        from public.student_kg_entities e where e.student_id=code and e.kg_version_id=v),'[]'::jsonb),
    'relations',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'source_entity_id',r.source_entity_id,'target_entity_id',r.target_entity_id,'relation_type',r.relation_type,'properties',academy_private.constellation_edge_props(r.properties)))
        from public.student_kg_relations r where r.student_id=code and r.kg_version_id=v),'[]'::jsonb));
end $$;


