$$;


ALTER FUNCTION "academy_private"."friend_notify"("p_user" "uuid", "p_type" "text", "p_title" "text", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."friend_notify"("p_user" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_surface" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r uuid; s text := case when p_surface = 'tamagotchi' then 'tamagotchi' else 'academy' end;
begin
  select res.id into r from public.profiles p
    join public.resource res on res.type='student' and res.status='active' and res.meta->>'id'=split_part(p.email,'@',1)
   where p.id=p_user limit 1;
  -- 선생님(2026-11-06) — 연결된 교직원 자리
  if r is null then
    select ur.resource_id into r from public.user_resource ur join public.resource res on res.id = ur.resource_id
     where ur.user_id = p_user and res.type in ('teacher','staff') limit 1;
  end if;
  if r is null then return; end if;
  insert into public.notification_events(resource_id,type,title,message,meta)
  values(r,p_type,p_title,p_message,jsonb_build_object(
    'link', case s when 'tamagotchi' then '/tamagotchi?friends=requests' else '/academy?friends=1' end,
    'surface', s));
end $$;


ALTER FUNCTION "academy_private"."friend_notify"("p_user" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_surface" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."friend_room"("p_friend" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); admin boolean:=academy_private.workshop_admin();
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode='42501'; end if;
  if p_friend is null or not academy_private.friend_student(p_friend) then raise exception '방문할 친구를 선택해 주세요.'; end if;
  if not (p_friend=u or admin or (academy_private.friend_student(u) and academy_private.are_friends(u,p_friend))) then
    raise exception '친구의 방만 방문할 수 있어요.' using errcode='42501';
  end if;
  return jsonb_build_object(
    'owner',jsonb_build_object('id',p_friend,'name',academy_private.friend_name(p_friend),
      'share_telescope',coalesce((select share_telescope from public.academy_friend_profiles where user_id=p_friend),false)),
    'outfit',coalesce((select jsonb_object_agg(i.academy_slot,jsonb_build_object('asset',i.academy_asset,'image_path',i.image_url))
        from public.academy_user_items o join public.academy_shop_items i on i.id=o.item_id
       where o.user_id=p_friend and o.is_equipped and i.academy_slot in ('room','ria')),'{}'::jsonb),
    'guestbook',coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
        select jsonb_build_object('id',g.id,'author_id',g.author_id,'author_name',academy_private.friend_name(g.author_id),'body',g.body,
          'created_at',g.created_at,'can_delete',(g.author_id=u or g.owner_id=u or admin)) x
          from public.academy_guestbook_entries g where g.owner_id=p_friend order by g.created_at desc limit 50) s),'[]'::jsonb));
end $$;


