CREATE OR REPLACE FUNCTION "academy_private"."friends_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); code text; share boolean;
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode='42501'; end if;
  if not academy_private.friend_student(u) then
    return jsonb_build_object('eligible',false,'admin',academy_private.workshop_admin());
  end if;
  code:=academy_private.friend_code_for(u);
  select share_telescope into share from public.academy_friend_profiles where user_id=u;
  return jsonb_build_object('eligible',true,'admin',academy_private.workshop_admin(),'code',code,'share_telescope',coalesce(share,false),
    'friends',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'name',coalesce(nullif(btrim(o.name),''),'학생'),'since',f.responded_at,'share_telescope',coalesce(fp.share_telescope,false)) order by o.name)
        from public.academy_friendships f
        join public.profiles o on o.id=case when f.requester_id=u then f.addressee_id else f.requester_id end
        left join public.academy_friend_profiles fp on fp.user_id=o.id
       where f.status='accepted' and u in (f.requester_id,f.addressee_id)),'[]'::jsonb),
    'incoming',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'user_id',o.id,'name',coalesce(nullif(btrim(o.name),''),'학생'),'created_at',f.created_at) order by f.created_at desc)
        from public.academy_friendships f join public.profiles o on o.id=f.requester_id
       where f.status='pending' and f.addressee_id=u),'[]'::jsonb),
    'outgoing',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'user_id',o.id,'name',coalesce(nullif(btrim(o.name),''),'학생'),'created_at',f.created_at) order by f.created_at desc)
        from public.academy_friendships f join public.profiles o on o.id=f.addressee_id
       where f.status='pending' and f.requester_id=u),'[]'::jsonb));
end $$;


ALTER FUNCTION "academy_private"."friends_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."friends_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$

declare u uuid:=auth.uid(); target uuid; f public.academy_friendships; code text; n int; share boolean;

  surface text := case when p_payload->>'from' = 'tamagotchi' then 'tamagotchi' else 'academy' end;

  place text := case when p_payload->>'from' = 'tamagotchi' then '다마고찌' else '별빛 아카데미' end;

begin

  if u is null or not academy_private.friend_student(u) then raise exception '친구 기능은 학생·선생님만 쓸 수 있어요.' using errcode='42501'; end if;

  perform academy_private.friend_code_for(u);

  perform pg_advisory_xact_lock(hashtextextended('academy-friends:'||u::text,0));

  if p_action='request' then

    code:=upper(regexp_replace(coalesce(p_payload->>'code',''),'[^A-Za-z0-9]','','g'));

    if code !~ '^[A-HJ-NP-Z2-9]{8}$' then raise exception '친구 코드 8자리를 확인해 주세요.'; end if;

    select user_id into target from public.academy_friend_profiles where friend_code=code;

    if target is null or not academy_private.friend_student(target) then raise exception '그 코드의 친구를 찾지 못했어요. 코드를 다시 확인해 주세요.'; end if;

    if target=u then raise exception '내 친구 코드예요. 친구의 코드를 적어 주세요.'; end if;

    select * into f from public.academy_friendships

     where least(requester_id,addressee_id)=least(u,target) and greatest(requester_id,addressee_id)=greatest(u,target) for update;

    if found then

      if f.status='accepted' then raise exception '이미 친구예요.'; end if;

      if f.requester_id=u then raise exception '이미 친구 요청을 보냈어요. 친구가 받아 주기를 기다려 주세요.'; end if;

      -- 상대가 먼저 보낸 요청이 있으면 서로 원하는 것이므로 곧바로 친구가 된다.

      update public.academy_friendships set status='accepted',responded_at=now() where id=f.id;

      perform academy_private.friend_notify(target,'academy_friend_accepted',place||' · 친구가 되었어요',academy_private.friend_label(u)||'과 친구가 되었어요.',surface);

      return jsonb_build_object('status','accepted','name',academy_private.friend_name(target));

    end if;

    select count(*) into n from public.academy_friendships where requester_id=u and status='pending';

    if n>=20 then raise exception '아직 받지 않은 친구 요청이 20개예요. 몇 개를 취소한 뒤 다시 보내 주세요.'; end if;

    select count(*) into n from public.academy_friendships where status='accepted' and u in (requester_id,addressee_id);

    if n>=100 then raise exception '친구는 100명까지 맺을 수 있어요.'; end if;

    insert into public.academy_friendships(requester_id,addressee_id) values(u,target);

    perform academy_private.friend_notify(target,'academy_friend_request',place||' · 친구 요청',academy_private.friend_label(u)||'이 친구가 되고 싶어 해요.',surface);

    return jsonb_build_object('status','pending','name',academy_private.friend_name(target));

  elsif p_action='respond' then

    select * into f from public.academy_friendships where id=(p_payload->>'id')::uuid and addressee_id=u and status='pending' for update;

    if not found then raise exception '받은 친구 요청을 찾지 못했어요.'; end if;

    if coalesce((p_payload->>'accept')::boolean,false) then

      select count(*) into n from public.academy_friendships where status='accepted' and u in (requester_id,addressee_id);

      if n>=100 then raise exception '친구는 100명까지 맺을 수 있어요.'; end if;

      update public.academy_friendships set status='accepted',responded_at=now() where id=f.id;

      perform academy_private.friend_notify(f.requester_id,'academy_friend_accepted',place||' · 친구가 되었어요',academy_private.friend_label(u)||'이 친구 요청을 받아 주었어요.',surface);

      return jsonb_build_object('status','accepted');

    end if;

    delete from public.academy_friendships where id=f.id; -- 거절은 알리지 않는다

    return jsonb_build_object('status','declined');

  elsif p_action='cancel' then

    delete from public.academy_friendships where id=(p_payload->>'id')::uuid and requester_id=u and status='pending';

    if not found then raise exception '보낸 친구 요청을 찾지 못했어요.'; end if;

    return jsonb_build_object('status','cancelled');

  elsif p_action='remove' then

    target:=(p_payload->>'user_id')::uuid;

    delete from public.academy_friendships

     where status='accepted' and least(requester_id,addressee_id)=least(u,target) and greatest(requester_id,addressee_id)=greatest(u,target);

    if not found then raise exception '친구 목록에서 찾지 못했어요.'; end if;

    return jsonb_build_object('status','removed');

  elsif p_action='share' then

    update public.academy_friend_profiles set share_telescope=coalesce((p_payload->>'on')::boolean,false),updated_at=now()

     where user_id=u returning share_telescope into share;

    return jsonb_build_object('share_telescope',share);

  elsif p_action='reset_code' then

    -- 코드가 퍼졌을 때 — 새 코드를 만들고 공개 설정은 그대로 둔다. 이미 맺은 친구는 그대로다.

    delete from public.academy_friend_profiles where user_id=u returning share_telescope into share;

    code:=academy_private.friend_code_for(u);

    update public.academy_friend_profiles set share_telescope=coalesce(share,false) where user_id=u;

    return jsonb_build_object('code',code);

  end if;

  raise exception '친구 목록에서 할 일을 선택해 주세요.';

end $_$;


ALTER FUNCTION "academy_private"."friends_write"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."guestbook_admin_read"("p_limit" integer DEFAULT 100, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not academy_private.workshop_admin() then raise exception '관리자만 볼 수 있어요.' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
    select jsonb_build_object('id',g.id,'owner_id',g.owner_id,'owner_name',academy_private.friend_name(g.owner_id),
      'author_id',g.author_id,'author_name',academy_private.friend_name(g.author_id),'body',g.body,'created_at',g.created_at) x
      from public.academy_guestbook_entries g
     where p_before is null or g.created_at<p_before
     order by g.created_at desc limit least(greatest(coalesce(p_limit,100),1),200)) s),'[]'::jsonb);
end $$;


ALTER FUNCTION "academy_private"."guestbook_admin_read"("p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."guestbook_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); owner uuid; body text; n int; g public.academy_guestbook_entries;
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode='42501'; end if;
  if p_action='write' then
    owner:=(p_payload->>'owner_id')::uuid;
    if not (academy_private.friend_student(u) and (owner=u or academy_private.are_friends(u,owner))) then
      raise exception '친구의 방명록에만 글을 남길 수 있어요.' using errcode='42501';
    end if;
    body:=btrim(coalesce(p_payload->>'body',''));
    if char_length(body) not between 1 and 200 then raise exception '방명록은 1자에서 200자까지 적을 수 있어요.'; end if;
    perform pg_advisory_xact_lock(hashtextextended('academy-guestbook:'||u::text,0));
    select count(*) into n from public.academy_guestbook_entries
     where author_id=u and owner_id=owner and created_at>=((now() at time zone 'Asia/Seoul')::date::timestamp at time zone 'Asia/Seoul');
    if n>=5 then raise exception '한 친구의 방명록에는 하루에 다섯 번까지 남길 수 있어요.'; end if;
    insert into public.academy_guestbook_entries(owner_id,author_id,body) values(owner,u,body) returning * into g;
    if owner<>u then
      perform academy_private.friend_notify(owner,'academy_guestbook','별빛 아카데미 · 방명록',academy_private.friend_label(u)||'이 기숙사 방명록에 글을 남겼어요.');
    end if;
    return jsonb_build_object('id',g.id,'author_id',g.author_id,'author_name',academy_private.friend_name(u),'body',g.body,'created_at',g.created_at,'can_delete',true);
  elsif p_action='delete' then
    delete from public.academy_guestbook_entries
     where id=(p_payload->>'id')::uuid and (author_id=u or owner_id=u or academy_private.workshop_admin());
    if not found then raise exception '지울 수 있는 방명록을 찾지 못했어요.' using errcode='42501'; end if;
    return jsonb_build_object('status','deleted');
  end if;
  raise exception '방명록에서 할 일을 선택해 주세요.';
end $$;


ALTER FUNCTION "academy_private"."guestbook_write"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."journey_write"("p_action" "text", "p_revision" integer DEFAULT 0, "p_activity" "uuid" DEFAULT NULL::"uuid", "p_reflection" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := auth.uid(); j public.academy_journeys; code text; owner_code text; first_record public.academy_game_progress;
begin
  if u is null or not exists(select 1 from public.profiles where id=u and role in ('student','teacher','admin')) then raise exception '본인 계정에서 연속 탐구를 진행해 주세요.' using errcode='42501'; end if;
  code := academy_private.player_code(u);
  if code is null or code='' then raise exception '계정을 확인해 주세요.' using errcode='42501'; end if;
  owner_code := case when code like 'experience:%' then '00-00001' else code end; -- 교직원 체험 = 견본 학생의 활동
  if p_action not in ('start','observe','complete','abandon') then raise exception '연속 탐구에서 할 일을 골라 주세요.'; end if;
  perform pg_advisory_xact_lock(hashtextextended('academy-journey:'||u::text,0));

  if p_action='abandon' then
    delete from public.academy_journeys where user_id=u;
    return jsonb_build_object('deleted', true);
  end if;

  if p_action='start' then
    select * into first_record from public.academy_game_progress where user_id=u and quest_step='completed';
    if not found then
      select c.activity_id, left(c.question || chr(10) || '궁금해진 이유: ' || c.curiosity_reason, 2000) into first_record.activity_id, first_record.question
        from public.academy_chapters c where c.user_id=u and c.chapter='library_questions' and c.completed_at is not null;
      if not found then raise exception '제2장에서 질문을 기록한 뒤 연속 탐구를 시작할 수 있어요.'; end if;
    end if;
    insert into public.academy_journeys(user_id, source_question, source_activity_id) values(u, first_record.question, first_record.activity_id) on conflict do nothing;
  end if;

  select * into j from public.academy_journeys where user_id=u for update;
  if not found then raise exception '먼저 연속 탐구를 시작해 주세요.'; end if;
  if p_action='start' then return to_jsonb(j); end if;
  if j.revision <> coalesce(p_revision, -1) then raise exception '다른 창에서 연속 탐구가 바뀌었어요. 수첩을 다시 펼쳐 주세요.'; end if;
  if j.stage='completed' then raise exception '이미 마친 연속 탐구예요. 새로 시작하려면 지운 뒤 다시 시작해 주세요.'; end if;

  if p_action='observe' then
    if p_activity is null then raise exception '실제로 해 본 활동을 골라 주세요.'; end if;
    perform 1 from public.student_detailed_activities where id=p_activity and student_id=owner_code for share;
    if not found then raise exception '내 기록에 있는 활동만 연결할 수 있어요.' using errcode='42501'; end if;
    update public.academy_journeys set activity_id=p_activity, stage='observed', revision=revision+1, updated_at=now() where user_id=u returning * into j;
    return to_jsonb(j);
  end if;

  -- complete
  if j.stage<>'observed' or j.activity_id is null then raise exception '먼저 실제로 해 본 활동을 연결해 주세요.'; end if;
  if p_reflection is null or char_length(btrim(p_reflection)) not between 40 and 4000 then raise exception '발견과 생각의 변화를 40~4,000자로 적어 주세요.'; end if;
  if j.design_id is not null and code not like 'experience:%' then
    update public.student_inquiry_designs set reflection=btrim(p_reflection), updated_at=now() where id=j.design_id and student_id=code;
  elsif j.trial_design_id is not null and code like 'experience:%' then
    update public.academy_experience_records set data=data||jsonb_build_object('reflection',btrim(p_reflection)), updated_at=now() where id=j.trial_design_id and owner_id=u;
  end if;
  update public.academy_journeys set reflection=btrim(p_reflection), stage='completed', completed_at=now(), revision=revision+1, updated_at=now() where user_id=u returning * into j;
  return to_jsonb(j);
end $$;


ALTER FUNCTION "academy_private"."journey_write"("p_action" "text", "p_revision" integer, "p_activity" "uuid", "p_reflection" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."latest_chapter_letter"() RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select id from public.ai_news where keep and nullif(btrim(comic_path),'') is not null
 and comic_path !~ '^(/|[a-zA-Z]+:)' and position('..' in comic_path)=0
 order by published_at desc nulls last,id desc limit 1;
$$;


ALTER FUNCTION "academy_private"."latest_chapter_letter"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."library_chapter_write"("p_action" "text", "p_revision" integer, "p_activity" "uuid" DEFAULT NULL::"uuid", "p_question" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); c public.academy_chapters; activity_name text;
begin
 if u is null or not exists(select 1 from public.profiles where id=u and role in ('student','teacher','admin')) then raise exception '학생 본인만 챕터를 진행할 수 있어요.' using errcode='42501'; end if;
 if p_action is null or p_action not in ('start','next','arrive','read','note') or p_revision is null or p_revision<0 then raise exception '다음 행동을 확인해 주세요.'; end if;
 if not exists(select 1 from public.academy_chapters where user_id=u and chapter='first_star' and completed_at is not null) then raise exception '제1장을 마친 뒤 루온을 만나 주세요.'; end if;
 if p_action='start' then
   insert into public.academy_chapters(user_id,chapter) values(u,'library_questions') on conflict do nothing;
 end if;
 select * into c from public.academy_chapters where user_id=u and chapter='library_questions' for update;
 if not found then raise exception '광장에서 루온과 다음 이야기를 시작해 주세요.'; end if;
 if p_action='start' or c.revision<>p_revision or c.step=18 then return to_jsonb(c); end if;
 if (p_action='next' and c.step in (5,13,14)) or (p_action='arrive' and c.step<>5) or (p_action='read' and c.step<>13) or (p_action='note' and c.step<>14) then raise exception '지금 안내받은 행동을 마친 뒤 이야기를 이어가세요.'; end if;
 if p_action='read' then
   -- activity_select 정책의 세 분기 전부(교직원 · 학생-school · 참여자). 한 분기라도 빼면
   -- 책장에는 보이는데 서버가 거부하는 상태가 된다. DEFINER 라 정책이 자동 적용되지 않는다.
   select name into activity_name from public.activity a where a.id=p_activity
     and (public.is_teacher_or_admin(u) or (public.current_student_code() is not null and a.visibility='school') or public.is_activity_participant(a.id)) for share;
   if not found then raise exception '열람할 수 있는 책의 활동을 골라 주세요.' using errcode='42501'; end if;
 end if;
 if p_action='note' and (c.activity_id is null or coalesce(char_length(btrim(p_question)),0) not between 10 and 1000 or coalesce(char_length(btrim(p_reason)),0) not between 10 and 1000) then raise exception '책에서 고른 활동의 질문과 궁금해진 이유를 각각 10~1,000자로 적어 주세요.'; end if;
 update public.academy_chapters set step=step+1,revision=revision+1,updated_at=now(),
   activity_id=case when p_action='read' then p_activity else activity_id end,
   activity_title=case when p_action='read' then activity_name else activity_title end,
   question=case when p_action='note' then btrim(p_question) else question end,
   curiosity_reason=case when p_action='note' then btrim(p_reason) else curiosity_reason end,
   completed_at=case when step=17 then now() else completed_at end
 where user_id=u and chapter='library_questions' returning * into c;
 return to_jsonb(c);
end $$;


ALTER FUNCTION "academy_private"."library_chapter_write"("p_action" "text", "p_revision" integer, "p_activity" "uuid", "p_question" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."plan_write"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); p public.academy_plans; t public.academy_tasks;
 gid uuid:=nullif(p_payload->>'related_goal_id','')::uuid; pid uuid:=nullif(p_payload->>'plan_id','')::uuid;
 tid uuid:=nullif(p_payload->>'id','')::uuid; d date:=(p_payload->>'task_date')::date;
 s time:=nullif(p_payload->>'start_time','')::time; e time:=nullif(p_payload->>'end_time','')::time;
begin
 if u is null or not exists(select 1 from public.profiles where id=u and role in ('student','teacher','admin')) then raise exception '본인만 계획을 기록할 수 있어요.' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));
 if d is null or char_length(btrim(coalesce(p_payload->>'title',''))) not between 1 and 200 or char_length(coalesce(p_payload->>'memo',''))>2000 then raise exception '계획 제목, 날짜와 메모를 확인해 주세요.'; end if;
 if (s is null)<>(e is null) or s>=e then raise exception '같은 날의 시작·종료 시간을 확인해 주세요.'; end if;
 if gid is not null and not exists(select 1 from public.academy_user_goals where id=gid and user_id=u and not is_archived) then raise exception '나의 이어가는 목표를 선택해 주세요.' using errcode='42501'; end if;
 if tid is not null then
  select * into t from public.academy_tasks where id=tid and user_id=u for update;
  if not found then raise exception '실천 기록을 찾을 수 없어요.' using errcode='42501'; end if;
  if pid is not null and pid<>t.plan_id then raise exception '실천의 계획은 바꿀 수 없어요.'; end if;
  pid:=t.plan_id;
 end if;
 if pid is not null then
  select * into p from public.academy_plans where id=pid and user_id=u and not is_archived for update;
  if not found then raise exception '나의 계획을 선택해 주세요.' using errcode='42501'; end if;
  if gid is distinct from p.goal_id then
   if tid is null then raise exception '같은 계획의 별자리는 바꿀 수 없어요. 새 계획으로 적어 주세요.'; end if;
   if (select count(*) from public.academy_tasks where plan_id=pid and user_id=u)=1 then
    update public.academy_plans set goal_id=gid,updated_at=now() where id=pid returning * into p;
   else
    insert into public.academy_plans(user_id,goal_id,title,priority,default_start,default_end) values(u,gid,btrim(p_payload->>'title'),coalesce(p_payload->>'priority','medium'),s,e) returning * into p;
    pid:=p.id;
   end if;
  end if;
  update public.academy_plans set title=btrim(p_payload->>'title'),priority=coalesce(p_payload->>'priority','medium'),default_start=s,default_end=e,updated_at=now() where id=pid returning * into p;
  update public.academy_tasks set title=p.title,priority=p.priority,updated_at=now() where plan_id=pid and user_id=u;
 else
  insert into public.academy_plans(user_id,goal_id,title,priority,default_start,default_end) values(u,gid,btrim(p_payload->>'title'),coalesce(p_payload->>'priority','medium'),s,e) returning * into p;
 end if;
 if tid is null then
  insert into public.academy_tasks(user_id,plan_id,title,task_date,priority,related_goal_id,memo,start_time,end_time)
  values(u,p.id,p.title,d,p.priority,p.goal_id,p_payload->>'memo',s,e)
  on conflict(plan_id,task_date) do update set plan_id=excluded.plan_id returning * into t;
 else
  update public.academy_tasks set plan_id=p.id,title=p.title,priority=p.priority,related_goal_id=p.goal_id,task_date=d,memo=p_payload->>'memo',start_time=s,end_time=e,updated_at=now() where id=tid returning * into t;
 end if;
 return to_jsonb(t);
end $$;


ALTER FUNCTION "academy_private"."plan_write"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."planner_focus_read"("p_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); result jsonb;
begin
  if u is null or not exists(select 1 from public.profiles where id=u and role in ('student','teacher','admin')) then
    raise exception '본인의 집중 기록만 읽을 수 있습니다.' using errcode='42501';
  end if;
  if p_date is null then raise exception '날짜가 필요합니다.' using errcode='22023'; end if;
  select coalesce(jsonb_agg(to_jsonb(s) - 'user_id' - 'created_at' order by s.ended_at desc),'[]'::jsonb) into result
  from public.planner_focus_sessions s join public.academy_tasks t on t.id=s.task_id
  where s.user_id=u and t.user_id=u and t.task_date=p_date;
  return result;
end $$;


ALTER FUNCTION "academy_private"."planner_focus_read"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "academy_private"."planner_focus_record"("p_record" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  session_id uuid := (p_record->>'id')::uuid;
  task_id uuid := (p_record->>'task_id')::uuid;
  started timestamptz := (p_record->>'started_at')::timestamptz;
  ended timestamptz := (p_record->>'ended_at')::timestamptz;
  seconds integer := (p_record->>'focus_seconds')::integer;
  planned integer := (p_record->>'planned_seconds')::integer;
  complete boolean := (p_record->>'completed')::boolean;
  saved public.planner_focus_sessions;
begin
  if u is null or not exists(select 1 from public.profiles where id=u and role in ('student','teacher','admin')) then
    raise exception '본인의 집중 기록만 저장할 수 있습니다.' using errcode='42501';
  end if;
  perform id from public.academy_tasks where id=task_id and user_id=u for key share;
  if not found then raise exception '계획을 찾을 수 없습니다.' using errcode='42501'; end if;
  if session_id is null or started is null or ended is null or seconds is null or planned is null or complete is null
    or ended > clock_timestamp() + interval '1 minute' then
    raise exception '집중 기록의 시간과 길이를 확인해 주세요.' using errcode='22023';
  end if;
  insert into public.planner_focus_sessions(id,user_id,task_id,started_at,ended_at,focus_seconds,planned_seconds,completed)
  values(session_id,u,task_id,started,ended,seconds,planned,complete)
  on conflict(id) do nothing;
  select * into saved from public.planner_focus_sessions where id=session_id and user_id=u;
  if not found then raise exception '본인의 집중 기록만 저장할 수 있습니다.' using errcode='42501'; end if;
  if saved.task_id<>task_id or saved.started_at<>started or saved.ended_at<>ended or saved.focus_seconds<>seconds
    or saved.planned_seconds<>planned or saved.completed<>complete then
    raise exception '이미 저장된 집중 기록과 내용이 다릅니다.' using errcode='22023';
  end if;
  return to_jsonb(saved) - 'user_id' - 'created_at';
end $$;


ALTER FUNCTION "academy_private"."planner_focus_record"("p_record" "jsonb") OWNER TO "postgres";


