CREATE TABLE IF NOT EXISTS "public"."student_inquiry_designs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "text" NOT NULL,
    "title" "text" NOT NULL,
    "target_kind" "text" NOT NULL,
    "target_name" "text" NOT NULL,
    "target_ref" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "academic_year" integer NOT NULL,
    "grade" integer NOT NULL,
    "semester" integer,
    "status" "text" DEFAULT 'saved'::"text" NOT NULL,
    "selected_source_snapshot" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "llm_result" "jsonb",
    "student_rationale" "text" NOT NULL,
    "reflection" "text",
    "llm_token_usage" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "observed_activity_id" "uuid",
    "observed_at" timestamp with time zone,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "kg_version_id" "uuid",
    CONSTRAINT "student_inquiry_designs_grade_check" CHECK ((("grade" >= 1) AND ("grade" <= 3))),
    CONSTRAINT "student_inquiry_designs_semester_check" CHECK ((("semester" IS NULL) OR (("semester" >= 1) AND ("semester" <= 2)))),
    CONSTRAINT "student_inquiry_designs_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'proposed'::"text", 'analyzed'::"text", 'saved'::"text", 'observed'::"text", 'archived'::"text"]))),
    CONSTRAINT "student_inquiry_designs_target_kind_check" CHECK (("target_kind" = ANY (ARRAY['subject'::"text", 'club'::"text", 'autonomous'::"text", 'career'::"text"])))
);

