    'status', r.status,
    'status_text', case r.status when 'sent' then '받음(아직 안 넘김)' when 'handed' then '에이전트에게 넘김'
                      when 'done' then '완료' when 'declined' then '거절' else '취소됨' end,
    'due_date', to_char(r.due_date, 'YYYY-MM-DD'),
    'handed_to', r.handed_to,
    'result', r.result,
    'at', to_char(r.created_at at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI'),
    'closed_at', to_char(r.closed_at at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI'))
  || case when p_full then jsonb_build_object('body', r.body, 'steps', r.steps, 'refs', r.refs)
          else jsonb_build_object('summary', left(r.body, 160)) end;
$$;


