CREATE OR REPLACE FUNCTION "automation_private"."closed_day_reason"("p_date" "date") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when extract(isodow from p_date) >= 6 then '주말'
    else (
      select btrim(m.meta->>'title')
      from meeting m
      where m.kind = 'schedule'
        and coalesce(btrim(m.meta->>'title'), '') <> ''
        and m.meta->>'sbtr_dd_sc_nm' in ('휴업일', '공휴일')
        and btrim(m.meta->>'title') <> '토요휴업일'
        and (jsonb_typeof(m.meta->'no_class_grades') is distinct from 'array'
             or jsonb_array_length(m.meta->'no_class_grades') = 0
             or jsonb_array_length(m.meta->'no_class_grades') >= 3)
        and (m.starts_at at time zone 'Asia/Seoul')::date <= p_date
        -- 끝이 다음 날 00:00 정각이면 그날은 포함하지 않는다(expandScheduleRows 와 같다)
        and ((m.ends_at - interval '1 millisecond') at time zone 'Asia/Seoul')::date >= p_date
      order by m.starts_at
      limit 1)
  end;
$$;


