CREATE OR REPLACE FUNCTION "automation_private"."config_valid"("p_kind" "text", "p_config" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'automation_private', 'pg_temp'
    AS $_$
declare
  v_mode text := p_config->>'body_mode';
  v_tok text;
  v_people jsonb := p_config->'recipients'->'people';
  v_rule jsonb := p_config->'recipients'->'rule';
begin
  if p_kind <> 'coolmsg.send' or p_config is null or jsonb_typeof(p_config) <> 'object' then return false; end if;
  if v_mode is null or v_mode not in ('fixed', 'date', 'data') then return false; end if;
  if char_length(btrim(coalesce(p_config->>'title', ''))) not between 1 and 60 then return false; end if;
  if char_length(btrim(coalesce(p_config->>'body', ''))) not between 1 and 4000 then return false; end if;
  if jsonb_typeof(p_config->'recipients') is distinct from 'object' then return false; end if;
  if v_people is not null and (jsonb_typeof(v_people) <> 'array' or jsonb_array_length(v_people) > 300
     or exists(select 1 from jsonb_array_elements(v_people) e
               where jsonb_typeof(e) <> 'string' or e #>> '{}' !~ '^[0-9a-f-]{36}$')) then
    return false;
  end if;
  if v_rule is not null and jsonb_typeof(v_rule) not in ('object', 'null') then return false; end if;
  if coalesce(jsonb_array_length(v_people), 0) = 0 and (v_rule is null or jsonb_typeof(v_rule) = 'null') then
    return false;  -- 받는 사람이 하나도 없다
  end if;
  -- {이름} 은 그 방식이 아는 것만
  for v_tok in
    select m[1] from regexp_matches(coalesce(p_config->>'title', '') || ' ' || coalesce(p_config->>'body', ''),
                                    '\{([^{}]{1,30})\}', 'g') m
  loop
    if not (v_tok = any (automation_private.known_tokens(v_mode))) then return false; end if;
  end loop;
  return true;
end;
$_$;


ALTER FUNCTION "automation_private"."config_valid"("p_kind" "text", "p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."cron_field_match"("p_field" "text", "p_v" integer, "p_lo" integer, "p_hi" integer) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_temp'
    AS $$
declare
  v_part text; v_base text; v_step int; v_a int; v_b int;
begin
  foreach v_part in array string_to_array(p_field, ',') loop
    v_step := coalesce(nullif(split_part(v_part, '/', 2), '')::int, 1);
    v_base := split_part(v_part, '/', 1);
    if v_base = '*' then
      v_a := p_lo; v_b := p_hi;
    else
      v_a := split_part(v_base, '-', 1)::int;
      v_b := coalesce(nullif(split_part(v_base, '-', 2), '')::int,
                      case when v_part ~ '/' then p_hi else v_a end);  -- «5/15» = 5부터 끝까지 15씩
    end if;
    if p_v between v_a and v_b and (p_v - v_a) % v_step = 0 then return true; end if;
  end loop;
  return false;
end;
$$;


ALTER FUNCTION "automation_private"."cron_field_match"("p_field" "text", "p_v" integer, "p_lo" integer, "p_hi" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."cron_field_ok"("p_field" "text", "p_lo" integer, "p_hi" integer) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_temp'
    AS $_$
declare
  v_part text; v_base text; v_a int; v_b int;
begin
  if p_field is null or p_field !~ '^[0-9*,/-]+$' then return false; end if;
  foreach v_part in array string_to_array(p_field, ',') loop
    if v_part !~ '^(\*|\d{1,2}(-\d{1,2})?)(/\d{1,2})?$' then return false; end if;
    if v_part ~ '/' and split_part(v_part, '/', 2)::int < 1 then return false; end if;
    v_base := split_part(v_part, '/', 1);
    if v_base <> '*' then
      v_a := split_part(v_base, '-', 1)::int;
      v_b := coalesce(nullif(split_part(v_base, '-', 2), '')::int, v_a);
      if v_a < p_lo or v_b > p_hi or v_a > v_b then return false; end if;
    end if;
  end loop;
  return true;
end;
$_$;


ALTER FUNCTION "automation_private"."cron_field_ok"("p_field" "text", "p_lo" integer, "p_hi" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."cron_matches"("p_expr" "text", "p_at" timestamp without time zone) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'automation_private', 'pg_temp'
    AS $$
declare
  f text[] := regexp_split_to_array(btrim(p_expr), '\s+');
  v_dow int := extract(dow from p_at)::int;
  v_dom_ok boolean; v_dow_ok boolean;
begin
  if not automation_private.cron_valid(p_expr) then return false; end if;
  if not automation_private.cron_field_match(f[1], extract(minute from p_at)::int, 0, 59) then return false; end if;
  if not automation_private.cron_field_match(f[2], extract(hour from p_at)::int, 0, 23) then return false; end if;
  if not automation_private.cron_field_match(f[4], extract(month from p_at)::int, 1, 12) then return false; end if;
  v_dom_ok := automation_private.cron_field_match(f[3], extract(day from p_at)::int, 1, 31);
  v_dow_ok := automation_private.cron_field_match(f[5], v_dow, 0, 7)
              or (v_dow = 0 and automation_private.cron_field_match(f[5], 7, 0, 7));
  if f[3] <> '*' and f[5] <> '*' then
    return v_dom_ok or v_dow_ok;
  end if;
  return v_dom_ok and v_dow_ok;
end;
$$;


ALTER FUNCTION "automation_private"."cron_matches"("p_expr" "text", "p_at" timestamp without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."cron_valid"("p_expr" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'automation_private', 'pg_temp'
    AS $$
declare
  f text[] := regexp_split_to_array(btrim(coalesce(p_expr, '')), '\s+');
begin
  return cardinality(f) = 5
    and automation_private.cron_field_ok(f[1], 0, 59)
    and automation_private.cron_field_ok(f[2], 0, 23)
    and automation_private.cron_field_ok(f[3], 1, 31)
    and automation_private.cron_field_ok(f[4], 1, 12)
    and automation_private.cron_field_ok(f[5], 0, 7);
end;
$$;


ALTER FUNCTION "automation_private"."cron_valid"("p_expr" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."data_value"("p_token" "text", "p_date" "date", "p_recipient" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v text;
begin
  case p_token
  when '급식지도 당번' then
    select string_agg(k, ', ' order by k) into v
    from meeting m,
         lateral jsonb_object_keys(case when jsonb_typeof(m.meta->'assignee') = 'object' then m.meta->'assignee' else '{}'::jsonb end) k
    where m.kind = 'duty' and m.meta->>'title' ~ '급식\s*지도'
      and (m.starts_at at time zone 'Asia/Seoul')::date = p_date;
  when '자습 감독' then
    select string_agg('· ' || btrim(m.meta->>'title'), E'\n' order by m.starts_at) into v
    from meeting m
    where m.kind = 'duty' and m.meta ? 'supervision'
      and (m.starts_at at time zone 'Asia/Seoul')::date = p_date;
  when '오늘 학사일정' then
    select string_agg(distinct btrim(m.meta->>'title'), ', ') into v
    from meeting m
    where m.kind = 'schedule' and coalesce(btrim(m.meta->>'title'), '') not in ('', '토요휴업일')
      and (m.starts_at at time zone 'Asia/Seoul')::date <= p_date
      and ((m.ends_at - interval '1 millisecond') at time zone 'Asia/Seoul')::date >= p_date;
  when '오늘 연수' then
    select string_agg('· ' || to_char(m.starts_at at time zone 'Asia/Seoul', 'HH24:MI') || ' ' || btrim(m.meta->>'title'),
                      E'\n' order by m.starts_at) into v
    from meeting m
    where m.kind = 'training' and (m.starts_at at time zone 'Asia/Seoul')::date = p_date;
  when '내 마감 임박 업무' then
    -- 받는 사람이 담당자이고 아직 안 끝낸 할 일, 오늘~3일 뒤 마감 (보이는 날 전은 뺀다)
    select string_agg('· ' || w.name || ' — ' || t.title || ' ('
                      || to_char(t.due_date at time zone 'Asia/Seoul', 'MM/DD') || ')',
                      E'\n' order by t.due_date) into v
    from task t join work w on w.id = t.event_id
    where p_recipient is not null
      and w.status not in ('cancelled', 'completed')
      and coalesce(t.status, '') not in ('completed', 'cancelled')
      and public.task_visible_to_assignees(t.meta)
      and (t.due_date at time zone 'Asia/Seoul')::date between p_date and p_date + 3
      and exists(select 1 from jsonb_array_elements(coalesce(t.meta->'assignees', '[]'::jsonb)) a
                 where (a->>'id')::uuid = p_recipient and coalesce(a->>'status', 'pending') = 'pending');
  else
    v := null;
  end case;
  return v;  -- null = 해당 없음
end;
$$;


ALTER FUNCTION "automation_private"."data_value"("p_token" "text", "p_date" "date", "p_recipient" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_approving boolean := coalesce(current_setting('automation.approving', true), '') = 'on';
begin
  if tg_op = 'INSERT' then
    if not v_approving then
      new.approved_at := null; new.approved_by := null; new.enabled := false;
    end if;
    return new;
  end if;
  if new.owner_id is distinct from old.owner_id then
    raise exception '자동화의 주인은 바꿀 수 없습니다' using errcode = '42501';
  end if;
  if not v_approving
     and (new.approved_at is distinct from old.approved_at or new.approved_by is distinct from old.approved_by) then
    raise exception '승인은 승인 버튼으로만 할 수 있습니다' using errcode = '42501';
  end if;
  if (new.kind, new.config, new.schedule_cron, new.starts_on, new.ends_on, new.skip_closed_days, new.grace_minutes)
     is distinct from (old.kind, old.config, old.schedule_cron, old.starts_on, old.ends_on, old.skip_closed_days, old.grace_minutes)
     and not v_approving then
    new.approved_at := null; new.approved_by := null; new.enabled := false;
  end if;
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "automation_private"."guard"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."automation" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "kind" "text" NOT NULL,
    "title" "text" NOT NULL,
    "schedule_cron" "text" NOT NULL,
    "schedule_spec" "jsonb",
    "skip_closed_days" boolean DEFAULT true NOT NULL,
    "starts_on" "date",
    "ends_on" "date",
    "grace_minutes" integer DEFAULT 30 NOT NULL,
    "config" "jsonb" NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "paused" boolean DEFAULT false NOT NULL,
    "approved_at" timestamp with time zone,
    "approved_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "automation_check" CHECK ((("ends_on" IS NULL) OR ("starts_on" IS NULL) OR ("ends_on" >= "starts_on"))),
    CONSTRAINT "automation_check1" CHECK ("automation_private"."config_valid"("kind", "config")),
    CONSTRAINT "automation_check2" CHECK (((NOT "enabled") OR ("approved_at" IS NOT NULL))),
    CONSTRAINT "automation_grace_minutes_check" CHECK ((("grace_minutes" >= 1) AND ("grace_minutes" <= 720))),
    CONSTRAINT "automation_kind_check" CHECK (("kind" = 'coolmsg.send'::"text")),
    CONSTRAINT "automation_schedule_cron_check" CHECK ("automation_private"."cron_valid"("schedule_cron")),
    CONSTRAINT "automation_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 60)))
);


ALTER TABLE "public"."automation" OWNER TO "postgres";


COMMENT ON TABLE "public"."automation" IS '자동화 업무 규칙. 승인 = automation_approve RPC 만, 반복·받는 사람·본문을 고치면 트리거가 승인을 풀고 끈다. 2026-10-23';



CREATE OR REPLACE FUNCTION "automation_private"."insert_skip"("a" "public"."automation", "p_slot" timestamp without time zone, "p_reason" "text", "p_notify" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  insert into automation_run(automation_id, automation_title, owner_id, kind, scheduled_for, expires_at,
                             status, skip_reason, finished_at)
  values (a.id, a.title, a.owner_id, a.kind, p_slot at time zone 'Asia/Seoul',
          (p_slot at time zone 'Asia/Seoul') + make_interval(mins => a.grace_minutes),
          'skipped', p_reason, now())
  on conflict do nothing
  returning id into v_id;
  if v_id is not null and p_notify then
    perform automation_private.notify_issue(v_id);
  end if;
end;
$$;


ALTER FUNCTION "automation_private"."insert_skip"("a" "public"."automation", "p_slot" timestamp without time zone, "p_reason" "text", "p_notify" boolean) OWNER TO "postgres";


