    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(p_uid is not null and exists(select 1 from profiles where id = p_uid and role = 'admin'), false);
$$;


