    when 'fixed' then array[]::text[]
    when 'date'  then array['날짜', '요일', '내일 날짜', '내일 요일']
    when 'data'  then array['날짜', '요일', '내일 날짜', '내일 요일',
                            '급식지도 당번', '자습 감독', '오늘 학사일정', '오늘 연수', '내 마감 임박 업무']
  end;
$$;


ALTER FUNCTION "automation_private"."known_tokens"("p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."notify_issue"("p_run_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_run automation_run;
  v_msg text;
  v_rid uuid;
begin
  select * into v_run from automation_run where id = p_run_id for update;
  if not found or v_run.notified_at is not null or v_run.is_test then return; end if;
  v_msg := '«' || v_run.automation_title || '» '
    || to_char(v_run.scheduled_for at time zone 'Asia/Seoul', 'MM/DD HH24:MI') || ' 회차: '
    || case v_run.status
         when 'skipped' then '건너뜀 — ' || coalesce(v_run.skip_reason, '')
         when 'expired' then '서버가 유효 시간 안에 보내지 못해 건너뜀'
         when 'failed'  then '발송 실패 — ' || coalesce(v_run.error, '')
         when 'unknown' then '발송 여부 확인 필요 — 쿨메신저 보낸 쪽지를 확인해 주세요(다시 보내지 않습니다)'
         else v_run.status end;
  for v_rid in
    select automation_private.resources_of(v_run.owner_id)
    union
    select automation_private.admin_resources()
  loop
    insert into notification_events(resource_id, type, title, message, priority, meta)
    values (v_rid, 'automation_issue', '자동화 업무 확인 필요', left(v_msg, 500), 'medium',
            jsonb_build_object('automation_id', v_run.automation_id, 'run_id', v_run.id, 'status', v_run.status));
  end loop;
  update automation_run set notified_at = now() where id = p_run_id;
end;
$$;


ALTER FUNCTION "automation_private"."notify_issue"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."owned"("p_id" "uuid") RETURNS "public"."automation"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  a automation;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  select * into a from automation where id = p_id;
  if not found or (a.owner_id <> auth.uid() and not automation_private.is_admin(auth.uid())) then
    raise exception '자동화를 찾을 수 없습니다' using errcode = 'P0002';
  end if;
  return a;
end;
$$;


ALTER FUNCTION "automation_private"."owned"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."plan_due"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  cfg automation_config;
  v_now timestamp := date_trunc('minute', now() at time zone 'Asia/Seoul');
  v_slot timestamp;
  v_date date;
  a automation;
  v_recips jsonb;
  v_rec jsonb;
  v_mode text;
  v_body text;
  v_made int := 0;
  v_runs_today int;
begin
  select * into cfg from automation_config where id;
  if cfg.paused_all then return 0; end if;

  -- 지난 5분을 다시 본다(pg_cron 이 한 분을 건너뛰어도 놓치지 않게). 유일 키가 중복을 막는다.
  for v_slot in select v_now - make_interval(mins => g) from generate_series(0, 4) g loop
    v_date := v_slot::date;
    for a in
      select * from automation
      where enabled and not paused and approved_at is not null
        and (starts_on is null or starts_on <= v_date)
        and (ends_on is null or ends_on >= v_date)
        and approved_at <= (v_slot at time zone 'Asia/Seoul') + interval '59 seconds'
    loop
      if not automation_private.cron_matches(a.schedule_cron, v_slot) then continue; end if;
      if exists(select 1 from automation_run r
                where r.automation_id = a.id and not r.is_test
                  and r.scheduled_for = v_slot at time zone 'Asia/Seoul') then
        continue;
      end if;

      if a.skip_closed_days then
        declare v_reason text := automation_private.closed_day_reason(v_date);
        begin
          if v_reason is not null then
            perform automation_private.insert_skip(a, v_slot, '쉬는 날(' || v_reason || ')', false);
            continue;
          end if;
        end;
      end if;

      select count(distinct r.scheduled_for) into v_runs_today
      from automation_run r
      where r.automation_id = a.id and not r.is_test and r.status <> 'skipped'
        and (r.scheduled_for at time zone 'Asia/Seoul')::date = v_date;
      if v_runs_today >= cfg.max_runs_per_day then
        perform automation_private.insert_skip(a, v_slot, '하루 회차 상한(' || cfg.max_runs_per_day || '회) 초과', true);
        continue;
      end if;

      if not automation_private.can_author(a.owner_id, a.kind) then
        perform automation_private.insert_skip(a, v_slot, '만든 사람에게 자동화 권한이 없습니다', true);
        continue;
      end if;

      begin
        v_recips := automation_private.recipients_of(a, true);
      exception when others then
        perform automation_private.insert_skip(a, v_slot, '받는 사람을 풀지 못함: ' || left(sqlerrm, 200), true);
        continue;
      end;
      if jsonb_array_length(v_recips) = 0 then
        perform automation_private.insert_skip(a, v_slot, '받는 사람이 0명', true);
        continue;
      end if;
      if jsonb_array_length(v_recips) > cfg.max_recipients_per_run then
        perform automation_private.insert_skip(a, v_slot,
          '받는 사람 ' || jsonb_array_length(v_recips) || '명 — 상한 ' || cfg.max_recipients_per_run || '명 초과', true);
        continue;
      end if;

      v_mode := a.config->>'body_mode';
      if automation_private.is_per_recipient(a.config) then
        for v_rec in select value from jsonb_array_elements(v_recips) loop
          -- 마감 임박 업무가 없는 사람에게는 보내지 않는다(정상 — 알림 없음)
          if automation_private.data_value('내 마감 임박 업무', v_date, (v_rec->>'resource_id')::uuid) is null then
            continue;
          end if;
          insert into automation_run(automation_id, automation_title, owner_id, kind, scheduled_for, expires_at,
                                     recipient_key, title, body, recipients)
          values (a.id, a.title, a.owner_id, a.kind, v_slot at time zone 'Asia/Seoul',
                  (v_slot at time zone 'Asia/Seoul') + make_interval(mins => a.grace_minutes),
                  v_rec->>'resource_id',
                  automation_private.render(a.config->>'title', v_mode, v_date, (v_rec->>'resource_id')::uuid),
                  automation_private.render(a.config->>'body', v_mode, v_date, (v_rec->>'resource_id')::uuid),
                  jsonb_build_array(v_rec))
          on conflict do nothing;
          v_made := v_made + 1;
        end loop;
      else
        insert into automation_run(automation_id, automation_title, owner_id, kind, scheduled_for, expires_at,
                                   title, body, recipients)
        values (a.id, a.title, a.owner_id, a.kind, v_slot at time zone 'Asia/Seoul',
                (v_slot at time zone 'Asia/Seoul') + make_interval(mins => a.grace_minutes),
                automation_private.render(a.config->>'title', v_mode, v_date, null),
                automation_private.render(a.config->>'body', v_mode, v_date, null),
                v_recips)
        on conflict do nothing;
        v_made := v_made + 1;
      end if;
    end loop;
  end loop;
  return v_made;
end;
$$;


ALTER FUNCTION "automation_private"."plan_due"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."recipients_of"("p_automation" "public"."automation", "p_as_owner" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_prev text := current_setting('request.jwt.claims', true);
  v_rule jsonb := p_automation.config->'recipients'->'rule';
  v_ids uuid[] := '{}';
  v_res jsonb;
begin
  if v_rule is not null and jsonb_typeof(v_rule) = 'object' then
    if p_as_owner then
      perform set_config('request.jwt.claims',
        jsonb_build_object('sub', p_automation.owner_id, 'role', 'authenticated')::text, true);
    end if;
    begin
      v_res := public.resolve_faculty_rule(v_rule);
    exception when others then
      if p_as_owner then perform set_config('request.jwt.claims', coalesce(v_prev, ''), true); end if;
      raise;
    end;
    if p_as_owner then perform set_config('request.jwt.claims', coalesce(v_prev, ''), true); end if;
    select coalesce(array_agg((r->>'resource_id')::uuid), '{}') into v_ids
    from jsonb_array_elements(coalesce(v_res->'rows', '[]'::jsonb)) r;
  end if;

  v_ids := v_ids || coalesce((
    select array_agg((e #>> '{}')::uuid)
    from jsonb_array_elements(coalesce(p_automation.config->'recipients'->'people', '[]'::jsonb)) e), '{}');

  -- 재직 교직원만, 이름이 있는 사람만 (쿨메신저는 이름으로 찾는다)
  return coalesce((
    select jsonb_agg(jsonb_build_object('resource_id', r.id, 'name', r.name) order by r.name)
    from resource r
    where r.id = any (v_ids)
      and r.type in ('teacher', 'staff')
      and coalesce(r.status, 'active') = 'active'
      and coalesce(btrim(r.name), '') <> ''), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "automation_private"."recipients_of"("p_automation" "public"."automation", "p_as_owner" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."render"("p_text" "text", "p_mode" "text", "p_date" "date", "p_recipient" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'automation_private', 'public', 'pg_temp'
    AS $$
declare
  v_out text := p_text;
  v_tok text;
  v_val text;
begin
  if p_mode = 'fixed' then return p_text; end if;
  foreach v_tok in array automation_private.known_tokens(p_mode) loop
    if position('{' || v_tok || '}' in v_out) = 0 then continue; end if;
    v_val := case v_tok
      when '날짜' then automation_private.k_date(p_date)
      when '요일' then automation_private.k_dow(p_date)
      when '내일 날짜' then automation_private.k_date(p_date + 1)
      when '내일 요일' then automation_private.k_dow(p_date + 1)
      else coalesce(automation_private.data_value(v_tok, p_date, p_recipient), '없음')
    end;
    v_out := replace(v_out, '{' || v_tok || '}', v_val);
  end loop;
  return v_out;
end;
$$;


ALTER FUNCTION "automation_private"."render"("p_text" "text", "p_mode" "text", "p_date" "date", "p_recipient" "uuid") OWNER TO "postgres";


