CREATE OR REPLACE FUNCTION "automation_private"."runner_by_key"("p_key_hash" "text") RETURNS "public"."automation_runner"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r automation_runner;
begin
  select * into r from automation_runner where key_hash = p_key_hash and revoked_at is null;
  if not found then
    raise exception '알 수 없는 실행기' using errcode = '42501';
  end if;
  update automation_runner set last_seen_at = now() where id = r.id;
  return r;
end;
$$;


ALTER FUNCTION "automation_private"."runner_by_key"("p_key_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."sweep"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_last timestamptz;
  v_rid uuid;
begin
  for v_id in
    update automation_run set status = 'expired', finished_at = now()
    where status = 'pending' and expires_at < now()
    returning id
  loop
    perform automation_private.notify_issue(v_id);
  end loop;

  -- 가져간 뒤 10분 동안 보고가 없으면 «나갔는지 모름» — 다시 보내지 않는다
  for v_id in
    update automation_run set status = 'unknown', finished_at = now(),
           error = coalesce(error, '실행기가 결과를 보고하지 않았습니다')
    where status = 'claimed' and claimed_at < now() - interval '10 minutes'
    returning id
  loop
    perform automation_private.notify_issue(v_id);
  end loop;

  -- 대기 회차가 있는데 실행기가 10분 넘게 조용하면 관리자에게 하루 한 번
  select max(last_seen_at) into v_last from automation_runner where revoked_at is null;
  if exists(select 1 from automation_run where status = 'pending')
     and (v_last is null or v_last < now() - interval '10 minutes')
     and coalesce((select runner_offline_alerted_at from automation_config where id), 'epoch'::timestamptz)
         < now() - interval '1 day' then
    for v_rid in select automation_private.admin_resources() loop
      insert into notification_events(resource_id, type, title, message, priority, meta)
      values (v_rid, 'automation_issue', '자동화 서버 응답 없음',
              '쿨메신저 발송 서버가 '
              || coalesce(to_char(v_last at time zone 'Asia/Seoul', 'MM/DD HH24:MI') || ' 이후', '한 번도')
              || ' 응답하지 않았습니다. 대기 중인 회차는 유효 시간이 지나면 건너뜁니다.',
              'high', jsonb_build_object('kind', 'runner_offline'));
    end loop;
    update automation_config set runner_offline_alerted_at = now() where id;
  end if;
end;
$$;


ALTER FUNCTION "automation_private"."sweep"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "automation_private"."tick"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform automation_private.plan_due();
  perform automation_private.sweep();
end;
