CREATE OR REPLACE FUNCTION "club_private"."page_amounts"("p_page" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with it as (
    select coalesce(r.meta->'itemStatus'->(i->>'id')->>'status', r.status) st,
           coalesce(nullif(regexp_replace(coalesce(i->'cells'->>'default-price', ''), '[^0-9.]', '', 'g'), '')::numeric, 0)
           * coalesce(nullif(regexp_replace(coalesce(i->'cells'->>'default-qty', ''), '[^0-9.]', '', 'g'), '')::numeric, 1) amt
    from public.purchase_requests r, jsonb_array_elements(coalesce(r.items, '[]'::jsonb)) i
    where r.page_id = p_page
  )
  select jsonb_build_object(
    'requested', coalesce(sum(amt) filter (where st <> 'rejected'), 0)::bigint,
    'approved', coalesce(sum(amt) filter (where st in ('approved', 'submitted', 'completed')), 0)::bigint,
    'pending_items', count(*) filter (where st = 'pending'),
    'items', count(*),
    'ordered', (select coalesce(sum(coalesce(l.unit_price, 0) * coalesce(l.qty, 1)), 0)::bigint from public.purchase_order_lines l where l.page_id = p_page))
  from it;
$$;


