CREATE OR REPLACE FUNCTION "club_private"."page_collaborators"("p_club_year_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_page uuid; v_owner uuid;
begin
  select f.purchase_page_id into v_page from public.club_finance f where f.club_year_id = p_club_year_id;
  if v_page is null then return; end if;
  select created_by into v_owner from public.purchase_request_pages where id = v_page;
  insert into public.purchase_request_collaborators (page_id, resource_id)
  select v_page, x.rid from (
    select a.teacher_resource_id rid from public.club_advisor a where a.club_year_id = p_club_year_id
    union
    select rta.resource_id from public.resource_tag_assignments rta join public.resource_tags rt on rt.id = rta.tag_id
    where rt.name = '동아리담당자'
  ) x
  where x.rid is distinct from v_owner
    and not exists (select 1 from public.purchase_request_collaborators c where c.page_id = v_page and c.resource_id = x.rid);
end $$;


