CREATE OR REPLACE FUNCTION "club_private"."resolve_student"("p" "jsonb") RETURNS TABLE("resource_id" "uuid", "code" "text", "grade" integer, "class_num" integer, "number" integer, "name" "text", "err" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare v_txt text; v_g int; v_c int; v_n int; v_cnt int;
begin
  if jsonb_typeof(p) in ('string', 'number') then
    v_txt := regexp_replace(p #>> '{}', '\s', '', 'g');
    if v_txt ~ '^\d+-\d+-\d+$' then
      v_g := split_part(v_txt, '-', 1)::int; v_c := split_part(v_txt, '-', 2)::int; v_n := split_part(v_txt, '-', 3)::int;
    elsif v_txt ~ '^\d{5}$' then
      v_g := substr(v_txt, 1, 1)::int; v_c := substr(v_txt, 2, 2)::int; v_n := substr(v_txt, 4, 2)::int;
    else
      p := jsonb_build_object('code', v_txt);
    end if;
    if v_g is not null then p := jsonb_build_object('grade', v_g, 'class', v_c, 'number', v_n); end if;
  end if;

  return query
  with c as (
    select r.id, r.meta->>'id' as code, (r.meta->>'grade')::int as g, (r.meta->>'class')::int as cl,
           (r.meta->>'number')::int as n, r.name
    from public.resource r
    where r.type = 'student' and r.status = 'active'
      and (
        (p ? 'resource_id' and r.id = (p->>'resource_id')::uuid)
        or (not p ? 'resource_id' and p ? 'code' and r.meta->>'id' = p->>'code')
        or (not p ? 'resource_id' and not p ? 'code' and p ? 'grade'
            and (r.meta->>'grade')::int = (p->>'grade')::int and (r.meta->>'class')::int = (p->>'class')::int
            and (r.meta->>'number')::int = (p->>'number')::int)
      )
  )
  select c.id, c.code, c.g, c.cl, c.n, c.name,
         case when (select count(*) from c) = 0 then '재학생에서 찾지 못함: ' || p::text
              when (select count(*) from c) > 1 then '여러 명이 맞음: ' || p::text end
  from c
  union all
  select null, null, null, null, null, null, '재학생에서 찾지 못함: ' || p::text
  where not exists (select 1 from c);
end $_$;


ALTER FUNCTION "club_private"."resolve_student"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "club_private"."sync_year"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  y public.club_year%rowtype;
  v_students jsonb; v_count int; v_grade int;
  v_tnames text; v_tprimary uuid;
  v_ci uuid; v_meta jsonb; v_leader record; v_old_leader jsonb;
  v_host uuid;
begin
  if coalesce(current_setting('club.skip_sync', true), '') = 'on' then return; end if;
  select * into y from public.club_year where id = p_id;
  if not found or y.status not in ('active', 'inactive') then return; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'resource_id', m.student_resource_id, 'code', m.student_code,
           'grade', m.grade, 'class', m.class_num, 'number', m.number, 'name', r.name)
         order by m.grade, m.class_num, m.number), '[]'::jsonb),
         count(*)::int,
         case when count(distinct m.grade) = 1 then max(m.grade) end
    into v_students, v_count, v_grade
  from public.club_member m left join public.resource r on r.id = m.student_resource_id
  where m.club_year_id = p_id and m.status = 'confirmed';

  select string_agg(r.name, ',' order by a.is_primary desc, r.name),
         (array_agg(a.teacher_resource_id order by a.is_primary desc, r.name))[1]
    into v_tnames, v_tprimary
  from public.club_advisor a join public.resource r on r.id = a.teacher_resource_id
  where a.club_year_id = p_id;

  select m.student_resource_id, m.student_code, m.grade, m.class_num, m.number, r.name
    into v_leader
  from public.club_member m left join public.resource r on r.id = m.student_resource_id
  where m.club_year_id = p_id and m.status = 'confirmed' and m.role = 'leader' limit 1;

  -- club_info
  v_ci := y.legacy_club_info_id;
  select meta into v_meta from public.club_info where id = v_ci;
  v_meta := coalesce(v_meta, '{}'::jsonb) || jsonb_build_object('status', y.status, 'club_year_id', y.id, 'club_id', y.club_id);
  v_meta := case when y.place is null then v_meta - 'place' else v_meta || jsonb_build_object('place', y.place) end;
  v_old_leader := v_meta -> 'leader';
  if v_leader.student_code is not null then
    if v_old_leader is null or v_old_leader ->> 'code' is distinct from v_leader.student_code then
      v_meta := v_meta || jsonb_build_object('leader', jsonb_build_object(
        'resource_id', v_leader.student_resource_id, 'code', v_leader.student_code,
        'grade', v_leader.grade, 'class', v_leader.class_num, 'number', v_leader.number, 'name', v_leader.name,
        'in_roster', true, 'source', 'club_member', 'set_at', to_char(now() at time zone 'Asia/Seoul', 'YYYY-MM-DD')));
    end if;
  elsif v_old_leader is not null and coalesce(v_old_leader ->> 'in_roster', 'true') <> 'false' then
    v_meta := v_meta - 'leader';   -- 명단 밖 기장(옛 자료)은 정해질 때까지 그대로 둔다
  end if;

  if v_ci is null then
    insert into public.club_info (name, category, teacher_name, teacher_resource_id, grade, students, student_count, academic_year, meta)
    values (y.name, y.category, v_tnames, v_tprimary, v_grade, v_students, v_count, y.academic_year, v_meta)
    returning id into v_ci;
    update public.club_year set legacy_club_info_id = v_ci where id = y.id;
  else
    update public.club_info set
      name = y.name, category = y.category, teacher_name = v_tnames, teacher_resource_id = v_tprimary,
      grade = v_grade, students = v_students, student_count = v_count, academic_year = y.academic_year,
      meta = v_meta, updated_at = now()
    where id = v_ci;
  end if;

  -- activity_host (창체 주최)
  v_host := y.activity_host_id;
  if v_host is null and y.status = 'active' then
    select id into v_host from public.activity_host where kind = 'club' and name = y.name;
    if v_host is null then
      insert into public.activity_host (kind, name, category, default_area, owner_resource_id, status, meta)
      values ('club', y.name, y.category, 'club', v_tprimary, 'active',
              jsonb_build_object('source', 'club_year', 'club_year_id', y.id, 'club_id', y.club_id, 'club_info_id', v_ci))
      returning id into v_host;
    end if;
    update public.club_year set activity_host_id = v_host where id = y.id;
  end if;
  if v_host is not null then
    update public.activity_host
       set status = case when y.status = 'inactive' then 'archived' else 'active' end,
           owner_resource_id = coalesce(v_tprimary, owner_resource_id),
           updated_at = now()
     where id = v_host;
    delete from public.activity_host_member hm
     where hm.host_id = v_host and hm.academic_year = y.academic_year
       and not exists (select 1 from public.club_member m where m.club_year_id = y.id and m.status = 'confirmed'
                       and m.student_code = hm.student_code);
    insert into public.activity_host_member (host_id, academic_year, student_code, student_resource_id, grade, class_num, number, role)
    select v_host, y.academic_year, m.student_code, m.student_resource_id, m.grade, m.class_num, m.number, m.role
    from public.club_member m where m.club_year_id = y.id and m.status = 'confirmed'
    on conflict (host_id, academic_year, student_code) do update
      set student_resource_id = excluded.student_resource_id, grade = excluded.grade,
          class_num = excluded.class_num, number = excluded.number, role = excluded.role;
  end if;
end $$;


