CREATE OR REPLACE FUNCTION "club_private"."trg_member_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_other text;
begin
  new.updated_at := now();
  if new.status <> 'confirmed' then return new; end if;
  if not exists (select 1 from public.club_year y where y.id = new.club_year_id and y.kind = 'regular' and y.status = 'active') then
    return new;
  end if;
  select y2.name into v_other
  from public.club_member m2 join public.club_year y2 on y2.id = m2.club_year_id
  join public.club_year y on y.id = new.club_year_id
  where m2.student_code = new.student_code and m2.status = 'confirmed' and m2.club_year_id <> new.club_year_id
    and y2.kind = 'regular' and y2.status = 'active' and y2.academic_year = y.academic_year
  limit 1;
  if v_other is not null then
    raise exception '정규 동아리는 한 학생에 하나입니다 — %(%)는 이미 «%» 부원입니다', new.student_code,
      concat_ws('-', new.grade, new.class_num, new.number), v_other using errcode = '23505';
  end if;
  return new;
end $$;


