CREATE OR REPLACE FUNCTION "club_private"."trg_purchase_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_year uuid; v_code text := public.current_student_code();
begin
  if v_code is null then return new; end if;
  select f.club_year_id into v_year from public.club_finance f where f.purchase_page_id = new.page_id;
  if v_year is null then return new; end if;
  if not exists (select 1 from public.club_member m where m.club_year_id = v_year and m.student_code = v_code and m.status = 'confirmed') then
    raise exception '이 동아리 부원만 신청할 수 있습니다' using errcode = '42501';
  end if;
  return new;
end $$;


