CREATE TABLE IF NOT EXISTS "public"."club_year" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "club_id" "uuid" NOT NULL,
    "academic_year" integer NOT NULL,
    "name" "text" NOT NULL,
    "kind" "text" DEFAULT 'regular'::"text" NOT NULL,
    "category" "text",
    "place" "text",
    "capacity" integer,
    "description" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "legacy_club_info_id" "uuid",
    "activity_host_id" "uuid",
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "club_year_capacity_check" CHECK ((("capacity" IS NULL) OR ("capacity" > 0))),
    CONSTRAINT "club_year_kind_check" CHECK (("kind" = ANY (ARRAY['regular'::"text", 'autonomous'::"text"]))),
    CONSTRAINT "club_year_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text", 'proposed'::"text", 'rejected'::"text"])))
);


ALTER TABLE "public"."club_year" OWNER TO "postgres";


COMMENT ON TABLE "public"."club_year" IS '동아리의 학년도별 운영 단위. 이름이 바뀐 해에는 한 club 이 두 행일 수 있다(옛 이름 행 = 그 이름으로 활동한 학년). 확정 명단은 트리거가 club_info · activity_host_member 로 동기화';



CREATE OR REPLACE FUNCTION "club_private"."year_json"("y" "public"."club_year", "p_full" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'id', y.id, 'club_id', y.club_id, 'academic_year', y.academic_year, 'name', y.name, 'kind', y.kind,
    'category', y.category, 'place', y.place, 'capacity', y.capacity, 'description', y.description, 'status', y.status,
    'activity_host_id', y.activity_host_id,
    'former_name', exists (select 1 from public.club c where c.id = y.club_id
                           and coalesce(c.meta->'former_names', '[]'::jsonb) @> jsonb_build_array(jsonb_build_object('name', y.name, 'until_year', y.academic_year))),
    'advisors', coalesce((select jsonb_agg(jsonb_build_object('resource_id', a.teacher_resource_id, 'name', r.name, 'is_primary', a.is_primary)
                                           order by a.is_primary desc, r.name)
                          from public.club_advisor a join public.resource r on r.id = a.teacher_resource_id
                          where a.club_year_id = y.id), '[]'::jsonb),
    'member_count', (select count(*) from public.club_member m where m.club_year_id = y.id and m.status = 'confirmed'),
    'pending_count', case when p_full then (select count(*) from public.club_member m where m.club_year_id = y.id and m.status = 'pending') end,
    'grades', (select jsonb_object_agg(g, n) from (select coalesce(m.grade::text, '?') g, count(*) n from public.club_member m
               where m.club_year_id = y.id and m.status = 'confirmed' group by 1) x),
    'leader', case when p_full then (
      select jsonb_build_object('code', m.student_code, 'grade', m.grade, 'class', m.class_num, 'number', m.number, 'name', r.name)
      from public.club_member m left join public.resource r on r.id = m.student_resource_id
      where m.club_year_id = y.id and m.status = 'confirmed' and m.role = 'leader' limit 1) end,
    'leader_unresolved', case when p_full then y.meta -> 'leader_unresolved' end,
    'years_running', (select count(distinct y2.academic_year) from public.club_year y2
                      where y2.club_id = y.club_id and y2.academic_year <= y.academic_year and y2.status in ('active', 'inactive'))
  );
$$;


