CREATE OR REPLACE FUNCTION "contest"."academy_encouragement_claim"("p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare d date:=(now() at time zone 'Asia/Seoul')::date; c contest.academy_luon_encouragements;
begin
 if not exists(select 1 from contest.profiles where id=p_user and role in ('student','teacher','admin')) then raise exception 'Student required' using errcode='42501'; end if;
 insert into contest.academy_luon_encouragements(user_id,day) values(p_user,d) on conflict do nothing;
 select * into strict c from contest.academy_luon_encouragements where user_id=p_user and day=d for update;
 if c.status='ready' or c.lease_until>now() then return jsonb_build_object('claimed',false,'entry',to_jsonb(c)-'lease_token'); end if;
 update contest.academy_luon_encouragements set status='generating',lease_token=gen_random_uuid(),lease_until=now()+interval '75 seconds'
 where user_id=p_user and day=d returning * into c;
 return jsonb_build_object('claimed',true,'token',c.lease_token,'entry',to_jsonb(c)-'lease_token');
end $$;


ALTER FUNCTION "contest"."academy_encouragement_claim"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."academy_encouragement_finish"("p_user" "uuid", "p_day" "date", "p_token" "uuid", "p_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare c contest.academy_luon_encouragements;
begin
 select * into strict c from contest.academy_luon_encouragements where user_id=p_user and day=p_day for update;
 if c.lease_token is distinct from p_token or c.status<>'generating' then return to_jsonb(c)-'lease_token'; end if;
 if p_message is not null and char_length(btrim(p_message)) not between 1 and 2000 then raise exception 'Invalid encouragement'; end if;
 update contest.academy_luon_encouragements set message=btrim(p_message),status=case when p_message is null then 'failed' else 'ready' end,lease_token=null,lease_until=null
 where user_id=p_user and day=p_day returning * into c;
 return to_jsonb(c)-'lease_token';
end $$;


