CREATE OR REPLACE FUNCTION "contest"."academy_experience_write"("p_kind" "text", "p_data" "jsonb", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r contest.academy_experience_records; v_id uuid:=coalesce(p_id,gen_random_uuid());
begin
 if not exists(select 1 from contest.profiles where id=auth.uid() and role in ('teacher','admin')) then raise exception 'Staff experience required' using errcode='42501'; end if;
 if p_kind not in ('design','recommendation','cache','interview') or p_data is null or jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>2000000 then raise exception 'Invalid experience record'; end if;
 perform pg_advisory_xact_lock(hashtextextended('academy-experience:'||auth.uid()::text,0));
 if p_id is not null then
  select * into r from contest.academy_experience_records where id=p_id and owner_id=auth.uid() and kind=p_kind for update;
  if not found then raise exception 'Experience record not found' using errcode='42501'; end if;
 end if;
 if p_kind='cache' then select id into v_id from contest.academy_experience_records where owner_id=auth.uid() and kind='cache' and data->>'cache_key'=p_data->>'cache_key'; v_id:=coalesce(v_id,gen_random_uuid()); end if;
 insert into contest.academy_experience_records(id,owner_id,kind,data) values(v_id,auth.uid(),p_kind,coalesce(r.data,'{}')||p_data||jsonb_build_object('student_id','experience:'||auth.uid()::text,'source_student_id','00-00001','owner_id',auth.uid()))
 on conflict(id) do update set data=excluded.data,updated_at=now(),created_at=case when excluded.kind='cache' then now() else academy_experience_records.created_at end where academy_experience_records.owner_id=auth.uid() returning * into r;
 return r.data||jsonb_build_object('id',r.id,'created_at',r.created_at,'updated_at',r.updated_at);
end $$;


