CREATE OR REPLACE FUNCTION "contest"."academy_generation_checkpoint"("p_id" "uuid", "p_lease" "uuid", "p_output" "jsonb" DEFAULT NULL::"jsonb", "p_usage" "jsonb" DEFAULT '{}'::"jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare j contest.academy_generation_jobs; target jsonb; result jsonb; saved uuid; data jsonb;
begin
 select * into j from contest.academy_generation_jobs where id=p_id and lease=p_lease and status='running' and lease_until>now() for update;
 if not found then return; end if;
 if p_error is not null then
  update contest.academy_generation_jobs set status=case when attempts>=3 or p_error like 'PROVIDER_HTTP_400%' or p_error like 'PROVIDER_HTTP_401%' or p_error like 'PROVIDER_CONFIG%' then 'failed' else 'retry' end,
   error=left(p_error,200),available_at=now()+make_interval(secs=>attempts*15),lease=null,lease_until=null,updated_at=now() where id=j.id; return;
 end if;
 if j.stage in ('design','graph') then
  if p_output is null or jsonb_typeof(p_output)<>'object' then raise exception 'Missing stage output'; end if;
  update contest.academy_generation_jobs set design=case when j.stage='design' then p_output else design end,graph=case when j.stage='graph' then p_output else graph end,
   usage=usage||jsonb_build_object(j.stage,p_usage),stage=case when j.stage='design' then 'graph' else 'save' end,status='queued',attempts=0,lease=null,lease_until=null,available_at=now(),error=null,updated_at=now() where id=j.id;
 else
  if not exists(select 1 from contest.profiles where id=j.owner_id and role in ('student','teacher','admin')) then raise exception 'Account no longer eligible'; end if;
  target:=j.input->'target'; result:=j.design||j.graph;
  data:=jsonb_build_object('title',j.design->>'title','kg_version_id',j.input->'kgVersionId','student_id',case when j.experience then 'experience:'||j.owner_id else j.student_id end,
   'target_kind',target->>'kind','target_name',target->>'name','target_ref',target->'ref','academic_year',target->'academic_year','grade',target->'grade','semester',target->'semester',
   'status','draft','selected_source_snapshot',coalesce((select jsonb_agg(s->'snapshot') from jsonb_array_elements(j.input->'selectedSources') s),'[]'),
   'sources',j.input->'selectedSources','llm_result',result,'entities',result->'entities','relations',result->'relations','student_rationale','','llm_token_usage',j.usage,'generation_job_id',j.id);
  if j.experience then
   insert into contest.academy_experience_records(owner_id,kind,data) values(j.owner_id,'design',data||jsonb_build_object('source_student_id','00-00001')) returning id into saved;
  else
   insert into contest.student_inquiry_designs(student_id,kg_version_id,title,target_kind,target_name,target_ref,academic_year,grade,semester,status,selected_source_snapshot,llm_result,student_rationale,llm_token_usage)
   values(j.student_id,nullif(j.input->>'kgVersionId','')::uuid,j.design->>'title',target->>'kind',target->>'name',target->'ref',(target->>'academic_year')::integer,(target->>'grade')::integer,nullif(target->>'semester','')::integer,'draft',data->'selected_source_snapshot',result,'',j.usage) returning id into saved;
  end if;
  update contest.academy_generation_jobs set status='completed',draft_id=case when j.experience then 'trial:' else '' end||saved,lease=null,lease_until=null,error=null,updated_at=now() where id=j.id;
 end if;
 perform contest_private.wake_generation_worker();
end $$;


ALTER FUNCTION "contest"."academy_generation_checkpoint"("p_id" "uuid", "p_lease" "uuid", "p_output" "jsonb", "p_usage" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "contest"."academy_generation_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_id" "uuid" NOT NULL,
    "request_key" "uuid" NOT NULL,
    "student_id" "text" NOT NULL,
    "experience" boolean NOT NULL,
    "provider" "text" NOT NULL,
    "input" "jsonb" NOT NULL,
    "stage" "text" DEFAULT 'design'::"text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "design" "jsonb",
    "graph" "jsonb",
    "usage" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "draft_id" "text",
    "attempts" integer DEFAULT 0 NOT NULL,
    "restarts" integer DEFAULT 0 NOT NULL,
    "lease" "uuid",
    "lease_until" timestamp with time zone,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "surface" "text" DEFAULT 'academy'::"text" NOT NULL,
    CONSTRAINT "academy_generation_jobs_provider_check" CHECK (("provider" = ANY (ARRAY['openai'::"text", 'solar-pro4'::"text"]))),
    CONSTRAINT "academy_generation_jobs_stage_check" CHECK (("stage" = ANY (ARRAY['design'::"text", 'graph'::"text", 'save'::"text"]))),
    CONSTRAINT "academy_generation_jobs_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'retry'::"text", 'failed'::"text", 'completed'::"text"]))),
    CONSTRAINT "academy_generation_jobs_surface_check" CHECK (("surface" = ANY (ARRAY['academy'::"text", 'inquiry-design'::"text"])))
);


ALTER TABLE "contest"."academy_generation_jobs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."academy_generation_claim"() RETURNS SETOF "contest"."academy_generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare j contest.academy_generation_jobs;
begin
 update contest.academy_generation_jobs set status='failed',error='WORKER_TIMEOUT',updated_at=now() where status='running' and lease_until<now() and attempts>=3;
 select * into j from contest.academy_generation_jobs where ((status in ('queued','retry') and available_at<=now()) or (status='running' and lease_until<now())) order by created_at for update skip locked limit 1;
 if not found then return; end if;
 return query update contest.academy_generation_jobs set status='running',lease=gen_random_uuid(),lease_until=now()+interval '150 seconds',attempts=attempts+1,updated_at=now() where id=j.id returning *;
end $$;


ALTER FUNCTION "contest"."academy_generation_claim"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."academy_generation_retry"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 update contest.academy_generation_jobs set status='queued',attempts=0,restarts=restarts+1,error=null,available_at=now(),updated_at=now()
 where id=p_id and owner_id=auth.uid() and status='failed' and restarts<3 and exists(select 1 from contest.profiles where id=auth.uid() and role in ('student','teacher','admin'));
 if not found then raise exception 'Retry unavailable' using errcode='42501'; end if;
 perform contest_private.wake_generation_worker();
end $$;


ALTER FUNCTION "contest"."academy_generation_retry"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."academy_generation_start"("p_request" "uuid", "p_input" "jsonb", "p_provider" "text" DEFAULT 'openai'::"text") RETURNS "contest"."academy_generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r contest.profiles; j contest.academy_generation_jobs; code text; trial boolean; version_id uuid;
begin
 select * into r from contest.profiles where id=auth.uid();
 if r.id is null or r.role not in ('student','teacher','admin') then raise exception 'Academy account required' using errcode='42501'; end if;
 if p_provider not in ('openai','solar-pro4') or (p_provider<>'openai' and r.role<>'admin') then raise exception 'Only administrators may select a model' using errcode='42501'; end if;
 if p_request is null or p_input is null or jsonb_typeof(p_input)<>'object' or octet_length(p_input::text)>300000 then raise exception 'Invalid request'; end if;
 if jsonb_typeof(p_input->'target') is distinct from 'object' or coalesce(p_input#>>'{target,name}','')='' or coalesce(p_input#>>'{target,kind}','') not in ('subject','club','autonomous','career') then raise exception 'Invalid target'; end if;
 if jsonb_typeof(p_input->'selectedSources') is distinct from 'array' or jsonb_array_length(p_input->'selectedSources')>20 then raise exception 'Invalid sources'; end if;
 trial:=r.role in ('teacher','admin'); code:=case when trial then '00-00001' else split_part(r.email,'@',1) end;
 if coalesce(p_input->>'studentId','')<>(case when trial then 'experience:'||r.id else code end) then raise exception 'Wrong owner scope' using errcode='42501'; end if;
 version_id:=nullif(p_input->>'kgVersionId','')::uuid;
 if version_id is not null and not exists(select 1 from contest.student_kg_versions where id=version_id and student_id=code) then raise exception 'Wrong KG scope' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(r.id::text,1400));
 select * into j from contest.academy_generation_jobs where owner_id=r.id and request_key=p_request;
 if found then return j; end if;
 -- One active design per account also prevents repeat clicks after a lost response.
 select * into j from contest.academy_generation_jobs where owner_id=r.id and surface='academy' and status in ('queued','running','retry') order by created_at desc limit 1;
 if found then return j; end if;
 if (select count(*) from contest.academy_generation_jobs where owner_id=r.id and surface='academy' and (created_at at time zone 'Asia/Seoul')::date=(now() at time zone 'Asia/Seoul')::date)>=20 then raise exception '오늘의 설계 의뢰 한도에 도달했어요.'; end if;
 insert into contest.academy_generation_jobs(owner_id,request_key,student_id,experience,provider,input,surface)
 values(r.id,p_request,code,trial,p_provider,p_input-'existingEntities'-'owner_id','academy') returning * into j;
 perform contest_private.wake_generation_worker(); return j;
end $$;


ALTER FUNCTION "contest"."academy_generation_start"("p_request" "uuid", "p_input" "jsonb", "p_provider" "text") OWNER TO "postgres";


