CREATE OR REPLACE FUNCTION "contest"."academy_journey_transition"("p_user" "uuid", "p_action" "text", "p_revision" integer, "p_design" "uuid" DEFAULT NULL::"uuid", "p_reflection" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare j contest.academy_journeys; d contest.student_inquiry_designs; code text; first_record contest.academy_game_progress;
begin
  if not exists(select 1 from contest.profiles where id=p_user and role in ('student','teacher','admin')) then raise exception '학생 본인 계정에서 의뢰를 진행해 주세요.' using errcode='42501'; end if;
  select contest_private.player_code(p_user) into code;
  if code is null or code='' then raise exception '학생 계정을 확인해 주세요.' using errcode='42501'; end if;
  if p_action not in ('start','bind','observe','complete') or p_revision is null or p_revision<0 then raise exception '의뢰 요청을 확인해 주세요.'; end if;
  if p_action='start' then
    select * into first_record from contest.academy_game_progress where user_id=p_user and quest_step='completed';

    if not found then

      select c.activity_id,left(c.question || chr(10) || '궁금해진 이유: ' || c.curiosity_reason,2000) into first_record.activity_id,first_record.question

      from contest.academy_chapters c where c.user_id=p_user and c.chapter='library_questions' and c.completed_at is not null;

    end if;
    if not found then raise exception '제2장에서 질문을 기록한 뒤 다음 의뢰를 시작해 주세요.'; end if;
    insert into contest.academy_journeys(user_id,source_question,source_activity_id)
      values(p_user,first_record.question,first_record.activity_id) on conflict do nothing;
  end if;
  select * into j from contest.academy_journeys where user_id=p_user for update;
  if not found then raise exception '연속 의뢰를 먼저 수락해 주세요.'; end if;
  if p_action='start' or j.stage='completed' or j.revision<>p_revision then return (to_jsonb(j)||jsonb_build_object('design_id',case when j.trial_design_id is not null then 'trial:'||j.trial_design_id::text else j.design_id::text end)); end if;
  if p_action='bind' then
    select * into d from contest_private.player_design(p_design,code);
    if not found or d.status not in ('saved','observed') or char_length(btrim(coalesce(d.student_rationale,'')))<10 then raise exception '내 선택 이유로 확정한 탐구만 의뢰에 연결할 수 있어요.'; end if;
    if coalesce(j.trial_design_id,j.design_id) is not distinct from d.id then return (to_jsonb(j)||jsonb_build_object('design_id',case when j.trial_design_id is not null then 'trial:'||j.trial_design_id::text else j.design_id::text end)); end if;
    update contest.academy_journeys set design_id=case when code not like 'experience:%' then d.id end,trial_design_id=case when code like 'experience:%' then d.id end,activity_id=null,reflection=null,stage='planned',revision=revision+1,updated_at=now() where user_id=p_user returning * into j;
    return (to_jsonb(j)||jsonb_build_object('design_id',case when j.trial_design_id is not null then 'trial:'||j.trial_design_id::text else j.design_id::text end));
  end if;
  select * into d from contest_private.player_design(coalesce(j.trial_design_id,j.design_id),code);
  if not found then raise exception '연결한 탐구를 찾을 수 없어요. 내 탐구를 다시 골라 주세요.'; end if;
  if d.status<>'observed' or d.observed_activity_id is null then raise exception '연구 수첩에서 실제로 수행한 활동을 먼저 연결해 주세요.'; end if;
  perform id from contest.student_detailed_activities where id=d.observed_activity_id and student_id=case when code like 'experience:%' then '00-00001' else code end for share;
  if not found then raise exception '내 계정의 실제 활동 기록만 연결할 수 있어요.' using errcode='42501'; end if;
  if p_action='observe' then
    if j.stage not in ('planned','observed') then raise exception '먼저 내 탐구 설계를 확정해 주세요.'; end if;
    if j.stage='observed' and j.activity_id=d.observed_activity_id then return (to_jsonb(j)||jsonb_build_object('design_id',case when j.trial_design_id is not null then 'trial:'||j.trial_design_id::text else j.design_id::text end)); end if;
    update contest.academy_journeys set activity_id=d.observed_activity_id,stage='observed',revision=revision+1,updated_at=now() where user_id=p_user returning * into j;
  elsif p_action='complete' then
    if j.stage<>'observed' or j.activity_id is distinct from d.observed_activity_id then raise exception '활동 연결이 바뀌었어요. 실행 기록을 다시 확인해 주세요.'; end if;
    if p_reflection is null or char_length(btrim(p_reflection)) not between 40 and 4000 then raise exception '발견과 생각의 변화를 40~4,000자로 적어 주세요.'; end if;
    if code like 'experience:%' then update contest.academy_experience_records set data=data||jsonb_build_object('reflection',btrim(p_reflection)),updated_at=now() where id=d.id and owner_id=p_user; else update contest.student_inquiry_designs set reflection=btrim(p_reflection),updated_at=now() where id=d.id; end if;
    update contest.academy_journeys set reflection=btrim(p_reflection),stage='completed',completed_at=now(),revision=revision+1,updated_at=now() where user_id=p_user returning * into j;
  end if;
  return (to_jsonb(j)||jsonb_build_object('design_id',case when j.trial_design_id is not null then 'trial:'||j.trial_design_id::text else j.design_id::text end));
end;
$$;


