    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare r contest.academy_self_assessments;
begin
 if not exists(select 1 from contest.profiles where id=p_user and role in ('student','teacher','admin')) then raise exception 'Student account required' using errcode='42501'; end if;
 insert into contest.academy_self_assessments(user_id,request_id,kind,version,answers,scores)
