CREATE OR REPLACE FUNCTION "contest"."activity_lineage_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'contest', 'pg_temp'
    AS $$
DECLARE
  cursor_id uuid := NEW.lineage_parent_id;
  hops int := 0;
BEGIN
  WHILE cursor_id IS NOT NULL AND hops < 64 LOOP
    IF cursor_id = NEW.id THEN
      RAISE EXCEPTION '활동 계보에 순환이 생깁니다 (activity %)', NEW.id USING ERRCODE = '23514';
    END IF;
    SELECT a.lineage_parent_id INTO cursor_id FROM contest.activity a WHERE a.id = cursor_id;
    hops := hops + 1;
  END LOOP;
  IF hops >= 64 THEN
    RAISE EXCEPTION '활동 계보가 너무 깊습니다 (64단계 초과)' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


