CREATE OR REPLACE FUNCTION "contest"."can_add_activity_participant"("p_activity_id" "uuid", "p_student_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'contest', 'pg_temp'
    AS $$
  SELECT
    contest.can_manage_activity(p_activity_id)
    AND (
      contest.is_teacher_or_admin(auth.uid())
      -- 학생은 그 활동 주최 동아리의 부원만 참여자로 넣을 수 있다.
      -- 주최가 없으면 EXISTS가 비어 거부된다 → 주최 연결이 사실상 필수가 된다.
      OR EXISTS (
        SELECT 1
        FROM contest.activity a
        JOIN contest.activity_host_link l ON l.activity_id = a.id
        JOIN contest.activity_host_member m
          ON m.host_id = l.host_id
         AND m.academic_year = a.academic_year
         AND m.student_code = p_student_code
        WHERE a.id = p_activity_id
      )
    );
$$;


ALTER FUNCTION "contest"."can_add_activity_participant"("p_activity_id" "uuid", "p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."can_link_activity_host"("p_activity_id" "uuid", "p_host_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'contest', 'pg_temp'
    AS $$
  SELECT
    contest.can_manage_activity(p_activity_id)
    AND (
      contest.is_teacher_or_admin(auth.uid())
      -- 학생은 자기가 그 해 소속된 동아리에만 활동을 걸 수 있다
      OR EXISTS (
        SELECT 1 FROM contest.activity a
        WHERE a.id = p_activity_id
          AND contest.is_activity_host_member(p_host_id, a.academic_year)
      )
    );
$$;


ALTER FUNCTION "contest"."can_link_activity_host"("p_activity_id" "uuid", "p_host_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."can_manage_activity"("p_activity_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'contest', 'pg_temp'
    AS $$
  SELECT
    contest.is_activity_manager()
    OR EXISTS (
      SELECT 1 FROM contest.activity a
      WHERE a.id = p_activity_id AND a.created_by = auth.uid()
    )
    -- 활동에 직접 배정된 담당교사
    OR EXISTS (
      SELECT 1
      FROM contest.activity_teacher at
      JOIN contest.user_resource ur ON ur.resource_id = at.teacher_resource_id
      WHERE at.activity_id = p_activity_id AND ur.user_id = auth.uid()
    )
    -- 주최(동아리 등)의 담당교사 — 학생이 만든 우리 동아리 활동을 검토·교정할 수 있어야 한다
    OR EXISTS (
      SELECT 1
      FROM contest.activity_host_link l
      JOIN contest.activity_host h ON h.id = l.host_id
      JOIN contest.user_resource ur ON ur.resource_id = h.owner_resource_id
      WHERE l.activity_id = p_activity_id AND ur.user_id = auth.uid()
    );
$$;


ALTER FUNCTION "contest"."can_manage_activity"("p_activity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."can_manage_activity_host"("p_host_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'contest', 'pg_temp'
    AS $$
  SELECT
    contest.is_activity_manager()
    OR EXISTS (
      SELECT 1 FROM contest.activity_host h
      WHERE h.id = p_host_id
        AND (
          h.created_by = auth.uid()
          OR EXISTS (
            SELECT 1 FROM contest.user_resource ur
            WHERE ur.user_id = auth.uid() AND ur.resource_id = h.owner_resource_id
          )
        )
    );
$$;


ALTER FUNCTION "contest"."can_manage_activity_host"("p_host_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "contest"."activity" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "area" "text" NOT NULL,
    "purpose" "text",
    "content" "text",
    "outcome" "text",
    "academic_year" integer NOT NULL,
    "semester" integer,
    "starts_on" "date" NOT NULL,
    "ends_on" "date",
    "hours" numeric(5,1),
    "place" "text",
    "lineage_parent_id" "uuid",
    "lineage_note" "text",
    "operator_type" "text" DEFAULT 'internal'::"text" NOT NULL,
    "operator_name" "text",
    "scale" "text" DEFAULT 'group'::"text" NOT NULL,
    "budget_source" "text",
    "budget_program" "text",
    "budget_planned" numeric(12,0),
    "budget_spent" numeric(12,0),
    "keywords" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "related_subjects" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "career_fields" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "target_grades" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "department" "text",
    "status" "text" DEFAULT 'planned'::"text" NOT NULL,
    "visibility" "text" DEFAULT 'school'::"text" NOT NULL,
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "meeting_id" "uuid",
    "attachments" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "activity_area_check" CHECK (("area" = ANY (ARRAY['autonomy'::"text", 'club'::"text", 'career'::"text", 'service'::"text"]))),
    CONSTRAINT "activity_budget_source_check" CHECK (("budget_source" = ANY (ARRAY['school'::"text", 'office'::"text", 'grant'::"text", 'external'::"text", 'self'::"text", 'none'::"text"]))),
    CONSTRAINT "activity_lineage_not_self" CHECK (("lineage_parent_id" IS DISTINCT FROM "id")),
    CONSTRAINT "activity_operator_type_check" CHECK (("operator_type" = ANY (ARRAY['internal'::"text", 'external'::"text", 'joint'::"text"]))),
    CONSTRAINT "activity_period_ordered" CHECK ((("ends_on" IS NULL) OR ("ends_on" >= "starts_on"))),
    CONSTRAINT "activity_scale_check" CHECK (("scale" = ANY (ARRAY['school'::"text", 'grade'::"text", 'class'::"text", 'group'::"text", 'individual'::"text"]))),
    CONSTRAINT "activity_semester_check" CHECK (("semester" = ANY (ARRAY[1, 2]))),
    CONSTRAINT "activity_source_check" CHECK (("source" = ANY (ARRAY['manual'::"text", 'timetable'::"text", 'meeting'::"text", 'issue'::"text", 'import'::"text"]))),
    CONSTRAINT "activity_status_check" CHECK (("status" = ANY (ARRAY['planned'::"text", 'running'::"text", 'done'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "activity_visibility_check" CHECK (("visibility" = ANY (ARRAY['school'::"text", 'participants'::"text"])))
);


