CREATE OR REPLACE FUNCTION "contest"."count_comprehensive_analysis_calls"("p_student_id" "text", "p_since" timestamp with time zone DEFAULT "date_trunc"('day'::"text", "now"())) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF NOT contest.inquiry_design_can_access_student(p_student_id) THEN
    RAISE EXCEPTION 'not allowed to count comprehensive analysis calls for student %', p_student_id;
  END IF;

  SELECT count(*)::integer INTO v_count
  FROM contest.student_inquiry_recommendations
  WHERE student_id = p_student_id
    AND generated_at IS NOT NULL
    AND generated_at >= p_since;

  RETURN COALESCE(v_count, 0);
END;
$$;


