CREATE OR REPLACE FUNCTION "contest"."count_inquiry_analysis_calls"("p_student_id" "text", "p_since" timestamp with time zone DEFAULT "date_trunc"('day'::"text", "now"())) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF NOT contest.inquiry_design_can_access_student(p_student_id) THEN
    RAISE EXCEPTION 'not allowed to count inquiry calls for student %', p_student_id;
  END IF;

  SELECT count(*)::integer
  INTO v_count
  FROM contest.inquiry_design_llm_cache
  WHERE student_id = p_student_id
    AND created_at >= p_since;

  RETURN COALESCE(v_count, 0);
END;
