CREATE OR REPLACE FUNCTION "contest"."get_curriculum_subject_plan"("p_admission_year" integer) RETURNS TABLE("academic_year" integer, "grade" integer, "semester" integer, "subject" "text", "area" "text", "category" "text", "has_survey" boolean, "is_required" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'contest'
    AS $$
  with pool as (
    select distinct g.academic_year, g.target_grade as grade, cs.name as subject
    from course_selection_slot_subject ss
    join course_selection_slot sl on sl.id = ss.slot_id
    join course_selection_group g on g.id = sl.group_id
    join course_selectable_subject cs on cs.id = ss.selectable_subject_id
  ),
  surveyed as (
    select distinct academic_year, grade from pool
  )
  select c.academic_year, c.grade, c.semester, c.subject, c.area, c.category,
         (s.academic_year is not null) as has_survey,
         (s.academic_year is not null and p.subject is null) as is_required
  from contest.school_curriculum c
  left join surveyed s on s.academic_year = c.academic_year and s.grade = c.grade
  left join pool p on p.academic_year = c.academic_year and p.grade = c.grade and p.subject = c.subject
  where c.admission_year = p_admission_year;
$$;


ALTER FUNCTION "contest"."get_curriculum_subject_plan"("p_admission_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."get_inquiry_analysis_cache"("p_cache_key" "text", "p_student_id" "text") RETURNS TABLE("result" "jsonb", "model" "text", "prompt_tokens" integer, "completion_tokens" integer, "created_at" timestamp with time zone, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
begin
  if not contest.inquiry_design_can_access_student(p_student_id) then
    raise exception 'not allowed to read inquiry cache for student %', p_student_id;
  end if;

  return query
  select c.result, c.model, c.prompt_tokens, c.completion_tokens, c.created_at, c.expires_at
    from contest.inquiry_design_llm_cache c
   where c.cache_key = p_cache_key
     and c.student_id = p_student_id
     and c.expires_at > now();
end;
$$;


