    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'contest', 'pg_temp'
    AS $$
  SELECT
    EXISTS (
      SELECT 1 FROM contest.user_resource ur
      WHERE ur.user_id = auth.uid() AND ur.resource_id = p_resource_id
    )
    OR EXISTS (
      SELECT 1 FROM contest.resource r
      WHERE r.id = p_resource_id
        AND r.type = 'student'
        AND r.meta->>'id' = contest.current_student_code()
    );
$$;


