CREATE OR REPLACE FUNCTION "contest"."save_academy_prologue"("p_scene_index" integer, "p_finish" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare actor uuid := auth.uid(); result contest.academy_prologues;
begin
  if actor is null or not exists (select 1 from contest.profiles where id = actor and role in ('student','teacher','admin')) then
    raise exception '학생 본인의 책갈피만 저장할 수 있어요.' using errcode = '42501';
  end if;
  if p_scene_index is null or p_scene_index not between 0 and 30 or (p_finish is not null and p_finish not in ('completed', 'skipped')) then
    raise exception '이야기의 장면을 확인해 주세요.' using errcode = '22023';
  end if;
  if p_finish = 'completed' and p_scene_index <> 30 then
    raise exception '마지막 장면을 읽거나 건너뛰기를 선택해 주세요.' using errcode = '22023';
  end if;
  insert into contest.academy_prologues(user_id, scene_index, completed_at, skipped)
    values (actor, p_scene_index, case when p_finish is not null then now() end, coalesce(p_finish = 'skipped', false))
  on conflict (user_id) do update set
    scene_index = greatest(academy_prologues.scene_index, excluded.scene_index),
    completed_at = coalesce(academy_prologues.completed_at, excluded.completed_at),
    skipped = case when academy_prologues.completed_at is null then excluded.skipped else academy_prologues.skipped end,
    updated_at = now()
  returning * into result;
  return to_jsonb(result);
end;
$$;


ALTER FUNCTION "contest"."save_academy_prologue"("p_scene_index" integer, "p_finish" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."save_inquiry_design_with_ontology"("p_design" "jsonb", "p_sources" "jsonb" DEFAULT '[]'::"jsonb", "p_entities" "jsonb" DEFAULT '[]'::"jsonb", "p_relations" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
DECLARE
  v_design_id uuid;
  v_student_id text := p_design ->> 'student_id';
  v_rationale text := trim(COALESCE(p_design ->> 'student_rationale', ''));
  v_created_by uuid := (SELECT auth.uid());
  v_entity jsonb;
  v_relation jsonb;
  v_source jsonb;
  v_reuse_map jsonb := '{}'::jsonb;
  v_source_id text;
  v_target_id text;
  v_source_scope text;
  v_target_scope text;
BEGIN
  IF v_student_id IS NULL OR v_student_id = '' THEN
    RAISE EXCEPTION 'student_id is required';
  END IF;

  IF NOT contest.inquiry_design_can_access_student(v_student_id) THEN
    RAISE EXCEPTION 'not allowed to save inquiry design for student %', v_student_id;
  END IF;

  INSERT INTO contest.student_inquiry_designs (
    student_id, kg_version_id, title, target_kind, target_name, target_ref,
    academic_year, grade, semester, status, selected_source_snapshot,
    llm_result, student_rationale, reflection, llm_token_usage, created_by
  )
  VALUES (
    v_student_id,
    -- 빈 문자열도 NULL 로 떨어뜨린다 — 클라이언트가 '' 를 보내면 uuid 캐스팅이 터진다.
    NULLIF(p_design ->> 'kg_version_id', '')::uuid,
    NULLIF(trim(p_design ->> 'title'), ''),
    p_design ->> 'target_kind',
    NULLIF(trim(p_design ->> 'target_name'), ''),
    COALESCE(p_design -> 'target_ref', '{}'::jsonb),
    (p_design ->> 'academic_year')::integer,
    (p_design ->> 'grade')::integer,
    NULLIF(p_design ->> 'semester', '')::integer,
    COALESCE(NULLIF(p_design ->> 'status', ''), 'saved'),
    COALESCE(p_design -> 'selected_source_snapshot', '[]'::jsonb),
    p_design -> 'llm_result',
    v_rationale,
    NULLIF(p_design ->> 'reflection', ''),
    COALESCE(p_design -> 'llm_token_usage', '{}'::jsonb),
    v_created_by
  )
  RETURNING id INTO v_design_id;

  FOR v_source IN SELECT value FROM jsonb_array_elements(COALESCE(p_sources, '[]'::jsonb))
  LOOP
    INSERT INTO contest.student_inquiry_design_sources (
      design_id, student_id, source_kind, kg_version_id,
      source_entity_id, source_relation_id, activity_id, snapshot
    )
    VALUES (
      v_design_id, v_student_id, v_source ->> 'source_kind',
      NULLIF(v_source ->> 'kg_version_id', '')::uuid,
      NULLIF(v_source ->> 'source_entity_id', ''),
      NULLIF(v_source ->> 'source_relation_id', '')::uuid,
      NULLIF(v_source ->> 'activity_id', '')::uuid,
      COALESCE(v_source -> 'snapshot', '{}'::jsonb)
    );
  END LOOP;

  FOR v_entity IN SELECT value FROM jsonb_array_elements(COALESCE(p_entities, '[]'::jsonb))
  LOOP
    IF NULLIF(v_entity ->> 'reuse_existing_id', '') IS NOT NULL THEN
      v_reuse_map := v_reuse_map || jsonb_build_object(v_entity ->> 'entity_id', v_entity ->> 'reuse_existing_id');
    ELSE
      INSERT INTO contest.student_inquiry_design_entities (
        design_id, student_id, entity_id, label, type, properties
      )
      VALUES (
        v_design_id, v_student_id,
        v_entity ->> 'entity_id', v_entity ->> 'label', v_entity ->> 'type',
        COALESCE(v_entity -> 'properties', '{}'::jsonb)
      );
    END IF;
  END LOOP;

  FOR v_relation IN SELECT value FROM jsonb_array_elements(COALESCE(p_relations, '[]'::jsonb))
  LOOP
    v_source_id := v_relation ->> 'source_entity_id';
    v_target_id := v_relation ->> 'target_entity_id';
    v_source_scope := COALESCE(NULLIF(v_relation ->> 'source_scope', ''), 'planned');
    v_target_scope := COALESCE(NULLIF(v_relation ->> 'target_scope', ''), 'planned');

    IF v_reuse_map ? v_source_id THEN
      v_source_id := v_reuse_map ->> v_source_id;
      v_source_scope := 'existing';
    END IF;

    IF v_reuse_map ? v_target_id THEN
      v_target_id := v_reuse_map ->> v_target_id;
      v_target_scope := 'existing';
    END IF;

    INSERT INTO contest.student_inquiry_design_relations (
      design_id, student_id, source_scope, source_entity_id,
      target_scope, target_entity_id, relation_type, confidence, evidence, properties
    )
    VALUES (
      v_design_id, v_student_id, v_source_scope, v_source_id,
      v_target_scope, v_target_id, v_relation ->> 'relation_type',
      NULLIF(v_relation ->> 'confidence', '')::numeric,
      NULLIF(v_relation ->> 'evidence', ''),
      COALESCE(v_relation -> 'properties', '{}'::jsonb)
    );
  END LOOP;

  RETURN v_design_id;
END;
$$;


ALTER FUNCTION "contest"."save_inquiry_design_with_ontology"("p_design" "jsonb", "p_sources" "jsonb", "p_entities" "jsonb", "p_relations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."save_kg_version"("p_student_id" "text", "p_kg_json" "jsonb", "p_source_categories" "text"[] DEFAULT ARRAY['regular'::"text"]) RETURNS TABLE("id" "uuid", "version" integer, "student_id" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
BEGIN
  RETURN QUERY
  INSERT INTO student_kg_versions (student_id, version, kg_json, source_categories, created_by)
  VALUES (
    p_student_id,
    COALESCE((SELECT MAX(v.version) FROM student_kg_versions v WHERE v.student_id = p_student_id), 0) + 1,
    p_kg_json,
    p_source_categories,
    NULL
  )
  RETURNING student_kg_versions.id, student_kg_versions.version, student_kg_versions.student_id, student_kg_versions.created_at;
END;
$$;


ALTER FUNCTION "contest"."save_kg_version"("p_student_id" "text", "p_kg_json" "jsonb", "p_source_categories" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."save_kg_version_secure"("p_student_id" "text", "p_kg_json" "jsonb", "p_source_categories" "text"[] DEFAULT '{}'::"text"[]) RETURNS TABLE("id" "uuid", "version" integer, "student_id" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
DECLARE
  v_caller_role TEXT;
  v_caller_id UUID;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT p.role INTO v_caller_role FROM profiles p WHERE p.id = v_caller_id;
  IF v_caller_role IS NULL OR v_caller_role NOT IN ('teacher', 'admin') THEN
    RAISE EXCEPTION 'Only teachers and admins can save KG versions' USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY SELECT * FROM save_kg_version(p_student_id, p_kg_json, p_source_categories, v_caller_id);
END;
$$;


ALTER FUNCTION "contest"."save_kg_version_secure"("p_student_id" "text", "p_kg_json" "jsonb", "p_source_categories" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."set_inquiry_recommendation_generated"("p_id" "uuid", "p_selected_weakness_ids" "jsonb", "p_selected_anchor_subjects" "jsonb", "p_user_notes" "text", "p_recommendations" "jsonb", "p_ai_provider" "text", "p_ai_model" "text", "p_token_usage" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
DECLARE v_student_id text;
BEGIN
  SELECT student_id INTO v_student_id
    FROM contest.student_inquiry_recommendations
   WHERE id = p_id;
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'recommendation % not found', p_id;
  END IF;
  IF NOT contest.inquiry_design_can_access_student(v_student_id) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  UPDATE contest.student_inquiry_recommendations
     SET selected_weakness_ids = p_selected_weakness_ids,
         selected_anchor_subjects = p_selected_anchor_subjects,
         user_notes = p_user_notes,
         recommendations = p_recommendations,
         ai_provider = p_ai_provider,
         ai_model = p_ai_model,
         token_usage = COALESCE(p_token_usage, '{}'::jsonb),
         generated_at = now()
   WHERE id = p_id;
END;
$$;


ALTER FUNCTION "contest"."set_inquiry_recommendation_generated"("p_id" "uuid", "p_selected_weakness_ids" "jsonb", "p_selected_anchor_subjects" "jsonb", "p_user_notes" "text", "p_recommendations" "jsonb", "p_ai_provider" "text", "p_ai_model" "text", "p_token_usage" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."set_kg_entity_embedding"("p_kg_version_id" "uuid", "p_entity_id" "text", "p_embedding" "extensions"."vector") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
DECLARE v_student_id text;
BEGIN
  SELECT student_id INTO v_student_id
    FROM contest.student_kg_versions
   WHERE id = p_kg_version_id;
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'KG version % not found', p_kg_version_id;
