CREATE OR REPLACE FUNCTION "contest"."upsert_inquiry_analysis_cache"("p_cache_key" "text", "p_student_id" "text", "p_result" "jsonb", "p_model" "text", "p_prompt_tokens" integer DEFAULT 0, "p_completion_tokens" integer DEFAULT 0, "p_expires_at" timestamp with time zone DEFAULT ("now"() + '24:00:00'::interval)) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
begin
  if not contest.inquiry_design_can_access_student(p_student_id) then
    raise exception 'not allowed to write inquiry cache for student %', p_student_id;
  end if;

  insert into contest.inquiry_design_llm_cache (cache_key, student_id, result, model, prompt_tokens, completion_tokens, created_at, expires_at)
  values (p_cache_key, p_student_id, p_result, p_model, coalesce(p_prompt_tokens, 0), coalesce(p_completion_tokens, 0), now(), p_expires_at)
  on conflict (cache_key) do update set
    student_id = excluded.student_id,
    result = excluded.result,
    model = excluded.model,
    prompt_tokens = excluded.prompt_tokens,
    completion_tokens = excluded.completion_tokens,
    created_at = excluded.created_at,
    expires_at = excluded.expires_at;
end;
$$;


ALTER FUNCTION "contest"."upsert_inquiry_analysis_cache"("p_cache_key" "text", "p_student_id" "text", "p_result" "jsonb", "p_model" "text", "p_prompt_tokens" integer, "p_completion_tokens" integer, "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."upsert_inquiry_recommendation_prepare"("p_student_id" "text", "p_kg_version_id" "uuid", "p_metrics" "jsonb", "p_weaknesses" "jsonb", "p_enrolled_subjects" "jsonb", "p_current_grade" integer, "p_formula_version" "text" DEFAULT 'v1'::"text", "p_hygiene_findings" "jsonb" DEFAULT '{"missing_edges": [], "duplicate_clusters": []}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
declare
  v_id uuid;
begin
  if not contest.inquiry_design_can_access_student(p_student_id) then
    raise exception 'not allowed for student %', p_student_id;
  end if;

  insert into contest.student_inquiry_recommendations (
    student_id, kg_version_id, metrics, weaknesses, enrolled_subjects,
    current_grade, formula_version, hygiene_findings, prepared_by
  ) values (
    p_student_id, p_kg_version_id, p_metrics, p_weaknesses, p_enrolled_subjects,
    p_current_grade, p_formula_version, p_hygiene_findings, (select auth.uid())
  )
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "contest"."upsert_inquiry_recommendation_prepare"("p_student_id" "text", "p_kg_version_id" "uuid", "p_metrics" "jsonb", "p_weaknesses" "jsonb", "p_enrolled_subjects" "jsonb", "p_current_grade" integer, "p_formula_version" "text", "p_hygiene_findings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest"."verify_kg_version_integrity"("p_student_id" "text") RETURNS TABLE("total_versions" integer, "max_version" integer, "min_version" integer, "versions_contiguous" boolean, "min_created_at" timestamp with time zone, "max_created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'contest'
    AS $$
DECLARE
  v_total INTEGER; v_max INTEGER; v_min INTEGER;
  v_min_ts TIMESTAMPTZ; v_max_ts TIMESTAMPTZ; v_contiguous BOOLEAN;
  v_caller_id UUID; v_caller_role TEXT;
BEGIN
  IF p_student_id IS NULL OR p_student_id = '' THEN
    RAISE EXCEPTION 'student_id is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT p.role INTO v_caller_role FROM profiles p WHERE p.id = v_caller_id;
  IF v_caller_role IS NULL OR v_caller_role NOT IN ('teacher', 'admin') THEN
    RAISE EXCEPTION 'Only teachers and admins can verify version integrity' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT COUNT(*)::INTEGER, COALESCE(MAX(skv.version), 0), COALESCE(MIN(skv.version), 0), MIN(skv.created_at), MAX(skv.created_at)
  INTO v_total, v_max, v_min, v_min_ts, v_max_ts FROM student_kg_versions skv WHERE skv.student_id = p_student_id;
  v_contiguous := (v_total = 0) OR (v_min = 1 AND v_max = v_total);
  RETURN QUERY SELECT v_total, v_max, v_min, v_contiguous, v_min_ts, v_max_ts;
END;
$$;


ALTER FUNCTION "contest"."verify_kg_version_integrity"("p_student_id" "text") OWNER TO "postgres";


