CREATE OR REPLACE FUNCTION "contest_private"."friend_notify"("p_user" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_surface" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r uuid; s text := case when p_surface = 'tamagotchi' then 'tamagotchi' else 'academy' end;
begin
  select res.id into r from contest.profiles p
    join contest.resource res on res.type='student' and res.status='active' and res.meta->>'id'=split_part(p.email,'@',1)
   where p.id=p_user limit 1;
  if r is null then return; end if;
  insert into contest.notification_events(resource_id,type,title,message,meta)
  values(r,p_type,p_title,p_message,jsonb_build_object(
    'link', case s when 'tamagotchi' then '/tamagotchi?friends=requests' else '/academy?friends=1' end,
    'surface', s));
end $$;


