CREATE OR REPLACE FUNCTION "contest_private"."friend_room"("p_friend" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); admin boolean:=contest_private.workshop_admin();
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode='42501'; end if;
  if p_friend is null or not contest_private.friend_student(p_friend) then raise exception '방문할 친구를 선택해 주세요.'; end if;
  if not (p_friend=u or admin or (contest_private.friend_student(u) and contest_private.are_friends(u,p_friend))) then
    raise exception '친구의 방만 방문할 수 있어요.' using errcode='42501';
  end if;
  return jsonb_build_object(
    'owner',jsonb_build_object('id',p_friend,'name',contest_private.friend_name(p_friend),
      'share_telescope',coalesce((select share_telescope from contest.academy_friend_profiles where user_id=p_friend),false)),
    'outfit',coalesce((select jsonb_object_agg(i.academy_slot,jsonb_build_object('asset',i.academy_asset,'image_path',i.image_url))
        from contest.academy_user_items o join contest.academy_shop_items i on i.id=o.item_id
       where o.user_id=p_friend and o.is_equipped and i.academy_slot in ('room','ria')),'{}'::jsonb),
    'guestbook',coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
        select jsonb_build_object('id',g.id,'author_id',g.author_id,'author_name',contest_private.friend_name(g.author_id),'body',g.body,
          'created_at',g.created_at,'can_delete',(g.author_id=u or g.owner_id=u or admin)) x
          from contest.academy_guestbook_entries g where g.owner_id=p_friend order by g.created_at desc limit 50) s),'[]'::jsonb));
end $$;


