    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if p_code like 'experience:%' then
  return query select (jsonb_populate_record(null::contest.student_inquiry_designs,r.data||jsonb_build_object('id',r.id,'created_at',r.created_at,'updated_at',r.updated_at))).* from contest.academy_experience_records r where r.id=p_id and r.kind='design' and 'experience:'||r.owner_id::text=p_code;
 else return query select * from contest.student_inquiry_designs where id=p_id and student_id=p_code for update;
 end if;
end $$;


