CREATE OR REPLACE FUNCTION "contest_private"."post_chapter_write"("p_action" "text", "p_revision" integer, "p_news" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); c contest.academy_chapters; n contest.ai_news; q text;
begin
 if u is null or not exists(select 1 from contest.profiles where id=u and role in ('student','teacher','admin')) then raise exception '학생 본인만 챕터를 진행할 수 있어요.' using errcode='42501'; end if;
 if p_action is null or p_action not in ('start','next','arrive','read','note') or p_revision is null or p_revision<0 then raise exception '다음 행동을 확인해 주세요.'; end if;
 if not exists(select 1 from contest.academy_chapters where user_id=u and chapter='dorm_first_plan' and completed_at is not null) then raise exception '제3장을 마친 뒤 광장에서 루온과 만나 주세요.'; end if;
 -- Same lock as coin payments and other chapters, including reward delivery.
 perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));
 if p_action='start' then insert into contest.academy_chapters(user_id,chapter) values(u,'post_first_letter') on conflict do nothing; end if;
 select * into c from contest.academy_chapters where user_id=u and chapter='post_first_letter' for update;
 if not found then raise exception '아침 광장에서 루온과 이야기를 시작해 주세요.'; end if;
 if p_action='start' or c.revision<>p_revision or c.step=30 then return to_jsonb(c); end if;
 if (p_action='next' and c.step in (12,20,22)) or (p_action='arrive' and c.step<>12) or (p_action='read' and c.step<>20) or (p_action='note' and c.step<>22) then raise exception '노엘이 안내한 행동을 마친 뒤 이야기를 이어가세요.'; end if;
 if p_action='read' then
   select * into n from contest.ai_news where id=p_news and keep and id=contest_private.latest_chapter_letter() for share;
   if not found then raise exception '네 컷 이야기가 담긴 최신 편지를 다시 확인해 주세요.'; end if;
 end if;
 if p_action='note' then
   select i.question into q from contest.world_news_inquiries i where i.user_id=u and i.news_id=c.news_id and i.updated_at>=c.read_at and char_length(btrim(i.question))>0 for share;
   if not found then raise exception '방금 읽은 편지에 나의 질문을 적고 관측 일지를 보관해 주세요.'; end if;
 end if;
 update contest.academy_chapters set step=step+1,revision=revision+1,updated_at=now(),
 news_id=case when p_action='read' then n.id else news_id end,
 news_title=case when p_action='read' then n.title else news_title end,
 read_at=case when p_action='read' then now() else read_at end,
 question=case when p_action='note' then q else question end,
 completed_at=case when step=29 then now() else completed_at end
 where user_id=u and chapter='post_first_letter' returning * into c;
 return to_jsonb(c);
end $$;


ALTER FUNCTION "contest_private"."post_chapter_write"("p_action" "text", "p_revision" integer, "p_news" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."postlude_write"("p_step" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); c contest.academy_chapters;
begin
 if u is null or not exists(select 1 from contest.profiles where id=u and role in ('student','teacher','admin')) then raise exception '본인만 이야기를 기록할 수 있어요.' using errcode='42501';end if;
 if p_step is null or p_step not between 0 and 9 then raise exception '대사의 책갈피를 확인해 주세요.';end if;
 perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));
 select * into c from contest.academy_chapters where user_id=u and chapter='post_first_letter' and completed_at is not null for update;
 if not found then raise exception '제4장을 마친 뒤 광장에서 만나요.';end if;
 if c.postlude_step<>p_step or c.postlude_step=9 then return to_jsonb(c);end if;
 update contest.academy_chapters set postlude_step=postlude_step+1,
 postlude_completed_at=case when postlude_step=8 then now() else null end,updated_at=now()
 where user_id=u and chapter='post_first_letter' returning * into c;
 return to_jsonb(c);
end $$;


ALTER FUNCTION "contest_private"."postlude_write"("p_step" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."protect_study_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if row(new.id,new.student_id,new.room_id,new.reservation_date,new.period_id) is distinct from
    row(old.id,old.student_id,old.room_id,old.reservation_date,old.period_id)
    and (old.is_attended or old.attendance_status is not null or exists(select 1 from contest.academy_study_rewards where reservation_id=old.id))
    and not exists(select 1 from contest.profiles where id=auth.uid() and role in ('teacher','admin')) then
   raise exception '출석 확인된 자습의 날짜와 회차는 담당 교사만 변경할 수 있어요.' using errcode='42501';
 end if;
 return new;
end $$;


ALTER FUNCTION "contest_private"."protect_study_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."purchase_item"("p_item" integer, "p_expected_price" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare u uuid:=auth.uid(); i contest.academy_shop_items; maker uuid; oid uuid; wallet uuid; credited integer;

begin

 if u is null or not exists(select 1 from contest.profiles where id=u and role in ('student','teacher','admin')) then raise exception '학생 본인만 구매할 수 있어요.' using errcode='42501'; end if;

 select * into i from contest.academy_shop_items where id=p_item and academy_slot is not null for share;

 if not found or not i.is_active or i.price is null or i.price<0 then raise exception '판매 중인 상품을 선택해 주세요.'; end if;

 if i.academy_asset like 'workshop:%' then

  select id,student_id into oid,maker from contest.academy_workshop_orders where item_id=i.id and status in ('delivered','received');

  if oid is null or i.price not between 20 and 50 or i.academy_owner is distinct from maker then raise exception '공방 작품의 판매 정보를 다시 확인해 주세요.'; end if;

  if p_expected_price is distinct from i.price then raise exception '진열 가격이 바뀌었어요. 새 가격을 확인하고 다시 구매해 주세요.'; end if;

  if maker=u then raise exception '직접 의뢰한 작품은 배송함에서 추가 비용 없이 받아 주세요.'; end if;

 end if;

 -- Reciprocal purchases lock both wallets in the same UUID order, before any writes.

 for wallet in select distinct x from unnest(array[u,maker]) x where x is not null order by x loop

  perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||wallet::text,0));

  insert into contest.academy_user_stats(user_id) values(wallet) on conflict(user_id) do nothing;

 end loop;

 if exists(select 1 from contest.academy_user_items where user_id=u and item_id=i.id) then return jsonb_build_object('already_owned',true); end if;

 update contest.academy_user_stats set coins=coins-i.price,updated_at=now() where user_id=u and coins>=i.price;

 if not found then raise exception '코인이 부족해요.'; end if;

 insert into contest.academy_user_items(user_id,item_id,item_type,is_equipped) values(u,i.id,i.type,false);

 if maker is not null then

  insert into contest.academy_workshop_commissions(order_id,buyer_id,recipient_id,sale_price) values(oid,u,maker,i.price) on conflict(order_id,buyer_id) do nothing;

  get diagnostics credited=row_count;

  if credited=1 then update contest.academy_user_stats set coins=coins+10,updated_at=now() where user_id=maker; end if;

 end if;

 return jsonb_build_object('ok',true);

end $$;


ALTER FUNCTION "contest_private"."purchase_item"("p_item" integer, "p_expected_price" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."reading_card_write"("p_action" "text", "p_id" "uuid" DEFAULT NULL::"uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); c contest.academy_reading_cards; b uuid:=nullif(p_payload->>'book_id','')::uuid;
begin
 if u is null or not exists(select 1 from contest.profiles where id=u and role in ('student','teacher','admin')) then raise exception '본인만 설명 카드를 적을 수 있어요.' using errcode='42501'; end if;
 if p_action is null or p_action not in ('save','delete') then raise exception '카드에서 할 일을 선택해 주세요.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('academy-reading:'||u::text,0));
 if p_action='delete' then
  delete from contest.academy_reading_cards where id=p_id and user_id=u returning * into c;
  if not found then raise exception '나의 카드를 선택해 주세요.' using errcode='42501'; end if;
  return to_jsonb(c);
 end if;
 if b is not null and not exists(select 1 from contest.academy_book_recommendations where id=b) then raise exception '추천 서가의 책을 선택해 주세요.'; end if;
 if char_length(btrim(coalesce(p_payload->>'book_title',''))) not between 1 and 200 then raise exception '어떤 책(또는 글)인지 제목을 적어 주세요.'; end if;
 if char_length(btrim(coalesce(p_payload->>'concept',''))) not between 3 and 200 then raise exception '이번 독서로 알고 싶은 것 하나를 3자 이상으로 적어 주세요.'; end if;
 if char_length(btrim(coalesce(p_payload->>'explanation','')))>1000 then raise exception '설명은 1,000자까지예요. 한 가지 생각만 담아 보세요.'; end if;
 if char_length(coalesce(p_payload->>'stuck',''))>500 or char_length(coalesce(p_payload->>'simplified',''))>1000 then raise exception '막힌 곳은 500자, 다듬은 설명은 1,000자까지예요.'; end if;
 if p_id is null then
  insert into contest.academy_reading_cards(user_id,book_id,book_title,concept,explanation,stuck,simplified)
  values(u,b,btrim(p_payload->>'book_title'),btrim(p_payload->>'concept'),btrim(coalesce(p_payload->>'explanation','')),btrim(coalesce(p_payload->>'stuck','')),btrim(coalesce(p_payload->>'simplified','')))
  returning * into c;
 else
  update contest.academy_reading_cards set book_id=b,book_title=btrim(p_payload->>'book_title'),concept=btrim(p_payload->>'concept'),explanation=btrim(coalesce(p_payload->>'explanation','')),
   stuck=btrim(coalesce(p_payload->>'stuck','')),simplified=btrim(coalesce(p_payload->>'simplified','')),updated_at=now() where id=p_id and user_id=u returning * into c;
  if not found then raise exception '나의 카드를 선택해 주세요.' using errcode='42501'; end if;
 end if;
 return to_jsonb(c);
end $$;


ALTER FUNCTION "contest_private"."reading_card_write"("p_action" "text", "p_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."reading_chapter_write"("p_action" "text", "p_revision" integer, "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); c contest.academy_chapters; b contest.academy_book_recommendations; k contest.academy_reading_cards;
begin
 if u is null or not exists(select 1 from contest.profiles where id=u and role in ('student','teacher','admin')) then raise exception '본인만 이야기를 기록할 수 있어요.' using errcode='42501'; end if;
 if p_action is null or p_action not in ('start','next','field','card') or p_revision is null or p_revision<0 then raise exception '다음 행동을 확인해 주세요.'; end if;
 if not exists(select 1 from contest.academy_chapters where user_id=u and chapter='sky_first_light' and completed_at is not null) then raise exception '제5장을 마친 뒤 도서관에서 만나요.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));
 if p_action='start' then insert into contest.academy_chapters(user_id,chapter) values(u,'library_reading') on conflict do nothing; end if;
 select * into c from contest.academy_chapters where user_id=u and chapter='library_reading' for update;
 if not found then raise exception '도서관에서 이야기를 시작해 주세요.'; end if;
 if p_action='start' or c.revision<>p_revision or c.step=17 then return to_jsonb(c); end if;
 if (p_action='next' and c.step in (8,12)) or (p_action='field' and c.step<>8) or (p_action='card' and c.step<>12) then raise exception '안내받은 행동을 마친 뒤 이야기를 이어가 주세요.'; end if;
 if p_action='field' then
  select * into b from contest.academy_book_recommendations where id=nullif(p_payload->>'book_id','')::uuid;
  if not found then raise exception '추천 서가에서 읽어 볼 책 한 권을 골라 주세요.'; end if;
 end if;
 if p_action='card' then
  select * into k from contest.academy_reading_cards where id=nullif(p_payload->>'card_id','')::uuid and user_id=u;
  if not found then raise exception '내가 적은 설명 카드를 골라 주세요.' using errcode='42501'; end if;
 end if;
 update contest.academy_chapters set step=step+1,revision=revision+1,updated_at=now(),
  reading_field=case when p_action='field' then b.field else reading_field end,
  reading_book_id=case when p_action='field' then b.id else reading_book_id end,
  reading_book_title=case when p_action='field' then b.title else reading_book_title end,
  reading_card_id=case when p_action='card' then k.id else reading_card_id end,
  completed_at=case when step=16 then now() else completed_at end
 where user_id=u and chapter='library_reading' returning * into c;
 return to_jsonb(c);
end $$;


ALTER FUNCTION "contest_private"."reading_chapter_write"("p_action" "text", "p_revision" integer, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."roommate_read"("p_student_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); actor_role text; h integer:=extract(hour from now() at time zone 'Asia/Seoul');
begin
 select role into actor_role from contest.profiles where id=u;
 if u is null or actor_role is null or actor_role not in ('student','teacher','admin') then raise exception 'Student or administrator required' using errcode='42501'; end if;
 if p_student_code is not null then
  if actor_role<>'admin' then raise exception 'Cannot preview another student' using errcode='42501'; end if;
  select p.id into u from contest.profiles p where p.role='student' and split_part(p.email,'@',1)=p_student_code and exists(select 1 from contest.student_basic_info s where s.id=p_student_code) order by p.id limit 1;
 end if;
 return jsonb_build_object('day',(now() at time zone 'Asia/Seoul')::date,
  'period',case when h>=5 and h<12 then 'morning' when h>=12 and h<18 then 'daytime' else 'evening' end,
  'assessments',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from (select * from contest.academy_self_assessments where user_id=u order by created_at desc limit 30) a),'[]'::jsonb),
  'conversations',coalesce((select jsonb_agg(to_jsonb(c)-'lease_token' order by c.day desc) from (select * from contest.academy_roommate_conversations where user_id=u order by day desc limit 60) c),'[]'::jsonb));
end $$;


ALTER FUNCTION "contest_private"."roommate_read"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."sky_chapter_write"("p_action" "text", "p_revision" integer, "p_record" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); c contest.academy_chapters; p contest.academy_plans; g contest.academy_user_goals;
begin
 if u is null or not exists(select 1 from contest.profiles where id=u and role in ('student','teacher','admin')) then raise exception '본인만 이야기를 기록할 수 있어요.' using errcode='42501'; end if;
 if p_action is null or p_action not in ('start','next','arrive','light','place') or p_revision is null or p_revision<0 then raise exception '다음 행동을 확인해 주세요.'; end if;
 if not exists(select 1 from contest.academy_chapters where user_id=u and chapter='post_first_letter' and completed_at is not null) then raise exception '제4장을 마친 뒤 저녁 광장에서 만나요.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));
 
 if not exists(select 1 from contest.academy_chapters where user_id=u and chapter='sky_first_light') then
  if not exists(select 1 from contest.academy_chapters where user_id=u and chapter='post_first_letter' and postlude_completed_at is not null) then
   raise exception '먼저 중앙 광장에서 루온과 이야기를 마쳐 주세요.';
  end if;
  if (contest_private.sky_eligibility(u)->>'completed_plans')::integer<5 then
   raise exception '한 목표에 연결된 서로 다른 계획 다섯 개를 실천한 뒤 루온을 찾아 주세요.';
  end if;
 end if;
 if p_action='start' then insert into contest.academy_chapters(user_id,chapter) values(u,'sky_first_light') on conflict do nothing; end if;
 select * into c from contest.academy_chapters where user_id=u and chapter='sky_first_light' for update;
 if not found then raise exception '광장에서 이야기를 시작해 주세요.'; end if;
 if p_action='start' or c.revision<>p_revision or c.step=29 then return to_jsonb(c); end if;
 if (p_action='next' and c.step in (16,21,22)) or (p_action='arrive' and c.step<>16) or (p_action='light' and c.step<>21) or (p_action='place' and c.step<>22) then raise exception '안내받은 행동을 마친 뒤 이야기를 이어가 주세요.'; end if;
 if p_action in ('light','place') then
  select pl.* into p from contest.academy_plans pl join contest.academy_user_goals gg on gg.id=pl.goal_id and gg.user_id=u
  where pl.user_id=u and not pl.is_archived and not gg.is_archived
  and (nullif(p_record->>'plan_id','') is null or pl.id=(p_record->>'plan_id')::uuid)
  and exists(select 1 from contest.academy_tasks t where t.plan_id=pl.id and t.user_id=u and t.completed)
  order by (pl.id=c.sky_plan_id) desc nulls last,pl.created_at,pl.id limit 1 for update of pl;
  if not found then raise exception '목표에 연결된 계획 하나에 실천 표시를 해 주세요.'; end if;
  if p_action='place' then
   select * into g from contest.academy_user_goals where id=p.goal_id and user_id=u for update;
   -- A stored star is a durable recovery point, even if another tab advanced the sky first.
   if p.sky_x is null then
    if g.sky_x is null then
     perform contest_private.sky_write('place_constellation',g.id,null,coalesce((p_record->>'goal_x')::numeric,.5),coalesce((p_record->>'goal_y')::numeric,.5),null,null,g.constellation_revision);
     select * into g from contest.academy_user_goals where id=g.id;
    end if;
    perform contest_private.sky_write('place_star',g.id,p.id,(p_record->>'x')::numeric,(p_record->>'y')::numeric,null,null,g.constellation_revision);
   end if;
  end if;
 end if;
 update contest.academy_chapters set step=step+1,revision=revision+1,updated_at=now(),
 sky_plan_id=case when p_action in ('light','place') then p.id else sky_plan_id end,
 sky_plan_title=case when p_action in ('light','place') then p.title else sky_plan_title end,
 sky_goal_id=case when p_action in ('light','place') then p.goal_id else sky_goal_id end,
 completed_at=case when step=28 then now() else completed_at end
 where user_id=u and chapter='sky_first_light' returning * into c;
 return to_jsonb(c);
end $$;


ALTER FUNCTION "contest_private"."sky_chapter_write"("p_action" "text", "p_revision" integer, "p_record" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."sky_eligibility"("p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select jsonb_build_object('completed_plans',coalesce(max(n),0),'required_plans',5)
 from (select count(*) n from contest.academy_plans p
 join contest.academy_user_goals g on g.id=p.goal_id and g.user_id=p_user
 where p.user_id=p_user and not p.is_archived and not g.is_archived
 and exists(select 1 from contest.academy_tasks t where t.plan_id=p.id and t.user_id=p_user and t.completed)
 group by p.goal_id) counts;
$$;


ALTER FUNCTION "contest_private"."sky_eligibility"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."sky_plans"("p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object(
 'practice_count',(select count(*) from contest.academy_tasks t where t.plan_id=p.id and t.user_id=p_user and t.completed),
 'records',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'date',t.task_date,'feedback',(select f.comment from contest.academy_task_feedback f where f.task_id=t.id and f.user_id=p_user order by f.created_at desc,f.id desc limit 1)) order by t.task_date desc) from contest.academy_tasks t where t.plan_id=p.id and t.user_id=p_user and t.completed),'[]'::jsonb)) order by p.created_at,p.id),'[]'::jsonb) from contest.academy_plans p where p.user_id=p_user;
$$;


ALTER FUNCTION "contest_private"."sky_plans"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."sky_region_write"("p_region" integer, "p_goal" "uuid" DEFAULT NULL::"uuid", "p_x" numeric DEFAULT 0.5, "p_y" numeric DEFAULT 0.5, "p_name" "text" DEFAULT NULL::"text", "p_revision" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); g contest.academy_user_goals; r contest.academy_sky_regions;
begin
 if u is null or not exists(select 1 from contest.profiles where id=u and role in ('student','teacher','admin')) then raise exception '본인만 하늘을 기록할 수 있어요.' using errcode='42501'; end if;
 if p_region is null or p_region not between 0 and 9995 then raise exception '하늘을 선택해 주세요.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));
 if p_goal is null then
  if char_length(btrim(coalesce(p_name,'')))>60 then raise exception '하늘 이름은 60자까지 적을 수 있어요.'; end if;
  insert into contest.academy_sky_regions(user_id,region) values(u,p_region) on conflict do nothing;
  select * into r from contest.academy_sky_regions where user_id=u and region=p_region for update;
  if p_revision is null or p_revision<>r.revision then raise exception '다른 창에서 하늘 이름이 바뀌었어요. 다시 확인해 주세요.' using errcode='40001'; end if;
  update contest.academy_sky_regions set name=nullif(btrim(p_name),''),revision=revision+1 where user_id=u and region=p_region returning * into r;
  return to_jsonb(r);
 end if;
 select * into g from contest.academy_user_goals where id=p_goal and user_id=u for update;
 if not found then raise exception '나의 별자리를 선택해 주세요.' using errcode='42501'; end if;
 if g.is_archived then raise exception '계획장에서 목표를 다시 꺼내 주세요.'; end if;
 if p_revision is null or p_revision<>g.constellation_revision then raise exception '다른 창에서 하늘이 바뀌었어요. 다시 확인해 주세요.' using errcode='40001'; end if;
 if p_x is null or p_y is null or not(p_x between 0 and 1 and p_y between 0 and 1) then raise exception '하늘 안의 자리를 선택해 주세요.'; end if;
 if (select count(*) from contest.academy_user_goals where user_id=u and sky_region=p_region and id<>p_goal)>=8 then raise exception '하나의 하늘에는 별자리를 여덟 개까지 담을 수 있어요.'; end if;
 insert into contest.academy_sky_regions(user_id,region) values(u,p_region) on conflict do nothing;
 update contest.academy_user_goals set sky_region=p_region,sky_x=p_x,sky_y=p_y,constellation_revision=constellation_revision+1,updated_at=now() where id=g.id returning * into g;
 return to_jsonb(g);
end $$;


ALTER FUNCTION "contest_private"."sky_region_write"("p_region" integer, "p_goal" "uuid", "p_x" numeric, "p_y" numeric, "p_name" "text", "p_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."sky_write"("p_action" "text", "p_goal" "uuid", "p_plan" "uuid" DEFAULT NULL::"uuid", "p_x" numeric DEFAULT NULL::numeric, "p_y" numeric DEFAULT NULL::numeric, "p_lines" "jsonb" DEFAULT NULL::"jsonb", "p_name" "text" DEFAULT NULL::"text", "p_revision" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); g contest.academy_user_goals; p contest.academy_plans; edge jsonb; a uuid; b uuid; seen text[]:='{}'; endpoints uuid[]:='{}'; canonical text;
begin
 if u is null or not exists(select 1 from contest.profiles where id=u and role in ('student','teacher','admin')) then raise exception '본인만 하늘을 기록할 수 있어요.' using errcode='42501'; end if;
 if p_action is null or p_action not in ('place_constellation','place_star','set_lines','name') then raise exception '하늘에서 할 일을 선택해 주세요.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));
 select * into g from contest.academy_user_goals where id=p_goal and user_id=u for update;
 if not found then raise exception '나의 별자리를 선택해 주세요.' using errcode='42501'; end if;
 if g.is_archived then raise exception '미완의 성도는 보관 중이에요. 목표를 다시 꺼내 주세요.'; end if;
 if p_revision is null or p_revision<>g.constellation_revision then raise exception '다른 창에서 하늘이 바뀌었어요. 새로 읽은 하늘에서 다시 놓아 주세요.' using errcode='40001'; end if;
 if p_action in ('place_constellation','place_star') then
  if p_x is null or p_y is null or not(p_x between 0 and 1 and p_y between 0 and 1) then raise exception '하늘 안의 자리를 선택해 주세요.'; end if;
  if not exists(select 1 from contest.academy_tasks t join contest.academy_plans pl on pl.id=t.plan_id where pl.goal_id=g.id and pl.user_id=u and t.user_id=u and t.completed) then raise exception '실천한 계획이 있어야 자리를 놓을 수 있어요.'; end if;
 end if;
 if p_action='place_star' then
  select * into p from contest.academy_plans where id=p_plan and user_id=u and goal_id=g.id and not is_archived for update;
  if not found then raise exception '이 별자리의 계획을 선택해 주세요.' using errcode='42501'; end if;
  if not exists(select 1 from contest.academy_tasks where plan_id=p.id and user_id=u and completed) then raise exception '실천 표시를 한 뒤 별을 놓아 주세요.'; end if;
  if g.sky_x is null then raise exception '먼저 별자리의 자리를 정해 주세요.'; end if;
  update contest.academy_plans set sky_x=p_x,sky_y=p_y,updated_at=now() where id=p.id;
 elsif p_action='place_constellation' then
  update contest.academy_user_goals set sky_x=p_x,sky_y=p_y where id=g.id;
 elsif p_action='name' then
  if not g.is_completed or char_length(btrim(coalesce(p_name,''))) not between 1 and 60 then raise exception '완료한 목표에 1~60자의 이름을 붙여 주세요.'; end if;
  update contest.academy_user_goals set constellation_name=btrim(p_name) where id=g.id;
 else
  if g.is_completed and g.constellation_name is not null then raise exception '이름을 붙인 별자리의 선은 완성되었어요.'; end if;
  if p_lines is null or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)>66 then raise exception '연결할 선을 확인해 주세요.'; end if;
  for edge in select value from jsonb_array_elements(p_lines) loop
   if jsonb_typeof(edge)<>'array' or jsonb_array_length(edge)<>2 then raise exception '선에는 두 별이 필요해요.'; end if;
   a:=(edge->>0)::uuid; b:=(edge->>1)::uuid;
   if a is null or b is null or a=b or (select count(*) from contest.academy_plans pl where pl.id in (a,b) and pl.goal_id=g.id and pl.user_id=u and not pl.is_archived and pl.sky_x is not null and exists(select 1 from contest.academy_tasks t where t.plan_id=pl.id and t.user_id=u and t.completed))<>2 then raise exception '같은 별자리의 밝혀진 두 별을 골라 주세요.'; end if;
   canonical:=least(a,b)::text||':'||greatest(a,b)::text;
   if canonical=any(seen) then raise exception '같은 선은 한 번만 이을 수 있어요.'; end if;
   seen:=array_append(seen,canonical); endpoints:=endpoints||array[a,b];
  end loop;
  if (select count(distinct x) from unnest(endpoints) x)>12 then raise exception '한 별자리에서 잇는 별은 열두 개까지예요.'; end if;
  update contest.academy_user_goals set constellation_lines=p_lines where id=g.id;
 end if;
 update contest.academy_user_goals set constellation_revision=constellation_revision+1,updated_at=now() where id=g.id returning * into g;
 return to_jsonb(g);
end $$;


ALTER FUNCTION "contest_private"."sky_write"("p_action" "text", "p_goal" "uuid", "p_plan" "uuid", "p_x" numeric, "p_y" numeric, "p_lines" "jsonb", "p_name" "text", "p_revision" integer) OWNER TO "postgres";


