    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ begin raise exception '공모전판에는 자습실 연동이 없어요.' using errcode = '0A000'; end $$;


ALTER FUNCTION "contest_private"."study_claim"("p_week" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."study_read"("p_week" "date" DEFAULT NULL::"date", "p_student_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid:=auth.uid(); actor text; today date:=(now() at time zone 'Asia/Seoul')::date;
 latest date:=date_trunc('week',today::timestamp)::date; w date:=coalesce(p_week,latest);
begin
 select role into actor from contest.profiles where id=u;
 if u is null or actor is null or actor not in ('student','teacher','admin') then raise exception '학생 또는 관리자만 열람할 수 있어요.' using errcode='42501'; end if;
 if p_student_code is not null then
   if actor<>'admin' then raise exception '다른 학생의 기록은 열람할 수 없어요.' using errcode='42501'; end if;
   select p.id into u from contest.profiles p where p.role='student' and split_part(p.email,'@',1)=p_student_code and exists(select 1 from contest.student_basic_info s where s.id=p_student_code) order by p.id limit 1;
   if u is null then raise exception '미리 볼 학생을 확인해 주세요.'; end if;
 end if;
 if w<date '2026-09-07' or w>latest or extract(isodow from w)<>1 then raise exception '2026년 9월 7일부터 이번 주까지의 월요일을 선택해 주세요.'; end if;
 return jsonb_build_object('week',w,'today',today,'first_week','2026-09-07','latest_week',latest,'claim_from',greatest(date '2026-09-07',latest-7),
   'coins',coalesce((select coins from contest.academy_user_stats where user_id=u),100),
   'entries',coalesce((select jsonb_agg(case when contest_private.experience_study_source(u) is distinct from u then to_jsonb(x)||jsonb_build_object('claimed',exists(select 1 from contest.academy_experience_study_rewards r where r.owner_id=u and r.reservation_id=x.id)) else to_jsonb(x) end) from contest_private.study_rows(contest_private.experience_study_source(u),w) x),'[]'::jsonb),
   'claimed_coins',case when contest_private.experience_study_source(u) is distinct from u then coalesce((select sum(amount) from contest.academy_experience_study_rewards where owner_id=u and reservation_date>=w and reservation_date<w+7),0) else coalesce((select sum(amount) from contest.academy_study_rewards where user_id=u and reservation_date>=w and reservation_date<w+7),0) end);
end $$;


