CREATE OR REPLACE FUNCTION "contest_private"."wake_generation_worker"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c contest_private.generation_worker_config;
begin
 if not exists(select 1 from contest.academy_generation_jobs where (status in ('queued','retry') and available_at<=now()) or (status='running' and lease_until<now())) then return; end if;
 select * into c from contest_private.generation_worker_config where singleton;
 perform net.http_post(url:=c.url,headers:=jsonb_build_object('Content-Type','application/json','x-academy-worker',c.secret),body:='{}'::jsonb,timeout_milliseconds:=3000);
end $$;


