    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select auth.uid() is not null and exists(select 1 from contest.profiles where id=auth.uid() and role='admin');
$$;


ALTER FUNCTION "contest_private"."workshop_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."workshop_read"("p_status" "text" DEFAULT NULL::"text", "p_offset" integer DEFAULT 0, "p_student_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare u uuid:=auth.uid(); admin boolean:=contest_private.workshop_admin(); actor text;

begin

 select role into actor from contest.profiles where id=u;

 if u is null or actor is null or actor not in ('student','teacher','admin') then raise exception '공방 주문을 열 권한이 없어요.' using errcode='42501'; end if;

 if p_student_code is not null then

  if not admin then raise exception '다른 학생의 주문을 볼 수 없어요.' using errcode='42501'; end if;

  select id into u from contest.profiles where role='student' and split_part(email,'@',1)=p_student_code order by id limit 1;

  admin:=false;

 end if;

 return jsonb_build_object('orders',coalesce((select jsonb_agg(x order by x.created_at desc,x.id desc) from (

  select o.*,coalesce(c.sales,0) as commission_count,coalesce(c.coins,0) as commission_coins,coalesce(p.name,p.nickname,'학생') as student_name,split_part(p.email,'@',1) as student_code

  from contest.academy_workshop_orders o join contest.profiles p on p.id=o.student_id

  left join lateral (select count(*) as sales,sum(amount) as coins from contest.academy_workshop_commissions where order_id=o.id) c on true

  where (admin or o.student_id=u) and (p_status is null or o.status=p_status)

  order by o.created_at desc,o.id desc limit 50 offset greatest(0,least(coalesce(p_offset,0),100000))

 ) x),'[]'::jsonb),'total',(select count(*) from contest.academy_workshop_orders o where (admin or o.student_id=u) and (p_status is null or o.status=p_status)));

end $$;


ALTER FUNCTION "contest_private"."workshop_read"("p_status" "text", "p_offset" integer, "p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "contest_private"."workshop_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$

declare u uuid:=auth.uid(); actor text; o contest.academy_workshop_orders; token uuid; iid integer; path text; note text; recipient uuid; price integer;

begin

 select role into actor from contest.profiles where id=u;

 if u is null or actor is null or actor not in ('student','teacher','admin') then raise exception '공방 주문을 처리할 권한이 없어요.' using errcode='42501'; end if;

 if p_action='submit' then

  if actor not in ('student','teacher','admin') then raise exception '학생 본인만 주문할 수 있어요.' using errcode='42501'; end if;

  perform pg_advisory_xact_lock(hashtextextended('academy-workshop:'||u::text,0));

  token:=(p_payload->>'client_token')::uuid;

  select * into o from contest.academy_workshop_orders where student_id=u and client_token=token;

  if found then return to_jsonb(o); end if;

  if (select count(*) from contest.academy_workshop_orders where student_id=u and status in ('submitted','crafting'))>=3 then raise exception '제작을 기다리는 주문은 세 개까지 맡길 수 있어요.'; end if;

  if p_payload->>'confirm_cost' is distinct from '100' or p_payload->>'publish_design' is distinct from 'true' then raise exception '100코인 제작비와 작품 진열 안내를 확인한 뒤 의뢰해 주세요.'; end if;

  perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));

  insert into contest.academy_user_stats(user_id) values(u) on conflict(user_id) do nothing;

  update contest.academy_user_stats set coins=coins-100,updated_at=now() where user_id=u and coins>=100;

  if not found then raise exception '맞춤 제작에는 100코인이 필요해요.'; end if;

  price:=35; -- Ignore prices submitted by older clients.

  insert into contest.academy_workshop_orders(student_id,client_token,slot,title,prompt,charged_coins,sale_price)

   values(u,token,p_payload->>'slot',btrim(p_payload->>'title'),btrim(p_payload->>'prompt'),100,price) returning * into o;

  for recipient in select distinct ur.resource_id from contest.user_resource ur join contest.profiles p on p.id=ur.user_id where p.role='admin' loop

   insert into contest.notification_events(resource_id,type,title,message,priority,meta,is_read) values(recipient,'academy_workshop_submitted','새 공방 주문서',o.title||E'\n학생의 맞춤 제작 의뢰가 도착했습니다.','medium',jsonb_build_object('order_id',o.id),false);

  end loop;

  return to_jsonb(o);

 end if;

 select * into o from contest.academy_workshop_orders where id=(p_payload->>'id')::uuid for update;

 if not found or (actor<>'admin' and o.student_id<>u) then raise exception '주문을 찾을 수 없어요.' using errcode='42501'; end if;

 if p_action='set_price' then

  raise exception '맞춤 작품의 진열 가격은 35코인으로 고정되어 있어요.';

 end if;

 if p_action in ('cancel','receive') then

  if actor not in ('student','teacher','admin') or o.student_id<>u then raise exception '학생 본인만 수령하거나 취소할 수 있어요.' using errcode='42501'; end if;

  if p_action='cancel' then

   if o.status='cancelled' then return to_jsonb(o); end if;

   if o.status<>'submitted' then raise exception '제작 전의 주문만 취소할 수 있어요.'; end if;

   perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||o.student_id::text,0));

   update contest.academy_user_stats set coins=coins+o.charged_coins-o.refunded_coins,updated_at=now() where user_id=o.student_id;

   update contest.academy_workshop_orders set status='cancelled',refunded_coins=charged_coins,updated_at=now() where id=o.id returning * into o;

  else

   if o.status='received' then return to_jsonb(o); end if;

   if o.status<>'delivered' then raise exception '아직 선물 상자가 도착하지 않았어요.'; end if;

   perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||u::text,0));

   insert into contest.academy_user_items(user_id,item_id,item_type,is_equipped)

    select u,o.item_id,case when o.slot='room' then 'background' else 'accessory' end,false

    where not exists(select 1 from contest.academy_user_items where user_id=u and item_id=o.item_id);

   update contest.academy_workshop_orders set status='received',received_at=now(),updated_at=now() where id=o.id returning * into o;

  end if;

  return to_jsonb(o);

 end if;

 if actor<>'admin' then raise exception '관리자만 제작과 배송을 처리할 수 있어요.' using errcode='42501'; end if;

 if p_action='decline' and o.status='declined' then return to_jsonb(o); end if;

 if p_action='deliver' and o.status in ('delivered','received') then return to_jsonb(o); end if;

 if o.status not in ('submitted','crafting') then raise exception '이미 처리된 주문입니다. 목록을 새로 열어 주세요.'; end if;

 note:=coalesce(p_payload->>'note','');

 if length(note)>1000 then raise exception '배송 편지는 1,000자까지 적을 수 있어요.'; end if;

 if p_action='start' then

  update contest.academy_workshop_orders set status='crafting',updated_at=now() where id=o.id returning * into o;

 elsif p_action='decline' then

  if length(btrim(note))<2 then raise exception '제작하지 못하는 이유를 학생에게 남겨 주세요.'; end if;

  perform pg_advisory_xact_lock(hashtextextended('academy-dorm:'||o.student_id::text,0));

  update contest.academy_user_stats set coins=coins+o.charged_coins-o.refunded_coins,updated_at=now() where user_id=o.student_id;

  update contest.academy_workshop_orders set status='declined',refunded_coins=charged_coins,admin_note=note,updated_at=now() where id=o.id returning * into o;

 elsif p_action='deliver' then

  path:=p_payload->>'image_path';

  if path is null or split_part(path,'/',1)<>o.id::text or path !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.png$'

   or not exists(select 1 from storage.objects where bucket_id='contest-academy-workshop' and name=path and metadata->>'mimetype'='image/png' and (metadata->>'size')::bigint between 1 and 10485760)

  then raise exception '이 주문에 등록한 PNG 이미지를 먼저 확인해 주세요.'; end if;

  insert into contest.academy_shop_items(name,description,price,type,rarity,is_active,academy_slot,academy_asset,academy_owner,image_url)

   values(o.title,'학생의 상상으로 제작한 왕립 공방 작품입니다.',o.sale_price,case when o.slot='room' then 'background' else 'accessory' end,'rare',true,o.slot,'workshop:'||o.id::text,o.student_id,path) returning id into iid;

  update contest.academy_workshop_orders set status='delivered',image_path=path,item_id=iid,admin_note=note,delivered_by=u,delivered_at=now(),updated_at=now() where id=o.id returning * into o;

 else raise exception '알 수 없는 공방 작업입니다.'; end if;

 if p_action in ('deliver','decline') then

  for recipient in

   select ur.resource_id from contest.user_resource ur where ur.user_id=o.student_id

   union select r.id from contest.resource r join contest.profiles p on p.id=o.student_id where r.type='student' and r.status='active' and r.meta->>'id'=split_part(p.email,'@',1)

  loop

   insert into contest.notification_events(resource_id,type,title,message,priority,meta,is_read) values(recipient,

    case when p_action='deliver' then 'academy_workshop_delivered' else 'academy_workshop_declined' end,

    case when p_action='deliver' then '공방에서 선물이 도착했어요' else '공방에서 답장이 왔어요' end,o.title||E'\n'||note,'medium',jsonb_build_object('order_id',o.id),false);

  end loop;

 end if;

 return to_jsonb(o);

end $_$;


