CREATE OR REPLACE FUNCTION "economy_private"."earn_rows"("p_user" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("user_id" "uuid", "at" timestamp with time zone, "amount" integer, "kind" "text", "note" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select l.user_id, l.created_at, l.delta, l.kind, coalesce(l.note, '')
    from public.wallet_ledger l
   where l.delta > 0 and l.kind not like 'invest\_%' and (p_user is null or l.user_id = p_user)
  union all
  select c.user_id, c.created_at, c.amount, 'tama_' || c.kind, ''
    from public.tama_credit_ledger c
   where c.amount > 0 and c.source_id not like 'forest:%' and (p_user is null or c.user_id = p_user)
  union all
  select r.user_id, r.awarded_at, r.amount, 'chapter', r.chapter
    from public.academy_chapter_rewards r
   where r.amount > 0 and (p_user is null or r.user_id = p_user)
  union all
  select r.user_id, r.claimed_at, r.amount, 'study_claim', r.reservation_date::text
    from public.academy_study_rewards r
   where r.source = 'claim' and r.amount > 0 and (p_user is null or r.user_id = p_user)
  union all
  select c.recipient_id, c.created_at, c.amount, 'workshop_commission', ''
    from public.academy_workshop_commissions c
   where c.amount > 0 and (p_user is null or c.recipient_id = p_user)
$$;


