CREATE OR REPLACE FUNCTION "economy_private"."spend_rows"("p_user" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("user_id" "uuid", "at" timestamp with time zone, "amount" integer, "kind" "text", "note" "text", "approx" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select l.user_id, l.created_at, -l.delta, l.kind, coalesce(l.note, ''), false
    from public.wallet_ledger l
   where l.delta < 0 and l.kind not in ('seaton_attendance_reversal', 'admin_revoke') and l.kind not like 'invest\_%'
     and (p_user is null or l.user_id = p_user)
  union all
  select g.owner, g.created_at, g.price - g.refund, 'gacha', g.machine || ':' || g.item_id, false
    from public.tama_gacha_log g
   where g.price - g.refund > 0 and (p_user is null or g.owner = p_user)
  union all
  select o.owner, o.created_at, o.charged_coins - o.refunded_coins, 'character_order', o.title, false
    from public.tama_character_order o
   where o.charged_coins - o.refunded_coins > 0 and (p_user is null or o.owner = p_user)
  union all
  select o.owner, o.created_at, o.charged_coins - o.refunded_coins, 'decor_order', o.title, false
    from public.tama_decor_order o
   where o.charged_coins - o.refunded_coins > 0 and (p_user is null or o.owner = p_user)
  union all
  select o.student_id, o.created_at, o.charged_coins - o.refunded_coins, 'workshop_order', o.title, false
    from public.academy_workshop_orders o
   where o.charged_coins - o.refunded_coins > 0 and (p_user is null or o.student_id = p_user)
  union all
  select c.buyer_id, c.created_at, c.sale_price, 'workshop_purchase', coalesce(o.title, ''), false
    from public.academy_workshop_commissions c
    left join public.academy_workshop_orders o on o.id = c.order_id
   where c.sale_price > 0 and (p_user is null or c.buyer_id = p_user)
  union all
  select ui.user_id, ui.purchased_at, s.price, 'shop_purchase', s.name, true
    from public.academy_user_items ui
    join public.academy_shop_items s on s.id = ui.item_id
   where s.academy_slot is not null and coalesce(s.academy_asset, '') not like 'workshop:%' and s.price > 0
     and (p_user is null or ui.user_id = p_user)
  union all
  select w.owner, null::timestamptz, coalesce(tama_private.slot_price(n), 0), 'pet_slot', (n + 1) || '번째 자리', true
    from public.tama_wallet w
    cross join lateral generate_series(0, least(w.bought_slots, 3) - 1) n
   where w.bought_slots > 0 and not tama_private.user_is_admin(w.owner)
     and (p_user is null or w.owner = p_user)
$$;


