CREATE OR REPLACE FUNCTION "graduate_privacy_private"."anonymize_detailed_activities_on_graduation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  student_code text;
  name_mapping jsonb;
begin
  if new.type <> 'student'
     or new.status <> 'graduated'
     or coalesce(new.name, '') !~ '^[0-9]{4}입학[0-9]{3}$'
     or coalesce(old.name, '') = ''
     or old.name = new.name then
    return new;
  end if;

  student_code := coalesce(new.meta ->> 'id', old.meta ->> 'id');
  if student_code is null or btrim(student_code) = '' then
    raise exception 'A graduated student is missing a student code';
  end if;

  name_mapping := jsonb_build_array(jsonb_build_object(
    'old_name', old.name,
    'anonymous_name', new.name
  ));

  update public.student_detailed_activities activity
  set
    content = case
      when activity.content is null then null
      else replace(activity.content, old.name, new.name)
    end,
    data = graduate_privacy_private.replace_names_in_jsonb(
      activity.data,
      name_mapping
    ),
    analysis = graduate_privacy_private.replace_names_in_jsonb(
      activity.analysis,
      name_mapping
    ),
    updated_at = now()
  where lower(activity.student_id) = lower(student_code)
    and (
      position(old.name in coalesce(activity.content, '')) > 0
      or position(old.name in coalesce(activity.data::text, '')) > 0
      or position(old.name in coalesce(activity.analysis::text, '')) > 0
    );

  if exists (
    select 1
    from public.student_detailed_activities activity
    where lower(activity.student_id) = lower(student_code)
      and (
        position(old.name in coalesce(activity.content, '')) > 0
        or position(old.name in coalesce(activity.data::text, '')) > 0
        or position(old.name in coalesce(activity.analysis::text, '')) > 0
      )
  ) then
    raise exception 'Graduate detailed activity anonymization verification failed';
  end if;

  return new;
end;
$_$;


ALTER FUNCTION "graduate_privacy_private"."anonymize_detailed_activities_on_graduation"() OWNER TO "postgres";


COMMENT ON FUNCTION "graduate_privacy_private"."anonymize_detailed_activities_on_graduation"() IS 'Removes a student real name from detailed activity content and JSON when the resource is anonymized at graduation.';



CREATE OR REPLACE FUNCTION "graduate_privacy_private"."replace_names_in_jsonb"("p_value" "jsonb", "p_mapping" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
declare
  result_value jsonb;
  text_value text;
  mapping_item jsonb;
begin
  case jsonb_typeof(p_value)
    when 'object' then
      select jsonb_object_agg(
        entry.key,
        graduate_privacy_private.replace_names_in_jsonb(entry.value, p_mapping)
      )
      into result_value
      from jsonb_each(p_value) as entry;

      return coalesce(result_value, '{}'::jsonb);

    when 'array' then
      select jsonb_agg(
        graduate_privacy_private.replace_names_in_jsonb(entry.value, p_mapping)
        order by entry.ordinality
      )
      into result_value
      from jsonb_array_elements(p_value)
        with ordinality as entry(value, ordinality);

      return coalesce(result_value, '[]'::jsonb);

    when 'string' then
      text_value := p_value #>> '{}';

      for mapping_item in
        select item.value
        from jsonb_array_elements(p_mapping) as item(value)
        order by
          length(item.value ->> 'old_name') desc,
          convert_to(item.value ->> 'old_name', 'UTF8')
      loop
        text_value := replace(
          text_value,
          mapping_item ->> 'old_name',
          mapping_item ->> 'anonymous_name'
        );
      end loop;

      return to_jsonb(text_value);

    else
      return p_value;
  end case;
end;
$$;


ALTER FUNCTION "graduate_privacy_private"."replace_names_in_jsonb"("p_value" "jsonb", "p_mapping" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "graduate_privacy_private"."replace_names_in_jsonb"("p_value" "jsonb", "p_mapping" "jsonb") IS 'Internal recursive JSON helper for the admin-only graduate privacy transaction.';



