CREATE OR REPLACE FUNCTION "invest_private"."wake"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c invest_private.config; plan jsonb := public.invest_fetch_plan();
begin
  if jsonb_array_length(plan->'kr_days') = 0 and jsonb_array_length(plan->'twelve') = 0 and not (plan->>'fx_due')::boolean then
    return false;
  end if;
  select * into c from invest_private.config where singleton;
  perform net.http_post(url := c.url, body := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-invest-secret', c.secret), timeout_milliseconds := 140000);
  return true;
end $$;


