    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with recursive l(action_id, depth, path) as (
    select p_action, 0, array[p_action]
    union all
    select a.rolled_over_from, l.depth + 1, l.path || a.rolled_over_from
    from l join public.task_action a on a.id = l.action_id
    where a.rolled_over_from is not null and not (a.rolled_over_from = any (l.path)) and l.depth < 20
  )
  select l.action_id, l.depth from l;
$$;


