CREATE OR REPLACE FUNCTION "mcp_private"."bg_check"("p_project" "uuid", "p_draft" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with d as (
    select l.line_id, l.name, l.budget, l.pumui, l.wonin,
           coalesce((p_draft ->> l.line_id::text)::bigint, l.budget) as amount
    from mcp_private.bg_lines(p_project) l
  ), issues as (
    select jsonb_build_object('kind',
             case when amount < 0 then 'negative'
                  when amount = budget and amount < wonin then 'overspent'
                  when amount < wonin then 'below_wonin'
                  when amount < pumui then 'below_pumui' end,
             'line_id', line_id, 'name', name, 'amount', amount, 'wonin', wonin, 'pumui', pumui) j
    from d
    where amount < 0 or amount < wonin or amount < pumui
  )
  select jsonb_build_object(
    'issues', coalesce((select jsonb_agg(j) from issues), '[]'::jsonb),
    'total_now', (select coalesce(sum(budget), 0) from d),
    'total_after', (select coalesce(sum(amount), 0) from d),
    'total_mismatch', case when (select kind from budget_project where id = p_project) = 'purpose'
                           then (select coalesce(sum(amount), 0) - coalesce(sum(budget), 0) from d) end,
    'blocking', exists (select 1 from d where amount < 0 or (amount <> budget and amount < wonin)));
$$;


