CREATE OR REPLACE FUNCTION "mcp_private"."bg_lines"("p_project" "uuid") RETURNS TABLE("line_id" "uuid", "sort_order" integer, "expense_item" "text", "name" "text", "budget" bigint, "pumui" bigint, "wonin" bigint, "pending" bigint, "remaining_plan" bigint, "unassigned" bigint, "proposed" bigint, "closed" boolean, "origin" "text", "missing_from_card" boolean, "manual_override" boolean, "note" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select l.id, l.sort_order, l.expense_item, l.name, l.budget_amount, l.pumui, l.wonin,
         greatest(l.pumui - l.wonin, 0)::bigint,
         case when l.closed then 0 else coalesce(p.rem, 0) end::bigint,
         (l.budget_amount - l.wonin - case when l.closed then 0 else coalesce(p.rem, 0) end)::bigint,
         case when l.closed then l.wonin else l.wonin + coalesce(p.rem, 0) end::bigint,
         l.closed, l.origin, l.missing_from_card, l.manual_override, l.note
  from budget_line l
  left join lateral (select sum(pi.amount)::bigint rem from budget_plan_item pi
                     where pi.line_id = l.id and pi.status in ('planned', 'in_order')) p on true
  where l.project_id = p_project
  order by l.sort_order, l.created_at;
$$;


