CREATE OR REPLACE FUNCTION "mcp_private"."bg_totals"("p_project" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'budget', coalesce(sum(budget), 0), 'pumui', coalesce(sum(pumui), 0), 'wonin', coalesce(sum(wonin), 0),
    'pending', coalesce(sum(pending), 0), 'remaining_plan', coalesce(sum(remaining_plan), 0),
    'unassigned', coalesce(sum(budget), 0) - coalesce(sum(wonin), 0) - coalesce(sum(remaining_plan), 0),
    'execution_rate', case when coalesce(sum(budget), 0) > 0 then round(sum(wonin)::numeric / sum(budget), 4) else 0 end,
    'over_planned_lines', count(*) filter (where unassigned < 0),
    'pending_lines', count(*) filter (where pending > 0))
  from mcp_private.bg_lines(p_project);
$$;


ALTER FUNCTION "mcp_private"."bg_totals"("p_project" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."check_month"("p_year" integer, "p_month" integer, OUT "m_from" "date", OUT "m_to" "date") RETURNS "record"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  if p_year is null or p_month is null or p_month < 1 or p_month > 12 then
    raise exception using errcode = '22023', message = 'year·month(1~12)가 필요합니다.';
  end if;
  m_from := make_date(p_year, p_month, 1);
  m_to := (m_from + interval '1 month - 1 day')::date;
  if m_to < date_trunc('month', v_today::timestamp)::date or m_from > v_today + 200 then
    raise exception using errcode = '22023', message = '이번 달부터 앞으로 6개월 안의 달만 다룬다.';
  end if;
end;
$$;


ALTER FUNCTION "mcp_private"."check_month"("p_year" integer, "p_month" integer, OUT "m_from" "date", OUT "m_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."check_period"("p" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if p is null or p < 1 or p > 9 then
    raise exception using errcode = '22023', message = '교시는 1~9 입니다.';
  end if;
  return p;
end;
$$;


ALTER FUNCTION "mcp_private"."check_period"("p" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."club_brief"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select jsonb_strip_nulls(jsonb_build_object(
    'club_year_id', p->>'id', 'name', p->>'name', 'kind', p->>'kind', 'status', p->>'status',
    'field', coalesce(p->>'category', substring(p->>'name' from '\(([^)]+)\)\s*$')),
    'place', p->>'place', 'capacity', p->'capacity', 'description', p->>'description',
    'advisors', (select jsonb_agg(a->>'name') from jsonb_array_elements(coalesce(p->'advisors', '[]'::jsonb)) a),
    'member_count', p->'member_count', 'pending_count', p->'pending_count',
    'leader', case when p->'leader' is not null and jsonb_typeof(p->'leader') = 'object'
                   then concat_ws(' ', concat_ws('-', p->'leader'->>'grade', p->'leader'->>'class', p->'leader'->>'number'), p->'leader'->>'name') end,
    'leader_unresolved', case when jsonb_typeof(p->'leader_unresolved') = 'object'
                   then concat_ws(' ', concat_ws('-', p->'leader_unresolved'->>'grade', p->'leader_unresolved'->>'class', p->'leader_unresolved'->>'number'),
                                  p->'leader_unresolved'->>'name') || ' (받은 기장 목록에 있으나 명단에 없음 — 지도교사가 정한다)' end,
    'years_running', p->'years_running', 'my_role', p->>'my_role'
  ));
$_$;


