CREATE OR REPLACE FUNCTION "mcp_private"."code_apply_files"("p_project" "uuid", "p_files" "jsonb", "p_delete" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  f jsonb; v_path text; v_content text; v_written integer := 0; v_deleted integer := 0; v_count integer; v_total bigint;
  v_removed text[] := '{}'; v_old text;
begin
  if p_files is not null and jsonb_typeof(p_files) <> 'array' then
    raise exception using errcode = '22023', message = 'files 는 [{path, content}] 배열입니다.';
  end if;
  if jsonb_array_length(coalesce(p_files, '[]'::jsonb)) > 300 then
    raise exception using errcode = '22023', message = '한 번에 파일은 300개까지입니다.';
  end if;
  for f in select * from jsonb_array_elements(coalesce(p_files, '[]'::jsonb)) loop
    v_path := f->>'path'; v_content := f->>'content';
    if not mcp_private.code_path_ok(v_path) then
      raise exception using errcode = '22023', message = format('저장할 수 없는 경로입니다: %s (상대 경로 · 점으로 시작하는 폴더·node_modules·잠금 파일 제외)', coalesce(v_path, '(없음)'));
    end if;
    if v_content is null then raise exception using errcode = '22023', message = format('%s: content 가 필요합니다(텍스트 파일만).', v_path); end if;
    if octet_length(v_content) > 1000000 then raise exception using errcode = '22023', message = format('%s: 텍스트 파일은 1MB까지입니다.', v_path); end if;
    select storage_path into v_old from code_project_file where project_id = p_project and path = v_path and is_binary;
    if v_old is not null then v_removed := v_removed || v_old; end if;
    insert into code_project_file (project_id, path, content, is_binary, size_bytes)
    values (p_project, v_path, v_content, false, octet_length(v_content))
    on conflict (project_id, path) do update
      set content = excluded.content, size_bytes = excluded.size_bytes, is_binary = false, storage_path = null, updated_at = now();
    v_written := v_written + 1;
  end loop;

  if coalesce(cardinality(p_delete), 0) > 0 then
    v_removed := v_removed || coalesce((select array_agg(storage_path) from code_project_file
                                         where project_id = p_project and path = any(p_delete) and is_binary and storage_path is not null), '{}');
    delete from code_project_file where project_id = p_project and path = any(p_delete);
    get diagnostics v_deleted = row_count;
  end if;

  select count(*), coalesce(sum(size_bytes), 0) into v_count, v_total from code_project_file where project_id = p_project;
  if v_count = 0 then raise exception using errcode = '22023', message = '파일이 하나는 있어야 합니다.'; end if;
  if v_count > 300 then raise exception using errcode = '22023', message = format('파일이 너무 많습니다 (%s개, 최대 300개).', v_count); end if;
  if v_total > 20 * 1024 * 1024 then raise exception using errcode = '22023', message = '전체 용량이 20MB 를 넘습니다.'; end if;
  return jsonb_strip_nulls(jsonb_build_object('written', v_written, 'deleted', v_deleted, 'file_count', v_count,
    'removed_objects', case when cardinality(v_removed) > 0 then to_jsonb(v_removed) end));
end $$;


ALTER FUNCTION "mcp_private"."code_apply_files"("p_project" "uuid", "p_files" "jsonb", "p_delete" "text"[]) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."code_project" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "owner_resource_id" "uuid" NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "visibility" "text" DEFAULT 'school'::"text" NOT NULL,
    "kind" "text" DEFAULT 'other'::"text" NOT NULL,
    "entry_path" "text",
    "origin_tool" "text",
    "tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "forked_from" "uuid",
    "file_count" integer DEFAULT 0 NOT NULL,
    "total_bytes" bigint DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "code_project_kind_check" CHECK (("kind" = ANY (ARRAY['html'::"text", 'static'::"text", 'node'::"text", 'skill'::"text", 'other'::"text"]))),
    CONSTRAINT "code_project_title_check" CHECK ((("length"("btrim"("title")) >= 1) AND ("length"("btrim"("title")) <= 120))),
    CONSTRAINT "code_project_visibility_check" CHECK (("visibility" = ANY (ARRAY['school'::"text", 'link'::"text", 'private'::"text"])))
);


ALTER TABLE "public"."code_project" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."code_out"("p" "public"."code_project") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'project_id', p.id, 'title', p.title, 'description', nullif(p.description, ''),
    'kind', p.kind, 'visibility', p.visibility,
    'visibility_label', case p.visibility when 'school' then '학교 전체' when 'link' then '링크를 아는 사람' else '나만' end,
    'entry_path', p.entry_path, 'origin_tool', p.origin_tool,
    'tags', case when cardinality(p.tags) > 0 then to_jsonb(p.tags) end,
    'file_count', p.file_count, 'total_kb', round(p.total_bytes / 1024.0, 1),
    'mine', p.owner_resource_id in (select public.current_actor_resource_ids()),
    -- 남의 것은 교직원이면 이름, 학생이면 «학생»만(학교 공개 작품에 학생 이름을 붙여 내보내지 않는다)
    'owner', case when p.owner_resource_id in (select public.current_actor_resource_ids()) then '나'
                  else (select case when r.type = 'student' then '학생' else r.name end from resource r where r.id = p.owner_resource_id) end,
    'updated_at', mcp_private.kst_ts(p.updated_at)));
$$;


ALTER FUNCTION "mcp_private"."code_out"("p" "public"."code_project") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."code_path_ok"("p" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select p is not null and char_length(p) between 1 and 400
     and p !~ '^/' and p !~ '\\' and p !~ '(^|/)\.{0,2}(/|$)'
     and not exists (select 1 from unnest(string_to_array(p, '/')) seg
                     where (seg like '.%' and seg <> '.claude')
                        or seg in ('node_modules', 'dist', 'build', 'coverage', '__MACOSX', 'out', '.next', '.vite', '.cache', '.turbo'))
     and (string_to_array(p, '/'))[array_length(string_to_array(p, '/'), 1)]
         not in ('package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lockb', 'bun.lock', 'Thumbs.db', 'desktop.ini');
$_$;


ALTER FUNCTION "mcp_private"."code_path_ok"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."current_term"(OUT "academic_year" integer, OUT "semester" integer) RETURNS "record"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
  select (s.setting_value->>'year')::integer, (s.setting_value->>'semester')::integer
    into academic_year, semester
  from public.system_settings s
  where s.setting_key = 'academic_term'
    and s.setting_value->>'year' ~ '^\d{4}$' and s.setting_value->>'semester' ~ '^[12]$';
  if academic_year is null then
    select st.academic_year, st.semester into academic_year, semester
    from public.student_timetable st
    order by st.academic_year desc, st.semester desc
    limit 1;
  end if;
end;
$_$;


ALTER FUNCTION "mcp_private"."current_term"(OUT "academic_year" integer, OUT "semester" integer) OWNER TO "postgres";


