     "filters":[{"name":"university","type":"text","required":true,"description":"대학 이름에 든 글자"},{"name":"questions","type":"boolean","description":"면접 기출 질문까지 (기본 true)"}],
     "fields":["university","region","recruitment","doc{evaluated,top_factors,ratios}","interview{status,methods[],time,process,source,top_factors,blocks[{admission,process,time,factors[{name,ratio,questions[]}]}]}"]},
