     "filters":[{"name":"university","type":"text","required":true,"description":"대학 이름"},{"name":"keyword","type":"text","description":"키워드 (예: 수능최저, 면접, 전형방식)"},{"name":"after_year","type":"integer","description":"바뀐 뒤 학년도 (예: 2028)"}],
     "fields":["university","exact(정확히 같은 대학인가)","category","comparison","admission","keywords[]","change_type","after","before"]},
