     "filters":[{"name":"admission_year","type":"integer","description":"입학 연도 (예: 2025 — 그 학생들의 3년)"},{"name":"academic_year","type":"integer","description":"적용 학년도"},{"name":"grade","type":"integer","description":"학년 1~3"},{"name":"semester","type":"integer","description":"학기 1·2"},{"name":"subject","type":"text","description":"과목 이름에 든 글자"},{"name":"area","type":"text","description":"교과 영역·교과에 든 글자"}],
     "fields":["admission_year","academic_year","grade","semester","area","category","subject","credits","hours","grading_type","subject_type","selection_group"]},
    {"name":"achievement_standards","area":"data.school","title":"교과 성취기준",
