COMMENT ON TABLE "public"."docgen_context" IS '문서 생성 맥락 라이브러리 — 사용자 소유, 기본 공개(hidden으로 비공개), 스펙 연결 시 숨김 불가(트리거 강제)';



COMMENT ON COLUMN "public"."docgen_context"."category" IS '맥락 분류(자유 텍스트, 선택). 예: 성취기준. enum이 아닌 이유 = 사용자가 그때그때 만드는 라벨이라 새 분류에 마이그레이션이 필요하면 안 된다';



CREATE OR REPLACE FUNCTION "mcp_private"."dc_entry"("c" "public"."docgen_context", "p_full" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', c.id, 'title', c.title, 'category', c.category, 'hidden', case when c.hidden then true end,
    'mine', c.user_id = auth.uid(),
    'written_by', (select p.name from profiles p where p.id = c.user_id),
    'updated_at', to_char(c.updated_at at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI'),
    'length', char_length(c.body),
    'preview', case when not p_full then left(regexp_replace(c.body, '\s+', ' ', 'g'), 160) end,
    'body', case when p_full then c.body end,
    'generations', (select jsonb_agg(jsonb_build_object('action_id', a.id, 'name', coalesce(a.title, a.config->'defaultTemplate'->>'name')) order by a.title)
                    from docgen_context_spec_link l
                    join task_action a on a.config->'defaultTemplate'->>'id' = l.template_id::text and a.archived_at is null
                    where l.context_id = c.id)));
$$;


ALTER FUNCTION "mcp_private"."dc_entry"("c" "public"."docgen_context", "p_full" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."dc_no_personal"("p_text" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if coalesce(p_text, '') ~ '\d{6}\s*-\s*[1-4]\d{6}' then
    raise exception using errcode = '22023', message = '주민등록번호 꼴이 보입니다 — 문서 맥락에는 개인정보를 적지 않습니다(교직원 모두가 봅니다).';
  end if;
  if coalesce(p_text, '') ~ '01[016789][\s.-]?\d{3,4}[\s.-]?\d{4}' then
    raise exception using errcode = '22023', message = '휴대전화 번호 꼴이 보입니다 — 문서 맥락에는 개인정보를 적지 않습니다.';
  end if;
  if coalesce(p_text, '') ~* '[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}' then
    raise exception using errcode = '22023', message = '이메일 주소가 보입니다 — 문서 맥락에는 개인정보를 적지 않습니다.';
  end if;
end;
$$;


ALTER FUNCTION "mcp_private"."dc_no_personal"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."dc_template_of"("p_action" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare v text;
begin
  select a.config->'defaultTemplate'->>'id' into v from task_action a where a.id = p_action and a.archived_at is null;
  if v is null or v !~ '^[0-9a-fA-F-]{36}$' then
    raise exception using errcode = 'P0002', message = '그 생성 방식이 없거나 양식이 없습니다 — list_document_generations 의 action_id 를 쓰세요.';
  end if;
  return v::uuid;
end;
$_$;


