    "title" "text" NOT NULL,
    "description" "text",
    "execution_mode" "text" DEFAULT 'assisted'::"text" NOT NULL,
    "verification_mode" "text" DEFAULT 'human_review'::"text" NOT NULL,
    "config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "is_required" boolean DEFAULT true NOT NULL,
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "instance_key" "text" DEFAULT ''::"text" NOT NULL,
    "rolled_over_from" "uuid",
    CONSTRAINT "task_action_action_type_check" CHECK (((("length"("action_type") >= 3) AND ("length"("action_type") <= 100)) AND ("action_type" ~ '^[a-z0-9]+([._-][a-z0-9]+)*$'::"text"))),
    CONSTRAINT "task_action_config_check" CHECK (("jsonb_typeof"("config") = 'object'::"text")),
    CONSTRAINT "task_action_execution_mode_check" CHECK (("execution_mode" = ANY (ARRAY['manual'::"text", 'assisted'::"text", 'automatic'::"text"]))),
    CONSTRAINT "task_action_handler_version_check" CHECK (("handler_version" > 0)),
    CONSTRAINT "task_action_instance_key_check" CHECK (("length"("instance_key") <= 64)),
    CONSTRAINT "task_action_title_check" CHECK ((("length"("btrim"("title")) >= 1) AND ("length"("btrim"("title")) <= 120))),
    CONSTRAINT "task_action_verification_mode_check" CHECK (("verification_mode" = ANY (ARRAY['none'::"text", 'automatic'::"text", 'human_review'::"text"])))
);

