    'upload_id', u.id, 'file_name', u.file_name, 'storage_path', u.storage_path,
    'uploaded', u.uploaded_at is not null, 'uploaded_at', u.uploaded_at,
    'expires_at', case when u.uploaded_at is null then u.expires_at end,
    'size_bytes', u.size_bytes, 'content_sha256', u.content_sha256,
    'action_id', u.action_id, 'template_id', u.template_id,
    'sections', case when p_with_sections then u.sections end))
  from mcp_private.docgen_upload u
  where u.id = p_upload_id and u.user_id = auth.uid();
$$;


ALTER FUNCTION "mcp_private"."dg_my_upload"("p_upload_id" "uuid", "p_with_sections" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."dg_new_upload"("p_resource" "uuid", "p_file_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_name   text := btrim(coalesce(p_file_name, ''));
  v_ticket text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  v_id     uuid := gen_random_uuid();
  v_exp    timestamptz := now() + interval '15 minutes';
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = '로그인이 필요합니다.';
  end if;
  if v_name = '' or length(v_name) > 255 then
    raise exception using errcode = '22023', message = 'file_name 은 1~255자입니다.';
  end if;
  if lower(v_name) !~ '\.hwpx$' then
    raise exception using errcode = '22023',
      message = '한글 HWPX 파일(.hwpx)만 받습니다. .hwp 는 한글에서 «다른 이름으로 저장 → HWPX» 로 바꿔 주세요.';
  end if;
  if (select count(*) from mcp_private.docgen_upload u
      where u.user_id = auth.uid() and u.created_at > now() - interval '1 day') >= 20 then
    raise exception using errcode = '54000', message = '하루에 양식 올리기는 20번까지입니다.';
  end if;

  insert into mcp_private.docgen_upload (id, user_id, resource_id, ticket_hash, file_name, storage_path, expires_at)
  values (v_id, auth.uid(), p_resource, encode(sha256(convert_to(v_ticket, 'UTF8')), 'hex'), v_name,
          auth.uid()::text || '/templates/' || v_id::text || '/template.hwpx', v_exp);

  return jsonb_build_object('upload_id', v_id, 'ticket', v_ticket, 'file_name', v_name, 'expires_at', v_exp);
end;
$_$;


ALTER FUNCTION "mcp_private"."dg_new_upload"("p_resource" "uuid", "p_file_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."doc_folder"("p" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare v text := btrim(regexp_replace(coalesce(p, ''), '^/+|/+$', '', 'g'));
begin
  if v = '' then return null; end if;
  if v ~ '(^|/)\s*(\.\.?)?\s*(/|$)' or char_length(v) > 200 then
    raise exception using errcode = '22023', message = '폴더 경로가 올바르지 않습니다(예: 2026/서류함/교무운영부, 200자까지).';
  end if;
  return v;
end $_$;


ALTER FUNCTION "mcp_private"."doc_folder"("p" "text") OWNER TO "postgres";


