CREATE OR REPLACE FUNCTION "mcp_private"."doc_out"("d" "public"."documents") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'document_id', d.id, 'title', d.title, 'file_name', d.file_name, 'file_type', d.file_type,
    'size_kb', case when d.file_size is not null then round(d.file_size / 1024.0) end,
    'folder', d.meta->>'directory_path', 'category', nullif(d.meta->>'category', ''),
    'department', nullif(d.meta->>'department', ''), 'year', d.meta->>'creation_year',
    'description', left(nullif(d.meta->>'description', ''), 300),
    'keywords', case when jsonb_typeof(d.meta->'keywords') = 'array' and jsonb_array_length(d.meta->'keywords') > 0 then d.meta->'keywords' end,
    'stored', case when d.storage_path ~ '^https?://' then
                     case when coalesce((d.meta->>'is_google_drive_file')::boolean, false) then 'drive' else 'link' end
                   else 'server' end,
    -- 드라이브·주소 문서는 링크를 그대로 준다(읽기 권한은 RLS 가 이미 확인했다). 서버 파일은 웹에서 연다.
    'link', case when d.storage_path ~ '^https?://' then d.storage_path end,
    'uploader', (select pr.name from profiles pr where pr.id = d.user_id),
    'mine', d.user_id = auth.uid(),
    'linked_to_work', case when d.meta ? 'source' then true end,
    'created_at', to_char(d.created_at at time zone 'Asia/Seoul', 'YYYY-MM-DD')));
$$;


