CREATE OR REPLACE FUNCTION "mcp_private"."ds_achievement_standards"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_subj text := mcp_private.f_text(p, 'subject');
  v_q text := mcp_private.f_text(p, 'query');
  v_off integer := coalesce(mcp_private.f_int(p, 'offset', 0, 100000), 0);
  v_total integer;
  v_rows jsonb;
begin
  with f as (
    select s.* from subject_achievement_standards s
    where s.subject ilike '%' || v_subj || '%'
      and (v_q is null or concat_ws(' ', s.standard_code, s.domain, s.subdomain, s.description) ilike '%' || v_q || '%')
  )
  select (select count(*) from f),
         coalesce((select jsonb_agg(x.j order by x.subject, x.standard_code) from (
           select f.subject, f.standard_code, jsonb_strip_nulls(jsonb_build_object(
             'subject', f.subject, 'code', f.standard_code, 'domain', f.domain, 'subdomain', f.subdomain,
             'description', f.description, 'level', f.level, 'curriculum_year', f.curriculum_year)) as j
           from f order by f.subject, f.standard_code limit p_limit offset v_off) x), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'matched', v_total, 'truncated', v_off + p_limit < v_total,
    'next_offset', case when v_off + p_limit < v_total then v_off + p_limit end, 'rows', v_rows,
    'note', '2022 개정 교육과정 성취기준. 세특·평가 문장에 쓸 때는 성취기준을 그대로 옮기지 말고 학생의 실제 활동과 이어서 쓴다.');
end;
$$;


ALTER FUNCTION "mcp_private"."ds_achievement_standards"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_admission_changes"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uni text := mcp_private.f_text(p, 'university');
  v_kw text := mcp_private.f_text(p, 'keyword');
  v_after integer := mcp_private.f_int(p, 'after_year', 2000, 2100);
  v_total integer;
  v_rows jsonb;
begin
  with f as (
    select c.* from public.get_admission_changes(array[v_uni]) c
    where (v_after is null or c.after_year = v_after)
      and (v_kw is null or exists (select 1 from unnest(c.keywords) k where k ilike '%' || ltrim(v_kw, '#') || '%')
           or concat_ws(' ', c.after_text, c.before_text) ilike '%' || v_kw || '%')
  )
  select (select count(*) from f),
         coalesce((select jsonb_agg(x.j order by x.after_year desc, x.category) from (
           select f.after_year, f.category, jsonb_strip_nulls(jsonb_build_object(
             'university', f.matched_university, 'exact', case when not f.is_exact then false end,
             'category', f.category, 'comparison', f.comparison, 'admission', f.admission_item, 'keywords', to_jsonb(f.keywords),
             'change_type', f.change_type, 'after', f.after_text, 'before', f.before_text)) as j
           from f order by f.after_year desc, f.category limit least(p_limit, 100)) x), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'matched', v_total, 'truncated', least(p_limit, 100) < v_total, 'rows', v_rows,
    'note', case when v_total = 0
      then '이 대학 변경 사항 자료가 없다 — 자료는 전국 주요 64개 대학뿐이라 «변경 없음»이 아니라 «자료 없음»이다. 대학 모집요강·입학처를 안내한다.'
      else '변경 사항 원문(자료 기준일 2026-05-02). exact=false 는 이름이 비슷한 다른 대학(캠퍼스)의 자료다. 전형 이름은 출처마다 표기가 달라 대학 단위로 모았다.' end);
end;
$$;


ALTER FUNCTION "mcp_private"."ds_admission_changes"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_admission_cutoffs"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uni text := mcp_private.f_text(p, 'university');
  v_major text := mcp_private.f_text(p, 'major');
  v_track text := mcp_private.f_text(p, 'track');
  v_region text := mcp_private.f_text(p, 'region');
  v_off integer := coalesce(mcp_private.f_int(p, 'offset', 0, 100000), 0);
  v_lim integer := least(p_limit, 100);
  v_total integer;
  v_rows jsonb;
begin
  if v_uni is null and v_major is null then
    raise exception using errcode = '22023', message = 'admission_cutoffs 에는 university 나 major 중 하나가 필요합니다.';
  end if;
  if v_track is not null and v_track not in ('교과', '종합') then
    raise exception using errcode = '22023', message = 'track 은 교과 · 종합 중 하나입니다.';
  end if;
  with f as (
    select a.* from admission_adiga_results a
    where (v_uni is null or strpos(mcp_private.adm_norm(a.university), mcp_private.adm_norm(v_uni)) > 0)
      and (v_major is null or a.major ilike '%' || v_major || '%' or a.program ilike '%' || v_major || '%')
      and (v_track is null or a.track = v_track)
      and (v_region is null or a.region ilike '%' || v_region || '%')
  )
  select (select count(*) from f),
         coalesce((select jsonb_agg(x.j order by x.university, x.track, x.major, x.program) from (
           select f.university, f.track, f.major, f.program, jsonb_strip_nulls(jsonb_build_object(
             'university', f.university, 'region', f.region, 'track', f.track, 'program', f.program, 'major', f.major, 'field', f.field,
             'cut50', f.grade50, 'cut70', f.grade70,
             'quality', case f.grade_quality when 'normal' then null when 'placeholder' then '추정(그해 자료 부족)'
                                             when 'inverted' then '50%·70% 컷이 뒤집힘' when 'degenerate' then '50%·70% 컷이 같음' else f.grade_quality end,
             'recruit', f.recruit_2026, 'competition', f.competition_2026, 'real_competition', f.real_competition_2026,
             'waitlist', f.waitlist_2026, 'fill_rate', f.fill_rate_2026,
             'history', f.history->'years', 'trend', f.history->'trend')) as j
           from f order by f.university, f.track, f.major, f.program limit v_lim offset v_off) x), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'matched', v_total, 'truncated', v_off + v_lim < v_total,
    'next_offset', case when v_off + v_lim < v_total then v_off + v_lim end, 'rows', v_rows,
    'note', '2026학년도 수시 결과(대학 발표, 대입정보포털). 컷은 내신 등급(1~9, 작을수록 높다) — cut70 = 합격자 하위 30% 선이지 합격선이 아니다. quality 가 있는 줄(추정·뒤집힘·같음)은 비교에 조심한다. 합격 가능성을 단정하지 않는다.');
end;
$$;


ALTER FUNCTION "mcp_private"."ds_admission_cutoffs"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_admission_gyogwa"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uni text := mcp_private.f_text(p, 'university');
  v_unit text := mcp_private.f_text(p, 'unit');
  v_q text := mcp_private.f_text(p, 'query');
  v_csat boolean;
  v_off integer := coalesce(mcp_private.f_int(p, 'offset', 0, 100000), 0);
  v_lim integer := least(p_limit, 30);
  v_total integer;
  v_rows jsonb;
begin
  if p ? 'csat' then
    if jsonb_typeof(p->'csat') <> 'boolean' then
      raise exception using errcode = '22023', message = '조건 csat 는 true · false 입니다.';
    end if;
    v_csat := (p->>'csat')::boolean;
  end if;
  if v_uni is null and v_unit is null and v_q is null then
    raise exception using errcode = '22023', message = 'admission_gyogwa 에는 university · unit · query 중 하나가 필요합니다.';
  end if;
  with f as (
    select g.* from admission_gyogwa_criteria g
    where (v_uni is null or strpos(mcp_private.adm_norm(g.university), mcp_private.adm_norm(v_uni)) > 0)
      and (v_unit is null or g.unit ilike '%' || v_unit || '%')
      and (v_q is null or g.search_blob ilike '%' || v_q || '%')
      and (v_csat is null or g.has_csat = v_csat)
  )
  select (select count(*) from f),
         coalesce((select jsonb_agg(x.j order by x.university, x.admission, x.unit) from (
           select f.university, f.admission, f.unit, jsonb_strip_nulls(jsonb_build_object(
             'university', f.university, 'region', f.region, 'admission', f.admission, 'unit', f.unit, 'method', f.method,
             'method_tags', to_jsonb(f.method_tags), 'unit_tags', to_jsonb(f.unit_tags),
             'quota', coalesce(f.quota_text, f.quota::text), 'csat', f.csat, 'csat_status', f.csat_status,
             'subjects', nullif(f.subjects_exact, '[]'::jsonb), 'careers', nullif(f.careers, '[]'::jsonb))) as j
           from f order by f.university, f.admission, f.unit limit v_lim offset v_off) x), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'matched', v_total, 'truncated', v_off + v_lim < v_total,
    'next_offset', case when v_off + v_lim < v_total then v_off + v_lim end, 'rows', v_rows,
    'note', '2027학년도 학생부교과전형(대교협 대입정보119). csat 는 수능 최저 원문 — 학과마다 조건이 다를 수 있어 원문을 그대로 보여 준다. 최종 확인은 대학 모집요강으로.');
end;
$$;


ALTER FUNCTION "mcp_private"."ds_admission_gyogwa"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_admission_jonghap"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uni text := mcp_private.f_text(p, 'university');
  v_q boolean := true;
  v_rows jsonb;
begin
  if p ? 'questions' then
    if jsonb_typeof(p->'questions') <> 'boolean' then
      raise exception using errcode = '22023', message = '조건 questions 는 true · false 입니다.';
    end if;
    v_q := (p->>'questions')::boolean;
  end if;
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'university', j.name, 'region', j.region, 'recruitment', j.recruitment,
           'doc', case when j.has_doc_eval then jsonb_strip_nulls(jsonb_build_object(
                    'top_factors', j.doc_top_factors, 'ratios', j.doc_parsed_ratios)) end,
           'interview', case when j.has_interview then jsonb_strip_nulls(jsonb_build_object(
                    'status', j.interview_status, 'methods', to_jsonb(j.interview_methods),
                    'time', j.interview_primary_time, 'process', j.interview_primary_process, 'source', j.interview_primary_source,
                    'top_factors', j.interview_top_factors,
                    'blocks', case when v_q then j.interview_blocks
                                   -- 질문은 블록에도(questions) 평가 요소에도(factors[].questions) 있다 — 둘 다 뺀다
                                   else (select jsonb_agg(b - 'questions' - 'factors' || jsonb_build_object('factors',
                                           (select jsonb_agg(fct - 'questions') from jsonb_array_elements(b->'factors') fct)))
                                         from jsonb_array_elements(j.interview_blocks) b) end)) end,
           'published', j.has_doc_eval or j.has_interview)) order by j.name), '[]'::jsonb)
    into v_rows
  from (select * from admission_jonghap_criteria c
        where strpos(mcp_private.adm_norm(c.name), mcp_private.adm_norm(v_uni)) > 0
        order by c.name limit least(p_limit, 5)) j;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'rows', v_rows,
    'note', '2027학년도 학생부종합전형 평가 기준(대학 공개 자료, 대입정보포털). published=false 는 대학이 공개하지 않은 것. 면접 기출 질문(interview.blocks[].factors[].questions)은 대학이 공개한 것만 — 면접 준비에 쓴다.');
end;
$$;


ALTER FUNCTION "mcp_private"."ds_admission_jonghap"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_admission_results"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uni text := mcp_private.f_text(p, 'university');
  v_dept text := mcp_private.f_text(p, 'department');
  v_year integer := mcp_private.f_int(p, 'year', 2000, 2100);
  v_period text := mcp_private.f_text(p, 'period');
  v_type text := mcp_private.f_text(p, 'type');
  v_region text := mcp_private.f_text(p, 'region');
  v_off integer := coalesce(mcp_private.f_int(p, 'offset', 0, 100000), 0);
  v_lim integer := least(p_limit, 100);
  v_total integer;
  v_rows jsonb;
begin
  if v_uni is null and v_dept is null then
    raise exception using errcode = '22023', message = 'admission_results 에는 university 나 department 중 하나가 필요합니다.';
  end if;
  if v_period is not null and v_period not in ('수시', '정시') then
    raise exception using errcode = '22023', message = 'period 는 수시 · 정시 중 하나입니다.';
  end if;
  with f as (
    select u.* from univ_admissions u
    where (v_uni is null or strpos(mcp_private.adm_norm(u.university_name), mcp_private.adm_norm(v_uni)) > 0)
      and (v_dept is null or u.department ilike '%' || v_dept || '%')
      and (v_year is null or u.year = v_year)
      and (v_period is null or u.admission_period like v_period || '%')
      and (v_type is null or concat_ws(' ', u.admission_type, u.admission_category) ilike '%' || v_type || '%')
      and (v_region is null or u.region ilike '%' || v_region || '%')
  )
  select (select count(*) from f),
         coalesce((select jsonb_agg(x.j order by x.year desc, x.university_name, x.department, x.admission_period, x.admission_type, x.seq) from (
           select f.year, f.university_name, f.department, f.admission_period, f.admission_type, f.seq, jsonb_strip_nulls(jsonb_build_object(
             'year', f.year, 'university', f.university_name, 'region', f.region, 'department', f.department,
             'period', f.admission_period, 'type', f.admission_type, 'category', f.admission_category,
             'quota', nullif(f.quota, 0), 'applicants', nullif(f.applicants, 0), 'competition', mcp_private.adm_nz(f.competition_rate),
             'additional_accepted', f.additional_accepted, 'gpa_cut70', mcp_private.adm_nz(f.gpa_cutoff),
             'converted_score', mcp_private.adm_nz(f.converted_score), 'max_score', mcp_private.adm_nz(f.max_score),
             'korean', mcp_private.adm_nz(f.korean_score), 'math', mcp_private.adm_nz(f.math_score),
             'science', mcp_private.adm_nz(f.science_score), 'csat_percentile', mcp_private.adm_nz(f.csat_percentile))) as j
           from f order by f.year desc, f.university_name, f.department, f.admission_period, f.admission_type, f.seq limit v_lim offset v_off) x), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'matched', v_total, 'truncated', v_off + v_lim < v_total,
    'next_offset', case when v_off + v_lim < v_total then v_off + v_lim end, 'rows', v_rows,
    'note', '리로스쿨 스마트 배치표 2021~2025학년도. gpa_cut70 = 내신 70% 컷(합격자 하위 30% 선 — 합격선이 아니다). 빈 칸은 미공개(원본 0). 특성화고·농어촌 등 특별전형은 일반 학생과 견주지 않는다.');
end;
$$;


ALTER FUNCTION "mcp_private"."ds_admission_results"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_admission_schedule"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uni text := mcp_private.f_text(p, 'university');
  v_type text := mcp_private.f_text(p, 'exam_type');
  v_from date := coalesce(mcp_private.f_date(p, 'from'), mcp_private.kst_today());
  v_to date;
  v_off integer := coalesce(mcp_private.f_int(p, 'offset', 0, 100000), 0);
  v_total integer;
  v_rows jsonb;
begin
  v_to := coalesce(mcp_private.f_date(p, 'to'), v_from + 14);
  if v_type is not null and v_type not in ('면접', '논술', '실기') then
    raise exception using errcode = '22023', message = 'exam_type 은 면접 · 논술 · 실기 중 하나입니다.';
  end if;
  if v_uni is null and (v_to < v_from or v_to - v_from > 92) then
    raise exception using errcode = '22023', message = '기간은 from ≤ to, 93일까지입니다.';
  end if;
  with src as (
    select s.matched_university as university, s.exam_type, s.stage, s.exam_start, s.exam_end, s.exam_time, s.admission_path,
           s.admission_name, s.units, s.apply_start, s.apply_end, s.announce_text, s.note, s.is_exact
    from public.get_admission_schedules(array[v_uni]) s
    where v_uni is not null
    union all
    select e.university_full, e.exam_type, e.stage, e.exam_start, e.exam_end, e.exam_time, e.admission_path,
           e.admission_name, e.units, e.apply_start, e.apply_end, e.announce_text, e.note, true
    from admission_exam_schedule e
    where v_uni is null and e.exam_start <= v_to and coalesce(e.exam_end, e.exam_start) >= v_from
  ), f as (select * from src where v_type is null or exam_type = v_type)
  select (select count(*) from f),
         coalesce((select jsonb_agg(x.j order by x.exam_start nulls last, x.university) from (
           select f.exam_start, f.university, jsonb_strip_nulls(jsonb_build_object(
             'university', f.university, 'exact', case when not f.is_exact then false end,
             'exam_type', f.exam_type, 'stage', f.stage, 'exam_start', f.exam_start, 'exam_end', nullif(f.exam_end, f.exam_start),
             'exam_time', f.exam_time, 'admission_path', f.admission_path, 'admission', f.admission_name,
             'units', to_jsonb(f.units), 'apply_start', f.apply_start, 'apply_end', f.apply_end,
             'final_announce', f.announce_text, 'note', f.note)) as j
           from f order by f.exam_start nulls last, f.university limit least(p_limit, 100) offset v_off) x), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_strip_nulls(jsonb_build_object('count', jsonb_array_length(v_rows), 'matched', v_total,
    'range', case when v_uni is null then jsonb_build_object('from', v_from, 'to', v_to) end,
    'truncated', v_off + least(p_limit, 100) < v_total,
    'next_offset', case when v_off + least(p_limit, 100) < v_total then v_off + least(p_limit, 100) end, 'rows', v_rows,
    'note', '2027학년도 수시 대학별고사(진학 자료, 수집일 2026-06-12) — 최종 날짜는 대학 공지로 확인한다. final_announce 는 최종 합격자 발표일이고, « / » 가 있으면 모집단위마다 다르다. 1차(면접 대상자) 발표일은 이 자료에 없다. exact=false 는 비슷한 이름 대학의 자료다.'));
end;
$$;


ALTER FUNCTION "mcp_private"."ds_admission_schedule"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_admission_university"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uni text := mcp_private.f_text(p, 'university');
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'university', u.university, 'region', u.region, 'address', u.address, 'phone', u.phone,
           'home_url', u.home_url, 'apply_url', u.apply_url,
           'multi_apply', jsonb_strip_nulls(jsonb_build_object('status', u.multi_apply_status, 'limit', u.multi_apply_limit, 'summary', u.multi_apply_summary)),
           'base_date', u.base_date)) order by u.university), '[]'::jsonb)
    into v_rows
  from (select * from admission_university_info i
        where strpos(mcp_private.adm_norm(i.university), mcp_private.adm_norm(v_uni)) > 0
        order by i.university limit least(p_limit, 20)) u;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'rows', v_rows,
    'note', 'phone 은 대학 대표(입학처) 번호다. 복수 지원 제한(교대·사관학교 등)은 multi_apply 를 본다.');
end;
$$;


ALTER FUNCTION "mcp_private"."ds_admission_university"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_admission_wishlist"("p_me" "uuid", "p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_grade integer := mcp_private.f_int(p, 'grade', 1, 3);
  v_class integer := mcp_private.f_int(p, 'class', 1, 30);
  v_no integer := mcp_private.f_int(p, 'number', 1, 99);
  v_uni text := mcp_private.f_text(p, 'university');
  v_track text := case mcp_private.f_text(p, 'track') when '교과' then 'gyogwa' when '종합' then 'jonghap' else mcp_private.f_text(p, 'track') end;
  v_tier text := case mcp_private.f_text(p, 'tier') when '지원' then 'apply' when '관심' then 'interest' else mcp_private.f_text(p, 'tier') end;
  v_off integer := coalesce(mcp_private.f_int(p, 'offset', 0, 100000), 0);
  v_lim integer := least(p_limit, 100);
  v_total integer;
  v_rows jsonb;
begin
  if v_track is not null and v_track not in ('gyogwa', 'jonghap') then
    raise exception using errcode = '22023', message = 'track 은 교과 · 종합 중 하나입니다.';
  end if;
  if v_tier is not null and v_tier not in ('apply', 'interest') then
    raise exception using errcode = '22023', message = 'tier 는 지원 · 관심 중 하나입니다.';
  end if;
  with stu as (
    select r.meta->>'id' as code, r.name,
           case when r.meta->>'grade' ~ '^\d{1,2}$' then (r.meta->>'grade')::integer end as g,
           case when r.meta->>'class' ~ '^\d{1,2}$' then (r.meta->>'class')::integer end as c,
           case when r.meta->>'number' ~ '^\d{1,3}$' then (r.meta->>'number')::integer end as n
    from resource r where r.type = 'student' and r.status = 'active' and coalesce(r.meta->>'id', '') <> ''
  ), w as (
    -- RLS(can_read_wishlist)가 범위를 정한다 — 학생 본인 정책(is_wishlist_owner)은 교직원에게 해당 없음
    select w.*, s.g, s.c, s.n, s.name
    from admission_wishlist w join stu s on s.code = w.student_code
    where s.g is not null and s.c is not null and s.n is not null
      and (v_grade is null or s.g = v_grade) and (v_class is null or s.c = v_class) and (v_no is null or s.n = v_no)
      and (v_uni is null or strpos(mcp_private.adm_norm(w.university), mcp_private.adm_norm(v_uni)) > 0)
      and (v_track is null or w.track = v_track) and (v_tier is null or w.tier = v_tier)
  ), by_stu as (
    select w.g, w.c, w.n, w.name,
           jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
             'track', case w.track when 'gyogwa' then '교과' when 'jonghap' then '종합' else w.track end,
             'tier', case w.tier when 'apply' then '지원' when 'interest' then '관심' else w.tier end,
             'university', w.university, 'department', w.department, 'admission', w.admission_name,
             'interview_date', nullif(w.interview_date, ''), 'first_announce', w.first_announce_date, 'final_announce', w.final_announce_date,
             'csat_check_6', nullif(w.csat_check_6, ''), 'csat_check_9', nullif(w.csat_check_9, ''),
             'converted_score', nullif(w.converted_score, ''), 'memo', nullif(btrim(coalesce(w.memo, '')), '')))
             order by w.tier, w.sort_order, w.created_at) as items
    from w group by w.g, w.c, w.n, w.name
  )
  select (select count(*) from by_stu),
         coalesce((select jsonb_agg(jsonb_build_object('grade', b.g, 'class', b.c, 'number', b.n, 'name', b.name, 'items', b.items)
                                    order by b.g, b.c, b.n)
                   from (select * from by_stu order by g, c, n limit v_lim offset v_off) b), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'matched', v_total, 'truncated', v_off + v_lim < v_total,
    'next_offset', case when v_off + v_lim < v_total then v_off + v_lim end, 'rows', v_rows,
    'note', '웹 «수시 지원 관리»와 같은 범위(담임은 담임 반, 학년 부장은 그 학년, 관리자는 전교)다 — 목록이 비면 볼 수 있는 학생의 지원이 없거나 범위 밖이다. '
            || '학생 정보다 — 지금 하는 일에만 쓰고 다른 서비스로 옮기지 않는다. 합격 가능성을 단정하지 않는다.');
end;
$_$;


ALTER FUNCTION "mcp_private"."ds_admission_wishlist"("p_me" "uuid", "p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_course_offerings"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_term record;
  v_year integer;
  v_sem integer;
  v_grade integer := mcp_private.f_int(p, 'grade', 1, 3);
  v_subj text := mcp_private.f_text(p, 'subject');
  v_teacher text := mcp_private.f_text(p, 'teacher');
  v_class text := mcp_private.f_text(p, 'class');
  v_off integer := coalesce(mcp_private.f_int(p, 'offset', 0, 100000), 0);
  v_total integer;
  v_rows jsonb;
begin
  select * into v_term from mcp_private.current_term();
  v_year := coalesce(mcp_private.f_int(p, 'year', 2000, 2100), v_term.academic_year);
  v_sem := coalesce(mcp_private.f_int(p, 'semester', 1, 2), v_term.semester);
  with f as (
    select o.* from course_offering o
    where o.academic_year = v_year and o.semester = v_sem
      and (v_grade is null or o.grade = v_grade)
      and (v_subj is null or o.subject_name ilike '%' || v_subj || '%')
      and (v_teacher is null or o.teacher_name ilike '%' || v_teacher || '%')
      and (v_class is null or o.class_label ilike '%' || v_class || '%')
  )
  select (select count(*) from f),
         coalesce((select jsonb_agg(x.j order by x.grade, x.subject_name, x.class_label) from (
           select f.grade, f.subject_name, f.class_label, jsonb_strip_nulls(jsonb_build_object(
             'year', f.academic_year, 'semester', f.semester, 'grade', f.grade, 'subject', f.subject_name, 'credits', f.credits,
             'class', f.class_label, 'classroom', coalesce(f.classroom, f.room_no), 'teacher', f.teacher_name)) as j
           from f order by f.grade, f.subject_name, f.class_label limit p_limit offset v_off) x), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_build_object('term', jsonb_build_object('year', v_year, 'semester', v_sem),
    'count', jsonb_array_length(v_rows), 'matched', v_total, 'truncated', v_off + p_limit < v_total,
    'next_offset', case when v_off + p_limit < v_total then v_off + p_limit end, 'rows', v_rows,
    'note', '학기별 개설 과목·담당 교사. 요일·교시는 teacher_timetable(교사 시간표)로 본다.');
end;
$$;


ALTER FUNCTION "mcp_private"."ds_course_offerings"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_course_selection"("p_me" "uuid", "p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_round_txt text := mcp_private.f_text(p, 'round');
  v_grade integer := mcp_private.f_int(p, 'grade', 1, 3);
  v_class integer := mcp_private.f_int(p, 'class', 1, 30);
  v_no integer := mcp_private.f_int(p, 'number', 1, 99);
  v_status text := mcp_private.f_text(p, 'status');
  v_items boolean := false;
  v_year integer := mcp_private.sch_year();
  v_round public.course_selection_round;
  v_expect integer;
  v_rows jsonb;
  v_summary jsonb;
  v_rounds jsonb;
begin
  if p ? 'items' then
    if jsonb_typeof(p->'items') <> 'boolean' then
      raise exception using errcode = '22023', message = '조건 items 는 true · false 입니다.';
    end if;
    v_items := (p->>'items')::boolean;
  end if;
  if v_status is not null and v_status not in ('제출', '확정', '미제출') then
    raise exception using errcode = '22023', message = 'status 는 제출 · 확정 · 미제출 중 하나입니다.';
  end if;
  -- 회차의 대상 = 입학 연도(admission_year) 코호트. target_grade 는 «조사할 때의 학년», academic_year 는 «고른 과목을 듣는 학년도»(보통 다음 해)라
  -- 둘로는 지금 학년을 못 정한다(2026-11-09 실측 — target_grade 로 정했더니 전원 «미제출»이 됐다). 지금 학년 = 지금 학년도 − 입학 연도 + 1
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'title', r.title, 'academic_year', r.academic_year, 'admission_year', r.admission_year,
           'round_number', r.round_number, 'status', r.status, 'current_grade', v_year - r.admission_year + 1)
           order by r.admission_year desc, r.academic_year desc, r.round_number desc), '[]'::jsonb)
    into v_rounds
  from course_selection_round r
  where r.admission_year is not null and v_year - r.admission_year + 1 between 1 and 3;
  if v_round_txt is not null then
    if v_round_txt !~ '^[0-9a-fA-F-]{36}$' then
      raise exception using errcode = '22023', message = 'round 는 회차 id 입니다 — 결과의 rounds 목록에서 고릅니다.';
    end if;
    select * into v_round from course_selection_round where id = v_round_txt::uuid;
    if not found then
      raise exception using errcode = 'P0002', message = '그 회차가 없습니다.';
    end if;
  else
    -- 내가 볼 수 있는 학생이 대상인 가장 최근 회차(그 코호트가 지금 1~3학년이고 내가 그 학년의 어느 반이든 볼 수 있는 것)
    select r.* into v_round from course_selection_round r
    where r.admission_year is not null and v_year - r.admission_year + 1 between 1 and 3
      and (v_grade is null or v_year - r.admission_year + 1 = v_grade)
      and exists (select 1 from generate_series(1, 20) c where mcp_private.sr_can_manage_student(v_year - r.admission_year + 1, c))
    order by r.academic_year desc, r.round_number desc, r.admission_year desc limit 1;
    if not found then
      return jsonb_build_object('rounds', v_rounds, 'rows', '[]'::jsonb,
        'note', '내가 볼 수 있는 학생(담임 반·학년 부장은 그 학년)이 대상인 과목 선택 회차가 없습니다. 다른 회차는 round 로 고릅니다.');
    end if;
  end if;
  v_expect := case when v_round.admission_year is not null then v_year - v_round.admission_year + 1 end;

  with stu as (
    select r.id, r.name,
           case when r.meta->>'grade' ~ '^\d{1,2}$' then (r.meta->>'grade')::integer end as g,
           case when r.meta->>'class' ~ '^\d{1,2}$' then (r.meta->>'class')::integer end as c,
           case when r.meta->>'number' ~ '^\d{1,3}$' then (r.meta->>'number')::integer end as n
    from resource r where r.type = 'student' and r.status = 'active'
  ), sub as (
    select s.* from course_selection_submission s where s.round_id = v_round.id
  ), scope as (
    -- 지금 재학생 중 대상 학년(미제출을 세려고) ∪ 이 회차에 낸 학생 — 둘 다 내가 볼 수 있는 반만
    select st.id, st.name, st.g, st.c, st.n from stu st
    where st.g = v_expect or exists (select 1 from sub where sub.student_resource_id = st.id)
  ), mine as (
    select sc.* from scope sc
    where sc.g is not null and sc.c is not null and sc.n is not null
      and mcp_private.sr_can_manage_student(sc.g, sc.c)
      and (v_grade is null or sc.g = v_grade) and (v_class is null or sc.c = v_class) and (v_no is null or sc.n = v_no)
  ), j as (
    select m.*, sub.id as sid, sub.status as sst, sub.submitted_at, sub.last_modified_at,
           case when sub.id is null then '미제출' when sub.status = 'submitted' then '제출' when sub.status = 'finalized' then '확정' else sub.status end as st
    from mine m left join sub on sub.student_resource_id = m.id
  )
  select jsonb_build_object('students', count(*), 'submitted', count(*) filter (where st = '제출'),
                            'finalized', count(*) filter (where st = '확정'), 'missing', count(*) filter (where st = '미제출')),
         coalesce((select jsonb_agg(x.o order by x.g, x.c, x.n) from (
           select j.g, j.c, j.n, jsonb_strip_nulls(jsonb_build_object('grade', j.g, 'class', j.c, 'number', j.n, 'name', j.name,
             'status', j.st,
             'submitted_at', to_char(j.submitted_at at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI'),
             'last_modified_at', to_char(j.last_modified_at at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI'),
             'items', case when v_items and j.sid is not null then (
               select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('semester', i.semester, 'subject', i.subject_name,
                        'priority', i.priority, 'assigned', i.is_assigned)) order by i.semester, i.priority nulls last, i.subject_name)
               from course_selection_item i where i.submission_id = j.sid) end)) as o
           from j where v_status is null or j.st = v_status
           order by j.g, j.c, j.n limit least(p_limit, 200)) x), '[]'::jsonb)
    into v_summary, v_rows
  from j;

  return jsonb_build_object(
    'round', jsonb_build_object('id', v_round.id, 'title', v_round.title, 'academic_year', v_round.academic_year,
      'admission_year', v_round.admission_year, 'grade_at_survey', v_round.target_grade, 'current_grade', v_expect,
      'round_number', v_round.round_number, 'status', v_round.status,
      'opens_at', to_char(v_round.opens_at at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI'),
      'closes_at', to_char(v_round.closes_at at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI')),
    'summary', v_summary, 'count', jsonb_array_length(v_rows), 'rows', v_rows, 'rounds', v_rounds,
    'note', '담임은 담임 반, 학년 부장은 그 학년, 관리자는 전교만 나온다. 미제출 = 지금 재학생 중 대상 학년(current_grade)인데 이 회차에 낸 것이 없는 학생. '
            || '확정 = 담당자가 마감 처리한 것. 학생 정보다 — 지금 하는 일에만 쓰고 다른 서비스로 옮기지 않는다.');
end;
$_$;


ALTER FUNCTION "mcp_private"."ds_course_selection"("p_me" "uuid", "p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_departments"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_year integer := coalesce(mcp_private.f_int(p, 'year', 2000, 2100), mcp_private.sch_year());
  v_q text := mcp_private.f_text(p, 'query'); ref date := mcp_private.seat_ref_date(v_year); v_rows jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_rows from (
    select jsonb_strip_nulls(jsonb_build_object(
      'department', d.name, 'category', d.category,
      'heads', (select jsonb_agg(h->>'name') from duty_seat s, jsonb_array_elements(mcp_private.seat_holders(s.id, ref)) h
                where s.academic_year = v_year and s.kind = 'head' and s.department_id = d.id),
      'members', (select jsonb_agg(r.name order by r.name) from department_member m join resource r on r.id = m.resource_id
                  where m.department_id = d.id and m.academic_year = v_year and r.status = 'active'),
      'member_count', (select count(*) from department_member m join resource r on r.id = m.resource_id
                       where m.department_id = d.id and m.academic_year = v_year and r.status = 'active'))) x
    from department d
    where d.is_active and (v_q is null or d.name ilike '%' || v_q || '%')
    order by d.display_order, d.name
    limit p_limit) s;
  return jsonb_build_object('academic_year', v_year, 'count', jsonb_array_length(v_rows), 'rows', v_rows);
end $$;


ALTER FUNCTION "mcp_private"."ds_departments"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_duty_seats"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_year integer := mcp_private.sch_year(); ref date := mcp_private.seat_ref_date(mcp_private.sch_year());
  v_q text := mcp_private.f_text(p, 'query'); v_dep text := mcp_private.f_text(p, 'department'); v_person text := mcp_private.f_text(p, 'person');
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_rows from (
    select jsonb_strip_nulls(jsonb_build_object(
      'seat', s.name,
      'kind', case s.kind when 'admin' then '관리자' when 'head' then '부장' when 'support' then '지원' else '업무' end,
      'department', d.name,
      'areas', (select jsonb_agg(a->>'name') from jsonb_array_elements(case when jsonb_typeof(s.areas) = 'array' then s.areas else '[]'::jsonb end) a),
      'holders', mcp_private.seat_holders(s.id, ref))) x
    from duty_seat s left join department d on d.id = s.department_id
    where s.academic_year = v_year
      and (v_q is null or s.name ilike '%' || v_q || '%'
           or exists (select 1 from jsonb_array_elements(case when jsonb_typeof(s.areas) = 'array' then s.areas else '[]'::jsonb end) a where a->>'name' ilike '%' || v_q || '%'))
      and (v_dep is null or coalesce(d.name, '') ilike '%' || v_dep || '%')
      and (v_person is null or exists (select 1 from jsonb_array_elements(mcp_private.seat_holders(s.id, ref)) h where h->>'name' ilike '%' || v_person || '%'))
    order by case s.kind when 'admin' then 0 when 'head' then 1 else 2 end, d.display_order nulls last, s.sort_order, s.name
    limit p_limit) l;
  return jsonb_build_object('academic_year', v_year, 'reference_date', ref, 'count', jsonb_array_length(v_rows), 'rows', v_rows);
end $$;


ALTER FUNCTION "mcp_private"."ds_duty_seats"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_homeroom_students"("p_me" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare h record;
begin
  select * into h from mcp_private.my_homeroom(p_me);
  return jsonb_build_object('grade', h.grade, 'class', h.class_num,
    'count', (select count(*) from mcp_private.room_students(h.grade, h.class_num)),
    'students', coalesce((select jsonb_agg(jsonb_build_object('number', s.no, 'name', r.name) order by s.no)
                          from mcp_private.room_students(h.grade, h.class_num) s join resource r on r.id = s.id), '[]'::jsonb),
    'note', '학생 정보다 — 지금 하는 일에만 쓰고 다른 서비스로 옮기지 않는다.');
end $$;


ALTER FUNCTION "mcp_private"."ds_homeroom_students"("p_me" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_my_profile"("p_me" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare c jsonb := mcp_private.person_card(p_me); t record; v_room text; v_teaching jsonb; v_synced boolean;
begin
  select * into t from mcp_private.current_term();
  select tg.name into v_room from resource_tag_assignments a join resource_tags tg on tg.id = a.tag_id
  where a.resource_id = p_me and btrim(tg.name) ~ '^[1-3]학년[[:space:]]*[0-9]{1,2}반$' limit 1;

  v_synced := exists (select 1 from school_exam_subject s where s.academic_year = t.academic_year and s.semester = t.semester);

  -- 이번 학기 수업: 과목 × 학년 → 반 목록 · 주당 시수 · 이번 학기 정기시험(계획)
  select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'subject', x.subject_name, 'grade', x.grade, 'classes', x.classes, 'periods_per_week', x.periods,
           'exams', case when v_synced then coalesce((
               select jsonb_agg(jsonb_build_object('exam', s.exam_name, 'reflect_ratio', s.reflect_ratio) order by s.exam_round nulls last, s.exam_name)
               from school_exam_subject s
               where s.academic_year = t.academic_year and s.semester = t.semester
                 and s.grade = x.grade and s.subject_name = x.subject_name), '[]'::jsonb) end))
         order by x.grade, x.subject_name)
    into v_teaching
  from (select tt.subject_name, tt.grade,
               jsonb_agg(distinct case when tt.grade is not null and coalesce(tt.class_label, '') <> ''
                                       then tt.grade || '-' || tt.class_label else tt.class_label end) as classes,
               count(*) as periods
        from teacher_timetable tt
        where tt.teacher_resource_id = p_me and tt.academic_year = t.academic_year and tt.semester = t.semester
          and coalesce(tt.subject_name, '') <> ''
        group by tt.subject_name, tt.grade) x;


  return jsonb_build_object('count', 1, 'rows', jsonb_build_array(jsonb_strip_nulls(c || jsonb_build_object(
    'role', (select pr.role from profiles pr where pr.id = auth.uid()),
    'homeroom', v_room, 'academic_year', t.academic_year, 'semester', t.semester,
    'teaching', coalesce(v_teaching, '[]'::jsonb),
    'exam_plan_synced', v_synced,
    'exam_note', case when v_synced then
        'teaching[].exams = 이번 학기 정기시험 계획(나이스 정기시험과목관리). 빈 목록이면 그 과목·학년은 정기시험이 없다(수행평가만). '
        || '정기시험이 있는 과목을 가르치면 그 시험의 출제·채점 대상이다.'
      else
        '이번 학기 정기시험 계획이 아직 올라오지 않았다(exam_plan_synced=false). '
        || '수업하는 과목에 정기시험이 있는지 모르면 «확인 필요»로 둔다.' end))));
end $_$;


ALTER FUNCTION "mcp_private"."ds_my_profile"("p_me" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_school_calendar"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_from date := coalesce(mcp_private.f_date(p, 'from'), mcp_private.kst_today());
  v_to   date := coalesce(mcp_private.f_date(p, 'to'), coalesce(mcp_private.f_date(p, 'from'), mcp_private.kst_today()) + 31);
  v_q    text := mcp_private.f_text(p, 'query');
  v_rows jsonb;
begin
  if v_to < v_from then raise exception using errcode = '22023', message = 'to 가 from 보다 앞입니다.'; end if;
  if v_to - v_from > 186 then raise exception using errcode = '22023', message = '기간은 186일까지입니다.'; end if;
  select coalesce(jsonb_agg(x order by x->>'date', x->>'title'), '[]'::jsonb) into v_rows from (
    select jsonb_strip_nulls(jsonb_build_object(
      'date', (m.starts_at at time zone 'Asia/Seoul')::date,
      'end_date', nullif((m.ends_at at time zone 'Asia/Seoul')::date, (m.starts_at at time zone 'Asia/Seoul')::date),
      'title', m.meta->>'title',
      'day_type', case
        when btrim(coalesce(m.meta->>'title', '')) = '토요휴업일' or m.meta->>'sbtr_dd_sc_nm' = '토요휴업일' then '토요휴업일'
        when m.meta->>'sbtr_dd_sc_nm' in ('휴업일', '공휴일')
          then case when jsonb_typeof(m.meta->'no_class_grades') = 'array' and jsonb_array_length(m.meta->'no_class_grades') between 1 and 2
                    then '일부 학년 휴업' else m.meta->>'sbtr_dd_sc_nm' end
        when coalesce(m.meta->>'title', '') ~ '[0-9]차고사' then '시험'
        else '수업일' end,
      'no_class_grades', case when m.meta->>'sbtr_dd_sc_nm' in ('휴업일', '공휴일') and jsonb_typeof(m.meta->'no_class_grades') = 'array'
                              and jsonb_array_length(m.meta->'no_class_grades') between 1 and 2 then m.meta->'no_class_grades' end)) x
    from meeting m
    where m.kind = 'schedule'
      and m.starts_at < ((v_to + 1)::timestamp at time zone 'Asia/Seoul')
      and m.ends_at >= (v_from::timestamp at time zone 'Asia/Seoul')
      and (v_q is null or coalesce(m.meta->>'title', '') ilike '%' || v_q || '%')
    order by m.starts_at
    limit p_limit) s;
  return jsonb_build_object('from', v_from, 'to', v_to, 'count', jsonb_array_length(v_rows), 'rows', v_rows,
    'note', '토요휴업일은 매주 토요일 표시다(주말). 휴업일·공휴일·일부 학년 휴업만 평일 수업이 없다.');
end $$;


ALTER FUNCTION "mcp_private"."ds_school_calendar"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_school_curriculum"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_adm integer := mcp_private.f_int(p, 'admission_year', 2000, 2100);
  v_year integer := mcp_private.f_int(p, 'academic_year', 2000, 2100);
  v_grade integer := mcp_private.f_int(p, 'grade', 1, 3);
  v_sem integer := mcp_private.f_int(p, 'semester', 1, 2);
  v_subj text := mcp_private.f_text(p, 'subject');
  v_area text := mcp_private.f_text(p, 'area');
  v_total integer;
  v_rows jsonb;
begin
  if v_adm is null and v_year is null then
    raise exception using errcode = '22023', message = 'school_curriculum 에는 admission_year(입학 연도) 나 academic_year(학년도) 중 하나가 필요합니다.';
  end if;
  with f as (
    select c.* from school_curriculum c
    where (v_adm is null or c.admission_year = v_adm) and (v_year is null or c.academic_year = v_year)
      and (v_grade is null or c.grade = v_grade) and (v_sem is null or c.semester = v_sem)
      and (v_subj is null or c.subject ilike '%' || v_subj || '%')
      and (v_area is null or concat_ws(' ', c.area, c.category) ilike '%' || v_area || '%')
  )
  select (select count(*) from f),
         coalesce((select jsonb_agg(x.j order by x.admission_year, x.grade, x.semester, x.area, x.subject) from (
           select f.admission_year, f.grade, f.semester, f.area, f.subject, jsonb_strip_nulls(jsonb_build_object(
             'admission_year', f.admission_year, 'academic_year', f.academic_year, 'grade', f.grade, 'semester', f.semester,
             'area', f.area, 'category', f.category, 'subject', f.subject, 'credits', f.credits, 'hours', f.hours,
             'grading_type', f.grading_type, 'subject_type', f.subject_type, 'selection_group', f.selection_group)) as j
           from f order by f.admission_year, f.grade, f.semester, f.area, f.subject limit p_limit) x), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'matched', v_total, 'truncated', p_limit < v_total, 'rows', v_rows,
    'note', '학교교육과정 편제(입학 연도별 — 한 입학 연도가 세 학년도에 걸친다). 선택군(selection_group)이 같은 과목은 그중에서 고른다.');
end;
$$;


ALTER FUNCTION "mcp_private"."ds_school_curriculum"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_school_info"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  t record; s jsonb; y integer := mcp_private.sch_year(); d date := mcp_private.kst_today(); ref date;
begin
  select * into t from mcp_private.current_term();
  select setting_value into s from system_settings where setting_key = 'academic_term';
  ref := mcp_private.seat_ref_date(y);
  return jsonb_build_object('count', 1, 'rows', jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
    -- 학교 고정값의 단일 출처 = neisApiService.ts(코드) · PrivacyPolicyContent.tsx(주소). 학교가 바뀌는 일은 없어 SQL 에 적는다
    'school_name', '샘플고등학교', 'short_name', '샘플고',
    'neis_office_code', 'Z99', 'neis_school_code', '9999999',
    'address', '전북특별자치도 전주시 완산구 유연로 133',
    'today', d, 'weekday', mcp_private.day_label(extract(isodow from d)::integer),
    'academic_year', t.academic_year, 'semester', t.semester,
    'term_start', s->>'start_date', 'term_end', s->>'end_date',
    'principal', (select mcp_private.seat_holders(ds.id, ref)->0->>'name' from duty_seat ds where ds.academic_year = y and ds.kind = 'admin' and ds.name = '교장' limit 1),
    'vice_principal', (select mcp_private.seat_holders(ds.id, ref)->0->>'name' from duty_seat ds where ds.academic_year = y and ds.kind = 'admin' and ds.name = '교감' limit 1),
    'periods', mcp_private.period_times()))));
end $$;


