CREATE OR REPLACE FUNCTION "mcp_private"."ds_section_students"("p_me" "uuid", "p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_subj text := mcp_private.f_text(p, 'subject'); v_class text := mcp_private.f_text(p, 'class'); v_rows jsonb;
begin
  select coalesce(jsonb_agg(x order by x->>'section'), '[]'::jsonb) into v_rows from (
    select jsonb_build_object('section', m.section, 'subject', m.subject, 'grade', m.grade, 'class', m.class_label,
      'student_count', count(distinct m.student_id),
      'students', jsonb_agg(distinct jsonb_build_object('grade', m.s_grade, 'class', m.s_class, 'number', m.s_no, 'name', m.s_name))) x
    from mcp_private.my_section_students(p_me) m
    where (v_subj is null or m.subject ilike '%' || v_subj || '%')
      and (v_class is null or (m.grade || '-' || m.class_label) = v_class or m.class_label = v_class)
    group by m.section, m.subject, m.grade, m.class_label
    limit p_limit) l;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'sections', v_rows,
    'note', '학생 정보다 — 지금 하는 일에만 쓰고 다른 서비스로 옮기지 않는다.');
end $$;


