CREATE OR REPLACE FUNCTION "mcp_private"."ds_staff"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_q text := mcp_private.f_text(p, 'query'); v_dep text := mcp_private.f_text(p, 'department');
  v_tag text := mcp_private.f_text(p, 'tag'); v_subj text := mcp_private.f_text(p, 'subject'); v_duty text := mcp_private.f_text(p, 'duty');
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(c order by c->>'name'), '[]'::jsonb) into v_rows from (
    select mcp_private.person_card(r.id) c
    from resource r
    where r.type in ('teacher', 'staff') and r.status = 'active'
      and (v_q is null or r.name ilike '%' || v_q || '%')
    ) s
  where (v_dep is null or exists (select 1 from jsonb_array_elements_text(coalesce(c->'departments', '[]')) e where e ilike '%' || v_dep || '%'))
    and (v_tag is null or exists (select 1 from jsonb_array_elements_text(coalesce(c->'tags', '[]')) e where e ilike '%' || v_tag || '%'))
    and (v_subj is null or exists (select 1 from jsonb_array_elements_text(coalesce(c->'subjects', '[]')) e where e ilike '%' || v_subj || '%'))
    and (v_duty is null or exists (select 1 from jsonb_array_elements_text(coalesce(c->'duties', '[]')) e where e ilike '%' || v_duty || '%'));
  return jsonb_build_object('academic_year', mcp_private.sch_year(), 'count', jsonb_array_length(v_rows),
    'rows', (select coalesce(jsonb_agg(e), '[]'::jsonb) from (select e from jsonb_array_elements(v_rows) e limit p_limit) l),
    'truncated', jsonb_array_length(v_rows) > p_limit);
end $$;


