CREATE OR REPLACE FUNCTION "mcp_private"."ds_student_attendance"("p_me" "uuid", "p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_today date := mcp_private.kst_today();
  v_from  date := coalesce(mcp_private.f_date(p, 'from'), date_trunc('month', mcp_private.kst_today())::date);
  v_to    date := coalesce(mcp_private.f_date(p, 'to'), mcp_private.kst_today());
  v_grade integer := mcp_private.f_int(p, 'grade', 1, 3);
  v_class integer := mcp_private.f_int(p, 'class', 1, 30);
  v_no    integer := mcp_private.f_int(p, 'number', 1, 99);
  v_daily boolean := true;
  v_stats jsonb; v_rows jsonb; v_none jsonb; v_matched integer;
begin
  if p ? 'daily' then
    if jsonb_typeof(p->'daily') <> 'boolean' then
      raise exception using errcode = '22023', message = '조건 daily 는 true · false 입니다.';
    end if;
    v_daily := (p->>'daily')::boolean;
  end if;
  if v_to < v_from then raise exception using errcode = '22023', message = 'to 가 from 보다 앞입니다.'; end if;
  if v_to - v_from > 92 then raise exception using errcode = '22023', message = '기간은 93일까지입니다.'; end if;

  v_stats := public.seaton_stats_students(v_from, v_to, null, null, false);

  with allowed as (
    select s.s_grade as g, s.s_class as c, s.s_no as n, s.s_name as nm from mcp_private.my_section_students(p_me) s
    union
    select h.grade, h.class_num, rs.no, r.name
    from mcp_private.my_homeroom_safe(p_me) h
    cross join lateral mcp_private.room_students(h.grade, h.class_num) rs
    join resource r on r.id = rs.id
  ), f as (
    select * from allowed
    where g is not null and c is not null and n is not null
      and (v_grade is null or g = v_grade) and (v_class is null or c = v_class) and (v_no is null or n = v_no)
  ), st as (
    select e from jsonb_array_elements(v_stats->'students') e
  ), hit as (
    select f.g, f.c, f.n, f.nm, st.e
    from f join st on (st.e->>'grade')::integer = f.g and (st.e->>'class')::integer = f.c and (st.e->>'number')::integer = f.n
  )
  select (select count(*) from hit),
         coalesce((select jsonb_agg(x.obj order by x.g, x.c, x.n) from (
           select h.g, h.c, h.n,
             jsonb_build_object('grade', h.g, 'class', h.c, 'number', h.n, 'name', h.nm,
               'total', (h.e->>'total')::integer, 'attended', (h.e->>'attended')::integer, 'absent', (h.e->>'absent')::integer,
               'pending', (h.e->>'pending')::integer, 'rate', h.e->'rate')
             || case when v_daily then jsonb_build_object('days', coalesce((
                  select jsonb_agg(jsonb_build_object('date', d.key, 'entries', (
                    select jsonb_agg(jsonb_build_object('period', (en->>0)::integer,
                      'status', case en->>1 when 'attended' then '출석' when 'excused' then '인정' when 'supplement' then '보완'
                                            when 'absent' then '결석' else '대기' end,
                      'room', (v_stats->'rooms'->((en->>3)::integer))->>1) order by (en->>0)::integer)
                    from jsonb_array_elements(d.value) en)) order by d.key)
                  from jsonb_each(h.e->'att') d), '[]'::jsonb))
                else '{}'::jsonb end as obj
           from hit h order by h.g, h.c, h.n limit p_limit) x), '[]'::jsonb),
         coalesce((select jsonb_agg(jsonb_build_object('grade', f.g, 'class', f.c, 'number', f.n, 'name', f.nm) order by f.g, f.c, f.n)
                   from (select * from f where not exists (select 1 from hit h where h.g = f.g and h.c = f.c and h.n = f.n)
                         order by g, c, n limit 200) f), '[]'::jsonb)
    into v_matched, v_rows, v_none;

  return jsonb_build_object('range', v_stats->'range', 'count', jsonb_array_length(v_rows), 'matched', v_matched,
    'truncated', v_matched > p_limit, 'rows', v_rows, 'no_record', v_none,
    'rules', '출석률 = 출석/(출석+결석), 대기(오늘 23시 전·미래)는 분모에 넣지 않는다. 인정·보완도 출석이다. 자습실 통계와 같은 규칙(seaton 계약).',
    'note', '내 담임 반·내 수업 반 학생만 나온다. no_record 는 그 기간에 신청 기록이 없는 내 학생이다. 학생 정보다 — 지금 하는 일에만 쓰고 다른 서비스로 옮기지 않는다.');
end $$;


ALTER FUNCTION "mcp_private"."ds_student_attendance"("p_me" "uuid", "p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_student_profile"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_grade integer := mcp_private.f_int(p, 'grade', 1, 3);
  v_class integer := mcp_private.f_int(p, 'class', 1, 30);
  v_no    integer := mcp_private.f_int(p, 'number', 1, 99);
  v_q     text    := mcp_private.f_text(p, 'query');
  v_off   integer := coalesce(mcp_private.f_int(p, 'offset', 0, 5000), 0);
  v_year  integer := mcp_private.sch_year();
  t       record;
  v_total integer;
  v_rows  jsonb;
begin
  select * into t from mcp_private.current_term();
  with s as (
    select rid, g, c, n, nm from (
      select r.id as rid,
             case when r.meta->>'grade'  ~ '^\d{1,2}$' then (r.meta->>'grade')::integer end as g,
             case when r.meta->>'class'  ~ '^\d{1,2}$' then (r.meta->>'class')::integer end as c,
             case when r.meta->>'number' ~ '^\d{1,3}$' then (r.meta->>'number')::integer end as n,
             r.name as nm
      from resource r
      where r.type = 'student' and r.status = 'active'
    ) x
    where g is not null and c is not null and n is not null
      and (v_grade is null or g = v_grade)
      and (v_class is null or c = v_class)
      and (v_no is null or n = v_no)
      and (v_q is null or nm ilike '%' || v_q || '%')
  ), page as (
    select * from s order by g, c, n limit p_limit offset v_off
  )
  select (select count(*) from s),
         coalesce((select jsonb_agg(jsonb_build_object(
             'grade', p.g, 'class', p.c, 'number', p.n, 'name', p.nm,
             -- 동아리 = 올해 활동 중인 동아리의 명단 스냅샷(resource_id 로 맞춘다 — 이름으로 맞추면 동명이인이 섞인다)
             'clubs', coalesce((select jsonb_agg(ci.name order by ci.name) from club_info ci
                                where ci.academic_year = v_year and coalesce(ci.meta->>'status', 'active') <> 'inactive'
                                  and jsonb_typeof(ci.students) = 'array'
                                  and ci.students @> jsonb_build_array(jsonb_build_object('resource_id', p.rid::text))), '[]'::jsonb),
             -- 수강 과목 = 이번 학기 시간표의 과목(중복 없이)
             'subjects', coalesce((select jsonb_agg(sj order by sj) from (
                                     select distinct st.subject as sj from student_timetable st
                                     where st.resource_id = p.rid and st.academic_year = t.academic_year and st.semester = t.semester
                                       and st.subject is not null) z), '[]'::jsonb)
           ) order by p.g, p.c, p.n) from page p), '[]'::jsonb)
    into v_total, v_rows;

  return jsonb_build_object('academic_year', t.academic_year, 'semester', t.semester,
    'total', v_total, 'count', jsonb_array_length(v_rows), 'offset', v_off,
    'truncated', v_off + jsonb_array_length(v_rows) < v_total, 'rows', v_rows,
    'note', '학번·이메일·사진·성적은 이 데이터셋에 없다. 시간표 자체는 student_timetable, 출결은 담임 반·내 수업 반 학생만 student_attendance. truncated 이면 grade·class·query 로 좁히거나 offset 을 올려 이어 읽는다. 학생 정보다 — 지금 하는 일에만 쓰고 다른 서비스로 옮기지 않는다.');
end $_$;


ALTER FUNCTION "mcp_private"."ds_student_profile"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_student_roster"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_grade integer := mcp_private.f_int(p, 'grade', 1, 3);
  v_class integer := mcp_private.f_int(p, 'class', 1, 30);
  v_q     text    := mcp_private.f_text(p, 'query');
  v_off   integer := coalesce(mcp_private.f_int(p, 'offset', 0, 5000), 0);
  v_total integer;
  v_rows  jsonb;
begin
  with s as (
    select g, c, n, nm from (
      select case when r.meta->>'grade'  ~ '^\d{1,2}$' then (r.meta->>'grade')::integer end as g,
             case when r.meta->>'class'  ~ '^\d{1,2}$' then (r.meta->>'class')::integer end as c,
             case when r.meta->>'number' ~ '^\d{1,3}$' then (r.meta->>'number')::integer end as n,
             r.name as nm
      from resource r
      where r.type = 'student' and r.status = 'active'
    ) x
    where g is not null and c is not null and n is not null
      and (v_grade is null or g = v_grade)
      and (v_class is null or c = v_class)
      and (v_q is null or nm ilike '%' || v_q || '%')
  ), page as (
    select * from s order by g, c, n limit p_limit offset v_off
  )
  select (select count(*) from s),
         coalesce((select jsonb_agg(jsonb_build_object('grade', g, 'class', c, 'number', n, 'name', nm) order by g, c, n) from page), '[]'::jsonb)
    into v_total, v_rows;

  return jsonb_build_object('total', v_total, 'count', jsonb_array_length(v_rows), 'offset', v_off,
    'truncated', v_off + jsonb_array_length(v_rows) < v_total, 'rows', v_rows,
    'note', '재학생의 학반 번호·이름뿐이다 — 동아리·수강 과목은 student_profile, 시간표는 student_timetable, 출결은 담임 반·내 수업 반 학생만 student_attendance 로 읽는다. truncated 이면 grade·class·query 로 좁히거나 offset 을 올려 이어 읽는다. 학생 정보다 — 지금 하는 일에만 쓰고 다른 서비스로 옮기지 않는다.');
end $_$;


ALTER FUNCTION "mcp_private"."ds_student_roster"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_student_timetable"("p_me" "uuid", "p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_no integer := mcp_private.f_int(p, 'number', 1, 99);
  v_grade integer := mcp_private.f_int(p, 'grade', 1, 3);
  v_class integer := mcp_private.f_int(p, 'class', 1, 30);
  h record; v_student uuid; v_name text; t record;
begin
  if v_no is null then raise exception using errcode = '22023', message = 'number(번호)가 필요합니다.'; end if;
  if v_grade is null and v_class is null then
    select * into h from mcp_private.my_homeroom(p_me);
    v_grade := h.grade; v_class := h.class_num;
  elsif v_grade is null or v_class is null then
    raise exception using errcode = '22023', message = 'grade·class 는 함께 주거나 둘 다 비웁니다(비우면 내 담임 반).';
  end if;
  select r.id, r.name into v_student, v_name from resource r
  where r.type = 'student' and r.status = 'active'
    and (r.meta->>'grade')::integer = v_grade and (r.meta->>'class')::integer = v_class and r.meta->>'number' = v_no::text
  limit 1;
  -- 전교 재학생이 대상이다(사용자 결정 2026-10-23) — 없는 번호만 거부한다
  if v_student is null then
    raise exception using errcode = 'P0002',
      message = format('%s학년 %s반 %s번 재학생이 없습니다 — student_roster 로 번호를 확인하세요.', v_grade, v_class, v_no);
  end if;
  select * into t from mcp_private.current_term();
  return jsonb_build_object(
    'student', jsonb_build_object('grade', v_grade, 'class', v_class, 'number', v_no, 'name', v_name),
    'academic_year', t.academic_year, 'semester', t.semester,
    'slots', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('day', s.day_of_week, 'day_label', mcp_private.day_label(s.day_of_week),
                         'period', s.period, 'subject', s.subject, 'teacher', s.teacher_name)) order by s.day_of_week, s.period)
                       from (select distinct st.day_of_week, st.period, st.subject, st.teacher_name from student_timetable st
                             where st.resource_id = v_student and st.academic_year = t.academic_year and st.semester = t.semester) s), '[]'::jsonb),
    'note', '학생 정보다 — 지금 하는 일에만 쓰고 다른 서비스로 옮기지 않는다.');
end $$;


ALTER FUNCTION "mcp_private"."ds_student_timetable"("p_me" "uuid", "p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_teacher_timetable"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_name text := mcp_private.f_text(p, 'teacher'); v_day integer := mcp_private.f_int(p, 'day', 1, 5);
  v_ids uuid[];
begin
  v_name := regexp_replace(coalesce(v_name, ''), '\s*(선생님|교사|님)$', '');
  select array_agg(r.id) into v_ids from resource r
  where r.type in ('teacher', 'staff') and r.status = 'active' and r.name = v_name;
  if v_ids is null then
    raise exception using errcode = 'P0002', message = format('재직 교직원 중 «%s» 이(가) 없습니다 — staff 데이터셋으로 이름을 먼저 찾으세요.', v_name);
  elsif array_length(v_ids, 1) > 1 then
    raise exception using errcode = '22023', message = format('«%s» 이(가) %s명입니다.', v_name, array_length(v_ids, 1));
  end if;
  return jsonb_build_object('teacher', v_name) || mcp_private.timetable_of(v_ids[1], v_day)
    || jsonb_build_object('note', '요일 모양 시간표다 — 그날 수업이 있는지는 school_calendar 로 함께 본다.');
end $_$;


ALTER FUNCTION "mcp_private"."ds_teacher_timetable"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ds_work_map"("p" "jsonb", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_year   integer := mcp_private.f_int(p, 'year', 2000, 2100);
  v_q      text := mcp_private.f_text(p, 'query');
  v_work   text := mcp_private.f_text(p, 'work');
  v_dep    text := mcp_private.f_text(p, 'department');
  v_office text := mcp_private.f_text(p, 'office');
  v_month  integer := mcp_private.f_int(p, 'month', 1, 12);
  v_seat   text := mcp_private.f_text(p, 'seat');
  v_offset integer := coalesce(mcp_private.f_int(p, 'offset', 0, 100000), 0);
  v_c      public.work_candidate;
  v_rows   jsonb;
  v_total  integer;
  v_note   text := '업무 지도는 문서 분석으로 만든 «학교가 실제로 하는 일»이다 — 시스템에 올라온 업무(list_managed_works)와 다르다. '
                  || 'seat_hint 는 분석 당시 자리라 참고만 한다(자리는 바뀔 수 있다) — 지금 담당자는 duty_seats · staff 로 확인한다. 사람 이름은 ○○ 로 가렸다.';
begin
  if v_office is not null and v_office not in ('교무실', '행정실') then
    raise exception using errcode = '22023', message = '조건 office 는 교무실 · 행정실 입니다.';
  end if;
  -- 학년도: 그 해 지도가 없으면 그보다 앞선 가장 최근 지도(새 학년도 초에 지도가 아직 없을 때)
  v_year := coalesce(
    (select max(academic_year) from work_candidate where kind = 'work' and academic_year <= coalesce(v_year, mcp_private.sch_year())),
    (select max(academic_year) from work_candidate where kind = 'work'));
  if v_year is null then
    return jsonb_build_object('count', 0, 'rows', '[]'::jsonb, 'note', '업무 지도 자료가 아직 없습니다.');
  end if;

  if v_work is not null then
    select * into v_c from work_candidate where academic_year = v_year and kind = 'work' and name = v_work order by id limit 1;
    if v_c.id is null then
      raise exception using errcode = 'P0002', message = format('%s학년도 업무 지도에 «%s» 업무가 없습니다 — query 로 이름을 먼저 찾으세요.', v_year, v_work);
    end if;
    return jsonb_build_object('academic_year', v_year, 'source_period', v_c.meta->>'source_period', 'note', v_note,
      'work', mcp_private.wm_detail(v_c));
  end if;

  select count(*)::integer into v_total
  from work_candidate c
  where c.academic_year = v_year and c.kind = 'work'
    and (v_q is null or c.name ilike '%' || v_q || '%' or coalesce(c.area_name, '') ilike '%' || v_q || '%')
    and (v_dep is null or coalesce(c.department, '') ilike '%' || v_dep || '%')
    and (v_office is null or (case when c.meta->>'office' = 'admin' then '행정실' else '교무실' end) = v_office)
    and (v_month is null or v_month = any(c.months))
    and (v_seat is null or coalesce(c.seat_name, c.seat_label, '') ilike '%' || v_seat || '%');
  select coalesce(jsonb_agg(mcp_private.wm_row(x) order by x.department nulls last, x.area_name nulls last, x.name), '[]') into v_rows
  from (select c.* from work_candidate c
        where c.academic_year = v_year and c.kind = 'work'
          and (v_q is null or c.name ilike '%' || v_q || '%' or coalesce(c.area_name, '') ilike '%' || v_q || '%')
          and (v_dep is null or coalesce(c.department, '') ilike '%' || v_dep || '%')
          and (v_office is null or (case when c.meta->>'office' = 'admin' then '행정실' else '교무실' end) = v_office)
          and (v_month is null or v_month = any(c.months))
          and (v_seat is null or coalesce(c.seat_name, c.seat_label, '') ilike '%' || v_seat || '%')
        order by c.department nulls last, c.area_name nulls last, c.name
        offset v_offset limit p_limit) x;
  return jsonb_build_object('academic_year', v_year,
    'source_period', (select meta->>'source_period' from work_candidate where academic_year = v_year and kind = 'work' and meta ? 'source_period' limit 1),
    'note', v_note, 'count', v_total, 'offset', v_offset, 'rows', v_rows,
    'truncated', v_offset + jsonb_array_length(v_rows) < v_total);
end $$;


ALTER FUNCTION "mcp_private"."ds_work_map"("p" "jsonb", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."f_date"("p" "jsonb", "k" "text") RETURNS "date"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare v text := btrim(coalesce(p->>k, ''));
begin
  if v = '' then return null; end if;
  if v !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception using errcode = '22023', message = format('조건 %s 는 YYYY-MM-DD 입니다.', k);
  end if;
  return v::date;
end $_$;


ALTER FUNCTION "mcp_private"."f_date"("p" "jsonb", "k" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."f_int"("p" "jsonb", "k" "text", "lo" integer, "hi" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare v text := btrim(coalesce(p->>k, ''));
begin
  if v = '' then return null; end if;
  if v !~ '^\d{1,6}$' or v::integer < lo or v::integer > hi then
    raise exception using errcode = '22023', message = format('조건 %s 는 %s~%s 의 정수입니다.', k, lo, hi);
  end if;
  return v::integer;
end $_$;


ALTER FUNCTION "mcp_private"."f_int"("p" "jsonb", "k" "text", "lo" integer, "hi" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."f_text"("p" "jsonb", "k" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if p ? k and jsonb_typeof(p->k) not in ('string', 'number') then
    raise exception using errcode = '22023', message = format('조건 %s 는 글자입니다.', k);
  end if;
  return nullif(left(btrim(coalesce(p->>k, '')), 100), '');
end $$;


ALTER FUNCTION "mcp_private"."f_text"("p" "jsonb", "k" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."file_ext"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select case when p_name ~ '\.[A-Za-z0-9]{1,10}$' then lower(substring(p_name from '\.([A-Za-z0-9]{1,10})$')) else 'bin' end;
$_$;


ALTER FUNCTION "mcp_private"."file_ext"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."file_mime"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case mcp_private.file_ext(p_name)
    when 'pdf' then 'application/pdf'
    when 'hwp' then 'application/x-hwp'
    when 'hwpx' then 'application/haansofthwpx'
    when 'doc' then 'application/msword'
    when 'docx' then 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    when 'xls' then 'application/vnd.ms-excel'
    when 'xlsx' then 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    when 'ppt' then 'application/vnd.ms-powerpoint'
    when 'pptx' then 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
    when 'csv' then 'text/csv'
    when 'txt' then 'text/plain'
    when 'md' then 'text/markdown'
    when 'html' then 'text/html'
    when 'htm' then 'text/html'
    when 'json' then 'application/json'
    when 'zip' then 'application/zip'
    when 'png' then 'image/png'
    when 'jpg' then 'image/jpeg'
    when 'jpeg' then 'image/jpeg'
    when 'gif' then 'image/gif'
    when 'webp' then 'image/webp'
    when 'svg' then 'image/svg+xml'
    when 'ico' then 'image/x-icon'
    when 'bmp' then 'image/bmp'
    when 'mp3' then 'audio/mpeg'
    when 'wav' then 'audio/wav'
    when 'ogg' then 'audio/ogg'
    when 'mp4' then 'video/mp4'
    when 'webm' then 'video/webm'
    when 'woff' then 'font/woff'
    when 'woff2' then 'font/woff2'
    when 'ttf' then 'font/ttf'
    when 'otf' then 'font/otf'
    when 'wasm' then 'application/wasm'
    else 'application/octet-stream' end;
$$;


ALTER FUNCTION "mcp_private"."file_mime"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."file_name_ok"("p" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare v text := btrim(coalesce(p, ''));
begin
  if v = '' then return null; end if;
  if v ~ '[\\/\r\n\t]' or v in ('.', '..') or char_length(v) > 200 then
    raise exception using errcode = '22023', message = '파일 이름이 올바르지 않습니다(경로 없이 이름만, 200자까지 — 예: 2026 교육계획.pdf).';
  end if;
  return v;
end $$;


ALTER FUNCTION "mcp_private"."file_name_ok"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."ipsi_lines"("p" "text"[], "p_name" "text", "p_max" integer DEFAULT 20) RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare v text[];
begin
  if p is null then
    return null;
  end if;
  select coalesce(array_agg(btrim(x) order by o), '{}') into v
  from unnest(p) with ordinality u(x, o) where btrim(coalesce(x, '')) <> '';
  if cardinality(v) > p_max then
    raise exception using errcode = '22023', message = format('%s 은(는) %s줄까지입니다.', p_name, p_max);
  end if;
  if exists (select 1 from unnest(v) x where length(x) > 1000) then
    raise exception using errcode = '22023', message = format('%s 의 한 줄은 1000자까지입니다.', p_name);
  end if;
  return v;
end;
$$;


