CREATE TABLE IF NOT EXISTS "public"."document_issue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "doc_type" "text" NOT NULL,
    "issue_no" "text" NOT NULL,
    "issue_year" integer NOT NULL,
    "title" "text" NOT NULL,
    "issued_on" "date" NOT NULL,
    "department" "text",
    "students" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "grade" integer,
    "class_number" integer,
    "form_data" "jsonb",
    "remarks" "text",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    CONSTRAINT "document_issue_doc_type_check" CHECK (("doc_type" = ANY (ARRAY['gajeong'::"text", 'volunteer_personal'::"text", 'volunteer_class'::"text", 'volunteer_club'::"text"]))),
    CONSTRAINT "document_issue_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."document_issue" OWNER TO "postgres";


COMMENT ON COLUMN "public"."document_issue"."status" IS '발급 상태. active(기본)=정상, cancelled=취소(삭제) — 행은 유지하되 대장에 발급번호만
   남기고 내용은 숨김(감사 추적용, 결번 방지). 취소는 UPDATE(기존 document_issue_update RLS,
   작성자/admin)로 처리하며 별도 DELETE는 더 이상 UI에서 호출하지 않는다.';



CREATE OR REPLACE FUNCTION "mcp_private"."iss_lock_mine"("p_issue_id" "uuid", "p_types" "text"[], "p_action" "text") RETURNS "public"."document_issue"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_row public.document_issue;
begin
  -- 잠그기 전에 읽는다 — SELECT … FOR UPDATE 는 UPDATE 정책(작성자·관리자)도 받아, 남의 발급이 «없음»으로 보인다
  select * into v_row from public.document_issue where id = p_issue_id;
  if not found then
    raise exception using errcode = 'P0002', message = '그 발급 기록을 찾을 수 없습니다 (list_issues 의 issue_id).';
  end if;
  if not v_row.doc_type = any(p_types) then
    raise exception using errcode = '22023',
      message = format('%s 발급이라 이 도구로 %s 수 없습니다.', mcp_private.iss_kind_label(v_row.doc_type), p_action);
  end if;
  if v_row.status = 'cancelled' then
    raise exception using errcode = '22023', message = format('%s 은(는) 이미 취소된 발급입니다.', v_row.issue_no);
  end if;
  if not (v_row.created_by = auth.uid() or public.is_admin()) then
    raise exception using errcode = '42501',
      message = format('%s 은(는) 내가 발급한 것이 아니라 %s 수 없습니다(작성자·관리자만).', v_row.issue_no, p_action);
  end if;
  select * into v_row from public.document_issue where id = p_issue_id for update;
  return v_row;
end;
$$;


ALTER FUNCTION "mcp_private"."iss_lock_mine"("p_issue_id" "uuid", "p_types" "text"[], "p_action" "text") OWNER TO "postgres";


