    'clubs', case when p.doc_type = 'volunteer_club' then
               (select jsonb_agg(c->>'club_name') from jsonb_array_elements(mcp_private.arr(p.form_data->'clubs')) c) end,
    'via_mcp', case when p.meta ? 'via' then true end));
$$;


