CREATE OR REPLACE FUNCTION "mcp_private"."iss_students"("p_refs" "jsonb", "p_hours" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $_$
declare
  v_ref   jsonb;
  v_txt   text;
  m       text[];
  v_g     integer;
  v_c     integer;
  v_n     integer;
  v_name  text;
  v_hits  jsonb;
  v_cnt   integer;
  v_out   jsonb := '[]'::jsonb;
  v_seen  uuid[] := '{}';
  v_bad   text[] := '{}';
  v_id    uuid;
begin
  if p_refs is null or jsonb_typeof(p_refs) <> 'array' or jsonb_array_length(p_refs) = 0 then
    raise exception using errcode = '22023', message = 'students 에 학생을 1명 이상 넣어 주세요 (예: {"grade":2,"class":5,"number":17}).';
  end if;
  if jsonb_array_length(p_refs) > 300 then
    raise exception using errcode = '22023', message = '한 번에 300명까지입니다.';
  end if;

  for v_ref in select * from jsonb_array_elements(p_refs) loop
    v_g := null; v_c := null; v_n := null; v_name := null;
    if jsonb_typeof(v_ref) = 'object' then
      v_g := mcp_private.iss_int(v_ref->>'grade');
      v_c := mcp_private.iss_int(v_ref->>'class');
      v_n := mcp_private.iss_int(v_ref->>'number');
      v_name := nullif(btrim(v_ref->>'name'), '');
      v_txt := coalesce(v_name, '') || case when v_g is not null then format(' (%s-%s-%s)', v_g, v_c, v_n) else '' end;
    elsif jsonb_typeof(v_ref) = 'string' then
      v_txt := btrim(v_ref #>> '{}');
      m := regexp_match(v_txt, '^([1-3])[[:space:]]*-[[:space:]]*([0-9]{1,2})[[:space:]]*-[[:space:]]*([0-9]{1,2})(?:[[:space:]]+(.+))?$');
      if m is null then
        m := regexp_match(v_txt, '^([1-3])([0-9]{2})([0-9]{2})(?:[[:space:]]+(.+))?$');
      end if;
      if m is not null then
        v_g := m[1]::integer; v_c := m[2]::integer; v_n := m[3]::integer; v_name := nullif(btrim(m[4]), '');
      else
        v_name := nullif(v_txt, '');
      end if;
    else
      v_bad := v_bad || format('%s — 학생은 {grade,class,number} 객체나 «2-5-17» 글자로 줍니다', v_ref::text);
      continue;
    end if;

    if v_name is null and (v_g is null or v_c is null or v_n is null) then
      v_bad := v_bad || format('%s — 학년·반·번호를 모두 주거나 이름을 주세요', coalesce(nullif(v_txt, ''), v_ref::text));
      continue;
    end if;

    select coalesce(jsonb_agg(jsonb_build_object(
             'resource_id', r.id, 'code', r.meta->>'id',
             'grade', mcp_private.iss_int(r.meta->>'grade'), 'class', mcp_private.iss_int(r.meta->>'class'),
             'number', mcp_private.iss_int(r.meta->>'number'), 'name', r.name, 'hours', coalesce(p_hours, 1))), '[]'::jsonb),
           count(*)
      into v_hits, v_cnt
    from public.resource r
    where r.type = 'student' and r.status = 'active'
      and (v_g is null or mcp_private.iss_int(r.meta->>'grade') = v_g)
      and (v_c is null or mcp_private.iss_int(r.meta->>'class') = v_c)
      and (v_n is null or mcp_private.iss_int(r.meta->>'number') = v_n)
      and (v_name is null or r.name = v_name);

    if v_cnt = 0 then
      v_bad := v_bad || format('%s — 재학생 중에 없습니다%s', v_txt,
        case when v_name is not null and v_g is not null then ' (학년·반·번호와 이름이 서로 다른지 확인)' else '' end);
    elsif v_cnt > 1 then
      v_bad := v_bad || format('%s — 같은 이름이 %s명입니다. 학년·반·번호로 주세요', v_txt, v_cnt);
    else
      v_id := (v_hits->0->>'resource_id')::uuid;
      if not v_id = any(v_seen) then
        v_seen := v_seen || v_id;
        v_out := v_out || v_hits;
      end if;
    end if;
  end loop;

  if cardinality(v_bad) > 0 then
    raise exception using errcode = '22023', hint = 'MCP_UNKNOWN_PERSON',
      message = format('학생을 정확히 찾지 못해 아무것도 발급하지 않았습니다 — %s', array_to_string(v_bad, ' · '));
  end if;
  return v_out;
end;
$_$;


