CREATE OR REPLACE FUNCTION "mcp_private"."iss_volunteer_form"("p_form" "jsonb", "p_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $_$
declare
  v_allowed text[] := case p_kind
    when 'personal' then array['period_start', 'period_end', 'org', 'org_tel', 'place', 'area', 'content', 'hours',
                               'note', 'opinion', 'confirmer_title', 'confirmer_name']
    else array['period_start', 'period_end', 'org', 'org_tel', 'place', 'area', 'content', 'hours', 'scope'] end;
  v_key   text;
  v_start date;
  v_end   date;
  v_hours numeric;
  v_out   jsonb;
begin
  if p_form is null or jsonb_typeof(p_form) <> 'object' then
    raise exception using errcode = '22023', message = 'form 은 봉사 양식 객체입니다.';
  end if;
  for v_key in select jsonb_object_keys(p_form) loop
    if not v_key = any(v_allowed) then
      raise exception using errcode = '22023',
        message = format('form 에 모르는 칸 «%s» — 쓸 수 있는 칸: %s', v_key, array_to_string(v_allowed, ' · '));
    end if;
  end loop;

  if coalesce(p_form->>'period_start', '') !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception using errcode = '22023', message = 'form.period_start(봉사 시작일, YYYY-MM-DD)가 필요합니다.';
  end if;
  v_start := (p_form->>'period_start')::date;
  if nullif(p_form->>'period_end', '') is not null then
    if p_form->>'period_end' !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception using errcode = '22023', message = 'form.period_end 는 YYYY-MM-DD 입니다.';
    end if;
    v_end := (p_form->>'period_end')::date;
    if v_end < v_start then
      raise exception using errcode = '22023', message = '봉사 종료일이 시작일보다 앞입니다.';
    end if;
  end if;

  if coalesce(p_form->>'area', '') not in ('이웃돕기활동', '환경보호활동', '캠페인활동') then
    raise exception using errcode = '22023', message = 'form.area 는 이웃돕기활동 · 환경보호활동 · 캠페인활동 중 하나입니다.';
  end if;
  if nullif(btrim(p_form->>'content'), '') is null or length(p_form->>'content') > 500 then
    raise exception using errcode = '22023', message = 'form.content(봉사활동 내용, 500자까지)가 필요합니다.';
  end if;
  if p_form ? 'hours' then
    if jsonb_typeof(p_form->'hours') <> 'number' and coalesce(p_form->>'hours', '') !~ '^\d+(\.\d+)?$' then
      raise exception using errcode = '22023', message = 'form.hours(인정시간)는 숫자입니다.';
    end if;
    v_hours := (p_form->>'hours')::numeric;
    if v_hours <= 0 or v_hours > 100 then
      raise exception using errcode = '22023', message = 'form.hours(인정시간)는 0보다 크고 100 이하입니다.';
    end if;
  else
    v_hours := 1;
  end if;
  if p_kind <> 'personal' and coalesce(p_form->>'scope', '정규교육과정 내') not in ('정규교육과정 내', '정규교육과정 외') then
    raise exception using errcode = '22023', message = 'form.scope 는 정규교육과정 내 · 정규교육과정 외 중 하나입니다.';
  end if;

  v_out := jsonb_build_object(
    'period_start', v_start::text,
    'org', coalesce(nullif(btrim(p_form->>'org'), ''), '샘플고등학교'),
    'org_tel', coalesce(nullif(btrim(p_form->>'org_tel'), ''), '000-0000-0032'),
    'place', coalesce(nullif(btrim(p_form->>'place'), ''), '샘플고등학교'),
    'area', p_form->>'area',
    'content', btrim(p_form->>'content'),
    'hours', v_hours);
  if v_end is not null then v_out := v_out || jsonb_build_object('period_end', v_end::text); end if;
  if p_kind = 'personal' then
    v_out := v_out || jsonb_build_object('confirmer_title', coalesce(nullif(btrim(p_form->>'confirmer_title'), ''), '교사'));
    if nullif(btrim(p_form->>'note'), '') is not null then v_out := v_out || jsonb_build_object('note', left(btrim(p_form->>'note'), 500)); end if;
    if nullif(btrim(p_form->>'opinion'), '') is not null then v_out := v_out || jsonb_build_object('opinion', left(btrim(p_form->>'opinion'), 500)); end if;
    if nullif(btrim(p_form->>'confirmer_name'), '') is not null then v_out := v_out || jsonb_build_object('confirmer_name', btrim(p_form->>'confirmer_name')); end if;
  else
    v_out := v_out || jsonb_build_object('scope', coalesce(p_form->>'scope', '정규교육과정 내'));
  end if;
  return v_out;
end;
$_$;


