    CONSTRAINT "meeting_kind_check" CHECK (("kind" = ANY (ARRAY['class'::"text", 'schedule'::"text", 'duty'::"text", 'training'::"text", 'event'::"text", 'document_submission'::"text", 'personal'::"text"]))),
