CREATE OR REPLACE FUNCTION "mcp_private"."meeting_insert"("p_kind" "text", "p_title" "text", "p_starts" timestamp with time zone, "p_ends" timestamp with time zone, "p_all_day" boolean, "p_desc" "text", "p_people" "jsonb", "p_extra" "jsonb", "p_me" "uuid") RETURNS "public"."meeting"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_row public.meeting;
begin
  insert into public.meeting (kind, starts_at, ends_at, status, meta, created_by, creator)
  values (
    p_kind, p_starts, p_ends, 'scheduled',
    jsonb_strip_nulls(jsonb_build_object(
      'title', p_title,
      'source', 'custom',
      'description', p_desc,
      'assignee', case when jsonb_array_length(coalesce(p_people, '[]')) > 0 then (
        select jsonb_object_agg(e->>'name',
                 case when p_kind = 'training' then jsonb_build_object('name', e->>'name', 'signature', 0)
                      else jsonb_build_object('name', e->>'name') end)
        from jsonb_array_elements(p_people) e) end,
      'exchangeable', false,
      'date_only', case when p_all_day then true end,
      'via', jsonb_build_object('channel', 'mcp', 'client_id', nullif(auth.jwt()->>'client_id', ''), 'at', now())
    )) || coalesce(p_extra, '{}'::jsonb),
    p_me, p_me)
  returning * into v_row;
  return v_row;
end;
$$;


