CREATE OR REPLACE FUNCTION "mcp_private"."month_absences"("p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('date', d, 'name', n, 'kind', m.kind,
           'title', coalesce(m.meta->>'title', case m.kind when 'event' then '출장' else '연수' end))), '[]'::jsonb)
  from meeting m
  cross join lateral jsonb_object_keys(case when jsonb_typeof(m.meta->'assignee') = 'object' then m.meta->'assignee' else '{}'::jsonb end) n
  cross join lateral generate_series((m.starts_at at time zone 'Asia/Seoul')::date,
                                     least((m.ends_at at time zone 'Asia/Seoul')::date, (m.starts_at at time zone 'Asia/Seoul')::date + 61), interval '1 day') g(dd)
  cross join lateral (select g.dd::date as d) x
  where m.kind in ('event', 'training')
    and m.starts_at < (p_to + 1)::timestamp at time zone 'Asia/Seoul'
    and m.ends_at >= p_from::timestamp at time zone 'Asia/Seoul'
    and x.d between p_from and p_to;
$$;


ALTER FUNCTION "mcp_private"."month_absences"("p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."my_grants"() RETURNS TABLE("resource_id" "uuid", "tool" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with mine as (
    select r.id, r.type
    from public.user_resource ur
    join public.resource r on r.id = ur.resource_id
    where auth.uid() is not null and ur.user_id = auth.uid() and r.type in ('teacher', 'staff')
  )
  select g.resource_id, g.tool
  from public.mcp_tool_grant g join mine m on m.id = g.resource_id
  union
  select m.id, p.tool
  from mine m join public.mcp_tool_policy p on p.teacher_default
  where m.type = 'teacher'
    and not exists (select 1 from public.mcp_tool_block b where b.resource_id = m.id and b.tool = p.tool);
$$;


ALTER FUNCTION "mcp_private"."my_grants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."my_homeroom"("p_me" "uuid", OUT "grade" integer, OUT "class_num" integer) RETURNS "record"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_count integer;
begin
  select count(*), min((m.parts)[1]::integer), min((m.parts)[2]::integer)
    into v_count, grade, class_num
  from public.resource r
  join public.resource_tag_assignments a on a.resource_id = r.id
  join public.resource_tags t on t.id = a.tag_id
  cross join lateral regexp_match(btrim(t.name), '^([1-3])학년[[:space:]]*([0-9]{1,2})반$') as m(parts)
  where r.id = p_me and r.type = 'teacher' and (m.parts)[2]::integer > 0;

  if v_count = 0 then
    raise exception using errcode = '42501',
      message = '담임 반이 없습니다 — 담임 태그(예: 2학년 3반)는 관리자가 붙입니다.',
      hint = 'MCP_NO_HOMEROOM';
  elsif v_count > 1 then
    raise exception using errcode = '42501',
      message = '담임 태그가 둘 이상이라 반을 정할 수 없습니다. 관리자에게 태그 정리를 요청하세요.',
      hint = 'MCP_HOMEROOM_AMBIGUOUS';
  end if;
end;
$_$;


ALTER FUNCTION "mcp_private"."my_homeroom"("p_me" "uuid", OUT "grade" integer, OUT "class_num" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."my_homeroom_safe"("p_me" "uuid") RETURNS TABLE("grade" integer, "class_num" integer)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  return query select h.grade, h.class_num from mcp_private.my_homeroom(p_me) h;
exception when others then
  return;
end $$;


