CREATE OR REPLACE FUNCTION "mcp_private"."my_section_students"("p_me" "uuid") RETURNS TABLE("section" "text", "subject" "text", "grade" integer, "class_label" "text", "student_id" "uuid", "s_grade" integer, "s_class" integer, "s_no" integer, "s_name" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with t as (select * from mcp_private.current_term()),
  tt as (select distinct x.subject_name, x.grade, x.class_label, x.day_of_week, x.period from teacher_timetable x, t
         where x.teacher_resource_id = p_me and x.academic_year = t.academic_year and x.semester = t.semester)
  select distinct
    tt.subject_name || case when tt.grade is not null and coalesce(tt.class_label, '') <> '' then ' ' || tt.grade || '-' || tt.class_label else '' end,
    tt.subject_name, tt.grade, tt.class_label, s.resource_id, s.student_grade, s.student_class, s.student_no, r.name
  from student_timetable s
  join t on s.academic_year = t.academic_year and s.semester = t.semester
  join tt on s.day_of_week = tt.day_of_week and s.period = tt.period and s.subject = tt.subject_name
  join resource r on r.id = s.resource_id and r.type = 'student' and r.status = 'active'
  where s.teacher_resource_id = p_me;
$$;


