CREATE OR REPLACE FUNCTION "mcp_private"."my_task_state"("p_task" "public"."task", "p_work_status" "text", "p_me" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with me as (
    select a.v from jsonb_array_elements(mcp_private.arr(p_task.meta->'assignees')) a(v)
    where a.v->>'id' = p_me::text limit 1
  )
  select case when not exists (select 1 from me) then null else jsonb_strip_nulls(jsonb_build_object(
    'my_status', case
      when p_task.status = 'cancelled' then 'cancelled'
      when p_task.status = 'completed' or p_work_status = 'completed' then 'completed'
      else coalesce((select v->>'status' from me), 'pending') end,
    'closed_by_manager', case when (p_task.status = 'completed' or p_work_status = 'completed')
                               and coalesce((select v->>'status' from me), 'pending') <> 'completed' then true end,
    'rounds', case when mcp_private.task_mode(p_task.meta) = 'rounds' then (
      select jsonb_agg(jsonb_build_object(
               'deadline', d.v #>> '{}',
               'status', coalesce(mcp_private.obj(p_task.meta->'deadlineProgress') -> (d.v #>> '{}') -> p_me::text ->> 'status', 'pending'))
             order by d.v #>> '{}')
      from jsonb_array_elements(p_task.meta->'deadlines') d(v)) end,
    'my_units', case when mcp_private.task_mode(p_task.meta) = 'units' then coalesce((
      select jsonb_agg(jsonb_build_object(
               'unit_key', u.v->>'key', 'label', u.v->>'label',
               'status', coalesce(mcp_private.obj(p_task.meta->'unitProgress') -> (u.v->>'key') -> p_me::text ->> 'status', 'pending'))
             order by u.ord)
      from jsonb_array_elements(p_task.meta->'units') with ordinality u(v, ord)
      where mcp_private.obj(p_task.meta->'unitProgress') -> (u.v->>'key') ? p_me::text), '[]'::jsonb) end,
    'unclaimed_units', case when mcp_private.task_mode(p_task.meta) = 'units' then (
      select count(*) from jsonb_array_elements(p_task.meta->'units') u(v)
      where mcp_private.obj(mcp_private.obj(p_task.meta->'unitProgress') -> (u.v->>'key')) = '{}'::jsonb) end,
    'submission_pending', case when p_task.status not in ('completed', 'cancelled') and p_work_status <> 'completed'
                                and public.assignee_has_pending_submission(p_task.id, p_me) then true end,
    'not_mine_reported', case when mcp_private.obj(p_task.meta->'assignmentIssues') ? p_me::text then true end
  )) end;
$$;


ALTER FUNCTION "mcp_private"."my_task_state"("p_task" "public"."task", "p_work_status" "text", "p_me" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."notice_department"("p" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v text := btrim(coalesce(p, ''));
begin
  if v = '' then raise exception using errcode = '22023', message = 'department 가 필요합니다.'; end if;
  if not exists (select 1 from department d where d.name = v and d.category = 'school') then
    raise exception using errcode = '22023',
      message = format('부서 «%s» 가 없습니다 — %s 중 하나로 적는다.', v,
                       (select string_agg(d.name, '·' order by d.display_order nulls last, d.name) from department d where d.category = 'school' and coalesce(d.is_active, true)));
  end if;
  return v;
end $$;


