CREATE OR REPLACE FUNCTION "mcp_private"."notice_out"("n" "public"."department_notice", "p_full" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'notice_id', n.id, 'title', n.title, 'department', n.department,
    'start_date', n.start_date, 'end_date', n.end_date,
    'state', case when n.start_date > mcp_private.kst_today() then '게시 예정'
                  when n.end_date < mcp_private.kst_today() then '게시 끝' else '게시 중' end,
    'author', n.author_name, 'mine', n.created_by = auth.uid(),
    'restricted', coalesce(cardinality(n.target_resource_ids), 0) > 0,
    'created_at', mcp_private.kst_ts(n.created_at),
    'content', case when p_full then n.content else left(n.content, 200) end,
    'attachments', (select jsonb_agg(a->>'name') from jsonb_array_elements(case when jsonb_typeof(n.attachments) = 'array' then n.attachments else '[]'::jsonb end) a),
    -- 열람 대상 이름은 쓴 사람(관리자)에게만 — 남의 대상 명단은 화면에도 없다
    'targets', case when p_full and coalesce(cardinality(n.target_resource_ids), 0) > 0 and (n.created_by = auth.uid() or public.is_admin())
                    then (select jsonb_agg(r.name order by r.name) from resource r where r.id = any(n.target_resource_ids)) end));
$$;


