CREATE OR REPLACE FUNCTION "mcp_private"."opt_text"("p" "text", "p_field" "text", "p_max" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if p is null or btrim(p) = '' then return null; end if;
  if char_length(btrim(p)) > p_max then
    raise exception using errcode = '22023', message = format('%s 은(는) %s자까지입니다.', p_field, p_max);
  end if;
  return btrim(p);
end $$;


