CREATE OR REPLACE FUNCTION "mcp_private"."parse_student"("p" "text", OUT "grade" integer, OUT "class_num" integer, OUT "num" integer) RETURNS "record"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare m text[];
begin
  m := regexp_match(btrim(coalesce(p, '')), '^([1-3])\s*(?:-|학년\s*)\s*([0-9]{1,2})\s*(?:-|반\s*)\s*([0-9]{1,2})\s*번?$');
  if m is null then
    raise exception using errcode = '22023', message = format('학생은 «학년-반-번호»(예: 2-3-15)로 적습니다: %s', p);
  end if;
  grade := m[1]::int; class_num := m[2]::int; num := m[3]::int;
end;
$_$;


