CREATE OR REPLACE FUNCTION "mcp_private"."person_card"("p_resource" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with y as (select mcp_private.sch_year() as year), t as (select * from mcp_private.current_term())
  select jsonb_strip_nulls(jsonb_build_object(
    'name', r.name,
    'type', case r.type when 'staff' then '직원' else '교사' end,
    'departments', (select jsonb_agg(d.name order by d.display_order, d.name) from department_member m join department d on d.id = m.department_id
                    where m.resource_id = r.id and m.academic_year = (select year from y)),
    'tags', (select jsonb_agg(tg.name order by tg.sort_order, tg.name) from resource_tag_assignments a join resource_tags tg on tg.id = a.tag_id
             where a.resource_id = r.id),
    'subjects', (select jsonb_agg(distinct tt.subject_name) from teacher_timetable tt, t
                 where tt.teacher_resource_id = r.id and tt.academic_year = t.academic_year and tt.semester = t.semester),
    'duties', (select jsonb_agg(s.name order by s.sort_order, s.name) from duty_seat s
               where s.academic_year = (select year from y)
                 and exists (select 1 from duty_seat_holder h where h.seat_id = s.id and h.resource_id = r.id
                             and (h.start_date is null or h.start_date <= mcp_private.seat_ref_date(s.academic_year))
                             and (h.end_date is null or h.end_date >= mcp_private.seat_ref_date(s.academic_year))))))
  from resource r where r.id = p_resource;
$$;


