    CONSTRAINT "academy_user_goals_constellation_lines_check" CHECK (("jsonb_typeof"("constellation_lines") = 'array'::"text")),
    CONSTRAINT "academy_user_goals_constellation_name_check" CHECK ((("char_length"("btrim"("constellation_name")) >= 1) AND ("char_length"("btrim"("constellation_name")) <= 60))),
