    CONSTRAINT "academy_user_goals_parent_shape" CHECK ((("parent_goal_id" IS NULL) OR (("horizon" = 'short'::"text") AND ("parent_goal_id" <> "id")))),
    CONSTRAINT "academy_user_goals_sky_region_check" CHECK ((("sky_region" >= 0) AND ("sky_region" <= 9995))),
    CONSTRAINT "user_goals_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text"])))
);


