CREATE OR REPLACE FUNCTION "mcp_private"."pl_time"("p" "text", "p_keep" time without time zone, "p_name" "text") RETURNS time without time zone
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
begin
  if p is null then return p_keep; end if;
  if btrim(p) = '' then return null; end if;
  if btrim(p) !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' and btrim(p) <> '24:00' then
    raise exception using errcode = '22023', message = format('%s 은(는) HH:MM(24시간)입니다.', p_name);
  end if;
  return case when btrim(p) = '24:00' then '23:59'::time else btrim(p)::time end;
end;
$_$;


ALTER FUNCTION "mcp_private"."pl_time"("p" "text", "p_keep" time without time zone, "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."pr_amount"("p_cells" "jsonb", "p_columns" "jsonb") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select case when exists (select 1 from jsonb_array_elements(mcp_private.arr(p_columns)) c where c->>'id' = 'default-price')
               and exists (select 1 from jsonb_array_elements(mcp_private.arr(p_columns)) c where c->>'id' = 'default-qty')
              and (mcp_private.obj(p_cells)->>'default-price') ~ '^\d+(\.\d+)?$'
              and (mcp_private.obj(p_cells)->>'default-qty') ~ '^\d+(\.\d+)?$'
         then (p_cells->>'default-price')::numeric * (p_cells->>'default-qty')::numeric end;
$_$;


ALTER FUNCTION "mcp_private"."pr_amount"("p_cells" "jsonb", "p_columns" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."pr_batch_label"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case p when 'draft' then '품의 작성 중' when 'submitted' then '품의 완료' when 'purchased' then '구매 완료' else p end;
$$;


ALTER FUNCTION "mcp_private"."pr_batch_label"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."pr_blank"("p" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$ select p is null or jsonb_typeof(p) = 'null' or (jsonb_typeof(p) = 'string' and btrim(p #>> '{}') = '') $$;


ALTER FUNCTION "mcp_private"."pr_blank"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."pr_build_cells"("p_input" "jsonb", "p_columns" "jsonb", "p_base" "jsonb", "p_label" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare
  v_out     jsonb := mcp_private.obj(p_base);
  v_key     text;
  v_val     jsonb;
  v_col     jsonb;
  v_text    text;
  v_num     numeric;
  v_missing text;
  v_names   text;
begin
  if p_input is null or jsonb_typeof(p_input) <> 'object' then
    raise exception using errcode = '22023', message = format('%s: cells 는 {칸 이름: 값} 객체여야 합니다.', p_label);
  end if;
  select string_agg(c->>'name', ' · ' order by o) into v_names
  from jsonb_array_elements(mcp_private.arr(p_columns)) with ordinality t(c, o);

  for v_key, v_val in select * from jsonb_each(p_input) loop
    v_col := (select c from jsonb_array_elements(mcp_private.arr(p_columns)) c
              where c->>'id' = v_key or btrim(c->>'name') = btrim(v_key) limit 1);
    if v_col is null then
      raise exception using errcode = '22023',
        message = format('%s: 이 페이지에 없는 칸입니다 — «%s». 칸: %s', p_label, v_key, v_names);
    end if;

    if mcp_private.pr_blank(v_val) then
      v_out := v_out || jsonb_build_object(v_col->>'id', '');
      continue;
    end if;

    if coalesce(v_col->>'type', 'text') = 'number' then
      v_text := replace(btrim(v_val #>> '{}'), ',', '');
      if jsonb_typeof(v_val) not in ('number', 'string') or v_text !~ '^\d+(\.\d+)?$' then
        raise exception using errcode = '22023',
          message = format('%s: «%s» 는 0 이상의 숫자 칸입니다.', p_label, v_col->>'name');
      end if;
      v_num := v_text::numeric;
      if v_num > 1000000000000 then
        raise exception using errcode = '22023', message = format('%s: «%s» 값이 너무 큽니다.', p_label, v_col->>'name');
      end if;
      v_out := v_out || jsonb_build_object(v_col->>'id', v_num);
    else
      if jsonb_typeof(v_val) not in ('string', 'number') then
        raise exception using errcode = '22023', message = format('%s: «%s» 는 글자 칸입니다.', p_label, v_col->>'name');
      end if;
      v_text := btrim(v_val #>> '{}');
      if length(v_text) > 1000 then
        raise exception using errcode = '22023', message = format('%s: «%s» 는 1000자까지입니다.', p_label, v_col->>'name');
      end if;
      if v_col->>'type' = 'url' and v_text !~ '^[a-zA-Z][a-zA-Z0-9+.-]*://' then
        v_text := 'https://' || v_text;
      end if;
      v_out := v_out || jsonb_build_object(v_col->>'id', v_text);
    end if;
  end loop;

  select string_agg(c->>'name', ' · ' order by o) into v_missing
  from jsonb_array_elements(mcp_private.arr(p_columns)) with ordinality t(c, o)
  where coalesce((c->>'required')::boolean, false) and mcp_private.pr_blank(v_out -> (c->>'id'));
  if v_missing is not null then
    raise exception using errcode = '22023', message = format('%s: 필수 칸이 비었습니다 — %s', p_label, v_missing);
  end if;

  -- 웹 표와 같은 모양: 모든 칸에 값(없으면 '')
  select v_out || coalesce(jsonb_object_agg(c->>'id', ''), '{}'::jsonb) into v_out
  from jsonb_array_elements(mcp_private.arr(p_columns)) c
  where not (v_out ? (c->>'id'));
  return v_out;
end;
$_$;


ALTER FUNCTION "mcp_private"."pr_build_cells"("p_input" "jsonb", "p_columns" "jsonb", "p_base" "jsonb", "p_label" "text") OWNER TO "postgres";


