    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', c->>'id', 'name', c->>'name', 'type', coalesce(c->>'type', 'text'),
           'required', coalesce((c->>'required')::boolean, false)) order by o), '[]'::jsonb)
  from jsonb_array_elements(mcp_private.arr(p_columns)) with ordinality t(c, o);
$$;


