    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(jsonb_object_agg(c->>'name', mcp_private.obj(p_cells) -> (c->>'id')), '{}'::jsonb)
  from jsonb_array_elements(mcp_private.arr(p_columns)) c
  where c->>'id' is distinct from mcp_private.pr_name_col(p_columns)
    and not mcp_private.pr_blank(mcp_private.obj(p_cells) -> (c->>'id'));
$$;


