CREATE OR REPLACE FUNCTION "mcp_private"."pr_history_diff"("p_columns" "jsonb", "p_o_items" "jsonb", "p_o_meta" "jsonb", "p_o_status" "text", "p_o_reason" "text", "p_n_items" "jsonb", "p_n_meta" "jsonb", "p_n_status" "text", "p_n_reason" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  with o as (
    select e.v->>'id' as rid, e.v->'cells' as cells, e.ord
    from jsonb_array_elements(mcp_private.arr(p_o_items)) with ordinality e(v, ord)
  ), n as (
    select e.v->>'id' as rid, e.v->'cells' as cells, e.ord
    from jsonb_array_elements(mcp_private.arr(p_n_items)) with ordinality e(v, ord)
  ), j as (
    select coalesce(n.rid, o.rid) as rid,
           coalesce(n.ord, 100000 + o.ord) as ord,
           o.cells as oc, n.cells as nc,
           (o.rid is null) as added, (n.rid is null) as removed,
           case when o.rid is not null then mcp_private.pr_item_status(p_o_meta, p_o_status, o.rid) end as os,
           case when n.rid is not null then mcp_private.pr_item_status(p_n_meta, p_n_status, n.rid) end as ns,
           case when o.rid is not null then mcp_private.pr_item_reason(p_o_meta, p_o_reason, o.rid) end as orr,
           case when n.rid is not null then mcp_private.pr_item_reason(p_n_meta, p_n_reason, n.rid) end as nrr
    from o full join n on n.rid = o.rid
  ), d as (
    select j.*,
           (select coalesce(jsonb_agg(jsonb_build_object(
                     'column', c->>'name',
                     'before', coalesce(j.oc->>(c->>'id'), ''),
                     'after',  coalesce(j.nc->>(c->>'id'), '')) order by t.pos), '[]'::jsonb)
              from jsonb_array_elements(mcp_private.arr(p_columns)) with ordinality t(c, pos)
             where not j.added and not j.removed
               and coalesce(j.oc->>(c->>'id'), '') is distinct from coalesce(j.nc->>(c->>'id'), '')) as cell_changes
    from j
  )
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'row_id', d.rid,
           'item', coalesce(nullif(mcp_private.obj(coalesce(d.nc, d.oc)) ->> mcp_private.pr_name_col(p_columns), ''), '(이름 없음)'),
           'change', case when d.added then 'added' when d.removed then 'removed' else 'edited' end,
           'cells', case when jsonb_array_length(d.cell_changes) > 0 then d.cell_changes end,
           'status', case when not d.added and not d.removed and d.os is distinct from d.ns
                          then jsonb_build_object('before', mcp_private.pr_status_label(d.os), 'after', mcp_private.pr_status_label(d.ns)) end,
           'reason', case when not d.added and not d.removed and d.orr is distinct from d.nrr
                          then jsonb_build_object('before', d.orr, 'after', d.nrr) end
         )) order by d.ord), '[]'::jsonb)
  from d
  where case when d.added or d.removed
             then mcp_private.pr_row_meaningful(coalesce(d.nc, d.oc), p_columns)
             else jsonb_array_length(d.cell_changes) > 0 or d.os is distinct from d.ns or d.orr is distinct from d.nrr end;
$$;


ALTER FUNCTION "mcp_private"."pr_history_diff"("p_columns" "jsonb", "p_o_items" "jsonb", "p_o_meta" "jsonb", "p_o_status" "text", "p_o_reason" "text", "p_n_items" "jsonb", "p_n_meta" "jsonb", "p_n_status" "text", "p_n_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."pr_item_reason"("p_meta" "jsonb", "p_reason" "text", "p_row_id" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case when mcp_private.obj(p_meta->'itemStatus') ? p_row_id
              then nullif(mcp_private.obj(p_meta->'itemStatus') -> p_row_id ->> 'reason', '')
              else nullif(p_reason, '') end;
$$;


ALTER FUNCTION "mcp_private"."pr_item_reason"("p_meta" "jsonb", "p_reason" "text", "p_row_id" "text") OWNER TO "postgres";


