CREATE OR REPLACE FUNCTION "mcp_private"."pr_lock_my_row"("p_me" "uuid", "p_request_id" "uuid", "p_row_id" "text", "p_action" "text", OUT "req" "public"."purchase_requests", OUT "page" "public"."purchase_request_pages", OUT "row_cells" "jsonb") RETURNS "record"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  if p_request_id is null or coalesce(btrim(p_row_id), '') = '' then
    raise exception using errcode = '22023', message = 'request_id 와 row_id 가 필요합니다 (list_my_purchase_requests 가 돌려준 값).';
  end if;
  select * into req from purchase_requests r where r.id = p_request_id and r.requester_id = p_me for update;
  if req.id is null then
    raise exception using errcode = '42501', message = '내 신청이 아니거나 없는 신청입니다.';
  end if;
  select * into page from purchase_request_pages p where p.id = req.page_id;
  perform mcp_private.pr_require_open(page, p_action);

  select e->'cells' into row_cells from jsonb_array_elements(mcp_private.arr(req.items)) e where e->>'id' = p_row_id limit 1;
  if row_cells is null then
    raise exception using errcode = 'P0002', message = '그 품목을 찾을 수 없습니다 — 이미 지워졌을 수 있습니다.';
  end if;

  v_status := mcp_private.pr_item_status(req.meta, req.status, p_row_id);
  if v_status not in ('submitted', 'pending') then
    raise exception using errcode = '42501',
      message = format('이미 처리된 품목(%s)이라 %s 수 없습니다 — 담당자에게 문의하세요.', mcp_private.pr_status_label(v_status), p_action);
  end if;
  if exists (select 1 from public.get_my_purchase_order_progress(req.page_id) g
             where g.request_id = p_request_id and g.row_id = p_row_id) then
    raise exception using errcode = '42501',
      message = format('담당자가 이미 품의에 담은 품목이라 %s 수 없습니다 — 담당자에게 문의하세요.', p_action);
  end if;
end;
$$;


ALTER FUNCTION "mcp_private"."pr_lock_my_row"("p_me" "uuid", "p_request_id" "uuid", "p_row_id" "text", "p_action" "text", OUT "req" "public"."purchase_requests", OUT "page" "public"."purchase_request_pages", OUT "row_cells" "jsonb") OWNER TO "postgres";


