    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case when p_type = 'student' then
           case when coalesce(p_meta->>'grade', '') <> '' and coalesce(p_meta->>'class', '') <> '' then
             format('학생 %s학년 %s반 %s번', p_meta->>'grade', p_meta->>'class', coalesce(nullif(p_meta->>'number', ''), '?'))
           else '학생' end
         else coalesce(p_name, '(이름 없음)') end;
$$;


