CREATE OR REPLACE FUNCTION "mcp_private"."pr_require_manager"("p_page_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
  if p_page_id is null or not public.is_purchase_page_manager(p_page_id) then
    raise exception using errcode = '42501', message = '이 페이지의 담당자(작성자·공동 작업자)만 할 수 있습니다.';
  end if;
end;
$$;


ALTER FUNCTION "mcp_private"."pr_require_manager"("p_page_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."pr_require_open"("p_page" "public"."purchase_request_pages", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    AS $$
begin
  if p_page.is_archived then
    raise exception using errcode = '42501', message = format('보관된 페이지라 %s 수 없습니다.', p_action);
  end if;
  if not ('teacher' = any(p_page.target_roles)) then
    raise exception using errcode = '42501', message = format('교직원 대상 페이지가 아니라 %s 수 없습니다.', p_action);
  end if;
  if now() < p_page.period_start then
    raise exception using errcode = '42501',
      message = format('아직 신청 기간이 아닙니다 (%s 부터) — %s 수 없습니다.', mcp_private.pr_kst(p_page.period_start), p_action);
  end if;
  if now() > p_page.period_end then
    raise exception using errcode = '42501',
      message = format('신청 기간이 끝났습니다 (%s 까지) — %s 수 없습니다. 담당자에게 문의하세요.', mcp_private.pr_kst(p_page.period_end), p_action);
  end if;
end;
$$;


ALTER FUNCTION "mcp_private"."pr_require_open"("p_page" "public"."purchase_request_pages", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."pr_row_id"("p_seq" integer) RETURNS "text"
    LANGUAGE "sql"
    AS $$
  select (floor(extract(epoch from clock_timestamp()) * 1000))::bigint::text || '-'
         || substr(md5(random()::text || p_seq::text), 1, 10);
$$;


