    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if p_val is null then return null; end if;
  if length(btrim(p_val)) > p_max then
    raise exception using errcode = '22023', message = format('%s 은 %s자까지입니다.', p_name, p_max);
  end if;
  return btrim(p_val);
end;
$$;


