    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case p when 'submitted' then '제출됨' when 'pending' then '검토중' when 'approved' then '승인'
                when 'completed' then '완료' when 'rejected' then '불가' else coalesce(p, '제출됨') end;
$$;


