CREATE OR REPLACE FUNCTION "mcp_private"."require_any_tool"("p_tools" "text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_resource uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = '로그인이 필요합니다.';
  end if;
  select g.resource_id into v_resource from mcp_private.my_grants() g where g.tool = any(p_tools) limit 1;
  if v_resource is null then
    raise exception using errcode = '42501',
      message = '데이터 읽기 허용이 하나도 없습니다. 관리자에게 요청하세요.', hint = 'MCP_TOOL_NOT_GRANTED';
  end if;
  return v_resource;
end;
$$;


ALTER FUNCTION "mcp_private"."require_any_tool"("p_tools" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."require_tool"("p_tool" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_resource uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = '로그인이 필요합니다.';
  end if;

  select g.resource_id into v_resource from mcp_private.my_grants() g where g.tool = p_tool limit 1;

  if v_resource is null then
    raise exception using errcode = '42501',
      message = format('이 도구(%s)는 아직 허용되지 않았습니다. 관리자에게 요청하세요.', p_tool),
      hint = 'MCP_TOOL_NOT_GRANTED';
  end if;
  return v_resource;
end;
$$;


