CREATE OR REPLACE FUNCTION "mcp_private"."room_students"("p_grade" integer, "p_class" integer) RETURNS TABLE("id" "uuid", "no" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  select r.id, (r.meta->>'number')::integer
  from public.resource r
  where r.type = 'student' and r.status = 'active'
    and (r.meta->>'grade')::integer = p_grade
    and (r.meta->>'class')::integer = p_class
    and r.meta->>'number' ~ '^\d+$';
$_$;


