CREATE TABLE IF NOT EXISTS "public"."school_context" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "key" "text" NOT NULL,
    "title" "text" NOT NULL,
    "area" "text" NOT NULL,
    "kind" "text" DEFAULT 'note'::"text" NOT NULL,
    "summary" "text" NOT NULL,
    "structure" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "contents" "text",
    "locations" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "maintenance" "text",
    "body" "text",
    "tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "sensitivity" "text" DEFAULT 'none'::"text" NOT NULL,
    "live" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "archived_reason" "text",
    "created_by" "uuid",
    "updated_by" "uuid",
    "via" "text" DEFAULT 'web'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "school_context_archived_reason_check" CHECK ((("archived_reason" IS NULL) OR ("length"("archived_reason") <= 500))),
    CONSTRAINT "school_context_area_check" CHECK (("area" = ANY (ARRAY['학교·학사'::"text", '교육과정'::"text", '평가'::"text", '업무'::"text", '조직'::"text", '학생'::"text", '시설·자원'::"text", '규정·지침'::"text", '기타'::"text"]))),
    CONSTRAINT "school_context_body_check" CHECK ((("body" IS NULL) OR ("length"("body") <= 8000))),
    CONSTRAINT "school_context_check" CHECK ((("kind" = 'source'::"text") OR (("body" IS NOT NULL) AND ("length"("btrim"("body")) > 0)))),
    CONSTRAINT "school_context_contents_check" CHECK ((("contents" IS NULL) OR ("length"("contents") <= 1500))),
    CONSTRAINT "school_context_key_check" CHECK (("key" ~ '^[a-z][a-z0-9_]{1,59}$'::"text")),
    CONSTRAINT "school_context_kind_check" CHECK (("kind" = ANY (ARRAY['source'::"text", 'note'::"text"]))),
    CONSTRAINT "school_context_locations_check" CHECK ((("jsonb_typeof"("locations") = 'array'::"text") AND ("jsonb_array_length"("locations") <= 20))),
    CONSTRAINT "school_context_maintenance_check" CHECK ((("maintenance" IS NULL) OR ("length"("maintenance") <= 600))),
    CONSTRAINT "school_context_sensitivity_check" CHECK (("sensitivity" = ANY (ARRAY['none'::"text", 'staff'::"text", 'student'::"text"]))),
    CONSTRAINT "school_context_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"]))),
    CONSTRAINT "school_context_structure_check" CHECK ((("jsonb_typeof"("structure") = 'array'::"text") AND ("jsonb_array_length"("structure") <= 40))),
    CONSTRAINT "school_context_summary_check" CHECK ((("length"("btrim"("summary")) >= 1) AND ("length"("btrim"("summary")) <= 600))),
    CONSTRAINT "school_context_tags_check" CHECK (("cardinality"("tags") <= 20)),
    CONSTRAINT "school_context_title_check" CHECK ((("length"("btrim"("title")) >= 1) AND ("length"("btrim"("title")) <= 120))),
    CONSTRAINT "school_context_via_check" CHECK (("via" = ANY (ARRAY['web'::"text", 'mcp'::"text", 'system'::"text"])))
);


ALTER TABLE "public"."school_context" OWNER TO "postgres";


COMMENT ON TABLE "public"."school_context" IS '학교 맥락 목록(2026-11-06) — 어떤 지식이 어디에 어떤 구조로 있는지(source)와 새로 적은 맥락(note). 개별 자료 열람용이 아니다. 읽기 = 교직원·교사·관리자, note 쓰기 = 같은 사람(고치기는 쓴 사람·관리자), source = 관리자. 지우지 않고 보관.';



CREATE OR REPLACE FUNCTION "mcp_private"."sc_entry"("c" "public"."school_context", "p_full" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(case when p_full then jsonb_build_object(
      'key', c.key, 'title', c.title, 'area', c.area, 'kind', c.kind, 'summary', c.summary,
      'structure', c.structure, 'contents', c.contents, 'locations', c.locations, 'maintenance', c.maintenance,
      'body', c.body, 'tags', to_jsonb(c.tags), 'sensitivity', c.sensitivity, 'status', c.status, 'archived_reason', c.archived_reason,
      'live', mcp_private.sc_live(c.live), 'mine', c.created_by = auth.uid(),
      'written_by', (select p.name from profiles p where p.id = c.created_by), 'updated_at', c.updated_at)
    else jsonb_build_object(
      'key', c.key, 'title', c.title, 'area', c.area, 'kind', c.kind, 'summary', c.summary,
      'where', (select jsonb_agg(l->>'type' || ':' || coalesce(l->>'ref', '')) from jsonb_array_elements(c.locations) l),
      'sensitivity', nullif(c.sensitivity, 'none'), 'status', nullif(c.status, 'active'),
      'live', mcp_private.sc_live(c.live), 'updated_at', c.updated_at::date)
    end);
$$;


ALTER FUNCTION "mcp_private"."sc_entry"("c" "public"."school_context", "p_full" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sc_live"("p_live" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r jsonb;
begin
  case p_live
  when 'exam_subject' then
    select jsonb_build_object('rows', count(*), 'semesters', coalesce(jsonb_agg(distinct academic_year || '-' || semester), '[]'),
                              'last_synced', max(synced_at)) into r from school_exam_subject;
  when 'achievement_standards' then
    select jsonb_build_object('docgen_subjects', (select count(*) from docgen_context where category = '성취기준' and not hidden),
                              'standards', count(*), 'subjects', count(distinct subject),
                              'curriculum_years', coalesce(jsonb_agg(distinct curriculum_year), '[]')) into r
    from subject_achievement_standards;
  when 'school_curriculum' then
    select jsonb_build_object('rows', count(*), 'admission_years', coalesce(jsonb_agg(distinct admission_year), '[]'),
                              'last_updated', max(updated_at)) into r from school_curriculum;
  when 'duty_seats' then
    select jsonb_build_object('seats', count(*), 'years', coalesce(jsonb_agg(distinct academic_year), '[]'),
                              'holders', (select count(*) from duty_seat_holder h where h.end_date is null or h.end_date >= current_date)) into r
    from duty_seat;
  when 'work_map' then
    select jsonb_build_object('areas', count(*) filter (where kind = 'area'), 'works', count(*) filter (where kind = 'work'),
                              'years', coalesce(jsonb_agg(distinct academic_year), '[]')) into r from work_candidate;
  when 'work_knowledge' then
    select jsonb_build_object('active', count(*) filter (where status = 'active'), 'works', count(distinct work_id),
                              'by_kind', (select coalesce(jsonb_object_agg(kind, n), '{}') from
                                (select kind, count(*) n from work_knowledge where status = 'active' group by kind) k),
                              'last_updated', max(updated_at), 'note', '내가 책임자인 업무의 지식만 센다') into r from work_knowledge;
  when 'work_summary' then
    select jsonb_build_object('documents', count(*), 'last_uploaded', max(created_at)) into r
    from documents where not coalesce(is_hidden, false) and title like '%업무 요약%';
  when 'documents' then
    select jsonb_build_object('documents', count(*), 'folders', (select count(*) from document_folders),
                              'last_uploaded', max(created_at)) into r from documents where not coalesce(is_hidden, false);
  when 'docgen_context' then
    select jsonb_build_object('by_category', coalesce(jsonb_object_agg(c, n), '{}')) into r
    from (select coalesce(category, '(분류 없음)') c, count(*) n from docgen_context where not hidden group by 1) x;
  when 'calendar' then
    select jsonb_build_object('rows', count(*), 'by_kind', (select coalesce(jsonb_object_agg(kind, n), '{}') from
                                (select kind, count(*) n from meeting where kind in ('schedule', 'event', 'training', 'duty') group by kind) k),
                              'from', min(starts_at)::date, 'to', max(starts_at)::date) into r
    from meeting where kind in ('schedule', 'event', 'training', 'duty');
  when 'notices' then
    select jsonb_build_object('notices', count(*), 'current', count(*) filter (where end_date is null or end_date >= current_date)) into r
    from department_notice;
  when 'clubs' then
    select jsonb_build_object('clubs', count(*), 'years', coalesce(jsonb_agg(distinct academic_year), '[]')) into r from club_info;
  when 'staff' then
    select jsonb_build_object('staff', (select count(*) from profiles where role in ('teacher', 'admin', 'staff')),
                              'departments', (select count(*) from department)) into r;
  when 'contexts' then
    select jsonb_build_object('active', count(*) filter (where status = 'active'),
                              'notes', count(*) filter (where status = 'active' and kind = 'note')) into r from school_context;
  else
    r := null;
  end case;
  return r;
exception when undefined_table or undefined_column or insufficient_privilege then
  return jsonb_build_object('error', '세지 못했습니다(' || sqlstate || ')');
end;
$$;


ALTER FUNCTION "mcp_private"."sc_live"("p_live" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sch_kind_label"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case p when 'schedule' then '학사일정' when 'event' then '출장' when 'duty' then '업무'
                when 'training' then '연수' when 'document_submission' then '서류제출' when 'personal' then '개인일정' else p end;
$$;


ALTER FUNCTION "mcp_private"."sch_kind_label"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sch_lock_mine"("p_id" "uuid", "p_me" "uuid", "p_action" "text") RETURNS "public"."meeting"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v public.meeting;
begin
  if p_id is null then
    raise exception using errcode = '22023', message = 'schedule_id 가 필요합니다 (list_schedules 가 돌려준 id).';
  end if;
  select * into v from meeting m where m.id = p_id and m.created_by = p_me for update;
  if v.id is null then
    raise exception using errcode = '42501',
      message = format('내가 만든 일정만 %s 수 있습니다(list_schedules 의 mine=true).', p_action);
  end if;
  if v.kind = 'document_submission' then
    raise exception using errcode = '42501', message = format('서류제출 일정은 웹에서 %s 수 있습니다(첨부 파일이 함께 있다).', p_action);
  end if;
  return v;
end;
$$;


ALTER FUNCTION "mcp_private"."sch_lock_mine"("p_id" "uuid", "p_me" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sch_out"("p" "public"."meeting", "p_me" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', p.id, 'kind', p.kind, 'kind_label', mcp_private.sch_kind_label(p.kind),
    'title', p.meta->>'title',
    'starts_at', to_char(p.starts_at at time zone 'Asia/Seoul', 'YYYY-MM-DD"T"HH24:MI'),
    'ends_at', to_char(p.ends_at at time zone 'Asia/Seoul', 'YYYY-MM-DD"T"HH24:MI'),
    'all_day', coalesce((p.meta->>'date_only')::boolean, false),
    'description', nullif(p.meta->>'description', ''),
    'attendees', case when p.kind <> 'personal' and jsonb_typeof(p.meta->'assignee') = 'object'
                      then (select jsonb_agg(k order by k) from jsonb_object_keys(p.meta->'assignee') k) end,
    'mine', p.created_by = p_me));
$$;


ALTER FUNCTION "mcp_private"."sch_out"("p" "public"."meeting", "p_me" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sch_people"("p_names" "text"[]) RETURNS TABLE("id" "uuid", "name" "text", "type" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_clean   text[];
  v_missing text;
begin
  select coalesce(array_agg(distinct n), '{}') into v_clean
  from (select btrim(regexp_replace(btrim(x), '\s*(선생님|선생|쌤|님)$', '')) as n from unnest(coalesce(p_names, '{}')) x) s
  where n <> '';
  if cardinality(v_clean) > 150 then
    raise exception using errcode = '22023', message = '참석자는 150명까지입니다.';
  end if;

  select string_agg(n, ', ' order by n) into v_missing
  from unnest(v_clean) n
  where (select count(*) from resource r
         where r.name = n and r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active') <> 1;
  if v_missing is not null then
    raise exception using errcode = '22023',
      message = format('교직원 명단에서 한 명으로 찾지 못한 이름이 있습니다 — %s. find_staff 로 정확한 이름을 확인하세요.', v_missing),
      hint = 'MCP_UNKNOWN_PERSON';
  end if;

  return query
    select r.id, r.name, r.type from resource r
    where r.name = any(v_clean) and r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active'
    order by r.name;
end;
$_$;


ALTER FUNCTION "mcp_private"."sch_people"("p_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sch_require_kind_grant"("p_row" "public"."meeting") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_has text[];
  v_need text;
begin
  select coalesce(array_agg(g.tool), '{}') into v_has from mcp_private.my_grants() g;
  if 'schedule.manage' = any(v_has) then return; end if;
  v_need := case
    when p_row.kind = 'personal' then 'schedule.mine'
    when p_row.kind = 'duty' and p_row.meta ? 'supervision' then 'supervision.plan'
    when p_row.kind = 'duty' and coalesce(p_row.meta->>'title', '') like '급식지도 - %' then 'mealduty.plan'
  end;
  if v_need is null or not v_need = any(v_has) then
    raise exception using errcode = '42501', hint = 'MCP_TOOL_NOT_GRANTED',
      message = format('이 %s 일정을 고치거나 지우려면 «일정 만들기·고치기» 허용이 필요합니다 — 관리자에게 요청하세요.',
                       mcp_private.sch_kind_label(p_row.kind));
  end if;
end $$;


ALTER FUNCTION "mcp_private"."sch_require_kind_grant"("p_row" "public"."meeting") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sch_window"("p_date" "date", "p_end_date" "date", "p_start" time without time zone, "p_end" time without time zone, OUT "starts_at" timestamp with time zone, OUT "ends_at" timestamp with time zone, OUT "all_day" boolean) RETURNS "record"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_last  date := coalesce(p_end_date, p_date);
begin
  if p_date is null or p_date < v_today - 366 or p_date > v_today + 731 then
    raise exception using errcode = '22023', message = '날짜는 지난 1년 ~ 앞으로 2년 안이어야 합니다.';
  end if;
  if v_last < p_date then
    raise exception using errcode = '22023', message = '끝 날짜가 시작 날짜보다 앞입니다.';
  end if;
  if v_last - p_date > 31 then
    raise exception using errcode = '22023', message = '한 일정은 31일까지입니다.';
  end if;
  if p_start is null and p_end is not null then
    raise exception using errcode = '22023', message = '끝 시각만 적을 수는 없습니다. 시작 시각도 적어 주세요.';
  end if;

  all_day := p_start is null;
  if all_day then
    starts_at := p_date::timestamp at time zone 'Asia/Seoul';
    ends_at   := (v_last + time '23:59:59') at time zone 'Asia/Seoul';
  else
    starts_at := (p_date + p_start) at time zone 'Asia/Seoul';
    ends_at   := (v_last + coalesce(p_end,
                   case when p_end_date is not null and p_end_date > p_date then time '23:59:59'
                        when p_start >= time '23:00' then time '23:59:59'
                        else p_start + interval '1 hour' end))
                 at time zone 'Asia/Seoul';
    if ends_at < starts_at then
      raise exception using errcode = '22023', message = '끝 시각이 시작 시각보다 앞입니다.';
    end if;
  end if;
end;
$$;


ALTER FUNCTION "mcp_private"."sch_window"("p_date" "date", "p_end_date" "date", "p_start" time without time zone, "p_end" time without time zone, OUT "starts_at" timestamp with time zone, OUT "ends_at" timestamp with time zone, OUT "all_day" boolean) OWNER TO "postgres";


