CREATE OR REPLACE FUNCTION "mcp_private"."schedule_rows"("p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('starts_at', m.starts_at, 'ends_at', m.ends_at, 'meta',
           jsonb_strip_nulls(jsonb_build_object('title', m.meta->'title', 'sbtr_dd_sc_nm', m.meta->'sbtr_dd_sc_nm',
                                                'no_class_grades', m.meta->'no_class_grades')))), '[]'::jsonb)
  from meeting m
  where m.kind = 'schedule'
    and m.starts_at < (p_to + 1)::timestamp at time zone 'Asia/Seoul'
    and m.ends_at >= p_from::timestamp at time zone 'Asia/Seoul';
$$;


