              then (select array_agg((e->>'id')::int order by (e->>'id')::int) from jsonb_array_elements(r.operating_periods) e)
              else array[0] end;
$$;


ALTER FUNCTION "mcp_private"."sr_period_ids"("r" "public"."study_rooms") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sr_require_head"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
  if mcp_private.sr_is_admin() then return; end if;
  if not exists (select 1 from unnest(mcp_private.sr_my_tags()) t where t ~ '^[0-9]+학년\s*부장$') then
    raise exception using errcode = '42501', message = '열람실 설정(신청 기간·운영 기간·학년·이름 등)은 학년 부장·관리자만 바꿀 수 있습니다.';
  end if;
end $_$;


ALTER FUNCTION "mcp_private"."sr_require_head"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sr_require_teacher"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (select 1 from profiles where id = auth.uid() and role in ('teacher', 'admin')) then
    raise exception using errcode = '42501', message = '자습실 관리는 교사·관리자만 할 수 있습니다(seaton 과 같다).';
  end if;
end $$;


ALTER FUNCTION "mcp_private"."sr_require_teacher"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sr_resolve_student"("p_code" "text") RETURNS TABLE("profile_id" "uuid", "grade" integer, "class" integer, "number" integer, "name" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare v_g integer; v_c integer; v_n integer; v_cnt integer;
begin
  if p_code is null or btrim(p_code) !~ '^[1-3]-[0-9]{1,2}-[0-9]{1,2}$' then
    raise exception using errcode = '22023', message = 'student 는 학년-반-번호입니다(예: 2-3-15).';
  end if;
  v_g := split_part(btrim(p_code), '-', 1)::int; v_c := split_part(btrim(p_code), '-', 2)::int; v_n := split_part(btrim(p_code), '-', 3)::int;
  select count(*) into v_cnt from resource r
   where r.type = 'student' and coalesce(r.status, 'active') = 'active'
     and (r.meta->>'grade')::int = v_g and (r.meta->>'class')::int = v_c and (r.meta->>'number')::int = v_n;
  if v_cnt = 0 then raise exception using errcode = 'P0002', message = format('%s 학생이 재학생 명단에 없습니다.', p_code); end if;
  if v_cnt > 1 then raise exception using errcode = '22023', message = format('%s 에 해당하는 학생이 여럿입니다 — seaton 에서 처리해 주세요.', p_code); end if;
  return query
    select p.id, v_g, v_c, v_n, r.name
      from resource r join profiles p on p.email = (r.meta->>'id') || '@myschool.hs.kr'
     where r.type = 'student' and coalesce(r.status, 'active') = 'active'
       and (r.meta->>'grade')::int = v_g and (r.meta->>'class')::int = v_c and (r.meta->>'number')::int = v_n;
  if not found then
    raise exception using errcode = 'P0002', message = format('%s 학생은 아직 seaton 에 로그인한 적이 없어 예약을 만들 수 없습니다.', p_code);
  end if;
end $_$;


ALTER FUNCTION "mcp_private"."sr_resolve_student"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sr_room_out"("r" "public"."study_rooms", "p_full" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with now_kst as (select (now() at time zone 'Asia/Seoul') as t)
  select jsonb_strip_nulls(jsonb_build_object(
    'room_id', r.id, 'name', r.name, 'active', r.is_active,
    'grades', to_jsonb(coalesce(r.grades, array[r.grade])),
    'seats', r.total_seats,
    'mode', case r.reservation_mode when 'FIXED' then '기간 신청(FIXED)' else '주간 신청(WEEKLY)' end,
    'operating_period', case when r.fixed_start_date is not null or r.fixed_end_date is not null
                             then jsonb_build_object('start', r.fixed_start_date, 'end', r.fixed_end_date) end,
    'operating_days', (select jsonb_agg(d order by d) from unnest(r.operating_days) d),
    'operating_days_label', (select string_agg((array['일','월','화','수','목','금','토'])[d + 1], '·' order by (d + 6) % 7) from unnest(r.operating_days) d),
    'periods', case when r.use_periods and jsonb_array_length(coalesce(r.operating_periods, '[]'::jsonb)) > 0
                    then r.operating_periods else '[{"id": 0, "name": "종일"}]'::jsonb end,
    'period_booking', case when r.use_periods then case r.period_booking_mode when 'INDIVIDUAL' then '교시마다 따로' else '모든 교시 한꺼번에' end end,
    'booking_windows', case when r.reservation_mode = 'FIXED' then
        (select jsonb_agg(w || jsonb_build_object('status',
                  case when (select t from now_kst) < (w->>'start')::timestamp then '예정'
                       when (select t from now_kst) <= (w->>'end')::timestamp then '접수 중' else '끝' end) order by w->>'start')
           from jsonb_array_elements(coalesce(r.booking_windows, '[]'::jsonb)) w
          where coalesce(w->>'start', '') <> '' and coalesce(w->>'end', '') <> '') end,
    'allow_duplicate', r.allow_duplicate_reservation,
    'sungong', case when r.is_sungong then true end,
    'rules', case when p_full then nullif(r.rules, '') else left(nullif(r.rules, ''), 120) end));
$$;


ALTER FUNCTION "mcp_private"."sr_room_out"("r" "public"."study_rooms", "p_full" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sr_seat_ok"("p_layout" "jsonb", "p_seat" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select p_seat ~ '^[A-Z][0-9]{1,2}$'
     and not coalesce(p_layout->'emptySeats' ? p_seat, false)
     and not coalesce(p_layout->'unavailableSeats' ? p_seat, false)
     and exists (select 1 from jsonb_array_elements(coalesce(p_layout->'sections', '[]'::jsonb)) s
                  where (ascii(left(p_seat, 1)) - 65) between (s->>'startRow')::int and (s->>'startRow')::int + (s->>'rows')::int - 1
                    and (substring(p_seat from 2)::int - 1) between (s->>'startCol')::int and (s->>'startCol')::int + (s->>'columns')::int - 1);
$_$;


ALTER FUNCTION "mcp_private"."sr_seat_ok"("p_layout" "jsonb", "p_seat" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sr_student"("p_student" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select jsonb_build_object(
        'student', format('%s-%s-%s', r.meta->>'grade', r.meta->>'class', r.meta->>'number'),
        'name', r.name)
       from profiles p join resource r on r.type = 'student' and r.meta->>'id' = split_part(p.email, '@', 1)
      where p.id = p_student limit 1),
    (select jsonb_build_object('student', null, 'name', coalesce(p.name, '(명단에 없음)')) from profiles p where p.id = p_student));
$$;


ALTER FUNCTION "mcp_private"."sr_student"("p_student" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sr_student_class"("p_student" "uuid") RETURNS TABLE("grade" integer, "class" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select (r.meta->>'grade')::int, (r.meta->>'class')::int
    from profiles p join resource r on r.type = 'student' and r.meta->>'id' = split_part(p.email, '@', 1)
   where p.id = p_student limit 1;
$$;


ALTER FUNCTION "mcp_private"."sr_student_class"("p_student" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sr_windows"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare w jsonb; i integer := 0; v_out jsonb := '[]'::jsonb; v_s text; v_e text; v_label text;
begin
  if p is null then return null; end if;
  if jsonb_typeof(p) <> 'array' then raise exception using errcode = '22023', message = 'booking_windows 는 [{label, start, end}] 배열입니다.'; end if;
  if jsonb_array_length(p) > 10 then raise exception using errcode = '22023', message = '신청 기간은 10개까지입니다.'; end if;
  for w in select * from jsonb_array_elements(p) loop
    i := i + 1;
    v_s := mcp_private.sr_local_ts(w->>'start', format('booking_windows[%s].start', i));
    v_e := mcp_private.sr_local_ts(w->>'end', format('booking_windows[%s].end', i));
    if v_s::timestamp >= v_e::timestamp then
      raise exception using errcode = '22023', message = format('신청 기간 %s 의 시작이 끝보다 늦습니다(%s ~ %s).', i, v_s, v_e);
    end if;
    v_label := nullif(btrim(coalesce(w->>'label', '')), '');
    if char_length(coalesce(v_label, '')) > 30 then raise exception using errcode = '22023', message = '신청 기간 이름은 30자까지입니다.'; end if;
    v_out := v_out || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('id', i, 'label', coalesce(v_label, i || '차'), 'start', v_s, 'end', v_e)));
  end loop;
  return v_out;
end $$;


ALTER FUNCTION "mcp_private"."sr_windows"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."student_label"("p_code" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select format('%s-%s-%s', r.meta->>'grade', r.meta->>'class', r.meta->>'number')
     from resource r where r.type = 'student' and r.meta->>'id' = p_code
     order by (coalesce(r.status, 'active') = 'active') desc limit 1),
    '(학반 모름)');
$$;


ALTER FUNCTION "mcp_private"."student_label"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sv_pool"("p_grade" integer, "p_ay" integer) RETURNS TABLE("resource_id" "uuid", "name" "text", "grades" integer[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  with g as (select x as grade from unnest(case when p_grade = 0 then array[1, 2, 3] else array[p_grade] end) x),
  m as (
    select g.grade, dm.resource_id from g
    join department d on d.name = g.grade || '학년부'
    join department_member dm on dm.department_id = d.id and dm.academic_year = p_ay
    union
    select g.grade, a.resource_id from g
    join resource_tags t on btrim(t.name) ~ ('^' || g.grade || '학년\s*(부장|[0-9]+반)$')
    join resource_tag_assignments a on a.tag_id = t.id
  )
  select r.id, r.name, array_agg(distinct m.grade order by m.grade)
  from m join resource r on r.id = m.resource_id
  where r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active'
  group by r.id, r.name;
$_$;


ALTER FUNCTION "mcp_private"."sv_pool"("p_grade" integer, "p_ay" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sv_require_grade"("p_me" "uuid", "p_grade" integer) RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare v_grades integer[];
begin
  if p_grade is null or p_grade not in (0, 1, 2, 3) then
    raise exception using errcode = '22023', message = 'grade 는 1·2·3 또는 0(전 학년 아침)입니다.';
  end if;
  if exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'admin') then return; end if;
  select coalesce(array_agg(distinct (regexp_match(btrim(t.name), '^([0-9]+)학년\s*(부장|[0-9]+반)$'))[1]::int), '{}') into v_grades
  from resource_tag_assignments a join resource_tags t on t.id = a.tag_id
  where a.resource_id = p_me and btrim(t.name) ~ '^[0-9]+학년\s*(부장|[0-9]+반)$';
  if (p_grade = 0 and cardinality(v_grades) = 0) or (p_grade <> 0 and not (p_grade = any(v_grades))) then
    raise exception using errcode = '42501',
      message = format('%s 자습 감독은 그 학년 학년부장·담임 태그가 있어야 배정할 수 있습니다(지금 = %s).',
                       case p_grade when 0 then '전 학년 아침' else p_grade || '학년' end,
                       coalesce(nullif(array_to_string(v_grades, '·'), ''), '없음'));
  end if;
end;
$_$;


