    "owner_name" "text",
    "target_resource_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "candidate_dates" "date"[] DEFAULT '{}'::"date"[] NOT NULL,
    "allow_custom_dates" boolean DEFAULT true NOT NULL,
    "due_date" "date",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "schedule_survey_answerable" CHECK (("allow_custom_dates" OR ("cardinality"("candidate_dates") > 0))),
    CONSTRAINT "schedule_survey_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'closed'::"text"]))),
    CONSTRAINT "schedule_survey_title_check" CHECK (("length"("btrim"("title")) > 0))
);


