CREATE OR REPLACE FUNCTION "mcp_private"."sw_notify_requested"("p" "public"."class_swap") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  insert into notification_events (type, title, message, resource_id, priority, meta, is_read)
  values ('class_swap_requested', '수업 교체 요청',
    format(E'%s 선생님이 수업 교체를 요청했습니다.\n\n📅 교체 날짜: %s\n\n내 수업: %s (%s%s교시)\n↕ 교체\n요청 수업: %s (%s%s교시)',
           p.meta->>'requester_name', mcp_private.ko_date(p.requester_swap_date),
           coalesce(p.meta->>'approver_section_name', ''), mcp_private.dow_name(p.approver_original_weekday), p.approver_original_period,
           coalesce(p.meta->>'requester_section_name', ''), mcp_private.dow_name(p.requester_original_weekday), p.requester_original_period),
    p.approver_resource_id, 'high',
    jsonb_build_object('swap_id', p.id, 'requester_name', p.meta->>'requester_name', 'swap_date', p.requester_swap_date),
    false);
end;
$$;


ALTER FUNCTION "mcp_private"."sw_notify_requested"("p" "public"."class_swap") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."sw_out"("p" "public"."class_swap", "p_me" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'swap_id', p.id,
    'type', case when p.meta->>'type' = 'substitute' then '대체' else '교체' end,
    'role', case when p.requester_resource_id = p_me then '보낸 요청' else '받은 요청' end,
    'status', p.status,
    'status_label', case p.status when 'pending' then '대기' when 'approved' then '승인됨' when 'rejected' then '거절됨' else '취소됨' end,
    'requester', p.meta->>'requester_name',
    'approver', p.meta->>'approver_name',
    'requester_lesson', jsonb_build_object('subject', p.meta->>'requester_section_name', 'date', p.requester_swap_date,
                          'day', mcp_private.dow_name(p.requester_original_weekday), 'period', p.requester_original_period),
    'approver_lesson', case when p.meta->>'type' = 'substitute' then null else jsonb_build_object(
                          'subject', p.meta->>'approver_section_name', 'date', p.approver_swap_date,
                          'day', mcp_private.dow_name(p.approver_original_weekday), 'period', p.approver_original_period) end,
    'meaning', case when p.meta->>'type' = 'substitute'
      then format('%s %s교시 %s 수업을 %s 선생님이 대신 맡는다', p.requester_swap_date, p.requester_original_period,
                  p.meta->>'requester_section_name', p.meta->>'approver_name')
      else format('%s %s교시엔 %s 선생님이 자기 과목을, %s %s교시엔 %s 선생님이 자기 과목을 한다',
                  p.requester_swap_date, p.requester_original_period, p.meta->>'approver_name',
                  p.approver_swap_date, p.approver_original_period, p.meta->>'requester_name') end,
    'reason', nullif(p.meta->>'reason', ''),
    'rejection_reason', nullif(p.meta->>'rejection_reason', ''),
    'absence', case p.meta->>'absence_kind' when 'event' then '출장' when 'personal' then '개인 사정' end,
    'requested_at', p.requested_at, 'responded_at', p.responded_at));
$$;


