CREATE OR REPLACE FUNCTION "mcp_private"."task_lineage"("p_task" "uuid") RETURNS TABLE("task_id" "uuid", "depth" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  with recursive l(task_id, depth, path) as (
    select p_task, 0, array[p_task]
    union all
    select x.parent, l.depth + 1, l.path || x.parent
    from l
    join public.task t on t.id = l.task_id
    cross join lateral (select case when t.meta->'rolledOverFrom'->>'taskId' ~ '^[0-9a-fA-F-]{36}$'
                                    then (t.meta->'rolledOverFrom'->>'taskId')::uuid end as parent) x
    where x.parent is not null and not (x.parent = any (l.path)) and l.depth < 20
  )
  select l.task_id, l.depth from l;
$_$;


ALTER FUNCTION "mcp_private"."task_lineage"("p_task" "uuid") OWNER TO "postgres";


