CREATE OR REPLACE FUNCTION "mcp_private"."timetable_of"("p_resource" "uuid", "p_day" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with t as (select * from mcp_private.current_term()),
  today as (select (now() at time zone 'Asia/Seoul')::date as d),
  slots as (
    select distinct tt.day_of_week, tt.period, tt.subject_name, tt.grade, tt.class_label, tt.override_title
    from t, today, public.teacher_timetable_effective(t.academic_year, t.semester, today.d, today.d + 6, p_resource) tt
    where tt.day_of_week between 1 and 5 and (p_day is null or tt.day_of_week = p_day))
  select jsonb_strip_nulls(jsonb_build_object(
    'academic_year', (select academic_year from t), 'semester', (select semester from t),
    'operational_timetable', (select jsonb_agg(distinct s.override_title) from slots s where s.override_title is not null),
    'slots', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'day', s.day_of_week, 'day_label', mcp_private.day_label(s.day_of_week), 'period', s.period,
        'start', pt->>'start', 'end', pt->>'end', 'subject', s.subject_name,
        'class', case when s.grade is not null and coalesce(s.class_label, '') <> '' then s.grade || '-' || s.class_label else s.class_label end))
        order by s.day_of_week, s.period)
      from slots s left join jsonb_array_elements(mcp_private.period_times()) pt on (pt->>'period')::integer = s.period), '[]'::jsonb),
    'free_periods', (select jsonb_object_agg(mcp_private.day_label(d), coalesce((
        select jsonb_agg(pp order by pp) from generate_series(1, 7) pp
        where not exists (select 1 from slots s where s.day_of_week = d and s.period = pp)), '[]'::jsonb))
      from generate_series(1, 5) d where p_day is null or d = p_day)));
$$;


ALTER FUNCTION "mcp_private"."timetable_of"("p_resource" "uuid", "p_day" integer) OWNER TO "postgres";


