COMMENT ON COLUMN "public"."teacher_timetable"."activity_type" IS 'subject (정규교과) | self_study (자율학습) | autonomy (자율·자치) | club (동아리) | volunteer (봉사) | career (진로)';



CREATE OR REPLACE FUNCTION "mcp_private"."tt_my_lesson"("p_me" "uuid", "p_dow" integer, "p_period" integer) RETURNS "public"."teacher_timetable"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_term record;
  v      public.teacher_timetable;
begin
  select * into v_term from mcp_private.current_term();
  select * into v from teacher_timetable t
  where t.teacher_resource_id = p_me and t.academic_year = v_term.academic_year and t.semester = v_term.semester
    and t.day_of_week = p_dow and t.period = p_period
  order by t.id limit 1;
  if not found then
    raise exception using errcode = 'P0002',
      message = format('%s요일 %s교시에 내 수업이 없습니다(%s학년도 %s학기 시간표).', mcp_private.dow_name(p_dow), p_period,
                       v_term.academic_year, v_term.semester);
  end if;
  return v;
end;
$$;


ALTER FUNCTION "mcp_private"."tt_my_lesson"("p_me" "uuid", "p_dow" integer, "p_period" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."we_actor"("p_work" "uuid", "p_task" "uuid", OUT "actor" "uuid", OUT "role" "text") RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then role := 'system'; return; end if;
  select x into actor from public.current_actor_resource_ids() x limit 1;
  if public.is_admin() then role := 'admin';
  elsif public.can_manage_work_structure(p_work) then role := 'manager';
  elsif p_task is not null and actor is not null and exists (
    select 1 from public.task t, jsonb_array_elements(mcp_private.arr(t.meta->'assignees')) a
    where t.id = p_task and a->>'id' = actor::text) then role := 'assignee';
  else role := 'other';
  end if;
end $$;


ALTER FUNCTION "mcp_private"."we_actor"("p_work" "uuid", "p_task" "uuid", OUT "actor" "uuid", OUT "role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."we_assignees"("p_meta" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select coalesce(jsonb_object_agg(a->>'id', coalesce(a->>'name', '')), '{}'::jsonb)
  from jsonb_array_elements(case when jsonb_typeof(p_meta->'assignees') = 'array' then p_meta->'assignees' else '[]'::jsonb end) a
  where coalesce(a->>'id', '') <> '';
$$;


ALTER FUNCTION "mcp_private"."we_assignees"("p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."we_deadlines"("p_meta" "jsonb", "p_due" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when jsonb_typeof(p_meta->'deadlines') = 'array' and jsonb_array_length(p_meta->'deadlines') > 1 then p_meta->'deadlines'
    when p_due is not null then jsonb_build_array(to_char(p_due at time zone 'Asia/Seoul', 'YYYY-MM-DD'))
    else '[]'::jsonb end;
$$;


ALTER FUNCTION "mcp_private"."we_deadlines"("p_meta" "jsonb", "p_due" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."we_insert"("p_work" "uuid", "p_task" "uuid", "p_action" "uuid", "p_kind" "text", "p_detail" "jsonb", "p_merge" interval DEFAULT NULL::interval) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  a record; v_id bigint; v_old jsonb;
  v_via text := case when coalesce(auth.jwt()->>'client_id', '') <> '' then 'mcp' when auth.uid() is null then 'system' else 'web' end;
begin
  if p_work is null or not exists (select 1 from public.work where id = p_work) then return null; end if;
  select * into a from mcp_private.we_actor(p_work, p_task);
  if p_merge is not null then
    select id, detail into v_id, v_old from public.work_event
    where work_id = p_work and kind = p_kind and action_id is not distinct from p_action and task_id is not distinct from p_task
      and actor_resource_id is not distinct from a.actor and via = v_via and at > now() - p_merge
    order by id desc limit 1;
    if v_id is not null then
      update public.work_event
         set detail = v_old || p_detail || case when jsonb_typeof(v_old->'changed') = 'array' and jsonb_typeof(p_detail->'changed') = 'array'
                       then jsonb_build_object('changed', (select jsonb_agg(distinct x) from (
                              select jsonb_array_elements_text(v_old->'changed') x union select jsonb_array_elements_text(p_detail->'changed')) u))
                       else '{}'::jsonb end
                     || jsonb_build_object('times', coalesce((v_old->>'times')::int, 1) + 1),
             at = now()
       where id = v_id;
      return v_id;
    end if;
  end if;
  insert into public.work_event (work_id, task_id, action_id, kind, actor_resource_id, actor_role, via, detail)
  values (p_work, p_task, p_action, p_kind, a.actor, a.role, v_via, coalesce(p_detail, '{}'::jsonb))
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "mcp_private"."we_insert"("p_work" "uuid", "p_task" "uuid", "p_action" "uuid", "p_kind" "text", "p_detail" "jsonb", "p_merge" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."week_range"("p_from" "date", "p_to" "date", OUT "d_from" "date", OUT "d_to" "date") RETURNS "record"
    LANGUAGE "plpgsql" STABLE
    AS $$
declare v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  d_from := coalesce(p_from, date_trunc('week', v_today::timestamp)::date);
  d_to := coalesce(p_to, d_from + 6);
  if d_to < d_from then raise exception using errcode = '22023', message = 'to 가 from 보다 앞입니다.'; end if;
  if d_to - d_from > 61 then raise exception using errcode = '22023', message = '한 번에 62일까지 읽습니다.'; end if;
end;
$$;


ALTER FUNCTION "mcp_private"."week_range"("p_from" "date", "p_to" "date", OUT "d_from" "date", OUT "d_to" "date") OWNER TO "postgres";


