ALTER TABLE "public"."task_workflow" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_workflow" IS 'User-owned visual maps connecting school events and tasks.';



COMMENT ON COLUMN "public"."task_workflow"."department_id" IS 'Optional department used to group and filter task workflows.';



CREATE OR REPLACE FUNCTION "mcp_private"."wf_editable"("p_workflow" "uuid") RETURNS "public"."task_workflow"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare f public.task_workflow;
begin
  select * into f from task_workflow where id = p_workflow;
  if f.id is null then raise exception using errcode = 'P0002', message = '그 업무 흐름을 찾지 못했습니다 (list_workflows).'; end if;
  if f.owner_id <> auth.uid() and not public.is_admin() then
    raise exception using errcode = '42501', message = format('«%s» 는 내 흐름이 아니라 바꿀 수 없습니다(흐름은 만든 사람이 고친다).', f.name);
  end if;
  return f;
end $$;


ALTER FUNCTION "mcp_private"."wf_editable"("p_workflow" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wf_node"("p_workflow" "uuid", "p_ref" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v uuid;
begin
  select n.id into v from task_workflow_node n
  where n.workflow_id = p_workflow and (n.id = p_ref or n.event_id = p_ref or n.task_id = p_ref or n.action_id = p_ref) limit 1;
  if v is null then raise exception using errcode = 'P0002', message = '그 노드가 이 흐름에 없습니다 — place_work 로 업무를 먼저 올리세요.'; end if;
  return v;
end $$;


ALTER FUNCTION "mcp_private"."wf_node"("p_workflow" "uuid", "p_ref" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wf_out"("p_workflow" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'workflow_id', f.id, 'name', f.name, 'mine', f.owner_id = auth.uid(),
    'nodes', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'node_id', n.id, 'kind', case n.node_kind when 'event' then 'work' else n.node_kind end, 'label', n.label,
        'ref_id', coalesce(n.event_id, n.task_id, n.action_id))) order by n.position_y, n.position_x)
      from task_workflow_node n where n.workflow_id = f.id), '[]'::jsonb),
    'edges', coalesce((select jsonb_agg(jsonb_build_object('from', s.label, 'to', t.label, 'relation', e.relation_type,
        'from_ref', coalesce(s.event_id, s.task_id, s.action_id, s.id), 'to_ref', coalesce(t.event_id, t.task_id, t.action_id, t.id)))
      from task_workflow_edge e join task_workflow_node s on s.id = e.source_node_id join task_workflow_node t on t.id = e.target_node_id
      where e.workflow_id = f.id), '[]'::jsonb))
  from task_workflow f where f.id = p_workflow;
$$;


ALTER FUNCTION "mcp_private"."wf_out"("p_workflow" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_action_def"("p_type" "text", OUT "title" "text", OUT "description" "text", OUT "exec_mode" "text", OUT "verify_mode" "text", OUT "multiple" boolean, OUT "kind" "text") RETURNS "record"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  kind := 'embed'; exec_mode := 'assisted'; verify_mode := 'human_review'; multiple := false;
  case p_type
    when 'link.volunteer_issue' then title := '봉사활동 발급'; description := '봉사활동 계획·확인서 발급 모달을 열어 발급번호를 채번하고 대장에 기록합니다.';
    when 'link.gajeong_issue' then title := '가정통신문 발급'; description := '가정통신문 발급 모달을 열어 발급번호를 채번하고 대장에 기록합니다.';
    when 'link.schedule_add' then title := '일정 추가'; description := '일정 등록 모달을 열어 학사 일정·행사·연수 등을 스케줄에 추가합니다.';
    when 'link.timetable_change' then title := '수업 교체'; description := '내 시간표에서 교체할 수업을 골라 교체 요청 모달을 엽니다.';
    when 'link.notice_write' then title := '공지사항 작성'; description := '공지 작성 모달을 열어 부서 공지사항을 작성·게시합니다.';
    when 'link.training_certificate' then title := '연수 이수증 등록'; description := '이수증 등록 모달을 열어 연수 이수 내역과 파일을 등록합니다.';
    when 'link.document_upload' then title := '문서 업로드'; description := '문서함 업로드 모달을 열어 파일을 등록합니다(Drive 연동 포함).';
    when 'link.work_create' then title := '할 일 생성'; description := '업무 생성 모달을 열어 프로젝트와 하위 할 일을 만듭니다.';
    when 'neis.screen' then kind := 'neis'; title := 'NEIS 업무 화면'; exec_mode := 'manual'; multiple := true;
      description := '나이스에서 처리할 화면(최대 10개)과 처리 안내를 담당자에게 보여 줍니다. 처리는 담당자가 나이스에서 직접 합니다.';
    when 'external.screen' then kind := 'external'; title := '외부 시스템에서 처리'; exec_mode := 'manual'; multiple := true;
      description := 'K-에듀파인·리로스쿨·업무포털처럼 나이스 밖 시스템에서 처리하는 일입니다. 어디서 무엇을 하는지 적어 두고 완료를 기록합니다.';
    when 'document.spec_fill' then kind := 'docgen'; title := 'HWPX 스펙 기반 문서 생성';
      description := '양식의 작성 지점을 스펙으로 확정하고, AI 계획 검토를 거쳐 문서를 완성·검증합니다.';
    when 'collect.input' then kind := 'collect'; title := '입력 받기'; exec_mode := 'manual'; multiple := true;
      description := '대상(예: 1학년 수학 교사 전원)에게서 과목·구분별 값을 받아 표로 모읍니다.';
    when 'submit.file' then kind := 'submit'; title := '파일 제출 받기'; exec_mode := 'manual'; multiple := true;
      description := '대상이 파일을 올립니다(구글 공용 드라이브). 담당자는 내면 완료됩니다.';
    when 'submit.document' then kind := 'submit'; title := '양식 문서 제출 받기'; exec_mode := 'manual'; multiple := true;
      description := '지정한 양식의 빈칸을 대상이 채워 냅니다. 값으로 모여 표로 보고 언제든 문서로 다시 엽니다.';
    when 'submit.physical' then kind := 'submit'; title := '실물 제출 받기'; exec_mode := 'manual'; multiple := true;
      description := '대상이 서류를 직접 냅니다. 책임자가 [받음]을 체크하면 완료됩니다. 제출 양식을 첨부할 수 있습니다.';
    when 'message.send' then kind := 'message'; title := '메시지 보내기'; exec_mode := 'manual'; multiple := true;
      description := '대상(학년·과목·담임·부서·업무분장·동아리…)에게 알림으로 메시지를 보냅니다. AI 초안·쿨메신저 안내 포함.';
    else kind := null;
  end case;
end $$;


ALTER FUNCTION "mcp_private"."wk_action_def"("p_type" "text", OUT "title" "text", OUT "description" "text", OUT "exec_mode" "text", OUT "verify_mode" "text", OUT "multiple" boolean, OUT "kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_action_progress"("p_action" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when exists (select 1 from task_action_run where action_id = p_action) then '실행 기록이 있습니다'
    when exists (select 1 from collect_request where action_id = p_action) then '이미 보낸 요청이 있습니다'
    when exists (select 1 from task_message_send where action_id = p_action) then '이미 보낸 메시지가 있습니다'
    when exists (select 1 from task_action_document where action_id = p_action) then '저장된 완성 문서가 있습니다'
  end;
$$;


ALTER FUNCTION "mcp_private"."wk_action_progress"("p_action" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_audience"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare v_out jsonb := jsonb_build_object('include', '[]'::jsonb, 'exclude', '[]'::jsonb); side text; c jsonb; v_t text; v_ids jsonb; v_names text[]; v_list jsonb; k text;
begin
  if p is null or jsonb_typeof(p) = 'null' then
    return jsonb_build_object('include', jsonb_build_array(jsonb_build_object('type', 'task_assignees')), 'exclude', '[]'::jsonb);
  end if;
  if jsonb_typeof(p) <> 'object' then raise exception using errcode = '22023', message = 'audience 는 {include:[조건], exclude:[조건]} 입니다.'; end if;
  foreach side in array array['include', 'exclude'] loop
    for c in select e from jsonb_array_elements(mcp_private.arr(p->side)) e loop
      if jsonb_typeof(c) <> 'object' then raise exception using errcode = '22023', message = '대상 조건은 {type: …} 객체입니다.'; end if;
      v_t := c->>'type';
      if v_t = 'people' then
        v_names := array(select jsonb_array_elements_text(mcp_private.arr(c->'names')));
        c := jsonb_build_object('type', 'people', 'ids', (select coalesce(jsonb_agg(x->'id'), '[]') from jsonb_array_elements(mcp_private.wk_people(v_names, '대상')) x));
      elsif v_t = 'department' then
        v_names := array(select jsonb_array_elements_text(mcp_private.arr(c->'names')));
        select jsonb_agg(d.id) into v_ids from department d where d.is_active and d.name = any(v_names);
        if coalesce(jsonb_array_length(v_ids), 0) <> cardinality(v_names) or cardinality(v_names) = 0 then
          raise exception using errcode = '22023', message = format('부서 이름을 찾지 못했습니다: %s — read_data departments 로 확인하세요.', array_to_string(v_names, ', '));
        end if;
        c := jsonb_build_object('type', 'department', 'ids', v_ids);
      elsif v_t = 'tag' then
        v_names := array(select jsonb_array_elements_text(mcp_private.arr(c->'names')));
        select jsonb_agg(t.id) into v_ids from resource_tags t where t.name = any(v_names);
        if coalesce(jsonb_array_length(v_ids), 0) <> cardinality(v_names) or cardinality(v_names) = 0 then
          raise exception using errcode = '22023', message = format('태그 이름을 찾지 못했습니다: %s', array_to_string(v_names, ', '));
        end if;
        c := jsonb_build_object('type', 'tag', 'ids', v_ids);
      elsif v_t = 'all_faculty' then
        select coalesce(jsonb_agg(distinct x), '[]') into v_list from jsonb_array_elements_text(mcp_private.arr(c->'types')) x where x in ('teacher', 'staff');
        c := jsonb_build_object('type', 'all_faculty', 'types', case when jsonb_array_length(v_list) = 0 then '["teacher"]'::jsonb else v_list end);
      elsif v_t in ('seat', 'club') then
        select coalesce(jsonb_agg(btrim(x)), '[]') into v_list from jsonb_array_elements_text(mcp_private.arr(c->'names')) x where btrim(x) <> '';
        if v_t = 'seat' and jsonb_array_length(v_list) = 0 then
          raise exception using errcode = '22023', message = '업무분장 자리 조건(seat)은 names 가 필요합니다 — read_data duty_seats 로 자리 이름을 확인하세요.';
        end if;
        c := jsonb_build_object('type', v_t, 'names', v_list);
      elsif v_t = 'position' then
        select coalesce(jsonb_agg(distinct x), '[]') into v_list from jsonb_array_elements_text(mcp_private.arr(c->'kinds')) x where x in ('head', 'admin');
        if jsonb_array_length(v_list) = 0 then
          raise exception using errcode = '22023', message = '직위 조건(position)은 kinds 가 필요합니다 — head(부장)·admin(교장·교감).';
        end if;
        c := jsonb_build_object('type', 'position', 'kinds', v_list);
      elsif v_t in ('homeroom', 'grade_head', 'teaching') then
        v_list := jsonb_build_object('type', v_t);
        if jsonb_typeof(c->'grades') = 'array' then
          v_list := v_list || jsonb_build_object('grades', (select coalesce(jsonb_agg(distinct x::int), '[]') from jsonb_array_elements_text(c->'grades') x where x ~ '^[1-3]$'));
        end if;
        if v_t = 'teaching' then
          foreach k in array array['subjectGroups', 'subjectClusters', 'subjects'] loop
            if jsonb_typeof(c->k) = 'array' then
              v_list := v_list || jsonb_build_object(k, (select coalesce(jsonb_agg(x), '[]') from jsonb_array_elements_text(c->k) x where btrim(x) <> ''));
            end if;
          end loop;
        end if;
        c := v_list;
      elsif v_t = 'task_assignees' then
        c := jsonb_build_object('type', 'task_assignees');
      else
        raise exception using errcode = '22023', message = format('대상 조건 %s 을(를) 모릅니다 — task_assignees·people(names)·department(names)·tag(names)·all_faculty(types?)·teaching·homeroom·grade_head·seat(names)·position(kinds)·club(names).', coalesce(v_t, '(없음)'));
      end if;
      v_out := jsonb_set(v_out, array[side], (v_out->side) || jsonb_build_array(c));
    end loop;
  end loop;
  if jsonb_array_length(v_out->'include') = 0 then
    raise exception using errcode = '22023', message = '대상(include)이 비었습니다. 비우려면 audience 를 빼면 «이 할 일의 담당자»가 된다.';
  end if;
  return v_out;
end $_$;


ALTER FUNCTION "mcp_private"."wk_audience"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_due"("p_dates" "text"[], OUT "due" timestamp with time zone, OUT "deadlines" "jsonb") RETURNS "record"
    LANGUAGE "plpgsql" STABLE
    AS $_$
declare v_list text[]; v_today text := to_char(mcp_private.kst_today(), 'YYYY-MM-DD'); d text;
begin
  foreach d in array coalesce(p_dates, '{}') loop
    if btrim(d) !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception using errcode = '22023', message = format('마감일 %s 은(는) YYYY-MM-DD 입니다.', d);
    end if;
    perform btrim(d)::date;
  end loop;
  select array_agg(distinct btrim(x) order by btrim(x)) into v_list from unnest(coalesce(p_dates, '{}')) x;
  if v_list is null then due := null; deadlines := null; return; end if;
  if array_length(v_list, 1) > 30 then raise exception using errcode = '22023', message = '마감일은 30개까지입니다.'; end if;
  due := (coalesce((select x from unnest(v_list) x where x >= v_today order by x limit 1), v_list[array_length(v_list, 1)])::date)::timestamp at time zone 'Asia/Seoul';
  deadlines := case when array_length(v_list, 1) > 1 then to_jsonb(v_list) end;
end $_$;


ALTER FUNCTION "mcp_private"."wk_due"("p_dates" "text"[], OUT "due" timestamp with time zone, OUT "deadlines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_generation_template"("p_generation" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v jsonb;
begin
  select a.config->'defaultTemplate' into v from task_action a
  where a.id = p_generation and a.action_type = 'document.spec_fill' and a.archived_at is null;
  if v is null or jsonb_typeof(v) <> 'object' or coalesce(v->>'id', '') = '' then
    raise exception using errcode = 'P0002', message = '그 문서 생성 방식을 찾지 못했거나 기본 양식이 없습니다 (list_document_generations 의 action_id).';
  end if;
  return jsonb_strip_nulls(jsonb_build_object('id', v->>'id', 'name', v->>'name',
    'familyId', coalesce(v->>'familyId', (select t.family_id::text from task_action_document_template t where t.id = (v->>'id')::uuid))));
end $$;


ALTER FUNCTION "mcp_private"."wk_generation_template"("p_generation" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_knowledge"("p_work" "uuid", "p_task" "uuid" DEFAULT NULL::"uuid", "p_kind" "text" DEFAULT NULL::"text", "p_include_archived" boolean DEFAULT false, "p_limit" integer DEFAULT 60, "p_action" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with lin as (select work_id, depth from mcp_private.work_lineage(p_work)),
       cur as (select t.id, t.title, tl.task_id as anc from public.task t cross join lateral mcp_private.task_lineage(t.id) tl
               where t.event_id = p_work),
       cur_a as (select a.id, a.title, a.action_type, a.task_id, al.action_id as anc
                 from public.task_action a join public.task t on t.id = a.task_id
                 cross join lateral mcp_private.action_lineage(a.id) al
                 where t.event_id = p_work and a.archived_at is null),
       want_task as (select coalesce(p_task, (select task_id from public.task_action where id = p_action)) as id)
  select coalesce(jsonb_agg(item order by ord1, ord2 desc), '[]'::jsonb) from (
    select jsonb_strip_nulls(jsonb_build_object(
      'knowledge_id', k.id, 'kind', k.kind, 'title', k.title, 'body', k.body, 'basis', k.basis, 'suggestions', k.suggestions,
      'action_type', k.action_type, 'status', case when k.status = 'archived' then 'archived' end,
      'archived_reason', k.archived_reason,
      'from', case when lin.depth = 0 then 'this_work' else format('%s년 전 업무', lin.depth) end,
      'source_work', case when lin.depth > 0 then w.name end, 'source_year', w.meta->'year',
      'task_now', (select jsonb_build_object('task_id', c.id, 'title', c.title) from cur c where c.anc = k.task_id limit 1),
      'task_then', case when k.task_id is not null and lin.depth > 0 then (select t.title from public.task t where t.id = k.task_id) end,
      'action_now', case when k.action_id is not null then
                      (select jsonb_build_object('action_id', ca.id, 'title', ca.title, 'type', ca.action_type) from cur_a ca where ca.anc = k.action_id limit 1) end,
      'action_then', case when k.action_id is not null and lin.depth > 0 then (select x.title from public.task_action x where x.id = k.action_id) end,
      'by', k.author_role, 'at', k.created_at,
      'decision', (select d.detail->>'decision' from public.work_event d
                   where d.work_id = p_work and d.kind = 'insight.decided' and d.detail->>'insight_id' = k.id::text
                   order by d.at desc limit 1))) as item,
      lin.depth as ord1, k.created_at as ord2
    from public.work_knowledge k
    join lin on lin.work_id = k.work_id
    join public.work w on w.id = k.work_id
    where (p_include_archived or k.status = 'active')
      and (p_kind is null or k.kind = p_kind)
      and ((select id from want_task) is null or k.task_id is null
           or k.task_id in (select anc from cur where id = (select id from want_task)))
      and (p_action is null or k.action_id is null or k.action_id in (select anc from cur_a where id = p_action))
    order by lin.depth, k.created_at desc
    limit greatest(1, least(coalesce(p_limit, 60), 200))
  ) x;
$$;


ALTER FUNCTION "mcp_private"."wk_knowledge"("p_work" "uuid", "p_task" "uuid", "p_kind" "text", "p_include_archived" boolean, "p_limit" integer, "p_action" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_managed_work"("p_work" "uuid") RETURNS "public"."work"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare w public.work;
begin
  select * into w from work where id = p_work;
  if w.id is null then raise exception using errcode = 'P0002', message = '그 업무를 찾지 못했습니다.'; end if;
  if not public.can_manage_work_structure(p_work) then
    raise exception using errcode = '42501', message = format('«%s» 의 책임자가 아닙니다 — 할 일·작업은 그 업무의 책임자만 바꿉니다.', w.name);
  end if;
  return w;
end $$;


ALTER FUNCTION "mcp_private"."wk_managed_work"("p_work" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_people"("p_names" "text"[], "p_what" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare v_out jsonb := '[]'; v_bad text[] := '{}'; n text; v_ids uuid[];
begin
  foreach n in array coalesce(p_names, '{}') loop
    n := regexp_replace(btrim(n), '\s*(선생님|교사|님)$', '');
    continue when n = '';
    select array_agg(r.id) into v_ids from resource r where r.type in ('teacher', 'staff') and r.status = 'active' and r.name = n;
    if v_ids is null then v_bad := v_bad || format('%s(없음)', n);
    elsif array_length(v_ids, 1) > 1 then v_bad := v_bad || format('%s(%s명)', n, array_length(v_ids, 1));
    elsif not v_out @> jsonb_build_array(jsonb_build_object('id', v_ids[1])) then
      v_out := v_out || jsonb_build_array(jsonb_build_object('id', v_ids[1], 'name', n));
    end if;
  end loop;
  if cardinality(v_bad) > 0 then
    raise exception using errcode = '22023', message = format('%s 이름을 명단에서 정확히 찾지 못했습니다: %s — read_data staff 또는 find_staff 로 확인하세요.', p_what, array_to_string(v_bad, ', '));
  end if;
  return v_out;
end $_$;


ALTER FUNCTION "mcp_private"."wk_people"("p_names" "text"[], "p_what" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_renumber"("p_work" "uuid") RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  update task t set order_index = x.n
  from (select id, row_number() over (order by order_index, created_at, id) as n
        from task where event_id = p_work and type = 'procedural') x
  where t.id = x.id and t.order_index is distinct from x.n;
$$;


