CREATE OR REPLACE FUNCTION "mcp_private"."wk_request_config"("p_type" "text", "p_title" "text", "s" "jsonb", "p_old" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare c jsonb := coalesce(p_old, '{}'); f jsonb; i int; v_fields jsonb := '[]'; v_dims jsonb := '[]';
begin
  if s is not null and jsonb_typeof(s) <> 'object' then raise exception using errcode = '22023', message = 'settings 는 객체입니다.'; end if;
  s := coalesce(s, '{}');
  if p_title is not null or not c ? 'title' then c := c || jsonb_build_object('title', coalesce(p_title, s->>'title', (mcp_private.wk_action_def(p_type)).title)); end if;
  if s ? 'audience' or not c ? 'audience' then c := c || jsonb_build_object('audience', mcp_private.wk_audience(s->'audience')); end if;
  if s ? 'guide' then c := c || jsonb_build_object('guide', left(coalesce(s->>'guide', ''), 4000)); elsif not c ? 'guide' and p_type <> 'message.send' then c := c || '{"guide":""}'; end if;
  if p_type <> 'message.send' and (s ? 'due_date' or not c ? 'dueDate') then
    if coalesce(s->>'due_date', '') <> '' and s->>'due_date' !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception using errcode = '22023', message = 'due_date 는 YYYY-MM-DD 입니다(비우면 할 일 마감).';
    end if;
    c := c || jsonb_build_object('dueDate', case when p_type = 'collect.input' then to_jsonb(nullif(s->>'due_date', '')) else to_jsonb(coalesce(s->>'due_date', '')) end);
  end if;

  if p_type = 'message.send' then
    if s ? 'body' or not c ? 'body' then
      if length(coalesce(s->>'body', '')) > 4000 then raise exception using errcode = '22023', message = '메시지 본문은 4000자까지입니다.'; end if;
      c := c || jsonb_build_object('body', coalesce(s->>'body', ''));
    end if;
  elsif p_type like 'submit.%' then
    if s ? 'template_generation_id' then
      if p_type <> 'submit.document' then raise exception using errcode = '22023', message = '양식은 양식 문서 제출(submit.document)에만 붙인다.'; end if;
      c := c || jsonb_build_object('template', mcp_private.wk_generation_template((s->>'template_generation_id')::uuid));
    elsif not c ? 'template' then c := c || '{"template":null}';
    end if;
    if not c ? 'forms' then c := c || '{"forms":[]}'; end if;
  elsif p_type = 'collect.input' then
    if s ? 'axis' or not c ? 'axis' then
      if coalesce(s->>'axis', 'person') not in ('person', 'subject', 'class', 'club', 'club_member') then raise exception using errcode = '22023', message = 'axis 는 person(사람마다)·subject(담당 학년×과목)·class(담당 학급)·club(지도 동아리마다)·club_member(지도 동아리 부원마다)입니다.'; end if;
      c := c || jsonb_build_object('axis', coalesce(s->>'axis', 'person'));
    end if;
    if s ? 'answer_mode' or not c ? 'answerMode' then
      if coalesce(s->>'answer_mode', 'each') not in ('each', 'shared') then raise exception using errcode = '22023', message = 'answer_mode 는 each(교사마다)·shared(단위당 한 번)입니다.'; end if;
      c := c || jsonb_build_object('answerMode', coalesce(s->>'answer_mode', 'each'));
    end if;
    if s ? 'visibility' or not c ? 'mode' then
      if coalesce(s->>'visibility', 'private') not in ('private', 'shared') then raise exception using errcode = '22023', message = 'visibility 는 private(요청한 사람만 봄)·shared(대상자 모두 표를 봄)입니다.'; end if;
      c := c || jsonb_build_object('mode', coalesce(s->>'visibility', 'private'));
    end if;
    if s ? 'dimensions' or not c ? 'dimensions' then
      i := 0;
      for f in select e from jsonb_array_elements(mcp_private.arr(s->'dimensions')) e loop
        i := i + 1;
        v_dims := v_dims || jsonb_build_array(jsonb_build_object('key', coalesce(nullif(f->>'key', ''), 'd' || i),
          'label', coalesce(nullif(f->>'label', ''), case when jsonb_typeof(f) = 'string' then f #>> '{}' end, '구분 ' || i)));
      end loop;
      c := c || jsonb_build_object('dimensions', v_dims);
    end if;
    if s ? 'fields' or not c ? 'fields' then
      i := 0;
      for f in select e from jsonb_array_elements(mcp_private.arr(s->'fields')) e loop
        i := i + 1;
        if coalesce(f->>'type', 'text') not in ('yesno', 'select', 'text', 'number', 'date') then
          raise exception using errcode = '22023', message = format('%s번째 항목의 type 은 yesno·select·text·number·date 입니다.', i);
        end if;
        if coalesce(f->>'label', '') = '' then raise exception using errcode = '22023', message = format('%s번째 항목에 label 이 필요합니다.', i); end if;
        v_fields := v_fields || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
          'key', coalesce(nullif(f->>'key', ''), 'f' || i), 'label', f->>'label', 'type', coalesce(f->>'type', 'text'),
          'options', case when f->>'type' = 'select' then mcp_private.arr(f->'options') end,
          'required', coalesce((f->>'required')::boolean, false))));
      end loop;
      if jsonb_array_length(v_fields) = 0 then
        v_fields := '[{"key":"f1","label":"완료 여부","type":"yesno","required":true}]';   -- 웹 DEFAULT_COLLECT_CONFIG
      end if;
      c := c || jsonb_build_object('fields', v_fields);
    end if;
  end if;
  return c;
end $_$;


ALTER FUNCTION "mcp_private"."wk_request_config"("p_type" "text", "p_title" "text", "s" "jsonb", "p_old" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_task"("p_task" "uuid") RETURNS "public"."task"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare t public.task;
begin
  select * into t from task where id = p_task;
  if t.id is null then raise exception using errcode = 'P0002', message = '그 할 일을 찾지 못했습니다.'; end if;
  perform mcp_private.wk_managed_work(t.event_id);
  return t;
end $$;


ALTER FUNCTION "mcp_private"."wk_task"("p_task" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_task_progress"("p_task" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  select coalesce(
    (select '완료한 담당자가 있습니다' from task t where t.id = p_task and (
        t.status = 'completed'
        or exists (select 1 from jsonb_array_elements(mcp_private.arr(t.meta->'assignees')) a where a->>'status' = 'completed')
        or t.meta->'deadlineProgress' @? '$.*.*.status ? (@ == "completed")'
        or t.meta->'unitProgress' @? '$.*.*.status ? (@ == "completed")')),
    (select '제출물이 있습니다' where exists (select 1 from task_submission where task_id = p_task)),
    (select '남긴 산출물 값이 있습니다' where exists (select 1 from task_output_value where task_id = p_task)),
    (select a.title || ' — ' || mcp_private.wk_action_progress(a.id) from task_action a
      where a.task_id = p_task and mcp_private.wk_action_progress(a.id) is not null limit 1));
$_$;


ALTER FUNCTION "mcp_private"."wk_task_progress"("p_task" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wk_work_out"("p_work" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'work_id', w.id, 'name', w.name, 'description', w.description, 'status', w.status,
    'department', w.meta->>'department', 'year', w.meta->'year',
    'managers', (select jsonb_agg(m->>'name') from jsonb_array_elements(mcp_private.arr(w.meta->'managers')) m),
    'tasks', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'task_id', t.id, 'title', t.title, 'type', case t.type when 'one_time' then 'one_time' else 'procedural' end,
        'step', case when t.type = 'procedural' then t.order_index end, 'status', t.status,
        'due_dates', coalesce(t.meta->'deadlines', case when t.due_date is not null then jsonb_build_array(to_char(t.due_date at time zone 'Asia/Seoul', 'YYYY-MM-DD')) end),
        'visible_from', t.meta->>'visibleFrom',
        'assignees', (select jsonb_agg(a->>'name') from jsonb_array_elements(mcp_private.arr(t.meta->'assignees')) a),
        'actions', (select jsonb_agg(jsonb_build_object('action_id', a.id, 'type', a.action_type, 'title', a.title) order by a.created_at)
                    from task_action a where a.task_id = t.id and a.archived_at is null)))
        order by (t.type = 'procedural'), t.order_index, t.created_at)
      from task t where t.event_id = w.id), '[]'::jsonb)))
  from work w where w.id = p_work;
$$;


