    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "academic_year" integer NOT NULL,
    "kind" "text" NOT NULL,
    "code" "text",
    "name" "text" NOT NULL,
    "area_name" "text",
    "seat_id" "uuid",
    "seat_name" "text",
    "seat_label" "text",
    "department" "text",
    "brm" "text",
    "work_type" "text",
    "scale" "text",
    "load" numeric,
    "months" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "repeat_hint" "text",
    "counts" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "note" "text",
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "budget" bigint,
    "evidence" "jsonb",
    "procedures" "jsonb",
    CONSTRAINT "work_candidate_kind_check" CHECK (("kind" = ANY (ARRAY['area'::"text", 'work'::"text"]))),
    CONSTRAINT "work_candidate_name_check" CHECK (("length"("btrim"("name")) > 0))
);


ALTER TABLE "public"."work_candidate" OWNER TO "postgres";


COMMENT ON TABLE "public"."work_candidate" IS '업무 후보 — 업무 지도 artifact(공문 분석)에서 온 «올라올 수 있는 일». Work 가 아니며 사람이 고치고 지운다.';



COMMENT ON COLUMN "public"."work_candidate"."budget" IS '사업비(원) — 학교회계 세출예산 현액. artifact 의 산출내역 낱말로 업무에 붙인 값이라 짐작이 섞인다.';



COMMENT ON COLUMN "public"."work_candidate"."evidence" IS '근거 문서 [{date,dir,tier,title,who[]}] — 업무 지도 artifact(사람별 업무). 목록 조회에서 빼고 펼칠 때만 읽는다';



COMMENT ON COLUMN "public"."work_candidate"."procedures" IS '사람 × 업무 절차 검토 [{person,kind,cycle,summary,revised,steps[],related[]}] — 목록 조회에서 빼고 펼칠 때만 읽는다';



CREATE OR REPLACE FUNCTION "mcp_private"."wm_detail"("c" "public"."work_candidate") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_names text[] := mcp_private.wm_names(c);
begin
  return mcp_private.wm_row(c) || jsonb_strip_nulls(jsonb_build_object(
    'note', mcp_private.wm_scrub(c.note, v_names),
    'procedures', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'kind', p->>'kind',
        'cycle', p->>'cycle',
        'summary', mcp_private.wm_scrub(p->>'summary', v_names),
        'steps', (select jsonb_agg(jsonb_build_object(
              'name', mcp_private.wm_scrub(st->>'name', v_names),
              -- 단계 문서는 그 단계를 보여 주는 대표 문서(분석이 1~6건만 남겼다)라 «횟수»로 내보내지 않는다
              'sample_dates', (select coalesce(jsonb_agg(dd.dt order by dd.dt), '[]') from (
                  select d->>'date' dt from jsonb_array_elements(coalesce(st->'docs', '[]')) d order by 1 limit 12) dd))
            order by si)
          from jsonb_array_elements(coalesce(p->'steps', '[]')) with ordinality s(st, si)),
        'related', (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
              'work', r->>'work', 'role', mcp_private.wm_scrub(r->>'role', v_names))) order by ri)
          from jsonb_array_elements(coalesce(p->'related', '[]')) with ordinality q(r, ri))))
        order by pi)
      from jsonb_array_elements(coalesce(c.procedures, '[]')) with ordinality t(p, pi)), '[]'),
    'budget_items', (select jsonb_agg(jsonb_build_object('item', b->>0, 'amount', (b->>1)::bigint)) from jsonb_array_elements(
        case when jsonb_typeof(c.meta->'budget'->'items') = 'array' then c.meta->'budget'->'items' else '[]' end) b),
    'budget_spent', (c.meta->'budget'->>'spent')::bigint,
    'supports', (select jsonb_agg(jsonb_build_object('work', s->>0, 'documents', (s->>1)::integer)) from jsonb_array_elements(
        case when jsonb_typeof(c.meta->'supports') = 'array' then c.meta->'supports' else '[]' end) s)));
end $$;


ALTER FUNCTION "mcp_private"."wm_detail"("c" "public"."work_candidate") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wm_names"("c" "public"."work_candidate") RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(n order by length(n) desc, n), '{}') from (
    select distinct btrim(n) n from (
      select p->>'person' n from jsonb_array_elements(coalesce(c.procedures, '[]')) p
      union all select st->>'by' from jsonb_array_elements(coalesce(c.procedures, '[]')) p, jsonb_array_elements(coalesce(p->'steps', '[]')) st
      union all select r->>'person' from jsonb_array_elements(coalesce(c.procedures, '[]')) p, jsonb_array_elements(coalesce(p->'related', '[]')) r
      union all select pp->>0 from jsonb_array_elements(case when jsonb_typeof(c.meta->'owner'->'people') = 'array' then c.meta->'owner'->'people' else '[]' end) pp
      union all select x from jsonb_array_elements_text(case when jsonb_typeof(c.meta->'owner'->'seatPeople') = 'array' then c.meta->'owner'->'seatPeople' else '[]' end) x
      union all select c.meta->'owner'->>'top'
      union all select r.name from resource r where r.type in ('teacher', 'staff')) a
    where n is not null and length(btrim(n)) >= 2) b
$$;


ALTER FUNCTION "mcp_private"."wm_names"("c" "public"."work_candidate") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wm_row"("c" "public"."work_candidate") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'name', c.name,
    'area', c.area_name,
    'office', case when c.meta->>'office' = 'admin' then '행정실' else '교무실' end,
    'department', c.department,
    'seat_hint', coalesce(c.seat_name, nullif(c.seat_label, '')),
    'work_type', c.work_type,
    'scale', nullif(c.scale, '—'),
    'months', to_jsonb(c.months),
    'repeat_hint', c.repeat_hint,
    'budget', c.budget,
    'period', case when c.meta ? 'first' then jsonb_build_object('first', c.meta->>'first', 'last', c.meta->>'last') end,
    'documents', (c.counts->>'docs')::integer,
    'procedures', (select jsonb_object_agg(k, n) from (
        select p->>'kind' k, count(*) n from jsonb_array_elements(coalesce(c.procedures, '[]')) p group by 1) g)))
$$;


ALTER FUNCTION "mcp_private"."wm_row"("c" "public"."work_candidate") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wm_scrub"("p" "text", "p_names" "text"[]) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare v text := p; n text;
begin
  if v is null or p_names is null then return v; end if;
  foreach n in array p_names loop
    if n is not null and length(n) >= 2 then v := replace(v, n, '○○'); end if;
  end loop;
  return v;
end $$;


ALTER FUNCTION "mcp_private"."wm_scrub"("p" "text", "p_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."work_descendants"("p_work" "uuid") RETURNS TABLE("work_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with recursive d(work_id, depth, path) as (
    select w.id, 1, array[p_work, w.id] from public.work w where w.meta->'rolledOverFrom'->>'workId' = p_work::text
    union all
    select w.id, d.depth + 1, d.path || w.id
    from d join public.work w on w.meta->'rolledOverFrom'->>'workId' = d.work_id::text
    where not (w.id = any (d.path)) and d.depth < 20
  )
  select distinct d.work_id from d;
$$;


ALTER FUNCTION "mcp_private"."work_descendants"("p_work" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."work_event_on_action"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_work uuid; v_changed jsonb;
begin
  if tg_op = 'DELETE' then
    select event_id into v_work from public.task where id = old.task_id;   -- 할 일째 지울 때는 할 일이 이미 없다 → 기록 안 함
    perform mcp_private.we_insert(v_work, old.task_id, old.id, 'action.removed', jsonb_build_object('type', old.action_type, 'title', old.title));
    return null;
  end if;
  select event_id into v_work from public.task where id = new.task_id;
  if v_work is null then return null; end if;
  if tg_op = 'INSERT' then
    perform mcp_private.we_insert(v_work, new.task_id, new.id, 'action.added', jsonb_build_object('type', new.action_type, 'title', new.title));
    return null;
  end if;
  if new.archived_at is not null and old.archived_at is null then
    perform mcp_private.we_insert(v_work, new.task_id, new.id, 'action.archived', jsonb_build_object('type', new.action_type, 'title', new.title));
  end if;
  -- 만든 트랜잭션 안의 설정 넣기는 «만들기»의 일부다(add_action → update_collect_config) — 변경으로 세지 않는다
  if (new.config is distinct from old.config or new.title is distinct from old.title) and old.created_at <> now() then
    -- 바뀐 칸 — 맨 위 키, 둘 다 객체면 한 단계 아래까지(collect.fields · message.body …)
    select coalesce(jsonb_agg(distinct x.c), '[]') into v_changed from (
      select ks.k || coalesce('.' || sub.s, '') as c
      from (select jsonb_object_keys(coalesce(new.config, '{}'::jsonb)) as k
            union select jsonb_object_keys(coalesce(old.config, '{}'::jsonb))) ks
      left join lateral (
        select ss.s from (
          select jsonb_object_keys(case when jsonb_typeof(new.config->ks.k) = 'object' then new.config->ks.k else '{}'::jsonb end) as s
          union select jsonb_object_keys(case when jsonb_typeof(old.config->ks.k) = 'object' then old.config->ks.k else '{}'::jsonb end)) ss
        where jsonb_typeof(new.config->ks.k) = 'object' and jsonb_typeof(old.config->ks.k) = 'object'
          and new.config->ks.k->ss.s is distinct from old.config->ks.k->ss.s) sub on true
      where new.config->ks.k is distinct from old.config->ks.k
      union all select 'title' where new.title is distinct from old.title) x;
    perform mcp_private.we_insert(v_work, new.task_id, new.id, 'action.config_changed',
      jsonb_build_object('type', new.action_type, 'changed', v_changed), interval '10 minutes');
  end if;
  return null;
end $$;


ALTER FUNCTION "mcp_private"."work_event_on_action"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."work_event_on_task"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare o jsonb; n jsonb; v_add jsonb; v_rm jsonb;
begin
  if tg_op = 'INSERT' then
    perform mcp_private.we_insert(new.event_id, new.id, null, 'task.created', jsonb_strip_nulls(jsonb_build_object(
      'title', new.title, 'type', new.type, 'step', case when new.type = 'procedural' then new.order_index end,
      'due_dates', mcp_private.we_deadlines(new.meta, new.due_date),
      'assignees', jsonb_array_length(case when jsonb_typeof(new.meta->'assignees') = 'array' then new.meta->'assignees' else '[]' end),
      'from_task_id', new.meta->'rolledOverFrom'->>'taskId')));
    return null;
  elsif tg_op = 'DELETE' then
    perform mcp_private.we_insert(old.event_id, old.id, null, 'task.deleted', jsonb_build_object('title', old.title));
    return null;
  end if;

  o := mcp_private.we_deadlines(old.meta, old.due_date);
  n := mcp_private.we_deadlines(new.meta, new.due_date);
  if o is distinct from n then
    perform mcp_private.we_insert(new.event_id, new.id, null, 'task.deadline_changed', jsonb_build_object('from', o, 'to', n));
  end if;

  o := mcp_private.we_assignees(old.meta);
  n := mcp_private.we_assignees(new.meta);
  if (select coalesce(array_agg(k order by k), '{}') from jsonb_object_keys(o) k)
     is distinct from (select coalesce(array_agg(k order by k), '{}') from jsonb_object_keys(n) k) then
    select coalesce(jsonb_agg(n->>k), '[]') into v_add from jsonb_object_keys(n) k where not o ? k;
    select coalesce(jsonb_agg(o->>k), '[]') into v_rm from jsonb_object_keys(o) k where not n ? k;
    perform mcp_private.we_insert(new.event_id, new.id, null, 'task.assignees_changed',
      jsonb_build_object('added', v_add, 'removed', v_rm, 'total', (select count(*) from jsonb_object_keys(n))));
  end if;

  if new.type is distinct from old.type or new.order_index is distinct from old.order_index then
    perform mcp_private.we_insert(new.event_id, new.id, null, 'task.step_changed', jsonb_build_object(
      'from', jsonb_build_object('type', old.type, 'step', old.order_index),
      'to', jsonb_build_object('type', new.type, 'step', new.order_index)));
  end if;

  if (new.meta->>'visibleFrom') is distinct from (old.meta->>'visibleFrom') then
    perform mcp_private.we_insert(new.event_id, new.id, null, 'task.visible_from_changed',
      jsonb_build_object('from', old.meta->>'visibleFrom', 'to', new.meta->>'visibleFrom'));
  end if;

  if new.title is distinct from old.title then
    perform mcp_private.we_insert(new.event_id, new.id, null, 'task.title_changed', jsonb_build_object('from', old.title, 'to', new.title));
  end if;
  return null;
end $$;


ALTER FUNCTION "mcp_private"."work_event_on_task"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."work_knowledge_stamp"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare a record; v_task uuid; v_type text;
begin
  if tg_op = 'INSERT' then
    -- 작업에 붙이면 할 일은 그 작업의 할 일이다(따로 적은 할 일이 다르면 거부)
    if new.action_id is not null then
      select x.task_id, x.action_type into v_task, v_type from public.task_action x where x.id = new.action_id and x.archived_at is null;
      if v_task is null or not exists (select 1 from public.task t where t.id = v_task and t.event_id = new.work_id) then
        raise exception using errcode = '22023', message = '그 작업은 이 업무의 작업이 아닙니다.';
      end if;
      if new.task_id is not null and new.task_id <> v_task then
        raise exception using errcode = '22023', message = '그 작업은 그 할 일의 작업이 아닙니다.';
      end if;
      new.task_id := v_task;
      new.action_type := coalesce(new.action_type, v_type);
    end if;
    select * into a from mcp_private.we_actor(new.work_id, new.task_id);
    new.author_resource_id := a.actor;
    new.author_role := a.role;
    new.via := case when coalesce(auth.jwt()->>'client_id', '') <> '' then 'mcp' when auth.uid() is null then 'system' else 'web' end;
    new.created_at := now(); new.updated_at := now();
    if new.task_id is not null and not exists (select 1 from public.task t where t.id = new.task_id and t.event_id = new.work_id) then
      raise exception using errcode = '22023', message = '그 할 일은 이 업무의 할 일이 아닙니다.';
    end if;
  else
    if new.work_id <> old.work_id or new.task_id is distinct from old.task_id or new.action_id is distinct from old.action_id
       or new.kind <> old.kind
       or new.author_resource_id is distinct from old.author_resource_id or new.author_role <> old.author_role
       or new.via <> old.via or new.created_at <> old.created_at then
      raise exception using errcode = '42501', message = '지식의 업무·할 일·작업·종류·작성 정보는 바꿀 수 없습니다 — 새로 남기고 옛것은 보관하세요.';
    end if;
    new.updated_at := now();
  end if;
  return new;
end $$;


ALTER FUNCTION "mcp_private"."work_knowledge_stamp"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."work_lineage"("p_work" "uuid") RETURNS TABLE("work_id" "uuid", "depth" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  with recursive l(work_id, depth, path) as (
    select p_work, 0, array[p_work]
    union all
    select x.parent, l.depth + 1, l.path || x.parent
    from l
    join public.work w on w.id = l.work_id
    cross join lateral (select case when w.meta->'rolledOverFrom'->>'workId' ~ '^[0-9a-fA-F-]{36}$'
                                    then (w.meta->'rolledOverFrom'->>'workId')::uuid end as parent) x
    where x.parent is not null and not (x.parent = any (l.path)) and l.depth < 20
  )
  select l.work_id, l.depth from l where exists (select 1 from public.work w where w.id = l.work_id);
$_$;


ALTER FUNCTION "mcp_private"."work_lineage"("p_work" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wr_action_facts"("p_action" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare a public.task_action; v_kind text; v_req public.collect_request; v_pending uuid[]; v_people int; v_cfg jsonb;
begin
  select * into a from public.task_action where id = p_action;
  if a.id is null or not public.can_manage_task_action(p_action) then return null; end if;
  v_kind := public.request_kind_of(a.action_type);
  if v_kind is not null then
    select * into v_req from public.collect_request where action_id = p_action;
    v_cfg := public.request_cfg_of(a.action_type, a.config);
    if v_req.action_id is not null then
      v_pending := mcp_private.wr_pending(p_action);
      select count(distinct t.resource_id) into v_people from public.collect_target t
      where t.action_id = p_action and t.removed_at is null and t.resource_id is not null;
    end if;
  end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'request_kind', v_kind,
    'config_error', case
      when v_kind = 'input' and v_req.action_id is null then public.collect_config_error(v_cfg)
      when v_kind is not null and v_req.action_id is null then public.submit_config_error(a.action_type, v_cfg)
      when a.action_type = 'message.send' and btrim(coalesce(a.config->'message'->>'body', '')) = '' then '보낼 본문이 없습니다' end,
    'request', case when v_req.action_id is not null then jsonb_strip_nulls(jsonb_build_object(
      'status', v_req.status, 'started_at', v_req.started_at, 'closed_at', v_req.closed_at, 'due_date', v_cfg->>'dueDate',
      'people', v_people, 'pending', coalesce(cardinality(v_pending), 0),
      'pending_names', case when coalesce(cardinality(v_pending), 0) > 0 then mcp_private.wr_names(v_pending, 30) end,
      'last_reminded_at', (select max(n.created_at) from public.notification_events n
                           where n.meta->>'action_id' = p_action::text and n.title like '%(다시 알림)'))) end,
    'messages_sent', nullif((select count(*) from public.task_message_send where action_id = p_action), 0),
    'last_sent_at', (select max(sent_at) from public.task_message_send where action_id = p_action),
    'documents', nullif((select count(*) from public.task_action_document where action_id = p_action and archived_at is null), 0),
    'runs', nullif((select count(*) from public.task_action_run where action_id = p_action), 0)));
end $$;


ALTER FUNCTION "mcp_private"."wr_action_facts"("p_action" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wr_action_ref"("p_action" "uuid", OUT "task_id" "uuid", OUT "work_id" "uuid", OUT "action_type" "text") RETURNS "record"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  select a.task_id, t.event_id, a.action_type into task_id, work_id, action_type
  from public.task_action a join public.task t on t.id = a.task_id
  where a.id = p_action and a.archived_at is null;
  if work_id is null then raise exception using errcode = 'P0002', message = '그 작업을 찾지 못했습니다 (get_work_progress 의 action_id).'; end if;
end $$;


ALTER FUNCTION "mcp_private"."wr_action_ref"("p_action" "uuid", OUT "task_id" "uuid", OUT "work_id" "uuid", OUT "action_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wr_event"("p_work" "uuid", "p_task" "uuid", "p_action" "uuid", "p_kind" "text", "p_detail" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if p_kind not in ('agent.preview', 'agent.sent', 'insight.saved', 'insight.decided') then
    raise exception using errcode = '22023', message = '기록 종류가 아닙니다.';
  end if;
  if not (public.can_manage_work_structure(p_work) or (p_action is not null and public.can_manage_task_action(p_action))) then
    raise exception using errcode = '42501', message = '이 업무의 책임자가 아닙니다.';
  end if;
  return mcp_private.we_insert(p_work, p_task, p_action, p_kind, p_detail);
end $$;


