CREATE OR REPLACE FUNCTION "mcp_private"."wr_message_preview"("p_action" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare a public.task_action; v_cfg jsonb; v_title text; v_body text; v_res jsonb; v_ids uuid[]; v_names jsonb; v_unlinked jsonb;
begin
  if not public.can_manage_task_action(p_action) then
    raise exception using errcode = '42501', message = '이 작업을 만든 사람과 업무 책임자만 보낼 수 있습니다.';
  end if;
  select * into a from public.task_action where id = p_action;
  if a.action_type <> 'message.send' then raise exception using errcode = '22023', message = '메시지 보내기 작업이 아닙니다.'; end if;
  v_cfg := coalesce(a.config->'message', '{}'::jsonb);
  v_body := btrim(coalesce(v_cfg->>'body', ''));
  v_title := coalesce(nullif(btrim(v_cfg->>'title'), ''), (select title from public.task where id = a.task_id), '메시지');
  v_res := public.resolve_audience(public.expand_task_audience(coalesce(v_cfg->'audience', '{}'::jsonb), a.task_id), 'person', null, null);
  select array_agg(distinct (r.value->>'resource_id')::uuid order by (r.value->>'resource_id')::uuid) into v_ids
  from jsonb_array_elements(v_res->'rows') r where r.value->>'resource_id' is not null;
  select coalesce(jsonb_agg(distinct r.value->>'name'), '[]') into v_unlinked
  from jsonb_array_elements(v_res->'rows') r where r.value->>'resource_id' is null;
  v_names := mcp_private.wr_names(v_ids, 200);
  return jsonb_strip_nulls(jsonb_build_object(
    'action_id', a.id, 'type', a.action_type, 'task_title', (select title from public.task where id = a.task_id),
    'message_title', v_title, 'body', v_body,
    'config_error', case when v_body = '' then '보낼 본문이 없습니다 — update_action 으로 settings.body 를 적으세요.'
                         when coalesce(cardinality(v_ids), 0) = 0 then '받을 사람이 없습니다 — 대상 규칙을 확인하세요.' end,
    'people', coalesce(cardinality(v_ids), 0), 'recipients', v_names,
    'not_linked', case when jsonb_array_length(v_unlinked) > 0 then v_unlinked end,
    'sent_before', (select count(*) from public.task_message_send where action_id = p_action),
    'fingerprint', md5('message|' || v_title || chr(31) || v_body || chr(31) || coalesce(array_to_string(v_ids, ','), ''))));
end $$;


ALTER FUNCTION "mcp_private"."wr_message_preview"("p_action" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wr_names"("p_ids" "uuid"[], "p_limit" integer DEFAULT 40) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(name order by name), '[]'::jsonb)
  from (select r.name from public.resource r where r.id = any (coalesce(p_ids, '{}')) order by r.name limit p_limit) x;
$$;


