CREATE OR REPLACE FUNCTION "mcp_private"."wr_pending"("p_action" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_req public.collect_request; v_cfg jsonb; v_ids uuid[];
begin
  select * into v_req from public.collect_request where action_id = p_action;
  if v_req.action_id is null then return null; end if;
  if v_req.kind <> 'input' then
    select array_agg(distinct t.resource_id) into v_ids
    from public.collect_target t
    where t.action_id = p_action and t.removed_at is null and t.resource_id is not null
      and public.submission_target_pending(p_action, t.resource_id);
    return coalesce(v_ids, '{}');
  end if;
  select config->'collect' into v_cfg from public.task_action where id = p_action;
  select array_agg(distinct t.resource_id) into v_ids
  from public.collect_target t
  cross join lateral (
    select coalesce(d.value->>'key', '') dim
    from jsonb_array_elements(case when jsonb_array_length(coalesce(v_cfg->'dimensions', '[]'::jsonb)) = 0
                                   then '[{"key":""}]'::jsonb else v_cfg->'dimensions' end) d
  ) dims
  where t.action_id = p_action and t.removed_at is null and t.resource_id is not null
    and not exists (
      select 1 from public.collect_response r
      where r.action_id = p_action and r.unit_key = t.unit_key and r.dimension_key = dims.dim
        and r.owner_key = case when v_req.answer_mode = 'shared' then '' else t.resource_id::text end
        and public.collect_cell_complete(r."values", v_cfg->'fields'));
  return coalesce(v_ids, '{}');
end $$;


ALTER FUNCTION "mcp_private"."wr_pending"("p_action" "uuid") OWNER TO "postgres";


