    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not public.can_manage_collect(p_action) then return null; end if;
  return mcp_private.wr_names(mcp_private.wr_pending(p_action), 200);
end $$;


