CREATE OR REPLACE FUNCTION "mcp_private"."wr_remind_preview"("p_action" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_req public.collect_request; v_ids uuid[];
begin
  if not public.can_manage_collect(p_action) then
    raise exception using errcode = '42501', message = '작업을 만든 사람과 업무 책임자만 다시 알릴 수 있습니다.';
  end if;
  select * into v_req from public.collect_request where action_id = p_action;
  v_ids := mcp_private.wr_pending(p_action);
  select array_agg(x order by x) into v_ids from unnest(coalesce(v_ids, '{}')) x;
  return jsonb_strip_nulls(jsonb_build_object(
    'action_id', p_action, 'title', (select title from public.task_action where id = p_action),
    'request_status', v_req.status, 'started_at', v_req.started_at,
    'people', coalesce(cardinality(v_ids), 0),
    'recipients', mcp_private.wr_names(v_ids, 200),
    'last_reminded_at', (select max(n.created_at) from public.notification_events n
                         where n.meta->>'action_id' = p_action::text and n.title like '%(다시 알림)'),
    'fingerprint', md5('remind|' || coalesce(array_to_string(v_ids, ','), ''))));
end $$;


