CREATE OR REPLACE FUNCTION "mcp_private"."wr_request_preview"("p_action" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare a public.task_action; v_kind text; v_cfg jsonb; v_err text; v_axis text; v_year int; v_sem int; v_res jsonb; v_rows jsonb;
begin
  if not public.can_manage_collect(p_action) then
    raise exception using errcode = '42501', message = '작업을 만든 사람과 업무 책임자만 요청을 보낼 수 있습니다.';
  end if;
  select * into a from public.task_action where id = p_action;
  v_kind := public.request_kind_of(a.action_type);
  if v_kind is null then raise exception using errcode = '22023', message = '요청을 보내는 작업(입력 받기·제출 받기)이 아닙니다.'; end if;
  v_cfg := public.request_cfg_of(a.action_type, a.config);
  v_err := case when v_kind = 'input' then public.collect_config_error(v_cfg) else public.submit_config_error(a.action_type, v_cfg) end;
  v_axis := case when v_kind = 'input' then coalesce(v_cfg->>'axis', 'person')
                 when public.task_has_units(a.task_id) then 'unit' else 'person' end;
  select t.academic_year, t.semester into v_year, v_sem from public.current_academic_term() t;
  v_res := public.resolve_audience(public.expand_task_audience(coalesce(v_cfg->'audience', '{}'::jsonb), a.task_id),
                                   case when v_axis = 'unit' then 'person' else v_axis end, v_year, v_sem);
  select coalesce(jsonb_agg(r.value order by r.value->>'name', r.value->>'unit_label'), '[]') into v_rows
  from jsonb_array_elements(v_res->'rows') r where r.value->>'unit_key' is not null;

  return jsonb_strip_nulls(jsonb_build_object(
    'action_id', a.id, 'title', a.title, 'type', a.action_type, 'kind', v_kind, 'axis', v_axis,
    'task_title', (select title from public.task where id = a.task_id),
    'already_sent', exists (select 1 from public.collect_request where action_id = p_action),
    'config_error', v_err,
    'due_date', v_cfg->>'dueDate',
    'fields', case when v_kind = 'input' then (select jsonb_agg(f->>'label') from jsonb_array_elements(coalesce(v_cfg->'fields', '[]')) f) end,
    'dimensions', case when v_kind = 'input' then (select jsonb_agg(d->>'label') from jsonb_array_elements(coalesce(v_cfg->'dimensions', '[]')) d) end,
    'visibility', case when v_kind = 'input' then coalesce(v_cfg->>'mode', 'private') end,
    'people', (select count(distinct r->>'resource_id') from jsonb_array_elements(v_rows) r where r->>'resource_id' is not null),
    'unlinked', (select count(*) from jsonb_array_elements(v_rows) r where r->>'resource_id' is null),
    'no_units', (select count(*) from jsonb_array_elements(v_res->'rows') r where r.value->>'unit_key' is null),
    'recipients', (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                     'name', r->>'name', 'unit', nullif(r->>'unit_label', ''),
                     'not_linked', case when r->>'resource_id' is null then true end)))
                   from (select r from jsonb_array_elements(v_rows) r limit 200) x),
    'fingerprint', md5(v_kind || '|' || v_axis || '|' || coalesce(v_cfg::text, '') || '|' || coalesce((
      select string_agg(coalesce(r->>'resource_id', 'name:' || (r->>'name')) || '@' || (r->>'unit_key'), ',' order by 1)
      from jsonb_array_elements(v_rows) r), ''))));
end $$;


ALTER FUNCTION "mcp_private"."wr_request_preview"("p_action" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "mcp_private"."wr_review_facts"("p_work" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare w public.work;
begin
  if not public.can_view_work_events(p_work) then return null; end if;
  select * into w from public.work where id = p_work;
  if w.id is null then return null; end if;
  return jsonb_build_object(
    'work', jsonb_strip_nulls(jsonb_build_object('work_id', w.id, 'name', w.name, 'status', w.status, 'year', w.meta->'year',
              'created_at', w.created_at, 'rolled_over_from', w.meta->'rolledOverFrom'->>'workId')),
    'tasks', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'task_id', t.id, 'title', t.title, 'type', t.type, 'step', case when t.type = 'procedural' then t.order_index end,
        'status', t.status, 'created_at', t.created_at, 'due_dates', mcp_private.we_deadlines(t.meta, t.due_date),
        'from_task_id', t.meta->'rolledOverFrom'->>'taskId',
        'assignees', jsonb_array_length(case when jsonb_typeof(t.meta->'assignees') = 'array' then t.meta->'assignees' else '[]' end),
        'assignees_done', (select count(*) from jsonb_array_elements(mcp_private.arr(t.meta->'assignees')) x where x->>'status' = 'completed'),
        'completed_at', (select max(h.changed_at) from public.task_status_history h where h.task_id = t.id and h.new_status = 'completed')))
        order by (t.type <> 'procedural'), t.order_index, t.created_at)
      from public.task t where t.event_id = w.id), '[]'::jsonb),
    'actions', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'action_id', a.id, 'task_id', a.task_id, 'type', a.action_type, 'title', a.title, 'created_at', a.created_at,
        'request', (select jsonb_build_object('kind', r.kind, 'started_at', r.started_at, 'closed_at', r.closed_at, 'closed_reason', r.closed_reason,
                      'people', (select count(distinct ct.resource_id) from public.collect_target ct where ct.action_id = a.id and ct.removed_at is null and ct.resource_id is not null),
                      'first_responses', coalesce((select jsonb_agg(f order by f) from (
                          select min(x.created_at) f from public.collect_response x where x.action_id = a.id and r.kind = 'input' group by x.responder_resource_id
                          union all
                          select min(s.created_at) from public.action_submission s where s.action_id = a.id and r.kind <> 'input' group by s.resource_id) fr), '[]'))
                    from public.collect_request r where r.action_id = a.id),
        'reminders', (select jsonb_agg(m order by m) from (select distinct date_trunc('minute', n.created_at) m from public.notification_events n
                       where n.meta->>'action_id' = a.id::text and n.title like '%(다시 알림)') rm),
        'messages', (select jsonb_agg(ms.sent_at order by ms.sent_at) from public.task_message_send ms where ms.action_id = a.id),
        'documents', (select jsonb_agg(d.created_at order by d.created_at) from public.task_action_document d where d.action_id = a.id))))
      from public.task_action a join public.task t on t.id = a.task_id where t.event_id = w.id), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'at', e.at, 'kind', e.kind, 'task_id', e.task_id, 'action_id', e.action_id, 'role', e.actor_role, 'via', e.via,
        -- 사람 이름은 빼고 개수만(담당자 변경)
        'detail', case when e.kind = 'task.assignees_changed'
                       then jsonb_build_object('added', jsonb_array_length(coalesce(e.detail->'added', '[]')),
                                               'removed', jsonb_array_length(coalesce(e.detail->'removed', '[]')), 'total', e.detail->'total')
                       when e.kind in ('agent.preview', 'agent.sent') then e.detail - 'recipients'
                       else e.detail end)) order by e.at)
      from (select * from public.work_event where work_id = w.id and kind not in ('insight.saved', 'insight.decided')
            order by at desc limit 300) e), '[]'::jsonb));
end $$;


ALTER FUNCTION "mcp_private"."wr_review_facts"("p_work" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "official_doc_private"."count_rule_hits"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  d official_doc;
begin
  select * into d from official_doc where id = new.doc_id;
  update doc_rule r
     set hits = r.hits + case when r.outcome->>'decision' is null or r.outcome->>'decision' = new.decision then 1 else 0 end,
         overturned = r.overturned + case when r.outcome->>'decision' is not null and r.outcome->>'decision' <> new.decision then 1 else 0 end
   where r.status = 'active'
     and not (new.id = any(r.source_decision_ids))
     and official_doc_private.rule_matches(r.condition, d.sender, d.title);
  return new;
end;
$$;


ALTER FUNCTION "official_doc_private"."count_rule_hits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "official_doc_private"."rule_matches"("p_condition" "jsonb", "p_sender" "text", "p_title" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select (coalesce(p_condition->>'sender', '') <> '' or jsonb_array_length(coalesce(p_condition->'title_all', '[]'::jsonb)) > 0)
     and (coalesce(p_condition->>'sender', '') = ''
          or position(lower(regexp_replace(p_condition->>'sender', '\s+', '', 'g'))
                      in lower(regexp_replace(coalesce(p_sender, ''), '\s+', '', 'g'))) > 0)
     and not exists (
       select 1 from jsonb_array_elements_text(coalesce(p_condition->'title_all', '[]'::jsonb)) w
        where position(lower(regexp_replace(w, '\s+', '', 'g')) in lower(regexp_replace(coalesce(p_title, ''), '\s+', '', 'g'))) = 0);
$$;


ALTER FUNCTION "official_doc_private"."rule_matches"("p_condition" "jsonb", "p_sender" "text", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "official_doc_private"."triage_nature"("p" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case when p->>'nature' in ('제출', '추천', '설문', '참석', '실시', '지침', '기회', '홍보', '무관', '업무') then p->>'nature' end;
$$;


ALTER FUNCTION "official_doc_private"."triage_nature"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."__overlap5"("a" "text", "b" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare i int; hit int := 0; tot int := 0; g text;
begin
  a := regexp_replace(coalesce(a,''), '\s+', '', 'g');
  b := regexp_replace(coalesce(b,''), '\s+', '', 'g');
  if length(a) < 5 then return null; end if;
  for i in 1..(length(a)-4) loop
    g := substr(a, i, 5);
    tot := tot + 1;
    if position(g in b) > 0 then hit := hit + 1; end if;
  end loop;
  return round(hit::numeric / nullif(tot,0), 3);
end $$;


ALTER FUNCTION "public"."__overlap5"("a" "text", "b" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_bench_linked_teacher"("uid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from public.profiles p where p.id = uid and p.role in ('teacher','admin'))
     and exists (select 1 from public.user_resource ur join public.resource r on r.id = ur.resource_id
                 where ur.user_id = uid and r.type <> 'inactive');
$$;


