CREATE OR REPLACE FUNCTION "public"."_start_action_request"("p_action_id" "uuid", "p_allow_empty" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_action public.task_action;
  v_kind   text;
  v_cfg    jsonb;
  v_err    text;
  v_res    jsonb;
  v_year   int;
  v_sem    int;
  v_axis   text;
  v_ids    uuid[];
  v_notified int := 0;
begin
  select * into v_action from public.task_action where id = p_action_id;
  v_kind := public.request_kind_of(v_action.action_type);
  if v_kind is null then raise exception '요청을 보낼 수 있는 작업이 아닙니다' using errcode = 'P0002'; end if;
  if exists (select 1 from public.collect_request where action_id = p_action_id) then
    raise exception '이미 보낸 요청입니다 — 명단 변경은 [다시 계산]을 쓰세요' using errcode = '23505';
  end if;

  v_cfg := public.request_cfg_of(v_action.action_type, v_action.config);
  v_err := case when v_kind = 'input' then public.collect_config_error(v_cfg)
                else public.submit_config_error(v_action.action_type, v_cfg) end;
  if v_err is not null then raise exception '%', v_err using errcode = '22023'; end if;

  v_axis := case when v_kind = 'input' then coalesce(v_cfg->>'axis', 'person')
                 when public.task_has_units(v_action.task_id) then 'unit'   -- 과제 단위별 제출(2026-10-01)
                 else 'person' end;
  select t.academic_year, t.semester into v_year, v_sem from public.current_academic_term() t;
  -- 대상(사람)은 언제나 사람 축으로 푼다 — 단위는 사람이 낼 때 고른다
  v_res := public.resolve_audience(public.expand_task_audience(coalesce(v_cfg->'audience', '{}'::jsonb), v_action.task_id),
                                   case when v_axis = 'unit' then 'person' else v_axis end, v_year, v_sem);

  if not p_allow_empty and not exists (select 1 from jsonb_array_elements(v_res->'rows') r where r.value->>'unit_key' is not null) then
    raise exception '대상이 한 명도 없습니다' using errcode = '22023';
  end if;

  insert into public.collect_request (action_id, task_id, academic_year, semester, axis, answer_mode, visibility,
                                      rule_snapshot, config_snapshot, kind)
  values (p_action_id, v_action.task_id, v_year, v_sem, v_axis,
          case when v_kind = 'input' then coalesce(v_cfg->>'answerMode', 'each') else 'each' end,
          case when v_kind = 'input' then coalesce(v_cfg->>'mode', 'private') else 'private' end,
          coalesce(v_cfg->'audience', '{}'::jsonb), v_cfg, v_kind);

  insert into public.collect_target (action_id, unit_key, unit_label, resource_id, holder_name, reasons)
  select p_action_id, r.value->>'unit_key', coalesce(r.value->>'unit_label', ''),
         nullif(r.value->>'resource_id', '')::uuid, r.value->>'name',
         array(select jsonb_array_elements_text(r.value->'reasons'))
  from jsonb_array_elements(v_res->'rows') r
  where r.value->>'unit_key' is not null
  on conflict do nothing;

  select array_agg(distinct resource_id) into v_ids
  from public.collect_target where action_id = p_action_id and resource_id is not null;
  v_notified := public.collect_notify(p_action_id, v_ids, 'request');

  -- 제출 요청이 열리면 그 대상인 담당자의 «완료»를 다시 맞춘다(이미 완료였던 담당자는 대기로 돌아간다)
  if v_kind <> 'input' then
    perform public._submission_resync_task(v_action.task_id);
  end if;

  return jsonb_build_object(
    'targets', (select count(*) from public.collect_target where action_id = p_action_id),
    'people', coalesce(cardinality(v_ids), 0),
    'unlinked', (select count(*) from public.collect_target where action_id = p_action_id and resource_id is null),
    'no_units', (select count(*) from jsonb_array_elements(v_res->'rows') r where r.value->>'unit_key' is null),
    'notified', v_notified,
    'academic_year', v_year, 'semester', v_sem);
end;
$$;


ALTER FUNCTION "public"."_start_action_request"("p_action_id" "uuid", "p_allow_empty" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."collect_request" (
    "action_id" "uuid" NOT NULL,
    "task_id" "uuid",
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "academic_year" integer NOT NULL,
    "semester" integer NOT NULL,
    "axis" "text" NOT NULL,
    "answer_mode" "text" DEFAULT 'each'::"text" NOT NULL,
    "visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    "rule_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "config_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_by" "uuid" DEFAULT "auth"."uid"(),
    "closed_at" timestamp with time zone,
    "closed_reason" "text",
    "kind" "text" DEFAULT 'input'::"text" NOT NULL,
    CONSTRAINT "collect_request_answer_mode_check" CHECK (("answer_mode" = ANY (ARRAY['each'::"text", 'shared'::"text"]))),
    CONSTRAINT "collect_request_axis_check" CHECK (("axis" = ANY (ARRAY['person'::"text", 'subject'::"text", 'class'::"text", 'unit'::"text", 'club'::"text", 'club_member'::"text"]))),
    CONSTRAINT "collect_request_kind_check" CHECK (("kind" = ANY (ARRAY['input'::"text", 'file'::"text", 'document'::"text", 'physical'::"text"]))),
    CONSTRAINT "collect_request_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'closed'::"text"]))),
    CONSTRAINT "collect_request_visibility_check" CHECK (("visibility" = ANY (ARRAY['private'::"text", 'shared'::"text"])))
);


ALTER TABLE "public"."collect_request" OWNER TO "postgres";


COMMENT ON TABLE "public"."collect_request" IS '입력 받기 요청의 실행 상태. 설정(설계)은 task_action.config.collect, 상태·학기·축·공개 방식은 여기(시작 후 잠금). 복사·연간 가져오기가 config 를 복제해도 상태는 따라가지 않는다.';



COMMENT ON COLUMN "public"."collect_request"."kind" IS '요청 종류(2026-10-01) — input=입력 받기, file/document/physical=제출 받기. 작업 유형에서 유도(request_kind_of).';



CREATE OR REPLACE FUNCTION "public"."_submission_check_unit"("p_req" "public"."collect_request", "p_unit_key" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if p_req.axis = 'unit' then
    if coalesce(p_unit_key, '') = '' then raise exception '어느 과제 단위의 제출인지 고르세요' using errcode = '22023'; end if;
    if not exists (select 1 from public.task t, jsonb_array_elements(t.meta->'units') u(value)
                   where t.id = p_req.task_id and u.value->>'key' = p_unit_key) then
      raise exception '없는 과제 단위입니다' using errcode = '22023';
    end if;
    return p_unit_key;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."_submission_check_unit"("p_req" "public"."collect_request", "p_unit_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_submission_open_for_me"("p_action_id" "uuid", "p_kind" "text") RETURNS "public"."collect_request"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.collect_request;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into v_req from public.collect_request where action_id = p_action_id;
  if not found or v_req.kind <> p_kind then raise exception '제출 요청을 찾을 수 없습니다' using errcode = 'P0002'; end if;
  if v_req.status <> 'open' then raise exception '마감된 요청입니다' using errcode = '22023'; end if;
  if not public.is_collect_target(p_action_id) then
    raise exception '이 요청의 대상이 아닙니다' using errcode = '42501';
  end if;
  return v_req;
end;
$$;


ALTER FUNCTION "public"."_submission_open_for_me"("p_action_id" "uuid", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_submission_resync_task"("p_task_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_id text;
  v_unit record;
begin
  if public.task_has_units(p_task_id) then
    -- 단위 할 일: 완료로 표시된 «맡은 단위» 중 이제 제출이 필요한 것을 대기로 되돌린다(맡은 기록은 남긴다)
    for v_unit in
      select u.key unit_key, p.key person
      from public.task t,
           lateral jsonb_each(case when jsonb_typeof(t.meta->'unitProgress') = 'object' then t.meta->'unitProgress' else '{}'::jsonb end) u,
           lateral jsonb_each(case when jsonb_typeof(u.value) = 'object' then u.value else '{}'::jsonb end) p
      where t.id = p_task_id and p.value->>'status' = 'completed'
    loop
      if v_unit.person ~ '^[0-9a-fA-F-]{36}$'
         and public.unit_has_pending_submission(p_task_id, v_unit.person::uuid, v_unit.unit_key) then
        perform public.set_task_unit_status(p_task_id, v_unit.unit_key, v_unit.person::uuid, 'pending');
      end if;
    end loop;
    return;
  end if;

  for v_id in
    select a.value->>'id' from public.task t,
      lateral jsonb_array_elements(case when jsonb_typeof(t.meta->'assignees') = 'array'
                                        then t.meta->'assignees' else '[]'::jsonb end) a(value)
    where t.id = p_task_id
  loop
    if v_id ~ '^[0-9a-fA-F-]{36}$' then
      -- 대기로 되돌리는 쪽만 한다 — 아무것도 안 낸 담당자를 저절로 완료로 만들지 않는다
      if public.assignee_has_pending_submission(p_task_id, v_id::uuid)
         and exists (select 1 from public.task t,
                       lateral jsonb_array_elements(t.meta->'assignees') a(value)
                     where t.id = p_task_id and a.value->>'id' = v_id and a.value->>'status' = 'completed') then
        perform public.set_task_assignee_status(p_task_id, v_id::uuid, 'pending');
      end if;
    end if;
  end loop;
end;
$_$;


ALTER FUNCTION "public"."_submission_resync_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_submission_sync_unit"("p_req" "public"."collect_request", "p_resource_id" "uuid", "p_unit_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  if p_req.axis <> 'unit' or p_unit_key is null then return; end if;
  select t.meta->'unitProgress'->p_unit_key->p_resource_id::text->>'status' into v_status
  from public.task t where t.id = p_req.task_id;

  if not public.unit_has_pending_submission(p_req.task_id, p_resource_id, p_unit_key) then
    if v_status is distinct from 'completed' then
      perform public.set_task_unit_status(p_req.task_id, p_unit_key, p_resource_id, 'completed');
    end if;
  elsif v_status = 'completed' then
    perform public.set_task_unit_status(p_req.task_id, p_unit_key, p_resource_id, 'pending');
  elsif v_status is null and exists (select 1 from public.action_submission s
             where s.action_id = p_req.action_id and s.resource_id = p_resource_id and s.unit_key = p_unit_key) then
    -- 아직 맡지 않은 단위에 냈다 — 맡게만 한다(완료는 남은 제출을 다 낸 뒤)
    perform public.set_task_unit_status(p_req.task_id, p_unit_key, p_resource_id, 'pending');
  end if;
end;
$$;


ALTER FUNCTION "public"."_submission_sync_unit"("p_req" "public"."collect_request", "p_resource_id" "uuid", "p_unit_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_sync_action_targets"("p_action_id" "uuid", "p_apply" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req    public.collect_request;
  v_action public.task_action;
  v_cfg    jsonb;
  v_res    jsonb;
  v_added  jsonb;
  v_removed jsonb;
  v_new_ids uuid[];
begin
  select * into v_req from public.collect_request where action_id = p_action_id;
  if not found then raise exception '아직 보내지 않은 요청입니다' using errcode = 'P0002'; end if;
  select * into v_action from public.task_action where id = p_action_id;
  v_cfg := public.request_cfg_of(v_action.action_type, v_action.config);
  v_res := public.resolve_audience(public.expand_task_audience(coalesce(v_cfg->'audience', '{}'::jsonb), v_action.task_id),
                                   case when v_req.axis = 'unit' then 'person' else v_req.axis end,
                                   v_req.academic_year, v_req.semester);

  create temp table if not exists _collect_next (unit_key text, unit_label text, resource_id uuid, holder_name text, reasons text[]) on commit drop;
  truncate _collect_next;
  insert into _collect_next
  select r.value->>'unit_key', coalesce(r.value->>'unit_label', ''), nullif(r.value->>'resource_id', '')::uuid,
         r.value->>'name', array(select jsonb_array_elements_text(r.value->'reasons'))
  from jsonb_array_elements(v_res->'rows') r
  where r.value->>'unit_key' is not null;

  select coalesce(jsonb_agg(jsonb_build_object('name', n.holder_name, 'unit_label', n.unit_label, 'resource_id', n.resource_id, 'reasons', n.reasons)), '[]'::jsonb)
    into v_added
  from _collect_next n
  where not exists (select 1 from public.collect_target t
                    where t.action_id = p_action_id and t.removed_at is null and t.unit_key = n.unit_key
                      and coalesce(t.resource_id::text, 'name:' || t.holder_name) = coalesce(n.resource_id::text, 'name:' || n.holder_name));

  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', t.holder_name, 'unit_label', t.unit_label, 'resource_id', t.resource_id)), '[]'::jsonb)
    into v_removed
  from public.collect_target t
  where t.action_id = p_action_id and t.removed_at is null
    and not exists (select 1 from _collect_next n where n.unit_key = t.unit_key
                    and coalesce(t.resource_id::text, 'name:' || t.holder_name) = coalesce(n.resource_id::text, 'name:' || n.holder_name));

  if p_apply then
    update public.collect_target t set removed_at = now()
    where t.id in (select (x->>'id')::uuid from jsonb_array_elements(v_removed) x);

    insert into public.collect_target (action_id, unit_key, unit_label, resource_id, holder_name, reasons)
    select p_action_id, n.unit_key, n.unit_label, n.resource_id, n.holder_name, n.reasons
    from _collect_next n
    on conflict (action_id, unit_key, coalesce(resource_id::text, 'name:' || holder_name))
    do update set removed_at = null, reasons = excluded.reasons, unit_label = excluded.unit_label;

    select array_agg(distinct (x->>'resource_id')::uuid) into v_new_ids
    from jsonb_array_elements(v_added) x where x->>'resource_id' is not null;
    perform public.collect_notify(p_action_id, v_new_ids, 'request');

    if v_req.kind <> 'input' then
      perform public._submission_resync_task(v_action.task_id);
    end if;
  end if;

  return jsonb_build_object('added', v_added, 'removed', v_removed, 'applied', p_apply,
                            'no_units', (select count(*) from jsonb_array_elements(v_res->'rows') r where r.value->>'unit_key' is null));
end;
$$;


