CREATE OR REPLACE FUNCTION "public"."academy_daily_claim"("p_user" "uuid", "p_day" "date", "p_revision" integer, "p_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare c public.academy_daily_conversations; today date := (now() at time zone 'Asia/Seoul')::date; token uuid; waiting text;
begin
  if not exists(select 1 from public.profiles where id = p_user and role in ('student','teacher','admin')) then raise exception 'Student account required' using errcode = '42501'; end if;
  if p_message is not null and char_length(btrim(p_message)) not between 1 and 2000 then raise exception 'Invalid message'; end if;
  if p_day = today then
    insert into public.academy_daily_conversations(user_id,day,npc) values(p_user,p_day,public.academy_daily_npc(p_user,p_day)) on conflict do nothing;
  end if;
  select * into c from public.academy_daily_conversations where user_id = p_user and day = p_day for update;
  if not found or (p_day <> today and c.question is null) then raise exception 'Refresh daily conversation'; end if;
  if c.revision <> p_revision or (c.status = 'generating' and c.lease_until > now()) or (c.status = 'ready' and p_message is null) then
    return jsonb_build_object('claimed',false,'conversation',to_jsonb(c)-'lease_token');
  end if;
  if c.status = 'ready' then
    if jsonb_array_length(c.turns) >= 150 then raise exception '이 대화의 수첩을 모두 채웠어요. 다음 날 새 대화를 이어가요.'; end if;
    c.pending_message := btrim(p_message);
    c.turns := c.turns || jsonb_build_array(jsonb_build_object('role','user','kind','message','content',c.pending_message,'at',now()));
  end if;
  -- Failed/expired work resumes its stored message, even if another tab sends a new one.
  if c.status = 'ready' or c.revision = 0 then
    waiting := case c.npc
      when 'luon' then '리아, 잠깐 함께 걸을까? 오늘은 네 생각을 조금 더 듣고 싶어. 무슨 이야기를 꺼낼지 생각하는 중이야.'
      when 'librarian' then '리아, 이쪽에 앉아 줘. 책갈피를 정리하는 동안 네게 건넬 이야기를 생각해 볼게.'
      when 'professor' then '리아, 망원경 옆에 자리를 마련했단다. 잠시 별을 보며 기다려 주겠니? 네게 물어보고 싶은 게 있어.'
      else '리아, 와 줬구나. 전서구에게 물을 주고 올게. 오늘은 네 생각이 궁금해졌어.' end;
    c.turns := c.turns || jsonb_build_array(jsonb_build_object('role','assistant','kind','waiting','content',waiting,'at',now()));
  end if;
  token := gen_random_uuid();
  update public.academy_daily_conversations set status='generating', turns=c.turns, pending_message=c.pending_message,
    revision=revision+1, lease_token=token, lease_until=now()+interval '75 seconds', updated_at=now()
    where user_id=p_user and day=p_day returning * into c;
  return jsonb_build_object('claimed',true,'token',token,'conversation',to_jsonb(c)-'lease_token');
end;
$$;


ALTER FUNCTION "public"."academy_daily_claim"("p_user" "uuid", "p_day" "date", "p_revision" integer, "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."academy_daily_finish"("p_user" "uuid", "p_day" "date", "p_token" "uuid", "p_reply" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare c public.academy_daily_conversations;
begin
  select * into c from public.academy_daily_conversations where user_id=p_user and day=p_day for update;
  if not found then raise exception 'Conversation missing'; end if;
  if c.lease_token is distinct from p_token or c.status <> 'generating' then return to_jsonb(c)-'lease_token'; end if;
  if p_reply is not null and char_length(btrim(p_reply)) not between 1 and 2000 then raise exception 'Invalid reply'; end if;
  if p_reply is not null then
    c.turns := c.turns || jsonb_build_array(jsonb_build_object('role','assistant','kind',case when c.question is null then 'question' else 'message' end,'content',btrim(p_reply),'at',now()));
  end if;
  update public.academy_daily_conversations set
    question=coalesce(question,btrim(p_reply)), turns=c.turns,
    pending_message=case when p_reply is null then pending_message else null end,
    status=case when p_reply is null then 'failed' else 'ready' end,
    lease_token=null, lease_until=null, revision=revision+1, updated_at=now()
    where user_id=p_user and day=p_day returning * into c;
  return to_jsonb(c)-'lease_token';
end;
$$;


ALTER FUNCTION "public"."academy_daily_finish"("p_user" "uuid", "p_day" "date", "p_token" "uuid", "p_reply" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."academy_daily_npc"("p_user" "uuid", "p_day" "date") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select (array['luon','librarian','professor','postmaster'])[1 + (sum(ascii(c)) % 4)::integer]
  from regexp_split_to_table(p_user::text || to_char(p_day, 'YYYY-MM-DD'), '') c;
$$;


ALTER FUNCTION "public"."academy_daily_npc"("p_user" "uuid", "p_day" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."academy_daily_state"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('day', d, 'npc', public.academy_daily_npc(auth.uid(),d),
    'conversation', (select to_jsonb(c) - 'lease_token' from public.academy_daily_conversations c where c.user_id = auth.uid() and c.day = d))
  from (select (now() at time zone 'Asia/Seoul')::date d) today;
$$;


ALTER FUNCTION "public"."academy_daily_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."academy_discovery_write"("p_user" "uuid", "p_source" "text", "p_revision" integer, "p_statement" "text" DEFAULT NULL::"text", "p_memory" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare r public.academy_self_discoveries; excerpt text;
begin
  if not exists(select 1 from public.profiles where id=p_user and role in ('student','teacher','admin')) then raise exception '학생 본인의 기록만 남길 수 있어요.' using errcode='42501'; end if;
  if p_source is null or p_source not in ('first','journey') or p_revision is null or p_revision<0 then raise exception '기억의 출처를 확인해 주세요.'; end if;
  -- Lock the owner row even before the first discovery exists, preventing insert races.
  perform id from public.profiles where id=p_user for update;
  select * into r from public.academy_self_discoveries where user_id=p_user and source=p_source for update;
  if coalesce(r.revision,0)<>p_revision then raise exception '다른 창에서 기록이 바뀌었어요. 새 기록을 불러와 주세요.'; end if;
  if p_memory is not null then
    if r.user_id is null then raise exception '먼저 나의 문장을 남겨 주세요.'; end if;
    update public.academy_self_discoveries set memory_enabled=p_memory,revision=revision+1,updated_at=now() where user_id=p_user and source=p_source returning * into r;
    return to_jsonb(r);
  end if;
  if p_statement is null or char_length(btrim(p_statement)) not between 10 and 1000 then raise exception '내가 확인한 문장을 10~1,000자로 적어 주세요.'; end if;
  if p_source='first' then
    select question into excerpt from public.academy_game_progress where user_id=p_user and quest_step in ('ready','completed');
  else
    select reflection into excerpt from public.academy_journeys where user_id=p_user and stage='completed';
  end if;
  if excerpt is null then raise exception '먼저 내 질문 또는 완료한 의뢰의 회고를 남겨 주세요.'; end if;
  insert into public.academy_self_discoveries(user_id,source,statement,source_excerpt)
    values(p_user,p_source,btrim(p_statement),excerpt)
    on conflict(user_id,source) do update set previous_statement=academy_self_discoveries.statement,
      statement=excluded.statement,source_excerpt=excluded.source_excerpt,revision=academy_self_discoveries.revision+1,updated_at=now()
    returning * into r;
  return to_jsonb(r);
end;
$$;


ALTER FUNCTION "public"."academy_discovery_write"("p_user" "uuid", "p_source" "text", "p_revision" integer, "p_statement" "text", "p_memory" boolean) OWNER TO "postgres";


