CREATE OR REPLACE FUNCTION "public"."academy_encouragement_claim"("p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare d date:=(now() at time zone 'Asia/Seoul')::date; c public.academy_luon_encouragements;
begin
 if not exists(select 1 from public.profiles where id=p_user and role in ('student','teacher','admin')) then raise exception 'Student required' using errcode='42501'; end if;
 insert into public.academy_luon_encouragements(user_id,day) values(p_user,d) on conflict do nothing;
 select * into strict c from public.academy_luon_encouragements where user_id=p_user and day=d for update;
 if c.status='ready' or c.lease_until>now() then return jsonb_build_object('claimed',false,'entry',to_jsonb(c)-'lease_token'); end if;
 update public.academy_luon_encouragements set status='generating',lease_token=gen_random_uuid(),lease_until=now()+interval '75 seconds'
 where user_id=p_user and day=d returning * into c;
 return jsonb_build_object('claimed',true,'token',c.lease_token,'entry',to_jsonb(c)-'lease_token');
end $$;


