 update public.academy_luon_encouragements set message=btrim(p_message),status=case when p_message is null then 'failed' else 'ready' end,lease_token=null,lease_until=null
 where user_id=p_user and day=p_day returning * into c;
 return to_jsonb(c)-'lease_token';
