    AS $$
begin
 if not exists(select 1 from public.profiles where id=auth.uid() and role in ('teacher','admin')) then raise exception 'Staff experience required' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(data||jsonb_build_object('id',id,'created_at',created_at,'updated_at',updated_at) order by created_at desc) from public.academy_experience_records where owner_id=auth.uid() and kind=p_kind),'[]');
end $$;


