CREATE OR REPLACE FUNCTION "public"."academy_progress_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  steps text[] := array['accepted','read','ready','completed'];
begin
  -- ON DELETE SET NULL may detach the source without deleting earned progress.
  if new.activity_id is null and old.activity_id is not null and
     new.quest_step = old.quest_step and new.question = old.question and new.user_id = old.user_id then
    new.updated_at := now();
    return new;
  end if;
  if new.user_id <> old.user_id or
     array_position(steps,new.quest_step) <> array_position(steps,old.quest_step) + 1 then
    raise exception 'Invalid academy quest transition' using errcode = '23514';
  end if;
  if new.quest_step = 'read' and new.activity_id is null then
    raise exception 'Choose a readable activity first' using errcode = '23514';
  end if;
  if old.quest_step <> 'accepted' and new.activity_id is distinct from old.activity_id then
    raise exception 'Quest source cannot be replaced' using errcode = '23514';
  end if;
  if new.quest_step = 'completed' and new.question is distinct from old.question then
    raise exception 'Claim the recorded discovery' using errcode = '23514';
  end if;
  new.updated_at := now();
  return new;
end $$;


