CREATE OR REPLACE FUNCTION "public"."academy_roommate_save_assessment"("p_user" "uuid", "p_request" "uuid", "p_kind" "text", "p_answers" "jsonb", "p_scores" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare r public.academy_self_assessments;
begin
 if not exists(select 1 from public.profiles where id=p_user and role in ('student','teacher','admin')) then raise exception 'Student account required' using errcode='42501'; end if;
 insert into public.academy_self_assessments(user_id,request_id,kind,version,answers,scores)
 values(p_user,p_request,p_kind,'serin-v1',p_answers,p_scores) on conflict(user_id,request_id) do nothing;
 select * into strict r from public.academy_self_assessments where user_id=p_user and request_id=p_request;
 if r.kind is distinct from p_kind or r.answers is distinct from p_answers then raise exception 'Request already used for different answers'; end if;
 return to_jsonb(r);
end $$;


