    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare r public.academy_tutorials;
begin
  if not exists(select 1 from public.profiles where id=p_user and role in ('student','teacher','admin')) then raise exception '학생 계정에서 안내를 이어갈 수 있어요.' using errcode='42501'; end if;
  if p_event is null or p_event not in ('telescope','pause','resume') then raise exception '안내 행동을 확인해 주세요.'; end if;
  insert into public.academy_tutorials(user_id,telescope_seen,paused) values(p_user,p_event='telescope',p_event='pause')
    on conflict(user_id) do update set telescope_seen=academy_tutorials.telescope_seen or p_event='telescope',
      paused=case when p_event='pause' then true when p_event='resume' then false else academy_tutorials.paused end,updated_at=now() returning * into r;
  return to_jsonb(r);
end;
$$;


