 if academy_private.player_code(auth.uid()) is null then raise exception 'Academy account required' using errcode='42501'; end if;
 return jsonb_build_object('orders',coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc) from (select o.*,coalesce(p.name,p.nickname,'체험자') as student_name,split_part(p.email,'@',1) as student_code,(select count(*) from public.academy_workshop_commissions c where c.order_id=o.id) as commission_count,(select coalesce(sum(amount),0) from public.academy_workshop_commissions c where c.order_id=o.id) as commission_coins from public.academy_workshop_orders o join public.profiles p on p.id=o.student_id where o.student_id=auth.uid() and (p_order is null or o.id=p_order) order by o.created_at desc limit 50 offset greatest(0,coalesce(p_offset,0))) r),'[]'::jsonb),'total',(select count(*) from public.academy_workshop_orders where student_id=auth.uid()));
end $$;


