CREATE OR REPLACE FUNCTION "public"."account_link_pre_request"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role   text := coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role', '');
  v_uid    uuid;
  v_status text;
  v_path   text;
  v_method text := upper(coalesce(current_setting('request.method', true), ''));
  v_schema text;
  v_contest boolean;
  v_client text;
begin
  if v_role <> 'authenticated' then
    return;  -- anon·service_role 은 이 차단막의 대상이 아니다
  end if;

  v_uid := auth.uid();
  if v_uid is null then
    return;
  end if;

  -- 공모전판(contest 스키마) 격리 (2026-10-15). 공모전 계정 = contest.profiles 에 있는 계정 —
  -- 공모전 스키마만 쓰고(운영 public 은 연결 절차 경로까지 전부 거부), 운영 계정은 공모전 스키마를 못 쓴다.
  -- 요청 스키마 = 읽기는 Accept-Profile, 쓰기·RPC 는 Content-Profile(없으면 public).
  -- 판정이 터지면 종전 동작으로 떨어진다(공모전 계정은 명단 미연결이라 아래에서 그대로 막힌다).
  begin
    v_schema := coalesce(current_setting('request.headers', true)::jsonb ->> (case when v_method in ('GET', 'HEAD') then 'accept-profile' else 'content-profile' end), 'public');
    v_contest := exists (select 1 from contest.profiles where id = v_uid);
  exception when others then
    raise warning 'account_link_pre_request: 공모전 판정 실패 (%)', sqlerrm;
    v_schema := 'public'; v_contest := false;
  end;
  if v_contest then
    if v_schema = 'contest' or v_method = 'OPTIONS' then
      return;
    end if;
    raise exception using errcode = '42501', message = '공모전 계정은 공모전 데이터만 쓸 수 있습니다.', hint = 'CONTEST_ONLY';
  elsif v_schema = 'contest' then
    raise exception using errcode = '42501', message = '공모전 데이터는 공모전 계정만 쓸 수 있습니다.', hint = 'CONTEST_ONLY';
  end if;

  v_path := regexp_replace(coalesce(current_setting('request.path', true), ''), '^/rest/v1', '');

  -- MCP 에이전트 토큰 (2026-10-18). Supabase OAuth 2.1 서버가 발급한 토큰에만 client_id 클레임이 있다.
  -- 이 토큰으로는 MCP 전용 RPC(public.mcp_*)만 부를 수 있다 — 토큰이 에이전트 밖으로 새도 다른 표에 못 닿는다.
  -- 통과해도 return 하지 않는다: 아래 명단 연결 판정을 그대로 거친다. 판정은 실패해도 닫는다(이 분기는 열 이유가 없다).
  v_client := nullif(current_setting('request.jwt.claims', true)::jsonb ->> 'client_id', '');
  if v_client is not null
     and not (v_method = 'OPTIONS' or (v_path like '/rpc/mcp\_%' and v_method in ('GET', 'POST')))
  then
    raise exception using errcode = '42501',
      message = '에이전트(MCP) 연결로는 허용된 도구만 쓸 수 있습니다.', hint = 'MCP_TOOLS_ONLY';
  end if;

  -- 판정 자체가 실패하면(예기치 않은 오류) 열어 둔다 — 이 함수는 모든 요청 앞에 서므로
  -- 여기서 터지면 연결된 사용자까지 전부 멈춘다. ②가 여전히 데이터 권한을 지킨다.
  begin
    v_status := public.account_link_status(v_uid);
  exception when others then
    raise warning 'account_link_pre_request: 판정 실패 (%), 통과시킴', sqlerrm;
    return;
  end;

  if v_status = 'linked' then
    return;
  end if;

  -- 연결 절차(프로필 로드 → 개인정보 동의 → 이름 등록·연결)에 필요한 것만 허용한다.
  if (v_path = '/profiles'                and v_method in ('GET', 'HEAD', 'PATCH', 'POST'))
     or (v_path = '/user_resource')
     or (v_path = '/privacy_policy_versions' and v_method in ('GET', 'HEAD'))
     or (v_path = '/user_privacy_consents'   and v_method in ('GET', 'HEAD', 'POST'))
     or (v_path = '/system_settings'         and v_method in ('GET', 'HEAD'))
     or v_path in ('/rpc/my_account_link_status',
                   '/rpc/find_self_linkable_resource',
                   '/rpc/check_resource_duplicate_connection')
     or v_method = 'OPTIONS'
  then
    -- 에이전트 토큰은 연결 절차에도 쓰지 않는다(위 분기가 이미 mcp_* 만 남겼다).
    if v_client is null then
      return;
    end if;
  end if;

  raise exception using
    errcode = '42501',
    message = case v_status
      when 'inactive' then '비활성 처리된 계정입니다. 관리자에게 문의하세요.'
      else '교직원·학생 명단에 연결되지 않은 계정입니다. 이름을 등록하거나 관리자에게 문의하세요.'
    end,
    hint = case v_status when 'inactive' then 'ACCOUNT_INACTIVE' else 'ACCOUNT_NOT_LINKED' end;
end;
$$;


ALTER FUNCTION "public"."account_link_pre_request"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."account_link_status"("p_uid" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with me as (
    select p.id, p.role, split_part(coalesce(p.email, ''), '@', 1) as prefix
    from public.profiles p
    where p.id = p_uid
  ),
  student_res as (
    select r.status::text as status
    from me
    join public.resource r
      on r.type = 'student'
     and me.role = 'student'
     and me.prefix <> ''
     and r.meta->>'id' = me.prefix
    union all
    select r.status::text
    from me
    join public.user_resource ur on ur.user_id = me.id
    join public.resource r on r.id = ur.resource_id and r.type = 'student'
    where me.role = 'student'
  ),
  faculty_res as (
    select r.type
    from me
    join public.user_resource ur on ur.user_id = me.id
    join public.resource r on r.id = ur.resource_id
    where me.role in ('teacher', 'staff', 'admin')
  )
  select case
    when not exists (select 1 from me) then 'unlinked'
    when (select role from me) = 'student' then
      case
        when exists (select 1 from student_res where status = 'active') then 'linked'
        when exists (select 1 from student_res) then 'inactive'
        else 'unlinked'
      end
    when exists (select 1 from faculty_res where type in ('teacher', 'staff')) then 'linked'
    when exists (select 1 from faculty_res where type = 'inactive') then 'inactive'
    else 'unlinked'
  end;
$$;


ALTER FUNCTION "public"."account_link_status"("p_uid" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."seaton_badge_acquire" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "student_id" "uuid" NOT NULL,
    "badge_id" integer NOT NULL,
    "acquired_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."seaton_badge_acquire" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_badge"("p_badge_id" integer) RETURNS "public"."seaton_badge_acquire"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id uuid := auth.uid();
  v_required_temp numeric;
  v_current_temp numeric;
  v_result seaton_badge_acquire;
BEGIN
  SELECT temperature INTO v_required_temp FROM seaton_badge WHERE id = p_badge_id;
  IF v_required_temp IS NULL THEN
    RAISE EXCEPTION '존재하지 않는 뱃지입니다.';
  END IF;

  v_current_temp := calculate_student_temperature(v_student_id);
  IF v_current_temp < v_required_temp THEN
    RAISE EXCEPTION '아직 온도가 부족합니다. (필요: %, 현재: %)', v_required_temp, v_current_temp;
  END IF;

  INSERT INTO seaton_badge_acquire (student_id, badge_id)
  VALUES (v_student_id, p_badge_id)
  ON CONFLICT (student_id, badge_id) DO NOTHING;

  SELECT * INTO v_result FROM seaton_badge_acquire
  WHERE student_id = v_student_id AND badge_id = p_badge_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."acquire_badge"("p_badge_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."act_on_approval_step"("p_request_id" "uuid", "p_action" "text", "p_signature" "jsonb", "p_comment" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request  public.approval_request;
  v_step     public.approval_step;
  v_my_name  text;
  v_remaining int;
BEGIN
  IF p_action NOT IN ('approve', 'reject') THEN
    RAISE EXCEPTION '알 수 없는 동작입니다: %', p_action USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_request FROM public.approval_request WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '결재 요청을 찾을 수 없습니다.' USING ERRCODE = 'P0002';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION '이미 종료된 결재입니다(상태: %).', v_request.status USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_step
  FROM public.approval_step
  WHERE request_id = p_request_id AND order_index = v_request.current_order;
  IF NOT FOUND THEN
    RAISE EXCEPTION '결재 단계를 찾을 수 없습니다.' USING ERRCODE = 'P0002';
  END IF;

  v_my_name := public.current_profile_name();
  IF NOT (
    v_step.approver_user_id = auth.uid()
    OR (v_step.approver_user_id IS NULL AND v_step.approver_name = v_my_name)
  ) THEN
    RAISE EXCEPTION '지금은 %님의 결재 차례입니다.', v_step.approver_name USING ERRCODE = '42501';
  END IF;

  IF p_action = 'approve' THEN
    IF p_signature IS NULL OR jsonb_typeof(p_signature -> 's') <> 'array' THEN
      RAISE EXCEPTION '서명이 필요합니다.' USING ERRCODE = '22023';
    END IF;

    UPDATE public.approval_step
       SET status = 'approved', signature = p_signature, comment = p_comment, acted_at = now()
     WHERE id = v_step.id;

    SELECT count(*) INTO v_remaining
    FROM public.approval_step
    WHERE request_id = p_request_id AND order_index > v_step.order_index;

    IF v_remaining = 0 THEN
      UPDATE public.approval_request
         SET status = 'approved', decided_at = now(), updated_at = now()
       WHERE id = p_request_id;
    ELSE
      UPDATE public.approval_request
         SET current_order = v_step.order_index + 1, updated_at = now()
       WHERE id = p_request_id;
    END IF;
  ELSE
    UPDATE public.approval_step
       SET status = 'rejected', comment = p_comment, acted_at = now()
     WHERE id = v_step.id;

    UPDATE public.approval_request
       SET status = 'rejected', decided_at = now(), updated_at = now()
     WHERE id = p_request_id;
  END IF;

  SELECT * INTO v_request FROM public.approval_request WHERE id = p_request_id;
  RETURN jsonb_build_object(
    'request_id', v_request.id,
    'status', v_request.status,
    'current_order', v_request.current_order
  );
END;
$$;


ALTER FUNCTION "public"."act_on_approval_step"("p_request_id" "uuid", "p_action" "text", "p_signature" "jsonb", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."act_on_signature_request"("p_request_id" "uuid", "p_action" "text", "p_signature" "jsonb" DEFAULT NULL::"jsonb", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request   public.signature_request;
  v_signer    public.signature_signer;
  v_my_name   text;
  v_remaining int;
  v_next      int;
begin
  if p_action not in ('sign', 'reject') then
    raise exception '알 수 없는 동작입니다: %', p_action using errcode = '22023';
  end if;

  select * into v_request from public.signature_request where id = p_request_id for update;
  if not found then
    raise exception '서명 요청을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if v_request.status <> 'pending' then
    raise exception '이미 종료된 요청입니다(상태: %).', v_request.status using errcode = '22023';
  end if;

  v_my_name := public.current_profile_name();

  -- **현재 그룹 안에서 나를 찾는다** — 결재와 달리 같은 순번에 여러 명이 있을 수 있으므로
  -- "그 순번의 유일한 행"을 집으면 안 된다.
  select * into v_signer
  from public.signature_signer s
  where s.request_id = p_request_id
    and s.order_index = v_request.current_order
    and s.status = 'pending'
    and (
      s.signer_user_id = auth.uid()
      or (s.signer_user_id is null and s.signer_name = v_my_name)
    )
  limit 1;

  if not found then
    raise exception '지금 서명할 차례가 아니거나 이미 서명했습니다.' using errcode = '42501';
  end if;

  if p_action = 'sign' then
    if p_signature is null or jsonb_typeof(p_signature -> 's') <> 'array' then
      raise exception '서명이 필요합니다.' using errcode = '22023';
    end if;

    update public.signature_signer
       set status = 'signed', signature = p_signature, comment = p_comment, acted_at = now()
     where id = v_signer.id;

    -- 같은 그룹에 아직 안 한 사람이 있으면 차례를 넘기지 않는다(= 동시 서명)
    select count(*) into v_remaining
    from public.signature_signer
    where request_id = p_request_id
      and order_index = v_request.current_order
      and status = 'pending';

    if v_remaining = 0 then
      select min(order_index) into v_next
      from public.signature_signer
      where request_id = p_request_id and order_index > v_request.current_order;

      if v_next is null then
        update public.signature_request
           set status = 'completed', decided_at = now(), updated_at = now()
         where id = p_request_id;
      else
        update public.signature_request
           set current_order = v_next, updated_at = now()
         where id = p_request_id;
      end if;
    else
      update public.signature_request set updated_at = now() where id = p_request_id;
    end if;
  else
    update public.signature_signer
       set status = 'rejected', comment = p_comment, acted_at = now()
     where id = v_signer.id;

    -- 한 명이라도 거절하면 요청 전체가 끝난다(결재와 같은 결정 — 부분 진행은 문서를 애매하게 만든다)
    update public.signature_request
       set status = 'rejected', decided_at = now(), updated_at = now()
     where id = p_request_id;
  end if;

  select * into v_request from public.signature_request where id = p_request_id;
  return jsonb_build_object(
    'request_id', v_request.id,
    'status', v_request.status,
    'current_order', v_request.current_order
  );
end;
$$;


ALTER FUNCTION "public"."act_on_signature_request"("p_request_id" "uuid", "p_action" "text", "p_signature" "jsonb", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activity_column_names"() RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select array_agg(attname::text order by attnum)
    from pg_attribute
   where attrelid = 'public.activity'::regclass
     and attnum > 0
     and not attisdropped;
$$;


