COMMENT ON FUNCTION "public"."activity_column_names"() IS '회귀 전용 — 목록 조회 열 목록(ACTIVITY_LIST_COLUMNS)과 실제 표 열을 대조한다.';



CREATE OR REPLACE FUNCTION "public"."activity_lineage_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  cursor_id uuid := NEW.lineage_parent_id;
  hops int := 0;
BEGIN
  WHILE cursor_id IS NOT NULL AND hops < 64 LOOP
    IF cursor_id = NEW.id THEN
      RAISE EXCEPTION '활동 계보에 순환이 생깁니다 (activity %)', NEW.id USING ERRCODE = '23514';
    END IF;
    SELECT a.lineage_parent_id INTO cursor_id FROM public.activity a WHERE a.id = cursor_id;
    hops := hops + 1;
  END LOOP;
  IF hops >= 64 THEN
    RAISE EXCEPTION '활동 계보가 너무 깊습니다 (64단계 초과)' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."activity_lineage_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_assignees_meta"("p_task_id" "uuid", "p_assignee_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    current_meta JSONB;
    current_assignees JSONB;
    updated_assignees JSONB;
    assignee_id UUID;
    existing_ids UUID[];
    new_assignee JSONB;
    resource_name TEXT;
BEGIN
    -- Get current meta and assignees
    SELECT meta INTO current_meta
    FROM task
    WHERE id = p_task_id;

    IF current_meta IS NULL THEN
        RAISE EXCEPTION 'Task not found: %', p_task_id;
    END IF;

    current_assignees := COALESCE(current_meta->'assignees', '[]'::JSONB);

    -- Extract existing assignee IDs
    SELECT array_agg((assignee->>'id')::UUID)
    INTO existing_ids
    FROM jsonb_array_elements(current_assignees) AS assignee;

    -- Start with current assignees
    updated_assignees := current_assignees;

    -- Add new assignees that don't already exist
    FOREACH assignee_id IN ARRAY p_assignee_ids
    LOOP
        IF assignee_id != ALL(COALESCE(existing_ids, ARRAY[]::UUID[])) THEN
            -- Get resource name
            SELECT name INTO resource_name
            FROM resource
            WHERE id = assignee_id;

            new_assignee := jsonb_build_object(
                'id', assignee_id,
                'name', COALESCE(resource_name, 'Unknown'),
                'status', 'pending',
                'assigned_at', NOW(),
                'completed_at', NULL
            );

            updated_assignees := updated_assignees || new_assignee;
        END IF;
    END LOOP;

    -- Update the task meta only
    UPDATE task
    SET meta = jsonb_set(current_meta, '{assignees}', updated_assignees),
        updated_at = NOW()
    WHERE id = p_task_id;
END;
$$;


ALTER FUNCTION "public"."add_assignees_meta"("p_task_id" "uuid", "p_assignee_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."add_assignees_meta"("p_task_id" "uuid", "p_assignee_ids" "uuid"[]) IS 'Add assignees to task.meta.assignees with resource name enrichment';



CREATE OR REPLACE FUNCTION "public"."add_custom_subject_to_slot"("p_slot_id" "uuid", "p_subject" "text", "p_category" "text", "p_credits" integer, "p_semester" integer, "p_academic_year" integer, "p_grade" integer, "p_subject_type" "text" DEFAULT NULL::"text", "p_grading_type" "text" DEFAULT NULL::"text", "p_area" "text" DEFAULT NULL::"text", "p_hours" integer DEFAULT NULL::integer, "p_override_capacity" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_curriculum_id uuid;
  v_subject_id uuid;
  v_curriculum_created boolean := false;
  v_subject_created boolean := false;
  v_attached boolean := false;
  v_inserted_count integer;
BEGIN
  -- 1. school_curriculum 매칭 (없으면 INSERT)
  SELECT id INTO v_curriculum_id
    FROM public.school_curriculum
    WHERE academic_year = p_academic_year
      AND grade = p_grade
      AND semester = p_semester
      AND subject = p_subject
    LIMIT 1;

  IF v_curriculum_id IS NULL THEN
    INSERT INTO public.school_curriculum (
      academic_year, grade, semester, subject, category, credits,
      subject_type, grading_type, area, hours
    ) VALUES (
      p_academic_year, p_grade, p_semester, p_subject, p_category, p_credits,
      p_subject_type, p_grading_type, p_area, p_hours
    ) RETURNING id INTO v_curriculum_id;
    v_curriculum_created := true;
  END IF;

  -- 2. course_selectable_subject 매칭 (school_curriculum_id 또는 이름) 또는 생성
  SELECT id INTO v_subject_id
    FROM public.course_selectable_subject
    WHERE school_curriculum_id = v_curriculum_id
       OR name = p_subject
    LIMIT 1;

  IF v_subject_id IS NULL THEN
    INSERT INTO public.course_selectable_subject (
      name, category_code, school_curriculum_id, is_active, display_order
    ) VALUES (
      p_subject, p_category, v_curriculum_id, true, 0
    )
    ON CONFLICT (name) DO UPDATE
      SET school_curriculum_id = COALESCE(
        public.course_selectable_subject.school_curriculum_id,
        EXCLUDED.school_curriculum_id
      )
    RETURNING id INTO v_subject_id;
    v_subject_created := true;
  END IF;

  -- 3. slot에 attach (이미 있으면 skip)
  INSERT INTO public.course_selection_slot_subject (
    slot_id, selectable_subject_id, semester, override_capacity
  ) VALUES (
    p_slot_id, v_subject_id, p_semester, p_override_capacity
  )
  ON CONFLICT (slot_id, selectable_subject_id, semester) DO NOTHING;

  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
  v_attached := v_inserted_count > 0;

  RETURN jsonb_build_object(
    'curriculum_id', v_curriculum_id,
    'subject_id', v_subject_id,
    'subject_name', p_subject,
    'curriculum_created', v_curriculum_created,
    'subject_created', v_subject_created,
    'attached', v_attached
  );
END $$;


ALTER FUNCTION "public"."add_custom_subject_to_slot"("p_slot_id" "uuid", "p_subject" "text", "p_category" "text", "p_credits" integer, "p_semester" integer, "p_academic_year" integer, "p_grade" integer, "p_subject_type" "text", "p_grading_type" "text", "p_area" "text", "p_hours" integer, "p_override_capacity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_performance_indexes"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Resource meta indexes
  CREATE INDEX IF NOT EXISTS idx_resource_meta_section 
    ON resource USING GIN ((meta->'section'));
  CREATE INDEX IF NOT EXISTS idx_resource_meta_grade 
    ON resource USING BTREE ((meta->>'grade'));
  CREATE INDEX IF NOT EXISTS idx_resource_meta_class 
    ON resource USING BTREE ((meta->>'class'));
  CREATE INDEX IF NOT EXISTS idx_resource_meta_email 
    ON resource USING BTREE ((meta->>'email'));

  -- Section meta indexes  
  CREATE INDEX IF NOT EXISTS idx_section_meta_grade 
    ON section USING BTREE ((meta->>'grade'));
  CREATE INDEX IF NOT EXISTS idx_section_meta_class 
    ON section USING BTREE ((meta->>'class'));

  -- Meeting meta indexes
  CREATE INDEX IF NOT EXISTS idx_meeting_meta_participants 
    ON meeting USING GIN ((meta->'participants'));
  CREATE INDEX IF NOT EXISTS idx_meeting_creator 
    ON meeting (creator);

  RETURN 'Performance indexes added successfully';
END;
$$;


ALTER FUNCTION "public"."add_performance_indexes"() OWNER TO "postgres";


