CREATE OR REPLACE FUNCTION "public"."admin_ai_log_feed"("p_feature" "text" DEFAULT NULL::"text", "p_since" timestamp with time zone DEFAULT ("now"() - '7 days'::interval), "p_problems_only" boolean DEFAULT false, "p_limit" integer DEFAULT 100, "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("source" "text", "id" "text", "created_at" timestamp with time zone, "feature" "text", "fn" "text", "action" "text", "label" "text", "app_path" "text", "level" "text", "outcome" "text", "provider" "text", "model" "text", "http_status" integer, "duration_ms" integer, "finish_reason" "text", "prompt_tokens" integer, "completion_tokens" integer, "reasoning_tokens" integer, "message" "text", "user_id" "uuid", "user_name" "text", "user_role" "text", "student_id" "text", "detail" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null or not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;

  return query
  select x.source, x.id, x.created_at, x.feature, x.fn, x.action, x.label, x.app_path, x.level, x.outcome,
         x.provider, x.model, x.http_status, x.duration_ms, x.finish_reason, x.prompt_tokens, x.completion_tokens,
         x.reasoning_tokens, x.message, x.user_id, pr.name::text, pr.role::text, x.student_id, x.detail
  from (
    select 'server'::text as source, l.id::text as id, l.created_at, l.feature, l.fn, l.action, l.label, l.app_path,
           l.level, l.outcome, l.provider, l.model, l.http_status, l.duration_ms, l.finish_reason,
           l.prompt_tokens, l.completion_tokens, l.reasoning_tokens, l.message, l.user_id, l.student_id, l.detail
    from public.ai_call_log l
    where l.created_at >= p_since
      and (p_before is null or l.created_at < p_before)
      and (p_feature is null or l.feature = p_feature)
      and (not p_problems_only or l.level = 'request' or l.outcome <> 'success')
    union all
    -- 브라우저가 알아챈 실패(응답 해석 실패 등) — 서버 기록에는 «성공»으로 남은 호출일 수 있다
    select 'client', e.id::text, e.created_at, e.feature, null, e.action, null, null,
           'client', 'error', e.provider, e.model, null, null, null,
           null, null, null, e.message, e.created_by, e.student_id, e.detail
    from public.ai_error_log e
    where e.created_at >= p_since
      and (p_before is null or e.created_at < p_before)
      and (p_feature is null or e.feature = p_feature)
    order by 3 desc
    limit greatest(1, least(coalesce(p_limit, 100), 500))
  ) x
  left join public.profiles pr on pr.id = x.user_id
  order by x.created_at desc;
end;
$$;


ALTER FUNCTION "public"."admin_ai_log_feed"("p_feature" "text", "p_since" timestamp with time zone, "p_problems_only" boolean, "p_limit" integer, "p_before" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_ai_log_summary"("p_since" timestamp with time zone) RETURNS TABLE("feature" "text", "calls" bigint, "ok_calls" bigint, "error_calls" bigint, "empty_calls" bigint, "truncated_calls" bigint, "request_failures" bigint, "client_errors" bigint, "users" bigint, "p50_ms" integer, "p90_ms" integer, "prompt_tokens" bigint, "completion_tokens" bigint, "last_at" timestamp with time zone, "last_problem_at" timestamp with time zone, "last_problem_message" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null or not public.is_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;

  return query
  with server as (
    select l.feature, l.level, l.outcome, l.duration_ms, l.prompt_tokens, l.completion_tokens,
           l.user_id, l.created_at, l.message
    from public.ai_call_log l
    where l.created_at >= p_since
  ),
  client as (
    select e.feature, e.created_by as user_id, e.created_at, e.message
    from public.ai_error_log e
    where e.created_at >= p_since
  ),
  problems as (
    select s.feature, s.created_at, s.message from server s where s.level = 'request' or s.outcome <> 'success'
    union all
    select c.feature, c.created_at, c.message from client c
  ),
  last_problem as (
    select distinct on (p.feature) p.feature, p.created_at, p.message
    from problems p
    order by p.feature, p.created_at desc
  ),
  features as (
    select s.feature from server s union select c.feature from client c
  )
  select
    f.feature,
    count(s.*) filter (where s.level = 'call'),
    count(s.*) filter (where s.level = 'call' and s.outcome = 'success'),
    count(s.*) filter (where s.level = 'call' and s.outcome = 'error'),
    count(s.*) filter (where s.level = 'call' and s.outcome = 'empty'),
    count(s.*) filter (where s.level = 'call' and s.outcome = 'truncated'),
    count(s.*) filter (where s.level = 'request'),
    (select count(*) from client c where c.feature = f.feature),
    (select count(distinct u.user_id) from (
       select s2.user_id from server s2 where s2.feature = f.feature
       union all select c2.user_id from client c2 where c2.feature = f.feature) u),
    (percentile_disc(0.5) within group (order by s.duration_ms) filter (where s.level = 'call' and s.outcome = 'success'))::integer,
    (percentile_disc(0.9) within group (order by s.duration_ms) filter (where s.level = 'call' and s.outcome = 'success'))::integer,
    coalesce(sum(s.prompt_tokens) filter (where s.level = 'call'), 0)::bigint,
    coalesce(sum(s.completion_tokens) filter (where s.level = 'call'), 0)::bigint,
    greatest(max(s.created_at), (select max(c.created_at) from client c where c.feature = f.feature)),
    lp.created_at,
    lp.message
  from features f
  left join server s on s.feature = f.feature
  left join last_problem lp on lp.feature = f.feature
  group by f.feature, lp.created_at, lp.message
  order by greatest(max(s.created_at), (select max(c.created_at) from client c where c.feature = f.feature)) desc nulls last;
end;
$$;


ALTER FUNCTION "public"."admin_ai_log_summary"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_coin_economy_set"("p_values" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  u uuid := economy_private.require_admin();
  k text;
  raw jsonb;
  v integer;
  s public.coin_economy_setting;
  changed integer := 0;
  bad text;
begin
  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception '바꿀 값을 보내 주세요.'; end if;
  for k, raw in select * from jsonb_each(p_values) loop
    select * into s from public.coin_economy_setting where key = k for update;
    if not found then raise exception '모르는 설정이에요: %', k; end if;
    if jsonb_typeof(raw) <> 'number' or (raw #>> '{}') !~ '^-?[0-9]+$' then
      raise exception '«%» 는 정수로 적어 주세요.', s.label;
    end if;
    v := (raw #>> '{}')::integer;
    if v < s.min_value or v > s.max_value then
      raise exception '«%» 는 %~% 사이여야 해요.', s.label, s.min_value, s.max_value;
    end if;
    if v <> s.value then
      update public.coin_economy_setting set value = v, updated_at = now(), updated_by = u where key = k;
      insert into public.coin_economy_setting_log(key, old_value, new_value, changed_by) values (k, s.value, v, u);
      changed := changed + 1;
    end if;
  end loop;
  -- 겹침 환급이 한 번 값보다 크면 뽑을수록 코인이 는다(무한 증식) — 서버가 막는다
  select string_agg(m, ', ') into bad from unnest(array['all', 'character', 'device', 'shell', 'deco']) m
   where economy_private.num('tama.gacha.' || m || '.refund') > economy_private.num('tama.gacha.' || m || '.price');
  if bad is not null then raise exception '가챠 겹침 환급은 한 번 값보다 클 수 없어요(%).', bad; end if;
  return jsonb_build_object('changed', changed);
end $_$;


ALTER FUNCTION "public"."admin_coin_economy_set"("p_values" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_coin_economy_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  start_coins integer := coalesce((select column_default::integer from information_schema.columns
                                    where table_schema = 'public' and table_name = 'academy_user_stats' and column_name = 'coins'), 0);
begin
  perform economy_private.require_admin();
  return (
    with earn as (select * from economy_private.earn_rows(null)),
    spend as (select * from economy_private.spend_rows(null)),
    revoked_rows as (select l.user_id, -l.delta as amount, l.kind from public.wallet_ledger l
                where l.delta < 0 and l.kind in ('seaton_attendance_reversal', 'admin_revoke')),
    wallets as (select count(*)::integer as n, coalesce(sum(coins), 0)::integer as coins from public.academy_user_stats),
    roy as (
      select l.user_id, l.delta, l.created_at, split_part(l.source_id, ':', 2) as log_id from public.wallet_ledger l where l.kind = 'tama_royalty'
    )
    select jsonb_build_object(
      'start_per_wallet', start_coins,
      'wallets', w.n,
      'circulating', w.coins,
      'started', w.n * start_coins,
      'earned', (select coalesce(sum(amount), 0) from earn),
      'spent', (select coalesce(sum(amount), 0) from spend),
      'spent_approx', (select coalesce(bool_or(approx), false) from spend),
      'revoked', (select coalesce(sum(amount), 0) from revoked_rows),
      'royalty', (select coalesce(sum(delta), 0) from roy),
      'earn_by_kind', coalesce((select jsonb_agg(x order by x.amount desc) from (
          select kind, sum(amount)::integer as amount, count(*)::integer as times, count(distinct user_id)::integer as people,
                 sum(amount) filter (where at > now() - interval '7 days')::integer as week
            from earn group by kind) x), '[]'::jsonb),
      'spend_by_kind', coalesce((select jsonb_agg(x order by x.amount desc) from (
          select kind, sum(amount)::integer as amount, count(*)::integer as times, count(distinct user_id)::integer as people,
                 sum(amount) filter (where at > now() - interval '7 days')::integer as week, bool_or(approx) as approx
            from spend group by kind) x), '[]'::jsonb),
      'daily', coalesce((select jsonb_agg(x order by x.day) from (
          select d::date as day,
                 (select coalesce(sum(amount), 0) from earn e where (e.at at time zone 'Asia/Seoul')::date = d::date)::integer as earned,
                 (select coalesce(sum(amount), 0) from spend s where (s.at at time zone 'Asia/Seoul')::date = d::date)::integer as spent
            from generate_series((now() at time zone 'Asia/Seoul')::date - 13, (now() at time zone 'Asia/Seoul')::date, interval '1 day') d) x), '[]'::jsonb),
      'royalty_items', coalesce((select jsonb_agg(x order by x.paid desc, x.name) from (
          select i.id, i.name, i.slot, i.rarity,
                 coalesce(nullif(btrim(p.name), ''), split_part(p.email, '@', 1)) as creator,
                 (select count(*) from public.tama_gacha_log g where g.item_id = i.id and g.owner <> i.creator and g.price > 0)::integer as draws,
                 coalesce((select sum(r.delta) from roy r join public.tama_gacha_log g on g.id::text = r.log_id where g.item_id = i.id), 0)::integer as paid
            from public.tama_item i left join public.profiles p on p.id = i.creator
           where i.creator is not null) x), '[]'::jsonb),
      'royalty_people', (select count(distinct user_id) from roy)
    ) from wallets w
  );
end $$;


ALTER FUNCTION "public"."admin_coin_economy_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_coin_grant"("p_users" "uuid"[], "p_amount" integer, "p_note" "text", "p_notify" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := economy_private.require_admin();
  batch uuid := gen_random_uuid();
  target uuid;
  moved integer;
  total integer := 0;
  n integer := 0;
  res uuid;
begin
  if p_amount is null or p_amount = 0 or p_amount not between -10000 and 10000 then
    raise exception '코인은 -10000~10000 사이(0 제외)로 적어 주세요.';
  end if;
  if p_note is null or char_length(btrim(p_note)) not between 1 and 200 then raise exception '사유를 적어 주세요(200자까지).'; end if;
  if p_users is null or cardinality(p_users) not between 1 and 2000 then raise exception '받을 사람을 골라 주세요.'; end if;
  for target in select distinct x from unnest(p_users) x
    where exists (select 1 from public.profiles p where p.id = x and p.role in ('student', 'teacher', 'staff', 'admin')) order by x loop
    moved := wallet_private.apply(target, p_amount, case when p_amount > 0 then 'admin_grant' else 'admin_revoke' end,
                                  'admin', batch::text || ':' || target::text, true, btrim(p_note));
    total := total + moved;
    n := n + 1;
    if p_notify and moved > 0 then
      res := push_private.resource_of_user(target);
      if res is not null then
        insert into public.notification_events(resource_id, type, title, message, priority, meta)
          values (res, 'coin_grant', format('코인 %s개를 받았어요', moved), btrim(p_note), 'low', jsonb_build_object('amount', moved));
      end if;
    end if;
  end loop;
  if n = 0 then raise exception '받을 수 있는 사람이 없어요.'; end if;
  insert into public.coin_admin_grant(id, admin_id, amount, note, user_count, moved_total) values (batch, u, p_amount, btrim(p_note), n, total);
  return jsonb_build_object('batch', batch, 'users', n, 'moved', total);
end $$;


ALTER FUNCTION "public"."admin_coin_grant"("p_users" "uuid"[], "p_amount" integer, "p_note" "text", "p_notify" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_coin_history"("p_user" "uuid", "p_limit" integer DEFAULT 80) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare lim integer := least(greatest(coalesce(p_limit, 80), 1), 300);
begin
  perform economy_private.require_admin();
  return jsonb_build_object(
    'coins', (select coins from public.academy_user_stats where user_id = p_user),
    'spent', coalesce((select sum(amount) from economy_private.spend_rows(p_user)), 0),
    'rows', coalesce((select jsonb_agg(to_jsonb(h) order by h.at desc nulls last) from (
      select * from (
        select l.created_at as at, l.delta, l.source_app as app, l.kind, coalesce(l.note, '') as note from public.wallet_ledger l where l.user_id = p_user
        union all
        select c.created_at, c.amount, 'tamagotchi', 'tama_' || c.kind, '' from public.tama_credit_ledger c where c.user_id = p_user
          and c.source_id not like 'forest:%' -- 집중의 숲은 상한 공유용으로 여기에도 적히지만 지급은 통합 원장 줄이다
        union all
        select r.awarded_at, r.amount, 'academy', 'chapter', r.chapter from public.academy_chapter_rewards r where r.user_id = p_user
        union all
        select r.claimed_at, r.amount, 'academy', 'study_claim', r.reservation_date::text from public.academy_study_rewards r where r.user_id = p_user and r.source = 'claim'
        union all
        select g.created_at, g.refund - g.price, 'tamagotchi', 'gacha', g.machine || ':' || g.item_id from public.tama_gacha_log g where g.owner = p_user and (g.price <> 0 or g.refund <> 0)
        union all
        select o.created_at, -o.charged_coins + o.refunded_coins, 'tamagotchi', 'character_order', o.title from public.tama_character_order o where o.owner = p_user
        union all
        select o.created_at, -o.charged_coins + o.refunded_coins, 'tamagotchi', 'decor_order', o.title from public.tama_decor_order o where o.owner = p_user
        union all
        select o.created_at, -o.charged_coins + o.refunded_coins, 'academy', 'workshop_order', o.title from public.academy_workshop_orders o where o.student_id = p_user
        union all
        select c.created_at, c.amount, 'academy', 'workshop_commission', '' from public.academy_workshop_commissions c where c.recipient_id = p_user
        union all
        select s.at, -s.amount, case when s.kind = 'pet_slot' then 'tamagotchi' else 'academy' end, s.kind,
               s.note || case when s.approx then ' (지금 값)' else '' end
          from economy_private.spend_rows(p_user) s where s.kind in ('workshop_purchase', 'shop_purchase', 'pet_slot')
      ) all_rows order by at desc nulls last limit lim) h), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."admin_coin_history"("p_user" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_coin_wallets"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform economy_private.require_admin();
  return coalesce((
    with spend as (select * from economy_private.spend_rows(null)),
    agg as (
      select s.user_id, sum(s.amount)::integer as spent, bool_or(s.approx) as approx
        from spend s group by s.user_id
    ),
    last as (
      select distinct on (s.user_id) s.user_id, s.at, s.amount, s.kind, s.note
        from spend s where s.at is not null
       order by s.user_id, s.at desc
    ),
    earned as (
      select distinct on (e.user_id) e.user_id, e.at, e.amount, e.kind, e.note
        from economy_private.earn_rows(null) e where e.at is not null
       order by e.user_id, e.at desc
    )
    select jsonb_agg(jsonb_build_object(
      'user_id', p.id,
      'name', coalesce(nullif(btrim(p.name), ''), p.nickname, split_part(p.email, '@', 1)),
      'email', p.email,
      'role', p.role,
      'grade', r.meta->>'grade', 'class', r.meta->>'class', 'number', r.meta->>'number',
      'status', r.status,
      'coins', st.coins,
      'updated_at', st.updated_at,
      'spent', coalesce(a.spent, 0),
      'spent_approx', coalesce(a.approx, false),
      'last_spent', case when l.user_id is null then null
                         else jsonb_build_object('at', l.at, 'amount', l.amount, 'kind', l.kind, 'note', l.note) end,
      'last_earned', case when e.user_id is null then null
                          else jsonb_build_object('at', e.at, 'amount', e.amount, 'kind', e.kind, 'note', e.note) end
      ) order by st.coins desc nulls last, p.name)
    from public.profiles p
    left join public.academy_user_stats st on st.user_id = p.id
    left join agg a on a.user_id = p.id
    left join last l on l.user_id = p.id
    left join earned e on e.user_id = p.id
    left join lateral (
      select x.meta, x.status from public.resource x
      where p.role = 'student' and x.type = 'student' and x.meta->>'id' = split_part(p.email, '@', 1)
      order by (x.status = 'active') desc limit 1) r on true
    where p.role in ('student', 'teacher', 'staff', 'admin')), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."admin_coin_wallets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_dashboard_count_datasets"("p_budget_ms" integer, "p_size_cap_mb" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_since timestamptz := now() - interval '30 days';
  v_started timestamptz := clock_timestamp();
  v_deadline timestamptz := clock_timestamp() + make_interval(secs => p_budget_ms / 1000.0);
  v_size_cap bigint := p_size_cap_mb::bigint * 1024 * 1024;
  v_datasets jsonb := '{}'::jsonb;
  v_row record;
  v_total bigint;
  v_recent bigint;
  v_exact boolean;
  v_skipped text;
  v_counted int := 0;
  v_estimated int := 0;
begin
  for v_row in
    with allow(key, tbl, ts_col) as (values
      ('events',                'event',                        'created_at'),
      ('tasks',                 'task',                         'created_at'),
      ('task_submissions',      'task_submission',              'created_at'),
      ('workflows',             'task_workflow',                'created_at'),
      ('work_runs',             'task_work_run',                'created_at'),
      ('work_documents',        'task_work_document',           'created_at'),
      ('doc_templates',         'task_work_document_template',  'created_at'),
      ('docgen_contexts',       'docgen_context',               'created_at'),
      ('collab_boards',         'collab_boards',                'created_at'),
      ('collab_notes',          'collab_notes',                 'created_at'),
      ('meetings',              'meeting',                      'created_at'),
      ('notices',               'department_notice',            'created_at'),
      ('documents',             'documents',                    'created_at'),
      ('document_folders',      'document_folders',             'created_at'),
      ('approvals',             'approval_request',             'created_at'),
      ('purchase_pages',        'purchase_request_pages',       'created_at'),
      ('purchase_requests',     'purchase_requests',            'created_at'),
      ('document_issues',       'document_issue',               'created_at'),
      ('training_certificates', 'training_certificates',        'created_at'),
      ('departments',           'department',                   'created_at'),
      ('students',              'student_basic_info',           'created_at'),
      ('detailed_activities',   'student_detailed_activities',  'created_at'),
      ('career_submissions',    'student_career_submissions',   null::text),
      ('school_exam_results',   'school_exam_result',           'created_at'),
      ('school_exam_questions', 'school_exam_question',         'created_at'),
      ('kg_versions',           'student_kg_versions',          'created_at'),
      ('kg_entities',           'student_kg_entities',          'created_at'),
      ('kg_relations',          'student_kg_relations',         'created_at'),
      ('rescue_notes',          'rescue_notes',                 'created_at'),
      ('admission_wishlists',   'admission_wishlist',           'created_at'),
      ('inquiry_designs',       'student_inquiry_designs',      'created_at'),
      ('activities',            'activity',                     'created_at'),
      ('activity_participation','activity_participation',       'created_at'),
      ('teacher_memos',         'teacher_memo',                 'created_at'),
      ('class_memos',           'class_student_memos',          'created_at'),
      ('curriculum',            'school_curriculum',            'created_at'),
      ('achievement_standards', 'subject_achievement_standards','created_at'),
      ('offerings',             'course_offering',              'created_at'),
      ('enrollments',           'student_enrollment',           'created_at'),
      ('teacher_timetable',     'teacher_timetable',            'created_at'),
      ('student_timetable',     'student_timetable',            'created_at'),
      ('sections',              'section',                      'created_at'),
      ('selection_submissions', 'course_selection_submission',  'created_at'),
      ('selection_items',       'course_selection_item',        'created_at'),
      ('exam_schedules',        'exam_schedule',                'created_at'),
      ('timetable_plans',       'timetable_plan',               'created_at'),
      ('class_swaps',           'class_swap',                   'created_at'),
      ('mock_problems',         'mock_problems',                null::text),
      ('seat_reservations',     'seat_reservations',            'created_at'),
      ('afterschool',           'afterschool_enrollments',      null::text),
      ('srs_cards',             'srs_cards',                    'created_at'),
      ('live_sessions',         'live_presentation_sessions',   'created_at'),
      ('student_devices',       'school_student_device',        'created_at'),
      ('device_logs',           'student_smart_device_log',     'created_at'),
      ('univ_admissions',       'univ_admissions',              'created_at'),
      ('educational_news',      'educational_news',             'created_at'),
      ('educational_videos',    'educational_videos',           'created_at'),
      ('academy_chapters',      'academy_chapters',             'started_at'),
      ('academy_daily',         'academy_daily_conversations',  'created_at'),
      ('academy_workshop',      'academy_workshop_orders',      'created_at'),
      ('tama_pets',             'tama_pet',                     'created_at'),
      ('tama_album',            'tama_album',                   'at'),
      ('tama_diary',            'tama_diary',                   'created_at'),
      ('tama_gacha',            'tama_gacha_log',               'created_at'),
      ('tama_focus',            'tama_focus',                   'started_at')
    )
    select a.key, a.tbl, a.ts_col,
           pg_relation_size(c.oid) as bytes,
           greatest(coalesce(c.reltuples, -1)::bigint, coalesce(s.n_live_tup, -1)::bigint) as est,
           greatest(s.last_analyze, s.last_autoanalyze) as analyzed_at
    from allow a
    join pg_class c on c.oid = to_regclass('public.' || quote_ident(a.tbl))
    left join pg_stat_user_tables s on s.relid = c.oid
    order by pg_relation_size(c.oid)
  loop
    v_recent := null;
    v_skipped := null;
    v_exact := (v_row.bytes <= v_size_cap and clock_timestamp() < v_deadline)
               or v_row.est < 0;

    if v_exact then
      execute format('select count(*) from public.%I', v_row.tbl) into v_total;
      v_counted := v_counted + 1;
    else
      v_total := v_row.est;
      v_estimated := v_estimated + 1;
    end if;

    if v_row.ts_col is null then
      v_skipped := 'no_timestamp';
    elsif not v_exact then
      v_skipped := case when v_row.bytes > v_size_cap then 'too_large' else 'budget' end;
    elsif clock_timestamp() >= v_deadline then
      v_skipped := 'budget';
    else
      execute format('select count(*) from public.%I where %I >= $1', v_row.tbl, v_row.ts_col)
        into v_recent using v_since;
    end if;

    v_datasets := v_datasets || jsonb_build_object(
      v_row.key, jsonb_build_object(
        'total',   v_total,
        'recent',  v_recent,
        'exact',   v_exact,
        'skipped', v_skipped,
        'as_of',   case when v_exact then null else v_row.analyzed_at end
      )
    );
  end loop;

  return jsonb_build_object(
    'datasets', v_datasets,
    'counting', jsonb_build_object(
      'counted',     v_counted,
      'estimated',   v_estimated,
      'elapsed_ms',  round(extract(epoch from clock_timestamp() - v_started) * 1000),
      'budget_hit',  clock_timestamp() >= v_deadline,
      'size_cap_mb', p_size_cap_mb
    )
  );
end;
$_$;


ALTER FUNCTION "public"."admin_dashboard_count_datasets"("p_budget_ms" integer, "p_size_cap_mb" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_dashboard_snapshot_save"("p_source" "text", "p_budget_ms" integer, "p_size_cap_mb" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_counts jsonb := public.admin_dashboard_count_datasets(p_budget_ms, p_size_cap_mb);
  v_snap public.admin_dashboard_snapshot;
begin
  insert into public.admin_dashboard_snapshot as s (id, datasets, counting, generated_at, source)
  values (1, v_counts->'datasets', v_counts->'counting', now(), p_source)
  on conflict (id) do update
    set datasets = excluded.datasets, counting = excluded.counting,
        generated_at = excluded.generated_at, source = excluded.source
  returning * into v_snap;
  return to_jsonb(v_snap);
end;
$$;


ALTER FUNCTION "public"."admin_dashboard_snapshot_save"("p_source" "text", "p_budget_ms" integer, "p_size_cap_mb" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_mcp_connections"() RETURNS TABLE("user_id" "uuid", "name" "text", "email" "text", "role" "text", "resource_id" "uuid", "client_id" "uuid", "client_name" "text", "scopes" "text", "granted_at" timestamp with time zone, "revoked_at" timestamp with time zone, "active_sessions" integer, "last_session_at" timestamp with time zone, "calls_30d" integer, "last_call_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or not public.is_admin() then
    raise exception '관리자만 볼 수 있습니다.' using errcode = '42501';
  end if;

  return query
  select
    c.user_id,
    coalesce(nullif(p.name, ''), u.email::text) as name,
    u.email::text,
    p.role::text,
    ur.resource_id,
    c.client_id,
    coalesce(nullif(cl.client_name, ''), '(이름 없는 에이전트)') as client_name,
    c.scopes,
    c.granted_at,
    c.revoked_at,
    coalesce(s.active, 0)::integer,
    s.last_at,
    coalesce(l.calls, 0)::integer,
    l.last_at
  from auth.oauth_consents c
  join auth.users u on u.id = c.user_id
  left join public.profiles p on p.id = c.user_id
  left join lateral (
    select x.resource_id from public.user_resource x where x.user_id = c.user_id limit 1
  ) ur on true
  left join auth.oauth_clients cl on cl.id = c.client_id
  left join lateral (
    select
      count(*) filter (where ss.not_after is null or ss.not_after > now()) as active,
      max(coalesce(ss.refreshed_at, ss.updated_at, ss.created_at)) as last_at
    from auth.sessions ss
    where ss.user_id = c.user_id and ss.oauth_client_id = c.client_id
  ) s on true
  left join lateral (
    select count(*) filter (where lg.at > now() - interval '30 days') as calls, max(lg.at) as last_at
    from public.mcp_call_log lg
    where lg.user_id = c.user_id and lg.client_id = c.client_id::text
  ) l on true
  order by (c.revoked_at is not null), coalesce(l.last_at, s.last_at, c.granted_at) desc;
end;
$$;


ALTER FUNCTION "public"."admin_mcp_connections"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_request_inbox"("p_status" "text" DEFAULT 'open'::"text", "p_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := agent_req_private.me();
  v_items jsonb;
begin
  if v_me is null then
    raise exception using errcode = '42501', message = '교직원 계정만 작업 요청을 받습니다.';
  end if;
  select jsonb_agg(agent_req_private.view(x, true) order by x.created_at desc) into v_items
    from (select * from public.agent_request r
           where r.recipient_resource_id = v_me
             and (coalesce(p_status, 'open') = 'all' or r.status in ('sent', 'handed'))
           order by r.created_at desc limit least(greatest(coalesce(p_limit, 30), 1), 100)) x;
  return coalesce(v_items, '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."agent_request_inbox"("p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_request_mark_handed"("p_id" "uuid", "p_via" "text", "p_label" "text" DEFAULT NULL::"text", "p_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := agent_req_private.me();
  r public.agent_request;
begin
  if coalesce(p_via, '') not in ('desk', 'phone', 'web') then
    raise exception using errcode = '22023', message = 'via 는 desk · phone · web 중 하나입니다.';
  end if;
  r := agent_req_private.set_status(v_me, p_id, 'handed', null,
         jsonb_build_object('via', p_via, 'label', left(coalesce(p_label, ''), 60), 'agent', left(coalesce(p_agent, ''), 60)));
  return agent_req_private.view(r, false);
end;
$$;


ALTER FUNCTION "public"."agent_request_mark_handed"("p_id" "uuid", "p_via" "text", "p_label" "text", "p_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_request_prompt"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := agent_req_private.me();
  r public.agent_request;
begin
  select * into r from public.agent_request where id = p_id and recipient_resource_id = v_me;
  if r.id is null then
    raise exception using errcode = 'P0002', message = '받은 작업 요청에서 찾을 수 없습니다.';
  end if;
  if r.status in ('done', 'declined', 'cancelled') then
    raise exception using errcode = '22023', message = '이미 끝난 요청입니다(완료·거절·취소).';
  end if;
  return agent_req_private.view(r, true) || jsonb_build_object('prompt', agent_req_private.prompt(r));
end;
$$;


ALTER FUNCTION "public"."agent_request_prompt"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_request_send_to_agent"("p_id" "uuid", "p_phone" "text", "p_to_device" "text", "p_to_agent" "text", "p_thread" "text" DEFAULT NULL::"text", "p_via" "text" DEFAULT 'phone'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := agent_req_private.me();
  r public.agent_request;
  v_sent jsonb;
begin
  if coalesce(p_via, '') not in ('phone', 'web') then
    raise exception using errcode = '22023', message = 'via 는 phone · web 중 하나입니다.';
  end if;
  select * into r from public.agent_request where id = p_id and recipient_resource_id = v_me;
  if r.id is null then
    raise exception using errcode = 'P0002', message = '받은 작업 요청에서 찾을 수 없습니다.';
  end if;
  if r.status in ('done', 'declined', 'cancelled') then
    raise exception using errcode = '22023', message = '이미 끝난 요청입니다(완료·거절·취소).';
  end if;
  v_sent := public.desk_agent_phone_send(p_phone, p_to_device, p_to_agent, agent_req_private.prompt(r), p_thread);
  r := agent_req_private.set_status(v_me, p_id, 'handed', null,
         jsonb_build_object('via', p_via, 'label', v_sent->>'label', 'agent', p_to_agent, 'message_id', v_sent->>'id'));
  return jsonb_build_object('sent', v_sent, 'request', agent_req_private.view(r, false));
end;
$$;


