CREATE OR REPLACE FUNCTION "public"."analyze_duplicate_tasks"() RETURNS TABLE("keyword" "text", "similar_tasks" "jsonb", "duplicate_count" bigint, "consolidation_potential" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    WITH keyword_tasks AS (
        SELECT
            unnest(keywords) as kw,
            jsonb_build_object(
                'id', id,
                'title', title,
                'description', description,
                'assignees', meta->'assignees',
                'created_at', created_at
            ) as task_info
        FROM task
        WHERE keywords IS NOT NULL AND array_length(keywords, 1) > 0
    )
    SELECT
        kw as keyword,
        jsonb_agg(task_info) as similar_tasks,
        COUNT(*) as duplicate_count,
        CASE
            WHEN COUNT(*) > 5 THEN 'HIGH'
            WHEN COUNT(*) > 2 THEN 'MEDIUM'
            ELSE 'LOW'
        END as consolidation_potential
    FROM keyword_tasks
    GROUP BY kw
    HAVING COUNT(*) > 1
    ORDER BY duplicate_count DESC;
END;
$$;


ALTER FUNCTION "public"."analyze_duplicate_tasks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analyze_tasks_by_keyword"() RETURNS TABLE("keyword" "text", "event_count" bigint, "task_count" bigint, "total_tasks" bigint, "completed_tasks" bigint, "avg_completion_rate" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    WITH all_keywords AS (
        -- 이벤트 키워드 추출
        SELECT unnest(keywords) as keyword, 'event' as source, id as source_id
        FROM work 
        WHERE keywords IS NOT NULL AND array_length(keywords, 1) > 0
        
        UNION ALL
        
        -- 업무 키워드 추출  
        SELECT unnest(keywords) as keyword, 'task' as source, id as source_id
        FROM task
        WHERE keywords IS NOT NULL AND array_length(keywords, 1) > 0
    ),
    keyword_stats AS (
        SELECT 
            ak.keyword,
            COUNT(DISTINCT CASE WHEN ak.source = 'event' THEN ak.source_id END) as event_count,
            COUNT(DISTINCT CASE WHEN ak.source = 'task' THEN ak.source_id END) as task_count,
            COUNT(t.id) as total_tasks,
            COUNT(CASE WHEN t.status = 'completed' THEN 1 END) as completed_tasks
        FROM all_keywords ak
        LEFT JOIN work e ON ak.source = 'event' AND ak.source_id = e.id
        LEFT JOIN task t ON (
            (ak.source = 'event' AND e.id = t.event_id) OR
            (ak.source = 'task' AND ak.source_id = t.id)
        )
        GROUP BY ak.keyword
    )
    SELECT 
        ks.keyword,
        ks.event_count,
        ks.task_count,
        ks.total_tasks,
        ks.completed_tasks,
        CASE 
            WHEN ks.total_tasks = 0 THEN 0
            ELSE ROUND((ks.completed_tasks::numeric / ks.total_tasks::numeric) * 100, 1)
        END as avg_completion_rate
    FROM keyword_stats ks
    WHERE ks.keyword IS NOT NULL AND trim(ks.keyword) != ''
    ORDER BY ks.total_tasks DESC, avg_completion_rate DESC;
END;
$$;


ALTER FUNCTION "public"."analyze_tasks_by_keyword"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_task_action_run_log_sequence"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  select coalesce(max(event_row.sequence_no), 0) + 1
  into new.sequence_no
  from public.task_action_run_log event_row
  where event_row.run_id = new.run_id;

  return new;
end;
$$;


ALTER FUNCTION "public"."assign_task_action_run_log_sequence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assignee_has_pending_submission"("p_task_id" "uuid", "p_resource_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.collect_request q
    join public.task_action a on a.id = q.action_id and a.archived_at is null
    join public.collect_target t on t.action_id = q.action_id and t.removed_at is null and t.resource_id = p_resource_id
    where q.task_id = p_task_id and q.kind <> 'input' and q.status = 'open'
      and public.submission_target_pending(q.action_id, p_resource_id));
$$;


