CREATE OR REPLACE FUNCTION "public"."attach_curriculum_subjects_to_slot"("p_slot_id" "uuid", "p_curriculum_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_curriculum record;
  v_subject_id uuid;
  v_attempted integer := 0;
  v_added integer := 0;
  v_added_names text[] := ARRAY[]::text[];
  v_inserted_count integer;
BEGIN
  FOR v_curriculum IN
    SELECT sc.*
    FROM unnest(p_curriculum_ids) AS cid
    JOIN public.school_curriculum sc ON sc.id = cid
  LOOP
    v_attempted := v_attempted + 1;

    -- 1. 매칭: school_curriculum_id, name 둘 다로 검사
    SELECT id INTO v_subject_id
      FROM public.course_selectable_subject
      WHERE school_curriculum_id = v_curriculum.id
         OR name = v_curriculum.subject
      LIMIT 1;

    -- 2. 없으면 INSERT, 있어도 idempotent하게 RETURNING 보장
    IF v_subject_id IS NULL THEN
      INSERT INTO public.course_selectable_subject (
        name, category_code, school_curriculum_id, is_active, display_order
      ) VALUES (
        v_curriculum.subject, v_curriculum.category, v_curriculum.id, true, 0
      )
      ON CONFLICT (name) DO UPDATE
        -- 기존 school_curriculum_id가 비어있을 때만 채워줌 (no harm)
        SET school_curriculum_id = COALESCE(
          public.course_selectable_subject.school_curriculum_id,
          EXCLUDED.school_curriculum_id
        )
      RETURNING id INTO v_subject_id;
    END IF;

    -- 3. attach (이미 있으면 skip)
    INSERT INTO public.course_selection_slot_subject (slot_id, selectable_subject_id, semester)
    VALUES (p_slot_id, v_subject_id, v_curriculum.semester)
    ON CONFLICT (slot_id, selectable_subject_id, semester) DO NOTHING;

    GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
    IF v_inserted_count > 0 THEN
      v_added := v_added + 1;
      v_added_names := array_append(v_added_names, v_curriculum.subject);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'attempted', v_attempted,
    'added', v_added,
    'skipped', v_attempted - v_added,
    'names', v_added_names
  );
END $$;


ALTER FUNCTION "public"."attach_curriculum_subjects_to_slot"("p_slot_id" "uuid", "p_curriculum_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audience_is_task_assignees_only"("p_rule" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_typeof(p_rule->'include') = 'array'
     and jsonb_array_length(p_rule->'include') = 1
     and p_rule->'include'->0->>'type' = 'task_assignees'
     and coalesce(jsonb_array_length(case when jsonb_typeof(p_rule->'exclude') = 'array' then p_rule->'exclude' end), 0) = 0;
$$;


