CREATE OR REPLACE FUNCTION "public"."audience_person_matches"("p_crit" "jsonb", "p_academic_year" integer, "p_semester" integer, "p_ref" "date") RETURNS TABLE("resource_id" "uuid", "holder_name" "text", "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_type   text := p_crit->>'type';
  v_ids    uuid[];
  v_grades int[];
  v_types  text[];
  v_names  text[];
  v_kinds  text[];
begin
  if jsonb_typeof(p_crit->'ids') = 'array' then
    select array_agg(x::uuid) into v_ids
    from jsonb_array_elements_text(p_crit->'ids') x
    where x ~ '^[0-9a-fA-F-]{36}$';
  end if;
  if jsonb_typeof(p_crit->'grades') = 'array' then
    select array_agg(x::int) into v_grades from jsonb_array_elements_text(p_crit->'grades') x where x ~ '^[0-9]+$';
  end if;

  if v_type = 'people' then
    return query
      select r.id, r.name, '직접 지정'::text
      from public.resource r
      where r.id = any (coalesce(v_ids, '{}')) and r.type in ('teacher', 'staff') and r.status = 'active';

  elsif v_type = 'all_faculty' then
    if jsonb_typeof(p_crit->'types') = 'array' then
      select array_agg(x) into v_types from jsonb_array_elements_text(p_crit->'types') x where x in ('teacher', 'staff');
    end if;
    v_types := coalesce(nullif(v_types, '{}'), array['teacher']);
    return query
      select r.id, r.name,
             case when v_types @> array['teacher', 'staff'] then '전체 교직원'
                  when v_types = array['staff'] then '전체 직원'
                  else '전체 교사' end
      from public.resource r
      where r.type = any (v_types) and r.status = 'active';

  elsif v_type = 'homeroom' then
    -- 담임 = 태그 `N학년 N반` (사용자 결정: 태그가 공식). 패턴은 앵커로 고정한다.
    return query
      select r.id, r.name, (t.name || ' 담임')::text
      from public.resource_tags t
      join public.resource_tag_assignments a on a.tag_id = t.id
      join public.resource r on r.id = a.resource_id and r.status = 'active'
      where t.name ~ '^[0-9]+학년\s*[0-9]+반$'
        and (v_grades is null or cardinality(v_grades) = 0
             or substring(t.name from '^([0-9]+)학년')::int = any (v_grades));

  elsif v_type = 'grade_head' then
    return query
      select r.id, r.name, t.name::text
      from public.resource_tags t
      join public.resource_tag_assignments a on a.tag_id = t.id
      join public.resource r on r.id = a.resource_id and r.status = 'active'
      where t.name ~ '^[0-9]+학년\s*부장$'
        and (v_grades is null or cardinality(v_grades) = 0
             or substring(t.name from '^([0-9]+)학년')::int = any (v_grades));

  elsif v_type = 'department' then
    -- 부서원 = 그 학년도 department_member ∪ 그 부서 분장 자리의 현 담당자
    return query
      select r.id, r.name, (d.name || ' 소속')::text
      from public.department_member m
      join public.department d on d.id = m.department_id
      join public.resource r on r.id = m.resource_id and r.status = 'active'
      where m.department_id = any (coalesce(v_ids, '{}')) and m.academic_year = p_academic_year
      union
      select h.resource_id, h.holder_name, (d.name || ' · ' || s.name)::text
      from public.duty_seat s
      join public.department d on d.id = s.department_id
      join public.duty_seat_holder h on h.seat_id = s.id
      where s.department_id = any (coalesce(v_ids, '{}')) and s.academic_year = p_academic_year
        and public.duty_holder_active(h.start_date, h.end_date, p_ref);

  elsif v_type = 'seat' then
    -- 자리는 이름으로 가리킨다 — 해마다 복사되는 자리의 id 는 학년도마다 다르다
    if jsonb_typeof(p_crit->'names') = 'array' then
      select array_agg(x) into v_names from jsonb_array_elements_text(p_crit->'names') x;
    end if;
    return query
      select h.resource_id, h.holder_name, ('분장: ' || s.name)::text
      from public.duty_seat s
      join public.duty_seat_holder h on h.seat_id = s.id
      where s.academic_year = p_academic_year and s.name = any (coalesce(v_names, '{}'))
        and public.duty_holder_active(h.start_date, h.end_date, p_ref);

  elsif v_type = 'position' then
    if jsonb_typeof(p_crit->'kinds') = 'array' then
      select array_agg(x) into v_kinds from jsonb_array_elements_text(p_crit->'kinds') x where x in ('head', 'admin');
    end if;
    return query
      select h.resource_id, h.holder_name, s.name::text
      from public.duty_seat s
      join public.duty_seat_holder h on h.seat_id = s.id
      where s.academic_year = p_academic_year and s.kind = any (coalesce(v_kinds, array['head']))
        and public.duty_holder_active(h.start_date, h.end_date, p_ref);

  elsif v_type = 'tag' then
    return query
      select r.id, r.name, ('태그: ' || t.name)::text
      from public.resource_tags t
      join public.resource_tag_assignments a on a.tag_id = t.id
      join public.resource r on r.id = a.resource_id and r.status = 'active'
      where t.id = any (coalesce(v_ids, '{}'));

  elsif v_type = 'club' then
    -- 동아리 담당 교사(2026-09-24). 동아리는 이름으로 가리킨다 — club_info 는 학년도마다 다시 적재되어
    -- id 가 바뀐다. 이름이 비면 그 학년도 동아리 담당 교사 전원.
    if jsonb_typeof(p_crit->'names') = 'array' then
      select array_agg(x) into v_names from jsonb_array_elements_text(p_crit->'names') x;
    end if;
    return query
      -- 2026-11-11: 정본 club_year · club_advisor 로 — 공동지도 교사도 모두 들어온다(club_info 는 대표 한 명만 연결)
      select a.teacher_resource_id, r.name, ('동아리: ' || y.name)::text
      from public.club_year y
      join public.club_advisor a on a.club_year_id = y.id
      join public.resource r on r.id = a.teacher_resource_id
      where y.academic_year = p_academic_year
        and (v_names is null or cardinality(v_names) = 0 or y.name = any (v_names))
        -- 지금은 없는 동아리(명칭 변경·교체)·개설 신청 중인 동아리는 대상에서 뺀다
        and y.status = 'active';
  elsif v_type = 'task_assignee_ids' then
    -- «이 할 일의 담당자»를 풀어 놓은 것(2026-10-01) — expand_task_audience 가 만든다. 사람이 고르는 조건이 아니다
    return query
      select r.id, r.name, '할 일 담당자'::text
      from public.resource r
      where r.id = any (coalesce(v_ids, '{}')) and r.status = 'active';
  end if;
  -- 'teaching' 은 audience_unit_matches 가 맡는다
end;
$_$;


ALTER FUNCTION "public"."audience_person_matches"("p_crit" "jsonb", "p_academic_year" integer, "p_semester" integer, "p_ref" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audience_teaching_rows"("p_academic_year" integer, "p_semester" integer) RETURNS TABLE("resource_id" "uuid", "teacher_name" "text", "grade" integer, "subject_name" "text", "class_label" "text", "subject_group" "text", "subject_cluster" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with base as (
    select distinct tt.teacher_resource_id, btrim(tt.teacher_name) teacher_name, tt.grade,
           btrim(tt.subject_name) subject_name, btrim(coalesce(tt.class_label, '')) class_label
    from public.teacher_timetable tt
    where tt.academic_year = p_academic_year
      and tt.semester = p_semester
      and tt.activity_type = 'subject'
  ),
  subj as (
    select s, public.subject_group_of(s) g, public.subject_cluster_of(s) c
    from (select distinct subject_name s from base) x
  )
  select distinct
    coalesce(
      b.teacher_resource_id,
      (select r.id from public.resource r
        where replace(r.name, ' ', '') = replace(b.teacher_name, ' ', '')
          and r.type in ('teacher', 'staff') and r.status = 'active'
        order by (r.type = 'teacher') desc limit 1)
    ),
    b.teacher_name, b.grade, b.subject_name, b.class_label, subj.g, subj.c
  from base b join subj on subj.s = b.subject_name;
$$;


ALTER FUNCTION "public"."audience_teaching_rows"("p_academic_year" integer, "p_semester" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audience_unit_matches"("p_crit" "jsonb", "p_academic_year" integer, "p_semester" integer) RETURNS TABLE("resource_id" "uuid", "teacher_name" "text", "grade" integer, "subject_name" "text", "class_label" "text", "reason" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  with f as (
    select
      (select array_agg(x::int) from jsonb_array_elements_text(
         case when jsonb_typeof(p_crit->'grades') = 'array' then p_crit->'grades' else '[]'::jsonb end) x
       where x ~ '^[0-9]+$') grades,
      (select array_agg(x) from jsonb_array_elements_text(
         case when jsonb_typeof(p_crit->'subjectGroups') = 'array' then p_crit->'subjectGroups' else '[]'::jsonb end) x) groups,
      (select array_agg(x) from jsonb_array_elements_text(
         case when jsonb_typeof(p_crit->'subjectClusters') = 'array' then p_crit->'subjectClusters' else '[]'::jsonb end) x) clusters,
      (select array_agg(btrim(x)) from jsonb_array_elements_text(
         case when jsonb_typeof(p_crit->'subjects') = 'array' then p_crit->'subjects' else '[]'::jsonb end) x) subjects
  )
  select t.resource_id, t.teacher_name, t.grade, t.subject_name, t.class_label,
         (t.grade || '학년 ' || t.subject_name || ' 수업')::text
  from public.audience_teaching_rows(p_academic_year, p_semester) t, f
  where p_crit->>'type' = 'teaching'
    and (f.grades is null or t.grade = any (f.grades))
    and ((f.groups is null and f.clusters is null)
         or t.subject_group = any (coalesce(f.groups, '{}'))
         or t.subject_cluster = any (coalesce(f.clusters, '{}')))
    and (f.subjects is null or t.subject_name = any (f.subjects));
$_$;


ALTER FUNCTION "public"."audience_unit_matches"("p_crit" "jsonb", "p_academic_year" integer, "p_semester" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audience_uses_task_assignees"("p_rule" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (select 1 from jsonb_array_elements(case when jsonb_typeof(p_rule->'include') = 'array'
                                                         then p_rule->'include' else '[]'::jsonb end) c
                 where c.value->>'type' = 'task_assignees');
$$;


ALTER FUNCTION "public"."audience_uses_task_assignees"("p_rule" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_admin_issue_runner"("p_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_key text := encode(extensions.gen_random_bytes(32), 'hex');
  v_id uuid;
begin
  if not automation_private.is_admin(auth.uid()) then
    raise exception '관리자만 발급할 수 있습니다' using errcode = '42501';
  end if;
  insert into automation_runner(key_hash, name)
  values (encode(extensions.digest(v_key, 'sha256'), 'hex'), btrim(p_name))
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'key', v_key);
end;
$$;


ALTER FUNCTION "public"."automation_admin_issue_runner"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_admin_revoke_runner"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not automation_private.is_admin(auth.uid()) then
    raise exception '관리자만 할 수 있습니다' using errcode = '42501';
  end if;
  update automation_runner set revoked_at = now() where id = p_id and revoked_at is null;
end;
$$;


ALTER FUNCTION "public"."automation_admin_revoke_runner"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_admin_runners"() RETURNS TABLE("id" "uuid", "name" "text", "revoked_at" timestamp with time zone, "last_seen_at" timestamp with time zone, "last_version" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not automation_private.is_admin(auth.uid()) then
    raise exception '관리자만 볼 수 있습니다' using errcode = '42501';
  end if;
  return query select r.id, r.name, r.revoked_at, r.last_seen_at, r.last_version, r.created_at
               from automation_runner r order by r.created_at desc;
end;
$$;


ALTER FUNCTION "public"."automation_admin_runners"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_approve"("p_id" "uuid") RETURNS "public"."automation"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  a automation := automation_private.owned(p_id);
begin
  if a.owner_id <> auth.uid() then
    raise exception '승인은 만든 사람만 할 수 있습니다' using errcode = '42501';
  end if;
  if not automation_private.can_author(auth.uid(), a.kind) then
    raise exception '자동화 업무 권한이 없습니다' using errcode = '42501';
  end if;
  perform set_config('automation.approving', 'on', true);
  update automation set approved_at = now(), approved_by = auth.uid(), enabled = true
  where id = p_id returning * into a;
  perform set_config('automation.approving', '', true);
  return a;
end;
$$;


ALTER FUNCTION "public"."automation_approve"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_cancel_run"("p_run_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  update automation_run set status = 'cancelled', finished_at = now()
  where id = p_run_id and status = 'pending'
    and (owner_id = auth.uid() or automation_private.is_admin(auth.uid()));
  if not found then
    raise exception '취소할 수 있는 대기 회차가 아닙니다' using errcode = 'P0002';
  end if;
end;
$$;


ALTER FUNCTION "public"."automation_cancel_run"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_preview"("p_id" "uuid", "p_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  a automation := automation_private.owned(p_id);
  v_date date := coalesce(p_date, (now() at time zone 'Asia/Seoul')::date);
  v_recips jsonb;
  v_mode text := a.config->>'body_mode';
  v_msgs jsonb := '[]'::jsonb;
  v_rec jsonb;
  v_body text;
  cfg automation_config;
begin
  select * into cfg from automation_config where id;
  -- 남의 것을 보는 관리자도 «주인이 보는 명단»을 본다
  v_recips := automation_private.recipients_of(a, a.owner_id <> auth.uid());
  if automation_private.is_per_recipient(a.config) then
    for v_rec in select value from jsonb_array_elements(v_recips) loop
      exit when jsonb_array_length(v_msgs) >= 3;
      v_body := automation_private.data_value('내 마감 임박 업무', v_date, (v_rec->>'resource_id')::uuid);
      if v_body is null then continue; end if;
      v_msgs := v_msgs || jsonb_build_array(jsonb_build_object(
        'to', v_rec,
        'title', automation_private.render(a.config->>'title', v_mode, v_date, (v_rec->>'resource_id')::uuid),
        'body',  automation_private.render(a.config->>'body',  v_mode, v_date, (v_rec->>'resource_id')::uuid)));
    end loop;
  else
    v_msgs := jsonb_build_array(jsonb_build_object(
      'to', null,
      'title', automation_private.render(a.config->>'title', v_mode, v_date, null),
      'body',  automation_private.render(a.config->>'body',  v_mode, v_date, null)));
  end if;
  return jsonb_build_object(
    'date', v_date,
    'closed_reason', case when a.skip_closed_days then automation_private.closed_day_reason(v_date) end,
    'per_recipient', automation_private.is_per_recipient(a.config),
    'recipients', v_recips,
    'recipient_count', jsonb_array_length(v_recips),
    'over_limit', jsonb_array_length(v_recips) > cfg.max_recipients_per_run,
    'max_recipients_per_run', cfg.max_recipients_per_run,
    'messages', v_msgs,
    'sender', '기전봇');
end;
$$;


ALTER FUNCTION "public"."automation_preview"("p_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_runner_claim"("p_key_hash" "text", "p_max" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r automation_runner := automation_private.runner_by_key(p_key_hash);
  v_out jsonb;
begin
  perform automation_private.sweep();
  if (select paused_all from automation_config where id) then
    return jsonb_build_object('runs', '[]'::jsonb, 'paused_all', true);
  end if;

  -- 회차를 만든 뒤 자동화가 꺼지거나 승인이 풀렸으면 보내지 않는다(시험 발송은 예외)
  update automation_run x set status = 'cancelled', finished_at = now(), skip_reason = '자동화가 꺼졌거나 승인이 풀림'
  where x.status = 'pending' and not x.is_test
    and not exists(select 1 from automation a
                   where a.id = x.automation_id and a.enabled and not a.paused and a.approved_at is not null);

  with picked as (
    select id from automation_run
    where status = 'pending' and scheduled_for <= now()
    order by scheduled_for, created_at
    limit greatest(1, least(coalesce(p_max, 1), 20))
    for update skip locked
  ), upd as (
    update automation_run x set status = 'claimed', claimed_at = now(), runner_id = r.id
    from picked where x.id = picked.id
    returning x.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', id, 'kind', kind, 'is_test', is_test, 'scheduled_for', scheduled_for, 'expires_at', expires_at,
           'title', title, 'body', body, 'recipients', recipients) order by scheduled_for), '[]'::jsonb)
    into v_out from upd;
  return jsonb_build_object('runs', v_out, 'paused_all', false);
end;
$$;


ALTER FUNCTION "public"."automation_runner_claim"("p_key_hash" "text", "p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_runner_heartbeat"("p_key_hash" "text", "p_version" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r automation_runner := automation_private.runner_by_key(p_key_hash);
begin
  update automation_runner set last_version = left(p_version, 40) where id = r.id;
  return jsonb_build_object('ok', true, 'paused_all', (select paused_all from automation_config where id));
end;
$$;


ALTER FUNCTION "public"."automation_runner_heartbeat"("p_key_hash" "text", "p_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_runner_report"("p_key_hash" "text", "p_run_id" "uuid", "p_status" "text", "p_message_key" bigint DEFAULT NULL::bigint, "p_arrival" "text" DEFAULT NULL::"text", "p_error" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r automation_runner := automation_private.runner_by_key(p_key_hash);
begin
  if p_status not in ('sent', 'unknown', 'failed') then
    raise exception '알 수 없는 결과: %', p_status using errcode = '22023';
  end if;
  update automation_run
  set status = p_status, finished_at = now(), message_key = p_message_key,
      arrival = left(p_arrival, 40), error = left(p_error, 1000)
  where id = p_run_id and status = 'claimed' and runner_id = r.id;
  if not found then
    raise exception '이 실행기가 가져간 회차가 아닙니다' using errcode = 'P0002';
  end if;
  if p_status in ('unknown', 'failed') then
    perform automation_private.notify_issue(p_run_id);
  end if;
  return jsonb_build_object('ok', true);
end;
$$;


ALTER FUNCTION "public"."automation_runner_report"("p_key_hash" "text", "p_run_id" "uuid", "p_status" "text", "p_message_key" bigint, "p_arrival" "text", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."automation_test_send"("p_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  a automation := automation_private.owned(p_id);
  v_me jsonb;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_mode text := a.config->>'body_mode';
  v_id uuid;
begin
  if a.owner_id <> auth.uid() then
    raise exception '시험 발송은 만든 사람만 할 수 있습니다' using errcode = '42501';
  end if;
  if not automation_private.can_author(auth.uid(), a.kind) then
    raise exception '자동화 업무 권한이 없습니다' using errcode = '42501';
  end if;
  if (select count(*) from automation_run where automation_id = a.id and is_test
        and (created_at at time zone 'Asia/Seoul')::date = v_today) >= 5 then
    raise exception '시험 발송은 하루 5번까지입니다' using errcode = 'P0001';
  end if;
  select jsonb_build_object('resource_id', r.id, 'name', r.name) into v_me
  from resource r
  where r.id in (select automation_private.resources_of(auth.uid())) and r.type in ('teacher', 'staff')
  order by (r.type = 'teacher') desc limit 1;
  if v_me is null then
    raise exception '교직원 명단에 연결된 계정이 아닙니다' using errcode = '42501';
  end if;
  insert into automation_run(automation_id, automation_title, owner_id, kind, is_test, scheduled_for, expires_at,
                             recipient_key, title, body, recipients)
  values (a.id, a.title, a.owner_id, a.kind, true, now(), now() + interval '30 minutes',
          'test:' || gen_random_uuid(),
          '[시험] ' || automation_private.render(a.config->>'title', v_mode, v_today, (v_me->>'resource_id')::uuid),
          automation_private.render(a.config->>'body', v_mode, v_today, (v_me->>'resource_id')::uuid),
          jsonb_build_array(v_me))
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."automation_test_send"("p_id" "uuid") OWNER TO "postgres";


