CREATE OR REPLACE FUNCTION "public"."backfill_course_submission_resource_id"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE updated_count int;
BEGIN
  UPDATE course_selection_submission css
  SET student_resource_id = r.id
  FROM resource r
  WHERE r.type = 'student'
    AND r.meta->>'id' = css.student_code
    AND css.student_resource_id IS NULL;
  GET DIAGNOSTICS updated_count = ROW_COUNT;

  -- selectable_subject_id backfill
  UPDATE course_selection_item ci
  SET selectable_subject_id = css.id
  FROM course_selectable_subject css
  WHERE ci.subject_name = css.name
    AND ci.selectable_subject_id IS NULL;

  RETURN updated_count;
END $$;


