CREATE OR REPLACE FUNCTION "public"."budget_add_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_resource uuid;
begin
  select ur.resource_id into v_resource from public.user_resource ur
    join public.resource r on r.id = ur.resource_id
   where ur.user_id = new.created_by
   order by (r.type = 'teacher') desc, ur.created_at
   limit 1;
  if v_resource is null then
    raise exception '교직원 명단에 연결된 계정만 사업을 만들 수 있습니다' using errcode = 'insufficient_privilege';
  end if;
  insert into public.budget_member (project_id, resource_id, role, added_by)
  values (new.id, v_resource, 'owner', new.created_by)
  on conflict (project_id, resource_id) do update set role = 'owner';
  return new;
end $$;


