CREATE OR REPLACE FUNCTION "public"."budget_apply_card"("p_project" "uuid", "p_file_name" "text", "p_card" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_line jsonb;
  v_id uuid;
  v_seen uuid[] := '{}';
  v_changed jsonb := '[]'::jsonb;
  v_prev bigint;
  v_budget bigint;
  v_rev uuid;
  v_seq int;
  v_new int := 0;
  v_updated int := 0;
  v_missing int := 0;
  v_order int := 0;
  v_snapshot jsonb := '[]'::jsonb;
  v_has_confirmed boolean;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = 'insufficient_privilege';
  end if;
  if not public.budget_can_edit(p_project) then
    raise exception '이 사업의 담당자만 카드를 반영할 수 있습니다' using errcode = 'insufficient_privilege';
  end if;
  if jsonb_typeof(p_card -> 'lines') is distinct from 'array' or jsonb_array_length(p_card -> 'lines') = 0 then
    raise exception '카드에 산출내역이 없습니다' using errcode = 'invalid_parameter_value';
  end if;

  for v_line in select * from jsonb_array_elements(p_card -> 'lines') loop
    v_order := v_order + 1;
    v_budget := coalesce((v_line ->> 'budget')::bigint, 0);
    v_id := nullif(v_line ->> 'line_id', '')::uuid;
    if v_id is not null and not exists (select 1 from public.budget_line where id = v_id and project_id = p_project) then
      raise exception '다른 사업의 산출내역입니다' using errcode = 'invalid_parameter_value';
    end if;
    if v_id is null then
      insert into public.budget_line (project_id, sort_order, expense_item, name, card_key, budget_amount,
                                      pumui, wonin, jichul, jigeup, origin)
      values (p_project, v_order, nullif(btrim(v_line ->> 'expense_item'), ''), btrim(v_line ->> 'name'),
              v_line ->> 'card_key', 0,
              coalesce((v_line ->> 'pumui')::bigint, 0), coalesce((v_line ->> 'wonin')::bigint, 0),
              coalesce((v_line ->> 'jichul')::bigint, 0), coalesce((v_line ->> 'jigeup')::bigint, 0), 'card')
      returning id into v_id;
      v_new := v_new + 1;
      v_prev := 0;
    else
      select budget_amount into v_prev from public.budget_line where id = v_id;
      update public.budget_line set
        sort_order = v_order,
        expense_item = coalesce(nullif(btrim(v_line ->> 'expense_item'), ''), expense_item),
        name = coalesce(nullif(btrim(v_line ->> 'name'), ''), name),
        card_key = coalesce(v_line ->> 'card_key', card_key),
        pumui = coalesce((v_line ->> 'pumui')::bigint, 0),
        wonin = coalesce((v_line ->> 'wonin')::bigint, 0),
        jichul = coalesce((v_line ->> 'jichul')::bigint, 0),
        jigeup = coalesce((v_line ->> 'jigeup')::bigint, 0),
        manual_override = false,
        missing_from_card = false,
        origin = 'card'
      where id = v_id;
      v_updated := v_updated + 1;
    end if;
    v_seen := v_seen || v_id;
    if v_prev is distinct from v_budget then
      v_changed := v_changed || jsonb_build_object('line_id', v_id, 'prev', v_prev, 'amount', v_budget);
    end if;
    v_snapshot := v_snapshot || jsonb_build_object(
      'line_id', v_id, 'name', v_line ->> 'name', 'expense_item', v_line ->> 'expense_item',
      'budget', v_budget, 'pumui', coalesce((v_line ->> 'pumui')::bigint, 0),
      'wonin', coalesce((v_line ->> 'wonin')::bigint, 0), 'jichul', coalesce((v_line ->> 'jichul')::bigint, 0),
      'jigeup', coalesce((v_line ->> 'jigeup')::bigint, 0));
  end loop;

  -- 카드에 없던 줄 표시(지우지 않는다 — 계획·연결이 매달려 있을 수 있다)
  update public.budget_line set missing_from_card = true
   where project_id = p_project and origin = 'card' and not (id = any (v_seen)) and not missing_from_card;
  get diagnostics v_missing = row_count;

  -- 예산현액이 바뀐 줄 → «카드 반영» 확정 차수
  if jsonb_array_length(v_changed) > 0 then
    select exists (select 1 from public.budget_revision where project_id = p_project and status = 'confirmed')
      into v_has_confirmed;
    select coalesce(max(seq) + 1, 0) into v_seq from public.budget_revision where project_id = p_project;
    -- 초안이 있으면 초안 뒤로 밀지 않는다: 초안의 seq 를 하나 뒤로 옮기고 그 자리에 카드 차수를 넣는다
    if exists (select 1 from public.budget_revision where project_id = p_project and status = 'draft') then
      update public.budget_revision set seq = v_seq where project_id = p_project and status = 'draft'
        returning seq - 1 into v_seq;
      -- returning 은 옮긴 뒤 값이라 1을 뺐다 = 비게 된 자리
    end if;
    insert into public.budget_revision (project_id, seq, title, status, source, confirmed_at, confirmed_by)
    values (p_project, v_seq,
            case when not v_has_confirmed then '본예산 (카드)'
                 else '카드 반영 ' || to_char(coalesce((p_card ->> 'card_date')::date, current_date), 'MM-DD') end,
            'confirmed', 'card', transaction_timestamp(), auth.uid())
    returning id into v_rev;
    insert into public.budget_revision_line (revision_id, project_id, line_id, amount, prev_amount)
    select v_rev, p_project, (c ->> 'line_id')::uuid, (c ->> 'amount')::bigint, (c ->> 'prev')::bigint
      from jsonb_array_elements(v_changed) c;
    update public.budget_line l set budget_amount = (c ->> 'amount')::bigint
      from jsonb_array_elements(v_changed) c
     where l.id = (c ->> 'line_id')::uuid;
  end if;

  insert into public.budget_card_import (project_id, file_name, card_date, snapshot, summary)
  values (p_project, nullif(btrim(p_file_name), ''),
          coalesce((p_card ->> 'card_date')::date, current_date),
          jsonb_build_object('lines', v_snapshot, 'card_total', p_card -> 'card_total'),
          jsonb_build_object('new', v_new, 'updated', v_updated, 'missing', v_missing,
                             'budget_changed', jsonb_array_length(v_changed), 'revision_id', v_rev));

  return jsonb_build_object('new', v_new, 'updated', v_updated, 'missing', v_missing,
                            'budget_changed', jsonb_array_length(v_changed), 'revision_id', v_rev);
end $$;


ALTER FUNCTION "public"."budget_apply_card"("p_project" "uuid", "p_file_name" "text", "p_card" "jsonb") OWNER TO "postgres";


