CREATE OR REPLACE FUNCTION "public"."budget_confirm_revision"("p_revision" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_project uuid;
  v_status text;
  v_bad text;
  v_count int;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = 'insufficient_privilege';
  end if;
  select project_id, status into v_project, v_status from public.budget_revision where id = p_revision;
  if v_project is null then
    raise exception '추경 차수를 찾지 못했습니다' using errcode = 'no_data_found';
  end if;
  if not public.budget_can_edit(v_project) then
    raise exception '이 사업의 담당자만 확정할 수 있습니다' using errcode = 'insufficient_privilege';
  end if;
  if v_status <> 'draft' then
    raise exception '이미 확정된 차수입니다' using errcode = 'check_violation';
  end if;
  select string_agg(l.name, ', ') into v_bad
    from public.budget_revision_line r join public.budget_line l on l.id = r.line_id
   where r.revision_id = p_revision and r.amount < l.wonin;
  if v_bad is not null then
    raise exception '원인행위보다 작게 줄일 수 없습니다: %', v_bad using errcode = 'check_violation';
  end if;

  update public.budget_revision_line r set prev_amount = l.budget_amount
    from public.budget_line l
   where r.revision_id = p_revision and l.id = r.line_id;
  update public.budget_line l set budget_amount = r.amount
    from public.budget_revision_line r
   where r.revision_id = p_revision and l.id = r.line_id;
  get diagnostics v_count = row_count;
  update public.budget_revision set status = 'confirmed', confirmed_at = now(), confirmed_by = auth.uid()
   where id = p_revision;
  return jsonb_build_object('revision_id', p_revision, 'lines', v_count);
end $$;


ALTER FUNCTION "public"."budget_confirm_revision"("p_revision" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."budget_guard_member"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- 사업이 통째로 지워지는 중이면 막지 않는다
  if not exists (select 1 from public.budget_project where id = old.project_id) then
    return coalesce(new, old);
  end if;
  if old.role = 'owner' and (tg_op = 'DELETE' or new.role <> 'owner')
     and not exists (select 1 from public.budget_member
                     where project_id = old.project_id and role = 'owner' and resource_id <> old.resource_id) then
    raise exception '사업에는 담당자(owner)가 한 명은 있어야 합니다' using errcode = 'check_violation';
  end if;
  return coalesce(new, old);
end $$;


ALTER FUNCTION "public"."budget_guard_member"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."budget_guard_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'confirmed'
       and exists (select 1 from public.budget_project where id = old.project_id) then
      raise exception '확정된 추경 차수는 지울 수 없습니다' using errcode = 'check_violation';
    end if;
    return old;
  end if;
  if old.status = 'confirmed' and (new.status <> 'confirmed' or new.seq <> old.seq) then
    raise exception '확정된 추경 차수는 되돌릴 수 없습니다' using errcode = 'check_violation';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."budget_guard_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."budget_is_owner"("p_project" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select auth.uid() is not null
     and exists (select 1 from public.budget_member m
                   join public.user_resource ur on ur.resource_id = m.resource_id
                  where m.project_id = p_project and ur.user_id = auth.uid() and m.role = 'owner');
$$;


ALTER FUNCTION "public"."budget_is_owner"("p_project" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."budget_lock_confirmed_line"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare v_status text; v_confirmed_at timestamptz;
begin
  -- 사업이 통째로 지워지는 중(연쇄 삭제)이면 막지 않는다
  if not exists (select 1 from public.budget_project where id = coalesce(new.project_id, old.project_id)) then
    return coalesce(new, old);
  end if;
  select status, confirmed_at into v_status, v_confirmed_at from public.budget_revision
   where id = coalesce(new.revision_id, old.revision_id);
  -- 예외 하나: 카드 반영 RPC 가 **같은 트랜잭션에서** 확정 차수를 만들고 줄을 채우는 것
  -- (초안이 이미 있으면 카드 차수를 초안으로 만들 수 없다 — 초안은 사업마다 하나)
  if v_status = 'confirmed' and tg_op = 'INSERT' and v_confirmed_at = transaction_timestamp() then
    return new;
  end if;
  if v_status = 'confirmed' then
    raise exception '확정된 추경 차수는 고칠 수 없습니다' using errcode = 'check_violation';
  end if;
  return coalesce(new, old);
end $$;


ALTER FUNCTION "public"."budget_lock_confirmed_line"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."budget_plan_status_from_link"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' and new.plan_item_id is not null then
    -- 이미 «구매 완료»인 차수의 품목을 이으면 곧바로 완료
    update public.budget_plan_item set status = case
        when exists (select 1 from public.purchase_order_lines ol join public.purchase_order_batches b on b.id = ol.batch_id
                      where ol.id = new.order_line_id and b.status = 'purchased') then 'done'
        else 'in_order' end
     where id = new.plan_item_id and status = 'planned';
  elsif tg_op = 'DELETE' and old.plan_item_id is not null then
    update public.budget_plan_item p set status = 'planned'
     where p.id = old.plan_item_id and p.status = 'in_order'
       and not exists (select 1 from public.budget_order_link l where l.plan_item_id = old.plan_item_id);
  elsif tg_op = 'UPDATE' and new.plan_item_id is distinct from old.plan_item_id then
    if new.plan_item_id is not null then
      update public.budget_plan_item set status = 'in_order' where id = new.plan_item_id and status = 'planned';
    end if;
    if old.plan_item_id is not null then
      update public.budget_plan_item p set status = 'planned'
       where p.id = old.plan_item_id and p.status = 'in_order'
         and not exists (select 1 from public.budget_order_link l where l.plan_item_id = old.plan_item_id);
    end if;
  end if;
  return coalesce(new, old);
end $$;


ALTER FUNCTION "public"."budget_plan_status_from_link"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."budget_sync_plans_from_batch"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status = 'purchased' and old.status is distinct from 'purchased' then
    update public.budget_plan_item p set status = 'done'
     where p.status in ('planned', 'in_order')
       and p.id in (select l.plan_item_id from public.budget_order_link l
                      join public.purchase_order_lines ol on ol.id = l.order_line_id
                     where ol.batch_id = new.id and l.plan_item_id is not null);
  elsif old.status = 'purchased' and new.status is distinct from 'purchased' then
    update public.budget_plan_item p set status = 'in_order'
     where p.status = 'done'
       and p.id in (select l.plan_item_id from public.budget_order_link l
                      join public.purchase_order_lines ol on ol.id = l.order_line_id
                     where ol.batch_id = new.id and l.plan_item_id is not null);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."budget_sync_plans_from_batch"() OWNER TO "postgres";


