CREATE OR REPLACE FUNCTION "public"."bulk_import_course_submissions"("payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  inserted_subs int := 0;
  inserted_items int := 0;
  rec jsonb;
  itm jsonb;
  sub_id uuid;
BEGIN
  -- payload 형태:
  -- [
  --   {"sub_id": "...", "round_id": "...", "student_code": "...", "student_name": "...",
  --    "student_grade": 1, "student_class": 1, "student_no": 1,
  --    "items": [{"subject_name": "...", "semester": 1, "category_code": "KOR"}, ...]}
  -- ]
  FOR rec IN SELECT * FROM jsonb_array_elements(payload)
  LOOP
    sub_id := (rec->>'sub_id')::uuid;
    INSERT INTO course_selection_submission (
      id, round_id, student_code, student_name,
      student_grade, student_class, student_no, status
    ) VALUES (
      sub_id,
      (rec->>'round_id')::uuid,
      rec->>'student_code',
      rec->>'student_name',
      (rec->>'student_grade')::int,
      (rec->>'student_class')::int,
      (rec->>'student_no')::int,
      'finalized'
    )
    ON CONFLICT (round_id, student_code) DO UPDATE SET
      student_name = EXCLUDED.student_name,
      student_grade = EXCLUDED.student_grade,
      student_class = EXCLUDED.student_class,
      student_no = EXCLUDED.student_no
    RETURNING id INTO sub_id;
    inserted_subs := inserted_subs + 1;

    -- 기존 items 삭제 후 재삽입 (idempotent)
    DELETE FROM course_selection_item WHERE submission_id = sub_id;
    FOR itm IN SELECT * FROM jsonb_array_elements(rec->'items')
    LOOP
      INSERT INTO course_selection_item (
        submission_id, subject_name, semester, category_code
      ) VALUES (
        sub_id,
        itm->>'subject_name',
        (itm->>'semester')::int,
        itm->>'category_code'
      );
      inserted_items := inserted_items + 1;
    END LOOP;
  END LOOP;
  RETURN jsonb_build_object('submissions', inserted_subs, 'items', inserted_items);
END $$;


ALTER FUNCTION "public"."bulk_import_course_submissions"("payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_problem_solving_progress"("_user_id" "uuid", "_achievement_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  achievement_record RECORD;
  progress_count INTEGER := 0;
BEGIN
  -- Get achievement details
  SELECT * INTO achievement_record FROM public.achievements WHERE id = _achievement_id;
  
  IF achievement_record.type = 'problem_solve' THEN
    -- Count unique problems solved or attempted
    SELECT COUNT(DISTINCT problem_id) INTO progress_count
    FROM (
      SELECT problem_id FROM public.user_problem_attempts 
      WHERE user_id = _user_id
      UNION
      SELECT DISTINCT ps.problem_id FROM public.problem_solutions ps
      WHERE ps.user_id = _user_id
    ) unique_problems
    JOIN public.problems p ON unique_problems.problem_id = p.id
    WHERE 
      (achievement_record.category = 'general' OR p.subject = achievement_record.category)
      AND (achievement_record.subcategory IS NULL OR p.chapter = achievement_record.subcategory)
      AND (achievement_record.difficulty IS NULL OR p.difficulty = achievement_record.difficulty);
      
  ELSIF achievement_record.type = 'solution_post' THEN
    -- Count solutions posted
    SELECT COUNT(*) INTO progress_count
    FROM public.problem_solutions 
    WHERE user_id = _user_id;
    
  ELSIF achievement_record.type = 'streak' THEN
    -- Calculate consecutive days of solution posting
    WITH daily_solutions AS (
      SELECT DATE(created_at) as solution_date
      FROM public.problem_solutions 
      WHERE user_id = _user_id
      GROUP BY DATE(created_at)
      ORDER BY DATE(created_at) DESC
    ),
    consecutive_days AS (
      SELECT solution_date,
             ROW_NUMBER() OVER (ORDER BY solution_date DESC) as rn,
             solution_date - INTERVAL '1 day' * ROW_NUMBER() OVER (ORDER BY solution_date DESC) as group_date
      FROM daily_solutions
    )
    SELECT COUNT(*) INTO progress_count
    FROM consecutive_days
    WHERE group_date = (
      SELECT group_date 
      FROM consecutive_days 
      WHERE rn = 1
    );
  END IF;
  
  RETURN COALESCE(progress_count, 0);
END;
$$;


ALTER FUNCTION "public"."calculate_problem_solving_progress"("_user_id" "uuid", "_achievement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_student_temperature"("student_uuid" "uuid") RETURNS double precision
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  result float;
BEGIN
  SELECT 28.0
    + COALESCE(SUM(
        (CAST(attended AS float) * 0.5 / total) -
        (CAST(absent AS float) * 1.0 / total)
      ), 0)
    + COALESCE((
        SELECT COUNT(*) * 0.1
        FROM seat_reservations
        WHERE student_id = student_uuid AND feedback_rating IS NOT NULL
      ), 0)
  INTO result
  FROM (
    SELECT
      reservation_date,
      COUNT(*) as total,
      COUNT(*) FILTER (WHERE is_attended = true) as attended,
      COUNT(*) FILTER (WHERE is_attended = false AND reservation_date < CURRENT_DATE) as absent
    FROM seat_reservations
    WHERE student_id = student_uuid
    GROUP BY reservation_date
  ) daily;

  RETURN ROUND(CAST(COALESCE(result, 28.0) AS numeric), 1);
END;
$$;


ALTER FUNCTION "public"."calculate_student_temperature"("student_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_student_temperatures_batch"("student_uuids" "uuid"[]) RETURNS TABLE("student_id" "uuid", "temperature" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT s.id, calculate_student_temperature(s.id)
    FROM unnest(student_uuids) as s(id);
END;
$$;


