CREATE OR REPLACE FUNCTION "public"."can_access_rescue"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  SELECT
    -- Admin
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
    -- Tag-based counselor / staff_admin
    OR current_rescue_role() IN ('counselor', 'staff_admin')
    -- Homeroom via "X학년 Y반" tag
    OR EXISTS (
      SELECT 1
      FROM resource_tag_assignments rta
      JOIN resource_tags rt ON rt.id = rta.tag_id
      JOIN user_resource ur ON ur.resource_id = rta.resource_id
      WHERE ur.user_id = auth.uid()
        AND rt.name ~ '^[0-9]+학년\s*[0-9]+반$'
    )
    -- 학년 부장 via "N학년 부장" tag
    OR EXISTS (
      SELECT 1
      FROM resource_tag_assignments rta
      JOIN resource_tags rt ON rt.id = rta.tag_id
      JOIN user_resource ur ON ur.resource_id = rta.resource_id
      WHERE ur.user_id = auth.uid()
        AND rt.name ~ '^[0-9]+학년\s*부장$'
    )
    -- Legacy fallback: meta.grade + class_number
    OR EXISTS (
      SELECT 1
      FROM resource r
      JOIN user_resource ur ON ur.resource_id = r.id
      WHERE ur.user_id = auth.uid()
        AND r.meta->>'grade' IS NOT NULL
        AND r.meta->>'class_number' IS NOT NULL
    );
$_$;


ALTER FUNCTION "public"."can_access_rescue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_add_activity_participant"("p_activity_id" "uuid", "p_student_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    public.can_manage_activity(p_activity_id)
    AND (
      public.is_teacher_or_admin(auth.uid())
      -- 학생은 그 활동 주최 동아리의 부원만 참여자로 넣을 수 있다.
      -- 주최가 없으면 EXISTS가 비어 거부된다 → 주최 연결이 사실상 필수가 된다.
      OR EXISTS (
        SELECT 1
        FROM public.activity a
        JOIN public.activity_host_link l ON l.activity_id = a.id
        JOIN public.activity_host_member m
          ON m.host_id = l.host_id
         AND m.academic_year = a.academic_year
         AND m.student_code = p_student_code
        WHERE a.id = p_activity_id
      )
    );
$$;


ALTER FUNCTION "public"."can_add_activity_participant"("p_activity_id" "uuid", "p_student_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_add_activity_participant"("p_activity_id" "uuid", "p_student_code" "text") IS '이 학생을 이 활동 참여자로 넣을 수 있는가. 학생 작성자는 주최 동아리 부원만 넣을 수 있다.';



CREATE OR REPLACE FUNCTION "public"."can_care_student"("p_student_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH stu AS (
    -- 학생의 현재 학년/반: 권위 출처는 resource(type='student')
    SELECT sr.meta->>'grade' AS grade,
           sr.meta->>'class' AS class_num
    FROM resource sr
    WHERE sr.type = 'student'
      AND sr.meta->>'id' = p_student_code
    LIMIT 1
  )
  SELECT
    -- (1) Admin
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
    -- (2) counselor / staff_admin (tag based)
    OR current_rescue_role() IN ('counselor', 'staff_admin')
    -- (3) Homeroom via "X학년 Y반" tag matching the student's grade/class_num
    OR EXISTS (
      SELECT 1
      FROM resource_tag_assignments rta
      JOIN resource_tags rt ON rt.id = rta.tag_id
      JOIN user_resource ur ON ur.resource_id = rta.resource_id
      CROSS JOIN stu
      WHERE ur.user_id = auth.uid()
        AND rt.name ~ '^[0-9]+학년\s*[0-9]+반$'
        AND (regexp_match(rt.name, '^([0-9]+)학년\s*([0-9]+)반$'))[1] = stu.grade
        AND (regexp_match(rt.name, '^([0-9]+)학년\s*([0-9]+)반$'))[2] = stu.class_num
    )
    -- (4) Legacy fallback: 교사 resource.meta.grade + class_number
    OR EXISTS (
      SELECT 1
      FROM resource r
      JOIN user_resource ur ON ur.resource_id = r.id
      CROSS JOIN stu
      WHERE ur.user_id = auth.uid()
        AND r.meta->>'grade' = stu.grade
        AND r.meta->>'class_number' = stu.class_num
    )
    -- (5) 학년 부장: "N학년 부장" 태그가 학생의 grade 와 일치 → 해당 학년 전체
    OR EXISTS (
      SELECT 1
      FROM resource_tag_assignments rta
      JOIN resource_tags rt ON rt.id = rta.tag_id
      JOIN user_resource ur ON ur.resource_id = rta.resource_id
      CROSS JOIN stu
      WHERE ur.user_id = auth.uid()
        AND rt.name ~ '^[0-9]+학년\s*부장$'
        AND (regexp_match(rt.name, '^([0-9]+)학년\s*부장$'))[1] = stu.grade
    );
$_$;


ALTER FUNCTION "public"."can_care_student"("p_student_code" "text") OWNER TO "postgres";


