CREATE OR REPLACE FUNCTION "public"."can_manage_course_selection_student"("p_student_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
WITH stu AS (
  SELECT (sr.meta->>'grade')::int AS grade, (sr.meta->>'class')::int AS class_num
    FROM resource sr
   WHERE sr.type = 'student'
     AND sr.meta->>'id' = p_student_code
     AND sr.meta->>'grade' ~ '^[0-9]+$'
     AND sr.meta->>'class'  ~ '^[0-9]+$'
  UNION
  SELECT s.grade, s.class_num
    FROM student_basic_info s
   WHERE s.id = p_student_code
     AND s.grade IS NOT NULL
     AND s.class_num IS NOT NULL
),
mytag AS (
  SELECT rt.name
    FROM resource_tag_assignments rta
    JOIN resource_tags rt ON rt.id = rta.tag_id
    JOIN user_resource ur ON ur.resource_id = rta.resource_id
   WHERE ur.user_id = auth.uid()
)
SELECT
  EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
  OR EXISTS (
    SELECT 1 FROM mytag t
     WHERE t.name LIKE '%부장%'
       AND t.name !~ '^[0-9]+학년\s*부장$'
  )
  OR EXISTS (
    SELECT 1 FROM mytag t CROSS JOIN stu
     WHERE t.name ~ '^[0-9]+학년\s*부장$'
       AND (substring(t.name from '^([0-9]+)학년'))::int = stu.grade
  )
  OR EXISTS (
    SELECT 1 FROM mytag t CROSS JOIN stu
     WHERE t.name NOT LIKE '%부장%'
       AND t.name ~ '[0-9]+학년'
       AND (substring(t.name from '([0-9]+)학년'))::int = stu.grade
       AND (
         t.name !~ '[0-9]+반'
         OR (substring(t.name from '([0-9]+)반'))::int = stu.class_num
       )
  )
  OR EXISTS (
    SELECT 1
      FROM resource r
      JOIN user_resource ur ON ur.resource_id = r.id
      CROSS JOIN stu
     WHERE ur.user_id = auth.uid()
       AND r.meta->>'grade' = stu.grade::text
       AND r.meta->>'class_number' = stu.class_num::text
  );
$_$;


