CREATE OR REPLACE FUNCTION "public"."can_view_object"("p_type" "text", "p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null or p_id is null then
    return false;
  end if;
  return case p_type
    when 'work' then exists (select 1 from public.work where id = p_id)
    when 'task' then exists (select 1 from public.task where id = p_id)
    when 'official_doc' then exists (select 1 from public.official_doc where id = p_id)
    when 'meeting' then exists (select 1 from public.meeting where id = p_id)
    when 'signature_request' then exists (select 1 from public.signature_request where id = p_id)
    when 'document' then exists (select 1 from public.documents where id = p_id)
    when 'budget_project' then exists (select 1 from public.budget_project where id = p_id)
    else false
  end;
end;
$$;


