CREATE OR REPLACE FUNCTION "public"."can_write_wishlist"("p_student_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH stu AS (
    -- 학생의 현재 학년/반: 권위 출처는 resource(type='student')
    SELECT sr.meta->>'grade' AS grade,
           sr.meta->>'class' AS class_num
    FROM resource sr
    WHERE sr.type = 'student'
      AND sr.meta->>'id' = p_student_code
    LIMIT 1
  )
  SELECT
    -- (1) Admin
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
    -- (2) 담임: "X학년 Y반" 태그가 학생의 grade/class_num 과 일치
    OR EXISTS (
      SELECT 1
      FROM resource_tag_assignments rta
      JOIN resource_tags rt ON rt.id = rta.tag_id
      JOIN user_resource ur ON ur.resource_id = rta.resource_id
      CROSS JOIN stu
      WHERE ur.user_id = auth.uid()
        AND rt.name ~ '^[0-9]+학년\s*[0-9]+반$'
        AND (regexp_match(rt.name, '^([0-9]+)학년\s*([0-9]+)반$'))[1] = stu.grade
        AND (regexp_match(rt.name, '^([0-9]+)학년\s*([0-9]+)반$'))[2] = stu.class_num
    )
    -- (3) 레거시 담임 폴백: 교사 resource.meta.grade + class_number
    OR EXISTS (
      SELECT 1
      FROM resource r
      JOIN user_resource ur ON ur.resource_id = r.id
      CROSS JOIN stu
      WHERE ur.user_id = auth.uid()
        AND r.meta->>'grade' = stu.grade
        AND r.meta->>'class_number' = stu.class_num
    )
    -- (4) 학년부장: "N학년 부장" 태그가 학생의 grade 와 일치 → 해당 학년 전체 R/W
    OR EXISTS (
      SELECT 1
      FROM resource_tag_assignments rta
      JOIN resource_tags rt ON rt.id = rta.tag_id
      JOIN user_resource ur ON ur.resource_id = rta.resource_id
      CROSS JOIN stu
      WHERE ur.user_id = auth.uid()
        AND rt.name ~ '^[0-9]+학년\s*부장$'
        AND (regexp_match(rt.name, '^([0-9]+)학년\s*부장$'))[1] = stu.grade
    );
$_$;


ALTER FUNCTION "public"."can_write_wishlist"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_approval_request"("p_request_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request public.approval_request;
BEGIN
  SELECT * INTO v_request FROM public.approval_request WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '결재 요청을 찾을 수 없습니다.' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (v_request.requester_user_id = auth.uid() OR public.is_admin()) THEN
    RAISE EXCEPTION '신청자만 취소할 수 있습니다.' USING ERRCODE = '42501';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION '이미 종료된 결재는 취소할 수 없습니다.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.approval_request
     SET status = 'cancelled', decided_at = now(), updated_at = now()
   WHERE id = p_request_id;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."cancel_approval_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_signature_request"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_request public.signature_request;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '28000';
  end if;

  select * into v_request from public.signature_request where id = p_request_id for update;
  if not found then
    raise exception '서명 요청을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not coalesce(v_request.requester_user_id = auth.uid(), false) and not public.is_admin() then
    raise exception '요청자만 취소할 수 있습니다.' using errcode = '42501';
  end if;
  if v_request.status <> 'pending' then
    raise exception '이미 종료된 요청입니다.' using errcode = '22023';
  end if;

  update public.signature_request
     set status = 'cancelled', decided_at = now(), updated_at = now()
   where id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."cancel_signature_request"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_supervision_swap"("p_request" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  update supervision_swap_request set status = 'cancelled', responded_at = now()
  where id = p_request
    and status = 'pending'
    and requester_resource_id in (select public.current_actor_resource_ids());
  if not found then
    raise exception '취소할 수 있는 신청이 없습니다' using errcode = '22023';
  end if;
end;
$$;


ALTER FUNCTION "public"."cancel_supervision_swap"("p_request" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_email_blocklist"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  user_email text;
begin
  user_email := lower(new.email);
  if user_email like 'kijungpt%' or user_email like 'kijunexam%' then
    raise exception 'Login blocked for accounts starting with kijungpt or kijunexam';
  end if;
  return new;
end;
$$;


