CREATE OR REPLACE FUNCTION "public"."check_kijun_domain"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Check if the email ends with @myschool.hs.kr
  IF NEW.email IS NOT NULL AND NEW.email NOT LIKE '%@myschool.hs.kr' THEN
    RAISE EXCEPTION 'Only @myschool.hs.kr domain emails are allowed';
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_kijun_domain"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_resource_duplicate_connection"("p_resource_id" "uuid", "p_current_user_id" "uuid") RETURNS TABLE("is_connected" boolean, "connected_user_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  -- 다른 사용자가 이 resource에 연결되어 있는지 확인
  SELECT ur.user_id INTO v_user_id
  FROM user_resource ur
  WHERE ur.resource_id = p_resource_id
    AND ur.user_id != p_current_user_id
  LIMIT 1;
  
  -- 결과 반환
  IF v_user_id IS NOT NULL THEN
    RETURN QUERY SELECT TRUE, v_user_id;
  ELSE
    RETURN QUERY SELECT FALSE, NULL::UUID;
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_resource_duplicate_connection"("p_resource_id" "uuid", "p_current_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_device_call"("p_action" "text", "p_device_key" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  v_hash text;
  v_args jsonb := coalesce(p_args, '{}'::jsonb);
  v_code text := v_args->>'code';
  v_name text;
  v_purpose text;
  v_pub text;
  v_minutes integer;
begin
  if p_device_key is null or p_device_key !~ '^[A-Za-z0-9_-]{32,128}$' then
    return jsonb_build_object('error', 'invalid_device');
  end if;
  if p_action is null or p_action not in ('start', 'poll', 'extend', 'end', 'forget_profile', 'type_start', 'type_poll', 'type_cancel') then
    return jsonb_build_object('error', 'invalid_action');
  end if;
  v_hash := encode(extensions.digest(p_device_key, 'sha256'), 'hex');

  begin
    if p_action = 'start' then
      v_name := left(btrim(coalesce(v_args->>'name', '')), 40);
      v_purpose := coalesce(v_args->>'purpose', 'session');
      if v_name = '' or coalesce(v_args->>'platform', '') not in ('windows', 'android')
         or v_purpose not in ('session', 'drive') then
        return jsonb_build_object('error', 'invalid_request');
      end if;
      return public.classroom_link_start(v_hash, v_name, v_args->>'platform', v_purpose);
    end if;

    if v_code is null or v_code !~ '^[A-Za-z0-9_-]{16,64}$' then
      return jsonb_build_object('error', 'invalid_code');
    end if;

    if p_action = 'type_start' then
      v_pub := coalesce(v_args->>'device_pub', '');
      if length(v_pub) < 40 or length(v_pub) > 200 or v_pub !~ '^[A-Za-z0-9_-]+$' then
        return jsonb_build_object('error', 'invalid_request');
      end if;
      return public.classroom_type_start(v_hash, v_code, v_pub);
    elsif p_action = 'type_poll' then
      return public.classroom_type_poll(v_hash, v_code);
    elsif p_action = 'type_cancel' then
      return public.classroom_type_cancel(v_hash, v_code);
    elsif p_action = 'poll' then
      return public.classroom_link_poll(v_hash, v_code);
    elsif p_action = 'extend' then
      v_minutes := case when coalesce(v_args->>'minutes', '') ~ '^[0-9]{1,4}$' then (v_args->>'minutes')::integer else 10 end;
      return public.classroom_link_extend(v_hash, v_code, v_minutes);
    elsif p_action = 'forget_profile' then
      return public.classroom_profile_forget(v_hash, v_code);
    end if;
    return public.classroom_link_end(v_hash, v_code);
  exception when others then
    if sqlerrm in ('rate_limited', 'link_expired', 'preset_not_found', 'not_allowed', 'invalid_minutes',
                   'not_session_teacher', 'google_token_required', 'invalid_purpose', 'not_active', 'type_expired',
                   'invalid_payload') then
      return jsonb_build_object('error', sqlerrm);
    end if;
    raise;
  end;
end;
$_$;


ALTER FUNCTION "public"."classroom_device_call"("p_action" "text", "p_device_key" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_link_approve"("p_code" "text", "p_user" "uuid", "p_preset_id" "uuid", "p_secrets" "jsonb", "p_space_session" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v public.classroom_link%rowtype;
  p public.classroom_preset%rowtype;
  v_name text;
  v_email text;
  v_ends timestamptz;
  v_session public.classroom_link%rowtype;
  v_secrets jsonb := coalesce(p_secrets, '{}'::jsonb);
  v_keep boolean := coalesce((p_secrets->>'keep_profile')::boolean, true);
  v_profile jsonb := null;
  v_ref text;
  v_secret text;
begin
  if public.account_link_status(p_user) <> 'linked' or not public.is_staff_teacher_or_admin(p_user) then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;

  select * into v from public.classroom_link where code = p_code for update;
  if not found or v.status <> 'pending' or v.expires_at < now() then
    raise exception 'link_expired' using errcode = 'P0001';
  end if;

  select pr.name, au.email into v_name, v_email
    from auth.users au left join public.profiles pr on pr.id = au.id
   where au.id = p_user;

  if v.purpose = 'drive' then
    -- 지금 이 기기에서 수업 중인 교사 본인만
    select * into v_session from public.classroom_link
     where device_key_hash = v.device_key_hash and purpose = 'session'
       and status in ('approved', 'active') and ends_at > now()
     order by approved_at desc limit 1;
    if not found or v_session.approved_by is distinct from p_user then
      raise exception 'not_session_teacher' using errcode = 'P0001';
    end if;
    if v_secrets->'google' is null then
      raise exception 'google_token_required' using errcode = 'P0001';
    end if;
    update public.classroom_link
       set status = 'approved', approved_by = p_user, approved_at = now(), ends_at = v_session.ends_at,
           handoff = jsonb_build_object(
             'teacher', jsonb_build_object('name', coalesce(v_name, ''), 'email', v_email),
             'google', v_secrets->'google')
     where id = v.id;
    return jsonb_build_object('device_name', v.device_name, 'ends_at', v_session.ends_at, 'title', '드라이브 다시 연결');
  end if;

  select * into p from public.classroom_preset where id = p_preset_id and owner_id = p_user;
  if not found then
    raise exception 'preset_not_found' using errcode = 'P0001';
  end if;

  if v_keep then
    insert into public.classroom_profile_key (device_key_hash, user_id, ref, secret)
    values (v.device_key_hash, p_user,
            translate(encode(extensions.gen_random_bytes(18), 'base64'), '+/', '-_'),
            encode(extensions.gen_random_bytes(32), 'base64'))
    on conflict (device_key_hash, user_id) do update set last_used_at = now()
    returning ref, secret into v_ref, v_secret;
    v_profile := jsonb_build_object('ref', v_ref, 'key', v_secret);
  else
    delete from public.classroom_profile_key where device_key_hash = v.device_key_hash and user_id = p_user;
  end if;

  v_ends := now() + make_interval(mins => p.auto_end_minutes);

  update public.classroom_link
     set status = 'approved', approved_by = p_user, approved_at = now(), preset_id = p.id,
         space_session_id = p_space_session, ends_at = v_ends,
         handoff = jsonb_build_object(
           'teacher', jsonb_build_object('name', coalesce(v_name, ''), 'email', v_email),
           'preset', jsonb_build_object(
             'id', p.id, 'title', p.title, 'section_name', p.section_name,
             'items', p.items, 'auto_end_minutes', p.auto_end_minutes)
         ) || (v_secrets - 'keep_profile')
           || case when v_profile is null then '{}'::jsonb else jsonb_build_object('profile', v_profile) end
   where id = v.id;

  insert into public.classroom_device (key_hash, name, platform, last_user_id)
  values (v.device_key_hash, v.device_name, v.platform, p_user)
  on conflict (key_hash) do update
     set name = excluded.name, platform = excluded.platform,
         last_seen_at = now(), last_user_id = excluded.last_user_id;

  update public.classroom_preset set last_used_at = now() where id = p.id;

  return jsonb_build_object('device_name', v.device_name, 'ends_at', v_ends, 'title', p.title);
end;
$$;


ALTER FUNCTION "public"."classroom_link_approve"("p_code" "text", "p_user" "uuid", "p_preset_id" "uuid", "p_secrets" "jsonb", "p_space_session" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_link_end"("p_key_hash" "text", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_session uuid;
begin
  update public.classroom_link
     set status = case when status = 'pending' then 'cancelled' else 'ended' end,
         ended_at = now(), handoff = null
   where code = p_code and device_key_hash = p_key_hash and status in ('pending', 'approved', 'active')
  returning space_session_id into v_session;
  perform public.classroom_link_revoke(v_session);
  return jsonb_build_object('status', 'ended');
end;
$$;


ALTER FUNCTION "public"."classroom_link_end"("p_key_hash" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_link_extend"("p_key_hash" "text", "p_code" "text", "p_minutes" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ends timestamptz;
begin
  if p_minutes is null or p_minutes < 1 or p_minutes > 60 then
    raise exception 'invalid_minutes' using errcode = 'P0001';
  end if;
  update public.classroom_link
     set ends_at = least(greatest(ends_at, now()) + make_interval(mins => p_minutes),
                         approved_at + interval '4 hours')
   where code = p_code and device_key_hash = p_key_hash and status = 'active'
  returning ends_at into v_ends;
  if v_ends is null then
    return jsonb_build_object('status', 'ended');
  end if;
  return jsonb_build_object('status', 'active', 'ends_at', v_ends);
end;
$$;


ALTER FUNCTION "public"."classroom_link_extend"("p_key_hash" "text", "p_code" "text", "p_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_link_inspect"("p_code" "text", "p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v public.classroom_link%rowtype;
  v_status text;
begin
  select * into v from public.classroom_link where code = p_code;
  if not found then
    return jsonb_build_object('status', 'unknown');
  end if;
  v_status := v.status;
  if v_status = 'pending' and v.expires_at < now() then
    v_status := 'expired';
  end if;
  -- 승인 뒤의 정보는 승인한 교사에게만
  if v_status in ('approved', 'active', 'ended') and v.approved_by is distinct from p_user then
    return jsonb_build_object('status', 'taken');
  end if;
  return jsonb_build_object(
    'status', v_status, 'purpose', v.purpose, 'device_name', v.device_name, 'platform', v.platform,
    'expires_at', v.expires_at, 'ends_at', v.ends_at, 'preset_id', v.preset_id);
end;
$$;


ALTER FUNCTION "public"."classroom_link_inspect"("p_code" "text", "p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_link_poll"("p_key_hash" "text", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v public.classroom_link%rowtype;
  v_handoff jsonb;
begin
  select * into v from public.classroom_link
   where code = p_code and device_key_hash = p_key_hash
   for update;
  if not found then
    return jsonb_build_object('status', 'unknown');
  end if;

  update public.classroom_device set last_seen_at = now() where key_hash = p_key_hash;

  if v.status = 'pending' then
    if v.expires_at < now() then
      return jsonb_build_object('status', 'expired');
    end if;
    return jsonb_build_object('status', 'pending', 'expires_at', v.expires_at);
  end if;

  if v.status = 'approved' then
    -- 승인 뒤 5분 안에 받아 가지 않으면 버린다(기기가 꺼졌다)
    if v.approved_at < now() - interval '5 minutes' then
      update public.classroom_link set status = 'ended', ended_at = now(), handoff = null where id = v.id;
      perform public.classroom_link_revoke(v.space_session_id);
      return jsonb_build_object('status', 'ended');
    end if;
    v_handoff := v.handoff;
    update public.classroom_link set status = 'active', handoff = null where id = v.id;
    return jsonb_build_object('status', 'approved', 'handoff', v_handoff, 'ends_at', v.ends_at);
  end if;

  if v.status = 'active' then
    if v.ends_at < now() then
      update public.classroom_link set status = 'ended', ended_at = now() where id = v.id;
      perform public.classroom_link_revoke(v.space_session_id);
      return jsonb_build_object('status', 'ended');
    end if;
    return jsonb_build_object('status', 'active', 'ends_at', v.ends_at);
  end if;

  return jsonb_build_object('status', v.status);
end;
$$;


ALTER FUNCTION "public"."classroom_link_poll"("p_key_hash" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_link_revoke"("p_session" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if p_session is not null then
    delete from auth.sessions where id = p_session;
  end if;
end;
$$;


ALTER FUNCTION "public"."classroom_link_revoke"("p_session" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_link_start"("p_key_hash" "text", "p_name" "text", "p_platform" "text", "p_purpose" "text" DEFAULT 'session'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_code text;
  v_expires timestamptz := now() + interval '10 minutes';
begin
  if p_purpose not in ('session', 'drive') then
    raise exception 'invalid_purpose' using errcode = 'P0001';
  end if;
  if (select count(*) from public.classroom_link
       where device_key_hash = p_key_hash and created_at > now() - interval '10 minutes') >= 20 then
    raise exception 'rate_limited' using errcode = 'P0001';
  end if;

  -- 오래된 QR 정리 — 끝난 연결은 handoff 없이 30일 기록으로 남긴다
  delete from public.classroom_link
   where (status in ('pending', 'cancelled') and expires_at < now() - interval '1 day')
      or (status = 'ended' and coalesce(ended_at, created_at) < now() - interval '30 days');

  -- 같은 목적의 대기 QR 만 접는다 — 수업 중 드라이브 QR 을 띄워도 수업 연결은 그대로다
  update public.classroom_link set status = 'cancelled'
   where device_key_hash = p_key_hash and status = 'pending' and purpose = p_purpose;

  v_code := translate(encode(gen_random_bytes(18), 'base64'), '+/', '-_');
  insert into public.classroom_link (code, device_key_hash, device_name, platform, expires_at, purpose)
  values (v_code, p_key_hash, btrim(p_name), p_platform, v_expires, p_purpose);

  return jsonb_build_object('code', v_code, 'expires_at', v_expires);
end;
$$;


ALTER FUNCTION "public"."classroom_link_start"("p_key_hash" "text", "p_name" "text", "p_platform" "text", "p_purpose" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_link_stop"("p_code" "text", "p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v public.classroom_link%rowtype;
begin
  select * into v from public.classroom_link where code = p_code for update;
  if not found then
    return jsonb_build_object('status', 'unknown');
  end if;
  if v.status = 'pending' then
    update public.classroom_link set status = 'cancelled' where id = v.id;
    return jsonb_build_object('status', 'cancelled');
  end if;
  if v.approved_by is distinct from p_user then
    raise exception 'not_allowed' using errcode = 'P0001';
  end if;
  if v.status in ('approved', 'active') then
    update public.classroom_link set status = 'ended', ended_at = now(), handoff = null where id = v.id;
    perform public.classroom_link_revoke(v.space_session_id);
  end if;
  return jsonb_build_object('status', 'ended');
end;
$$;


ALTER FUNCTION "public"."classroom_link_stop"("p_code" "text", "p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_link_sweep"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  n integer := 0;
begin
  for r in
    update public.classroom_link
       set status = 'ended', ended_at = now(), handoff = null
     where (status = 'active' and ends_at < now())
        or (status = 'approved' and approved_at < now() - interval '5 minutes')
    returning space_session_id
  loop
    perform public.classroom_link_revoke(r.space_session_id);
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."classroom_link_sweep"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_preset_items_valid"("p_items" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_item jsonb;
  v_kind text;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 30 then
    return false;
  end if;
  for v_item in select value from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item) <> 'object' then
      return false;
    end if;
    v_kind := v_item->>'kind';
    if char_length(coalesce(v_item->>'name', '')) > 120 then
      return false;
    end if;
    if v_kind = 'drive' then
      if coalesce(v_item->>'id', '') !~ '^[A-Za-z0-9_-]{10,128}$' then return false; end if;
    elsif v_kind = 'url' then
      if coalesce(v_item->>'url', '') !~ '^https?://\S+$'
         or char_length(v_item->>'url') > 2000 then return false; end if;
    elsif v_kind = 'program' then
      -- 기기가 아는 이름(허용 목록)만 실행한다. 실행 파일 경로는 서버에 두지 않는다.
      if coalesce(v_item->>'program', '') !~ '^[a-z0-9_-]{1,40}$' then return false; end if;
    elsif v_kind = 'space' then
      if coalesce(v_item->>'path', '') !~ '^/[A-Za-z0-9/_?=&.-]{0,200}$' then return false; end if;
    else
      return false;
    end if;
  end loop;
  return true;
end;
$_$;


ALTER FUNCTION "public"."classroom_preset_items_valid"("p_items" "jsonb") OWNER TO "postgres";


