CREATE OR REPLACE FUNCTION "public"."classroom_profile_forget"("p_key_hash" "text", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_user uuid;
begin
  select approved_by into v_user from public.classroom_link
   where code = p_code and device_key_hash = p_key_hash and purpose = 'session' and status = 'active';
  if v_user is null then
    return jsonb_build_object('status', 'not_active');
  end if;
  delete from public.classroom_profile_key where device_key_hash = p_key_hash and user_id = v_user;
  return jsonb_build_object('status', 'forgotten');
end;
$$;


