CREATE OR REPLACE FUNCTION "public"."classroom_type_cancel"("p_key_hash" "text", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  delete from public.classroom_type_relay where code = p_code and device_key_hash = p_key_hash;
  return jsonb_build_object('status', 'cancelled');
end;
$$;


ALTER FUNCTION "public"."classroom_type_cancel"("p_key_hash" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_type_inspect"("p_code" "text", "p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v public.classroom_type_relay%rowtype;
begin
  select * into v from public.classroom_type_relay where code = p_code;
  if not found or v.expires_at < now() then
    return jsonb_build_object('status', 'expired');
  end if;
  if v.teacher_id <> p_user then
    return jsonb_build_object('status', 'not_session_teacher');
  end if;
  return jsonb_build_object('status', case when v.payload is null then 'pending' else 'sent' end,
                            'device_name', v.device_name, 'expires_at', v.expires_at);
end;
$$;


ALTER FUNCTION "public"."classroom_type_inspect"("p_code" "text", "p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_type_poll"("p_key_hash" "text", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v public.classroom_type_relay%rowtype;
begin
  select * into v from public.classroom_type_relay where code = p_code and device_key_hash = p_key_hash for update;
  if not found or v.expires_at < now() then
    delete from public.classroom_type_relay where code = p_code and device_key_hash = p_key_hash;
    return jsonb_build_object('status', 'expired');
  end if;
  if v.payload is null then
    return jsonb_build_object('status', 'pending');
  end if;
  delete from public.classroom_type_relay where code = p_code;        -- 한 번 받아 가면 지운다
  return jsonb_build_object('status', 'sent', 'payload', v.payload);
end;
$$;


ALTER FUNCTION "public"."classroom_type_poll"("p_key_hash" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_type_start"("p_key_hash" "text", "p_session_code" "text", "p_device_pub" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v public.classroom_link%rowtype;
  v_code text;
  v_expires timestamptz := now() + interval '3 minutes';
begin
  delete from public.classroom_type_relay where expires_at < now() - interval '1 minute';
  select * into v from public.classroom_link
   where code = p_session_code and device_key_hash = p_key_hash and purpose = 'session'
     and status = 'active' and ends_at > now() and approved_by is not null;
  if not found then
    raise exception 'not_active';
  end if;
  -- 한 기기에 하나만 — 새로 누르면 앞의 것은 지운다
  delete from public.classroom_type_relay where device_key_hash = p_key_hash;
  v_code := translate(encode(gen_random_bytes(18), 'base64'), '+/', '-_');
  insert into public.classroom_type_relay (code, device_key_hash, link_id, teacher_id, device_name, device_pub, expires_at)
  values (v_code, p_key_hash, v.id, v.approved_by, v.device_name, p_device_pub, v_expires);
  return jsonb_build_object('code', v_code, 'expires_at', v_expires);
end;
$$;


ALTER FUNCTION "public"."classroom_type_start"("p_key_hash" "text", "p_session_code" "text", "p_device_pub" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_type_submit"("p_code" "text", "p_user" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v public.classroom_type_relay%rowtype;
  v_epk text := coalesce(p_payload->>'epk', '');
  v_iv text := coalesce(p_payload->>'iv', '');
  v_ct text := coalesce(p_payload->>'ct', '');
begin
  select * into v from public.classroom_type_relay where code = p_code for update;
  if not found or v.expires_at < now() then
    raise exception 'type_expired';
  end if;
  if v.teacher_id <> p_user then
    raise exception 'not_session_teacher';
  end if;
  if v.payload is not null then
    raise exception 'type_expired';      -- 한 번만
  end if;
  if jsonb_typeof(p_payload) <> 'object'
     or v_epk !~ '^[A-Za-z0-9_-]+$' or char_length(v_epk) not between 40 and 200
     or v_iv !~ '^[A-Za-z0-9_-]+$' or char_length(v_iv) not between 12 and 32
     or v_ct !~ '^[A-Za-z0-9_-]+$' or char_length(v_ct) not between 20 and 1400 then
    raise exception 'invalid_payload';
  end if;
  update public.classroom_type_relay
     set payload = jsonb_build_object('epk', v_epk, 'iv', v_iv, 'ct', v_ct),
         expires_at = least(expires_at, now() + interval '1 minute')
   where code = p_code;
  return jsonb_build_object('status', 'sent', 'device_name', v.device_name);
end;
$_$;


ALTER FUNCTION "public"."classroom_type_submit"("p_code" "text", "p_user" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classroom_type_sweep"() RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  delete from public.classroom_type_relay r
   where r.expires_at < now()
      or exists (select 1 from public.classroom_link l where l.id = r.link_id and l.status <> 'active');
$$;


ALTER FUNCTION "public"."classroom_type_sweep"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_old_schema"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Drop old constraints
  ALTER TABLE meeting DROP CONSTRAINT IF EXISTS meeting_section_id_fkey;
  ALTER TABLE meeting DROP CONSTRAINT IF EXISTS meeting_created_by_fkey;
  
  -- Drop old columns
  ALTER TABLE section DROP COLUMN IF EXISTS grade;
  ALTER TABLE meeting DROP COLUMN IF EXISTS section_id;
  ALTER TABLE meeting DROP COLUMN IF EXISTS created_by;
  
  -- Add new constraints
  ALTER TABLE meeting ADD CONSTRAINT meeting_creator_fkey 
    FOREIGN KEY (creator) REFERENCES resource(id);
  
  -- Drop junction tables
  DROP TABLE IF EXISTS section_member CASCADE;
  DROP TABLE IF EXISTS meeting_allocation CASCADE;
  
  -- Update tracking
  UPDATE schema_migration_tracking 
  SET status = 'completed', completed_at = now()
  WHERE table_name IN ('section_member_cleanup', 'meeting_allocation_cleanup');
  
  RETURN 'Schema cleanup completed successfully';
END;
$$;


ALTER FUNCTION "public"."cleanup_old_schema"() OWNER TO "postgres";


