CREATE OR REPLACE FUNCTION "public"."close_collect_on_action_archive"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.archived_at is not null and old.archived_at is null then
    update public.collect_request
       set status = 'closed', closed_at = now(), closed_reason = 'archived'
     where action_id = new.id and status = 'open';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."close_collect_on_action_archive"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_collect_on_task_end"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status in ('completed', 'cancelled') and old.status is distinct from new.status then
    update public.collect_request
       set status = 'closed', closed_at = now(), closed_reason = 'task_' || new.status
     where task_id = new.id and status = 'open';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."close_collect_on_task_end"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_activities"("p_club_year_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with me as (select * from public.club_year where id = p_club_year_id),
  hosts as (
    select y.activity_host_id host_id, y.name host_name from public.club_year y, me
    where y.club_id = me.club_id and y.activity_host_id is not null
    union
    select al.activity_host_id, h.name from public.club_host_alias al join public.activity_host h on h.id = al.activity_host_id, me
    where al.club_id = me.club_id
  ),
  acts as (
    select distinct on (a.id) a.*, ho.host_name
    from hosts ho join public.activity_host_link l on l.host_id = ho.host_id join public.activity a on a.id = l.activity_id
    order by a.id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id, 'name', a.name, 'area', a.area, 'academic_year', a.academic_year, 'starts_on', a.starts_on, 'ends_on', a.ends_on,
    'place', a.place, 'hours', a.hours, 'status', a.status, 'content', left(a.content, 300),
    'host_name', a.host_name, 'this_year', coalesce(a.academic_year = me.academic_year, false),
    'participants', (select count(*) from public.activity_participation p where p.activity_id = a.id),
    'mine', exists (select 1 from public.activity_participation p where p.activity_id = a.id and p.student_code = public.current_student_code()))
    order by coalesce(a.academic_year = me.academic_year, false) desc, a.academic_year desc nulls last, a.starts_on desc nulls last, a.created_at desc), '[]'::jsonb)
  from acts a, me;
$$;


ALTER FUNCTION "public"."club_activities"("p_club_year_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_applications"("p_club_year_id" "uuid", "p_recruit_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not club_private.can_judge(p_club_year_id) then raise exception '지원자는 기장·지도교사·동아리 담당자가 봅니다' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', a.id, 'recruit_id', a.recruit_id, 'recruit', rc.title, 'code', a.student_code, 'name', rs.name,
             'grade', a.grade, 'class', a.class_num, 'number', a.number, 'choice_rank', a.choice_rank, 'motivation', a.motivation,
             'status', a.status, 'interview_note', a.interview_note, 'judged_at', a.judged_at,
             -- 다른 곳에 이미 확정(정규)이면 여기 확정은 안 된다 — 미리 보여 준다
             'enrolled_elsewhere', (select y2.name from public.club_member m join public.club_year y2 on y2.id = m.club_year_id
                                    where m.student_code = a.student_code and m.status = 'confirmed' and y2.kind = 'regular' and y2.status = 'active'
                                      and y2.academic_year = y.academic_year and y2.id <> a.club_year_id limit 1))
           order by (a.status = 'applied') desc, a.choice_rank, a.grade, a.class_num, a.number)
    from public.club_application a join public.club_recruit rc on rc.id = a.recruit_id join public.club_year y on y.id = a.club_year_id
    left join public.resource rs on rs.id = a.student_resource_id
    where a.club_year_id = p_club_year_id and a.status <> 'withdrawn' and (p_recruit_id is null or a.recruit_id = p_recruit_id)), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."club_applications"("p_club_year_id" "uuid", "p_recruit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_apply"("p_recruit_id" "uuid", "p_choices" "uuid"[], "p_motivations" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.club_recruit%rowtype; v_code text := public.current_student_code(); s record; v_id uuid; i int := 0;
begin
  if auth.uid() is null or v_code is null then raise exception '학생만 지원합니다' using errcode = '42501'; end if;
  select * into r from public.club_recruit where id = p_recruit_id;
  if not found then raise exception '회차를 찾지 못했습니다' using errcode = 'P0002'; end if;
  if not (r.status = 'open' and now() between r.opens_at and r.closes_at) then raise exception '지원 기간이 아닙니다' using errcode = '22023'; end if;
  select rs.id, (rs.meta->>'grade')::int g, (rs.meta->>'class')::int c, (rs.meta->>'number')::int n into s
  from public.resource rs where rs.type = 'student' and rs.status = 'active' and rs.meta->>'id' = v_code;
  if s.id is null then raise exception '재학생 명단에서 찾지 못했습니다' using errcode = '42501'; end if;
  if not s.g = any (r.target_grades) then raise exception '이번 편성 대상 학년이 아닙니다' using errcode = '22023'; end if;
  if cardinality(coalesce(p_choices, '{}')) = 0 or cardinality(p_choices) > r.max_choices then
    raise exception '지망은 1~%개입니다', r.max_choices using errcode = '22023';
  end if;
  if cardinality(p_choices) <> (select count(distinct x) from unnest(p_choices) x) then raise exception '같은 동아리를 두 번 고를 수 없습니다' using errcode = '22023'; end if;
  if exists (select 1 from unnest(p_choices) x where not exists (
      select 1 from public.club_year y where y.id = x and y.academic_year = r.academic_year and y.status = 'active' and (r.kind = 'all' or y.kind = r.kind))) then
    raise exception '이번 편성에 없는 동아리가 있습니다' using errcode = '22023';
  end if;
  if exists (select 1 from public.club_application a where a.recruit_id = r.id and a.student_code = v_code and a.status in ('accepted', 'enrolled', 'rejected')) then
    raise exception '면접 결과가 나온 뒤에는 지망을 바꿀 수 없습니다' using errcode = '22023';
  end if;
  delete from public.club_application a where a.recruit_id = r.id and a.student_code = v_code;
  foreach v_id in array p_choices loop
    i := i + 1;
    insert into public.club_application (recruit_id, club_year_id, student_code, student_resource_id, grade, class_num, number, choice_rank, motivation)
    values (r.id, v_id, v_code, s.id, s.g, s.c, s.n, i, nullif(btrim(coalesce(p_motivations->>v_id::text, '')), ''));
  end loop;
  return public.club_recruit_get(r.id);
end $$;


ALTER FUNCTION "public"."club_apply"("p_recruit_id" "uuid", "p_choices" "uuid"[], "p_motivations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_decide_members"("p_member_ids" "uuid"[], "p_decision" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_years uuid[]; v_y uuid; v_n int;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if p_decision not in ('confirm', 'reject', 'remove') then
    raise exception 'decision 은 confirm · reject · remove' using errcode = '22023';
  end if;
  select array_agg(distinct club_year_id) into v_years from public.club_member where id = any(p_member_ids);
  if v_years is null then raise exception '명단 줄을 찾지 못했습니다' using errcode = 'P0002'; end if;
  foreach v_y in array v_years loop
    if not public.can_manage_club_year(v_y) then
      raise exception '명단은 지도교사·동아리 담당자가 확정합니다' using errcode = '42501';
    end if;
  end loop;
  update public.club_member set
    status = case p_decision when 'confirm' then 'confirmed' else 'removed' end,
    role = case when p_decision = 'confirm' then role else 'member' end,
    note = coalesce(nullif(btrim(p_note), ''), note),
    decided_by = auth.uid(), decided_at = now()
  where id = any(p_member_ids)
    and ((p_decision in ('confirm', 'reject') and status = 'pending') or (p_decision = 'remove' and status = 'confirmed'));
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'changed', v_n);
end $$;


ALTER FUNCTION "public"."club_decide_members"("p_member_ids" "uuid"[], "p_decision" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_decide_proposal"("p_club_year_id" "uuid", "p_approve" boolean, "p_teacher_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare y public.club_year%rowtype;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.is_club_manager() then raise exception '개설은 동아리 담당자가 결정합니다' using errcode = '42501'; end if;
  select * into y from public.club_year where id = p_club_year_id for update;
  if not found or y.status <> 'proposed' then raise exception '심사 중인 신청이 아닙니다' using errcode = '22023'; end if;
  if p_approve then
    if cardinality(coalesce(p_teacher_ids, '{}')) = 0 then raise exception '지도교사를 한 명 이상 정해 주세요' using errcode = '22023'; end if;
    perform public.club_set_advisors(p_club_year_id, p_teacher_ids);
    update public.club_year set status = 'active', meta = meta || jsonb_build_object('approved_at', now()), updated_at = now() where id = p_club_year_id;
    update public.club_member set status = 'confirmed', decided_by = auth.uid(), decided_at = now()
    where club_year_id = p_club_year_id and source = 'proposal';
  else
    update public.club_year set status = 'rejected', meta = meta || jsonb_build_object('rejected_reason', nullif(btrim(p_reason), ''), 'rejected_at', now()),
      updated_at = now() where id = p_club_year_id;
  end if;
  return public.club_get(p_club_year_id);
end $$;


ALTER FUNCTION "public"."club_decide_proposal"("p_club_year_id" "uuid", "p_approve" boolean, "p_teacher_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_delete_note"("p_note_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_y uuid;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select club_year_id into v_y from public.club_observation where id = p_note_id;
  if v_y is null then raise exception '기록을 찾지 못했습니다' using errcode = 'P0002'; end if;
  if not public.can_manage_club_year(v_y) then raise exception '지울 수 없습니다' using errcode = '42501'; end if;
  delete from public.club_observation where id = p_note_id;
  return jsonb_build_object('ok', true);
end $$;


ALTER FUNCTION "public"."club_delete_note"("p_note_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_finalize_applications"("p_club_year_id" "uuid", "p_recruit_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare a record; v_added int := 0; v_skipped jsonb := '[]'::jsonb; y public.club_year%rowtype; v_other text;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.can_manage_club_year(p_club_year_id) then raise exception '명단 확정은 지도교사·동아리 담당자가 합니다' using errcode = '42501'; end if;
  select * into y from public.club_year where id = p_club_year_id;
  for a in select ap.* from public.club_application ap
           where ap.club_year_id = p_club_year_id and ap.status = 'accepted' and (p_recruit_id is null or ap.recruit_id = p_recruit_id)
           order by ap.choice_rank, ap.grade, ap.class_num, ap.number loop
    v_other := null;
    if y.kind = 'regular' then
      select y2.name into v_other from public.club_member m join public.club_year y2 on y2.id = m.club_year_id
      where m.student_code = a.student_code and m.status = 'confirmed' and y2.kind = 'regular' and y2.status = 'active'
        and y2.academic_year = y.academic_year and y2.id <> y.id limit 1;
    end if;
    if v_other is not null then
      v_skipped := v_skipped || jsonb_build_object('student', concat_ws('-', a.grade, a.class_num, a.number), 'reason', format('이미 «%s» 부원', v_other));
      continue;
    end if;
    insert into public.club_member (club_year_id, student_code, student_resource_id, grade, class_num, number, status, source, note, decided_by, decided_at)
    values (p_club_year_id, a.student_code, a.student_resource_id, a.grade, a.class_num, a.number, 'confirmed', 'recruit', a.interview_note, auth.uid(), now())
    on conflict (club_year_id, student_code) do update set status = 'confirmed', source = 'recruit', decided_by = excluded.decided_by, decided_at = now();
    update public.club_application set status = 'enrolled', updated_at = now() where id = a.id;
    -- 같은 회차의 다른(정규) 지원은 정리 — 한 곳에 들어갔다
    if y.kind = 'regular' then
      update public.club_application o set status = 'withdrawn', updated_at = now()
      from public.club_year oy
      where o.recruit_id = a.recruit_id and o.student_code = a.student_code and o.id <> a.id and oy.id = o.club_year_id
        and oy.kind = 'regular' and o.status in ('applied', 'accepted', 'rejected');
    end if;
    v_added := v_added + 1;
  end loop;
  return jsonb_build_object('ok', true, 'added', v_added, 'skipped', v_skipped);
end $$;


ALTER FUNCTION "public"."club_finalize_applications"("p_club_year_id" "uuid", "p_recruit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_finance_get"("p_club_year_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare f public.club_finance%rowtype; v_line jsonb; v_amt jsonb;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not (public.is_teacher_or_admin(auth.uid()) or public.is_club_manager() or public.club_student_role(p_club_year_id) is not null) then
    raise exception '볼 수 없습니다' using errcode = '42501';
  end if;
  select * into f from public.club_finance where club_year_id = p_club_year_id;
  if f.budget_line_id is not null then
    select jsonb_build_object('id', l.id, 'name', l.name, 'project', p.name, 'budget_amount', l.budget_amount,
             'allocated_to_clubs', (select coalesce(sum(f2.allocated), 0) from public.club_finance f2 where f2.budget_line_id = l.id))
      into v_line
    from public.budget_line l join public.budget_project p on p.id = l.project_id where l.id = f.budget_line_id;
  end if;
  if f.purchase_page_id is not null then v_amt := club_private.page_amounts(f.purchase_page_id); end if;
  return jsonb_build_object(
    'allocated', f.allocated, 'note', f.note, 'budget_line', v_line,
    'page', case when f.purchase_page_id is not null then (select jsonb_build_object('id', pg.id, 'title', pg.title, 'archived', pg.is_archived)
                                                           from public.purchase_request_pages pg where pg.id = f.purchase_page_id) end,
    'amounts', coalesce(v_amt, jsonb_build_object('requested', 0, 'approved', 0, 'ordered', 0, 'pending_items', 0, 'items', 0)),
    'can_allocate', public.is_club_manager(),
    'can_open_page', public.can_manage_club_year(p_club_year_id));
end $$;


