CREATE OR REPLACE FUNCTION "public"."club_finance_overview"("p_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_year int := coalesce(p_year, club_private.current_year());
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not (public.is_teacher_or_admin(auth.uid()) or public.is_club_manager()) then raise exception '교직원만' using errcode = '42501'; end if;
  return coalesce((select jsonb_object_agg(y.id, jsonb_build_object('allocated', f.allocated,
                     'amounts', case when f.purchase_page_id is not null then club_private.page_amounts(f.purchase_page_id) end))
                   from public.club_year y join public.club_finance f on f.club_year_id = y.id
                   where y.academic_year = v_year), '{}'::jsonb);
end $$;


