CREATE OR REPLACE FUNCTION "public"."club_get"("p_club_year_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare y public.club_year%rowtype; v_fac boolean; v_role text; v_manage boolean; v_members jsonb;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into y from public.club_year where id = p_club_year_id;
  if not found then raise exception '동아리를 찾지 못했습니다' using errcode = 'P0002'; end if;
  v_fac := public.is_teacher_or_admin(auth.uid());
  v_manage := public.can_manage_club_year(y.id);
  v_role := club_private.my_role(y.id);
  if not (y.status in ('active', 'inactive') or coalesce(y.created_by = auth.uid(), false) or v_manage) then
    raise exception '볼 수 없는 동아리입니다' using errcode = '42501';
  end if;

  if v_fac or v_manage or public.is_club_manager() then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', m.id, 'code', m.student_code, 'resource_id', m.student_resource_id, 'name', r.name,
             'grade', m.grade, 'class', m.class_num, 'number', m.number, 'role', m.role, 'status', m.status,
             'source', m.source, 'note', m.note, 'enrolled', coalesce(r.status = 'active', false),
             'decided_at', m.decided_at, 'created_at', m.created_at)
           order by (m.status = 'pending') desc, m.status, m.grade, m.class_num, m.number), '[]'::jsonb)
      into v_members
    from public.club_member m left join public.resource r on r.id = m.student_resource_id
    where m.club_year_id = y.id and m.status <> 'removed';
  elsif v_role is not null or exists (select 1 from public.club_member m where m.club_year_id = y.id and m.student_code = public.current_student_code()) then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', m.id, 'code', m.student_code, 'name', r.name, 'grade', m.grade, 'class', m.class_num, 'number', m.number,
             'role', m.role, 'status', m.status, 'mine', m.student_code = public.current_student_code())
           order by m.grade, m.class_num, m.number), '[]'::jsonb)
      into v_members
    from public.club_member m left join public.resource r on r.id = m.student_resource_id
    where m.club_year_id = y.id
      and (m.status = 'confirmed' or m.student_code = public.current_student_code()
           or (v_role = 'leader' and m.status = 'pending'));
  end if;

  return club_private.year_json(y, v_fac or v_manage or v_role is not null)
    || jsonb_build_object(
      'club', (select jsonb_build_object('id', c.id, 'canonical_name', c.canonical_name, 'former_names', coalesce(c.meta -> 'former_names', '[]'::jsonb))
               from public.club c where c.id = y.club_id),
      'lineage', coalesce((select jsonb_agg(jsonb_build_object('id', y2.id, 'academic_year', y2.academic_year, 'name', y2.name, 'status', y2.status,
                                                            'member_count', (select count(*) from public.club_member m where m.club_year_id = y2.id and m.status = 'confirmed'))
                                         order by y2.academic_year desc, y2.name)
                           from public.club_year y2 where y2.club_id = y.club_id and y2.id <> y.id and y2.status in ('active', 'inactive')), '[]'::jsonb),
      'linked_hosts', coalesce((select jsonb_agg(h.name order by h.name) from public.club_host_alias al join public.activity_host h on h.id = al.activity_host_id
                                where al.club_id = y.club_id), '[]'::jsonb),
      'members', v_members,
      'my_role', v_role,
      'can_manage', v_manage,
      'is_manager', public.is_club_manager()
    );
end $$;


ALTER FUNCTION "public"."club_get"("p_club_year_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_host_candidates"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.is_club_manager() then raise exception '동아리 담당자만' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'host_id', h.id, 'name', h.name, 'status', h.status,
      'activities', (select count(*) from public.activity_host_link l where l.host_id = h.id),
      'years', (select jsonb_agg(distinct a.academic_year order by a.academic_year) from public.activity_host_link l join public.activity a on a.id = l.activity_id where l.host_id = h.id),
      'linked_club', (select jsonb_build_object('club_id', c.id, 'name', c.canonical_name) from public.club_host_alias al join public.club c on c.id = al.club_id where al.activity_host_id = h.id),
      'suggestion', (select case when count(distinct y.club_id) = 1 then jsonb_build_object('club_id', min(y.club_id::text), 'name', min(y.name)) end
                     from public.club_year y where club_private.norm_name(y.name) = club_private.norm_name(h.name)))
      order by (select count(*) from public.activity_host_link l where l.host_id = h.id) desc, h.name)
    from public.activity_host h
    where h.kind = 'club' and not exists (select 1 from public.club_year y where y.activity_host_id = h.id)
  ), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."club_host_candidates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_judge_applications"("p_ids" "uuid"[], "p_result" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v uuid; v_n int;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if p_result not in ('accepted', 'rejected', 'applied') then raise exception 'result 는 accepted · rejected · applied' using errcode = '22023'; end if;
  for v in select distinct club_year_id from public.club_application where id = any (p_ids) loop
    if not club_private.can_judge(v) then raise exception '면접 결과는 기장·지도교사·동아리 담당자가 적습니다' using errcode = '42501'; end if;
  end loop;
  update public.club_application set status = p_result,
    interview_note = coalesce(nullif(btrim(p_note), ''), interview_note),
    judged_by = case when p_result = 'applied' then null else auth.uid() end,
    judged_at = case when p_result = 'applied' then null else now() end, updated_at = now()
  where id = any (p_ids) and status in ('applied', 'accepted', 'rejected');
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'changed', v_n);
end $$;


ALTER FUNCTION "public"."club_judge_applications"("p_ids" "uuid"[], "p_result" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_link_host"("p_host_id" "uuid", "p_club_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.is_club_manager() then raise exception '동아리 담당자만' using errcode = '42501'; end if;
  if not exists (select 1 from public.activity_host where id = p_host_id and kind = 'club') then raise exception '동아리 주최가 아닙니다' using errcode = '22023'; end if;
  if exists (select 1 from public.club_year where activity_host_id = p_host_id) then raise exception '이미 동아리 운영 단위의 주최입니다' using errcode = '22023'; end if;
  if p_club_id is null then
    delete from public.club_host_alias where activity_host_id = p_host_id;
  else
    if not exists (select 1 from public.club where id = p_club_id) then raise exception '동아리를 찾지 못했습니다' using errcode = 'P0002'; end if;
    insert into public.club_host_alias (activity_host_id, club_id, linked_by) values (p_host_id, p_club_id, auth.uid())
    on conflict (activity_host_id) do update set club_id = excluded.club_id, linked_by = excluded.linked_by, linked_at = now();
  end if;
  return jsonb_build_object('ok', true);
end $$;


ALTER FUNCTION "public"."club_link_host"("p_host_id" "uuid", "p_club_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_list"("p_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_year int := coalesce(p_year, club_private.current_year()); v_fac boolean; v_mgr boolean;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  v_fac := public.is_teacher_or_admin(auth.uid());
  v_mgr := public.is_club_manager();
  return jsonb_build_object(
    'year', v_year,
    'years', coalesce((select jsonb_agg(distinct academic_year order by academic_year desc) from public.club_year), '[]'::jsonb),
    'is_manager', v_mgr,
    'clubs', coalesce((
      select jsonb_agg(club_private.year_json(y, v_fac or v_mgr or club_private.my_role(y.id) is not null)
                       || jsonb_build_object('my_role', club_private.my_role(y.id))
                       order by (y.status = 'active') desc, y.name)
      from public.club_year y
      where y.academic_year = v_year
        and (y.status in ('active', 'inactive') or y.created_by = auth.uid() or public.can_manage_club_year(y.id))
    ), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."club_list"("p_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_notes"("p_club_year_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare y public.club_year%rowtype;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into y from public.club_year where id = p_club_year_id;
  if not found then raise exception '동아리를 찾지 못했습니다' using errcode = 'P0002'; end if;
  if not public.can_manage_club_year(y.id) then
    raise exception '누가기록은 지도교사·동아리 담당자만 봅니다' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'club_year_id', y.id,
    'students', coalesce((
      select jsonb_agg(jsonb_build_object(
        'code', m.student_code, 'name', r.name, 'grade', m.grade, 'class', m.class_num, 'number', m.number, 'role', m.role,
        'notes', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'period', o.period, 'body', o.body, 'source', o.source,
                                                               'author', ar.name, 'created_at', o.created_at, 'updated_at', o.updated_at)
                                            order by o.created_at desc)
                           from public.club_observation o left join public.resource ar on ar.id = o.author_resource_id
                           where o.club_year_id = y.id and o.student_code = m.student_code), '[]'::jsonb),
        'answers', coalesce((select jsonb_agg(jsonb_build_object('action_id', cr.action_id, 'dimension_key', cr.dimension_key,
                                                                 'values', cr."values", 'updated_at', cr.updated_at)
                                              order by cr.updated_at desc)
                             from public.collect_response cr
                             where cr.unit_key = 'club|' || y.id || '|' || m.student_code), '[]'::jsonb))
        order by m.grade, m.class_num, m.number)
      from public.club_member m left join public.resource r on r.id = m.student_resource_id
      where m.club_year_id = y.id and m.status = 'confirmed'), '[]'::jsonb),
    'requests', coalesce((
      select jsonb_object_agg(ta.id, jsonb_build_object(
        'title', coalesce(nullif(ta.config->'collect'->>'title', ''), ta.title),
        'fields', coalesce(ta.config->'collect'->'fields', '[]'::jsonb),
        'dimensions', coalesce(ta.config->'collect'->'dimensions', '[]'::jsonb)))
      from public.task_action ta
      where ta.id in (select distinct t.action_id from public.collect_target t
                      where t.unit_key like 'club|' || y.id || '|%')), '{}'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."club_notes"("p_club_year_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_open_purchase_page"("p_club_year_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare y public.club_year%rowtype; v_me uuid; v_page uuid;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.can_manage_club_year(p_club_year_id) then raise exception '지도교사·동아리 담당자가 엽니다' using errcode = '42501'; end if;
  select * into y from public.club_year where id = p_club_year_id;
  select purchase_page_id into v_page from public.club_finance where club_year_id = p_club_year_id;
  if v_page is not null then return public.club_finance_get(p_club_year_id); end if;
  select ur.resource_id into v_me from public.user_resource ur join public.resource r on r.id = ur.resource_id
   where ur.user_id = auth.uid() and r.type in ('teacher', 'staff') limit 1;
  if v_me is null then raise exception '교직원 명단에 연결된 계정이 아닙니다' using errcode = '42501'; end if;
  insert into public.purchase_request_pages (title, target_roles, description, period_start, period_end, columns, created_by)
  values (format('[동아리] %s 물품 신청 (%s학년도)', y.name, y.academic_year), array['student', 'teacher'],
          format('%s 부원이 필요한 물품을 신청하고, 지도교사가 승인하면 품의로 넘어갑니다. 이 동아리 부원만 신청할 수 있습니다.', y.name),
          now(), (make_date(y.academic_year + 1, 3, 1)::timestamp at time zone 'Asia/Seoul') - interval '1 second',   -- 학년도 끝(2월 말)까지
          jsonb_build_array(
            jsonb_build_object('id', 'default-name', 'isDefault', true, 'name', '물품명', 'required', true, 'type', 'text'),
            jsonb_build_object('id', 'default-url', 'isDefault', true, 'name', '구매 가능한 주소', 'required', true, 'type', 'url'),
            jsonb_build_object('id', 'default-price', 'isDefault', true, 'name', '개별 가격', 'required', true, 'type', 'number'),
            jsonb_build_object('id', 'default-qty', 'isDefault', true, 'name', '개수', 'required', true, 'type', 'number'),
            jsonb_build_object('id', 'default-note', 'isDefault', true, 'name', '쓰임(어느 활동에)', 'required', false, 'type', 'text')),
          v_me)
  returning id into v_page;
  insert into public.club_finance (club_year_id, purchase_page_id, updated_by) values (p_club_year_id, v_page, auth.uid())
  on conflict (club_year_id) do update set purchase_page_id = excluded.purchase_page_id, updated_by = excluded.updated_by, updated_at = now();
  perform club_private.page_collaborators(p_club_year_id);
  return public.club_finance_get(p_club_year_id);
end $$;


ALTER FUNCTION "public"."club_open_purchase_page"("p_club_year_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_proposals"("p_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', y.id, 'name', y.name, 'category', y.category, 'description', y.description,
                     'status', y.status, 'wish_advisor', y.meta->>'wish_advisor', 'rejected_reason', y.meta->>'rejected_reason', 'created_at', y.created_at,
                     'proposer', (select concat_ws(' ', concat_ws('-', m.grade, m.class_num, m.number), r.name) from public.club_member m
                                  left join public.resource r on r.id = m.student_resource_id where m.club_year_id = y.id and m.source = 'proposal' limit 1))
                   order by (y.status = 'proposed') desc, y.created_at desc)
                   from public.club_year y
                   where y.status in ('proposed', 'rejected') and y.academic_year = coalesce(p_year, club_private.current_year())
                     and (public.is_club_manager() or y.created_by = auth.uid())), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."club_proposals"("p_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_propose_autonomous"("p_name" "text", "p_category" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_wish_advisor" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_code text := public.current_student_code(); v_club uuid; v_year uuid; s record; v_y int := club_private.current_year();
begin
  if auth.uid() is null or v_code is null then raise exception '학생만 신청합니다' using errcode = '42501'; end if;
  if coalesce(btrim(p_name), '') = '' or length(p_name) > 60 then raise exception '이름은 1~60자' using errcode = '22023'; end if;
  if coalesce(btrim(p_description), '') = '' then raise exception '무엇을 하는 동아리인지 적어 주세요' using errcode = '22023'; end if;
  if exists (select 1 from public.club_year where academic_year = v_y and name = btrim(p_name)) then
    raise exception '올해 같은 이름의 동아리가 있습니다' using errcode = '23505';
  end if;
  if (select count(*) from public.club_year where created_by = auth.uid() and status = 'proposed') >= 2 then
    raise exception '심사 중인 신청이 이미 있습니다' using errcode = '22023';
  end if;
  select rs.id, (rs.meta->>'grade')::int g, (rs.meta->>'class')::int c, (rs.meta->>'number')::int n into s
  from public.resource rs where rs.type = 'student' and rs.status = 'active' and rs.meta->>'id' = v_code;
  insert into public.club (canonical_name, meta) values (btrim(p_name), jsonb_build_object('source', 'student_proposal')) returning id into v_club;
  insert into public.club_year (club_id, academic_year, name, kind, category, description, status, created_by, meta)
  values (v_club, v_y, btrim(p_name), 'autonomous', nullif(btrim(p_category), ''), btrim(p_description), 'proposed', auth.uid(),
          jsonb_strip_nulls(jsonb_build_object('wish_advisor', nullif(btrim(p_wish_advisor), ''), 'proposed_by', v_code)))
  returning id into v_year;
  insert into public.club_member (club_year_id, student_code, student_resource_id, grade, class_num, number, role, status, source)
  values (v_year, v_code, s.id, s.g, s.c, s.n, 'leader', 'pending', 'proposal');
  return jsonb_build_object('ok', true, 'club_year_id', v_year);
end $$;


ALTER FUNCTION "public"."club_propose_autonomous"("p_name" "text", "p_category" "text", "p_description" "text", "p_wish_advisor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_recruit_get"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare r public.club_recruit%rowtype;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into r from public.club_recruit where id = p_id;
  if not found then raise exception '회차를 찾지 못했습니다' using errcode = 'P0002'; end if;
  return to_jsonb(r) || jsonb_build_object(
    'is_open', r.status = 'open' and now() between r.opens_at and r.closes_at,
    'clubs', coalesce((select jsonb_agg(jsonb_build_object('club_year_id', y.id, 'name', y.name, 'kind', y.kind, 'capacity', y.capacity,
                         'description', y.description, 'place', y.place,
                         'advisors', (select jsonb_agg(rs.name order by a.is_primary desc) from public.club_advisor a join public.resource rs on rs.id = a.teacher_resource_id where a.club_year_id = y.id),
                         'members', (select count(*) from public.club_member m where m.club_year_id = y.id and m.status = 'confirmed'),
                         'applied', (select count(*) from public.club_application ap where ap.recruit_id = r.id and ap.club_year_id = y.id and ap.status <> 'withdrawn'),
                         'accepted', (select count(*) from public.club_application ap where ap.recruit_id = r.id and ap.club_year_id = y.id and ap.status in ('accepted', 'enrolled')),
                         'enrolled', (select count(*) from public.club_application ap where ap.recruit_id = r.id and ap.club_year_id = y.id and ap.status = 'enrolled'))
                       order by y.name)
                       from public.club_year y
                       where y.academic_year = r.academic_year and y.status = 'active'
                         and (r.kind = 'all' or y.kind = r.kind)), '[]'::jsonb),
    'unassigned', case when public.is_club_manager() then (
      select count(*) from public.resource s
      where s.type = 'student' and s.status = 'active' and (s.meta->>'grade')::int = any (r.target_grades)
        and not exists (select 1 from public.club_member m join public.club_year y on y.id = m.club_year_id
                        where m.student_code = s.meta->>'id' and m.status = 'confirmed' and y.academic_year = r.academic_year
                          and y.kind = 'regular' and y.status = 'active')) end,
    'my_applications', coalesce((select jsonb_agg(jsonb_build_object('id', ap.id, 'club_year_id', ap.club_year_id, 'name', y.name,
                                   'choice_rank', ap.choice_rank, 'motivation', ap.motivation, 'status', ap.status) order by ap.choice_rank)
                                 from public.club_application ap join public.club_year y on y.id = ap.club_year_id
                                 where ap.recruit_id = r.id and ap.student_code = public.current_student_code()), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."club_recruit_get"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_recruit_list"("p_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(r) || jsonb_build_object('is_open', r.status = 'open' and now() between r.opens_at and r.closes_at,
                     'applications', (select count(*) from public.club_application a where a.recruit_id = r.id and a.status <> 'withdrawn'))
                   order by r.opens_at desc), '[]'::jsonb)
  from public.club_recruit r
  where auth.uid() is not null and (p_year is null or r.academic_year = p_year);
$$;


ALTER FUNCTION "public"."club_recruit_list"("p_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_recruit_save"("p_id" "uuid", "p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.is_club_manager() then raise exception '편성은 동아리 담당자가 엽니다' using errcode = '42501'; end if;
  if p_id is null then
    insert into public.club_recruit (academic_year, title, kind, target_grades, max_choices, opens_at, closes_at, guide, created_by)
    values (coalesce((p->>'academic_year')::int, club_private.current_year()), btrim(p->>'title'), coalesce(p->>'kind', 'regular'),
            coalesce((select array_agg(x::int) from jsonb_array_elements_text(case when jsonb_typeof(p->'target_grades') = 'array' then p->'target_grades' end) x), '{1,2}'),
            coalesce((p->>'max_choices')::int, 3), (p->>'opens_at')::timestamptz, (p->>'closes_at')::timestamptz,
            nullif(btrim(p->>'guide'), ''), auth.uid())
    returning id into v_id;
  else
    update public.club_recruit set
      title = coalesce(nullif(btrim(p->>'title'), ''), title),
      target_grades = coalesce((select array_agg(x::int) from jsonb_array_elements_text(case when jsonb_typeof(p->'target_grades') = 'array' then p->'target_grades' end) x), target_grades),
      max_choices = coalesce((p->>'max_choices')::int, max_choices),
      opens_at = coalesce((p->>'opens_at')::timestamptz, opens_at), closes_at = coalesce((p->>'closes_at')::timestamptz, closes_at),
      guide = case when p ? 'guide' then nullif(btrim(p->>'guide'), '') else guide end,
      status = coalesce(p->>'status', status), updated_at = now()
    where id = p_id returning id into v_id;
    if v_id is null then raise exception '회차를 찾지 못했습니다' using errcode = 'P0002'; end if;
  end if;
  return public.club_recruit_get(v_id);
end $$;


ALTER FUNCTION "public"."club_recruit_save"("p_id" "uuid", "p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_request_members"("p_club_year_id" "uuid", "p_students" "jsonb", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare y public.club_year%rowtype; e jsonb; s record; v_errors jsonb := '[]'::jsonb; v_n int := 0;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into y from public.club_year where id = p_club_year_id;
  if not found then raise exception '동아리를 찾지 못했습니다' using errcode = 'P0002'; end if;
  if public.club_student_role(y.id) is null and not public.can_manage_club_year(y.id) then
    raise exception '그 동아리 부원만 명단을 제안할 수 있습니다' using errcode = '42501';
  end if;
  for e in select * from jsonb_array_elements(coalesce(p_students, '[]'::jsonb)) loop
    for s in select * from club_private.resolve_student(e) loop
      if s.err is not null then
        v_errors := v_errors || to_jsonb(s.err);
      elsif y.kind = 'regular' and y.status = 'active' and exists (
        select 1 from public.club_member m2 join public.club_year y2 on y2.id = m2.club_year_id
        where m2.student_code = s.code and m2.status = 'confirmed' and y2.kind = 'regular' and y2.status = 'active'
          and y2.academic_year = y.academic_year and y2.id <> y.id) then
        v_errors := v_errors || to_jsonb(format('%s-%s-%s 은(는) 이미 다른 정규 동아리 부원입니다', s.grade, s.class_num, s.number));
      end if;
    end loop;
  end loop;
  if jsonb_array_length(v_errors) > 0 then
    raise exception '%', (select string_agg(x #>> '{}', ' / ') from jsonb_array_elements(v_errors) x) using errcode = '22023';
  end if;
  for e in select * from jsonb_array_elements(coalesce(p_students, '[]'::jsonb)) loop
    for s in select * from club_private.resolve_student(e) loop
      insert into public.club_member (club_year_id, student_code, student_resource_id, grade, class_num, number, status, source, note, requested_by)
      values (y.id, s.code, s.resource_id, s.grade, s.class_num, s.number, 'pending', 'student_request', nullif(btrim(p_note), ''), auth.uid())
      on conflict (club_year_id, student_code) do update
        set status = 'pending', source = 'student_request', note = excluded.note, requested_by = excluded.requested_by,
            decided_by = null, decided_at = null
        where public.club_member.status = 'removed';
      if found then v_n := v_n + 1; end if;
    end loop;
  end loop;
  return jsonb_build_object('ok', true, 'requested', v_n);
end $$;


ALTER FUNCTION "public"."club_request_members"("p_club_year_id" "uuid", "p_students" "jsonb", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_requests"("p_club_year_id" "uuid" DEFAULT NULL::"uuid", "p_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_year int := coalesce(p_year, club_private.current_year());
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if p_club_year_id is null and not public.is_club_manager() then
    raise exception '전체 요청 현황은 동아리 담당자만 봅니다' using errcode = '42501';
  end if;
  if p_club_year_id is not null and not (public.can_manage_club_year(p_club_year_id) or public.is_teacher_or_admin(auth.uid())) then
    raise exception '볼 수 없습니다' using errcode = '42501';
  end if;
  return coalesce((
    with tg as (
      select t.action_id, split_part(t.unit_key, '|', 2)::uuid club_year_id, t.unit_key
      from public.collect_target t
      where t.removed_at is null and t.unit_key like 'club|%'
        and (p_club_year_id is null or split_part(t.unit_key, '|', 2) = p_club_year_id::text)
    ),
    per_club as (
      select tg.action_id, tg.club_year_id, count(distinct tg.unit_key) units,
             count(distinct tg.unit_key) filter (where exists (
               select 1 from public.collect_response r where r.action_id = tg.action_id and r.unit_key = tg.unit_key)) answered
      from tg group by 1, 2
    )
    select jsonb_agg(jsonb_build_object(
      'action_id', cr.action_id, 'task_id', cr.task_id, 'status', cr.status, 'axis', cr.axis, 'started_at', cr.started_at,
      'title', coalesce(nullif(ta.config->'collect'->>'title', ''), ta.title),
      'due', coalesce(nullif(ta.config->'collect'->>'dueDate', ''), left((select tk.due_date::text from public.task tk where tk.id = cr.task_id), 10)),
      'clubs', (select jsonb_agg(jsonb_build_object('club_year_id', pc.club_year_id, 'name', y.name, 'units', pc.units, 'answered', pc.answered)
                                 order by (pc.answered >= pc.units), y.name)
                from per_club pc join public.club_year y on y.id = pc.club_year_id
                where pc.action_id = cr.action_id and (p_club_year_id is not null or y.academic_year = v_year)))
      order by (cr.status = 'open') desc, cr.started_at desc)
    from public.collect_request cr join public.task_action ta on ta.id = cr.action_id
    where cr.axis in ('club', 'club_member')
      and exists (select 1 from per_club pc join public.club_year y on y.id = pc.club_year_id
                  where pc.action_id = cr.action_id and (p_club_year_id is not null or y.academic_year = v_year))
  ), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."club_requests"("p_club_year_id" "uuid", "p_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_roll_over"("p_from" integer, "p_to" integer, "p_carry_members" boolean DEFAULT false, "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare y record; v_new uuid; v_made int := 0; v_skip jsonb := '[]'::jsonb; v_carried int := 0; v_n int;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.is_club_manager() then raise exception '새 학년도 준비는 동아리 담당자가 합니다' using errcode = '42501'; end if;
  if p_to <> p_from + 1 then raise exception '바로 다음 학년도로만 이어 갑니다' using errcode = '22023'; end if;
  for y in select * from public.club_year where academic_year = p_from and status = 'active'
             and not coalesce((select c.meta->'former_names' @> jsonb_build_array(jsonb_build_object('name', club_year.name, 'until_year', p_from))
                               from public.club c where c.id = club_year.club_id), false)
           order by name loop
    if exists (select 1 from public.club_year n where n.club_id = y.club_id and n.academic_year = p_to)
       or exists (select 1 from public.club_year n where n.academic_year = p_to and n.name = y.name) then
      v_skip := v_skip || to_jsonb(y.name);
      continue;
    end if;
    v_made := v_made + 1;
    if p_check_only then continue; end if;
    insert into public.club_year (club_id, academic_year, name, kind, category, place, capacity, description, status, created_by, meta)
    values (y.club_id, p_to, y.name, y.kind, y.category, y.place, y.capacity, y.description, 'active', auth.uid(),
            jsonb_build_object('rolled_over_from', y.id))
    returning id into v_new;
    insert into public.club_advisor (club_year_id, teacher_resource_id, is_primary)
    select v_new, a.teacher_resource_id, a.is_primary from public.club_advisor a
    join public.resource r on r.id = a.teacher_resource_id and coalesce(r.status, 'active') = 'active'
    where a.club_year_id = y.id;
    if p_carry_members then
      insert into public.club_member (club_year_id, student_code, student_resource_id, grade, class_num, number, status, source, note)
      select v_new, m.student_code, rs.id, (rs.meta->>'grade')::int, (rs.meta->>'class')::int, (rs.meta->>'number')::int,
             'pending', 'carry', format('%s학년도 부원 이월 — 지도교사 확인', p_from)
      from public.club_member m join public.resource rs on rs.id = m.student_resource_id and rs.status = 'active'
      where m.club_year_id = y.id and m.status = 'confirmed' and coalesce(m.grade, 3) < 3;
      get diagnostics v_n = row_count;
      v_carried := v_carried + v_n;
    end if;
  end loop;
  return jsonb_build_object('check_only', p_check_only, 'from', p_from, 'to', p_to, 'clubs', v_made, 'skipped', v_skip, 'carried_members', v_carried);
end $$;


ALTER FUNCTION "public"."club_roll_over"("p_from" integer, "p_to" integer, "p_carry_members" boolean, "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_save"("p_club_year_id" "uuid", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  y public.club_year%rowtype; v_mgr boolean; v_club uuid; v_name text; v_key text;
  v_allowed text[];
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  v_mgr := public.is_club_manager();
  p_patch := coalesce(p_patch, '{}'::jsonb);

  if p_club_year_id is null then
    if not v_mgr then raise exception '동아리를 만들 수 있는 사람은 동아리 담당자뿐입니다' using errcode = '42501'; end if;
    v_name := nullif(btrim(p_patch->>'name'), '');
    if v_name is null then raise exception '동아리 이름을 적어 주세요' using errcode = '22023'; end if;
    v_club := nullif(p_patch->>'club_id', '')::uuid;
    if v_club is null then
      insert into public.club (canonical_name) values (v_name) returning id into v_club;
    else
      update public.club set
        meta = case when canonical_name <> v_name
                    then jsonb_set(meta, '{former_names}', coalesce(meta->'former_names', '[]'::jsonb)
                         || jsonb_build_array(jsonb_build_object('name', canonical_name, 'until_year', coalesce((p_patch->>'academic_year')::int, club_private.current_year()) - 1)))
                    else meta end,
        canonical_name = v_name, updated_at = now()
      where id = v_club;
      if not found then raise exception '이어 갈 동아리를 찾지 못했습니다' using errcode = 'P0002'; end if;
    end if;
    insert into public.club_year (club_id, academic_year, name, kind, category, place, capacity, description, status, created_by)
    values (v_club, coalesce((p_patch->>'academic_year')::int, club_private.current_year()), v_name,
            coalesce(p_patch->>'kind', 'regular'), nullif(btrim(p_patch->>'category'), ''), nullif(btrim(p_patch->>'place'), ''),
            nullif(p_patch->>'capacity', '')::int, nullif(btrim(p_patch->>'description'), ''),
            coalesce(p_patch->>'status', 'active'), auth.uid())
    returning * into y;
    return public.club_get(y.id);
  end if;

  select * into y from public.club_year where id = p_club_year_id for update;
  if not found then raise exception '동아리를 찾지 못했습니다' using errcode = 'P0002'; end if;
  if v_mgr then
    v_allowed := array['name', 'kind', 'category', 'place', 'capacity', 'description', 'status'];
  elsif public.is_club_advisor(y.id) then
    v_allowed := array['place', 'capacity', 'description'];
  else
    raise exception '이 동아리를 고칠 수 없습니다(지도교사·동아리 담당자만)' using errcode = '42501';
  end if;
  for v_key in select jsonb_object_keys(p_patch) loop
    if not v_key = any(v_allowed) then
      raise exception '«%» 칸은 고칠 수 없습니다 (고칠 수 있는 칸: %)', v_key, array_to_string(v_allowed, ', ') using errcode = '42501';
    end if;
  end loop;

  if p_patch ? 'name' and nullif(btrim(p_patch->>'name'), '') is distinct from y.name then
    v_name := nullif(btrim(p_patch->>'name'), '');
    if v_name is null then raise exception '동아리 이름을 비울 수 없습니다' using errcode = '22023'; end if;
    update public.club set
      meta = jsonb_set(meta, '{former_names}', coalesce(meta->'former_names', '[]'::jsonb)
             || jsonb_build_array(jsonb_build_object('name', y.name, 'until_year', y.academic_year))),
      canonical_name = case when not exists (select 1 from public.club_year y2 where y2.club_id = y.club_id and y2.academic_year > y.academic_year)
                            then v_name else canonical_name end,
      updated_at = now()
    where id = y.club_id;
  end if;

  update public.club_year set
    name = case when p_patch ? 'name' then btrim(p_patch->>'name') else name end,
    kind = case when p_patch ? 'kind' then p_patch->>'kind' else kind end,
    category = case when p_patch ? 'category' then nullif(btrim(p_patch->>'category'), '') else category end,
    place = case when p_patch ? 'place' then nullif(btrim(p_patch->>'place'), '') else place end,
    capacity = case when p_patch ? 'capacity' then nullif(p_patch->>'capacity', '')::int else capacity end,
    description = case when p_patch ? 'description' then nullif(btrim(p_patch->>'description'), '') else description end,
    status = case when p_patch ? 'status' then p_patch->>'status' else status end,
    updated_at = now()
  where id = y.id;
  return public.club_get(y.id);
end $$;


ALTER FUNCTION "public"."club_save"("p_club_year_id" "uuid", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_save_note"("p_club_year_id" "uuid", "p_student_code" "text", "p_body" "text", "p_note_id" "uuid" DEFAULT NULL::"uuid", "p_period" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'manual'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_id uuid; v_res uuid; v_me uuid;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.can_manage_club_year(p_club_year_id) then
    raise exception '누가기록은 지도교사·동아리 담당자가 씁니다' using errcode = '42501';
  end if;
  if coalesce(btrim(p_body), '') = '' then raise exception '내용을 적어 주세요' using errcode = '22023'; end if;
  if coalesce(p_source, 'manual') not in ('manual', 'agent') then raise exception 'source 는 manual · agent' using errcode = '22023'; end if;
  select student_resource_id into v_res from public.club_member
   where club_year_id = p_club_year_id and student_code = p_student_code and status = 'confirmed';
  if not found then raise exception '이 동아리의 확정 부원이 아닙니다' using errcode = '22023'; end if;
  select ur.resource_id into v_me from public.user_resource ur join public.resource r on r.id = ur.resource_id
   where ur.user_id = auth.uid() and r.type in ('teacher', 'staff') limit 1;
  if p_note_id is null then
    insert into public.club_observation (club_year_id, student_code, student_resource_id, period, body, source, author_resource_id)
    values (p_club_year_id, p_student_code, v_res, nullif(btrim(p_period), ''), btrim(p_body), coalesce(p_source, 'manual'), v_me)
    returning id into v_id;
  else
    update public.club_observation set body = btrim(p_body), period = nullif(btrim(p_period), ''), updated_at = now()
     where id = p_note_id and club_year_id = p_club_year_id and student_code = p_student_code
    returning id into v_id;
    if v_id is null then raise exception '고칠 기록을 찾지 못했습니다' using errcode = 'P0002'; end if;
  end if;
  return jsonb_build_object('ok', true, 'id', v_id);
end $$;


ALTER FUNCTION "public"."club_save_note"("p_club_year_id" "uuid", "p_student_code" "text", "p_body" "text", "p_note_id" "uuid", "p_period" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_send_request"("p_title" "text", "p_axis" "text", "p_fields" "jsonb", "p_due" "date" DEFAULT NULL::"date", "p_club_year_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_guide" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT 'private'::"text", "p_year" integer DEFAULT NULL::integer, "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_year int := coalesce(p_year, club_private.current_year());
  v_me uuid; v_me_name text; v_names text[]; v_rule jsonb; v_cfg jsonb; v_res jsonb; v_fields jsonb := '[]'; f jsonb; i int := 0;
  v_work uuid; v_task uuid; v_action uuid; def record; v_wname text; v_start jsonb;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.is_club_manager() then raise exception '동아리 요청은 동아리 담당자가 보냅니다' using errcode = '42501'; end if;
  if coalesce(btrim(p_title), '') = '' or length(p_title) > 120 then raise exception '제목은 1~120자입니다' using errcode = '22023'; end if;
  if p_axis not in ('club', 'club_member') then raise exception '줄 단위는 club(동아리마다) · club_member(부원마다)' using errcode = '22023'; end if;
  if coalesce(p_visibility, 'private') not in ('private', 'shared') then raise exception 'visibility 는 private · shared' using errcode = '22023'; end if;
  for f in select e from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) e loop
    i := i + 1;
    if coalesce(f->>'type', 'text') not in ('yesno', 'select', 'text', 'number', 'date') then
      raise exception '%번째 항목 형식은 yesno·select·text·number·date', i using errcode = '22023';
    end if;
    if coalesce(btrim(f->>'label'), '') = '' then raise exception '%번째 항목에 이름이 없습니다', i using errcode = '22023'; end if;
    v_fields := v_fields || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'key', 'f' || i, 'label', btrim(f->>'label'), 'type', coalesce(f->>'type', 'text'),
      'options', case when f->>'type' = 'select' then f->'options' end,
      'required', coalesce((f->>'required')::boolean, false))));
  end loop;
  if jsonb_array_length(v_fields) = 0 then raise exception '입력 항목을 하나 이상 만드세요' using errcode = '22023'; end if;

  select array_agg(y.name order by y.name) into v_names from public.club_year y
   where y.academic_year = v_year and y.status = 'active'
     and (p_club_year_ids is null or cardinality(p_club_year_ids) = 0 or y.id = any (p_club_year_ids));
  if v_names is null then raise exception '보낼 동아리가 없습니다' using errcode = '22023'; end if;
  v_rule := jsonb_build_object('include', jsonb_build_array(jsonb_build_object('type', 'club', 'names', to_jsonb(v_names))), 'exclude', '[]'::jsonb);
  v_cfg := jsonb_build_object('title', btrim(p_title), 'audience', v_rule, 'guide', coalesce(p_guide, ''),
    'dueDate', case when p_due is null then null else to_jsonb(p_due::text) end,
    'axis', p_axis, 'answerMode', 'shared', 'mode', coalesce(p_visibility, 'private'),
    'dimensions', '[]'::jsonb, 'fields', v_fields);
  if public.collect_config_error(v_cfg) is not null then
    raise exception '%', public.collect_config_error(v_cfg) using errcode = '22023';
  end if;

  v_res := public.resolve_audience(v_rule, p_axis, v_year, null);
  if p_check_only then
    return jsonb_build_object('check_only', true,
      'clubs', to_jsonb(v_names),
      'advisors', (select count(distinct r->>'resource_id') from jsonb_array_elements(v_res->'rows') r where r->>'unit_key' is not null),
      'rows', (select count(distinct r->>'unit_key') from jsonb_array_elements(v_res->'rows') r where r->>'unit_key' is not null),
      'config', v_cfg);
  end if;

  select ur.resource_id, r.name into v_me, v_me_name from public.user_resource ur join public.resource r on r.id = ur.resource_id
   where ur.user_id = auth.uid() and r.type in ('teacher', 'staff') limit 1;
  if v_me is null then raise exception '교직원 명단에 연결된 계정이 아닙니다' using errcode = '42501'; end if;

  v_wname := format('동아리 운영 (%s학년도)', v_year);
  select w.id into v_work from public.work w
   where w.name = v_wname and w.status = 'active' and coalesce(w.meta->'managers', '[]'::jsonb) @> jsonb_build_array(jsonb_build_object('id', v_me))
   order by w.created_at limit 1;
  if v_work is null then
    insert into public.work (name, description, manager_id, status, keywords, meta)
    values (v_wname, '동아리 담당자가 동아리들에 보낸 요청(누가기록 등)을 모은 업무 — 동아리 화면 «요청»에서 만든다',
            v_me, 'active', '{}',
            jsonb_build_object('managers', jsonb_build_array(jsonb_build_object('id', v_me, 'name', v_me_name)),
                               'year', v_year, 'via', jsonb_build_object('channel', 'clubs')))
    returning id into v_work;
  end if;

  insert into public.task (event_id, title, description, type, order_index, due_date, keywords, meta, status, created_by)
  values (v_work, btrim(p_title), nullif(btrim(coalesce(p_guide, '')), ''), 'one_time',
          coalesce((select max(order_index) + 1 from public.task where event_id = v_work), 0),
          case when p_due is null then null else p_due::timestamptz end, '{}',
          jsonb_build_object('assignees', '[]'::jsonb, 'via', jsonb_build_object('channel', 'clubs')), 'pending', v_me)
  returning id into v_task;

  select * into def from mcp_private.wk_action_def('collect.input');
  insert into public.task_action (task_id, action_type, handler_version, title, description, execution_mode, verification_mode, config, instance_key)
  values (v_task, 'collect.input', 1, btrim(p_title), def.description, def.exec_mode, def.verify_mode, '{}'::jsonb,
          case when def.multiple then gen_random_uuid()::text else '' end)
  returning id into v_action;
  perform public.update_collect_config(v_action, v_cfg);
  v_start := public.start_collect_request(v_action);
  return jsonb_build_object('ok', true, 'work_id', v_work, 'task_id', v_task, 'action_id', v_action, 'started', v_start);
end $$;


ALTER FUNCTION "public"."club_send_request"("p_title" "text", "p_axis" "text", "p_fields" "jsonb", "p_due" "date", "p_club_year_ids" "uuid"[], "p_guide" "text", "p_visibility" "text", "p_year" integer, "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_set_advisors"("p_club_year_id" "uuid", "p_teacher_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_bad int;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.is_club_manager() then raise exception '지도교사는 동아리 담당자가 정합니다' using errcode = '42501'; end if;
  if not exists (select 1 from public.club_year where id = p_club_year_id) then
    raise exception '동아리를 찾지 못했습니다' using errcode = 'P0002';
  end if;
  select count(*) into v_bad from unnest(coalesce(p_teacher_ids, '{}')) t(id)
  where not exists (select 1 from public.resource r where r.id = t.id and r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active');
  if v_bad > 0 then raise exception '재직 교직원이 아닌 사람이 %명 있습니다', v_bad using errcode = '22023'; end if;

  delete from public.club_advisor where club_year_id = p_club_year_id and not teacher_resource_id = any(coalesce(p_teacher_ids, '{}'));
  insert into public.club_advisor (club_year_id, teacher_resource_id, is_primary)
  select p_club_year_id, t.id, t.ord = 1 from unnest(coalesce(p_teacher_ids, '{}')) with ordinality t(id, ord)
  on conflict (club_year_id, teacher_resource_id) do update set is_primary = excluded.is_primary;
  return public.club_get(p_club_year_id);
end $$;


ALTER FUNCTION "public"."club_set_advisors"("p_club_year_id" "uuid", "p_teacher_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_set_finance"("p_club_year_id" "uuid", "p_allocated" bigint, "p_budget_line_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.is_club_manager() then raise exception '배정액은 동아리 담당자가 정합니다' using errcode = '42501'; end if;
  if not exists (select 1 from public.club_year where id = p_club_year_id) then raise exception '동아리를 찾지 못했습니다' using errcode = 'P0002'; end if;
  if p_allocated is not null and p_allocated < 0 then raise exception '배정액은 0 이상' using errcode = '22023'; end if;
  insert into public.club_finance (club_year_id, allocated, budget_line_id, note, updated_by, updated_at)
  values (p_club_year_id, p_allocated, p_budget_line_id, nullif(btrim(p_note), ''), auth.uid(), now())
  on conflict (club_year_id) do update set allocated = excluded.allocated, budget_line_id = excluded.budget_line_id,
    note = excluded.note, updated_by = excluded.updated_by, updated_at = now();
  return public.club_finance_get(p_club_year_id);
end $$;


ALTER FUNCTION "public"."club_set_finance"("p_club_year_id" "uuid", "p_allocated" bigint, "p_budget_line_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_set_leader"("p_club_year_id" "uuid", "p_student_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.can_manage_club_year(p_club_year_id) then
    raise exception '기장은 지도교사·동아리 담당자가 정합니다' using errcode = '42501';
  end if;
  if p_student_code is not null and not exists (
    select 1 from public.club_member where club_year_id = p_club_year_id and student_code = p_student_code and status = 'confirmed') then
    raise exception '기장은 확정된 부원 중에서 고릅니다' using errcode = '22023';
  end if;
  update public.club_member set role = 'member' where club_year_id = p_club_year_id and role = 'leader'
    and student_code is distinct from p_student_code;
  if p_student_code is not null then
    update public.club_member set role = 'leader' where club_year_id = p_club_year_id and student_code = p_student_code;
    update public.club_year set meta = meta - 'leader_unresolved' where id = p_club_year_id;
  end if;
  return public.club_get(p_club_year_id);
end $$;


ALTER FUNCTION "public"."club_set_leader"("p_club_year_id" "uuid", "p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_set_members"("p_club_year_id" "uuid", "p_students" "jsonb", "p_mode" "text" DEFAULT 'add'::"text", "p_check_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  y public.club_year%rowtype; e jsonb; s record; v_errors jsonb := '[]'::jsonb; v_add jsonb := '[]'::jsonb;
  v_keep text[] := '{}'; v_remove jsonb; v_other text; v_already int := 0;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into y from public.club_year where id = p_club_year_id;
  if not found then raise exception '동아리를 찾지 못했습니다' using errcode = 'P0002'; end if;
  if not public.can_manage_club_year(y.id) then
    raise exception '명단은 지도교사·동아리 담당자가 확정합니다' using errcode = '42501';
  end if;
  if p_mode not in ('add', 'replace') then raise exception 'mode 는 add 또는 replace' using errcode = '22023'; end if;
  if jsonb_typeof(p_students) <> 'array' then raise exception 'students 는 배열이어야 합니다' using errcode = '22023'; end if;

  for e in select * from jsonb_array_elements(p_students) loop
    for s in select * from club_private.resolve_student(e) loop
      if s.err is not null then
        v_errors := v_errors || to_jsonb(s.err);
      elsif s.code = any(v_keep) then
        null;
      else
        v_keep := v_keep || s.code;
        if exists (select 1 from public.club_member m where m.club_year_id = y.id and m.student_code = s.code and m.status = 'confirmed') then
          v_already := v_already + 1;
        else
          v_other := null;
          if y.kind = 'regular' and y.status = 'active' then
            select y2.name into v_other from public.club_member m2 join public.club_year y2 on y2.id = m2.club_year_id
            where m2.student_code = s.code and m2.status = 'confirmed' and y2.kind = 'regular' and y2.status = 'active'
              and y2.academic_year = y.academic_year and y2.id <> y.id limit 1;
          end if;
          if v_other is not null then
            v_errors := v_errors || to_jsonb(format('%s-%s-%s %s 은(는) 이미 «%s» 부원(정규 동아리는 하나)', s.grade, s.class_num, s.number, s.name, v_other));
          else
            v_add := v_add || jsonb_build_object('code', s.code, 'resource_id', s.resource_id, 'name', s.name,
                                                 'grade', s.grade, 'class', s.class_num, 'number', s.number,
                                                 'role', coalesce(case when jsonb_typeof(e) = 'object' then e->>'role' end, 'member'));
          end if;
        end if;
      end if;
    end loop;
  end loop;

  if p_mode = 'replace' then
    select coalesce(jsonb_agg(jsonb_build_object('code', m.student_code, 'name', r.name, 'grade', m.grade, 'class', m.class_num, 'number', m.number)), '[]'::jsonb)
      into v_remove
    from public.club_member m left join public.resource r on r.id = m.student_resource_id
    where m.club_year_id = y.id and m.status = 'confirmed' and not m.student_code = any(v_keep);
  else
    v_remove := '[]'::jsonb;
  end if;

  if p_check_only or jsonb_array_length(v_errors) > 0 then
    return jsonb_build_object('check_only', true, 'ok', jsonb_array_length(v_errors) = 0, 'errors', v_errors,
                              'add', v_add, 'remove', v_remove, 'unchanged', v_already);
  end if;

  update public.club_member m set status = 'removed', role = 'member', decided_by = auth.uid(), decided_at = now()
  where m.club_year_id = y.id and m.status = 'confirmed' and p_mode = 'replace' and not m.student_code = any(v_keep);

  -- 기장을 넣는다면 기존 기장은 부원으로
  if exists (select 1 from jsonb_array_elements(v_add) a where a->>'role' = 'leader') then
    update public.club_member set role = 'member' where club_year_id = y.id and role = 'leader';
  end if;
  insert into public.club_member (club_year_id, student_code, student_resource_id, grade, class_num, number, role, status, source, decided_by, decided_at)
  select y.id, a->>'code', (a->>'resource_id')::uuid, (a->>'grade')::int, (a->>'class')::int, (a->>'number')::int,
         case when a->>'role' = 'leader' then 'leader' else 'member' end, 'confirmed', 'manual', auth.uid(), now()
  from jsonb_array_elements(v_add) a
  on conflict (club_year_id, student_code) do update
    set status = 'confirmed', role = excluded.role, student_resource_id = excluded.student_resource_id,
        grade = excluded.grade, class_num = excluded.class_num, number = excluded.number,
        decided_by = excluded.decided_by, decided_at = excluded.decided_at, source = coalesce(public.club_member.source, 'manual');

  return jsonb_build_object('ok', true, 'added', jsonb_array_length(v_add), 'removed', jsonb_array_length(v_remove), 'unchanged', v_already);
end $$;


ALTER FUNCTION "public"."club_set_members"("p_club_year_id" "uuid", "p_students" "jsonb", "p_mode" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."club_student_role"("p_club_year_id" "uuid") RETURNS "text"
