COMMENT ON FUNCTION "public"."club_student_role"("p_club_year_id" "uuid") IS '현재 사용자(학생)의 그 동아리 역할 leader/member, 아니면 NULL';



CREATE OR REPLACE FUNCTION "public"."club_view_as"("p_student" "jsonb", "p_fn" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_claims text := current_setting('request.jwt.claims', true);
  s record;
  v_uid uuid;
  v_out jsonb;
  a jsonb := coalesce(p_args, '{}'::jsonb);
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin') then
    raise exception '학생으로 보기는 관리자만 할 수 있습니다' using errcode = '42501';
  end if;
  if p_fn not in ('club_list', 'club_get', 'club_activities', 'club_finance_get', 'club_recruit_list',
                  'club_recruit_get', 'club_applications', 'club_proposals') then
    raise exception '학생으로 보기에서 부를 수 없는 함수: %', p_fn using errcode = '22023';
  end if;

  select * into s from club_private.resolve_student(p_student) limit 1;
  if s.err is not null then raise exception '%', s.err using errcode = '22023'; end if;
  select p.id into v_uid from public.profiles p
   where p.role = 'student' and split_part(p.email, '@', 1) = s.code
   order by p.created_at desc limit 1;
  if v_uid is null then
    raise exception '%(%)은 아직 로그인한 적이 없어 학생 화면을 만들 수 없습니다', s.name, s.code using errcode = 'P0002';
  end if;

  perform set_config('request.jwt.claims',
    (coalesce(nullif(v_claims, '')::jsonb, '{}'::jsonb)
      || jsonb_build_object('sub', v_uid::text, 'role', 'authenticated'))::text, true);
  begin
    v_out := case p_fn
      when 'club_list'         then public.club_list(nullif(a->>'p_year', '')::int)
      when 'club_get'          then public.club_get((a->>'p_club_year_id')::uuid)
      when 'club_activities'   then public.club_activities((a->>'p_club_year_id')::uuid)
      when 'club_finance_get'  then public.club_finance_get((a->>'p_club_year_id')::uuid)
      when 'club_recruit_list' then public.club_recruit_list(nullif(a->>'p_year', '')::int)
      when 'club_recruit_get'  then public.club_recruit_get((a->>'p_id')::uuid)
      when 'club_applications' then public.club_applications((a->>'p_club_year_id')::uuid, nullif(a->>'p_recruit_id', '')::uuid)
      when 'club_proposals'    then public.club_proposals(nullif(a->>'p_year', '')::int)
    end;
  exception when others then
    perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
    raise;
  end;
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);

  return jsonb_build_object('student', jsonb_build_object('code', s.code, 'name', s.name, 'grade', s.grade,
                                                          'class', s.class_num, 'number', s.number),
                            'data', v_out);
end $$;


ALTER FUNCTION "public"."club_view_as"("p_student" "jsonb", "p_fn" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."club_view_as"("p_student" "jsonb", "p_fn" "text", "p_args" "jsonb") IS '관리자 전용 — 고른 학생 계정으로 동아리 읽기 함수(화이트리스트)를 불러 학생 화면 그대로를 돌려준다. 클라이언트 짝 = src/features/clubs/viewAs.ts';



CREATE OR REPLACE FUNCTION "public"."club_withdraw_application"("p_recruit_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_code text := public.current_student_code();
begin
  if v_code is null then raise exception '학생만' using errcode = '42501'; end if;
  update public.club_application set status = 'withdrawn', updated_at = now()
  where recruit_id = p_recruit_id and student_code = v_code and status = 'applied';
  return jsonb_build_object('ok', true);
end $$;


