CREATE OR REPLACE FUNCTION "public"."collab_desk_sticky_board_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and old.meta->>'kind' = 'desk_sticky' then
    new.meta := coalesce(new.meta, '{}'::jsonb) || jsonb_build_object('kind', 'desk_sticky');
  end if;
  if new.meta->>'kind' = 'desk_sticky' then
    new.visibility := 'private';
  end if;
  return new;
end;
$$;


