CREATE OR REPLACE FUNCTION "public"."collect_cell_complete"("p_values" "jsonb", "p_fields" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when exists (select 1 from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) f
                 where coalesce((f.value->>'required')::boolean, false))
      then not exists (
        select 1 from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) f
        where coalesce((f.value->>'required')::boolean, false)
          and coalesce(btrim(p_values->>(f.value->>'key')), '') = '')
    else coalesce(p_values, '{}'::jsonb) <> '{}'::jsonb
  end;
$$;


ALTER FUNCTION "public"."collect_cell_complete"("p_values" "jsonb", "p_fields" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."collect_clean_values"("p_values" "jsonb", "p_fields" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare
  v_out   jsonb := '{}'::jsonb;
  v_field jsonb;
  v_val   text;
begin
  for v_field in select value from jsonb_array_elements(coalesce(p_fields, '[]'::jsonb)) loop
    v_val := btrim(coalesce(p_values->>(v_field->>'key'), ''));
    continue when v_val = '';
    case v_field->>'type'
      when 'yesno' then
        if v_val not in ('yes', 'no') then raise exception '"%"는 예/아니오로 답해야 합니다', v_field->>'label' using errcode = '22023'; end if;
      when 'select' then
        if not exists (select 1 from jsonb_array_elements_text(v_field->'options') o where o = v_val) then
          raise exception '"%"의 보기에 없는 값입니다', v_field->>'label' using errcode = '22023';
        end if;
      when 'number' then
        if v_val !~ '^-?[0-9]+(\.[0-9]+)?$' then raise exception '"%"는 숫자여야 합니다', v_field->>'label' using errcode = '22023'; end if;
      when 'date' then
        if v_val !~ '^\d{4}-\d{2}-\d{2}$' then raise exception '"%"는 날짜여야 합니다', v_field->>'label' using errcode = '22023'; end if;
      else
        if length(v_val) > 2000 then raise exception '"%"가 너무 깁니다(2000자)', v_field->>'label' using errcode = '22023'; end if;
    end case;
    v_out := v_out || jsonb_build_object(v_field->>'key', v_val);
  end loop;
  return v_out;
end;
$_$;


ALTER FUNCTION "public"."collect_clean_values"("p_values" "jsonb", "p_fields" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."collect_config_error"("p_cfg" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_field jsonb;
  v_keys  text[] := '{}';
  v_key   text;
begin
  if p_cfg is null or jsonb_typeof(p_cfg) <> 'object' then return '설정이 없습니다'; end if;
  if coalesce(p_cfg->>'axis', 'person') not in ('person', 'subject', 'class', 'club', 'club_member') then return '줄 단위가 올바르지 않습니다'; end if;
  if coalesce(p_cfg->>'answerMode', 'each') not in ('each', 'shared') then return '응답 방식이 올바르지 않습니다'; end if;
  if coalesce(p_cfg->>'mode', 'private') not in ('private', 'shared') then return '공개 방식이 올바르지 않습니다'; end if;
  if jsonb_typeof(p_cfg->'fields') <> 'array' or jsonb_array_length(p_cfg->'fields') = 0 then
    return '입력 항목을 하나 이상 만드세요';
  end if;
  for v_field in select value from jsonb_array_elements(p_cfg->'fields') loop
    v_key := v_field->>'key';
    if coalesce(btrim(v_key), '') = '' or coalesce(btrim(v_field->>'label'), '') = '' then
      return '입력 항목에 이름이 없습니다';
    end if;
    if v_key = any (v_keys) then return '입력 항목 키가 겹칩니다: ' || v_key; end if;
    v_keys := v_keys || v_key;
    if coalesce(v_field->>'type', '') not in ('yesno', 'select', 'text', 'number', 'date') then
      return '입력 항목 형식이 올바르지 않습니다: ' || (v_field->>'label');
    end if;
    if v_field->>'type' = 'select'
       and (jsonb_typeof(v_field->'options') <> 'array' or jsonb_array_length(v_field->'options') = 0) then
      return '선택 항목에 보기가 없습니다: ' || (v_field->>'label');
    end if;
  end loop;
  if p_cfg ? 'dimensions' and jsonb_typeof(p_cfg->'dimensions') <> 'array' then return '구분 목록이 올바르지 않습니다'; end if;
  if (select count(*) <> count(distinct value->>'key')
        or bool_or(coalesce(btrim(value->>'key'), '') = '' or coalesce(btrim(value->>'label'), '') = '')
      from jsonb_array_elements(coalesce(p_cfg->'dimensions', '[]'::jsonb))) then
    return '구분 이름이 비었거나 겹칩니다';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."collect_config_error"("p_cfg" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."collect_notify"("p_action_id" "uuid", "p_resource_ids" "uuid"[], "p_kind" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_title text;
  v_task  text;
  v_from  text;
  v_n     int;
  v_submit boolean;
  v_label text;
begin
  select a.title, t.title, public.is_submit_action_type(a.action_type) into v_title, v_task, v_submit
  from public.task_action a left join public.task t on t.id = a.task_id
  where a.id = p_action_id;
  select r.name into v_from
  from public.current_actor_resource_ids() me join public.resource r on r.id = me limit 1;
  v_label := case when v_submit then '제출' else '입력' end;

  insert into public.notification_events (type, title, message, resource_id, is_read, meta)
  select case when v_submit then 'submission_requested' else 'collect_input_requested' end,
         case when p_kind = 'reminder' then v_label || ' 요청 (다시 알림)' else v_label || ' 요청' end,
         coalesce(v_from || '님이 ', '') || '"' || coalesce(v_task, v_title, '할 일') || '" ' || v_label || '을 요청했습니다.',
         rid, false,
         jsonb_build_object('action_id', p_action_id, 'action_title', v_title, 'task_title', v_task)
  from (select distinct unnest(p_resource_ids) rid) x
  where rid is not null;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."collect_notify"("p_action_id" "uuid", "p_resource_ids" "uuid"[], "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."collect_ref_date"("p_academic_year" integer) RETURNS "date"
    LANGUAGE "sql" STABLE
    AS $$
  -- 그 학년도 안의 기준일: 오늘이 학년도 안이면 오늘, 아니면 가까운 끝
  select least(greatest(current_date, make_date(p_academic_year, 3, 1)),
               make_date(p_academic_year + 1, 2, 28));
$$;


