    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "area" "text" NOT NULL,
    "purpose" "text",
    "content" "text",
    "outcome" "text",
    "academic_year" integer NOT NULL,
    "semester" integer,
    "starts_on" "date" NOT NULL,
    "ends_on" "date",
    "hours" numeric(5,1),
    "place" "text",
    "lineage_parent_id" "uuid",
    "lineage_note" "text",
    "operator_type" "text" DEFAULT 'internal'::"text" NOT NULL,
    "operator_name" "text",
    "scale" "text" DEFAULT 'group'::"text" NOT NULL,
    "budget_source" "text",
    "budget_program" "text",
    "budget_planned" numeric(12,0),
    "budget_spent" numeric(12,0),
    "keywords" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "related_subjects" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "career_fields" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "target_grades" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "department" "text",
    "status" "text" DEFAULT 'planned'::"text" NOT NULL,
    "visibility" "text" DEFAULT 'school'::"text" NOT NULL,
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    "meeting_id" "uuid",
    "attachments" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "activity_area_check" CHECK (("area" = ANY (ARRAY['autonomy'::"text", 'club'::"text", 'career'::"text", 'service'::"text"]))),
    CONSTRAINT "activity_budget_source_check" CHECK (("budget_source" = ANY (ARRAY['school'::"text", 'office'::"text", 'grant'::"text", 'external'::"text", 'self'::"text", 'none'::"text"]))),
    CONSTRAINT "activity_lineage_not_self" CHECK (("lineage_parent_id" IS DISTINCT FROM "id")),
    CONSTRAINT "activity_operator_type_check" CHECK (("operator_type" = ANY (ARRAY['internal'::"text", 'external'::"text", 'joint'::"text"]))),
    CONSTRAINT "activity_period_ordered" CHECK ((("ends_on" IS NULL) OR ("ends_on" >= "starts_on"))),
    CONSTRAINT "activity_scale_check" CHECK (("scale" = ANY (ARRAY['school'::"text", 'grade'::"text", 'class'::"text", 'group'::"text", 'individual'::"text"]))),
    CONSTRAINT "activity_semester_check" CHECK (("semester" = ANY (ARRAY[1, 2]))),
    CONSTRAINT "activity_source_check" CHECK (("source" = ANY (ARRAY['manual'::"text", 'timetable'::"text", 'meeting'::"text", 'issue'::"text", 'import'::"text"]))),
    CONSTRAINT "activity_status_check" CHECK (("status" = ANY (ARRAY['planned'::"text", 'running'::"text", 'done'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "activity_visibility_check" CHECK (("visibility" = ANY (ARRAY['school'::"text", 'participants'::"text"])))
);


