CREATE OR REPLACE FUNCTION "public"."convert_grade_scale"("p_grade" numeric, "p_from" "text" DEFAULT '5tier'::"text", "p_to" "text" DEFAULT '9tier'::"text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_from = p_to THEN
    RETURN p_grade;
  END IF;
  
  IF p_from = '5tier' AND p_to = '9tier' THEN
    -- 5등급→9등급 중앙값 매핑
    -- A(1)→1.5, B(2)→3.0, C(3)→5.0, D(4)→7.0, E(5)→8.5
    RETURN CASE
      WHEN p_grade <= 1 THEN 1.5
      WHEN p_grade <= 2 THEN 1.5 + (p_grade - 1) * 1.5  -- 1→1.5, 2→3.0
      WHEN p_grade <= 3 THEN 3.0 + (p_grade - 2) * 2.0  -- 2→3.0, 3→5.0
      WHEN p_grade <= 4 THEN 5.0 + (p_grade - 3) * 2.0  -- 3→5.0, 4→7.0
      WHEN p_grade <= 5 THEN 7.0 + (p_grade - 4) * 1.5  -- 4→7.0, 5→8.5
      ELSE 9.0
    END;
  ELSIF p_from = '9tier' AND p_to = '5tier' THEN
    -- 9등급→5등급 역매핑
    RETURN CASE
      WHEN p_grade <= 2.0 THEN 1.0   -- 1~2 → A
      WHEN p_grade <= 4.0 THEN 2.0   -- 2~4 → B
      WHEN p_grade <= 6.0 THEN 3.0   -- 4~6 → C
      WHEN p_grade <= 8.0 THEN 4.0   -- 6~8 → D
      ELSE 5.0                        -- 8~9 → E
    END;
  ELSE
    RAISE EXCEPTION 'Unsupported scale conversion: % → %', p_from, p_to;
  END IF;
END;
$$;


ALTER FUNCTION "public"."convert_grade_scale"("p_grade" numeric, "p_from" "text", "p_to" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."convert_grade_scale"("p_grade" numeric, "p_from" "text", "p_to" "text") IS '5등급(성취평가)↔9등급(상대평가) 변환. 입시 분석 시 1~2학년(5등급)과 3학년(9등급) 비교에 사용';



CREATE OR REPLACE FUNCTION "public"."copy_duty_seats"("p_from_year" integer, "p_to_year" integer, "p_keep_holders" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_seat  record;
  v_new   uuid;
  v_count int := 0;
  v_ref   date := make_date(p_from_year + 1, 2, 28);  -- 학년도 끝
begin
  if auth.uid() is null or not public.is_admin() then
    raise exception '관리자만 업무분장을 복사할 수 있습니다' using errcode = '42501';
  end if;
  if p_from_year is null or p_to_year is null or p_from_year = p_to_year then
    raise exception '원본과 대상 학년도가 필요합니다' using errcode = '22023';
  end if;

  for v_seat in
    select * from public.duty_seat where academic_year = p_from_year order by sort_order
  loop
    insert into public.duty_seat (academic_year, name, department_id, kind, areas, sort_order, note, meta)
    values (p_to_year, v_seat.name, v_seat.department_id, v_seat.kind, v_seat.areas,
            v_seat.sort_order, v_seat.note,
            v_seat.meta || jsonb_build_object('copied_from', v_seat.id))
    on conflict (academic_year, name) do nothing
    returning id into v_new;

    if v_new is null then
      continue;
    end if;
    v_count := v_count + 1;

    if p_keep_holders then
      insert into public.duty_seat_holder (seat_id, resource_id, holder_name, role)
      select v_new, h.resource_id, h.holder_name, h.role
      from public.duty_seat_holder h
      where h.seat_id = v_seat.id
        and public.duty_holder_active(h.start_date, h.end_date, v_ref);
    end if;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "public"."copy_duty_seats"("p_from_year" integer, "p_to_year" integer, "p_keep_holders" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."copy_task_workflow"("p_source_workflow_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_excluded_node_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  src public.task_workflow%ROWTYPE;
  new_workflow_id uuid := gen_random_uuid();
  actor_resource_id uuid;
  actor_resource_name text;
  cnt_events int; cnt_tasks int; cnt_nodes int; cnt_edges int; cnt_actions int;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO src FROM public.task_workflow WHERE id = p_source_workflow_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Workflow not found: %', p_source_workflow_id USING ERRCODE = 'P0002';
  END IF;

  SELECT ur.resource_id INTO actor_resource_id
  FROM public.user_resource ur WHERE ur.user_id = auth.uid()
  ORDER BY ur.created_at LIMIT 1;
  IF actor_resource_id IS NOT NULL THEN
    SELECT r.name INTO actor_resource_name FROM public.resource r WHERE r.id = actor_resource_id;
  END IF;

  -- 포함 노드 = 제외 목록에 없는 전부. **연쇄 제외는 클라이언트가 그래프의 선(edge)으로 계산해
  -- 제외 목록에 모두 담아 보낸다**(2026-09-23). 종전엔 여기서 containerNodeId 로 한 번 더 걸렀는데,
  -- 그 표시는 '업무를 올릴 때 자동 생성된' 노드에만 있어 직접 연결한 노드와 기준이 어긋났고,
  -- 사용자가 업무를 빼고 그 아래 할 일만 다시 넣어도 서버가 조용히 뺐다.
  CREATE TEMP TABLE tmp_nodes ON COMMIT DROP AS
    SELECT * FROM public.task_workflow_node
    WHERE workflow_id = p_source_workflow_id
      AND NOT (id = ANY(p_excluded_node_ids));

  -- 매핑 테이블
  CREATE TEMP TABLE tmp_node_map ON COMMIT DROP AS
    SELECT id AS old_id, gen_random_uuid() AS new_id FROM tmp_nodes;

  -- 복제 대상 이벤트 = 포함된 이벤트 노드의 work ∪ 포함된 task 노드가 속한 work(이벤트 노드가 캔버스에 없어도 task는 event가 필요)
  CREATE TEMP TABLE tmp_event_map ON COMMIT DROP AS
    SELECT DISTINCT e.id AS old_id, gen_random_uuid() AS new_id
    FROM public.work e
    WHERE e.id IN (
      SELECT event_id FROM tmp_nodes WHERE node_kind = 'event' AND event_id IS NOT NULL
      UNION
      SELECT t.event_id FROM tmp_nodes tn
      JOIN public.task t ON t.id = tn.task_id
      WHERE tn.node_kind = 'task' AND tn.task_id IS NOT NULL
    );

  CREATE TEMP TABLE tmp_task_map ON COMMIT DROP AS
    SELECT DISTINCT t.id AS old_id, gen_random_uuid() AS new_id
    FROM public.task t
    WHERE t.id IN (SELECT task_id FROM tmp_nodes WHERE node_kind = 'task' AND task_id IS NOT NULL);

  -- 새 워크플로
  INSERT INTO public.task_workflow (id, owner_id, department_id, name, description, viewport)
  VALUES (
    new_workflow_id,
    auth.uid(),
    src.department_id,
    COALESCE(NULLIF(TRIM(p_name), ''), src.name || ' (복사본)'),
    src.description,
    src.viewport
  );

  -- 이벤트 복제: 매니저 = 복사자(원본 매니저는 원본 이벤트의 책임자이므로 승계하지 않음)
  INSERT INTO public.work (id, name, description, manager_id, status, keywords, meta)
  SELECT
    m.new_id,
    e.name,
    e.description,
    actor_resource_id,
    'active',
    e.keywords,
    (COALESCE(e.meta, '{}'::jsonb) - 'files')
      || CASE
           WHEN actor_resource_id IS NOT NULL THEN jsonb_build_object(
             'managers',
             jsonb_build_array(jsonb_build_object('id', actor_resource_id, 'name', COALESCE(actor_resource_name, '')))
           )
           ELSE jsonb_build_object('managers', '[]'::jsonb)
         END
  FROM tmp_event_map m
  JOIN public.work e ON e.id = m.old_id;
  GET DIAGNOSTICS cnt_events = ROW_COUNT;

  -- 태스크 복제: 담당자 유지하되 상태 pending 리셋, 회차 기록·파일·AI 메타 제거, status pending
  INSERT INTO public.task (id, event_id, title, description, type, order_index, status, due_date, keywords, meta, created_by)
  SELECT
    m.new_id,
    em.new_id,
    t.title,
    t.description,
    t.type,
    t.order_index,
    'pending',
    t.due_date,
    t.keywords,
    (COALESCE(t.meta, '{}'::jsonb) - 'files' - 'deadlineProgress' - 'ai_generated' - 'documentAnalysisId' - 'documentAnalysisCandidateId')
      || jsonb_build_object(
        'assignees',
        COALESCE((
          SELECT jsonb_agg(
            jsonb_set(jsonb_set(a.value, '{status}', '"pending"'), '{completed_at}', 'null'::jsonb)
          )
          FROM jsonb_array_elements(
            CASE WHEN jsonb_typeof(t.meta->'assignees') = 'array' THEN t.meta->'assignees' ELSE '[]'::jsonb END
          ) a
        ), '[]'::jsonb)
      ),
    actor_resource_id
  FROM tmp_task_map m
  JOIN public.task t ON t.id = m.old_id
  JOIN tmp_event_map em ON em.old_id = t.event_id;
  GET DIAGNOSTICS cnt_tasks = ROW_COUNT;

  -- 작업(Action) 복제(2026-09-23): 복제된 할 일에 붙은 연결을 새 할 일로. 작성자 = 복사자
  -- (task_action 쓰기 RLS 가 created_by = 본인). **실행 이력(RUN)은 복제하지 않는다.**
  -- 한 개뿐인 유형(instance_key = '')은 작성자가 여럿이면 복사 후 모두 복사자 것이 되어 유일 제약에
  -- 걸리므로 (할 일, 유형)마다 하나만 — 값 제출용 연결(origin=submission) 우선, 없으면 복사자 것, 없으면 먼저 만든 것.
  -- 여러 개 유형(NEIS 등)은 전부 옮기고 instance_key 를 새로 준다.
  CREATE TEMP TABLE tmp_action_map ON COMMIT DROP AS
    SELECT a.id AS old_id, gen_random_uuid() AS new_id
    FROM public.task_action a
    JOIN tmp_task_map m ON m.old_id = a.task_id
    WHERE a.archived_at IS NULL AND a.instance_key <> ''
    UNION ALL
    SELECT x.id, gen_random_uuid()
    FROM (
      SELECT DISTINCT ON (a.task_id, a.action_type) a.id
      FROM public.task_action a
      JOIN tmp_task_map m ON m.old_id = a.task_id
      WHERE a.archived_at IS NULL AND a.instance_key = ''
      ORDER BY a.task_id, a.action_type,
        (a.config->>'origin' = 'submission') DESC NULLS LAST,
        (a.created_by = auth.uid()) DESC,
        a.created_at
    ) x;

  INSERT INTO public.task_action (
    id, task_id, created_by, action_type, handler_version, title, description,
    execution_mode, verification_mode, config, is_required, instance_key
  )
  SELECT
    am.new_id, tm.new_id, auth.uid(), a.action_type, a.handler_version, a.title, a.description,
    a.execution_mode, a.verification_mode, COALESCE(a.config, '{}'::jsonb), a.is_required,
    CASE WHEN a.instance_key = '' THEN '' ELSE gen_random_uuid()::text END
  FROM tmp_action_map am
  JOIN public.task_action a ON a.id = am.old_id
  JOIN tmp_task_map tm ON tm.old_id = a.task_id;
  GET DIAGNOSTICS cnt_actions = ROW_COUNT;

  -- 작업 노드는 **옮겨진 작업이 있을 때만** 복사한다 (2026-09-24).
  -- tmp_action_map 은 보관된 연결과 (할 일,유형) 중복을 걸러내므로 대응이 없는 노드가 생기는데,
  -- 그대로 넣으면 action_id 가 NULL 이 되어 CHECK 위반으로 **복사 전체가 실패**한다.
  -- 노드를 빼면 그 노드를 쓰는 선도 함께 빠져야 하므로 매핑에서 지운다(엣지 복제가 이 표를 조인한다).
  DELETE FROM tmp_node_map
  WHERE old_id IN (
    SELECT n.id FROM tmp_nodes n
    WHERE n.node_kind = 'action'
      AND (n.action_id IS NULL
           OR NOT EXISTS (SELECT 1 FROM tmp_action_map am WHERE am.old_id = n.action_id))
  );
  DELETE FROM tmp_nodes WHERE id NOT IN (SELECT old_id FROM tmp_node_map);

  -- 할 일 meta 가 가리키는 작업 id 를 새 id 로 — 안 하면 복사본이 **원본의 작업**을 조용히 쓴다.
  -- ① 값 제출이 쓰는 연결(submission.actionId) — 대응이 없으면 null(매니저가 다시 저장하면 새로 만든다)
  UPDATE public.task t
  SET meta = jsonb_set(
    t.meta, '{submission,actionId}',
    COALESCE(
      (SELECT to_jsonb(am.new_id::text) FROM tmp_action_map am WHERE am.old_id::text = t.meta->'submission'->>'actionId'),
      'null'::jsonb
    )
  )
  WHERE t.id IN (SELECT new_id FROM tmp_task_map)
    AND jsonb_typeof(t.meta->'submission'->'actionId') = 'string';
  -- ② 작업 순서(actionFlow) — 'submission' 은 그대로, 연결 id 는 새 id, 대응이 없는 키는 버린다
  UPDATE public.task t
  SET meta = jsonb_set(
    t.meta, '{actionFlow}',
    COALESCE((
      SELECT jsonb_agg(k.v ORDER BY k.ord)
      FROM (
        SELECT
          CASE WHEN e.value #>> '{}' = 'submission' THEN to_jsonb('submission'::text)
               ELSE to_jsonb(am.new_id::text) END AS v,
          e.ord
        FROM jsonb_array_elements(t.meta->'actionFlow') WITH ORDINALITY AS e(value, ord)
        LEFT JOIN tmp_action_map am ON am.old_id::text = e.value #>> '{}'
      ) k
      WHERE k.v IS NOT NULL
    ), '[]'::jsonb)
  )
  WHERE t.id IN (SELECT new_id FROM tmp_task_map)
    AND jsonb_typeof(t.meta->'actionFlow') = 'array';

  -- 노드 복제: entity id·컨테이너 참조 remap, 소스 유실/WORK 연결 표시는 초기화
  INSERT INTO public.task_workflow_node (id, workflow_id, node_kind, event_id, task_id, action_id, label, position_x, position_y, metadata)
  SELECT
    nm.new_id,
    new_workflow_id,
    n.node_kind,
    em.new_id,
    tm.new_id,
    am.new_id,
    n.label,
    n.position_x,
    n.position_y,
    (
      (COALESCE(n.metadata, '{}'::jsonb) - 'sourceDeleted' - 'workConnected')
      || CASE
           WHEN COALESCE(n.metadata->>'containerNodeId', '') <> ''
                AND EXISTS (SELECT 1 FROM tmp_node_map c WHERE c.old_id = (n.metadata->>'containerNodeId')::uuid)
             THEN jsonb_build_object(
               'containerNodeId',
               (SELECT c.new_id FROM tmp_node_map c WHERE c.old_id = (n.metadata->>'containerNodeId')::uuid)::text
             )
           WHEN COALESCE(n.metadata->>'containerNodeId', '') <> ''
             THEN '{"containerNodeId": null}'::jsonb
           ELSE '{}'::jsonb
         END
    )
  FROM tmp_nodes n
  JOIN tmp_node_map nm ON nm.old_id = n.id
  LEFT JOIN tmp_event_map em ON em.old_id = n.event_id
  LEFT JOIN tmp_task_map tm ON tm.old_id = n.task_id
  LEFT JOIN tmp_action_map am ON am.old_id = n.action_id;
  GET DIAGNOSTICS cnt_nodes = ROW_COUNT;

  -- 엣지 복제: 양 끝이 모두 포함된 것만
  INSERT INTO public.task_workflow_edge (id, workflow_id, source_node_id, target_node_id, relation_type, label, metadata)
  SELECT
    gen_random_uuid(),
    new_workflow_id,
    sm.new_id,
    tm2.new_id,
    ed.relation_type,
    ed.label,
    COALESCE(ed.metadata, '{}'::jsonb)
  FROM public.task_workflow_edge ed
  JOIN tmp_node_map sm ON sm.old_id = ed.source_node_id
  JOIN tmp_node_map tm2 ON tm2.old_id = ed.target_node_id
  WHERE ed.workflow_id = p_source_workflow_id;
  GET DIAGNOSTICS cnt_edges = ROW_COUNT;

  RETURN jsonb_build_object(
    'workflow_id', new_workflow_id,
    'events', cnt_events,
    'tasks', cnt_tasks,
    'nodes', cnt_nodes,
    'edges', cnt_edges,
    'actions', cnt_actions
  );
END;
$$;


ALTER FUNCTION "public"."copy_task_workflow"("p_source_workflow_id" "uuid", "p_name" "text", "p_excluded_node_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_comprehensive_analysis_calls"("p_student_id" "text", "p_since" timestamp with time zone DEFAULT "date_trunc"('day'::"text", "now"())) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF NOT public.inquiry_design_can_access_student(p_student_id) THEN
    RAISE EXCEPTION 'not allowed to count comprehensive analysis calls for student %', p_student_id;
  END IF;

  SELECT count(*)::integer INTO v_count
  FROM public.student_inquiry_recommendations
  WHERE student_id = p_student_id
    AND generated_at IS NOT NULL
    AND generated_at >= p_since;

  RETURN COALESCE(v_count, 0);
END;
$$;


