CREATE OR REPLACE FUNCTION "public"."count_inquiry_generation_requests"("p_student_id" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode='42501';
  end if;
  if not public.inquiry_design_can_access_student(p_student_id) then
    raise exception 'Not allowed for student %', p_student_id using errcode='42501';
  end if;
  select count(*)::integer into v from public.academy_generation_jobs
   where surface = 'inquiry-design' and student_id = p_student_id
     and (created_at at time zone 'Asia/Seoul')::date = (now() at time zone 'Asia/Seoul')::date;
  return coalesce(v, 0);
end $$;


ALTER FUNCTION "public"."count_inquiry_generation_requests"("p_student_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."course_analyze_subject_category"("p_group" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p_group IS NULL THEN '기타'
    WHEN p_group = '국어' THEN '국어'
    WHEN p_group = '영어' THEN '영어'
    WHEN p_group = '수학' THEN '수학'
    WHEN p_group = '한국사' THEN '역사'
    WHEN p_group IN ('사회', '사회(역사/도덕포함)') THEN '사회'
    WHEN p_group IN ('과학', '물리', '물리학', '화학', '생명', '생명과학', '지구과학') THEN '과학'
    WHEN p_group ILIKE '%물리%' THEN '과학'
    WHEN p_group ILIKE '%화학%' THEN '과학'
    WHEN p_group ILIKE '%생명%' THEN '과학'
    WHEN p_group ILIKE '%지구%' THEN '과학'
    WHEN p_group ILIKE '%과학%' THEN '과학'
    WHEN p_group ILIKE '%역사%' THEN '역사'
    WHEN p_group ILIKE '%사회%' OR p_group ILIKE '%도덕%' THEN '사회'
    ELSE '기타'
  END
$$;


ALTER FUNCTION "public"."course_analyze_subject_category"("p_group" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_approval_request"("p_subject_type" "text", "p_subject_id" "text", "p_title" "text", "p_summary" "text", "p_payload" "jsonb", "p_steps" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_request_id  uuid;
  v_name        text;
  v_resource_id uuid;
  v_step        jsonb;
  v_idx         int := 0;
  v_approver_rid uuid;
  v_approver_uid uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION '로그인이 필요합니다.' USING ERRCODE = '28000';
  END IF;

  v_name := public.current_profile_name();
  IF v_name IS NULL OR btrim(v_name) = '' THEN
    RAISE EXCEPTION '프로필 이름이 없어 결재를 신청할 수 없습니다.' USING ERRCODE = '22023';
  END IF;

  IF p_steps IS NULL OR jsonb_typeof(p_steps) <> 'array' OR jsonb_array_length(p_steps) = 0 THEN
    RAISE EXCEPTION '결재선을 한 명 이상 지정해야 합니다.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_steps) > 10 THEN
    RAISE EXCEPTION '결재선은 최대 10단계입니다.' USING ERRCODE = '22023';
  END IF;

  SELECT ur.resource_id INTO v_resource_id
  FROM public.user_resource ur WHERE ur.user_id = auth.uid() LIMIT 1;

  INSERT INTO public.approval_request (
    subject_type, subject_id, title, summary, payload,
    requester_user_id, requester_resource_id, requester_name
  )
  VALUES (
    btrim(p_subject_type), btrim(p_subject_id), p_title, p_summary,
    COALESCE(p_payload, '{}'::jsonb),
    auth.uid(), v_resource_id, v_name
  )
  RETURNING id INTO v_request_id;

  FOR v_step IN SELECT * FROM jsonb_array_elements(p_steps)
  LOOP
    IF COALESCE(btrim(v_step->>'approver_name'), '') = '' THEN
      RAISE EXCEPTION '결재자 이름이 비어 있습니다.' USING ERRCODE = '22023';
    END IF;

    v_approver_rid := NULLIF(v_step->>'approver_resource_id', '')::uuid;

    SELECT ur.user_id INTO v_approver_uid
    FROM public.user_resource ur
    WHERE v_approver_rid IS NOT NULL AND ur.resource_id = v_approver_rid
    LIMIT 1;

    IF v_approver_uid IS NULL THEN
      SELECT p.id INTO v_approver_uid
      FROM public.profiles p
      WHERE p.name = btrim(v_step->>'approver_name')
      LIMIT 1;
    END IF;

    INSERT INTO public.approval_step (
      request_id, order_index, role_label,
      approver_user_id, approver_resource_id, approver_name
    )
    VALUES (
      v_request_id, v_idx,
      COALESCE(NULLIF(btrim(v_step->>'role_label'), ''), '결재'),
      v_approver_uid, v_approver_rid, btrim(v_step->>'approver_name')
    );

    v_idx := v_idx + 1;
  END LOOP;

  RETURN v_request_id;
END;
$$;


ALTER FUNCTION "public"."create_approval_request"("p_subject_type" "text", "p_subject_id" "text", "p_title" "text", "p_summary" "text", "p_payload" "jsonb", "p_steps" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_document_issue"("p_doc_type" "text", "p_title" "text", "p_issued_on" "date", "p_department" "text" DEFAULT NULL::"text", "p_students" "jsonb" DEFAULT '[]'::"jsonb", "p_grade" integer DEFAULT NULL::integer, "p_class_number" integer DEFAULT NULL::integer, "p_form_data" "jsonb" DEFAULT NULL::"jsonb", "p_remarks" "text" DEFAULT NULL::"text", "p_meta" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_space text;
  v_no    text;
  v_year  int := EXTRACT(YEAR FROM now())::int;
  v_id    uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('teacher','admin')) THEN
    RAISE EXCEPTION 'teacher/admin only' USING ERRCODE = '42501';
  END IF;
  IF p_doc_type NOT IN ('gajeong','volunteer_personal','volunteer_class','volunteer_club') THEN
    RAISE EXCEPTION 'invalid doc_type %', p_doc_type USING ERRCODE = '22023';
  END IF;
  IF p_title IS NULL OR btrim(p_title) = '' THEN
    RAISE EXCEPTION 'title required' USING ERRCODE = '22023';
  END IF;

  v_space := CASE WHEN p_doc_type = 'gajeong' THEN 'gajeong' ELSE 'volunteer' END;
  v_no := next_document_issue_no(v_space);

  INSERT INTO document_issue (
    doc_type, issue_no, issue_year, title, issued_on, department,
    students, grade, class_number, form_data, remarks, created_by, meta
  ) VALUES (
    p_doc_type, v_no, v_year, btrim(p_title), p_issued_on, p_department,
    COALESCE(p_students,'[]'::jsonb), p_grade, p_class_number, p_form_data, p_remarks, auth.uid(),
    COALESCE(p_meta, '{}'::jsonb)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."create_document_issue"("p_doc_type" "text", "p_title" "text", "p_issued_on" "date", "p_department" "text", "p_students" "jsonb", "p_grade" integer, "p_class_number" integer, "p_form_data" "jsonb", "p_remarks" "text", "p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_manual_notification"("p_target_resource_ids" "uuid"[], "p_title" "text", "p_message" "text", "p_related_meeting_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target_resource_id UUID;
BEGIN
  FOREACH target_resource_id IN ARRAY p_target_resource_ids
  LOOP
    INSERT INTO public.notification_events (
      resource_id, type, title, message, related_meeting_id
    ) VALUES (
      target_resource_id, 'manual', p_title, p_message, p_related_meeting_id
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."create_manual_notification"("p_target_resource_ids" "uuid"[], "p_title" "text", "p_message" "text", "p_related_meeting_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_meeting_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  notification_title TEXT;
  notification_message TEXT;
  assignee_name TEXT;
  resource_record RECORD;
BEGIN
  -- Create notifications for training, duty, and document_submission meeting types
  -- No notifications for: schedule (학사일정), event (행사), personal (개인일정)
  IF NEW.kind IN ('training', 'duty', 'document_submission') THEN
    -- Set notification content based on meeting type
    CASE NEW.kind
      WHEN 'training' THEN
        notification_title := '새로운 연수 일정';
        notification_message := (NEW.meta->>'title') || ' 연수가 ' ||
          to_char(NEW.starts_at, 'YYYY년 MM월 DD일 HH24:MI') || '에 예정되어 있습니다.';
      WHEN 'duty' THEN
        notification_title := '새로운 근무 일정';
        notification_message := (NEW.meta->>'title') || ' 근무가 ' ||
          to_char(NEW.starts_at, 'YYYY년 MM월 DD일 HH24:MI') || '에 예정되어 있습니다.';
      WHEN 'document_submission' THEN
        notification_title := '새로운 서류 제출 일정';
        notification_message := (NEW.meta->>'title') || ' 서류 제출이 ' ||
          to_char(NEW.ends_at, 'YYYY년 MM월 DD일 HH24:MI') || '까지입니다.';
    END CASE;

    -- Create notifications for assignees stored in meta.assignee JSONB only
    -- No notifications sent to creators
    -- meta.assignee is now an object with names as keys: {"이름1": {"name": "이름1"}, "이름2": {"name": "이름2"}}
    IF NEW.meta ? 'assignee' AND jsonb_typeof(NEW.meta->'assignee') = 'object' THEN
      FOR assignee_name IN SELECT jsonb_object_keys(NEW.meta->'assignee')
      LOOP
        -- Find resource by name
        FOR resource_record IN
          SELECT r.id
          FROM public.resource r
          WHERE r.name = assignee_name AND r.type = 'teacher'
        LOOP
          INSERT INTO public.notification_events (
            resource_id, type, title, message, related_meeting_id, meta
          ) VALUES (
            resource_record.id,
            'schedule_created',
            notification_title,
            notification_message,
            NEW.id,
            -- 2026-10-25 — 연수 알림은 누르면 «내 서명 QR»(/training-sign-qr/<id>)로(notificationNavigation.ts)
            CASE WHEN NEW.kind = 'training' THEN jsonb_build_object('meeting_kind', 'training') ELSE '{}'::jsonb END
          );
        END LOOP;
      END LOOP;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_meeting_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_notification"("p_user_id" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_related_problem_id" "uuid" DEFAULT NULL::"uuid", "p_related_solution_id" "uuid" DEFAULT NULL::"uuid", "p_related_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  -- Don't send notification to yourself
  IF p_user_id = p_related_user_id THEN
    RETURN;
  END IF;
  
  INSERT INTO public.notifications (
    user_id, type, title, message, 
    related_problem_id, related_solution_id, related_user_id
  ) VALUES (
    p_user_id, p_type, p_title, p_message,
    p_related_problem_id, p_related_solution_id, p_related_user_id
  );
END;
$$;


ALTER FUNCTION "public"."create_notification"("p_user_id" "uuid", "p_type" "text", "p_title" "text", "p_message" "text", "p_related_problem_id" "uuid", "p_related_solution_id" "uuid", "p_related_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_problem_solving_achievements"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  subject_record RECORD;
  chapter_record RECORD;
  difficulty_record RECORD;
BEGIN
  -- Clear existing achievements
  DELETE FROM public.achievements;
  
  -- Create general difficulty achievements
  FOR difficulty_record IN 
    SELECT DISTINCT difficulty FROM public.problems WHERE difficulty IS NOT NULL
  LOOP
    -- 5, 10, 20, 50 problems for each difficulty
    INSERT INTO public.achievements (title, description, type, category, difficulty, target_count, icon)
    VALUES 
      (difficulty_record.difficulty || ' 난이도 5문제 도전자', difficulty_record.difficulty || ' 난이도 문제 5개를 풀어보세요!', 'problem_solve', 'general', difficulty_record.difficulty, 5, '🌟'),
      (difficulty_record.difficulty || ' 난이도 10문제 마스터', difficulty_record.difficulty || ' 난이도 문제 10개를 풀어보세요!', 'problem_solve', 'general', difficulty_record.difficulty, 10, '⭐'),
      (difficulty_record.difficulty || ' 난이도 20문제 전문가', difficulty_record.difficulty || ' 난이도 문제 20개를 풀어보세요!', 'problem_solve', 'general', difficulty_record.difficulty, 20, '🏆'),
      (difficulty_record.difficulty || ' 난이도 50문제 마스터', difficulty_record.difficulty || ' 난이도 문제 50개를 풀어보세요!', 'problem_solve', 'general', difficulty_record.difficulty, 50, '👑');
  END LOOP;
  
  -- Create subject-based achievements
  FOR subject_record IN 
    SELECT DISTINCT subject FROM public.problems WHERE subject IS NOT NULL
  LOOP
    -- 5, 10, 20 problems for each subject
    INSERT INTO public.achievements (title, description, type, category, target_count, icon)
    VALUES 
      (subject_record.subject || ' 5문제 도전자', subject_record.subject || ' 문제 5개를 풀어보세요!', 'problem_solve', subject_record.subject, 5, '📚'),
      (subject_record.subject || ' 10문제 마스터', subject_record.subject || ' 문제 10개를 풀어보세요!', 'problem_solve', subject_record.subject, 10, '📖'),
      (subject_record.subject || ' 20문제 전문가', subject_record.subject || ' 문제 20개를 풀어보세요!', 'problem_solve', subject_record.subject, 20, '🎓');
      
    -- Create chapter-based achievements for each difficulty within subject
    FOR chapter_record IN 
      SELECT DISTINCT chapter FROM public.problems 
      WHERE subject = subject_record.subject AND chapter IS NOT NULL
    LOOP
      FOR difficulty_record IN 
        SELECT DISTINCT difficulty FROM public.problems 
        WHERE subject = subject_record.subject AND chapter = chapter_record.chapter AND difficulty IS NOT NULL
      LOOP
        INSERT INTO public.achievements (title, description, type, category, subcategory, difficulty, target_count, icon)
        VALUES 
          (subject_record.subject || ' ' || chapter_record.chapter || ' ' || difficulty_record.difficulty || ' 3문제', 
           subject_record.subject || '의 ' || chapter_record.chapter || ' 단원 ' || difficulty_record.difficulty || ' 난이도 문제 3개를 풀어보세요!', 
           'problem_solve', subject_record.subject, chapter_record.chapter, difficulty_record.difficulty, 3, '📝'),
          (subject_record.subject || ' ' || chapter_record.chapter || ' ' || difficulty_record.difficulty || ' 5문제', 
           subject_record.subject || '의 ' || chapter_record.chapter || ' 단원 ' || difficulty_record.difficulty || ' 난이도 문제 5개를 풀어보세요!', 
           'problem_solve', subject_record.subject, chapter_record.chapter, difficulty_record.difficulty, 5, '📋');
      END LOOP;
    END LOOP;
  END LOOP;
  
  -- Create solution posting achievements
  INSERT INTO public.achievements (title, description, type, category, target_count, icon)
  VALUES 
    ('첫 풀이 등록', '첫 번째 풀이를 등록해보세요!', 'solution_post', 'general', 1, '🎯'),
    ('풀이 공유자', '풀이 5개를 등록해보세요!', 'solution_post', 'general', 5, '📤'),
    ('풀이 기여자', '풀이 10개를 등록해보세요!', 'solution_post', 'general', 10, '🤝'),
    ('풀이 마스터', '풀이 20개를 등록해보세요!', 'solution_post', 'general', 20, '🚀'),
    ('일주일 연속 풀이', '7일 연속 풀이를 등록해보세요!', 'streak', 'general', 7, '🔥'),
    ('2주 연속 풀이', '14일 연속 풀이를 등록해보세요!', 'streak', 'general', 14, '⚡'),
    ('한 달 연속 풀이', '30일 연속 풀이를 등록해보세요!', 'streak', 'general', 30, '💫');
END;
$$;


ALTER FUNCTION "public"."create_problem_solving_achievements"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_rescue_note_with_companions"("p_student_code" "text", "p_co_student_codes" "text"[], "p_occurred_at" timestamp with time zone, "p_content" "text", "p_end_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_title" "text" DEFAULT ''::"text", "p_remarks" "text" DEFAULT NULL::"text", "p_visibility" "public"."rescue_visibility" DEFAULT 'team'::"public"."rescue_visibility", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_note_no   text;
  v_master_id uuid;
  v_co_code   text;
  v_other_companions text[];
BEGIN
  -- Auth check: caller must be able to care for the master student
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  -- 무결성: 마스터 학생은 현재 재학생 명부(resource)에 존재해야 함 (FK 대체)
  IF NOT EXISTS (
    SELECT 1 FROM resource
    WHERE type = 'student' AND meta->>'id' = p_student_code
  ) THEN
    RAISE EXCEPTION 'unknown student %', p_student_code USING ERRCODE = '23503';
  END IF;

  IF NOT can_care_student(p_student_code) THEN
    RAISE EXCEPTION 'access denied for student %', p_student_code USING ERRCODE = '42501';
  END IF;

  -- Validate co-students
  IF p_co_student_codes IS NOT NULL THEN
    FOREACH v_co_code IN ARRAY p_co_student_codes LOOP
      IF v_co_code IS NULL OR v_co_code = '' OR v_co_code = p_student_code THEN
        CONTINUE;
      END IF;
      -- 무결성: 동반 학생도 재학생 명부에 존재해야 함 (FK 대체)
      IF NOT EXISTS (
        SELECT 1 FROM resource
        WHERE type = 'student' AND meta->>'id' = v_co_code
      ) THEN
        RAISE EXCEPTION 'unknown co-student %', v_co_code USING ERRCODE = '23503';
      END IF;
      IF NOT can_care_student(v_co_code) THEN
        RAISE EXCEPTION 'access denied for co-student %', v_co_code USING ERRCODE = '42501';
      END IF;
    END LOOP;
  END IF;

  v_note_no := next_rescue_note_no();

  -- Master row: co_student_codes = p_co_student_codes (without nulls/duplicates of self)
  INSERT INTO rescue_notes (
    student_code, occurred_at, end_at, title, remarks, content, visibility, meta,
    created_by, note_no, co_student_codes, linked_note_id
  ) VALUES (
    p_student_code,
    p_occurred_at,
    p_end_at,
    COALESCE(p_title, ''),
    p_remarks,
    p_content,
    COALESCE(p_visibility, 'team'),
    COALESCE(p_meta, '{}'::jsonb),
    auth.uid(),
    v_note_no,
    COALESCE(p_co_student_codes, '{}'::text[]),
    NULL
  )
  RETURNING id INTO v_master_id;

  -- Companion copies
  IF p_co_student_codes IS NOT NULL THEN
    FOREACH v_co_code IN ARRAY p_co_student_codes LOOP
      IF v_co_code IS NULL OR v_co_code = '' OR v_co_code = p_student_code THEN
        CONTINUE;
      END IF;

      v_other_companions :=
        array_remove(
          array_append(COALESCE(p_co_student_codes, '{}'::text[]), p_student_code),
          v_co_code
        );

      INSERT INTO rescue_notes (
        student_code, occurred_at, end_at, title, remarks, content, visibility, meta,
        created_by, note_no, co_student_codes, linked_note_id
      ) VALUES (
        v_co_code,
        p_occurred_at,
        p_end_at,
        COALESCE(p_title, ''),
        p_remarks,
        p_content,
        COALESCE(p_visibility, 'team'),
        COALESCE(p_meta, '{}'::jsonb),
        auth.uid(),
        v_note_no,
        v_other_companions,
        v_master_id
      );
    END LOOP;
  END IF;

  RETURN v_master_id;
END;
$$;


ALTER FUNCTION "public"."create_rescue_note_with_companions"("p_student_code" "text", "p_co_student_codes" "text"[], "p_occurred_at" timestamp with time zone, "p_content" "text", "p_end_at" timestamp with time zone, "p_title" "text", "p_remarks" "text", "p_visibility" "public"."rescue_visibility", "p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_rescue_scholarship"("p_student_code" "text", "p_name" "text", "p_awarded_on" "date", "p_remarks" "text" DEFAULT NULL::"text", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_no text;
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT can_care_student(p_student_code) THEN
    RAISE EXCEPTION 'access denied for student %', p_student_code USING ERRCODE = '42501';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'scholarship name required' USING ERRCODE = '22023';
  END IF;

  v_no := next_rescue_scholarship_no();

  INSERT INTO rescue_scholarships (
    student_code, scholarship_no, name, awarded_on, remarks, meta, created_by
  ) VALUES (
    p_student_code, v_no, btrim(p_name), p_awarded_on, p_remarks,
    COALESCE(p_meta, '{}'::jsonb), auth.uid()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."create_rescue_scholarship"("p_student_code" "text", "p_name" "text", "p_awarded_on" "date", "p_remarks" "text", "p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_signature_request"("p_title" "text", "p_message" "text", "p_source_kind" "text", "p_source_path" "text", "p_source_name" "text", "p_source_mime" "text", "p_page_count" integer, "p_signers" "jsonb", "p_subject_type" "text" DEFAULT NULL::"text", "p_subject_id" "text" DEFAULT NULL::"text", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request_id  uuid;
  v_name        text;
  v_resource_id uuid;
  v_signer      jsonb;
  v_signer_rid  uuid;
  v_signer_uid  uuid;
  v_order       int;
  v_min_order   int;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '28000';
  end if;

  v_name := public.current_profile_name();
  if v_name is null or btrim(v_name) = '' then
    raise exception '프로필 이름이 없어 서명을 요청할 수 없습니다.' using errcode = '22023';
  end if;

  if p_signers is null or jsonb_typeof(p_signers) <> 'array' or jsonb_array_length(p_signers) = 0 then
    raise exception '서명자를 한 명 이상 지정해야 합니다.' using errcode = '22023';
  end if;
  if jsonb_array_length(p_signers) > 30 then
    raise exception '서명자는 최대 30명입니다.' using errcode = '22023';
  end if;

  select ur.resource_id into v_resource_id
  from public.user_resource ur where ur.user_id = auth.uid() limit 1;

  insert into public.signature_request (
    title, message, subject_type, subject_id,
    source_kind, source_path, source_name, source_mime, page_count,
    requester_user_id, requester_resource_id, requester_name, meta
  ) values (
    p_title, nullif(btrim(coalesce(p_message, '')), ''),
    nullif(btrim(coalesce(p_subject_type, '')), ''),
    nullif(btrim(coalesce(p_subject_id, '')), ''),
    p_source_kind, p_source_path, p_source_name, p_source_mime, p_page_count,
    auth.uid(), v_resource_id, v_name, coalesce(p_meta, '{}'::jsonb)
  ) returning id into v_request_id;

  for v_signer in select * from jsonb_array_elements(p_signers)
  loop
    if coalesce(btrim(v_signer->>'signer_name'), '') = '' then
      raise exception '서명자 이름이 비어 있습니다.' using errcode = '22023';
    end if;

    v_signer_rid := nullif(v_signer->>'signer_resource_id', '')::uuid;

    select ur.user_id into v_signer_uid
    from public.user_resource ur
    where v_signer_rid is not null and ur.resource_id = v_signer_rid
    limit 1;

    if v_signer_uid is null then
      select p.id into v_signer_uid
      from public.profiles p
      where p.name = btrim(v_signer->>'signer_name')
      limit 1;
    end if;

    v_order := coalesce((v_signer->>'order_index')::int, 0);
    if v_order < 0 or v_order > 29 then
      raise exception '서명 순서 값이 올바르지 않습니다: %', v_order using errcode = '22023';
    end if;

    insert into public.signature_signer (
      request_id, order_index, role_label,
      signer_user_id, signer_resource_id, signer_name, fields
    ) values (
      v_request_id, v_order,
      nullif(btrim(coalesce(v_signer->>'role_label', '')), ''),
      v_signer_uid, v_signer_rid, btrim(v_signer->>'signer_name'),
      case when jsonb_typeof(v_signer->'fields') = 'array'
           then v_signer->'fields' else '[]'::jsonb end
    );
  end loop;

  -- 첫 차례는 **실제로 존재하는 가장 작은 그룹**이다. 0 으로 고정하면 요청자가
  -- 순서를 1부터 매긴 경우 아무도 차례가 아니어서 영원히 멈춘다.
  select min(order_index) into v_min_order
  from public.signature_signer where request_id = v_request_id;

  update public.signature_request
     set current_order = coalesce(v_min_order, 0), updated_at = now()
   where id = v_request_id;

  -- 로그인 없는 QR 서명용 링크 토큰(서명자 1인당 1개)
  perform public.issue_signature_sign_tokens(v_request_id);

  return v_request_id;
end;
$$;


ALTER FUNCTION "public"."create_signature_request"("p_title" "text", "p_message" "text", "p_source_kind" "text", "p_source_path" "text", "p_source_name" "text", "p_source_mime" "text", "p_page_count" integer, "p_signers" "jsonb", "p_subject_type" "text", "p_subject_id" "text", "p_meta" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."task_action_document_template" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "format" "text" DEFAULT 'hwpx'::"text" NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "source_file_name" "text" NOT NULL,
    "storage_bucket" "text" DEFAULT 'task-work-documents'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "mime_type" "text" DEFAULT 'application/hwp+zip'::"text" NOT NULL,
    "size_bytes" bigint NOT NULL,
    "content_sha256" "text" NOT NULL,
    "fields" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "family_id" "uuid" NOT NULL,
    "previous_version_id" "uuid",
    "spec" "jsonb",
    CONSTRAINT "task_action_document_template_content_sha256_check" CHECK (("content_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "task_action_document_template_fields_check" CHECK (("jsonb_typeof"("fields") = 'array'::"text")),
    CONSTRAINT "task_action_document_template_format_check" CHECK (("format" = 'hwpx'::"text")),
    CONSTRAINT "task_action_document_template_lineage_shape_check" CHECK (((("version" = 1) AND ("previous_version_id" IS NULL) AND ("family_id" = "id")) OR (("version" > 1) AND ("previous_version_id" IS NOT NULL) AND ("family_id" <> "id")))),
    CONSTRAINT "task_action_document_template_name_check" CHECK ((("length"("btrim"("name")) >= 1) AND ("length"("btrim"("name")) <= 120))),
    CONSTRAINT "task_action_document_template_size_bytes_check" CHECK ((("size_bytes" > 0) AND ("size_bytes" <= 20971520))),
    CONSTRAINT "task_action_document_template_source_file_name_check" CHECK ((("length"("btrim"("source_file_name")) >= 1) AND ("length"("btrim"("source_file_name")) <= 255))),
    CONSTRAINT "task_action_document_template_storage_bucket_check" CHECK (("storage_bucket" = 'task-work-documents'::"text")),
    CONSTRAINT "task_action_document_template_storage_path_check" CHECK ((("length"("btrim"("storage_path")) >= 1) AND ("length"("btrim"("storage_path")) <= 1024))),
    CONSTRAINT "task_action_document_template_version_check" CHECK (("version" > 0))
);

ALTER TABLE ONLY "public"."task_action_document_template" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."task_action_document_template" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_action_document_template" IS 'HWPX 양식 템플릿(+Work Spec). 읽기=전 교사/admin(공유), 쓰기=생성자 ∨ admin. Storage 경로 첫 폴더는 항상 행 소유자(created_by)와 같아야 한다. 버전 행은 불변이며 삭제 불가(과거 RUN·완성 문서 재구성 보호) — 목록 제거는 archived_at.';



COMMENT ON COLUMN "public"."task_action_document_template"."fields" IS 'key, label, required, defaultValue, occurrences를 가진 치환 필드 정의 배열.';



COMMENT ON COLUMN "public"."task_action_document_template"."family_id" IS '같은 논리 템플릿 버전 계보의 v1 행 ID.';



COMMENT ON COLUMN "public"."task_action_document_template"."previous_version_id" IS '바로 이전 불변 템플릿 버전. 계보는 분기 없는 선형 구조다.';



COMMENT ON COLUMN "public"."task_action_document_template"."spec" IS 'Work Spec v1 — 채움 타깃·제약·지식 소스 선언(JSON). null = 기존 fields 전용 템플릿';



CREATE OR REPLACE FUNCTION "public"."create_task_action_document_template_version"("p_previous_template_id" "uuid", "p_id" "uuid", "p_name" "text", "p_description" "text", "p_source_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_content_sha256" "text", "p_fields" "jsonb") RETURNS "public"."task_action_document_template"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_previous public.task_action_document_template%rowtype;
  v_created public.task_action_document_template%rowtype;
begin
  if v_user_id is null then
    raise exception '인증이 필요합니다.'
      using errcode = '42501';
  end if;

  select *
  into v_previous
  from public.task_action_document_template
  where id = p_previous_template_id
    and created_by = v_user_id
    and archived_at is null
  for update;

  if not found then
    raise exception '현재 문서 템플릿 버전을 찾을 수 없습니다.'
      using errcode = 'P0002';
  end if;

  update public.task_action_document_template
  set archived_at = clock_timestamp()
  where id = v_previous.id;

  insert into public.task_action_document_template (
    id,
    created_by,
    family_id,
    previous_version_id,
    name,
    description,
    version,
    source_file_name,
    storage_path,
    mime_type,
    size_bytes,
    content_sha256,
    fields
  )
  values (
    p_id,
    v_user_id,
    v_previous.family_id,
    v_previous.id,
    btrim(p_name),
    nullif(btrim(p_description), ''),
    v_previous.version + 1,
    p_source_file_name,
    p_storage_path,
    p_mime_type,
    p_size_bytes,
    p_content_sha256,
    p_fields
  )
  returning * into v_created;

  return v_created;
end;
$$;


ALTER FUNCTION "public"."create_task_action_document_template_version"("p_previous_template_id" "uuid", "p_id" "uuid", "p_name" "text", "p_description" "text", "p_source_file_name" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_content_sha256" "text", "p_fields" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."task_action_document" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "template_version_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "plan" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "knowledge" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "field_values" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "row_values" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "user_context" "text",
    "family_id" "uuid" NOT NULL,
    "previous_version_id" "uuid",
    "version" integer DEFAULT 1 NOT NULL,
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "action_id" "uuid",
    CONSTRAINT "task_action_document_field_values_check" CHECK ((("jsonb_typeof"("field_values") = 'object'::"text") AND ("octet_length"(("field_values")::"text") <= 2097152))),
    CONSTRAINT "task_action_document_knowledge_check" CHECK ((("jsonb_typeof"("knowledge") = 'object'::"text") AND ("octet_length"(("knowledge")::"text") <= 2097152))),
    CONSTRAINT "task_action_document_lineage_shape_check" CHECK (((("version" = 1) AND ("previous_version_id" IS NULL) AND ("family_id" = "id")) OR (("version" > 1) AND ("previous_version_id" IS NOT NULL) AND ("family_id" <> "id")))),
    CONSTRAINT "task_action_document_plan_check" CHECK ((("jsonb_typeof"("plan") = 'object'::"text") AND ("octet_length"(("plan")::"text") <= 2097152))),
    CONSTRAINT "task_action_document_row_values_check" CHECK ((("jsonb_typeof"("row_values") = 'object'::"text") AND ("octet_length"(("row_values")::"text") <= 2097152))),
    CONSTRAINT "task_action_document_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'final'::"text"]))),
    CONSTRAINT "task_action_document_title_check" CHECK ((("length"("btrim"("title")) >= 1) AND ("length"("btrim"("title")) <= 200))),
    CONSTRAINT "task_action_document_version_check" CHECK (("version" > 0))
);

ALTER TABLE ONLY "public"."task_action_document" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."task_action_document" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_action_document" IS '값-기반 완성 문서: 템플릿 버전 참조 + plan/knowledge/확정 값(JSONB)만 저장하고 파일은 재구성한다.';



COMMENT ON COLUMN "public"."task_action_document"."template_version_id" IS '재구성에 사용할 템플릿 "버전 행" 고정 참조(가족이 아님).';



COMMENT ON COLUMN "public"."task_action_document"."field_values" IS '타깃별 확정 값(FillOutput.values — prose 포함). presetValues로 재주입하면 LLM 없이 동일 문서가 재구성된다.';



COMMENT ON COLUMN "public"."task_action_document"."row_values" IS 'rowGroup 타깃별 확정 행 데이터(FillOutput.rows).';



COMMENT ON COLUMN "public"."task_action_document"."action_id" IS '이 문서를 만든 WORK(노드). 러너의 "저장된 완성 문서" 목록은 이 값으로 거른다. 노드 삭제 시 NULL(문서는 보존, 목록에서만 사라짐).';



CREATE OR REPLACE FUNCTION "public"."create_task_action_document_version"("p_previous_document_id" "uuid", "p_id" "uuid", "p_title" "text", "p_status" "text", "p_plan" "jsonb", "p_knowledge" "jsonb", "p_field_values" "jsonb", "p_row_values" "jsonb", "p_user_context" "text", "p_template_version_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."task_action_document"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_previous public.task_action_document%rowtype;
  v_created public.task_action_document%rowtype;
begin
  if v_user_id is null then
    raise exception '인증이 필요합니다.'
      using errcode = '42501';
  end if;

  select *
  into v_previous
  from public.task_action_document
  where id = p_previous_document_id
    and created_by = v_user_id
    and archived_at is null
  for update;

  if not found then
    raise exception '현재 완성 문서 버전을 찾을 수 없습니다.'
      using errcode = 'P0002';
  end if;

  update public.task_action_document
  set archived_at = clock_timestamp()
  where id = v_previous.id;

  insert into public.task_action_document (
    id, created_by, template_version_id, title, status,
    plan, knowledge, field_values, row_values, user_context,
    family_id, previous_version_id, version, action_id
  )
  values (
    p_id,
    v_user_id,
    coalesce(p_template_version_id, v_previous.template_version_id),
    btrim(p_title),
    coalesce(p_status, 'draft'),
    coalesce(p_plan, '{}'::jsonb),
    coalesce(p_knowledge, '{}'::jsonb),
    coalesce(p_field_values, '{}'::jsonb),
    coalesce(p_row_values, '{}'::jsonb),
    nullif(btrim(coalesce(p_user_context, '')), ''),
    v_previous.family_id,
    v_previous.id,
    v_previous.version + 1,
    v_previous.action_id   -- 소속 노드 승계
  )
  returning * into v_created;

  return v_created;
end;
$$;


