CREATE OR REPLACE FUNCTION "public"."current_academic_term"() RETURNS TABLE("academic_year" integer, "semester" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select * from (
    select (s.setting_value->>'year')::int, (s.setting_value->>'semester')::int
    from public.system_settings s
    where s.setting_key = 'academic_term'
      and s.setting_value ? 'year' and s.setting_value ? 'semester'
    union all
    select * from (
      select tt.academic_year, tt.semester
      from public.teacher_timetable tt
      order by tt.academic_year desc, tt.semester desc
      limit 1
    ) latest
  ) x
  limit 1;
$$;


ALTER FUNCTION "public"."current_academic_term"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."current_academic_term"() IS '현재 학년도·학기. 학사력(system_settings.academic_term) 우선, 없으면 가장 최근 교사 시간표 학기. 클라이언트 짝 = useTimetableTerm.';



CREATE OR REPLACE FUNCTION "public"."current_actor_resource_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(
    (
      SELECT ur.resource_id
      FROM public.user_resource ur
      WHERE ur.user_id = auth.uid()
      ORDER BY ur.created_at
      LIMIT 1
    ),
    (
      SELECT r.id
      FROM public.profiles p
      JOIN public.resource r
        ON r.type = 'student'
       AND r.meta->>'id' = SPLIT_PART(p.email, '@', 1)
      WHERE p.id = auth.uid()
      LIMIT 1
    )
  );
$$;


