CREATE OR REPLACE FUNCTION "public"."current_rescue_role"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN EXISTS (
      SELECT 1
      FROM resource_tag_assignments rta
      JOIN resource_tags rt ON rt.id = rta.tag_id
      JOIN user_resource ur ON ur.resource_id = rta.resource_id
      WHERE ur.user_id = auth.uid()
        AND rt.name = '위기관리담당자'
    ) THEN 'staff_admin'
    WHEN EXISTS (
      SELECT 1
      FROM resource_tag_assignments rta
      JOIN resource_tags rt ON rt.id = rta.tag_id
      JOIN user_resource ur ON ur.resource_id = rta.resource_id
      WHERE ur.user_id = auth.uid()
        AND rt.name = '상담교사'
    ) THEN 'counselor'
    ELSE NULL
  END;
$$;


