CREATE OR REPLACE FUNCTION "public"."delete_action_submission"("p_submission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.action_submission;
  v_req public.collect_request;
  v_manage boolean;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into v_row from public.action_submission where id = p_submission_id for update;
  if not found then raise exception '제출물을 찾을 수 없습니다' using errcode = 'P0002'; end if;
  select * into v_req from public.collect_request where action_id = v_row.action_id;
  v_manage := public.can_manage_collect(v_row.action_id);
  if not v_manage then
    if v_row.kind = 'physical' then raise exception '실물 수령 기록은 책임자만 취소할 수 있습니다' using errcode = '42501'; end if;
    if v_row.resource_id is distinct from public.current_actor_resource_id() then
      raise exception '본인 제출물만 지울 수 있습니다' using errcode = '42501';
    end if;
    if v_req.status <> 'open' then raise exception '마감된 요청입니다' using errcode = '22023'; end if;
  end if;
  delete from public.action_submission where id = p_submission_id;
  perform public._submission_sync_unit(v_req, v_row.resource_id, v_row.unit_key);
  perform public.submission_sync_assignee(v_req.task_id, v_row.resource_id);
  return jsonb_build_object('success', true, 'remaining',
    (select count(*) from public.action_submission where action_id = v_row.action_id and resource_id = v_row.resource_id
       and coalesce(unit_key, '') = coalesce(v_row.unit_key, '')));
end;
$$;


ALTER FUNCTION "public"."delete_action_submission"("p_submission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_inquiry_design"("p_design_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_student_id text;
BEGIN
  SELECT student_id
  INTO v_student_id
  FROM public.student_inquiry_designs
  WHERE id = p_design_id;

  IF v_student_id IS NULL THEN
    RETURN false;
  END IF;

  IF NOT public.inquiry_design_can_access_student(v_student_id) THEN
    RAISE EXCEPTION 'not allowed to delete inquiry design %', p_design_id;
  END IF;

  DELETE FROM public.student_inquiry_designs
  WHERE id = p_design_id;

  RETURN true;
END;
$$;


