CREATE OR REPLACE FUNCTION "public"."delete_signature_request"("p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_request public.signature_request;
begin
  -- 익명이면 아래 비교가 NULL 이 되어 조용히 통과한다(SQL 3값 논리) — 맨 앞에서 막는다
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '28000';
  end if;

  select * into v_request from public.signature_request where id = p_request_id for update;
  if not found then
    raise exception '서명 요청을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not coalesce(v_request.requester_user_id = auth.uid(), false) and not public.is_admin() then
    raise exception '요청자만 삭제할 수 있습니다.' using errcode = '42501';
  end if;

  -- signature_signer · signature_sign_token 은 FK ON DELETE CASCADE 로 함께 사라진다
  delete from public.signature_request where id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."delete_signature_request"("p_request_id" "uuid") OWNER TO "postgres";


