CREATE OR REPLACE FUNCTION "public"."delete_task_action_run"("p_run_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_run public.task_action_run%rowtype;
  v_paths text[];
begin
  if v_user_id is null then
    raise exception '인증이 필요합니다.' using errcode = '42501';
  end if;

  select * into v_run
  from public.task_action_run
  where id = p_run_id and created_by = v_user_id
  for update;

  if not found then
    raise exception 'RUN을 찾을 수 없거나 권한이 없습니다.' using errcode = 'P0002';
  end if;

  -- 상태 가드 없음(2026-08-14): created/running도 삭제 허용 — 위 주석 참조.

  select coalesce(array_agg(a.locator->>'path'), '{}'::text[])
  into v_paths
  from public.task_action_artifact a
  where a.run_id = p_run_id
    and a.artifact_type = 'file'
    and a.locator->>'bucket' = 'task-work-documents'
    and coalesce(a.locator->>'path', '') <> '';

  delete from public.task_action_run where id = p_run_id;

  return v_paths;
end;
$$;


ALTER FUNCTION "public"."delete_task_action_run"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_task_submission"("p_submission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor_resource_id uuid;
  row_task_id uuid;
  row_assignee_id uuid;
  row_unit_key text;
  row_kind text;
  task_meta jsonb;
  has_units boolean := false;
  unit_still_defined boolean := false;
  assignee_in_pool boolean := false;
  remaining int;
  actor_is_manager boolean;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  actor_resource_id := public.current_actor_resource_id();
  if actor_resource_id is null then
    raise exception 'User resource not found' using errcode = '42501';
  end if;

  select s.task_id, s.assignee_resource_id, s.unit_key, s.kind
  into row_task_id, row_assignee_id, row_unit_key, row_kind
  from public.task_submission s
  where s.id = p_submission_id
  for update;

  if not found then
    raise exception 'Submission not found: %', p_submission_id using errcode = 'P0002';
  end if;

  actor_is_manager := public.is_task_event_manager(row_task_id, actor_resource_id) or public.is_admin();

  if row_assignee_id <> actor_resource_id and not actor_is_manager then
    raise exception 'Only the submitter or an work manager can remove this submission'
      using errcode = '42501';
  end if;

  -- 실물 수령 기록은 매니저가 남긴 것이다 — 담당자가 지우면 받은 사실이 사라진다
  if row_kind = 'physical' and not actor_is_manager then
    raise exception '실물 수령 기록은 책임자만 취소할 수 있습니다.' using errcode = '42501';
  end if;

  delete from public.task_submission where id = p_submission_id;

  select coalesce(t.meta, '{}'::jsonb) into task_meta
  from public.task t where t.id = row_task_id;
  has_units := jsonb_typeof(task_meta->'units') = 'array'
    and jsonb_array_length(task_meta->'units') > 0;

  if has_units then
    select count(*) into remaining
    from public.task_submission
    where task_id = row_task_id
      and assignee_resource_id = row_assignee_id
      and unit_key is not distinct from row_unit_key;

    if remaining = 0 and row_unit_key is not null then
      select exists (
        select 1 from jsonb_array_elements(task_meta->'units') as unit(value)
        where value->>'key' = row_unit_key
      ) into unit_still_defined;
      select exists (
        select 1 from jsonb_array_elements(
          case when jsonb_typeof(task_meta->'assignees') = 'array'
            then task_meta->'assignees' else '[]'::jsonb end
        ) as a(value)
        where a.value->>'id' = row_assignee_id::text
          and coalesce(a.value->>'status', 'pending') <> 'cancelled'
      ) into assignee_in_pool;

      if unit_still_defined and assignee_in_pool then
        perform public.set_task_unit_status(row_task_id, row_unit_key, row_assignee_id, 'pending');
      end if;
    end if;
  else
    select count(*) into remaining
    from public.task_submission
    where task_id = row_task_id and assignee_resource_id = row_assignee_id;

    if remaining = 0 then
      perform public.set_task_assignee_status(row_task_id, row_assignee_id, 'pending');
    end if;
  end if;

  return jsonb_build_object(
    'success', true,
    'task_id', row_task_id,
    'assignee_id', row_assignee_id,
    'unit_key', row_unit_key,
    'remaining', remaining
  );
end;
$$;


