CREATE OR REPLACE FUNCTION "public"."desk_agent_ack"("p_device" "text", "p_message" "uuid", "p_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
  v_count int;
begin
  perform public.desk_agent_check_device(p_device);
  if p_status not in ('delivered', 'refused') then
    raise exception '상태가 올바르지 않습니다' using errcode = '22023';
  end if;
  update public.desk_agent_message
     set status = p_status, done_at = now(), note = left(nullif(btrim(coalesce(p_note, '')), ''), 200)
   where id = p_message and recipient_resource_id = v_id and recipient_device = p_device and status = 'sent';
  get diagnostics v_count = row_count;
  return jsonb_build_object('ok', v_count = 1);
end;
$$;


ALTER FUNCTION "public"."desk_agent_ack"("p_device" "text", "p_message" "uuid", "p_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_beat"("p_device" "text", "p_label" "text", "p_agents" "jsonb", "p_cross" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
  v_label text := left(btrim(coalesce(p_label, '')), 40);
  v_agents jsonb;
  v_inbox jsonb;
begin
  perform public.desk_agent_check_device(p_device);
  if v_label = '' then
    v_label := 'PC';
  end if;
  if p_agents is null or jsonb_typeof(p_agents) <> 'array' then
    raise exception '에이전트 목록 형식이 올바르지 않습니다' using errcode = '22023';
  end if;
  -- 이름·제목·도구·상태·방만 남긴다 (폴더 같은 것은 받지 않는다). 방은 uuid 모양일 때만
  select coalesce(jsonb_agg(jsonb_build_object(
           'name', left(a->>'name', 40), 'title', left(coalesce(a->>'title', ''), 60),
           'tool', left(coalesce(a->>'tool', ''), 20), 'status', left(coalesce(a->>'status', ''), 30),
           'thread', case when coalesce(a->>'thread', '') ~ '^[0-9a-f-]{36}$' then a->>'thread' end)), '[]'::jsonb)
    into v_agents
  from (select a from jsonb_array_elements(p_agents) a
        where jsonb_typeof(a) = 'object' and coalesce(a->>'name', '') ~ '^[A-Za-z0-9._-]{1,40}$'
        limit 12) x;

  insert into public.desk_agent_peer (resource_id, device, label, agents, seen_at, cross_pc)
  values (v_id, p_device, v_label, v_agents, now(), coalesce(p_cross, true))
  on conflict (resource_id, device) do update set label = excluded.label, agents = excluded.agents, seen_at = now(),
                                                  cross_pc = excluded.cross_pc;

  update public.desk_agent_message
     set status = 'expired', done_at = now(), note = '받는 PC 가 10분 안에 받아 가지 않았습니다'
   where status = 'sent' and created_at < now() - interval '10 minutes' and recipient_device !~ '^phone:';
  delete from public.desk_agent_message where created_at < now() - interval '7 days';
  delete from public.desk_agent_peer where seen_at < now() - interval '1 day';

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', m.id, 'body', m.body, 'agent', m.recipient_agent, 'reply_to', m.reply_to,
           'is_reply', (o.id is not null), 'created_at', m.created_at, 'thread', m.thread,
           'from_phone', (m.sender_resource_id = v_id and m.sender_device ~ '^phone:'),
           'from_own_pc', (m.sender_resource_id = v_id and m.sender_device ~ '^[0-9a-f]{32}$' and m.sender_device <> p_device),
           'sender', jsonb_build_object('resource_id', m.sender_resource_id, 'name', r.name,
                                        'label', m.sender_label, 'device', m.sender_device, 'agent', m.sender_agent))
           order by m.created_at), '[]'::jsonb)
    into v_inbox
  from (select * from public.desk_agent_message
        where recipient_resource_id = v_id and recipient_device = p_device and status = 'sent'
        order by created_at limit 20) m
  join public.resource r on r.id = m.sender_resource_id
  left join public.desk_agent_message o
    on o.id = m.reply_to and o.sender_resource_id = v_id and o.sender_device = p_device
   and o.sender_agent = m.recipient_agent;

  return jsonb_build_object('me', v_me->>'label', 'inbox', v_inbox);
end;
$_$;


ALTER FUNCTION "public"."desk_agent_beat"("p_device" "text", "p_label" "text", "p_agents" "jsonb", "p_cross" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_check_device"("p_device" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
  if p_device is null or p_device !~ '^[0-9a-f]{32}$' then
    raise exception '데스크 PC 표시가 올바르지 않습니다' using errcode = '22023';
  end if;
end;
$_$;


ALTER FUNCTION "public"."desk_agent_check_device"("p_device" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_cron_post"("p_device" "text", "p_label" "text", "p_agent" "text", "p_title" "text", "p_prompt" "text", "p_result" "text", "p_status" "text" DEFAULT 'done'::"text", "p_late" boolean DEFAULT false, "p_thread" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
  v_title text := left(btrim(coalesce(p_title, '')), 40);
  v_label text := left(btrim(coalesce(p_label, '')), 40);
  v_prompt text := left(btrim(coalesce(p_prompt, '')), 2000);
  v_result text := btrim(coalesce(p_result, ''));
  v_status text := coalesce(p_status, 'done');
  v_thread text := nullif(btrim(coalesce(p_thread, '')), '');
  v_head uuid;
  v_reply uuid;
begin
  perform public.desk_agent_check_device(p_device);
  if coalesce(p_agent, '') !~ '^[A-Za-z0-9._-]{1,40}$' then
    raise exception '에이전트 이름이 올바르지 않습니다' using errcode = '22023';
  end if;
  if v_title = '' then
    raise exception '예약 이름이 비어 있습니다' using errcode = '22023';
  end if;
  if v_thread is not null and v_thread !~ '^[0-9a-f-]{36}$' then
    raise exception '대화 방 id 가 올바르지 않습니다' using errcode = '22023';
  end if;
  if v_prompt = '' then
    v_prompt := '(시킨 일 없음)';
  end if;
  if v_result = '' then
    v_result := '(결과 없음)';
  end if;
  if char_length(v_result) > 8000 then
    raise exception '결과는 8000자까지 올릴 수 있습니다 (지금 %자)', char_length(v_result) using errcode = '22001';
  end if;
  if v_status not in ('done', 'stopped', 'error', 'login', 'busy', 'timeout') then
    raise exception '결과 상태가 올바르지 않습니다' using errcode = '22023';
  end if;
  if v_label = '' then
    v_label := 'PC';
  end if;
  if (select count(*) from public.desk_agent_message
      where sender_resource_id = v_id and created_at > now() - interval '1 hour') >= 120 then
    raise exception '한 시간에 120건까지 보낼 수 있습니다. 잠시 뒤에 다시 보내 주세요' using errcode = '54000';
  end if;

  insert into public.desk_agent_message (sender_resource_id, sender_device, sender_label, sender_agent,
                                         recipient_resource_id, recipient_device, recipient_agent, body,
                                         status, note, done_at, thread)
  values (v_id, 'cron:' || p_device, v_title, 'cron', v_id, p_device, p_agent, v_prompt,
          'delivered', v_status || case when coalesce(p_late, false) then ' late' else '' end, now(), v_thread)
  returning id into v_head;

  insert into public.desk_agent_message (sender_resource_id, sender_device, sender_label, sender_agent,
                                         recipient_resource_id, recipient_device, recipient_agent, body,
                                         reply_to, status, done_at)
  values (v_id, p_device, v_label, p_agent, v_id, 'phone:cron', 'phone', v_result, v_head, 'delivered', now())
  returning id into v_reply;

  return jsonb_build_object('id', v_head, 'reply', v_reply);
end;
$_$;


ALTER FUNCTION "public"."desk_agent_cron_post"("p_device" "text", "p_label" "text", "p_agent" "text", "p_title" "text", "p_prompt" "text", "p_result" "text", "p_status" "text", "p_late" boolean, "p_thread" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_directory"("p_device" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
begin
  perform public.desk_agent_check_device(p_device);
  return coalesce((
    select jsonb_agg(jsonb_build_object('resource_id', p.resource_id, 'name', r.name, 'device', p.device,
                                        'label', p.label, 'agents', p.agents, 'mine', p.resource_id = v_id)
                     order by (p.resource_id = v_id) desc, r.name, p.label)
    from public.desk_agent_peer p
    join public.resource r on r.id = p.resource_id
    where p.seen_at > now() - interval '30 seconds'
      and jsonb_array_length(p.agents) > 0
      and p.cross_pc                                  -- «다른 PC» 를 끈 PC(휴대폰만 켬)는 남에게 보이지 않는다
      and not (p.resource_id = v_id and p.device = p_device)), '[]'::jsonb);
end;
$$;


