declare
  v_me jsonb := public.desk_agent_me();
begin
  perform public.desk_agent_check_device(p_device);
  delete from public.desk_agent_peer where resource_id = (v_me->>'resource_id')::uuid and device = p_device;
  return jsonb_build_object('ok', true);
end;
