CREATE OR REPLACE FUNCTION "public"."desk_agent_me"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_message_who(auth.uid());
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '28000';
  end if;
  if v_me is null or v_me->>'role' <> 'teacher' then
    raise exception '교직원 계정만 다른 PC 의 에이전트와 메시지를 주고받을 수 있습니다' using errcode = '42501';
  end if;
  return v_me;
end;
$$;


