CREATE OR REPLACE FUNCTION "public"."desk_agent_own_overview"("p_device" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
begin
  perform public.desk_agent_check_device(p_device);
  return jsonb_build_object(
    'me', v_me->>'label',
    'pcs', coalesce((
      select jsonb_agg(jsonb_build_object('device', p.device, 'label', p.label, 'seen_at', p.seen_at,
                                          'online', p.seen_at > now() - interval '30 seconds', 'agents', p.agents)
                       order by p.seen_at desc)
      from public.desk_agent_peer p
      where p.resource_id = v_id and p.device <> p_device and p.seen_at > now() - interval '1 day'), '[]'::jsonb),
    'messages', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', m.id, 'body', m.body, 'created_at', m.created_at, 'status', m.status, 'thread', m.thread, 'note', m.note,
               'to_device', m.recipient_device, 'to_agent', m.recipient_agent,
               'to_label', coalesce(p.label, 'PC'),
               'replies', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'body', a.body, 'created_at', a.created_at,
                                                                         'agent', a.sender_agent, 'label', a.sender_label)
                                                      order by a.created_at)
                                    from public.desk_agent_message a
                                    where a.reply_to = m.id and a.recipient_resource_id = v_id), '[]'::jsonb))
             order by m.created_at desc)
      from (select * from public.desk_agent_message
            where sender_resource_id = v_id and recipient_resource_id = v_id
              and sender_device = p_device and sender_agent = 'desk'
            order by created_at desc limit 300) m
      left join public.desk_agent_peer p on p.resource_id = v_id and p.device = m.recipient_device), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."desk_agent_own_overview"("p_device" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_own_send"("p_device" "text", "p_to_device" "text", "p_to_agent" "text", "p_body" "text", "p_thread" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
  v_from public.desk_agent_peer;
  v_peer public.desk_agent_peer;
  v_body text := btrim(coalesce(p_body, ''));
  v_thread text := nullif(btrim(coalesce(p_thread, '')), '');
  v_new uuid;
begin
  perform public.desk_agent_check_device(p_device);
  perform public.desk_agent_check_device(p_to_device);
  if p_device = p_to_device then
    raise exception '이 PC 의 에이전트에게는 터미널에서 바로 말하면 됩니다' using errcode = '22023';
  end if;
  if coalesce(p_to_agent, '') !~ '^[A-Za-z0-9._-]{1,40}$' then
    raise exception '받는 에이전트 이름이 올바르지 않습니다' using errcode = '22023';
  end if;
  if v_body = '' then
    raise exception '메시지 내용이 비어 있습니다' using errcode = '22023';
  end if;
  if char_length(v_body) > 8000 then
    raise exception '메시지는 8000자까지 보낼 수 있습니다 (지금 %자)', char_length(v_body) using errcode = '22001';
  end if;
  if v_thread is not null and v_thread !~ '^[0-9a-f-]{36}$' then
    raise exception '대화 방 id 가 올바르지 않습니다' using errcode = '22023';
  end if;
  -- 보내는 이 PC 도 내 데스크여야 한다(알린 적이 있어야 답이 이 PC 로 돌아온다)
  select * into v_from from public.desk_agent_peer where resource_id = v_id and device = p_device;
  if v_from.device is null then
    raise exception '이 PC 가 아직 연결되지 않았습니다 — 에이전트 터미널의 «내 PC» 연결을 켜 주세요' using errcode = 'P0002';
  end if;
  select * into v_peer from public.desk_agent_peer where resource_id = v_id and device = p_to_device;
  if v_peer.device is null or v_peer.seen_at < now() - interval '30 seconds' then
    raise exception '그 PC 가 지금 연결되어 있지 않습니다 — 그 PC 의 데스크에서 에이전트 터미널을 열어 두어야 합니다'
      using errcode = 'P0002';
  end if;
  if not exists (select 1 from jsonb_array_elements(v_peer.agents) a where a->>'name' = p_to_agent) then
    raise exception '그 PC 에 그 이름의 에이전트가 열려 있지 않습니다' using errcode = 'P0002';
  end if;
  if v_thread is not null and not exists (select 1 from jsonb_array_elements(v_peer.agents) a
                                          where a->>'name' = p_to_agent and a->>'thread' = v_thread) then
    raise exception '그 대화는 끝났습니다 — 같은 이름의 에이전트가 새 대화로 열려 있으면 그 방에서 보내 주세요'
      using errcode = 'P0002';
  end if;
  if (select count(*) from public.desk_agent_message
      where sender_resource_id = v_id and created_at > now() - interval '1 hour') >= 120 then
    raise exception '한 시간에 120건까지 보낼 수 있습니다. 잠시 뒤에 다시 보내 주세요' using errcode = '54000';
  end if;

  insert into public.desk_agent_message (sender_resource_id, sender_device, sender_label, sender_agent,
                                         recipient_resource_id, recipient_device, recipient_agent, body, thread)
  values (v_id, p_device, v_from.label, 'desk', v_id, p_to_device, p_to_agent, v_body, v_thread)
  returning id into v_new;
  return jsonb_build_object('id', v_new, 'label', v_peer.label, 'agent', p_to_agent, 'thread', v_thread);
end;
$_$;


ALTER FUNCTION "public"."desk_agent_own_send"("p_device" "text", "p_to_device" "text", "p_to_agent" "text", "p_body" "text", "p_thread" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_phone_overview"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
begin
  return jsonb_build_object(
    'me', v_me->>'label',
    'pcs', coalesce((
      select jsonb_agg(jsonb_build_object('device', p.device, 'label', p.label, 'seen_at', p.seen_at,
                                          'online', p.seen_at > now() - interval '30 seconds', 'agents', p.agents)
                       order by p.seen_at desc)
      from public.desk_agent_peer p
      where p.resource_id = v_id and p.seen_at > now() - interval '1 day'), '[]'::jsonb),
    'messages', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', m.id, 'body', m.body, 'created_at', m.created_at, 'status', m.status, 'thread', m.thread,
               'kind', case when m.sender_device like 'cron:%' then 'cron' else 'phone' end,
               'title', case when m.sender_device like 'cron:%' then m.sender_label end,
               'note', case when m.sender_device like 'cron:%' then null else m.note end,
               'result_status', case when m.sender_device like 'cron:%' then split_part(m.note, ' ', 1) end,
               'late', (m.sender_device like 'cron:%' and m.note like '% late'),
               'to_device', m.recipient_device,
               'to_label', coalesce(p.label, (select a.sender_label from public.desk_agent_message a
                                              where a.reply_to = m.id and a.recipient_resource_id = v_id
                                              order by a.created_at limit 1), 'PC'),
               'to_agent', m.recipient_agent,
               'replies', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'body', a.body, 'created_at', a.created_at,
                                                                         'agent', a.sender_agent, 'label', a.sender_label)
                                                      order by a.created_at)
                                    from public.desk_agent_message a
                                    where a.reply_to = m.id and a.recipient_resource_id = v_id), '[]'::jsonb))
             order by m.created_at desc)
      from (select * from public.desk_agent_message
            where sender_resource_id = v_id and recipient_resource_id = v_id
              and (sender_device ~ '^phone:' or sender_device ~ '^cron:')
            order by created_at desc limit 300) m
      left join public.desk_agent_peer p on p.resource_id = v_id and p.device = m.recipient_device), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."desk_agent_phone_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_phone_send"("p_phone" "text", "p_to_device" "text", "p_to_agent" "text", "p_body" "text", "p_thread" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
  v_peer public.desk_agent_peer;
  v_body text := btrim(coalesce(p_body, ''));
  v_thread text := nullif(btrim(coalesce(p_thread, '')), '');
  v_new uuid;
begin
  perform public.desk_agent_check_device(p_phone);
  perform public.desk_agent_check_device(p_to_device);
  if v_body = '' then
    raise exception '메시지 내용이 비어 있습니다' using errcode = '22023';
  end if;
  if char_length(v_body) > 8000 then
    raise exception '메시지는 8000자까지 보낼 수 있습니다 (지금 %자)', char_length(v_body) using errcode = '22001';
  end if;
  if v_thread is not null and v_thread !~ '^[0-9a-f-]{36}$' then
    raise exception '대화 방 id 가 올바르지 않습니다' using errcode = '22023';
  end if;
  select * into v_peer from public.desk_agent_peer where resource_id = v_id and device = p_to_device;
  if v_peer.device is null or v_peer.seen_at < now() - interval '30 seconds' then
    raise exception '그 PC 가 지금 연결되어 있지 않습니다 — 데스크의 에이전트 터미널 위쪽 «휴대폰» 스위치를 켜 두어야 합니다'
      using errcode = 'P0002';
  end if;
  if not exists (select 1 from jsonb_array_elements(v_peer.agents) a where a->>'name' = p_to_agent) then
    raise exception '그 PC 에 그 이름의 에이전트가 열려 있지 않습니다' using errcode = 'P0002';
  end if;
  -- 방을 주었으면 그 방이 지금 열려 있어야 한다 — 이름이 같아도 다른 대화(새로 연 칸·/clear 뒤)에는 보내지 않는다
  if v_thread is not null and not exists (select 1 from jsonb_array_elements(v_peer.agents) a
                                          where a->>'name' = p_to_agent and a->>'thread' = v_thread) then
    raise exception '그 대화는 끝났습니다 — 같은 이름의 에이전트가 새 대화로 열려 있으면 그 방에서 보내 주세요'
      using errcode = 'P0002';
  end if;
  if (select count(*) from public.desk_agent_message
      where sender_resource_id = v_id and created_at > now() - interval '1 hour') >= 120 then
    raise exception '한 시간에 120건까지 보낼 수 있습니다. 잠시 뒤에 다시 보내 주세요' using errcode = '54000';
  end if;

  insert into public.desk_agent_message (sender_resource_id, sender_device, sender_label, sender_agent,
                                         recipient_resource_id, recipient_device, recipient_agent, body, thread)
  values (v_id, 'phone:' || p_phone, '휴대폰', 'phone', v_id, p_to_device, p_to_agent, v_body, v_thread)
  returning id into v_new;
  return jsonb_build_object('id', v_new, 'label', v_peer.label, 'agent', p_to_agent, 'thread', v_thread);
end;
$_$;


ALTER FUNCTION "public"."desk_agent_phone_send"("p_phone" "text", "p_to_device" "text", "p_to_agent" "text", "p_body" "text", "p_thread" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_reply"("p_device" "text", "p_agent" "text", "p_message" "uuid", "p_body" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
  v_label text;
  v_original public.desk_agent_message;
  v_body text := btrim(coalesce(p_body, ''));
  v_new uuid;
begin
  perform public.desk_agent_check_device(p_device);
  if coalesce(p_agent, '') !~ '^[A-Za-z0-9._-]{1,40}$' then
    raise exception '답하는 에이전트 이름이 올바르지 않습니다' using errcode = '22023';
  end if;
  select * into v_original from public.desk_agent_message
   where id = p_message and recipient_resource_id = v_id and recipient_device = p_device;
  if v_original.id is null then
    raise exception '이 PC 로 온 메시지가 아닙니다' using errcode = 'P0002';
  end if;
  if v_original.status <> 'delivered' then
    raise exception '받아 들인 메시지에만 답할 수 있습니다 (지금 %)', v_original.status using errcode = '22023';
  end if;
  if v_body = '' then
    raise exception '메시지 내용이 비어 있습니다' using errcode = '22023';
  end if;
  if char_length(v_body) > 8000 then
    raise exception '메시지는 8000자까지 보낼 수 있습니다 (지금 %자)', char_length(v_body) using errcode = '22001';
  end if;
  if (select count(*) from public.desk_agent_message
      where sender_resource_id = v_id and created_at > now() - interval '1 hour') >= 120 then
    raise exception '한 시간에 120건까지 보낼 수 있습니다. 잠시 뒤에 다시 보내 주세요' using errcode = '54000';
  end if;
  select label into v_label from public.desk_agent_peer where resource_id = v_id and device = p_device;

  insert into public.desk_agent_message (sender_resource_id, sender_device, sender_label, sender_agent,
                                         recipient_resource_id, recipient_device, recipient_agent, body, reply_to)
  values (v_id, p_device, coalesce(v_label, 'PC'), p_agent, v_original.sender_resource_id, v_original.sender_device,
          v_original.sender_agent, v_body, v_original.id)
  returning id into v_new;
  return jsonb_build_object('id', v_new, 'to', (select name from public.resource where id = v_original.sender_resource_id),
                            'label', v_original.sender_label, 'agent', v_original.sender_agent);
end;
$_$;


ALTER FUNCTION "public"."desk_agent_reply"("p_device" "text", "p_agent" "text", "p_message" "uuid", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_send"("p_device" "text", "p_agent" "text", "p_to_resource" "uuid", "p_to_device" "text", "p_to_agent" "text", "p_body" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
  v_mine public.desk_agent_peer;
  v_peer public.desk_agent_peer;
  v_body text := btrim(coalesce(p_body, ''));
  v_new uuid;
begin
  perform public.desk_agent_check_device(p_device);
  perform public.desk_agent_check_device(p_to_device);
  select * into v_mine from public.desk_agent_peer where resource_id = v_id and device = p_device;
  if v_mine.device is null or v_mine.seen_at < now() - interval '1 minute' then
    raise exception '이 PC 가 아직 연결되지 않았습니다. 잠시 뒤 다시 보내 주세요' using errcode = '22023';
  end if;
  if coalesce(p_agent, '') !~ '^[A-Za-z0-9._-]{1,40}$' then
    raise exception '보내는 에이전트 이름이 올바르지 않습니다' using errcode = '22023';
  end if;
  if p_to_resource = v_id and p_to_device = p_device then
    raise exception '같은 PC 의 에이전트에게는 데스크 안 중계(/send)로 보내세요' using errcode = '22023';
  end if;
  if v_body = '' then
    raise exception '메시지 내용이 비어 있습니다' using errcode = '22023';
  end if;
  if char_length(v_body) > 8000 then
    raise exception '메시지는 8000자까지 보낼 수 있습니다 (지금 %자)', char_length(v_body) using errcode = '22001';
  end if;
  select * into v_peer from public.desk_agent_peer where resource_id = p_to_resource and device = p_to_device;
  if v_peer.device is null or v_peer.seen_at < now() - interval '30 seconds' then
    raise exception '받는 PC 가 지금 연결되어 있지 않습니다' using errcode = 'P0002';
  end if;
  if not v_peer.cross_pc then
    raise exception '받는 PC 가 «다른 PC» 메시지를 받지 않습니다' using errcode = 'P0002';
  end if;
  if not exists (select 1 from jsonb_array_elements(v_peer.agents) a where a->>'name' = p_to_agent) then
    raise exception '받는 PC 에 그 이름의 에이전트가 열려 있지 않습니다' using errcode = 'P0002';
  end if;
  if (select count(*) from public.desk_agent_message
      where sender_resource_id = v_id and created_at > now() - interval '1 hour') >= 120 then
    raise exception '한 시간에 120건까지 보낼 수 있습니다. 잠시 뒤에 다시 보내 주세요' using errcode = '54000';
  end if;

  insert into public.desk_agent_message (sender_resource_id, sender_device, sender_label, sender_agent,
                                         recipient_resource_id, recipient_device, recipient_agent, body)
  values (v_id, p_device, v_mine.label, p_agent, p_to_resource, p_to_device, p_to_agent, v_body)
  returning id into v_new;
  return jsonb_build_object('id', v_new, 'to', (select name from public.resource where id = p_to_resource),
                            'label', v_peer.label, 'agent', p_to_agent);
end;
$_$;


ALTER FUNCTION "public"."desk_agent_send"("p_device" "text", "p_agent" "text", "p_to_resource" "uuid", "p_to_device" "text", "p_to_agent" "text", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_agent_status"("p_device" "text", "p_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_agent_me();
  v_id uuid := (v_me->>'resource_id')::uuid;
begin
  perform public.desk_agent_check_device(p_device);
  if p_ids is null or cardinality(p_ids) > 50 then
    raise exception '한 번에 50건까지 볼 수 있습니다' using errcode = '22023';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', m.id, 'status', m.status, 'note', m.note, 'done_at', m.done_at,
             'replies', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'status', a.status, 'created_at', a.created_at)
                                                   order by a.created_at)
                                  from public.desk_agent_message a where a.reply_to = m.id), '[]'::jsonb)))
    from public.desk_agent_message m
    where m.id = any(p_ids) and m.sender_resource_id = v_id and m.sender_device = p_device), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."desk_agent_status"("p_device" "text", "p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_message_decide"("p_student_resource_id" "uuid", "p_approve" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_message_who(auth.uid());
  v_request uuid;
  v_status text := case when p_approve then 'active' else 'declined' end;
begin
  if v_me is null or v_me->>'role' <> 'teacher' then
    raise exception '선생님만 허락하거나 거절할 수 있습니다' using errcode = '42501';
  end if;
  if p_approve is null then
    raise exception '허락 또는 거절을 골라 주세요' using errcode = '22023';
  end if;
  update public.desk_message_session
     set status = v_status, decided_at = now()
   where student_resource_id = p_student_resource_id and teacher_resource_id = (v_me->>'resource_id')::uuid
     and status = 'pending'
  returning request_notification_id into v_request;
  if not found then
    raise exception '기다리는 요청이 없습니다' using errcode = 'P0002';
  end if;
  update public.notification_events set is_read = true where id = v_request;
  perform public.desk_message_session_notice(v_me, p_student_resource_id,
    case when p_approve then 'approved' else 'declined' end,
    case when p_approve then '메시지 요청을 허락했습니다. 이제 메시지를 보낼 수 있습니다.'
         else '메시지 요청을 거절했습니다.' end);
  return jsonb_build_object('status', v_status);
end;
$$;


ALTER FUNCTION "public"."desk_message_decide"("p_student_resource_id" "uuid", "p_approve" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_message_directory"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_message_who(auth.uid());
  v_people jsonb;
begin
  if v_me is null then
    raise exception '학생 또는 선생님으로 연결된 계정만 메시지를 보낼 수 있습니다' using errcode = '42501';
  end if;
  if v_me->>'role' = 'student' then
    select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name) order by r.name), '[]'::jsonb)
      into v_people
    from public.resource r
    where r.type = 'teacher' and coalesce(r.status, 'active') = 'active';
  else
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', r.id, 'name', r.name, 'grade', r.meta->>'grade', 'class', r.meta->>'class',
             'number', r.meta->>'number')
           order by (r.meta->>'grade'), lpad(coalesce(r.meta->>'class', ''), 3, '0'),
                    lpad(coalesce(r.meta->>'number', ''), 3, '0'), r.name), '[]'::jsonb)
      into v_people
    from public.resource r
    where r.type = 'student' and coalesce(r.status, 'active') = 'active'
      and coalesce(r.meta->>'test_account', '') <> 'true';
  end if;
  return jsonb_build_object('role', v_me->>'role', 'me', v_me->>'label', 'people', v_people);
end;
$$;


ALTER FUNCTION "public"."desk_message_directory"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_message_end_session"("p_student_resource_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_message_who(auth.uid());
begin
  if v_me is null or v_me->>'role' <> 'teacher' then
    raise exception '선생님만 대화를 종료할 수 있습니다' using errcode = '42501';
  end if;
  update public.desk_message_session
     set status = 'ended', decided_at = now()
   where student_resource_id = p_student_resource_id and teacher_resource_id = (v_me->>'resource_id')::uuid
     and status = 'active';
  if not found then
    raise exception '진행 중인 대화가 아닙니다' using errcode = 'P0002';
  end if;
  perform public.desk_message_session_notice(v_me, p_student_resource_id, 'ended',
    '대화를 종료했습니다. 다시 메시지를 보내려면 허락을 요청해 주세요.');
  return jsonb_build_object('status', 'ended');
end;
$$;


ALTER FUNCTION "public"."desk_message_end_session"("p_student_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_message_image"("p_image_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_message_who(auth.uid());
  v_row public.desk_message_images%rowtype;
begin
  if v_me is null or p_image_id is null then
    return null;
  end if;
  select * into v_row from public.desk_message_images i where i.id = p_image_id;
  if v_row.id is null then
    return null;
  end if;
  if v_row.sender_resource_id::text <> v_me->>'resource_id'
     and not public.owns_notification_resource(v_row.recipient_resource_id) then
    return null;
  end if;
  return jsonb_build_object('id', v_row.id, 'mime', v_row.mime, 'width', v_row.width, 'height', v_row.height,
                            'created_at', v_row.created_at, 'data', encode(v_row.data, 'base64'));
end;
$$;


ALTER FUNCTION "public"."desk_message_image"("p_image_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_message_request"("p_teacher_resource_id" "uuid", "p_body" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_message_who(auth.uid());
  v_body text := btrim(coalesce(p_body, ''));
  v_teacher public.resource%rowtype;
  v_sent int;
  v_status text;
  v_new_id uuid;
  v_linked boolean;
begin
  if v_me is null or v_me->>'role' <> 'student' then
    raise exception '학생만 메시지 허락을 요청할 수 있습니다' using errcode = '42501';
  end if;
  if v_body = '' then
    raise exception '용건을 써 주세요' using errcode = '22023';
  end if;
  if char_length(v_body) > 1000 then
    raise exception '용건은 1000자까지 쓸 수 있습니다 (지금 %자)', char_length(v_body) using errcode = '22001';
  end if;
  select * into v_teacher from public.resource r
  where r.id = p_teacher_resource_id and r.type = 'teacher' and coalesce(r.status, 'active') = 'active';
  if v_teacher.id is null then
    raise exception '받는 사람을 찾을 수 없습니다' using errcode = 'P0002';
  end if;

  select count(*) into v_sent
  from public.notification_events n
  where n.type = 'desk_message' and n.created_at > now() - interval '1 hour'
    and n.meta->>'sender_resource_id' = v_me->>'resource_id';
  if v_sent >= 30 then
    raise exception '한 시간에 30건까지 보낼 수 있습니다. 잠시 뒤에 다시 보내 주세요' using errcode = '54000';
  end if;

  -- 동시에 눌러도 한 건만 — 이미 대기·진행 중이면 행이 바뀌지 않는다
  insert into public.desk_message_session (student_resource_id, teacher_resource_id, status, requested_at, decided_at)
  values ((v_me->>'resource_id')::uuid, v_teacher.id, 'pending', now(), null)
  on conflict (student_resource_id, teacher_resource_id)
  do update set status = 'pending', requested_at = now(), decided_at = null
    where public.desk_message_session.status in ('declined', 'ended')
  returning status into v_status;
  if v_status is null then
    select s.status into v_status from public.desk_message_session s
    where s.student_resource_id = (v_me->>'resource_id')::uuid and s.teacher_resource_id = v_teacher.id;
    raise exception '%', case when v_status = 'active' then '이미 대화 중인 선생님입니다'
                              else '이미 허락을 요청했습니다. 선생님의 답을 기다려 주세요' end
      using errcode = '22023';
  end if;

  insert into public.notification_events (resource_id, type, title, message, meta, priority)
  values (v_teacher.id, 'desk_message', '[메시지 요청] ' || (v_me->>'label'), v_body,
          jsonb_build_object('source', 'spacekijun_desk', 'kind', 'session_request',
                             'sender_resource_id', v_me->>'resource_id', 'sender_name', v_me->>'name',
                             'sender_role', v_me->>'role', 'sender_label', v_me->>'label'), 'medium')
  returning id into v_new_id;

  update public.desk_message_session set request_notification_id = v_new_id
  where student_resource_id = (v_me->>'resource_id')::uuid and teacher_resource_id = v_teacher.id;

  select exists (select 1 from public.user_resource ur where ur.resource_id = v_teacher.id) into v_linked;
  return jsonb_build_object('notification_id', v_new_id, 'recipient_name', v_teacher.name, 'recipient_linked', v_linked);
end;
$$;


ALTER FUNCTION "public"."desk_message_request"("p_teacher_resource_id" "uuid", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_message_sent"("p_limit" integer DEFAULT 300) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_message_who(auth.uid());
  v_rows jsonb;
begin
  if v_me is null then
    raise exception '학생 또는 선생님으로 연결된 계정만 메시지를 볼 수 있습니다' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'to', s.resource_id, 'body', s.message, 'time', s.created_at, 'read', s.is_read,
           'kind', s.meta->>'kind',
           'images', coalesce(s.meta->'images', '[]'::jsonb), 'photo_only', coalesce((s.meta->>'photo_only')::boolean, false),
           'to_label', case
             when r.type = 'student' and coalesce(r.meta->>'grade', '') <> '' and coalesce(r.meta->>'class', '') <> ''
               then format('%s학년 %s반 %s', r.meta->>'grade', r.meta->>'class',
                           case when coalesce(r.meta->>'number', '') <> '' then (r.meta->>'number') || '번 ' else '' end)
                    || r.name
             when r.type = 'student' then r.name
             when r.name is not null then r.name || ' 선생님'
             else '' end)
         order by s.created_at), '[]'::jsonb)
    into v_rows
  from (select n.id, n.resource_id, n.message, n.created_at, n.is_read, n.meta
        from public.notification_events n
        where n.type = 'desk_message'
          and n.meta->>'sender_resource_id' = v_me->>'resource_id'
        order by n.created_at desc
        limit least(greatest(coalesce(p_limit, 300), 1), 500)) s
  left join public.resource r on r.id = s.resource_id;
  return v_rows;
end;
$$;


ALTER FUNCTION "public"."desk_message_sent"("p_limit" integer) OWNER TO "postgres";


