          jsonb_build_object('source', 'spacekijun_desk', 'kind', 'session_event', 'event', p_event,
                             'sender_resource_id', p_me->>'resource_id', 'sender_name', p_me->>'name',
                             'sender_role', p_me->>'role', 'sender_label', p_me->>'label'), 'medium');
