CREATE OR REPLACE FUNCTION "public"."desk_message_sessions"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me jsonb := public.desk_message_who(auth.uid());
  v_id uuid := (v_me->>'resource_id')::uuid;
  v_rows jsonb;
begin
  if v_me is null then
    raise exception '학생 또는 선생님으로 연결된 계정만 메시지를 볼 수 있습니다' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'peer', case when v_me->>'role' = 'student' then s.teacher_resource_id else s.student_resource_id end,
           'status', s.status, 'requested_at', s.requested_at, 'decided_at', s.decided_at)), '[]'::jsonb)
    into v_rows
  from public.desk_message_session s
  where case when v_me->>'role' = 'student' then s.student_resource_id else s.teacher_resource_id end = v_id;
  return jsonb_build_object('role', v_me->>'role', 'sessions', v_rows);
end;
$$;


ALTER FUNCTION "public"."desk_message_sessions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."desk_message_who"("p_uid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_name text;
  v_meta jsonb;
  v_code text;
  v_count int;
begin
  if p_uid is null then
    return null;
  end if;

  if public.is_staff_teacher_or_admin(p_uid) then
    select r.id, r.name into v_id, v_name
    from public.user_resource ur
    join public.resource r on r.id = ur.resource_id
    where ur.user_id = p_uid and r.type in ('teacher', 'staff')
    order by (r.type = 'teacher') desc, r.name
    limit 1;
    if v_id is null then
      return null;
    end if;
    return jsonb_build_object('resource_id', v_id, 'name', v_name, 'role', 'teacher',
                              'label', v_name || ' 선생님');
  end if;

  select split_part(p.email, '@', 1) into v_code
  from public.profiles p
  where p.id = p_uid and p.role = 'student';
  if v_code is null or v_code = '' then
    return null;
  end if;
  select count(*) into v_count
  from public.resource r
  where r.type = 'student' and coalesce(r.status, 'active') = 'active' and r.meta->>'id' = v_code;
  if v_count <> 1 then
    return null;
  end if;
  select r.id, r.name, r.meta into v_id, v_name, v_meta
  from public.resource r
  where r.type = 'student' and coalesce(r.status, 'active') = 'active' and r.meta->>'id' = v_code;
  return jsonb_build_object(
    'resource_id', v_id, 'name', v_name, 'role', 'student',
    'label', case when coalesce(v_meta->>'grade', '') <> '' and coalesce(v_meta->>'class', '') <> ''
                  then format('%s학년 %s반 %s', v_meta->>'grade', v_meta->>'class',
                              case when coalesce(v_meta->>'number', '') <> '' then (v_meta->>'number') || '번 ' else '' end)
                       || v_name
                  else v_name end);
end;
$$;


ALTER FUNCTION "public"."desk_message_who"("p_uid" "uuid") OWNER TO "postgres";


