CREATE OR REPLACE FUNCTION "public"."docgen_upload_claim"("p_ticket_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_row mcp_private.docgen_upload;
begin
  update mcp_private.docgen_upload
  set claimed_at = now()
  where ticket_hash = p_ticket_hash
    and uploaded_at is null
    and expires_at > now()
    and (claimed_at is null or claimed_at < now() - interval '2 minutes')
  returning * into v_row;
  if v_row.id is null then return null; end if;

  return jsonb_build_object(
    'id', v_row.id, 'user_id', v_row.user_id, 'storage_path', v_row.storage_path, 'file_name', v_row.file_name,
    -- 하루가 지나도 생성 방식을 만들지 않은 이 사람의 올린 파일 — 함수가 저장소에서 지우고 docgen_upload_forget 으로 정리
    'abandoned', coalesce((
      select jsonb_agg(jsonb_build_object('id', u.id, 'storage_path', u.storage_path))
      from mcp_private.docgen_upload u
      where u.user_id = v_row.user_id and u.template_id is null and u.id <> v_row.id
        and u.created_at < now() - interval '1 day'), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."docgen_upload_claim"("p_ticket_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."docgen_upload_complete"("p_id" "uuid", "p_size" bigint, "p_sha" "text", "p_sections" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
begin
  if p_sha !~ '^[0-9a-f]{64}$' or p_size <= 0 or p_size > 20971520
     or jsonb_typeof(p_sections) <> 'array' or jsonb_array_length(p_sections) = 0 then
    raise exception using errcode = '22023', message = 'docgen_upload_complete: 잘못된 값';
  end if;
  update mcp_private.docgen_upload
  set uploaded_at = now(), size_bytes = p_size, content_sha256 = p_sha, sections = p_sections
  where id = p_id and uploaded_at is null and claimed_at is not null;
  if not found then
    raise exception using errcode = 'P0002', message = 'docgen_upload_complete: 집은 올리기가 없다';
  end if;
end;
$_$;


ALTER FUNCTION "public"."docgen_upload_complete"("p_id" "uuid", "p_size" bigint, "p_sha" "text", "p_sections" "jsonb") OWNER TO "postgres";


