CREATE OR REPLACE FUNCTION "public"."enter_queue"() RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
  v_user_role TEXT;
  v_max_users INT;
  v_active_count INT;
  v_user_active BOOLEAN;
  v_queue_pos INT;
  v_setting_val JSONB;
  v_waiting_room_enabled BOOLEAN;
BEGIN
  v_user_id := auth.uid();

  -- 1. Check if waiting room is enabled
  SELECT setting_value INTO v_setting_val FROM system_settings WHERE setting_key = 'waiting_room_enabled';
  
  -- Default to true if not set
  IF v_setting_val IS NULL THEN
    v_waiting_room_enabled := true;
  ELSE
    -- Handle jsonb "true"/"false" string or boolean
    v_waiting_room_enabled := (v_setting_val#>>'{}')::BOOLEAN;
  END IF;

  -- If disabled, bypass everything and return active
  IF v_waiting_room_enabled = false THEN
    RETURN json_build_object('status', 'active');
  END IF;

  -- 2. Check user role (Teachers bypass)
  SELECT role INTO v_user_role FROM profiles WHERE id = v_user_id;
  
  IF v_user_role = 'teacher' THEN
    RETURN json_build_object('status', 'active');
  END IF;

  -- 3. Cleanup stale sessions
  PERFORM cleanup_stale_sessions();

  -- 4. Get max users
  SELECT setting_value INTO v_setting_val FROM system_settings WHERE setting_key = 'max_concurrent_users';
  
  IF v_setting_val IS NULL THEN 
    v_max_users := 50; 
  ELSE
    v_max_users := (v_setting_val#>>'{}')::INT;
  END IF;

  -- 5. Check if user is already active
  SELECT EXISTS(SELECT 1 FROM active_sessions WHERE user_id = v_user_id) INTO v_user_active;
  
  IF v_user_active THEN
    UPDATE active_sessions SET last_seen = now() WHERE user_id = v_user_id;
    RETURN json_build_object('status', 'active');
  END IF;

  -- 6. Check active count
  SELECT count(*) INTO v_active_count FROM active_sessions;

  IF v_active_count < v_max_users THEN
    -- Allow entry
    INSERT INTO active_sessions (user_id) VALUES (v_user_id)
    ON CONFLICT (user_id) DO UPDATE SET last_seen = now();
    
    -- Remove from queue if exists
    DELETE FROM waiting_queue WHERE user_id = v_user_id;
    
    RETURN json_build_object('status', 'active');
  ELSE
    -- Add to queue
    INSERT INTO waiting_queue (user_id) VALUES (v_user_id)
    ON CONFLICT (user_id) DO NOTHING;
    
    -- Get position
    SELECT count(*) + 1 INTO v_queue_pos FROM waiting_queue 
    WHERE created_at <= (SELECT created_at FROM waiting_queue WHERE user_id = v_user_id);
    
    RETURN json_build_object('status', 'waiting', 'position', v_queue_pos);
  END IF;
END;
$$;


ALTER FUNCTION "public"."enter_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."exam_grade1_2026_3_dump"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
  v_n int;
BEGIN
  DROP TABLE IF EXISTS _rf;
  DROP TABLE IF EXISTS _mf;
  DROP TABLE IF EXISTS _pq;
  DROP TABLE IF EXISTS _st;

  CREATE TEMP TABLE _rf ON COMMIT DROP AS
  SELECT sim.student_code,
    CASE WHEN norm = '공통과학' THEN '통합과학'
         WHEN norm = '공통사회' THEN '통합사회' ELSE norm END AS subj,
    ((r->'subjects'->norm)->>'raw_score')::numeric AS raw_score,
    NULLIF((r->'subjects'->norm)->>'standard_score','')::numeric AS std_score,
    NULLIF((r->'subjects'->norm)->>'percentile','')::numeric AS pct,
    ((r->'subjects'->norm)->>'grade')::int AS grade
  FROM student_basic_info sbi
  JOIN student_identity_map sim ON sim.student_code = sbi.id,
       jsonb_array_elements(sbi.mock_result) r,
       LATERAL (VALUES ('국어'),('수학'),('영어'),('한국사'),('공통과학'),('공통사회')) v(norm)
  WHERE sim.current_grade = 1
    AND (r->>'academic_year')::int = 2026 AND (r->>'exam_month')::int = 3 AND (r->>'exam_grade')::int = 1
    AND (r->'subjects') ? norm
    AND ((r->'subjects'->norm)->>'raw_score') IS NOT NULL;

  CREATE TEMP TABLE _mf ON COMMIT DROP AS
  SELECT sim.student_code,
    CASE WHEN norm IN ('공통과학','과학탐구','통합과학') THEN '통합과학'
         WHEN norm IN ('공통사회','사회탐구','통합사회') THEN '통합사회' ELSE norm END AS subj,
    m->'subjects'->norm->'correct' AS correct_arr
  FROM student_basic_info sbi
  JOIN student_identity_map sim ON sim.student_code = sbi.id,
       jsonb_array_elements(sbi.mock_marking) m,
       LATERAL (VALUES ('국어'),('수학'),('영어'),('한국사'),('공통과학'),('공통사회'),('과학탐구'),('사회탐구'),('통합과학'),('통합사회')) v(norm)
  WHERE sim.current_grade = 1
    AND (m->>'academic_year')::int = 2026 AND (m->>'exam_month')::int = 3 AND (m->>'exam_grade')::int = 1
    AND (m->'subjects') ? norm
    AND (m->'subjects'->norm->'correct') IS NOT NULL;

  CREATE TEMP TABLE _pq ON COMMIT DROP AS
  SELECT r.subj, ord AS q, r.student_code, r.raw_score, r.grade,
    CASE WHEN (m.correct_arr->(ord-1))::text::boolean THEN 1 ELSE 0 END AS ci
  FROM _rf r JOIN _mf m ON m.student_code=r.student_code AND m.subj=r.subj,
    LATERAL generate_series(1, jsonb_array_length(m.correct_arr)) AS ord;

  -- student-level correct-count totals per subject (unweighted)
  CREATE TEMP TABLE _st ON COMMIT DROP AS
  SELECT subj, student_code, SUM(ci) AS count_correct FROM _pq GROUP BY subj, student_code;

  SELECT COUNT(DISTINCT student_code) INTO v_n FROM _rf;

  SELECT jsonb_build_object(
    'n_matched', v_n,
    'qstats', (
      SELECT jsonb_agg(jsonb_build_object(
        'subj',subj,'q',q,'n',n,
        'p_sch',ROUND(p_sch::numeric,4),
        'rpb',ROUND(COALESCE(rpb,0)::numeric,4),
        'p_s',ROUND(COALESCE(p_s,0)::numeric,4),
        'p_m',ROUND(COALESCE(p_m,0)::numeric,4),
        'p_h',ROUND(COALESCE(p_h,0)::numeric,4))
      ORDER BY CASE subj WHEN '국어' THEN 1 WHEN '수학' THEN 2 WHEN '영어' THEN 3 WHEN '한국사' THEN 4 WHEN '통합과학' THEN 5 ELSE 6 END, q)
      FROM (
        SELECT subj,q,COUNT(*) AS n,AVG(ci) AS p_sch,
          CORR(ci::double precision, raw_score::double precision) AS rpb,
          AVG(ci) FILTER (WHERE grade<=2) AS p_s,
          AVG(ci) FILTER (WHERE grade BETWEEN 3 AND 5) AS p_m,
          AVG(ci) FILTER (WHERE grade>=6) AS p_h
        FROM _pq GROUP BY subj,q
      ) t
    ),
    'subj_totals', (
      SELECT jsonb_agg(jsonb_build_object(
        'subj',subj,'n',n,
        'mean',ROUND(mean::numeric,4),'sd',ROUND(sd::numeric,4),
        'var',ROUND(var::numeric,4),
        'var_count', ROUND(var_count::numeric, 4),
        'skew',ROUND(COALESCE(skew,0)::numeric,4),
        'kurt',ROUND(COALESCE(kurt,0)::numeric,4),
        'max_rs',max_rs,'min_rs',min_rs,'sumpq',ROUND(sumpq::numeric,4)))
      FROM (
        SELECT r.subj, COUNT(*) AS n,
          AVG(r.raw_score) AS mean,
          STDDEV_POP(r.raw_score) AS sd,
          VAR_POP(r.raw_score) AS var,
          (SELECT VAR_POP(count_correct) FROM _st st WHERE st.subj=r.subj) AS var_count,
          (AVG(POWER(r.raw_score - m.mu, 3)) / NULLIF(POWER(STDDEV_POP(r.raw_score),3),0)) AS skew,
          (AVG(POWER(r.raw_score - m.mu, 4)) / NULLIF(POWER(STDDEV_POP(r.raw_score),4),0) - 3) AS kurt,
          MAX(r.raw_score) AS max_rs, MIN(r.raw_score) AS min_rs,
          (SELECT SUM(p_sch*(1-p_sch)) FROM (SELECT AVG(ci) AS p_sch FROM _pq pq WHERE pq.subj=r.subj GROUP BY pq.q) tt) AS sumpq
        FROM _rf r
        CROSS JOIN LATERAL (SELECT AVG(raw_score) AS mu FROM _rf r2 WHERE r2.subj=r.subj) m
        GROUP BY r.subj, m.mu
      ) z
    ),
    'grade_counts', (
      SELECT jsonb_object_agg(subj, grades) FROM (
        SELECT subj, jsonb_agg(jsonb_build_object('g',grade,'n',cnt) ORDER BY grade) AS grades
        FROM (SELECT subj, grade, COUNT(*) AS cnt FROM _rf GROUP BY subj, grade) t
        GROUP BY subj
      ) z
    ),
    'std_meta', (
      SELECT jsonb_object_agg(subj, o) FROM (
        SELECT subj, jsonb_build_object(
          'n_std', COUNT(std_score) FILTER (WHERE std_score IS NOT NULL),
          'n_pct', COUNT(pct) FILTER (WHERE pct IS NOT NULL),
          'std_mean', ROUND(AVG(std_score)::numeric,2),
          'std_min', MIN(std_score)::int, 'std_max', MAX(std_score)::int,
          'pct_mean', ROUND(AVG(pct)::numeric,2)
        ) AS o FROM _rf GROUP BY subj
      ) z
    ),
    'raw_hist', (
      SELECT jsonb_object_agg(subj, hist) FROM (
        SELECT subj, jsonb_agg(jsonb_build_array(b, c) ORDER BY b) AS hist FROM (
          SELECT subj, FLOOR(raw_score/10)*10 AS b, COUNT(*) AS c FROM _rf GROUP BY subj, FLOOR(raw_score/10)*10
        ) t GROUP BY subj
      ) z
    ),
    'std_hist', (
      SELECT jsonb_object_agg(subj, hist) FROM (
        SELECT subj, jsonb_agg(jsonb_build_array(b, c) ORDER BY b) AS hist FROM (
          SELECT subj, FLOOR(std_score/10)*10 AS b, COUNT(*) AS c
          FROM _rf WHERE std_score IS NOT NULL GROUP BY subj, FLOOR(std_score/10)*10
        ) t GROUP BY subj
      ) z
    ),
    'pct_hist', (
      SELECT jsonb_object_agg(subj, hist) FROM (
        SELECT subj, jsonb_agg(jsonb_build_array(b, c) ORDER BY b) AS hist FROM (
          SELECT subj, FLOOR(pct/10)*10 AS b, COUNT(*) AS c
          FROM _rf WHERE pct IS NOT NULL GROUP BY subj, FLOOR(pct/10)*10
        ) t GROUP BY subj
      ) z
    ),
    'cuts', (
      SELECT jsonb_object_agg(subj, arr) FROM (
        SELECT subj, jsonb_agg(jsonb_build_object('g',grade,'lo',lo::int,'hi',hi::int,'n',c) ORDER BY grade) AS arr FROM (
          SELECT subj, grade, MIN(std_score) AS lo, MAX(std_score) AS hi, COUNT(*) AS c
          FROM _rf WHERE std_score IS NOT NULL GROUP BY subj, grade
        ) t GROUP BY subj
      ) z
    )
  ) INTO result;

  RETURN result;
END; $$;


ALTER FUNCTION "public"."exam_grade1_2026_3_dump"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expand_task_audience"("p_rule" "jsonb", "p_task_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with ids as (
    select coalesce(jsonb_agg(a.value->>'id'), '[]'::jsonb) ids
    from public.task t,
         lateral jsonb_array_elements(case when jsonb_typeof(t.meta->'assignees') = 'array'
                                           then t.meta->'assignees' else '[]'::jsonb end) a(value)
    where t.id = p_task_id and coalesce(a.value->>'status', 'pending') <> 'cancelled'
  )
  select jsonb_build_object(
    'include', coalesce((select jsonb_agg(case when c.value->>'type' = 'task_assignees'
                                                then jsonb_build_object('type', 'task_assignee_ids', 'ids', (select ids from ids))
                                                else c.value end)
                         from jsonb_array_elements(case when jsonb_typeof(p_rule->'include') = 'array'
                                                        then p_rule->'include' else '[]'::jsonb end) c), '[]'::jsonb),
    'exclude', coalesce((select jsonb_agg(case when c.value->>'type' = 'task_assignees'
                                                then jsonb_build_object('type', 'task_assignee_ids', 'ids', (select ids from ids))
                                                else c.value end)
                         from jsonb_array_elements(case when jsonb_typeof(p_rule->'exclude') = 'array'
                                                        then p_rule->'exclude' else '[]'::jsonb end) c), '[]'::jsonb));
$$;


ALTER FUNCTION "public"."expand_task_audience"("p_rule" "jsonb", "p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_signature_purge"("p_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_days    int := public.signature_purge_days();
  v_req     record;
  v_purged  int := 0;
  v_expired int := 0;
begin
  for v_req in
    select r.id, r.title, r.status, r.requester_resource_id, (r.meta ? 'drive') as moved
    from public.signature_request r
    where r.id = any(p_ids) and r.purged_at is null
  loop
    if v_req.status = 'pending' then
      /*
        **미완료 종료** — `pending` 으로 두면 서명자에게 계속 "내 차례"로 뜨는데 문서가 없어
        서명할 수 없다(영원히 못 끝내는 유령 항목). 요청 글과 이미 한 서명은 그대로 남기고
        상태만 `expired` 로 바꾼다 → 화면에 "미서명"으로 드러난다.
      */
      update public.signature_request
         set purged_at = now(), signed_path = null,
             status = 'expired', decided_at = now(), updated_at = now()
       where id = v_req.id;
      v_expired := v_expired + 1;
    else
      update public.signature_request
         set purged_at = now(), signed_path = null, updated_at = now()
       where id = v_req.id;
    end if;
    v_purged := v_purged + 1;

    -- Drive 로 옮긴 건은 안전하므로 알리지 않는다. 기한 경과만 알린다.
    if not v_req.moved and v_req.requester_resource_id is not null then
      insert into public.notification_events (type, title, message, resource_id, meta)
      values (
        'signature_request',
        case when v_req.status = 'pending' then '서명 요청 만료' else '서명 문서 정리됨' end,
        case when v_req.status = 'pending'
             then format('«%s» 요청이 서명 마감일을 지나 만료됐습니다. 서명이 완료되지 않았고 문서는 정리됐습니다.', v_req.title)
             else format('«%s» 문서를 %s일이 지나 정리했습니다. Google Drive로 옮기지 않아 다시 받을 수 없습니다.',
                         v_req.title, v_days) end,
        v_req.requester_resource_id,
        jsonb_build_object('signature_request_id', v_req.id, 'link', '/signatures')
      );
    end if;
  end loop;

  return jsonb_build_object('purged', v_purged, 'expired', v_expired);
end;
$$;


ALTER FUNCTION "public"."finalize_signature_purge"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_task_action_run"("p_run_id" "uuid", "p_status" "text", "p_output_summary" "jsonb" DEFAULT '{}'::"jsonb", "p_error_summary" "text" DEFAULT NULL::"text", "p_checks" "jsonb" DEFAULT '[]'::"jsonb", "p_artifacts" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  check_item jsonb;
  artifact_item jsonb;
  previous_status text;
  affected_rows integer;
begin
  if (select auth.uid()) is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if p_status not in ('needs_review', 'failed', 'cancelled') then
    raise exception 'invalid finalization status' using errcode = '22023';
  end if;

  if jsonb_typeof(coalesce(p_output_summary, '{}'::jsonb)) <> 'object'
    or jsonb_typeof(coalesce(p_checks, '[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_artifacts, '[]'::jsonb)) <> 'array'
  then
    raise exception 'invalid output, checks, or artifacts payload' using errcode = '22023';
  end if;

  select status
  into previous_status
  from public.task_action_run
  where id = p_run_id
    and created_by = (select auth.uid())
    and status in ('created', 'running');

  if previous_status is null then
    raise exception 'run not found, inaccessible, or already finalized' using errcode = '42501';
  end if;

  perform pg_catalog.set_config(
    'app.task_action_audit_writer',
    (select auth.uid())::text,
    true
  );

  update public.task_action_run
  set
    status = p_status,
    output_summary = coalesce(p_output_summary, '{}'::jsonb),
    error_summary = nullif(btrim(p_error_summary), ''),
    completed_at = now()
  where id = p_run_id
    and created_by = (select auth.uid())
    and status = previous_status;

  get diagnostics affected_rows = row_count;
  if affected_rows <> 1 then
    raise exception 'run changed while finalizing' using errcode = '40001';
  end if;

  for check_item in
    select value
    from jsonb_array_elements(coalesce(p_checks, '[]'::jsonb))
  loop
    if coalesce(check_item->>'status', '') not in ('pass', 'warn', 'fail') then
      raise exception 'invalid check status' using errcode = '22023';
    end if;

    insert into public.task_action_check (
      run_id,
      created_by,
      check_key,
      label,
      status,
      message,
      evidence
    )
    values (
      p_run_id,
      (select auth.uid()),
      check_item->>'key',
      check_item->>'label',
      check_item->>'status',
      nullif(btrim(check_item->>'message'), ''),
      coalesce(check_item->'evidence', '{}'::jsonb)
    );
  end loop;

  for artifact_item in
    select value
    from jsonb_array_elements(coalesce(p_artifacts, '[]'::jsonb))
  loop
    if coalesce(artifact_item->>'type', '') not in (
      'record_set',
      'file',
      'link',
      'summary'
    ) then
      raise exception 'invalid artifact type' using errcode = '22023';
    end if;

    if jsonb_typeof(coalesce(artifact_item->'locator', '{}'::jsonb)) <> 'object'
      or jsonb_typeof(coalesce(artifact_item->'metadata', '{}'::jsonb)) <> 'object'
    then
      raise exception 'artifact locator and metadata must be objects' using errcode = '22023';
    end if;

    insert into public.task_action_artifact (
      run_id,
      created_by,
      artifact_key,
      artifact_type,
      label,
      locator,
      mime_type,
      size_bytes,
      content_sha256,
      metadata
    )
    values (
      p_run_id,
      (select auth.uid()),
      artifact_item->>'key',
      artifact_item->>'type',
      artifact_item->>'label',
      coalesce(artifact_item->'locator', '{}'::jsonb),
      nullif(btrim(artifact_item->>'mimeType'), ''),
      nullif(artifact_item->>'sizeBytes', '')::bigint,
      nullif(btrim(artifact_item->>'contentSha256'), ''),
      coalesce(artifact_item->'metadata', '{}'::jsonb)
    );
  end loop;

  insert into public.task_action_run_log (
    run_id,
    created_by,
    log_type,
    from_status,
    to_status,
    payload
  )
  values (
    p_run_id,
    (select auth.uid()),
    'finalized',
    previous_status,
    p_status,
    jsonb_build_object(
      'checkCount', jsonb_array_length(coalesce(p_checks, '[]'::jsonb)),
      'artifactCount', jsonb_array_length(coalesce(p_artifacts, '[]'::jsonb)),
      'hasError', nullif(btrim(p_error_summary), '') is not null
    )
  );
end;
$$;


ALTER FUNCTION "public"."finalize_task_action_run"("p_run_id" "uuid", "p_status" "text", "p_output_summary" "jsonb", "p_error_summary" "text", "p_checks" "jsonb", "p_artifacts" "jsonb") OWNER TO "postgres";


