CREATE OR REPLACE FUNCTION "public"."find_similar_kg_entities"("p_student_id" "text", "p_query_embedding" "extensions"."vector", "p_match_threshold" double precision DEFAULT 0.92, "p_match_count" integer DEFAULT 5) RETURNS TABLE("entity_id" "text", "label" "text", "type" "text", "similarity" double precision)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.inquiry_design_can_access_student(p_student_id) THEN
    RAISE EXCEPTION 'not allowed to search KG entities for student %', p_student_id;
  END IF;

  RETURN QUERY
  SELECT e.entity_id,
         e.label,
         e.type,
         (1 - (e.embedding <=> p_query_embedding))::double precision AS similarity
  FROM public.student_kg_entities e
  WHERE e.student_id = p_student_id
    AND e.embedding IS NOT NULL
    AND (1 - (e.embedding <=> p_query_embedding)) >= p_match_threshold
  ORDER BY e.embedding <=> p_query_embedding
  LIMIT LEAST(GREATEST(COALESCE(p_match_count, 5), 1), 20);
END;
$$;


ALTER FUNCTION "public"."find_similar_kg_entities"("p_student_id" "text", "p_query_embedding" "extensions"."vector", "p_match_threshold" double precision, "p_match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_populate_kg_entities"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_entity JSONB;
  v_entity_id TEXT;
  v_label TEXT;
  v_type TEXT;
  v_properties JSONB;
  v_known_keys TEXT[] := ARRAY['id', 'name', 'type'];
BEGIN
  DELETE FROM student_kg_entities
    WHERE kg_version_id = NEW.id;

  IF NEW.kg_json IS NULL
     OR NEW.kg_json->'entities' IS NULL
     OR jsonb_typeof(NEW.kg_json->'entities') != 'array'
  THEN
    RETURN NEW;
  END IF;

  FOR v_entity IN SELECT jsonb_array_elements(NEW.kg_json->'entities')
  LOOP
    v_entity_id := v_entity->>'id';
    v_label     := COALESCE(v_entity->>'name', v_entity->>'label');
    v_type      := v_entity->>'type';

    IF v_entity_id IS NULL OR v_label IS NULL THEN
      CONTINUE;
    END IF;

    SELECT COALESCE(
      jsonb_object_agg(key, value),
      '{}'::jsonb
    )
    INTO v_properties
    FROM jsonb_each(v_entity)
    WHERE key != ALL(v_known_keys);

    INSERT INTO student_kg_entities (
      kg_version_id, student_id, entity_id, label, type, properties
    ) VALUES (
      NEW.id, NEW.student_id, v_entity_id, v_label, v_type, v_properties
    );
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_populate_kg_entities"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_populate_kg_entities"() IS 'Trigger function: extracts entities from kg_json. Reads "name" field (skill format) with "label" fallback.';



CREATE OR REPLACE FUNCTION "public"."fn_populate_kg_relations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_relation JSONB;
  v_source TEXT;
  v_target TEXT;
  v_label TEXT;
  v_properties JSONB;
  v_known_keys TEXT[] := ARRAY['subject', 'predicate', 'object', 'source', 'target', 'label'];
  v_arr JSONB;
BEGIN
  DELETE FROM student_kg_relations
    WHERE kg_version_id = NEW.id;

  -- Try 'triples' first (skill format), fall back to 'relations' (legacy format)
  IF NEW.kg_json->'triples' IS NOT NULL
     AND jsonb_typeof(NEW.kg_json->'triples') = 'array'
  THEN
    v_arr := NEW.kg_json->'triples';
  ELSIF NEW.kg_json->'relations' IS NOT NULL
     AND jsonb_typeof(NEW.kg_json->'relations') = 'array'
  THEN
    v_arr := NEW.kg_json->'relations';
  ELSE
    RETURN NEW;
  END IF;

  FOR v_relation IN SELECT jsonb_array_elements(v_arr)
  LOOP
    v_source := COALESCE(v_relation->>'subject', v_relation->>'source');
    v_target := COALESCE(v_relation->>'object', v_relation->>'target');
    v_label  := COALESCE(v_relation->>'predicate', v_relation->>'label');

    IF v_source = 'Student' THEN
      v_source := 'student';
    END IF;

    IF v_source IS NULL OR v_target IS NULL OR v_label IS NULL THEN
      CONTINUE;
    END IF;

    SELECT COALESCE(
      jsonb_object_agg(key, value),
      '{}'::jsonb
    )
    INTO v_properties
    FROM jsonb_each(v_relation)
    WHERE key != ALL(v_known_keys);

    INSERT INTO student_kg_relations (
      kg_version_id, student_id, source_entity_id, target_entity_id, relation_type, properties
    ) VALUES (
      NEW.id, NEW.student_id, v_source, v_target, v_label, v_properties
    );
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_populate_kg_relations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_populate_kg_relations"() IS 'Trigger function: extracts relations from kg_json. Reads "triples" with subject/predicate/object (skill format), falls back to "relations" with source/target/label (legacy).';



CREATE OR REPLACE FUNCTION "public"."follow_task_assignees_in_requests"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_action uuid;
begin
  if public.jsonb_person_ids(new.meta->'assignees') is not distinct from public.jsonb_person_ids(old.meta->'assignees') then
    return new;
  end if;
  for v_action in
    select q.action_id
    from public.collect_request q join public.task_action a on a.id = q.action_id and a.archived_at is null
    where q.task_id = new.id and q.status = 'open'
      and public.audience_uses_task_assignees(public.request_cfg_of(a.action_type, a.config)->'audience')
  loop
    perform public._sync_action_targets(v_action, true);
  end loop;
  return new;
end;
$$;


