CREATE OR REPLACE FUNCTION "public"."get_admin_dashboard_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_since timestamptz := now() - interval '30 days';
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_started timestamptz := clock_timestamp();
  v_snap jsonb;
  v_users jsonb;
  v_resources jsonb;
  v_system jsonb;
  v_login jsonb;
  v_academy jsonb;
  v_players jsonb;
  v_tama jsonb;
  v_policy text;
begin
  if not public.is_admin() then
    raise exception '관리자만 조회할 수 있습니다.' using errcode = '42501';
  end if;

  -- ──────────────────────────────────── 기능별 자료 = 스냅샷 (머리말 참고)
  select to_jsonb(s) into v_snap from public.admin_dashboard_snapshot s where s.id = 1;
  if v_snap is null then
    -- 배포 직후 한 번만. 이후로는 크론·[지금 다시 세기]가 채운다.
    v_snap := public.admin_dashboard_snapshot_save('bootstrap', 3500, 20);
  end if;

  select jsonb_build_object(
    'total',           count(*),
    'student',         count(*) filter (where role = 'student'),
    'teacher',         count(*) filter (where role = 'teacher'),
    'staff',           count(*) filter (where role = 'staff'),
    'admin',           count(*) filter (where role = 'admin'),
    'new_30d',         count(*) filter (where created_at >= v_since),
    'active_7d',       count(*) filter (where last_login >= now() - interval '7 days'),
    'active_30d',      count(*) filter (where last_login >= v_since),
    'never_logged_in', count(*) filter (where last_login is null)
  ) into v_users
  from public.profiles;

  select version into v_policy
  from public.privacy_policy_versions
  where is_active
  order by effective_date desc
  limit 1;

  v_users := v_users || jsonb_build_object(
    'links', (select count(*) from public.user_resource),
    'unlinked_faculty', (
      select count(*) from public.profiles p
      where p.role in ('teacher', 'staff', 'admin')
        and not exists (select 1 from public.user_resource ur where ur.user_id = p.id)
    ),
    'privacy_policy_version', v_policy,
    'privacy_consented', case when v_policy is null then null else (
      select count(distinct c.user_id)
      from public.user_privacy_consents c
      where c.policy_version = v_policy
    ) end
  );

  select jsonb_build_object(
    'total',             count(*),
    'student_active',    count(*) filter (where type = 'student' and status = 'active'),
    'student_graduated', count(*) filter (where type = 'student' and status = 'graduated'),
    'student_left',      count(*) filter (where type = 'student' and status in ('transferred', 'withdrawn')),
    'teacher',           count(*) filter (where type = 'teacher' and status = 'active'),
    'staff',             count(*) filter (where type = 'staff'   and status = 'active'),
    'external_menu',     count(*) filter (where type in ('iframe', 'link'))
  ) into v_resources
  from public.resource;

  select jsonb_agg(jsonb_build_object('date', g.d::date, 'count', coalesce(s.c, 0)) order by g.d)
    into v_login
  from generate_series(v_today - 13, v_today, interval '1 day') g(d)
  left join (
    select (last_login at time zone 'Asia/Seoul')::date as d, count(*) as c
    from public.profiles
    where last_login >= (v_today - 13)::timestamp at time zone 'Asia/Seoul'
    group by 1
  ) s on s.d = g.d::date;

  -- ────────────────────────────────────────────── 별빛 탐구 아카데미 챕터 진행
  -- 20260914203658 의 경고 셋을 함께 볼 것
  -- (kidon 레거시 · completed_at 이 완료의 정본 · final_step 은 진행률 전용).
  with declared(ord, key, final_step) as (values
    (10, 'first_star',        16),
    (20, 'library_questions', 18),
    (30, 'dorm_first_plan',   36),
    (40, 'post_first_letter', 30),
    (45, 'postlude',           9),
    (50, 'sky_first_light',   29)
  ),
  progress as (
    select c.chapter as key, c.user_id, c.step,
           c.completed_at is not null as done, c.updated_at
    from public.academy_chapters c
    union all
    select 'postlude', c.user_id, c.postlude_step,
           c.postlude_completed_at is not null, c.updated_at
    from public.academy_chapters c
    where c.chapter = 'post_first_letter' and c.completed_at is not null
  ),
  sided as (
    select p.key, p.step, p.done, p.updated_at,
           coalesce(pr.role, '') = 'student' as is_student
    from progress p
    left join public.profiles pr on pr.id = p.user_id
  ),
  agg as (
    select key,
           count(*) filter (where is_student)              as student_total,
           count(*) filter (where is_student and done)     as student_done,
           coalesce(sum(step) filter (where is_student and not done), 0) as student_progress_sum,
           count(*) filter (where not is_student)          as faculty_total,
           count(*) filter (where not is_student and done) as faculty_done,
           max(step)                                       as step_max,
           max(updated_at)                                 as last_activity
    from sided
    group by key
  )
  select jsonb_agg(
           jsonb_build_object(
             'key',                  coalesce(d.key, a.key),
             'final_step',           d.final_step,
             'student_total',        coalesce(a.student_total, 0),
             'student_done',         coalesce(a.student_done, 0),
             'student_progress_sum', coalesce(a.student_progress_sum, 0),
             'faculty_total',        coalesce(a.faculty_total, 0),
             'faculty_done',         coalesce(a.faculty_done, 0),
             'step_max',             a.step_max,
             'last_activity',        a.last_activity
           )
           order by coalesce(d.ord, 99), coalesce(d.key, a.key)
         )
    into v_academy
  from declared d
  full join agg a on a.key = d.key;

  -- ───────────────────────────────────────── 참여자 명단(누가 어디까지 갔나)
  -- 장 순서 선언은 위 블록과 **같은 값**이어야 한다(20260915093000 머리말).
  with declared(ord, key, final_step) as (values
    (10, 'first_star',        16),
    (20, 'library_questions', 18),
    (30, 'dorm_first_plan',   36),
    (40, 'post_first_letter', 30),
    (45, 'postlude',           9),
    (50, 'sky_first_light',   29)
  ),
  progress as (
    select c.chapter as key, c.user_id, c.step, c.completed_at is not null as done
    from public.academy_chapters c
    union all
    select 'postlude', c.user_id, c.postlude_step, c.postlude_completed_at is not null
    from public.academy_chapters c
    where c.chapter = 'post_first_letter' and c.completed_at is not null
  ),
  seen as (
    select user_id, max(seen) as last_seen
    from (
      select user_id, updated_at as seen from public.academy_chapters
      union all
      select user_id, updated_at from public.academy_prologues
    ) u
    group by 1
  ),
  furthest as (
    select distinct on (p.user_id) p.user_id, p.key, p.step, p.done, d.final_step
    from progress p
    left join declared d on d.key = p.key
    order by p.user_id, coalesce(d.ord, 9999) desc, p.key
  )
  select coalesce(jsonb_agg(x.row order by x.last_seen desc), '[]'::jsonb)
    into v_players
  from (
    select s.last_seen,
           jsonb_build_object(
             'user_id',          s.user_id,
             'name',             pr.name,
             'is_student',       coalesce(pr.role, '') = 'student',
             'grade',            sr.grade,
             'class',            sr.class,
             'number',           sr.number,
             'stage_key',        coalesce(f.key, 'prologue'),
             'stage_step',       f.step,
             'stage_final_step', f.final_step,
             'stage_done',       coalesce(f.done, pl.completed_at is not null, false),
             'prologue_skipped', pl.skipped,
             'last_seen',        s.last_seen
           ) as row
    from seen s
    left join public.profiles pr on pr.id = s.user_id
    left join furthest f on f.user_id = s.user_id
    left join public.academy_prologues pl on pl.user_id = s.user_id
    left join lateral (
      select r.meta->>'grade' as grade, r.meta->>'class' as class, r.meta->>'number' as number
      from public.resource r
      where r.type = 'student' and r.meta->>'id' = split_part(pr.email, '@', 1)
      order by (r.status = 'active') desc
      limit 1
    ) sr on true
    order by s.last_seen desc nulls last
    limit 200
  ) x;

  v_academy := jsonb_build_object(
    'chapters', coalesce(v_academy, '[]'::jsonb),
    'players', (
      select jsonb_build_object(
        'total',             count(*),
        'student',           count(*) filter (where is_student),
        'faculty',           count(*) filter (where not is_student),
        'student_active_7d', count(*) filter (where is_student and last_seen >= now() - interval '7 days'),
        'active_7d',         count(*) filter (where last_seen >= now() - interval '7 days')
      )
      from (
        select u.user_id,
               coalesce(pr.role, '') = 'student' as is_student,
               max(u.seen) as last_seen
        from (
          select user_id, updated_at as seen from public.academy_chapters
          union all
          select user_id, updated_at from public.academy_prologues
        ) u
        left join public.profiles pr on pr.id = u.user_id
        group by 1, 2
      ) players
    ),
    'players_list', coalesce(v_players, '[]'::jsonb),
    'prologue', (
      select jsonb_build_object(
        'student_total',   count(*) filter (where is_student),
        'student_done',    count(*) filter (where is_student and completed_at is not null),
        'student_skipped', count(*) filter (where is_student and skipped),
        'faculty_total',   count(*) filter (where not is_student),
        'faculty_done',    count(*) filter (where not is_student and completed_at is not null)
      )
      from (
        select p.completed_at, p.skipped, coalesce(pr.role, '') = 'student' as is_student
        from public.academy_prologues p
        left join public.profiles pr on pr.id = p.user_id
      ) q
    )
  );

  -- ──────────────────────────────────────────────────────── 다마고찌 (머리말 참고)
  -- 표가 없는 배포본(브랜치)에서는 블록을 통째로 null 로 둔다 — 문장이 실행될 때만
  -- 계획되므로 이 if 안의 표 이름은 표가 없어도 함수를 죽이지 않는다.
  if to_regclass('public.tama_pet') is not null then
    select jsonb_build_object(
      'owners', (
        select jsonb_build_object(
          'total',   count(*),
          'student', count(*) filter (where role = 'student'),
          'teacher', count(*) filter (where role = 'teacher'),
          'admin',   count(*) filter (where role = 'admin'),
          'other',   count(*) filter (where coalesce(role, '') not in ('student', 'teacher', 'admin'))
        )
        from (
          select distinct p.owner, pr.role
          from public.tama_pet p left join public.profiles pr on pr.id = p.owner
        ) o
      ),
      'pets', (
        select jsonb_build_object(
          'total',    count(*),
          'resting',  count(*) filter (where not is_primary),
          'sick',     count(*) filter (where is_primary and coalesce((state->>'sick')::boolean, false)),
          'by_stage', coalesce((
            select jsonb_object_agg(stage, n)
            from (select coalesce(state->>'stage', '?') as stage, count(*) as n
                  from public.tama_pet group by 1) x
          ), '{}'::jsonb)
        )
        from public.tama_pet
      ),
      -- «돌본 날» = 펫을 저장한 한국 날짜(tama_care_day, 트리거가 쌓는다)
      'care', jsonb_build_object(
        'today',          (select count(*) from public.tama_care_day where day = v_today),
        'active_7d',      (select count(distinct owner) from public.tama_care_day where day > v_today - 7),
        'students_3days', (
          select count(*) from (
            select c.owner from public.tama_care_day c
            join public.profiles pr on pr.id = c.owner and pr.role = 'student'
            group by c.owner having count(*) >= 3
          ) x
        )
      ),
      'daily', (
        select jsonb_agg(jsonb_build_object('date', g.d::date,
                 'count', (select count(*) from public.tama_care_day c where c.day = g.d::date)) order by g.d)
        from generate_series(v_today - 13, v_today, interval '1 day') g(d)
      ),
      'activity_30d', jsonb_build_object(
        'gacha',          (select count(*) from public.tama_gacha_log where created_at >= v_since),
        'trades',         (select count(*) from public.tama_trade where status = 'accepted' and responded_at >= v_since),
        'diary',          (select count(*) from public.tama_diary where created_at >= v_since),
        'focus_started',  (select count(*) from public.tama_focus where started_at >= v_since),
        'focus_completed',(select count(*) from public.tama_focus where started_at >= v_since and outcome = 'completed'),
        'visits',         (select count(*) from public.tama_visit where day > v_today - 30),
        'coins',          (select coalesce(sum(amount), 0) from public.tama_credit_ledger where earned_on > v_today - 30)
      ),
      -- 관리자가 손으로 만들어 배송하는 의뢰 — 열린 것(접수·제작 중)이 곧 할 일이다
      'orders', jsonb_build_object(
        'character_open', (select count(*) from public.tama_character_order where status in ('submitted', 'crafting')),
        'decor_open',     (select count(*) from public.tama_decor_order     where status in ('submitted', 'crafting')),
        'oldest_open_at', (
          select min(created_at) from (
            select created_at from public.tama_character_order where status in ('submitted', 'crafting')
            union all
            select created_at from public.tama_decor_order     where status in ('submitted', 'crafting')
          ) o
        )
      ),
      'event', (
        select jsonb_build_object('title', e.title, 'ends_at', e.ends_at)
        from public.tama_event e
        where now() between e.starts_at and e.ends_at
        order by e.ends_at
        limit 1
      ),
      -- Web Push 는 다마고찌 Phase 4 로 들어왔지만 앱 전체 알림이 쓴다
      'push', (
        select jsonb_build_object(
          'subscriptions', count(*),
          'users',         count(distinct user_id),
          'failing',       count(*) filter (where fail_count > 0)
        )
        from public.push_subscriptions
      )
    ) into v_tama;
  end if;

  v_system := jsonb_build_object(
    'academic_term',   (select setting_value from public.system_settings where setting_key = 'academic_term'),
    'menu_visibility', (select setting_value from public.system_settings where setting_key = 'menu_visibility'),
    'notifications_30d',    (select count(*) from public.notification_events where created_at >= v_since),
    'notifications_unread', (select count(*) from public.notification_events where not is_read),
    'database_size',   pg_size_pretty(pg_database_size(current_database()))
  );

  return jsonb_build_object(
    'generated_at',  now(),
    'datasets',      v_snap->'datasets',
    'users',         v_users,
    'resources',     v_resources,
    'login_recency', coalesce(v_login, '[]'::jsonb),
    'academy',       v_academy,
    'tamagotchi',    v_tama,
    'system',        v_system,
    -- counting 은 **스냅샷을 만들 때**의 기록이다. 기준 시각·출처를 함께 실어 화면이 말하게 한다.
    'counting',      (v_snap->'counting') || jsonb_build_object(
                       'generated_at', v_snap->'generated_at',
                       'source',       v_snap->'source'
                     ),
    'live_ms',       round(extract(epoch from clock_timestamp() - v_started) * 1000)
  );
end;
$$;


ALTER FUNCTION "public"."get_admin_dashboard_stats"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admin_dashboard_stats"() IS '관리자 대시보드 통계. authenticated 의 8초 statement_timeout 안에서 끝나도록 3.5초 자체 예산 + 20MB 표 크기 상한을 두고, 그 밖은 pg_stat 추정치(exact=false)로 돌려준다. admin 전용.';



CREATE OR REPLACE FUNCTION "public"."get_admission_changes"("p_universities" "text"[]) RETURNS TABLE("query_university" "text", "matched_university" "text", "id" "text", "category" "text", "comparison" "text", "after_year" smallint, "before_year" smallint, "admission_item" "text", "keywords" "text"[], "after_text" "text", "before_text" "text", "change_type" "text", "is_exact" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with q as (
    select distinct u from unnest(coalesce(p_universities, '{}'::text[])) as t(u)
  ),
  exact_hit as (
    select q.u, exists (select 1 from public.admission_change c where c.university = q.u) as hit
    from q
  )
  select
    q.u as query_university,
    c.university as matched_university,
    c.id, c.category, c.comparison, c.after_year, c.before_year,
    c.admission_item, c.keywords, c.after_text, c.before_text, c.change_type,
    (c.university = q.u) as is_exact
  from q
  join exact_hit e on e.u = q.u
  join public.admission_change c
    on (e.hit and c.university = q.u)
    or (not e.hit and c.university % q.u and similarity(c.university, q.u) >= 0.6)
  order by q.u, c.after_year desc nulls last, c.university, c.id;
$$;


ALTER FUNCTION "public"."get_admission_changes"("p_universities" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admission_changes"("p_universities" "text"[]) IS '위시리스트 대학별 전형 변경사항. 대학명 정확 일치 우선(있으면 trgm 폴백 버림 — 캠퍼스 혼입 차단), 전형 단위로는 거르지 않는다(전형명 표기가 출처마다 달라 좁히면 0건). 자료는 전국 주요 대학 64곳 한정.';



CREATE OR REPLACE FUNCTION "public"."get_admission_schedules"("p_universities" "text"[]) RETURNS TABLE("query_university" "text", "matched_university" "text", "id" "text", "exam_type" "text", "stage" smallint, "exam_start" "date", "exam_end" "date", "admission_path" "text", "admission_name" "text", "apply_start" "date", "apply_end" "date", "announce_text" "text", "units" "text"[], "exam_time" "text", "note" "text", "is_exact" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with q as (
    select distinct
      u,
      replace(
        regexp_replace(regexp_replace(u, '\s', '', 'g'), '[\[\(][^\]\)]*[\]\)]', '', 'g'),
        '대학교', '대'
      ) as canon
    from unnest(coalesce(p_universities, '{}'::text[])) as t(u)
  )
  select
    q.u as query_university,
    s.university as matched_university,
    s.id, s.exam_type, s.stage, s.exam_start, s.exam_end,
    s.admission_path, s.admission_name, s.apply_start, s.apply_end,
    s.announce_text, s.units, s.exam_time, s.note,
    (s.university = q.u) as is_exact
  from q
  join public.admission_exam_schedule s on s.university_canon = q.canon
  order by q.u, s.exam_start nulls last, s.id;
$$;


ALTER FUNCTION "public"."get_admission_schedules"("p_universities" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_admission_schedules"("p_universities" "text"[]) IS '위시리스트 대학별 고사 일정. 정규화 대학명(공백·괄호 제거, 대학교→대)으로 매칭 — 자료가 정식명이라 약칭과 절대 정확히 일치하지 않는다. 캠퍼스가 뭉개지므로 화면은 matched_university 원문을 함께 보여줄 것. 전형·모집단위로는 거르지 않는다.';



CREATE OR REPLACE FUNCTION "public"."get_admission_university_info"("p_keys" "text"[]) RETURNS TABLE("university" "text", "university_canon" "text", "university_base" "text", "region" "text", "address" "text", "phone" "text", "home_url" "text", "home_raw" "text", "apply_url" "text", "apply_raw" "text", "multi_apply_status" "text", "multi_apply_limit" smallint, "multi_apply_summary" "text", "multi_apply_text" "text", "base_date" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    i.university, i.university_canon, i.university_base,
    i.region, i.address, i.phone,
    i.home_url, i.home_raw, i.apply_url, i.apply_raw,
    i.multi_apply_status, i.multi_apply_limit,
    i.multi_apply_summary, i.multi_apply_text, i.base_date
  from public.admission_university_info i
  where i.university_canon = any(coalesce(p_keys, '{}'::text[]))
     or i.university_base  = any(coalesce(p_keys, '{}'::text[]))
  order by i.university;
$$;


ALTER FUNCTION "public"."get_admission_university_info"("p_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_admission_wishlist"("p_student_code" "text") RETURNS TABLE("id" "uuid", "student_code" "text", "track" "text", "university" "text", "department" "text", "admission_name" "text", "memo" "text", "sort_order" integer, "tier" "text", "converted_score" "text", "interview_date" "text", "first_announce_date" "date", "final_announce_date" "date", "csat_check_6" "text", "csat_check_9" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "gyogwa" "jsonb", "jonghap" "jsonb", "adiga" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH base AS (
    SELECT w.*,
      ( SELECT ar.id FROM public.admission_adiga_results ar
        WHERE (w.adiga_id IS NOT NULL AND ar.id = w.adiga_id)
           OR (w.adiga_id IS NULL AND w.department IS NOT NULL
               AND ar.track = CASE w.track WHEN 'gyogwa' THEN '교과' WHEN 'jonghap' THEN '종합' END
               AND ar.university % w.university AND ar.major % w.department)
        ORDER BY (w.adiga_id IS NOT NULL AND ar.id = w.adiga_id) DESC,
                 similarity(ar.university, w.university) + similarity(ar.major, COALESCE(w.department,'')) DESC
        LIMIT 1 ) AS resolved_adiga_id
    FROM public.admission_wishlist w
    WHERE w.student_code = p_student_code
  )
  SELECT
    b.id, b.student_code, b.track, b.university, b.department, b.admission_name,
    b.memo, b.sort_order, b.tier,
    b.converted_score, b.interview_date, b.first_announce_date, b.final_announce_date,
    b.csat_check_6, b.csat_check_9,
    b.created_at, b.updated_at,
    ( SELECT CASE WHEN g.id IS NULL THEN NULL ELSE jsonb_build_object(
        'id', g.id, 'region', g.region, 'university', g.university,
        'admission', g.admission, 'unit', g.unit, 'method', g.method,
        'method_tags', to_jsonb(g.method_tags), 'unit_tags', to_jsonb(g.unit_tags),
        'quota', g.quota, 'quota_text', g.quota_text,
        'csat_status', g.csat_status, 'has_csat', g.has_csat, 'csat', g.csat,
        'subjects_all', g.subjects_all, 'careers', g.careers
      ) END
      FROM public.admission_gyogwa_criteria g
      WHERE (b.gyogwa_id IS NOT NULL AND g.id = b.gyogwa_id)
         OR (b.gyogwa_id IS NULL AND b.track = 'gyogwa' AND g.university % b.university)
      ORDER BY
        (b.gyogwa_id IS NOT NULL AND g.id = b.gyogwa_id) DESC,
        similarity(g.university, b.university) DESC,
        (CASE WHEN b.department IS NOT NULL AND g.unit IS NOT NULL
              AND similarity(g.unit, b.department) >= 0.3 THEN 1 ELSE 0 END) DESC,
        (g.has_csat)::int DESC,
        (CASE WHEN b.department IS NOT NULL AND g.unit IS NOT NULL
              THEN similarity(g.unit, b.department) ELSE 0 END) DESC,
        (CASE WHEN b.admission_name IS NOT NULL THEN similarity(COALESCE(g.admission,''), b.admission_name) ELSE 0 END) DESC
      LIMIT 1 ) AS gyogwa,
    ( SELECT CASE WHEN j.code IS NULL THEN NULL ELSE jsonb_build_object(
        'code', j.code, 'name', j.name, 'region', j.region, 'recruitment', j.recruitment,
        'has_doc_eval', j.has_doc_eval, 'doc_top_factors', j.doc_top_factors,
        'doc_parsed_ratios', j.doc_parsed_ratios, 'doc_section_text', j.doc_section_text,
        'doc_content_tables', j.doc_content_tables,
        'has_interview', j.has_interview, 'interview_status', j.interview_status,
        'interview_methods', to_jsonb(j.interview_methods),
        'interview_blocks', j.interview_blocks, 'interview_top_factors', j.interview_top_factors,
        'interview_primary_time', j.interview_primary_time,
        'interview_primary_process', j.interview_primary_process,
        'interview_primary_source', j.interview_primary_source
      ) END
      FROM public.admission_jonghap_criteria j
      WHERE (b.jonghap_code IS NOT NULL AND j.code = b.jonghap_code)
         OR (b.jonghap_code IS NULL AND b.track = 'jonghap' AND j.name % b.university)
      ORDER BY (b.jonghap_code IS NOT NULL AND j.code = b.jonghap_code) DESC,
               similarity(j.name, b.university) DESC
      LIMIT 1 ) AS jonghap,
    ( SELECT CASE WHEN a.id IS NULL THEN NULL ELSE jsonb_build_object(
        'id', a.id, 'university', a.university, 'major', a.major, 'track', a.track,
        'program', a.program, 'field', a.field, 'domain', a.domain,
        'grade50', a.grade50, 'grade70', a.grade70, 'grade_quality', a.grade_quality,
        'recruit_2026', a.recruit_2026, 'competition_2026', a.competition_2026,
        'real_competition_2026', a.real_competition_2026, 'waitlist_2026', a.waitlist_2026,
        'fill_rate_2026', a.fill_rate_2026, 'history', a.history
      ) END
      FROM public.admission_adiga_results a WHERE a.id = b.resolved_adiga_id LIMIT 1 ) AS adiga
  FROM base b
  ORDER BY (b.tier = 'interest'), b.sort_order, b.created_at;
$$;


ALTER FUNCTION "public"."get_admission_wishlist"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_class_correlation"("p_grade" integer, "p_class_num" integer, "p_domain_x" "text", "p_domain_y" "text") RETURNS TABLE("student_code" "text", "name" "text", "x_value" numeric, "y_value" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH students AS (
    SELECT sim.student_code, sim.name
    FROM student_identity_map sim
    WHERE sim.current_grade = p_grade AND sim.current_class = p_class_num
  ),
  domain_values AS (
    SELECT
      s.student_code,
      s.name,
      -- X domain
      CASE p_domain_x
        WHEN 'academic_avg' THEN (
          SELECT CASE WHEN SUM(saf.units) > 0 THEN ROUND(SUM(saf.rank * saf.units) / SUM(saf.units), 2) END
          FROM student_academic_flat saf
          WHERE saf.student_code = s.student_code AND saf.category = 'regular' AND saf.rank IS NOT NULL AND saf.units > 0
        )
        WHEN 'mock_avg' THEN (
          SELECT ROUND(AVG(ms.grade)::numeric, 1)
          FROM get_student_mock_summary(s.student_code) ms
        )
        WHEN 'study_room_rate' THEN (
          SELECT sr.attendance_rate
          FROM get_student_study_room_summary(s.student_code) sr
          WHERE sr.academic_year = EXTRACT(YEAR FROM CURRENT_DATE)::int
          LIMIT 1
        )
        WHEN 'reading_count' THEN (
          SELECT COUNT(*)::numeric FROM get_student_reading_flat(s.student_code)
        )
        WHEN 'activity_count' THEN (
          SELECT COUNT(*)::numeric FROM student_detailed_activities WHERE student_id = s.student_code
        )
      END AS x_val,
      -- Y domain
      CASE p_domain_y
        WHEN 'academic_avg' THEN (
          SELECT CASE WHEN SUM(saf.units) > 0 THEN ROUND(SUM(saf.rank * saf.units) / SUM(saf.units), 2) END
          FROM student_academic_flat saf
          WHERE saf.student_code = s.student_code AND saf.category = 'regular' AND saf.rank IS NOT NULL AND saf.units > 0
        )
        WHEN 'mock_avg' THEN (
          SELECT ROUND(AVG(ms.grade)::numeric, 1)
          FROM get_student_mock_summary(s.student_code) ms
        )
        WHEN 'study_room_rate' THEN (
          SELECT sr.attendance_rate
          FROM get_student_study_room_summary(s.student_code) sr
          WHERE sr.academic_year = EXTRACT(YEAR FROM CURRENT_DATE)::int
          LIMIT 1
        )
        WHEN 'reading_count' THEN (
          SELECT COUNT(*)::numeric FROM get_student_reading_flat(s.student_code)
        )
        WHEN 'activity_count' THEN (
          SELECT COUNT(*)::numeric FROM student_detailed_activities WHERE student_id = s.student_code
        )
      END AS y_val
    FROM students s
  )
  SELECT dv.student_code, dv.name, dv.x_val, dv.y_val
  FROM domain_values dv
  WHERE dv.x_val IS NOT NULL AND dv.y_val IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."get_class_correlation"("p_grade" integer, "p_class_num" integer, "p_domain_x" "text", "p_domain_y" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_class_transition_map"("p_from_grade" integer, "p_entry_year" integer DEFAULT NULL::integer) RETURNS TABLE("past_class" integer, "current_class" integer, "student_count" bigint, "avg_past_rank" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    (gi->>'class')::int AS past_class,
    sim.current_class,
    COUNT(*) AS student_count,
    ROUND(AVG(saf_avg.avg_rank)::numeric, 2) AS avg_past_rank
  FROM student_basic_info sbi
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(sbi.grade_info, '[]'::jsonb)) AS gi
  JOIN student_identity_map sim ON sim.student_code = sbi.id
  LEFT JOIN (
    SELECT student_code, AVG(rank) as avg_rank
    FROM student_academic_flat
    WHERE category = 'regular' AND rank IS NOT NULL
    GROUP BY student_code
  ) saf_avg ON saf_avg.student_code = sbi.id
  WHERE (gi->>'grade')::int = p_from_grade
    AND jsonb_typeof(sbi.grade_info) = 'array'
    AND sim.current_grade IS NOT NULL
    AND (p_entry_year IS NULL OR sbi.id LIKE LPAD((p_entry_year % 100)::text, 2, '0') || '-%')
  GROUP BY (gi->>'class')::int, sim.current_class
  ORDER BY (gi->>'class')::int, sim.current_class;
$$;


ALTER FUNCTION "public"."get_class_transition_map"("p_from_grade" integer, "p_entry_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_class_wishlist_summary"("p_grade" integer, "p_class" integer) RETURNS TABLE("student_code" "text", "name" "text", "number_in_class" integer, "wishlist_id" "uuid", "track" "text", "university" "text", "department" "text", "admission_name" "text", "sort_order" integer, "grade70" numeric, "competition_2026" numeric, "field" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_sample_code text;
BEGIN
  SELECT sr.meta->>'id' INTO v_sample_code
  FROM resource sr
  WHERE sr.type = 'student'
    AND sr.meta->>'grade' = p_grade::text
    AND sr.meta->>'class' = p_class::text
  ORDER BY NULLIF(sr.meta->>'number','')::int NULLS LAST
  LIMIT 1;

  -- 권한 게이트: 반 대표 학생 1명을 읽을 수 있는가 (담임=자기반/학년부장=학년/admin).
  -- 상담교사는 제외 (can_read_wishlist 에 미포함).
  IF NOT (v_sample_code IS NOT NULL AND public.can_read_wishlist(v_sample_code)) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    (sr.meta->>'id') AS student_code,
    sr.name,
    NULLIF(sr.meta->>'number','')::int AS number_in_class,
    w.id AS wishlist_id,
    w.track, w.university, w.department, w.admission_name, w.sort_order,
    a.grade70, a.competition_2026, a.field
  FROM resource sr
  LEFT JOIN admission_wishlist w ON w.student_code = sr.meta->>'id'
  LEFT JOIN LATERAL (
    SELECT ar.grade70, ar.competition_2026, ar.field
    FROM admission_adiga_results ar
    WHERE w.id IS NOT NULL AND (
      (w.adiga_id IS NOT NULL AND ar.id = w.adiga_id)
      OR (w.adiga_id IS NULL AND w.department IS NOT NULL
          AND ar.track = CASE w.track WHEN 'gyogwa' THEN '교과' WHEN 'jonghap' THEN '종합' END
          AND ar.university % w.university AND ar.major % w.department)
    )
    ORDER BY (w.adiga_id IS NOT NULL AND ar.id = w.adiga_id) DESC,
             similarity(ar.university, w.university) + similarity(ar.major, COALESCE(w.department,'')) DESC
    LIMIT 1
  ) a ON true
  WHERE sr.type = 'student'
    AND sr.meta->>'grade' = p_grade::text
    AND sr.meta->>'class' = p_class::text
  ORDER BY NULLIF(sr.meta->>'number','')::int NULLS LAST, w.sort_order;
END $$;


ALTER FUNCTION "public"."get_class_wishlist_summary"("p_grade" integer, "p_class" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_class_wishlist_summary"("p_grade" integer, "p_class" integer) IS '학급 전체 수시 지원 현황 (행=학생×지원항목, 지원없는 학생도 1행). 명단 출처=resource.meta(권위·최신). SECURITY DEFINER + 권한 게이트(반 대표 학생 케어 OR admin). adiga 커트/경쟁률 매칭 포함.';



