CREATE OR REPLACE FUNCTION "public"."get_cohort_analysis"("p_entry_year" integer, "p_current_grade" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
  v_entry_prefix TEXT;
  v_class_academics JSONB;
  v_mock_trend JSONB;
  v_study_room_corr JSONB;
  v_activity_stats JSONB;
BEGIN
  v_entry_prefix := LPAD((p_entry_year % 100)::text, 2, '0') || '-';

  SELECT jsonb_agg(class_data ORDER BY class_data->>'class_num')
  INTO v_class_academics
  FROM (
    SELECT jsonb_build_object(
      'class_num', sim.current_class,
      'student_count', COUNT(DISTINCT saf.student_code),
      'avg_grade', ROUND(
        CASE WHEN SUM(saf.units) FILTER (WHERE saf.units > 0) > 0
        THEN SUM(saf.rank * saf.units) FILTER (WHERE saf.rank IS NOT NULL AND saf.units > 0)
             / SUM(saf.units) FILTER (WHERE saf.rank IS NOT NULL AND saf.units > 0)
        ELSE NULL END, 2
      )
    ) AS class_data
    FROM student_academic_flat saf
    JOIN student_identity_map sim ON sim.student_code = saf.student_code
    WHERE saf.student_code LIKE v_entry_prefix || '%'
      AND saf.grade = p_current_grade
      AND saf.category = 'regular'
      AND sim.current_grade = p_current_grade
    GROUP BY sim.current_class
  ) sub;

  SELECT jsonb_agg(
    jsonb_build_object(
      'academic_year', sub.academic_year,
      'exam_month', sub.exam_month,
      'avg_grade', sub.avg_grade,
      'student_count', sub.student_count
    ) ORDER BY sub.academic_year, sub.exam_month
  )
  INTO v_mock_trend
  FROM (
    SELECT
      ms.academic_year,
      ms.exam_month,
      ROUND(AVG(ms.grade)::numeric, 2) AS avg_grade,
      COUNT(DISTINCT ms.student_code) AS student_count
    FROM get_student_mock_summary() ms
    WHERE ms.student_code LIKE v_entry_prefix || '%'
      AND ms.exam_grade = p_current_grade
    GROUP BY ms.academic_year, ms.exam_month
  ) sub;

  SELECT jsonb_build_object(
    'students_using', COUNT(DISTINCT sr.student_code),
    'avg_attendance_rate', ROUND(AVG(sr.attendance_rate), 1),
    'total_reservations', SUM(sr.total_reservations)
  )
  INTO v_study_room_corr
  FROM get_student_study_room_summary() sr
  WHERE sr.student_code LIKE v_entry_prefix || '%'
    AND sr.academic_year = EXTRACT(YEAR FROM CURRENT_DATE)::int;

  SELECT jsonb_build_object(
    'total_students', COUNT(DISTINCT sbi.id),
    'with_activities', COUNT(DISTINCT sda.student_id),
    'avg_activity_count', ROUND(AVG(act_count)::numeric, 1),
    'with_reading', (
      SELECT COUNT(*)
      FROM student_basic_info s2
      WHERE s2.id LIKE v_entry_prefix || '%'
        AND s2.reading IS NOT NULL
        AND jsonb_array_length(s2.reading) > 0
    )
  )
  INTO v_activity_stats
  FROM student_basic_info sbi
  LEFT JOIN (
    SELECT student_id, COUNT(*) as act_count
    FROM student_detailed_activities
    WHERE student_id LIKE v_entry_prefix || '%'
    GROUP BY student_id
  ) sda ON sda.student_id = sbi.id
  WHERE sbi.id LIKE v_entry_prefix || '%';

  v_result := jsonb_build_object(
    'entry_year', p_entry_year,
    'current_grade', p_current_grade,
    'class_academics', COALESCE(v_class_academics, '[]'::jsonb),
    'mock_trend', COALESCE(v_mock_trend, '[]'::jsonb),
    'study_room', COALESCE(v_study_room_corr, '{}'::jsonb),
    'activity_stats', COALESCE(v_activity_stats, '{}'::jsonb)
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_cohort_analysis"("p_entry_year" integer, "p_current_grade" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_collect_board"("p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_action  public.task_action;
  v_req     public.collect_request;
  v_manage  boolean;
  v_target  boolean;
  v_me      uuid[];
  v_all     boolean;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into v_action from public.task_action where id = p_action_id;
  if not found then raise exception '작업을 찾을 수 없습니다' using errcode = 'P0002'; end if;

  v_manage := public.can_manage_collect(p_action_id);
  v_target := public.is_collect_target(p_action_id);
  if not v_manage and not v_target then
    raise exception '이 요청을 볼 수 없습니다' using errcode = '42501';
  end if;
  select array_agg(x) into v_me from public.current_actor_resource_ids() x;
  select * into v_req from public.collect_request where action_id = p_action_id;
  v_all := v_manage or coalesce(v_req.visibility = 'shared', false);

  return jsonb_build_object(
    'action', jsonb_build_object(
      'id', v_action.id, 'title', v_action.title, 'task_id', v_action.task_id, 'created_by', v_action.created_by,
      'archived_at', v_action.archived_at,
      'task_title', (select title from public.task where id = v_action.task_id),
      'task_status', (select status from public.task where id = v_action.task_id),
      'work_title', (select w.name from public.task t join public.work w on w.id = t.event_id where t.id = v_action.task_id)),
    'config', public.request_cfg_of(v_action.action_type, v_action.config),
    'kind', public.request_kind_of(v_action.action_type),
    -- 과제 단위(2026-10-01) — 단위 축 요청의 화면이 고를 목록·맡은 사람을 그린다
    'units', coalesce((select case when jsonb_typeof(t.meta->'units') = 'array' then t.meta->'units' end
                       from public.task t where t.id = v_action.task_id), '[]'::jsonb),
    'unit_progress', coalesce((select case when jsonb_typeof(t.meta->'unitProgress') = 'object' then t.meta->'unitProgress' end
                               from public.task t where t.id = v_action.task_id), '{}'::jsonb),
    'request', case when v_req.action_id is null then null else to_jsonb(v_req) - 'rule_snapshot' - 'config_snapshot' end,
    'viewer', jsonb_build_object('can_manage', v_manage, 'is_target', v_target, 'resource_ids', to_jsonb(coalesce(v_me, '{}'))),
    'targets', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', t.id, 'unit_key', t.unit_key, 'unit_label', t.unit_label, 'resource_id', t.resource_id,
               'name', coalesce(r.name, t.holder_name), 'reasons', to_jsonb(t.reasons),
               'removed', t.removed_at is not null)
             order by t.unit_label, coalesce(r.name, t.holder_name))
      from public.collect_target t left join public.resource r on r.id = t.resource_id
      where t.action_id = p_action_id
        and (v_all
             or t.resource_id = any (v_me)
             or (v_req.answer_mode = 'shared' and t.unit_key in (
                   select t2.unit_key from public.collect_target t2
                   where t2.action_id = p_action_id and t2.resource_id = any (v_me) and t2.removed_at is null)))
    ), '[]'::jsonb),
    'responses', coalesce((
      select jsonb_agg(jsonb_build_object(
               'unit_key', x.unit_key, 'dimension_key', x.dimension_key, 'owner_key', x.owner_key,
               'responder_resource_id', x.responder_resource_id, 'responder_name', r.name,
               'values', x."values", 'updated_at', x.updated_at))
      from public.collect_response x left join public.resource r on r.id = x.responder_resource_id
      where x.action_id = p_action_id
        and (v_all
             or x.responder_resource_id = any (v_me)
             or (v_req.answer_mode = 'shared' and x.unit_key in (
                   select t2.unit_key from public.collect_target t2
                   where t2.action_id = p_action_id and t2.resource_id = any (v_me) and t2.removed_at is null)))
    ), '[]'::jsonb),
    -- 제출물(2026-10-01) — 매니저는 전원, 대상자는 자기 것만
    'submissions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', s.id, 'resource_id', s.resource_id, 'name', r.name, 'kind', s.kind, 'unit_key', s.unit_key,
               'file_name', s.file_name, 'file_url', s.file_url, 'google_drive_id', s.google_drive_id,
               'mime_type', s.mime_type, 'file_size', s.file_size,
               'document_id', s.document_id, 'document_title', d.title,
               'received_at', s.received_at, 'created_at', s.created_at, 'updated_at', s.updated_at)
             order by s.created_at)
      from public.action_submission s
      left join public.resource r on r.id = s.resource_id
      left join public.task_action_document d on d.id = s.document_id
      where s.action_id = p_action_id
        and (v_manage or s.resource_id = any (v_me))
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_collect_board"("p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_course_analyze_snapshot"("p_academic_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_target_year integer;
  v_available_years integer[];
  v_student_data jsonb;
  v_subject_config jsonb;
  v_meta jsonb;
BEGIN
  -- 1) 사용 가능한 학년도 + target year 결정
  SELECT array_agg(DISTINCT academic_year ORDER BY academic_year DESC)
    INTO v_available_years
  FROM course_selection_round;

  IF v_available_years IS NULL OR array_length(v_available_years, 1) = 0 THEN
    RETURN NULL;
  END IF;

  v_target_year := COALESCE(p_academic_year, v_available_years[1]);

  -- 2) studentData: rounds × submissions × items 평탄화 + resource JOIN으로 realID
  SELECT jsonb_agg(
    jsonb_build_array(
      raw_id,
      student_name,
      grade_str,
      class_num,
      no_num,
      round_str,
      sem1,
      sem2,
      0,           -- grade (JSON 평균등급 폐기, RPC가 별도 처리)
      real_id      -- realID (resource.meta->>'id') — Phase3: 클라이언트 enrichment 불필요
    ) ORDER BY raw_id
  )
    INTO v_student_data
  FROM (
    SELECT
      -- 학생ID는 student_code prefix 제거 (10101 형식)
      CASE
        WHEN s.student_code LIKE '%-%' THEN split_part(s.student_code, '-', 2)
        ELSE s.student_code
      END AS raw_id,
      s.student_name,
      r.target_grade::text AS grade_str,
      COALESCE(s.student_class, 0) AS class_num,
      COALESCE(s.student_no, 0) AS no_num,
      r.round_number::text AS round_str,
      -- semester 1 과목 콤마 join
      COALESCE(
        string_agg(CASE WHEN i.semester = 1 THEN i.subject_name END, ', ' ORDER BY i.subject_name)
          FILTER (WHERE i.semester = 1),
        ''
      ) AS sem1,
      COALESCE(
        string_agg(CASE WHEN i.semester = 2 THEN i.subject_name END, ', ' ORDER BY i.subject_name)
          FILTER (WHERE i.semester = 2),
        ''
      ) AS sem2,
      -- realID: resource JOIN. student_resource_id가 있으면 직접, 없으면 student_code 매칭
      COALESCE(
        (SELECT res.meta->>'id' FROM resource res WHERE res.id = s.student_resource_id),
        s.student_code
      ) AS real_id
    FROM course_selection_submission s
    JOIN course_selection_round r ON r.id = s.round_id
    LEFT JOIN course_selection_item i ON i.submission_id = s.id
    WHERE r.academic_year = v_target_year
      AND s.student_code IS NOT NULL  -- resource 매칭 실패 케이스 제외
    GROUP BY s.id, s.student_code, s.student_name, s.student_class, s.student_no,
             r.target_grade, r.round_number, s.student_resource_id
  ) flat;

  IF v_student_data IS NULL OR jsonb_array_length(v_student_data) = 0 THEN
    RETURN NULL;
  END IF;

  -- 3) subjectConfiguration: course_selectable_subject 카탈로그
  SELECT jsonb_object_agg(category_code, subjects)
    INTO v_subject_config
  FROM (
    SELECT
      category_code,
      jsonb_agg(name ORDER BY display_order, name) AS subjects
    FROM course_selectable_subject
    WHERE is_active = true
    GROUP BY category_code
  ) cat;

  -- 4) meta + 최종 반환 객체
  v_meta := jsonb_build_object(
    'academicYear', v_target_year,
    'availableAcademicYears', to_jsonb(v_available_years),
    'studentCount', jsonb_array_length(v_student_data)
  );

  RETURN jsonb_build_object(
    'studentData', v_student_data,
    'subjectsByCategory', COALESCE(v_subject_config, '{}'::jsonb),
    'meta', v_meta
  );
END;
$$;


ALTER FUNCTION "public"."get_course_analyze_snapshot"("p_academic_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_course_analyze_snapshot"("p_academic_year" integer) IS 'course-analyze: 한 학년도의 rounds+submissions+items+subjectConfig+realID JOIN을 단일 RTT로 반환. Phase3 최적화 (~6 RTTs → 1).';



CREATE OR REPLACE FUNCTION "public"."get_course_selection_round_tree"("p_round_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
WITH groups AS (
  SELECT g.*,
    COALESCE(
      (
        SELECT jsonb_agg(slot_row ORDER BY (slot_row->>'display_order')::int)
        FROM (
          SELECT jsonb_build_object(
            'id', s.id,
            'group_id', s.group_id,
            'title', s.title,
            'semester', s.semester,
            'pick_count', s.pick_count,
            'capacity', s.capacity,
            'display_order', s.display_order,
            'meta', s.meta,
            'subjects', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                'id', ss.id,
                'selectable_subject_id', ss.selectable_subject_id,
                'semester', ss.semester,
                'override_capacity', ss.override_capacity,
                'display_order', ss.display_order,
                'bundle_key', ss.bundle_key,
                'bundle_label', ss.bundle_label,
                'name', sub.name,
                'category_code', sub.category_code,
                'default_max_capacity', sub.default_max_capacity,
                'meta', sub.meta,
                'credits', sc.credits,
                'subject_type', sc.subject_type,
                'grading_type', sc.grading_type,
                'area', sc.area
              ) ORDER BY ss.bundle_key NULLS LAST, ss.display_order)
              FROM public.course_selection_slot_subject ss
              JOIN public.course_selectable_subject sub ON sub.id = ss.selectable_subject_id
              LEFT JOIN public.school_curriculum sc ON sc.id = sub.school_curriculum_id
              WHERE ss.slot_id = s.id
            ), '[]'::jsonb)
          ) AS slot_row
          FROM public.course_selection_slot s
          WHERE s.group_id = g.id
        ) sj
      ),
      '[]'::jsonb
    ) AS slots
  FROM public.course_selection_group g
  WHERE g.round_id = p_round_id
)
SELECT jsonb_build_object(
  'round', (SELECT to_jsonb(r) FROM public.course_selection_round r WHERE r.id = p_round_id),
  'groups', COALESCE((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.display_order) FROM groups g), '[]'::jsonb)
);
$$;


ALTER FUNCTION "public"."get_course_selection_round_tree"("p_round_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_current_user_info"() RETURNS "json"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  result JSON;
BEGIN
  SELECT json_build_object(
    'auth_uid', auth.uid(),
    'auth_role', auth.role(),
    'profile_exists', EXISTS (
      SELECT 1 FROM profiles WHERE id = auth.uid()
    ),
    'profile_data', (
      SELECT json_build_object(
        'id', id,
        'email', email,
        'role', role,
        'name', name,
        'last_login', last_login
      )
      FROM profiles
      WHERE id = auth.uid()
    ),
    'can_update_check', EXISTS (
      SELECT 1 FROM profiles
      WHERE id = auth.uid() AND role = 'teacher'
    )
  ) INTO result;

  RETURN result;
END;
$$;


