CREATE OR REPLACE FUNCTION "public"."get_curriculum_by_term"("p_academic_year" integer, "p_grade" integer DEFAULT NULL::integer, "p_semester" integer DEFAULT NULL::integer) RETURNS TABLE("academic_year" integer, "grade" integer, "semester" integer, "area" "text", "category" "text", "subject" "text", "credits" integer, "hours" integer, "grading_type" "text", "subject_type" "text", "curriculum_revision" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT academic_year, grade, semester, area, category, subject, credits, hours, grading_type, subject_type, curriculum_revision
  FROM school_curriculum
  WHERE academic_year = p_academic_year
    AND (p_grade IS NULL OR grade = p_grade)
    AND (p_semester IS NULL OR semester = p_semester)
  ORDER BY grade, semester, area NULLS FIRST,
    CASE category
      WHEN '국어' THEN 1 WHEN '수학' THEN 2 WHEN '영어' THEN 3
      WHEN '사회' THEN 4 WHEN '과학' THEN 5 WHEN '체육' THEN 6
      WHEN '예술' THEN 7 WHEN '기술·가정' THEN 8 WHEN '교양' THEN 9
      ELSE 10
    END,
    subject;
$$;


ALTER FUNCTION "public"."get_curriculum_by_term"("p_academic_year" integer, "p_grade" integer, "p_semester" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_curriculum_comparison"("p_year_a" integer, "p_year_b" integer) RETURNS TABLE("change_type" "text", "category" "text", "subject" "text", "subject_type_a" "text", "subject_type_b" "text", "total_credits_a" integer, "total_credits_b" integer, "semesters_a" "jsonb", "semesters_b" "jsonb", "details" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH per_subject AS (
    SELECT
      sc.admission_year, sc.category, sc.subject, sc.subject_type,
      SUM(sc.credits)::int AS total_credits,
      jsonb_object_agg(sc.grade::text || '-' || sc.semester::text, sc.credits) AS semesters
    FROM school_curriculum sc
    WHERE sc.admission_year IN (p_year_a, p_year_b)
    GROUP BY sc.admission_year, sc.category, sc.subject, sc.subject_type
  ),
  a AS (SELECT * FROM per_subject WHERE admission_year = p_year_a),
  b AS (SELECT * FROM per_subject WHERE admission_year = p_year_b)
  SELECT * FROM (
    SELECT 'added'::text, b.category, b.subject, NULL::text, b.subject_type,
           NULL::int, b.total_credits, NULL::jsonb, b.semesters, '신규 개설'::text
    FROM b LEFT JOIN a USING (subject) WHERE a.subject IS NULL
    UNION ALL
    SELECT 'removed', a.category, a.subject, a.subject_type, NULL,
           a.total_credits, NULL, a.semesters, NULL, '폐지'
    FROM a LEFT JOIN b USING (subject) WHERE b.subject IS NULL
    UNION ALL
    SELECT 'modified', COALESCE(b.category, a.category), a.subject,
           a.subject_type, b.subject_type, a.total_credits, b.total_credits,
           a.semesters, b.semesters,
           CASE
             WHEN COALESCE(a.subject_type, '') <> COALESCE(b.subject_type, '')
               THEN '과목유형 변경: ' || COALESCE(a.subject_type, 'NULL') || ' → ' || COALESCE(b.subject_type, 'NULL')
             WHEN a.total_credits <> b.total_credits
               THEN '학점 변경: ' || a.total_credits || ' → ' || b.total_credits
             WHEN a.semesters::text <> b.semesters::text
               THEN '학기 배치 변경'
             ELSE '기타 변경'
           END
    FROM a JOIN b USING (subject)
    WHERE COALESCE(a.subject_type,'') <> COALESCE(b.subject_type,'')
       OR a.total_credits <> b.total_credits
       OR a.semesters::text <> b.semesters::text
  ) sub
  ORDER BY 1, 2, 3;
END;
$$;


ALTER FUNCTION "public"."get_curriculum_comparison"("p_year_a" integer, "p_year_b" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_curriculum_comparison"("p_year_a" integer, "p_year_b" integer) IS '두 입학연도 간 교육과정 변경점 비교';



CREATE OR REPLACE FUNCTION "public"."get_curriculum_overview"("p_admission_year" integer DEFAULT NULL::integer) RETURNS TABLE("admission_year" integer, "category" "text", "subject_type" "text", "subject_count" integer, "total_credits_sum" integer, "subjects" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH per_subject AS (
    SELECT
      sc.admission_year,
      sc.category,
      sc.subject_type,
      sc.subject,
      MAX(sc.area) AS area,
      SUM(sc.credits)::int AS total_credits,
      jsonb_object_agg(sc.grade::text || '-' || sc.semester::text, sc.credits) AS semesters
    FROM school_curriculum sc
    WHERE (p_admission_year IS NULL OR sc.admission_year = p_admission_year)
    GROUP BY sc.admission_year, sc.category, sc.subject_type, sc.subject
  )
  SELECT
    ps.admission_year,
    ps.category,
    ps.subject_type,
    COUNT(*)::int AS subject_count,
    SUM(ps.total_credits)::int AS total_credits_sum,
    jsonb_agg(
      jsonb_build_object(
        'subject', ps.subject,
        'area', ps.area,
        'total_credits', ps.total_credits,
        'semesters', ps.semesters
      ) ORDER BY ps.subject
    ) AS subjects
  FROM per_subject ps
  GROUP BY ps.admission_year, ps.category, ps.subject_type
  ORDER BY ps.admission_year,
    CASE ps.category
      WHEN '국어' THEN 1 WHEN '수학' THEN 2 WHEN '영어' THEN 3
      WHEN '사회' THEN 4 WHEN '과학' THEN 5 WHEN '체육' THEN 6
      WHEN '예술' THEN 7 WHEN '기술·가정' THEN 8 WHEN '교양' THEN 9
      ELSE 10
    END,
    ps.subject_type NULLS LAST;
$$;


ALTER FUNCTION "public"."get_curriculum_overview"("p_admission_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_curriculum_overview"("p_admission_year" integer) IS '입학연도별 교육과정 편성 현황 (교과군×과목유형 집계)';



CREATE OR REPLACE FUNCTION "public"."get_curriculum_subject_plan"("p_admission_year" integer) RETURNS TABLE("academic_year" integer, "grade" integer, "semester" integer, "subject" "text", "area" "text", "category" "text", "has_survey" boolean, "is_required" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with pool as (
    select distinct g.academic_year, g.target_grade as grade, cs.name as subject
    from course_selection_slot_subject ss
    join course_selection_slot sl on sl.id = ss.slot_id
    join course_selection_group g on g.id = sl.group_id
    join course_selectable_subject cs on cs.id = ss.selectable_subject_id
  ),
  surveyed as (
    select distinct academic_year, grade from pool
  )
  select c.academic_year, c.grade, c.semester, c.subject, c.area, c.category,
         (s.academic_year is not null) as has_survey,
         (s.academic_year is not null and p.subject is null) as is_required
  from public.school_curriculum c
  left join surveyed s on s.academic_year = c.academic_year and s.grade = c.grade
  left join pool p on p.academic_year = c.academic_year and p.grade = c.grade and p.subject = c.subject
  where c.admission_year = p_admission_year;
$$;


ALTER FUNCTION "public"."get_curriculum_subject_plan"("p_admission_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_curriculum_subjects_for_group"("p_group_id" "uuid", "p_semester" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_year integer;
  v_grade integer;
  v_result jsonb;
BEGIN
  SELECT COALESCE(g.academic_year, r.academic_year), COALESCE(g.target_grade, r.target_grade)
    INTO v_year, v_grade
  FROM public.course_selection_group g
  JOIN public.course_selection_round r ON r.id = g.round_id
  WHERE g.id = p_group_id;

  IF v_year IS NULL OR v_grade IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  -- 매칭 안 되는 school_curriculum 과목을 course_selectable_subject에 자동 등록
  -- NULL을 명시적으로 integer로 캐스팅 (default_max_capacity integer 컬럼)
  -- name UNIQUE constraint 충돌 시 skip
  INSERT INTO public.course_selectable_subject (
    name, category_code, school_curriculum_id, default_max_capacity, display_order, is_active
  )
  SELECT DISTINCT ON (sc.subject)
    sc.subject, sc.category, sc.id, NULL::integer, 0, true
  FROM public.school_curriculum sc
  WHERE sc.academic_year = v_year
    AND sc.grade = v_grade
    AND (p_semester IS NULL OR sc.semester = p_semester)
    AND NOT EXISTS (
      SELECT 1 FROM public.course_selectable_subject css
      WHERE css.school_curriculum_id = sc.id
         OR (css.school_curriculum_id IS NULL AND css.name = sc.subject)
    )
  ORDER BY sc.subject, sc.id
  ON CONFLICT (name) DO NOTHING;

  -- 조회 (INSERT 이후 매칭 가능)
  SELECT COALESCE(jsonb_agg(row_obj ORDER BY (row_obj->>'category'), (row_obj->>'subject')), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT DISTINCT ON (sc.subject, sc.semester)
        jsonb_build_object(
          'curriculum_id', sc.id,
          'subject', sc.subject,
          'category', sc.category,
          'credits', sc.credits,
          'semester', sc.semester,
          'academic_year', sc.academic_year,
          'grade', sc.grade,
          'subject_type', sc.subject_type,
          'grading_type', sc.grading_type,
          'selectable_subject_id', css.id,
          'default_max_capacity', css.default_max_capacity,
          'category_code', css.category_code
        ) AS row_obj
      FROM public.school_curriculum sc
      LEFT JOIN public.course_selectable_subject css
        ON css.school_curriculum_id = sc.id
        OR (css.school_curriculum_id IS NULL AND css.name = sc.subject)
      WHERE sc.academic_year = v_year
        AND sc.grade = v_grade
        AND (p_semester IS NULL OR sc.semester = p_semester)
    ) AS rows;

  RETURN COALESCE(v_result, '[]'::jsonb);
END $$;


ALTER FUNCTION "public"."get_curriculum_subjects_for_group"("p_group_id" "uuid", "p_semester" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_curriculum_subjects_for_round"("p_round_id" "uuid", "p_semester" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
WITH r AS (
  SELECT academic_year, target_grade
  FROM public.course_selection_round
  WHERE id = p_round_id
)
SELECT COALESCE(jsonb_agg(row_obj ORDER BY (row_obj->>'category'), (row_obj->>'subject')), '[]'::jsonb)
FROM (
  SELECT DISTINCT ON (sc.subject, sc.semester)
    jsonb_build_object(
      'curriculum_id', sc.id,
      'subject', sc.subject,
      'category', sc.category,
      'credits', sc.credits,
      'semester', sc.semester,
      'academic_year', sc.academic_year,
      'grade', sc.grade,
      'subject_type', sc.subject_type,
      'grading_type', sc.grading_type,
      'selectable_subject_id', css.id,
      'default_max_capacity', css.default_max_capacity,
      'category_code', css.category_code
    ) AS row_obj
  FROM r
  JOIN public.school_curriculum sc
    ON sc.academic_year = r.academic_year
   AND sc.grade = r.target_grade
   AND (p_semester IS NULL OR sc.semester = p_semester)
  LEFT JOIN public.course_selectable_subject css
    ON css.school_curriculum_id = sc.id
    OR (css.school_curriculum_id IS NULL AND css.name = sc.subject)
) AS rows;
$$;


ALTER FUNCTION "public"."get_curriculum_subjects_for_round"("p_round_id" "uuid", "p_semester" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_daily_statistics"("start_date" "date", "end_date" "date", "target_grade" integer DEFAULT NULL::integer) RETURNS TABLE("date" "text", "total_reservations" bigint, "attended" bigint, "attendance_rate" integer, "by_grade" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    WITH daily_grade_data AS (
        SELECT
            sr.reservation_date,
            (res.meta->>'grade')::int as grade,
            count(*) as total,
            count(*) FILTER (WHERE sr.is_attended) as attended_count
        FROM seat_reservations sr
        JOIN profiles p ON sr.student_id = p.id
        LEFT JOIN resource res ON res.meta->>'id' = split_part(p.email, '@', 1)
        WHERE sr.reservation_date BETWEEN start_date AND end_date
        AND res.meta->>'grade' IS NOT NULL
        AND (target_grade IS NULL OR (res.meta->>'grade')::int = target_grade)
        GROUP BY sr.reservation_date, (res.meta->>'grade')::int
    ),
    daily_totals AS (
        SELECT
            dgd.reservation_date,
            sum(dgd.total) as total_res,
            sum(dgd.attended_count) as total_att
        FROM daily_grade_data dgd
        GROUP BY dgd.reservation_date
    )
    SELECT
        dt.reservation_date::text,
        dt.total_res::bigint,
        dt.total_att::bigint,
        CASE WHEN dt.total_res > 0
            THEN round((dt.total_att::numeric / dt.total_res::numeric) * 100)::int
            ELSE 0
        END,
        COALESCE(
            jsonb_object_agg(
                dgd.grade,
                jsonb_build_object(
                    'total_reservations', dgd.total,
                    'attended', dgd.attended_count
                )
            ),
            '{}'::jsonb
        )
    FROM daily_totals dt
    JOIN daily_grade_data dgd ON dt.reservation_date = dgd.reservation_date
    GROUP BY dt.reservation_date, dt.total_res, dt.total_att
    ORDER BY dt.reservation_date;
END;
$$;


ALTER FUNCTION "public"."get_daily_statistics"("start_date" "date", "end_date" "date", "target_grade" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_statistics"("p_today" "date", "p_week_start" "date", "p_week_end" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today_applicants INT;
  v_today_by_grade JSONB;
  v_weekly_applicants INT;
  v_weekly_by_grade JSONB;
  v_total_attendance_rate NUMERIC;
  v_attendance_rate_by_grade JSONB;
  
  v_total_attended INT;
  v_valid_total INT;
  v_is_past_closing_time BOOLEAN;
BEGIN
  v_is_past_closing_time := (EXTRACT(HOUR FROM (now() AT TIME ZONE 'Asia/Seoul')) >= 23);
  
  SELECT 
    COALESCE(SUM(count), 0),
    COALESCE(jsonb_object_agg(grade, count), '{}'::jsonb)
  INTO v_today_applicants, v_today_by_grade
  FROM (
    SELECT (res.meta->>'grade')::text as grade, COUNT(*) as count
    FROM seat_reservations r
    JOIN profiles p ON r.student_id = p.id
    LEFT JOIN resource res ON res.meta->>'id' = split_part(p.email, '@', 1)
    WHERE r.reservation_date = p_today
    AND res.meta->>'grade' IS NOT NULL
    GROUP BY res.meta->>'grade'
  ) t;
  
  SELECT 
    COALESCE(SUM(count), 0),
    COALESCE(jsonb_object_agg(grade, count), '{}'::jsonb)
  INTO v_weekly_applicants, v_weekly_by_grade
  FROM (
    SELECT (res.meta->>'grade')::text as grade, COUNT(*) as count
    FROM seat_reservations r
    JOIN profiles p ON r.student_id = p.id
    LEFT JOIN resource res ON res.meta->>'id' = split_part(p.email, '@', 1)
    WHERE r.reservation_date >= p_week_start AND r.reservation_date <= p_week_end
    AND res.meta->>'grade' IS NOT NULL
    GROUP BY res.meta->>'grade'
  ) t;

  WITH attendance_data AS (
    SELECT 
      (res.meta->>'grade')::int as grade,
      CASE WHEN r.is_attended THEN 1 ELSE 0 END as is_attended_val,
      CASE 
        WHEN r.is_attended OR r.reservation_date < p_today OR (r.reservation_date = p_today AND v_is_past_closing_time) THEN 1
        ELSE 0
      END as is_valid_val
    FROM seat_reservations r
    JOIN profiles p ON r.student_id = p.id
    LEFT JOIN resource res ON res.meta->>'id' = split_part(p.email, '@', 1)
    WHERE r.reservation_date <= p_today
    AND res.meta->>'grade' IS NOT NULL
  ),
  aggregated AS (
    SELECT grade, SUM(is_attended_val) as attended_count, SUM(is_valid_val) as valid_count
    FROM attendance_data
    GROUP BY grade
  )
  SELECT 
    COALESCE(SUM(valid_count), 0),
    COALESCE(SUM(attended_count), 0),
    COALESCE(jsonb_object_agg(grade::text, CASE WHEN valid_count > 0 THEN ROUND((attended_count::numeric / valid_count) * 100) ELSE 0 END), '{}'::jsonb)
  INTO v_valid_total, v_total_attended, v_attendance_rate_by_grade
  FROM aggregated;

  IF v_valid_total > 0 THEN
    v_total_attendance_rate := ROUND((v_total_attended::numeric / v_valid_total) * 100);
  ELSE
    v_total_attendance_rate := 0;
  END IF;

  RETURN jsonb_build_object(
    'todayApplicants', COALESCE(v_today_applicants, 0),
    'todayApplicantsByGrade', COALESCE(v_today_by_grade, '{}'::jsonb),
    'weeklyApplicants', COALESCE(v_weekly_applicants, 0),
    'weeklyApplicantsByGrade', COALESCE(v_weekly_by_grade, '{}'::jsonb),
    'averageAttendanceRate', COALESCE(v_total_attendance_rate, 0),
    'attendanceRateByGrade', COALESCE(v_attendance_rate_by_grade, '{}'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_dashboard_statistics"("p_today" "date", "p_week_start" "date", "p_week_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_exam_subject_candidates"("p_grade" integer) RETURNS TABLE("subject" "text", "student_count" integer, "student_codes" "text"[], "is_universal" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid()
      AND role IN ('teacher','admin')
  ) THEN
    RAISE EXCEPTION 'forbidden: teacher or admin role required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH activity_filter AS (
    SELECT unnest(ARRAY[
      '자율활동','자율·자치활동','동아리활동','진로활동',
      '창체','창의적 체험활동','학급자치','진로','봉사활동','봉사'
    ]) AS subject_name
  ),
  -- 학년 재적 전체 (timetable 유무 무관) — 전입생 포함
  all_students AS (
    SELECT COALESCE(r.meta->>'id', r.id::text) AS student_code
    FROM public.resource r
    WHERE r.type = 'student'
      AND COALESCE((r.meta->>'grade')::int, -1) = p_grade
  ),
  student_total AS (
    SELECT COUNT(*)::int AS total FROM all_students
  ),
  student_subjects AS (
    SELECT DISTINCT
      COALESCE(r.meta->>'id', r.id::text) AS student_code,
      e->>'subject' AS subject_name
    FROM public.resource r
    CROSS JOIN LATERAL jsonb_array_elements(r.meta->'timetable') AS e
    WHERE r.type = 'student'
      AND COALESCE((r.meta->>'grade')::int, -1) = p_grade
      AND r.meta ? 'timetable'
      AND (e->>'subject') IS NOT NULL
      AND (e->>'subject') NOT IN (SELECT af.subject_name FROM activity_filter af)
  ),
  subject_agg AS (
    SELECT
      ss.subject_name,
      COUNT(*)::int AS taker_count,
      array_agg(ss.student_code ORDER BY ss.student_code) AS taker_codes,
      (COUNT(*) >= GREATEST(1, FLOOR((SELECT total FROM student_total) * 0.95)::int)) AS universal
    FROM student_subjects ss
    GROUP BY ss.subject_name
    HAVING COUNT(*) > 0
  )
  SELECT
    sa.subject_name AS subject,
    CASE WHEN sa.universal
         THEN (SELECT total FROM student_total)
         ELSE sa.taker_count
    END AS student_count,
    CASE WHEN sa.universal
         THEN (SELECT array_agg(a.student_code ORDER BY a.student_code) FROM all_students a)
         ELSE sa.taker_codes
    END AS student_codes,
    sa.universal AS is_universal
  FROM subject_agg sa
  ORDER BY 2 DESC, sa.subject_name;
END;
$$;


ALTER FUNCTION "public"."get_exam_subject_candidates"("p_grade" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_exam_subject_candidates"("p_grade" integer) IS '학년별 시험 후보 과목 자동 추출. resource.meta.timetable에서 활동 과목 제외. is_universal=true이면 95%+ 학생이 듣는 공통과목.';



CREATE OR REPLACE FUNCTION "public"."get_grade_statistics"("start_date" "date", "end_date" "date", "target_grade" integer DEFAULT NULL::integer) RETURNS TABLE("grade" integer, "total_reservations" bigint, "attended" bigint, "attendance_rate" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        (res.meta->>'grade')::int as grade,
        count(*)::bigint as total_reservations,
        count(*) FILTER (WHERE sr.is_attended)::bigint as attended,
        CASE WHEN count(*) > 0 THEN round((count(*) FILTER (WHERE sr.is_attended)::numeric / count(*)::numeric) * 100)::int ELSE 0 END as attendance_rate
    FROM seat_reservations sr
    JOIN profiles p ON sr.student_id = p.id
    LEFT JOIN resource res ON res.meta->>'id' = split_part(p.email, '@', 1)
    WHERE sr.reservation_date BETWEEN start_date AND end_date
    AND res.meta->>'grade' IS NOT NULL
    AND (target_grade IS NULL OR (res.meta->>'grade')::int = target_grade)
    GROUP BY res.meta->>'grade'
    ORDER BY (res.meta->>'grade')::int;
END;
$$;


