CREATE OR REPLACE FUNCTION "public"."get_inquiry_analysis_cache"("p_cache_key" "text", "p_student_id" "text") RETURNS TABLE("result" "jsonb", "model" "text", "prompt_tokens" integer, "completion_tokens" integer, "created_at" timestamp with time zone, "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.inquiry_design_can_access_student(p_student_id) THEN
    RAISE EXCEPTION 'not allowed to read inquiry cache for student %', p_student_id;
  END IF;

  RETURN QUERY
  SELECT c.result, c.model, c.prompt_tokens, c.completion_tokens, c.created_at, c.expires_at
  FROM public.inquiry_design_llm_cache c
  WHERE c.cache_key = p_cache_key
    AND c.student_id = p_student_id
    AND c.expires_at > now();
END;
$$;


ALTER FUNCTION "public"."get_inquiry_analysis_cache"("p_cache_key" "text", "p_student_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_ipsi_hub_feed"("p_type" "text" DEFAULT 'all'::"text", "p_category" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
declare
  v_items       jsonb;
  v_total       bigint;
  v_video_count bigint;
  v_news_count  bigint;
  v_uid         uuid := auth.uid();
  v_terms       text[];
  v_has_query   boolean;
  v_ids         uuid[];
begin
  -- 검색어 → 소문자 단어 목록(입력 순서 유지 — 발췌는 앞 단어부터 찾는다)
  v_terms := array(
    select lower(x.t)
    from unnest(regexp_split_to_array(btrim(left(coalesce(p_query, ''), 100)), '\s+'))
         with ordinality as x(t, ord)
    where x.t <> ''
    order by x.ord
    limit 8
  );
  v_has_query := cardinality(v_terms) > 0;

  if v_has_query then
    select coalesce(array_agg(d.id), '{}'::uuid[]) into v_ids
    from (
      select v.id,
             translate(lower(concat_ws(' ',
               v.title, v.headline_summary, v.category, v.channel_label,
               (select string_agg(s #>> '{}', ' ')
                  from jsonb_path_query(coalesce(v.meta, '{}'::jsonb), 'strict $.** ? (@.type() == "string")') s),
               v.transcript
             )), E' \t\n\r ', '') as doc
      from public.educational_videos v
      union all
      select n.id,
             translate(lower(concat_ws(' ',
               n.title, n.headline_summary, n.category,
               case n.source when 'jinhak' then '진학사' when 'uway' then '유웨이' when 'riroschool' then '리로스쿨' when 'manual' then '직접 추가' end,
               array_to_string(n.core_points, ' '), array_to_string(n.strategy_implications, ' '),
               array_to_string(n.data_points, ' '), array_to_string(n.cautions, ' '),
               n.content
             )), E' \t\n\r ', '') as doc
      from public.educational_news n
    ) d
    where not exists (select 1 from unnest(v_terms) t where strpos(d.doc, t) = 0);
  end if;

  select count(*) into v_total
  from public.ipsi_hub_feed f
  where (p_type = 'all' or f.kind = p_type)
    and (p_category is null or p_category = '전체' or f.category = p_category)
    and (not v_has_query or f.id = any(v_ids));

  -- 배지: 종류·카테고리와 무관(종전 의미 유지), 검색 중이면 검색에 맞는 것만
  select count(*) filter (where kind = 'video'),
         count(*) filter (where kind = 'news')
    into v_video_count, v_news_count
  from public.ipsi_hub_feed f
  where (not v_has_query or f.id = any(v_ids));

  select coalesce(jsonb_agg(to_jsonb(t) order by t.sort_date desc nulls last), '[]'::jsonb)
    into v_items
  from (
    select
      p.*,
      case
        when p.kind = 'video' and v_uid is not null then exists (
          select 1 from public.video_likes vl
          where vl.video_id = p.id and vl.user_id = v_uid
        )
        else false
      end as is_liked_by_user,
      m.match_field,
      m.match_snippet
    from (
      select f.*
      from public.ipsi_hub_feed f
      where (p_type = 'all' or f.kind = p_type)
        and (p_category is null or p_category = '전체' or f.category = p_category)
        and (not v_has_query or f.id = any(v_ids))
      order by f.sort_date desc nulls last
      limit p_limit offset p_offset
    ) p
    -- 제목·요약에 이미 보이는 단어는 발췌할 필요가 없다 — 안 보이는 단어만 찾는다
    left join lateral (
      select array(
        select t from unnest(v_terms) t
        where strpos(translate(lower(concat_ws(' ', p.title, p.headline_summary)), E' \t\n\r ', ''), t) = 0
      ) as hidden
    ) h on v_has_query
    left join lateral (
      select c.label as match_field, c.snip as match_snippet
      from (
        select 1 as ord, '핵심 내용'::text as label,
               public.ipsi_hub_search_snippet(array_to_string(
                 coalesce(en.core_points, '{}') || coalesce(en.strategy_implications, '{}')
                 || coalesce(en.data_points, '{}') || coalesce(en.cautions, '{}'), ' · '), h.hidden) as snip
        from public.educational_news en where p.kind = 'news' and en.id = p.id
        union all
        select 2, '기사 본문', public.ipsi_hub_search_snippet(en.content, h.hidden)
        from public.educational_news en where p.kind = 'news' and en.id = p.id
        union all
        select 1, '영상 설명', public.ipsi_hub_search_snippet(ev.meta ->> 'description', h.hidden)
        from public.educational_videos ev where p.kind = 'video' and ev.id = p.id
        union all
        select 2, '핵심 내용', public.ipsi_hub_search_snippet(
                 (select string_agg(s #>> '{}', ' · ')
                    from jsonb_path_query(coalesce(ev.meta, '{}'::jsonb) - 'description',
                                          'strict $.** ? (@.type() == "string")') s), h.hidden)
        from public.educational_videos ev where p.kind = 'video' and ev.id = p.id
        union all
        select 3, '자막', public.ipsi_hub_search_snippet(ev.transcript, h.hidden)
        from public.educational_videos ev where p.kind = 'video' and ev.id = p.id
      ) c
      where c.snip is not null
      order by c.ord
      limit 1
    ) m on v_has_query and cardinality(h.hidden) > 0
  ) t;

  return jsonb_build_object(
    'items',        v_items,
    'total_count',  v_total,
    'video_count',  v_video_count,
    'news_count',   v_news_count
  );
end;
$_$;


ALTER FUNCTION "public"."get_ipsi_hub_feed"("p_type" "text", "p_category" "text", "p_limit" integer, "p_offset" integer, "p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_latest_kg_version"("p_student_id" "text") RETURNS TABLE("id" "uuid", "student_id" "text", "version" integer, "kg_json" "jsonb", "source_categories" "text"[], "created_by" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id UUID;
  v_caller_role TEXT;
  v_caller_email TEXT;
BEGIN
  IF p_student_id IS NULL OR p_student_id = '' THEN
    RAISE EXCEPTION 'student_id is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT p.role, p.email INTO v_caller_role, v_caller_email FROM profiles p WHERE p.id = v_caller_id;
  IF v_caller_role NOT IN ('teacher', 'admin') THEN
    IF v_caller_role = 'student' THEN
      IF SPLIT_PART(v_caller_email, '@', 1) <> p_student_id THEN
        RAISE EXCEPTION 'Students can only view their own knowledge graph' USING ERRCODE = 'insufficient_privilege';
      END IF;
    ELSE
      RAISE EXCEPTION 'Unauthorized role' USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  RETURN QUERY SELECT skv.id, skv.student_id, skv.version, skv.kg_json, skv.source_categories, skv.created_by, skv.created_at
    FROM student_kg_versions skv WHERE skv.student_id = p_student_id ORDER BY skv.version DESC LIMIT 1;
END;
$$;


