COMMENT ON FUNCTION "public"."get_latest_kg_version"("p_student_id" "text") IS 'Retrieves the most recent KG version for a student with role-based access control.';



CREATE OR REPLACE FUNCTION "public"."get_latest_timetable_term"() RETURNS TABLE("academic_year" integer, "semester" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH terms AS (
    SELECT DISTINCT t.academic_year, t.semester FROM public.teacher_timetable t
    UNION
    SELECT DISTINCT s.academic_year, s.semester FROM public.student_timetable s
  )
  SELECT terms.academic_year, terms.semester
  FROM terms
  ORDER BY terms.academic_year DESC, terms.semester DESC
  LIMIT 1;
$$;


