COMMENT ON FUNCTION "public"."get_latest_timetable_term"() IS '정규화 시간표에 존재하는 최신 (학년도, 학기). 학사력 미설정 시 클라이언트 폴백용.';



CREATE OR REPLACE FUNCTION "public"."get_meal_duty_history"("p_since" "date", "p_until" "date") RETURNS TABLE("duty_date" "date", "names" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  if not coalesce(public.is_staff_teacher_or_admin(auth.uid()), false) then
    raise exception '교직원만 볼 수 있습니다' using errcode = '42501';
  end if;

  return query
  select (m.starts_at at time zone 'Asia/Seoul')::date as duty_date,
         array(
           select k from jsonb_object_keys(
             case when jsonb_typeof(m.meta -> 'assignee') = 'object' then m.meta -> 'assignee' else '{}'::jsonb end
           ) k order by k
         ) as names
  from meeting m
  where m.kind = 'duty'
    and m.meta ->> 'title' ~ '급식\s*지도'
    and m.starts_at >= (p_since::timestamp at time zone 'Asia/Seoul')
    and m.starts_at <  ((p_until + 1)::timestamp at time zone 'Asia/Seoul')
  order by m.starts_at;
end;
$$;


ALTER FUNCTION "public"."get_meal_duty_history"("p_since" "date", "p_until" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_meal_duty_history"("p_since" "date", "p_until" "date") IS '급식지도 일정의 날짜·담당자 이름(교직원 전용). meeting duty 의 RLS 가 만든 사람·담당자에게만 보여 명단 순환 계산이 틀리는 것을 막는다.';



CREATE OR REPLACE FUNCTION "public"."get_mock_category_stats"("p_year" integer, "p_month" integer, "p_grade" integer, "p_subject" "text" DEFAULT NULL::"text") RETURNS TABLE("subject" "text", "major_category" "text", "problem_count" integer, "avg_national_rate" numeric, "avg_school_rate" numeric, "avg_rate_gap" numeric, "hardest_problem" integer, "easiest_problem" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH item_stats AS (
    SELECT
      mp.subject,
      mp.major_category,
      mp.problem_number,
      mp.correct_rate::DECIMAL AS national_rate,
      mss.school_correct_rate AS school_rate
    FROM mock_problems mp
    LEFT JOIN mock_school_stats mss 
      ON mss.year = mp.year AND mss.month = mp.month 
      AND mss.student_grade = mp.student_grade
      AND mss.subject = mp.subject AND mss.problem_number = mp.problem_number
    WHERE mp.year = p_year AND mp.month = p_month AND mp.student_grade = p_grade
      AND (p_subject IS NULL OR mp.subject = p_subject)
      AND mp.major_category IS NOT NULL
  )
  SELECT
    subject,
    major_category,
    COUNT(*)::INT AS problem_count,
    ROUND(AVG(national_rate), 1) AS avg_national_rate,
    ROUND(AVG(school_rate), 1) AS avg_school_rate,
    ROUND(AVG(school_rate) - AVG(national_rate), 1) AS avg_rate_gap,
    (array_agg(problem_number ORDER BY COALESCE(school_rate, national_rate) ASC))[1] AS hardest_problem,
    (array_agg(problem_number ORDER BY COALESCE(school_rate, national_rate) DESC))[1] AS easiest_problem
  FROM item_stats
  GROUP BY subject, major_category
  ORDER BY subject, avg_national_rate ASC;
$$;


ALTER FUNCTION "public"."get_mock_category_stats"("p_year" integer, "p_month" integer, "p_grade" integer, "p_subject" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_mock_category_stats"("p_year" integer, "p_month" integer, "p_grade" integer, "p_subject" "text") IS '모의고사 영역별 집계 통계';



CREATE OR REPLACE FUNCTION "public"."get_mock_item_analysis"("p_year" integer, "p_month" integer, "p_grade" integer, "p_subject" "text" DEFAULT NULL::"text") RETURNS TABLE("subject" "text", "problem_number" integer, "major_category" "text", "sub_category" "text", "difficulty_level" "text", "point" integer, "national_correct_rate" numeric, "school_correct_rate" numeric, "school_total_students" integer, "school_correct_count" integer, "rate_gap" numeric, "answer_distribution" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    mp.subject,
    mp.problem_number,
    mp.major_category,
    mp.sub_category,
    mp.difficulty_level,
    COALESCE(mp.point, 2) AS point,
    mp.correct_rate::DECIMAL AS national_correct_rate,
    mss.school_correct_rate,
    mss.total_students AS school_total_students,
    mss.correct_count AS school_correct_count,
    CASE 
      WHEN mss.school_correct_rate IS NOT NULL AND mp.correct_rate IS NOT NULL 
      THEN mss.school_correct_rate - mp.correct_rate::DECIMAL
      ELSE NULL 
    END AS rate_gap,
    mss.answer_distribution
  FROM mock_problems mp
  LEFT JOIN mock_school_stats mss 
    ON mss.year = mp.year 
    AND mss.month = mp.month 
    AND mss.student_grade = mp.student_grade
    AND mss.subject = mp.subject
    AND mss.problem_number = mp.problem_number
  WHERE mp.year = p_year
    AND mp.month = p_month
    AND mp.student_grade = p_grade
    AND (p_subject IS NULL OR mp.subject = p_subject)
  ORDER BY mp.subject, mp.problem_number;
$$;


ALTER FUNCTION "public"."get_mock_item_analysis"("p_year" integer, "p_month" integer, "p_grade" integer, "p_subject" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_mock_item_analysis"("p_year" integer, "p_month" integer, "p_grade" integer, "p_subject" "text") IS '모의고사 문항별 분석 (학교 vs 전국 정답률)';



CREATE OR REPLACE FUNCTION "public"."get_monthly_statistics"("start_date" "date", "end_date" "date", "target_grade" integer DEFAULT NULL::integer) RETURNS TABLE("month" "text", "total_reservations" bigint, "attended" bigint, "attendance_rate" integer, "by_grade" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    WITH monthly_data AS (
        SELECT
            to_char(sr.reservation_date, 'YYYY-MM') as m,
            (res.meta->>'grade')::int as grade,
            count(*) as total,
            count(*) FILTER (WHERE sr.is_attended) as attended_count
        FROM seat_reservations sr
        JOIN profiles p ON sr.student_id = p.id
        LEFT JOIN resource res ON res.meta->>'id' = split_part(p.email, '@', 1)
        WHERE sr.reservation_date BETWEEN start_date AND end_date
        AND res.meta->>'grade' IS NOT NULL
        AND (target_grade IS NULL OR (res.meta->>'grade')::int = target_grade)
        GROUP BY to_char(sr.reservation_date, 'YYYY-MM'), res.meta->>'grade'
    ),
    monthly_totals AS (
        SELECT m, sum(total) as total_res, sum(attended_count) as total_att
        FROM monthly_data
        GROUP BY m
    )
    SELECT
        mt.m as month,
        mt.total_res::bigint,
        mt.total_att::bigint,
        CASE WHEN mt.total_res > 0 THEN round((mt.total_att::numeric / mt.total_res::numeric) * 100)::int ELSE 0 END,
        jsonb_object_agg(
            md.grade,
            jsonb_build_object(
                'totalReservations', md.total,
                'attended', md.attended_count,
                'attendanceRate', CASE WHEN md.total > 0 THEN round((md.attended_count::numeric / md.total::numeric) * 100)::int ELSE 0 END
            )
        )
    FROM monthly_totals mt
    JOIN monthly_data md ON mt.m = md.m
    GROUP BY mt.m, mt.total_res, mt.total_att
    ORDER BY mt.m;
END;
$$;


ALTER FUNCTION "public"."get_monthly_statistics"("start_date" "date", "end_date" "date", "target_grade" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_monthly_temperature_ranking"("p_month" "date") RETURNS TABLE("rank" bigint, "student_id" "uuid", "name" "text", "grade" integer, "class" integer, "monthly_change" numeric, "attended_days" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH month_reservations AS (
    SELECT sr.student_id, sr.reservation_date, sr.is_attended, sr.feedback_rating
    FROM seat_reservations sr
    WHERE sr.reservation_date >= date_trunc('month', p_month)::date
      AND sr.reservation_date < (date_trunc('month', p_month) + interval '1 month')::date
  ),
  daily_stats AS (
    SELECT
      mr.student_id,
      mr.reservation_date,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE mr.is_attended = true) AS attended,
      COUNT(*) FILTER (WHERE mr.is_attended = false AND mr.reservation_date < CURRENT_DATE) AS absent
    FROM month_reservations mr
    GROUP BY mr.student_id, mr.reservation_date
  ),
  student_scores AS (
    SELECT
      ds.student_id,
      SUM(
        (CAST(ds.attended AS float) * 0.5 / ds.total) -
        (CAST(ds.absent AS float) * 1.0 / ds.total)
      ) AS score_change,
      COUNT(*) FILTER (WHERE ds.attended > 0)::integer AS attended_days
    FROM daily_stats ds
    GROUP BY ds.student_id
  ),
  feedback_bonus AS (
    SELECT mr.student_id, COUNT(*) * 0.1 AS bonus
    FROM month_reservations mr
    WHERE mr.feedback_rating IS NOT NULL
    GROUP BY mr.student_id
  ),
  scored AS (
    SELECT
      p.id AS student_id,
      COALESCE(p.name, sbi.name) AS name,
      sbi.grade,
      sbi.class_num AS class,
      ROUND(CAST(ss.score_change + COALESCE(fb.bonus, 0) AS numeric), 1) AS monthly_change,
      ss.attended_days
    FROM student_scores ss
    JOIN profiles p ON p.id = ss.student_id
    LEFT JOIN feedback_bonus fb ON fb.student_id = ss.student_id
    LEFT JOIN student_basic_info sbi ON sbi.id = split_part(p.email, '@', 1)
    WHERE p.role = 'student'
  )
  SELECT
    RANK() OVER (ORDER BY s.monthly_change DESC) AS rank,
    s.student_id,
    s.name,
    s.grade,
    s.class,
    s.monthly_change,
    s.attended_days
  FROM scored s
  ORDER BY s.monthly_change DESC, s.attended_days DESC, s.name ASC;
$$;


ALTER FUNCTION "public"."get_monthly_temperature_ranking"("p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_course_selection"("p_round_id" "uuid", "p_student_code" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
WITH sub AS (
  SELECT * FROM public.course_selection_submission
   WHERE round_id = p_round_id AND student_code = p_student_code
   LIMIT 1
)
SELECT jsonb_build_object(
  'submission', (SELECT to_jsonb(s) FROM sub s),
  'items', COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', i.id,
      'slot_id', i.slot_id,
      'group_id', sl.group_id,
      'selectable_subject_id', i.selectable_subject_id,
      'subject_name', i.subject_name,
      'semester', i.semester,
      'priority', i.priority,
      'category_code', i.category_code,
      'created_at', i.created_at
    ))
    FROM public.course_selection_item i
    JOIN public.course_selection_slot sl ON sl.id = i.slot_id
    WHERE i.submission_id = (SELECT id FROM sub)
  ), '[]'::jsonb),
  'saved_group_ids', COALESCE((
    SELECT jsonb_agg(DISTINCT sl.group_id)
    FROM public.course_selection_item i
    JOIN public.course_selection_slot sl ON sl.id = i.slot_id
    WHERE i.submission_id = (SELECT id FROM sub)
  ), '[]'::jsonb)
);
$$;


ALTER FUNCTION "public"."get_my_course_selection"("p_round_id" "uuid", "p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_purchase_order_progress"("p_page_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("request_id" "uuid", "row_id" "text", "line_name" "text", "batch_title" "text", "batch_status" "text", "status_updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select li.request_id, li.row_id, l.name, b.title, b.status, b.status_updated_at
    from public.purchase_order_line_items li
    join public.purchase_order_lines l on l.id = li.line_id
    join public.purchase_order_batches b on b.id = l.batch_id
    join public.purchase_requests r on r.id = li.request_id
   where auth.uid() is not null
     and (p_page_id is null or li.page_id = p_page_id)
     and r.requester_id in (select public.current_actor_resource_ids());
$$;


ALTER FUNCTION "public"."get_my_purchase_order_progress"("p_page_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_my_tasks_jsonb"("p_user_id" "uuid", "p_status" "text" DEFAULT NULL::"text", "p_include_managed" boolean DEFAULT true) RETURNS TABLE("summary" "jsonb", "assigned_tasks" "jsonb", "managed_tasks" "jsonb", "urgent_tasks" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    user_resource_id uuid;
    assigned_task_data jsonb := '[]'::jsonb;
    managed_task_data jsonb := '[]'::jsonb;
    urgent_task_data jsonb := '[]'::jsonb;
    summary_data jsonb;
BEGIN
    -- Get user's resource ID from user_resource table first
    SELECT ur.resource_id INTO user_resource_id
    FROM user_resource ur
    WHERE ur.user_id = p_user_id
    LIMIT 1;

    -- If not found in user_resource, try to find by profile name matching resource name
    IF user_resource_id IS NULL THEN
        SELECT r.id INTO user_resource_id
        FROM profiles p
        JOIN resource r ON r.name = p.name
        WHERE p.id = p_user_id
          AND p.role = 'teacher'
        LIMIT 1;
    END IF;

    -- If still not found, return empty results
    IF user_resource_id IS NULL THEN
        RETURN QUERY SELECT
            '{"total": 0, "assigned": 0, "managed": 0, "completed": 0, "overdue": 0}'::jsonb,
            '[]'::jsonb,
            '[]'::jsonb,
            '[]'::jsonb;
        RETURN;
    END IF;

    -- 담당 할 일 — 취소된 업무만 뺀다(완료된 업무의 할 일도 기록으로 남긴다, 2026-10-05).
    -- 보이는 날이 아직 안 된 할 일은 뺀다. event_status 로 화면이 «끝난 업무»를 가른다.
    -- ⚠️ 완료된 업무의 할 일은 status 를 'completed' 로 싣는다 — «매니저가 끝내면 끝난 것»(2026-08-22 결정)과
    --    같은 원리이고, 이렇게 해야 이 함수를 읽는 **모든 화면(배포 전 옛 코드 포함)**이 그것을 남은 일로
    --    세지 않는다. 운영 실측: 완료된 업무 안에 미완료 상태의 할 일 13건(담당자 미완료 3건) — 그대로 실으면
    --    홈에 «기한 지남»으로 떠오른다. 원래 값은 task_status 로 함께 싣는다.
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', t.id,
            'title', t.title,
            'description', t.description,
            'type', t.type,
            'status', CASE WHEN e.status = 'completed' AND t.status <> 'cancelled' THEN 'completed' ELSE t.status END,
            'task_status', t.status,
            'due_date', t.due_date,
            'event_id', t.event_id,
            'event_name', e.name,
            'event_description', e.description,
            'event_status', e.status,
            'keywords', t.keywords,
            'meta', t.meta,
            'created_at', t.created_at,
            'updated_at', t.updated_at,
            'order_index', t.order_index
        )
    ), '[]'::jsonb) INTO assigned_task_data
    FROM task t
    JOIN work e ON t.event_id = e.id
    WHERE e.status <> 'cancelled'
      AND public.task_visible_to_assignees(t.meta)
      AND (p_status IS NULL OR t.status = p_status)
      AND EXISTS (
          SELECT 1
          FROM jsonb_array_elements(t.meta->'assignees') AS assignee
          WHERE (assignee->>'id')::uuid = user_resource_id
      );

    -- 매니저 할 일 — 보이는 날과 무관하게 언제나 본다
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', t.id,
            'title', t.title,
            'description', t.description,
            'type', t.type,
            'status', t.status,
            'due_date', t.due_date,
            'event_id', t.event_id,
            'event_name', e.name,
            'event_description', e.description,
            'event_status', e.status,
            'keywords', t.keywords,
            'meta', t.meta,
            'created_at', t.created_at,
            'updated_at', t.updated_at,
            'order_index', t.order_index
        )
    ), '[]'::jsonb) INTO managed_task_data
    FROM task t
    JOIN work e ON t.event_id = e.id
    WHERE e.status IN ('active', 'pending')
      AND (p_status IS NULL OR t.status = p_status)
      AND e.manager_id = user_resource_id
      AND p_include_managed = true
      AND NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements(t.meta->'assignees') AS assignee
          WHERE (assignee->>'id')::uuid = user_resource_id
      );

    -- 급한 할 일 (마감 3일 이내 또는 지남) — 진행 중 업무만. 담당자 쪽은 보이는 날을 지킨다
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', t.id,
            'title', t.title,
            'description', t.description,
            'type', t.type,
            'status', t.status,
            'due_date', t.due_date,
            'event_id', t.event_id,
            'event_name', e.name,
            'event_description', e.description,
            'event_status', e.status,
            'keywords', t.keywords,
            'meta', t.meta,
            'created_at', t.created_at,
            'updated_at', t.updated_at,
            'order_index', t.order_index
        )
    ), '[]'::jsonb) INTO urgent_task_data
    FROM task t
    JOIN work e ON t.event_id = e.id
    WHERE e.status IN ('active', 'pending')
      AND t.due_date IS NOT NULL
      AND t.due_date < NOW() + INTERVAL '3 days'
      AND t.status != 'completed'
      AND (
          (
              public.task_visible_to_assignees(t.meta)
              AND EXISTS (
                  SELECT 1
                  FROM jsonb_array_elements(t.meta->'assignees') AS assignee
                  WHERE (assignee->>'id')::uuid = user_resource_id
              )
          )
          OR (e.manager_id = user_resource_id AND p_include_managed = true)
      );

    -- 요약 — 진행 중 업무만(종전과 같다). 담당 쪽은 보이는 날을 지킨다
    WITH task_counts AS (
        SELECT
            COUNT(*) FILTER (WHERE role = 'assigned') as assigned_count,
            COUNT(*) FILTER (WHERE role = 'managed') as managed_count,
            COUNT(*) FILTER (WHERE status = 'completed') as completed_count,
            COUNT(*) FILTER (WHERE due_date < NOW() AND status != 'completed') as overdue_count
        FROM (
            SELECT 'assigned' as role, t.status, t.due_date
            FROM task t
            JOIN work e ON t.event_id = e.id
            WHERE e.status IN ('active', 'pending')
              AND public.task_visible_to_assignees(t.meta)
              AND EXISTS (
                  SELECT 1
                  FROM jsonb_array_elements(t.meta->'assignees') AS assignee
                  WHERE (assignee->>'id')::uuid = user_resource_id
              )

            UNION ALL

            SELECT 'managed' as role, t.status, t.due_date
            FROM task t
            JOIN work e ON t.event_id = e.id
            WHERE e.status IN ('active', 'pending')
              AND e.manager_id = user_resource_id
              AND p_include_managed = true
              AND NOT EXISTS (
                  SELECT 1
                  FROM jsonb_array_elements(t.meta->'assignees') AS assignee
                  WHERE (assignee->>'id')::uuid = user_resource_id
              )
        ) combined
    )
    SELECT jsonb_build_object(
        'total', tc.assigned_count + tc.managed_count,
        'assigned', tc.assigned_count,
        'managed', tc.managed_count,
        'completed', tc.completed_count,
        'overdue', tc.overdue_count
    ) INTO summary_data
    FROM task_counts tc;

    -- Return results as table
    RETURN QUERY SELECT
        COALESCE(summary_data, '{"total": 0, "assigned": 0, "managed": 0, "completed": 0, "overdue": 0}'::jsonb),
        assigned_task_data,
        managed_task_data,
        urgent_task_data;
END;
$$;


ALTER FUNCTION "public"."get_my_tasks_jsonb"("p_user_id" "uuid", "p_status" "text", "p_include_managed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_next_kg_version"("p_student_id" "text") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(MAX(version), 0) + 1
  FROM student_kg_versions
  WHERE student_id = p_student_id;
$$;


ALTER FUNCTION "public"."get_next_kg_version"("p_student_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_overall_statistics"("start_date" "date", "end_date" "date", "target_grade" integer DEFAULT NULL::integer) RETURNS TABLE("total_reservations" bigint, "total_attended" bigint, "total_absent" bigint, "overall_attendance_rate" integer, "unique_students" bigint, "active_rooms" bigint)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    today date := current_date;
    is_past_closing_time boolean := extract(hour from now()) >= 23;
BEGIN
    RETURN QUERY
    SELECT
        count(*)::bigint,
        count(*) FILTER (WHERE sr.is_attended)::bigint,
        count(*) FILTER (WHERE NOT sr.is_attended AND (sr.reservation_date < today OR (sr.reservation_date = today AND is_past_closing_time)))::bigint,
        CASE
            WHEN (count(*) FILTER (WHERE sr.is_attended) + count(*) FILTER (WHERE NOT sr.is_attended AND (sr.reservation_date < today OR (sr.reservation_date = today AND is_past_closing_time)))) > 0 THEN
                round((count(*) FILTER (WHERE sr.is_attended)::numeric / (count(*) FILTER (WHERE sr.is_attended) + count(*) FILTER (WHERE NOT sr.is_attended AND (sr.reservation_date < today OR (sr.reservation_date = today AND is_past_closing_time))))::numeric) * 100)::int
            ELSE 0
        END,
        count(DISTINCT sr.student_id)::bigint,
        count(DISTINCT sr.room_id)::bigint
    FROM seat_reservations sr
    JOIN profiles p ON sr.student_id = p.id
    LEFT JOIN resource res ON res.meta->>'id' = split_part(p.email, '@', 1)
    WHERE sr.reservation_date BETWEEN start_date AND end_date
    AND (target_grade IS NULL OR (res.meta->>'grade')::int = target_grade);
END;
$$;


ALTER FUNCTION "public"."get_overall_statistics"("start_date" "date", "end_date" "date", "target_grade" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_past_class_academic_summary"("p_past_grade" integer, "p_entry_year" integer DEFAULT NULL::integer) RETURNS TABLE("past_class" integer, "student_count" bigint, "subject_group" "text", "avg_rank" numeric, "std_rank" numeric, "best_rank" numeric, "worst_rank" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    (gi->>'class')::int AS past_class,
    COUNT(DISTINCT sbi.id) AS student_count,
    saf.subject_group,
    ROUND(AVG(saf.rank)::numeric, 2) AS avg_rank,
    ROUND(STDDEV(saf.rank)::numeric, 2) AS std_rank,
    ROUND(MIN(saf.rank)::numeric, 2) AS best_rank,
    ROUND(MAX(saf.rank)::numeric, 2) AS worst_rank
  FROM student_basic_info sbi
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(sbi.grade_info, '[]'::jsonb)) AS gi
  JOIN student_academic_flat saf ON saf.student_code = sbi.id
  WHERE (gi->>'grade')::int = p_past_grade
    AND saf.grade = p_past_grade
    AND saf.category = 'regular'
    AND saf.rank IS NOT NULL
    AND jsonb_typeof(sbi.grade_info) = 'array'
    AND (p_entry_year IS NULL OR sbi.id LIKE LPAD((p_entry_year % 100)::text, 2, '0') || '-%')
  GROUP BY (gi->>'class')::int, saf.subject_group
  ORDER BY (gi->>'class')::int, saf.subject_group;
$$;


ALTER FUNCTION "public"."get_past_class_academic_summary"("p_past_grade" integer, "p_entry_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rescue_crisis_dashboard"() RETURNS TABLE("student_code" "text", "name" "text", "grade" integer, "class_num" integer, "number_in_class" integer, "homeroom_name" "text", "tag_keys" "text"[], "status" "public"."rescue_status", "last_note_at" timestamp with time zone, "note_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH notes AS (
    SELECT n.student_code, MAX(n.occurred_at) AS last_note_at, COUNT(*) AS note_count
    FROM rescue_notes n
    WHERE n.visibility = 'team'
      OR (n.visibility = 'counselor_author'
          AND (n.created_by = auth.uid() OR current_rescue_role() = 'counselor'))
      OR (n.visibility = 'author_only' AND n.created_by = auth.uid())
      OR EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
    GROUP BY n.student_code
  ),
  visible_students AS (
    SELECT DISTINCT s.id, s.name, s.grade, s.class_num, s.number
    FROM student_basic_info s
    WHERE can_care_student(s.id)
      AND (
        EXISTS (SELECT 1 FROM rescue_tags rt WHERE rt.student_code = s.id)
        OR EXISTS (SELECT 1 FROM rescue_student_status ss
                   WHERE ss.student_code = s.id AND ss.status <> 'closed')
        -- 태그·상태가 없어도 가시성 규칙을 통과한 상담 노트가 있으면 포함
        OR EXISTS (SELECT 1 FROM notes nn WHERE nn.student_code = s.id)
      )
  ),
  tagged AS (
    SELECT t.student_code, array_agg(t.tag_key ORDER BY td.sort_order) AS tag_keys
    FROM rescue_tags t
    JOIN rescue_tag_definitions td ON td.key = t.tag_key
    GROUP BY t.student_code
  ),
  homerooms AS (
    SELECT r.meta->>'grade' AS g, r.meta->>'class_number' AS c, r.name AS teacher_name
    FROM resource r
    WHERE r.meta->>'grade' IS NOT NULL AND r.meta->>'class_number' IS NOT NULL
  )
  SELECT
    vs.id, vs.name, vs.grade, vs.class_num, vs.number,
    h.teacher_name,
    COALESCE(tagged.tag_keys, '{}'::text[]),
    COALESCE(ss.status, 'closed'::rescue_status),
    notes.last_note_at,
    COALESCE(notes.note_count, 0)
  FROM visible_students vs
  LEFT JOIN tagged ON tagged.student_code = vs.id
  LEFT JOIN rescue_student_status ss ON ss.student_code = vs.id
  LEFT JOIN notes ON notes.student_code = vs.id
  LEFT JOIN homerooms h ON h.g = vs.grade::text AND h.c = vs.class_num::text
  ORDER BY notes.last_note_at DESC NULLS LAST, vs.grade, vs.class_num, vs.number;
$$;


ALTER FUNCTION "public"."get_rescue_crisis_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rescue_roster"("p_grade" integer, "p_class" integer) RETURNS TABLE("student_code" "text", "name" "text", "grade" integer, "class_num" integer, "number_in_class" integer, "tag_keys" "text"[], "status" "public"."rescue_status", "last_note_at" timestamp with time zone, "note_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH base AS (
    -- 재학생 명단/총원: resource(type='student') 의 현재 학년·반 기준
    SELECT
      r.meta->>'id'            AS id,
      r.name                   AS name,
      (r.meta->>'grade')::int  AS grade,
      (r.meta->>'class')::int  AS class_num,
      (r.meta->>'number')::int AS number
    FROM resource r
    WHERE r.type = 'student'
      AND r.meta->>'id' IS NOT NULL
      AND r.meta->>'grade' ~ '^[0-9]+$'
      AND r.meta->>'class' ~ '^[0-9]+$'
      AND (r.meta->>'grade')::int = p_grade
      AND (r.meta->>'class')::int = p_class
      AND can_care_student(r.meta->>'id')
  ),
  tagged AS (
    SELECT t.student_code, array_agg(t.tag_key ORDER BY td.sort_order) AS tag_keys
    FROM rescue_tags t
    JOIN rescue_tag_definitions td ON td.key = t.tag_key
    GROUP BY t.student_code
  ),
  notes AS (
    SELECT n.student_code, MAX(n.occurred_at) AS last_note_at, COUNT(*) AS note_count
    FROM rescue_notes n
    WHERE n.visibility = 'team'
      OR (n.visibility = 'counselor_author'
          AND (n.created_by = auth.uid() OR current_rescue_role() = 'counselor'))
      OR (n.visibility = 'author_only' AND n.created_by = auth.uid())
      OR EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin')
    GROUP BY n.student_code
  )
  SELECT
    b.id, b.name, b.grade, b.class_num, b.number,
    COALESCE(tagged.tag_keys, '{}'::text[]),
    COALESCE(ss.status, 'closed'::rescue_status),
    notes.last_note_at,
    COALESCE(notes.note_count, 0)
  FROM base b
  LEFT JOIN tagged ON tagged.student_code = b.id
  LEFT JOIN rescue_student_status ss ON ss.student_code = b.id
  LEFT JOIN notes ON notes.student_code = b.id
  ORDER BY b.number;
$_$;


ALTER FUNCTION "public"."get_rescue_roster"("p_grade" integer, "p_class" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_room_statistics"("start_date" "date", "end_date" "date", "target_grade" integer DEFAULT NULL::integer) RETURNS TABLE("room_id" "uuid", "room_name" "text", "grade" integer, "total_reservations" bigint, "attended" bigint, "attendance_rate" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        sr.room_id,
        r.name,
        r.grade,
        count(*)::bigint,
        count(*) FILTER (WHERE sr.is_attended)::bigint,
        CASE WHEN count(*) > 0 THEN round((count(*) FILTER (WHERE sr.is_attended)::numeric / count(*)::numeric) * 100)::int ELSE 0 END
    FROM seat_reservations sr
    JOIN study_rooms r ON sr.room_id = r.id
    JOIN profiles p ON sr.student_id = p.id
    LEFT JOIN resource res ON res.meta->>'id' = split_part(p.email, '@', 1)
    WHERE sr.reservation_date BETWEEN start_date AND end_date
    AND (target_grade IS NULL OR (res.meta->>'grade')::int = target_grade)
    GROUP BY sr.room_id, r.name, r.grade
    ORDER BY r.grade, r.name;
END;
$$;


ALTER FUNCTION "public"."get_room_statistics"("start_date" "date", "end_date" "date", "target_grade" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_school_exam_student_overview"("p_student_code" "text", "p_academic_year" integer, "p_semester" integer, "p_exam_round" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
with mine as (
  select grade, subject_section, subject_name, total_score, selective_score, descriptive_score
  from public.school_exam_result
  where student_code = p_student_code
    and academic_year = p_academic_year
    and semester = p_semester
    and exam_round = p_exam_round
),
taken as (
  select r.grade, r.subject_section, r.student_code, r.total_score
  from public.school_exam_result r
  join mine m on m.grade = r.grade and m.subject_section = r.subject_section
  where r.academic_year = p_academic_year
    and r.semester = p_semester
    and r.exam_round = p_exam_round
),
cohort as (
  select * from taken where total_score is not null
),
taken_stats as (
  select grade, subject_section, count(*)::int as taken_n
  from taken group by grade, subject_section
),
stats as (
  select grade,
         subject_section,
         count(*)::int as n,
         min(total_score) as lo,
         max(total_score) as hi,
         round(avg(total_score), 2) as avg,
         round(percentile_cont(0.25) within group (order by total_score)::numeric, 2) as q1,
         round(percentile_cont(0.50) within group (order by total_score)::numeric, 2) as median,
         round(percentile_cont(0.75) within group (order by total_score)::numeric, 2) as q3
  from cohort
  group by grade, subject_section
),
cohort_ranked as (
  select grade, subject_section, student_code,
         rank() over (partition by grade, subject_section order by total_score desc) as rnk,
         count(*) over (partition by grade, subject_section) as cohort_count
  from cohort
),
ranked as (
  select grade, subject_section, rnk, cohort_count
  from cohort_ranked
  where student_code = p_student_code
)
select coalesce(jsonb_agg(
  jsonb_build_object(
    'subject_section', m.subject_section,
    'subject_name', m.subject_name,
    'grade', m.grade,
    'total_score', m.total_score,
    'selective_score', m.selective_score,
    'descriptive_score', m.descriptive_score,
    'cohort_count', coalesce(s.n, 0),
    'taken_count', coalesce(t.taken_n, 0),
    'lo', s.lo,
    'q1', s.q1,
    'median', s.median,
    'q3', s.q3,
    'hi', s.hi,
    'avg', s.avg,
    'rank', r.rnk,
    'percentile', case when r.cohort_count > 0
                       then round((r.rnk::numeric / r.cohort_count) * 100, 1)
                       else null end
  ) order by m.subject_name
), '[]'::jsonb)
from mine m
left join stats s on s.grade = m.grade and s.subject_section = m.subject_section
left join taken_stats t on t.grade = m.grade and t.subject_section = m.subject_section
left join ranked r on r.grade = m.grade and r.subject_section = m.subject_section;
$$;


ALTER FUNCTION "public"."get_school_exam_student_overview"("p_student_code" "text", "p_academic_year" integer, "p_semester" integer, "p_exam_round" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_school_exam_subject_analysis"("p_student_code" "text", "p_academic_year" integer, "p_semester" integer, "p_exam_round" integer, "p_grade" integer, "p_subject_section" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
with results as (
  select *
  from public.school_exam_result
  where academic_year = p_academic_year
    and semester = p_semester
    and exam_round = p_exam_round
    and grade = p_grade
    and subject_section = p_subject_section
),
scored as (
  select * from results where total_score is not null
),
ranked as (
  select student_code,
         total_score,
         rank() over (order by total_score desc) as rnk,
         count(*) over () as cohort_count
  from scored
),
items as (
  select ord::int as problem_number,
         count(*) filter (where c) as correct_count,
         count(*) as answered_count
  from results r, unnest(r.correct) with ordinality as t(c, ord)
  group by ord
),
joined as (
  select i.problem_number,
         i.correct_count,
         i.answered_count,
         q.content_area,
         q.standard_code,
         q.standard_text
  from items i
  left join public.school_exam_question q
    on q.academic_year = p_academic_year
   and q.semester = p_semester
   and q.exam_round = p_exam_round
   and q.grade = p_grade
   and q.subject_section = p_subject_section
   and q.answer_type = '선택형'
   and q.problem_number = i.problem_number
),
areas as (
  select content_area,
         sum(correct_count) as correct_count,
         sum(answered_count) as answered_count
  from joined
  where content_area is not null
  group by content_area
),
standards as (
  select standard_code,
         max(standard_text) as standard_text,
         sum(correct_count) as correct_count,
         sum(answered_count) as answered_count
  from joined
  where standard_code is not null
  group by standard_code
)
select jsonb_build_object(
  'cohort', (
    select jsonb_build_object(
      'count', count(*),
      'avg', round(avg(total_score), 2),
      'max', max(total_score),
      'min', min(total_score),
      'stddev', round(coalesce(stddev_samp(total_score), 0), 2)
    ) from scored
  ),
  'student', (
    select jsonb_build_object(
      'total_score', total_score,
      'rank', rnk,
      'cohort_count', cohort_count,
      'percentile', round((rnk::numeric / nullif(cohort_count, 0)) * 100, 1)
    ) from ranked where student_code = p_student_code
  ),
  'items', coalesce((
    select jsonb_agg(jsonb_build_object(
      'problem_number', problem_number,
      'correct_count', correct_count,
      'answered_count', answered_count,
      'correct_rate', round((correct_count::numeric / nullif(answered_count, 0)) * 100, 1)
    ) order by problem_number) from joined
  ), '[]'::jsonb),
  'areas', coalesce((
    select jsonb_agg(jsonb_build_object(
      'content_area', content_area,
      'correct_count', correct_count,
      'answered_count', answered_count,
      'wrong_rate', round(((answered_count - correct_count)::numeric / nullif(answered_count, 0)) * 100, 1)
    ) order by content_area) from areas
  ), '[]'::jsonb),
  'standards', coalesce((
    select jsonb_agg(jsonb_build_object(
      'standard_code', standard_code,
      'standard_text', standard_text,
      'correct_count', correct_count,
      'answered_count', answered_count,
      'wrong_rate', round(((answered_count - correct_count)::numeric / nullif(answered_count, 0)) * 100, 1)
    ) order by standard_code) from standards
  ), '[]'::jsonb)
);
$$;


ALTER FUNCTION "public"."get_school_exam_subject_analysis"("p_student_code" "text", "p_academic_year" integer, "p_semester" integer, "p_exam_round" integer, "p_grade" integer, "p_subject_section" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_school_life_assignment_courses"() RETURNS TABLE("id" "uuid", "academic_year" integer, "semester" integer, "grade" integer, "subject_name" "text", "class_label" "text", "classroom" "text", "teacher_name" "text", "is_enrolled" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select c.id, c.academic_year, c.semester, c.grade,
    c.subject_name, c.class_label, c.classroom, c.teacher_name,
    c.id in (select school_life_private.enrolled_course_ids()) as is_enrolled
  from public.course_offering c
  cross join (select school_life_private.current_context() as ctx) actor
  join public.system_settings settings on settings.setting_key = 'academic_term'
  where (select auth.uid()) is not null and actor.ctx->>'role' = 'student'
    and c.academic_year = (settings.setting_value->>'year')::integer
    and c.semester = (settings.setting_value->>'semester')::integer
    and c.academic_year = (actor.ctx->>'academic_year')::integer
    and exists (select 1 from jsonb_array_elements(actor.ctx->'classes') cls where (cls->>'grade')::integer = c.grade)
    and exists (select 1 from public.student_enrollment e where e.course_offering_id = c.id
      and e.academic_year = c.academic_year and e.semester = c.semester)
  order by is_enrolled desc, c.subject_name, c.class_label, c.teacher_name;
$$;


