CREATE OR REPLACE FUNCTION "public"."get_section_students"("p_teacher_name" "text", "p_day_of_week" integer, "p_period" integer, "p_academic_year" integer, "p_semester" integer) RETURNS TABLE("resource_id" "uuid", "student_name" "text", "student_code" "text", "grade" integer, "class_num" integer, "number" integer, "picture" "text", "subject" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = auth.uid() AND role IN ('teacher', 'admin')
  ) THEN
    RETURN;
  END IF;

  IF p_teacher_name IS NULL OR p_day_of_week IS NULL OR p_period IS NULL
     OR p_academic_year IS NULL OR p_semester IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT f.resource_id, f.student_name, f.student_code, f.grade,
         f.class_num, f.number, f.picture, f.subject
  FROM public.student_timetable_flat f
  WHERE f.teacher_name  = p_teacher_name
    AND f.day_of_week   = p_day_of_week
    AND f.period        = p_period
    AND f.academic_year = p_academic_year
    AND f.semester      = p_semester
  ORDER BY f.class_num ASC NULLS LAST, f.number ASC NULLS LAST;
END;
$$;


