COMMENT ON FUNCTION "public"."get_section_students"("p_teacher_name" "text", "p_day_of_week" integer, "p_period" integer, "p_academic_year" integer, "p_semester" integer) IS '(교사, 요일, 교시, 학년도, 학기) 수업의 학생 명단. student_timetable_flat MV 는 authenticated 에 GRANT 되지 않아 이 DEFINER RPC 로만 읽는다.';



CREATE OR REPLACE FUNCTION "public"."get_self_study_supervision_history"("p_grade" integer, "p_since" "date", "p_until" "date") RETURNS TABLE("meeting_id" "uuid", "duty_date" "date", "slot" "text", "with_morning" boolean, "names" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  if not coalesce(public.is_staff_teacher_or_admin(auth.uid()), false) then
    raise exception '교직원만 볼 수 있습니다' using errcode = '42501';
  end if;

  return query
  select m.id,
         (m.starts_at at time zone 'Asia/Seoul')::date,
         m.meta -> 'supervision' ->> 'slot',
         coalesce((m.meta -> 'supervision' ->> 'with_morning')::boolean, false),
         public.supervision_assignee_names(m.meta)
  from meeting m
  where m.kind = 'duty'
    and jsonb_typeof(m.meta -> 'supervision') = 'object'
    and m.meta -> 'supervision' ->> 'grade' = p_grade::text
    and m.starts_at >= (p_since::timestamp at time zone 'Asia/Seoul')
    and m.starts_at <  ((p_until + 1)::timestamp at time zone 'Asia/Seoul')
  order by m.starts_at;
end;
$$;


ALTER FUNCTION "public"."get_self_study_supervision_history"("p_grade" integer, "p_since" "date", "p_until" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_self_study_supervision_history"("p_grade" integer, "p_since" "date", "p_until" "date") IS '한 학년의 자습 감독 일정(날짜·시간대·담당자 이름). 교직원 전용. duty RLS 가 만든 사람·담당자에게만 보여 누적 횟수가 틀리는 것을 막는다.';



CREATE OR REPLACE FUNCTION "public"."get_semester_credit_distribution"("p_admission_year" integer) RETURNS TABLE("semester" "text", "category" "text", "subject_type" "text", "credit_sum" integer, "subject_list" "text"[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    (sc.grade::text || '-' || sc.semester::text) AS semester,
    sc.category,
    sc.subject_type,
    SUM(sc.credits)::int AS credit_sum,
    array_agg(DISTINCT sc.subject ORDER BY sc.subject) AS subject_list
  FROM school_curriculum sc
  WHERE sc.admission_year = p_admission_year
  GROUP BY sc.grade, sc.semester, sc.category, sc.subject_type
  ORDER BY sc.grade, sc.semester,
    CASE sc.category
      WHEN '국어' THEN 1 WHEN '수학' THEN 2 WHEN '영어' THEN 3
      WHEN '사회' THEN 4 WHEN '과학' THEN 5 WHEN '체육' THEN 6
      WHEN '예술' THEN 7 WHEN '기술·가정' THEN 8 WHEN '교양' THEN 9
      ELSE 10
    END;
$$;


ALTER FUNCTION "public"."get_semester_credit_distribution"("p_admission_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_semester_credit_distribution"("p_admission_year" integer) IS '학기별 학점 배분 분석';



CREATE OR REPLACE FUNCTION "public"."get_signature_by_token"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_tok     public.signature_sign_token;
  v_signer  public.signature_signer;
  v_request public.signature_request;
  v_active  int;
begin
  select * into v_tok from public.signature_sign_token where token = p_token;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if v_tok.expires_at < now() then
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;

  select * into v_signer from public.signature_signer where id = v_tok.signer_id;
  select * into v_request from public.signature_request where id = v_tok.request_id;
  if v_signer is null or v_request is null then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;

  -- 지금 서명할 차례인 그룹(= 아직 pending 인 가장 작은 순번)
  select min(order_index) into v_active
  from public.signature_signer
  where request_id = v_tok.request_id and status = 'pending';

  return jsonb_build_object(
    'ok', true,
    'title', v_request.title,
    'message', v_request.message,
    'source_name', v_request.source_name,
    'source_kind', v_request.source_kind,
    'requester_name', v_request.requester_name,
    'request_status', v_request.status,
    'signer_name', v_signer.signer_name,
    'role_label', v_signer.role_label,
    'signer_status', v_signer.status,
    -- 진행 상황은 **숫자만** 준다(명단은 주지 않는다)
    'signed_count', (select count(*) from public.signature_signer
                      where request_id = v_tok.request_id and status = 'signed'),
    'total_count',  (select count(*) from public.signature_signer
                      where request_id = v_tok.request_id),
    'is_my_turn', (
      v_request.status = 'pending'
      and v_signer.status = 'pending'
      and v_active is not null
      and v_signer.order_index = v_active
    )
  );
end;
$$;


ALTER FUNCTION "public"."get_signature_by_token"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_signature_sign_links"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.signature_request;
  v_is_owner boolean;
  v_my_name text;
begin
  -- **가장 먼저** 익명을 막는다. 아래 비교들이 NULL 이 되어 조용히 통과하는 것을 원천 차단.
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '28000';
  end if;

  select * into v_request from public.signature_request where id = p_request_id;
  if not found then
    raise exception '서명 요청을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;

  v_is_owner := coalesce(v_request.requester_user_id = auth.uid(), false) or public.is_admin();
  v_my_name := public.current_profile_name();

  if not v_is_owner and not exists (
    select 1 from public.signature_signer s
    where s.request_id = p_request_id
      and (s.signer_user_id = auth.uid()
           or (s.signer_user_id is null and v_my_name is not null and s.signer_name = v_my_name))
  ) then
    raise exception '권한이 없습니다.' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'signer_id', s.id,
      'signer_name', s.signer_name,
      'status', s.status,
      'token', t.token,
      'expires_at', t.expires_at
    ) order by s.order_index, s.signer_name)
    from public.signature_signer s
    join public.signature_sign_token t on t.signer_id = s.id
    where s.request_id = p_request_id
      and (
        v_is_owner
        or s.signer_user_id = auth.uid()
        or (s.signer_user_id is null and v_my_name is not null and s.signer_name = v_my_name)
      )
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."get_signature_sign_links"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_activities_by_category"("p_student_code" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_grade" integer DEFAULT NULL::integer) RETURNS TABLE("student_code" "text", "name" "text", "category" "text", "subject_name" "text", "grade" integer, "semester" integer, "content" "text", "hours" integer, "area" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    sda.student_id AS student_code,
    sbi.name,
    sda.category,
    sda.subject_name,
    sda.grade,
    sda.semester,
    sda.content,
    COALESCE((sda.data->>'시간')::int, 0) AS hours,
    sda.data->>'영역' AS area
  FROM student_detailed_activities sda
  JOIN student_basic_info sbi ON sbi.id = sda.student_id
  WHERE (p_student_code IS NULL OR sda.student_id = p_student_code)
    AND (p_category IS NULL OR sda.category = p_category)
    AND (p_grade IS NULL OR sda.grade = p_grade);
$$;


ALTER FUNCTION "public"."get_student_activities_by_category"("p_student_code" "text", "p_category" "text", "p_grade" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_activity_summary"("p_student_code" "text" DEFAULT NULL::"text") RETURNS TABLE("student_code" "text", "name" "text", "regular_count" integer, "career_count" integer, "pe_arts_count" integer, "autonomy_count" integer, "autonomy_hours" integer, "club_count" integer, "club_hours" integer, "career_activity_count" integer, "career_activity_hours" integer, "behavior_count" integer, "total_count" integer, "total_creative_hours" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    sda.student_id AS student_code,
    sbi.name,
    COUNT(*) FILTER (WHERE sda.category = 'regular')::int AS regular_count,
    COUNT(*) FILTER (WHERE sda.category = 'career')::int AS career_count,
    COUNT(*) FILTER (WHERE sda.category = 'pe_arts')::int AS pe_arts_count,
    COUNT(*) FILTER (WHERE sda.category = '자율활동')::int AS autonomy_count,
    COALESCE(SUM((sda.data->>'시간')::int) FILTER (WHERE sda.category = '자율활동'), 0)::int AS autonomy_hours,
    COUNT(*) FILTER (WHERE sda.category = '동아리활동')::int AS club_count,
    COALESCE(SUM((sda.data->>'시간')::int) FILTER (WHERE sda.category = '동아리활동'), 0)::int AS club_hours,
    COUNT(*) FILTER (WHERE sda.category = '진로활동')::int AS career_activity_count,
    COALESCE(SUM((sda.data->>'시간')::int) FILTER (WHERE sda.category = '진로활동'), 0)::int AS career_activity_hours,
    COUNT(*) FILTER (WHERE sda.category = '행동특성및종합의견')::int AS behavior_count,
    COUNT(*)::int AS total_count,
    COALESCE(SUM((sda.data->>'시간')::int) FILTER (WHERE sda.category IN ('자율활동','동아리활동','진로활동')), 0)::int AS total_creative_hours
  FROM student_detailed_activities sda
  JOIN student_basic_info sbi ON sbi.id = sda.student_id
  WHERE (p_student_code IS NULL OR sda.student_id = p_student_code)
  GROUP BY sda.student_id, sbi.name;
$$;


ALTER FUNCTION "public"."get_student_activity_summary"("p_student_code" "text") OWNER TO "postgres";


