CREATE OR REPLACE FUNCTION "public"."get_student_attendance_flat"("p_student_code" "text" DEFAULT NULL::"text") RETURNS TABLE("student_code" "text", "name" "text", "grade" integer, "school_days" integer, "absence_disease" integer, "absence_unapproved" integer, "absence_other" integer, "tardiness_disease" integer, "tardiness_unapproved" integer, "tardiness_other" integer, "early_leave_disease" integer, "early_leave_unapproved" integer, "early_leave_other" integer, "class_skip_disease" integer, "class_skip_unapproved" integer, "class_skip_other" integer, "total_absence" integer, "total_tardiness" integer, "total_early_leave" integer, "total_class_skip" integer, "attendance_rate" numeric, "notes" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    sbi.id AS student_code,
    sbi.name,
    (att->>'grade')::int AS grade,
    (att->>'schoolDays')::int AS school_days,
    COALESCE((att->'absence'->>'disease')::int, 0) AS absence_disease,
    COALESCE((att->'absence'->>'unapproved')::int, 0) AS absence_unapproved,
    COALESCE((att->'absence'->>'other')::int, 0) AS absence_other,
    COALESCE((att->'tardiness'->>'disease')::int, 0) AS tardiness_disease,
    COALESCE((att->'tardiness'->>'unapproved')::int, 0) AS tardiness_unapproved,
    COALESCE((att->'tardiness'->>'other')::int, 0) AS tardiness_other,
    COALESCE((att->'earlyLeave'->>'disease')::int, 0) AS early_leave_disease,
    COALESCE((att->'earlyLeave'->>'unapproved')::int, 0) AS early_leave_unapproved,
    COALESCE((att->'earlyLeave'->>'other')::int, 0) AS early_leave_other,
    COALESCE((att->'classSkip'->>'disease')::int, 0) AS class_skip_disease,
    COALESCE((att->'classSkip'->>'unapproved')::int, 0) AS class_skip_unapproved,
    COALESCE((att->'classSkip'->>'other')::int, 0) AS class_skip_other,
    -- Totals
    COALESCE((att->'absence'->>'disease')::int, 0) + COALESCE((att->'absence'->>'unapproved')::int, 0) + COALESCE((att->'absence'->>'other')::int, 0) AS total_absence,
    COALESCE((att->'tardiness'->>'disease')::int, 0) + COALESCE((att->'tardiness'->>'unapproved')::int, 0) + COALESCE((att->'tardiness'->>'other')::int, 0) AS total_tardiness,
    COALESCE((att->'earlyLeave'->>'disease')::int, 0) + COALESCE((att->'earlyLeave'->>'unapproved')::int, 0) + COALESCE((att->'earlyLeave'->>'other')::int, 0) AS total_early_leave,
    COALESCE((att->'classSkip'->>'disease')::int, 0) + COALESCE((att->'classSkip'->>'unapproved')::int, 0) + COALESCE((att->'classSkip'->>'other')::int, 0) AS total_class_skip,
    -- Attendance rate: (school_days - total_absence) / school_days * 100
    CASE WHEN (att->>'schoolDays')::int > 0
      THEN ROUND(
        ((att->>'schoolDays')::int - (
          COALESCE((att->'absence'->>'disease')::int, 0) +
          COALESCE((att->'absence'->>'unapproved')::int, 0) +
          COALESCE((att->'absence'->>'other')::int, 0)
        ))::numeric / (att->>'schoolDays')::int * 100, 1
      )
      ELSE NULL
    END AS attendance_rate,
    att->>'notes' AS notes
  FROM student_basic_info sbi,
    jsonb_array_elements(COALESCE(sbi.attendance, '[]'::jsonb)) AS att
  WHERE sbi.attendance IS NOT NULL
    AND jsonb_array_length(sbi.attendance) > 0
    AND (p_student_code IS NULL OR sbi.id = p_student_code);
$$;


ALTER FUNCTION "public"."get_student_attendance_flat"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_audience_vocab"("p_academic_year" integer DEFAULT NULL::integer, "p_semester" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_year int := p_academic_year;
  v_sem  int := p_semester;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  if not public.is_teacher_or_admin(auth.uid()) then
    raise exception '교사만 조회할 수 있습니다' using errcode = '42501';
  end if;
  if v_year is null or v_sem is null then
    select t.academic_year, t.semester into v_year, v_sem from public.current_academic_term() t;
  end if;

  return jsonb_build_object(
    'academic_year', v_year,
    'semester', v_sem,
    'classes', (
      select coalesce(jsonb_agg(jsonb_build_object('grade', grade, 'class', class, 'count', n) order by grade, class), '[]'::jsonb)
      from (select p.grade, p.class, count(*) n from public.student_audience_pool() p
            where p.grade is not null and p.class is not null group by 1, 2) x),
    'subjects', (
      select coalesce(jsonb_agg(jsonb_build_object('subject', subject, 'grades', grades, 'count', n) order by subject), '[]'::jsonb)
      from (select t.subject, array_agg(distinct p.grade order by p.grade) grades, count(distinct t.resource_id) n
            from public.student_timetable t
            join public.student_audience_pool() p on p.resource_id = t.resource_id
            where t.academic_year = v_year and t.semester = v_sem
            group by t.subject) x),
    'clubs', (
      select coalesce(jsonb_agg(jsonb_build_object('name', c.name, 'category', c.category, 'count', (
               select count(*) from jsonb_array_elements(coalesce(c.students, '[]'::jsonb)) s
               join public.student_audience_pool() p on p.resource_id::text = s->>'resource_id'))
             order by c.name), '[]'::jsonb)
      from public.club_info c
      where c.academic_year = v_year and coalesce(c.meta->>'status', 'active') = 'active'),
    'my_homeroom', (
      select coalesce(jsonb_agg(jsonb_build_object('grade', m[1]::int, 'class', m[2]::int) order by m[1]::int, m[2]::int), '[]'::jsonb)
      from public.resource_tag_assignments a
      join public.resource_tags tg on tg.id = a.tag_id
      cross join lateral regexp_match(tg.name, '^([0-9])학년 ([0-9]+)반$') m
      where a.resource_id in (select public.current_actor_resource_ids()) and m is not null),
    'my_subjects', (
      select coalesce(jsonb_agg(distinct t.subject), '[]'::jsonb)
      from public.student_timetable t
      where t.academic_year = v_year and t.semester = v_sem
        and t.teacher_resource_id in (select public.current_actor_resource_ids())),
    -- 이번 학기 수업이 있는 선생님(「ㅇㅇㅇ 선생님 수업」 선택지·AI 이름 대조)
    'teachers', (
      select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'subjects', x.subjects) order by x.name), '[]'::jsonb)
      from (select r.id, r.name, array_agg(distinct t.subject order by t.subject) subjects
            from public.student_timetable t
            join public.resource r on r.id = t.teacher_resource_id
            where t.academic_year = v_year and t.semester = v_sem and r.status = 'active'
            group by r.id, r.name) x),
    -- 끝난 학기 과목(성적 기록) — 과목마다 어느 학년·학기에 있었는지
    'past_subjects', (
      select coalesce(jsonb_agg(jsonb_build_object('subject', x.subject, 'terms', x.terms, 'count', x.n) order by x.subject), '[]'::jsonb)
      from (select f.subject, array_agg(distinct f.grade || '-' || f.semester order by f.grade || '-' || f.semester) terms,
                   count(distinct f.student_code) n
            from public.student_academic_flat f
            join public.student_audience_pool() p on p.student_code = f.student_code
            where f.subject is not null
            group by f.subject) x),
    'max_period', (
      select coalesce(max(t.period), 7) from public.student_timetable t
      where t.academic_year = v_year and t.semester = v_sem)
  );
end;
$_$;


