CREATE OR REPLACE FUNCTION "public"."get_student_cross_domain_stats"("p_student_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
  v_academic_avg NUMERIC;
  v_mock_latest JSONB;
  v_study_room JSONB;
  v_reading_count INT;
  v_activity_summary JSONB;
  v_attendance JSONB;
  v_volunteer JSONB;
  v_engagement JSONB;
BEGIN
  -- 1. Academic weighted average (unchanged)
  SELECT
    CASE WHEN SUM(units) > 0 THEN ROUND(SUM(rank * units) / SUM(units), 2) ELSE NULL END
  INTO v_academic_avg
  FROM student_academic_flat
  WHERE student_code = p_student_code
    AND category = 'regular'
    AND rank IS NOT NULL AND units IS NOT NULL AND units > 0;

  -- 2. Latest mock exam (optimized single call)
  SELECT jsonb_build_object(
    'exam_month', sub.exam_month,
    'exam_grade', sub.exam_grade,
    'academic_year', sub.academic_year,
    'avg_grade', sub.avg_grade,
    'subject_count', sub.subject_count
  )
  INTO v_mock_latest
  FROM (
    SELECT ms.exam_month, ms.exam_grade, ms.academic_year,
      ROUND(AVG(ms.grade)::numeric, 1) AS avg_grade,
      COUNT(*) AS subject_count
    FROM get_student_mock_summary(p_student_code) ms
    GROUP BY ms.academic_year, ms.exam_grade, ms.exam_month
    ORDER BY ms.academic_year DESC, ms.exam_month DESC
    LIMIT 1
  ) sub;

  -- 3. Study room (current year)
  SELECT jsonb_build_object(
    'total', COALESCE(s.total_reservations, 0),
    'attended', COALESCE(s.attended_count, 0),
    'rate', COALESCE(s.attendance_rate, 0)
  )
  INTO v_study_room
  FROM get_student_study_room_summary(p_student_code) s
  WHERE s.academic_year = EXTRACT(YEAR FROM CURRENT_DATE)::int;

  -- 4. Reading count
  SELECT COUNT(*) INTO v_reading_count
  FROM get_student_reading_flat(p_student_code);

  -- 5. NEW: Activity summary (categories + creative hours)
  SELECT jsonb_build_object(
    'total', COALESCE(a.total_count, 0),
    'regular', COALESCE(a.regular_count, 0),
    'creative_hours', COALESCE(a.total_creative_hours, 0),
    'autonomy_hours', COALESCE(a.autonomy_hours, 0),
    'club_hours', COALESCE(a.club_hours, 0),
    'career_hours', COALESCE(a.career_activity_hours, 0)
  )
  INTO v_activity_summary
  FROM get_student_activity_summary(p_student_code) a;

  -- 6. NEW: Attendance (latest grade)
  SELECT jsonb_build_object(
    'grade', att.grade,
    'school_days', att.school_days,
    'total_absence', att.total_absence,
    'total_tardiness', att.total_tardiness,
    'attendance_rate', att.attendance_rate
  )
  INTO v_attendance
  FROM get_student_attendance_flat(p_student_code) att
  ORDER BY att.grade DESC
  LIMIT 1;

  -- 7. NEW: Volunteer summary
  SELECT jsonb_build_object(
    'total_hours', COALESCE(SUM(v.hours), 0),
    'activity_count', COUNT(*),
    'max_cumulative', COALESCE(MAX(v.cumulative_hours), 0)
  )
  INTO v_volunteer
  FROM get_student_volunteer_flat(p_student_code) v;

  -- 8. NEW: Engagement (afterschool + career submissions)
  SELECT jsonb_build_object(
    'afterschool', COALESCE(e.afterschool_total, 0),
    'career_submissions', COALESCE(e.career_submissions_total, 0),
    'career_on_time', COALESCE(e.career_submissions_on_time, 0)
  )
  INTO v_engagement
  FROM get_student_engagement_summary(p_student_code) e;

  -- Build result
  v_result := jsonb_build_object(
    'student_code', p_student_code,
    'academic_avg', v_academic_avg,
    'mock_latest', COALESCE(v_mock_latest, '{}'::jsonb),
    'study_room', COALESCE(v_study_room, jsonb_build_object('total', 0, 'attended', 0, 'rate', 0)),
    'reading_count', v_reading_count,
    'activities', COALESCE(v_activity_summary, jsonb_build_object('total', 0, 'regular', 0, 'creative_hours', 0)),
    'attendance', COALESCE(v_attendance, '{}'::jsonb),
    'volunteer', COALESCE(v_volunteer, jsonb_build_object('total_hours', 0, 'activity_count', 0)),
    'engagement', COALESCE(v_engagement, jsonb_build_object('afterschool', 0, 'career_submissions', 0, 'career_on_time', 0))
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_student_cross_domain_stats"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_dashboard_data"("p_grade" integer DEFAULT NULL::integer, "p_class_num" integer DEFAULT NULL::integer, "p_search_term" "text" DEFAULT NULL::"text", "p_student_code" "text" DEFAULT NULL::"text") RETURNS TABLE("student_code" "text", "resource_id" "uuid", "name" "text", "grade" integer, "class_num" integer, "number" integer, "student_no" "text", "picture" "text", "phone" "text", "career" "text", "major" "text", "birthday" "text", "academic_development" "jsonb", "attendance" "jsonb", "volunteer" "jsonb", "reading" "jsonb", "total_reservations" bigint, "attended_count" bigint, "attendance_rate" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  user_role TEXT;
BEGIN
  -- Check if user is authenticated
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Get user role from profiles
  SELECT p.role INTO user_role
  FROM profiles p
  WHERE p.id = auth.uid();

  -- Only allow teachers and admins
  IF user_role IS NULL OR user_role NOT IN ('teacher', 'admin') THEN
    RAISE EXCEPTION 'Access denied. Only teachers and administrators can access student dashboard.';
  END IF;

  -- 학년 필터가 없고, 학생코드도 없고, 검색어도 없으면 빈 결과 반환
  IF p_grade IS NULL AND p_student_code IS NULL AND (p_search_term IS NULL OR p_search_term = '') THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    v.student_code,
    v.resource_id,
    v.name,
    v.grade,
    v.class_num,
    v.number,
    v.student_no,
    v.picture,
    v.phone,
    v.career,
    v.major,
    v.birthday,
    v.academic_development,
    v.attendance,
    v.volunteer,
    v.reading,
    COALESCE(stats.total_reservations, 0) as total_reservations,
    COALESCE(stats.attended_count, 0) as attended_count,
    CASE 
      WHEN COALESCE(stats.total_reservations, 0) > 0 
      THEN ROUND((COALESCE(stats.attended_count, 0)::NUMERIC / stats.total_reservations) * 100, 1)
      ELSE 0
    END as attendance_rate
  FROM student_dashboard_view v
  LEFT JOIN LATERAL (
    SELECT
      COUNT(*) as total_reservations,
      COUNT(*) FILTER (WHERE sr.is_attended = true) as attended_count
    FROM seat_reservations sr
    JOIN profiles p ON sr.student_id = p.id
    WHERE split_part(p.email, '@', 1) = v.student_code
      AND sr.reservation_date < CURRENT_DATE  -- 어제까지의 데이터만 계산
  ) stats ON true
  WHERE
    (p_student_code IS NULL OR v.student_code = p_student_code)
    AND (p_grade IS NULL OR v.grade = p_grade)
    AND (p_class_num IS NULL OR v.class_num = p_class_num)
    AND (
      p_search_term IS NULL 
      OR p_search_term = ''
      OR v.name ILIKE '%' || p_search_term || '%'
      OR v.number::TEXT = p_search_term
      OR v.student_no ILIKE '%' || p_search_term || '%'
    )
  ORDER BY v.grade, v.class_num, v.number;
END;
$$;


ALTER FUNCTION "public"."get_student_dashboard_data"("p_grade" integer, "p_class_num" integer, "p_search_term" "text", "p_student_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_student_dashboard_data"("p_grade" integer, "p_class_num" integer, "p_search_term" "text", "p_student_code" "text") IS '학생 대시보드 데이터 조회 - 학년+반 필수 또는 특정 학생 코드 필요';



CREATE OR REPLACE FUNCTION "public"."get_student_engagement_summary"("p_student_code" "text" DEFAULT NULL::"text") RETURNS TABLE("student_code" "text", "name" "text", "afterschool_total" integer, "afterschool_paid" integer, "afterschool_free" integer, "career_submissions_total" integer, "career_submissions_on_time" integer, "career_board_types" integer, "career_with_material" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    sbi.id AS student_code,
    sbi.name,
    -- Afterschool
    COALESCE(ae_agg.total, 0)::int AS afterschool_total,
    COALESCE(ae_agg.paid, 0)::int AS afterschool_paid,
    COALESCE(ae_agg.free, 0)::int AS afterschool_free,
    -- Career submissions
    COALESCE(cs_agg.total, 0)::int AS career_submissions_total,
    COALESCE(cs_agg.on_time, 0)::int AS career_submissions_on_time,
    COALESCE(cs_agg.board_types, 0)::int AS career_board_types,
    COALESCE(cs_agg.with_material, 0)::int AS career_with_material
  FROM student_basic_info sbi
  LEFT JOIN (
    SELECT student_id,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE is_paid = true) AS paid,
      COUNT(*) FILTER (WHERE is_paid = false) AS free
    FROM afterschool_enrollments
    GROUP BY student_id
  ) ae_agg ON ae_agg.student_id = sbi.id
  LEFT JOIN (
    SELECT my_id,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE submission_datetime IS NOT NULL AND submission_datetime <> '' AND deadline IS NOT NULL AND submission_datetime <= deadline) AS on_time,
      COUNT(DISTINCT board_name) AS board_types,
      COUNT(*) FILTER (WHERE material_link_url IS NOT NULL AND material_link_url <> '') AS with_material
    FROM student_career_submissions
    GROUP BY my_id
  ) cs_agg ON cs_agg.my_id = sbi.id
  WHERE (p_student_code IS NULL OR sbi.id = p_student_code)
    AND (ae_agg.total IS NOT NULL OR cs_agg.total IS NOT NULL);
$$;


ALTER FUNCTION "public"."get_student_engagement_summary"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_grade_summary"("p_student_ids" "text"[]) RETURNS TABLE("student_code" "text", "overall_grade" numeric, "subject_group_grades" "jsonb", "total_units" numeric, "subject_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
  WITH records AS (
    SELECT
      sbi.id AS student_code,
      (rec->>'category')::text AS category,
      (rec->>'subject_group')::text AS subject_group,
      (rec->>'units')::numeric AS units,
      (rec->>'rank')::numeric AS rank
    FROM student_basic_info sbi
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(sbi.academic_development, '[]'::jsonb)) AS rec
    WHERE sbi.id = ANY(p_student_ids)
  ),
  valid AS (
    SELECT * FROM records WHERE category = 'regular' AND rank IS NOT NULL
  ),
  per_group AS (
    SELECT
      student_code,
      public.course_analyze_subject_category(subject_group) AS category,
      sum(rank * units)::numeric / NULLIF(sum(units), 0) AS group_grade
    FROM valid
    GROUP BY student_code, public.course_analyze_subject_category(subject_group)
  ),
  group_obj AS (
    SELECT
      student_code,
      jsonb_object_agg(category, group_grade) AS subject_group_grades
    FROM per_group
    GROUP BY student_code
  ),
  totals AS (
    SELECT
      student_code,
      sum(rank * units)::numeric / NULLIF(sum(units), 0) AS overall_grade,
      sum(units)::numeric AS total_units,
      count(*)::integer AS subject_count
    FROM valid
    GROUP BY student_code
  ),
  -- 입력에 있지만 academic_development가 없는 학생도 결과에 포함 (0/empty)
  base AS (
    SELECT unnest(p_student_ids) AS student_code
  )
  SELECT
    b.student_code,
    coalesce(t.overall_grade, 0)::numeric AS overall_grade,
    coalesce(g.subject_group_grades, '{}'::jsonb) AS subject_group_grades,
    coalesce(t.total_units, 0)::numeric AS total_units,
    coalesce(t.subject_count, 0)::integer AS subject_count
  FROM base b
  LEFT JOIN totals t ON t.student_code = b.student_code
  LEFT JOIN group_obj g ON g.student_code = b.student_code
$$;


ALTER FUNCTION "public"."get_student_grade_summary"("p_student_ids" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_student_grade_summary"("p_student_ids" "text"[]) IS 'course-analyze: student_basic_info.academic_development에서 regular+rank 레코드만 가중평균/과목군별 평균 계산. 클라이언트 페이로드 95% 절감 (Phase2 최적화).';



CREATE OR REPLACE FUNCTION "public"."get_student_grade_trajectory"("p_student_code" "text") RETURNS TABLE("academic_year" integer, "semester" integer, "subject_group" "text", "weighted_avg" numeric, "rank_change" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH entry_year AS (
    SELECT 2000 + SPLIT_PART(p_student_code, '-', 1)::int AS yr
  ),
  semester_avgs AS (
    SELECT
      (ey.yr + saf.grade - 1) AS academic_year,
      saf.semester,
      saf.subject_group,
      CASE
        WHEN SUM(saf.units) FILTER (WHERE saf.units > 0) > 0
        THEN ROUND(
          SUM(saf.rank * saf.units) FILTER (WHERE saf.rank IS NOT NULL AND saf.units > 0)
          / SUM(saf.units) FILTER (WHERE saf.rank IS NOT NULL AND saf.units > 0),
          2
        )
        ELSE NULL
      END AS weighted_avg
    FROM student_academic_flat saf, entry_year ey
    WHERE saf.student_code = p_student_code
      AND saf.category = 'regular'
    GROUP BY ey.yr, saf.grade, saf.semester, saf.subject_group
  ),
  with_change AS (
    SELECT
      sa.academic_year,
      sa.semester,
      sa.subject_group,
      sa.weighted_avg,
      sa.weighted_avg - LAG(sa.weighted_avg) OVER (
        PARTITION BY sa.subject_group
        ORDER BY sa.academic_year, sa.semester
      ) AS rank_change
    FROM semester_avgs sa
  )
  SELECT wc.academic_year, wc.semester, wc.subject_group, wc.weighted_avg, wc.rank_change
  FROM with_change wc
  WHERE wc.weighted_avg IS NOT NULL
  ORDER BY wc.academic_year, wc.semester, wc.subject_group;
$$;


ALTER FUNCTION "public"."get_student_grade_trajectory"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_mock_summary"("p_student_code" "text" DEFAULT NULL::"text") RETURNS TABLE("student_code" "text", "name" "text", "academic_year" integer, "exam_grade" integer, "exam_month" integer, "subject" "text", "raw_score" numeric, "standard_score" numeric, "percentile" numeric, "grade" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    sbi.id AS student_code,
    sbi.name,
    (exam->>'academic_year')::int AS academic_year,
    (exam->>'exam_grade')::int AS exam_grade,
    (exam->>'exam_month')::int AS exam_month,
    subj.key AS subject,
    (subj.value->>'raw_score')::numeric AS raw_score,
    (subj.value->>'standard_score')::numeric AS standard_score,
    (subj.value->>'percentile')::numeric AS percentile,
    (subj.value->>'grade')::int AS grade
  FROM student_basic_info sbi,
    jsonb_array_elements(COALESCE(sbi.mock_result, '[]'::jsonb)) AS exam,
    jsonb_each(exam->'subjects') AS subj
  WHERE sbi.mock_result IS NOT NULL
    AND jsonb_array_length(sbi.mock_result) > 0
    AND (p_student_code IS NULL OR sbi.id = p_student_code);
$$;


ALTER FUNCTION "public"."get_student_mock_summary"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_points"("p_student_id" "uuid") RETURNS TABLE("total_earned" integer, "total_spent" integer, "balance" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    COALESCE(SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END), 0)::INTEGER AS total_earned,
    COALESCE(SUM(CASE WHEN amount < 0 THEN ABS(amount) ELSE 0 END), 0)::INTEGER AS total_spent,
    COALESCE(SUM(amount), 0)::INTEGER AS balance
  FROM point_transactions
  WHERE student_id = p_student_id;
$$;


ALTER FUNCTION "public"."get_student_points"("p_student_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_reading_flat"("p_student_code" "text" DEFAULT NULL::"text") RETURNS TABLE("student_code" "text", "name" "text", "grade" integer, "semester" integer, "related_subject" "text", "title" "text", "author" "text", "content" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    sbi.id AS student_code,
    sbi.name,
    (book->>'grade')::int AS grade,
    (book->>'semester')::int AS semester,
    book->>'related' AS related_subject,
    book->>'title' AS title,
    book->>'author' AS author,
    book->>'content' AS content
  FROM student_basic_info sbi,
    jsonb_array_elements(COALESCE(sbi.reading, '[]'::jsonb)) AS book
  WHERE sbi.reading IS NOT NULL
    AND jsonb_array_length(sbi.reading) > 0
    AND (p_student_code IS NULL OR sbi.id = p_student_code);
$$;


ALTER FUNCTION "public"."get_student_reading_flat"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_reservation_stats"("p_student_code" "text") RETURNS TABLE("total_reservations" bigint, "attended_count" bigint, "attendance_rate" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    COUNT(*)::BIGINT as total_reservations,
    COUNT(CASE WHEN sr.is_attended = true THEN 1 END)::BIGINT as attended_count,
    CASE 
      WHEN COUNT(*) > 0 THEN 
        ROUND((COUNT(CASE WHEN sr.is_attended = true THEN 1 END)::NUMERIC / COUNT(*)::NUMERIC) * 100, 1)
      ELSE 0
    END as attendance_rate
  FROM seat_reservations sr
  JOIN profiles p ON sr.student_id = p.id
  WHERE SPLIT_PART(p.email, '@', 1) = p_student_code;
END;
$$;


ALTER FUNCTION "public"."get_student_reservation_stats"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_reservations_by_year"("p_student_code" "text") RETURNS TABLE("year" integer, "total_reservations" bigint, "attended_count" bigint, "attendance_rate" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    -- 학년도 기준: 3월~2월을 1년으로 계산 (3월 이후는 해당 연도, 1-2월은 전년도)
    CASE 
      WHEN EXTRACT(MONTH FROM sr.reservation_date) >= 3 
      THEN EXTRACT(YEAR FROM sr.reservation_date)::integer
      ELSE (EXTRACT(YEAR FROM sr.reservation_date) - 1)::integer
    END as year,
    COUNT(*) as total_reservations,
    COUNT(*) FILTER (WHERE sr.is_attended = true) as attended_count,
    CASE 
      WHEN COUNT(*) > 0 
      THEN ROUND((COUNT(*) FILTER (WHERE sr.is_attended = true)::NUMERIC / COUNT(*)) * 100, 1)
      ELSE 0
    END as attendance_rate
  FROM seat_reservations sr
  JOIN profiles p ON sr.student_id = p.id
  WHERE split_part(p.email, '@', 1) = p_student_code
    AND sr.reservation_date < CURRENT_DATE
  GROUP BY 
    CASE 
      WHEN EXTRACT(MONTH FROM sr.reservation_date) >= 3 
      THEN EXTRACT(YEAR FROM sr.reservation_date)::integer
      ELSE (EXTRACT(YEAR FROM sr.reservation_date) - 1)::integer
    END
  ORDER BY year DESC;
END;
$$;


ALTER FUNCTION "public"."get_student_reservations_by_year"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_stats_bundle"("p_start" "date", "p_end" "date", "p_today" "date", "p_past_closing" boolean, "p_attendance_increment" double precision, "p_absence_decrement" double precision, "p_grade" integer DEFAULT NULL::integer, "p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    SET "work_mem" TO '16MB'
    AS $_$
DECLARE
  v_filters text := '';
  v_result jsonb;
BEGIN
  -- 쓰지 않는 필터는 아예 빼고, 매 호출을 실제 값으로 계획한다(동적 SQL).
  -- LANGUAGE sql 버전은 일반(generic) 계획으로 "$x IS NULL OR ..." 조건의 추정이 틀어져
  -- 학기 범위에서 7초 이상 걸렸다.
  IF p_room_id IS NOT NULL THEN
    v_filters := v_filters || ' AND sr.room_id = $8';
  END IF;
  IF p_grade IS NOT NULL THEN
    v_filters := v_filters || ' AND p.email IN (
        SELECT res.meta->>''id'' || ''@myschool.hs.kr''
        FROM resource res
        WHERE res.meta->>''grade'' = $7::text)';
  END IF;

  EXECUTE $q$
  WITH rows AS (
    SELECT
      sr.id,
      sr.student_id,
      sr.room_id,
      sr.reservation_date AS d,
      sr.period_id,
      sr.is_attended,
      sr.attendance_status,
      c.name AS checker_name,
      r.name AS room_name,
      (sr.reservation_date < $3 OR (sr.reservation_date = $3 AND $4)) AS missed,
      -- 같은 날 여러 교시를 신청하면 온도 변화에 1/N 가중치
      count(*) OVER (PARTITION BY sr.student_id, sr.reservation_date) AS day_n
    FROM seat_reservations sr
    JOIN profiles p ON p.id = sr.student_id
    LEFT JOIN profiles c ON c.id = sr.checked_by
    LEFT JOIN study_rooms r ON r.id = sr.room_id
    WHERE sr.reservation_date BETWEEN $1 AND $2
    $q$ || v_filters || $q$
  ),
  rooms AS (
    SELECT room_id, max(room_name) AS room_name, (row_number() OVER (ORDER BY room_id)) - 1 AS idx
    FROM rows
    GROUP BY room_id
  ),
  agg AS (
    SELECT
      student_id,
      count(*) AS total,
      count(*) FILTER (WHERE is_attended) AS attended,
      count(*) FILTER (WHERE NOT coalesce(is_attended, false) AND missed) AS absent,
      sum(
        CASE
          WHEN is_attended THEN $5 * (1.0::float8 / day_n)
          WHEN missed THEN -$6 * (1.0::float8 / day_n)
          ELSE 0
        END
      ) AS temp
    FROM rows
    GROUP BY student_id
  ),
  weekday_rooms AS (
    SELECT student_id, jsonb_object_agg(dow::text, names) AS wr
    FROM (
      SELECT student_id, extract(isodow FROM d)::int AS dow, jsonb_agg(DISTINCT room_name) AS names
      FROM rows
      WHERE extract(isodow FROM d) BETWEEN 1 AND 5 AND room_name IS NOT NULL
      GROUP BY student_id, extract(isodow FROM d)
    ) per_dow
    GROUP BY student_id
  ),
  per_day AS (
    SELECT
      x.student_id,
      x.d,
      jsonb_agg(
        jsonb_build_array(
          x.period_id,
          CASE
            WHEN x.attendance_status = 'excused' THEN 'excused'
            WHEN x.is_attended THEN 'attended'
            WHEN x.missed THEN 'absent'
            ELSE 'none'
          END,
          x.checker_name,
          rm.idx
        )
        ORDER BY x.period_id, x.id
      ) AS entries
    FROM rows x
    JOIN rooms rm ON rm.room_id = x.room_id
    GROUP BY x.student_id, x.d
  ),
  attendance AS (
    SELECT student_id, jsonb_object_agg(d::text, entries) AS att
    FROM per_day
    GROUP BY student_id
  ),
  student_profiles AS (
    SELECT a.student_id, p.email, p.name, split_part(p.email, '@', 1) AS local_part
    FROM agg a
    JOIN profiles p ON p.id = a.student_id
  ),
  -- 대상 학생의 resource 행만 한 번에 조회 (학생마다 resource 전체를 다시 훑지 않도록)
  student_resources AS (
    SELECT res.id, res.name, res.meta, res.meta->>'id' AS sid
    FROM resource res
    WHERE res.meta->>'id' IN (SELECT local_part FROM student_profiles)
  ),
  -- fetchStudentNumbers(): 가장 큰 snumN(N>0) 값
  latest_snum AS (
    SELECT DISTINCT ON (sr2.sid) sr2.sid, sr2.meta->(k.key) AS snum
    FROM student_resources sr2
    CROSS JOIN LATERAL jsonb_object_keys(sr2.meta) AS k(key)
    WHERE k.key ~ '^snum[0-9]+'
      AND substring(k.key FROM '^snum([0-9]+)')::int > 0
    ORDER BY sr2.sid, substring(k.key FROM '^snum([0-9]+)')::int DESC
  ),
  identity AS (
    -- enrichWithResourceMeta(): 학번 형식(숫자/하이픈) 이메일만 resource.meta.id로 매칭
    SELECT
      sp.student_id,
      sp.email,
      CASE WHEN res.id IS NOT NULL THEN coalesce(nullif(sp.name, ''), res.name) ELSE sp.name END AS name,
      res.meta->'grade' AS grade,
      res.meta->'class' AS class,
      res.meta->'id' AS sid,
      res.meta->'number' AS number,
      ls.snum
    FROM student_profiles sp
    LEFT JOIN student_resources res
      ON sp.local_part ~ '^[0-9-]+$'
     AND res.sid = sp.local_part
    LEFT JOIN latest_snum ls ON ls.sid = sp.local_part
  )
  SELECT jsonb_build_object(
    'rooms', coalesce(
      (SELECT jsonb_agg(jsonb_build_array(room_id, room_name) ORDER BY idx) FROM rooms),
      '[]'::jsonb
    ),
    'students', coalesce(
      (
        SELECT jsonb_agg(
          jsonb_build_object(
            'id', i.student_id,
            'email', i.email,
            'name', i.name,
            'grade', i.grade,
            'class', i.class,
            'sid', i.sid,
            'number', i.number,
            'snum', i.snum,
            'total', a.total,
            'attended', a.attended,
            'absent', a.absent,
            'temp', a.temp,
            'wr', '{"1": [], "2": [], "3": [], "4": [], "5": []}'::jsonb || coalesce(w.wr, '{}'::jsonb),
            'att', coalesce(t.att, '{}'::jsonb)
          )
        )
        FROM agg a
        JOIN identity i ON i.student_id = a.student_id
        LEFT JOIN attendance t ON t.student_id = a.student_id
        LEFT JOIN weekday_rooms w ON w.student_id = a.student_id
      ),
      '[]'::jsonb
    )
  )
  $q$
  INTO v_result
  USING p_start, p_end, p_today, p_past_closing,
        p_attendance_increment, p_absence_decrement, p_grade, p_room_id;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."get_student_stats_bundle"("p_start" "date", "p_end" "date", "p_today" "date", "p_past_closing" boolean, "p_attendance_increment" double precision, "p_absence_decrement" double precision, "p_grade" integer, "p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_study_room_summary"("p_student_code" "text" DEFAULT NULL::"text") RETURNS TABLE("student_code" "text", "name" "text", "academic_year" integer, "total_reservations" bigint, "attended_count" bigint, "attendance_rate" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    sim.student_code,
    sim.name,
    EXTRACT(YEAR FROM sr.reservation_date)::int AS academic_year,
    COUNT(*) AS total_reservations,
    COUNT(*) FILTER (WHERE sr.is_attended = true) AS attended_count,
    CASE
      WHEN COUNT(*) > 0 THEN
        ROUND(COUNT(*) FILTER (WHERE sr.is_attended = true)::numeric / COUNT(*)::numeric * 100, 1)
      ELSE 0
    END AS attendance_rate
  FROM seat_reservations sr
  INNER JOIN student_identity_map sim ON sim.profile_id = sr.student_id
  WHERE (p_student_code IS NULL OR sim.student_code = p_student_code)
  GROUP BY sim.student_code, sim.name, EXTRACT(YEAR FROM sr.reservation_date);
$$;


ALTER FUNCTION "public"."get_student_study_room_summary"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_volunteer_flat"("p_student_code" "text" DEFAULT NULL::"text") RETURNS TABLE("student_code" "text", "name" "text", "grade" integer, "activity" "text", "institution" "text", "date_or_period" "text", "hours" integer, "cumulative_hours" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    sbi.id AS student_code,
    sbi.name,
    (vol->>'grade')::int AS grade,
    vol->>'activity' AS activity,
    vol->>'institution' AS institution,
    vol->>'dateOrPeriod' AS date_or_period,
    COALESCE((vol->>'hours')::int, 0) AS hours,
    COALESCE((vol->>'cumulativeHours')::int, 0) AS cumulative_hours
  FROM student_basic_info sbi,
    jsonb_array_elements(COALESCE(sbi.volunteer, '[]'::jsonb)) AS vol
  WHERE sbi.volunteer IS NOT NULL
    AND jsonb_array_length(sbi.volunteer) > 0
    AND (p_student_code IS NULL OR sbi.id = p_student_code);
$$;


ALTER FUNCTION "public"."get_student_volunteer_flat"("p_student_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_student_year_context"("p_student_code" "text", "p_academic_year" integer) RETURNS TABLE("grade" integer, "class_num" integer, "number" integer, "homeroom_teacher" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- entry_year (from student_code prefix) + grade - 1 = academic_year
  -- So grade = academic_year - entry_year + 1
  -- entry_year = 2000 + left(student_code, 2)::int
  WITH target_grade AS (
    SELECT p_academic_year - (2000 + SPLIT_PART(p_student_code, '-', 1)::int) + 1 AS g
  )
  SELECT
    (gi->>'grade')::int AS grade,
    (gi->>'class')::int AS class_num,
    (gi->>'number')::int AS number,
    gi->>'teacher' AS homeroom_teacher
  FROM student_basic_info sbi,
    jsonb_array_elements(COALESCE(sbi.grade_info, '[]'::jsonb)) AS gi,
    target_grade tg
  WHERE sbi.id = p_student_code
    AND (gi->>'grade')::int = tg.g;
$$;


ALTER FUNCTION "public"."get_student_year_context"("p_student_code" "text", "p_academic_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_students_by_past_class"("p_past_grade" integer, "p_past_class" integer, "p_entry_year" integer DEFAULT NULL::integer) RETURNS TABLE("student_code" "text", "name" "text", "past_grade" integer, "past_class" integer, "past_number" integer, "past_teacher" "text", "current_grade" integer, "current_class" integer, "current_number" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    sbi.id AS student_code,
    sbi.name,
    (gi->>'grade')::int AS past_grade,
    (gi->>'class')::int AS past_class,
    (gi->>'number')::int AS past_number,
    gi->>'teacher' AS past_teacher,
    sim.current_grade,
    sim.current_class,
    sim.current_number
  FROM student_basic_info sbi
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(sbi.grade_info, '[]'::jsonb)) AS gi
  LEFT JOIN student_identity_map sim ON sim.student_code = sbi.id
  WHERE (gi->>'grade')::int = p_past_grade
    AND (gi->>'class')::int = p_past_class
    AND jsonb_typeof(sbi.grade_info) = 'array'
    AND (p_entry_year IS NULL OR sbi.id LIKE LPAD((p_entry_year % 100)::text, 2, '0') || '-%')
  ORDER BY (gi->>'number')::int;
$$;


ALTER FUNCTION "public"."get_students_by_past_class"("p_past_grade" integer, "p_past_class" integer, "p_entry_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_swap_roster_fit"("p_teacher_resource_id" "uuid", "p_day_of_week" integer, "p_period" integer, "p_academic_year" integer, "p_semester" integer) RETURNS TABLE("teacher_resource_id" "uuid", "day_of_week" integer, "period" integer, "my_count" integer, "their_count" integer, "shared_count" integer, "their_conflict_count" integer, "their_conflict_names" "text"[], "my_conflict_count" integer, "my_conflict_names" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_teacher_or_admin(auth.uid()) THEN
    RAISE EXCEPTION 'teacher or admin only' USING ERRCODE = '42501';
  END IF;

  IF p_teacher_resource_id IS NULL OR p_day_of_week IS NULL OR p_period IS NULL
     OR p_academic_year IS NULL OR p_semester IS NULL THEN
    RETURN;
  END IF;

  -- 성능 요점: "학생 x 가 수업 L 에 있다" ⇔ x 의 (L 요일, L 교시) 행의 교사가 L 의 교사.
  -- 그래서 모든 판정이 유니크 인덱스 (학년도, 학기, 학생, 요일, 교시) 한 번 조회로 끝난다.
  -- (첫 구현은 학기 전체를 CTE 로 들고 CTE 끼리 EXISTS 를 걸어 호출 한 번에 3.5초였다.)
  RETURN QUERY
  WITH mine AS MATERIALIZED (
    SELECT s.resource_id AS sid, s.student_name
    FROM public.student_timetable s
    WHERE s.academic_year = p_academic_year AND s.semester = p_semester
      AND s.teacher_resource_id = p_teacher_resource_id
      AND s.day_of_week = p_day_of_week AND s.period = p_period
  ),
  my_label AS (
    SELECT tt.grade, tt.class_label
    FROM public.teacher_timetable tt
    WHERE tt.academic_year = p_academic_year AND tt.semester = p_semester
      AND tt.teacher_resource_id = p_teacher_resource_id
      AND tt.day_of_week = p_day_of_week AND tt.period = p_period
    LIMIT 1
  ),
  -- 후보 수업 (교사, 요일, 교시) = 내 학생이 듣는 다른 교사의 수업 ∪ 표기가 같은 수업
  lessons AS MATERIALIZED (
    SELECT DISTINCT s.teacher_resource_id AS tid, s.day_of_week AS d, s.period AS p
    FROM mine
    JOIN public.student_timetable s
      ON s.academic_year = p_academic_year AND s.semester = p_semester AND s.resource_id = mine.sid
    WHERE s.teacher_resource_id IS NOT NULL
      AND s.teacher_resource_id <> p_teacher_resource_id
    UNION
    SELECT DISTINCT tt.teacher_resource_id, tt.day_of_week, tt.period
    FROM public.teacher_timetable tt
    JOIN my_label ml ON tt.grade = ml.grade AND tt.class_label = ml.class_label
    WHERE tt.academic_year = p_academic_year AND tt.semester = p_semester
      AND tt.teacher_resource_id IS NOT NULL
      AND tt.teacher_resource_id <> p_teacher_resource_id
  ),
  -- 상대 학생 한 명마다: 내 시간에 무엇을 듣는가
  --   그 시간 교사 = 나        → 같은 학생(shared)
  --   다른 교사의 수업이 있다   → 맞바꾸면 겹친다(conflict)
  --   아무 수업도 없다          → 비어 있어 괜찮다
  theirs AS (
    SELECT l.tid, l.d, l.p, s.student_name,
           (o.teacher_resource_id = p_teacher_resource_id) AS shared,
           (o.resource_id IS NOT NULL
             AND o.teacher_resource_id IS DISTINCT FROM p_teacher_resource_id) AS conflict
    FROM lessons l
    JOIN public.student_timetable s
      ON s.academic_year = p_academic_year AND s.semester = p_semester
     AND s.teacher_resource_id = l.tid AND s.day_of_week = l.d AND s.period = l.p
    LEFT JOIN public.student_timetable o
      ON o.academic_year = p_academic_year AND o.semester = p_semester
     AND o.resource_id = s.resource_id AND o.day_of_week = p_day_of_week AND o.period = p_period
  ),
  -- 내 학생 한 명 × 후보 수업마다: 상대 시간에 무엇을 듣는가(교사 = 상대면 같은 학생)
  my_side AS (
    SELECT l.tid, l.d, l.p, m.student_name,
           (o.resource_id IS NOT NULL
             AND o.teacher_resource_id IS DISTINCT FROM l.tid) AS conflict
    FROM lessons l
    CROSS JOIN mine m
    LEFT JOIN public.student_timetable o
      ON o.academic_year = p_academic_year AND o.semester = p_semester
     AND o.resource_id = m.sid AND o.day_of_week = l.d AND o.period = l.p
  ),
  their_agg AS (
    SELECT t.tid, t.d, t.p,
           count(*)::int AS their_count,
           count(*) FILTER (WHERE t.shared)::int AS shared_count,
           count(*) FILTER (WHERE t.conflict)::int AS conflict_count,
           (array_agg(t.student_name ORDER BY t.student_name) FILTER (WHERE t.conflict))[1:3] AS names
    FROM theirs t GROUP BY t.tid, t.d, t.p
  ),
  my_agg AS (
    SELECT x.tid, x.d, x.p,
           count(*) FILTER (WHERE x.conflict)::int AS conflict_count,
           (array_agg(x.student_name ORDER BY x.student_name) FILTER (WHERE x.conflict))[1:3] AS names
    FROM my_side x GROUP BY x.tid, x.d, x.p
  )
  SELECT
    l.tid,
    l.d,
    l.p,
    (SELECT count(*)::int FROM mine),
    coalesce(ta.their_count, 0),
    coalesce(ta.shared_count, 0),
    coalesce(ta.conflict_count, 0),
    ta.names,
    coalesce(ma.conflict_count, 0),
    ma.names
  FROM lessons l
  LEFT JOIN their_agg ta ON ta.tid = l.tid AND ta.d = l.d AND ta.p = l.p
  LEFT JOIN my_agg    ma ON ma.tid = l.tid AND ma.d = l.d AND ma.p = l.p;
END;
$$;


