CREATE OR REPLACE FUNCTION "public"."get_teacher_timetables_for_swap"("target_grade" integer, "target_class" integer, "p_academic_year" integer, "p_semester" integer) RETURNS TABLE("id" "text", "period" integer, "weekday" integer, "subject" "text", "section_name" "text", "teacher_name" "text", "grade" integer, "class_number" integer, "resource_id" "uuid", "section_id" "uuid", "weekday_time" "text", "activity_type" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    (sec.id::text || '-' || tt.day_of_week::text || tt.period::text) AS id,
    tt.period                                               AS period,
    tt.day_of_week                                          AS weekday,
    sec.name                                                AS subject,
    sec.name                                                AS section_name,
    tt.teacher_name                                         AS teacher_name,
    (sec.meta ->> 'grade')::integer                         AS grade,
    (sec.meta ->> 'class')::integer                         AS class_number,
    tt.teacher_resource_id                                  AS resource_id,
    sec.id                                                  AS section_id,
    (tt.day_of_week::text || tt.period::text)               AS weekday_time,
    tt.activity_type                                        AS activity_type
  FROM public.teacher_timetable tt
  JOIN public.section sec
    ON sec.name = (tt.subject_name || ' ' || tt.grade || '-' || tt.class_label)
  WHERE tt.academic_year = p_academic_year
    AND tt.semester      = p_semester
    AND tt.teacher_resource_id IS NOT NULL
    AND tt.class_label IS NOT NULL
    AND tt.day_of_week BETWEEN 1 AND 7
    AND tt.period      BETWEEN 1 AND 8;
$$;


