CREATE OR REPLACE FUNCTION "public"."get_training_by_token"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  t record;
  m record;
  v_exp timestamptz;
  v_signed boolean;
begin
  select * into t from public.training_sign_token where token = p_token;
  if t.token is null then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  select id, kind, starts_at, ends_at, meta into m from public.meeting where id = t.meeting_id;
  if m.id is null or m.kind <> 'training' or not coalesce((m.meta->'assignee') ? t.signer_name, false) then
    return jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  select expires_at into v_exp from public.training_sign_link where meeting_id = m.id;
  v_signed := exists (select 1 from public.training_signature s where s.meeting_id = m.id and s.signer_name = t.signer_name);
  if not v_signed and v_exp is not null and v_exp < now() then
    return jsonb_build_object('ok', false, 'reason', 'expired');
  end if;
  -- 참석자 명단·남의 서명은 내보내지 않는다
  return jsonb_build_object(
    'ok', true,
    'title', coalesce(m.meta->>'title', '연수'),
    'starts_at', m.starts_at,
    'ends_at', m.ends_at,
    'location', nullif(coalesce(m.meta->>'room_name', m.meta->>'location'), ''),
    'signer_name', t.signer_name,
    'signed', v_signed,
    'expires_at', v_exp);
end;
$$;


ALTER FUNCTION "public"."get_training_by_token"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_training_sign_links"("p_meeting_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  m record;
  v_all boolean;
  v_me text;
  v_link record;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  select id, kind, meta, created_by, creator into m from public.meeting where id = p_meeting_id;
  if m.id is null or m.kind <> 'training' then raise exception '연수 일정을 찾을 수 없습니다.' using errcode = 'P0002'; end if;
  select * into v_link from public.training_sign_link where meeting_id = m.id;
  if v_link.meeting_id is null then
    -- 이 기능 전에 만든 연수 — 링크가 없다(오류가 아니라 «없음»)
    return jsonb_build_object('enabled', false);
  end if;

  v_all := public.is_training_creator(m.id) or public.is_admin();
  v_me := public.current_profile_name();
  if not v_all and not coalesce((m.meta->'assignee') ? v_me, false) then
    raise exception '이 연수의 서명 링크를 볼 수 없습니다.' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'enabled', true,
    'can_manage', v_all,
    'expires_at', v_link.expires_at,
    'expires_custom', v_link.expires_custom,
    'default_expires_at', public.training_sign_default_expiry((select ends_at from public.meeting where id = m.id)),
    'links', coalesce((
      select jsonb_agg(jsonb_build_object(
               'signer_name', t.signer_name,
               'token', t.token,
               'signed', exists (select 1 from public.training_signature s where s.meeting_id = m.id and s.signer_name = t.signer_name))
             order by t.signer_name)
        from public.training_sign_token t
       where t.meeting_id = m.id and (v_all or t.signer_name = v_me)), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."get_training_sign_links"("p_meeting_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_ranking_position"("_user_id" "uuid") RETURNS TABLE("user_id" "uuid", "author_nickname" "text", "author_email" "text", "total_problems" bigint, "total_solutions" bigint, "total_likes" bigint, "total_saves" bigint, "total_score" bigint, "last_activity" timestamp with time zone, "ranking_position" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  WITH ranked_users AS (
    SELECT 
      p.id as user_id,
      p.nickname as author_nickname,
      p.email as author_email,
      p.problems_registered::bigint as total_problems,
      p.solutions_registered::bigint as total_solutions,
      (COALESCE((
        SELECT SUM(pr.likes_count) 
        FROM public.problems pr 
        WHERE pr.user_id = p.id
      ), 0) + COALESCE((
        SELECT SUM(ps.likes_count) 
        FROM public.problem_solutions ps 
        WHERE ps.user_id = p.id
      ), 0))::bigint as total_likes,
      COALESCE((
        SELECT SUM(pr.saves_count) 
        FROM public.problems pr 
        WHERE pr.user_id = p.id
      ), 0)::bigint as total_saves,
      (p.problems_registered + p.solutions_registered + COALESCE((
        SELECT SUM(pr.likes_count) 
        FROM public.problems pr 
        WHERE pr.user_id = p.id
      ), 0) + COALESCE((
        SELECT SUM(ps.likes_count) 
        FROM public.problem_solutions ps 
        WHERE ps.user_id = p.id
      ), 0))::bigint as total_score,
      p.updated_at as last_activity,
      ROW_NUMBER() OVER (
        ORDER BY (
          p.problems_registered + p.solutions_registered + COALESCE((
            SELECT SUM(pr.likes_count) 
            FROM public.problems pr 
            WHERE pr.user_id = p.id
          ), 0) + COALESCE((
            SELECT SUM(ps.likes_count) 
            FROM public.problem_solutions ps 
            WHERE ps.user_id = p.id
          ), 0)
        ) DESC
      ) as ranking_position
    FROM public.profiles p
    WHERE p.problems_registered > 0 OR p.solutions_registered > 0 OR p.total_likes_received > 0
  )
  SELECT 
    ru.user_id,
    ru.author_nickname,
    ru.author_email,
    ru.total_problems,
    ru.total_solutions,
    ru.total_likes,
    ru.total_saves,
    ru.total_score,
    ru.last_activity,
    ru.ranking_position
  FROM ranked_users ru
  WHERE ru.user_id = _user_id;
END;
$$;


ALTER FUNCTION "public"."get_user_ranking_position"("_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_rankings"() RETURNS TABLE("user_id" "uuid", "author_nickname" "text", "author_email" "text", "total_problems" bigint, "total_solutions" bigint, "total_likes" bigint, "total_saves" bigint, "total_score" bigint, "last_activity" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p.id as user_id,
    p.nickname as author_nickname,
    p.email as author_email,
    p.problems_registered::bigint as total_problems,
    p.solutions_registered::bigint as total_solutions,
    (COALESCE((
      SELECT SUM(pr.likes_count) 
      FROM public.problems pr 
      WHERE pr.user_id = p.id
    ), 0) + COALESCE((
      SELECT SUM(ps.likes_count) 
      FROM public.problem_solutions ps 
      WHERE ps.user_id = p.id
    ), 0))::bigint as total_likes,
    COALESCE((
      SELECT SUM(pr.saves_count) 
      FROM public.problems pr 
      WHERE pr.user_id = p.id
    ), 0)::bigint as total_saves,
    -- total_score: problems + solutions + likes (no saves)
    (p.problems_registered + p.solutions_registered + COALESCE((
      SELECT SUM(pr.likes_count) 
      FROM public.problems pr 
      WHERE pr.user_id = p.id
    ), 0) + COALESCE((
      SELECT SUM(ps.likes_count) 
      FROM public.problem_solutions ps 
      WHERE ps.user_id = p.id
    ), 0))::bigint as total_score,
    p.updated_at as last_activity
  FROM public.profiles p
  WHERE (p.problems_registered > 0 OR p.solutions_registered > 0 OR p.total_likes_received > 0)
    AND p.email != 'user597@example.com'
  ORDER BY total_score DESC
  LIMIT 20;
END;
$$;


ALTER FUNCTION "public"."get_user_rankings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_rankings_1month"() RETURNS TABLE("user_id" "uuid", "author_nickname" "text", "author_email" "text", "total_problems" bigint, "total_solutions" bigint, "total_likes" bigint, "total_saves" bigint, "total_score" bigint, "last_activity" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY
  WITH user_stats AS (
    SELECT 
      p.id as user_id,
      p.nickname as author_nickname,
      p.email as author_email,
      -- Problems in last month
      COALESCE((
        SELECT COUNT(*)
        FROM public.problems pr
        WHERE pr.user_id = p.id AND pr.created_at >= NOW() - INTERVAL '30 days'
      ), 0)::bigint as total_problems,
      -- Solutions in last month
      COALESCE((
        SELECT COUNT(*)
        FROM public.problem_solutions ps
        WHERE ps.user_id = p.id AND ps.created_at >= NOW() - INTERVAL '30 days'
      ), 0)::bigint as total_solutions,
      -- Total likes from problems + solutions in last month
      (COALESCE((
        SELECT SUM(pr.likes_count)
        FROM public.problems pr
        WHERE pr.user_id = p.id AND pr.created_at >= NOW() - INTERVAL '30 days'
      ), 0) + COALESCE((
        SELECT SUM(ps.likes_count)
        FROM public.problem_solutions ps
        WHERE ps.user_id = p.id AND ps.created_at >= NOW() - INTERVAL '30 days'
      ), 0))::bigint AS total_likes,
      -- Total saves from problems in last month
      COALESCE((
        SELECT SUM(pr.saves_count)
        FROM public.problems pr
        WHERE pr.user_id = p.id AND pr.created_at >= NOW() - INTERVAL '30 days'
      ), 0)::bigint as total_saves,
      -- Last activity
      GREATEST(
        (SELECT MAX(pr.created_at) FROM public.problems pr WHERE pr.user_id = p.id AND pr.created_at >= NOW() - INTERVAL '30 days'),
        (SELECT MAX(ps.created_at) FROM public.problem_solutions ps WHERE ps.user_id = p.id AND ps.created_at >= NOW() - INTERVAL '30 days')
      ) as last_activity
    FROM public.profiles p
    WHERE p.email != 'user597@example.com'
  )
  SELECT 
    us.user_id,
    us.author_nickname,
    us.author_email,
    us.total_problems,
    us.total_solutions,
    us.total_likes,
    us.total_saves,
    -- total_score: problems + solutions + likes (no saves)
    (us.total_problems + us.total_solutions + us.total_likes)::bigint as total_score,
    us.last_activity
  FROM user_stats us
  WHERE us.total_problems > 0 OR us.total_solutions > 0 OR us.total_likes > 0 OR us.total_saves > 0
  ORDER BY (us.total_problems + us.total_solutions + us.total_likes) DESC
  LIMIT 20;
END;
$$;


ALTER FUNCTION "public"."get_user_rankings_1month"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_rankings_daily"("month_offset" integer DEFAULT 0) RETURNS TABLE("day_number" integer, "day_date" "date", "user_id" "uuid", "author_nickname" "text", "author_email" "text", "daily_problems" bigint, "daily_solutions" bigint, "daily_likes" bigint, "daily_saves" bigint, "daily_score" bigint, "cumulative_problems" bigint, "cumulative_solutions" bigint, "cumulative_likes" bigint, "cumulative_saves" bigint, "cumulative_score" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'Asia/Seoul'
    AS $$
DECLARE
  start_date DATE;
  end_date DATE;
  current_date_iter DATE;
  day_count INT := 0;
BEGIN
  -- Calculate date range based on month_offset using Seoul timezone
  IF month_offset = 0 THEN
    -- Current month: from start of current month to now (Seoul time)
    start_date := date_trunc('month', NOW() AT TIME ZONE 'Asia/Seoul')::DATE;
    end_date := (NOW() AT TIME ZONE 'Asia/Seoul')::DATE;
  ELSE
    -- Previous months: complete calendar months (Seoul time)
    start_date := date_trunc('month', (NOW() AT TIME ZONE 'Asia/Seoul') - INTERVAL '1 month' * month_offset)::DATE;
    end_date := (date_trunc('month', (NOW() AT TIME ZONE 'Asia/Seoul') - INTERVAL '1 month' * (month_offset - 1)) - INTERVAL '1 day')::DATE;
  END IF;

  -- Generate data for each day in the range
  current_date_iter := start_date;
  
  WHILE current_date_iter <= end_date LOOP
    day_count := day_count + 1;
    
    RETURN QUERY
    WITH daily_stats AS (
      SELECT 
        p.id as user_id,
        p.nickname as author_nickname,
        p.email as author_email,
        -- Daily problems (created on this specific day in Seoul timezone)
        COALESCE((
          SELECT COUNT(*)
          FROM public.problems pr
          WHERE pr.user_id = p.id 
            AND (pr.created_at AT TIME ZONE 'Asia/Seoul')::DATE = current_date_iter
        ), 0)::bigint as daily_problems,
        -- Daily solutions (created on this specific day in Seoul timezone)
        COALESCE((
          SELECT COUNT(*)
          FROM public.problem_solutions ps
          WHERE ps.user_id = p.id 
            AND (ps.created_at AT TIME ZONE 'Asia/Seoul')::DATE = current_date_iter
        ), 0)::bigint as daily_solutions,
        -- Daily likes from problems + solutions created on this day
        (COALESCE((
          SELECT SUM(pr.likes_count)
          FROM public.problems pr
          WHERE pr.user_id = p.id 
            AND (pr.created_at AT TIME ZONE 'Asia/Seoul')::DATE = current_date_iter
        ), 0) + COALESCE((
          SELECT SUM(ps.likes_count)
          FROM public.problem_solutions ps
          WHERE ps.user_id = p.id 
            AND (ps.created_at AT TIME ZONE 'Asia/Seoul')::DATE = current_date_iter
        ), 0))::bigint AS daily_likes,
        -- Daily saves from problems created on this day
        COALESCE((
          SELECT SUM(pr.saves_count)
          FROM public.problems pr
          WHERE pr.user_id = p.id 
            AND (pr.created_at AT TIME ZONE 'Asia/Seoul')::DATE = current_date_iter
        ), 0)::bigint as daily_saves,
        -- Cumulative problems (from start of month to current day, Seoul timezone)
        COALESCE((
          SELECT COUNT(*)
          FROM public.problems pr
          WHERE pr.user_id = p.id 
            AND pr.created_at AT TIME ZONE 'Asia/Seoul' >= start_date::timestamp
            AND (pr.created_at AT TIME ZONE 'Asia/Seoul')::DATE <= current_date_iter
        ), 0)::bigint as cumulative_problems,
        -- Cumulative solutions (from start of month to current day, Seoul timezone)
        COALESCE((
          SELECT COUNT(*)
          FROM public.problem_solutions ps
          WHERE ps.user_id = p.id 
            AND ps.created_at AT TIME ZONE 'Asia/Seoul' >= start_date::timestamp
            AND (ps.created_at AT TIME ZONE 'Asia/Seoul')::DATE <= current_date_iter
        ), 0)::bigint as cumulative_solutions,
        -- Cumulative likes from problems + solutions (from start of month to current day, Seoul timezone)
        (COALESCE((
          SELECT SUM(pr.likes_count)
          FROM public.problems pr
          WHERE pr.user_id = p.id 
            AND pr.created_at AT TIME ZONE 'Asia/Seoul' >= start_date::timestamp
            AND (pr.created_at AT TIME ZONE 'Asia/Seoul')::DATE <= current_date_iter
        ), 0) + COALESCE((
          SELECT SUM(ps.likes_count)
          FROM public.problem_solutions ps
          WHERE ps.user_id = p.id 
            AND ps.created_at AT TIME ZONE 'Asia/Seoul' >= start_date::timestamp
            AND (ps.created_at AT TIME ZONE 'Asia/Seoul')::DATE <= current_date_iter
        ), 0))::bigint AS cumulative_likes,
        -- Cumulative saves from problems (from start of month to current day, Seoul timezone)
        COALESCE((
          SELECT SUM(pr.saves_count)
          FROM public.problems pr
          WHERE pr.user_id = p.id 
            AND pr.created_at AT TIME ZONE 'Asia/Seoul' >= start_date::timestamp
            AND (pr.created_at AT TIME ZONE 'Asia/Seoul')::DATE <= current_date_iter
        ), 0)::bigint as cumulative_saves
      FROM public.profiles p
      WHERE p.email != 'user597@example.com'
    )
    SELECT 
      day_count,
      current_date_iter,
      ds.user_id,
      ds.author_nickname,
      ds.author_email,
      ds.daily_problems,
      ds.daily_solutions,
      ds.daily_likes,
      ds.daily_saves,
      -- daily_score: problems + solutions + likes (no saves for daily)
      (ds.daily_problems + ds.daily_solutions + ds.daily_likes)::bigint as daily_score,
      ds.cumulative_problems,
      ds.cumulative_solutions,
      ds.cumulative_likes,
      ds.cumulative_saves,
      -- cumulative_score: problems + solutions + likes (no saves)
      (ds.cumulative_problems + ds.cumulative_solutions + ds.cumulative_likes)::bigint as cumulative_score
    FROM daily_stats ds
    WHERE ds.cumulative_problems > 0 OR ds.cumulative_solutions > 0 OR ds.cumulative_likes > 0 OR ds.cumulative_saves > 0
    ORDER BY (ds.cumulative_problems + ds.cumulative_solutions + ds.cumulative_likes) DESC
    LIMIT 10; -- Top 10 users per day
    
    current_date_iter := current_date_iter + INTERVAL '1 day';
  END LOOP;
  
END;
$$;


ALTER FUNCTION "public"."get_user_rankings_daily"("month_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_rankings_monthly"("month_offset" integer DEFAULT 0) RETURNS TABLE("user_id" "uuid", "author_nickname" "text", "author_email" "text", "total_problems" bigint, "total_solutions" bigint, "total_likes" bigint, "total_saves" bigint, "total_score" bigint, "last_activity" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  start_date timestamp with time zone;
  end_date timestamp with time zone;
BEGIN
  -- Calculate date range based on month_offset using Seoul timezone
  IF month_offset = 0 THEN
    -- Current month: from start of current month to now (Seoul time)
    start_date := date_trunc('month', NOW() AT TIME ZONE 'Asia/Seoul') AT TIME ZONE 'Asia/Seoul';
    end_date := NOW() AT TIME ZONE 'Asia/Seoul';
  ELSE
    -- Previous months: complete calendar months (Seoul time)  
    start_date := date_trunc('month', (NOW() AT TIME ZONE 'Asia/Seoul') - INTERVAL '1 month' * month_offset) AT TIME ZONE 'Asia/Seoul';
    end_date := date_trunc('month', (NOW() AT TIME ZONE 'Asia/Seoul') - INTERVAL '1 month' * (month_offset - 1)) AT TIME ZONE 'Asia/Seoul';
  END IF;

  RETURN QUERY
  WITH user_stats AS (
    SELECT 
      p.id as user_id,
      p.nickname as author_nickname,
      p.email as author_email,
      -- Problems in specified month (using original logic with Seoul timezone dates)
      COALESCE((
        SELECT COUNT(*)
        FROM public.problems pr
        WHERE pr.user_id = p.id 
          AND pr.created_at >= start_date 
          AND pr.created_at < end_date
      ), 0)::bigint as total_problems,
      -- Solutions in specified month
      COALESCE((
        SELECT COUNT(*)
        FROM public.problem_solutions ps
        WHERE ps.user_id = p.id 
          AND ps.created_at >= start_date 
          AND ps.created_at < end_date
      ), 0)::bigint as total_solutions,
      -- Total likes from problems + solutions in specified month
      (COALESCE((
        SELECT SUM(pr.likes_count)
        FROM public.problems pr
        WHERE pr.user_id = p.id 
          AND pr.created_at >= start_date 
          AND pr.created_at < end_date
      ), 0) + COALESCE((
        SELECT SUM(ps.likes_count)
        FROM public.problem_solutions ps
        WHERE ps.user_id = p.id 
          AND ps.created_at >= start_date 
          AND ps.created_at < end_date
      ), 0))::bigint AS total_likes,
      -- Total saves from problems in specified month
      COALESCE((
        SELECT SUM(pr.saves_count)
        FROM public.problems pr
        WHERE pr.user_id = p.id 
          AND pr.created_at >= start_date 
          AND pr.created_at < end_date
      ), 0)::bigint as total_saves,
      -- Last activity in specified month (keep original timestamp with time zone)
      GREATEST(
        (SELECT MAX(pr.created_at) 
         FROM public.problems pr 
         WHERE pr.user_id = p.id 
           AND pr.created_at >= start_date 
           AND pr.created_at < end_date),
        (SELECT MAX(ps.created_at) 
         FROM public.problem_solutions ps 
         WHERE ps.user_id = p.id 
           AND ps.created_at >= start_date 
           AND ps.created_at < end_date)
      ) as last_activity
    FROM public.profiles p
    WHERE p.email != 'user597@example.com'
  )
  SELECT 
    us.user_id,
    us.author_nickname,
    us.author_email,
    us.total_problems,
    us.total_solutions,
    us.total_likes,
    us.total_saves,
    -- total_score: problems + solutions + likes (no saves)
    (us.total_problems + us.total_solutions + us.total_likes)::bigint as total_score,
    us.last_activity
  FROM user_stats us
  WHERE us.total_problems > 0 OR us.total_solutions > 0 OR us.total_likes > 0 OR us.total_saves > 0
  ORDER BY (us.total_problems + us.total_solutions + us.total_likes) DESC
  LIMIT 20;
END;
$$;


