    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_access_key text := 'google_access_token:' || p_user_id::text;
  v_refresh_key text := 'google_refresh_token:' || p_user_id::text;
BEGIN
  RETURN QUERY
  SELECT
    (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = v_access_key LIMIT 1) AS access_token,
    (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = v_refresh_key LIMIT 1) AS refresh_token;
END;
$$;


