CREATE OR REPLACE FUNCTION "public"."get_weekday_crosstab"("p_start" "date", "p_end" "date", "p_grade" integer DEFAULT NULL::integer) RETURNS TABLE("room_id" "uuid", "room_name" "text", "by_day" "jsonb", "total" bigint, "unique_students" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT DISTINCT sr.room_id, sr.reservation_date, sr.student_id
    FROM seat_reservations sr
    WHERE sr.reservation_date BETWEEN p_start AND p_end
      AND (
        p_grade IS NULL
        OR sr.student_id IN (
          SELECT p.id
          FROM profiles p
          JOIN resource res ON res.meta->>'id' || '@myschool.hs.kr' = p.email
          WHERE res.meta->>'grade' = p_grade::text
        )
      )
  ),
  d AS (
    SELECT b.*, extract(dow FROM b.reservation_date)::int AS dow FROM base b
  )
  SELECT
    d.room_id,
    coalesce(r.name, '알 수 없음'),
    jsonb_build_object(
      '0', count(*) FILTER (WHERE d.dow = 0),
      '1', count(*) FILTER (WHERE d.dow = 1),
      '2', count(*) FILTER (WHERE d.dow = 2),
      '3', count(*) FILTER (WHERE d.dow = 3),
      '4', count(*) FILTER (WHERE d.dow = 4),
      '5', count(*) FILTER (WHERE d.dow = 5),
      '6', count(*) FILTER (WHERE d.dow = 6)
    ),
    count(*),
    count(DISTINCT d.student_id) FILTER (WHERE d.dow BETWEEN 1 AND 5)
  FROM d
  LEFT JOIN study_rooms r ON r.id = d.room_id
  GROUP BY d.room_id, r.name;
$$;


ALTER FUNCTION "public"."get_weekday_crosstab"("p_start" "date", "p_end" "date", "p_grade" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_wishlist_mock"("p_student_code" "text") RETURNS TABLE("academic_year" integer, "exam_month" integer, "subject" "text", "grade" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_latest jsonb;
BEGIN
  IF NOT (
    public.is_wishlist_owner(p_student_code)
    OR public.can_read_wishlist(p_student_code)
  ) THEN
    RETURN;
  END IF;

  SELECT mr INTO v_latest
  FROM student_basic_info sbi,
       jsonb_array_elements(sbi.mock_result) mr
  WHERE sbi.id = p_student_code
    AND sbi.mock_result IS NOT NULL
    AND jsonb_typeof(sbi.mock_result) = 'array'
  ORDER BY (mr->>'academic_year')::int DESC NULLS LAST, (mr->>'exam_month')::int DESC NULLS LAST
  LIMIT 1;

  IF v_latest IS NULL THEN RETURN; END IF;

  RETURN QUERY
  SELECT
    (v_latest->>'academic_year')::int,
    (v_latest->>'exam_month')::int,
    e.key AS subject,
    NULLIF(e.value->>'grade','')::int AS grade
  FROM jsonb_each(v_latest->'subjects') e(key, value)
  WHERE NULLIF(e.value->>'grade','') IS NOT NULL;
END $$;


ALTER FUNCTION "public"."get_wishlist_mock"("p_student_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_wishlist_mock"("p_student_code" "text") IS '수능최저 판정용 학생 최근 모의고사 영역별 등급(mock_result 최근 회차). DEFINER + 위시리스트 권한 게이트.';



