CREATE OR REPLACE FUNCTION "public"."get_wishlist_naesin"("p_student_code" "text") RETURNS TABLE("avg_grade" numeric, "subject_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT (
    public.is_wishlist_owner(p_student_code)
    OR public.can_read_wishlist(p_student_code)
  ) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    CASE WHEN SUM(saf.units) FILTER (WHERE saf.rank IS NOT NULL AND saf.units > 0) > 0
      THEN ROUND(
        SUM(saf.rank * saf.units) FILTER (WHERE saf.rank IS NOT NULL AND saf.units > 0)
        / SUM(saf.units) FILTER (WHERE saf.rank IS NOT NULL AND saf.units > 0), 3)
      ELSE NULL
    END AS avg_grade,
    COUNT(*) FILTER (WHERE saf.rank IS NOT NULL AND saf.units > 0)::int AS subject_count
  FROM public.student_academic_flat saf
  WHERE saf.student_code = p_student_code
    AND saf.category = 'regular';
END $$;


