COMMENT ON FUNCTION "public"."get_wishlist_naesin"("p_student_code" "text") IS '적합도 판정용 학점 가중 내신 평균. SECURITY DEFINER(authenticated 가 student_academic_flat MV 직접 SELECT 불가하므로) + 위시리스트 동일 권한 게이트(본인/케어/admin). 권한 없으면 빈 결과.';



CREATE OR REPLACE FUNCTION "public"."get_wishlist_subjects"("p_student_code" "text") RETURNS TABLE("academic_year" integer, "grade" integer, "semester" integer, "category" "text", "subject_group" "text", "subject" "text", "units" numeric, "rank" numeric, "achievement" "text", "score" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_entry_year integer;
BEGIN
  IF NOT (
    public.is_wishlist_owner(p_student_code)
    OR public.can_read_wishlist(p_student_code)
  ) THEN
    RETURN;
  END IF;

  v_entry_year := 2000 + split_part(p_student_code, '-', 1)::int;

  RETURN QUERY
  SELECT
    (v_entry_year + saf.grade - 1) AS academic_year,
    saf.grade, saf.semester, saf.category, saf.subject_group, saf.subject,
    saf.units, saf.rank, saf.achievement, saf.score
  FROM public.student_academic_flat saf
  WHERE saf.student_code = p_student_code
    AND saf.category IN ('regular', 'career', 'general')
  ORDER BY saf.grade, saf.semester, saf.subject_group, saf.subject;
END $$;


ALTER FUNCTION "public"."get_wishlist_subjects"("p_student_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_wishlist_subjects"("p_student_code" "text") IS '적합도 전형 맞춤 계산용 학생 과목별 기록. category regular(정량)+career(진로선택)+general 반환, 예체능(pe_arts) 제외. 진로선택은 rank null·성취도만 → 클라이언트가 환산. SECURITY DEFINER + 위시리스트 권한 게이트.';



CREATE OR REPLACE FUNCTION "public"."get_work_detail"("p_event_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "status" "text", "keywords" "text"[], "manager_id" "uuid", "manager_name" "text", "manager_type" "text", "meta" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "tasks" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        e.id,
        e.name,
        e.description,
        e.status,
        e.keywords,
        e.manager_id,
        r.name AS manager_name,
        r.type AS manager_type,
        e.meta,
        e.created_at,
        e.updated_at,
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', t.id,
                        'title', t.title,
                        'description', t.description,
                        'type', t.type,
                        'status', t.status,
                        'due_date', t.due_date,
                        'order_index', t.order_index,
                        'keywords', t.keywords,
                        'meta', t.meta,  -- Return full meta including assignees
                        'created_by', t.created_by,
                        'created_at', t.created_at,
                        'updated_at', t.updated_at,
                        -- Completion statistics
                        'completion_stats', jsonb_build_object(
                            'total', jsonb_array_length(COALESCE(t.meta->'assignees', '[]'::JSONB)),
                            'completed', (
                                SELECT COUNT(*)
                                FROM jsonb_array_elements(COALESCE(t.meta->'assignees', '[]'::JSONB)) AS assignee
                                WHERE assignee->>'status' = 'completed'
                            ),
                            'pending', (
                                SELECT COUNT(*)
                                FROM jsonb_array_elements(COALESCE(t.meta->'assignees', '[]'::JSONB)) AS assignee
                                WHERE assignee->>'status' = 'pending'
                            )
                        )
                    )
                    ORDER BY
                        CASE WHEN t.type = 'procedural' THEN t.order_index ELSE 999999 END,
                        t.created_at
                )
                FROM task t
                WHERE t.event_id = e.id
            ),
            '[]'::JSONB
        ) AS tasks
    FROM work e
    LEFT JOIN resource r ON e.manager_id = r.id
    WHERE e.id = p_event_id;
END;
$$;


ALTER FUNCTION "public"."get_work_detail"("p_event_id" "uuid") OWNER TO "postgres";


