CREATE OR REPLACE FUNCTION "public"."get_work_knowledge"("p_work_id" "uuid", "p_include_archived" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = '로그인이 필요합니다.';
  end if;
  if not public.can_view_work_events(p_work_id) then
    return jsonb_build_object('can_view', false);
  end if;
  return jsonb_build_object(
    'can_view', true,
    'can_write', public.can_manage_work_structure(p_work_id),
    'lineage', (select jsonb_agg(jsonb_build_object('work_id', l.work_id, 'name', w.name, 'year', w.meta->'year', 'generations_ago', l.depth) order by l.depth)
                from mcp_private.work_lineage(p_work_id) l join public.work w on w.id = l.work_id),
    'items', mcp_private.wk_knowledge(p_work_id, null, null, coalesce(p_include_archived, false), 200));
end;
$$;


