CREATE OR REPLACE FUNCTION "public"."get_works"("p_status" "text" DEFAULT NULL::"text", "p_manager_id" "uuid" DEFAULT NULL::"uuid", "p_keyword" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "manager_id" "uuid", "manager_name" "text", "status" "text", "keywords" "text"[], "total_tasks" bigint, "completed_tasks" bigint, "pending_tasks" bigint, "progress_percentage" numeric, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        te.id,
        te.name,
        te.description,
        te.manager_id,
        r.name as manager_name,
        te.status,
        te.keywords,
        COUNT(t.id) as total_tasks,
        COUNT(CASE WHEN t.status = 'completed' THEN 1 END) as completed_tasks,
        COUNT(CASE WHEN t.status != 'completed' THEN 1 END) as pending_tasks,
        CASE 
            WHEN COUNT(t.id) = 0 THEN 0
            ELSE ROUND((COUNT(CASE WHEN t.status = 'completed' THEN 1 END)::numeric / COUNT(t.id)::numeric) * 100, 1)
        END as progress_percentage,
        te.created_at,
        te.updated_at
    FROM task_event te
    LEFT JOIN resource r ON te.manager_id = r.id
    LEFT JOIN task t ON te.id = t.event_id
    WHERE (p_status IS NULL OR te.status = p_status)
      AND (p_manager_id IS NULL OR te.manager_id = p_manager_id)
      AND (p_keyword IS NULL OR 
           te.name ILIKE '%' || p_keyword || '%' OR 
           te.description ILIKE '%' || p_keyword || '%' OR
           te.keywords && string_to_array(p_keyword, ' ') OR
           array_to_string(te.keywords, ' ') ILIKE '%' || p_keyword || '%')
    GROUP BY te.id, r.name, te.keywords
    ORDER BY te.created_at DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."get_works"("p_status" "text", "p_manager_id" "uuid", "p_keyword" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_attendance_points"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_points INTEGER;
  v_description TEXT;
  v_ref_id TEXT;
BEGIN
  IF OLD.attendance_status IS DISTINCT FROM NEW.attendance_status THEN
    v_ref_id := NEW.id::TEXT;

    IF OLD.attendance_status = 'attended' THEN
      DELETE FROM point_transactions
      WHERE reference_id = v_ref_id
        AND type = 'attendance';
    END IF;

    IF NEW.attendance_status = 'attended' THEN
      v_points := 10;
      v_description := '출석 포인트';

      INSERT INTO point_transactions (student_id, amount, type, reference_id, description)
      VALUES (NEW.student_id, v_points, 'attendance', v_ref_id, v_description);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."grant_attendance_points"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_review_points"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ref_id TEXT;
BEGIN
  IF OLD.feedback_rating IS NULL AND NEW.feedback_rating IS NOT NULL THEN
    v_ref_id := NEW.id::TEXT;

    IF NOT EXISTS (
      SELECT 1 FROM point_transactions
      WHERE reference_id = v_ref_id AND type = 'review'
    ) THEN
      INSERT INTO point_transactions (student_id, amount, type, reference_id, description)
      VALUES (NEW.student_id, 3, 'review', v_ref_id, '리뷰 작성 포인트');
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


