    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is not null and exists (select 1 from public.collect_request where action_id = old.id) then
    raise exception '입력을 받기 시작한 작업은 지울 수 없습니다 — 빼면 보관됩니다' using errcode = '23503';
  end if;
  return old;
end;
$$;


