CREATE OR REPLACE FUNCTION "public"."guard_purchase_request_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (NEW.status IS DISTINCT FROM OLD.status
      OR NEW.status_reason IS DISTINCT FROM OLD.status_reason
      OR (NEW.meta -> 'itemStatus') IS DISTINCT FROM (OLD.meta -> 'itemStatus'))
     AND NOT is_purchase_page_manager(NEW.page_id) THEN
    NEW.status := OLD.status;
    NEW.status_reason := OLD.status_reason;
    NEW.status_updated_at := OLD.status_updated_at;
    -- meta 의 나머지 키는 신청자가 쓸 수 있게 두고 itemStatus 만 되돌린다
    NEW.meta := CASE
      WHEN (OLD.meta -> 'itemStatus') IS NULL
        THEN coalesce(NEW.meta, '{}'::jsonb) - 'itemStatus'
      ELSE jsonb_set(coalesce(NEW.meta, '{}'::jsonb), '{itemStatus}', OLD.meta -> 'itemStatus', true)
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_purchase_request_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_signature_due"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status is distinct from old.status and new.status in ('signed', 'rejected')
     and exists (select 1 from public.signature_request r
                  where r.id = new.request_id and r.status = 'pending' and r.due_at < now()) then
    raise exception '서명 마감이 지났습니다.' using errcode = '22023';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_signature_due"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_submission_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_id text;
  v_unit record;
begin
  for v_id in
    select n.value->>'id'
    from jsonb_array_elements(case when jsonb_typeof(new.meta->'assignees') = 'array'
                                   then new.meta->'assignees' else '[]'::jsonb end) n(value)
    where coalesce(n.value->>'status', 'pending') = 'completed'
      and not exists (
        select 1 from jsonb_array_elements(case when jsonb_typeof(old.meta->'assignees') = 'array'
                                                then old.meta->'assignees' else '[]'::jsonb end) o(value)
        where o.value->>'id' = n.value->>'id' and coalesce(o.value->>'status', 'pending') = 'completed')
  loop
    if v_id ~ '^[0-9a-fA-F-]{36}$' and public.assignee_has_pending_submission(new.id, v_id::uuid) then
      raise exception '아직 내지 않은 제출이 있어 완료할 수 없습니다 — 제출하면 저절로 완료됩니다' using errcode = '0A000';
    end if;
  end loop;

  -- 단위 완료: unitProgress[unit][person].status 가 completed 로 바뀌는 것
  for v_unit in
    select u.key unit_key, p.key person
    from jsonb_each(case when jsonb_typeof(new.meta->'unitProgress') = 'object' then new.meta->'unitProgress' else '{}'::jsonb end) u,
         lateral jsonb_each(case when jsonb_typeof(u.value) = 'object' then u.value else '{}'::jsonb end) p
    where p.value->>'status' = 'completed'
      and coalesce(old.meta->'unitProgress'->u.key->p.key->>'status', '') <> 'completed'
  loop
    if v_unit.person ~ '^[0-9a-fA-F-]{36}$'
       and public.unit_has_pending_submission(new.id, v_unit.person::uuid, v_unit.unit_key) then
      raise exception '이 과제 단위는 아직 제출하지 않아 완료할 수 없습니다 — 제출하면 저절로 완료됩니다' using errcode = '0A000';
    end if;
  end loop;
  return new;
end;
$_$;


ALTER FUNCTION "public"."guard_submission_completion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_task_action_audit_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  caller_id uuid := (select auth.uid());
  old_json jsonb;
  new_json jsonb;
  old_workflow_id text;
begin
  -- 바깥 IF는 레코드 필드를 참조하지 않는다(컬럼 없는 테이블 보호)
  if tg_op = 'UPDATE' then
    old_json := to_jsonb(old);
    new_json := to_jsonb(new);
    old_workflow_id := old_json ->> 'workflow_id';

    if old_workflow_id is not null
       and (new_json ->> 'workflow_id') is null
       and (new_json - 'workflow_id' - 'updated_at') = (old_json - 'workflow_id' - 'updated_at')
       and not exists (
         select 1 from public.task_workflow w where w.id = old_workflow_id::uuid
       )
    then
      -- 워크플로 삭제 연쇄(ON DELETE SET NULL) — 감사 내용은 불변, 참조만 끊긴다
      return new;
    end if;
  end if;

  if caller_id is not null
    and current_setting('app.task_action_audit_writer', true)
      is distinct from caller_id::text
  then
    raise exception 'WORK audit rows can only be changed through the transition RPCs'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_task_action_audit_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_task_action_document_lineage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_previous public.task_action_document%rowtype;
begin
  if tg_op = 'INSERT' then
    if new.version = 1 then
      new.family_id := new.id;
      new.previous_version_id := null;
      return new;
    end if;

    if new.previous_version_id is null then
      raise exception '완성 문서 이전 버전이 필요합니다.'
        using errcode = '23514';
    end if;

    select *
    into v_previous
    from public.task_action_document
    where id = new.previous_version_id
      and created_by = new.created_by;

    if not found then
      raise exception '소유한 완성 문서 이전 버전을 찾을 수 없습니다.'
        using errcode = '42501';
    end if;

    if new.family_id <> v_previous.family_id
      or new.version <> v_previous.version + 1 then
      raise exception '완성 문서 버전 계보가 올바르지 않습니다.'
        using errcode = '23514';
    end if;

    return new;
  end if;

  -- 신원·계보 컬럼은 항상 불변
  if row(new.id, new.created_by, new.family_id, new.previous_version_id,
         new.version, new.template_version_id, new.created_at)
    is distinct from
     row(old.id, old.created_by, old.family_id, old.previous_version_id,
         old.version, old.template_version_id, old.created_at) then
    raise exception '완성 문서의 신원·계보는 변경할 수 없습니다.'
      using errcode = '23514';
  end if;

  -- final 또는 보관된 행은 내용 불변(보관 전이는 아래에서 별도 허용)
  if (old.status = 'final' or old.archived_at is not null)
    and row(new.title, new.plan, new.knowledge, new.field_values,
            new.row_values, new.user_context)
      is distinct from
       row(old.title, old.plan, old.knowledge, old.field_values,
           old.row_values, old.user_context) then
    raise exception '확정(final)·보관된 완성 문서 내용은 변경할 수 없습니다. 새 버전으로 저장하세요.'
      using errcode = '23514';
  end if;

  -- 상태는 draft → final 단방향
  if new.status is distinct from old.status
    and not (old.status = 'draft' and new.status = 'final') then
    raise exception '완성 문서 상태는 draft에서 final로만 바꿀 수 있습니다.'
      using errcode = '23514';
  end if;

  -- 보관은 null → set 단방향
  if new.archived_at is distinct from old.archived_at
    and not (old.archived_at is null and new.archived_at is not null) then
    raise exception '보관된 완성 문서 버전은 다시 활성화할 수 없습니다.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_task_action_document_lineage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_task_action_document_template_lineage"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_previous public.task_action_document_template%rowtype;
begin
  if tg_op = 'INSERT' then
    if new.version = 1 then
      new.family_id := new.id;
      new.previous_version_id := null;
      return new;
    end if;

    if new.previous_version_id is null then
      raise exception '문서 템플릿 이전 버전이 필요합니다.'
        using errcode = '23514';
    end if;

    select *
    into v_previous
    from public.task_action_document_template
    where id = new.previous_version_id
      and created_by = new.created_by;

    if not found then
      raise exception '소유한 문서 템플릿 이전 버전을 찾을 수 없습니다.'
        using errcode = '42501';
    end if;

    if new.family_id <> v_previous.family_id
      or new.version <> v_previous.version + 1 then
      raise exception '문서 템플릿 버전 계보가 올바르지 않습니다.'
        using errcode = '23514';
    end if;

    return new;
  end if;

  if row(
    new.id,
    new.created_by,
    new.family_id,
    new.previous_version_id,
    new.name,
    new.description,
    new.format,
    new.version,
    new.source_file_name,
    new.storage_bucket,
    new.storage_path,
    new.mime_type,
    new.size_bytes,
    new.content_sha256,
    new.fields,
    new.created_at
  ) is distinct from row(
    old.id,
    old.created_by,
    old.family_id,
    old.previous_version_id,
    old.name,
    old.description,
    old.format,
    old.version,
    old.source_file_name,
    old.storage_bucket,
    old.storage_path,
    old.mime_type,
    old.size_bytes,
    old.content_sha256,
    old.fields,
    old.created_at
  ) then
    raise exception '문서 템플릿 버전 내용은 변경할 수 없습니다.'
      using errcode = '23514';
  end if;

  if new.archived_at is distinct from old.archived_at
    and not (old.archived_at is null and new.archived_at is not null) then
    raise exception '보관된 문서 템플릿 버전은 다시 활성화할 수 없습니다.'
      using errcode = '23514';
  end if;

  return new;
end;
