CREATE OR REPLACE FUNCTION "public"."guard_task_structure"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if current_user <> 'authenticated' then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    if not public.can_manage_work_structure(old.event_id) then
      raise exception '이 업무의 책임자만 할 일을 지울 수 있습니다.' using errcode = '42501';
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' then
    if cardinality(public.jsonb_person_ids(new.meta->'assignees')) > 0
       and not public.can_manage_work_structure(new.event_id) then
      raise exception '이 업무의 책임자만 담당자가 있는 할 일을 만들 수 있습니다.' using errcode = '42501';
    end if;
    return new;
  end if;

  -- UPDATE
  if new.event_id is distinct from old.event_id
     and not (public.can_manage_work_structure(old.event_id) and public.can_manage_work_structure(new.event_id)) then
    raise exception '할 일을 다른 업무로 옮기려면 두 업무 모두의 책임자여야 합니다.' using errcode = '42501';
  end if;
  if public.jsonb_person_ids(new.meta->'assignees') is distinct from public.jsonb_person_ids(old.meta->'assignees')
     and not public.can_manage_work_structure(new.event_id) then
    raise exception '이 업무의 책임자만 담당자를 바꿀 수 있습니다.' using errcode = '42501';
  end if;
  if new.created_by is distinct from old.created_by and not public.can_manage_work_structure(new.event_id) then
    new.created_by := old.created_by;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_task_structure"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_task_submission_config"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s jsonb := new.meta->'submission'; c jsonb; seen_keys text[] := '{}'; seen_labels text[] := '{}';
begin
  if tg_op = 'UPDATE' then
    if old.meta->'submission' is not distinct from s then return new; end if;
    if exists (select 1 from public.task_submission where task_id = new.id) then
      if coalesce(old.meta->'submission'->>'mode', 'file') <> coalesce(s->>'mode', 'file') then
        raise exception '제출 데이터가 있어 제출 방식을 변경할 수 없습니다.' using errcode = '22023';
      end if;
      if s->>'mode' = 'spreadsheet' and old.meta->'submission'->'columns' is distinct from s->'columns' then
        raise exception '제출 데이터가 있어 컬럼을 변경할 수 없습니다.' using errcode = '22023';
      end if;
    end if;
  end if;
  if s->>'mode' = 'spreadsheet' and s->>'required' = 'true' then
    if jsonb_typeof(s->'columns') is distinct from 'array' then raise exception '컬럼을 입력해 주세요.' using errcode = '22023'; end if;
    if jsonb_array_length(s->'columns') not between 1 and 30 or coalesce(s->>'visibility', 'own') not in ('own', 'all') then
      raise exception '컬럼 수 또는 공개 범위가 올바르지 않습니다.' using errcode = '22023';
    end if;
    for c in select value from jsonb_array_elements(s->'columns') loop
      if jsonb_typeof(c->'key') is distinct from 'string' or jsonb_typeof(c->'label') is distinct from 'string'
         or length(c->>'key') not between 1 and 80 or length(btrim(c->>'label')) not between 1 and 80
         or c->>'key' = any(seen_keys) or btrim(c->>'label') = any(seen_labels) then
        raise exception '컬럼 이름과 식별자는 비어 있거나 중복될 수 없습니다.' using errcode = '22023';
      end if;
      seen_keys := array_append(seen_keys, c->>'key'); seen_labels := array_append(seen_labels, btrim(c->>'label'));
    end loop;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_task_submission_config"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_task_submission_kind"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s jsonb;
begin
  select meta->'submission' into s from public.task where id = new.task_id for update;
  if coalesce(s->>'mode', 'file') <> new.kind then
    raise exception '할 일에 설정된 제출 방식과 다릅니다.' using errcode = '22023';
  end if;
  return new;
end;
$$;


