CREATE OR REPLACE FUNCTION "public"."guard_work_structure"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if current_user <> 'authenticated' then
    return coalesce(new, old);
  end if;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();   -- 만든 사람은 주장이 아니라 사실로
    return new;
  end if;

  if tg_op = 'DELETE' then
    if not public.can_manage_work_structure(old.id) then
      raise exception '이 업무의 책임자만 업무를 지울 수 있습니다.' using errcode = '42501';
    end if;
    return old;
  end if;

  new.created_by := old.created_by;   -- 바꿀 수 없다
  if (new.manager_id is distinct from old.manager_id
      or public.jsonb_person_ids(new.meta->'managers') is distinct from public.jsonb_person_ids(old.meta->'managers'))
     and not public.can_manage_work_structure(old.id) then
    raise exception '이 업무의 책임자만 책임자를 바꿀 수 있습니다.' using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_work_structure"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_existing_user_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  email_prefix TEXT;
  user_role TEXT;
  v_name TEXT;
BEGIN
  email_prefix := split_part(NEW.email, '@', 1);

  -- 학생 계정 패턴: 숫자2자리-로 시작 (예: user233@example.com)
  IF email_prefix ~ '^\d{2}-' THEN
    user_role := 'student';
  ELSE
    user_role := 'teacher';
  END IF;

  v_name := public.resolve_profile_name(NEW.email);

  -- 프로필이 없으면 생성, 있으면 비어 있는 nickname/name만 보충
  INSERT INTO public.profiles AS p (id, email, nickname, name, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data ->> 'full_name', NEW.email),
    v_name,
    user_role
  )
  ON CONFLICT (id) DO UPDATE SET
    nickname   = COALESCE(p.nickname, EXCLUDED.nickname),
    name       = COALESCE(p.name, EXCLUDED.name),
    email      = EXCLUDED.email,
    updated_at = NOW()
  WHERE p.nickname IS NULL OR p.name IS NULL;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_existing_user_profile"() OWNER TO "postgres";


