CREATE OR REPLACE FUNCTION "public"."import_univ_admissions"("data" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  inserted_count integer;
BEGIN
  INSERT INTO univ_admissions (
    year, region, university_name, department,
    admission_period, admission_type, admission_category,
    quota, applicants, competition_rate, additional_accepted,
    gpa_cutoff, converted_score, max_score,
    korean_score, math_score, science_score, csat_percentile,
    seq
  )
  SELECT
    (r->>'year')::smallint,
    r->>'region',
    r->>'university_name',
    r->>'department',
    r->>'admission_period',
    r->>'admission_type',
    r->>'admission_category',
    (r->>'quota')::integer,
    (r->>'applicants')::integer,
    (r->>'competition_rate')::numeric,
    (r->>'additional_accepted')::integer,
    (r->>'gpa_cutoff')::numeric,
    (r->>'converted_score')::numeric,
    (r->>'max_score')::numeric,
    (r->>'korean_score')::numeric,
    (r->>'math_score')::numeric,
    (r->>'science_score')::numeric,
    (r->>'csat_percentile')::numeric,
    COALESCE((r->>'seq')::smallint, 1)
  FROM jsonb_array_elements(data) AS r
  ON CONFLICT (year, university_name, department, admission_period, admission_type, seq)
  DO UPDATE SET
    region = EXCLUDED.region,
    admission_category = EXCLUDED.admission_category,
    quota = EXCLUDED.quota,
    applicants = EXCLUDED.applicants,
    competition_rate = EXCLUDED.competition_rate,
    additional_accepted = EXCLUDED.additional_accepted,
    gpa_cutoff = EXCLUDED.gpa_cutoff,
    converted_score = EXCLUDED.converted_score,
    max_score = EXCLUDED.max_score,
    korean_score = EXCLUDED.korean_score,
    math_score = EXCLUDED.math_score,
    science_score = EXCLUDED.science_score,
    csat_percentile = EXCLUDED.csat_percentile;

  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  RETURN inserted_count;
END;
$$;


