  );
$$;


ALTER FUNCTION "public"."inquiry_design_is_teacher_or_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inquiry_generation_start"("p_request" "uuid", "p_student_id" "text", "p_input" "jsonb", "p_provider" "text" DEFAULT 'openai'::"text") RETURNS "public"."academy_generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.profiles; j public.academy_generation_jobs; version_id uuid; used integer;
begin
  -- ⚠️ 로그인 필수 함수는 맨 앞에서 끊는다. auth.uid() 가 null 이면 뒤의 비교가
  --    false 가 아니라 NULL 이 되어 `if not (...)` 형태의 가드가 조용히 통과한다.
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode='42501';
  end if;

  select * into r from public.profiles where id = auth.uid();
  if r.id is null or r.role not in ('student','teacher','admin') then
    raise exception 'Inquiry design account required' using errcode='42501';
  end if;

  -- 학생 범위 판정은 이 기능이 이미 쓰는 단일 출처다(RLS·다른 RPC 와 같은 함수).
  if not public.inquiry_design_can_access_student(p_student_id) then
    raise exception 'Not allowed for student %', p_student_id using errcode='42501';
  end if;

  if p_provider not in ('openai','solar-pro4') or (p_provider <> 'openai' and r.role <> 'admin') then
    raise exception 'Only administrators may select a model' using errcode='42501';
  end if;

  if p_request is null or p_input is null or jsonb_typeof(p_input) <> 'object'
     or octet_length(p_input::text) > 300000 then
    raise exception 'Invalid request';
  end if;
  if jsonb_typeof(p_input->'target') is distinct from 'object'
     or coalesce(p_input#>>'{target,name}','') = ''
     or coalesce(p_input#>>'{target,kind}','') not in ('subject','club','autonomous','career') then
    raise exception 'Invalid target';
  end if;
  if jsonb_typeof(p_input->'selectedSources') is distinct from 'array'
     or jsonb_array_length(p_input->'selectedSources') > 40 then
    raise exception 'Invalid sources';
  end if;
  if coalesce(p_input->>'studentId','') <> p_student_id then
    raise exception 'Wrong owner scope' using errcode='42501';
  end if;

  version_id := nullif(p_input->>'kgVersionId','')::uuid;
  if version_id is not null and not exists (
    select 1 from public.student_kg_versions where id = version_id and student_id = p_student_id
  ) then
    raise exception 'Wrong KG scope' using errcode='42501';
  end if;

  -- 잠금·활성 제한은 (계정, 학생) 단위다 — 교사는 여러 학생의 설계를 나란히 맡는다.
  perform pg_advisory_xact_lock(hashtextextended(r.id::text || ':' || p_student_id, 1401));

  select * into j from public.academy_generation_jobs
   where owner_id = r.id and request_key = p_request;
  if found then return j; end if;

  select * into j from public.academy_generation_jobs
   where owner_id = r.id and surface = 'inquiry-design' and student_id = p_student_id
     and status in ('queued','running','retry')
   order by created_at desc limit 1;
  if found then return j; end if;

  -- 하루 한도는 학생 기준이다. 클라이언트 짝 = INQUIRY_REQUEST_DAILY_LIMIT.
  select count(*) into used from public.academy_generation_jobs
   where surface = 'inquiry-design' and student_id = p_student_id
     and (created_at at time zone 'Asia/Seoul')::date = (now() at time zone 'Asia/Seoul')::date;
  if used >= 20 then
    raise exception '오늘 이 학생의 탐구 설계 의뢰 한도(20회)에 도달했어요.';
  end if;

  insert into public.academy_generation_jobs(
    owner_id, request_key, student_id, experience, provider, input, surface)
  values (r.id, p_request, p_student_id, false, p_provider,
          p_input - 'existingEntities' - 'owner_id', 'inquiry-design')
  returning * into j;

  perform academy_private.wake_generation_worker();
  return j;
end $$;


ALTER FUNCTION "public"."inquiry_generation_start"("p_request" "uuid", "p_student_id" "text", "p_input" "jsonb", "p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inquiry_search_text"("p_title" "text", "p_rq" "text", "p_concepts" "text"[]) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  select coalesce(p_title, '') || ' ' ||
         coalesce(p_rq, '') || ' ' ||
         coalesce(array_to_string(p_concepts, ' '), '')
$$;


