CREATE OR REPLACE FUNCTION "public"."interview_prep_claim_answer"("p_user" "uuid", "p_question" "uuid", "p_answer" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  q public.interview_prep_questions;
  a public.interview_prep_answers;
  token uuid;
  next_version integer;
begin
  if p_user is null then raise exception 'User required' using errcode = '42501'; end if;
  select * into q from public.interview_prep_questions
    where id = p_question and user_id = p_user for update;
  if not found then raise exception '질문을 다시 불러와 주세요.'; end if;
  if q.status <> 'ready' then raise exception '아직 질문이 준비되지 않았어요.'; end if;
  if char_length(btrim(p_answer)) not between 20 and 6000 then
    raise exception '답변은 20자 이상 6,000자 이내로 적어 주세요.' using errcode = 'P0001';
  end if;

  -- 작업 중인 평가가 살아 있으면 그것을 돌려준다(두 탭이 같은 답변을 두 번 평가하지 않는다).
  select * into a from public.interview_prep_answers
    where question_id = p_question and status = 'generating' and lease_until > now()
    order by version desc limit 1;
  if found then
    return jsonb_build_object('claimed', false, 'answer', to_jsonb(a) - 'lease_token');
  end if;

  select coalesce(max(version), 0) + 1 into next_version
    from public.interview_prep_answers where question_id = p_question;
  -- `_shared/interviewPrep.ts` 의 ANSWER_VERSION_LIMIT 과 짝(회귀가 검사).
  if next_version > 10 then
    raise exception '이 질문의 답변을 충분히 다듬었어요. 새 질문으로 이어가요.' using errcode = 'P0001';
  end if;

  token := gen_random_uuid();
  insert into public.interview_prep_answers(
    question_id, user_id, student_id, version, answer, status, lease_token, lease_until)
  values (p_question, p_user, q.student_id, next_version, btrim(p_answer),
    'generating', token, now() + interval '120 seconds')
  returning * into a;
  return jsonb_build_object('claimed', true, 'token', token, 'answer', to_jsonb(a) - 'lease_token');
end;
$$;


ALTER FUNCTION "public"."interview_prep_claim_answer"("p_user" "uuid", "p_question" "uuid", "p_answer" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."interview_prep_claim_question"("p_user" "uuid", "p_student" "text", "p_kind" "text", "p_activity" "text" DEFAULT NULL::"text", "p_theme" "text" DEFAULT NULL::"text", "p_source_kind" "text" DEFAULT 'activity'::"text", "p_source_label" "text" DEFAULT NULL::"text", "p_source_excerpt" "text" DEFAULT NULL::"text", "p_source_ref" "jsonb" DEFAULT '{}'::"jsonb", "p_parent" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  r public.interview_prep_questions;
  today date := (now() at time zone 'Asia/Seoul')::date;
  token uuid;
  used integer;
  depth integer;
begin
  if p_user is null then raise exception 'User required' using errcode = '42501'; end if;
  if not exists(
    select 1 from public.profiles where id = p_user and (
      role = 'student'
      or (role in ('teacher','admin') and p_student = '00-00001')
    )
  ) then
    raise exception '학생·교사 계정에서만 면접 준비를 이용할 수 있어요.' using errcode = '42501';
  end if;
  if p_kind not in ('daily','practice','followup') then raise exception 'Invalid kind'; end if;

  if p_kind = 'daily' then
    select * into r from public.interview_prep_questions
      where user_id = p_user and kind = 'daily' and day = today for update;
    if found then
      -- 이미 완성됐거나 다른 탭이 작업 중이면 그대로 돌려준다(두 번 만들지 않는다).
      if r.status = 'ready' or (r.status = 'generating' and r.lease_until > now()) then
        return jsonb_build_object('claimed', false, 'question', to_jsonb(r) - 'lease_token');
      end if;
      token := gen_random_uuid();
      update public.interview_prep_questions set
        status = 'generating', lease_token = token, lease_until = now() + interval '75 seconds',
        activity_entity_id = p_activity, theme_id = p_theme,
        source_kind = coalesce(p_source_kind, 'activity'),
        source_label = p_source_label, source_excerpt = p_source_excerpt,
        source_ref = coalesce(p_source_ref, '{}'::jsonb), updated_at = now()
        where id = r.id returning * into r;
      return jsonb_build_object('claimed', true, 'token', token, 'question', to_jsonb(r) - 'lease_token');
    end if;
  end if;

  if p_kind = 'practice' then
    select count(*) into used from public.interview_prep_questions
      where user_id = p_user and kind = 'practice'
        and (created_at at time zone 'Asia/Seoul')::date = today;
    -- 이 값은 `_shared/interviewPrep.ts` 의 PRACTICE_DAILY_LIMIT 과 짝이다(회귀가 검사).
    if used >= 5 then
      raise exception '오늘 받을 수 있는 연습 질문을 모두 사용했어요. 내일 다시 이어가요.'
        using errcode = 'P0001';
    end if;
  end if;

  if p_kind = 'followup' then
    if p_parent is null then raise exception 'Parent question required'; end if;
    -- 깊이를 세어 2단에서 끊는다. 더 내려가면 원 질문과 멀어져 면접 연습이 아니게 된다.
    -- 스칼라 서브쿼리 **대입**으로 쓴다 — PL/pgSQL 의 `WITH ... SELECT ... INTO` 는
    -- 파서 판정에 기대는 형태라, 값 하나를 얻는 데 굳이 그 형태를 쓸 이유가 없다.
    -- 부모가 남의 질문이면 체인이 비어 null 이 되고 아래에서 걸린다(소유자 검증 겸용).
    depth := (
      with recursive chain as (
        select id, parent_id, 1 as d from public.interview_prep_questions
          where id = p_parent and user_id = p_user
        union all
        select q.id, q.parent_id, c.d + 1 from public.interview_prep_questions q
          join chain c on q.id = c.parent_id
      ) select max(d) from chain
    );
    if depth is null then raise exception '질문을 다시 불러와 주세요.'; end if;
    if depth >= 3 then
      raise exception '이 질문의 꼬리 질문을 모두 마쳤어요. 새 질문으로 이어가요.'
        using errcode = 'P0001';
    end if;
  end if;

  token := gen_random_uuid();
  begin
    insert into public.interview_prep_questions(
      user_id, student_id, day, kind, parent_id, activity_entity_id, theme_id,
      source_kind, source_label, source_excerpt, source_ref, status, lease_token, lease_until)
    values (
      p_user, p_student, case when p_kind = 'daily' then today else null end, p_kind, p_parent,
      p_activity, p_theme, coalesce(p_source_kind, 'activity'), p_source_label, p_source_excerpt,
      coalesce(p_source_ref, '{}'::jsonb), 'generating', token, now() + interval '75 seconds')
    returning * into r;
  exception when unique_violation then
    -- 같은 순간 다른 탭이 오늘의 질문을 만들었다. 그쪽 결과를 쓴다.
    select * into r from public.interview_prep_questions
      where user_id = p_user and kind = 'daily' and day = today;
    return jsonb_build_object('claimed', false, 'question', to_jsonb(r) - 'lease_token');
  end;
  return jsonb_build_object('claimed', true, 'token', token, 'question', to_jsonb(r) - 'lease_token');
end;
$$;


ALTER FUNCTION "public"."interview_prep_claim_question"("p_user" "uuid", "p_student" "text", "p_kind" "text", "p_activity" "text", "p_theme" "text", "p_source_kind" "text", "p_source_label" "text", "p_source_excerpt" "text", "p_source_ref" "jsonb", "p_parent" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."interview_prep_finish_answer"("p_id" "uuid", "p_token" "uuid", "p_evaluation" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare a public.interview_prep_answers;
begin
  select * into a from public.interview_prep_answers where id = p_id for update;
  if not found then raise exception 'Answer missing'; end if;
  if a.lease_token is distinct from p_token or a.status <> 'generating' then
    return to_jsonb(a) - 'lease_token';
  end if;
  if p_evaluation is not null and jsonb_typeof(p_evaluation) <> 'object' then
    raise exception 'Invalid evaluation';
  end if;
  update public.interview_prep_answers set
    evaluation = coalesce(p_evaluation, evaluation),
    status = case when p_evaluation is null then 'failed' else 'ready' end,
    lease_token = null, lease_until = null, updated_at = now()
    where id = p_id returning * into a;
  return to_jsonb(a) - 'lease_token';
end;
$$;


ALTER FUNCTION "public"."interview_prep_finish_answer"("p_id" "uuid", "p_token" "uuid", "p_evaluation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."interview_prep_finish_question"("p_id" "uuid", "p_token" "uuid", "p_question" "text" DEFAULT NULL::"text", "p_intent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare r public.interview_prep_questions;
begin
  select * into r from public.interview_prep_questions where id = p_id for update;
  if not found then raise exception 'Question missing'; end if;
  -- 임대를 잃었으면(만료 후 다른 시도가 이어받았다) 현재 상태를 그대로 돌려준다.
  if r.lease_token is distinct from p_token or r.status <> 'generating' then
    return to_jsonb(r) - 'lease_token';
  end if;
  if p_question is not null and char_length(btrim(p_question)) not between 1 and 1500 then
    raise exception 'Invalid question';
  end if;
  update public.interview_prep_questions set
    question = case when p_question is null then question else btrim(p_question) end,
    intent = case when p_question is null then intent else btrim(p_intent) end,
    status = case when p_question is null then 'failed' else 'ready' end,
    lease_token = null, lease_until = null, updated_at = now()
    where id = p_id returning * into r;
  return to_jsonb(r) - 'lease_token';
end;
$$;


ALTER FUNCTION "public"."interview_prep_finish_question"("p_id" "uuid", "p_token" "uuid", "p_question" "text", "p_intent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."interview_prep_state"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with t as (select (now() at time zone 'Asia/Seoul')::date as d),
  q as (
    select * from public.interview_prep_questions where user_id = (select auth.uid())
  ),
  a as (
    select * from public.interview_prep_answers
    where user_id = (select auth.uid()) and status = 'ready'
  )
  select jsonb_build_object(
    'day', t.d,
    'daily', (
      select to_jsonb(x) - 'lease_token' from q x where x.kind = 'daily' and x.day = t.d
    ),
    'practiceUsed', (
      select count(*) from q
      where kind = 'practice' and (created_at at time zone 'Asia/Seoul')::date = t.d
    ),
    'practiceLimit', 5,
    'questionCount', (select count(*) from q where status = 'ready'),
    -- 연속이 아니라 **누적** 답변 일수. 하루 빠졌다고 0이 되면 벌점처럼 읽힌다.
    'answeredDays', (
      select count(distinct (created_at at time zone 'Asia/Seoul')::date) from a
    ),
    'answeredToday', (
      select exists(
        select 1 from a
        join q on q.id = a.question_id
        where q.kind = 'daily' and q.day = t.d
      )
    )
  ) from t;
$$;


ALTER FUNCTION "public"."interview_prep_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invest_fetch_plan"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with today as (select (now() at time zone 'Asia/Seoul')::date d)
  select jsonb_build_object(
    'kr_days', coalesce((select jsonb_agg(to_char(x.day, 'YYYY-MM-DD') order by x.day desc) from (
        select g::date as day from today, generate_series(today.d - 180, today.d, interval '1 day') g
         where extract(isodow from g) < 6
           and exists (select 1 from public.invest_asset a where a.active and a.source in ('krx_stock', 'krx_etf'))
           and not exists (select 1 from public.invest_fetch_day f where f.source = 'krx' and f.day = g::date
                            and (f.rows > 0 or f.attempted_at > now() - interval '1 hour' or g::date < today.d - 7))
         order by g desc limit 6) x), '[]'::jsonb),
    'kr_codes', jsonb_build_object(
      'stock', coalesce((select jsonb_object_agg(a.symbol, a.id) from public.invest_asset a where a.active and a.source = 'krx_stock'), '{}'::jsonb),
      'etf', coalesce((select jsonb_object_agg(a.symbol, a.id) from public.invest_asset a where a.active and a.source = 'krx_etf'), '{}'::jsonb)),
    'twelve', coalesce((select jsonb_agg(x) from (
                    select jsonb_build_object('id', a.id, 'symbol', a.symbol, 'since', (select max(day) from public.invest_quote q where q.asset_id = a.id)) x
                      from public.invest_asset a where a.active and a.source = 'twelve'
                       and (a.fetched_at is null or a.fetched_at < now() - interval '12 hours')
                     order by a.fetched_at nulls first, a.sort limit 7) t), '[]'::jsonb),
    'fx_since', (select max(day) from public.invest_fx),
    'fx_due', not exists (select 1 from public.invest_fetch_log where source = 'fx' and ok and at > now() - interval '3 hours')
  )
$$;


ALTER FUNCTION "public"."invest_fetch_plan"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invest_ingest"("p_quotes" "jsonb", "p_fx" "jsonb", "p_touched" "text"[], "p_logs" "jsonb", "p_days" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare nq integer; nf integer; dup integer;
begin
  insert into public.invest_fx(day, usd_krw)
  select distinct on ((x->>'day')::date) (x->>'day')::date, (x->>'usd_krw')::numeric
    from jsonb_array_elements(coalesce(p_fx, '[]'::jsonb)) with ordinality as t(x, n)
   where (x->>'usd_krw')::numeric > 0
   order by (x->>'day')::date, n
  on conflict (day) do update set usd_krw = excluded.usd_krw, fetched_at = now();
  get diagnostics nf = row_count;
  -- 달러 자체(1달러) = 환율이 있는 날마다 종가 1
  insert into public.invest_quote(asset_id, day, close, close_at)
  select a.id, f.day, 1, invest_private.close_at('fx', f.day) from public.invest_asset a cross join public.invest_fx f where a.source = 'fx'
  on conflict (asset_id, day) do nothing;
  insert into public.invest_quote(asset_id, day, open, high, low, close, volume, close_at)
  select distinct on (x->>'asset_id', (x->>'day')::date)
         x->>'asset_id', (x->>'day')::date,
         nullif((x->>'open')::numeric, 0), nullif((x->>'high')::numeric, 0), nullif((x->>'low')::numeric, 0),
         (x->>'close')::numeric, (x->>'volume')::numeric,
         invest_private.close_at(a.source, (x->>'day')::date)
    from jsonb_array_elements(coalesce(p_quotes, '[]'::jsonb)) with ordinality as t(x, n) join public.invest_asset a on a.id = x->>'asset_id'
   where (x->>'close')::numeric > 0
   order by x->>'asset_id', (x->>'day')::date, n
  on conflict (asset_id, day) do update set open = excluded.open, high = excluded.high, low = excluded.low, close = excluded.close,
    volume = excluded.volume, close_at = excluded.close_at, fetched_at = now();
  get diagnostics nq = row_count;
  select count(*) - count(distinct (x->>'asset_id', x->>'day')) into dup from jsonb_array_elements(coalesce(p_quotes, '[]'::jsonb)) x;
  insert into public.invest_fetch_day(source, day, rows)
  select 'krx', (x->>'day')::date, coalesce((x->>'rows')::integer, 0) from jsonb_array_elements(coalesce(p_days, '[]'::jsonb)) x
  on conflict (source, day) do update set rows = greatest(public.invest_fetch_day.rows, excluded.rows), attempted_at = now();
  update public.invest_asset set fetched_at = now() where id = any(coalesce(p_touched, '{}'));
  insert into public.invest_fetch_log(source, ok, rows, message)
  select x->>'source', coalesce((x->>'ok')::boolean, false), coalesce((x->>'rows')::integer, 0),
         nullif(left(concat_ws(' | ', x->>'message', case when dup > 0 and x->>'source' = 'twelve' then format('같은 날 중복 %s줄 걸러 냄', dup) end), 500), '')
    from jsonb_array_elements(coalesce(p_logs, '[]'::jsonb)) x;
  return jsonb_build_object('quotes', nq, 'fx', nf, 'duplicates', dup);
end $$;


