CREATE OR REPLACE FUNCTION "public"."ipsi_hub_search_snippet"("p_text" "text", "p_terms" "text"[]) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_text  text;
  v_lower text;
  v_pos   int := 0;
  v_hit   int;
  v_len   int := 0;
  v_term  text;
  v_start int;
  v_end   int;
begin
  if p_text is null or p_text = '' or p_terms is null or cardinality(p_terms) = 0 then
    return null;
  end if;
  v_text := btrim(regexp_replace(p_text, '\s+', ' ', 'g'));
  v_lower := lower(v_text);
  foreach v_term in array p_terms loop
    v_hit := strpos(v_lower, v_term);
    if v_hit > 0 and (v_pos = 0 or v_hit < v_pos) then
      v_pos := v_hit;
      v_len := length(v_term);
    end if;
  end loop;
  if v_pos = 0 then
    return null;
  end if;
  v_start := greatest(1, v_pos - 35);
  v_end := least(length(v_text), v_pos + v_len + 60);
  return case when v_start > 1 then '…' else '' end
      || substr(v_text, v_start, v_end - v_start + 1)
      || case when v_end < length(v_text) then '…' else '' end;
end;
$$;


