CREATE OR REPLACE FUNCTION "public"."is_wishlist_owner"("p_student_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- 학생 본인 판정: user_resource 링크에 의존하지 않고 profiles.email 접두사로
  -- 직접 매칭 (inquiry_design_can_access_student / get_latest_kg_version 과 동일 관례).
  -- 이유: 대다수 학생 계정은 resource(type='student') 는 있지만 user_resource
  -- 링크 행이 없음(대량 학생 import가 링크를 생성하지 않고, 학생용 자동연결 UI도 없음).
  SELECT EXISTS (
    SELECT 1
    FROM profiles p
    WHERE p.id = auth.uid()
      AND p.role = 'student'
      AND split_part(p.email, '@', 1) = p_student_code
  );
$$;


ALTER FUNCTION "public"."is_wishlist_owner"("p_student_code" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."is_wishlist_owner"("p_student_code" "text") IS '현재 로그인 사용자가 p_student_code 학생 본인인지 판정 (resource type=student, meta->>id 기준). admission_wishlist 쓰기 권한 게이트.';



CREATE OR REPLACE FUNCTION "public"."is_work_manager"("p_task_id" "uuid", "p_resource_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.task t
    JOIN public.work e ON e.id = t.event_id
    WHERE t.id = p_task_id
      AND p_resource_id IS NOT NULL
      AND (
        e.manager_id = p_resource_id
        OR EXISTS (
          SELECT 1
          FROM jsonb_array_elements(
            CASE WHEN jsonb_typeof(COALESCE(e.meta, '{}'::jsonb)->'managers') = 'array'
                 THEN e.meta->'managers' ELSE '[]'::jsonb END
          ) AS manager(value)
          WHERE CASE WHEN jsonb_typeof(value) = 'object' THEN value->>'id'
                     ELSE TRIM(BOTH '"' FROM value::text) END = p_resource_id::text
        )
      )
  );
$$;


ALTER FUNCTION "public"."is_work_manager"("p_task_id" "uuid", "p_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_signature_sign_tokens"("p_request_id" "uuid", "p_valid_days" integer DEFAULT 30) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_signer record;
begin
  for v_signer in
    select id from public.signature_signer where request_id = p_request_id
  loop
    insert into public.signature_sign_token (signer_id, request_id, token, expires_at)
    values (
      v_signer.id,
      p_request_id,
      -- gen_random_bytes(32) → base64url. `/`·`+`·`=` 는 URL 에서 다루기 번거로우므로 치환한다
      translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/=', '-_'),
      now() + make_interval(days => greatest(1, least(p_valid_days, 365)))
    )
    on conflict (signer_id) do nothing;
  end loop;
end;
$$;


ALTER FUNCTION "public"."issue_signature_sign_tokens"("p_request_id" "uuid", "p_valid_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jsonb_person_ids"("p" "jsonb") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct x order by x), '{}')
  from (
    select case when jsonb_typeof(v) = 'object' then v->>'id' else trim(both '"' from v::text) end as x
    from jsonb_array_elements(case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end) e(v)
  ) s
  where x is not null and x <> '';
$$;


