CREATE OR REPLACE FUNCTION "public"."leave_queue"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN;
  END IF;

  DELETE FROM active_sessions WHERE user_id = v_user_id;
  DELETE FROM waiting_queue WHERE user_id = v_user_id;
END;
$$;


