CREATE OR REPLACE FUNCTION "public"."link_objects"("p_from_type" "text", "p_from_id" "uuid", "p_to_type" "text", "p_to_id" "uuid", "p_kind" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  if not coalesce(public.can_view_object(p_from_type, p_from_id), false)
     or not coalesce(public.can_view_object(p_to_type, p_to_id), false) then
    raise exception '연결할 대상을 볼 수 없습니다' using errcode = '42501';
  end if;

  insert into public.ontology_link (from_type, from_id, to_type, to_id, kind, note)
  values (p_from_type, p_from_id, p_to_type, p_to_id, p_kind, nullif(btrim(coalesce(p_note, '')), ''))
  on conflict on constraint ontology_link_unique do nothing
  returning id into v_id;

  if v_id is null then
    select id into v_id from public.ontology_link
    where from_type = p_from_type and from_id = p_from_id and to_type = p_to_type and to_id = p_to_id and kind = p_kind;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."link_objects"("p_from_type" "text", "p_from_id" "uuid", "p_to_type" "text", "p_to_id" "uuid", "p_kind" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_my_supervision_swaps"() RETURNS TABLE("id" "uuid", "grade" integer, "status" "text", "message" "text", "created_at" timestamp with time zone, "responded_at" timestamp with time zone, "i_am_requester" boolean, "requester_name" "text", "partner_name" "text", "requester_meeting_id" "uuid", "requester_date" "date", "requester_slot" "text", "partner_meeting_id" "uuid", "partner_date" "date", "partner_slot" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;

  return query
  select s.id, s.grade, s.status, s.message, s.created_at, s.responded_at,
         s.requester_resource_id in (select public.current_actor_resource_ids()),
         rq.name, pt.name,
         s.requester_meeting_id, (mr.starts_at at time zone 'Asia/Seoul')::date, mr.meta -> 'supervision' ->> 'slot',
         s.partner_meeting_id, (mp.starts_at at time zone 'Asia/Seoul')::date, mp.meta -> 'supervision' ->> 'slot'
  from supervision_swap_request s
  join resource rq on rq.id = s.requester_resource_id
  join resource pt on pt.id = s.partner_resource_id
  join meeting mr on mr.id = s.requester_meeting_id
  left join meeting mp on mp.id = s.partner_meeting_id
  where s.requester_resource_id in (select public.current_actor_resource_ids())
     or s.partner_resource_id in (select public.current_actor_resource_ids())
  order by s.created_at desc
  limit 100;
end;
$$;


ALTER FUNCTION "public"."list_my_supervision_swaps"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_official_docs"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_limit" integer DEFAULT 1000, "p_mine" boolean DEFAULT false, "p_slim" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_from  timestamptz := case when p_from is null then null else (p_from::timestamp at time zone 'Asia/Seoul') end;
  v_to    timestamptz := case when p_to   is null then null else ((p_to + 1)::timestamp at time zone 'Asia/Seoul') end;
  v_limit integer := least(greatest(coalesce(p_limit, 1000), 1), 2000);
  v_slim  boolean := coalesce(p_slim, false);
  v       jsonb;
  v_names text[];
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '28000';
  end if;

  -- 내 공문만(2026-11-12) — 결재권자 이름 = 내 이름(명단에 연결된 교직원 이름, official_doc_is_mine 과 같은 판정) · 결정 없음.
  -- 이름은 한 번만 읽는다(공문마다 판정 함수를 부르지 않게).
  if coalesce(p_mine, false) then
    select coalesce(array_agg(distinct r.name), '{}'::text[]) into v_names
    from public.user_resource ur
    join public.resource r on r.id = ur.resource_id
    where ur.user_id = auth.uid() and r.type in ('teacher', 'staff');
  end if;

  with scope as (
    select o.id
    from official_doc o
    where not coalesce(p_mine, false)
       or (btrim(o.approver_name) = any(v_names)
           and not exists (select 1 from official_doc_decision x where x.doc_id = o.id))
  ),
  in_range as (
    select o.id
    from official_doc o
    join scope s on s.id = o.id
    where (v_from is null or o.registered_at >= v_from)
      and (v_to   is null or o.registered_at <  v_to)
  ),
  picked as (
    select o.id
    from official_doc o
    join in_range r on r.id = o.id
    order by o.registered_at desc nulls last, o.doc_no desc
    limit v_limit
  ),
  shaped as (
    select
      o.id,
      o.doc_no,
      o.registered_at,
      o.meta,
      jsonb_build_object(
        'id', o.id, 'doc_no', o.doc_no, 'registered_at', o.registered_at, 'title', o.title, 'sender', o.sender,
        'approver_name', o.approver_name, 'approval_type', o.approval_type, 'process_status', o.process_status,
        'body_status', o.body_status, 'meta', case when v_slim then null else o.meta end, 'first_seen_at', o.first_seen_at,
        'slim', v_slim,
        'triage', case when t.id is null then null else jsonb_build_object(
          'id', t.id, 'engine', t.engine, 'model', t.model, 'prompt_version', t.prompt_version, 'nature', t.nature,
          'needs_action', t.needs_action, 'deadline', t.deadline, 'confidence', t.confidence,
          'question', case when v_slim then null else t.question end,
          'result', case when not v_slim then t.result else
            -- 목록 행·필터·정렬·정확도·결정 기본값이 쓰는 칸만(officialDocInbox.ts · officialDocDecision.ts)
            jsonb_strip_nulls(jsonb_build_object(
              'nature', t.result->'nature', 'needs_action', t.result->'needs_action', 'obligation', t.result->'obligation',
              'sender_official', t.result->'sender_official', 'opportunity', t.result->'opportunity',
              'waivable', t.result->'waivable', 'explicit_required', t.result->'explicit_required',
              'survey_respondent', t.result->'survey_respondent', 'parent', t.result->'parent',
              'adds_new_work', t.result->'adds_new_work', 'new_work', t.result->'new_work',
              'summary', t.result->'summary', 'deadline', t.result->'deadline', 'confidence', t.result->'confidence',
              'rules', t.result->'rules',
              'work_candidates', case when jsonb_typeof(t.result->'work_candidates') = 'array' then (
                select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('id', c->'id', 'name', c->'name', 'score', c->'score')))
                from jsonb_array_elements(t.result->'work_candidates') c) end))
            end,
          'created_at', t.created_at) end,
        'decision', case when d.id is null then null else jsonb_build_object(
          'id', d.id, 'decision', d.decision, 'nature', d.nature, 'work_id', d.work_id, 'task_id', d.task_id,
          'work_candidate_id', d.work_candidate_id, 'assignee_names', d.assignee_names, 'reason', d.reason,
          'created_at', d.created_at) end
      ) as j,
      t.result as triage_result
    from official_doc o
    join picked p on p.id = o.id
    left join lateral (select * from official_doc_triage x where x.doc_id = o.id order by x.created_at desc limit 1) t on true
    left join lateral (select * from official_doc_decision x where x.doc_id = o.id order by x.created_at desc limit 1) d on true
  ),
  ref_nos as (
    select p->>'doc_no' as no
    from shaped s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.triage_result->'parent') = 'array' then s.triage_result->'parent' else '[]'::jsonb end) p
    union
    select m->>'doc_no'
    from shaped s
    cross join lateral jsonb_array_elements(
      case when jsonb_typeof(s.meta->'similar') = 'array' then s.meta->'similar' else '[]'::jsonb end) m
  ),
  related as (
    -- 기간 밖 원 공문·비슷한 공문 — 결정만(판정·meta 는 화면이 쓰지 않는다)
    select jsonb_build_object(
      'id', o.id, 'doc_no', o.doc_no, 'registered_at', o.registered_at, 'title', o.title, 'sender', o.sender,
      'approver_name', o.approver_name, 'approval_type', o.approval_type, 'process_status', o.process_status,
      'body_status', o.body_status, 'meta', null, 'first_seen_at', o.first_seen_at, 'triage', null,
      'decision', case when d.id is null then null else jsonb_build_object(
        'id', d.id, 'decision', d.decision, 'nature', d.nature, 'work_id', d.work_id, 'task_id', d.task_id,
        'work_candidate_id', d.work_candidate_id, 'assignee_names', d.assignee_names, 'reason', d.reason,
        'created_at', d.created_at) end
    ) as j
    from official_doc o
    left join lateral (select * from official_doc_decision x where x.doc_id = o.id order by x.created_at desc limit 1) d on true
    where o.doc_no in (select no from ref_nos where no is not null)
      and not exists (select 1 from picked p where p.id = o.id)
  )
  select jsonb_build_object(
    'docs',    coalesce((select jsonb_agg(s.j order by s.registered_at desc nulls last, s.doc_no desc) from shaped s), '[]'::jsonb),
    'related', coalesce((select jsonb_agg(r.j) from related r), '[]'::jsonb),
    'total',   (select count(*) from in_range),
    'pending_outside', (
      select count(*) from official_doc o
      join scope s on s.id = o.id
      where not exists (select 1 from in_range r where r.id = o.id)
        and not exists (select 1 from official_doc_decision x where x.doc_id = o.id))
  ) into v;

  return v;
end;
$$;


ALTER FUNCTION "public"."list_official_docs"("p_from" "date", "p_to" "date", "p_limit" integer, "p_mine" boolean, "p_slim" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."list_official_docs"("p_from" "date", "p_to" "date", "p_limit" integer, "p_mine" boolean, "p_slim" boolean) IS '공문 판단함 목록 — 접수 등록일 기간(한국 날짜, 양끝 포함) 안 공문(본문 제외) + 최신 판정·결정 1건씩 + 기간 밖 원·비슷한 공문(결정만) + total·pending_outside. p_mine = 결재권자가 나이고 결정 없는 것만(업무노트, 2026-11-12). p_slim = meta 빼고 판정은 목록이 쓰는 칸만(판단함, 2026-11-13 — 펼칠 때 한 건 전체를 따로 받는다). INVOKER(RLS = 관리자·담당 본인). 클라이언트 = officialDocService.listOfficialDocs';



CREATE OR REPLACE FUNCTION "public"."list_signature_purge_targets"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_days int := public.signature_purge_days();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', r.id,
      'status', r.status,
      'moved', (r.meta ? 'drive'),
      'paths', array_remove(array[nullif(r.source_path, 'pending'), r.signed_path], null)
    ))
    from public.signature_request r
    where r.purged_at is null
      and (
        (r.meta ? 'drive')
        or (r.status = 'completed' and r.decided_at is not null
            and r.decided_at < now() - make_interval(days => v_days))
        or (r.status = 'pending' and r.due_at < now())
        or (r.status in ('rejected', 'cancelled')
            and coalesce(r.decided_at, r.created_at) < now() - make_interval(days => v_days))
      )
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."list_signature_purge_targets"() OWNER TO "postgres";


