    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "uuid" NOT NULL,
    "slide_key" "text" NOT NULL,
    "slide_index" integer,
    "kind" "text" NOT NULL,
    "prompt" "text" NOT NULL,
    "config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "opened_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "current_round" integer DEFAULT 1 NOT NULL,
    "revealed_at" timestamp with time zone,
    CONSTRAINT "live_presentation_activities_kind_check" CHECK (("kind" = ANY (ARRAY['choice'::"text", 'ox'::"text", 'short'::"text", 'wordcloud'::"text", 'exit'::"text", 'code'::"text"]))),
    CONSTRAINT "live_presentation_activities_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'open'::"text", 'closed'::"text", 'revealed'::"text"])))
);


