CREATE OR REPLACE FUNCTION "public"."live_presentation__auth_host"("p_session_id" "uuid", "p_host_token" "uuid") RETURNS "public"."live_presentation_sessions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  s live_presentation_sessions;
begin
  select * into s from live_presentation_sessions
   where id = p_session_id and host_token = p_host_token;
  if not found then
    raise exception 'LP_AUTH: invalid session or host token';
  end if;
  return s;
end;
$$;


ALTER FUNCTION "public"."live_presentation__auth_host"("p_session_id" "uuid", "p_host_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_presentation__gen_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  chars constant text := '23456789ACDEFGHJKMNPQRSTUVWXYZ';
  result text := '';
  i int;
begin
  for i in 1..6 loop
    result := result || substr(chars, (floor(random() * 30) + 1)::int, 1);
  end loop;
  return result;
end;
$$;


ALTER FUNCTION "public"."live_presentation__gen_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_presentation__leaderboard"("p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select coalesce((
    select jsonb_agg(jsonb_build_object(
             'nickname', t.nickname, 'studentNo', t.student_no, 'score', t.score)
           order by t.score desc, t.first_at)
    from (
      select p.nickname, p.student_no, sum(r.score)::int as score,
             min(r.created_at) as first_at
      from live_presentation_responses r
      join live_presentation_participants p on p.id = r.participant_id
      where r.session_id = p_session_id and r.score > 0
      group by p.id, p.nickname, p.student_no
      order by sum(r.score) desc, min(r.created_at)
      limit 5
    ) t
  ), '[]'::jsonb);
$$;


ALTER FUNCTION "public"."live_presentation__leaderboard"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."live_presentation__reveal_payload"("a" "public"."live_presentation_activities") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  agg jsonb;
  r1 jsonb;
  r2 jsonb;
  v_gamify boolean;
begin
  if a.current_round > 1 then
    r1 := live_presentation__aggregate(a.id, 1);
    r2 := live_presentation__aggregate(a.id, 2);
    agg := jsonb_build_object('kind', a.kind, 'pi', true,
                              'rounds', jsonb_build_array(r1, r2),
                              'total', coalesce((r2->>'total')::int, 0));
  else
    agg := live_presentation__aggregate(a.id, 1);
  end if;
  if a.kind in ('choice','ox') and a.config ? 'answer' then
    agg := agg || jsonb_build_object('answer', a.config->'answer');
  end if;
  select gamify into v_gamify from live_presentation_sessions where id = a.session_id;
  if coalesce(v_gamify, false) then
    agg := agg || jsonb_build_object('leaderboard', live_presentation__leaderboard(a.session_id));
  end if;
  return agg;
end;
$$;


