CREATE OR REPLACE FUNCTION "public"."log_course_selection_change"("p_round_id" "uuid", "p_actor_name" "text", "p_actor_role" "text", "p_action" "text", "p_target_type" "text", "p_target_id" "uuid", "p_target_label" "text", "p_diff" "jsonb" DEFAULT '{}'::"jsonb", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.course_selection_audit_log (
    round_id, actor_id, actor_name, actor_role, action,
    target_type, target_id, target_label, diff, reason, occurred_at
  ) VALUES (
    p_round_id, auth.uid(), p_actor_name, p_actor_role, p_action,
    p_target_type, p_target_id, p_target_label, p_diff, p_reason, now()
  ) RETURNING id INTO v_id;
  RETURN v_id;
END $$;


ALTER FUNCTION "public"."log_course_selection_change"("p_round_id" "uuid", "p_actor_name" "text", "p_actor_role" "text", "p_action" "text", "p_target_type" "text", "p_target_id" "uuid", "p_target_label" "text", "p_diff" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_schedule_permission_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.schedule_permission_logs (permission_id, action, performed_by, details)
        VALUES (NEW.id, 'granted', NEW.granted_by, row_to_json(NEW));
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.is_active = true AND NEW.is_active = false THEN
            INSERT INTO public.schedule_permission_logs (permission_id, action, performed_by, details)
            VALUES (NEW.id, 'revoked', auth.uid(), jsonb_build_object('old', row_to_json(OLD), 'new', row_to_json(NEW)));
        ELSE
            INSERT INTO public.schedule_permission_logs (permission_id, action, performed_by, details)
            VALUES (NEW.id, 'modified', auth.uid(), jsonb_build_object('old', row_to_json(OLD), 'new', row_to_json(NEW)));
        END IF;
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."log_schedule_permission_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lp_advance_round"("p_session_id" "uuid", "p_host_token" "uuid", "p_activity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  a live_presentation_activities;
begin
  perform live_presentation__auth_host(p_session_id, p_host_token);
  update live_presentation_activities
     set current_round = 2, status = 'open', opened_at = now(), closed_at = null, revealed_at = null
   where id = p_activity_id and session_id = p_session_id
  returning * into a;
  if not found then raise exception 'LP: activity not found'; end if;
  return live_presentation__activity_public(a);
end;
$$;


