CREATE OR REPLACE FUNCTION "public"."lp_submit"("p_activity_id" "uuid", "p_participant_id" "uuid", "p_client_id" "uuid", "p_payload" "jsonb", "p_round" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  a live_presentation_activities;
  s live_presentation_sessions;
  p live_presentation_participants;
  v_round int;
  correct boolean;
  v_score int := 0;
  v_prev_correct int;
begin
  if pg_column_size(p_payload) > 20000 then
    raise exception 'LP_SUBMIT: payload too large';
  end if;

  select * into a from live_presentation_activities where id = p_activity_id;
  if not found or a.status <> 'open' then
    return jsonb_build_object('ok', false, 'reason', 'not_open');
  end if;
  v_round := greatest(1, a.current_round);

  select * into p from live_presentation_participants
   where id = p_participant_id and session_id = a.session_id and client_id = p_client_id;
  if not found then raise exception 'LP_SUBMIT: invalid participant'; end if;

  if a.kind = 'choice' and a.config ? 'answer' then
    correct := (p_payload->>'choice')::int = (a.config->>'answer')::int;
  elsif a.kind = 'ox' and a.config ? 'answer' then
    correct := (p_payload->>'ox')::boolean = (a.config->>'answer')::boolean;
  else
    correct := null;
  end if;

  -- gamify 세션: 정답 500 + 속도 보너스(정답 제출 순위, 라운드별 독립)
  if correct is true then
    select * into s from live_presentation_sessions where id = a.session_id;
    if s.gamify then
      select count(*) into v_prev_correct from live_presentation_responses
       where activity_id = p_activity_id and round = v_round and is_correct is true;
      v_score := 500 + greatest(50, 500 - v_prev_correct * 50);
    end if;
  end if;

  begin
    insert into live_presentation_responses
           (activity_id, session_id, participant_id, round, payload, is_correct, score)
    values (p_activity_id, a.session_id, p_participant_id, v_round, p_payload, correct, v_score);
  exception when unique_violation then
    if a.kind = 'code' then
      -- 반복 개선 장려: 최신 코드로 갱신 (code는 gamify 채점 제외 — score 0 유지)
      update live_presentation_responses
         set payload = p_payload, is_correct = correct, created_at = now()
       where activity_id = p_activity_id and participant_id = p_participant_id and round = v_round;
      return jsonb_build_object('ok', true, 'round', v_round, 'updated', true);
    end if;
    return jsonb_build_object('ok', false, 'reason', 'duplicate', 'round', v_round);
  end;

  return jsonb_build_object('ok', true, 'round', v_round);
end;
$$;


ALTER FUNCTION "public"."lp_submit"("p_activity_id" "uuid", "p_participant_id" "uuid", "p_client_id" "uuid", "p_payload" "jsonb", "p_round" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_action_received"("p_action_id" "uuid", "p_resource_id" "uuid", "p_received" boolean, "p_unit_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.collect_request;
  v_unit text;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if p_received is null then raise exception 'p_received 가 필요합니다' using errcode = '22023'; end if;
  if not public.can_manage_collect(p_action_id) then
    raise exception '실물 수령은 이 업무의 책임자만 기록할 수 있습니다' using errcode = '42501';
  end if;
  select * into v_req from public.collect_request where action_id = p_action_id;
  if not found or v_req.kind <> 'physical' then raise exception '실물 제출 요청이 아닙니다' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.collect_target where action_id = p_action_id and resource_id = p_resource_id and removed_at is null) then
    raise exception '이 요청의 대상이 아닙니다' using errcode = 'P0002';
  end if;
  v_unit := public._submission_check_unit(v_req, p_unit_key);
  if p_received then
    if v_req.status <> 'open' then raise exception '마감된 요청입니다' using errcode = '22023'; end if;
    insert into public.action_submission (action_id, resource_id, kind, unit_key, file_name, received_at, received_by, submitted_by)
    values (p_action_id, p_resource_id, 'physical', v_unit, '실물 수령', now(), auth.uid(), auth.uid())
    on conflict (action_id, resource_id, coalesce(unit_key, '')) where kind in ('document', 'physical') do nothing;
  else
    delete from public.action_submission
     where action_id = p_action_id and resource_id = p_resource_id and kind = 'physical'
       and coalesce(unit_key, '') = coalesce(v_unit, '');
  end if;
  perform public._submission_sync_unit(v_req, p_resource_id, v_unit);
  perform public.submission_sync_assignee(v_req.task_id, p_resource_id);
  return jsonb_build_object('success', true, 'received', p_received);
end;
$$;


ALTER FUNCTION "public"."mark_action_received"("p_action_id" "uuid", "p_resource_id" "uuid", "p_received" boolean, "p_unit_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_task_physical_submission"("p_task_id" "uuid", "p_assignee_resource_id" "uuid", "p_received" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor_resource_id uuid;
  task_meta jsonb;
  deadline_count int := 0;
  remaining int := 0;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_received is null then
    raise exception 'p_received is required' using errcode = '22023';
  end if;

  actor_resource_id := public.current_actor_resource_id();
  if actor_resource_id is null then
    raise exception 'User resource not found' using errcode = '42501';
  end if;

  select coalesce(t.meta, '{}'::jsonb) into task_meta
  from public.task t where t.id = p_task_id
  for update;
  if not found then
    raise exception 'Task not found: %', p_task_id using errcode = 'P0002';
  end if;

  -- 매니저만. (관리자라도 매니저가 아니면 아래 set_task_assignee_status 가 거부하므로 같은 규칙으로 맞춘다)
  if not public.is_task_event_manager(p_task_id, actor_resource_id) then
    raise exception '실물 수령은 이 업무의 책임자만 기록할 수 있습니다.' using errcode = '42501';
  end if;

  if coalesce(task_meta->'submission'->>'mode', 'file') <> 'physical'
     or coalesce((task_meta->'submission'->>'required')::boolean, false) is not true then
    raise exception '실물로 받는 할 일이 아닙니다.' using errcode = '0A000';
  end if;

  if jsonb_typeof(task_meta->'units') = 'array' and jsonb_array_length(task_meta->'units') > 0 then
    raise exception '과제 단위 할 일은 실물로 받기를 지원하지 않습니다.' using errcode = '0A000';
  end if;

  if jsonb_typeof(task_meta->'deadlines') = 'array' then
    deadline_count := jsonb_array_length(task_meta->'deadlines');
  end if;
  if deadline_count > 1 then
    raise exception '마감이 여러 번인 할 일은 실물로 받기를 지원하지 않습니다.' using errcode = '0A000';
  end if;

  if not public.is_task_assignee(p_task_id, p_assignee_resource_id) then
    raise exception '이 할 일의 담당자가 아닙니다: %', p_assignee_resource_id using errcode = 'P0002';
  end if;

  if p_received then
    -- 두 번 눌러도 한 행 — 이미 받았으면 새로 넣지 않는다
    if not exists (
      select 1 from public.task_submission s
      where s.task_id = p_task_id and s.assignee_resource_id = p_assignee_resource_id and s.kind = 'physical'
    ) then
      insert into public.task_submission (task_id, assignee_resource_id, submitted_by, file_name, kind, meta)
      values (
        p_task_id, p_assignee_resource_id, auth.uid(), '실물 수령', 'physical',
        jsonb_build_object('received_by_resource_id', actor_resource_id)
      );
    end if;
    perform public.set_task_assignee_status(p_task_id, p_assignee_resource_id, 'completed');
  else
    delete from public.task_submission s
    where s.task_id = p_task_id and s.assignee_resource_id = p_assignee_resource_id and s.kind = 'physical';

    select count(*) into remaining
    from public.task_submission s
    where s.task_id = p_task_id and s.assignee_resource_id = p_assignee_resource_id;

    -- '완료인데 제출 없음'을 남기지 않는다(delete_task_submission 과 같은 규칙)
    if remaining = 0 then
      perform public.set_task_assignee_status(p_task_id, p_assignee_resource_id, 'pending');
    end if;
  end if;

  return jsonb_build_object(
    'success', true,
    'task_id', p_task_id,
    'assignee_id', p_assignee_resource_id,
    'received', p_received
  );
end;
$$;


ALTER FUNCTION "public"."mark_task_physical_submission"("p_task_id" "uuid", "p_assignee_resource_id" "uuid", "p_received" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_action_results"("p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.run');
  r record := mcp_private.wr_action_ref(p_action_id);
  v_board jsonb;
begin
  if r.action_type = 'message.send' then
    if not public.can_manage_task_action(p_action_id) then
      raise exception using errcode = '42501', message = '이 작업을 만든 사람과 업무 책임자만 볼 수 있습니다.';
    end if;
    return jsonb_build_object('type', r.action_type, 'sends', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('sent_at', s.sent_at, 'title', s.title, 'body', left(s.body, 500),
               'people', cardinality(s.recipient_ids),
               'not_linked', case when cardinality(s.unlinked_names) > 0 then to_jsonb(s.unlinked_names) end)) order by s.sent_at)
      from public.task_message_send s where s.action_id = p_action_id), '[]'::jsonb));
  end if;
  if public.request_kind_of(r.action_type) is null then
    raise exception using errcode = '22023', message = '결과를 모으는 작업(입력 받기·제출 받기·메시지 보내기)이 아닙니다.';
  end if;
  v_board := public.get_collect_board(p_action_id);
  return jsonb_build_object('type', r.action_type, 'board', v_board,
    'pending_names', mcp_private.wr_pending_names(p_action_id));
end;
$$;


ALTER FUNCTION "public"."mcp_action_results"("p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_add_action"("p_task_id" "uuid", "p_type" "text", "p_title" "text" DEFAULT NULL::"text", "p_settings" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.manage');
  t public.task := mcp_private.wk_task(p_task_id);
  def record; v_cfg jsonb := '{}'; v_id uuid; v_title text; v_warn text; s jsonb := coalesce(p_settings, '{}'); v_screens jsonb;
begin
  select * into def from mcp_private.wk_action_def(p_type);
  if def.kind is null then
    raise exception using errcode = '22023', message = format('연결할 수 없는 작업 종류입니다: %s — link.schedule_add·link.notice_write 등 바로가기, neis.screen, external.screen, document.spec_fill, collect.input, submit.file·submit.document·submit.physical, message.send', p_type);
  end if;
  if jsonb_typeof(s) <> 'object' then raise exception using errcode = '22023', message = 'settings 는 객체입니다.'; end if;
  if not def.multiple and exists (select 1 from task_action a where a.task_id = p_task_id and a.action_type = p_type and a.archived_at is null) then
    raise exception using errcode = '22023', message = format('이 할 일에는 «%s» 가 이미 있습니다(하나만 둘 수 있는 종류).', def.title);
  end if;
  v_title := coalesce(nullif(btrim(coalesce(p_title, '')), ''), def.title);
  if length(v_title) > 120 then raise exception using errcode = '22023', message = 'title 은 120자까지입니다.'; end if;

  if def.kind = 'neis' then
    v_screens := mcp_private.arr(s->'screens');
    if jsonb_array_length(v_screens) not between 1 and 10 then raise exception using errcode = '22023', message = 'neis.screen 의 screens 는 화면 1~10개입니다 [{name, path:[영역,단위,…], note?}].'; end if;
    if exists (select 1 from jsonb_array_elements(v_screens) x where coalesce(x->>'name', '') = '' or jsonb_typeof(x->'path') <> 'array') then
      raise exception using errcode = '22023', message = '화면마다 name 과 path(나이스 메뉴 경로 배열)가 필요합니다.';
    end if;
    v_cfg := jsonb_build_object('neis', jsonb_strip_nulls(jsonb_build_object('version', 1, 'screens', v_screens, 'note', nullif(s->>'note', ''))));
    if p_title is null then v_title := left(v_screens->0->>'name', 120); end if;    -- 웹 updateNeisActionConfig 처럼 첫 화면 이름
  elsif def.kind = 'external' then
    v_screens := mcp_private.arr(s->'screens');
    if coalesce(s->>'system', '') = '' then raise exception using errcode = '22023', message = 'external.screen 에는 system(예: K-에듀파인)이 필요합니다.'; end if;
    v_cfg := jsonb_build_object('external', jsonb_strip_nulls(jsonb_build_object('version', 1, 'system', s->>'system',
      'systemUrl', nullif(s->>'system_url', ''), 'screens', v_screens)));
  elsif def.kind = 'docgen' then
    if coalesce(s->>'generation_id', '') = '' then raise exception using errcode = '22023', message = 'document.spec_fill 에는 generation_id(문서 생성 방식의 action_id)가 필요합니다.'; end if;
    v_cfg := jsonb_build_object('defaultTemplate', mcp_private.wk_generation_template((s->>'generation_id')::uuid));
  end if;

  insert into task_action (task_id, action_type, handler_version, title, description, execution_mode, verification_mode, config, instance_key)
  values (p_task_id, p_type, 1, v_title, def.description, def.exec_mode, def.verify_mode, v_cfg,
          case when def.multiple then gen_random_uuid()::text else '' end)
  returning id into v_id;

  -- 입력·제출·메시지 설정은 웹과 같은 함수로(검사·요청 뒤 잠금이 거기 있다)
  if def.kind in ('collect', 'submit') then
    v_warn := public.update_collect_config(v_id, mcp_private.wk_request_config(p_type, nullif(btrim(coalesce(p_title, '')), ''), s, null))->>'warning';
  elsif def.kind = 'message' then
    -- update_message_config 는 값을 돌려주지 않는다(검사 실패는 예외)
    perform public.update_message_config(v_id, mcp_private.wk_request_config(p_type, nullif(btrim(coalesce(p_title, '')), ''), s, null));
  end if;
  -- 권장 순서를 이미 쓰는 할 일이면 끝에 붙인다
  if jsonb_typeof(t.meta->'actionFlow') = 'array' then
    update task set meta = jsonb_set(meta, '{actionFlow}', (meta->'actionFlow') || to_jsonb(v_id::text)) where id = p_task_id;
  end if;
  perform mcp_private.log_call(v_me, 'add_action', jsonb_build_object('action_id', v_id, 'task_id', p_task_id, 'type', p_type));
  return jsonb_strip_nulls(jsonb_build_object('action_id', v_id, 'type', p_type, 'title', (select title from task_action where id = v_id),
    'warning', v_warn,
    'note', case when def.kind in ('collect', 'submit') then '설정했다 — 아직 아무에게도 알림이 가지 않았다. 요청은 send_request(check_only 미리보기 → 사용자 확인 → fingerprint)로 보낸다(웹 [요청 보내기]와 같다).'
                 when def.kind = 'message' then '설정했다 — 아직 보내지 않았다. 발송은 send_message(check_only 미리보기 → 사용자 확인 → fingerprint)로 한다(웹 [보내기]와 같다).' end));
end $$;


ALTER FUNCTION "public"."mcp_add_action"("p_task_id" "uuid", "p_type" "text", "p_title" "text", "p_settings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_add_document_link"("p_url" "text", "p_title" "text", "p_folder" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_keywords" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('document.library');
  v_url   text := btrim(coalesce(p_url, ''));
  v_title text := mcp_private.opt_text(p_title, 'title', 200);
  v_dept  text := mcp_private.opt_text(p_department, 'department', 50);
  v_cat   text := mcp_private.opt_text(p_category, 'category', 50);
  v_year  integer := extract(year from (now() at time zone 'Asia/Seoul'))::int;
  v_id    text;
  v_type  text;
  v_mime  text;
  v_edit  text;
  v_kw    jsonb;
  v_doc   public.documents;
begin
  if v_title is null then raise exception using errcode = '22023', message = 'title 이 필요합니다(서류함에 보일 이름).'; end if;
  if p_keywords is not null and cardinality(p_keywords) > 20 then raise exception using errcode = '22023', message = '키워드는 20개까지입니다.'; end if;
  if v_url ~ 'docs\.google\.com/document/d/[A-Za-z0-9_-]+' then
    v_id := substring(v_url from 'docs\.google\.com/document/d/([A-Za-z0-9_-]+)'); v_type := 'document';
    v_mime := 'application/vnd.google-apps.document'; v_edit := format('https://docs.google.com/document/d/%s/edit', v_id);
  elsif v_url ~ 'docs\.google\.com/spreadsheets/d/[A-Za-z0-9_-]+' then
    v_id := substring(v_url from 'docs\.google\.com/spreadsheets/d/([A-Za-z0-9_-]+)'); v_type := 'spreadsheet';
    v_mime := 'application/vnd.google-apps.spreadsheet'; v_edit := format('https://docs.google.com/spreadsheets/d/%s/edit', v_id);
  elsif v_url ~ 'docs\.google\.com/presentation/d/[A-Za-z0-9_-]+' then
    v_id := substring(v_url from 'docs\.google\.com/presentation/d/([A-Za-z0-9_-]+)'); v_type := 'presentation';
    v_mime := 'application/vnd.google-apps.presentation'; v_edit := format('https://docs.google.com/presentation/d/%s/edit', v_id);
  elsif v_url ~ 'drive\.google\.com/drive/folders/[A-Za-z0-9_-]+' then
    v_id := substring(v_url from 'drive\.google\.com/drive/folders/([A-Za-z0-9_-]+)'); v_type := 'folder';
    v_mime := 'application/vnd.google-apps.folder'; v_edit := format('https://drive.google.com/drive/folders/%s', v_id);
  elsif v_url ~ 'drive\.google\.com/file/d/[A-Za-z0-9_-]+' then
    v_id := substring(v_url from 'drive\.google\.com/file/d/([A-Za-z0-9_-]+)'); v_type := 'file';
    v_mime := 'application/octet-stream'; v_edit := format('https://drive.google.com/file/d/%s/view', v_id);
  else
    raise exception using errcode = '22023', message = '구글 드라이브 주소만 등록할 수 있습니다(문서·시트·슬라이드·파일·폴더 공유 주소). 다른 파일은 start_document_upload 로 올린다.';
  end if;
  v_kw := coalesce((select jsonb_agg(distinct btrim(k)) from unnest(p_keywords) k where btrim(k) <> ''), '[]'::jsonb);

  insert into documents (title, file_name, file_type, file_size, storage_path, upload_status, user_id, meta)
  values (v_title, v_title, v_mime, 0, v_edit, 'completed', auth.uid(),
    jsonb_strip_nulls(jsonb_build_object(
      'department', v_dept, 'category', v_cat, 'keywords', v_kw, 'search_keywords', v_kw,
      'description', mcp_private.opt_text(p_description, 'description', 2000),
      'directory_path', coalesce(mcp_private.doc_folder(p_folder), array_to_string(array_remove(array[v_year::text, '서류함', v_dept], null), '/')),
      'uploadContext', jsonb_strip_nulls(jsonb_build_object('feature', '서류함', 'year', v_year, 'department', v_dept)),
      'uploaded_from', 'google_drive', 'google_drive_id', v_id, 'google_drive_edit_url', v_edit,
      'is_google_drive_file', true, 'uploaded_via', 'mcp')))
  returning * into v_doc;
  perform mcp_private.log_call(v_me, 'add_document_link', jsonb_build_object('document_id', v_doc.id, 'type', v_type));
  return jsonb_build_object('created', true, 'document', mcp_private.doc_out(v_doc),
    'note', '서류함에는 링크만 등록된다 — 드라이브의 공유 설정(누가 열 수 있는지)은 드라이브에서 정한다.');
end;
$$;


ALTER FUNCTION "public"."mcp_add_document_link"("p_url" "text", "p_title" "text", "p_folder" "text", "p_category" "text", "p_department" "text", "p_description" "text", "p_keywords" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_add_ipsi_news"("p_url" "text", "p_title" "text", "p_category" "text", "p_article_date" "date" DEFAULT NULL::"date", "p_content" "text" DEFAULT NULL::"text", "p_headline_summary" "text" DEFAULT NULL::"text", "p_core_points" "text"[] DEFAULT NULL::"text"[], "p_strategy_implications" "text"[] DEFAULT NULL::"text"[], "p_data_points" "text"[] DEFAULT NULL::"text"[], "p_cautions" "text"[] DEFAULT NULL::"text"[], "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('ipsi.hub');
  v_url text := btrim(coalesce(p_url, ''));
  v_source text;
  v_dup record;
  v_cp text[] := mcp_private.ipsi_lines(p_core_points, 'core_points');
  v_si text[] := mcp_private.ipsi_lines(p_strategy_implications, 'strategy_implications');
  v_dp text[] := mcp_private.ipsi_lines(p_data_points, 'data_points');
  v_ca text[] := mcp_private.ipsi_lines(p_cautions, 'cautions');
  v_summary text := nullif(btrim(coalesce(p_headline_summary, '')), '');
  v_id uuid;
begin
  perform mcp_private.ipsi_teacher();
  if v_url !~ '^https?://[^/\s]+\.[^/\s]+' or length(v_url) > 2000 then
    raise exception using errcode = '22023', message = 'url 은 http(s) 기사 주소입니다(2000자까지).';
  end if;
  if length(btrim(coalesce(p_title, ''))) not between 1 and 300 then
    raise exception using errcode = '22023', message = 'title 은 1~300자입니다.';
  end if;
  if p_category is null or p_category not in ('수시', '정시', '진로', '대입', '전형분석', '학생부', '기타') then
    raise exception using errcode = '22023', message = 'category 는 수시 · 정시 · 진로 · 대입 · 전형분석 · 학생부 · 기타 중 하나입니다(웹 기사 분류).';
  end if;
  if p_article_date is not null and p_article_date > (now() at time zone 'Asia/Seoul')::date + 1 then
    raise exception using errcode = '22023', message = 'article_date 가 미래입니다.';
  end if;
  if length(coalesce(p_content, '')) > 60000 or length(coalesce(v_summary, '')) > 500 then
    raise exception using errcode = '22023', message = 'content 는 60000자, headline_summary 는 500자까지입니다.';
  end if;
  select n.id, n.title, n.source into v_dup from educational_news n
  where n.url = v_url or rtrim(n.url, '/') = rtrim(v_url, '/') limit 1;
  if found then
    raise exception using errcode = '23505',
      message = format('이미 있는 기사입니다 — «%s» (%s, id %s).', v_dup.title, mcp_private.ipsi_source_label(v_dup.source), v_dup.id);
  end if;
  v_source := mcp_private.ipsi_news_source(v_url);
  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true,
      'title', btrim(p_title), 'url', v_url, 'source', mcp_private.ipsi_source_label(v_source), 'category', p_category,
      'article_date', p_article_date, 'summary', v_summary,
      'core_points', to_jsonb(v_cp), 'strategy_implications', to_jsonb(v_si), 'data_points', to_jsonb(v_dp), 'cautions', to_jsonb(v_ca),
      'content_length', length(coalesce(p_content, '')),
      'note', '아직 넣지 않았다 — 사용자에게 보여 확인받은 뒤 check_only:false. 입시 정보 피드는 학생도 본다. '
              || '넣은 뒤 고치기·지우기는 관리자만 된다.'));
  end if;
  insert into educational_news (source, title, url, article_date, category, headline_summary,
                                core_points, strategy_implications, data_points, cautions, content,
                                collected_at, analyzed_at, meta)
  values (v_source, btrim(p_title), v_url, p_article_date, p_category, v_summary,
          v_cp, v_si, v_dp, v_ca, nullif(btrim(coalesce(p_content, '')), ''),
          now(),
          case when v_summary is not null or coalesce(cardinality(v_cp), 0) + coalesce(cardinality(v_si), 0)
                    + coalesce(cardinality(v_dp), 0) + coalesce(cardinality(v_ca), 0) > 0 then now() end,
          jsonb_build_object('added_by', auth.uid(), 'added_via', 'mcp'))
  returning id into v_id;
  perform mcp_private.log_call(v_me, 'add_ipsi_news', jsonb_build_object('news_id', v_id, 'source', v_source));
  return jsonb_build_object('saved', true, 'id', v_id, 'source', mcp_private.ipsi_source_label(v_source),
    'note', '웹 «입시 정보» 피드에 보인다(학생 포함). 고치기·지우기는 관리자만.');
end;
$$;


ALTER FUNCTION "public"."mcp_add_ipsi_news"("p_url" "text", "p_title" "text", "p_category" "text", "p_article_date" "date", "p_content" "text", "p_headline_summary" "text", "p_core_points" "text"[], "p_strategy_implications" "text"[], "p_data_points" "text"[], "p_cautions" "text"[], "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_add_ipsi_video"("p_url" "text", "p_title" "text", "p_category" "text", "p_headline_summary" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_core_points" "text"[] DEFAULT NULL::"text"[], "p_strategy_implications" "text"[] DEFAULT NULL::"text"[], "p_cautions" "text"[] DEFAULT NULL::"text"[], "p_key_concepts" "text"[] DEFAULT NULL::"text"[], "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('ipsi.hub');
  v_vid text := mcp_private.ipsi_youtube_id(p_url);
  v_url text;
  v_dup record;
  v_meta jsonb;
  v_analyzed boolean;
  v_id uuid;
begin
  perform mcp_private.ipsi_teacher();
  if v_vid is null then
    raise exception using errcode = '22023', message = 'YouTube 영상 주소가 아닙니다(youtube.com/watch?v= · youtu.be · shorts · live).';
  end if;
  if length(btrim(coalesce(p_title, ''))) not between 1 and 300 then
    raise exception using errcode = '22023', message = 'title 은 1~300자입니다.';
  end if;
  if p_category is null or p_category not in ('입시', '진학') then
    raise exception using errcode = '22023', message = 'category 는 입시 · 진학 중 하나입니다(웹 영상 분류).';
  end if;
  if length(coalesce(p_headline_summary, '')) > 500 or length(coalesce(p_description, '')) > 5000 then
    raise exception using errcode = '22023', message = 'headline_summary 는 500자, description 은 5000자까지입니다.';
  end if;
  v_url := 'https://www.youtube.com/watch?v=' || v_vid;
  select v.id, v.title into v_dup from educational_videos v
  where v.video_id = v_vid or strpos(v.url, v_vid) > 0 limit 1;
  if found then
    raise exception using errcode = '23505',
      message = format('이미 있는 영상입니다 — «%s» (id %s). 고치려면 update_ipsi_video.', v_dup.title, v_dup.id);
  end if;
  v_meta := jsonb_strip_nulls(jsonb_build_object(
    'description', nullif(btrim(coalesce(p_description, '')), ''),
    'core_points', to_jsonb(nullif(mcp_private.ipsi_lines(p_core_points, 'core_points'), '{}')),
    'strategy_implications', to_jsonb(nullif(mcp_private.ipsi_lines(p_strategy_implications, 'strategy_implications'), '{}')),
    'cautions', to_jsonb(nullif(mcp_private.ipsi_lines(p_cautions, 'cautions'), '{}')),
    'key_concepts', to_jsonb(nullif(mcp_private.ipsi_lines(p_key_concepts, 'key_concepts', 30), '{}'))));
  v_analyzed := nullif(btrim(coalesce(p_headline_summary, '')), '') is not null or v_meta <> '{}'::jsonb;
  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true,
      'title', btrim(p_title), 'url', v_url, 'video_id', v_vid, 'category', p_category,
      'summary', nullif(btrim(coalesce(p_headline_summary, '')), ''), 'meta', nullif(v_meta, '{}'::jsonb),
      'url_changed', case when v_url <> btrim(p_url) then '웹 플레이어가 읽는 주소 모양으로 바꿔 넣는다' end,
      'note', '아직 넣지 않았다 — 사용자에게 보여 확인받은 뒤 check_only:false. 입시 정보 피드는 학생도 본다.'));
  end if;
  insert into educational_videos (title, url, thumbnail, category, created_by, video_id, meta, headline_summary, analyzed_at)
  values (btrim(p_title), v_url, 'https://img.youtube.com/vi/' || v_vid || '/maxresdefault.jpg', p_category, auth.uid(), v_vid,
          v_meta, nullif(btrim(coalesce(p_headline_summary, '')), ''), case when v_analyzed then now() end)
  returning id into v_id;
  perform mcp_private.log_call(v_me, 'add_ipsi_video', jsonb_build_object('video_id', v_id, 'youtube_id', v_vid));
  return jsonb_build_object('saved', true, 'id', v_id, 'url', v_url, 'note', '웹 «입시 정보» 피드에 보인다(학생 포함).');
end;
$$;


ALTER FUNCTION "public"."mcp_add_ipsi_video"("p_url" "text", "p_title" "text", "p_category" "text", "p_headline_summary" "text", "p_description" "text", "p_core_points" "text"[], "p_strategy_implications" "text"[], "p_cautions" "text"[], "p_key_concepts" "text"[], "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_add_study_room_reservations"("p_room_id" "uuid", "p_student" "text", "p_seat" "text", "p_start" "date", "p_end" "date", "p_days" integer[] DEFAULT NULL::integer[], "p_period_ids" integer[] DEFAULT NULL::integer[], "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('studyroom.manage');
  v_room  public.study_rooms;
  v_stu   record;
  v_pids  integer[];
  v_days  integer[];
  v_seat  text := upper(btrim(coalesce(p_seat, '')));
  v_want  integer;
  v_rows  jsonb;
  v_skip_student integer;
  v_skip_seat integer;
  v_n     integer;
begin
  perform mcp_private.sr_require_teacher();
  select * into v_room from study_rooms where id = p_room_id;
  if not found or not v_room.is_active then raise exception using errcode = 'P0002', message = '사용 중인 열람실을 찾을 수 없습니다.'; end if;
  select * into v_stu from mcp_private.sr_resolve_student(p_student);
  if not mcp_private.sr_can_manage_student(v_stu.grade, v_stu.class) then
    raise exception using errcode = '42501', message = format('%s 학생의 자습은 %s학년 부장·%s학년 %s반 담임만 추가할 수 있습니다.', p_student, v_stu.grade, v_stu.grade, v_stu.class);
  end if;
  if not mcp_private.sr_seat_ok(v_room.seat_layout, v_seat) then
    raise exception using errcode = '22023', message = format('%s 에 %s 자리가 없거나 쓸 수 없는 자리입니다.', v_room.name, coalesce(nullif(v_seat, ''), '(빈 자리 번호)'));
  end if;
  if p_start is null or p_end is null or p_start > p_end then raise exception using errcode = '22023', message = 'start ≤ end 인 두 날짜가 필요합니다.'; end if;
  if p_end - p_start > 120 then raise exception using errcode = '22023', message = '한 번에 120일까지입니다.'; end if;
  if p_start < (now() at time zone 'Asia/Seoul')::date then raise exception using errcode = '22023', message = '지난 날짜에는 자습을 추가하지 않습니다.'; end if;

  v_days := case when p_days is null then v_room.operating_days
                 else (select array_agg(d) from unnest(p_days) d where d = any(v_room.operating_days)) end;
  if v_days is null or cardinality(v_days) = 0 then raise exception using errcode = '22023', message = '운영 요일과 겹치는 요일이 없습니다.'; end if;
  v_pids := mcp_private.sr_period_ids(v_room);
  if p_period_ids is not null then
    if exists (select 1 from unnest(p_period_ids) x where not x = any(v_pids)) then
      raise exception using errcode = '22023', message = format('이 열람실의 교시 id 는 %s 입니다(0 = 종일).', array_to_string(v_pids, ', '));
    end if;
    v_pids := p_period_ids;
  end if;

  with want as (
    select d::date as reservation_date, pid as period_id
      from generate_series(p_start, p_end, interval '1 day') d cross join unnest(v_pids) pid
     where extract(dow from d)::int = any(v_days)),
  judged as (
    select w.*,
      -- 학생 겹침: 중복 허용 열람실은 그 열람실 안에서만, 일반 열람실은 중복 허용 열람실을 빼고(웹 applyPoolFilter)
      exists (select 1 from seat_reservations s join study_rooms sr on sr.id = s.room_id
               where s.student_id = v_stu.profile_id and s.reservation_date = w.reservation_date
                 and (case when v_room.allow_duplicate_reservation then s.room_id = p_room_id
                           else not coalesce(sr.allow_duplicate_reservation, false) end)
                 and (s.period_id = 0 or w.period_id = 0 or s.period_id = w.period_id)) as student_busy,
      exists (select 1 from seat_reservations s
               where s.room_id = p_room_id and s.seat_number = v_seat and s.reservation_date = w.reservation_date
                 and (s.period_id = 0 or w.period_id = 0 or s.period_id = w.period_id)) as seat_busy
      from want w)
  select count(*), count(*) filter (where student_busy), count(*) filter (where seat_busy and not student_busy),
         coalesce(jsonb_agg(jsonb_build_object('date', reservation_date, 'period_id', period_id) order by reservation_date, period_id)
                  filter (where not student_busy and not seat_busy), '[]'::jsonb)
    into v_want, v_skip_student, v_skip_seat, v_rows
    from judged;

  if coalesce(p_check_only, true) or jsonb_array_length(v_rows) = 0 then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true, 'room', v_room.name, 'seat', v_seat,
      'student', format('%s-%s-%s', v_stu.grade, v_stu.class, v_stu.number), 'name', v_stu.name,
      'will_create', jsonb_array_length(v_rows), 'requested', v_want,
      'skipped_student_busy', nullif(v_skip_student, 0), 'skipped_seat_taken', nullif(v_skip_seat, 0),
      'first', v_rows->0->>'date', 'last', v_rows->-1->>'date',
      'note', case when jsonb_array_length(v_rows) = 0 then '만들 수 있는 날짜·교시가 없다(학생이 이미 신청했거나 자리가 찼다).'
                   else '아직 만들지 않았다 — 학생·열람실·자리·기간·건수를 사용자에게 보여 확인받은 뒤 check_only:false.' end));
  end if;

  insert into seat_reservations (student_id, room_id, seat_number, reservation_date, period_id)
  select v_stu.profile_id, p_room_id, v_seat, (x->>'date')::date, (x->>'period_id')::int from jsonb_array_elements(v_rows) x;
  get diagnostics v_n = row_count;
  perform mcp_private.log_call(v_me, 'add_study_room_reservations',
    jsonb_build_object('room_id', p_room_id, 'grade', v_stu.grade, 'class', v_stu.class, 'rows', v_n));
  return jsonb_strip_nulls(jsonb_build_object('saved', true, 'created', v_n, 'room', v_room.name, 'seat', v_seat,
    'student', format('%s-%s-%s', v_stu.grade, v_stu.class, v_stu.number), 'name', v_stu.name,
    'skipped_student_busy', nullif(v_skip_student, 0), 'skipped_seat_taken', nullif(v_skip_seat, 0),
    'first', v_rows->0->>'date', 'last', v_rows->-1->>'date'));
end;
$$;


ALTER FUNCTION "public"."mcp_add_study_room_reservations"("p_room_id" "uuid", "p_student" "text", "p_seat" "text", "p_start" "date", "p_end" "date", "p_days" integer[], "p_period_ids" integer[], "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_apply_budget_card"("p_lines" "jsonb", "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_new_name" "text" DEFAULT NULL::"text", "p_new_kind" "text" DEFAULT NULL::"text", "p_year" integer DEFAULT NULL::integer, "p_file_name" "text" DEFAULT NULL::"text", "p_card_date" "date" DEFAULT NULL::"date", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('budget.manage');
  v_project uuid := p_project_id;
  v_line jsonb;
  v_hit uuid;
  v_used uuid[] := '{}';
  v_out jsonb := '[]'::jsonb;
  v_preview jsonb := '[]'::jsonb;
  v_key text;
  v_existing record;
  v_missing jsonb;
  v_result jsonb;
begin
  if jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception using errcode = '22023', message = 'lines 에 산출내역이 하나 이상 있어야 합니다 — [{expense_item, name, budget, pumui, wonin}].';
  end if;
  if jsonb_array_length(p_lines) > 200 then
    raise exception using errcode = '22023', message = 'lines 는 200줄까지입니다(사업 하나씩 보내세요).';
  end if;
  if v_project is not null then
    perform mcp_private.bg_require_edit(v_project);
  else
    if length(btrim(coalesce(p_new_name, ''))) not between 1 and 200 then
      raise exception using errcode = '22023', message = '새 사업이면 new_name(카드의 사업 이름 — [목적]… 그대로)이 필요합니다. 있는 사업이면 project_id.';
    end if;
    if coalesce(p_new_kind, 'basic') not in ('purpose', 'total', 'basic') then
      raise exception using errcode = '22023', message = 'new_kind 는 purpose(목적사업)·total(총액배분)·basic 중 하나입니다.';
    end if;
  end if;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    if length(btrim(coalesce(v_line ->> 'name', ''))) = 0 then
      raise exception using errcode = '22023', message = '모든 줄에 name(산출내역)이 있어야 합니다.';
    end if;
    v_key := mcp_private.bg_norm(coalesce(v_line ->> 'expense_item', '') || '|' || (v_line ->> 'name'));
    v_hit := null;
    if v_project is not null then
      -- 짝: 카드 열쇠 → (비목, 이름) → 이름 (parseBudgetCard.ts diffCardWithLines 와 같은 순서)
      select id into v_hit from budget_line
       where project_id = v_project and card_key = v_key and not (id = any (v_used)) limit 1;
      if v_hit is null then
        select id into v_hit from budget_line
         where project_id = v_project and not (id = any (v_used))
           and mcp_private.bg_norm(name) = mcp_private.bg_norm(v_line ->> 'name')
           and mcp_private.bg_norm(coalesce(expense_item, '')) = mcp_private.bg_norm(coalesce(v_line ->> 'expense_item', ''))
         limit 1;
      end if;
      if v_hit is null then
        select id into v_hit from budget_line
         where project_id = v_project and not (id = any (v_used))
           and mcp_private.bg_norm(name) = mcp_private.bg_norm(v_line ->> 'name')
         limit 1;
      end if;
    end if;
    if v_hit is not null then v_used := v_used || v_hit; end if;
    select budget_amount, pumui, wonin, manual_override into v_existing from budget_line where id = v_hit;
    v_preview := v_preview || jsonb_strip_nulls(jsonb_build_object(
      'name', v_line ->> 'name', 'change', case when v_hit is null then 'new'
        when v_existing.budget_amount = coalesce((v_line ->> 'budget')::bigint, 0) and v_existing.pumui = coalesce((v_line ->> 'pumui')::bigint, 0)
             and v_existing.wonin = coalesce((v_line ->> 'wonin')::bigint, 0) then 'same' else 'changed' end,
      'budget', jsonb_build_object('before', v_existing.budget_amount, 'after', coalesce((v_line ->> 'budget')::bigint, 0)),
      'wonin', jsonb_build_object('before', v_existing.wonin, 'after', coalesce((v_line ->> 'wonin')::bigint, 0)),
      'overwrites_manual', case when v_existing.manual_override then true end));
    v_out := v_out || jsonb_build_object(
      'line_id', v_hit, 'name', btrim(v_line ->> 'name'), 'expense_item', nullif(btrim(coalesce(v_line ->> 'expense_item', '')), ''),
      'card_key', v_key,
      'budget', coalesce((v_line ->> 'budget')::bigint, 0), 'pumui', coalesce((v_line ->> 'pumui')::bigint, 0),
      'wonin', coalesce((v_line ->> 'wonin')::bigint, 0), 'jichul', coalesce((v_line ->> 'jichul')::bigint, 0),
      'jigeup', coalesce((v_line ->> 'jigeup')::bigint, 0));
  end loop;

  if v_project is not null then
    select coalesce(jsonb_agg(name), '[]'::jsonb) into v_missing from budget_line
     where project_id = v_project and origin = 'card' and not (id = any (v_used));
  end if;

  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true,
      'project', coalesce((select name from budget_project where id = v_project), '새 사업: ' || btrim(p_new_name)),
      'lines', v_preview,
      'new', (select count(*) from jsonb_array_elements(v_preview) x where x ->> 'change' = 'new'),
      'changed', (select count(*) from jsonb_array_elements(v_preview) x where x ->> 'change' = 'changed'),
      'missing_from_card', v_missing,
      'note', '아직 반영하지 않았다 — 새 줄·바뀐 줄·카드에 없는 줄을 사용자에게 보여 확인받은 뒤 check_only:false. '
              || '예산현액이 바뀐 줄이 있으면 «카드 반영» 확정 차수가 생긴다. 계획은 그대로 남는다.'));
  end if;

  if v_project is null then
    insert into budget_project (fiscal_year, name, kind, card_key)
    values (coalesce(p_year, mcp_private.bg_fiscal_year(p_card_date)), btrim(p_new_name), coalesce(p_new_kind, 'basic'), mcp_private.bg_norm(p_new_name))
    returning id into v_project;
  end if;
  v_result := public.budget_apply_card(v_project, p_file_name,
    jsonb_build_object('lines', v_out, 'card_date', coalesce(p_card_date, (now() at time zone 'Asia/Seoul')::date)));
  perform mcp_private.log_call(v_me, 'apply_budget_card', jsonb_build_object('project_id', v_project, 'lines', jsonb_array_length(p_lines)));
  return v_result || jsonb_build_object('project_id', v_project, 'note', '웹 «업무 관리 › 예산»에 바로 보인다.');
end;
$$;


ALTER FUNCTION "public"."mcp_apply_budget_card"("p_lines" "jsonb", "p_project_id" "uuid", "p_new_name" "text", "p_new_kind" "text", "p_year" integer, "p_file_name" "text", "p_card_date" "date", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_archive_action"("p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('work.manage');
  a     public.task_action;
  v_why text;
  v_n   int;
begin
  select * into a from task_action where id = p_action_id and archived_at is null;
  if a.id is null or a.task_id is null then raise exception using errcode = 'P0002', message = '그 작업을 찾지 못했습니다.'; end if;
  perform mcp_private.wk_task(a.task_id);
  v_why := mcp_private.wk_action_progress(p_action_id);
  if v_why is null then
    raise exception using errcode = '22023', message = '진행 기록이 없는 작업이라 보관하지 않고 뗍니다 — remove_action 을 쓰세요.';
  end if;
  -- 웹 deleteTaskAction 과 같은 칸 — 입력 받기 요청은 트리거(collect_close_on_action_archive)가 마감한다
  update task_action set archived_at = now() where id = p_action_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception using errcode = '42501', message = '이 작업은 만든 사람만 보관할 수 있습니다(웹과 같다).'; end if;
  perform mcp_private.log_call(v_me, 'archive_action', jsonb_build_object('action_id', p_action_id, 'title', a.title, 'why', v_why));
  return jsonb_build_object('archived', true, 'action_id', p_action_id, 'title', a.title, 'progress', v_why,
    'note', '보관했다 — 할 일에서 빠지고 받은 응답·실행 기록·문서는 남는다. 입력 받기 요청이었다면 요청도 마감됐다. 되돌리기는 웹에서.');
end;
$$;


ALTER FUNCTION "public"."mcp_archive_action"("p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_archive_context"("p_key" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('knowledge.context');
  c public.school_context;
begin
  if length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception using errcode = '22023', message = '보관하는 까닭(reason)을 적어 주세요.';
  end if;
  select * into c from school_context where key = p_key;
  if not found then
    raise exception using errcode = 'P0002', message = '그 맥락이 없습니다.';
  end if;
  if not public.is_admin() and not (c.kind = 'note' and c.created_by = auth.uid()) then
    raise exception using errcode = '42501', message = '보관할 수 있는 것은 내가 쓴 맥락(note)뿐입니다.';
  end if;
  update school_context set status = 'archived', archived_reason = left(btrim(p_reason), 500) where id = c.id;
  perform mcp_private.log_call(v_me, 'archive_context', jsonb_build_object('key', p_key));
  return jsonb_build_object('archived', true, 'key', p_key);
end;
$$;


ALTER FUNCTION "public"."mcp_archive_context"("p_key" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_cancel_class_swap"("p_swap_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('swap.class');
  v_row public.class_swap;
  v_was text;
begin
  select * into v_row from class_swap where id = p_swap_id and requester_resource_id = v_me;  -- 잠그기 전에 읽는다(respond 와 같은 이유)
  if not found then raise exception using errcode = 'P0002', message = '내가 보낸 교체 요청을 찾을 수 없습니다(list_class_swaps 의 swap_id).'; end if;
  if v_row.status not in ('pending', 'approved') then
    raise exception using errcode = '22023', message = format('이미 끝난 요청입니다(%s).', v_row.status);
  end if;
  select * into v_row from class_swap where id = p_swap_id and status in ('pending', 'approved') for update;
  if not found then raise exception using errcode = '22023', message = '그 사이에 끝난 요청입니다.'; end if;
  v_was := v_row.status;

  update class_swap
  set status = 'cancelled',
      meta = meta || jsonb_build_object('via_cancelled', jsonb_build_object('channel', 'mcp', 'client_id', nullif(auth.jwt()->>'client_id', ''), 'at', now()))
  where id = v_row.id
  returning * into v_row;

  insert into notification_events (type, title, message, resource_id, priority, meta, is_read)
  values ('class_swap_cancelled', '수업 교체 취소됨',
    format(E'%s 선생님이 수업 교체 요청을 취소했습니다.\n\n📅 %s\n교체 요청: %s ↔ %s',
           v_row.meta->>'requester_name', mcp_private.ko_date(v_row.approver_swap_date),
           coalesce(v_row.meta->>'requester_section_name', ''), coalesce(v_row.meta->>'approver_section_name', '')),
    v_row.approver_resource_id, 'low',
    jsonb_build_object('swap_id', v_row.id, 'requester_name', v_row.meta->>'requester_name', 'swap_date', v_row.approver_swap_date),
    false);

  perform mcp_private.log_call(v_me, 'cancel_class_swap', jsonb_build_object('swap_id', v_row.id, 'was', v_was));
  return mcp_private.sw_out(v_row, v_me) || jsonb_build_object('note',
    case when v_was = 'approved' then '승인됐던 교체를 취소했다 — 시간표가 원래대로 돌아가고 상대 선생님에게 알림이 갔다.'
         else '대기 중이던 요청을 취소했다 — 상대 선생님에게 알림이 갔다.' end);
end;
$$;


ALTER FUNCTION "public"."mcp_cancel_class_swap"("p_swap_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_cancel_gajeong_issue"("p_issue_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('issue.register');
  v_row document_issue := mcp_private.iss_lock_mine(p_issue_id, array['gajeong'], '취소할');
begin
  update document_issue set status = 'cancelled', meta = meta || jsonb_build_object('via_cancelled', mcp_private.iss_via())
  where id = v_row.id;
  if not found then
    raise exception using errcode = '42501', message = '취소하지 못했습니다(작성자·관리자만).';
  end if;
  perform mcp_private.log_call(v_me, 'cancel_gajeong_issue', jsonb_build_object('issue_id', v_row.id, 'issue_no', v_row.issue_no));
  return jsonb_build_object('issue_id', v_row.id, 'issue_no', v_row.issue_no, 'status', 'cancelled',
    'note', '번호는 다시 쓰지 않는다 — 대장에 «삭제된 발급»으로 남는다.');
end;
$$;


ALTER FUNCTION "public"."mcp_cancel_gajeong_issue"("p_issue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_cancel_my_purchase_item"("p_request_id" "uuid", "p_row_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('purchase.request');
  v_lock  record;
  v_rest  jsonb;
  v_item  text;
  v_deleted boolean;
begin
  select * into v_lock from mcp_private.pr_lock_my_row(v_me, p_request_id, p_row_id, '취소할');
  v_item := v_lock.row_cells ->> mcp_private.pr_name_col((v_lock.page).columns);

  select coalesce(jsonb_agg(e order by o), '[]'::jsonb) into v_rest
  from jsonb_array_elements(mcp_private.arr((v_lock.req).items)) with ordinality t(e, o)
  where e->>'id' is distinct from p_row_id;

  v_deleted := not exists (select 1 from jsonb_array_elements(v_rest) e
                           where mcp_private.pr_row_meaningful(e->'cells', (v_lock.page).columns));
  if v_deleted then
    delete from purchase_requests where id = p_request_id;
  else
    update purchase_requests set items = v_rest where id = p_request_id;
  end if;

  perform mcp_private.log_call(v_me, 'cancel_my_purchase_item',
    jsonb_build_object('request_id', p_request_id, 'row_id', p_row_id, 'request_deleted', v_deleted));

  return jsonb_strip_nulls(jsonb_build_object(
    'request_id', p_request_id, 'row_id', p_row_id, 'item', v_item,
    'request_deleted', case when v_deleted then true end,
    'note', case when v_deleted then '취소했다. 남은 품목이 없어 신청이 지워졌다.' else '취소했다.' end
  ));
end;
$$;


ALTER FUNCTION "public"."mcp_cancel_my_purchase_item"("p_request_id" "uuid", "p_row_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_cancel_sign_request"("p_kind" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('sign.request');
  v_out jsonb;
begin
  if p_kind not in ('approval', 'signature') then raise exception using errcode = '22023', message = 'kind 는 approval · signature 중 하나입니다.'; end if;
  v_out := mcp_private.sign_items('sent', true, p_kind, p_request_id);
  if jsonb_array_length(v_out) = 0 or not coalesce((v_out->0->>'i_requested')::boolean, false) then
    raise exception using errcode = '42501', message = '내가 올린 요청만 취소할 수 있습니다.';
  end if;
  if p_kind = 'approval' then
    perform public.cancel_approval_request(p_request_id);
  else
    perform public.cancel_signature_request(p_request_id);
  end if;
  perform mcp_private.log_call(v_me, 'cancel_sign_request', jsonb_build_object('kind', p_kind));
  return jsonb_build_object('cancelled', true, 'request', mcp_private.sign_items('all', true, p_kind, p_request_id)->0,
    'note', '취소는 알림을 보내지 않는다(웹과 같다). 기록은 남는다.');
end;
$$;


ALTER FUNCTION "public"."mcp_cancel_sign_request"("p_kind" "text", "p_request_id" "uuid") OWNER TO "postgres";


