CREATE OR REPLACE FUNCTION "public"."mcp_cancel_volunteer_issues"("p_issue_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('issue.register');
  v_id  uuid;
  v_row document_issue;
  v_out jsonb := '[]'::jsonb;
begin
  if p_issue_ids is null or cardinality(p_issue_ids) = 0 then
    raise exception using errcode = '22023', message = 'issue_ids 에 취소할 발급을 1개 이상 주세요.';
  end if;
  if cardinality(p_issue_ids) > 300 then
    raise exception using errcode = '22023', message = '한 번에 300건까지입니다.';
  end if;
  foreach v_id in array (select array_agg(distinct x) from unnest(p_issue_ids) x) loop
    v_row := mcp_private.iss_lock_mine(v_id, array['volunteer_personal', 'volunteer_class', 'volunteer_club'], '취소할');
    update document_issue set status = 'cancelled', meta = meta || jsonb_build_object('via_cancelled', mcp_private.iss_via())
    where id = v_row.id;
    if not found then
      raise exception using errcode = '42501', message = format('%s 을(를) 취소하지 못했습니다(작성자·관리자만).', v_row.issue_no);
    end if;
    v_out := v_out || jsonb_build_object('issue_id', v_row.id, 'issue_no', v_row.issue_no);
  end loop;
  perform mcp_private.log_call(v_me, 'cancel_volunteer_issues', jsonb_build_object('count', jsonb_array_length(v_out)));
  return jsonb_build_object('cancelled', v_out,
    'note', '번호는 다시 쓰지 않는다 — 대장에 «삭제된 발급»으로 남는다.');
end;
$$;


ALTER FUNCTION "public"."mcp_cancel_volunteer_issues"("p_issue_ids" "uuid"[]) OWNER TO "postgres";


