  v_q text := lower(nullif(btrim(p_query), ''));
begin
  return jsonb_build_object(
    'academic_year', v->'year', 'years', v->'years', 'i_am_manager', v->'is_manager',
    'clubs', coalesce((select jsonb_agg(mcp_private.club_brief(c))
                       from jsonb_array_elements(v->'clubs') c
                       where v_q is null or strpos(lower(concat_ws(' ', c->>'name', c->>'place', c->>'category',
                             (select string_agg(a->>'name', ' ') from jsonb_array_elements(c->'advisors') a))), v_q) > 0), '[]'::jsonb),
    'note', 'my_role = 내 역할(advisor 지도교사 · manager 담당자). 명단은 get_club. 쓰기는 지도교사·담당자만, 모두 check_only 로 먼저 미리 본다.');
