CREATE OR REPLACE FUNCTION "public"."mcp_code_file_targets"("p_project_id" "uuid", "p_paths" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('code.share');
  v_files jsonb;
  v_text  text[];
begin
  if p_project_id is null or not public.can_view_code_project(p_project_id) then
    raise exception using errcode = 'P0002', message = '프로젝트를 찾을 수 없습니다(지워졌거나 볼 수 없다).';
  end if;
  if p_paths is not null and cardinality(p_paths) > 20 then raise exception using errcode = '22023', message = 'paths 는 20개까지입니다.'; end if;
  -- code_project_file SELECT 정책(can_view)과 같은 판정 — 링크 공개 프로젝트도 id 로 열린다
  select coalesce(jsonb_agg(jsonb_build_object('path', f.path, 'storage_path', f.storage_path, 'size', f.size_bytes) order by f.path), '[]'::jsonb)
    into v_files
  from (select * from code_project_file f
         where f.project_id = p_project_id and f.is_binary and f.storage_path like p_project_id || '/%'
           and (p_paths is null or f.path = any(p_paths))
         order by f.path limit 20) f;
  if p_paths is not null then
    select array_agg(p) into v_text from unnest(p_paths) p
     where not exists (select 1 from code_project_file f where f.project_id = p_project_id and f.path = p and f.is_binary);
  end if;
  perform mcp_private.log_call(v_me, 'get_code_files', jsonb_build_object('project_id', p_project_id, 'files', jsonb_array_length(v_files)));
  return jsonb_strip_nulls(jsonb_build_object('files', v_files,
    'not_binary', case when cardinality(v_text) > 0 then to_jsonb(v_text) end,
    'note', case when cardinality(v_text) > 0 then '이진 파일이 아니거나 없는 경로다 — 텍스트 파일 내용은 get_code_project 로 읽는다.' end));
end;
$$;


ALTER FUNCTION "public"."mcp_code_file_targets"("p_project_id" "uuid", "p_paths" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_code_file_upload_begin"("p_project_id" "uuid", "p_paths" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('code.share');
  v_files jsonb;
  v_orph  jsonb;
  v_bad   text;
begin
  if p_project_id is null or not public.can_edit_code_project(p_project_id) then
    raise exception using errcode = '42501', message = '내 프로젝트에만 올릴 수 있습니다(새 프로젝트는 create_code_project 로 텍스트 파일 하나부터 만든다).';
  end if;
  if coalesce(cardinality(p_paths), 0) = 0 or cardinality(p_paths) > 20 then
    raise exception using errcode = '22023', message = 'paths 는 1~20개입니다(한 번에 20개까지 — 더 있으면 나눠 올린다).';
  end if;
  select p into v_bad from unnest(p_paths) p where not mcp_private.code_path_ok(p) limit 1;
  if found then
    raise exception using errcode = '22023', message = format('저장할 수 없는 경로입니다: %s (상대 경로 · 점으로 시작하는 폴더·node_modules·잠금 파일 제외)', v_bad);
  end if;
  select jsonb_agg(jsonb_build_object('path', p, 'storage_path', p_project_id || '/' || p, 'mime', mcp_private.file_mime(p)) order by p)
    into v_files from (select distinct p from unnest(p_paths) p) s;
  perform set_config('mcp.read_storage', 'on', true);
  select coalesce(jsonb_agg(o.name), '[]'::jsonb) into v_orph
    from (select o.name from storage.objects o
           where o.bucket_id = 'code-projects' and o.name like p_project_id || '/%' and o.created_at < now() - interval '1 day'
             and not exists (select 1 from code_project_file f where f.project_id = p_project_id and f.storage_path = o.name)
           limit 50) o;
  perform set_config('mcp.read_storage', '', true);
  perform mcp_private.log_call(v_me, 'start_code_file_upload', jsonb_build_object('project_id', p_project_id, 'files', jsonb_array_length(v_files)));
  return jsonb_build_object('project_id', p_project_id, 'files', v_files, 'orphans', v_orph);
end;
$$;


ALTER FUNCTION "public"."mcp_code_file_upload_begin"("p_project_id" "uuid", "p_paths" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_code_orphan_objects"("p_project_id" "uuid", "p_paths" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('code.share');
  v_rows jsonb;
begin
  if p_project_id is null or not public.can_edit_code_project(p_project_id) then
    raise exception using errcode = '42501', message = '내 프로젝트만 정리할 수 있습니다.';
  end if;
  perform set_config('mcp.read_storage', 'on', true);
  select coalesce(jsonb_agg(o.name), '[]'::jsonb) into v_rows
    from (select o.name from storage.objects o
           where o.bucket_id = 'code-projects' and o.name like p_project_id || '/%'
             and (o.name = any(coalesce(p_paths, '{}')) or o.created_at < now() - interval '1 day')
             and not exists (select 1 from code_project_file f where f.project_id = p_project_id and f.storage_path = o.name)
           limit 300) o;
  perform set_config('mcp.read_storage', '', true);
  return jsonb_build_object('objects', v_rows);
end;
$$;


ALTER FUNCTION "public"."mcp_code_orphan_objects"("p_project_id" "uuid", "p_paths" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_confirm_budget_revision"("p_revision_id" "uuid", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('budget.manage');
  v_rev budget_revision;
  v_check jsonb;
  v_result jsonb;
begin
  select * into v_rev from budget_revision where id = p_revision_id;
  if v_rev.id is null then
    raise exception using errcode = 'P0002', message = '추경 차수를 찾지 못했습니다 — get_budget 의 draft_revision_id.';
  end if;
  perform mcp_private.bg_require_edit(v_rev.project_id);
  if v_rev.status <> 'draft' then
    raise exception using errcode = '22023', message = '이미 확정된 차수입니다.';
  end if;
  v_check := mcp_private.bg_check(v_rev.project_id, (select coalesce(jsonb_object_agg(line_id::text, amount), '{}'::jsonb)
                                                      from budget_revision_line where revision_id = v_rev.id));
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true, 'title', v_rev.title,
      'changes', (select coalesce(jsonb_agg(jsonb_build_object('name', l.name, 'now', l.budget_amount, 'after', rl.amount,
                    'delta', rl.amount - l.budget_amount)), '[]'::jsonb)
                  from budget_revision_line rl join budget_line l on l.id = rl.line_id where rl.revision_id = v_rev.id),
      'check', v_check,
      'note', '확정하면 이 줄들의 예산현액이 바뀌고 차수는 잠겨 되돌릴 수 없다. 에듀파인 추경 입력은 사람이 따로 한다. '
              || '목적사업인데 total_mismatch 가 0 이 아니면 그 점을 분명히 말하고 확인받는다. 확인받은 뒤 check_only:false.');
  end if;
  v_result := public.budget_confirm_revision(p_revision_id);
  perform mcp_private.log_call(v_me, 'confirm_budget_revision', jsonb_build_object('revision_id', p_revision_id));
  return v_result || jsonb_build_object('confirmed', true, 'figures', mcp_private.bg_totals(v_rev.project_id));
end;
$$;


ALTER FUNCTION "public"."mcp_confirm_budget_revision"("p_revision_id" "uuid", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_connect_nodes"("p_workflow_id" "uuid", "p_from" "uuid", "p_to" "uuid", "p_relation" "text" DEFAULT 'flow'::"text", "p_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('workflow.manage');
  f public.task_workflow := mcp_private.wf_editable(p_workflow_id);
  v_s uuid := mcp_private.wf_node(p_workflow_id, p_from); v_t uuid := mcp_private.wf_node(p_workflow_id, p_to);
  v_rel text := coalesce(nullif(p_relation, ''), 'flow'); v_n int;
begin
  if v_rel not in ('flow', 'depends_on', 'handoff', 'related', 'contains', 'action') then
    raise exception using errcode = '22023', message = 'relation 은 flow(다음 순서)·depends_on(선행 필요)·handoff(인계)·related(관련)·contains(포함)·action(작업) 입니다.';
  end if;
  if v_s = v_t then raise exception using errcode = '22023', message = '같은 노드끼리는 잇지 않습니다.'; end if;
  insert into task_workflow_edge (workflow_id, source_node_id, target_node_id, relation_type, label)
  values (p_workflow_id, v_s, v_t, v_rel, nullif(left(btrim(coalesce(p_label, '')), 120), ''))
  on conflict do nothing;
  get diagnostics v_n = row_count;
  update task_workflow set updated_at = now() where id = p_workflow_id;
  perform mcp_private.log_call(v_me, 'connect_nodes', jsonb_build_object('workflow_id', p_workflow_id, 'relation', v_rel));
  return jsonb_build_object('connected', v_n = 1, 'note', case when v_n = 0 then '이미 같은 연결이 있다.' end, 'workflow', mcp_private.wf_out(p_workflow_id));
end $$;


ALTER FUNCTION "public"."mcp_connect_nodes"("p_workflow_id" "uuid", "p_from" "uuid", "p_to" "uuid", "p_relation" "text", "p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_code_project"("p_title" "text", "p_files" "jsonb", "p_kind" "text", "p_entry_path" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT 'private'::"text", "p_tags" "text"[] DEFAULT NULL::"text"[], "p_origin_tool" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('code.share');
  v_title text := mcp_private.opt_text(p_title, 'title', 120);
  v_vis   text := coalesce(nullif(btrim(p_visibility), ''), 'private');
  v_id    uuid := gen_random_uuid();
  v_res   jsonb;
  v_p     public.code_project;
begin
  if v_title is null then raise exception using errcode = '22023', message = '제목(title)이 필요합니다.'; end if;
  if v_vis not in ('school', 'link', 'private') then raise exception using errcode = '22023', message = 'visibility 는 school · link · private 중 하나입니다.'; end if;
  if coalesce(p_kind, '') not in ('html', 'static', 'node', 'skill', 'other') then raise exception using errcode = '22023', message = 'kind 가 올바르지 않습니다.'; end if;
  if jsonb_array_length(coalesce(p_files, '[]'::jsonb)) = 0 then raise exception using errcode = '22023', message = '파일이 하나는 있어야 합니다.'; end if;
  if coalesce(cardinality(p_tags), 0) > 10 then raise exception using errcode = '22023', message = '태그는 10개까지입니다.'; end if;

  insert into code_project (id, owner_resource_id, created_by, title, description, visibility, kind, entry_path, origin_tool, tags)
  values (v_id, v_me, auth.uid(), v_title, mcp_private.opt_text(p_description, 'description', 2000), v_vis, p_kind,
          nullif(btrim(coalesce(p_entry_path, '')), ''), mcp_private.opt_text(p_origin_tool, 'origin_tool', 40),
          coalesce((select array_agg(distinct btrim(t)) from unnest(p_tags) t where btrim(t) <> ''), '{}'));
  v_res := mcp_private.code_apply_files(v_id, p_files, null);
  select * into v_p from code_project where id = v_id;
  perform mcp_private.log_call(v_me, 'create_code_project', jsonb_build_object('visibility', v_vis, 'files', v_res->'file_count'));
  return jsonb_build_object('created', true, 'project', mcp_private.code_out(v_p), 'files', v_res,
    'web_path', '/code-share/' || v_id);
end;
$$;


ALTER FUNCTION "public"."mcp_create_code_project"("p_title" "text", "p_files" "jsonb", "p_kind" "text", "p_entry_path" "text", "p_description" "text", "p_visibility" "text", "p_tags" "text"[], "p_origin_tool" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_document_folder"("p_path" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me   uuid := mcp_private.require_tool('document.library');
  v_path text := mcp_private.doc_folder(p_path);
begin
  if v_path is null then raise exception using errcode = '22023', message = 'path 가 필요합니다.'; end if;
  if exists (select 1 from document_folders where path = v_path) then
    return jsonb_build_object('folder', v_path, 'created', false, 'note', '이미 있는 폴더다.');
  end if;
  insert into document_folders (path, created_by) values (v_path, auth.uid());
  return jsonb_build_object('folder', v_path, 'created', true);
end;
$$;


ALTER FUNCTION "public"."mcp_create_document_folder"("p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_gajeong_issue"("p_title" "text", "p_issued_on" "date" DEFAULT NULL::"date", "p_department" "text" DEFAULT NULL::"text", "p_remarks" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('issue.register');
  v_title text := btrim(coalesce(p_title, ''));
  v_id    uuid;
  v_no    text;
begin
  perform mcp_private.iss_require_issuer();
  if v_title = '' or length(v_title) > 200 then
    raise exception using errcode = '22023', message = 'title(가정통신문 제목, 200자까지)이 필요합니다.';
  end if;

  v_id := public.create_document_issue(
    'gajeong', v_title, coalesce(p_issued_on, mcp_private.iss_today()), nullif(btrim(p_department), ''),
    '[]'::jsonb, null, null, null, nullif(btrim(p_remarks), ''),
    jsonb_build_object('via', mcp_private.iss_via()));
  select issue_no into v_no from document_issue where id = v_id;

  perform mcp_private.log_call(v_me, 'create_gajeong_issue', jsonb_build_object('issue_id', v_id, 'issue_no', v_no));
  return jsonb_build_object('issue_id', v_id, 'issue_no', v_no, 'title', v_title,
    'issued_on', coalesce(p_issued_on, mcp_private.iss_today()),
    'note', format('가정통신문 발급번호 %s 을(를) 받았다. 문서에 이 번호를 적는다.', v_no));
end;
$$;


ALTER FUNCTION "public"."mcp_create_gajeong_issue"("p_title" "text", "p_issued_on" "date", "p_department" "text", "p_remarks" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_meal_duty_schedules"("p_days" "jsonb", "p_start_time" time without time zone DEFAULT '11:50:00'::time without time zone, "p_end_time" time without time zone DEFAULT '12:20:00'::time without time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me     uuid := mcp_private.require_tool('mealduty.plan');
  v_today  date := (now() at time zone 'Asia/Seoul')::date;
  v_e      jsonb;
  v_date   date;
  v_seen   date[] := '{}';
  v_names  text[];
  v_people jsonb;
  v_row    public.meeting;
  v_made   jsonb := '[]'::jsonb;
  v_notified integer := 0;
begin
  if jsonb_typeof(coalesce(p_days, 'null')) <> 'array' or jsonb_array_length(p_days) = 0 then
    raise exception using errcode = '22023', message = 'days 는 [{date, names}] 배열입니다(draft_meal_duty 의 days 에서).';
  end if;
  if jsonb_array_length(p_days) > 31 then raise exception using errcode = '22023', message = '한 번에 31일까지 만든다.'; end if;
  if p_start_time is null or p_end_time is null or p_end_time <= p_start_time then
    raise exception using errcode = '22023', message = '시각을 확인하세요(시작 < 끝).';
  end if;

  for v_e in select * from jsonb_array_elements(p_days) loop
    begin v_date := (v_e->>'date')::date;
    exception when others then raise exception using errcode = '22023', message = format('날짜 형식이 아닙니다: %s', v_e->>'date'); end;
    if v_date is null or v_date < v_today or v_date > v_today + 200 then
      raise exception using errcode = '22023', message = format('오늘 이후 날짜만 만든다: %s', v_e->>'date');
    end if;
    if extract(isodow from v_date) > 5 then raise exception using errcode = '22023', message = format('주말입니다: %s', v_date); end if;
    if v_date = any(v_seen) then raise exception using errcode = '22023', message = format('같은 날짜가 두 번 있습니다: %s', v_date); end if;
    v_seen := v_seen || v_date;
    if exists (select 1 from public.get_meal_duty_history(v_date, v_date)) then
      raise exception using errcode = '22023', message = format('%s 에는 급식지도 일정이 이미 있습니다 — 스케줄에서 고치세요.', v_date);
    end if;
    if jsonb_typeof(v_e->'names') <> 'array' then raise exception using errcode = '22023', message = format('%s 의 names 는 이름 배열입니다.', v_date); end if;
    select coalesce(array_agg(distinct x), '{}') into v_names
    from jsonb_array_elements_text(v_e->'names') x where nullif(btrim(x), '') is not null;
    if cardinality(v_names) = 0 or cardinality(v_names) > 4 then
      raise exception using errcode = '22023', message = format('%s 는 1~4명이어야 합니다(빈칸인 날은 빼고 보낸다).', v_date);
    end if;
    -- 웹 제목과 같은 순서(보낸 순서) — 사람은 재직 교직원 정확히 한 명씩
    select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'type', p.type)), '[]'::jsonb) into v_people from mcp_private.sch_people(v_names) p;
    -- 꼬리(«선생님»)는 sch_people 과 같은 규칙으로 뗀다 — 제목은 명단 이름 그대로
    select array_agg(x order by o) into v_names from (
      select distinct on (c) c as x, o
      from jsonb_array_elements_text(v_e->'names') with ordinality t(raw, o)
      cross join lateral (select btrim(regexp_replace(btrim(raw), '\s*(선생님|선생|쌤|님)$', '')) as c) cc
      where c <> '' order by c, o) s;

    v_row := mcp_private.meeting_insert('duty', '급식지도 - ' || array_to_string(v_names, ', '),
               (v_date + p_start_time) at time zone 'Asia/Seoul', (v_date + p_end_time) at time zone 'Asia/Seoul', false,
               '급식지도', v_people, '{}'::jsonb, v_me);
    v_made := v_made || jsonb_build_object('date', v_date, 'schedule_id', v_row.id, 'names', to_jsonb(v_names));
    select v_notified + count(*) into v_notified from jsonb_array_elements(v_people) e where e->>'type' = 'teacher';
  end loop;

  perform mcp_private.log_call(v_me, 'create_meal_duty_schedules', jsonb_build_object('days', jsonb_array_length(v_made)));
  return jsonb_build_object('made', jsonb_array_length(v_made), 'days', v_made, 'notified', v_notified,
    'time', format('%s~%s', to_char(p_start_time, 'HH24:MI'), to_char(p_end_time, 'HH24:MI')),
    'note', '급식지도 업무 일정을 만들었다 — 교사 담당자에게 알림이 갔다. 날짜별로 다시 고치는 것은 스케줄에서(update_schedule 은 내가 만든 일정만).');
end;
$_$;


ALTER FUNCTION "public"."mcp_create_meal_duty_schedules"("p_days" "jsonb", "p_start_time" time without time zone, "p_end_time" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_notice"("p_title" "text", "p_content" "text", "p_department" "text", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_targets" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me      uuid := mcp_private.require_tool('notice.board');
  v_title   text := mcp_private.opt_text(p_title, 'title', 200);
  v_content text := mcp_private.opt_text(p_content, 'content', 20000);
  v_start   date := coalesce(p_start_date, mcp_private.kst_today());
  v_end     date := coalesce(p_end_date, coalesce(p_start_date, mcp_private.kst_today()) + 7);
  v_targets uuid[] := mcp_private.notice_targets(p_targets);
  v_id      uuid;
  v_n       public.department_notice;
begin
  if v_title is null then raise exception using errcode = '22023', message = '제목(title)이 필요합니다.'; end if;
  if v_content is null then raise exception using errcode = '22023', message = '내용(content)이 필요합니다.'; end if;
  if v_end < v_start then raise exception using errcode = '22023', message = '게시 끝 날짜가 시작 날짜보다 앞입니다.'; end if;

  v_id := gen_random_uuid();
  insert into department_notice (id, department, title, content, start_date, end_date, created_by, author_name, target_resource_ids)
  values (v_id, mcp_private.notice_department(p_department), v_title, v_content, v_start, v_end, auth.uid(),
          (select pr.name from profiles pr where pr.id = auth.uid()), v_targets);
  select * into v_n from department_notice where id = v_id;
  perform mcp_private.log_call(v_me, 'create_notice', jsonb_build_object('department', v_n.department, 'targets', coalesce(cardinality(v_targets), 0)));
  return jsonb_build_object('created', true, 'notice', mcp_private.notice_out(v_n, true),
    'note', '공지는 알림을 보내지 않는다(웹과 같다) — 대시보드·공지사항에서 보인다. 첨부 파일은 웹에서 붙인다.');
end;
$$;


ALTER FUNCTION "public"."mcp_create_notice"("p_title" "text", "p_content" "text", "p_department" "text", "p_start_date" "date", "p_end_date" "date", "p_targets" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_personal_schedule"("p_title" "text", "p_date" "date", "p_start_time" time without time zone DEFAULT NULL::time without time zone, "p_end_time" time without time zone DEFAULT NULL::time without time zone, "p_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('schedule.mine');
  v_name   text;
  v_title  text := btrim(coalesce(p_title, ''));
  v_desc   text := nullif(btrim(coalesce(p_description, '')), '');
  v_today  date := (now() at time zone 'Asia/Seoul')::date;
  v_allday boolean := p_start_time is null and p_end_time is null;
  v_start  timestamptz;
  v_end    timestamptz;
  v_id     uuid;
begin
  if v_title = '' or char_length(v_title) > 200 then
    raise exception using errcode = '22023', message = '제목은 1~200자로 적어 주세요.';
  end if;
  if v_desc is not null and char_length(v_desc) > 2000 then
    raise exception using errcode = '22023', message = '설명은 2000자까지입니다.';
  end if;
  if p_date is null or p_date < v_today - 366 or p_date > v_today + 731 then
    raise exception using errcode = '22023', message = '날짜는 지난 1년 ~ 앞으로 2년 안이어야 합니다.';
  end if;
  if p_start_time is null and p_end_time is not null then
    raise exception using errcode = '22023', message = '끝 시각만 적을 수는 없습니다. 시작 시각도 적어 주세요.';
  end if;

  if v_allday then
    v_start := p_date::timestamp at time zone 'Asia/Seoul';
    v_end   := (p_date + time '23:59:59') at time zone 'Asia/Seoul';
  else
    v_start := (p_date + p_start_time) at time zone 'Asia/Seoul';
    -- 끝 시각이 없으면 1시간 — time + interval 은 자정을 넘으면 되돌아가므로(23:30 + 1h = 00:30) 23시 이후는 그날 끝까지.
    v_end   := (p_date + coalesce(p_end_time,
                 case when p_start_time >= time '23:00' then time '23:59:59'
                      else p_start_time + interval '1 hour' end))
               at time zone 'Asia/Seoul';
    if v_end < v_start then
      raise exception using errcode = '22023', message = '끝 시각이 시작 시각보다 앞입니다.';
    end if;
  end if;

  select r.name into v_name from public.resource r where r.id = v_me;

  insert into public.meeting (kind, starts_at, ends_at, status, meta, created_by, creator)
  values (
    'personal', v_start, v_end, 'scheduled',
    jsonb_strip_nulls(jsonb_build_object(
      'title', v_title,
      'source', 'custom',
      'description', v_desc,
      'assignee', jsonb_build_object(v_name, jsonb_build_object('name', v_name)),
      'exchangeable', false,
      'date_only', v_allday,
      'via', jsonb_build_object(
        'channel', 'mcp',
        'client_id', nullif(auth.jwt()->>'client_id', ''),
        'at', now()
      )
    )),
    v_me, v_me
  )
  returning id into v_id;

  return jsonb_build_object(
    'id', v_id,
    'kind', 'personal',
    'title', v_title,
    'date', p_date,
    'all_day', v_allday,
    'starts_at', to_char(v_start at time zone 'Asia/Seoul', 'YYYY-MM-DD"T"HH24:MI'),
    'ends_at', to_char(v_end at time zone 'Asia/Seoul', 'YYYY-MM-DD"T"HH24:MI')
  );
end;
$$;


ALTER FUNCTION "public"."mcp_create_personal_schedule"("p_title" "text", "p_date" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_purchase_order_batch"("p_page_id" "uuid", "p_title" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('purchase.request');
  v_page  public.purchase_request_pages%rowtype;
  v_title text := mcp_private.pr_short_text(p_title, 'title', 200);
  v_cnt   integer;
  v_max   integer;
  v_cols  jsonb;
  v_id    uuid;
begin
  if p_page_id is null then
    raise exception using errcode = '22023', message = 'page_id 가 필요합니다 (list_purchase_pages 의 page_id).';
  end if;
  select * into v_page from purchase_request_pages where id = p_page_id;
  if v_page.id is null then
    raise exception using errcode = 'P0002', message = '구매 신청 페이지를 찾을 수 없습니다.';
  end if;
  perform mcp_private.pr_require_manager(v_page.id);

  select count(*), coalesce(max(((regexp_match(title, '^\s*(\d+)\s*차'))[1])::integer), 0)
    into v_cnt, v_max from purchase_order_batches where page_id = v_page.id;
  if v_cnt >= 50 then
    raise exception using errcode = '22023', message = '한 페이지의 품의 차수는 50개까지입니다.';
  end if;
  if v_title is null or v_title = '' then
    v_title := (greatest(v_max, v_cnt) + 1)::text || '차 품의';
  end if;
  select columns into v_cols from purchase_order_batches where page_id = v_page.id order by sort_order desc, created_at desc limit 1;

  insert into purchase_order_batches (page_id, title, sort_order, created_by, columns)
  values (v_page.id, v_title, v_cnt, v_me, coalesce(v_cols, '[]'::jsonb))
  returning id into v_id;

  perform mcp_private.log_call(v_me, 'create_purchase_order_batch', jsonb_build_object('page_id', v_page.id, 'batch_id', v_id));
  return jsonb_build_object('created', true, 'batch_id', v_id, 'title', v_title, 'status', 'draft', 'status_label', mcp_private.pr_batch_label('draft'),
    'note', '새 차수(작성 중). 품의 품목은 save_purchase_order_line 으로 넣는다.');
end;
$$;


ALTER FUNCTION "public"."mcp_create_purchase_order_batch"("p_page_id" "uuid", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_purchase_page"("p_title" "text", "p_target_roles" "text"[], "p_period_end" timestamp with time zone, "p_period_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_description" "text" DEFAULT NULL::"text", "p_columns" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me      uuid := mcp_private.require_tool('purchase.page');
  v_title   text := btrim(coalesce(p_title, ''));
  v_desc    text := nullif(btrim(coalesce(p_description, '')), '');
  v_start   timestamptz := coalesce(p_period_start, now());
  v_roles   text[];
  v_cols    jsonb := '[]'::jsonb;
  v_el      jsonb;
  v_i       integer;
  v_kind    text;
  v_name    text;
  v_type    text;
  v_id      uuid;
begin
  if v_title = '' or length(v_title) > 200 then
    raise exception using errcode = '22023', message = 'title 은 1~200자입니다.';
  end if;
  if v_desc is not null and length(v_desc) > 4000 then
    raise exception using errcode = '22023', message = 'description 은 4000자까지입니다.';
  end if;
  select array_agg(distinct r order by r) into v_roles from unnest(coalesce(p_target_roles, '{}')) r;
  if v_roles is null or not (v_roles <@ array['student', 'teacher']) then
    raise exception using errcode = '22023', message = 'target_roles 는 teacher(교직원) · student(학생) 중 1개 이상입니다.';
  end if;
  if p_period_end is null then
    raise exception using errcode = '22023', message = 'period_end(신청 마감)가 필요합니다.';
  end if;
  if p_period_end <= now() then
    raise exception using errcode = '22023', message = '신청 마감이 이미 지난 시각입니다.';
  end if;
  if p_period_end <= v_start then
    raise exception using errcode = '22023', message = '신청 마감이 시작보다 뒤여야 합니다.';
  end if;
  if p_period_end - v_start > interval '366 days' then
    raise exception using errcode = '22023', message = '신청 기간은 1년까지입니다.';
  end if;

  if p_columns is null or jsonb_typeof(p_columns) = 'null' then
    v_cols := '[
      {"id":"default-name","name":"물품명","type":"text","required":true,"isDefault":true},
      {"id":"default-option","name":"상세 옵션","type":"text","required":false,"isDefault":true},
      {"id":"default-url","name":"구매 가능한 주소","type":"url","required":true,"isDefault":true},
      {"id":"default-price","name":"개별 가격","type":"number","required":true,"isDefault":true},
      {"id":"default-qty","name":"개수","type":"number","required":true,"isDefault":true},
      {"id":"default-note","name":"비고(필요한 이유)","type":"text","required":false,"isDefault":true}
    ]'::jsonb;
  else
    if jsonb_typeof(p_columns) <> 'array' or jsonb_array_length(p_columns) = 0 or jsonb_array_length(p_columns) > 20 then
      raise exception using errcode = '22023', message = 'columns 는 칸 1~20개의 배열입니다 (비우면 기본 6칸).';
    end if;
    for v_el, v_i in select e, o::integer from jsonb_array_elements(p_columns) with ordinality t(e, o) loop
      if jsonb_typeof(v_el) <> 'object' then
        raise exception using errcode = '22023', message = format('%s번째 칸이 객체가 아닙니다.', v_i);
      end if;
      v_name := btrim(coalesce(v_el->>'name', ''));
      v_kind := nullif(btrim(coalesce(v_el->>'kind', '')), '');
      v_type := coalesce(nullif(v_el->>'type', ''), 'text');
      if v_name = '' or length(v_name) > 100 then
        raise exception using errcode = '22023', message = format('%s번째 칸의 name 은 1~100자입니다.', v_i);
      end if;
      if v_type not in ('text', 'number', 'url') then
        raise exception using errcode = '22023', message = format('%s번째 칸의 type 은 text · number · url 중 하나입니다.', v_i);
      end if;
      if v_kind is not null and v_kind not in ('name', 'option', 'url', 'price', 'qty', 'note') then
        raise exception using errcode = '22023',
          message = format('%s번째 칸의 kind 는 name · option · url · price · qty · note 중 하나입니다.', v_i);
      end if;
      if v_kind in ('price', 'qty') then v_type := 'number'; end if;
      if v_kind = 'url' then v_type := 'url'; end if;
      if exists (select 1 from jsonb_array_elements(v_cols) c where c->>'name' = v_name) then
        raise exception using errcode = '22023', message = format('칸 이름이 겹칩니다 — «%s».', v_name);
      end if;
      if v_kind is not null and exists (select 1 from jsonb_array_elements(v_cols) c where c->>'id' = 'default-' || v_kind) then
        raise exception using errcode = '22023', message = format('kind «%s» 는 한 칸에만 줄 수 있습니다.', v_kind);
      end if;
      if v_el ? 'required' and jsonb_typeof(v_el->'required') <> 'boolean' then
        raise exception using errcode = '22023', message = format('%s번째 칸의 required 는 true · false 입니다.', v_i);
      end if;
      v_cols := v_cols || jsonb_build_array(jsonb_build_object(
        'id', case when v_kind is not null then 'default-' || v_kind
                   else 'custom-' || (floor(extract(epoch from clock_timestamp()) * 1000))::bigint::text || '-'
                        || substr(md5(random()::text || v_i::text), 1, 12) end,
        'name', v_name, 'type', v_type,
        'required', coalesce((v_el->>'required')::boolean, false),
        'isDefault', v_kind is not null));
    end loop;
  end if;

  insert into purchase_request_pages (title, target_roles, description, period_start, period_end, columns, created_by)
  values (v_title, v_roles, v_desc, v_start, p_period_end, v_cols, v_me)
  returning id into v_id;

  perform mcp_private.log_call(v_me, 'create_purchase_page', jsonb_build_object('page_id', v_id, 'title', v_title));

  return jsonb_strip_nulls(jsonb_build_object(
    'page_id', v_id, 'title', v_title,
    'target', (select string_agg(case r when 'teacher' then '교직원' else '학생' end, '·') from unnest(v_roles) r),
    'period_start', mcp_private.pr_kst(v_start), 'period_end', mcp_private.pr_kst(p_period_end),
    'columns', mcp_private.pr_columns_out(v_cols),
    'note', '만들었다(알림은 가지 않는다 — 대상자에게 알리려면 공지 등으로). 공동 작업자 추가·수정·보관은 웹 구매 신청에서.'
  ));
end;
$$;


ALTER FUNCTION "public"."mcp_create_purchase_page"("p_title" "text", "p_target_roles" "text"[], "p_period_end" timestamp with time zone, "p_period_start" timestamp with time zone, "p_description" "text", "p_columns" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_schedule"("p_kind" "text", "p_title" "text", "p_date" "date", "p_start_time" time without time zone DEFAULT NULL::time without time zone, "p_end_time" time without time zone DEFAULT NULL::time without time zone, "p_end_date" "date" DEFAULT NULL::"date", "p_description" "text" DEFAULT NULL::"text", "p_attendees" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('schedule.manage');
  v_kind   text := btrim(coalesce(p_kind, ''));
  v_title  text := btrim(coalesce(p_title, ''));
  v_desc   text := nullif(btrim(coalesce(p_description, '')), '');
  v_win    record;
  v_people jsonb;
  v_assign jsonb;
  v_row    public.meeting;
  v_notified integer := 0;
begin
  if v_kind not in ('schedule', 'event', 'duty', 'training') then
    raise exception using errcode = '22023',
      message = 'kind 는 schedule(학사일정) · event(출장) · duty(업무) · training(연수) 중 하나입니다. 개인일정은 create_personal_schedule.';
  end if;
  if v_title = '' or char_length(v_title) > 200 then
    raise exception using errcode = '22023', message = '제목은 1~200자로 적어 주세요.';
  end if;
  if v_desc is not null and char_length(v_desc) > 4000 then
    raise exception using errcode = '22023', message = '설명은 4000자까지입니다.';
  end if;
  select * into v_win from mcp_private.sch_window(p_date, p_end_date, p_start_time, p_end_time);

  select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'type', p.type)), '[]'::jsonb) into v_people
  from mcp_private.sch_people(p_attendees) p;
  if v_kind in ('duty', 'training') and jsonb_array_length(v_people) = 0 then
    raise exception using errcode = '22023',
      message = format('%s 일정은 참석자(담당자)가 1명 이상이어야 합니다 — 참석자에게만 보이기 때문이다.', mcp_private.sch_kind_label(v_kind));
  end if;

  select coalesce(jsonb_object_agg(e->>'name',
           case when v_kind = 'training' then jsonb_build_object('name', e->>'name', 'signature', 0)
                else jsonb_build_object('name', e->>'name') end), '{}'::jsonb)
    into v_assign
  from jsonb_array_elements(v_people) e;

  insert into public.meeting (kind, starts_at, ends_at, status, meta, created_by, creator)
  values (
    v_kind, v_win.starts_at, v_win.ends_at, 'scheduled',
    jsonb_strip_nulls(jsonb_build_object(
      'title', v_title,
      'source', 'custom',
      'description', v_desc,
      'assignee', case when jsonb_array_length(v_people) > 0 then v_assign end,
      'exchangeable', false,
      'date_only', v_win.all_day,
      'via', jsonb_build_object('channel', 'mcp', 'client_id', nullif(auth.jwt()->>'client_id', ''), 'at', now())
    )),
    v_me, v_me
  )
  returning * into v_row;

  if v_kind in ('duty', 'training') then
    select count(*) into v_notified from jsonb_array_elements(v_people) e where e->>'type' = 'teacher';
  end if;

  perform mcp_private.log_call(v_me, 'create_schedule',
    jsonb_build_object('id', v_row.id, 'kind', v_kind, 'attendees', jsonb_array_length(v_people), 'notified', v_notified));

  return mcp_private.sch_out(v_row, v_me) || jsonb_build_object(
    'notified', v_notified,
    'note', case v_kind
      when 'training' then '연수 일정을 만들었다. 교사 참석자에게 알림이 갔다(직원은 알림 없음 — 알림을 누르면 자기 서명 QR). 참석자마다 로그인 없이 서명하는 링크가 생겼다 — 주소는 get_training_sign_links, 기한(기본 연수 끝 + 7일)은 set_training_sign_link_expiry.'
      when 'duty' then '업무 일정을 만들었다. 교사 담당자에게 알림이 갔다(직원은 알림 없음). 담당자와 나에게만 보인다.'
      when 'event' then '출장 일정을 만들었다(모든 교직원에게 보인다, 알림 없음). 그 시간 수업이 있으면 웹 일정 상세의 «수업 처리»로 교체·대체를 처리한다.'
      else '학사일정을 만들었다 — 모든 교직원·학생 달력에 보인다(알림 없음).' end
  );
end;
$$;


ALTER FUNCTION "public"."mcp_create_schedule"("p_kind" "text", "p_title" "text", "p_date" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_end_date" "date", "p_description" "text", "p_attendees" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_schedule_from_survey"("p_survey_id" "uuid", "p_date" "date", "p_title" "text", "p_kind" "text" DEFAULT 'duty'::"text", "p_start_time" time without time zone DEFAULT NULL::time without time zone, "p_end_time" time without time zone DEFAULT NULL::time without time zone, "p_attendees" "text"[] DEFAULT NULL::"text"[], "p_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('schedule.survey');
  v_s      public.schedule_survey;
  v_kind   text := btrim(coalesce(p_kind, 'duty'));
  v_title  text := btrim(coalesce(p_title, ''));
  v_desc   text := nullif(btrim(coalesce(p_description, '')), '');
  v_win    record;
  v_names  text[];
  v_people jsonb;
  v_skip   integer := 0;
  v_row    public.meeting;
  v_notified integer := 0;
begin
  select * into v_s from schedule_survey where id = p_survey_id;
  if not found or not coalesce(public.can_manage_schedule_survey(v_s.id), false) then
    raise exception using errcode = 'P0002', message = '내가 만든 설문을 찾을 수 없습니다.';
  end if;
  if v_kind not in ('duty', 'training', 'event', 'schedule') then
    raise exception using errcode = '22023', message = 'kind 는 duty(업무) · training(연수) · event(출장) · schedule(학사일정) 중 하나입니다.';
  end if;
  if v_title = '' or char_length(v_title) > 200 then raise exception using errcode = '22023', message = '제목은 1~200자입니다.'; end if;
  if char_length(coalesce(v_desc, '')) > 4000 then raise exception using errcode = '22023', message = '설명은 4000자까지입니다.'; end if;
  select * into v_win from mcp_private.sch_window(p_date, null, p_start_time, p_end_time);

  if p_attendees is null then
    -- 그날 가능하다고 답한 사람 중 교직원(학생은 일정 참석자로 넣지 않는다 — 웹과 같다)
    select coalesce(array_agg(r.name order by r.name) filter (where r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active'), '{}'),
           count(*) filter (where r.type = 'student')
      into v_names, v_skip
    from schedule_survey_response x
    join resource r on r.id = x.respondent_resource_id
    where x.survey_id = v_s.id
      and exists (select 1 from jsonb_array_elements(x.items) e where e->>'date' = p_date::text and (e->>'available')::boolean);
  else
    v_names := p_attendees;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'type', p.type)), '[]'::jsonb) into v_people from mcp_private.sch_people(v_names) p;
  if v_kind in ('duty', 'training') and jsonb_array_length(v_people) = 0 then
    raise exception using errcode = '22023', message = '업무·연수 일정은 참석자가 1명 이상이어야 합니다 — 그날 가능하다고 답한 교직원이 없다면 attendees 로 정한다.';
  end if;

  v_row := mcp_private.meeting_insert(v_kind, v_title, v_win.starts_at, v_win.ends_at, v_win.all_day, v_desc,
             case when v_kind in ('duty', 'training', 'event') then v_people else '[]'::jsonb end,
             jsonb_build_object('survey_id', v_s.id), v_me);
  if v_kind in ('duty', 'training') then
    select count(*) into v_notified from jsonb_array_elements(v_people) e where e->>'type' = 'teacher';
  end if;
  perform mcp_private.log_call(v_me, 'create_schedule_from_survey', jsonb_build_object('survey_id', v_s.id, 'meeting_id', v_row.id, 'kind', v_kind));

  return mcp_private.sch_out(v_row, v_me) || jsonb_strip_nulls(jsonb_build_object(
    'survey_id', v_s.id, 'notified', v_notified,
    'skipped_students', case when v_skip > 0 then v_skip end,
    'note', case when v_kind in ('duty', 'training') then '일정을 만들었다 — 교사 참석자에게 알림이 갔다(직원은 알림 없음).'
                 else '일정을 만들었다(알림 없음).' end
            || case when v_skip > 0 then format(' 그날 가능하다고 답한 학생 %s명은 참석자에 넣지 않았다.', v_skip) else '' end));
end;
$$;


ALTER FUNCTION "public"."mcp_create_schedule_from_survey"("p_survey_id" "uuid", "p_date" "date", "p_title" "text", "p_kind" "text", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_attendees" "text"[], "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_schedule_survey"("p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_staff" "text"[] DEFAULT NULL::"text"[], "p_students" "text"[] DEFAULT NULL::"text"[], "p_candidate_dates" "date"[] DEFAULT NULL::"date"[], "p_allow_custom_dates" boolean DEFAULT true, "p_due_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me      uuid := mcp_private.require_tool('schedule.survey');
  v_today   date := (now() at time zone 'Asia/Seoul')::date;
  v_title   text := btrim(coalesce(p_title, ''));
  v_desc    text := nullif(btrim(coalesce(p_description, '')), '');
  v_dates   date[];
  v_staff   uuid[];
  v_stu     uuid[] := '{}';
  v_x       text;
  v_who     record;
  v_id      uuid;
  v_targets uuid[];
  v_row     public.schedule_survey;
  v_name    text := mcp_private.me_name(v_me);
begin
  if v_title = '' or char_length(v_title) > 200 then raise exception using errcode = '22023', message = '제목은 1~200자입니다.'; end if;
  if char_length(coalesce(v_desc, '')) > 4000 then raise exception using errcode = '22023', message = '설명은 4000자까지입니다.'; end if;
  select coalesce(array_agg(distinct d order by d), '{}') into v_dates from unnest(coalesce(p_candidate_dates, '{}')) d;
  if cardinality(v_dates) > 40 then raise exception using errcode = '22023', message = '후보 날짜는 40개까지입니다.'; end if;
  if exists (select 1 from unnest(v_dates) d where d < v_today or d > v_today + 366) then
    raise exception using errcode = '22023', message = '후보 날짜는 오늘부터 1년 안이어야 합니다.';
  end if;
  if not coalesce(p_allow_custom_dates, true) and cardinality(v_dates) = 0 then
    raise exception using errcode = '22023', message = '후보 날짜가 없으면 날짜 제안(allow_custom_dates)을 열어 두어야 응답할 수 있습니다.';
  end if;
  if p_due_date is not null and p_due_date < v_today then raise exception using errcode = '22023', message = '마감일이 지났습니다.'; end if;

  select coalesce(array_agg(p.id), '{}') into v_staff from mcp_private.sch_people(p_staff) p;
  foreach v_x in array coalesce(p_students, '{}') loop
    select * into v_who from mcp_private.parse_student(v_x);
    select r.id into v_id from resource r
    where r.type = 'student' and coalesce(r.status, 'active') = 'active'
      and r.meta->>'grade' = v_who.grade::text and r.meta->>'class' = v_who.class_num::text and r.meta->>'number' = v_who.num::text
    limit 1;
    if v_id is null then raise exception using errcode = '22023', message = format('재학생을 찾지 못했습니다: %s', v_x); end if;
    v_stu := v_stu || v_id;
  end loop;
  select coalesce(array_agg(distinct x), '{}') into v_targets from unnest(v_staff || v_stu) x;
  if cardinality(v_targets) = 0 then raise exception using errcode = '22023', message = '대상자가 1명 이상이어야 합니다(staff · students).'; end if;
  if cardinality(v_targets) > 700 then raise exception using errcode = '22023', message = '대상자는 700명까지입니다.'; end if;

  insert into schedule_survey (title, description, created_by, owner_resource_id, owner_name, target_resource_ids,
                               candidate_dates, allow_custom_dates, due_date)
  values (v_title, v_desc, auth.uid(), v_me, v_name, v_targets, v_dates, coalesce(p_allow_custom_dates, true), p_due_date)
  returning * into v_row;

  -- RETURNING 금지 — 받는 사람만 읽는다
  insert into notification_events (type, title, message, resource_id, is_read, meta)
  select 'schedule_survey_requested', '일정 설문 요청', format('%s님이 "%s" 설문에 응답을 요청했습니다.', v_name, v_title),
         t, false, jsonb_build_object('survey_id', v_row.id, 'survey_title', v_title)
  from unnest(v_targets) t;

  perform mcp_private.log_call(v_me, 'create_schedule_survey',
    jsonb_build_object('survey_id', v_row.id, 'staff', cardinality(v_staff), 'students', cardinality(v_stu)));
  return mcp_private.sv_survey_out(v_row, v_me) || jsonb_build_object('notified', cardinality(v_targets),
    'note', format('설문을 만들고 대상자 %s명에게 알림을 보냈다. 결과는 get_schedule_survey_result, 마감은 set_schedule_survey_status.', cardinality(v_targets)));
end;
$$;


ALTER FUNCTION "public"."mcp_create_schedule_survey"("p_title" "text", "p_description" "text", "p_staff" "text"[], "p_students" "text"[], "p_candidate_dates" "date"[], "p_allow_custom_dates" boolean, "p_due_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_sign_request"("p_run_id" "uuid", "p_title" "text", "p_signers" "jsonb", "p_message" "text" DEFAULT NULL::"text", "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_page_count" integer DEFAULT NULL::integer, "p_check_only" boolean DEFAULT true, "p_notify" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me       uuid := mcp_private.require_tool('sign.request');
  v_prefix   text := auth.uid()::text || '/runs/' || p_run_id::text || '/';
  v_loc      jsonb;
  v_title    text := btrim(coalesce(p_title, ''));
  v_s        jsonb;
  v_f        jsonb;
  v_name     text;
  v_rid      uuid;
  v_n        int;
  v_order    int;
  v_out      jsonb := '[]'::jsonb;
  v_names    text[] := '{}';
  v_id       uuid;
  v_path     text;
begin
  -- 원본 — 내가 실행한 문서 생성의 한글 결과물만
  select a.locator into v_loc
    from task_action_run r
    join task_action_artifact a on a.run_id = r.id and a.artifact_key = 'generated-hwpx'
   where r.id = p_run_id and r.created_by = auth.uid()
   order by a.created_at desc limit 1;
  if v_loc is null then
    raise exception using errcode = 'P0002', message = '그 실행의 한글 결과물을 찾지 못했습니다(create_document 가 돌려준 run_id — 내가 만든 문서만).';
  end if;
  if v_loc->>'bucket' <> 'task-work-documents' or left(v_loc->>'path', length(v_prefix)) <> v_prefix
     or right(lower(v_loc->>'path'), 5) <> '.hwpx' or position('..' in v_loc->>'path') > 0 then
    raise exception using errcode = '42501', message = '내 실행 폴더의 한글 문서만 서명 요청에 쓸 수 있습니다.';
  end if;

  if v_title = '' or length(v_title) > 200 then
    raise exception using errcode = '22023', message = '제목은 1~200자입니다.';
  end if;
  if p_page_count is not null and (p_page_count < 1 or p_page_count > 500) then
    raise exception using errcode = '22023', message = 'page_count 는 1~500 입니다.';
  end if;
  if p_due_at is not null and (p_due_at < now() + interval '1 hour'
                               or p_due_at > now() + make_interval(days => public.signature_due_max_days())) then
    raise exception using errcode = '22023',
      message = format('마감은 지금부터 1시간 뒤 ~ %s일 안으로 정해 주세요.', public.signature_due_max_days());
  end if;

  if p_signers is null or jsonb_typeof(p_signers) <> 'array' or jsonb_array_length(p_signers) = 0 then
    raise exception using errcode = '22023', message = '서명자를 한 명 이상 넣어 주세요.';
  end if;
  if jsonb_array_length(p_signers) > 30 then
    raise exception using errcode = '22023', message = '서명자는 최대 30명입니다.';
  end if;

  for v_s in select * from jsonb_array_elements(p_signers) loop
    v_name := btrim(coalesce(v_s->>'name', ''));
    if v_name = '' then
      raise exception using errcode = '22023', message = '이름이 빈 서명자가 있습니다.';
    end if;
    if v_name = any(v_names) then
      raise exception using errcode = '22023', message = format('%s 님이 두 번 들어 있습니다.', v_name);
    end if;
    v_names := v_names || v_name;

    -- 재직 교직원 이름 — 정확히 한 명일 때만
    select count(*), min(r.id::text)::uuid into v_n, v_rid
      from resource r
     where r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active' and r.name = v_name;
    if v_n = 0 then
      raise exception using errcode = '22023', message = format('교직원 «%s» 이 명단에 없습니다(find_staff 로 정확한 이름을).', v_name);
    elsif v_n > 1 then
      raise exception using errcode = '22023', message = format('«%s» 이름이 %s명입니다 — 웹에서 골라 주세요.', v_name, v_n);
    end if;

    v_order := coalesce((v_s->>'order')::int, 1);
    if v_order < 1 or v_order > 30 then
      raise exception using errcode = '22023', message = format('%s 님의 순서(order)는 1~30 입니다(같은 숫자 = 동시 서명).', v_name);
    end if;

    if jsonb_typeof(v_s->'fields') <> 'array' or jsonb_array_length(v_s->'fields') = 0 then
      raise exception using errcode = '22023',
        message = format('%s 님의 서명란(fields)이 없습니다 — 서명란이 없으면 서명이 문서에 찍히지 않습니다.', v_name);
    end if;
    for v_f in select * from jsonb_array_elements(v_s->'fields') loop
      if v_f->>'kind' = 'hwpx-cell' then
        if btrim(coalesce(v_f->>'label', '')) = '' then
          raise exception using errcode = '22023', message = 'hwpx-cell 서명란에는 label(칸 이름)이 필요합니다.';
        end if;
      elsif v_f->>'kind' = 'page-box' then
        -- 웹 isValidPlacement 와 같은 규칙: 쪽은 0 이상 정수, 0~1 안, 가로·세로 0.01 이상, 쪽 밖으로 넘지 않는다
        if jsonb_typeof(v_f->'page') <> 'number' or jsonb_typeof(v_f->'x') <> 'number' or jsonb_typeof(v_f->'y') <> 'number'
           or jsonb_typeof(v_f->'w') <> 'number' or jsonb_typeof(v_f->'h') <> 'number'
           or (v_f->>'page')::numeric <> trunc((v_f->>'page')::numeric) or (v_f->>'page')::int < 0
           or (v_f->>'x')::numeric < 0 or (v_f->>'y')::numeric < 0
           or (v_f->>'w')::numeric < 0.01 or (v_f->>'h')::numeric < 0.01
           or (v_f->>'x')::numeric + (v_f->>'w')::numeric > 1.0001
           or (v_f->>'y')::numeric + (v_f->>'h')::numeric > 1.0001 then
          raise exception using errcode = '22023',
            message = format('%s 님의 page-box 가 올바르지 않습니다 — page(0부터 정수)·x·y·w·h 는 쪽 대비 0~1, w·h ≥ 0.01, 쪽을 넘지 않게.', v_name);
        end if;
        if p_page_count is not null and (v_f->>'page')::int >= p_page_count then
          raise exception using errcode = '22023', message = format('%s 님의 서명란 쪽(page %s)이 문서 쪽수(%s)를 넘습니다(page 는 0부터).', v_name, v_f->>'page', p_page_count);
        end if;
      else
        raise exception using errcode = '22023', message = '서명란 kind 는 page-box · hwpx-cell 입니다.';
      end if;
    end loop;

    v_out := v_out || jsonb_build_object(
      'order_index', v_order - 1,
      'role_label', nullif(btrim(coalesce(v_s->>'role', '')), ''),
      'signer_resource_id', v_rid,
      'signer_name', v_name,
      'fields', (select jsonb_agg(case when f->>'kind' = 'page-box'
                    then jsonb_build_object('kind', 'page-box', 'page', (f->>'page')::int,
                           'x', (f->>'x')::numeric, 'y', (f->>'y')::numeric, 'w', (f->>'w')::numeric, 'h', (f->>'h')::numeric)
                    else jsonb_build_object('kind', 'hwpx-cell', 'label', btrim(f->>'label')) end)
                 from jsonb_array_elements(v_s->'fields') f));
  end loop;

  if coalesce(p_check_only, true) then
    return jsonb_build_object(
      'ok', true, 'saved', false,
      'title', v_title,
      'file_name', v_loc->>'fileName',
      'due_at', mcp_private.kst_ts(coalesce(p_due_at, now() + interval '7 days')),
      'notify', coalesce(p_notify, true),
      'signers', (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                    'order', (x->>'order_index')::int + 1, 'name', x->>'signer_name', 'role', x->>'role_label',
                    'fields', x->'fields')) order by (x->>'order_index')::int)
                  from jsonb_array_elements(v_out) x),
      'next', '서명자·서명란·마감을 사용자에게 확인받은 뒤 check_only:false 로 다시 부르면 요청이 만들어지고 서명자에게 알림이 간다.');
  end if;

  v_id := public.create_signature_request(
    v_title, p_message, 'hwpx', 'pending',
    coalesce(nullif(v_loc->>'fileName', ''), v_title || '.hwpx'), 'application/haansofthwpx',
    p_page_count, v_out, null, null,
    jsonb_build_object('via', 'mcp', 'from_run', p_run_id)
      || case when coalesce(p_notify, true) then '{}'::jsonb else jsonb_build_object('notify', false) end);
  v_path := v_id::text || '/source.hwpx';
  perform public.set_signature_source_path(v_id, v_path);
  if p_due_at is not null then
    perform public.set_signature_due(v_id, p_due_at);
  end if;

  perform mcp_private.log_call(v_me, 'create_sign_request',
    jsonb_build_object('request_id', v_id, 'run_id', p_run_id, 'signers', jsonb_array_length(v_out), 'notify', coalesce(p_notify, true)));

  return jsonb_build_object(
    'ok', true, 'saved', true,
    'request_id', v_id,
    -- 엣지 mcp-sign 이 이 두 경로로만 복사한다(복사 실패 시 요청을 취소한다)
    'copy_from', v_loc->>'path',
    'copy_to', v_path,
    'web_path', '/signatures?request=' || v_id::text);
end;
$$;


ALTER FUNCTION "public"."mcp_create_sign_request"("p_run_id" "uuid", "p_title" "text", "p_signers" "jsonb", "p_message" "text", "p_due_at" timestamp with time zone, "p_page_count" integer, "p_check_only" boolean, "p_notify" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_supervision_schedules"("p_grade" integer, "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('supervision.plan');
  v_today  date := (now() at time zone 'Asia/Seoul')::date;
  v_e      jsonb;
  v_date   date;
  v_slot   text;
  v_wm     boolean;
  v_name   text;
  v_start  time;
  v_end    time;
  v_seen   text[] := '{}';
  v_ay     integer;
  v_person record;
  v_label  text;
  v_row    public.meeting;
  v_made   jsonb := '[]'::jsonb;
  v_notified integer := 0;
begin
  perform mcp_private.sv_require_grade(v_me, p_grade);
  if jsonb_typeof(coalesce(p_rows, 'null')) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception using errcode = '22023', message = '만들 칸이 없습니다.';
  end if;
  if jsonb_array_length(p_rows) > 80 then raise exception using errcode = '22023', message = '한 번에 80칸까지 만든다.'; end if;

  for v_e in select * from jsonb_array_elements(p_rows) loop
    begin
      v_date := (v_e->>'date')::date;
      v_start := (v_e->>'start')::time;
      v_end := (v_e->>'end')::time;
    exception when others then
      raise exception using errcode = '22023', message = format('날짜·시각 형식을 확인하세요: %s', v_e::text);
    end;
    v_slot := v_e->>'slot';
    v_wm := coalesce((v_e->>'with_morning')::boolean, false);
    v_name := btrim(coalesce(v_e->>'name', ''));
    if v_slot not in ('morning', 'evening', 'saturday') then raise exception using errcode = '22023', message = format('slot 은 morning · evening · saturday: %s', v_slot); end if;
    if p_grade = 0 and (v_slot <> 'morning' or v_wm) then
      raise exception using errcode = '22023', message = '전 학년(0)은 아침 칸만 만든다.';
    end if;
    if v_wm and v_slot <> 'evening' then raise exception using errcode = '22023', message = 'with_morning 은 저녁 칸에만.'; end if;
    if v_date is null or v_date < v_today or v_date > v_today + 200 then
      raise exception using errcode = '22023', message = format('오늘 이후 날짜만 만든다: %s', v_e->>'date');
    end if;
    if v_start is null or v_end is null or v_end <= v_start then raise exception using errcode = '22023', message = format('%s 시각을 확인하세요.', v_date); end if;
    if (v_date::text || '|' || v_slot) = any(v_seen) then
      raise exception using errcode = '22023', message = format('같은 칸이 두 번 있습니다: %s %s', v_date, v_slot);
    end if;
    v_seen := v_seen || (v_date::text || '|' || v_slot);
    v_ay := case when extract(month from v_date) >= 3 then extract(year from v_date)::int else extract(year from v_date)::int - 1 end;
    select * into v_person from mcp_private.sv_pool(p_grade, v_ay) p where p.name = v_name;
    if v_person.resource_id is null then
      raise exception using errcode = '22023',
        message = format('%s 선생님은 %s 감독 명단(학년부 소속·담임·학년부장)에 없습니다.', v_name, case p_grade when 0 then '전 학년' else p_grade || '학년' end);
    end if;
    if exists (select 1 from public.get_self_study_supervision_history(p_grade, v_date, v_date) h
               where h.slot = v_slot or (v_slot = 'morning' and h.slot = 'evening' and coalesce(h.with_morning, false))
                  or (v_wm and h.slot = 'morning')) then
      raise exception using errcode = '22023', message = format('%s %s 감독은 이미 있습니다.', v_date, v_slot);
    end if;

    v_label := case when v_slot = 'evening' and v_wm then '아침·저녁' when v_slot = 'morning' then '아침' when v_slot = 'evening' then '저녁' else '토요일' end;
    v_row := mcp_private.meeting_insert('duty',
               format('자습감독 · %s %s · %s', case p_grade when 0 then '전 학년' else p_grade || '학년' end, v_label, v_person.name),
               (v_date + v_start) at time zone 'Asia/Seoul', (v_date + v_end) at time zone 'Asia/Seoul', false,
               left(nullif(btrim(coalesce(v_e->>'description', '')), ''), 1000),
               jsonb_build_array(jsonb_build_object('name', v_person.name)),
               jsonb_build_object('supervision', jsonb_strip_nulls(jsonb_build_object('grade', p_grade, 'slot', v_slot,
                                                                                      'with_morning', case when v_wm then true end))),
               v_me);
    v_made := v_made || jsonb_build_object('date', v_date, 'slot', v_slot, 'name', v_person.name, 'schedule_id', v_row.id);
    if exists (select 1 from resource r where r.id = v_person.resource_id and r.type = 'teacher') then v_notified := v_notified + 1; end if;
  end loop;

  perform mcp_private.log_call(v_me, 'create_supervision_schedules', jsonb_build_object('grade', p_grade, 'cells', jsonb_array_length(v_made)));
  return jsonb_build_object('made', jsonb_array_length(v_made), 'cells', v_made, 'notified', v_notified,
    'note', '자습 감독 업무 일정을 만들었다 — 교사 담당자에게 알림이 갔다. 교체는 선생님들이 «내 감독·교체»(또는 request_supervision_swap)에서 한다.');
end;
$$;


ALTER FUNCTION "public"."mcp_create_supervision_schedules"("p_grade" integer, "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_task"("p_work_id" "uuid", "p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_type" "text" DEFAULT 'procedural'::"text", "p_step" integer DEFAULT NULL::integer, "p_due_dates" "text"[] DEFAULT NULL::"text"[], "p_assignees" "text"[] DEFAULT NULL::"text"[], "p_visible_from" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := mcp_private.require_tool('work.manage');
  w public.work := mcp_private.wk_managed_work(p_work_id);
  v_title text := btrim(coalesce(p_title, ''));
  v_type text := coalesce(nullif(p_type, ''), 'procedural');
  d record; v_assignees jsonb := '[]'; v_order int; v_id uuid; v_vis text := nullif(btrim(coalesce(p_visible_from, '')), '');
begin
  if v_title = '' or length(v_title) > 200 then raise exception using errcode = '22023', message = 'title 은 1~200자입니다.'; end if;
  if v_type not in ('procedural', 'one_time') then raise exception using errcode = '22023', message = 'type 은 procedural(절차 단계)·one_time(일회성)입니다.'; end if;
  select * into d from mcp_private.wk_due(p_due_dates);
  if v_vis is not null then
    if v_vis !~ '^\d{4}-\d{2}-\d{2}$' then raise exception using errcode = '22023', message = 'visible_from 은 YYYY-MM-DD 입니다.'; end if;
    if d.due is not null and v_vis > coalesce(d.deadlines->>0, to_char(d.due at time zone 'Asia/Seoul', 'YYYY-MM-DD')) then
      raise exception using errcode = '22023', message = '담당자에게 보이는 날(visible_from)이 첫 마감보다 늦습니다.';
    end if;
  end if;
  if p_assignees is not null and cardinality(p_assignees) > 0 then
    select coalesce(jsonb_agg(x || jsonb_build_object('status', 'pending', 'assigned_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'))), '[]')
      into v_assignees from jsonb_array_elements(mcp_private.wk_people(p_assignees, '담당자')) x;
  end if;
  if v_type = 'procedural' then
    if p_step is not null and p_step >= 1 then
      update task set order_index = order_index + 1 where event_id = p_work_id and type = 'procedural' and order_index >= p_step;
      v_order := p_step;
    else
      select coalesce(max(order_index), 0) + 1 into v_order from task where event_id = p_work_id and type = 'procedural';
    end if;
  else v_order := 0; end if;

  insert into task (event_id, title, description, type, order_index, due_date, keywords, meta, status, created_by)
  values (p_work_id, v_title, nullif(btrim(coalesce(p_description, '')), ''), v_type, v_order, d.due, '{}',
          jsonb_strip_nulls(jsonb_build_object('assignees', v_assignees, 'deadlines', d.deadlines, 'visibleFrom', v_vis,
            'via', jsonb_build_object('channel', 'mcp'))),
          'pending', v_me)
  returning id into v_id;
  if v_type = 'procedural' then perform mcp_private.wk_renumber(p_work_id); end if;
  perform mcp_private.log_call(v_me, 'create_task', jsonb_build_object('task_id', v_id, 'work_id', p_work_id, 'title', v_title));
  return jsonb_build_object('task_id', v_id, 'work', mcp_private.wk_work_out(p_work_id));
end $_$;


ALTER FUNCTION "public"."mcp_create_task"("p_work_id" "uuid", "p_title" "text", "p_description" "text", "p_type" "text", "p_step" integer, "p_due_dates" "text"[], "p_assignees" "text"[], "p_visible_from" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_volunteer_club"("p_clubs" "jsonb", "p_form" "jsonb" DEFAULT NULL::"jsonb", "p_issued_on" "date" DEFAULT NULL::"date", "p_department" "text" DEFAULT NULL::"text", "p_remarks" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me       uuid := mcp_private.require_tool('issue.register');
  v_year     integer := mcp_private.iss_academic_year();
  v_form     jsonb := mcp_private.obj(p_form);
  v_key      text;
  v_ref      text;
  v_club     club_info;
  v_ids      uuid[] := '{}';
  v_bad      text[] := '{}';
  v_sched    jsonb := '[]'::jsonb;
  v_e        jsonb;
  v_entries  jsonb := '[]'::jsonb;
  v_union    jsonb;
  v_title    text;
  v_id       uuid;
  v_no       text;
begin
  perform mcp_private.iss_require_issuer();
  for v_key in select jsonb_object_keys(v_form) loop
    if not v_key = any(array['scope', 'area', 'org', 'org_tel', 'place', 'schedule']) then
      raise exception using errcode = '22023',
        message = format('form 에 모르는 칸 «%s» — 쓸 수 있는 칸: scope · area · org · org_tel · place · schedule', v_key);
    end if;
  end loop;
  if coalesce(v_form->>'scope', '정규교육과정 내') not in ('정규교육과정 내', '정규교육과정 외') then
    raise exception using errcode = '22023', message = 'form.scope 는 정규교육과정 내 · 정규교육과정 외 중 하나입니다.';
  end if;
  if coalesce(v_form->>'area', '동아리') not in ('자율자치', '동아리', '진로') then
    raise exception using errcode = '22023', message = 'form.area(봉사 주관 영역)는 자율자치 · 동아리 · 진로 중 하나입니다.';
  end if;
  if jsonb_array_length(mcp_private.arr(v_form->'schedule')) > 9 then
    raise exception using errcode = '22023', message = 'schedule 은 9건까지입니다(확인서 날짜 칸이 9개).';
  end if;
  for v_e in select * from jsonb_array_elements(mcp_private.arr(v_form->'schedule')) loop
    if coalesce(v_e->>'date', '') !~ '^\d{4}-\d{2}-\d{2}$' or coalesce(v_e->>'hours', '') !~ '^\d+(\.\d+)?$'
       or (v_e->>'hours')::numeric <= 0 or (v_e->>'hours')::numeric > 24 then
      raise exception using errcode = '22023', message = 'schedule 은 [{"date":"YYYY-MM-DD","hours":2}] 모양입니다(시간 0~24).';
    end if;
    if not exists (select 1 from jsonb_array_elements(v_sched) x where x->>'date' = v_e->>'date') then
      v_sched := v_sched || jsonb_build_object('date', (v_e->>'date')::date::text, 'hours', (v_e->>'hours')::numeric);
    end if;
  end loop;
  select coalesce(jsonb_agg(x order by x->>'date'), '[]'::jsonb) into v_sched from jsonb_array_elements(v_sched) x;

  if p_clubs is null or jsonb_typeof(p_clubs) <> 'array' or jsonb_array_length(p_clubs) = 0 then
    raise exception using errcode = '22023', message = 'clubs 에 동아리 이름이나 club_id 를 1개 이상 주세요(list_clubs). 전부면 ["all"].';
  end if;
  for v_ref in select btrim(x) from jsonb_array_elements_text(p_clubs) x loop
    if v_ref = 'all' then
      v_ids := v_ids || array(select c.id from club_info c where c.academic_year = v_year
                                and coalesce(c.meta->>'status', '') <> 'inactive' and not c.id = any(v_ids) order by c.name);
      continue;
    end if;
    select * into v_club from club_info c
    where c.academic_year = v_year and (c.id::text = lower(v_ref) or c.name = v_ref)
    limit 1;
    if not found then
      v_bad := v_bad || v_ref;
    elsif not v_club.id = any(v_ids) then
      v_ids := v_ids || v_club.id;
    end if;
  end loop;
  if cardinality(v_bad) > 0 then
    raise exception using errcode = '22023',
      message = format('%s학년도 동아리에 없습니다 — %s (list_clubs 의 이름을 그대로)', v_year, array_to_string(v_bad, ' · '));
  end if;
  if cardinality(v_ids) = 0 then
    raise exception using errcode = '22023', message = '발급할 동아리가 없습니다.';
  end if;

  select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'club_id', c.id, 'club_name', c.name, 'teacher_name', c.teacher_name, 'teacher_resource_id', c.teacher_resource_id,
           'students', (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                          'resource_id', s->>'resource_id', 'code', s->>'code', 'grade', s->'grade', 'class', s->'class',
                          'number', s->'number', 'name', s->>'name'))), '[]'::jsonb)
                        from jsonb_array_elements(mcp_private.arr(c.students)) s),
           'activities', (select coalesce(jsonb_agg(jsonb_build_object('date', x->>'date', 'hours', x->'hours', 'content', '')
                                                    order by x->>'date'), '[]'::jsonb)
                          from jsonb_array_elements(v_sched) x)))
         order by array_position(v_ids, c.id))
    into v_entries
  from club_info c where c.id = any(v_ids);

  select coalesce(jsonb_agg(s), '[]'::jsonb) into v_union from (
    select distinct on (s->>'resource_id') s
    from jsonb_array_elements(v_entries) c, jsonb_array_elements(c->'students') s
    order by s->>'resource_id') u;

  v_title := case when jsonb_array_length(v_entries) = 1 then format('%s 동아리 봉사활동', v_entries->0->>'club_name')
                  else format('동아리 봉사활동 (%s개 동아리)', jsonb_array_length(v_entries)) end;

  v_id := public.create_document_issue(
    'volunteer_club', v_title, coalesce(p_issued_on, mcp_private.iss_today()), nullif(btrim(p_department), ''),
    v_union, null, null,
    jsonb_build_object('kind', 'club',
      'scope', coalesce(v_form->>'scope', '정규교육과정 내'), 'area', coalesce(v_form->>'area', '동아리'),
      'org', coalesce(nullif(btrim(v_form->>'org'), ''), '샘플고등학교'),
      'org_tel', coalesce(nullif(btrim(v_form->>'org_tel'), ''), '000-0000-0032'),
      'place', coalesce(nullif(btrim(v_form->>'place'), ''), '샘플고등학교'),
      'schedule', v_sched, 'clubs', v_entries),
    nullif(btrim(p_remarks), ''), jsonb_build_object('via', mcp_private.iss_via()));
  select issue_no into v_no from document_issue where id = v_id;

  perform mcp_private.log_call(v_me, 'create_volunteer_club',
    jsonb_build_object('issue_id', v_id, 'issue_no', v_no, 'clubs', jsonb_array_length(v_entries)));
  return jsonb_build_object('issue_id', v_id, 'issue_no', v_no, 'title', v_title,
    'clubs', (select jsonb_agg(jsonb_build_object('club_id', c->>'club_id', 'club_name', c->>'club_name',
                                                 'teacher', c->>'teacher_name', 'student_count', jsonb_array_length(c->'students')))
              from jsonb_array_elements(v_entries) c),
    'schedule', v_sched,
    'note', '발급번호를 받았다. 동아리마다 활동(날짜·시간·내용)을 set_club_activities 로 적는다 — 내용이 비면 확인서에 빈칸으로 나온다. ' ||
            '날짜별 참가·제외 학생과 한글 파일은 웹 봉사 발급 대장에서.');
end;
$_$;


ALTER FUNCTION "public"."mcp_create_volunteer_club"("p_clubs" "jsonb", "p_form" "jsonb", "p_issued_on" "date", "p_department" "text", "p_remarks" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_volunteer_group"("p_students" "jsonb", "p_form" "jsonb", "p_title" "text" DEFAULT NULL::"text", "p_issued_on" "date" DEFAULT NULL::"date", "p_department" "text" DEFAULT NULL::"text", "p_remarks" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me       uuid := mcp_private.require_tool('issue.register');
  v_form     jsonb;
  v_students jsonb;
  v_title    text;
  v_grade    integer;
  v_class    integer;
  v_id       uuid;
  v_no       text;
begin
  perform mcp_private.iss_require_issuer();
  v_form := mcp_private.iss_volunteer_form(p_form, 'group');
  v_students := mcp_private.iss_students(p_students, (v_form->>'hours')::numeric);
  v_title := coalesce(nullif(btrim(p_title), ''), v_form->>'content');
  if length(v_title) > 200 then
    raise exception using errcode = '22023', message = 'title 은 200자까지입니다.';
  end if;

  select case when count(distinct s->>'grade') = 1 then min((s->>'grade')::int) end into v_grade
  from jsonb_array_elements(v_students) s;
  if v_grade is not null then
    select case when count(distinct s->>'class') = 1 then min((s->>'class')::int) end into v_class
    from jsonb_array_elements(v_students) s where (s->>'grade')::int = v_grade;
  end if;

  v_id := public.create_document_issue(
    'volunteer_class', v_title, coalesce(p_issued_on, mcp_private.iss_today()), nullif(btrim(p_department), ''),
    v_students, v_grade, v_class, v_form, nullif(btrim(p_remarks), ''),
    jsonb_build_object('via', mcp_private.iss_via()));
  select issue_no into v_no from document_issue where id = v_id;

  perform mcp_private.log_call(v_me, 'create_volunteer_group',
    jsonb_build_object('issue_id', v_id, 'issue_no', v_no, 'count', jsonb_array_length(v_students)));
  return jsonb_build_object('issue_id', v_id, 'issue_no', v_no, 'title', v_title, 'student_count', jsonb_array_length(v_students),
    'students', (select jsonb_agg(mcp_private.iss_student_label(s)) from jsonb_array_elements(v_students) s),
    'form', v_form,
    'note', '단체 봉사 발급번호 하나를 받았다. 반별 명단 고치기와 확인서 한글 파일은 웹 봉사 발급 대장에서.');
end;
$$;


ALTER FUNCTION "public"."mcp_create_volunteer_group"("p_students" "jsonb", "p_form" "jsonb", "p_title" "text", "p_issued_on" "date", "p_department" "text", "p_remarks" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_volunteer_personal"("p_students" "jsonb", "p_form" "jsonb", "p_issued_on" "date" DEFAULT NULL::"date", "p_department" "text" DEFAULT NULL::"text", "p_remarks" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me       uuid := mcp_private.require_tool('issue.register');
  v_form     jsonb;
  v_students jsonb;
  v_s        jsonb;
  v_batch    uuid := gen_random_uuid();
  v_id       uuid;
  v_out      jsonb := '[]'::jsonb;
  v_classes  integer;
  v_note     text;
begin
  perform mcp_private.iss_require_issuer();
  v_form := mcp_private.iss_volunteer_form(p_form, 'personal');
  v_students := mcp_private.iss_students(p_students, 1);

  if not v_form ? 'confirmer_name' then
    select count(distinct (s->>'grade') || '-' || (s->>'class')) into v_classes from jsonb_array_elements(v_students) s;
    if v_classes = 1 then
      v_form := v_form || jsonb_strip_nulls(jsonb_build_object('confirmer_name',
        mcp_private.iss_homeroom_name((v_students->0->>'grade')::int, (v_students->0->>'class')::int)));
    end if;
    v_note := case when v_form ? 'confirmer_name'
                   then format('확인자 성명은 담임 %s 선생님으로 채웠다.', v_form->>'confirmer_name')
                   else '확인자 성명이 비어 있다 — 반이 섞였거나 담임을 못 찾았다. 웹 대장에서 학생마다 고치거나 confirmer_name 을 주고 다시 발급한다.' end;
  end if;

  for v_s in select * from jsonb_array_elements(v_students) loop
    v_id := public.create_document_issue(
      'volunteer_personal', v_form->>'content', coalesce(p_issued_on, mcp_private.iss_today()), nullif(btrim(p_department), ''),
      jsonb_build_array(v_s), (v_s->>'grade')::int, (v_s->>'class')::int, v_form, nullif(btrim(p_remarks), ''),
      jsonb_build_object('batch_id', v_batch, 'via', mcp_private.iss_via()));
    v_out := v_out || jsonb_build_object('issue_id', v_id, 'issue_no', (select issue_no from document_issue where id = v_id),
                                         'student', mcp_private.iss_student_label(v_s));
  end loop;

  perform mcp_private.log_call(v_me, 'create_volunteer_personal',
    jsonb_build_object('batch_id', v_batch, 'count', jsonb_array_length(v_out)));
  return jsonb_strip_nulls(jsonb_build_object(
    'batch_id', v_batch, 'issued', v_out, 'form', v_form,
    'note', concat_ws(' ', format('학생 %s명에게 발급번호를 하나씩 줬다.', jsonb_array_length(v_out)), v_note,
                      '확인서 한글 파일은 웹 봉사 발급 대장에서 받는다(이 묶음은 한 줄로 보인다).')));
end;
$$;


ALTER FUNCTION "public"."mcp_create_volunteer_personal"("p_students" "jsonb", "p_form" "jsonb", "p_issued_on" "date", "p_department" "text", "p_remarks" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_work"("p_name" "text", "p_description" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text", "p_managers" "text"[] DEFAULT NULL::"text"[], "p_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.manage');
  v_name text := btrim(coalesce(p_name, ''));
  v_managers jsonb;
  v_dep text := nullif(btrim(coalesce(p_department, '')), '');
  v_id uuid;
begin
  if v_name = '' or length(v_name) > 200 then raise exception using errcode = '22023', message = 'name 은 1~200자입니다.'; end if;
  -- 책임자를 비우면 나 — 웹도 책임자 없는 업무를 만들지 않는다
  v_managers := case when p_managers is null or cardinality(p_managers) = 0
    then (select jsonb_build_array(jsonb_build_object('id', r.id, 'name', r.name)) from resource r where r.id = v_me)
    else mcp_private.wk_people(p_managers, '책임자') end;
  if v_dep is not null and not exists (select 1 from department d where d.is_active and d.name = v_dep) then
    raise exception using errcode = '22023', message = format('부서 «%s» 를 찾지 못했습니다 — read_data departments 로 확인하세요.', v_dep);
  end if;
  insert into work (name, description, manager_id, status, keywords, meta)
  values (v_name, nullif(btrim(coalesce(p_description, '')), ''), (v_managers->0->>'id')::uuid, 'active', '{}',
          jsonb_strip_nulls(jsonb_build_object('managers', v_managers, 'department', v_dep,
            'year', coalesce(p_year, mcp_private.sch_year()), 'via', jsonb_build_object('channel', 'mcp'))))
  returning id into v_id;
  perform mcp_private.log_call(v_me, 'create_work', jsonb_build_object('work_id', v_id, 'name', v_name));
  return mcp_private.wk_work_out(v_id);
end $$;


ALTER FUNCTION "public"."mcp_create_work"("p_name" "text", "p_description" "text", "p_department" "text", "p_managers" "text"[], "p_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_decide_club_members"("p_member_ids" "uuid"[], "p_decision" "text", "p_note" "text" DEFAULT NULL::"text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('club.manage');
  v jsonb; v_rows jsonb;
begin
  if p_decision not in ('confirm', 'reject', 'remove') then
    raise exception using errcode = '22023', message = 'decision 은 confirm(제안 확정) · reject(제안 거절) · remove(확정 부원 빼기)';
  end if;
  select jsonb_agg(jsonb_build_object('member_id', m.id, 'student', concat_ws('-', m.grade, m.class_num, m.number),
                                      'name', r.name, 'status', m.status, 'club', y.name))
    into v_rows
  from public.club_member m join public.club_year y on y.id = m.club_year_id left join public.resource r on r.id = m.student_resource_id
  where m.id = any(p_member_ids);
  if v_rows is null then raise exception using errcode = 'P0002', message = '명단 줄을 찾지 못했습니다(get_club 의 members[].member_id)'; end if;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true, 'decision', p_decision, 'rows', v_rows,
      'next', 'confirm·reject 는 pending 줄만, remove 는 confirmed 줄만 바뀐다. 확인받은 뒤 check_only:false.');
  end if;
  v := public.club_decide_members(p_member_ids, p_decision, p_note);
  perform mcp_private.log_call(v_me, 'decide_club_members', jsonb_build_object('members', to_jsonb(p_member_ids), 'decision', p_decision));
  return v;
end $$;


ALTER FUNCTION "public"."mcp_decide_club_members"("p_member_ids" "uuid"[], "p_decision" "text", "p_note" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_decide_club_proposal"("p_club_year_id" "uuid", "p_approve" boolean, "p_teachers" "text"[] DEFAULT NULL::"text"[], "p_reason" "text" DEFAULT NULL::"text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := mcp_private.require_tool('club.manage'); t text; v_ids uuid[] := '{}'; v_n int; v_id uuid; v jsonb;
begin
  if not public.is_club_manager() then raise exception using errcode = '42501', message = '개설은 동아리 담당자가 결정합니다'; end if;
  foreach t in array coalesce(p_teachers, '{}') loop
    select count(*), min(r.id::text)::uuid into v_n, v_id from public.resource r
    where r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active' and (r.id::text = btrim(t) or r.name = btrim(t));
    if v_n <> 1 then raise exception using errcode = '22023', message = format('지도교사 «%s» 를 정확히 한 명으로 찾지 못했습니다(find_staff 로 확인)', t); end if;
    v_ids := v_ids || v_id;
  end loop;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true, 'approve', p_approve,
      'proposal', (select x from jsonb_array_elements(public.club_proposals(null)) x where x->>'id' = p_club_year_id::text),
      'teachers', (select jsonb_agg(r.name) from public.resource r where r.id = any (v_ids)),
      'next', '결정을 사용자에게 보여 확인받은 뒤 check_only:false.');
  end if;
  v := public.club_decide_proposal(p_club_year_id, p_approve, v_ids, p_reason);
  perform mcp_private.log_call(v_me, 'decide_club_proposal', jsonb_build_object('club_year_id', p_club_year_id, 'approve', p_approve));
  return mcp_private.club_brief(v);
end $$;


ALTER FUNCTION "public"."mcp_decide_club_proposal"("p_club_year_id" "uuid", "p_approve" boolean, "p_teachers" "text"[], "p_reason" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_decide_official_doc"("p_doc_no" "text", "p_decision" "text", "p_reason" "text" DEFAULT NULL::"text", "p_nature" "text" DEFAULT NULL::"text", "p_work_id" "uuid" DEFAULT NULL::"uuid", "p_task_id" "uuid" DEFAULT NULL::"uuid", "p_assignee_names" "text"[] DEFAULT '{}'::"text"[], "p_rule" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('official.doc');
  o official_doc;
  v_dec uuid;
  v_rule uuid;
  v_year int := extract(year from (now() at time zone 'Asia/Seoul'))::int;
begin
  select * into o from official_doc where doc_no = btrim(p_doc_no);
  if not found then
    raise exception using errcode = 'P0002', message = '그 문서번호의 공문이 없습니다(또는 볼 수 없습니다).';
  end if;
  if p_decision not in ('ignore', 'info', 'link_work', 'create_work', 'reassign') then
    raise exception using errcode = '22023', message = 'decision 은 link_work · create_work · reassign · info · ignore 중 하나입니다.';
  end if;
  if p_nature is not null and p_nature not in ('제출', '추천', '설문', '참석', '실시', '지침', '기회', '홍보', '무관') then
    raise exception using errcode = '22023', message = 'nature 는 제출 · 추천 · 설문 · 참석 · 실시 · 지침 · 기회 · 홍보 · 무관 중 하나입니다.';
  end if;
  if p_decision in ('link_work', 'create_work') and p_work_id is null then
    raise exception using errcode = '22023', message = 'link_work · create_work 는 work_id 가 필요합니다 — 먼저 create_task(기존 업무) 또는 create_work 로 만드세요.';
  end if;
  if p_work_id is not null and not exists (select 1 from work where id = p_work_id) then
    raise exception using errcode = '22023', message = '그 업무가 없습니다.';
  end if;
  if p_task_id is not null and not exists (select 1 from task where id = p_task_id and event_id = p_work_id) then
    raise exception using errcode = '22023', message = '그 할 일은 이 업무의 할 일이 아닙니다.';
  end if;
  if p_decision = 'reassign' and coalesce(array_length(p_assignee_names, 1), 0) = 0 then
    raise exception using errcode = '22023', message = 'reassign 은 assignee_names(누구 일인지)가 필요합니다.';
  end if;

  insert into official_doc_decision (doc_id, triage_id, decision, nature, work_id, task_id, assignee_names, reason, via)
  values (o.id,
          (select id from official_doc_triage where doc_id = o.id order by created_at desc limit 1),
          p_decision, p_nature,
          case when p_decision in ('link_work', 'create_work') then p_work_id end,
          case when p_decision in ('link_work', 'create_work') then p_task_id end,
          coalesce(p_assignee_names, '{}'), nullif(btrim(coalesce(p_reason, '')), ''), 'mcp')
  returning id into v_dec;

  if p_rule is not null then
    if jsonb_typeof(p_rule) <> 'object'
       or (coalesce(p_rule->>'sender', '') = '' and jsonb_array_length(coalesce(p_rule->'title_all', '[]'::jsonb)) = 0) then
      raise exception using errcode = '22023', message = 'rule 은 {sender?, title_all?: [낱말]} — 조건이 하나 이상 있어야 합니다.';
    end if;
    insert into doc_rule (kind, condition, outcome, note, status, academic_year, source_decision_ids)
    values ('route',
            jsonb_strip_nulls(jsonb_build_object('sender', nullif(btrim(coalesce(p_rule->>'sender', '')), ''),
                                                 'title_all', case when jsonb_array_length(coalesce(p_rule->'title_all', '[]'::jsonb)) > 0 then p_rule->'title_all' end)),
            jsonb_strip_nulls(jsonb_build_object('decision', p_decision, 'nature', p_nature, 'work_id', p_work_id,
                                                 'assignee_names', case when coalesce(array_length(p_assignee_names, 1), 0) > 0 then to_jsonb(p_assignee_names) end)),
            nullif(btrim(coalesce(p_reason, '')), ''), 'active', v_year, array[v_dec])
    returning id into v_rule;
  end if;

  perform mcp_private.log_call(v_me, 'decide_official_doc', jsonb_build_object('doc_no', o.doc_no, 'decision', p_decision, 'rule', v_rule is not null));
  return jsonb_build_object('decision_id', v_dec, 'rule_id', v_rule);
end;
$$;


ALTER FUNCTION "public"."mcp_decide_official_doc"("p_doc_no" "text", "p_decision" "text", "p_reason" "text", "p_nature" "text", "p_work_id" "uuid", "p_task_id" "uuid", "p_assignee_names" "text"[], "p_rule" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_decide_work_insight"("p_work_id" "uuid", "p_insight_id" bigint, "p_decision" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.run');
  w public.work := mcp_private.wk_managed_work(p_work_id);
  k public.work_knowledge;
begin
  if p_decision not in ('applied', 'dismissed') then
    raise exception using errcode = '22023', message = 'decision 은 applied(따름) · dismissed(따르지 않음) 중 하나입니다.';
  end if;
  select * into k from public.work_knowledge where id = p_insight_id;
  if k.id is null or not exists (select 1 from mcp_private.work_lineage(w.id) l where l.work_id = k.work_id) then
    raise exception using errcode = 'P0002', message = '이 업무(또는 지난 해 업무)의 지식이 아닙니다 (get_work_progress 의 knowledge_id).';
  end if;
  perform mcp_private.wr_event(w.id, null, null, 'insight.decided', jsonb_strip_nulls(jsonb_build_object(
    'insight_id', p_insight_id, 'kind', k.kind, 'decision', p_decision, 'note', left(p_note, 500))));
  return jsonb_build_object('insight_id', p_insight_id, 'decision', p_decision);
end;
$$;


