CREATE OR REPLACE FUNCTION "public"."mcp_delete_code_project"("p_project_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('code.share');
  v_p  public.code_project;
  v_objects jsonb;
begin
  select * into v_p from code_project where id = p_project_id;
  if not found or not coalesce(v_p.owner_resource_id in (select public.current_actor_resource_ids()), false) then
    raise exception using errcode = '42501', message = '내 프로젝트만 지울 수 있습니다.';
  end if;
  perform set_config('mcp.read_storage', 'on', true);
  select coalesce(jsonb_agg(o.name), '[]'::jsonb) into v_objects
    from storage.objects o where o.bucket_id = 'code-projects' and o.name like p_project_id || '/%';
  perform set_config('mcp.read_storage', '', true);
  delete from code_project where id = p_project_id;
  if not found then raise exception using errcode = '42501', message = '이 프로젝트를 지울 권한이 없습니다.'; end if;
  perform mcp_private.log_call(v_me, 'delete_code_project', jsonb_build_object('title', v_p.title, 'objects', jsonb_array_length(v_objects)));
  return jsonb_build_object('deleted', true, 'title', v_p.title, 'storage_paths', v_objects);
end;
$$;


ALTER FUNCTION "public"."mcp_delete_code_project"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_doc_context"("p_id" "uuid", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('knowledge.context');
  o public.docgen_context;
begin
  select * into o from docgen_context where id = p_id;
  if not found then
    raise exception using errcode = 'P0002', message = '그 문서 맥락이 없습니다.';
  end if;
  if o.user_id is distinct from auth.uid() then
    raise exception using errcode = '42501', message = '지울 수 있는 것은 내가 쓴 문서 맥락뿐입니다.';
  end if;
  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true, 'id', o.id, 'title', o.title, 'category', o.category,
      'length', char_length(o.body), 'generations', mcp_private.dc_entry(o, false)->'generations',
      'note', '되돌릴 수 없다 — 생성 방식 연결도 함께 사라진다. 잠시 안 보이게만 하려면 save_doc_context 의 hidden:true. 사용자에게 확인받은 뒤 check_only:false.'));
  end if;
  delete from docgen_context where id = o.id;
  perform mcp_private.log_call(v_me, 'delete_doc_context', jsonb_build_object('context_id', o.id, 'title', o.title));
  return jsonb_build_object('deleted', true, 'id', o.id, 'title', o.title);
end;
$$;


ALTER FUNCTION "public"."mcp_delete_doc_context"("p_id" "uuid", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_document"("p_document_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me  uuid := mcp_private.require_tool('document.library');
  v_doc public.documents;
  v_from text;
  v_path text;
begin
  if p_document_id is null then raise exception using errcode = '22023', message = 'document_id 가 필요합니다.'; end if;
  select * into v_doc from documents where id = p_document_id;
  if not found then raise exception using errcode = 'P0002', message = '문서를 찾을 수 없습니다.'; end if;
  if not coalesce(v_doc.user_id = auth.uid(), false) and not public.is_admin() then
    raise exception using errcode = '42501', message = '내가 올린 문서만 지울 수 있습니다.';
  end if;
  if v_doc.meta ? 'source' then
    raise exception using errcode = '22023', message = '업무·이벤트에 연결된 문서는 지울 수 없습니다(그 업무에서 정리한다).';
  end if;
  v_from := nullif(v_doc.meta->>'uploaded_from', '');
  if v_from is not null and v_from not in ('document_upload', 'google_drive', 'google_drive_folder', 'google_drive_integration') then
    raise exception using errcode = '22023', message = '다른 기능(공지·회의·업무 등)에서 올린 문서는 서류함에서 지울 수 없습니다.';
  end if;

  delete from documents where id = p_document_id;
  if not found then raise exception using errcode = '42501', message = '이 문서를 지울 권한이 없습니다.'; end if;
  -- 정리할 저장소 객체 — 서류함 버킷의 상대 경로만(드라이브·외부 주소는 손대지 않는다)
  if v_doc.storage_path !~ '^https?://' and coalesce(nullif(v_doc.meta->>'storage_bucket', ''), 'documents') = 'documents'
     and v_doc.storage_path !~ '\.\.' and v_doc.storage_path ~ '^(library/)?[0-9a-f-]{36}/[^/]+$' then
    v_path := v_doc.storage_path;
  end if;
  perform mcp_private.log_call(v_me, 'delete_document', jsonb_build_object('document_id', p_document_id, 'title', v_doc.title));
  return jsonb_strip_nulls(jsonb_build_object('deleted', true, 'title', v_doc.title, 'storage_path', v_path,
    'note', case when coalesce((v_doc.meta->>'is_google_drive_file')::boolean, false) or v_doc.meta->>'uploaded_from' like 'google_drive%'
                 then '서류함에서만 지웠다 — 구글 드라이브의 원본 파일은 그대로다(필요하면 드라이브에서 지운다).' end));
end;
$_$;


ALTER FUNCTION "public"."mcp_delete_document"("p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_document_generation"("p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me   uuid := mcp_private.require_tool('docgen.create');
  a      public.task_action := mcp_private.dg_my_method(p_action_id);
  v_runs int;
  v_docs int;
  v_n    int;
begin
  select count(*) into v_runs from task_action_run r where r.action_id = a.id;
  if v_runs > 0 then
    -- 실행마다 저장소에 결과 파일이 있다 — 에이전트 토큰은 저장소를 못 만지니 웹에서 지워야 파일까지 정리된다
    raise exception using errcode = '22023',
      message = format('이 생성 방식으로 만든 기록이 %s건 있어 이 연결로는 지우지 않습니다 — 웹 문서 생성에서 지우면 결과 파일까지 정리됩니다.', v_runs);
  end if;
  select count(*) into v_docs from task_action_document d where d.action_id = a.id;
  delete from task_action where id = a.id;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception using errcode = '42501', message = '지우지 못했습니다(만든 사람만).'; end if;
  perform mcp_private.log_call(v_me, 'delete_document_generation', jsonb_build_object('action_id', a.id, 'title', a.title));
  return jsonb_build_object('deleted', true, 'action_id', a.id, 'title', a.title,
    'note', '지웠다(되돌릴 수 없다). 올린 한글 양식은 양식 목록에 남는다.'
            || case when v_docs > 0 then format(' 완성 문서 %s건은 남지만 이 생성 방식과의 연결이 끊긴다.', v_docs) else '' end);
end;
$$;


ALTER FUNCTION "public"."mcp_delete_document_generation"("p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_generated_document"("p_document_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('docgen.fill');
  d     public.task_action_document;
  v_final int;
  v_id  uuid;
  v_n   int := 0;
begin
  select * into d from task_action_document where id = p_document_id and created_by = auth.uid();
  if d.id is null then raise exception using errcode = 'P0002', message = '내 완성 문서를 찾지 못했습니다 (list_generated_documents 의 document_id).'; end if;
  select count(*) into v_final from task_action_document v where v.family_id = d.family_id and v.status = 'final';
  if v_final > 0 then
    -- 웹은 최신부터 지우다 확정 판에서 멈춘다(반쯤 지워짐). 여기서는 하나도 지우지 않고 거부한다
    raise exception using errcode = '22023', message = '확정된 판이 있는 문서는 지울 수 없습니다(웹과 같다).';
  end if;
  -- 뒤 판이 앞 판을 FK 로 가리키므로 최신부터
  for v_id in select v.id from task_action_document v where v.family_id = d.family_id order by v.version desc loop
    delete from task_action_document where id = v_id;
    v_n := v_n + 1;
  end loop;
  perform mcp_private.log_call(v_me, 'delete_generated_document', jsonb_build_object('family_id', d.family_id, 'title', d.title, 'versions', v_n));
  return jsonb_build_object('deleted', true, 'title', d.title, 'versions_deleted', v_n,
    'note', '초안 문서를 모든 판과 함께 지웠다(되돌릴 수 없다). 만든 기록(실행)은 웹 문서 생성 기록에 남는다.');
end;
$$;


ALTER FUNCTION "public"."mcp_delete_generated_document"("p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_ipsi_news"("p_id" "uuid", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('ipsi.hub');
  o public.educational_news;
  v_used integer;
begin
  perform mcp_private.ipsi_teacher();
  if not public.is_admin() then
    raise exception using errcode = '42501', message = '기사 지우기는 관리자만 됩니다(웹과 같은 권한).';
  end if;
  select * into o from educational_news where id = p_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = '그 기사가 없습니다.';
  end if;
  select count(*) into v_used from educational_news_compound_analysis a where o.id = any(a.source_news_ids);
  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true, 'id', o.id, 'title', o.title, 'url', o.url,
      'source', mcp_private.ipsi_source_label(o.source), 'used_in_analyses', nullif(v_used, 0),
      'warning', case when o.source <> 'manual' then '수집기가 모은 기사다 — 수집기가 다시 모으면 되살아날 수 있다.' end,
      'note', '되돌릴 수 없다 — 이 기사를 근거로 쓴 분석에는 «지워진 자료»로 남는다. 사용자에게 확인받은 뒤 check_only:false.'));
  end if;
  delete from educational_news where id = o.id;
  perform mcp_private.log_call(v_me, 'delete_ipsi_news', jsonb_build_object('news_id', o.id, 'title', o.title));
  return jsonb_build_object('deleted', true, 'id', o.id, 'title', o.title);
end;
$$;


