CREATE OR REPLACE FUNCTION "public"."mcp_delete_purchase_order_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('purchase.request');
  v_batch public.purchase_order_batches%rowtype;
  v_lines integer;
  v_links integer;
  v_rows  integer;
begin
  if p_batch_id is null then
    raise exception using errcode = '22023', message = 'batch_id 가 필요합니다 (list_purchase_orders 의 batch_id).';
  end if;
  select * into v_batch from purchase_order_batches where id = p_batch_id for update;
  if v_batch.id is null then
    raise exception using errcode = 'P0002', message = '품의 차수를 찾을 수 없습니다.';
  end if;
  perform mcp_private.pr_require_manager(v_batch.page_id);
  if v_batch.status <> 'draft' then
    raise exception using errcode = '42501',
      message = format('«%s» 는 이미 %s 라 이 연결로 지울 수 없습니다 — 웹 구매 신청에서.', v_batch.title, mcp_private.pr_batch_label(v_batch.status));
  end if;

  select count(distinct l.id), count(li.id) into v_lines, v_links
    from purchase_order_lines l left join purchase_order_line_items li on li.line_id = l.id where l.batch_id = v_batch.id;
  delete from purchase_order_batches where id = v_batch.id;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception using errcode = '42501', message = '삭제 권한이 없습니다.';
  end if;

  perform mcp_private.log_call(v_me, 'delete_purchase_order_batch',
    jsonb_build_object('page_id', v_batch.page_id, 'batch_id', v_batch.id, 'lines', v_lines));
  return jsonb_build_object('deleted', true, 'batch_id', v_batch.id, 'title', v_batch.title, 'lines_removed', v_lines,
    'note', '차수와 그 품의 품목을 지웠다. 연결됐던 신청 품목은 «아직 안 담긴» 쪽으로 돌아간다(신청 품목 자체는 그대로).');
end;
$$;


ALTER FUNCTION "public"."mcp_delete_purchase_order_batch"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_purchase_order_lines"("p_line_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me      uuid := mcp_private.require_tool('purchase.request');
  v_ids     uuid[];
  v_pages   uuid[];
  v_pid     uuid;
  v_found   integer;
  v_links   integer;
  v_deleted integer;
begin
  if p_line_ids is null or cardinality(p_line_ids) = 0 then
    raise exception using errcode = '22023', message = 'line_ids 에 지울 품의 품목 id 를 넣어 주세요 (list_purchase_orders 의 line_id).';
  end if;
  if cardinality(p_line_ids) > 100 then
    raise exception using errcode = '22023', message = '한 번에 100개까지 지울 수 있습니다.';
  end if;
  select array_agg(distinct x) into v_ids from unnest(p_line_ids) x;
  select count(*), array_agg(distinct page_id) into v_found, v_pages from purchase_order_lines where id = any(v_ids);
  if v_found <> cardinality(v_ids) then
    raise exception using errcode = 'P0002', message = '찾을 수 없는 품의 품목이 있습니다.';
  end if;
  foreach v_pid in array v_pages loop
    perform mcp_private.pr_require_manager(v_pid);
  end loop;

  select count(*) into v_links from purchase_order_line_items where line_id = any(v_ids);
  delete from purchase_order_lines where id = any(v_ids);
  get diagnostics v_deleted = row_count;
  if v_deleted <> v_found then
    raise exception using errcode = '42501', message = '삭제 권한이 없습니다.';
  end if;

  perform mcp_private.log_call(v_me, 'delete_purchase_order_lines', jsonb_build_object('lines', v_deleted, 'unlinked', v_links));
  return jsonb_build_object('deleted', v_deleted, 'unlinked_items', v_links,
    'note', '품의 품목을 지웠다. 연결됐던 신청 품목은 «아직 안 담긴» 쪽으로 돌아가고 신청 품목 자체·그 상태는 그대로다.');
end;
$$;


ALTER FUNCTION "public"."mcp_delete_purchase_order_lines"("p_line_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_purchase_request"("p_request_id" "uuid", "p_check_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('purchase.request');
  v_req    public.purchase_requests%rowtype;
  v_page   public.purchase_request_pages%rowtype;
  v_items  jsonb;
  v_linked integer;
begin
  if p_request_id is null then
    raise exception using errcode = '22023', message = 'request_id 가 필요합니다 (list_managed_purchase_requests 의 request_id).';
  end if;
  select * into v_req from purchase_requests where id = p_request_id for update;
  if v_req.id is null then
    raise exception using errcode = 'P0002', message = '구매 신청을 찾을 수 없습니다.';
  end if;
  perform mcp_private.pr_require_manager(v_req.page_id);
  select * into v_page from purchase_request_pages where id = v_req.page_id;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'row_id', e.v->>'id',
           'item', mcp_private.obj(e.v->'cells') ->> mcp_private.pr_name_col(v_page.columns),
           'fields', mcp_private.pr_fields(e.v->'cells', v_page.columns),
           'amount', mcp_private.pr_amount(e.v->'cells', v_page.columns),
           'status', mcp_private.pr_item_status(v_req.meta, v_req.status, e.v->>'id'),
           'status_label', mcp_private.pr_status_label(mcp_private.pr_item_status(v_req.meta, v_req.status, e.v->>'id')),
           'in_order', (select b.title || ' (' || mcp_private.pr_batch_label(b.status) || ')'
                          from purchase_order_line_items li
                          join purchase_order_lines l on l.id = li.line_id
                          join purchase_order_batches b on b.id = l.batch_id
                         where li.request_id = v_req.id and li.row_id = e.v->>'id' limit 1)
         )) order by e.ord), '[]'::jsonb)
    into v_items
  from jsonb_array_elements(mcp_private.arr(v_req.items)) with ordinality e(v, ord)
  where mcp_private.pr_row_meaningful(e.v->'cells', v_page.columns);

  select count(*) into v_linked from purchase_order_line_items where request_id = v_req.id;

  if coalesce(p_check_only, false) then
    return jsonb_build_object('check_only', true, 'request_id', v_req.id,
      'requester', (select mcp_private.pr_requester_label(res.type, res.name, res.meta) from resource res where res.id = v_req.requester_id),
      'items', v_items, 'can_delete', v_linked = 0,
      'note', case when v_linked > 0
                   then '지울 수 없다 — 이미 품의 품목에 묶인 품목이 있다(in_order). save_purchase_order_line 의 unlink 로 먼저 뺀 뒤 다시 본다.'
                   else '아직 지우지 않았다 — 이 품목들이 통째로 사라지고 수정 이력도 함께 지워지며 되돌릴 수 없다. 사용자에게 보여 확인받은 뒤 check_only:false 로 다시 부른다.' end);
  end if;

  if v_linked > 0 then
    raise exception using errcode = '42501',
      message = '이미 품의 품목에 묶인 품목이 있어 지울 수 없습니다 — save_purchase_order_line 의 unlink 로 먼저 빼 주세요.';
  end if;

  delete from purchase_requests where id = v_req.id;
  if not found then
    raise exception using errcode = '42501', message = '삭제 권한이 없습니다. 페이지 작성자·공동 작업자만 신청을 지울 수 있습니다.';
  end if;

  perform mcp_private.log_call(v_me, 'delete_purchase_request',
    jsonb_build_object('request_id', v_req.id, 'page_id', v_req.page_id, 'items', jsonb_array_length(v_items)));

  return jsonb_build_object('deleted', true, 'request_id', v_req.id, 'items', v_items,
    'note', '지웠다(신청자에게 알림은 가지 않는다). 수정 이력도 함께 지워졌고 되돌릴 수 없다.');
end;
$$;


ALTER FUNCTION "public"."mcp_delete_purchase_request"("p_request_id" "uuid", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_schedule"("p_schedule_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_any_tool(array['schedule.manage', 'schedule.mine', 'mealduty.plan', 'supervision.plan']);
  v_row   public.meeting := mcp_private.sch_lock_mine(p_schedule_id, v_me, '지울');
  v_count integer;
begin
  -- 2026-11-04 — 일정 관리 허용이 없어도 개인일정(schedule.mine)·급식지도(mealduty.plan)·자습 감독(supervision.plan)은 그 허용으로
  perform mcp_private.sch_require_kind_grant(v_row);
  if v_row.kind = 'training' then
    select count(*) into v_count from training_signature s where s.meeting_id = v_row.id;
    if v_count > 0 then
      raise exception using errcode = '42501',
        message = format('참석 서명이 %s건 있는 연수라 이 연결로는 지울 수 없습니다 — 웹에서 확인하고 지우세요.', v_count);
    end if;
  end if;

  delete from meeting where id = v_row.id;
  get diagnostics v_count = row_count;
  if v_count = 0 then
    raise exception using errcode = '42501', message = '일정을 지우지 못했습니다(권한).';
  end if;

  perform mcp_private.log_call(v_me, 'delete_schedule',
    jsonb_build_object('id', v_row.id, 'kind', v_row.kind, 'title', v_row.meta->>'title'));

  return jsonb_build_object(
    'deleted', true, 'id', v_row.id, 'kind_label', mcp_private.sch_kind_label(v_row.kind), 'title', v_row.meta->>'title',
    'note', '지웠다(되돌릴 수 없다). 참석자에게 취소 알림은 가지 않는다 — 필요하면 따로 알린다.'
  );
end;
$$;


ALTER FUNCTION "public"."mcp_delete_schedule"("p_schedule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_schedule_survey"("p_survey_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('schedule.survey');
  v_row   public.schedule_survey;
  v_resp  int;
  v_n     int;
begin
  if not coalesce(public.can_manage_schedule_survey(p_survey_id), false) then
    raise exception using errcode = 'P0002', message = '내가 만든 설문을 찾을 수 없습니다 (list_schedule_surveys 의 survey_id).';
  end if;
  select * into v_row from schedule_survey where id = p_survey_id;
  select count(*) into v_resp from schedule_survey_response r where r.survey_id = v_row.id;
  delete from schedule_survey where id = v_row.id;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception using errcode = '42501', message = '설문을 지우지 못했습니다(작성자·관리자만).'; end if;
  perform mcp_private.log_call(v_me, 'delete_schedule_survey', jsonb_build_object('survey_id', v_row.id, 'title', v_row.title, 'responses', v_resp));
  return jsonb_build_object('deleted', true, 'survey_id', v_row.id, 'title', v_row.title, 'responses_deleted', v_resp,
    'note', '지웠다(되돌릴 수 없다) — 응답도 함께 지워졌고, 이 설문으로 만든 일정은 그대로 남는다. 대상자에게 알림은 가지 않는다.');
end;
$$;


ALTER FUNCTION "public"."mcp_delete_schedule_survey"("p_survey_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_study_room_reservations"("p_room_id" "uuid", "p_student" "text", "p_start" "date", "p_end" "date", "p_period_ids" integer[] DEFAULT NULL::integer[], "p_reason" "text" DEFAULT NULL::"text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('studyroom.manage');
  v_room   public.study_rooms;
  v_stu    record;
  v_ids    uuid[];
  v_kept   integer;
  v_n      integer;
  v_reason text := mcp_private.opt_text(p_reason, 'reason', 200);
begin
  perform mcp_private.sr_require_teacher();
  select * into v_room from study_rooms where id = p_room_id;
  if not found then raise exception using errcode = 'P0002', message = '열람실을 찾을 수 없습니다.'; end if;
  select * into v_stu from mcp_private.sr_resolve_student(p_student);
  if not mcp_private.sr_can_manage_student(v_stu.grade, v_stu.class) then
    raise exception using errcode = '42501', message = format('%s 학생의 자습은 %s학년 부장·%s학년 %s반 담임만 지울 수 있습니다.', p_student, v_stu.grade, v_stu.grade, v_stu.class);
  end if;
  if p_start is null or p_end is null or p_start > p_end then raise exception using errcode = '22023', message = 'start ≤ end 인 두 날짜가 필요합니다.'; end if;

  select array_agg(s.id) filter (where not coalesce(s.is_attended, false) and s.attendance_status is null),
         count(*) filter (where coalesce(s.is_attended, false) or s.attendance_status is not null)
    into v_ids, v_kept
    from seat_reservations s
   where s.room_id = p_room_id and s.student_id = v_stu.profile_id and s.reservation_date between p_start and p_end
     and (p_period_ids is null or s.period_id = any(p_period_ids));

  if coalesce(p_check_only, true) or v_ids is null then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true, 'room', v_room.name,
      'student', format('%s-%s-%s', v_stu.grade, v_stu.class, v_stu.number), 'name', v_stu.name,
      'will_delete', coalesce(cardinality(v_ids), 0),
      'dates', (select jsonb_agg(distinct reservation_date) from seat_reservations where id = any(coalesce(v_ids, '{}'))),
      'kept_attended', nullif(v_kept, 0),
      'note', case when v_ids is null then '지울 신청이 없다' || case when v_kept > 0 then '(출석 처리된 신청은 먼저 출석 취소 clear 뒤에 지운다).' else '.' end
                   else '아직 지우지 않았다 — 지우면 보관함(list_study_room_trash)에 남아 되살릴 수 있다. 출석 처리된 신청은 지우지 않는다(먼저 출석 취소). 사용자에게 확인받은 뒤 check_only:false.' end));
  end if;

  insert into study_room_reservation_trash (reservation_id, reservation, student_id, room_id, seat_number, reservation_date, period_id, reason)
  select s.id, to_jsonb(s), s.student_id, s.room_id, s.seat_number, s.reservation_date, s.period_id, v_reason
    from seat_reservations s where s.id = any(v_ids);
  delete from seat_reservations where id = any(v_ids);
  get diagnostics v_n = row_count;
  if v_n <> cardinality(v_ids) then
    raise exception using errcode = '42501', message = '일부 신청을 지울 권한이 없습니다 — 아무것도 지우지 않았습니다.';
  end if;
  perform mcp_private.log_call(v_me, 'delete_study_room_reservations',
    jsonb_build_object('room_id', p_room_id, 'grade', v_stu.grade, 'class', v_stu.class, 'rows', v_n));
  return jsonb_strip_nulls(jsonb_build_object('saved', true, 'deleted', v_n, 'backed_up', v_n, 'kept_attended', nullif(v_kept, 0),
    'student', format('%s-%s-%s', v_stu.grade, v_stu.class, v_stu.number), 'room', v_room.name,
    'note', '보관함에 남겼다 — list_study_room_trash 로 찾아 restore_study_room_reservations 로 되살린다.'));
end;
$$;


ALTER FUNCTION "public"."mcp_delete_study_room_reservations"("p_room_id" "uuid", "p_student" "text", "p_start" "date", "p_end" "date", "p_period_ids" integer[], "p_reason" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_supervision_unavailability"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('supervision.mine');
  v_id uuid;
begin
  -- RLS 가 남의 행을 0행 삭제로 조용히 거른다 — 지워졌는지 행으로 확인한다(웹과 같다)
  delete from supervision_unavailability where id = p_id returning id into v_id;
  if v_id is null then raise exception using errcode = 'P0002', message = '지울 권한이 없거나 이미 지워졌습니다.'; end if;
  return jsonb_build_object('id', v_id, 'deleted', true);
end;
$$;


ALTER FUNCTION "public"."mcp_delete_supervision_unavailability"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_task"("p_task_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.manage');
  t public.task := mcp_private.wk_task(p_task_id);
  v_why text := mcp_private.wk_task_progress(p_task_id); v_n int;
begin
  if v_why is not null then
    raise exception using errcode = '22023', message = format('지우지 않았습니다 — %s. 그만둘 할 일이면 웹에서 취소로 바꾸세요.', v_why);
  end if;
  delete from task_workflow_node where task_id = p_task_id;
  delete from task where id = p_task_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception using errcode = '42501', message = '지우지 못했습니다(권한).'; end if;
  perform mcp_private.wk_renumber(t.event_id);
  perform mcp_private.log_call(v_me, 'delete_task', jsonb_build_object('task_id', p_task_id, 'title', t.title));
  return jsonb_build_object('deleted', true, 'task_id', p_task_id, 'work', mcp_private.wk_work_out(t.event_id));
end $$;


ALTER FUNCTION "public"."mcp_delete_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_work"("p_work_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.manage');
  w public.work := mcp_private.wk_managed_work(p_work_id);
  v_why text; v_n int;
begin
  select t.title || ' — ' || mcp_private.wk_task_progress(t.id) into v_why from task t
  where t.event_id = p_work_id and mcp_private.wk_task_progress(t.id) is not null limit 1;
  if v_why is not null then
    raise exception using errcode = '22023', message = format('지우지 않았습니다 — 진행 기록이 있습니다(%s). 끝난 업무는 update_work 로 status 를 completed·cancelled 로 바꾸세요.', v_why);
  end if;
  -- 흐름에 남는 빈 노드를 치운다(내가 바꿀 수 있는 흐름만 — 나머지는 FK 가 참조를 비운다)
  delete from task_workflow_node n where n.event_id = p_work_id or n.task_id in (select id from task where event_id = p_work_id);
  delete from work where id = p_work_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception using errcode = '42501', message = '지우지 못했습니다(권한).'; end if;
  perform mcp_private.log_call(v_me, 'delete_work', jsonb_build_object('work_id', p_work_id, 'name', w.name));
  return jsonb_build_object('deleted', true, 'work_id', p_work_id, 'name', w.name);
end $$;


ALTER FUNCTION "public"."mcp_delete_work"("p_work_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_workflow"("p_workflow_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('workflow.manage');
  f public.task_workflow := mcp_private.wf_editable(p_workflow_id);
  v_nodes int; v_n int;
begin
  select count(*) into v_nodes from public.task_workflow_node where workflow_id = f.id;
  delete from public.task_workflow where id = f.id;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception using errcode = '42501', message = '이 흐름을 지울 수 없습니다(만든 사람만).'; end if;
  perform mcp_private.log_call(v_me, 'delete_workflow', jsonb_build_object('workflow_id', f.id, 'name', f.name));
  return jsonb_build_object('deleted', true, 'workflow_id', f.id, 'name', f.name, 'nodes', v_nodes,
    'note', '흐름의 노드·연결만 지웠다 — 업무·할 일·작업은 그대로다.');
end;
$$;


ALTER FUNCTION "public"."mcp_delete_workflow"("p_workflow_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_disconnect_nodes"("p_workflow_id" "uuid", "p_from" "uuid", "p_to" "uuid", "p_relation" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('workflow.manage');
  f public.task_workflow := mcp_private.wf_editable(p_workflow_id);
  v_s uuid := mcp_private.wf_node(p_workflow_id, p_from); v_t uuid := mcp_private.wf_node(p_workflow_id, p_to); v_n int;
begin
  delete from task_workflow_edge e
  where e.workflow_id = p_workflow_id and e.source_node_id = v_s and e.target_node_id = v_t
    and (nullif(p_relation, '') is null or e.relation_type = p_relation);
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception using errcode = 'P0002', message = '그 연결이 없습니다(방향: from → to).'; end if;
  update task_workflow set updated_at = now() where id = p_workflow_id;
  perform mcp_private.log_call(v_me, 'disconnect_nodes', jsonb_build_object('workflow_id', p_workflow_id, 'removed', v_n));
  return jsonb_build_object('removed', v_n, 'workflow', mcp_private.wf_out(p_workflow_id));
end $$;


ALTER FUNCTION "public"."mcp_disconnect_nodes"("p_workflow_id" "uuid", "p_from" "uuid", "p_to" "uuid", "p_relation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_docgen_check_people"("p_teachers" "text"[], "p_students" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('docgen.fill');
begin
  return jsonb_build_object(
    'teacher', coalesce((
      select jsonb_agg(jsonb_build_object('name', n, 'matches', c))
      from (select n, (select count(*) from resource r where r.type in ('teacher', 'staff') and r.status = 'active' and r.name = n) c
            from unnest(coalesce(p_teachers, '{}')) n) s
      where c <> 1), '[]'::jsonb),
    'student', coalesce((
      select jsonb_agg(jsonb_build_object('name', n, 'matches', c))
      from (select n, (select count(*) from resource r where r.type = 'student' and r.status = 'active' and r.name = n) c
            from unnest(coalesce(p_students, '{}')) n) s
      where c <> 1), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."mcp_docgen_check_people"("p_teachers" "text"[], "p_students" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_docgen_create"("p_upload_id" "uuid", "p_title" "text", "p_description" "text", "p_template_name" "text", "p_spec" "jsonb", "p_public" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('docgen.create');
  v_u      jsonb := mcp_private.dg_my_upload(p_upload_id, false);
  v_title  text := btrim(coalesce(p_title, ''));
  v_tname  text := btrim(coalesce(nullif(btrim(coalesce(p_template_name, '')), ''), p_title, ''));
  v_desc   text := nullif(btrim(coalesce(p_description, '')), '');
  v_tid    uuid;
  v_aid    uuid;
  v_n      int;
begin
  if v_u is null then
    raise exception using errcode = 'P0002', message = '그 올리기를 찾지 못했습니다 (내가 start_template_upload 로 받은 upload_id 만).';
  end if;
  if not (v_u->>'uploaded')::boolean then
    raise exception using errcode = '22023', message = '아직 파일이 올라오지 않았습니다.';
  end if;
  if v_u ? 'action_id' then
    raise exception using errcode = '22023', message = '이 파일로는 이미 생성 방식을 만들었습니다.';
  end if;
  if v_title = '' or length(v_title) > 200 then
    raise exception using errcode = '22023', message = 'title 은 1~200자입니다.';
  end if;
  if length(v_tname) > 120 then v_tname := left(v_tname, 120); end if;
  if v_desc is not null and length(v_desc) > 4000 then
    raise exception using errcode = '22023', message = 'description 은 4000자까지입니다.';
  end if;
  if p_spec is null or jsonb_typeof(p_spec) <> 'object' or p_spec->>'specVersion' <> '1'
     or jsonb_typeof(p_spec->'targets') <> 'array' then
    raise exception using errcode = '22023', message = '스펙 모양이 아닙니다 (specVersion 1 · targets 배열).';
  end if;
  v_n := jsonb_array_length(p_spec->'targets');
  if v_n = 0 or v_n > 200 or length(p_spec::text) > 1000000 then
    raise exception using errcode = '22023', message = '채울 자리는 1~200개입니다.';
  end if;

  -- 양식(v1) — id 는 올리기 id 그대로(파일 경로가 이미 이 id 로 정해져 있다)
  insert into task_action_document_template (
    id, created_by, family_id, name, description, source_file_name, storage_path,
    mime_type, size_bytes, content_sha256, fields, spec)
  values (
    p_upload_id, auth.uid(), p_upload_id, v_tname, null, v_u->>'file_name', v_u->>'storage_path',
    'application/hwp+zip', (v_u->>'size_bytes')::bigint, v_u->>'content_sha256', '[]'::jsonb, p_spec)
  returning id into v_tid;

  insert into task_action (
    task_id, created_by, action_type, handler_version, title, description,
    execution_mode, verification_mode, config)
  values (
    null, auth.uid(), 'document.spec_fill', 1, v_title, v_desc, 'assisted', 'human_review',
    jsonb_build_object(
      'origin', 'docgen',
      'defaultTemplate', jsonb_build_object('id', v_tid, 'name', v_tname),
      'visibility', case when coalesce(p_public, false) then 'public' else 'private' end))
  returning id into v_aid;

  perform mcp_private.dg_mark_created(p_upload_id, v_tid, v_aid);
  perform mcp_private.log_call(v_me, 'create_document_generation',
    jsonb_build_object('action_id', v_aid, 'template_id', v_tid, 'title', v_title, 'targets', v_n));

  return jsonb_build_object(
    'action_id', v_aid, 'template_id', v_tid, 'title', v_title, 'template_name', v_tname, 'targets', v_n,
    'visibility', case when coalesce(p_public, false) then 'public' else 'private' end,
    'path', '/document-generation?entry=' || v_aid::text);
end;
$$;


ALTER FUNCTION "public"."mcp_docgen_create"("p_upload_id" "uuid", "p_title" "text", "p_description" "text", "p_template_name" "text", "p_spec" "jsonb", "p_public" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_docgen_list"("p_query" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('docgen.fill');
  v_q  text := nullif(btrim(coalesce(p_query, '')), '');
begin
  return coalesce((
    select jsonb_agg(row_to_json(x)::jsonb - 'sort_at' order by x.mine desc, x.sort_at desc)
    from (
      select a.id as action_id, a.title, a.description,
             a.created_by = auth.uid() as mine,
             coalesce(a.config->>'visibility', case when a.config->>'origin' = 'docgen' then 'private' end) as visibility,
             a.config->>'origin' as origin,
             a.config->'defaultTemplate'->>'name' as template_name,
             (select p.name from profiles p where p.id = a.created_by) as owner,
             (select count(*) from task_action_document d
               where d.action_id = a.id and d.created_by = auth.uid() and d.archived_at is null) as my_documents,
             a.updated_at as sort_at
      from task_action a
      where a.action_type = 'document.spec_fill'
        and a.archived_at is null
        and a.config ? 'defaultTemplate'
        and (v_q is null or a.title ilike '%' || v_q || '%' or coalesce(a.description, '') ilike '%' || v_q || '%')
      order by a.updated_at desc
      limit 100
    ) x), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."mcp_docgen_list"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_docgen_run_finish"("p_run_id" "uuid", "p_status" "text", "p_output_summary" "jsonb", "p_error" "text", "p_checks" "jsonb", "p_artifacts" "jsonb", "p_document" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('docgen.fill');
  v_run    task_action_run;
  v_prefix text := auth.uid()::text || '/runs/' || p_run_id::text || '/';
  v_doc    uuid;
  v_title  text;
begin
  select * into v_run from task_action_run r where r.id = p_run_id and r.created_by = auth.uid();
  if v_run.id is null then
    raise exception using errcode = 'P0002', message = '그 실행을 찾지 못했습니다.';
  end if;
  if p_status not in ('needs_review', 'failed') then
    raise exception using errcode = '22023', message = 'status 는 needs_review · failed 입니다.';
  end if;
  if exists (select 1 from jsonb_array_elements(coalesce(p_artifacts, '[]'::jsonb)) x
             where x->'locator'->>'bucket' <> 'task-work-documents' or left(x->'locator'->>'path', length(v_prefix)) <> v_prefix) then
    raise exception using errcode = '42501', message = '산출물은 내 실행 폴더에만 둘 수 있습니다.';
  end if;

  perform public.finalize_task_action_run(p_run_id, p_status, coalesce(p_output_summary, '{}'::jsonb), p_error,
    coalesce(p_checks, '[]'::jsonb), coalesce(p_artifacts, '[]'::jsonb));

  if p_status = 'needs_review' and p_document is not null and jsonb_typeof(p_document) = 'object' then
    v_title := btrim(coalesce(p_document->>'title', ''));
    if v_title = '' or length(v_title) > 200 then
      raise exception using errcode = '22023', message = '문서 제목은 1~200자입니다.';
    end if;
    v_doc := gen_random_uuid();
    -- 웹 createSpecDocument 와 같은 모양 — INSERT 정책(내 것 + 읽을 수 있는 양식)·계보 트리거가 그대로 검사한다
    insert into task_action_document (id, family_id, action_id, template_version_id, title, status,
                                      plan, knowledge, field_values, row_values, user_context)
    values (v_doc, v_doc, v_run.action_id, (p_document->>'template_version_id')::uuid, v_title, 'draft',
            coalesce(p_document->'plan', '{}'::jsonb), coalesce(p_document->'knowledge', '{}'::jsonb),
            coalesce(p_document->'field_values', '{}'::jsonb), coalesce(p_document->'row_values', '{}'::jsonb),
            nullif(btrim(coalesce(p_document->>'user_context', '')), ''));
  end if;

  perform mcp_private.log_call(v_me, 'create_document',
    jsonb_build_object('action_id', v_run.action_id, 'run_id', p_run_id, 'document_id', v_doc, 'status', p_status));
  return jsonb_strip_nulls(jsonb_build_object('run_id', p_run_id, 'document_id', v_doc, 'status', p_status));
end;
$$;


ALTER FUNCTION "public"."mcp_docgen_run_finish"("p_run_id" "uuid", "p_status" "text", "p_output_summary" "jsonb", "p_error" "text", "p_checks" "jsonb", "p_artifacts" "jsonb", "p_document" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_docgen_run_start"("p_action_id" "uuid", "p_snapshot" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('docgen.fill');
  v_run uuid;
begin
  if not exists (select 1 from task_action a where a.id = p_action_id and a.action_type = 'document.spec_fill' and a.archived_at is null) then
    raise exception using errcode = 'P0002', message = '그 생성 방식을 찾지 못했습니다.';
  end if;
  v_run := public.start_task_action_run(p_action_id, gen_random_uuid()::text, null,
    coalesce(p_snapshot, '{}'::jsonb) || jsonb_build_object('via', jsonb_build_object('channel', 'mcp', 'client_id', nullif(auth.jwt()->>'client_id', ''))));
  return v_run;
end;
$$;


ALTER FUNCTION "public"."mcp_docgen_run_start"("p_action_id" "uuid", "p_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_docgen_target"("p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('docgen.fill');
  v_a   task_action;
  v_t   task_action_document_template;
  v_pin uuid;
  v_fam uuid;
begin
  select * into v_a from task_action a
  where a.id = p_action_id and a.action_type = 'document.spec_fill' and a.archived_at is null;
  if v_a.id is null then
    raise exception using errcode = 'P0002', message = '그 생성 방식을 찾지 못했습니다 (list_document_generations 의 action_id 만 — 남의 비공개 생성 방식은 안 보인다).';
  end if;
  v_pin := nullif(v_a.config->'defaultTemplate'->>'id', '')::uuid;
  v_fam := nullif(v_a.config->'defaultTemplate'->>'familyId', '')::uuid;
  if v_pin is null then
    raise exception using errcode = '22023', message = '이 생성 방식에는 기본 양식이 없습니다 — 웹 문서 생성에서 양식을 먼저 정하세요.';
  end if;
  select * into v_t from task_action_document_template t where t.id = v_pin;
  -- 양식이 새 판으로 갈렸으면 같은 계열의 현재 판(웹 findPinned 와 같은 규칙)
  if v_t.id is null or v_t.archived_at is not null then
    select * into v_t from task_action_document_template t
    where t.family_id = coalesce(v_t.family_id, v_fam, v_pin) and t.archived_at is null
    order by t.version desc limit 1;
  end if;
  if v_t.id is null or v_t.spec is null or jsonb_typeof(v_t.spec->'targets') <> 'array' then
    raise exception using errcode = '22023', message = '이 생성 방식의 양식에 채울 자리(스펙)가 없습니다 — 웹에서 [채울 자리 고치기]로 먼저 정하세요.';
  end if;
  return jsonb_build_object(
    'action_id', v_a.id, 'title', v_a.title, 'mine', v_a.created_by = auth.uid(),
    'template_id', v_t.id, 'template_name', v_t.name, 'file_name', v_t.source_file_name,
    'storage_path', v_t.storage_path, 'spec', v_t.spec);
end;
$$;


ALTER FUNCTION "public"."mcp_docgen_target"("p_action_id" "uuid") OWNER TO "postgres";


