begin
  v_r := mcp_private.dg_new_upload(v_me, p_file_name);
  perform mcp_private.log_call(v_me, 'start_template_upload', jsonb_build_object('upload_id', v_r->'upload_id', 'file_name', v_r->'file_name'));
