ALTER FUNCTION "public"."mcp_docgen_upload_begin"("p_file_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_docgen_upload_read"("p_upload_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('docgen.create');
  v_u  jsonb := mcp_private.dg_my_upload(p_upload_id, true);
begin
  if v_u is null then
    raise exception using errcode = 'P0002', message = '그 올리기를 찾지 못했습니다 (내가 start_template_upload 로 받은 upload_id 만).';
  end if;
  if not (v_u->>'uploaded')::boolean then
    raise exception using errcode = '22023',
      message = case when (v_u->>'expires_at')::timestamptz < now()
        then '올리기 주소가 만료됐습니다(15분). start_template_upload 로 다시 받으세요.'
        else '아직 파일이 올라오지 않았습니다. 받은 curl 명령으로 먼저 올리세요.' end;
  end if;
  if v_u ? 'action_id' then
    raise exception using errcode = '22023', message = '이 파일로는 이미 생성 방식을 만들었습니다. 새로 만들려면 다시 올리세요.';
  end if;
  return v_u - 'storage_path';
end;
$$;


ALTER FUNCTION "public"."mcp_docgen_upload_read"("p_upload_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_document_file_target"("p_document_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('document.library');
  v_doc public.documents;
  v_bucket text;
begin
  if p_document_id is null then raise exception using errcode = '22023', message = 'document_id 가 필요합니다.'; end if;
  select * into v_doc from documents where id = p_document_id and not coalesce(is_hidden, false);
  if not found then raise exception using errcode = 'P0002', message = '문서를 찾을 수 없습니다.'; end if;
  perform mcp_private.log_call(v_me, 'get_document_file', jsonb_build_object('document_id', p_document_id));
  if v_doc.storage_path ~ '^https?://' then
    return jsonb_build_object('stored', case when coalesce((v_doc.meta->>'is_google_drive_file')::boolean, false) then 'drive' else 'link' end,
      'title', v_doc.title, 'link', v_doc.storage_path);
  end if;
  v_bucket := coalesce(nullif(v_doc.meta->>'storage_bucket', ''), 'documents');
  -- 서류함 버킷의 library/ (교직원이 읽는다) 또는 옛 «내 폴더»(<나>/) 만 — 다른 기능의 버킷은 그 기능 화면에서
  if v_bucket <> 'documents' or v_doc.storage_path like '%..%'
     or not (v_doc.storage_path like 'library/%' or split_part(v_doc.storage_path, '/', 1) = auth.uid()::text) then
    raise exception using errcode = 'P0002', message = '이 문서 파일은 이 연결로 받을 수 없습니다 — 웹 «서류함»에서 연다.';
  end if;
  return jsonb_build_object('stored', 'server', 'title', v_doc.title, 'path', v_doc.storage_path,
    'file_name', coalesce(nullif(v_doc.file_name, ''), nullif(v_doc.meta->>'original_filename', ''), v_doc.title));
end;
$$;


ALTER FUNCTION "public"."mcp_document_file_target"("p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_document_upload_begin"("p_file_name" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me   uuid := mcp_private.require_tool('document.library');
  v_name text := mcp_private.file_name_ok(p_file_name);
  v_path text;
  v_orph jsonb;
begin
  if v_name is null then raise exception using errcode = '22023', message = 'file_name 이 필요합니다(올릴 파일의 이름).'; end if;
  if not public.is_staff_teacher_or_admin(auth.uid()) then
    raise exception using errcode = '42501', message = '서류함에는 교직원만 올릴 수 있습니다.';
  end if;
  v_path := format('library/%s/%s_%s.%s', auth.uid(), (extract(epoch from clock_timestamp()) * 1000)::bigint,
                   gen_random_uuid(), mcp_private.file_ext(v_name));
  -- 행 없이 하루 넘은 내 객체 = 올리다 만 파일(웹은 행 만들기 실패 시 바로 지운다 — 하루면 진행 중인 올리기와 겹치지 않는다)
  perform set_config('mcp.read_storage', 'on', true);
  select coalesce(jsonb_agg(o.name), '[]'::jsonb) into v_orph
    from (select o.name from storage.objects o
           where o.bucket_id = 'documents' and o.name like 'library/' || auth.uid() || '/%'
             and o.created_at < now() - interval '1 day'
             and not exists (select 1 from documents d where d.storage_path = o.name)
           limit 50) o;
  perform set_config('mcp.read_storage', '', true);
  perform mcp_private.log_call(v_me, 'start_document_upload', jsonb_build_object('file_name', v_name));
  return jsonb_build_object('storage_path', v_path, 'file_name', v_name, 'mime', mcp_private.file_mime(v_name), 'orphans', v_orph);
end;
$$;


ALTER FUNCTION "public"."mcp_document_upload_begin"("p_file_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_finalize_club_applications"("p_club_year_id" "uuid", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := mcp_private.require_tool('club.manage'); v jsonb;
begin
  if not public.can_manage_club_year(p_club_year_id) then raise exception using errcode = '42501', message = '명단 확정은 지도교사·동아리 담당자가 합니다'; end if;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true,
      'accepted', (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('student', concat_ws('-', a->>'grade', a->>'class', a->>'number'), 'name', a->>'name',
                     'choice_rank', a->'choice_rank', 'will_skip', a->>'enrolled_elsewhere')))
                   from jsonb_array_elements(public.club_applications(p_club_year_id, null)) a where a->>'status' = 'accepted'),
      'next', '합격자를 사용자에게 보여 확인받은 뒤 check_only:false — 명단(club_member)에 들어가고 발급대장·대상 규칙·창체에 반영된다.');
  end if;
  v := public.club_finalize_applications(p_club_year_id, null);
  perform mcp_private.log_call(v_me, 'finalize_club_applications', jsonb_build_object('club_year_id', p_club_year_id, 'added', v->'added'));
  return v;
end $$;


