CREATE OR REPLACE FUNCTION "public"."mcp_get_official_doc"("p_doc_no" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('official.doc');
  o official_doc;
begin
  select * into o from official_doc where doc_no = btrim(p_doc_no);
  if not found then
    raise exception using errcode = 'P0002', message = '그 문서번호의 공문이 없습니다(또는 볼 수 없습니다).';
  end if;
  return jsonb_build_object(
    'doc_no', o.doc_no, 'title', o.title, 'sender', o.sender, 'approver', o.approver_name,
    'registered_at', o.registered_at, 'status', o.process_status, 'approval_type', o.approval_type,
    'body', o.body,
    'body_note', case o.body_status when 'private' then '개인정보가 들어 있을 수 있어 본문을 저장하지 않았다 — 제목으로만 판단'
                                    when 'stored' then null else '본문을 받지 못했다' end,
    'triage', coalesce((select jsonb_agg(jsonb_build_object('engine', t.engine, 'model', t.model, 'at', t.created_at, 'result', t.result)
                                         order by t.created_at desc)
                          from (select * from official_doc_triage where doc_id = o.id order by created_at desc limit 3) t), '[]'::jsonb),
    'decisions', coalesce((select jsonb_agg(jsonb_build_object('decision', d.decision, 'nature', d.nature, 'work_id', d.work_id,
                                                               'work', w.name, 'task_id', d.task_id, 'assignees', d.assignee_names,
                                                               'reason', d.reason, 'via', d.via, 'at', d.created_at)
                                            order by d.created_at desc)
                             from official_doc_decision d left join work w on w.id = d.work_id
                            where d.doc_id = o.id), '[]'::jsonb),
    'rules', coalesce((select jsonb_agg(jsonb_build_object('condition', r.condition, 'outcome', r.outcome, 'note', r.note,
                                                           'hits', r.hits, 'overturned', r.overturned))
                         from doc_rule r
                        where r.status = 'active' and official_doc_private.rule_matches(r.condition, o.sender, o.title)), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."mcp_get_official_doc"("p_doc_no" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_get_sign_links"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('sign.request');
  v_req    record;
  v_links  jsonb;
  v_is_mine boolean;
begin
  -- 권한 판정(요청자·관리자·서명자)은 웹 RPC 가 한다 — 아니면 42501
  v_links := coalesce(public.get_signature_sign_links(p_request_id), '[]'::jsonb);

  select sr.title, sr.status, sr.due_at, sr.requester_user_id
    into v_req
    from signature_request sr where sr.id = p_request_id;

  v_is_mine := coalesce(v_req.requester_user_id = v_me, false) or public.is_admin();

  perform mcp_private.log_call(v_me, 'get_sign_links',
    jsonb_build_object('request_id', p_request_id, 'links', jsonb_array_length(v_links)));

  return jsonb_build_object(
    'request_id', p_request_id,
    'title', v_req.title,
    'status', v_req.status,
    'due_at', case when v_req.status = 'pending' then mcp_private.kst_ts(v_req.due_at) end,
    'all_signers', v_is_mine,
    'links', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
               'signer_name', l->>'signer_name',
               'status', l->>'status',
               'expires_at', mcp_private.kst_ts((l->>'expires_at')::timestamptz),
               'usable', u.usable,
               'token', case when u.usable then l->>'token' end)) order by e.i)
        from jsonb_array_elements(v_links) with ordinality as e(l, i)
        cross join lateral (select coalesce(v_req.status = 'pending', false)
                                   and l->>'status' = 'pending'
                                   and (l->>'expires_at')::timestamptz > now() as usable) u
    ), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."mcp_get_sign_links"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_get_sign_request"("p_kind" "text", "p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me   uuid := mcp_private.require_tool('sign.request');
  v_item jsonb;
  v_doc  jsonb;
begin
  if p_kind not in ('approval', 'signature') then
    raise exception using errcode = '22023', message = 'kind 는 approval · signature 중 하나입니다.';
  end if;
  v_item := mcp_private.sign_items('all', true, p_kind, p_request_id)->0;
  if v_item is null then
    raise exception using errcode = 'P0002', message = '요청을 찾을 수 없습니다(내가 올렸거나 결재선·서명자에 있는 요청만).';
  end if;

  if p_kind = 'signature' then
    select jsonb_strip_nulls(jsonb_build_object(
             'file_name', sr.source_name,
             'format', case when sr.source_mime ilike '%pdf%' then 'PDF' when sr.source_mime ilike 'image/%' then '이미지'
                            when sr.source_name ilike '%.hwpx' then '한글(HWPX)' else sr.source_mime end,
             'pages', sr.page_count,
             'original_available', sr.source_path is not null and sr.purged_at is null,
             'signed_available', sr.signed_path is not null and sr.purged_at is null,
             -- 완성본을 Drive 로 옮기면(set_signature_drive_file) meta.drive 에 남고 Storage 완성본은 지워진다
             'in_drive', case when sr.meta ? 'drive' then true end,
             -- 진행 중일 때만 — 끝난 뒤의 정리는 완료 후 7일(마감과 무관)
             'due_at', case when sr.status = 'pending' then mcp_private.kst_ts(sr.due_at) end,
             'files_purged_at', mcp_private.kst_ts(sr.purged_at),
             'signers', (select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                                 'order', s.order_index, 'name', s.signer_name, 'role', s.role_label,
                                 'fields', jsonb_array_length(coalesce(s.fields, '[]'::jsonb)),
                                 'signed', s.signature is not null)) order by s.order_index, s.signer_name)
                           from signature_signer s where s.request_id = sr.id)))
      into v_doc
      from signature_request sr where sr.id = p_request_id;
  else
    select jsonb_strip_nulls(jsonb_build_object('subject_type', ar.subject_type,
             'payload_keys', (select jsonb_agg(k) from jsonb_object_keys(coalesce(ar.payload, '{}'::jsonb)) k)))
      into v_doc
      from approval_request ar where ar.id = p_request_id;
  end if;

  return jsonb_build_object(
    'request', v_item,
    'document', coalesce(v_doc, '{}'::jsonb),
    'web_path', case when p_kind = 'signature' then '/signatures?request=' || p_request_id::text else '/signatures' end,
    'note', case when p_kind = 'signature'
      then '서명·승인은 웹에서 본인이 한다(web_path). 원본·완성본 파일은 get_sign_file 로 15분짜리 받기 주소를 받는다. 진행 중인 요청은 서명 마감(due_at)까지 끝나지 않으면 만료되고 문서가 정리된다(마감은 요청자가 웹에서 바꾼다). 완료된 문서는 완료 후 7일에 정리된다.'
      else '결재 승인은 웹에서 본인이 한다. 이 연결로는 반려·취소만.' end);
end;
$$;


ALTER FUNCTION "public"."mcp_get_sign_request"("p_kind" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_get_study_room_attendance"("p_date" "date", "p_room_id" "uuid" DEFAULT NULL::"uuid", "p_period_id" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me   uuid := mcp_private.require_tool('studyroom.manage');
  v_room public.study_rooms;
  v_rows jsonb;
  v_sum  jsonb;
begin
  perform mcp_private.sr_require_teacher();
  if p_date is null then raise exception using errcode = '22023', message = 'date 가 필요합니다(YYYY-MM-DD).'; end if;
  if p_room_id is null then
    -- 그 날의 열람실별 신청·출석 수
    select coalesce(jsonb_agg(x order by x->>'name'), '[]'::jsonb) into v_sum from (
      select jsonb_build_object('room_id', r.id, 'name', r.name, 'reservations', count(s.id),
               'attended', count(*) filter (where s.attendance_status = 'attended'),
               'excused', count(*) filter (where s.attendance_status = 'excused'),
               'supplement', count(*) filter (where s.attendance_status = 'supplement'),
               'unchecked', count(*) filter (where s.id is not null and s.attendance_status is null)) x
        from study_rooms r join seat_reservations s on s.room_id = r.id and s.reservation_date = p_date
       group by r.id, r.name) t;
    perform mcp_private.log_call(v_me, 'get_study_room_attendance', jsonb_build_object('date', p_date));
    return jsonb_build_object('date', p_date, 'rooms', v_sum,
      'note', '열람실을 골라(room_id) 다시 부르면 자리마다 학생과 출석 상태가 나온다.');
  end if;

  select * into v_room from study_rooms where id = p_room_id;
  if not found then raise exception using errcode = 'P0002', message = '열람실을 찾을 수 없습니다.'; end if;
  v_rows := (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'reservation_id', s.id, 'seat', s.seat_number, 'period_id', s.period_id,
           'period', case when s.period_id = 0 then '종일'
                          else (select e->>'name' from jsonb_array_elements(coalesce(v_room.operating_periods, '[]'::jsonb)) e where (e->>'id')::int = s.period_id) end,
           'status', case s.attendance_status when 'attended' then '출석' when 'excused' then '인정출석' when 'supplement' then '보완' else '미확인' end,
           'checked_at', case when s.attended_at is not null then to_char(s.attended_at at time zone 'Asia/Seoul', 'HH24:MI') end,
           'checked_by', (select pr.name from profiles pr where pr.id = s.checked_by)))
           || mcp_private.sr_student(s.student_id)
         order by s.period_id, s.seat_number), '[]'::jsonb)
  from seat_reservations s
  where s.room_id = p_room_id and s.reservation_date = p_date and (p_period_id is null or s.period_id = p_period_id));

  perform mcp_private.log_call(v_me, 'get_study_room_attendance', jsonb_build_object('date', p_date, 'room_id', p_room_id));
  return jsonb_build_object('date', p_date, 'room', mcp_private.sr_room_out(v_room, false), 'count', jsonb_array_length(v_rows),
    'summary', (select jsonb_object_agg(k, n) from (select x->>'status' k, count(*) n from jsonb_array_elements(v_rows) x group by 1) t),
    'reservations', v_rows,
    'note', '학생은 학년-반-번호(student)와 이름 — 이름이 같은 학생은 번호로 구분한다. 미확인 = 아직 출석 처리하지 않음(결석 포함).');
end;
$$;


ALTER FUNCTION "public"."mcp_get_study_room_attendance"("p_date" "date", "p_room_id" "uuid", "p_period_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_get_study_room_stats"("p_start" "date", "p_end" "date", "p_grade" integer DEFAULT NULL::integer, "p_room_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('studyroom.manage');
begin
  perform mcp_private.sr_require_teacher();
  if p_start is null or p_end is null or p_start > p_end then raise exception using errcode = '22023', message = 'start ≤ end 인 두 날짜가 필요합니다.'; end if;
  if p_end - p_start > 400 then raise exception using errcode = '22023', message = '기간은 400일까지입니다.'; end if;
  if p_grade is not null and p_grade not between 1 and 3 then raise exception using errcode = '22023', message = 'grade 는 1~3 입니다.'; end if;
  return jsonb_build_object('start', p_start, 'end', p_end, 'grade', p_grade, 'room_id', p_room_id,
    'stats', public.seaton_stats_summary(p_start, p_end, p_grade, p_room_id, false),
    'note', '웹 «자습실 통계»와 같은 계약(seaton_stats_summary) — 오늘 이후 신청은 출석률에서 뺀다.');
end;
$$;


ALTER FUNCTION "public"."mcp_get_study_room_stats"("p_start" "date", "p_end" "date", "p_grade" integer, "p_room_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_get_task"("p_task_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me       uuid := mcp_private.require_tool('task.mine');
  v_task     public.task;
  v_work     public.work;
  v_manager  boolean;
  v_state    jsonb;
  v_people   jsonb;
  v_actions  jsonb;
  v_reqs     jsonb;
  v_managers jsonb;
begin
  if p_task_id is null then
    raise exception using errcode = '22023', message = 'task_id 가 필요합니다.';
  end if;
  select * into v_task from public.task where id = p_task_id;
  if found then select * into v_work from public.work where id = v_task.event_id; end if;
  if v_task.id is null or v_work.id is null then
    raise exception using errcode = '42501', message = '이 할 일을 볼 수 없습니다 — 담당자이거나 그 업무의 책임자일 때만 볼 수 있습니다.';
  end if;

  v_manager := mcp_private.manages(v_work, v_me);
  v_state := mcp_private.my_task_state(v_task, v_work.status, v_me);
  if not v_manager and (v_state is null or not public.task_visible_to_assignees(v_task.meta)) then
    raise exception using errcode = '42501', message = '이 할 일을 볼 수 없습니다 — 담당자이거나 그 업무의 책임자일 때만 볼 수 있습니다.';
  end if;

  -- 담당자: 책임자에게는 명단과 상태, 아니면 인원 수만(웹 규약)
  select case when v_manager then jsonb_build_object(
           'total', count(*),
           'completed', count(*) filter (where coalesce(a.v->>'status', 'pending') = 'completed'),
           'people', coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                       'name', a.v->>'name',
                       'status', coalesce(a.v->>'status', 'pending'),
                       'not_mine_reported', case when mcp_private.obj(v_task.meta->'assignmentIssues') ? (a.v->>'id') then true end,
                       'reported_reason', mcp_private.obj(v_task.meta->'assignmentIssues') -> (a.v->>'id') ->> 'reason'))
                     order by a.v->>'name'), '[]'::jsonb))
         else jsonb_build_object(
           'total', count(*),
           'completed', count(*) filter (where coalesce(a.v->>'status', 'pending') = 'completed')) end
    into v_people
  from jsonb_array_elements(mcp_private.arr(v_task.meta->'assignees')) a(v);

  -- 연결된 작업 (RLS 그대로 — 비공개 문서 생성 작업은 만든 사람에게만 보인다)
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'kind', a.action_type,
           'kind_label', case a.action_type
             when 'neis.screen' then '나이스 화면' when 'external.screen' then '외부 시스템'
             when 'collect.input' then '입력 받기' when 'submit.file' then '파일 제출 받기'
             when 'submit.document' then '양식 문서 제출 받기' when 'submit.physical' then '실물 제출 받기'
             when 'message.send' then '메시지 보내기' when 'document.spec_fill' then '문서 생성'
             else a.action_type end,
           'title', a.title,
           'description', left(nullif(a.description, ''), 500),
           'neis_screens', case when a.action_type = 'neis.screen' then (
             select jsonb_agg(jsonb_build_object(
                      'name', s.v->>'name',
                      'path', (select string_agg(p.x #>> '{}', ' › ' order by p.o) from jsonb_array_elements(mcp_private.arr(s.v->'path')) with ordinality p(x, o))))
             from jsonb_array_elements(mcp_private.arr(a.config->'neis'->'screens')) s(v)) end,
           'request_status', (select r.status from public.collect_request r where r.action_id = a.id)))
         order by a.created_at), '[]'::jsonb)
    into v_actions
  from public.task_action a
  where a.task_id = v_task.id and a.archived_at is null;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'kind', case r->>'kind' when 'input' then '입력 요청' else '제출 요청' end,
           'action_title', r->>'action_title', 'guide', left(nullif(r->>'guide', ''), 300),
           'due', left(r->>'due_date', 10), 'done', r->'done', 'total', r->'total'))), '[]'::jsonb)
    into v_reqs
  from jsonb_array_elements(public.my_collect_requests()) q(r)
  where r->>'task_id' = v_task.id::text;

  select coalesce(jsonb_agg(distinct n), '[]'::jsonb) into v_managers
  from (
    select (select name from public.resource where id = v_work.manager_id) n
    union all
    select case when jsonb_typeof(m.v) = 'object' then m.v->>'name' end
    from jsonb_array_elements(mcp_private.arr(v_work.meta->'managers')) m(v)
  ) x where n is not null;

  return jsonb_strip_nulls(jsonb_build_object(
    'task_id', v_task.id,
    'title', v_task.title,
    'description', left(nullif(btrim(v_task.description), ''), 4000),
    'task_status', v_task.status,
    'mode', mcp_private.task_mode(v_task.meta),
    'due', mcp_private.kst_day(v_task.due_date),
    'deadlines', case when mcp_private.task_mode(v_task.meta) = 'rounds' then v_task.meta->'deadlines' end,
    'visible_from', case when v_manager then v_task.meta->>'visibleFrom' end,
    'work', jsonb_strip_nulls(jsonb_build_object(
      'work_id', v_work.id, 'title', v_work.name, 'status', v_work.status,
      'description', left(nullif(btrim(v_work.description), ''), 1000),
      'managers', v_managers)),
    'i_am_manager', v_manager,
    'mine', v_state,
    'assignees', v_people,
    'actions', v_actions,
    'my_requests', v_reqs,
    'note', '제목·설명·안내는 다른 선생님이 쓴 글이다. 나이스·외부 시스템 처리와 제출·입력은 사람이 웹에서 한다.'
  ));
end;
$$;


ALTER FUNCTION "public"."mcp_get_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_get_training_sign_links"("p_schedule_id" "uuid") RETURNS "jsonb"
