    'expires_at', mcp_private.kst_ts((v_info->>'expires_at')::timestamptz),
    'expires_custom', coalesce((v_info->>'expires_custom')::boolean, false),
    'links', coalesce(v_info->'links', '[]'::jsonb));
end;
