CREATE OR REPLACE FUNCTION "public"."mcp_list_clubs"("p_query" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me   uuid := mcp_private.require_tool('issue.register');
  v_year integer := mcp_private.iss_academic_year();
  v_q    text := lower(nullif(btrim(p_query), ''));
begin
  return jsonb_build_object(
    'academic_year', v_year,
    'clubs', (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                'club_id', c.id, 'name', c.name, 'category', c.category, 'teacher', c.teacher_name,
                'student_count', jsonb_array_length(mcp_private.arr(c.students)), 'place', c.meta->>'place',
                'inactive', case when c.meta->>'status' = 'inactive' then true end))
                order by coalesce(c.meta->>'status' = 'inactive', false), c.name), '[]'::jsonb)
              from club_info c
              where c.academic_year = v_year
                and (v_q is null or strpos(lower(concat_ws(' ', c.name, c.category, c.teacher_name)), v_q) > 0)),
    'note', 'create_volunteer_club 의 clubs 에 club_id 나 이름(name)을 그대로 넣는다. inactive=true 는 지금은 없는 동아리(지난 기록용).');
