CREATE OR REPLACE FUNCTION "public"."mcp_list_code_projects"("p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('code.share');
  v_q     text := nullif(btrim(coalesce(p_query, '')), '');
  v_rows  jsonb;
begin
  select coalesce(jsonb_agg(mcp_private.code_out(p) order by p.updated_at desc), '[]'::jsonb) into v_rows
  from (select * from code_project p
        where p.owner_resource_id in (select public.current_actor_resource_ids())
          and (v_q is null or p.title ilike '%' || v_q || '%' or coalesce(p.description, '') ilike '%' || v_q || '%'
               or array_to_string(p.tags, ' ') ilike '%' || v_q || '%')
        order by p.updated_at desc limit least(greatest(coalesce(p_limit, 50), 1), 200)) p;
  return jsonb_build_object('count', jsonb_array_length(v_rows), 'projects', v_rows,
    'note', '내 프로젝트만 나온다. 다른 사람의 프로젝트는 링크(웹 주소 /code-share/<id>)의 id 로 get_code_project 를 부른다.');
end;
$$;


