  if not coalesce(p_check_only, true) then
    perform mcp_private.log_call(v_me, 'roll_over_clubs', jsonb_build_object('from', p_from, 'clubs', v->'clubs'));
  end if;
  return v || jsonb_build_object('next', case when coalesce(p_check_only, true) then '만들 동아리 수를 사용자에게 보여 확인받은 뒤 check_only:false.' end);
end $$;


ALTER FUNCTION "public"."mcp_roll_over_clubs"("p_from" integer, "p_carry_members" boolean, "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_budget_plan"("p_project_id" "uuid", "p_plan_id" "uuid" DEFAULT NULL::"uuid", "p_line_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_amount" bigint DEFAULT NULL::bigint, "p_planned_month" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_delete" boolean DEFAULT false, "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := mcp_private.require_tool('budget.manage');
  v_plan budget_plan_item;
  v_month date;
  v_year int;
  v_line_name text;
  v_after jsonb;
  v_id uuid;
begin
  perform mcp_private.bg_require_edit(p_project_id);
  select fiscal_year into v_year from budget_project where id = p_project_id;
  if p_plan_id is not null then
    select * into v_plan from budget_plan_item where id = p_plan_id and project_id = p_project_id;
    if v_plan.id is null then
      raise exception using errcode = 'P0002', message = '이 사업의 계획 항목이 아닙니다 — get_budget 의 plans[].id.';
    end if;
  elsif coalesce(p_delete, false) then
    raise exception using errcode = '22023', message = '지울 계획의 plan_id 가 필요합니다.';
  end if;
  if p_line_id is not null and not exists (select 1 from budget_line where id = p_line_id and project_id = p_project_id) then
    raise exception using errcode = '22023', message = '이 사업의 산출내역이 아닙니다 — get_budget 의 lines[].id.';
  end if;
  if p_plan_id is null and p_line_id is null then
    raise exception using errcode = '22023', message = '새 계획에는 line_id(산출내역)가 필요합니다.';
  end if;
  if p_planned_month is not null and p_planned_month <> '' then
    if p_planned_month !~ '^\d{4}-\d{2}$' then
      raise exception using errcode = '22023', message = 'planned_month 는 YYYY-MM 입니다.';
    end if;
    v_month := to_date(p_planned_month || '-01', 'YYYY-MM-DD');
  end if;
  if p_status is not null and p_status not in ('planned', 'in_order', 'done', 'cancelled') then
    raise exception using errcode = '22023', message = 'status 는 planned·in_order·done·cancelled 중 하나입니다.';
  end if;
  if p_amount is not null and p_amount < 0 then
    raise exception using errcode = '22023', message = 'amount 는 0 이상입니다.';
  end if;
  if p_title is not null and length(btrim(p_title)) not between 1 and 200 then
    raise exception using errcode = '22023', message = 'title 은 1~200자입니다.';
  end if;
  if p_plan_id is null and (p_title is null or p_amount is null) then
    raise exception using errcode = '22023', message = '새 계획에는 title 과 amount 가 필요합니다.';
  end if;

  select name into v_line_name from budget_line where id = coalesce(p_line_id, v_plan.line_id);
  v_after := jsonb_strip_nulls(jsonb_build_object(
    'line', v_line_name,
    'title', coalesce(btrim(p_title), v_plan.title),
    'amount', coalesce(p_amount, v_plan.amount),
    'planned_month', coalesce(to_char(v_month, 'YYYY-MM'), to_char(v_plan.planned_month, 'YYYY-MM')),
    'status', coalesce(p_status, v_plan.status, 'planned'),
    'note', coalesce(p_note, v_plan.note)));

  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true,
      'action', case when coalesce(p_delete, false) then 'delete' when p_plan_id is null then 'create' else 'update' end,
      'before', case when v_plan.id is not null then jsonb_build_object('title', v_plan.title, 'amount', v_plan.amount,
                  'planned_month', to_char(v_plan.planned_month, 'YYYY-MM'), 'status', v_plan.status) end,
      'after', case when not coalesce(p_delete, false) then v_after end,
      'warning', case when v_month is not null and (v_month < make_date(v_year, 3, 1) or v_month > make_date(v_year + 1, 2, 1))
                      then '회계연도(' || v_year || '.3 ~ ' || (v_year + 1) || '.2) 밖의 달입니다 — 그때는 이 예산을 쓸 수 없습니다.' end,
      'note', '아직 저장하지 않았다 — 사용자에게 보여 확인받은 뒤 check_only:false.'));
  end if;

  if coalesce(p_delete, false) then
    delete from budget_plan_item where id = p_plan_id;
    v_id := p_plan_id;
  elsif p_plan_id is null then
    insert into budget_plan_item (project_id, line_id, title, amount, planned_month, status, note, sort_order)
    values (p_project_id, p_line_id, btrim(p_title), p_amount, v_month, coalesce(p_status, 'planned'), nullif(btrim(coalesce(p_note, '')), ''),
            (select coalesce(max(sort_order), 0) + 1 from budget_plan_item where line_id = p_line_id))
    returning id into v_id;
  else
    update budget_plan_item set
      line_id = coalesce(p_line_id, line_id),
      title = coalesce(btrim(p_title), title),
      amount = coalesce(p_amount, amount),
      planned_month = case when p_planned_month = '' then null else coalesce(v_month, planned_month) end,
      status = coalesce(p_status, status),
      note = case when p_note is null then note else nullif(btrim(p_note), '') end
    where id = p_plan_id
    returning id into v_id;
  end if;
  perform mcp_private.log_call(v_me, 'save_budget_plan', jsonb_build_object('project_id', p_project_id, 'plan_id', v_id, 'delete', coalesce(p_delete, false)));
  return jsonb_build_object('saved', true, 'plan_id', v_id, 'figures', mcp_private.bg_totals(p_project_id));
end;
$_$;


ALTER FUNCTION "public"."mcp_save_budget_plan"("p_project_id" "uuid", "p_plan_id" "uuid", "p_line_id" "uuid", "p_title" "text", "p_amount" bigint, "p_planned_month" "text", "p_status" "text", "p_note" "text", "p_delete" boolean, "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_club"("p_club_year_id" "uuid", "p_patch" "jsonb", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('club.manage');
  v_before jsonb;
  v jsonb;
begin
  if jsonb_typeof(coalesce(p_patch, '{}'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'patch 는 객체입니다';
  end if;
  if p_club_year_id is not null then
    v_before := mcp_private.club_brief(public.club_get(p_club_year_id));
    if not (public.club_get(p_club_year_id)->>'can_manage')::boolean then
      raise exception using errcode = '42501', message = '이 동아리를 고칠 수 없습니다(지도교사·동아리 담당자만)';
    end if;
  elsif not public.is_club_manager() then
    raise exception using errcode = '42501', message = '동아리를 만들 수 있는 사람은 동아리 담당자뿐입니다';
  end if;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true, 'before', v_before, 'patch', p_patch,
      'next', '바뀔 내용을 사용자에게 보여 확인받은 뒤 check_only:false 로 다시 부른다.');
  end if;
  v := public.club_save(p_club_year_id, p_patch);
  perform mcp_private.log_call(v_me, 'save_club', jsonb_build_object('club_year_id', v->>'id', 'patch', p_patch));
  return jsonb_build_object('ok', true, 'club', mcp_private.club_brief(v));
end $$;


ALTER FUNCTION "public"."mcp_save_club"("p_club_year_id" "uuid", "p_patch" "jsonb", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_club_note"("p_club_year_id" "uuid", "p_student" "text", "p_body" "text", "p_period" "text" DEFAULT NULL::"text", "p_note_id" "uuid" DEFAULT NULL::"uuid", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := mcp_private.require_tool('club.manage');
  v_t text := regexp_replace(coalesce(p_student, ''), '\s', '', 'g');
  v_code text; v_label text; v jsonb;
begin
  if not public.can_manage_club_year(p_club_year_id) then
    raise exception using errcode = '42501', message = '누가기록은 지도교사·동아리 담당자가 씁니다';
  end if;
  select m.student_code, concat_ws(' ', concat_ws('-', m.grade, m.class_num, m.number), r.name) into v_code, v_label
  from public.club_member m left join public.resource r on r.id = m.student_resource_id
  where m.club_year_id = p_club_year_id and m.status = 'confirmed'
    and (concat_ws('-', m.grade, m.class_num, m.number) = v_t
         or (v_t ~ '^\d{5}$' and m.grade = substr(v_t, 1, 1)::int and m.class_num = substr(v_t, 2, 2)::int and m.number = substr(v_t, 4, 2)::int));
  if v_code is null then raise exception using errcode = '22023', message = '이 동아리의 확정 부원이 아닙니다 — ' || coalesce(p_student, ''); end if;
  if coalesce(btrim(p_body), '') = '' or length(p_body) > 4000 then raise exception using errcode = '22023', message = 'body 는 1~4000자입니다'; end if;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true, 'student', v_label, 'period', p_period, 'body', btrim(p_body),
      'next', '학생·내용을 사용자에게 보여 확인받은 뒤 check_only:false. 웹 누가기록에 «에이전트 초안»으로 표시된다.');
  end if;
  v := public.club_save_note(p_club_year_id, v_code, p_body, p_note_id, p_period, 'agent');
  perform mcp_private.log_call(v_me, 'save_club_note', jsonb_build_object('club_year_id', p_club_year_id, 'note_id', v->>'id'));
  return jsonb_build_object('ok', true, 'note_id', v->>'id', 'student', v_label);
end $_$;


ALTER FUNCTION "public"."mcp_save_club_note"("p_club_year_id" "uuid", "p_student" "text", "p_body" "text", "p_period" "text", "p_note_id" "uuid", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_club_recruit"("p_recruit_id" "uuid", "p_settings" "jsonb", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := mcp_private.require_tool('club.manage'); v jsonb;
begin
  if not public.is_club_manager() then raise exception using errcode = '42501', message = '편성은 동아리 담당자가 엽니다'; end if;
  if jsonb_typeof(coalesce(p_settings, '{}'::jsonb)) <> 'object' then raise exception using errcode = '22023', message = '설정은 객체입니다'; end if;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true,
      'before', case when p_recruit_id is not null then public.club_recruit_get(p_recruit_id) - 'clubs' - 'my_applications' end, 'patch', p_settings,
      'next', '회차(이름·대상 학년·지망 수·기간)를 사용자에게 보여 확인받은 뒤 check_only:false. 열리면 학생 «동아리» 화면에 지원 안내가 뜬다.');
  end if;
  v := public.club_recruit_save(p_recruit_id, p_settings);
  perform mcp_private.log_call(v_me, 'save_club_recruit', jsonb_build_object('recruit_id', v->>'id'));
  return v - 'my_applications';
end $$;


ALTER FUNCTION "public"."mcp_save_club_recruit"("p_recruit_id" "uuid", "p_settings" "jsonb", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_context"("p_key" "text", "p_title" "text" DEFAULT NULL::"text", "p_area" "text" DEFAULT NULL::"text", "p_summary" "text" DEFAULT NULL::"text", "p_structure" "jsonb" DEFAULT NULL::"jsonb", "p_contents" "text" DEFAULT NULL::"text", "p_locations" "jsonb" DEFAULT NULL::"jsonb", "p_maintenance" "text" DEFAULT NULL::"text", "p_body" "text" DEFAULT NULL::"text", "p_tags" "text"[] DEFAULT NULL::"text"[], "p_sensitivity" "text" DEFAULT NULL::"text", "p_kind" "text" DEFAULT NULL::"text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := mcp_private.require_tool('knowledge.context');
  v_old public.school_context;
  v_new public.school_context;
  v_loc jsonb;
begin
  if p_key is null or p_key !~ '^[a-z][a-z0-9_]{1,59}$' then
    raise exception using errcode = '22023', message = 'key 는 영문 소문자로 시작하는 영문 소문자·숫자·_ 2~60자입니다(예: exam_proctoring_rule).';
  end if;
  for v_loc in select * from jsonb_array_elements(coalesce(p_locations, '[]'::jsonb)) loop
    if jsonb_typeof(v_loc) <> 'object' or coalesce(v_loc->>'type', '') not in
       ('dataset', 'mcp_tool', 'table', 'web', 'docgen_context', 'document_folder', 'work_knowledge', 'neis', 'file', 'person', 'external') then
      raise exception using errcode = '22023',
        message = 'locations 는 [{type, ref, how}] — type 은 dataset · mcp_tool · table · web · docgen_context · document_folder · work_knowledge · neis · file · person · external 중 하나입니다.';
    end if;
  end loop;
  select * into v_old from school_context where key = p_key;
  if found then
    v_new := v_old;
    v_new.title := coalesce(p_title, v_old.title);           v_new.area := coalesce(p_area, v_old.area);
    v_new.summary := coalesce(p_summary, v_old.summary);     v_new.structure := coalesce(p_structure, v_old.structure);
    v_new.contents := coalesce(p_contents, v_old.contents);  v_new.locations := coalesce(p_locations, v_old.locations);
    v_new.maintenance := coalesce(p_maintenance, v_old.maintenance); v_new.body := coalesce(p_body, v_old.body);
    v_new.tags := coalesce(p_tags, v_old.tags);              v_new.sensitivity := coalesce(p_sensitivity, v_old.sensitivity);
    if not public.is_admin() and not (v_old.kind = 'note' and v_old.created_by = auth.uid()) then
      raise exception using errcode = '42501', message = '고칠 수 있는 것은 내가 쓴 맥락(note)뿐입니다 — 자료 위치(source)는 관리자가 고칩니다.';
    end if;
  else
    if p_title is null or p_area is null or p_summary is null then
      raise exception using errcode = '22023', message = '새 맥락에는 title · area · summary 가 필요합니다.';
    end if;
    if coalesce(p_kind, 'note') = 'source' and not public.is_admin() then
      raise exception using errcode = '42501', message = '자료 위치(source)는 관리자만 등록합니다 — 새로 알게 된 지식은 note 로 남깁니다.';
    end if;
    v_new.key := p_key; v_new.title := p_title; v_new.area := p_area; v_new.kind := coalesce(p_kind, 'note');
    v_new.summary := p_summary; v_new.structure := coalesce(p_structure, '[]'); v_new.contents := p_contents;
    v_new.locations := coalesce(p_locations, '[]'); v_new.maintenance := p_maintenance; v_new.body := p_body;
    v_new.tags := coalesce(p_tags, '{}'); v_new.sensitivity := coalesce(p_sensitivity, 'none'); v_new.status := 'active';
  end if;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true, 'action', case when v_old.id is null then 'create' else 'update' end,
      'before', case when v_old.id is not null then mcp_private.sc_entry(v_old, true) end,
      'after', jsonb_strip_nulls(jsonb_build_object('key', v_new.key, 'title', v_new.title, 'area', v_new.area, 'kind', v_new.kind,
        'summary', v_new.summary, 'structure', v_new.structure, 'contents', v_new.contents, 'locations', v_new.locations,
        'maintenance', v_new.maintenance, 'body', v_new.body, 'tags', to_jsonb(v_new.tags), 'sensitivity', v_new.sensitivity)),
      'note', '아직 저장하지 않았다 — 사용자에게 보여 확인받은 뒤 check_only:false. 학생·교직원 개인정보는 적지 않는다(모든 교직원이 본다).');
  end if;
  if v_old.id is null then
    insert into school_context (key, title, area, kind, summary, structure, contents, locations, maintenance, body, tags, sensitivity)
    values (v_new.key, btrim(v_new.title), v_new.area, v_new.kind, btrim(v_new.summary), v_new.structure, v_new.contents,
            v_new.locations, v_new.maintenance, v_new.body, v_new.tags, v_new.sensitivity);
  else
    update school_context set title = btrim(v_new.title), area = v_new.area, summary = btrim(v_new.summary), structure = v_new.structure,
      contents = v_new.contents, locations = v_new.locations, maintenance = v_new.maintenance, body = v_new.body,
      tags = v_new.tags, sensitivity = v_new.sensitivity
    where id = v_old.id;
  end if;
  perform mcp_private.log_call(v_me, 'save_context', jsonb_build_object('key', p_key, 'action', case when v_old.id is null then 'create' else 'update' end));
  return jsonb_build_object('saved', true, 'key', p_key, 'action', case when v_old.id is null then 'create' else 'update' end,
    'note', '모든 교직원의 에이전트가 list_contexts 로 이 맥락을 찾는다.');
end;
$_$;


ALTER FUNCTION "public"."mcp_save_context"("p_key" "text", "p_title" "text", "p_area" "text", "p_summary" "text", "p_structure" "jsonb", "p_contents" "text", "p_locations" "jsonb", "p_maintenance" "text", "p_body" "text", "p_tags" "text"[], "p_sensitivity" "text", "p_kind" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_doc_context"("p_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_body" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_hidden" boolean DEFAULT NULL::boolean, "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('knowledge.context');
  o public.docgen_context;
  v_title text;
  v_body text;
  v_cat text;
  v_hidden boolean;
  v_id uuid;
  v_links integer := 0;
begin
  if p_id is not null then
    select * into o from docgen_context where id = p_id;
    if not found then
      raise exception using errcode = 'P0002', message = '그 문서 맥락이 없습니다.';
    end if;
    if o.user_id is distinct from auth.uid() then
      raise exception using errcode = '42501', message = '고칠 수 있는 것은 내가 쓴 문서 맥락뿐입니다.';
    end if;
    select count(*) into v_links from docgen_context_spec_link l where l.context_id = o.id;
  elsif p_title is null or p_body is null then
    raise exception using errcode = '22023', message = '새 문서 맥락에는 title 과 body 가 필요합니다.';
  end if;
  v_title := coalesce(nullif(btrim(coalesce(p_title, '')), ''), o.title);
  v_body := coalesce(p_body, o.body);
  v_cat := case when p_category is null then o.category else nullif(btrim(p_category), '') end;
  v_hidden := coalesce(p_hidden, o.hidden, false);
  if char_length(btrim(coalesce(v_title, ''))) not between 1 and 120 then
    raise exception using errcode = '22023', message = '제목(title)은 1~120자입니다.';
  end if;
  if char_length(coalesce(v_body, '')) > 20000 or btrim(coalesce(v_body, '')) = '' then
    raise exception using errcode = '22023', message = '내용(body)은 1~20000자입니다.';
  end if;
  if v_cat is not null and char_length(v_cat) > 40 then
    raise exception using errcode = '22023', message = '분류(category)는 40자까지입니다.';
  end if;
  if v_hidden and v_links > 0 then
    raise exception using errcode = '22023', message = format('생성 방식 %s개에 연결되어 있어 숨길 수 없습니다 — 먼저 link_doc_context 로 연결을 풉니다.', v_links);
  end if;
  perform mcp_private.dc_no_personal(concat_ws(' ', v_title, v_cat, v_body));
  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true, 'action', case when o.id is null then 'create' else 'update' end,
      'before', case when o.id is not null then jsonb_strip_nulls(jsonb_build_object('title', o.title, 'category', o.category, 'hidden', o.hidden,
                  'length', char_length(o.body), 'body_start', left(o.body, 300))) end,
      'after', jsonb_strip_nulls(jsonb_build_object('title', btrim(v_title), 'category', v_cat, 'hidden', v_hidden,
                  'length', char_length(v_body), 'body_start', left(v_body, 300))),
      'body_changed', case when o.id is not null then o.body is distinct from v_body end,
      'visibility', case when v_hidden then '나만 본다'
                         when v_cat = '성취기준' then '교직원 모두 + 학생(분류 «성취기준»은 학생 탐구 설계가 읽는다)'
                         else '교직원 모두' end,
      'note', '아직 저장하지 않았다 — 사용자에게 보여 확인받은 뒤 check_only:false. 학생·교직원 개인정보는 적지 않는다.'));
  end if;
  if o.id is null then
    insert into docgen_context (user_id, title, body, category, hidden)
    values (auth.uid(), btrim(v_title), v_body, v_cat, v_hidden)
    returning id into v_id;
  else
    update docgen_context set title = btrim(v_title), body = v_body, category = v_cat, hidden = v_hidden
    where id = o.id returning id into v_id;
  end if;
  perform mcp_private.log_call(v_me, 'save_doc_context',
    jsonb_build_object('context_id', v_id, 'action', case when o.id is null then 'create' else 'update' end, 'length', char_length(v_body)));
  return jsonb_build_object('saved', true, 'id', v_id, 'action', case when o.id is null then 'create' else 'update' end,
    'note', '웹 «맥락 관리 › 문서 맥락»과 문서 생성의 «맥락 고르기»에 보인다.');
end;
$$;


ALTER FUNCTION "public"."mcp_save_doc_context"("p_id" "uuid", "p_title" "text", "p_body" "text", "p_category" "text", "p_hidden" boolean, "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_ipsi_analysis"("p_title" "text", "p_summary" "text", "p_news_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_video_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_perspective" "text" DEFAULT NULL::"text", "p_key_findings" "text"[] DEFAULT NULL::"text"[], "p_trends" "text"[] DEFAULT NULL::"text"[], "p_strategy" "text"[] DEFAULT NULL::"text"[], "p_cautions" "text"[] DEFAULT NULL::"text"[], "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('ipsi.hub');
  v_news uuid[] := array(select distinct x from unnest(coalesce(p_news_ids, '{}'::uuid[])) x);
  v_videos uuid[] := array(select distinct x from unnest(coalesce(p_video_ids, '{}'::uuid[])) x);
  v_found_news uuid[];
  v_found_videos uuid[];
  v_kf text[] := coalesce(mcp_private.ipsi_lines(p_key_findings, 'key_findings'), '{}');
  v_tr text[] := coalesce(mcp_private.ipsi_lines(p_trends, 'trends'), '{}');
  v_st text[] := coalesce(mcp_private.ipsi_lines(p_strategy, 'strategy'), '{}');
  v_ca text[] := coalesce(mcp_private.ipsi_lines(p_cautions, 'cautions'), '{}');
  v_id uuid;
begin
  perform mcp_private.ipsi_teacher();
  if length(btrim(coalesce(p_title, ''))) not between 1 and 200 then
    raise exception using errcode = '22023', message = 'title 은 1~200자입니다.';
  end if;
  if length(btrim(coalesce(p_summary, ''))) not between 1 and 4000 then
    raise exception using errcode = '22023', message = 'summary 는 1~4000자입니다.';
  end if;
  if length(coalesce(p_perspective, '')) > 1000 then
    raise exception using errcode = '22023', message = 'perspective 는 1000자까지입니다.';
  end if;
  if cardinality(v_news) + cardinality(v_videos) = 0 then
    raise exception using errcode = '22023', message = '근거 자료(news_ids·video_ids)가 하나 이상 있어야 합니다 — search_ipsi 의 id.';
  end if;
  if cardinality(v_news) + cardinality(v_videos) > 40 then
    raise exception using errcode = '22023', message = '근거 자료는 40건까지입니다.';
  end if;
  v_found_news := array(select n.id from educational_news n where n.id = any(v_news));
  v_found_videos := array(select v.id from educational_videos v where v.id = any(v_videos));
  if cardinality(v_found_news) <> cardinality(v_news) or cardinality(v_found_videos) <> cardinality(v_videos) then
    raise exception using errcode = 'P0002', message = format('없는 자료 id 가 있습니다(기사 %s건 · 영상 %s건) — search_ipsi 로 확인하세요.',
      cardinality(v_news) - cardinality(v_found_news), cardinality(v_videos) - cardinality(v_found_videos));
  end if;
  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true,
      'title', btrim(p_title), 'perspective', p_perspective, 'summary', btrim(p_summary),
      'key_findings', to_jsonb(v_kf), 'trends', to_jsonb(v_tr), 'strategy', to_jsonb(v_st), 'cautions', to_jsonb(v_ca),
      'sources', jsonb_build_object(
        'news', (select coalesce(jsonb_agg(n.title order by n.article_date desc nulls last), '[]'::jsonb) from educational_news n where n.id = any(v_news)),
        'videos', (select coalesce(jsonb_agg(v.title order by v.created_at desc), '[]'::jsonb) from educational_videos v where v.id = any(v_videos))),
      'note', '아직 저장하지 않았다 — 사용자에게 보여 확인받은 뒤 check_only:false. 저장하면 교직원 모두가 웹 «입시 정보 › AI 분석 › 이력»에서 본다.'));
  end if;
  insert into educational_news_compound_analysis
    (title, perspective, source_news_ids, source_video_ids, summary, key_findings, trends, strategy, cautions, raw_response, model, created_by)
  values (btrim(p_title), nullif(btrim(coalesce(p_perspective, '')), ''), v_news, v_videos, btrim(p_summary), v_kf, v_tr, v_st, v_ca,
          jsonb_build_object('via', 'mcp'), 'mcp-agent', auth.uid())
  returning id into v_id;
  perform mcp_private.log_call(v_me, 'save_ipsi_analysis',
    jsonb_build_object('analysis_id', v_id, 'news', cardinality(v_news), 'videos', cardinality(v_videos)));
  return jsonb_build_object('saved', true, 'id', v_id, 'note', '웹 «입시 정보 › AI 분석 › 이력»에 보인다.');
end;
$$;


ALTER FUNCTION "public"."mcp_save_ipsi_analysis"("p_title" "text", "p_summary" "text", "p_news_ids" "uuid"[], "p_video_ids" "uuid"[], "p_perspective" "text", "p_key_findings" "text"[], "p_trends" "text"[], "p_strategy" "text"[], "p_cautions" "text"[], "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_plan"("p_task_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_date" "date" DEFAULT NULL::"date", "p_start_time" "text" DEFAULT NULL::"text", "p_end_time" "text" DEFAULT NULL::"text", "p_priority" "text" DEFAULT NULL::"text", "p_goal_id" "text" DEFAULT NULL::"text", "p_memo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me    uuid := mcp_private.require_tool('planner.mine');
  v_old   academy_tasks;
  v_goal  uuid;
  v_start time;
  v_end   time;
  v_res   jsonb;
  v_row   academy_tasks;
begin
  perform mcp_private.pl_require_planner();
  if p_task_id is not null then
    v_old := mcp_private.pl_my_task(p_task_id);
  elsif nullif(btrim(p_title), '') is null or p_date is null then
    raise exception using errcode = '22023', message = '새 계획에는 title 과 date 가 필요합니다.';
  end if;
  if p_priority is not null and p_priority not in ('high', 'medium', 'low') then
    raise exception using errcode = '22023', message = 'priority 는 high · medium · low 중 하나입니다.';
  end if;

  v_goal := case when p_goal_id is null then v_old.related_goal_id
                 when btrim(p_goal_id) = '' then null
                 when btrim(p_goal_id) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then btrim(p_goal_id)::uuid
                 else null end;
  if p_goal_id is not null and btrim(p_goal_id) <> '' and v_goal is null then
    raise exception using errcode = '22023', message = 'goal_id 는 list_planner_goals 의 goal_id 입니다(비우기 = 빈 글자).';
  end if;
  v_start := mcp_private.pl_time(p_start_time, v_old.start_time, 'start_time');
  v_end := mcp_private.pl_time(p_end_time, v_old.end_time, 'end_time');

  v_res := public.academy_dormitory_write('save_task', jsonb_strip_nulls(jsonb_build_object(
    'id', v_old.id,
    'title', coalesce(nullif(btrim(p_title), ''), v_old.title),
    'task_date', coalesce(p_date, v_old.task_date),
    'start_time', mcp_private.pl_hhmm(v_start),
    'end_time', mcp_private.pl_hhmm(v_end),
    'priority', coalesce(p_priority, v_old.priority, 'medium'),
    'related_goal_id', v_goal,
    'memo', case when p_memo is null then v_old.memo else nullif(btrim(p_memo), '') end)));

  select * into v_row from academy_tasks where id = (v_res->>'id')::uuid;
  perform mcp_private.log_call(v_me, 'save_plan', jsonb_build_object('task_id', v_row.id, 'new', p_task_id is null));
  return mcp_private.pl_task_out(v_row) || jsonb_build_object('created', p_task_id is null);
end;
$_$;


ALTER FUNCTION "public"."mcp_save_plan"("p_task_id" "uuid", "p_title" "text", "p_date" "date", "p_start_time" "text", "p_end_time" "text", "p_priority" "text", "p_goal_id" "text", "p_memo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_plan_reflection"("p_task_id" "uuid", "p_comment" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('planner.mine');
  v_old academy_tasks;
  v_row academy_tasks;
begin
  perform mcp_private.pl_require_planner();
  v_old := mcp_private.pl_my_task(p_task_id);
  if p_comment is null or length(p_comment) > 2000 then
    raise exception using errcode = '22023', message = 'comment(돌아보기, 2000자까지)를 주세요 — 빈 글자 = 지우기.';
  end if;
  perform public.academy_dormitory_write('save_feedback', jsonb_build_object('id', v_old.id, 'comment', p_comment));
  select * into v_row from academy_tasks where id = v_old.id;
  perform mcp_private.log_call(v_me, 'save_plan_reflection', jsonb_build_object('task_id', v_row.id));
  return mcp_private.pl_task_out(v_row);
end;
$$;


ALTER FUNCTION "public"."mcp_save_plan_reflection"("p_task_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_planner_goal"("p_goal_id" "uuid" DEFAULT NULL::"uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_horizon" "text" DEFAULT NULL::"text", "p_parent_goal_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me     uuid := mcp_private.require_tool('planner.mine');
  v_old    academy_user_goals;
  v_parent text;
  v_res    jsonb;
  v_row    academy_user_goals;
begin
  perform mcp_private.pl_require_planner();
  if p_goal_id is not null then
    v_old := mcp_private.pl_my_goal(p_goal_id);
  elsif nullif(btrim(p_title), '') is null then
    raise exception using errcode = '22023', message = '새 목표에는 title 이 필요합니다.';
  end if;
  if p_horizon is not null and p_horizon not in ('long', 'short') then
    raise exception using errcode = '22023', message = 'horizon 은 long(장기) · short(단기) 중 하나입니다.';
  end if;
  if p_parent_goal_id is not null and btrim(p_parent_goal_id) <> ''
     and btrim(p_parent_goal_id) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception using errcode = '22023', message = 'parent_goal_id 는 장기 목표의 goal_id 입니다(풀기 = 빈 글자).';
  end if;
  v_parent := case when p_parent_goal_id is null then v_old.parent_goal_id::text else nullif(btrim(p_parent_goal_id), '') end;

  v_res := public.academy_dormitory_write('save_goal', jsonb_strip_nulls(jsonb_build_object(
    'id', v_old.id,
    'title', coalesce(nullif(btrim(p_title), ''), v_old.title),
    'description', case when p_description is null then v_old.description else nullif(btrim(p_description), '') end,
    'horizon', coalesce(p_horizon, v_old.horizon, 'short'),
    'is_completed', v_old.is_completed)) || jsonb_build_object('parent_goal_id', coalesce(v_parent, '')));

  select * into v_row from academy_user_goals where id = (v_res->>'id')::uuid;
  perform mcp_private.log_call(v_me, 'save_planner_goal', jsonb_build_object('goal_id', v_row.id, 'new', p_goal_id is null));
  return mcp_private.pl_goal_out(v_row) || jsonb_build_object('created', p_goal_id is null);
end;
$_$;


ALTER FUNCTION "public"."mcp_save_planner_goal"("p_goal_id" "uuid", "p_title" "text", "p_description" "text", "p_horizon" "text", "p_parent_goal_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_purchase_order_line"("p_batch_id" "uuid" DEFAULT NULL::"uuid", "p_line_id" "uuid" DEFAULT NULL::"uuid", "p_name" "text" DEFAULT NULL::"text", "p_spec" "text" DEFAULT NULL::"text", "p_unit_price" numeric DEFAULT NULL::numeric, "p_qty" numeric DEFAULT NULL::numeric, "p_usage_period" "text" DEFAULT NULL::"text", "p_vendor" "text" DEFAULT NULL::"text", "p_url" "text" DEFAULT NULL::"text", "p_payment_method" "text" DEFAULT NULL::"text", "p_budget_item" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_clear" "text"[] DEFAULT NULL::"text"[], "p_link" "jsonb" DEFAULT NULL::"jsonb", "p_unlink" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('purchase.request');
  v_line   public.purchase_order_lines%rowtype;
  v_batch  public.purchase_order_batches%rowtype;
  v_clear  text[] := coalesce(p_clear, '{}');
  v_bad    text[];
  v_name   text := mcp_private.pr_short_text(p_name, 'name', 200);
  v_spec   text := mcp_private.pr_short_text(p_spec, 'spec', 500);
  v_period text := mcp_private.pr_short_text(p_usage_period, 'usage_period', 200);
  v_vendor text := mcp_private.pr_short_text(p_vendor, 'vendor', 200);
  v_url    text := mcp_private.pr_short_text(p_url, 'url', 2000);
  v_pay    text := mcp_private.pr_short_text(p_payment_method, 'payment_method', 200);
  v_budget text := mcp_private.pr_short_text(p_budget_item, 'budget_item', 200);
  v_note   text := mcp_private.pr_short_text(p_note, 'note', 2000);
  v_el     jsonb;
  v_req    uuid;
  v_row    text;
  v_missing text[] := '{}';
  v_linked integer := 0;
  v_moved  integer := 0;
  v_unlinked integer := 0;
  v_n      integer;
  v_created boolean := false;
  v_sort   integer;
begin
  if p_line_id is null and p_batch_id is null then
    raise exception using errcode = '22023', message = '새 품의 품목은 batch_id, 고치기는 line_id 가 필요합니다 (list_purchase_orders).';
  end if;
  if p_line_id is not null and p_batch_id is not null then
    raise exception using errcode = '22023', message = 'batch_id 와 line_id 중 하나만 보냅니다 — 만들기는 batch_id, 고치기는 line_id.';
  end if;
  select coalesce(array_agg(x), '{}') into v_bad from unnest(v_clear) x
   where x not in ('spec', 'unit_price', 'qty', 'usage_period', 'vendor', 'url', 'payment_method', 'budget_item', 'note');
  if cardinality(v_bad) > 0 then
    raise exception using errcode = '22023', message = format('clear 에 지울 수 없는 칸이 있습니다: %s (name 은 지울 수 없다).', array_to_string(v_bad, ', '));
  end if;
  if p_unit_price is not null and p_unit_price < 0 then
    raise exception using errcode = '22023', message = 'unit_price 는 0 이상입니다.';
  end if;
  if p_qty is not null and p_qty < 0 then
    raise exception using errcode = '22023', message = 'qty 는 0 이상입니다.';
  end if;
  if p_link is not null and (jsonb_typeof(p_link) <> 'array' or jsonb_array_length(p_link) > 100) then
    raise exception using errcode = '22023', message = 'link 는 {request_id,row_id} 배열(100개까지)입니다.';
  end if;
  if p_unlink is not null and (jsonb_typeof(p_unlink) <> 'array' or jsonb_array_length(p_unlink) > 100) then
    raise exception using errcode = '22023', message = 'unlink 는 {request_id,row_id} 배열(100개까지)입니다.';
  end if;

  if p_line_id is null then
    -- 만들기
    select * into v_batch from purchase_order_batches where id = p_batch_id;
    if v_batch.id is null then
      raise exception using errcode = 'P0002', message = '품의 차수를 찾을 수 없습니다.';
    end if;
    perform mcp_private.pr_require_manager(v_batch.page_id);
    if v_name is null or v_name = '' then
      raise exception using errcode = '22023', message = '새 품의 품목에는 name(품명)이 필요합니다.';
    end if;
    select coalesce(max(sort_order) + 1, 0), count(*) into v_sort, v_n from purchase_order_lines where batch_id = v_batch.id;
    if v_n >= 300 then
      raise exception using errcode = '22023', message = '한 차수의 품의 품목은 300개까지입니다.';
    end if;
    insert into purchase_order_lines (batch_id, page_id, sort_order, name, spec, unit_price, qty, usage_period, vendor, url, payment_method, budget_item, note)
    values (v_batch.id, v_batch.page_id, v_sort, v_name, nullif(v_spec, ''), p_unit_price, p_qty, nullif(v_period, ''), nullif(v_vendor, ''),
            nullif(v_url, ''), nullif(v_pay, ''), nullif(v_budget, ''), nullif(v_note, ''))
    returning * into v_line;
    v_created := true;
  else
    -- 고치기
    select * into v_line from purchase_order_lines where id = p_line_id;
    if v_line.id is null then
      raise exception using errcode = 'P0002', message = '품의 품목을 찾을 수 없습니다.';
    end if;
    perform mcp_private.pr_require_manager(v_line.page_id);
    select * into v_batch from purchase_order_batches where id = v_line.batch_id;
    if v_name is not null and v_name = '' then
      raise exception using errcode = '22023', message = 'name 은 비울 수 없습니다.';
    end if;
    update purchase_order_lines set
      name = coalesce(v_name, name),
      spec = case when 'spec' = any(v_clear) then null when v_spec is null then spec else nullif(v_spec, '') end,
      unit_price = case when 'unit_price' = any(v_clear) then null else coalesce(p_unit_price, unit_price) end,
      qty = case when 'qty' = any(v_clear) then null else coalesce(p_qty, qty) end,
      usage_period = case when 'usage_period' = any(v_clear) then null when v_period is null then usage_period else nullif(v_period, '') end,
      vendor = case when 'vendor' = any(v_clear) then null when v_vendor is null then vendor else nullif(v_vendor, '') end,
      url = case when 'url' = any(v_clear) then null when v_url is null then url else nullif(v_url, '') end,
      payment_method = case when 'payment_method' = any(v_clear) then null when v_pay is null then payment_method else nullif(v_pay, '') end,
      budget_item = case when 'budget_item' = any(v_clear) then null when v_budget is null then budget_item else nullif(v_budget, '') end,
      note = case when 'note' = any(v_clear) then null when v_note is null then note else nullif(v_note, '') end
    where id = v_line.id
    returning * into v_line;
    if v_line.id is null then
      raise exception using errcode = '42501', message = '수정 권한이 없습니다.';
    end if;
  end if;

  -- 신청 품목 연결(옮기기 포함) — 같은 페이지의 신청, 지워지지 않은 행만
  if p_link is not null then
    for v_el in select * from jsonb_array_elements(p_link) loop
      begin
        v_req := (v_el ->> 'request_id')::uuid;
      exception when others then
        raise exception using errcode = '22023', message = 'link 의 request_id 는 uuid 입니다.';
      end;
      v_row := nullif(btrim(coalesce(v_el ->> 'row_id', '')), '');
      if v_req is null or v_row is null then
        raise exception using errcode = '22023', message = 'link 의 각 항목에 request_id 와 row_id 가 필요합니다.';
      end if;
      if not exists (
        select 1 from purchase_requests r, jsonb_array_elements(mcp_private.arr(r.items)) e
         where r.id = v_req and r.page_id = v_line.page_id and e ->> 'id' = v_row
      ) then
        v_missing := v_missing || (v_req::text || '/' || v_row);
        continue;
      end if;
      if exists (select 1 from purchase_order_line_items where request_id = v_req and row_id = v_row and line_id <> v_line.id) then
        v_moved := v_moved + 1;
      end if;
      insert into purchase_order_line_items (line_id, page_id, request_id, row_id)
      values (v_line.id, v_line.page_id, v_req, v_row)
      on conflict (request_id, row_id) do update set line_id = excluded.line_id;
      v_linked := v_linked + 1;
    end loop;
    if cardinality(v_missing) > 0 then
      raise exception using errcode = '22023',
        message = format('이 페이지에 없는 신청 품목입니다: %s (list_purchase_orders 의 request_id/row_id).', array_to_string(v_missing, ', '));
    end if;
  end if;

  if p_unlink is not null then
    for v_el in select * from jsonb_array_elements(p_unlink) loop
      begin
        v_req := (v_el ->> 'request_id')::uuid;
      exception when others then
        raise exception using errcode = '22023', message = 'unlink 의 request_id 는 uuid 입니다.';
      end;
      delete from purchase_order_line_items
       where line_id = v_line.id and request_id = v_req and row_id = btrim(coalesce(v_el ->> 'row_id', ''));
      get diagnostics v_n = row_count;
      v_unlinked := v_unlinked + v_n;
    end loop;
  end if;

  perform mcp_private.log_call(v_me, 'save_purchase_order_line',
    jsonb_build_object('page_id', v_line.page_id, 'line_id', v_line.id, 'created', v_created, 'linked', v_linked, 'unlinked', v_unlinked));

  return jsonb_build_object(
    case when v_created then 'created' else 'updated' end, true,
    'line_id', v_line.id, 'batch_id', v_line.batch_id, 'batch', v_batch.title,
    'line', jsonb_strip_nulls(jsonb_build_object('name', v_line.name, 'spec', v_line.spec, 'unit_price', v_line.unit_price, 'qty', v_line.qty,
      'amount', case when v_line.unit_price is not null and v_line.qty is not null then v_line.unit_price * v_line.qty end,
      'usage_period', v_line.usage_period, 'vendor', v_line.vendor, 'url', v_line.url,
      'payment_method', v_line.payment_method, 'budget_item', v_line.budget_item, 'note', v_line.note)),
    'linked', v_linked, 'moved_from_other_lines', v_moved, 'unlinked', v_unlinked,
    'linked_items_now', (select count(*) from purchase_order_line_items where line_id = v_line.id),
    'note', concat_ws(' ',
      '수량·단가는 자동으로 더하지 않는다 — 연결한 신청 품목의 개수·가격을 보고 qty·unit_price 를 직접 맞춘다.',
      case when v_batch.status <> 'draft' then format('⚠️ 이 차수는 이미 «%s» 라 연결한 품목의 상태가 자동으로 바뀌지 않는다 — 필요하면 set_purchase_order_status 를 다시 부른다.', mcp_private.pr_batch_label(v_batch.status)) end));
end;
$$;


ALTER FUNCTION "public"."mcp_save_purchase_order_line"("p_batch_id" "uuid", "p_line_id" "uuid", "p_name" "text", "p_spec" "text", "p_unit_price" numeric, "p_qty" numeric, "p_usage_period" "text", "p_vendor" "text", "p_url" "text", "p_payment_method" "text", "p_budget_item" "text", "p_note" "text", "p_clear" "text"[], "p_link" "jsonb", "p_unlink" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_student_memo"("p_date" "date", "p_period" integer, "p_student" "text", "p_content" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me      uuid := mcp_private.require_tool('timetable.memo');
  v_term    record;
  v_lesson  public.teacher_timetable;
  v_name    text := mcp_private.me_name(v_me);
  v_dow     integer;
  v_who     record;
  v_stu     record;
  v_content text := btrim(coalesce(p_content, ''));
begin
  if p_date is null then raise exception using errcode = '22023', message = 'date 가 필요합니다.'; end if;
  if char_length(v_content) > 2000 then raise exception using errcode = '22023', message = '메모는 2000자까지입니다.'; end if;
  v_dow := extract(isodow from p_date)::int;
  select * into v_term from mcp_private.current_term();
  v_lesson := mcp_private.tt_my_lesson(v_me, v_dow, mcp_private.check_period(p_period));
  select * into v_who from mcp_private.parse_student(p_student);

  select s.* into v_stu
  from public.get_section_students(v_name, v_dow, p_period, v_term.academic_year, v_term.semester) s
  where s.grade = v_who.grade and s.class_num = v_who.class_num and s.number = v_who.num
  limit 1;
  if v_stu.student_code is null then
    raise exception using errcode = 'P0002',
      message = format('%s 학생은 %s요일 %s교시 내 수업(%s)의 학생이 아닙니다 — list_lesson_students 로 확인하세요.',
                       p_student, mcp_private.dow_name(v_dow), p_period, v_lesson.subject_name);
  end if;

  if v_content = '' then
    delete from class_student_memos
    where student_code = v_stu.student_code and year = v_term.academic_year and subject = v_lesson.subject_name
      and created_by = auth.uid() and day_of_week = v_dow and period = p_period and memo_date = p_date;
  else
    insert into class_student_memos (student_code, student_name, year, subject, teacher_name, grade, class_num,
                                     day_of_week, period, memo_date, content, created_by)
    values (v_stu.student_code, v_stu.student_name, v_term.academic_year, v_lesson.subject_name, v_name, v_stu.grade, v_stu.class_num,
            v_dow, p_period, p_date, v_content, auth.uid())
    on conflict (student_code, year, subject, created_by, day_of_week, period, memo_date)
    do update set content = excluded.content, updated_at = now();
  end if;

  perform mcp_private.log_call(v_me, 'save_student_memo',
    jsonb_build_object('date', p_date, 'period', p_period, 'student', format('%s-%s-%s', v_who.grade, v_who.class_num, v_who.num), 'deleted', v_content = ''));

  return jsonb_build_object('date', p_date, 'period', p_period, 'student', format('%s-%s-%s', v_who.grade, v_who.class_num, v_who.num),
                            'lesson', v_lesson.subject_name, case when v_content = '' then 'deleted' else 'saved' end, true);
end;
$$;


ALTER FUNCTION "public"."mcp_save_student_memo"("p_date" "date", "p_period" integer, "p_student" "text", "p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_timetable_memo"("p_date" "date", "p_period" integer, "p_content" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me      uuid := mcp_private.require_tool('timetable.memo');
  v_content text := btrim(coalesce(p_content, ''));
  v_period  integer := mcp_private.check_period(p_period);
  v_row     public.teacher_memo;
begin
  if p_date is null then raise exception using errcode = '22023', message = 'date 가 필요합니다.'; end if;
  if char_length(v_content) > 2000 then raise exception using errcode = '22023', message = '메모는 2000자까지입니다.'; end if;

  if v_content = '' then
    delete from teacher_memo where resource_id = v_me and memo_date = p_date and period = v_period;
    return jsonb_build_object('date', p_date, 'period', v_period, 'deleted', found);
  end if;

  insert into teacher_memo (resource_id, memo_date, period, content)
  values (v_me, p_date, v_period, v_content)
  on conflict (resource_id, memo_date, period) do update set content = excluded.content, updated_at = now()
  returning * into v_row;
  return jsonb_build_object('date', v_row.memo_date, 'period', v_row.period, 'content', v_row.content, 'saved', true);
end;
$$;


ALTER FUNCTION "public"."mcp_save_timetable_memo"("p_date" "date", "p_period" integer, "p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_work_insight"("p_work_id" "uuid", "p_summary" "text", "p_suggestions" "jsonb" DEFAULT NULL::"jsonb", "p_instruction" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.run');
  w public.work := mcp_private.wk_managed_work(p_work_id);
  v_sugg jsonb := '[]'::jsonb; s jsonb; v_task uuid; v_id bigint;
begin
  if p_summary is null or btrim(p_summary) = '' or length(p_summary) > 2000 then
    raise exception using errcode = '22023', message = 'summary 는 1~2000자입니다.';
  end if;
  if p_suggestions is not null and jsonb_typeof(p_suggestions) <> 'array' then
    raise exception using errcode = '22023', message = 'suggestions 는 [{text, task_id?, basis?}] 배열입니다.';
  end if;
  if jsonb_array_length(coalesce(p_suggestions, '[]')) > 20 then
    raise exception using errcode = '22023', message = '제안은 20개까지입니다.';
  end if;
  for s in select * from jsonb_array_elements(coalesce(p_suggestions, '[]')) loop
    if jsonb_typeof(s) <> 'object' or btrim(coalesce(s->>'text', '')) = '' or length(s->>'text') > 500 or length(coalesce(s->>'basis', '')) > 500 then
      raise exception using errcode = '22023', message = '제안마다 text(1~500자)가 필요하고 basis 는 500자까지입니다.';
    end if;
    v_task := null;
    if coalesce(s->>'task_id', '') <> '' then
      select id into v_task from public.task where id::text = s->>'task_id' and event_id = w.id;
      if v_task is null then raise exception using errcode = '22023', message = format('task_id %s 은(는) 이 업무의 할 일이 아닙니다.', s->>'task_id'); end if;
    end if;
    v_sugg := v_sugg || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'text', btrim(s->>'text'), 'basis', nullif(btrim(coalesce(s->>'basis', '')), ''), 'task_id', v_task,
      'task_title', (select title from public.task where id = v_task))));
  end loop;
  insert into public.work_knowledge (work_id, kind, title, body, basis, suggestions)
  values (w.id, 'insight', left(btrim(split_part(btrim(p_summary), E'\n', 1)), 200), btrim(p_summary),
          nullif(left(btrim(coalesce(p_instruction, '')), 1000), ''), v_sugg)
  returning id into v_id;
  perform mcp_private.log_call(v_me, 'save_work_insight', jsonb_build_object('work_id', w.id, 'suggestions', jsonb_array_length(v_sugg)));
  return jsonb_build_object('insight_id', v_id, 'saved', true, 'suggestions', jsonb_array_length(v_sugg));
end;
$$;


ALTER FUNCTION "public"."mcp_save_work_insight"("p_work_id" "uuid", "p_summary" "text", "p_suggestions" "jsonb", "p_instruction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_work_knowledge"("p_work_id" "uuid", "p_kind" "text", "p_title" "text", "p_body" "text", "p_task_id" "uuid" DEFAULT NULL::"uuid", "p_action_type" "text" DEFAULT NULL::"text", "p_basis" "text" DEFAULT NULL::"text", "p_action_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := mcp_private.require_tool('work.run');
  w public.work := mcp_private.wk_managed_work(p_work_id);
  v_id bigint;
begin
  if p_kind not in ('procedure', 'tip', 'caution', 'reference') then
    raise exception using errcode = '22023', message = 'kind 는 procedure(절차) · tip(요령) · caution(주의) · reference(참고) 중 하나입니다(인사이트는 save_work_insight).';
  end if;
  if p_action_type is not null and p_action_type !~ '^[a-z_]+\.[a-z_]+$' then
    raise exception using errcode = '22023', message = 'action_type 은 작업 종류(예: collect.input)입니다.';
  end if;
  insert into public.work_knowledge (work_id, task_id, action_id, action_type, kind, title, body, basis)
  values (w.id, p_task_id, p_action_id, p_action_type, p_kind, btrim(coalesce(p_title, '')), btrim(coalesce(p_body, '')),
          nullif(btrim(coalesce(p_basis, '')), ''))
  returning id into v_id;
  perform mcp_private.log_call(v_me, 'save_work_knowledge', jsonb_build_object('work_id', w.id, 'kind', p_kind, 'action_id', p_action_id));
  return jsonb_build_object('knowledge_id', v_id, 'saved', true, 'kind', p_kind,
    'note', case when p_action_id is not null
                 then '이 작업에 붙였다 — 다음 해 «지난 업무 가져오기»로 옮겨진 같은 작업에서 읽힌다.'
                 else '이 업무를 «지난 업무 가져오기»로 이어받은 다음 해 업무에서도 읽힌다.' end);
end;
$_$;


ALTER FUNCTION "public"."mcp_save_work_knowledge"("p_work_id" "uuid", "p_kind" "text", "p_title" "text", "p_body" "text", "p_task_id" "uuid", "p_action_type" "text", "p_basis" "text", "p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_schedule_survey_source"("p_survey_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('schedule.survey');
  v_s  public.schedule_survey;
begin
  select * into v_s from schedule_survey where id = p_survey_id;
  if not found or not coalesce(public.can_manage_schedule_survey(v_s.id), false) then
    raise exception using errcode = 'P0002', message = '내가 만든 설문을 찾을 수 없습니다(list_schedule_surveys 의 i_organize=true).';
  end if;
  perform mcp_private.log_call(v_me, 'get_schedule_survey_result', jsonb_build_object('survey_id', v_s.id));
  return jsonb_build_object(
    'survey', jsonb_build_object('id', v_s.id, 'title', v_s.title, 'status', v_s.status, 'candidate_dates', to_jsonb(v_s.candidate_dates),
                                 'target_resource_ids', to_jsonb(v_s.target_resource_ids), 'due_date', v_s.due_date,
                                 'allow_custom_dates', v_s.allow_custom_dates),
    'responses', (select coalesce(jsonb_agg(jsonb_build_object('respondent_resource_id', r.respondent_resource_id,
                    'respondent_name', mcp_private.person_label(r.respondent_resource_id), 'items', r.items, 'comment', r.comment)), '[]'::jsonb)
                  from schedule_survey_response r where r.survey_id = v_s.id),
    'target_names', (select coalesce(jsonb_object_agg(t, coalesce(mcp_private.person_label(t), '(없는 사람)')), '{}'::jsonb)
                     from unnest(v_s.target_resource_ids) t));
end;
$$;


ALTER FUNCTION "public"."mcp_schedule_survey_source"("p_survey_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_search_ipsi"("p_type" "text" DEFAULT 'all'::"text", "p_category" "text" DEFAULT NULL::"text", "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := mcp_private.require_tool('ipsi.hub');
  v_type text := coalesce(nullif(btrim(coalesce(p_type, '')), ''), 'all');
  v_query text := nullif(btrim(coalesce(p_query, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 30);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_feed jsonb;
  v_total integer;
begin
  perform mcp_private.ipsi_teacher();
  if v_type not in ('all', 'news', 'video') then
    raise exception using errcode = '22023', message = 'type 은 all · news · video 중 하나입니다.';
  end if;
  v_feed := public.get_ipsi_hub_feed(v_type, nullif(btrim(coalesce(p_category, '')), ''), v_limit, v_offset, v_query);
  v_total := coalesce((v_feed->>'total_count')::integer, 0);
  return jsonb_strip_nulls(jsonb_build_object(
    'total', v_total,
    'news_count', v_feed->'news_count',
    'video_count', v_feed->'video_count',
    'counts_note', case when v_query is not null then 'news_count·video_count 는 검색어에 맞는 수다(종류·분류 필터와 무관) — 이 분류에 없어도 다른 분류에 있을 수 있다' end,
    'items', (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
                'kind', i->>'kind',
                'id', i->>'id',
                'title', i->>'title',
                'url', i->>'url',
                'date', ((i->>'sort_date')::timestamptz at time zone 'Asia/Seoul')::date,
                'category', i->>'category',
                'source', case when i->>'kind' = 'news' then mcp_private.ipsi_source_label(i->>'source') end,
                'channel', case when i->>'kind' = 'video' then i->>'channel_label' end,
                'summary', i->>'headline_summary',
                'duration_min', case when (i->>'duration_seconds') ~ '^\d+$' then round((i->>'duration_seconds')::numeric / 60, 1) end,
                'likes', case when i->>'kind' = 'video' then (i->>'likes')::integer end,
                'match_field', i->>'match_field',
                'match_snippet', i->>'match_snippet')) order by e.o), '[]'::jsonb)
              from jsonb_array_elements(coalesce(v_feed->'items', '[]'::jsonb)) with ordinality e(i, o)),
    'next_offset', case when v_offset + v_limit < v_total then v_offset + v_limit end,
    'how', '자세한 내용(기사 본문·핵심/전략/수치/주의 포인트, 영상 설명·자막)은 get_ipsi_item(kind, id). 검색은 띄어쓰기를 무시하고 모든 낱말이 든 것(AND)을 찾는다 — 최대 8낱말.'));
end;
$_$;


ALTER FUNCTION "public"."mcp_search_ipsi"("p_type" "text", "p_category" "text", "p_query" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_search_official_docs"("p_query" "text" DEFAULT NULL::"text", "p_sender" "text" DEFAULT NULL::"text", "p_approver" "text" DEFAULT NULL::"text", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_mine" boolean DEFAULT false, "p_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('official.read');
  v_limit int := least(greatest(coalesce(p_limit, 30), 1), 100);
  v_words text[] := array(select w from regexp_split_to_table(lower(coalesce(btrim(p_query), '')), '\s+') w where w <> '');
  v_sender text := lower(nullif(btrim(p_sender), ''));
  v_approver text := nullif(btrim(p_approver), '');
  v_total int;
  v_docs jsonb;
begin
  if p_from is not null and p_to is not null and p_from > p_to then
    raise exception using errcode = '22023', message = 'from 이 to 보다 늦습니다.';
  end if;
  perform set_config('mcp.read_official_docs', 'on', true);

  with hit as (
    select o.*
      from official_doc o
     where (p_from is null or (o.registered_at at time zone 'Asia/Seoul')::date >= p_from)
       and (p_to is null or (o.registered_at at time zone 'Asia/Seoul')::date <= p_to)
       and (v_sender is null or strpos(lower(coalesce(o.sender, '') || ' ' || coalesce(o.meta->>'발신기관', '')), v_sender) > 0)
       and (v_approver is null or o.approver_name = v_approver)
       and (not coalesce(p_mine, false) or public.official_doc_is_mine(o.approver_name))
       and (cardinality(v_words) = 0 or not exists (
             select 1 from unnest(v_words) w
              where strpos(lower(concat_ws(' ', o.doc_no, o.title, o.sender, o.body, o.meta->>'붙임', o.meta->'시행'->>'번호')), w) = 0))
  ), page as (
    select h.* from hit h order by h.registered_at desc limit v_limit
  )
  select (select count(*) from hit),
         coalesce(jsonb_agg(
           mcp_private.od_head(p) || jsonb_strip_nulls(jsonb_build_object(
             'nature', t.nature, 'needs_action', t.needs_action, 'deadline', t.deadline,
             'obligation', t.result->>'obligation', 'summary', t.result->>'summary',
             'has_body', p.body_status = 'stored' and coalesce(p.body, '') <> '',
             'decision', mcp_private.od_last_decision(p.id)))
           order by p.registered_at desc), '[]'::jsonb)
    into v_total, v_docs
    from page p
    left join lateral (select * from official_doc_triage x where x.doc_id = p.id order by x.created_at desc limit 1) t on true;

  perform set_config('mcp.read_official_docs', '', true);
  perform mcp_private.log_call(v_me, 'search_official_docs', jsonb_strip_nulls(jsonb_build_object(
    'query', nullif(btrim(p_query), ''), 'sender', v_sender, 'approver', v_approver,
    'from', p_from, 'to', p_to, 'mine', coalesce(p_mine, false), 'total', v_total)));
  return jsonb_build_object(
    'total', v_total, 'shown', jsonb_array_length(v_docs),
    'note', case when v_total > jsonb_array_length(v_docs) then '최신 접수순으로 잘렸다 — 기간·낱말을 좁히거나 limit 을 늘린다' end,
    'docs', v_docs);
end;
$$;


ALTER FUNCTION "public"."mcp_search_official_docs"("p_query" "text", "p_sender" "text", "p_approver" "text", "p_from" "date", "p_to" "date", "p_mine" boolean, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mcp_search_official_docs"("p_query" "text", "p_sender" "text", "p_approver" "text", "p_from" "date", "p_to" "date", "p_mine" boolean, "p_limit" integer) IS '에이전트 공문 찾기(official.read, 2026-11-12) — 교직원은 이 함수 안에서만 모든 공문을 읽는다(mcp.read_official_docs). INVOKER.';



CREATE OR REPLACE FUNCTION "public"."mcp_send_agent_request"("p_recipients" "jsonb", "p_title" "text", "p_body" "text", "p_steps" "jsonb" DEFAULT '[]'::"jsonb", "p_refs" "jsonb" DEFAULT '[]'::"jsonb", "p_due_date" "date" DEFAULT NULL::"date", "p_check_only" boolean DEFAULT true, "p_fingerprint" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me     uuid := mcp_private.require_tool('agent.request');
  v_title  text := btrim(coalesce(p_title, ''));
  v_body   text := btrim(coalesce(p_body, ''));
  v_steps  jsonb := '[]'::jsonb;
  v_refs   jsonb := '[]'::jsonb;
  v_people jsonb := '[]'::jsonb;
  v_names  text[] := '{}';
  v_x      jsonb;
  v_name   text;
  v_n      int;
  v_rid    uuid;
  v_kind   text;
  v_rt     text;
  v_fp     text;
  v_res    jsonb;
begin
  if v_title = '' or char_length(v_title) > 80 then
    raise exception using errcode = '22023', message = 'title 은 1~80자입니다.';
  end if;
  if v_body = '' or char_length(v_body) > 3000 then
    raise exception using errcode = '22023', message = 'body(요청 내용)는 1~3000자입니다.';
  end if;
  if p_due_date is not null and p_due_date < (now() at time zone 'Asia/Seoul')::date then
    raise exception using errcode = '22023', message = '기한(due_date)이 이미 지났습니다.';
  end if;

  -- 받는 사람 — 재직 교직원 이름, 정확히 한 명일 때만(find_staff 로 찾은 이름)
  if p_recipients is null or jsonb_typeof(p_recipients) <> 'array' or jsonb_array_length(p_recipients) = 0 then
    raise exception using errcode = '22023', message = 'recipients(받는 교직원 이름 목록)가 필요합니다.';
  end if;
  if jsonb_array_length(p_recipients) > 30 then
    raise exception using errcode = '22023', message = '한 번에 30명까지 보낼 수 있습니다.';
  end if;
  for v_x in select * from jsonb_array_elements(p_recipients) loop
    v_name := btrim(coalesce(v_x #>> '{}', ''));
    if v_name = '' then
      raise exception using errcode = '22023', message = '이름이 빈 받는 사람이 있습니다.';
    end if;
    if v_name = any(v_names) then
      raise exception using errcode = '22023', message = format('%s 님이 두 번 들어 있습니다.', v_name);
    end if;
    v_names := v_names || v_name;
    select count(*), min(r.id::text)::uuid into v_n, v_rid
      from resource r
     where r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active' and r.name = v_name;
    if v_n = 0 then
      raise exception using errcode = '22023', message = format('교직원 «%s» 이 명단에 없습니다(find_staff 로 정확한 이름을).', v_name);
    elsif v_n > 1 then
      raise exception using errcode = '22023', message = format('«%s» 이름이 %s명입니다 — 이 도구로는 보낼 수 없습니다.', v_name, v_n);
    end if;
    v_people := v_people || jsonb_build_object('id', v_rid, 'name', v_name);
  end loop;

  -- 수행 안내 — 글 단계 최대 12개
  if p_steps is not null and jsonb_typeof(p_steps) = 'array' then
    if jsonb_array_length(p_steps) > 12 then
      raise exception using errcode = '22023', message = 'steps 는 12단계까지입니다.';
    end if;
    for v_x in select * from jsonb_array_elements(p_steps) loop
      v_name := btrim(coalesce(v_x #>> '{}', ''));
      if v_name = '' or char_length(v_name) > 400 then
        raise exception using errcode = '22023', message = 'steps 의 각 단계는 1~400자 글입니다.';
      end if;
      v_steps := v_steps || to_jsonb(v_name);
    end loop;
  elsif p_steps is not null and jsonb_typeof(p_steps) <> 'null' then
    raise exception using errcode = '22023', message = 'steps 는 글 목록입니다.';
  end if;
  -- 맡길 말은 데스크 메시지 한 통(8000자) 안에 들어가야 한다 — 요청 내용 + 수행 안내 합쳐 5000자
  if char_length(v_body) + coalesce((select sum(char_length(s #>> '{}')) from jsonb_array_elements(v_steps) s), 0) > 5000 then
    raise exception using errcode = '22023', message = '요청 내용과 수행 안내를 합쳐 5000자 안으로 줄여 주세요.';
  end if;

  -- 연결 항목 — 내가 볼 수 있는 것만(INVOKER — 표 RLS), 제목은 서버가 채운다
  if p_refs is not null and jsonb_typeof(p_refs) = 'array' then
    if jsonb_array_length(p_refs) > 10 then
      raise exception using errcode = '22023', message = 'refs 는 10개까지입니다.';
    end if;
    for v_x in select * from jsonb_array_elements(p_refs) loop
      v_kind := v_x->>'kind';
      v_rt := null;
      if v_kind = 'skill' then
        v_rt := btrim(coalesce(v_x->>'name', ''));
        if v_rt = '' or char_length(v_rt) > 80 then
          raise exception using errcode = '22023', message = 'skill 연결은 name(스킬 이름, 80자 안)이 필요합니다.';
        end if;
        v_refs := v_refs || jsonb_build_object('kind', 'skill', 'title', v_rt);
        continue;
      end if;
      if coalesce(v_x->>'id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
        raise exception using errcode = '22023', message = format('refs 의 id 가 올바르지 않습니다(%s).', coalesce(v_x->>'id', '없음'));
      end if;
      if v_kind = 'document_generation' then
        select a.title into v_rt from task_action a
         where a.id = (v_x->>'id')::uuid and a.action_type = 'document.spec_fill' and a.archived_at is null;
      elsif v_kind = 'action' then
        select a.title into v_rt from task_action a where a.id = (v_x->>'id')::uuid and a.archived_at is null;
      elsif v_kind = 'work' then
        select e.name into v_rt from event e where e.id = (v_x->>'id')::uuid;
      elsif v_kind = 'task' then
        select t.title into v_rt from task t where t.id = (v_x->>'id')::uuid;
      else
        raise exception using errcode = '22023',
          message = 'refs 의 kind 는 document_generation · action · work · task · skill 중 하나입니다.';
      end if;
      if v_rt is null then
        raise exception using errcode = 'P0002', message = format('연결할 %s(%s)를 찾을 수 없습니다 — 내가 볼 수 있는 것만 연결합니다.', v_kind, v_x->>'id');
      end if;
      v_refs := v_refs || jsonb_build_object('kind', v_kind, 'id', v_x->>'id', 'title', v_rt);
    end loop;
  end if;

  v_fp := md5(array_to_string(v_names, ',') || chr(31) || v_title || chr(31) || v_body || chr(31) || v_steps::text
              || chr(31) || v_refs::text || chr(31) || coalesce(p_due_date::text, ''));

  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true,
      'to', to_jsonb(v_names), 'title', v_title, 'body', v_body, 'steps', v_steps, 'refs', v_refs,
      'due_date', to_char(p_due_date, 'YYYY-MM-DD'),
      'fingerprint', v_fp,
      'note', '아직 보내지 않았다 — 받는 사람·제목·요청 내용·수행 안내·연결 항목을 사용자에게 그대로 보여 주고 확인받은 뒤, '
              || 'check_only:false 와 이 fingerprint 로 다시 부른다. 받는 선생님에게 알림(휴대폰 푸시 포함)이 가고, '
              || '받는 쪽은 이것을 자기 에이전트에게 넘겨 처리한다. 연결 항목은 받는 사람 권한으로 다시 열리므로 그 사람이 볼 수 없으면 안내만 남는다.');
  end if;

  if p_fingerprint is null then
    raise exception using errcode = '22023', message = 'check_only:true 로 먼저 미리 보고, 사용자 확인 뒤 돌려받은 fingerprint 를 넣으세요.';
  end if;
  if p_fingerprint <> v_fp then
    raise exception using errcode = '22023', message = '미리 본 뒤 내용이 바뀌었습니다 — check_only:true 로 다시 미리 보고 확인받으세요.';
  end if;
  if (select count(*) from public.agent_request where sender_resource_id = v_me and created_at > now() - interval '1 hour')
     + jsonb_array_length(v_people) > 60 then
    raise exception using errcode = '54000', message = '작업 요청은 한 시간에 60건까지 보낼 수 있습니다.';
  end if;

  v_res := agent_req_private.insert(v_me, v_people, v_title, v_body, v_steps, v_refs, p_due_date);
  perform mcp_private.log_call(v_me, 'send_agent_request',
    jsonb_build_object('batch_id', v_res->>'batch_id', 'recipients', jsonb_array_length(v_people), 'refs', jsonb_array_length(v_refs)));
  return v_res || jsonb_build_object('sent', true,
    'note', '보냈다 — 받는 선생님의 알림·휴대폰에 바로 보인다. 진행은 list_agent_requests(box:"sent")로 본다.');
end;
$_$;


ALTER FUNCTION "public"."mcp_send_agent_request"("p_recipients" "jsonb", "p_title" "text", "p_body" "text", "p_steps" "jsonb", "p_refs" "jsonb", "p_due_date" "date", "p_check_only" boolean, "p_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_send_club_request"("p_title" "text", "p_axis" "text", "p_fields" "jsonb", "p_due" "date" DEFAULT NULL::"date", "p_clubs" "text"[] DEFAULT NULL::"text"[], "p_guide" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT 'private'::"text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('club.manage');
  v_year int := club_private.current_year();
  v_ids uuid[] := null; v_bad text[] := '{}'; c text; v_id uuid; v jsonb;
begin
  if p_clubs is not null and cardinality(p_clubs) > 0 then
    v_ids := '{}';
    foreach c in array p_clubs loop
      select y.id into v_id from public.club_year y
       where y.academic_year = v_year and y.status = 'active'
         and (y.id::text = btrim(c) or y.name = btrim(c)) limit 1;
      if v_id is null then v_bad := v_bad || c; else v_ids := v_ids || v_id; end if;
    end loop;
    if cardinality(v_bad) > 0 then
      raise exception using errcode = '22023', message = '올해 활동 중인 동아리에서 찾지 못함: ' || array_to_string(v_bad, ', ') || ' (get_club_overview 의 name)';
    end if;
  end if;
  v := public.club_send_request(p_title, p_axis, p_fields, p_due, v_ids, p_guide, p_visibility, v_year, coalesce(p_check_only, true));
  if coalesce(p_check_only, true) then
    return (v - 'config') || jsonb_build_object('next', '보낼 동아리·지도교사 수·줄 수를 사용자에게 보여 확인받은 뒤 check_only:false. 지도교사에게 알림이 간다.');
  end if;
  perform mcp_private.log_call(v_me, 'send_club_request', jsonb_build_object('action_id', v->>'action_id', 'title', p_title));
  return v - 'started';
end $$;


ALTER FUNCTION "public"."mcp_send_club_request"("p_title" "text", "p_axis" "text", "p_fields" "jsonb", "p_due" "date", "p_clubs" "text"[], "p_guide" "text", "p_visibility" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_send_message"("p_action_id" "uuid", "p_check_only" boolean DEFAULT false, "p_fingerprint" "text" DEFAULT NULL::"text", "p_instruction" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.run');
  r record := mcp_private.wr_action_ref(p_action_id);
  v_prev jsonb := mcp_private.wr_message_preview(p_action_id);
  v_res jsonb;
begin
  if coalesce(p_check_only, false) then
    perform mcp_private.wr_event(r.work_id, r.task_id, p_action_id, 'agent.preview', jsonb_strip_nulls(jsonb_build_object(
      'tool', 'send_message', 'people', v_prev->'people', 'fingerprint', v_prev->>'fingerprint', 'instruction', left(p_instruction, 300))));
    return v_prev || jsonb_build_object('check_only', true,
      'next', '제목·본문·받는 사람을 사용자에게 보여 주고 확인받은 뒤, check_only 없이 fingerprint 를 넣어 다시 부른다.');
  end if;
  if v_prev->>'config_error' is not null then
    raise exception using errcode = '22023', message = v_prev->>'config_error';
  end if;
  if p_fingerprint is null then
    raise exception using errcode = '22023', message = 'check_only:true 로 먼저 미리 보고, 사용자 확인 뒤 돌려받은 fingerprint 를 넣으세요.';
  end if;
  if p_fingerprint <> v_prev->>'fingerprint' then
    raise exception using errcode = '22023', message = '미리 본 뒤 본문이나 받는 사람이 바뀌었습니다 — check_only 로 다시 보고 사용자에게 확인받으세요.';
  end if;
  v_res := public.send_task_message(p_action_id);
  perform mcp_private.wr_event(r.work_id, r.task_id, p_action_id, 'agent.sent', jsonb_strip_nulls(jsonb_build_object(
    'tool', 'send_message', 'people', v_prev->'people', 'notified', v_res->'notified', 'instruction', left(p_instruction, 300))));
  perform mcp_private.log_call(v_me, 'send_message', jsonb_build_object('action_id', p_action_id, 'notified', v_res->'notified'));
  return jsonb_strip_nulls(jsonb_build_object('sent', true, 'notified', v_res->'notified', 'send_id', v_res->'send_id',
    'recipients', v_res->'recipient_names', 'not_linked', case when jsonb_array_length(coalesce(v_res->'unlinked_names', '[]')) > 0 then v_res->'unlinked_names' end,
    'note', case when jsonb_array_length(coalesce(v_res->'unlinked_names', '[]')) > 0
                 then 'not_linked 는 SPACEKIJUN 에 로그인한 적이 없어 알림이 가지 않는다 — 쿨메신저로 따로 보내라고 사용자에게 알린다.' end));
end;
$$;


ALTER FUNCTION "public"."mcp_send_message"("p_action_id" "uuid", "p_check_only" boolean, "p_fingerprint" "text", "p_instruction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_send_request"("p_action_id" "uuid", "p_check_only" boolean DEFAULT false, "p_fingerprint" "text" DEFAULT NULL::"text", "p_instruction" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.run');
  r record := mcp_private.wr_action_ref(p_action_id);
  v_prev jsonb := mcp_private.wr_request_preview(p_action_id);
  v_res jsonb;
begin
  if coalesce(p_check_only, false) then
    perform mcp_private.wr_event(r.work_id, r.task_id, p_action_id, 'agent.preview', jsonb_strip_nulls(jsonb_build_object(
      'tool', 'send_request', 'people', v_prev->'people', 'fingerprint', v_prev->>'fingerprint', 'instruction', left(p_instruction, 300))));
    return v_prev || jsonb_build_object('check_only', true,
      'next', '받는 사람·칸·마감을 사용자에게 보여 주고 확인받은 뒤, check_only 없이 fingerprint 를 넣어 다시 부른다.');
  end if;
  if (v_prev->>'already_sent')::boolean then
    raise exception using errcode = '22023', message = '이미 보낸 요청입니다 — 안 낸 사람에게 다시 알리려면 remind_pending.';
  end if;
  if v_prev->>'config_error' is not null then
    raise exception using errcode = '22023', message = format('설정이 덜 됐습니다 — %s (update_action 으로 고친 뒤 다시 미리보기)', v_prev->>'config_error');
  end if;
  if p_fingerprint is null then
    raise exception using errcode = '22023', message = 'check_only:true 로 먼저 미리 보고, 사용자 확인 뒤 돌려받은 fingerprint 를 넣으세요.';
  end if;
  if p_fingerprint <> v_prev->>'fingerprint' then
    raise exception using errcode = '22023', message = '미리 본 뒤 받는 사람이나 설정이 바뀌었습니다 — check_only 로 다시 보고 사용자에게 확인받으세요.';
  end if;
  v_res := public.start_collect_request(p_action_id);
  perform mcp_private.wr_event(r.work_id, r.task_id, p_action_id, 'agent.sent', jsonb_strip_nulls(jsonb_build_object(
    'tool', 'send_request', 'people', v_res->'people', 'notified', v_res->'notified', 'instruction', left(p_instruction, 300))));
  perform mcp_private.log_call(v_me, 'send_request', jsonb_build_object('action_id', p_action_id, 'people', v_res->'people'));
  return v_res || jsonb_build_object('sent', true, 'title', v_prev->'title', 'task_title', v_prev->'task_title');
end;
$$;


ALTER FUNCTION "public"."mcp_send_request"("p_action_id" "uuid", "p_check_only" boolean, "p_fingerprint" "text", "p_instruction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_booking_windows"("p_room_ids" "uuid"[], "p_booking_windows" "jsonb", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('studyroom.manage');
  v_win   jsonb;
  v_rooms jsonb;
  v_bad   text;
  v_n     integer;
begin
  perform mcp_private.sr_require_teacher();
  perform mcp_private.sr_require_head();   -- 2026-11-05: 열람실 설정은 학년 부장·관리자만
  if coalesce(cardinality(p_room_ids), 0) = 0 or cardinality(p_room_ids) > 30 then
    raise exception using errcode = '22023', message = 'room_ids 는 1~30개입니다.';
  end if;
  if p_booking_windows is null then raise exception using errcode = '22023', message = 'booking_windows 가 필요합니다([] = 비우기).'; end if;
  v_win := mcp_private.sr_windows(p_booking_windows);
  if (select count(*) from study_rooms where id = any(p_room_ids)) <> (select count(distinct x) from unnest(p_room_ids) x) then
    raise exception using errcode = 'P0002', message = '찾을 수 없는 열람실이 있습니다(list_study_rooms 의 room_id).';
  end if;
  select string_agg(name, ', ') into v_bad from study_rooms where id = any(p_room_ids) and reservation_mode <> 'FIXED';
  if v_bad is not null then
    raise exception using errcode = '22023', message = format('주간 신청(WEEKLY) 열람실은 신청 기간을 쓰지 않는다: %s', v_bad);
  end if;
  select jsonb_agg(jsonb_build_object('room_id', id, 'name', name,
           'before', (select jsonb_agg(w order by w->>'start') from jsonb_array_elements(coalesce(booking_windows, '[]'::jsonb)) w)) order by name)
    into v_rooms from study_rooms where id = any(p_room_ids);
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true, 'rooms', v_rooms, 'after', v_win,
      'note', '아직 바꾸지 않았다 — 열람실들의 신청 기간이 after 로 통째로 바뀐다. 사용자에게 확인받은 뒤 check_only:false.');
  end if;
  update study_rooms
     set booking_windows = v_win,
         booking_start_date = (v_win->0->>'start')::timestamptz, booking_end_date = (v_win->0->>'end')::timestamptz,
         updated_at = now()
   where id = any(p_room_ids);
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception using errcode = '42501', message = '열람실을 고칠 권한이 없습니다.'; end if;
  perform mcp_private.log_call(v_me, 'set_booking_windows', jsonb_build_object('rooms', v_n, 'windows', jsonb_array_length(v_win)));
  return jsonb_build_object('saved', true, 'rooms', v_n, 'booking_windows', v_win);
end;
$$;


ALTER FUNCTION "public"."mcp_set_booking_windows"("p_room_ids" "uuid"[], "p_booking_windows" "jsonb", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_budget_line"("p_line_id" "uuid", "p_closed" boolean DEFAULT NULL::boolean, "p_note" "text" DEFAULT NULL::"text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('budget.manage');
  v_line budget_line;
begin
  select * into v_line from budget_line where id = p_line_id;
  if v_line.id is null then
    raise exception using errcode = 'P0002', message = '산출내역을 찾지 못했습니다 — get_budget 의 lines[].id.';
  end if;
  perform mcp_private.bg_require_edit(v_line.project_id);
  if p_closed is null and p_note is null then
    raise exception using errcode = '22023', message = 'closed 나 note 중 하나는 보내야 합니다.';
  end if;
  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true, 'line', v_line.name,
      'before', jsonb_build_object('closed', v_line.closed, 'note', v_line.note),
      'after', jsonb_build_object('closed', coalesce(p_closed, v_line.closed), 'note', coalesce(p_note, v_line.note)),
      'note', '마감한 줄은 남은 계획을 0으로 세고 추경 제안이 원인행위가 된다. 확인받은 뒤 check_only:false.'));
  end if;
  update budget_line set closed = coalesce(p_closed, closed),
    note = case when p_note is null then note else nullif(btrim(p_note), '') end
  where id = p_line_id;
  perform mcp_private.log_call(v_me, 'set_budget_line', jsonb_build_object('line_id', p_line_id, 'closed', p_closed));
  return jsonb_build_object('saved', true, 'figures', mcp_private.bg_totals(v_line.project_id));
end;
$$;


ALTER FUNCTION "public"."mcp_set_budget_line"("p_line_id" "uuid", "p_closed" boolean, "p_note" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_club_activities"("p_issue_id" "uuid", "p_club" "text", "p_activities" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me    uuid := mcp_private.require_tool('issue.register');
  v_row   document_issue;
  v_club  jsonb;
  v_e     jsonb;
  v_acts  jsonb := '[]'::jsonb;
begin
  select * into v_row from document_issue where id = p_issue_id;
  if not found then
    raise exception using errcode = 'P0002', message = '그 발급 기록을 찾을 수 없습니다 (list_issues 의 issue_id).';
  end if;
  if v_row.doc_type <> 'volunteer_club' then
    raise exception using errcode = '22023', message = format('%s 은(는) 동아리 봉사 발급이 아닙니다.', v_row.issue_no);
  end if;
  if v_row.status = 'cancelled' then
    raise exception using errcode = '22023', message = format('%s 은(는) 취소된 발급입니다.', v_row.issue_no);
  end if;
  select c into v_club from jsonb_array_elements(mcp_private.arr(v_row.form_data->'clubs')) c
  where c->>'club_id' = lower(btrim(p_club)) or c->>'club_name' = btrim(p_club) limit 1;
  if v_club is null then
    raise exception using errcode = '22023', message = format('이 발급에 «%s» 동아리가 없습니다 — %s', p_club,
      (select string_agg(c->>'club_name', ' · ') from jsonb_array_elements(mcp_private.arr(v_row.form_data->'clubs')) c));
  end if;

  if p_activities is null or jsonb_typeof(p_activities) <> 'array' then
    raise exception using errcode = '22023', message = 'activities 는 [{"date","hours","content"}] 배열입니다(빈 배열 = 모두 지우기).';
  end if;
  if jsonb_array_length(p_activities) > 9 then
    raise exception using errcode = '22023', message = '활동은 9건까지입니다(확인서 날짜 칸이 9개).';
  end if;
  for v_e in select * from jsonb_array_elements(p_activities) loop
    if jsonb_typeof(v_e) <> 'object' or coalesce(v_e->>'date', '') !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception using errcode = '22023', message = '활동마다 date(YYYY-MM-DD)가 필요합니다.';
    end if;
    if coalesce(v_e->>'hours', '') !~ '^\d+(\.\d+)?$' or (v_e->>'hours')::numeric <= 0 or (v_e->>'hours')::numeric > 24 then
      raise exception using errcode = '22023', message = format('%s 활동의 hours(시간)는 0보다 크고 24 이하인 숫자입니다.', v_e->>'date');
    end if;
    if length(coalesce(v_e->>'content', '')) > 300 then
      raise exception using errcode = '22023', message = format('%s 활동의 content 는 300자까지입니다.', v_e->>'date');
    end if;
    if exists (select 1 from jsonb_array_elements(v_acts) x where x->>'date' = v_e->>'date') then
      raise exception using errcode = '22023', message = format('%s 이(가) 두 번 나옵니다 — 날짜마다 한 건입니다.', v_e->>'date');
    end if;
    v_acts := v_acts || jsonb_build_object('date', (v_e->>'date')::date::text, 'hours', (v_e->>'hours')::numeric,
                                           'content', btrim(coalesce(v_e->>'content', '')));
  end loop;
  select coalesce(jsonb_agg(x order by x->>'date'), '[]'::jsonb) into v_acts from jsonb_array_elements(v_acts) x;

  perform public.update_club_activities(v_row.id, v_club->>'club_id', v_acts);

  perform mcp_private.log_call(v_me, 'set_club_activities',
    jsonb_build_object('issue_id', v_row.id, 'issue_no', v_row.issue_no, 'club_id', v_club->>'club_id', 'count', jsonb_array_length(v_acts)));
  return jsonb_build_object('issue_id', v_row.id, 'issue_no', v_row.issue_no, 'club_name', v_club->>'club_name', 'activities', v_acts,
    'note', '동아리 활동을 저장했다. 날짜별 참가(√)를 학생마다 바꾸려면 웹 다운로드 미리보기에서 — 바꾸지 않으면 전원·전일 참가로 나온다.');
end;
$_$;


ALTER FUNCTION "public"."mcp_set_club_activities"("p_issue_id" "uuid", "p_club" "text", "p_activities" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_club_advisors"("p_club_year_id" "uuid", "p_teachers" "jsonb", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := mcp_private.require_tool('club.manage');
  e jsonb; v_txt text; v_ids uuid[] := '{}'; v_names text[] := '{}'; v_errors text[] := '{}'; v_n int; v_id uuid; v_name text;
  v jsonb;
begin
  if not public.is_club_manager() then
    raise exception using errcode = '42501', message = '지도교사는 동아리 담당자가 정합니다';
  end if;
  for e in select * from jsonb_array_elements(coalesce(p_teachers, '[]'::jsonb)) loop
    v_txt := btrim(e #>> '{}');
    if v_txt ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      select count(*), min(r.id::text)::uuid, min(r.name) into v_n, v_id, v_name from public.resource r
      where r.id = v_txt::uuid and r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active';
    else
      select count(*), min(r.id::text)::uuid, min(r.name) into v_n, v_id, v_name from public.resource r
      where r.name = v_txt and r.type in ('teacher', 'staff') and coalesce(r.status, 'active') = 'active';
    end if;
    if v_n = 1 then v_ids := v_ids || v_id; v_names := v_names || v_name;
    else v_errors := v_errors || format('%s: %s', v_txt, case when v_n = 0 then '재직 교직원에서 찾지 못함' else '여러 명 — resource id 로 지정' end);
    end if;
  end loop;
  if array_length(v_errors, 1) > 0 then
    raise exception using errcode = '22023', message = array_to_string(v_errors, ' / ');
  end if;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true,
      'before', (select jsonb_agg(a->>'name') from jsonb_array_elements(public.club_get(p_club_year_id)->'advisors') a),
      'after', to_jsonb(v_names), 'next', '첫 사람이 대표 지도교사다. 확인받은 뒤 check_only:false.');
  end if;
  v := public.club_set_advisors(p_club_year_id, v_ids);
  perform mcp_private.log_call(v_me, 'set_club_advisors', jsonb_build_object('club_year_id', p_club_year_id, 'teachers', to_jsonb(v_names)));
  return jsonb_build_object('ok', true, 'club', mcp_private.club_brief(v));
end $_$;


ALTER FUNCTION "public"."mcp_set_club_advisors"("p_club_year_id" "uuid", "p_teachers" "jsonb", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_club_finance"("p_club_year_id" "uuid", "p_allocated" bigint, "p_budget_line_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_me uuid := mcp_private.require_tool('club.manage'); v jsonb;
begin
  if not public.is_club_manager() then raise exception using errcode = '42501', message = '배정액은 동아리 담당자가 정합니다'; end if;
  if coalesce(p_check_only, true) then
    v := public.club_finance_get(p_club_year_id);
    return jsonb_build_object('check_only', true, 'before', jsonb_build_object('allocated', v->'allocated', 'budget_line', v->'budget_line'),
      'after', jsonb_build_object('allocated', p_allocated, 'budget_line_id', p_budget_line_id),
      'next', '바뀔 배정액·예산 출처를 사용자에게 보여 확인받은 뒤 check_only:false.');
  end if;
  v := public.club_set_finance(p_club_year_id, p_allocated, p_budget_line_id, p_note);
  perform mcp_private.log_call(v_me, 'set_club_finance', jsonb_build_object('club_year_id', p_club_year_id, 'allocated', p_allocated));
  return jsonb_build_object('ok', true, 'finance', v);
end $$;


ALTER FUNCTION "public"."mcp_set_club_finance"("p_club_year_id" "uuid", "p_allocated" bigint, "p_budget_line_id" "uuid", "p_note" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_club_leader"("p_club_year_id" "uuid", "p_student" "text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := mcp_private.require_tool('club.manage');
  v_t text := regexp_replace(coalesce(p_student, ''), '\s', '', 'g');
  v_code text; v_label text; v jsonb;
begin
  if v_t <> '' then
    select m.student_code, concat_ws(' ', concat_ws('-', m.grade, m.class_num, m.number), r.name) into v_code, v_label
    from public.club_member m left join public.resource r on r.id = m.student_resource_id
    where m.club_year_id = p_club_year_id and m.status = 'confirmed'
      and (m.student_code = v_t
           or concat_ws('-', m.grade, m.class_num, m.number) = v_t
           or (v_t ~ '^\d{5}$' and m.grade = substr(v_t, 1, 1)::int and m.class_num = substr(v_t, 2, 2)::int and m.number = substr(v_t, 4, 2)::int));
    if v_code is null then
      raise exception using errcode = '22023', message = '기장은 이 동아리의 확정된 부원 중에서 고릅니다 — ' || p_student;
    end if;
  end if;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true, 'before', mcp_private.club_brief(public.club_get(p_club_year_id))->'leader',
      'after', coalesce(v_label, '(비움)'), 'next', '확인받은 뒤 check_only:false.');
  end if;
  v := public.club_set_leader(p_club_year_id, v_code);
  perform mcp_private.log_call(v_me, 'set_club_leader', jsonb_build_object('club_year_id', p_club_year_id));
  return jsonb_build_object('ok', true, 'club', mcp_private.club_brief(v));
end $_$;


ALTER FUNCTION "public"."mcp_set_club_leader"("p_club_year_id" "uuid", "p_student" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_club_members"("p_club_year_id" "uuid", "p_students" "jsonb", "p_mode" "text" DEFAULT 'add'::"text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('club.manage');
  v jsonb;
begin
  v := public.club_set_members(p_club_year_id, p_students, coalesce(p_mode, 'add'), coalesce(p_check_only, true));
  if not coalesce(p_check_only, true) and (v->>'ok')::boolean then
    perform mcp_private.log_call(v_me, 'set_club_members', jsonb_build_object('club_year_id', p_club_year_id, 'mode', p_mode,
      'added', v->'added', 'removed', v->'removed'));
  end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'check_only', v->'check_only', 'ok', v->'ok', 'errors', v->'errors',
    'add', (select jsonb_agg(concat_ws(' ', concat_ws('-', a->>'grade', a->>'class', a->>'number'), a->>'name')
                             || case when a->>'role' = 'leader' then ' (기장)' else '' end)
            from jsonb_array_elements(coalesce(v->'add', '[]'::jsonb)) a),
    'remove', (select jsonb_agg(concat_ws(' ', concat_ws('-', a->>'grade', a->>'class', a->>'number'), a->>'name'))
               from jsonb_array_elements(coalesce(v->'remove', '[]'::jsonb)) a),
    'unchanged', v->'unchanged', 'added', v->'added', 'removed', v->'removed',
    'next', case when (v->>'check_only')::boolean and (v->>'ok')::boolean
                 then '넣을·뺄 학생을 사용자에게 보여 확인받은 뒤 check_only:false 로 다시 부른다.'
                 when (v->>'check_only')::boolean then 'errors 를 사용자에게 알리고 학생 목록을 고쳐 다시 미리 본다(정규 동아리는 한 학생에 하나).' end));
end $$;


ALTER FUNCTION "public"."mcp_set_club_members"("p_club_year_id" "uuid", "p_students" "jsonb", "p_mode" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_my_task_status"("p_task_id" "uuid", "p_status" "text", "p_deadline" "text" DEFAULT NULL::"text", "p_unit_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('task.mine');
  v_task  public.task;
  v_work  public.work;
  v_mode  text;
  v_state jsonb;
  v_after jsonb;
begin
  if p_status is null or p_status not in ('completed', 'pending') then
    raise exception using errcode = '22023', message = 'status 는 completed(완료) 또는 pending(되돌리기)입니다.';
  end if;
  select * into v_task from public.task where id = p_task_id;
  if found then select * into v_work from public.work where id = v_task.event_id; end if;
  v_state := case when v_task.id is not null and v_work.id is not null
                  then mcp_private.my_task_state(v_task, v_work.status, v_me) end;
  if v_state is null or not public.task_visible_to_assignees(v_task.meta) then
    raise exception using errcode = '42501', message = '내가 담당자인 할 일만 완료·되돌리기할 수 있습니다.';
  end if;
  if v_work.status not in ('active', 'pending') or v_task.status = 'cancelled' then
    raise exception using errcode = '0A000', message = '끝났거나 취소된 업무·할 일은 바꿀 수 없습니다.';
  end if;

  v_mode := mcp_private.task_mode(v_task.meta);

  if v_mode = 'units' then
    if p_deadline is not null then
      raise exception using errcode = '22023', message = '과제 단위 할 일입니다 — deadline 대신 unit_key 를 주세요.';
    end if;
    if p_unit_key is null or not exists (
      select 1 from jsonb_array_elements(v_state->'my_units') u(v) where u.v->>'unit_key' = p_unit_key) then
      raise exception using errcode = '22023',
        message = '과제 단위 할 일입니다 — 내가 맡은 단위의 unit_key 를 주세요(mcp get_task 의 mine.my_units). 단위를 새로 맡는 것은 웹에서 합니다.';
    end if;
    if p_status = 'completed' and public.unit_has_pending_submission(v_task.id, v_me, p_unit_key) then
      raise exception using errcode = '0A000',
        message = '이 단위는 제출이 남아 완료할 수 없습니다 — 웹 «내 할 일»에서 제출하면 저절로 완료됩니다.';
    end if;
    perform public.set_task_unit_status(v_task.id, p_unit_key, v_me, p_status);

  elsif v_mode = 'rounds' then
    if p_unit_key is not null then
      raise exception using errcode = '22023', message = '여러 회차 할 일입니다 — unit_key 대신 deadline 을 주세요.';
    end if;
    if p_deadline is null or not (v_task.meta->'deadlines' ? p_deadline) then
      raise exception using errcode = '22023',
        message = format('여러 회차 할 일입니다 — deadline 에 회차 날짜를 주세요: %s', (
          select string_agg(d #>> '{}', ', ' order by d #>> '{}') from jsonb_array_elements(v_task.meta->'deadlines') x(d)));
    end if;
    if p_status = 'completed' and public.assignee_has_pending_submission(v_task.id, v_me) then
      raise exception using errcode = '0A000',
        message = '제출이 남아 완료할 수 없습니다 — 웹 «내 할 일»에서 제출하면 저절로 완료됩니다.';
    end if;
    perform public.set_task_deadline_status(v_task.id, v_me, p_deadline, p_status);

  else
    if p_deadline is not null or p_unit_key is not null then
      raise exception using errcode = '22023', message = '마감이 하나인 할 일입니다 — deadline·unit_key 없이 부르세요.';
    end if;
    if p_status = 'completed' and public.assignee_has_pending_submission(v_task.id, v_me) then
      raise exception using errcode = '0A000',
        message = '제출이 남아 완료할 수 없습니다 — 웹 «내 할 일»에서 제출하면 저절로 완료됩니다.';
    end if;
    perform public.set_task_assignee_status(v_task.id, v_me, p_status);
  end if;

  perform mcp_private.log_call(v_me, 'set_my_task_status', jsonb_strip_nulls(jsonb_build_object(
    'task_id', v_task.id, 'status', p_status, 'deadline', p_deadline, 'unit_key', p_unit_key)));

  select * into v_task from public.task where id = p_task_id;
  v_after := mcp_private.my_task_state(v_task, v_work.status, v_me);
  return jsonb_strip_nulls(jsonb_build_object(
    'task_id', v_task.id, 'title', v_task.title, 'mode', v_mode,
    'changed', jsonb_strip_nulls(jsonb_build_object('status', p_status, 'deadline', p_deadline, 'unit_key', p_unit_key)),
    'task_status', v_task.status,
    'mine', v_after));
end;
$$;


ALTER FUNCTION "public"."mcp_set_my_task_status"("p_task_id" "uuid", "p_status" "text", "p_deadline" "text", "p_unit_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_plan_done"("p_task_id" "uuid", "p_done" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('planner.mine');
  v_old academy_tasks;
  v_res jsonb;
  v_row academy_tasks;
begin
  perform mcp_private.pl_require_planner();
  v_old := mcp_private.pl_my_task(p_task_id);
  v_res := public.academy_dormitory_write('complete', jsonb_build_object('id', v_old.id, 'completed', coalesce(p_done, true)));
  select * into v_row from academy_tasks where id = v_old.id;
  perform mcp_private.log_call(v_me, 'set_plan_done', jsonb_build_object('task_id', v_row.id, 'done', v_row.completed));
  return mcp_private.pl_task_out(v_row) || jsonb_strip_nulls(jsonb_build_object(
    'reward', nullif((v_res->>'reward')::int, 0)));
end;
$$;


ALTER FUNCTION "public"."mcp_set_plan_done"("p_task_id" "uuid", "p_done" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_planner_goal_status"("p_goal_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('planner.mine');
  v_old academy_user_goals;
  v_row academy_user_goals;
begin
  perform mcp_private.pl_require_planner();
  v_old := mcp_private.pl_my_goal(p_goal_id);
  if p_status = 'completed' or p_status = 'active' then
    perform public.academy_dormitory_write('complete_goal', jsonb_build_object('id', v_old.id, 'completed', p_status = 'completed'));
    if p_status = 'active' and v_old.is_archived then
      perform public.academy_dormitory_write('archive_goal', jsonb_build_object('id', v_old.id, 'archived', false));
    end if;
  elsif p_status = 'archived' or p_status = 'unarchived' then
    perform public.academy_dormitory_write('archive_goal', jsonb_build_object('id', v_old.id, 'archived', p_status = 'archived'));
  else
    raise exception using errcode = '22023', message = 'status 는 completed · active · archived · unarchived 중 하나입니다.';
  end if;
  select * into v_row from academy_user_goals where id = v_old.id;
  perform mcp_private.log_call(v_me, 'set_planner_goal_status', jsonb_build_object('goal_id', v_row.id, 'status', p_status));
  return mcp_private.pl_goal_out(v_row);
end;
$$;


ALTER FUNCTION "public"."mcp_set_planner_goal_status"("p_goal_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_purchase_item_status"("p_request_id" "uuid", "p_status" "text", "p_row_ids" "text"[] DEFAULT NULL::"text"[], "p_reason" "text" DEFAULT NULL::"text", "p_check_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me      uuid := mcp_private.require_tool('purchase.request');
  v_req     public.purchase_requests%rowtype;
  v_page    public.purchase_request_pages%rowtype;
  v_reason  text := nullif(btrim(coalesce(p_reason, '')), '');
  v_all_ids text[];
  v_every   text[];
  v_target  text[];
  v_pass    text[];
  v_unknown text[];
  v_items   jsonb;
  v_changes integer;
  v_new_req text;
begin
  if p_request_id is null then
    raise exception using errcode = '22023', message = 'request_id 가 필요합니다 (list_managed_purchase_requests 의 request_id).';
  end if;
  if p_status is null or p_status not in ('submitted', 'pending', 'approved', 'completed', 'rejected') then
    raise exception using errcode = '22023', message = 'status 는 submitted · pending · approved · completed · rejected 중 하나입니다.';
  end if;
  if v_reason is not null and length(v_reason) > 500 then
    raise exception using errcode = '22023', message = 'reason 은 500자까지입니다.';
  end if;
  if p_row_ids is not null and cardinality(p_row_ids) > 200 then
    raise exception using errcode = '22023', message = 'row_ids 는 200개까지입니다.';
  end if;

  select * into v_req from purchase_requests where id = p_request_id;
  if v_req.id is null then
    raise exception using errcode = 'P0002', message = '구매 신청을 찾을 수 없습니다.';
  end if;
  perform mcp_private.pr_require_manager(v_req.page_id);
  select * into v_page from purchase_request_pages where id = v_req.page_id;

  -- 이 신청의 모든 행 · 값이 있는 행(빈 줄은 품목이 아니다)
  select coalesce(array_agg(e.v->>'id' order by e.ord), '{}'),
         coalesce(array_agg(e.v->>'id' order by e.ord) filter (where mcp_private.pr_row_meaningful(e.v->'cells', v_page.columns)), '{}')
    into v_every, v_all_ids
  from jsonb_array_elements(mcp_private.arr(v_req.items)) with ordinality e(v, ord);

  if p_row_ids is null or cardinality(p_row_ids) = 0 then
    v_target := v_all_ids;
    v_pass := null;                       -- 웹과 같이 «전체» = null
  else
    select coalesce(array_agg(x), '{}') into v_unknown from unnest(p_row_ids) x where not (x = any(v_every));
    if cardinality(v_unknown) > 0 then
      raise exception using errcode = '22023',
        message = format('이 신청에 없는 row_id 입니다: %s (list_managed_purchase_requests 의 row_id).', array_to_string(v_unknown, ', '));
    end if;
    v_target := (select array_agg(distinct x) from unnest(p_row_ids) x);
    v_pass := case when v_every <@ v_target then null else v_target end;
  end if;
  if coalesce(cardinality(v_target), 0) = 0 then
    raise exception using errcode = '22023', message = '바꿀 품목이 없습니다.';
  end if;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'row_id', t.rid,
           'item', mcp_private.obj(t.cells) ->> mcp_private.pr_name_col(v_page.columns),
           'before', t.st, 'before_label', mcp_private.pr_status_label(t.st),
           'before_reason', t.rs,
           'after', p_status, 'after_label', mcp_private.pr_status_label(p_status), 'after_reason', v_reason,
           'in_order', (select b.title || ' (' || mcp_private.pr_batch_label(b.status) || ')'
                          from purchase_order_line_items li
                          join purchase_order_lines l on l.id = li.line_id
                          join purchase_order_batches b on b.id = l.batch_id
                         where li.request_id = v_req.id and li.row_id = t.rid limit 1)
         )) order by t.ord), '[]'::jsonb),
         count(*) filter (where t.st is distinct from p_status or t.rs is distinct from v_reason)
    into v_items, v_changes
  from (
    select e.v->>'id' as rid, e.v->'cells' as cells, e.ord,
           mcp_private.pr_item_status(v_req.meta, v_req.status, e.v->>'id') as st,
           mcp_private.pr_item_reason(v_req.meta, v_req.status_reason, e.v->>'id') as rs
    from jsonb_array_elements(mcp_private.arr(v_req.items)) with ordinality e(v, ord)
    where e.v->>'id' = any(v_target)
  ) t;

  if v_changes = 0 then
    raise exception using errcode = '22023', message = '바꿀 것이 없습니다 — 모든 품목이 이미 그 상태·사유입니다.';
  end if;

  if coalesce(p_check_only, false) then
    return jsonb_build_object('check_only', true, 'request_id', v_req.id, 'status', p_status,
      'requester', (select mcp_private.pr_requester_label(res.type, res.name, res.meta) from resource res where res.id = v_req.requester_id),
      'items', v_items,
      'note', '아직 바꾸지 않았다 — 어느 품목이 어떻게 바뀌는지(특히 in_order: 이미 품의에 담긴 품목)를 사용자에게 보여 확인받은 뒤 check_only:false 로 다시 부른다. reason 을 안 보내면 기존 사유가 지워진다.');
  end if;

  perform public.set_purchase_request_item_status(v_req.id, p_status, v_pass, v_reason);
  select status into v_new_req from purchase_requests where id = v_req.id;

  perform mcp_private.log_call(v_me, 'set_purchase_item_status',
    jsonb_build_object('request_id', v_req.id, 'status', p_status, 'items', cardinality(v_target)));

  return jsonb_build_object('updated', true, 'request_id', v_req.id, 'status', p_status,
    'request_status', v_new_req, 'request_status_label', mcp_private.pr_status_label(v_new_req),
    'items', v_items,
    'note', '바꿨다(신청자에게 알림은 가지 않는다 — 신청자는 «내 신청 품목»에서 본다). 신청건 상태는 품목 상태에서 서버가 다시 정한다.');
end;
$$;


ALTER FUNCTION "public"."mcp_set_purchase_item_status"("p_request_id" "uuid", "p_status" "text", "p_row_ids" "text"[], "p_reason" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_purchase_order_status"("p_batch_id" "uuid", "p_status" "text", "p_check_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('purchase.request');
  v_batch  public.purchase_order_batches%rowtype;
  v_page   public.purchase_request_pages%rowtype;
  v_target text;
  v_prev   jsonb;
  v_n      integer;
  v_res    jsonb;
begin
  if p_batch_id is null then
    raise exception using errcode = '22023', message = 'batch_id 가 필요합니다 (list_purchase_orders 의 batch_id).';
  end if;
  if p_status is null or p_status not in ('draft', 'submitted', 'purchased') then
    raise exception using errcode = '22023', message = 'status 는 draft(작성 중) · submitted(품의 완료) · purchased(구매 완료) 중 하나입니다.';
  end if;
  select * into v_batch from purchase_order_batches where id = p_batch_id;
  if v_batch.id is null then
    raise exception using errcode = 'P0002', message = '품의 차수를 찾을 수 없습니다.';
  end if;
  perform mcp_private.pr_require_manager(v_batch.page_id);
  select * into v_page from purchase_request_pages where id = v_batch.page_id;

  v_target := case p_status when 'submitted' then 'approved' when 'purchased' then 'completed' end;

  -- 미리보기 — 웹 RPC 와 같은 조건(고아 연결은 건너뛴다)
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'request_id', t.request_id, 'row_id', t.row_id,
           'requester', mcp_private.pr_requester_label(t.rtype, t.rname, t.rmeta),
           'item', mcp_private.obj(t.cells) ->> mcp_private.pr_name_col(v_page.columns),
           'before', t.st, 'before_label', mcp_private.pr_status_label(t.st),
           'after', v_target, 'after_label', mcp_private.pr_status_label(v_target)
         )) order by t.created_at, t.ord) filter (where t.would), '[]'::jsonb),
         count(*) filter (where t.would)
    into v_prev, v_n
  from (
    select li.request_id, li.row_id, e.v->'cells' as cells, e.ord, r.created_at,
           res.type as rtype, res.name as rname, res.meta as rmeta,
           mcp_private.pr_item_status(r.meta, r.status, li.row_id) as st,
           (v_target = 'approved' and mcp_private.pr_item_status(r.meta, r.status, li.row_id) in ('submitted', 'pending'))
             or (v_target = 'completed' and mcp_private.pr_item_status(r.meta, r.status, li.row_id) not in ('completed', 'rejected')) as would
    from purchase_order_line_items li
    join purchase_order_lines l on l.id = li.line_id
    join purchase_requests r on r.id = li.request_id
    left join resource res on res.id = r.requester_id
    cross join lateral jsonb_array_elements(mcp_private.arr(r.items)) with ordinality e(v, ord)
    where l.batch_id = v_batch.id and e.v->>'id' = li.row_id
  ) t;

  if coalesce(p_check_only, false) then
    return jsonb_build_object('check_only', true, 'batch_id', v_batch.id, 'title', v_batch.title,
      'from', v_batch.status, 'from_label', mcp_private.pr_batch_label(v_batch.status),
      'to', p_status, 'to_label', mcp_private.pr_batch_label(p_status),
      'items_to_change', v_n, 'items', v_prev,
      'note', case when v_target is null
                   then '작성 중으로 바꾸는 것은 신청 품목 상태를 건드리지 않는다.'
                   else format('아직 바꾸지 않았다 — 연결된 신청 품목 %s개가 «%s» 로 바뀐다(신청자에게 알림은 가지 않는다). 사용자에게 보여 확인받은 뒤 check_only:false 로 다시 부른다.', v_n, mcp_private.pr_status_label(v_target)) end);
  end if;

  v_res := public.set_purchase_order_batch_status(v_batch.id, p_status);

  perform mcp_private.log_call(v_me, 'set_purchase_order_status',
    jsonb_build_object('page_id', v_batch.page_id, 'batch_id', v_batch.id, 'status', p_status, 'updated_items', v_res -> 'updatedItems'));

  return jsonb_build_object('updated', true, 'batch_id', v_batch.id, 'title', v_batch.title,
    'from', v_batch.status, 'to', p_status, 'to_label', mcp_private.pr_batch_label(p_status),
    'updated_items', coalesce((v_res ->> 'updatedItems')::integer, 0), 'items', v_prev,
    'note', case when v_target is null
                 then '품목 상태는 바꾸지 않았다(되돌리기·작성 중).'
                 else '연결된 신청 품목의 상태를 함께 바꿨다. 되돌려도 품목 상태는 자동으로 돌아가지 않는다 — set_purchase_item_status 로 품목마다.' end);
end;
$$;


ALTER FUNCTION "public"."mcp_set_purchase_order_status"("p_batch_id" "uuid", "p_status" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_schedule_survey_status"("p_survey_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('schedule.survey');
  v_row public.schedule_survey;
begin
  if p_status not in ('open', 'closed') then raise exception using errcode = '22023', message = 'status 는 open · closed 입니다.'; end if;
  if not coalesce(public.can_manage_schedule_survey(p_survey_id), false) then
    raise exception using errcode = 'P0002', message = '내가 만든 설문을 찾을 수 없습니다.';
  end if;
  update schedule_survey set status = p_status where id = p_survey_id returning * into v_row;
  return mcp_private.sv_survey_out(v_row, v_me) || jsonb_build_object('note',
    case p_status when 'closed' then '마감했다 — 더는 응답할 수 없다(알림은 가지 않는다, 웹과 같다).' else '다시 열었다.' end);
end;
$$;


ALTER FUNCTION "public"."mcp_set_schedule_survey_status"("p_survey_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_sign_request_due"("p_request_id" "uuid", "p_due_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('sign.request');
  v_due timestamptz;
begin
  if p_request_id is null or p_due_at is null then
    raise exception using errcode = '22023', message = 'request_id 와 due(새 마감)가 필요합니다.';
  end if;
  -- 요청자·관리자·진행 중·1시간 뒤~요청일+최대일 판정은 웹과 같은 함수 한 곳
  v_due := public.set_signature_due(p_request_id, p_due_at);
  perform mcp_private.log_call(v_me, 'set_sign_request_due', jsonb_build_object('request_id', p_request_id, 'due', v_due));
  return jsonb_build_object('request_id', p_request_id, 'due', to_char(v_due at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI'),
    'note', '마감을 바꿨다(서명자에게 알림은 가지 않는다). 마감이 지나면 요청은 만료·정리된다.');
end;
$$;


ALTER FUNCTION "public"."mcp_set_sign_request_due"("p_request_id" "uuid", "p_due_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_study_room_attendance"("p_room_id" "uuid", "p_date" "date", "p_status" "text", "p_seats" "text"[] DEFAULT NULL::"text"[], "p_students" "text"[] DEFAULT NULL::"text"[], "p_all_unchecked" boolean DEFAULT false, "p_period_id" integer DEFAULT NULL::integer, "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('studyroom.manage');
  v_room   public.study_rooms;
  v_status text := nullif(btrim(coalesce(p_status, '')), '');
  v_new    text;
  v_ids    uuid[];
  v_list   jsonb;
  v_miss   text[];
  v_n      integer;
begin
  perform mcp_private.sr_require_teacher();
  select * into v_room from study_rooms where id = p_room_id;
  if not found then raise exception using errcode = 'P0002', message = '열람실을 찾을 수 없습니다.'; end if;
  if p_date is null then raise exception using errcode = '22023', message = 'date 가 필요합니다.'; end if;
  if p_date > (now() at time zone 'Asia/Seoul')::date then
    raise exception using errcode = '22023', message = '오늘 이후 날짜는 출석 처리할 수 없습니다.';
  end if;
  v_new := case v_status when 'attended' then 'attended' when 'excused' then 'excused' when 'supplement' then 'supplement'
                         when 'clear' then null else 'bad' end;
  if v_new = 'bad' then raise exception using errcode = '22023', message = 'status 는 attended(출석) · excused(인정출석) · supplement(보완 — 순공 열람실) · clear(취소) 중 하나입니다.'; end if;
  if v_status = 'supplement' and not coalesce(v_room.is_sungong, false) then
    raise exception using errcode = '22023', message = '보완 출석은 순공 열람실에서만 쓴다.';
  end if;
  if coalesce(cardinality(p_seats), 0) = 0 and coalesce(cardinality(p_students), 0) = 0 and not coalesce(p_all_unchecked, false) then
    raise exception using errcode = '22023', message = '누구를 바꿀지(seats · students · all_unchecked) 하나는 있어야 합니다.';
  end if;

  with target as (
    select s.* from seat_reservations s
    where s.room_id = p_room_id and s.reservation_date = p_date and (p_period_id is null or s.period_id = p_period_id)
      and (s.seat_number = any(coalesce(p_seats, '{}'))
           or (coalesce(p_all_unchecked, false) and s.attendance_status is null)
           or exists (select 1 from profiles p join resource r on r.type = 'student' and r.meta->>'id' = split_part(p.email, '@', 1)
                       where p.id = s.student_id
                         and format('%s-%s-%s', r.meta->>'grade', r.meta->>'class', r.meta->>'number') = any(coalesce(p_students, '{}'))))
  )
  select array_agg(t.id), coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'seat', t.seat_number, 'period_id', t.period_id,
           'from', case t.attendance_status when 'attended' then '출석' when 'excused' then '인정출석' when 'supplement' then '보완' else '미확인' end,
           'to', case v_new when 'attended' then '출석' when 'excused' then '인정출석' when 'supplement' then '보완' else '미확인' end,
           'unchanged', case when t.attendance_status is not distinct from v_new then true end))
           || mcp_private.sr_student(t.student_id) order by t.period_id, t.seat_number), '[]'::jsonb)
    into v_ids, v_list from target t;

  -- 준 자리·학생 중 그 날 신청이 없는 것
  select array_agg(x) into v_miss from (
    select x from unnest(coalesce(p_seats, '{}')) x
     where not exists (select 1 from seat_reservations s where s.room_id = p_room_id and s.reservation_date = p_date
                         and (p_period_id is null or s.period_id = p_period_id) and s.seat_number = x)
    union all
    select x from unnest(coalesce(p_students, '{}')) x
     where not exists (select 1 from seat_reservations s join profiles p on p.id = s.student_id
                        join resource r on r.type = 'student' and r.meta->>'id' = split_part(p.email, '@', 1)
                       where s.room_id = p_room_id and s.reservation_date = p_date and (p_period_id is null or s.period_id = p_period_id)
                         and format('%s-%s-%s', r.meta->>'grade', r.meta->>'class', r.meta->>'number') = x)) m;

  if coalesce(p_check_only, true) or v_ids is null then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true, 'room', v_room.name, 'date', p_date,
      'count', coalesce(cardinality(v_ids), 0), 'changes', v_list,
      'not_found', case when cardinality(v_miss) > 0 then to_jsonb(v_miss) end,
      'note', case when v_ids is null then '바꿀 신청이 없다.'
                   else '아직 바꾸지 않았다 — 학생·자리·바뀜을 사용자에게 보여 확인받은 뒤 check_only:false. 출석·인정출석·보완은 학생에게 출석 코인이 자동으로 가고(금액 = 코인 경제 설정), 취소하면 회수된다.' end));
  end if;

  update seat_reservations
     set is_attended = v_new is not null,
         attendance_status = v_new,
         attended_at = case when v_new is null then null else now() end,
         checked_by = case when v_new is null then null else auth.uid() end
   where id = any(v_ids) and attendance_status is distinct from v_new;
  get diagnostics v_n = row_count;
  perform mcp_private.log_call(v_me, 'set_study_room_attendance',
    jsonb_build_object('room_id', p_room_id, 'date', p_date, 'status', coalesce(v_new, 'clear'), 'rows', v_n));
  return jsonb_strip_nulls(jsonb_build_object('saved', true, 'room', v_room.name, 'date', p_date, 'updated', v_n,
    'unchanged', cardinality(v_ids) - v_n,
    'not_found', case when cardinality(v_miss) > 0 then to_jsonb(v_miss) end));
end;
$$;


ALTER FUNCTION "public"."mcp_set_study_room_attendance"("p_room_id" "uuid", "p_date" "date", "p_status" "text", "p_seats" "text"[], "p_students" "text"[], "p_all_unchecked" boolean, "p_period_id" integer, "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_supervision_unavailability"("p_slots" "text"[], "p_weekday" integer DEFAULT NULL::integer, "p_date" "date" DEFAULT NULL::"date", "p_from" "date" DEFAULT NULL::"date", "p_until" "date" DEFAULT NULL::"date", "p_note" "text" DEFAULT NULL::"text", "p_teacher" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('supervision.mine');
  v_who   uuid := v_me;
  v_slots text[];
  v_id    uuid;
begin
  if (p_weekday is null) = (p_date is null) then
    raise exception using errcode = '22023', message = 'weekday(매주 1~6) 와 date(그날 하루) 중 하나만 준다.';
  end if;
  if p_weekday is not null and (p_weekday < 1 or p_weekday > 6) then raise exception using errcode = '22023', message = 'weekday 는 1(월)~6(토)입니다.'; end if;
  select coalesce(array_agg(distinct s), '{}') into v_slots from unnest(coalesce(p_slots, '{}')) s;
  if cardinality(v_slots) = 0 or exists (select 1 from unnest(v_slots) s where s not in ('morning', 'evening', 'saturday')) then
    raise exception using errcode = '22023', message = 'slots 는 morning · evening · saturday 중 하나 이상입니다.';
  end if;
  if p_from is not null and p_until is not null and p_until < p_from then raise exception using errcode = '22023', message = 'until 이 from 보다 앞입니다.'; end if;
  if char_length(coalesce(p_note, '')) > 200 then raise exception using errcode = '22023', message = '메모는 200자까지입니다.'; end if;
  if nullif(btrim(coalesce(p_teacher, '')), '') is not null then
    select p.id into v_who from mcp_private.sch_people(array[p_teacher]) p limit 1;
  end if;

  insert into supervision_unavailability (resource_id, weekday, on_date, slots, valid_from, valid_until, note)
  values (v_who, case when p_date is null then p_weekday end, p_date, v_slots,
          case when p_date is null then p_from end, case when p_date is null then p_until end, nullif(btrim(coalesce(p_note, '')), ''))
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'teacher', mcp_private.me_name(v_who), 'saved', true,
    'note', '자동 배정(draft_supervision)이 이 사정을 피한다. 이미 만든 감독은 바뀌지 않는다 — 교체로.');
end;
$$;


ALTER FUNCTION "public"."mcp_set_supervision_unavailability"("p_slots" "text"[], "p_weekday" integer, "p_date" "date", "p_from" "date", "p_until" "date", "p_note" "text", "p_teacher" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_task_status"("p_task_id" "uuid", "p_status" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.manage');
  t    public.task := mcp_private.wk_task(p_task_id);
begin
  if p_status is null or p_status not in ('pending', 'completed', 'cancelled') then
    raise exception using errcode = '22023', message = 'status 는 pending(진행 중) · completed(완료) · cancelled(취소) 중 하나입니다.';
  end if;
  if t.status = p_status then
    raise exception using errcode = '22023', message = format('이미 %s 상태입니다.', case p_status when 'pending' then '진행 중' when 'completed' then '완료' else '취소' end);
  end if;
  if char_length(coalesce(p_comment, '')) > 500 then raise exception using errcode = '22023', message = 'comment 는 500자까지입니다.'; end if;
  -- 상태·이력은 기존 함수 한 곳(task.status + task_status_history). 제출 가드 등 task 트리거는 그대로 받는다
  perform public.update_task_status(t.id, p_status, v_me, coalesce(nullif(btrim(p_comment), ''), '에이전트(MCP)'));
  perform mcp_private.log_call(v_me, 'set_task_status', jsonb_build_object('task_id', t.id, 'from', t.status, 'to', p_status));
  return jsonb_build_object('task_id', t.id, 'title', t.title, 'from', t.status, 'status', p_status,
    'note', case p_status
      when 'completed' then '할 일 전체를 완료로 했다 — 담당자 개인 상태는 그대로이고, 담당자들의 «내 할 일»에서는 빠진다(웹과 같다). 알림은 가지 않는다.'
      when 'cancelled' then '할 일을 취소했다 — 담당자들의 «내 할 일»에서 빠진다. 알림은 가지 않는다.'
      else '진행 중으로 되돌렸다.' end);
end;
$$;


ALTER FUNCTION "public"."mcp_set_task_status"("p_task_id" "uuid", "p_status" "text", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_training_sign_link_expiry"("p_schedule_id" "uuid", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_reset" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me   uuid := mcp_private.require_tool('schedule.manage');
  v_exp  timestamptz;
  v_info jsonb;
begin
  if not coalesce(p_reset, false) and p_expires_at is null then
    raise exception using errcode = '22023', message = 'expires(새 기한) 또는 reset:true(기본으로 되돌리기) 중 하나를 주세요.';
  end if;
  v_exp := public.set_training_sign_link_expiry(p_schedule_id, case when coalesce(p_reset, false) then null else p_expires_at end);
  v_info := public.get_training_sign_links(p_schedule_id);

  perform mcp_private.log_call(v_me, 'set_training_sign_link_expiry',
    jsonb_build_object('schedule_id', p_schedule_id, 'reset', coalesce(p_reset, false)));

  return jsonb_build_object(
    'schedule_id', p_schedule_id,
    'title', (select meta->>'title' from meeting where id = p_schedule_id),
    'expires_at', mcp_private.kst_ts(v_exp),
    'custom', not coalesce(p_reset, false),
    'signed', (select count(*) from jsonb_array_elements(v_info->'links') l where (l->>'signed')::boolean),
    'attendees', jsonb_array_length(coalesce(v_info->'links', '[]'::jsonb)),
    'note', '링크 주소는 get_training_sign_links(링크 = 그 사람의 서명 자격, 본인에게만). 참석자는 연수 알림을 누르면 자기 서명 QR 을 본다.');
end;
$$;


ALTER FUNCTION "public"."mcp_set_training_sign_link_expiry"("p_schedule_id" "uuid", "p_expires_at" timestamp with time zone, "p_reset" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_volunteer_class_roster"("p_issue_id" "uuid", "p_grade" integer, "p_class" integer, "p_students" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me       uuid := mcp_private.require_tool('issue.register');
  v_row      document_issue;
  v_students jsonb;
begin
  select * into v_row from document_issue where id = p_issue_id;
  if v_row.id is null then raise exception using errcode = 'P0002', message = '그 발급 기록을 찾을 수 없습니다 (list_issues 의 issue_id).'; end if;
  if v_row.doc_type <> 'volunteer_class' then
    raise exception using errcode = '22023', message = '단체(반별) 봉사 발급만 반별 명단을 바꿉니다.';
  end if;
  if v_row.status = 'cancelled' then raise exception using errcode = '22023', message = format('%s 은(는) 취소된 발급입니다.', v_row.issue_no); end if;
  if p_grade is null or p_class is null or p_grade not between 1 and 3 or p_class not between 1 and 20 then
    raise exception using errcode = '22023', message = 'grade(1~3)·class 가 필요합니다.';
  end if;
  if p_students is null or jsonb_typeof(p_students) <> 'array' then
    raise exception using errcode = '22023', message = 'students 는 그 반 학생 배열입니다(빈 배열 = 그 반을 명단에서 뺀다).';
  end if;
  v_students := case when jsonb_array_length(p_students) = 0 then '[]'::jsonb
                     -- 시간: 양식 값 > 그 반 학생에게 적힌 값 > 첫 학생의 값 > 1 (단체 봉사는 웹이 학생마다 적는다)
                     else mcp_private.iss_students(p_students, coalesce(
                       (v_row.form_data->>'hours')::numeric,
                       (select (s->>'hours')::numeric from jsonb_array_elements(coalesce(v_row.students, '[]'::jsonb)) s
                         where (s->>'grade')::int = p_grade and (s->>'class')::int = p_class and s ? 'hours' limit 1),
                       (v_row.students->0->>'hours')::numeric, 1)) end;
  if exists (select 1 from jsonb_array_elements(v_students) s where (s->>'grade')::int <> p_grade or (s->>'class')::int <> p_class) then
    raise exception using errcode = '22023', message = format('%s학년 %s반 학생만 넣을 수 있습니다(다른 반은 그 반으로 따로).', p_grade, p_class);
  end if;
  -- 권한(작성자·관리자·그 반 담임)·다른 반 보존은 웹과 같은 함수가 판정한다
  v_row := public.update_volunteer_class_roster(v_row.id, p_grade, p_class, v_students);

  perform mcp_private.log_call(v_me, 'set_volunteer_class_roster',
    jsonb_build_object('issue_id', v_row.id, 'grade', p_grade, 'class', p_class, 'count', jsonb_array_length(v_students)));
  return mcp_private.iss_row_out(v_row) || jsonb_build_object(
    'class', format('%s학년 %s반', p_grade, p_class),
    'class_students', (select coalesce(jsonb_agg(mcp_private.iss_student_label(s)), '[]'::jsonb) from jsonb_array_elements(v_students) s),
    'note', '그 반 명단만 바꿨다(다른 반은 그대로). 발급번호는 그대로다.');
end;
$$;


ALTER FUNCTION "public"."mcp_set_volunteer_class_roster"("p_issue_id" "uuid", "p_grade" integer, "p_class" integer, "p_students" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_sign_file_target"("p_request_id" "uuid", "p_which" "text" DEFAULT 'auto'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('sign.request');
  v_which text := coalesce(nullif(btrim(p_which), ''), 'auto');
  r       record;
  v_path  text;
  v_kind  text;
begin
  if v_which not in ('auto', 'original', 'signed') then
    raise exception using errcode = '22023', message = 'which 는 auto · original · signed 중 하나입니다.';
  end if;
  if jsonb_array_length(mcp_private.sign_items('all', true, 'signature', p_request_id)) = 0 then
    raise exception using errcode = 'P0002', message = '전자서명 요청을 찾을 수 없습니다(내가 올렸거나 서명자에 있는 요청만).';
  end if;
  select sr.title, sr.source_path, sr.source_name, sr.signed_path, sr.status, sr.purged_at into r
    from signature_request sr where sr.id = p_request_id;
  if r.purged_at is not null then
    raise exception using errcode = 'P0002', message = '문서 파일이 이미 정리됐습니다(끝난 뒤 7일). Drive 로 옮겼다면 Drive 에서 받으세요.';
  end if;
  if v_which = 'signed' or (v_which = 'auto' and r.signed_path is not null) then
    if r.signed_path is null then
      raise exception using errcode = 'P0002', message = case when r.status = 'completed'
        then '완성본이 아직 저장되지 않았거나 Drive 로 옮겨졌습니다 — 웹에서 열면 완성본을 만듭니다.'
        else '서명이 끝나지 않아 완성본이 없습니다(원본은 which: original).' end;
    end if;
    v_path := r.signed_path; v_kind := 'signed';
  else
    if r.source_path is null then
      raise exception using errcode = 'P0002', message = '원본 파일이 없습니다.';
    end if;
    v_path := r.source_path; v_kind := 'original';
  end if;
  -- 경로는 이 요청의 폴더 안이어야 한다(저장소 정책과 같은 규약 — 첫 세그먼트 = 요청 id)
  if split_part(v_path, '/', 1) <> p_request_id::text then
    raise exception 'sign file path shape';
  end if;
  perform mcp_private.log_call(v_me, 'get_sign_file', jsonb_build_object('which', v_kind));
  return jsonb_build_object('path', v_path, 'which', v_kind, 'title', r.title, 'file_name', r.source_name, 'status', r.status);
end;
$$;


ALTER FUNCTION "public"."mcp_sign_file_target"("p_request_id" "uuid", "p_which" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_simulate_budget_revision"("p_project_id" "uuid", "p_mode" "text" DEFAULT 'propose'::"text", "p_amounts" "jsonb" DEFAULT NULL::"jsonb", "p_leftover_line_id" "uuid" DEFAULT NULL::"uuid", "p_new_lines" "jsonb" DEFAULT NULL::"jsonb", "p_title" "text" DEFAULT NULL::"text", "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('budget.manage');
  v_draft budget_revision;
  v_map jsonb := '{}'::jsonb;  -- line_id → amount (지금 초안)
  v_total bigint;
  v_sum bigint;
  v_left bigint;
  v_x jsonb;
  v_new_id uuid;
  v_check jsonb;
  v_rows jsonb;
begin
  perform mcp_private.bg_require_edit(p_project_id);
  if coalesce(p_mode, 'propose') not in ('propose', 'set') then
    raise exception using errcode = '22023', message = 'mode 는 propose(제안대로) · set(금액 넣기) 중 하나입니다.';
  end if;
  if p_leftover_line_id is not null and not exists (select 1 from budget_line where id = p_leftover_line_id and project_id = p_project_id) then
    raise exception using errcode = '22023', message = 'leftover_line_id 가 이 사업의 산출내역이 아닙니다.';
  end if;
  select * into v_draft from budget_revision where project_id = p_project_id and status = 'draft';
  if v_draft.id is not null then
    select coalesce(jsonb_object_agg(line_id::text, amount), '{}'::jsonb) into v_map from budget_revision_line where revision_id = v_draft.id;
  end if;

  if coalesce(p_mode, 'propose') = 'propose' then
    v_map := '{}'::jsonb;
    select coalesce(jsonb_object_agg(line_id::text, proposed), '{}'::jsonb), coalesce(sum(budget), 0), coalesce(sum(proposed), 0)
      into v_map, v_total, v_sum from mcp_private.bg_lines(p_project_id);
    v_left := v_total - v_sum;
    if p_leftover_line_id is not null and v_left <> 0 then
      v_map := v_map || jsonb_build_object(p_leftover_line_id::text, (v_map ->> p_leftover_line_id::text)::bigint + v_left);
      v_left := 0;
    end if;
  else
    if jsonb_typeof(p_amounts) is distinct from 'array' then
      raise exception using errcode = '22023', message = 'mode set 에는 amounts = [{line_id, amount}] 가 필요합니다.';
    end if;
    for v_x in select * from jsonb_array_elements(p_amounts) loop
      if not exists (select 1 from budget_line where id = (v_x ->> 'line_id')::uuid and project_id = p_project_id) then
        raise exception using errcode = '22023', message = format('이 사업의 산출내역이 아닙니다: %s', v_x ->> 'line_id');
      end if;
      v_map := v_map || jsonb_build_object(v_x ->> 'line_id', (v_x ->> 'amount')::bigint);
    end loop;
  end if;

  v_check := mcp_private.bg_check(p_project_id, v_map);
  select jsonb_agg(jsonb_build_object('line_id', l.line_id, 'name', l.name, 'now', l.budget, 'wonin', l.wonin, 'pumui', l.pumui,
           'proposed', l.proposed, 'after', coalesce((v_map ->> l.line_id::text)::bigint, l.budget),
           'delta', coalesce((v_map ->> l.line_id::text)::bigint, l.budget) - l.budget) order by l.sort_order)
    into v_rows from mcp_private.bg_lines(p_project_id) l;

  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true,
      'draft_exists', v_draft.id is not null,
      'lines', v_rows,
      'new_lines', p_new_lines,
      'leftover', case when coalesce(p_mode, 'propose') = 'propose' then v_left end,
      'check', v_check,
      'note', '아직 초안에 쓰지 않았다 — 표·검사(total_mismatch·issues)를 사용자에게 보여 확인받은 뒤 check_only:false. '
              || 'leftover 가 0 이 아니면 어느 줄에 넣을지(leftover_line_id) 묻는다. 확정은 confirm_budget_revision.'));
  end if;

  if v_draft.id is null then
    insert into budget_revision (project_id, seq, title)
    values (p_project_id, (select coalesce(max(seq), -1) + 1 from budget_revision where project_id = p_project_id),
            coalesce(nullif(btrim(p_title), ''),
                     (select count(*) + 1 from budget_revision where project_id = p_project_id and source = 'manual' and status = 'confirmed') || '회 추경 (초안)'))
    returning * into v_draft;
  elsif p_title is not null then
    update budget_revision set title = btrim(p_title) where id = v_draft.id;
  end if;

  -- 신설 줄
  if jsonb_typeof(p_new_lines) = 'array' then
    for v_x in select * from jsonb_array_elements(p_new_lines) loop
      if length(btrim(coalesce(v_x ->> 'name', ''))) = 0 then
        raise exception using errcode = '22023', message = 'new_lines 의 줄마다 name 이 필요합니다.';
      end if;
      insert into budget_line (project_id, name, expense_item, budget_amount, origin, sort_order)
      values (p_project_id, btrim(v_x ->> 'name'), nullif(btrim(coalesce(v_x ->> 'expense_item', '')), ''), 0, 'manual',
              (select coalesce(max(sort_order), 0) + 1 from budget_line where project_id = p_project_id))
      returning id into v_new_id;
      v_map := v_map || jsonb_build_object(v_new_id::text, coalesce((v_x ->> 'amount')::bigint, 0));
    end loop;
  end if;

  -- 초안 줄 = 지금 예산과 다른 줄만
  delete from budget_revision_line where revision_id = v_draft.id;
  insert into budget_revision_line (revision_id, project_id, line_id, amount)
  select v_draft.id, p_project_id, l.id, (v_map ->> l.id::text)::bigint
    from budget_line l
   where l.project_id = p_project_id and v_map ? l.id::text and (v_map ->> l.id::text)::bigint <> l.budget_amount;

  perform mcp_private.log_call(v_me, 'simulate_budget_revision', jsonb_build_object('project_id', p_project_id, 'revision_id', v_draft.id, 'mode', p_mode));
  return jsonb_build_object('saved', true, 'revision_id', v_draft.id, 'title', (select title from budget_revision where id = v_draft.id),
    'check', mcp_private.bg_check(p_project_id, (select coalesce(jsonb_object_agg(line_id::text, amount), '{}'::jsonb)
                                                  from budget_revision_line where revision_id = v_draft.id)),
    'note', '웹 «예산 › 추경» 초안에 보인다. 확정은 confirm_budget_revision(check_only 먼저).');
end;
$$;


ALTER FUNCTION "public"."mcp_simulate_budget_revision"("p_project_id" "uuid", "p_mode" "text", "p_amounts" "jsonb", "p_leftover_line_id" "uuid", "p_new_lines" "jsonb", "p_title" "text", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_submit_purchase_request"("p_page_id" "uuid", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('purchase.request');
  v_page  public.purchase_request_pages;
  v_rows  jsonb := '[]'::jsonb;
  v_out   jsonb := '[]'::jsonb;
  v_el    jsonb;
  v_i     integer;
  v_cells jsonb;
  v_rid   text;
  v_id    uuid;
  v_total numeric := 0;
  v_has_total boolean := false;
begin
  if p_page_id is null then
    raise exception using errcode = '22023', message = 'page_id 가 필요합니다.';
  end if;
  select * into v_page from purchase_request_pages where id = p_page_id;
  if v_page.id is null then
    raise exception using errcode = 'P0002', message = '신청 페이지를 찾을 수 없습니다.';
  end if;
  perform mcp_private.pr_require_open(v_page, '신청할');

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception using errcode = '22023', message = 'items 에 품목을 1개 이상 넣어 주세요.';
  end if;
  if jsonb_array_length(p_items) > 30 then
    raise exception using errcode = '22023', message = '한 번에 30개 품목까지 신청할 수 있습니다.';
  end if;

  for v_el, v_i in select e, o::integer from jsonb_array_elements(p_items) with ordinality t(e, o) loop
    v_cells := mcp_private.pr_build_cells(
                 case when jsonb_typeof(v_el) = 'object' and v_el ? 'cells' then v_el->'cells' else v_el end,
                 v_page.columns, '{}'::jsonb, format('%s번째 품목', v_i));
    v_rid := mcp_private.pr_row_id(v_i) || v_i::text;
    v_rows := v_rows || jsonb_build_array(jsonb_build_object('id', v_rid, 'cells', v_cells));
    v_out := v_out || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
               'row_id', v_rid, 'item', v_cells ->> mcp_private.pr_name_col(v_page.columns),
               'amount', mcp_private.pr_amount(v_cells, v_page.columns))));
    if mcp_private.pr_amount(v_cells, v_page.columns) is not null then
      v_total := v_total + mcp_private.pr_amount(v_cells, v_page.columns);
      v_has_total := true;
    end if;
  end loop;

  insert into purchase_requests (page_id, requester_id, items, status, meta)
  values (p_page_id, v_me, v_rows, 'submitted',
          jsonb_build_object('via', jsonb_build_object(
            'channel', 'mcp', 'client_id', nullif(auth.jwt() ->> 'client_id', ''), 'at', now())))
  returning id into v_id;

  perform mcp_private.log_call(v_me, 'submit_purchase_request',
    jsonb_build_object('page_id', p_page_id, 'request_id', v_id, 'items', jsonb_array_length(v_rows)));

  return jsonb_strip_nulls(jsonb_build_object(
    'request_id', v_id, 'page_title', v_page.title, 'items', v_out,
    'total', case when v_has_total then v_total end,
    'note', '신청했다. 페이지 담당자에게(내가 담당자면 나는 빼고) 새 신청 알림이 간다. 처리 상태는 list_my_purchase_requests 로 본다.'
  ));
end;
$$;


ALTER FUNCTION "public"."mcp_submit_purchase_request"("p_page_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_supervision_sources"("p_grade" integer, "p_year" integer, "p_month" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('supervision.plan');
  v_m   record;
  v_ay  integer;
  v_sm  jsonb;
begin
  perform mcp_private.sv_require_grade(v_me, p_grade);
  select * into v_m from mcp_private.check_month(p_year, p_month);
  v_ay := case when p_month >= 3 then p_year else p_year - 1 end;
  if p_grade <> 0 then
    select coalesce(jsonb_agg(h.duty_date), '[]'::jsonb) into v_sm
    from public.get_self_study_supervision_history(0, make_date(v_ay, 3, 1), v_m.m_to) h where h.slot = 'morning';
  end if;
  return jsonb_build_object(
    'today', (now() at time zone 'Asia/Seoul')::date,
    'grade', p_grade, 'year', p_year, 'month', p_month, 'academic_year', v_ay,
    'pool', (select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'grades', to_jsonb(p.grades)) order by p.name), '[]'::jsonb)
             from mcp_private.sv_pool(p_grade, v_ay) p),
    'rooms', (select coalesce(jsonb_agg(jsonb_build_object('name', s.name, 'grades', to_jsonb(s.grades), 'operating_days', to_jsonb(s.operating_days),
                'operating_periods', to_jsonb(s.operating_periods))), '[]'::jsonb)
              from study_rooms s where s.is_active),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('meeting_id', h.meeting_id, 'date', h.duty_date, 'slot', h.slot,
                  'with_morning', coalesce(h.with_morning, false), 'names', to_jsonb(coalesce(h.names, '{}')))), '[]'::jsonb)
                from public.get_self_study_supervision_history(p_grade, make_date(v_ay, 3, 1), v_m.m_to) h),
    'school_morning_dates', (select coalesce(jsonb_agg(x), '[]'::jsonb) from jsonb_array_elements_text(coalesce(v_sm, '[]')) x
                             where x::date between v_m.m_from and v_m.m_to),
    'school_morning_in_year', coalesce(jsonb_array_length(v_sm), 0) > 0,
    'calendar_rows', mcp_private.schedule_rows(v_m.m_from, v_m.m_to),
    'csat_rows', case when p_grade = 0 then mcp_private.schedule_rows(make_date(v_ay, 9, 1), make_date(v_ay, 12, 31)) else '[]'::jsonb end,
    'absences', mcp_private.month_absences(v_m.m_from, v_m.m_to),
    'unavailability', (select coalesce(jsonb_agg(jsonb_build_object('name', r.name, 'weekday', u.weekday, 'date', u.on_date,
                         'from', u.valid_from, 'until', u.valid_until, 'slots', to_jsonb(u.slots), 'note', u.note)), '[]'::jsonb)
                       from supervision_unavailability u join resource r on r.id = u.resource_id));
end;
$$;


ALTER FUNCTION "public"."mcp_supervision_sources"("p_grade" integer, "p_year" integer, "p_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_swap_sources"("p_day" integer, "p_period" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('swap.class');
  v_term   record;
  v_roster jsonb;
begin
  if p_day is null or p_day < 1 or p_day > 5 then raise exception using errcode = '22023', message = 'day 는 1(월)~5(금)입니다.'; end if;
  perform mcp_private.check_period(p_period);
  select * into v_term from mcp_private.current_term();

  -- 수강생 판정(교사·관리자만 — 실패하면 표기로만 고른다고 화면이 말한다). 학생 이름 칸은 싣지 않는다
  begin
    select coalesce(jsonb_agg(jsonb_build_object(
             'teacher_resource_id', f.teacher_resource_id, 'day_of_week', f.day_of_week, 'period', f.period,
             'my_count', f.my_count, 'their_count', f.their_count, 'shared_count', f.shared_count,
             'their_conflict_count', f.their_conflict_count, 'my_conflict_count', f.my_conflict_count)), '[]'::jsonb)
      into v_roster
    from public.get_swap_roster_fit(v_me, p_day, p_period, v_term.academic_year, v_term.semester) f;
  exception when others then
    v_roster := null;
  end;

  return jsonb_build_object(
    'me', jsonb_build_object('resource_id', v_me, 'name', mcp_private.me_name(v_me)),
    'weekday', p_day, 'period', p_period,
    'entries', (select coalesce(jsonb_agg(to_jsonb(e)), '[]'::jsonb)
                from public.get_teacher_timetables_for_swap(0, 0, v_term.academic_year, v_term.semester) e),
    'roster_fit', v_roster,
    'excluded_ids', (select coalesce(jsonb_agg(x), '[]'::jsonb) from mcp_private.sw_excluded() x),
    'teachers', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name) order by r.name), '[]'::jsonb)
                 from resource r where r.type = 'teacher' and coalesce(r.status, 'active') = 'active'));
end;
$$;


ALTER FUNCTION "public"."mcp_swap_sources"("p_day" integer, "p_period" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_action"("p_action_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_settings" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.manage');
  a public.task_action; def record; v_warn text; v_cfg jsonb; s jsonb := coalesce(p_settings, '{}'); v_n int;
begin
  select * into a from task_action where id = p_action_id and archived_at is null;
  if a.id is null or a.task_id is null then raise exception using errcode = 'P0002', message = '그 작업을 찾지 못했습니다.'; end if;
  perform mcp_private.wk_task(a.task_id);
  select * into def from mcp_private.wk_action_def(a.action_type);
  if def.kind is null then raise exception using errcode = '22023', message = format('«%s» 는 이 연결로 고칠 수 없는 종류입니다 — 웹에서.', a.title); end if;
  if p_title is not null and (btrim(p_title) = '' or length(btrim(p_title)) > 120) then raise exception using errcode = '22023', message = 'title 은 1~120자입니다.'; end if;

  if def.kind in ('collect', 'submit') then
    v_warn := public.update_collect_config(p_action_id, mcp_private.wk_request_config(a.action_type, nullif(btrim(coalesce(p_title, '')), ''), s,
      case when def.kind = 'submit' then a.config->'submit' else a.config->'collect' end))->>'warning';
  elsif def.kind = 'message' then
    perform public.update_message_config(p_action_id, mcp_private.wk_request_config(a.action_type, nullif(btrim(coalesce(p_title, '')), ''), s, a.config->'message'));
  else
    v_cfg := a.config;
    if def.kind = 'neis' and s ? 'screens' then
      if jsonb_array_length(mcp_private.arr(s->'screens')) not between 1 and 10 then raise exception using errcode = '22023', message = 'screens 는 1~10개입니다.'; end if;
      v_cfg := jsonb_set(v_cfg, '{neis}', mcp_private.obj(v_cfg->'neis') || jsonb_build_object('version', 1, 'screens', s->'screens'));
    end if;
    if def.kind = 'neis' and s ? 'note' then v_cfg := jsonb_set(v_cfg, '{neis}', mcp_private.obj(v_cfg->'neis') || jsonb_build_object('note', s->>'note')); end if;
    if def.kind = 'external' and (s ? 'system' or s ? 'screens' or s ? 'system_url') then
      v_cfg := jsonb_set(v_cfg, '{external}', mcp_private.obj(v_cfg->'external') || jsonb_strip_nulls(jsonb_build_object('version', 1,
        'system', s->>'system', 'systemUrl', s->>'system_url', 'screens', s->'screens')));
    end if;
    if def.kind = 'docgen' and s ? 'generation_id' then
      v_cfg := v_cfg || jsonb_build_object('defaultTemplate', mcp_private.wk_generation_template((s->>'generation_id')::uuid));
    end if;
    update task_action set config = v_cfg, title = coalesce(nullif(btrim(p_title), ''), title), updated_at = now() where id = p_action_id;
    get diagnostics v_n = row_count;
    if v_n = 0 then raise exception using errcode = '42501', message = '이 작업은 만든 사람만 고칠 수 있습니다(웹과 같다).'; end if;
  end if;
  perform mcp_private.log_call(v_me, 'update_action', jsonb_build_object('action_id', p_action_id));
  return jsonb_strip_nulls(jsonb_build_object('action_id', p_action_id, 'title', (select title from task_action where id = p_action_id), 'warning', v_warn));
end $$;


ALTER FUNCTION "public"."mcp_update_action"("p_action_id" "uuid", "p_title" "text", "p_settings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_code_project"("p_project_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT NULL::"text", "p_tags" "text"[] DEFAULT NULL::"text"[], "p_files" "jsonb" DEFAULT NULL::"jsonb", "p_delete_paths" "text"[] DEFAULT NULL::"text"[], "p_kind" "text" DEFAULT NULL::"text", "p_entry_path" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('code.share');
  v_p   public.code_project;
  v_res jsonb;
  v_changed text[] := '{}';
begin
  select * into v_p from code_project where id = p_project_id;
  if not found or not public.can_edit_code_project(p_project_id) then
    raise exception using errcode = '42501', message = '내 프로젝트만 고칠 수 있습니다.';
  end if;
  if p_title is not null then
    v_p.title := mcp_private.opt_text(p_title, 'title', 120);
    if v_p.title is null then raise exception using errcode = '22023', message = '제목은 비울 수 없습니다.'; end if;
    v_changed := v_changed || 'title'::text;
  end if;
  if p_description is not null then v_p.description := mcp_private.opt_text(p_description, 'description', 2000); v_changed := v_changed || 'description'::text; end if;
  if p_visibility is not null then
    if p_visibility not in ('school', 'link', 'private') then raise exception using errcode = '22023', message = 'visibility 는 school · link · private 중 하나입니다.'; end if;
    v_p.visibility := p_visibility; v_changed := v_changed || 'visibility'::text;
  end if;
  if p_tags is not null then
    if cardinality(p_tags) > 10 then raise exception using errcode = '22023', message = '태그는 10개까지입니다.'; end if;
    v_p.tags := coalesce((select array_agg(distinct btrim(t)) from unnest(p_tags) t where btrim(t) <> ''), '{}'); v_changed := v_changed || 'tags'::text;
  end if;
  if p_files is not null or p_delete_paths is not null then
    v_res := mcp_private.code_apply_files(p_project_id, p_files, p_delete_paths);
    v_changed := v_changed || 'files'::text;
  end if;
  if p_kind is not null then
    if p_kind not in ('html', 'static', 'node', 'skill', 'other') then raise exception using errcode = '22023', message = 'kind 가 올바르지 않습니다.'; end if;
    v_p.kind := p_kind; v_p.entry_path := nullif(btrim(coalesce(p_entry_path, '')), '');
  end if;
  if cardinality(v_changed) = 0 then raise exception using errcode = '22023', message = '바꿀 것이 없습니다.'; end if;

  update code_project
     set title = v_p.title, description = v_p.description, visibility = v_p.visibility, tags = v_p.tags,
         kind = v_p.kind, entry_path = v_p.entry_path, updated_at = now()
   where id = p_project_id;
  if not found then raise exception using errcode = '42501', message = '이 프로젝트를 고칠 권한이 없습니다.'; end if;
  select * into v_p from code_project where id = p_project_id;
  perform mcp_private.log_call(v_me, 'update_code_project', jsonb_build_object('changed', v_changed));
  return jsonb_build_object('changed', v_changed, 'project', mcp_private.code_out(v_p), 'files', v_res);
end;
$$;


ALTER FUNCTION "public"."mcp_update_code_project"("p_project_id" "uuid", "p_title" "text", "p_description" "text", "p_visibility" "text", "p_tags" "text"[], "p_files" "jsonb", "p_delete_paths" "text"[], "p_kind" "text", "p_entry_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_document"("p_document_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_folder" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_keywords" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me   uuid := mcp_private.require_tool('document.library');
  v_doc  public.documents;
  v_meta jsonb;
  v_changed text[] := '{}';
begin
  if p_document_id is null then raise exception using errcode = '22023', message = 'document_id 가 필요합니다.'; end if;
  select * into v_doc from documents where id = p_document_id;
  if not found then raise exception using errcode = 'P0002', message = '문서를 찾을 수 없습니다.'; end if;
  if not coalesce(v_doc.user_id = auth.uid(), false) and not public.is_admin() then
    raise exception using errcode = '42501', message = '내가 올린 문서만 고칠 수 있습니다.';
  end if;

  v_meta := coalesce(v_doc.meta, '{}'::jsonb);
  if p_title is not null then
    if btrim(p_title) = '' then raise exception using errcode = '22023', message = '제목은 비울 수 없습니다.'; end if;
    v_doc.title := mcp_private.opt_text(p_title, 'title', 200); v_changed := v_changed || 'title'::text;
  end if;
  if p_folder is not null then
    if mcp_private.doc_folder(p_folder) is null then raise exception using errcode = '22023', message = '폴더는 비울 수 없습니다.'; end if;
    v_meta := v_meta || jsonb_build_object('directory_path', mcp_private.doc_folder(p_folder)); v_changed := v_changed || 'folder'::text;
  end if;
  if p_category is not null then
    v_meta := v_meta || jsonb_build_object('category', coalesce(mcp_private.opt_text(p_category, 'category', 50), '')); v_changed := v_changed || 'category'::text;
  end if;
  if p_description is not null then
    v_meta := v_meta || jsonb_build_object('description', coalesce(mcp_private.opt_text(p_description, 'description', 2000), '')); v_changed := v_changed || 'description'::text;
  end if;
  if p_keywords is not null then
    if cardinality(p_keywords) > 20 then raise exception using errcode = '22023', message = '키워드는 20개까지입니다.'; end if;
    v_meta := v_meta || jsonb_build_object('keywords', coalesce((select jsonb_agg(distinct btrim(k)) from unnest(p_keywords) k where btrim(k) <> ''), '[]'::jsonb));
    v_changed := v_changed || 'keywords'::text;
  end if;
  if cardinality(v_changed) = 0 then raise exception using errcode = '22023', message = '바꿀 칸이 없습니다.'; end if;

  update documents set title = v_doc.title, meta = v_meta, updated_at = now() where id = p_document_id;
  if not found then raise exception using errcode = '42501', message = '이 문서를 고칠 권한이 없습니다.'; end if;
  select * into v_doc from documents where id = p_document_id;
  return jsonb_build_object('changed', v_changed, 'document', mcp_private.doc_out(v_doc),
    'note', case when 'folder' = any(v_changed) and v_doc.storage_path ~ '^https?://' and coalesce((v_doc.meta->>'is_google_drive_file')::boolean, false)
                 then '서류함의 폴더만 옮겼다 — 구글 드라이브 안의 파일 위치는 그대로다.' end);
end;
$$;


ALTER FUNCTION "public"."mcp_update_document"("p_document_id" "uuid", "p_title" "text", "p_folder" "text", "p_category" "text", "p_description" "text", "p_keywords" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_document_generation"("p_action_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_public" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('docgen.create');
  a       public.task_action := mcp_private.dg_my_method(p_action_id);
  v_title text := coalesce(btrim(p_title), a.title);
  v_desc  text := case when p_description is null then a.description else nullif(btrim(p_description), '') end;
  v_cfg   jsonb := coalesce(a.config, '{}'::jsonb);
begin
  if p_title is null and p_description is null and p_public is null then
    raise exception using errcode = '22023', message = '바꿀 것(title · description · public)을 하나 이상 주세요.';
  end if;
  if v_title = '' or char_length(v_title) > 200 then raise exception using errcode = '22023', message = 'title 은 1~200자입니다.'; end if;
  if char_length(coalesce(v_desc, '')) > 4000 then raise exception using errcode = '22023', message = 'description 은 4000자까지입니다.'; end if;
  -- 공개는 웹과 같이 키를 지우지 않고 'public' · 'private' 을 적는다(setDocGenActionVisibility)
  if p_public is not null then v_cfg := v_cfg || jsonb_build_object('visibility', case when p_public then 'public' else 'private' end); end if;
  update task_action set title = v_title, description = v_desc, config = v_cfg where id = a.id;
  perform mcp_private.log_call(v_me, 'update_document_generation', jsonb_build_object('action_id', a.id, 'title', v_title, 'public', p_public));
  return jsonb_build_object('action_id', a.id, 'title', v_title, 'description', v_desc, 'visibility', v_cfg->>'visibility',
    'note', '고쳤다. 채울 자리(이름·지시)는 웹 문서 생성의 [채울 자리 고치기]에서.');
end;
$$;


ALTER FUNCTION "public"."mcp_update_document_generation"("p_action_id" "uuid", "p_title" "text", "p_description" "text", "p_public" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_gajeong_issue"("p_issue_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_issued_on" "date" DEFAULT NULL::"date", "p_department" "text" DEFAULT NULL::"text", "p_remarks" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me  uuid := mcp_private.require_tool('issue.register');
  v_row document_issue := mcp_private.iss_lock_mine(p_issue_id, array['gajeong'], '고칠');
begin
  if p_title is null and p_issued_on is null and p_department is null and p_remarks is null then
    raise exception using errcode = '22023', message = '바꿀 칸(title · issued_on · department · remarks)을 하나 이상 주세요.';
  end if;
  if p_title is not null and (btrim(p_title) = '' or length(p_title) > 200) then
    raise exception using errcode = '22023', message = 'title 은 1~200자입니다(지울 수 없다).';
  end if;

  update document_issue set
    title = coalesce(btrim(p_title), title),
    issued_on = coalesce(p_issued_on, issued_on),
    department = case when p_department is null then department else nullif(btrim(p_department), '') end,
    remarks = case when p_remarks is null then remarks else nullif(btrim(p_remarks), '') end,
    meta = meta || jsonb_build_object('via_updated', mcp_private.iss_via())
  where id = v_row.id
  returning * into v_row;
  if not found then
    raise exception using errcode = '42501', message = '고치지 못했습니다(작성자·관리자만).';
  end if;

  perform mcp_private.log_call(v_me, 'update_gajeong_issue', jsonb_build_object('issue_id', v_row.id, 'issue_no', v_row.issue_no));
  return mcp_private.iss_row_out(v_row) || jsonb_strip_nulls(jsonb_build_object('remarks', v_row.remarks));
end;
$$;


ALTER FUNCTION "public"."mcp_update_gajeong_issue"("p_issue_id" "uuid", "p_title" "text", "p_issued_on" "date", "p_department" "text", "p_remarks" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_ipsi_news"("p_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_article_date" "date" DEFAULT NULL::"date", "p_content" "text" DEFAULT NULL::"text", "p_headline_summary" "text" DEFAULT NULL::"text", "p_core_points" "text"[] DEFAULT NULL::"text"[], "p_strategy_implications" "text"[] DEFAULT NULL::"text"[], "p_data_points" "text"[] DEFAULT NULL::"text"[], "p_cautions" "text"[] DEFAULT NULL::"text"[], "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('ipsi.hub');
  o public.educational_news;
  n public.educational_news;
  v_changes jsonb;
begin
  perform mcp_private.ipsi_teacher();
  if not public.is_admin() then
    raise exception using errcode = '42501', message = '기사 고치기는 관리자만 됩니다(웹과 같은 권한).';
  end if;
  select * into o from educational_news where id = p_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = '그 기사가 없습니다.';
  end if;
  if p_category is not null and p_category not in ('수시', '정시', '진로', '대입', '전형분석', '학생부', '기타') then
    raise exception using errcode = '22023', message = 'category 는 수시 · 정시 · 진로 · 대입 · 전형분석 · 학생부 · 기타 중 하나입니다.';
  end if;
  if length(coalesce(p_title, '')) > 300 or length(coalesce(p_content, '')) > 60000 or length(coalesce(p_headline_summary, '')) > 500 then
    raise exception using errcode = '22023', message = 'title 300자 · content 60000자 · headline_summary 500자까지입니다.';
  end if;
  n := o;
  n.title := coalesce(nullif(btrim(coalesce(p_title, '')), ''), o.title);
  n.category := coalesce(p_category, o.category);
  n.article_date := coalesce(p_article_date, o.article_date);
  n.content := case when p_content is null then o.content else nullif(btrim(p_content), '') end;
  n.headline_summary := case when p_headline_summary is null then o.headline_summary else nullif(btrim(p_headline_summary), '') end;
  n.core_points := coalesce(mcp_private.ipsi_lines(p_core_points, 'core_points'), o.core_points);
  n.strategy_implications := coalesce(mcp_private.ipsi_lines(p_strategy_implications, 'strategy_implications'), o.strategy_implications);
  n.data_points := coalesce(mcp_private.ipsi_lines(p_data_points, 'data_points'), o.data_points);
  n.cautions := coalesce(mcp_private.ipsi_lines(p_cautions, 'cautions'), o.cautions);
  select coalesce(jsonb_agg(jsonb_build_object('field', f, 'before', b, 'after', a)), '[]'::jsonb) into v_changes
  from (values
    ('title', to_jsonb(o.title), to_jsonb(n.title)),
    ('category', to_jsonb(o.category), to_jsonb(n.category)),
    ('article_date', to_jsonb(o.article_date), to_jsonb(n.article_date)),
    ('content', to_jsonb(left(o.content, 200)), to_jsonb(left(n.content, 200))),
    ('summary', to_jsonb(o.headline_summary), to_jsonb(n.headline_summary)),
    ('core_points', to_jsonb(o.core_points), to_jsonb(n.core_points)),
    ('strategy_implications', to_jsonb(o.strategy_implications), to_jsonb(n.strategy_implications)),
    ('data_points', to_jsonb(o.data_points), to_jsonb(n.data_points)),
    ('cautions', to_jsonb(o.cautions), to_jsonb(n.cautions))
  ) x(f, b, a)
  where b is distinct from a or (f = 'content' and o.content is distinct from n.content);
  if jsonb_array_length(v_changes) = 0 then
    return jsonb_build_object('changed', false, 'note', '바뀌는 것이 없습니다.');
  end if;
  if coalesce(p_check_only, true) then
    return jsonb_build_object('check_only', true, 'id', o.id, 'source', mcp_private.ipsi_source_label(o.source), 'changes', v_changes,
      'note', '아직 바꾸지 않았다 — 사용자에게 보여 확인받은 뒤 check_only:false. 수집기가 같은 기사를 다시 모으면 수집기 값으로 덮일 수 있다.');
  end if;
  update educational_news set title = n.title, category = n.category, article_date = n.article_date, content = n.content,
    headline_summary = n.headline_summary, core_points = n.core_points, strategy_implications = n.strategy_implications,
    data_points = n.data_points, cautions = n.cautions
  where id = o.id;
  perform mcp_private.log_call(v_me, 'update_ipsi_news', jsonb_build_object('news_id', o.id, 'fields', (select jsonb_agg(c->>'field') from jsonb_array_elements(v_changes) c)));
  return jsonb_build_object('saved', true, 'id', o.id, 'changed', jsonb_array_length(v_changes));
end;
$$;


ALTER FUNCTION "public"."mcp_update_ipsi_news"("p_id" "uuid", "p_title" "text", "p_category" "text", "p_article_date" "date", "p_content" "text", "p_headline_summary" "text", "p_core_points" "text"[], "p_strategy_implications" "text"[], "p_data_points" "text"[], "p_cautions" "text"[], "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_ipsi_video"("p_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_url" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_headline_summary" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_core_points" "text"[] DEFAULT NULL::"text"[], "p_strategy_implications" "text"[] DEFAULT NULL::"text"[], "p_cautions" "text"[] DEFAULT NULL::"text"[], "p_key_concepts" "text"[] DEFAULT NULL::"text"[], "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('ipsi.hub');
  o public.educational_videos;
  v_vid text;
  v_url text;
  v_title text;
  v_category text;
  v_summary text;
  v_meta jsonb;
  v_moved boolean := false;
  v_changes jsonb := '[]'::jsonb;
begin
  perform mcp_private.ipsi_teacher();
  -- 잠그기 전에 읽는다 — FOR UPDATE 는 UPDATE 정책(올린 사람·관리자)을 통과한 행만 보여 «남의 영상»이 «없는 영상»으로 보인다
  select * into o from educational_videos where id = p_id;
  if not found then
    raise exception using errcode = 'P0002', message = '그 영상이 없습니다 — search_ipsi 로 id 를 확인하세요.';
  end if;
  if not (o.created_by = auth.uid() or public.is_admin()) then
    raise exception using errcode = '42501', message = '고칠 수 있는 영상은 내가 올린 것뿐입니다(관리자는 모두).';
  end if;
  select * into o from educational_videos where id = p_id for update;
  v_title := coalesce(nullif(btrim(coalesce(p_title, '')), ''), o.title);
  if length(v_title) > 300 then
    raise exception using errcode = '22023', message = 'title 은 300자까지입니다.';
  end if;
  v_category := coalesce(p_category, o.category);
  if v_category not in ('입시', '진학') then
    raise exception using errcode = '22023', message = 'category 는 입시 · 진학 중 하나입니다.';
  end if;
  v_url := o.url;
  v_vid := coalesce(o.video_id, mcp_private.ipsi_youtube_id(o.url));
  if p_url is not null then
    v_vid := mcp_private.ipsi_youtube_id(p_url);
    if v_vid is null then
      raise exception using errcode = '22023', message = 'YouTube 영상 주소가 아닙니다.';
    end if;
    v_url := 'https://www.youtube.com/watch?v=' || v_vid;
    v_moved := v_vid is distinct from coalesce(o.video_id, mcp_private.ipsi_youtube_id(o.url));
    if v_moved and exists (select 1 from educational_videos v where v.id <> o.id and (v.video_id = v_vid or strpos(v.url, v_vid) > 0)) then
      raise exception using errcode = '23505', message = '그 주소의 영상은 이미 피드에 있습니다.';
    end if;
  end if;
  -- "" = 지우기, null = 그대로
  v_summary := case when p_headline_summary is null then o.headline_summary else nullif(btrim(p_headline_summary), '') end;
  if length(coalesce(v_summary, '')) > 500 or length(coalesce(p_description, '')) > 5000 then
    raise exception using errcode = '22023', message = 'headline_summary 는 500자, description 은 5000자까지입니다.';
  end if;
  v_meta := coalesce(o.meta, '{}'::jsonb);
  if p_description is not null then
    v_meta := case when btrim(p_description) = '' then v_meta - 'description' else v_meta || jsonb_build_object('description', btrim(p_description)) end;
  end if;
  if p_core_points is not null then
    v_meta := v_meta - 'core_points' || jsonb_strip_nulls(jsonb_build_object('core_points', to_jsonb(nullif(mcp_private.ipsi_lines(p_core_points, 'core_points'), '{}'))));
  end if;
  if p_strategy_implications is not null then
    v_meta := v_meta - 'strategy_implications' || jsonb_strip_nulls(jsonb_build_object('strategy_implications',
      to_jsonb(nullif(mcp_private.ipsi_lines(p_strategy_implications, 'strategy_implications'), '{}'))));
  end if;
  if p_cautions is not null then
    v_meta := v_meta - 'cautions' || jsonb_strip_nulls(jsonb_build_object('cautions', to_jsonb(nullif(mcp_private.ipsi_lines(p_cautions, 'cautions'), '{}'))));
  end if;
  if p_key_concepts is not null then
    v_meta := v_meta - 'key_concepts' || jsonb_strip_nulls(jsonb_build_object('key_concepts', to_jsonb(nullif(mcp_private.ipsi_lines(p_key_concepts, 'key_concepts', 30), '{}'))));
  end if;
  select coalesce(jsonb_agg(c), '[]'::jsonb) into v_changes from (
    select jsonb_build_object('field', 'title', 'before', o.title, 'after', v_title) c where v_title is distinct from o.title
    union all select jsonb_build_object('field', 'url', 'before', o.url, 'after', v_url) where v_url is distinct from o.url
    union all select jsonb_build_object('field', 'category', 'before', o.category, 'after', v_category) where v_category is distinct from o.category
    union all select jsonb_build_object('field', 'summary', 'before', o.headline_summary, 'after', v_summary) where v_summary is distinct from o.headline_summary
    union all select jsonb_build_object('field', 'meta.' || k, 'before', coalesce(o.meta, '{}'::jsonb) -> k, 'after', v_meta -> k)
      from (select jsonb_object_keys(coalesce(o.meta, '{}'::jsonb) || v_meta) k) ks
      where (coalesce(o.meta, '{}'::jsonb) -> k) is distinct from (v_meta -> k)
  ) x;
  if jsonb_array_length(v_changes) = 0 then
    return jsonb_build_object('changed', false, 'note', '바뀌는 것이 없습니다.');
  end if;
  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true, 'id', o.id, 'changes', v_changes,
      'warning', case when v_moved then '다른 영상으로 바뀐다 — 옛 영상의 자막·채널·길이는 지운다(요약·포인트는 보낸 것만 바뀐다).' end,
      'note', '아직 바꾸지 않았다 — 사용자에게 보여 확인받은 뒤 check_only:false.'));
  end if;
  update educational_videos set
    title = v_title, url = v_url, category = v_category, headline_summary = v_summary, meta = v_meta,
    thumbnail = case when v_moved then 'https://img.youtube.com/vi/' || v_vid || '/maxresdefault.jpg' else thumbnail end,
    video_id = case when v_moved then v_vid else video_id end,
    transcript = case when v_moved then null else transcript end,
    caption_lang = case when v_moved then null else caption_lang end,
    caption_type = case when v_moved then null else caption_type end,
    channel_id = case when v_moved then null else channel_id end,
    channel_label = case when v_moved then null else channel_label end,
    duration_seconds = case when v_moved then null else duration_seconds end
  where id = o.id;
  perform mcp_private.log_call(v_me, 'update_ipsi_video', jsonb_build_object('video_id', o.id, 'fields', (select jsonb_agg(c->>'field') from jsonb_array_elements(v_changes) c)));
  return jsonb_build_object('saved', true, 'id', o.id, 'changed', jsonb_array_length(v_changes));
end;
$$;


ALTER FUNCTION "public"."mcp_update_ipsi_video"("p_id" "uuid", "p_title" "text", "p_url" "text", "p_category" "text", "p_headline_summary" "text", "p_description" "text", "p_core_points" "text"[], "p_strategy_implications" "text"[], "p_cautions" "text"[], "p_key_concepts" "text"[], "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_my_purchase_item"("p_request_id" "uuid", "p_row_id" "text", "p_cells" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('purchase.request');
  v_lock  record;
  v_cells jsonb;
begin
  select * into v_lock from mcp_private.pr_lock_my_row(v_me, p_request_id, p_row_id, '고칠');
  v_cells := mcp_private.pr_build_cells(p_cells, (v_lock.page).columns, v_lock.row_cells, '품목');

  update purchase_requests
     set items = (select jsonb_agg(case when e->>'id' = p_row_id then jsonb_build_object('id', e->'id', 'cells', v_cells) else e end
                                   order by o)
                  from jsonb_array_elements(mcp_private.arr(items)) with ordinality t(e, o))
   where id = p_request_id;

  perform mcp_private.log_call(v_me, 'update_my_purchase_item', jsonb_build_object('request_id', p_request_id, 'row_id', p_row_id));

  return jsonb_strip_nulls(jsonb_build_object(
    'request_id', p_request_id, 'row_id', p_row_id,
    'item', v_cells ->> mcp_private.pr_name_col((v_lock.page).columns),
    'fields', mcp_private.pr_fields(v_cells, (v_lock.page).columns),
    'amount', mcp_private.pr_amount(v_cells, (v_lock.page).columns),
    'note', '고쳤다. 수정은 새 신청이 아니라 담당자에게 알림이 가지 않는다.'
  ));
end;
$$;


ALTER FUNCTION "public"."mcp_update_my_purchase_item"("p_request_id" "uuid", "p_row_id" "text", "p_cells" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_notice"("p_notice_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_content" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text", "p_start_date" "date" DEFAULT NULL::"date", "p_end_date" "date" DEFAULT NULL::"date", "p_targets" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('notice.board');
  v_n  public.department_notice;
  v_changed text[] := '{}';
begin
  select * into v_n from department_notice where id = p_notice_id;
  if not found then raise exception using errcode = 'P0002', message = '공지를 찾을 수 없습니다.'; end if;
  if not coalesce(v_n.created_by = auth.uid(), false) and not public.is_admin() then
    raise exception using errcode = '42501', message = '내가 쓴 공지만 고칠 수 있습니다.';
  end if;

  if p_title is not null then
    v_n.title := mcp_private.opt_text(p_title, 'title', 200);
    if v_n.title is null then raise exception using errcode = '22023', message = '제목은 비울 수 없습니다.'; end if;
    v_changed := v_changed || 'title'::text;
  end if;
  if p_content is not null then
    v_n.content := mcp_private.opt_text(p_content, 'content', 20000);
    if v_n.content is null then raise exception using errcode = '22023', message = '내용은 비울 수 없습니다.'; end if;
    v_changed := v_changed || 'content'::text;
  end if;
  if p_department is not null then v_n.department := mcp_private.notice_department(p_department); v_changed := v_changed || 'department'::text; end if;
  if p_start_date is not null then v_n.start_date := p_start_date; v_changed := v_changed || 'start_date'::text; end if;
  if p_end_date is not null then v_n.end_date := p_end_date; v_changed := v_changed || 'end_date'::text; end if;
  if p_targets is not null then v_n.target_resource_ids := mcp_private.notice_targets(p_targets); v_changed := v_changed || 'targets'::text; end if;
  if cardinality(v_changed) = 0 then raise exception using errcode = '22023', message = '바꿀 칸이 없습니다.'; end if;
  if v_n.end_date < v_n.start_date then raise exception using errcode = '22023', message = '게시 끝 날짜가 시작 날짜보다 앞입니다.'; end if;

  update department_notice
     set title = v_n.title, content = v_n.content, department = v_n.department, start_date = v_n.start_date,
         end_date = v_n.end_date, target_resource_ids = v_n.target_resource_ids, updated_at = now()
   where id = p_notice_id;
  if not found then raise exception using errcode = '42501', message = '이 공지를 고칠 권한이 없습니다.'; end if;
  select * into v_n from department_notice where id = p_notice_id;
  return jsonb_build_object('changed', v_changed, 'notice', mcp_private.notice_out(v_n, true));
end;
$$;


ALTER FUNCTION "public"."mcp_update_notice"("p_notice_id" "uuid", "p_title" "text", "p_content" "text", "p_department" "text", "p_start_date" "date", "p_end_date" "date", "p_targets" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_purchase_item_cells"("p_request_id" "uuid", "p_edits" "jsonb", "p_check_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me      uuid := mcp_private.require_tool('purchase.request');
  v_req     public.purchase_requests%rowtype;
  v_page    public.purchase_request_pages%rowtype;
  v_edit    jsonb;
  v_rid     text;
  v_seen    text[] := '{}';
  v_old     jsonb;
  v_new     jsonb;
  v_changes jsonb;
  v_map     jsonb := '{}'::jsonb;      -- row_id → 새 cells (바뀐 품목만)
  v_out     jsonb := '[]'::jsonb;
  v_in_ord  text;
  v_linked  integer := 0;
begin
  if p_request_id is null then
    raise exception using errcode = '22023', message = 'request_id 가 필요합니다 (list_managed_purchase_requests 의 request_id).';
  end if;
  if p_edits is null or jsonb_typeof(p_edits) <> 'array' or jsonb_array_length(p_edits) = 0 then
    raise exception using errcode = '22023', message = 'edits 는 [{row_id, cells}] 배열이어야 합니다.';
  end if;
  if jsonb_array_length(p_edits) > 50 then
    raise exception using errcode = '22023', message = 'edits 는 50개까지입니다.';
  end if;

  select * into v_req from purchase_requests where id = p_request_id for update;
  if v_req.id is null then
    raise exception using errcode = 'P0002', message = '구매 신청을 찾을 수 없습니다.';
  end if;
  perform mcp_private.pr_require_manager(v_req.page_id);
  select * into v_page from purchase_request_pages where id = v_req.page_id;

  for v_edit in select * from jsonb_array_elements(p_edits) loop
    if jsonb_typeof(v_edit) <> 'object' then
      raise exception using errcode = '22023', message = 'edits 의 각 항목은 {row_id, cells} 객체여야 합니다.';
    end if;
    v_rid := btrim(coalesce(v_edit->>'row_id', ''));
    if v_rid = '' then
      raise exception using errcode = '22023', message = 'edits 의 각 항목에 row_id 가 필요합니다 (list_managed_purchase_requests 의 row_id).';
    end if;
    if v_rid = any(v_seen) then
      raise exception using errcode = '22023', message = format('edits 에 같은 row_id 가 두 번 있습니다: %s', v_rid);
    end if;
    v_seen := v_seen || v_rid;

    select e->'cells' into v_old from jsonb_array_elements(mcp_private.arr(v_req.items)) e where e->>'id' = v_rid limit 1;
    if v_old is null then
      raise exception using errcode = 'P0002',
        message = format('이 신청에 없는 row_id 입니다: %s — 신청자가 지웠을 수 있습니다 (list_managed_purchase_requests 로 다시 확인).', v_rid);
    end if;

    v_new := mcp_private.pr_build_cells(v_edit->'cells', v_page.columns, v_old,
               format('품목 «%s»', coalesce(nullif(v_old ->> mcp_private.pr_name_col(v_page.columns), ''), v_rid)));

    select coalesce(jsonb_agg(jsonb_build_object(
             'column', c->>'name',
             'before', coalesce(v_old->>(c->>'id'), ''),
             'after',  coalesce(v_new->>(c->>'id'), '')) order by t.pos), '[]'::jsonb)
      into v_changes
    from jsonb_array_elements(mcp_private.arr(v_page.columns)) with ordinality t(c, pos)
    where coalesce(v_old->>(c->>'id'), '') is distinct from coalesce(v_new->>(c->>'id'), '');

    if jsonb_array_length(v_changes) = 0 then
      continue;                          -- 이미 그 값 — 바꿀 것이 없는 품목
    end if;

    select b.title || ' (' || mcp_private.pr_batch_label(b.status) || ')' into v_in_ord
      from purchase_order_line_items li
      join purchase_order_lines l on l.id = li.line_id
      join purchase_order_batches b on b.id = l.batch_id
     where li.request_id = v_req.id and li.row_id = v_rid limit 1;
    if v_in_ord is not null then v_linked := v_linked + 1; end if;

    v_map := v_map || jsonb_build_object(v_rid, v_new);
    v_out := v_out || jsonb_strip_nulls(jsonb_build_object(
      'row_id', v_rid,
      'item', v_new ->> mcp_private.pr_name_col(v_page.columns),
      'changes', v_changes,
      'amount', mcp_private.pr_amount(v_new, v_page.columns),
      'status', mcp_private.pr_item_status(v_req.meta, v_req.status, v_rid),
      'status_label', mcp_private.pr_status_label(mcp_private.pr_item_status(v_req.meta, v_req.status, v_rid)),
      'in_order', v_in_ord
    ));
    v_in_ord := null;
  end loop;

  if jsonb_array_length(v_out) = 0 then
    raise exception using errcode = '22023', message = '바꿀 것이 없습니다 — 보낸 칸이 모두 이미 그 값입니다.';
  end if;

  if coalesce(p_check_only, false) then
    return jsonb_build_object('check_only', true, 'request_id', v_req.id,
      'requester', (select mcp_private.pr_requester_label(res.type, res.name, res.meta) from resource res where res.id = v_req.requester_id),
      'items', v_out,
      'note', '아직 바꾸지 않았다 — 어느 칸이 어떻게 바뀌는지를 사용자에게 보여 확인받은 뒤 check_only:false 로 다시 부른다.'
              || case when v_linked > 0 then ' in_order 가 있는 품목은 이미 품의 품목에 묶여 있다 — 품의 품목의 이름·단가·수량은 자동으로 바뀌지 않으니 필요하면 save_purchase_order_line 으로 따로 고친다.' else '' end);
  end if;

  update purchase_requests
     set items = (select jsonb_agg(case when v_map ? (e->>'id')
                                        then jsonb_build_object('id', e->'id', 'cells', v_map -> (e->>'id'))
                                        else e end order by o)
                    from jsonb_array_elements(mcp_private.arr(items)) with ordinality t(e, o))
   where id = v_req.id;
  if not found then
    raise exception using errcode = '42501', message = '수정 권한이 없습니다. 페이지 작성자·공동 작업자만 품목을 고칠 수 있습니다.';
  end if;

  perform mcp_private.log_call(v_me, 'update_purchase_item_cells',
    jsonb_build_object('request_id', v_req.id, 'rows', jsonb_array_length(v_out)));

  return jsonb_build_object('updated', true, 'request_id', v_req.id, 'items', v_out,
    'note', '고쳤다(신청자에게 알림은 가지 않는다). 수정 전 모양은 list_purchase_request_history 로 볼 수 있다.'
            || case when v_linked > 0 then ' in_order 가 있는 품목은 품의 품목의 값이 자동으로 바뀌지 않았다.' else '' end);
end;
$$;


ALTER FUNCTION "public"."mcp_update_purchase_item_cells"("p_request_id" "uuid", "p_edits" "jsonb", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_purchase_order_batch"("p_batch_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_edufine_title" "text" DEFAULT NULL::"text", "p_edufine_no" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me    uuid := mcp_private.require_tool('purchase.request');
  v_batch public.purchase_order_batches%rowtype;
  v_title text := mcp_private.pr_short_text(p_title, 'title', 200);
  v_note  text := mcp_private.pr_short_text(p_note, 'note', 2000);
  v_etitle text := mcp_private.pr_short_text(p_edufine_title, 'edufine_title', 300);
  v_eno   text := mcp_private.pr_short_text(p_edufine_no, 'edufine_no', 40);
  v_rows  integer;
  v_after public.purchase_order_batches%rowtype;
begin
  if p_batch_id is null then
    raise exception using errcode = '22023', message = 'batch_id 가 필요합니다 (list_purchase_orders 의 batch_id).';
  end if;
  if v_title is null and v_note is null and v_etitle is null and v_eno is null then
    raise exception using errcode = '22023', message = '바꿀 것이 없습니다 — title·note·edufine_title·edufine_no 중 하나를 보내세요.';
  end if;
  if v_title is not null and v_title = '' then
    raise exception using errcode = '22023', message = 'title 은 비울 수 없습니다.';
  end if;
  select * into v_batch from purchase_order_batches where id = p_batch_id;
  if v_batch.id is null then
    raise exception using errcode = 'P0002', message = '품의 차수를 찾을 수 없습니다.';
  end if;
  perform mcp_private.pr_require_manager(v_batch.page_id);

  update purchase_order_batches
     set title = coalesce(v_title, title),
         note = case when v_note is null then note else nullif(v_note, '') end,
         edufine_title = case when v_etitle is null then edufine_title else nullif(btrim(v_etitle), '') end,
         edufine_no = case when v_eno is null then edufine_no else nullif(btrim(v_eno), '') end,
         edufine_linked_at = case when v_etitle is null and v_eno is null then edufine_linked_at else now() end
   where id = v_batch.id
  returning * into v_after;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    raise exception using errcode = '42501', message = '수정 권한이 없습니다.';
  end if;

  perform mcp_private.log_call(v_me, 'update_purchase_order_batch', jsonb_build_object('batch_id', v_batch.id));
  return jsonb_build_object('updated', true, 'batch_id', v_after.id, 'title', v_after.title, 'note', v_after.note,
    'edufine_title', v_after.edufine_title, 'edufine_no', v_after.edufine_no);
end;
$$;


ALTER FUNCTION "public"."mcp_update_purchase_order_batch"("p_batch_id" "uuid", "p_title" "text", "p_note" "text", "p_edufine_title" "text", "p_edufine_no" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_purchase_page"("p_page_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_period_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_period_end" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_archived" boolean DEFAULT NULL::boolean, "p_check_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_tool('purchase.page');
  v_page   public.purchase_request_pages%rowtype;
  v_title  text;
  v_desc   text;
  v_start  timestamptz;
  v_end    timestamptz;
  v_arch   boolean;
  v_changed text[] := '{}';
  v_before jsonb;
  v_after  jsonb;
begin
  if p_page_id is null then
    raise exception using errcode = '22023', message = 'page_id 가 필요합니다 (list_purchase_pages 의 page_id).';
  end if;
  select * into v_page from purchase_request_pages where id = p_page_id;
  if v_page.id is null then
    raise exception using errcode = 'P0002', message = '구매 신청 페이지를 찾을 수 없습니다.';
  end if;
  if not public.is_purchase_page_manager(v_page.id) then
    raise exception using errcode = '42501', message = '이 페이지의 담당자(만든 사람·공동 작업자)만 고칠 수 있습니다.';
  end if;

  v_title := coalesce(btrim(p_title), v_page.title);
  v_desc  := case when p_description is null then v_page.description else nullif(btrim(p_description), '') end;
  v_start := coalesce(p_period_start, v_page.period_start);
  v_end   := coalesce(p_period_end, v_page.period_end);
  v_arch  := coalesce(p_archived, v_page.is_archived);

  if v_title = '' or length(v_title) > 200 then
    raise exception using errcode = '22023', message = 'title 은 1~200자입니다.';
  end if;
  if v_desc is not null and length(v_desc) > 4000 then
    raise exception using errcode = '22023', message = 'description 은 4000자까지입니다.';
  end if;
  if v_end <= v_start then
    raise exception using errcode = '22023', message = '신청 마감이 시작보다 뒤여야 합니다.';
  end if;
  if v_end - v_start > interval '366 days' then
    raise exception using errcode = '22023', message = '신청 기간은 1년까지입니다.';
  end if;

  if v_title is distinct from v_page.title then v_changed := v_changed || 'title'::text; end if;
  if v_desc is distinct from v_page.description then v_changed := v_changed || 'description'::text; end if;
  if v_start is distinct from v_page.period_start then v_changed := v_changed || 'period_start'::text; end if;
  if v_end is distinct from v_page.period_end then v_changed := v_changed || 'period_end'::text; end if;
  if v_arch is distinct from v_page.is_archived then v_changed := v_changed || 'archived'::text; end if;
  if cardinality(v_changed) = 0 then
    raise exception using errcode = '22023', message = '바꿀 것이 없습니다 — 지금 값과 같습니다.';
  end if;

  v_before := jsonb_build_object('title', v_page.title, 'period_start', mcp_private.pr_kst(v_page.period_start),
    'period_end', mcp_private.pr_kst(v_page.period_end), 'period_status', mcp_private.pr_period(v_page.period_start, v_page.period_end),
    'archived', v_page.is_archived);
  v_after := jsonb_build_object('title', v_title, 'period_start', mcp_private.pr_kst(v_start),
    'period_end', mcp_private.pr_kst(v_end), 'period_status', mcp_private.pr_period(v_start, v_end), 'archived', v_arch);

  if coalesce(p_check_only, false) then
    return jsonb_build_object('check_only', true, 'page_id', v_page.id, 'changed', to_jsonb(v_changed),
      'before', v_before, 'after', v_after,
      'note', '아직 바꾸지 않았다 — 바뀌는 것(특히 period_status: upcoming·open·closed)을 사용자에게 보여 확인받은 뒤 check_only:false 로 다시 부른다.');
  end if;

  update purchase_request_pages
     set title = v_title,
         description = v_desc,
         period_start = v_start,
         period_end = v_end,
         is_archived = v_arch,
         archived_at = case when v_arch = v_page.is_archived then archived_at when v_arch then now() else null end
   where id = v_page.id;

  perform mcp_private.log_call(v_me, 'update_purchase_page', jsonb_build_object('page_id', v_page.id, 'changed', to_jsonb(v_changed)));

  return jsonb_build_object('updated', true, 'page_id', v_page.id, 'changed', to_jsonb(v_changed),
    'before', v_before, 'after', v_after,
    'note', '고쳤다(알림은 가지 않는다). 대상·칸 구성·공동 작업자는 웹 구매 신청에서.');
end;
$$;


ALTER FUNCTION "public"."mcp_update_purchase_page"("p_page_id" "uuid", "p_title" "text", "p_description" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_archived" boolean, "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_schedule"("p_schedule_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_date" "date" DEFAULT NULL::"date", "p_start_time" time without time zone DEFAULT NULL::time without time zone, "p_end_time" time without time zone DEFAULT NULL::time without time zone, "p_end_date" "date" DEFAULT NULL::"date", "p_description" "text" DEFAULT NULL::"text", "p_attendees" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me     uuid := mcp_private.require_any_tool(array['schedule.manage', 'schedule.mine', 'mealduty.plan', 'supervision.plan']);
  v_row    public.meeting := mcp_private.sch_lock_mine(p_schedule_id, v_me, '고칠');
  v_meta   jsonb := coalesce(v_row.meta, '{}'::jsonb);
  v_title  text := nullif(btrim(coalesce(p_title, '')), '');
  v_win    record;
  v_people jsonb;
  v_assign jsonb;
  v_signed text;
  v_added  integer := 0;
  v_changed text[] := '{}';
begin
  -- 2026-11-04 — 일정 관리 허용이 없어도 개인일정(schedule.mine)·급식지도(mealduty.plan)·자습 감독(supervision.plan)은 그 허용으로
  perform mcp_private.sch_require_kind_grant(v_row);
  if v_title is not null then
    if char_length(v_title) > 200 then
      raise exception using errcode = '22023', message = '제목은 200자까지입니다.';
    end if;
    v_meta := v_meta || jsonb_build_object('title', v_title);
    v_changed := v_changed || '제목'::text;
  end if;

  if p_description is not null then
    if char_length(btrim(p_description)) > 4000 then
      raise exception using errcode = '22023', message = '설명은 4000자까지입니다.';
    end if;
    v_meta := case when btrim(p_description) = '' then v_meta - 'description'
                   else v_meta || jsonb_build_object('description', btrim(p_description)) end;
    v_changed := v_changed || '설명'::text;
  end if;

  if p_date is not null then
    select * into v_win from mcp_private.sch_window(p_date, p_end_date, p_start_time, p_end_time);
    v_row.starts_at := v_win.starts_at;
    v_row.ends_at := v_win.ends_at;
    v_meta := v_meta || jsonb_build_object('date_only', v_win.all_day);
    v_changed := v_changed || '날짜·시각'::text;
  elsif p_start_time is not null or p_end_time is not null or p_end_date is not null then
    raise exception using errcode = '22023', message = '시각·끝 날짜를 바꿀 때는 date 도 함께 주세요(그날의 시각을 다시 정한다).';
  end if;

  if p_attendees is not null then
    if v_row.kind = 'personal' then
      raise exception using errcode = '22023', message = '개인일정에는 참석자를 넣을 수 없습니다.';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('name', p.name, 'type', p.type)), '[]'::jsonb) into v_people
    from mcp_private.sch_people(p_attendees) p;
    if v_row.kind in ('duty', 'training') and jsonb_array_length(v_people) = 0 then
      raise exception using errcode = '22023', message = '업무·연수 일정은 참석자가 1명 이상이어야 합니다.';
    end if;
    if v_row.kind = 'training' then
      select string_agg(s.signer_name, ', ' order by s.signer_name) into v_signed
      from training_signature s
      where s.meeting_id = v_row.id
        and not exists (select 1 from jsonb_array_elements(v_people) e where e->>'name' = s.signer_name);
      if v_signed is not null then
        raise exception using errcode = '42501', message = format('이미 서명한 사람은 참석자에서 뺄 수 없습니다 — %s', v_signed);
      end if;
    end if;
    -- 남는 사람은 기존 칸(서명 표시 등)을 그대로, 새 사람은 새 칸
    select coalesce(jsonb_object_agg(e->>'name',
             coalesce(case when jsonb_typeof(v_meta->'assignee') = 'object' then v_meta->'assignee'->(e->>'name') end,
                      case when v_row.kind = 'training' then jsonb_build_object('name', e->>'name', 'signature', 0)
                           else jsonb_build_object('name', e->>'name') end)), '{}'::jsonb),
           count(*) filter (where not (case when jsonb_typeof(v_meta->'assignee') = 'object' then v_meta->'assignee' else '{}'::jsonb end ? (e->>'name')))
      into v_assign, v_added
    from jsonb_array_elements(v_people) e;
    v_meta := case when jsonb_array_length(v_people) = 0 then v_meta - 'assignee' else v_meta || jsonb_build_object('assignee', v_assign) end;
    v_changed := v_changed || '참석자'::text;
  end if;

  if cardinality(v_changed) = 0 then
    raise exception using errcode = '22023', message = '바꿀 것이 없습니다 — title · date(+시각) · description · attendees 중 하나 이상을 주세요.';
  end if;

  v_meta := v_meta || jsonb_build_object('via_updated', jsonb_build_object(
    'channel', 'mcp', 'client_id', nullif(auth.jwt()->>'client_id', ''), 'at', now()));

  update meeting set meta = v_meta, starts_at = v_row.starts_at, ends_at = v_row.ends_at
   where id = v_row.id
  returning * into v_row;

  perform mcp_private.log_call(v_me, 'update_schedule',
    jsonb_build_object('id', v_row.id, 'kind', v_row.kind, 'changed', to_jsonb(v_changed)));

  return mcp_private.sch_out(v_row, v_me) || jsonb_strip_nulls(jsonb_build_object(
    'changed', to_jsonb(v_changed),
    'note', '고쳤다. 고치기는 알림을 보내지 않는다(웹과 같다)' ||
            case when v_added > 0 then format(' — 새로 넣은 참석자 %s명에게도 알림이 가지 않았으니 따로 알려야 한다.', v_added) else '.' end
  ));
end;
$$;


ALTER FUNCTION "public"."mcp_update_schedule"("p_schedule_id" "uuid", "p_title" "text", "p_date" "date", "p_start_time" time without time zone, "p_end_time" time without time zone, "p_end_date" "date", "p_description" "text", "p_attendees" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_schedule_survey"("p_survey_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_staff" "text"[] DEFAULT NULL::"text"[], "p_students" "text"[] DEFAULT NULL::"text"[], "p_candidate_dates" "date"[] DEFAULT NULL::"date"[], "p_allow_custom_dates" boolean DEFAULT NULL::boolean, "p_due_date" "date" DEFAULT NULL::"date", "p_check_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me      uuid := mcp_private.require_tool('schedule.survey');
  v_today   date := (now() at time zone 'Asia/Seoul')::date;
  v_row     public.schedule_survey;
  v_title   text;
  v_desc    text;
  v_dates   date[];
  v_allow   boolean;
  v_due     date;
  v_targets uuid[];
  v_staff   uuid[];
  v_stu     uuid[] := '{}';
  v_x       text;
  v_who     record;
  v_id      uuid;
  v_changed text[] := '{}';
  v_added   int := 0;
  v_removed int := 0;
  v_resp    int;
  v_resp_gone int := 0;
begin
  if not coalesce(public.can_manage_schedule_survey(p_survey_id), false) then
    raise exception using errcode = 'P0002', message = '내가 만든 설문을 찾을 수 없습니다 (list_schedule_surveys 의 survey_id).';
  end if;
  select * into v_row from schedule_survey where id = p_survey_id;

  v_title := coalesce(btrim(p_title), v_row.title);
  v_desc  := case when p_description is null then v_row.description else nullif(btrim(p_description), '') end;
  v_allow := coalesce(p_allow_custom_dates, v_row.allow_custom_dates);
  v_due   := coalesce(p_due_date, v_row.due_date);
  if v_title = '' or char_length(v_title) > 200 then raise exception using errcode = '22023', message = '제목은 1~200자입니다.'; end if;
  if char_length(coalesce(v_desc, '')) > 4000 then raise exception using errcode = '22023', message = '설명은 4000자까지입니다.'; end if;

  if p_candidate_dates is not null then
    select coalesce(array_agg(distinct d order by d), '{}') into v_dates from unnest(p_candidate_dates) d;
    if cardinality(v_dates) > 40 then raise exception using errcode = '22023', message = '후보 날짜는 40개까지입니다.'; end if;
    -- 이미 있던 날짜는 지났어도 남겨 둘 수 있다. 새로 넣는 날짜만 오늘부터 1년 안
    if exists (select 1 from unnest(v_dates) d
               where not d = any(coalesce(v_row.candidate_dates, '{}'::date[])) and (d < v_today or d > v_today + 366)) then
      raise exception using errcode = '22023', message = '새로 넣는 후보 날짜는 오늘부터 1년 안이어야 합니다.';
    end if;
  else
    v_dates := v_row.candidate_dates;
  end if;
  if not v_allow and cardinality(coalesce(v_dates, '{}'::date[])) = 0 then
    raise exception using errcode = '22023', message = '후보 날짜가 없으면 날짜 제안(allow_custom_dates)을 열어 두어야 응답할 수 있습니다.';
  end if;
  if p_due_date is not null and p_due_date < v_today then raise exception using errcode = '22023', message = '마감일이 지났습니다.'; end if;

  -- 대상자: staff·students 중 하나라도 주면 «두 목록을 합친 것»으로 통째로 바뀐다
  if p_staff is not null or p_students is not null then
    select coalesce(array_agg(p.id), '{}') into v_staff from mcp_private.sch_people(coalesce(p_staff, '{}')) p;
    foreach v_x in array coalesce(p_students, '{}') loop
      select * into v_who from mcp_private.parse_student(v_x);
      v_id := null;
      select r.id into v_id from resource r
      where r.type = 'student' and coalesce(r.status, 'active') = 'active'
        and r.meta->>'grade' = v_who.grade::text and r.meta->>'class' = v_who.class_num::text and r.meta->>'number' = v_who.num::text
      limit 1;
      if v_id is null then raise exception using errcode = '22023', message = format('재학생을 찾지 못했습니다: %s', v_x); end if;
      v_stu := v_stu || v_id;
    end loop;
    select coalesce(array_agg(distinct x), '{}') into v_targets from unnest(v_staff || v_stu) x;
    if cardinality(v_targets) = 0 then raise exception using errcode = '22023', message = '대상자가 1명 이상이어야 합니다(staff · students).'; end if;
    if cardinality(v_targets) > 700 then raise exception using errcode = '22023', message = '대상자는 700명까지입니다.'; end if;
    select count(*) into v_added from unnest(v_targets) x where not x = any(v_row.target_resource_ids);
    select count(*) into v_removed from unnest(v_row.target_resource_ids) x where not x = any(v_targets);
    select count(*) into v_resp_gone from schedule_survey_response r
     where r.survey_id = v_row.id and not r.respondent_resource_id = any(v_targets);
  else
    v_targets := v_row.target_resource_ids;
  end if;

  if v_title is distinct from v_row.title then v_changed := v_changed || '제목'::text; end if;
  if v_desc is distinct from v_row.description then v_changed := v_changed || '설명'::text; end if;
  if v_dates is distinct from v_row.candidate_dates then v_changed := v_changed || '후보 날짜'::text; end if;
  if v_allow is distinct from v_row.allow_custom_dates then v_changed := v_changed || '날짜 제안'::text; end if;
  if v_due is distinct from v_row.due_date then v_changed := v_changed || '마감일'::text; end if;
  if v_added + v_removed > 0 then v_changed := v_changed || '대상자'::text; end if;
  if cardinality(v_changed) = 0 then
    raise exception using errcode = '22023', message = '바꿀 것이 없습니다 — 지금 값과 같습니다.';
  end if;
  select count(*) into v_resp from schedule_survey_response r where r.survey_id = v_row.id;

  if coalesce(p_check_only, false) then
    return jsonb_build_object('check_only', true, 'survey_id', v_row.id, 'changed', to_jsonb(v_changed),
      'targets_added', v_added, 'targets_removed', v_removed, 'responses', v_resp, 'responses_from_removed', v_resp_gone,
      'note', '아직 바꾸지 않았다 — 바뀌는 것을 사용자에게 보여 확인받은 뒤 check_only:false. '
              || '새 대상자에게 알림은 가지 않는다(웹과 같다). 빠진 대상자의 응답은 남지만 결과에서 대상 밖이 된다.');
  end if;

  update schedule_survey
     set title = v_title, description = v_desc, target_resource_ids = v_targets, candidate_dates = v_dates,
         allow_custom_dates = v_allow, due_date = v_due
   where id = v_row.id
  returning * into v_row;
  if not found then raise exception using errcode = '42501', message = '설문을 고치지 못했습니다(작성자·관리자만).'; end if;

  perform mcp_private.log_call(v_me, 'update_schedule_survey',
    jsonb_build_object('survey_id', v_row.id, 'changed', to_jsonb(v_changed), 'added', v_added, 'removed', v_removed));
  return mcp_private.sv_survey_out(v_row, v_me) || jsonb_build_object('changed', to_jsonb(v_changed),
    'note', case when v_added > 0 then format('고쳤다 — 새 대상자 %s명에게는 알림이 가지 않았다(웹과 같다). 알리려면 따로.', v_added)
                 else '고쳤다(알림은 가지 않는다, 웹과 같다).' end);
end;
$$;


ALTER FUNCTION "public"."mcp_update_schedule_survey"("p_survey_id" "uuid", "p_title" "text", "p_description" "text", "p_staff" "text"[], "p_students" "text"[], "p_candidate_dates" "date"[], "p_allow_custom_dates" boolean, "p_due_date" "date", "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_study_room"("p_room_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_is_active" boolean DEFAULT NULL::boolean, "p_rules" "text" DEFAULT NULL::"text", "p_operating_start" "date" DEFAULT NULL::"date", "p_operating_end" "date" DEFAULT NULL::"date", "p_operating_days" integer[] DEFAULT NULL::integer[], "p_periods" "jsonb" DEFAULT NULL::"jsonb", "p_booking_windows" "jsonb" DEFAULT NULL::"jsonb", "p_allow_duplicate" boolean DEFAULT NULL::boolean, "p_grades" integer[] DEFAULT NULL::integer[], "p_check_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me      uuid := mcp_private.require_tool('studyroom.manage');
  v_old     public.study_rooms;
  v_new     public.study_rooms;
  v_changed text[] := '{}';
  v_win     jsonb;
  v_p       jsonb;
  v_cur     jsonb;
  v_periods jsonb;
  v_warn    text[] := '{}';
  v_n       integer;
  v_last    date;
begin
  perform mcp_private.sr_require_teacher();
  perform mcp_private.sr_require_head();   -- 2026-11-05: 열람실 설정은 학년 부장·관리자만
  select * into v_old from study_rooms where id = p_room_id;
  if not found then raise exception using errcode = 'P0002', message = '열람실을 찾을 수 없습니다(list_study_rooms 의 room_id).'; end if;
  v_new := v_old;

  if p_name is not null then
    v_new.name := mcp_private.opt_text(p_name, 'name', 100);
    if v_new.name is null then raise exception using errcode = '22023', message = '이름은 비울 수 없습니다.'; end if;
    v_changed := v_changed || 'name'::text;
    select count(*) into v_n from seat_reservations where room_id = p_room_id and reservation_date >= (now() at time zone 'Asia/Seoul')::date;
    if v_n > 0 then v_warn := v_warn || format('오늘 이후 신청 %s건의 학생 «내 예약»에도 새 이름이 바로 보인다.', v_n); end if;
  end if;
  if p_is_active is not null then v_new.is_active := p_is_active; v_changed := v_changed || 'active'::text; end if;
  if p_rules is not null then v_new.rules := coalesce(mcp_private.opt_text(p_rules, 'rules', 4000), ''); v_changed := v_changed || 'rules'::text; end if;

  if p_grades is not null then
    if cardinality(p_grades) = 0 or exists (select 1 from unnest(p_grades) g where g not between 1 and 3) then
      raise exception using errcode = '22023', message = 'grades 는 1~3 숫자 하나 이상입니다(예: [2]).';
    end if;
    v_new.grades := (select array_agg(distinct g order by g) from unnest(p_grades) g);
    v_new.grade := v_new.grades[1];   -- 웹 RoomEditor 의 레거시 칸
    v_changed := v_changed || 'grades'::text;
    -- 새 학년 밖 학생의 남은 신청(학생 학년 = resource.meta.grade) — 운영은 그대로, 신청 화면 목록만 바뀐다
    select count(*), max(s.reservation_date) into v_n, v_last
      from seat_reservations s join profiles p on p.id = s.student_id
      left join resource r on r.type = 'student' and r.meta->>'id' = split_part(p.email, '@', 1)
     where s.room_id = p_room_id and s.reservation_date >= (now() at time zone 'Asia/Seoul')::date
       and not coalesce((r.meta->>'grade')::int = any(v_new.grades), false);
    if v_n > 0 then
      v_warn := v_warn || format('새 학년 밖 학생의 오늘 이후 신청 %s건(마지막 %s)은 그대로 운영된다(출석·내 예약·취소·코인) — 그 학생들의 «자리 신청» 화면에서만 이 열람실이 빠진다.', v_n, v_last);
    end if;
  end if;

  if p_operating_start is not null or p_operating_end is not null then
    v_new.fixed_start_date := coalesce(p_operating_start, v_old.fixed_start_date);
    v_new.fixed_end_date := coalesce(p_operating_end, v_old.fixed_end_date);
    if v_new.fixed_start_date is null or v_new.fixed_end_date is null or v_new.fixed_start_date > v_new.fixed_end_date then
      raise exception using errcode = '22023', message = '운영 기간은 시작 ≤ 끝인 두 날짜입니다.';
    end if;
    v_changed := v_changed || 'operating_period'::text;
    select count(*) into v_n from seat_reservations
     where room_id = p_room_id and (reservation_date < v_new.fixed_start_date or reservation_date > v_new.fixed_end_date)
       and reservation_date >= (now() at time zone 'Asia/Seoul')::date;
    if v_n > 0 then v_warn := v_warn || format('새 운영 기간 밖에 남는 오늘 이후 신청 %s건 — 지워지지 않는다(필요하면 seaton 에서 정리). seaton «자리 변경·예약 추가» 창의 기본 날짜는 새 운영 기간을 따른다.', v_n); end if;
  end if;

  if p_operating_days is not null then
    if cardinality(p_operating_days) = 0 or exists (select 1 from unnest(p_operating_days) d where d not between 0 and 6) then
      raise exception using errcode = '22023', message = 'operating_days 는 0(일)~6(토) 숫자 하나 이상입니다(월~금 = [1,2,3,4,5]).';
    end if;
    v_new.operating_days := (select array_agg(distinct d order by d) from unnest(p_operating_days) d);
    v_new.is_saturday_open := 6 = any(v_new.operating_days);   -- 웹 RoomEditor 와 같이 함께 맞춘다
    v_new.is_sunday_open := 0 = any(v_new.operating_days);
    v_changed := v_changed || 'operating_days'::text;
    select count(*) into v_n from seat_reservations
     where room_id = p_room_id and reservation_date >= (now() at time zone 'Asia/Seoul')::date
       and not (extract(dow from reservation_date)::int = any(v_new.operating_days));
    if v_n > 0 then v_warn := v_warn || format('빠진 요일에 오늘 이후 신청 %s건 — 지워지지 않는다.', v_n); end if;
  end if;

  if p_periods is not null then
    if not v_old.use_periods or jsonb_array_length(coalesce(v_old.operating_periods, '[]'::jsonb)) = 0 then
      raise exception using errcode = '22023', message = '이 열람실은 교시를 쓰지 않는다(종일) — 교시 켜기는 seaton 에서.';
    end if;
    if jsonb_typeof(p_periods) <> 'array' then raise exception using errcode = '22023', message = 'periods 는 [{id, name?, start_time?, end_time?}] 배열입니다.'; end if;
    v_periods := v_old.operating_periods;
    for v_p in select * from jsonb_array_elements(p_periods) loop
      select e into v_cur from jsonb_array_elements(v_periods) e where (e->>'id')::int = (v_p->>'id')::int;
      if v_cur is null then
        raise exception using errcode = '22023', message = format('교시 id %s 가 없습니다 — 있는 교시의 이름·시각만 고친다(더하기·빼기는 seaton 에서).', coalesce(v_p->>'id', '(없음)'));
      end if;
      if (v_p ? 'start_time' and v_p->>'start_time' !~ '^([01]\d|2[0-3]):[0-5]\d$') or (v_p ? 'end_time' and v_p->>'end_time' !~ '^([01]\d|2[0-3]):[0-5]\d$') then
        raise exception using errcode = '22023', message = '교시 시각은 HH:MM(24시간)입니다.';
      end if;
      v_cur := v_cur || jsonb_strip_nulls(jsonb_build_object('name', nullif(btrim(coalesce(v_p->>'name', '')), ''),
                                                            'start_time', v_p->>'start_time', 'end_time', v_p->>'end_time'));
      if (v_cur->>'start_time') >= (v_cur->>'end_time') then
        raise exception using errcode = '22023', message = format('교시 %s 의 시작이 끝보다 늦습니다.', v_cur->>'name');
      end if;
      select jsonb_agg(case when (e->>'id')::int = (v_cur->>'id')::int then v_cur else e end order by ord) into v_periods
        from jsonb_array_elements(v_periods) with ordinality as x(e, ord);
      v_cur := null;
    end loop;
    v_new.operating_periods := v_periods;
    v_changed := v_changed || 'periods'::text;
  end if;

  if p_booking_windows is not null then
    if v_old.reservation_mode <> 'FIXED' then
      raise exception using errcode = '22023', message = '주간 신청(WEEKLY) 열람실은 신청 기간을 쓰지 않는다 — 매주 열리는 때(weekly_booking)를 따른다.';
    end if;
    v_win := mcp_private.sr_windows(p_booking_windows);
    v_new.booking_windows := v_win;
    -- 레거시 호환: 첫 신청 기간을 단일 칸에도(웹 RoomEditor)
    v_new.booking_start_date := (v_win->0->>'start')::timestamptz;
    v_new.booking_end_date := (v_win->0->>'end')::timestamptz;
    v_changed := v_changed || 'booking_windows'::text;
  end if;
  if p_allow_duplicate is not null then v_new.allow_duplicate_reservation := p_allow_duplicate; v_changed := v_changed || 'allow_duplicate'::text; end if;
  if cardinality(v_changed) = 0 then raise exception using errcode = '22023', message = '바꿀 칸이 없습니다.'; end if;

  if coalesce(p_check_only, true) then
    return jsonb_strip_nulls(jsonb_build_object('check_only', true, 'changed', v_changed,
      'before', mcp_private.sr_room_out(v_old), 'after', mcp_private.sr_room_out(v_new),
      'warnings', case when cardinality(v_warn) > 0 then to_jsonb(v_warn) end,
      'note', '아직 바꾸지 않았다 — before/after 를 사용자에게 보여 확인받은 뒤 check_only:false 로 다시 부른다. 학생 화면에 바로 반영된다.'));
  end if;

  update study_rooms
     set name = v_new.name, is_active = v_new.is_active, rules = v_new.rules,
         grades = v_new.grades, grade = v_new.grade,
         fixed_start_date = v_new.fixed_start_date, fixed_end_date = v_new.fixed_end_date,
         operating_days = v_new.operating_days, is_saturday_open = v_new.is_saturday_open, is_sunday_open = v_new.is_sunday_open,
         operating_periods = v_new.operating_periods, booking_windows = v_new.booking_windows,
         booking_start_date = v_new.booking_start_date, booking_end_date = v_new.booking_end_date,
         allow_duplicate_reservation = v_new.allow_duplicate_reservation, updated_at = now()
   where id = p_room_id;
  if not found then raise exception using errcode = '42501', message = '이 열람실을 고칠 권한이 없습니다.'; end if;
  select * into v_new from study_rooms where id = p_room_id;
  perform mcp_private.log_call(v_me, 'update_study_room', jsonb_build_object('room_id', p_room_id, 'changed', v_changed));
  return jsonb_strip_nulls(jsonb_build_object('saved', true, 'changed', v_changed, 'room', mcp_private.sr_room_out(v_new),
    'warnings', case when cardinality(v_warn) > 0 then to_jsonb(v_warn) end));
end;
$_$;


ALTER FUNCTION "public"."mcp_update_study_room"("p_room_id" "uuid", "p_name" "text", "p_is_active" boolean, "p_rules" "text", "p_operating_start" "date", "p_operating_end" "date", "p_operating_days" integer[], "p_periods" "jsonb", "p_booking_windows" "jsonb", "p_allow_duplicate" boolean, "p_grades" integer[], "p_check_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_task"("p_task_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_type" "text" DEFAULT NULL::"text", "p_step" integer DEFAULT NULL::integer, "p_due_dates" "text"[] DEFAULT NULL::"text"[], "p_assignees" "text"[] DEFAULT NULL::"text"[], "p_visible_from" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_me uuid := mcp_private.require_tool('work.manage');
  t public.task := mcp_private.wk_task(p_task_id);
  v_meta jsonb := coalesce(t.meta, '{}'); v_due timestamptz := t.due_date; d record;
  v_type text := coalesce(nullif(p_type, ''), t.type); v_order int := t.order_index;
  v_new jsonb; v_removed text[]; v_dates text[]; v_vis text; v_first text;
begin
  if p_title is not null and (btrim(p_title) = '' or length(btrim(p_title)) > 200) then raise exception using errcode = '22023', message = 'title 은 1~200자입니다.'; end if;
  if v_type not in ('procedural', 'one_time') then raise exception using errcode = '22023', message = 'type 은 procedural·one_time 입니다.'; end if;

  if p_due_dates is not null then
    select * into d from mcp_private.wk_due(p_due_dates);
    if d.deadlines is not null and jsonb_array_length(mcp_private.arr(v_meta->'units')) > 0 then
      raise exception using errcode = '22023', message = '과제 단위 할 일에는 마감을 여러 개 둘 수 없습니다.';
    end if;
    v_due := d.due;
    v_dates := array(select jsonb_array_elements_text(coalesce(d.deadlines, '[]')));
    -- 회차 기록은 새 회차 목록에 남는 것만(웹 pruneDeadlineProgress)
    v_meta := v_meta || jsonb_build_object('deadlines', d.deadlines,
      'deadlineProgress', case when d.deadlines is null then null else
        nullif((select coalesce(jsonb_object_agg(k, v), '{}') from jsonb_each(mcp_private.obj(v_meta->'deadlineProgress')) e(k, v) where k = any(v_dates)), '{}') end);
  end if;

  if p_assignees is not null then
    select coalesce(jsonb_agg(coalesce(
             (select o from jsonb_array_elements(mcp_private.arr(v_meta->'assignees')) o where o->>'id' = x->>'id' limit 1),
             x || jsonb_build_object('status', 'pending', 'assigned_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')))), '[]')
      into v_new from jsonb_array_elements(mcp_private.wk_people(p_assignees, '담당자')) x;
    select array_agg(o->>'id') into v_removed from jsonb_array_elements(mcp_private.arr(v_meta->'assignees')) o
    where not v_new @> jsonb_build_array(jsonb_build_object('id', o->>'id'));
    if v_removed is not null and exists (select 1 from jsonb_each(mcp_private.obj(v_meta->'unitProgress')) u(k, v), jsonb_object_keys(mcp_private.obj(u.v)) who
                                         where who = any(v_removed)) then
      raise exception using errcode = '22023', message = '과제 단위를 맡은 담당자는 뺄 수 없습니다 — 웹에서 단위를 먼저 풀어 주세요.';
    end if;
    v_meta := v_meta || jsonb_build_object('assignees', v_new);
    if v_removed is not null then
      v_meta := v_meta || jsonb_build_object(
        'deadlineProgress', case when jsonb_typeof(v_meta->'deadlineProgress') = 'object'
          then (select coalesce(jsonb_object_agg(k, v - v_removed), '{}') from jsonb_each(v_meta->'deadlineProgress') e(k, v)) end,
        'assignmentIssues', case when jsonb_typeof(v_meta->'assignmentIssues') = 'object' then (v_meta->'assignmentIssues') - v_removed end);
    end if;
  end if;

  if p_visible_from is not null then
    v_vis := nullif(btrim(p_visible_from), '');
    if v_vis is not null and v_vis !~ '^\d{4}-\d{2}-\d{2}$' then raise exception using errcode = '22023', message = 'visible_from 은 YYYY-MM-DD 입니다(지우려면 "").'; end if;
    v_meta := v_meta || jsonb_build_object('visibleFrom', v_vis);   -- null 을 명시해야 지워진다(웹과 같다)
  end if;
  v_first := coalesce(v_meta->'deadlines'->>0, to_char(v_due at time zone 'Asia/Seoul', 'YYYY-MM-DD'));
  if v_meta->>'visibleFrom' is not null and v_first is not null and v_meta->>'visibleFrom' > v_first then
    raise exception using errcode = '22023', message = '담당자에게 보이는 날(visible_from)이 첫 마감보다 늦습니다.';
  end if;

  if v_type = 'one_time' then v_order := 0;
  elsif t.type <> 'procedural' or p_step is not null then
    if p_step is not null and p_step >= 1 then
      update task set order_index = order_index + 1
      where event_id = t.event_id and type = 'procedural' and id <> t.id and order_index >= p_step;
      v_order := p_step;
    else
      select coalesce(max(order_index), 0) + 1 into v_order from task where event_id = t.event_id and type = 'procedural' and id <> t.id;
    end if;
  end if;

  if p_title is null and p_description is null and p_type is null and p_step is null and p_due_dates is null
     and p_assignees is null and p_visible_from is null then
    raise exception using errcode = '22023', message = '바꿀 것이 없습니다.';
  end if;
  update task set
    title = coalesce(nullif(btrim(p_title), ''), title),
    description = case when p_description is null then description else nullif(btrim(p_description), '') end,
    type = v_type, order_index = v_order, due_date = v_due, meta = v_meta
  where id = p_task_id;
  perform mcp_private.wk_renumber(t.event_id);
  perform mcp_private.log_call(v_me, 'update_task', jsonb_build_object('task_id', p_task_id));
  return jsonb_build_object('task_id', p_task_id, 'work', mcp_private.wk_work_out(t.event_id));
end $_$;


ALTER FUNCTION "public"."mcp_update_task"("p_task_id" "uuid", "p_title" "text", "p_description" "text", "p_type" "text", "p_step" integer, "p_due_dates" "text"[], "p_assignees" "text"[], "p_visible_from" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_volunteer_issue"("p_issue_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_issued_on" "date" DEFAULT NULL::"date", "p_department" "text" DEFAULT NULL::"text", "p_remarks" "text" DEFAULT NULL::"text", "p_form" "jsonb" DEFAULT NULL::"jsonb", "p_students" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me       uuid := mcp_private.require_tool('issue.register');
  v_row      document_issue := mcp_private.iss_lock_mine(p_issue_id, array['volunteer_personal', 'volunteer_class', 'volunteer_club'], '고칠');
  v_kind     text := case v_row.doc_type when 'volunteer_personal' then 'personal' else 'group' end;
  v_allowed  text[] := case when v_row.doc_type = 'volunteer_personal'
    then array['period_start', 'period_end', 'org', 'org_tel', 'place', 'area', 'content', 'hours', 'note', 'opinion', 'confirmer_title', 'confirmer_name']
    else array['period_start', 'period_end', 'org', 'org_tel', 'place', 'area', 'content', 'hours', 'scope'] end;
  v_form     jsonb := coalesce(v_row.form_data, '{}'::jsonb);
  v_base     jsonb;
  v_hours    numeric;
  v_students jsonb := v_row.students;
  v_title    text;
  v_grade    integer := v_row.grade;
  v_class    integer := v_row.class_number;
begin
  if p_title is null and p_issued_on is null and p_department is null and p_remarks is null and p_form is null and p_students is null then
    raise exception using errcode = '22023', message = '바꿀 칸(title · issued_on · department · remarks · form · students)을 하나 이상 주세요.';
  end if;
  if v_row.doc_type = 'volunteer_club' and (p_form is not null or p_students is not null) then
    raise exception using errcode = '22023', message = '동아리 봉사의 활동은 set_club_activities 로, 학생·출석은 웹 봉사 발급 대장에서 고칩니다.';
  end if;
  if p_title is not null and (btrim(p_title) = '' or length(p_title) > 200) then
    raise exception using errcode = '22023', message = 'title 은 1~200자입니다(지울 수 없다).';
  end if;

  if p_form is not null then
    if jsonb_typeof(p_form) <> 'object' then raise exception using errcode = '22023', message = 'form 은 바꿀 칸만 담은 객체입니다.'; end if;
    -- 지금 양식(쓸 수 있는 칸만) + 바꿀 칸 → 만들 때와 같은 검사. 웹이 적은 다른 칸은 그대로 둔다
    -- 웹 단체 봉사는 빈 칸을 ""로 적어 둔다 — 빈 값은 «없음»으로 보고 뺀다
    select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) into v_base from jsonb_each(v_form) e(k, v)
     where k = any(v_allowed) and v is distinct from '""'::jsonb and v is distinct from 'null'::jsonb;
    if not (v_base ? 'period_start') and not (p_form ? 'period_start') then
      -- 웹에서 만든 단체 봉사 중 양식이 빈 것이 있다 — 그때는 양식을 고치려면 필수 칸을 함께 줘야 한다
      raise exception using errcode = '22023',
        message = '이 발급에는 봉사 양식이 비어 있어, form 을 고치려면 period_start·area·content 를 함께 주세요(지금 값은 get_issue 로 확인).';
    end if;
    v_base := mcp_private.iss_volunteer_form(v_base || p_form, v_kind);
    -- 인정시간 기본값(1)을 새로 적지 않는다 — 단체 봉사는 웹이 시간을 학생마다 적고 양식에는 두지 않는다
    if not (v_form ? 'hours') and not (p_form ? 'hours') then v_base := v_base - 'hours'; end if;
    v_form := v_form || v_base;
  end if;
  -- 학생에게 적을 시간: 바꾼 값 > 양식 값 > 지금 첫 학생의 값 > 1
  v_hours := coalesce((v_form->>'hours')::numeric, (v_row.students->0->>'hours')::numeric, 1);

  if p_students is not null then
    v_students := mcp_private.iss_students(p_students, v_hours);
    if v_row.doc_type = 'volunteer_personal' and jsonb_array_length(v_students) <> 1 then
      raise exception using errcode = '22023', message = '개인 봉사는 학생 한 명입니다(여러 명이면 새로 발급).';
    end if;
  elsif v_row.doc_type <> 'volunteer_club' and p_form ? 'hours' and (v_form->>'hours') is distinct from (v_row.form_data->>'hours') then
    -- 인정시간이 바뀌면 학생마다 적힌 시간도 같이(웹 확인서가 학생 칸을 읽는다)
    select coalesce(jsonb_agg(case when s ? 'hours' then s || jsonb_build_object('hours', v_hours) else s end), '[]'::jsonb)
      into v_students from jsonb_array_elements(coalesce(v_row.students, '[]'::jsonb)) s;
  end if;

  if p_students is not null then
    if v_row.doc_type = 'volunteer_personal' then
      v_grade := (v_students->0->>'grade')::int; v_class := (v_students->0->>'class')::int;
    else
      select case when count(distinct s->>'grade') = 1 then min((s->>'grade')::int) end into v_grade from jsonb_array_elements(v_students) s;
      v_class := null;
      if v_grade is not null then
        select case when count(distinct s->>'class') = 1 then min((s->>'class')::int) end into v_class
        from jsonb_array_elements(v_students) s where (s->>'grade')::int = v_grade;
      end if;
    end if;
  end if;

  v_title := coalesce(btrim(p_title),
                      case when v_row.doc_type = 'volunteer_personal' and p_form ? 'content' then v_form->>'content' end,
                      v_row.title);

  update document_issue set
    title = v_title,
    issued_on = coalesce(p_issued_on, issued_on),
    department = case when p_department is null then department else nullif(btrim(p_department), '') end,
    remarks = case when p_remarks is null then remarks else nullif(btrim(p_remarks), '') end,
    form_data = v_form,
    students = v_students,
    grade = v_grade,
    class_number = v_class,
    meta = meta || jsonb_build_object('via_updated', mcp_private.iss_via())
  where id = v_row.id
  returning * into v_row;
  if not found then raise exception using errcode = '42501', message = '고치지 못했습니다(작성자·관리자만).'; end if;

  perform mcp_private.log_call(v_me, 'update_volunteer_issue', jsonb_build_object('issue_id', v_row.id, 'issue_no', v_row.issue_no,
    'form', p_form is not null, 'students', case when p_students is not null then jsonb_array_length(v_students) end));
  return mcp_private.iss_row_out(v_row) || jsonb_strip_nulls(jsonb_build_object(
    'form', case when v_row.doc_type <> 'volunteer_club' then v_form end,
    'students', (select jsonb_agg(mcp_private.iss_student_label(s)) from jsonb_array_elements(coalesce(v_row.students, '[]'::jsonb)) s),
    'note', '고쳤다. 발급번호는 그대로다. 확인서 한글 파일은 웹 봉사 발급 대장에서 다시 받는다.'));
end;
$$;


ALTER FUNCTION "public"."mcp_update_volunteer_issue"("p_issue_id" "uuid", "p_title" "text", "p_issued_on" "date", "p_department" "text", "p_remarks" "text", "p_form" "jsonb", "p_students" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_work"("p_work_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text", "p_managers" "text"[] DEFAULT NULL::"text"[], "p_status" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.manage');
  w public.work := mcp_private.wk_managed_work(p_work_id);
  v_meta jsonb := w.meta; v_managers jsonb;
begin
  if p_name is not null and (btrim(p_name) = '' or length(btrim(p_name)) > 200) then raise exception using errcode = '22023', message = 'name 은 1~200자입니다.'; end if;
  if p_status is not null and p_status not in ('active', 'completed', 'cancelled') then
    raise exception using errcode = '22023', message = 'status 는 active(진행 중)·completed(완료)·cancelled(취소)입니다.';
  end if;
  if p_department is not null then
    if btrim(p_department) = '' then v_meta := v_meta - 'department';
    elsif not exists (select 1 from department d where d.is_active and d.name = btrim(p_department)) then
      raise exception using errcode = '22023', message = format('부서 «%s» 를 찾지 못했습니다.', p_department);
    else v_meta := v_meta || jsonb_build_object('department', btrim(p_department)); end if;
  end if;
  if p_managers is not null then
    if cardinality(p_managers) = 0 then raise exception using errcode = '22023', message = '책임자는 한 명 이상이어야 합니다.'; end if;
    v_managers := mcp_private.wk_people(p_managers, '책임자');
    v_meta := v_meta || jsonb_build_object('managers', v_managers);
  end if;
  if p_name is null and p_description is null and p_department is null and p_managers is null and p_status is null then
    raise exception using errcode = '22023', message = '바꿀 것이 없습니다.';
  end if;
  update work set
    name = coalesce(nullif(btrim(p_name), ''), name),
    description = case when p_description is null then description else nullif(btrim(p_description), '') end,
    manager_id = coalesce((v_managers->0->>'id')::uuid, manager_id),
    status = coalesce(p_status, status),
    meta = v_meta
  where id = p_work_id;
  perform mcp_private.log_call(v_me, 'update_work', jsonb_build_object('work_id', p_work_id));
  return mcp_private.wk_work_out(p_work_id);
end $$;


ALTER FUNCTION "public"."mcp_update_work"("p_work_id" "uuid", "p_name" "text", "p_description" "text", "p_department" "text", "p_managers" "text"[], "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_work_knowledge"("p_knowledge_id" bigint, "p_title" "text" DEFAULT NULL::"text", "p_body" "text" DEFAULT NULL::"text", "p_basis" "text" DEFAULT NULL::"text", "p_archive" boolean DEFAULT NULL::boolean, "p_archived_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.run');
  k public.work_knowledge;
  v_n int;
begin
  select * into k from public.work_knowledge where id = p_knowledge_id;
  if k.id is null then raise exception using errcode = 'P0002', message = '그 지식을 찾지 못했습니다 (list_work_knowledge 의 knowledge_id).'; end if;
  if coalesce(p_archive, false) and btrim(coalesce(p_archived_reason, '')) = '' then
    raise exception using errcode = '22023', message = '보관할 때는 이유(archived_reason)를 적습니다 — 다음 담당자가 왜 빠졌는지 알 수 있게.';
  end if;
  update public.work_knowledge set
    title = coalesce(nullif(btrim(p_title), ''), title),
    body = coalesce(nullif(btrim(p_body), ''), body),
    basis = case when p_basis is null then basis else nullif(btrim(p_basis), '') end,
    status = case when p_archive is null then status when p_archive then 'archived' else 'active' end,
    archived_reason = case when p_archive is null then archived_reason when p_archive then left(btrim(p_archived_reason), 500) else null end
  where id = p_knowledge_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception using errcode = '42501', message = '이 지식을 고칠 수 없습니다 — 그 업무(또는 이어받은 업무)의 책임자만.'; end if;
  perform mcp_private.log_call(v_me, 'update_work_knowledge', jsonb_build_object('knowledge_id', p_knowledge_id, 'archive', p_archive));
  return (select jsonb_strip_nulls(jsonb_build_object('knowledge_id', id, 'kind', kind, 'title', title, 'status', status,
            'archived_reason', archived_reason)) from public.work_knowledge where id = p_knowledge_id);
end;
$$;


ALTER FUNCTION "public"."mcp_update_work_knowledge"("p_knowledge_id" bigint, "p_title" "text", "p_body" "text", "p_basis" "text", "p_archive" boolean, "p_archived_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_workflow"("p_workflow_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me   uuid := mcp_private.require_tool('workflow.manage');
  f      public.task_workflow := mcp_private.wf_editable(p_workflow_id);
  v_name text := coalesce(btrim(p_name), f.name);
  v_dept uuid := f.department_id;
begin
  if p_name is null and p_department is null then
    raise exception using errcode = '22023', message = '바꿀 것(name · department)을 하나 이상 주세요.';
  end if;
  if v_name = '' or char_length(v_name) > 200 then raise exception using errcode = '22023', message = 'name 은 1~200자입니다.'; end if;
  if p_department is not null then
    if btrim(p_department) = '' then
      v_dept := null;
    else
      select d.id into v_dept from department d where d.name = btrim(p_department) and coalesce(d.is_active, true);
      if v_dept is null then
        raise exception using errcode = '22023', message = format('부서 «%s» 를 찾지 못했습니다 — read_data 의 부서 이름 그대로 주세요.', btrim(p_department));
      end if;
    end if;
  end if;
  update task_workflow set name = v_name, department_id = v_dept where id = f.id;
  perform mcp_private.log_call(v_me, 'update_workflow', jsonb_build_object('workflow_id', f.id, 'name', v_name));
  return jsonb_build_object('workflow_id', f.id, 'name', v_name,
    'department', (select d.name from department d where d.id = v_dept), 'note', '고쳤다.');
end;
$$;


