CREATE OR REPLACE FUNCTION "public"."mcp_work_progress"("p_work_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_me uuid := mcp_private.require_tool('work.run');
  w public.work := mcp_private.wk_managed_work(p_work_id);
  v_prev uuid := nullif(w.meta->'rolledOverFrom'->>'workId', '')::uuid;
begin
  return jsonb_build_object(
    'today', to_char(mcp_private.kst_today(), 'YYYY-MM-DD'),
    'work', jsonb_strip_nulls(jsonb_build_object('work_id', w.id, 'name', w.name, 'status', w.status, 'year', w.meta->'year',
              'department', w.meta->>'department',
              'rolled_over_from', case when v_prev is not null then jsonb_build_object('work_id', v_prev, 'year', w.meta->'rolledOverFrom'->'year', 'name', w.meta->'rolledOverFrom'->>'name') end,
              'lineage_years', (select count(*) - 1 from mcp_private.work_lineage(w.id)))),
    'tasks', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'task_id', t.id, 'title', t.title, 'type', case t.type when 'one_time' then 'one_time' else 'procedural' end,
        'step', case when t.type = 'procedural' then t.order_index end, 'status', t.status,
        'due_dates', mcp_private.we_deadlines(t.meta, t.due_date), 'visible_from', t.meta->>'visibleFrom',
        'mode', case when jsonb_typeof(t.meta->'units') = 'array' and jsonb_array_length(t.meta->'units') > 0 then 'units'
                     when jsonb_typeof(t.meta->'deadlines') = 'array' and jsonb_array_length(t.meta->'deadlines') > 1 then 'rounds' else 'single' end,
        'assignees', jsonb_array_length(case when jsonb_typeof(t.meta->'assignees') = 'array' then t.meta->'assignees' else '[]' end),
        'assignees_done', (select count(*) from jsonb_array_elements(mcp_private.arr(t.meta->'assignees')) x where x->>'status' = 'completed'),
        'assignees_pending', (select jsonb_agg(x->>'name' order by x->>'name') from jsonb_array_elements(mcp_private.arr(t.meta->'assignees')) x
                              where coalesce(x->>'status', 'pending') = 'pending'),
        'actions', (select jsonb_agg(jsonb_build_object('action_id', a.id, 'type', a.action_type, 'title', a.title)
                                     || coalesce(mcp_private.wr_action_facts(a.id), '{}'::jsonb) order by a.created_at)
                    from public.task_action a where a.task_id = t.id and a.archived_at is null)))
        order by (t.type <> 'procedural'), case when t.type = 'procedural' then t.order_index end, t.due_date nulls last, t.created_at)
      from public.task t where t.event_id = w.id), '[]'::jsonb),
    -- 이 업무와 지난 해들(계보)의 수행 지식 — 할 일 지식은 계보가 이어진 올해 할 일(task_now)에 붙는다
    'knowledge', mcp_private.wk_knowledge(w.id, null, null, false, 40),
    -- 돌아보기 권하기·지식 후보의 재료 — 화면에 내보내지 않고 enrichProgress 가 판정한 뒤 지운다(사람 이름 없음)
    'history', mcp_private.wr_review_facts(w.id),
    'previous_history', case when v_prev is not null then mcp_private.wr_review_facts(v_prev) end,
    'reflection', (select jsonb_build_object('notes', count(*), 'last_note_at', max(k.created_at))
                   from public.work_knowledge k where k.work_id = w.id and k.status = 'active'));
end;
$$;


