CREATE OR REPLACE FUNCTION "public"."migrate_classroom_resources"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  migrated_count INTEGER := 0;
  failed_count INTEGER := 0;
  rec RECORD;
BEGIN
  UPDATE schema_migration_tracking 
  SET status = 'in_progress', started_at = now()
  WHERE table_name = 'resource_classrooms';

  FOR rec IN 
    SELECT r.id, r.meta,
           ARRAY_AGG(DISTINCT s.name) FILTER (WHERE s.name IS NOT NULL) as sections
    FROM resource r
    LEFT JOIN section_member sm ON r.id = sm.resource_id AND sm.role IN ('room', 'classroom')
    LEFT JOIN section s ON sm.section_id = s.id
    WHERE r.type = 'room'
    GROUP BY r.id, r.meta
  LOOP
    BEGIN
      UPDATE resource 
      SET meta = COALESCE(meta, '{}'::jsonb) || 
                 jsonb_build_object('section', COALESCE(rec.sections, ARRAY[]::TEXT[]))
      WHERE id = rec.id;
      
      migrated_count := migrated_count + 1;
    EXCEPTION
      WHEN OTHERS THEN
        failed_count := failed_count + 1;
        RAISE WARNING 'Failed to migrate classroom resource %: %', rec.id, SQLERRM;
    END;
  END LOOP;

  UPDATE schema_migration_tracking 
  SET migrated_records = migrated_count, 
      failed_records = failed_count,
      status = CASE WHEN failed_count = 0 THEN 'completed' ELSE 'partial' END,
      completed_at = now()
  WHERE table_name = 'resource_classrooms';

  RAISE NOTICE 'Classroom migration completed: % migrated, % failed', migrated_count, failed_count;
  RETURN migrated_count;
END;
$$;


ALTER FUNCTION "public"."migrate_classroom_resources"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_meeting_participants"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  migrated_count INTEGER := 0;
  failed_count INTEGER := 0;
  rec RECORD;
  participants JSONB;
BEGIN
  UPDATE schema_migration_tracking 
  SET status = 'in_progress', started_at = now()
  WHERE table_name = 'meeting_participants';

  -- Add meta column and rename created_by to creator
  ALTER TABLE meeting ADD COLUMN IF NOT EXISTS meta JSONB DEFAULT '{}';
  ALTER TABLE meeting ADD COLUMN IF NOT EXISTS creator UUID;
  
  -- Copy created_by to creator if not already done
  UPDATE meeting SET creator = created_by WHERE creator IS NULL AND created_by IS NOT NULL;

  FOR rec IN 
    SELECT m.id,
           jsonb_agg(
             jsonb_build_object(
               'resource_id', ma.resource_id,
               'role', ma.role,
               'required', COALESCE(ma.required, true)
             )
           ) as participants
    FROM meeting m
    LEFT JOIN meeting_allocation ma ON m.id = ma.meeting_id
    GROUP BY m.id
  LOOP
    BEGIN
      UPDATE meeting 
      SET meta = COALESCE(meta, '{}'::jsonb) || 
                 jsonb_build_object('participants', COALESCE(rec.participants, '[]'::jsonb))
      WHERE id = rec.id;
      
      migrated_count := migrated_count + 1;
    EXCEPTION
      WHEN OTHERS THEN
        failed_count := failed_count + 1;
        RAISE WARNING 'Failed to migrate meeting participants %: %', rec.id, SQLERRM;
    END;
  END LOOP;

  UPDATE schema_migration_tracking 
  SET migrated_records = migrated_count, 
      failed_records = failed_count,
      status = CASE WHEN failed_count = 0 THEN 'completed' ELSE 'partial' END,
      completed_at = now()
  WHERE table_name = 'meeting_participants';

  RAISE NOTICE 'Meeting participants migration completed: % migrated, % failed', migrated_count, failed_count;
  RETURN migrated_count;
END;
$$;


