CREATE OR REPLACE FUNCTION "public"."migrate_student_resources"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  migrated_count INTEGER := 0;
  failed_count INTEGER := 0;
  rec RECORD;
  section_names TEXT[];
BEGIN
  UPDATE schema_migration_tracking 
  SET status = 'in_progress', started_at = now()
  WHERE table_name = 'resource_students';

  -- Process each student resource
  FOR rec IN 
    SELECT r.id, r.meta,
           ARRAY_AGG(DISTINCT s.name) FILTER (WHERE s.name IS NOT NULL) as sections
    FROM resource r
    LEFT JOIN section_member sm ON r.id = sm.resource_id AND sm.role = 'student'
    LEFT JOIN section s ON sm.section_id = s.id
    WHERE r.type = 'student'
    GROUP BY r.id, r.meta
  LOOP
    BEGIN
      -- Merge existing meta with new section array
      UPDATE resource 
      SET meta = COALESCE(meta, '{}'::jsonb) || 
                 jsonb_build_object('section', COALESCE(rec.sections, ARRAY[]::TEXT[]))
      WHERE id = rec.id;
      
      migrated_count := migrated_count + 1;
    EXCEPTION
      WHEN OTHERS THEN
        failed_count := failed_count + 1;
        RAISE WARNING 'Failed to migrate student resource %: %', rec.id, SQLERRM;
    END;
  END LOOP;

  UPDATE schema_migration_tracking 
  SET migrated_records = migrated_count, 
      failed_records = failed_count,
      status = CASE WHEN failed_count = 0 THEN 'completed' ELSE 'partial' END,
      completed_at = now()
  WHERE table_name = 'resource_students';

  RAISE NOTICE 'Student migration completed: % migrated, % failed', migrated_count, failed_count;
  RETURN migrated_count;
END;
$$;


