CREATE OR REPLACE FUNCTION "public"."move_document_folder"("p_old_path" "text", "p_new_path" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_moved integer := 0;
begin
  if not public.is_admin() then
    raise exception 'permission denied: admin only';
  end if;
  if coalesce(p_old_path, '') = '' or coalesce(p_new_path, '') = '' then
    raise exception 'invalid path';
  end if;
  if p_new_path = p_old_path
     or left(p_new_path, length(p_old_path) + 1) = p_old_path || '/' then
    raise exception 'cannot move a folder into itself';
  end if;

  -- 문서 경로 prefix 치환
  update public.documents
     set meta = jsonb_set(coalesce(meta, '{}'::jsonb), '{directory_path}',
                to_jsonb(p_new_path || substr(meta->>'directory_path', length(p_old_path) + 1))),
         updated_at = now()
   where meta->>'directory_path' = p_old_path
      or left(meta->>'directory_path', length(p_old_path) + 1) = p_old_path || '/';
  get diagnostics v_moved = row_count;

  -- 폴더 registry 치환: 목적지에 같은 경로가 이미 있으면 병합(원본 행 제거)
  delete from public.document_folders src
   where (src.path = p_old_path or left(src.path, length(p_old_path) + 1) = p_old_path || '/')
     and exists (
       select 1 from public.document_folders dst
        where dst.path = p_new_path || substr(src.path, length(p_old_path) + 1)
     );
  update public.document_folders
     set path = p_new_path || substr(path, length(p_old_path) + 1)
   where path = p_old_path
      or left(path, length(p_old_path) + 1) = p_old_path || '/';

  -- 이동 결과 경로를 registry에 보장 (빈 폴더 이동 보존)
  insert into public.document_folders(path, created_by)
  values (p_new_path, auth.uid())
  on conflict (path) do nothing;

  return v_moved;
end;
$$;


ALTER FUNCTION "public"."move_document_folder"("p_old_path" "text", "p_new_path" "text") OWNER TO "postgres";


