CREATE OR REPLACE FUNCTION "public"."my_classroom_overview"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null or not public.is_staff_teacher_or_admin(v_uid) then
    return jsonb_build_object('active', '[]'::jsonb, 'recent', '[]'::jsonb, 'logins', '[]'::jsonb);
  end if;
  return jsonb_build_object(
    'active', coalesce((
      select jsonb_agg(jsonb_build_object(
               'code', l.code, 'device_name', l.device_name, 'title', p.title, 'section_name', p.section_name,
               'approved_at', l.approved_at, 'ends_at', l.ends_at) order by l.approved_at desc)
        from public.classroom_link l left join public.classroom_preset p on p.id = l.preset_id
       where l.approved_by = v_uid and l.purpose = 'session'
         and l.status in ('approved', 'active') and l.ends_at > now()), '[]'::jsonb),
    'recent', coalesce((
      select jsonb_agg(r.item order by r.at desc)
        from (select jsonb_build_object('device_name', l.device_name, 'title', p.title, 'section_name', p.section_name,
                                        'approved_at', l.approved_at, 'ended_at', coalesce(l.ended_at, l.ends_at)) as item,
                     l.approved_at as at
                from public.classroom_link l left join public.classroom_preset p on p.id = l.preset_id
               where l.approved_by = v_uid and l.purpose = 'session' and l.status = 'ended'
               order by l.approved_at desc limit 8) r), '[]'::jsonb),
    'logins', coalesce((
      select jsonb_agg(jsonb_build_object('ref', k.ref, 'device_name', coalesce(d.name, '교실 기기'),
                                          'created_at', k.created_at, 'last_used_at', k.last_used_at)
                       order by k.last_used_at desc)
        from public.classroom_profile_key k left join public.classroom_device d on d.key_hash = k.device_key_hash
       where k.user_id = v_uid), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."my_classroom_overview"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_collect_requests"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_out jsonb;
begin
  if auth.uid() is null then return '[]'::jsonb; end if;

  with me as (select x id from public.current_actor_resource_ids() x),
  mine as (
    select distinct t.action_id, t.unit_key, t.resource_id
    from public.collect_target t join me on me.id = t.resource_id
    where t.removed_at is null
  ),
  req as (
    select r.*, a.title action_title, public.request_cfg_of(a.action_type, a.config) cfg, tk.title task_title, tk.due_date task_due,
           (select w.name from public.work w where w.id = tk.event_id) work_title
    from public.collect_request r
    join public.task_action a on a.id = r.action_id and a.archived_at is null
    left join public.task tk on tk.id = r.task_id
    where r.action_id in (select action_id from mine)
      and r.status = 'open'
      and coalesce(tk.status, 'pending') not in ('completed', 'cancelled')
  ),
  cells as (
    -- 제출 요청(사람 축): 사람당 한 칸, 채움 = 낸 것이 있다(실물은 [받음])
    select q.action_id, m.unit_key, ''::text dim,
           public.submission_target_complete(q.action_id, m.resource_id) done
    from req q join mine m on m.action_id = q.action_id
    where q.kind <> 'input' and q.axis <> 'unit'
    union all
    -- 제출 요청(단위 축): 내가 맡은 단위마다 한 칸 — 맡은 단위가 없으면 칸도 없다(낼 것이 없다)
    select q.action_id, m.unit_key, h.key,
           exists (select 1 from public.action_submission s
                   where s.action_id = q.action_id and s.resource_id = m.resource_id and s.unit_key = h.key) done
    from req q join mine m on m.action_id = q.action_id
    cross join lateral unnest(public.submission_held_units(q.task_id, m.resource_id)) h(key)
    where q.kind <> 'input' and q.axis = 'unit'
    union all
    select q.action_id, m.unit_key, dims.dim,
           exists (
             select 1 from public.collect_response x
             where x.action_id = q.action_id and x.unit_key = m.unit_key and x.dimension_key = dims.dim
               and x.owner_key = case when q.answer_mode = 'shared' then '' else m.resource_id::text end
               and public.collect_cell_complete(x."values", q.cfg->'fields')) done
    from req q
    join mine m on m.action_id = q.action_id
    cross join lateral (
      select coalesce(d.value->>'key', '') dim
      from jsonb_array_elements(case when jsonb_array_length(coalesce(q.cfg->'dimensions', '[]'::jsonb)) = 0
                                     then '[{"key":""}]'::jsonb else q.cfg->'dimensions' end) d
    ) dims
    where q.kind = 'input'
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'action_id', q.action_id, 'kind', q.kind, 'task_id', q.task_id, 'task_title', q.task_title, 'work_title', q.work_title,
           'action_title', q.action_title, 'guide', q.cfg->>'guide',
           'due_date', coalesce(q.cfg->>'dueDate', q.task_due::text),
           'visibility', q.visibility, 'answer_mode', q.answer_mode,
           'total', (select count(*) from cells c where c.action_id = q.action_id),
           'done', (select count(*) from cells c where c.action_id = q.action_id and c.done),
           'started_at', q.started_at)
         order by coalesce(q.cfg->>'dueDate', q.task_due::text) nulls last, q.started_at), '[]'::jsonb)
    into v_out
  from req q;
  return v_out;
end;
$$;


