CREATE OR REPLACE FUNCTION "public"."next_document_issue_no"("p_space" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_year int := EXTRACT(YEAR FROM now())::int;
  v_next int;
BEGIN
  INSERT INTO document_issue_sequences (number_space, year, last_value)
  VALUES (p_space, v_year, 1)
  ON CONFLICT (number_space, year) DO UPDATE
    SET last_value = document_issue_sequences.last_value + 1
  RETURNING last_value INTO v_next;
  RETURN v_year::text || '-' || lpad(v_next::text, 3, '0');
END;
$$;


