CREATE OR REPLACE FUNCTION "public"."normalize_output_people"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(
    case when r.id is not null
      then jsonb_build_object('resourceId', r.id, 'name', r.name)
      else jsonb_build_object('resourceId', null, 'name', left(coalesce(x.e->>'name', ''), 60))
    end order by x.ord), '[]'::jsonb)
  from jsonb_array_elements(case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end) with ordinality as x(e, ord)
  left join public.resource r on r.id::text = x.e->>'resourceId'
  where coalesce(r.name, x.e->>'name', '') <> '';
$$;


ALTER FUNCTION "public"."normalize_output_people"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_subject_group"("p_category" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case btrim(coalesce(p_category, ''))
    when '국어'                  then '국어'
    when '수학'                  then '수학'
    when '영어'                  then '영어'
    when '사회'                  then '사회(역사/도덕 포함)'
    when '사회(역사/도덕 포함)'   then '사회(역사/도덕 포함)'
    when '한국사'                then '사회(역사/도덕 포함)'
    when '과학'                  then '과학'
    when '체육'                  then '체육'
    when '예술'                  then '예술'
    when '기술·가정'             then '기술·가정/정보'
    when '기술·가정/정보'        then '기술·가정/정보'
    when '정보·통신'             then '기술·가정/정보'
    when '제2외국어'             then '제2외국어/한문'
    when '한문'                  then '제2외국어/한문'
    when '제2외국어/한문'        then '제2외국어/한문'
    when '교양'                  then '교양'
    -- '기술·가정/제2외국어/한문/교양' 묶음은 과목마다 다르므로 NULL(수동 지정 대상)
    else null
  end;
$$;


ALTER FUNCTION "public"."normalize_subject_group"("p_category" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_subject_group"("p_category" "text") IS 'school_curriculum.category 원본 라벨 → 교과(군) 10종. 묶음 라벨(기술·가정/제2외국어/한문/교양)은 NULL — 과목별 수동 지정이 필요하다.';



