CREATE OR REPLACE FUNCTION "public"."notify_purchase_request_submitted"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_page_title text;
  v_page_columns jsonb;
  v_requester_name text;
  v_name_col text;
  v_first_name text;
  v_item_count int;
  v_summary text;
  v_manager uuid;
begin
  -- 알림 실패가 신청을 되돌려서는 안 된다. 이 블록은 하위 트랜잭션이라
  -- 알림 INSERT 만 롤백되고 본 신청은 그대로 커밋된다.
  begin
    v_item_count := coalesce(jsonb_array_length(NEW.items), 0);
    if v_item_count = 0 then
      return NEW;  -- 빈 신청은 알릴 내용이 없다
    end if;

    select prp.title, prp.columns into v_page_title, v_page_columns
    from public.purchase_request_pages prp
    where prp.id = NEW.page_id;

    if v_page_title is null then
      return NEW;
    end if;

    select r.name into v_requester_name
    from public.resource r
    where r.id = NEW.requester_id;

    -- 품목 요약("보드마카 외 2건") — 물품명 열은 기본 `default-name`, 없으면 첫 text 열.
    -- 클라이언트 `summarizeItemNames()` 의 **표시용 메아리**이지 판정 경로가 아니다
    -- (어긋나도 알림 문구만 덜 친절해질 뿐 승인·상태에는 영향이 없다).
    select coalesce(
             (select c->>'id' from jsonb_array_elements(v_page_columns) c
               where c->>'id' = 'default-name' limit 1),
             (select c->>'id' from jsonb_array_elements(v_page_columns) c
               where c->>'type' = 'text' limit 1)
           )
      into v_name_col;

    if v_name_col is not null then
      v_first_name := nullif(btrim(coalesce(NEW.items->0->'cells'->>v_name_col, '')), '');
    end if;

    if v_first_name is null then
      v_summary := v_item_count || '개 품목';
    elsif v_item_count > 1 then
      v_summary := v_first_name || ' 외 ' || (v_item_count - 1) || '건';
    else
      v_summary := v_first_name;
    end if;

    for v_manager in
      select prp.created_by
        from public.purchase_request_pages prp
       where prp.id = NEW.page_id
      union
      select prc.resource_id
        from public.purchase_request_collaborators prc
       where prc.page_id = NEW.page_id
    loop
      -- 매니저가 자기 페이지에 직접 신청한 경우는 자기 자신에게 알리지 않는다
      continue when v_manager is null or v_manager = NEW.requester_id;

      insert into public.notification_events (
        resource_id, type, title, message, priority, meta, is_read
      ) values (
        v_manager,
        'purchase_request_submitted',
        '새 구매 신청',
        coalesce(v_requester_name, '알 수 없는 신청자') || '님 · ' || v_summary
          || E'\n📋 ' || v_page_title,
        'medium',
        jsonb_build_object(
          'purchase_request_id', NEW.id,
          'purchase_page_id', NEW.page_id,
          'purchase_page_title', v_page_title,
          'requester_name', v_requester_name,
          'item_count', v_item_count
        ),
        false
      );
    end loop;
  exception when others then
    raise warning '구매 신청 알림 생성 실패 (request %): %', NEW.id, sqlerrm;
  end;

  return NEW;
end;
$$;


ALTER FUNCTION "public"."notify_purchase_request_submitted"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notify_purchase_request_submitted"() IS '구매 신청 INSERT 시 페이지 담당자(작성자·공동작업자)에게 notification_events 발송. 신청자 본인 제외, 실패해도 신청은 커밋.';



CREATE OR REPLACE FUNCTION "public"."notify_signature_created"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  -- 원본 경로가 확정되는 순간 = 요청이 실제로 쓸 수 있게 된 순간
  if old.source_path = 'pending' and new.source_path <> 'pending' then
    begin
      perform public.notify_signature_turn(new.id, new.current_order);
    exception when others then
      raise warning '전자서명 요청 알림 실패(요청 %): %', new.id, sqlerrm;
    end;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."notify_signature_created"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_signature_progress"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  begin
    -- 다음 그룹 차례
    if new.status = 'pending' and new.current_order <> old.current_order then
      perform public.notify_signature_turn(new.id, new.current_order);
    end if;

    -- 종료 → 요청자에게. 취소는 본인이 한 것이라 알리지 않는다
    if old.status = 'pending' and new.status in ('completed', 'rejected')
       and new.requester_resource_id is not null then
      insert into public.notification_events (type, title, message, resource_id, meta)
      values (
        'signature_request',
        case when new.status = 'completed' then '서명 완료' else '서명 거절' end,
        case when new.status = 'completed'
             then format('«%s» 서명이 모두 끝났습니다.', new.title)
             else format('«%s» 서명이 거절됐습니다.', new.title) end,
        new.requester_resource_id,
        jsonb_build_object('signature_request_id', new.id, 'link', '/signatures')
      );
    end if;
  exception when others then
    raise warning '전자서명 진행 알림 실패(요청 %): %', new.id, sqlerrm;
  end;
  return new;
end;
$$;


ALTER FUNCTION "public"."notify_signature_progress"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_signature_turn"("p_request_id" "uuid", "p_order" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request public.signature_request;
  v_signer  public.signature_signer;
  v_rid     uuid;
begin
  select * into v_request from public.signature_request where id = p_request_id;
  if not found or v_request.status <> 'pending' then return; end if;
  -- 알림 없이 만든 요청(meta.notify = false) — 서명자는 목록에서만 본다
  if coalesce(v_request.meta->>'notify', 'true') = 'false' then return; end if;

  for v_signer in
    select * from public.signature_signer
    where request_id = p_request_id and order_index = p_order and status = 'pending'
  loop
    v_rid := public.signature_signer_resource(v_signer);
    -- 리소스를 못 찾으면 보낼 곳이 없다. 조용히 건너뛰되 서명 자체는 계속 가능하다
    if v_rid is null then continue; end if;

    insert into public.notification_events (type, title, message, resource_id, meta)
    values (
      'signature_request',
      '서명 요청',
      case
        when v_rid = v_request.requester_resource_id
          then format('«%s» 서명할 차례입니다.', v_request.title)
        else format('%s님이 «%s» 서명을 요청했습니다.', v_request.requester_name, v_request.title)
      end,
      v_rid,
      -- related_meeting_id 는 meeting FK 라 쓸 수 없다 — 딥링크는 meta 로 (구매 신청과 같은 처리)
      jsonb_build_object('signature_request_id', v_request.id, 'link', '/signatures')
    );
  end loop;
end;
$$;


ALTER FUNCTION "public"."notify_signature_turn"("p_request_id" "uuid", "p_order" integer) OWNER TO "postgres";


