CREATE OR REPLACE FUNCTION "public"."notify_task_deadlines"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_inserted integer := 0;
  v_managers integer := 0;
begin
  -- 로그인 필수 — `auth.uid()` 가 NULL 이면 3값 논리로 조용히 통과하는 자리가 생긴다
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  -- 교직원만 방아쇠를 당긴다(학생 접속마다 전체 할 일을 훑을 이유가 없다)
  if not public.is_staff_teacher_or_admin(auth.uid()) then
    return 0;
  end if;

  -- ⚠️ 한 트랜잭션에서 두 번 불릴 수 있다(다른 함수가 부르거나 검증 스크립트가 잇달아 부를 때)
  -- — `on commit drop` 은 «커밋 때» 지우므로 두 번째 호출이 42P07 로 죽는다. 먼저 치운다.
  drop table if exists tmp_deadline_targets;
  create temp table tmp_deadline_targets on commit drop as
  with live as (
    select t.id as task_id, t.title, t.event_id, t.meta, t.due_date
    from public.task t
    join public.work w on w.id = t.event_id
    where coalesce(t.status, '') not in ('completed', 'cancelled')
      and coalesce(w.status, '') not in ('completed', 'cancelled')
  ),
  -- 다중 마감은 회차를 전개하고, 단일 마감은 due_date 하나. 두 경로를 섞지 않는다
  -- (`meta.deadlines` 가 있으면 `due_date` 는 «다음 마감»의 사본이라 세면 두 번이다).
  rounds as (
    select l.task_id, l.title, l.event_id, l.meta, d.value::date as deadline
    from live l
    cross join lateral jsonb_array_elements_text(l.meta->'deadlines') as d(value)
    where jsonb_typeof(l.meta->'deadlines') = 'array'
      and d.value ~ '^\d{4}-\d{2}-\d{2}$'
      and d.value::date between current_date and current_date + 3
    union all
    -- ⚠️ `task.due_date` 는 timestamptz 다 — `::date` 로 못 박지 않으면 위 회차(date)와
    -- 타입이 갈려 `deadline - current_date` 가 정수가 아니라 interval 이 된다(D-n 계산이 깨진다).
    select l.task_id, l.title, l.event_id, l.meta, l.due_date::date
    from live l
    -- ⚠️ `coalesce` 가 필수다 — 키가 없으면 `jsonb_typeof` 가 NULL 이고 `NULL <> 'array'` 는
    -- false 가 아니라 **NULL** 이라 WHERE 를 통과하지 못한다. 그러면 **단일 마감 할 일 전체가
    -- 조용히 빠진다**(가장 흔한 경우인데 오류가 나지 않아 «알림이 안 온다»로만 드러난다).
    where coalesce(jsonb_typeof(l.meta->'deadlines'), '') <> 'array'
      and l.due_date is not null
      and l.due_date::date between current_date and current_date + 3
  )
  select
    r.task_id,
    r.title,
    r.event_id,
    r.deadline,
    (a.value->>'id')::uuid as resource_id
  from rounds r
  cross join lateral jsonb_array_elements(r.meta->'assignees') as a(value)
  where coalesce(jsonb_typeof(r.meta->'assignees'), '') = 'array'
    and (a.value->>'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    -- 담당자 개인 상태
    and coalesce(a.value->>'status', 'pending') not in ('completed', 'cancelled')
    -- ⚠️ 다중 마감은 «그 회차»를 이미 끝냈는지 따로 본다 — 담당자 상태는 **모든 회차**를
    -- 끝내야 completed 가 되므로, 그것만 보면 끝낸 회차에도 알림이 간다.
    and coalesce(
      r.meta->'deadlineProgress'->(r.deadline::text)->(a.value->>'id')->>'status',
      'pending'
    ) <> 'completed';

  -- ── 담당자에게 ──────────────────────────────────────────────────────────
  insert into public.notification_events (resource_id, type, title, message, priority, meta)
  select
    g.resource_id,
    'task_deadline',
    case
      when g.deadline = current_date then '오늘 마감'
      when g.deadline = current_date + 1 then '내일 마감'
      else 'D-' || (g.deadline - current_date) || ' 마감'
    end || ' · ' || left(g.title, 40),
    to_char(g.deadline, 'MM월 DD일') || '까지 「' || g.title || '」를 마쳐 주세요.',
    -- ⚠️ 허용값은 low|medium|high 다('normal' 은 CHECK 위반)
    case when g.deadline <= current_date + 1 then 'high' else 'medium' end,
    jsonb_build_object(
      'task_id', g.task_id::text,
      'deadline', to_char(g.deadline, 'YYYY-MM-DD'),
      'work_id', g.event_id::text
    )
  from tmp_deadline_targets g
  where not exists (
    select 1 from public.notification_events n
    where n.resource_id = g.resource_id
      and n.type = 'task_deadline'
      and n.meta->>'task_id' = g.task_id::text
      and n.meta->>'deadline' = to_char(g.deadline, 'YYYY-MM-DD')
  )
  on conflict (resource_id, type, ((meta->>'task_id')), ((meta->>'deadline')))
    where type in ('task_deadline', 'task_deadline_summary')
    do nothing;
  get diagnostics v_inserted = row_count;

  -- ── 매니저에게 미완료 요약 ──────────────────────────────────────────────
  -- 매니저이면서 담당자인 사람에게는 보내지 않는다(위에서 개인 알림을 이미 받았다).
  insert into public.notification_events (resource_id, type, title, message, priority, meta)
  select
    m.resource_id,
    'task_deadline_summary',
    case
      when s.deadline = current_date then '오늘 마감'
      when s.deadline = current_date + 1 then '내일 마감'
      else 'D-' || (s.deadline - current_date) || ' 마감'
    end || ' · 미완료 ' || s.pending || '명',
    '「' || s.title || '」 ' || to_char(s.deadline, 'MM월 DD일') || ' 마감 — 아직 ' || s.pending || '명이 남았습니다.',
    'medium',
    jsonb_build_object(
      'task_id', s.task_id::text,
      'deadline', to_char(s.deadline, 'YYYY-MM-DD'),
      'work_id', s.event_id::text,
      'pending', s.pending
    )
  from (
    select task_id, title, event_id, deadline, count(*) as pending
    from tmp_deadline_targets
    group by task_id, title, event_id, deadline
  ) s
  cross join lateral (
    -- `event.meta.managers` 가 정본이고 `manager_id` 는 레거시 호환으로 함께 본다
    select distinct manager_id as resource_id
    from (
      select (mm.value->>'id')::uuid as manager_id
      from public.work w
      cross join lateral jsonb_array_elements(w.meta->'managers') as mm(value)
      where w.id = s.event_id
        and coalesce(jsonb_typeof(w.meta->'managers'), '') = 'array'
        and (mm.value->>'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      union
      select w.manager_id from public.work w where w.id = s.event_id and w.manager_id is not null
    ) x
    where manager_id is not null
  ) m
  where not exists (
    select 1 from tmp_deadline_targets g
    where g.task_id = s.task_id and g.deadline = s.deadline and g.resource_id = m.resource_id
  )
  and not exists (
    select 1 from public.notification_events n
    where n.resource_id = m.resource_id
      and n.type = 'task_deadline_summary'
      and n.meta->>'task_id' = s.task_id::text
      and n.meta->>'deadline' = to_char(s.deadline, 'YYYY-MM-DD')
  )
  on conflict (resource_id, type, ((meta->>'task_id')), ((meta->>'deadline')))
    where type in ('task_deadline', 'task_deadline_summary')
    do nothing;
  get diagnostics v_managers = row_count;

  return v_inserted + v_managers;
end;
$_$;


ALTER FUNCTION "public"."notify_task_deadlines"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."official_doc_ingest"("p_key_hash" "text", "p_docs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  r automation_runner := automation_private.runner_by_key(p_key_hash);
  d jsonb;
  t jsonb;
  v_id uuid;
  v_new boolean;
  v_body text;
  v_status text;
  v_inserted int := 0;
  v_updated int := 0;
  v_triaged int := 0;
  v_hash text;
  v_deadline date;
  v_conf numeric;
begin
  if jsonb_typeof(p_docs) is distinct from 'array' then
    raise exception 'docs 는 배열이어야 합니다' using errcode = '22023';
  end if;
  if jsonb_array_length(p_docs) > 300 then
    raise exception '한 번에 300건까지' using errcode = '22023';
  end if;

  for d in select * from jsonb_array_elements(p_docs) loop
    if coalesce(btrim(d->>'doc_no'), '') = '' or coalesce(btrim(d->>'title'), '') = '' then
      continue;
    end if;
    v_status := case when d->>'body_status' in ('none', 'stored', 'private', 'failed') then d->>'body_status' else 'none' end;
    v_body := case when v_status = 'stored' then left(d->>'body', 20000) end;
    if v_body is null and v_status = 'stored' then v_status := 'none'; end if;

    insert into official_doc as o (doc_no, registered_at, title, sender, approver_name, drafter_name,
                                   approval_type, process_status, disclosure, body, body_status,
                                   attachments, meta, runner_id)
    values (btrim(d->>'doc_no'), nullif(d->>'registered_at', '')::timestamptz, left(d->>'title', 500),
            left(d->>'sender', 200), left(d->>'approver_name', 100), left(d->>'drafter_name', 100),
            left(d->>'approval_type', 50), left(d->>'process_status', 50), left(d->>'disclosure', 50),
            v_body, v_status,
            case when jsonb_typeof(d->'attachments') = 'array' then d->'attachments' else '[]'::jsonb end,
            case when jsonb_typeof(d->'meta') = 'object' then d->'meta' else '{}'::jsonb end,
            r.id)
    on conflict (doc_no) do update set
      process_status = coalesce(nullif(btrim(excluded.process_status), ''), o.process_status),
      -- «미지정»·빈 값은 이미 정해진 담당을 지우지 않는다(옛 수집 파일을 다시 올려도 안전)
      approver_name  = case when coalesce(btrim(excluded.approver_name), '') in ('', '미지정') then coalesce(o.approver_name, excluded.approver_name)
                            else excluded.approver_name end,
      drafter_name   = coalesce(excluded.drafter_name, o.drafter_name),
      -- 본문은 «새로 받았을 때만» 바꾼다(다음 회차가 본문 없이 올려도 지우지 않는다)
      body           = case when excluded.body_status in ('stored', 'private') then excluded.body else o.body end,
      body_status    = case when excluded.body_status in ('stored', 'private') then excluded.body_status else o.body_status end,
      attachments    = case when jsonb_array_length(excluded.attachments) > 0 then excluded.attachments else o.attachments end,
      -- 메타(머리·꼬리에서 뗀 수신·시행·접수·결재선·연락처·붙임 등)는 새로 온 칸이 덮는다(빈 칸은 남긴다)
      meta           = o.meta || excluded.meta,
      updated_at     = now()
    returning id, (xmax = 0) into v_id, v_new;

    if v_new then v_inserted := v_inserted + 1; else v_updated := v_updated + 1; end if;

    t := d->'triage';
    if jsonb_typeof(t) = 'object' and t->>'engine' in ('rules', 'llm') then
      v_hash := md5(coalesce(t->>'model', '') || '|' || coalesce(t->>'prompt_version', '') || '|' || coalesce(t->'result', '{}'::jsonb)::text);
      v_deadline := case when (t->'result'->>'deadline') ~ '^\d{4}-\d{2}-\d{2}$' then (t->'result'->>'deadline')::date end;
      v_conf := case when jsonb_typeof(t->'result'->'confidence') = 'number'
                      then least(1, greatest(0, (t->'result'->>'confidence')::numeric)) end;
      insert into official_doc_triage (doc_id, engine, model, prompt_version, nature, needs_action, deadline,
                                       confidence, question, result, result_hash)
      values (v_id, t->>'engine', left(t->>'model', 80), left(t->>'prompt_version', 40),
              official_doc_private.triage_nature(t->'result'),
              case when jsonb_typeof(t->'result'->'needs_action') = 'boolean' then (t->'result'->>'needs_action')::boolean end,
              v_deadline, v_conf, left(t->'result'->>'question', 500),
              coalesce(t->'result', '{}'::jsonb), v_hash)
      on conflict (doc_id, result_hash) do nothing;
      if found then v_triaged := v_triaged + 1; end if;
    end if;
  end loop;

  return jsonb_build_object('inserted', v_inserted, 'updated', v_updated, 'triaged', v_triaged);
end;
$_$;


ALTER FUNCTION "public"."official_doc_ingest"("p_key_hash" "text", "p_docs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."official_doc_is_mine"("p_approver" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select auth.uid() is not null
    and coalesce(btrim(p_approver), '') <> ''
    and public.is_staff_teacher_or_admin(auth.uid())
    and exists (
      select 1
      from public.user_resource ur
      join public.resource r on r.id = ur.resource_id
      where ur.user_id = auth.uid()
        and r.type in ('teacher', 'staff')
        and r.name = btrim(p_approver)
    );
$$;


ALTER FUNCTION "public"."official_doc_is_mine"("p_approver" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."official_doc_is_mine"("p_approver" "text") IS '공문의 결재권자 이름이 호출자(명단에 연결된 교직원)의 이름인가 — 담당 본인 읽기 정책의 판정(2026-11-08). INVOKER.';



CREATE OR REPLACE FUNCTION "public"."official_doc_knowledge"("p_key_hash" "text", "p_year" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r automation_runner := automation_private.runner_by_key(p_key_hash);
  v_year int := coalesce(p_year, extract(year from (now() at time zone 'Asia/Seoul'))::int);
begin
  return jsonb_build_object(
    'year', v_year,
    'candidates', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', c.id, 'name', c.name, 'area', c.area_name, 'seat', c.seat_name,
               'department', c.department, 'brm', c.brm, 'type', c.work_type, 'months', c.months,
               'examples', (select coalesce(jsonb_agg(e->>'title'), '[]'::jsonb)
                              from (select e from jsonb_array_elements(coalesce(c.evidence, '[]'::jsonb)) e
                                     where e->>'title' is not null and coalesce((e->>'dir')::int, 0) = 0
                                     limit 6) x)
             ) order by c.name)
        from work_candidate c
       where c.kind = 'work' and c.academic_year = v_year), '[]'::jsonb),
    'works', coalesce((
      select jsonb_agg(jsonb_build_object('id', w.id, 'name', w.name, 'keywords', w.keywords,
                                          'department', w.meta->>'department') order by w.name)
        from work w
       where w.status = 'active'
         and coalesce(w.meta->>'year', v_year::text) = v_year::text), '[]'::jsonb),
    'seats', coalesce((
      select jsonb_agg(jsonb_build_object(
               'name', s.name, 'department', dp.name, 'kind', s.kind,
               'areas', (select coalesce(jsonb_agg(a->>'name'), '[]'::jsonb) from jsonb_array_elements(s.areas) a),
               'holders', (select coalesce(jsonb_agg(h.holder_name order by h.role), '[]'::jsonb)
                             from duty_seat_holder h
                            where h.seat_id = s.id and public.duty_holder_active(h.start_date, h.end_date, current_date))
             ) order by s.sort_order, s.name)
        from duty_seat s left join department dp on dp.id = s.department_id
       where s.academic_year = v_year), '[]'::jsonb),
    'rules', coalesce((
      select jsonb_agg(jsonb_build_object('id', x.id, 'kind', x.kind, 'condition', x.condition,
                                          'outcome', x.outcome, 'note', x.note))
        from doc_rule x
       where x.status = 'active' and (x.academic_year is null or x.academic_year = v_year)), '[]'::jsonb),
    'decisions', coalesce((
      select jsonb_agg(z.j order by z.at desc) from (
        select y.at, y.j from (
          select distinct on (dd.doc_id)
                 dd.created_at as at,
                 jsonb_build_object('title', o.title, 'sender', o.sender, 'decision', dd.decision,
                                    'nature', dd.nature, 'work', w.name, 'candidate', c.name,
                                    'assignees', dd.assignee_names, 'reason', dd.reason) as j
            from official_doc_decision dd
            join official_doc o on o.id = dd.doc_id
            left join work w on w.id = dd.work_id
            left join work_candidate c on c.id = dd.work_candidate_id
           order by dd.doc_id, dd.created_at desc
        ) y
        order by y.at desc limit 300
      ) z), '[]'::jsonb),
    -- 이미 올라온 문서번호(최근 60일) — 서버 PC 가 다시 판정하지 않게
    'known', coalesce((
      select jsonb_agg(o.doc_no) from official_doc o
       where o.registered_at >= now() - interval '60 days'
         and exists (select 1 from official_doc_triage t where t.doc_id = o.id and t.engine = 'llm')), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."official_doc_knowledge"("p_key_hash" "text", "p_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."official_doc_my_names"() RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when auth.uid() is null or not public.is_staff_teacher_or_admin(auth.uid()) then '{}'::text[]
    else coalesce((
      select array_agg(distinct r.name)
      from public.user_resource ur
      join public.resource r on r.id = ur.resource_id
      where ur.user_id = auth.uid()
        and r.type in ('teacher', 'staff')
        and coalesce(btrim(r.name), '') <> ''
    ), '{}'::text[])
  end;
$$;


ALTER FUNCTION "public"."official_doc_my_names"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."official_doc_my_names"() IS '공문 «담당 본인 읽기» 정책용 — 호출자(명단에 연결된 교직원)의 이름 배열. official_doc_is_mine 과 같은 판정을 문장마다 한 번만(2026-11-13). INVOKER.';



CREATE OR REPLACE FUNCTION "public"."official_doc_refs"("p_key_hash" "text", "p_numbers" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r automation_runner := automation_private.runner_by_key(p_key_hash);
begin
  if coalesce(array_length(p_numbers, 1), 0) = 0 then
    return '[]'::jsonb;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'issued_no', o.meta->'시행'->>'번호', 'doc_no', o.doc_no, 'title', o.title,
             'nature', t.nature, 'obligation', t.result->>'obligation', 'deadline', t.deadline,
             'decision', d.decision, 'work_id', d.work_id))
    from official_doc o
    left join lateral (select * from official_doc_triage x where x.doc_id = o.id order by x.created_at desc limit 1) t on true
    left join lateral (select * from official_doc_decision x where x.doc_id = o.id order by x.created_at desc limit 1) d on true
    where o.meta->'시행'->>'번호' = any (p_numbers[1:50])
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."official_doc_refs"("p_key_hash" "text", "p_numbers" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."official_doc_unassigned"("p_key_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r automation_runner := automation_private.runner_by_key(p_key_hash);
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object('doc_no', o.doc_no, 'registered_at', o.registered_at) order by o.registered_at)
    from official_doc o
    where coalesce(btrim(o.approver_name), '') in ('', '미지정')
      and o.registered_at >= now() - interval '30 days'
  ), '[]'::jsonb);
end;
$$;


