CREATE OR REPLACE FUNCTION "public"."owns_notification_resource"("p_resource_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    EXISTS (
      SELECT 1 FROM public.user_resource ur
      WHERE ur.user_id = auth.uid() AND ur.resource_id = p_resource_id
    )
    OR EXISTS (
      SELECT 1 FROM public.resource r
      WHERE r.id = p_resource_id
        AND r.type = 'student'
        AND r.meta->>'id' = public.current_student_code()
    );
$$;


