CREATE OR REPLACE FUNCTION "public"."process_graduated_student_cohort"("p_admission_year" integer, "p_expected_mapping" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  admission_prefix text;
  existing_sequence integer;
  student_count integer;
  account_count integer;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.profiles profile
    where profile.id = auth.uid()
      and profile.role = 'admin'
  ) then
    raise exception 'Only administrators can process graduated students'
      using errcode = '42501';
  end if;

  if p_admission_year < 2000 or p_admission_year > 2099 then
    raise exception 'Admission year must be between 2000 and 2099'
      using errcode = '22023';
  end if;

  if p_expected_mapping is null
     or jsonb_typeof(p_expected_mapping) <> 'array' then
    raise exception 'Expected mapping must be a JSON array'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('graduate_student_privacy', 0));

  admission_prefix := right(p_admission_year::text, 2) || '-';

  select coalesce(
    max(substring(resource.name from '입학([0-9]{3})$')::integer),
    0
  )
  into existing_sequence
  from public.resource resource
  where resource.type = 'student'
    and resource.status = 'graduated'
    and resource.meta ->> 'id' like admission_prefix || '%'
    and resource.name ~ (
      '^' || p_admission_year::text || '입학[0-9]{3}$'
    );

  if exists (
    select 1
    from public.resource resource
    where resource.type = 'student'
      and resource.status = 'active'
      and resource.meta ->> 'id' like admission_prefix || '%'
      and (
        resource.meta ->> 'id' !~ '^[0-9]{2}-'
        or resource.name is null
        or btrim(resource.name) = ''
      )
  ) then
    raise exception 'A graduation candidate is missing a valid student code or name';
  end if;

  drop table if exists pg_temp.graduate_name_map;

  create temporary table graduate_name_map (
    resource_id uuid primary key,
    student_code text not null unique,
    admission_year integer not null,
    sequence integer not null,
    real_name text not null,
    anonymous_name text not null unique
  ) on commit drop;

  insert into pg_temp.graduate_name_map (
    resource_id,
    student_code,
    admission_year,
    sequence,
    real_name,
    anonymous_name
  )
  with ranked as (
    select
      resource.id as resource_id,
      resource.meta ->> 'id' as student_code,
      resource.name as real_name,
      existing_sequence + row_number() over (
        order by
          convert_to(resource.name, 'UTF8'),
          convert_to(resource.meta ->> 'id', 'UTF8')
      )::integer as sequence
    from public.resource resource
    where resource.type = 'student'
      and resource.status = 'active'
      and resource.meta ->> 'id' like admission_prefix || '%'
  )
  select
    ranked.resource_id,
    ranked.student_code,
    p_admission_year,
    ranked.sequence,
    ranked.real_name,
    p_admission_year::text || '입학' || lpad(ranked.sequence::text, 3, '0')
  from ranked;

  select count(*)::integer
  into student_count
  from pg_temp.graduate_name_map;

  if student_count = 0 then
    raise exception 'No active students were found for admission year %', p_admission_year;
  end if;

  if existing_sequence + student_count > 999 then
    raise exception 'Graduate alias sequence exceeds 999 for admission year %',
      p_admission_year;
  end if;

  if jsonb_array_length(p_expected_mapping) <> student_count
     or (
       select count(distinct (item.value ->> 'resource_id', item.value ->> 'anonymous_name'))
       from jsonb_array_elements(p_expected_mapping) as item(value)
     ) <> student_count
     or exists (
       select 1
       from pg_temp.graduate_name_map mapping
       where not exists (
         select 1
         from jsonb_array_elements(p_expected_mapping) as item(value)
         where item.value ->> 'resource_id' = mapping.resource_id::text
           and item.value ->> 'anonymous_name' = mapping.anonymous_name
       )
     )
  then
    raise exception 'Graduation preview is stale; search again before processing'
      using errcode = '40001';
  end if;

  if exists (
    select 1
    from public.resource resource
    join pg_temp.graduate_name_map mapping
      on resource.name = mapping.anonymous_name
     and resource.id <> mapping.resource_id
    where resource.type = 'student'
  ) then
    raise exception 'A generated graduate alias is already in use';
  end if;

  drop table if exists pg_temp.graduate_user_map;

  create temporary table graduate_user_map on commit drop as
  select
    mapping.*,
    auth_user.id as user_id
  from pg_temp.graduate_name_map mapping
  join auth.users auth_user
    on split_part(lower(auth_user.email), '@', 1) = lower(mapping.student_code);

  create unique index graduate_user_map_user_id_idx
    on graduate_user_map (user_id);

  select count(*)::integer
  into account_count
  from pg_temp.graduate_user_map;

  update public.student_basic_info student
  set
    name = mapping.anonymous_name,
    grade = null,
    class_num = null,
    number = null,
    section1_personal_info =
      graduate_privacy_private.replace_names_in_jsonb(
        student.section1_personal_info,
        jsonb_build_array(jsonb_build_object(
          'old_name', mapping.real_name,
          'anonymous_name', mapping.anonymous_name
        ))
      ),
    grade_info = graduate_privacy_private.replace_names_in_jsonb(
      student.grade_info,
      jsonb_build_array(jsonb_build_object(
        'old_name', mapping.real_name,
        'anonymous_name', mapping.anonymous_name
      ))
    ),
    attendance = graduate_privacy_private.replace_names_in_jsonb(
      student.attendance,
      jsonb_build_array(jsonb_build_object(
        'old_name', mapping.real_name,
        'anonymous_name', mapping.anonymous_name
      ))
    ),
    volunteer = graduate_privacy_private.replace_names_in_jsonb(
      student.volunteer,
      jsonb_build_array(jsonb_build_object(
        'old_name', mapping.real_name,
        'anonymous_name', mapping.anonymous_name
      ))
    ),
    reading = graduate_privacy_private.replace_names_in_jsonb(
      student.reading,
      jsonb_build_array(jsonb_build_object(
        'old_name', mapping.real_name,
        'anonymous_name', mapping.anonymous_name
      ))
    ),
    academic_development =
      graduate_privacy_private.replace_names_in_jsonb(
        student.academic_development,
        jsonb_build_array(jsonb_build_object(
          'old_name', mapping.real_name,
          'anonymous_name', mapping.anonymous_name
        ))
      ),
    mock_result = graduate_privacy_private.replace_names_in_jsonb(
      student.mock_result,
      jsonb_build_array(jsonb_build_object(
        'old_name', mapping.real_name,
        'anonymous_name', mapping.anonymous_name
      ))
    ),
    mock_marking = graduate_privacy_private.replace_names_in_jsonb(
      student.mock_marking,
      jsonb_build_array(jsonb_build_object(
        'old_name', mapping.real_name,
        'anonymous_name', mapping.anonymous_name
      ))
    )
  from pg_temp.graduate_name_map mapping
  where lower(student.id) = lower(mapping.student_code);

  update public.student_career_submissions submission
  set student_name = mapping.anonymous_name
  from pg_temp.graduate_name_map mapping
  where lower(submission.my_id) = lower(mapping.student_code);

  update public.afterschool_enrollments enrollment
  set student_name = mapping.anonymous_name
  from pg_temp.graduate_name_map mapping
  where lower(enrollment.student_id) = lower(mapping.student_code)
     or lower(enrollment.my_id) = lower(mapping.student_code);

  update public.student_timetable timetable
  set student_name = mapping.anonymous_name
  from pg_temp.graduate_name_map mapping
  where timetable.resource_id = mapping.resource_id;

  update public.student_enrollment enrollment
  set student_name = mapping.anonymous_name
  from pg_temp.graduate_name_map mapping
  where enrollment.student_resource_id = mapping.resource_id;

  update public.course_selection_submission submission
  set student_name = mapping.anonymous_name
  from pg_temp.graduate_name_map mapping
  where submission.student_resource_id = mapping.resource_id
     or lower(submission.student_code) = lower(mapping.student_code);

  update public.class_student_memos memo
  set student_name = mapping.anonymous_name
  from pg_temp.graduate_name_map mapping
  where lower(memo.student_code) = lower(mapping.student_code);

  update public.teacher_observations observation
  set student_name = mapping.anonymous_name
  from pg_temp.graduate_name_map mapping
  where lower(observation.student_id) = lower(mapping.student_code);

  with rebuilt_rosters as (
    select
      document.id,
      jsonb_agg(
        case
          when mapping.resource_id is null then roster.value
          else jsonb_set(
            roster.value,
            '{name}',
            to_jsonb(mapping.anonymous_name),
            true
          )
        end
        order by roster.ordinality
      ) as students
    from public.document_issue document
    cross join lateral jsonb_array_elements(document.students)
      with ordinality as roster(value, ordinality)
    left join pg_temp.graduate_name_map mapping
      on roster.value ->> 'resource_id' = mapping.resource_id::text
      or lower(roster.value ->> 'code') = lower(mapping.student_code)
    where exists (
      select 1
      from jsonb_array_elements(document.students) candidate
      join pg_temp.graduate_name_map graduate
        on candidate ->> 'resource_id' = graduate.resource_id::text
        or lower(candidate ->> 'code') = lower(graduate.student_code)
    )
    group by document.id
  )
  update public.document_issue document
  set students = rebuilt.students
  from rebuilt_rosters rebuilt
  where document.id = rebuilt.id;

  -- Roster names are mapped by resource ID/student code. If a free-text form
  -- contains a duplicated real name, replace it with all matching aliases so
  -- the real name is still removed without choosing the wrong student.
  with document_name_groups as (
    select
      document.id,
      mapping.real_name,
      string_agg(
        distinct mapping.anonymous_name,
        '·'
        order by mapping.anonymous_name
      ) as anonymous_name
    from public.document_issue document
    cross join lateral jsonb_array_elements(document.students) roster
    join pg_temp.graduate_name_map mapping
      on roster ->> 'resource_id' = mapping.resource_id::text
      or lower(roster ->> 'code') = lower(mapping.student_code)
    group by document.id, mapping.real_name
  ),
  document_mappings as (
    select
      mapping.id,
      jsonb_agg(
        jsonb_build_object(
          'old_name', mapping.real_name,
          'anonymous_name', mapping.anonymous_name
        )
      ) as mapping
    from document_name_groups mapping
    group by mapping.id
  )
  update public.document_issue document
  set form_data = graduate_privacy_private.replace_names_in_jsonb(
    document.form_data,
    document_mappings.mapping
  )
  from document_mappings
  where document.id = document_mappings.id;

  update public.profiles profile
  set
    name = mapping.anonymous_name,
    nickname = case
      when profile.nickname is null then null
      else replace(profile.nickname, mapping.real_name, mapping.anonymous_name)
    end,
    updated_at = now()
  from pg_temp.graduate_user_map mapping
  where profile.id = mapping.user_id;

  update auth.users auth_user
  set
    raw_user_meta_data = jsonb_set(
      jsonb_set(
        graduate_privacy_private.replace_names_in_jsonb(
          coalesce(auth_user.raw_user_meta_data, '{}'::jsonb),
          jsonb_build_array(jsonb_build_object(
            'old_name', mapping.real_name,
            'anonymous_name', mapping.anonymous_name
          ))
        ) - 'picture' - 'avatar_url' - 'grade' - 'birthday',
        '{name}',
        to_jsonb(mapping.anonymous_name),
        true
      ),
      '{full_name}',
      to_jsonb(mapping.anonymous_name),
      true
    ),
    banned_until = '2999-12-31 23:59:59+00'::timestamptz,
    updated_at = now()
  from pg_temp.graduate_user_map mapping
  where auth_user.id = mapping.user_id;

  update auth.identities identity
  set identity_data = jsonb_set(
    jsonb_set(
      graduate_privacy_private.replace_names_in_jsonb(
        coalesce(identity.identity_data, '{}'::jsonb),
        jsonb_build_array(jsonb_build_object(
          'old_name', mapping.real_name,
          'anonymous_name', mapping.anonymous_name
        ))
      ) - 'picture' - 'avatar_url' - 'grade' - 'birthday',
      '{name}',
      to_jsonb(mapping.anonymous_name),
      true
    ),
    '{full_name}',
    to_jsonb(mapping.anonymous_name),
    true
  )
  from pg_temp.graduate_user_map mapping
  where identity.user_id = mapping.user_id;

  update public.youtube_profiles youtube
  set
    display_name = mapping.anonymous_name,
    avatar_url = null,
    updated_at = now()
  from pg_temp.graduate_user_map mapping
  where youtube.id = mapping.user_id;

  update public.problems problem
  set author_nickname = mapping.anonymous_name
  from pg_temp.graduate_user_map mapping
  where problem.user_id = mapping.user_id;

  update public.problem_solutions solution
  set author_nickname = mapping.anonymous_name
  from pg_temp.graduate_user_map mapping
  where solution.user_id = mapping.user_id;

  update public.course_selection_audit_log audit
  set actor_name = mapping.anonymous_name
  from pg_temp.graduate_user_map mapping
  where audit.actor_id = mapping.user_id;

  update auth.audit_log_entries audit
  set payload = graduate_privacy_private.replace_names_in_jsonb(
    audit.payload::jsonb,
    jsonb_build_array(jsonb_build_object(
      'old_name', mapping.real_name,
      'anonymous_name', mapping.anonymous_name
    ))
  )::json
  from pg_temp.graduate_user_map mapping
  where audit.payload ->> 'actor_id' = mapping.user_id::text;

  delete from auth.refresh_tokens refresh_token
  using pg_temp.graduate_user_map mapping
  where refresh_token.user_id = mapping.user_id::text;

  delete from auth.sessions session
  using pg_temp.graduate_user_map mapping
  where session.user_id = mapping.user_id;

  update public.resource resource
  set
    name = mapping.anonymous_name,
    status = 'graduated',
    meta = graduate_privacy_private.replace_names_in_jsonb(
      coalesce(resource.meta, '{}'::jsonb),
      jsonb_build_array(jsonb_build_object(
        'old_name', mapping.real_name,
        'anonymous_name', mapping.anonymous_name
      ))
    ) - 'grade' - 'picture' - 'birthday',
    updated_at = now()
  from pg_temp.graduate_name_map mapping
  where resource.id = mapping.resource_id;

  if exists (
    select 1
    from public.resource resource
    join pg_temp.graduate_name_map mapping on resource.id = mapping.resource_id
    where resource.status <> 'graduated'
       or resource.name <> mapping.anonymous_name
       or coalesce(resource.meta, '{}'::jsonb)
          ?| array['grade', 'picture', 'birthday']
       or position(mapping.real_name in resource.meta::text) > 0
  ) then
    raise exception 'Graduate resource anonymization verification failed';
  end if;

  if exists (
    select 1
    from public.student_basic_info student
    join pg_temp.graduate_name_map mapping
      on lower(student.id) = lower(mapping.student_code)
    where student.name <> mapping.anonymous_name
       or student.grade is not null
       or student.class_num is not null
       or student.number is not null
       or position(
         mapping.real_name in concat_ws(
           ' ',
           student.section1_personal_info::text,
           student.grade_info::text,
           student.attendance::text,
           student.volunteer::text,
           student.reading::text,
           student.academic_development::text,
           student.mock_result::text,
           student.mock_marking::text
         )
       ) > 0
  ) then
    raise exception 'Graduate student record anonymization verification failed';
  end if;

  if exists (
    select 1
    from public.document_issue document
    cross join lateral jsonb_array_elements(document.students) roster
    join pg_temp.graduate_name_map mapping
      on roster ->> 'resource_id' = mapping.resource_id::text
      or lower(roster ->> 'code') = lower(mapping.student_code)
    where roster ->> 'name' <> mapping.anonymous_name
       or position(mapping.real_name in coalesce(document.form_data::text, '')) > 0
  ) then
    raise exception 'Graduate document anonymization verification failed';
  end if;

  if exists (
    select 1
    from auth.users auth_user
    join pg_temp.graduate_user_map mapping on auth_user.id = mapping.user_id
    where auth_user.raw_user_meta_data ->> 'name' <> mapping.anonymous_name
       or auth_user.raw_user_meta_data ->> 'full_name' <> mapping.anonymous_name
       or auth_user.raw_user_meta_data
          ?| array['picture', 'avatar_url', 'grade', 'birthday']
       or auth_user.banned_until is null
       or auth_user.banned_until <= now()
  ) then
    raise exception 'Graduate account anonymization verification failed';
  end if;

  if exists (
    select 1
    from auth.sessions session
    join pg_temp.graduate_user_map mapping on session.user_id = mapping.user_id
  ) or exists (
    select 1
    from auth.refresh_tokens refresh_token
    join pg_temp.graduate_user_map mapping
      on refresh_token.user_id = mapping.user_id::text
  ) then
    raise exception 'Graduate account session revocation verification failed';
  end if;

  return jsonb_build_object(
    'admission_year', p_admission_year,
    'processed_students', student_count,
    'blocked_accounts', account_count
  );
end;
$_$;


ALTER FUNCTION "public"."process_graduated_student_cohort"("p_admission_year" integer, "p_expected_mapping" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_graduated_student_cohort"("p_admission_year" integer, "p_expected_mapping" "jsonb") IS 'Admin-only atomic graduation workflow. Verifies the downloaded alias preview, anonymizes dependent data, removes current personal metadata, bans matching Auth accounts, and revokes sessions.';



CREATE OR REPLACE FUNCTION "public"."protect_attendance_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_staff boolean;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM profiles WHERE id = auth.uid() AND role IN ('teacher', 'admin')
  ) INTO v_is_staff;

  IF v_is_staff THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.is_attended IS TRUE
       OR NEW.attendance_status IS NOT NULL
       OR NEW.attended_at IS NOT NULL
       OR NEW.checked_by IS NOT NULL THEN
      RAISE EXCEPTION '출석 정보는 학생이 직접 설정할 수 없습니다.';
    END IF;
    RETURN NEW;
  END IF;

  -- TG_OP = 'UPDATE'
  IF NEW.is_attended IS DISTINCT FROM OLD.is_attended
     OR NEW.attendance_status IS DISTINCT FROM OLD.attendance_status
     OR NEW.attended_at IS DISTINCT FROM OLD.attended_at
     OR NEW.checked_by IS DISTINCT FROM OLD.checked_by THEN
    RAISE EXCEPTION '출석 정보는 학생이 직접 수정할 수 없습니다.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."protect_attendance_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_profile_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_prefix text;
  v_has_student_resource boolean;
BEGIN
  -- 관리자는 제한 없이 변경 가능
  IF is_admin() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.role NOT IN ('student', 'teacher', 'staff') THEN
      RAISE EXCEPTION '허용되지 않은 role 값입니다: %', NEW.role;
    END IF;
    RETURN NEW;
  END IF;

  -- TG_OP = 'UPDATE': role 값이 그대로면 통과
  IF NEW.role IS NOT DISTINCT FROM OLD.role THEN
    RETURN NEW;
  END IF;

  -- 실제 학생(resource에 학생으로 등록된 계정)은 어떤 자가 전환도 불가
  v_user_prefix := split_part(NEW.email, '@', 1);
  SELECT EXISTS(
    SELECT 1 FROM resource
    WHERE type = 'student'
      AND (meta->>'id' = v_user_prefix OR meta->>'studentId' = v_user_prefix)
  ) INTO v_has_student_resource;

  -- 기존 허용: 이메일은 교사인데 role이 student로 잘못 등록된 경우의 자가 교정
  IF OLD.role = 'student' AND NEW.role = 'teacher' AND NOT v_has_student_resource THEN
    RETURN NEW;
  END IF;

  -- 신규 허용(2026-08-14): 연결된 resource.type과 role을 일치시키는 전환.
  -- resource 종류명과 role 값이 같아서(teacher/staff) 그대로 비교한다.
  -- 링크가 실재해야 하므로 클라이언트가 임의로 role을 올릴 수 없다.
  IF NEW.role IN ('teacher', 'staff')
     AND NOT v_has_student_resource
     AND EXISTS (
       SELECT 1
       FROM user_resource ur
       JOIN resource r ON r.id = ur.resource_id
       WHERE ur.user_id = NEW.id
         AND r.type = NEW.role
     )
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'role 컬럼은 본인이 변경할 수 없습니다.';
END;
$$;


ALTER FUNCTION "public"."protect_profile_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_derive_request_status"("p_item_status" "jsonb", "p_fallback" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  WITH s AS (
    SELECT value->>'status' AS st
    FROM jsonb_each(coalesce(p_item_status, '{}'::jsonb))
  )
  SELECT CASE
    WHEN (SELECT count(*) FROM s) = 0 THEN p_fallback
    WHEN (SELECT count(DISTINCT st) FROM s) = 1 THEN (SELECT min(st) FROM s)
    WHEN EXISTS (SELECT 1 FROM s WHERE st IN ('submitted', 'pending')) THEN 'pending'
    WHEN NOT EXISTS (SELECT 1 FROM s WHERE st NOT IN ('completed', 'rejected')) THEN 'completed'
    ELSE 'approved'
  END;
$$;


ALTER FUNCTION "public"."purchase_derive_request_status"("p_item_status" "jsonb", "p_fallback" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_order_line_fill_page"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  select b.page_id into new.page_id
    from public.purchase_order_batches b
   where b.id = new.batch_id;
  if new.page_id is null then
    raise exception '품의 차수를 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."purchase_order_line_fill_page"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_order_line_item_fill_page"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request_page uuid;
begin
  select l.page_id into new.page_id
    from public.purchase_order_lines l
   where l.id = new.line_id;
  if new.page_id is null then
    raise exception '품의 품목을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;

  -- 신청 표를 RLS 없이 읽어야 하는데 이 함수는 INVOKER 다. 다만 연결을 쓸 수 있는 사람은
  -- 곧 그 페이지의 매니저이고, 매니저는 RLS 로 그 페이지 신청을 모두 읽는다.
  select r.page_id into v_request_page
    from public.purchase_requests r
   where r.id = new.request_id;
  if v_request_page is distinct from new.page_id then
    raise exception '다른 신청 페이지의 품목은 연결할 수 없습니다.' using errcode = '22023';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."purchase_order_line_item_fill_page"() OWNER TO "postgres";


