CREATE OR REPLACE FUNCTION "public"."purge_ai_call_log"("p_keep_days" integer DEFAULT 90) RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with gone as (
    delete from public.ai_call_log
    where created_at < now() - make_interval(days => greatest(p_keep_days, 7))
    returning 1
  )
  select coalesce(count(*), 0)::integer from gone;
$$;


