CREATE OR REPLACE FUNCTION "public"."push_record"("p_notification" "uuid", "p_kind" "text", "p_results" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r jsonb; n integer := 0;
begin
  for r in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    insert into public.push_delivery_log(notification_id, user_id, subscription_id, kind, status, detail)
      values (p_notification, (r->>'user_id')::uuid, (r->>'subscription_id')::uuid, p_kind, r->>'status', left(r->>'detail', 300));
    if r->>'status' = 'gone' then
      delete from public.push_subscriptions where id = (r->>'subscription_id')::uuid;
    elsif r->>'status' = 'sent' then
      update public.push_subscriptions set last_success_at = now(), fail_count = 0 where id = (r->>'subscription_id')::uuid;
    else
      -- 계속 실패하는 구독(만료 신호를 410 으로 주지 않는 서비스)은 20번째에 정리한다
      update public.push_subscriptions set fail_count = fail_count + 1 where id = (r->>'subscription_id')::uuid;
      delete from public.push_subscriptions where id = (r->>'subscription_id')::uuid and fail_count >= 20;
    end if;
    n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."push_record"("p_notification" "uuid", "p_kind" "text", "p_results" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_subscribe"("p_endpoint" "text", "p_p256dh" "text", "p_auth" "text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := auth.uid();
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;
  insert into public.push_subscriptions(user_id, endpoint, p256dh, auth, user_agent)
    values (u, p_endpoint, p_p256dh, p_auth, left(p_user_agent, 300))
  on conflict (endpoint) do update
    set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth,
        user_agent = excluded.user_agent, fail_count = 0, created_at = now();
  delete from public.push_subscriptions
   where user_id = u and id not in (
     select id from public.push_subscriptions where user_id = u order by created_at desc limit 10);
  return jsonb_build_object('ok', true, 'count', (select count(*) from public.push_subscriptions where user_id = u));
end $$;


ALTER FUNCTION "public"."push_subscribe"("p_endpoint" "text", "p_p256dh" "text", "p_auth" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."push_targets"("p_notification" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  n public.notification_events;
  u uuid;
  day0 timestamptz := push_private.kst_day_start(now());
  sent_today integer;
  calls_today integer;
  invites_today integer;
  out_subs jsonb := '[]'::jsonb;
begin
  select * into n from public.notification_events where id = p_notification;
  if n.id is null or n.type = 'coolmessenger' then return jsonb_build_object('subs', out_subs); end if;
  -- 같은 알림을 두 번 보내지 않는다(트리거 재시도 · 수동 재호출)
  if exists (select 1 from public.push_delivery_log where notification_id = n.id) then
    return jsonb_build_object('subs', out_subs, 'duplicate', true);
  end if;

  for u in select distinct x from push_private.users_of_resource(n.resource_id) x
            where exists (select 1 from public.push_subscriptions s where s.user_id = x) loop
    if push_private.is_quiet(now()) then
      insert into public.push_delivery_log(notification_id, user_id, kind, status) values (n.id, u, n.type, 'skipped_quiet');
      continue;
    end if;
    select count(*) filter (where status = 'sent'),
           count(*) filter (where status = 'sent' and kind = 'tama_call'),
           count(*) filter (where status = 'sent' and kind = 'tama_focus_invite')
      into sent_today, calls_today, invites_today
      from (select distinct on (notification_id) notification_id, kind, status
              from public.push_delivery_log where user_id = u and created_at >= day0
             order by notification_id, (status = 'sent') desc) d;
    if sent_today >= 8
       or (n.type = 'tama_call' and calls_today >= 3)
       or (n.type = 'tama_focus_invite' and invites_today >= 3) then
      insert into public.push_delivery_log(notification_id, user_id, kind, status) values (n.id, u, n.type, 'skipped_budget');
      continue;
    end if;
    out_subs := out_subs || coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'user_id', s.user_id, 'endpoint', s.endpoint,
                                          'keys', jsonb_build_object('p256dh', s.p256dh, 'auth', s.auth)))
        from public.push_subscriptions s where s.user_id = u), '[]'::jsonb);
  end loop;

  return jsonb_build_object(
    'subs', out_subs,
    'notification', jsonb_build_object('id', n.id, 'type', n.type,
      'title', left(coalesce(nullif(n.title, ''), '새 알림'), 80),
      'body', left(coalesce(n.message, ''), 240))
  );
end $$;


ALTER FUNCTION "public"."push_targets"("p_notification" "uuid") OWNER TO "postgres";


