CREATE OR REPLACE FUNCTION "public"."ranch_save"("p_version" integer, "p_state" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := ranch_private.actor(); r public.ranch_state; shards_ bigint; allowed bigint;
begin
  if p_state is null or jsonb_typeof(p_state) <> 'object' or octet_length(p_state::text) > 48000 then
    raise exception '목장 저장 형식이 올바르지 않아요.' using errcode = '22023';
  end if;
  begin shards_ := (p_state->>'shards')::bigint; exception when others then shards_ := null; end;
  if shards_ is null or shards_ < 0 or shards_ > 2000000000 then raise exception '틈새 조각 수가 올바르지 않아요.' using errcode = '22023'; end if;
  select * into r from public.ranch_state where owner = u for update;
  if r.owner is null then
    if coalesce(p_version, 0) <> 0 then
      return jsonb_build_object('conflict', true, 'ranch', null, 'server_now', now());
    end if;
    if shards_ > 50000 then
      return jsonb_build_object('conflict', true, 'rejected', '틈새 조각이 너무 많아요. 처음부터 다시 시작해요.', 'ranch', null, 'server_now', now());
    end if;
    insert into public.ranch_state(owner, state, version, shards) values (u, p_state, 1, shards_);
    return jsonb_build_object('conflict', false, 'version', 1, 'server_now', now());
  end if;
  if p_version is distinct from r.version then
    return jsonb_build_object('conflict', true, 'ranch', ranch_private.row_json(r), 'server_now', now());
  end if;
  allowed := r.shards + 50000 + least(1000000, floor(extract(epoch from now() - r.saved_at) / 60))::bigint * 50000;
  if shards_ > allowed then
    return jsonb_build_object('conflict', true, 'rejected', '틈새 조각이 너무 빨리 늘었어요. 서버의 목장을 불러왔어요.',
                              'ranch', ranch_private.row_json(r), 'server_now', now());
  end if;
  update public.ranch_state set state = p_state, shards = shards_, version = version + 1, saved_at = now()
   where owner = u returning * into r;
  return jsonb_build_object('conflict', false, 'version', r.version, 'server_now', now());
end $$;


ALTER FUNCTION "public"."ranch_save"("p_version" integer, "p_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ranch_sell_shards"("p_times" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := ranch_private.actor(); r public.ranch_state; unit_ int; left_ int; got int;
begin
  if exists (select 1 from public.profiles where id = u and role = 'admin') then
    raise exception '관리자 계정은 조각을 코인으로 바꾸지 않아요(시험 값이 섞이지 않게).' using errcode = '42501';
  end if;
  if ranch_private.in_class(u) then raise exception '수업 중에는 바꿀 수 없어요. 쉬는 시간에 해요.' using errcode = 'P0001'; end if;
  if p_times is null or p_times < 1 or p_times > 100 then raise exception '바꿀 수가 올바르지 않아요.' using errcode = '22023'; end if;
  unit_ := economy_private.num('ranch.shards_per_coin');
  left_ := (ranch_private.today_info(u)->>'coins_left')::int;
  if p_times > left_ then raise exception '오늘은 % 코인까지 더 바꿀 수 있어요.', left_ using errcode = 'P0001'; end if;
  select * into r from public.ranch_state where owner = u for update;          -- 게임 줄 먼저, 지갑은 마지막
  if r.owner is null or r.shards < p_times * unit_ then raise exception '틈새 조각이 모자라요.' using errcode = 'P0001'; end if;
  update public.ranch_state
     set shards = shards - p_times * unit_, version = version + 1, saved_at = now(),
         state = jsonb_set(state, '{shards}', to_jsonb(r.shards - p_times * unit_))
   where owner = u returning * into r;
  got := wallet_private.apply(u, p_times, 'ranch_shard_sale', 'ranch', gen_random_uuid()::text, false, format('틈새 조각 %s개', p_times * unit_));
  return jsonb_build_object('coins', got, 'ranch', ranch_private.row_json(r), 'today', ranch_private.today_info(u), 'server_now', now());
end $$;


ALTER FUNCTION "public"."ranch_sell_shards"("p_times" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ranch_study_gifts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := ranch_private.actor(); d date := ranch_private.today(); granted jsonb := '{}'; k text; ok boolean;
begin
  foreach k in array array['lunch', 'seed', 'egg'] loop
    ok := case k
      when 'lunch' then exists (select 1 from public.wallet_ledger where user_id = u and kind = 'seaton_attendance' and delta > 0 and earned_on = d)
      when 'seed' then exists (select 1 from public.academy_planning_rewards where user_id = u and reward_date = d)
      when 'egg' then exists (select 1 from public.tower_focus where owner = u and outcome = 'completed'
                                and (ended_at at time zone 'Asia/Seoul')::date = d)
    end;
    if ok then
      insert into public.ranch_gift(owner, gift_on, kind) values (u, d, k) on conflict do nothing;
      if found then granted := granted || jsonb_build_object(k, 1); end if;
    end if;
  end loop;
  return jsonb_build_object('granted', granted, 'server_now', now());
end $$;


ALTER FUNCTION "public"."ranch_study_gifts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_ai_suggestion_decision"("p_id" "uuid", "p_item" "text", "p_decision" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v jsonb;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  if p_decision not in ('applied', 'dismissed', 'copied') then
    raise exception '알 수 없는 결정입니다: %', p_decision using errcode = '22023';
  end if;
  update public.task_ai_suggestion
     set decisions = coalesce(decisions, '{}'::jsonb) || jsonb_build_object(left(p_item, 40), p_decision),
         updated_at = now()
   where id = p_id and created_by = auth.uid()
  returning decisions into v;
  return v;
end;
$$;


