    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (OLD.items IS DISTINCT FROM NEW.items)
     OR (OLD.status IS DISTINCT FROM NEW.status)
     OR (OLD.meta IS DISTINCT FROM NEW.meta) THEN
    INSERT INTO purchase_request_history (request_id, page_id, requester_id, items, status, status_reason, meta, snapshot_at)
    VALUES (OLD.id, OLD.page_id, OLD.requester_id, OLD.items, OLD.status, OLD.status_reason, OLD.meta, OLD.updated_at);
  END IF;
  RETURN NEW;
END;
$$;


