CREATE OR REPLACE FUNCTION "public"."record_student_audience_rule"("p_rule" "jsonb", "p_rule_key" "text", "p_label" "text", "p_sentence" "text" DEFAULT NULL::"text", "p_pin" boolean DEFAULT false, "p_target" "text" DEFAULT 'student'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_target text := coalesce(p_target, 'student');
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  -- 시각은 clock_timestamp() — now() 는 트랜잭션 시작 시각이라 정리 순서가 정해지지 않는다
  insert into public.student_audience_saved_rule as s (user_id, target, rule, rule_key, label, sentence, pinned, last_used_at)
  values (auth.uid(), v_target, p_rule, p_rule_key, left(p_label, 500), nullif(left(coalesce(p_sentence, ''), 500), ''), coalesce(p_pin, false), clock_timestamp())
  on conflict (user_id, target, rule_key) do update
     set rule = excluded.rule,
         label = excluded.label,
         sentence = coalesce(excluded.sentence, s.sentence),
         pinned = s.pinned or excluded.pinned,
         use_count = s.use_count + 1,
         last_used_at = clock_timestamp()
  returning id into v_id;

  -- 별표 없는 행은 대상(학생/교사)마다 최근 8개만
  delete from public.student_audience_saved_rule d
  where d.user_id = auth.uid() and d.target = v_target and not d.pinned
    and d.id not in (
      select k.id from public.student_audience_saved_rule k
      where k.user_id = auth.uid() and k.target = v_target and not k.pinned
      order by k.last_used_at desc
      limit 8);
  return v_id;
end;
$$;


ALTER FUNCTION "public"."record_student_audience_rule"("p_rule" "jsonb", "p_rule_key" "text", "p_label" "text", "p_sentence" "text", "p_pin" boolean, "p_target" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_student_audience_rule"("p_rule" "jsonb", "p_rule_key" "text", "p_label" "text", "p_sentence" "text", "p_pin" boolean, "p_target" "text") IS '조건 사용 기록 — 같은 (대상, 규칙)이면 횟수·시각 갱신, 별표 없는 행은 대상마다 최근 8개만. INVOKER(RLS 적용).';



CREATE OR REPLACE FUNCTION "public"."refresh_admin_dashboard_datasets"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_snap public.admin_dashboard_snapshot;
begin
  if not public.is_admin() then
    raise exception '관리자만 실행할 수 있습니다.' using errcode = '42501';
  end if;
  -- 연달아 누르면 매번 5초 가까이 DB 를 훑는다 — 1분 안이면 방금 값을 돌려준다
  select * into v_snap from public.admin_dashboard_snapshot where id = 1;
  if found and v_snap.generated_at > now() - interval '1 minute' then
    return to_jsonb(v_snap) || jsonb_build_object('throttled', true);
  end if;
  -- 8초 statement_timeout 안 — 종전과 같은 예산·상한(20260903105347 참고)
  return public.admin_dashboard_snapshot_save('manual', 3500, 20) || jsonb_build_object('throttled', false);
end;
$$;


ALTER FUNCTION "public"."refresh_admin_dashboard_datasets"() OWNER TO "postgres";


