CREATE OR REPLACE FUNCTION "public"."remind_collect_pending"("p_action_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.collect_request;
  v_cfg jsonb;
  v_ids uuid[];
begin
  if auth.uid() is null or not public.can_manage_collect(p_action_id) then
    raise exception '작업을 만든 사람과 업무 책임자만 다시 알릴 수 있습니다' using errcode = '42501';
  end if;
  select * into v_req from public.collect_request where action_id = p_action_id;
  if not found or v_req.status <> 'open' then raise exception '열려 있는 요청이 아닙니다' using errcode = '22023'; end if;

  if v_req.kind <> 'input' then
    select array_agg(distinct t.resource_id) into v_ids
    from public.collect_target t
    where t.action_id = p_action_id and t.removed_at is null and t.resource_id is not null
      and public.submission_target_pending(p_action_id, t.resource_id);
    return public.collect_notify(p_action_id, v_ids, 'reminder');
  end if;

  select config->'collect' into v_cfg from public.task_action where id = p_action_id;
  select array_agg(distinct t.resource_id) into v_ids
  from public.collect_target t
  cross join lateral (
    select coalesce(d.value->>'key', '') dim
    from jsonb_array_elements(case when jsonb_array_length(coalesce(v_cfg->'dimensions', '[]'::jsonb)) = 0
                                   then '[{"key":""}]'::jsonb else v_cfg->'dimensions' end) d
  ) dims
  where t.action_id = p_action_id and t.removed_at is null and t.resource_id is not null
    and not exists (
      select 1 from public.collect_response r
      where r.action_id = p_action_id and r.unit_key = t.unit_key and r.dimension_key = dims.dim
        and r.owner_key = case when v_req.answer_mode = 'shared' then '' else t.resource_id::text end
        and public.collect_cell_complete(r."values", v_cfg->'fields'));

  return public.collect_notify(p_action_id, v_ids, 'reminder');
end;
$$;


ALTER FUNCTION "public"."remind_collect_pending"("p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_assignees_meta"("p_task_id" "uuid", "p_assignee_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    current_meta JSONB;
    current_assignees JSONB;
    updated_assignees JSONB;
    assignee JSONB;
BEGIN
    SELECT meta INTO current_meta FROM task WHERE id = p_task_id;
    IF current_meta IS NULL THEN RAISE EXCEPTION 'Task not found: %', p_task_id; END IF;

    current_assignees := current_meta->'assignees';
    IF current_assignees IS NULL THEN RAISE EXCEPTION 'No assignees found for task: %', p_task_id; END IF;

    updated_assignees := '[]'::JSONB;
    FOR assignee IN SELECT * FROM jsonb_array_elements(current_assignees)
    LOOP
        IF (assignee->>'id')::UUID != ALL(p_assignee_ids) THEN
            updated_assignees := updated_assignees || assignee;
        END IF;
    END LOOP;

    UPDATE task SET meta = jsonb_set(current_meta, '{assignees}', updated_assignees), updated_at = NOW() WHERE id = p_task_id;
END;
$$;


ALTER FUNCTION "public"."remove_assignees_meta"("p_task_id" "uuid", "p_assignee_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."remove_assignees_meta"("p_task_id" "uuid", "p_assignee_ids" "uuid"[]) IS 'Remove assignees from task.meta.assignees';



CREATE OR REPLACE FUNCTION "public"."report_task_assignment_issue"("p_task_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare actor uuid := public.current_actor_resource_id(); t_meta jsonb; issues jsonb;
begin
  if auth.uid() is null or actor is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  select meta into t_meta from public.task where id = p_task_id for update;
  if not found or not public.is_task_assignee(p_task_id, actor) then raise exception '배정된 담당자만 표시할 수 있습니다.' using errcode = '42501'; end if;
  if p_reason is not null and length(btrim(p_reason)) not between 1 and 500 then raise exception '사유는 1~500자로 입력해 주세요.' using errcode = '22023'; end if;
  issues := coalesce(t_meta->'assignmentIssues', '{}'::jsonb);
  if p_reason is null then issues := issues - actor::text;
  else issues := issues || jsonb_build_object(actor::text, jsonb_build_object('reason', btrim(p_reason), 'reportedAt', clock_timestamp())); end if;
  update public.task set meta = jsonb_set(coalesce(meta, '{}'), '{assignmentIssues}', issues) where id = p_task_id;
end;
$$;


ALTER FUNCTION "public"."report_task_assignment_issue"("p_task_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_cfg_of"("p_type" "text", "p_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case when p_type = 'collect.input' then coalesce(p_config->'collect', '{}'::jsonb)
              else public.submit_cfg_of(p_config) end;
$$;


ALTER FUNCTION "public"."request_cfg_of"("p_type" "text", "p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_kind_of"("p_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case p_type
    when 'collect.input' then 'input'
    when 'submit.file' then 'file'
    when 'submit.document' then 'document'
    when 'submit.physical' then 'physical'
  end;
$$;


