CREATE OR REPLACE FUNCTION "public"."request_supervision_swap"("p_my_meeting" "uuid", "p_partner" "uuid", "p_partner_meeting" "uuid" DEFAULT NULL::"uuid", "p_message" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_me_id uuid;
  v_me_name text;
  v_partner_name text;
  v_mine meeting%rowtype;
  v_theirs meeting%rowtype;
  v_grade int;
  v_id uuid;
  v_slot_label text;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  if not coalesce(public.is_staff_teacher_or_admin(auth.uid()), false) then
    raise exception '교직원만 신청할 수 있습니다' using errcode = '42501';
  end if;

  select m.* into v_mine from meeting m where m.id = p_my_meeting;
  if not found or v_mine.kind <> 'duty' or jsonb_typeof(v_mine.meta -> 'supervision') <> 'object' then
    raise exception '자습 감독 일정이 아닙니다' using errcode = '22023';
  end if;
  if v_mine.starts_at <= now() then
    raise exception '이미 지난 감독은 교체할 수 없습니다' using errcode = '22023';
  end if;
  v_grade := (v_mine.meta -> 'supervision' ->> 'grade')::int;

  -- 나 = 그 감독의 담당자(이름으로 저장돼 있다)
  select r.id, r.name into v_me_id, v_me_name
  from resource r
  where r.id in (select public.current_actor_resource_ids())
    and r.name = any (public.supervision_assignee_names(v_mine.meta))
  limit 1;
  if v_me_id is null then
    raise exception '내가 맡은 감독만 교체를 신청할 수 있습니다' using errcode = '42501';
  end if;

  select r.name into v_partner_name from resource r where r.id = p_partner and r.type in ('teacher', 'staff');
  if v_partner_name is null or p_partner = v_me_id then
    raise exception '교체할 선생님을 찾을 수 없습니다' using errcode = '22023';
  end if;
  if v_partner_name = any (public.supervision_assignee_names(v_mine.meta)) then
    raise exception '그 선생님은 이미 이 감독을 맡고 있습니다' using errcode = '22023';
  end if;

  if p_partner_meeting is not null then
    select m.* into v_theirs from meeting m where m.id = p_partner_meeting;
    if not found or v_theirs.kind <> 'duty' or jsonb_typeof(v_theirs.meta -> 'supervision') <> 'object'
       or (v_theirs.meta -> 'supervision' ->> 'grade')::int <> v_grade then
      raise exception '같은 학년의 자습 감독과만 맞바꿀 수 있습니다' using errcode = '22023';
    end if;
    if v_theirs.starts_at <= now() then
      raise exception '이미 지난 감독과는 맞바꿀 수 없습니다' using errcode = '22023';
    end if;
    if not (v_partner_name = any (public.supervision_assignee_names(v_theirs.meta))) then
      raise exception '그 감독의 담당자가 아닙니다' using errcode = '22023';
    end if;
  end if;

  insert into supervision_swap_request (grade, requester_resource_id, partner_resource_id, requester_meeting_id, partner_meeting_id, message)
  values (v_grade, v_me_id, p_partner, p_my_meeting, p_partner_meeting, nullif(btrim(coalesce(p_message, '')), ''))
  returning id into v_id;

  v_slot_label := case v_mine.meta -> 'supervision' ->> 'slot' when 'morning' then '아침' when 'saturday' then '토요일' else '저녁' end;

  -- RETURNING 금지 — notification_events SELECT 정책은 받는 사람만이라 RETURNING 이 42501 로 전체를 되돌린다
  insert into notification_events (type, title, message, resource_id, meta, priority, is_read)
  values (
    'supervision_swap_requested',
    '자습 감독 교체 요청',
    format('%s 선생님이 %s %s 감독을 %s 요청했습니다.',
      v_me_name,
      to_char(v_mine.starts_at at time zone 'Asia/Seoul', 'FMMM/FMDD'),
      v_slot_label,
      case when p_partner_meeting is null then '대신 맡아 달라고' else
        format('%s 감독과 맞바꾸자고', to_char(v_theirs.starts_at at time zone 'Asia/Seoul', 'FMMM/FMDD')) end),
    p_partner,
    jsonb_build_object('swap_request_id', v_id, 'grade', v_grade),
    'medium',
    false
  );

  return v_id;
end;
$$;


ALTER FUNCTION "public"."request_supervision_swap"("p_my_meeting" "uuid", "p_partner" "uuid", "p_partner_meeting" "uuid", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rescue_log_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_entity_type text;
  v_entity_id   text;
  v_student     text;
  v_action      rescue_audit_action;
  v_actor_role  text;
BEGIN
  v_entity_type := TG_ARGV[0];

  -- determine action
  IF TG_OP = 'INSERT' THEN v_action := 'create';
  ELSIF TG_OP = 'UPDATE' THEN v_action := 'update';
  ELSE v_action := 'delete';
  END IF;

  -- determine entity id / student code per table
  IF v_entity_type = 'note' THEN
    v_entity_id := COALESCE(NEW.id::text, OLD.id::text);
    v_student   := COALESCE(NEW.student_code, OLD.student_code);
  ELSIF v_entity_type = 'tag' THEN
    v_entity_id := COALESCE(NEW.id::text, OLD.id::text);
    v_student   := COALESCE(NEW.student_code, OLD.student_code);
  ELSIF v_entity_type = 'scholarship' THEN
    v_entity_id := COALESCE(NEW.id::text, OLD.id::text);
    v_student   := COALESCE(NEW.student_code, OLD.student_code);
  ELSIF v_entity_type = 'status' THEN
    v_entity_id := COALESCE(NEW.student_code, OLD.student_code);
    v_student   := COALESCE(NEW.student_code, OLD.student_code);
  ELSIF v_entity_type = 'tag_definition' THEN
    v_entity_id := COALESCE(NEW.key, OLD.key);
    v_student   := NULL;
  END IF;

  -- skip audit when no authenticated session (e.g. migrations)
  IF auth.uid() IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- determine actor role
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin') THEN 'admin'
    WHEN current_rescue_role() IS NOT NULL THEN current_rescue_role()
    ELSE 'homeroom'
  END INTO v_actor_role;

  INSERT INTO rescue_audit_log (
    entity_type, entity_id, student_code, action,
    actor_id, actor_role, before_data, after_data
  ) VALUES (
    v_entity_type, v_entity_id, v_student, v_action,
    auth.uid(), v_actor_role,
    CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) ELSE NULL END
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."rescue_log_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rescue_log_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO rescue_status_history (student_code, from_status, to_status, changed_by, reason)
    VALUES (NEW.student_code, NULL, NEW.status, NEW.updated_by, NEW.reason);
  ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO rescue_status_history (student_code, from_status, to_status, changed_by, reason)
    VALUES (NEW.student_code, OLD.status, NEW.status, NEW.updated_by, NEW.reason);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."rescue_log_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_audience"("p_rule" "jsonb", "p_axis" "text" DEFAULT 'person'::"text", "p_academic_year" integer DEFAULT NULL::integer, "p_semester" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_year int := p_academic_year;
  v_sem  int := p_semester;
  v_ref  date;
  v_rows jsonb;
begin
  if auth.uid() is null or not public.is_staff_teacher_or_admin(auth.uid()) then
    raise exception '교직원만 대상을 계산할 수 있습니다' using errcode = '42501';
  end if;
  if p_axis not in ('person', 'subject', 'class', 'club', 'club_member') then
    raise exception '알 수 없는 축: %', p_axis using errcode = '22023';
  end if;
  if v_year is null or v_sem is null then
    select t.academic_year, t.semester into v_year, v_sem from public.current_academic_term() t;
  end if;
  v_ref := public.collect_ref_date(v_year);

  with
  inc as (select value c from jsonb_array_elements(
            case when jsonb_typeof(p_rule->'include') = 'array' then p_rule->'include' else '[]'::jsonb end)),
  exc as (select value c from jsonb_array_elements(
            case when jsonb_typeof(p_rule->'exclude') = 'array' then p_rule->'exclude' else '[]'::jsonb end)),
  inc_units as (select u.* from inc, lateral public.audience_unit_matches(inc.c, v_year, v_sem) u),
  exc_units as (select u.* from exc, lateral public.audience_unit_matches(exc.c, v_year, v_sem) u),
  inc_people as (
    select p.resource_id, p.holder_name, p.reason, false via_teaching
    from inc, lateral public.audience_person_matches(inc.c, v_year, v_sem, v_ref) p
    union all
    select u.resource_id, u.teacher_name, u.reason, true from inc_units u
  ),
  exc_people as (
    select p.resource_id, p.holder_name
    from exc, lateral public.audience_person_matches(exc.c, v_year, v_sem, v_ref) p
  ),
  people as (
    select coalesce(ip.resource_id::text, 'name:' || ip.holder_name) pkey,
           ip.resource_id,
           coalesce((select r.name from public.resource r where r.id = ip.resource_id), max(ip.holder_name)) name,
           array_agg(distinct ip.reason) reasons,
           bool_or(not ip.via_teaching) via_other
    from inc_people ip
    where not exists (
      select 1 from exc_people e
      where (ip.resource_id is not null and e.resource_id = ip.resource_id)
         or (ip.resource_id is null and e.resource_id is null and e.holder_name = ip.holder_name)
    )
    group by 1, 2
  ),
  -- 과목·학급 축의 수업 단위
  units_raw as (
    select u.resource_id, u.grade, u.subject_name, u.class_label
    from inc_units u
    join people p on p.resource_id = u.resource_id
    union
    select t.resource_id, t.grade, t.subject_name, t.class_label
    from public.audience_teaching_rows(v_year, v_sem) t
    join people p on p.resource_id = t.resource_id and p.via_other
  ),
  units as (
    select ur.* from units_raw ur
    where not exists (
      select 1 from exc_units e
      where e.resource_id is not distinct from ur.resource_id
        and e.grade = ur.grade and e.subject_name = ur.subject_name
        and (p_axis <> 'class' or e.class_label = ur.class_label)
    )
  ),
  unit_rows as (
    select distinct on (u.resource_id, k.unit_key)
      u.resource_id, k.unit_key, k.unit_label, u.grade, u.subject_name,
      case when p_axis = 'class' then u.class_label end class_label
    from units u,
    lateral (select
      case when p_axis = 'class'
           then u.grade || '|' || u.subject_name || '|' || u.class_label
           else u.grade || '|' || u.subject_name end unit_key,
      case when p_axis = 'class'
           then u.grade || '학년 ' || u.subject_name || ' · '
                || case when u.class_label ~ '^[0-9]+$' then u.class_label || '반' else u.class_label end
           else u.grade || '학년 ' || u.subject_name end unit_label) k
  ),
  -- 동아리 축(2026-11-11): 대상자가 지도하는 그 학년도 활동 중 동아리마다(club) · 그 동아리 확정 부원마다(club_member)
  club_units as (
    select a.teacher_resource_id resource_id, y.id club_year_id, y.name club_name
    from public.club_advisor a
    join public.club_year y on y.id = a.club_year_id and y.academic_year = v_year and y.status = 'active'
    join people p on p.resource_id = a.teacher_resource_id
    where p_axis in ('club', 'club_member')
  ),
  club_rows as (
    select cu.resource_id, 'club|' || cu.club_year_id unit_key, cu.club_name unit_label,
           null::int grade, cu.club_name subject, null::text class_label
    from club_units cu where p_axis = 'club'
    union all
    select cu.resource_id, 'club|' || cu.club_year_id || '|' || m.student_code,
           cu.club_name || ' · ' || concat_ws('-', m.grade, m.class_num, m.number) || coalesce(' ' || sr.name, ''),
           m.grade, cu.club_name, concat_ws('-', m.grade, lpad(m.class_num::text, 2, '0'), lpad(m.number::text, 2, '0'))
    from club_units cu
    join public.club_member m on m.club_year_id = cu.club_year_id and m.status = 'confirmed'
    left join public.resource sr on sr.id = m.student_resource_id
    where p_axis = 'club_member'
  ),
  out_rows as (
    -- 사람 축
    select p.resource_id, p.name, 'person'::text unit_key, ''::text unit_label,
           null::int grade, null::text subject, null::text class_label, p.reasons
    from people p where p_axis = 'person'
    union all
    -- 과목·학급 축
    select ur.resource_id, p.name, ur.unit_key, ur.unit_label, ur.grade, ur.subject_name, ur.class_label, p.reasons
    from unit_rows ur join people p on p.resource_id = ur.resource_id
    where p_axis in ('subject', 'class')
    union all
    select cr.resource_id, p.name, cr.unit_key, cr.unit_label, cr.grade, cr.subject, cr.class_label, p.reasons
    from club_rows cr join people p on p.resource_id = cr.resource_id
    union all
    -- 과목·학급 축인데 수업이 없는 사람 / 미연결 담당자.
    -- 수업이 아닌 조건(담임·분장…)으로 들어온 사람만 해당한다. 수업 조건으로만 들어왔는데 단위가
    -- 전부 제외된 사람은 명단에서 빠지는 게 맞다(예: "1학년 전원, 수학 제외"의 수학 전담 교사).
    select p.resource_id, p.name, null, '', null, null, null, p.reasons
    from people p
    where p_axis in ('subject', 'class')
      and (p.via_other or p.resource_id is null)
      and not exists (select 1 from unit_rows ur where ur.resource_id = p.resource_id)
    union all
    -- 동아리 축인데 지도하는 동아리(club_member 면 부원)가 없는 사람 — 미리보기가 «단위 없음»으로 알린다
    select p.resource_id, p.name, null, '', null, null, null, p.reasons
    from people p
    where p_axis in ('club', 'club_member')
      and not exists (select 1 from club_rows cr where cr.resource_id = p.resource_id)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'resource_id', o.resource_id, 'name', o.name, 'unit_key', o.unit_key,
           'unit_label', o.unit_label, 'grade', o.grade, 'subject', o.subject,
           'class_label', o.class_label, 'reasons', to_jsonb(o.reasons))
         order by o.grade nulls last, o.subject nulls last, o.class_label nulls last, o.name), '[]'::jsonb)
    into v_rows
  from out_rows o;

  return jsonb_build_object(
    'academic_year', v_year, 'semester', v_sem, 'ref_date', v_ref, 'axis', p_axis, 'rows', v_rows);
end;
$_$;


ALTER FUNCTION "public"."resolve_audience"("p_rule" "jsonb", "p_axis" "text", "p_academic_year" integer, "p_semester" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_audience"("p_rule" "jsonb", "p_axis" "text", "p_academic_year" integer, "p_semester" integer) IS '대상 규칙 해석(할 일 입력 받기). 규칙 = {include:[…], exclude:[…]}, 조건 type = people|all_faculty|teaching|homeroom|grade_head|department|seat|position|tag. 클라이언트 짝 = src/lib/audienceRule.ts.';



CREATE OR REPLACE FUNCTION "public"."resolve_faculty_rule"("p_rule" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_side   text;
  v_grp    jsonb;
  v_idx    bigint;
  v_crits  jsonb;
  v_crit   jsonb;
  v_res    jsonb;
  v_set    uuid[];
  v_ids    uuid[];
  v_inc    uuid[] := '{}';
  v_exc    uuid[] := '{}';
  v_r_ids  uuid[] := '{}';
  v_r_txt  text[] := '{}';
  v_cinfo  jsonb;
  v_groups jsonb := '[]'::jsonb;
  v_final  uuid[];
  v_rows   jsonb;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  if not public.is_staff_teacher_or_admin(auth.uid()) then
    raise exception '교직원만 조건으로 교직원을 고를 수 있습니다' using errcode = '42501';
  end if;
  if p_rule is null or jsonb_typeof(p_rule) <> 'object' then
    raise exception '규칙 형식이 아닙니다' using errcode = '22023';
  end if;

  foreach v_side in array array['include', 'exclude'] loop
    for v_grp, v_idx in
      select g.value, g.ord - 1
      from jsonb_array_elements(coalesce(p_rule->v_side, '[]'::jsonb)) with ordinality g(value, ord)
    loop
      v_crits := case
        when jsonb_typeof(v_grp->'all') = 'array' then v_grp->'all'
        when v_grp ? 'type' then jsonb_build_array(v_grp)
        else null end;
      if v_crits is null or jsonb_array_length(v_crits) = 0 then
        raise exception '비어 있는 조건 묶음이 있습니다' using errcode = '22023';
      end if;
      v_set := null;
      v_cinfo := '[]'::jsonb;
      for v_crit in select value from jsonb_array_elements(v_crits) loop
        if (v_crit->>'type') not in ('people', 'all_faculty', 'teaching', 'homeroom', 'grade_head',
                                     'department', 'seat', 'position', 'tag', 'club') then
          raise exception '알 수 없는 교직원 조건: %', coalesce(v_crit->>'type', '(없음)') using errcode = '22023';
        end if;
        -- 조건 하나 = resolve_audience 의 포함 조건 하나(사람 축). 분장표에만 있는 이름(resource_id 없음)은 고를 수 없어 뺀다.
        v_res := public.resolve_audience(jsonb_build_object('include', jsonb_build_array(v_crit), 'exclude', '[]'::jsonb), 'person', null, null);
        select coalesce(array_agg(distinct (r->>'resource_id')::uuid), '{}')
          into v_ids
        from jsonb_array_elements(v_res->'rows') r
        where r->>'resource_id' is not null;
        if v_side = 'include' then
          select v_r_ids || coalesce(array_agg((r->>'resource_id')::uuid), '{}'),
                 v_r_txt || coalesce(array_agg(x.reason), '{}')
            into v_r_ids, v_r_txt
          from jsonb_array_elements(v_res->'rows') r
          cross join lateral jsonb_array_elements_text(coalesce(r->'reasons', '[]'::jsonb)) x(reason)
          where r->>'resource_id' is not null;
        end if;
        v_cinfo := v_cinfo || jsonb_build_array(jsonb_build_object('type', v_crit->>'type', 'count', cardinality(v_ids)));
        v_set := case when v_set is null then v_ids
                      else array(select x from unnest(v_set) x where x = any (v_ids)) end;
      end loop;
      v_groups := v_groups || jsonb_build_array(jsonb_build_object(
        'side', v_side, 'index', v_idx, 'count', cardinality(v_set), 'criteria', v_cinfo));
      if v_side = 'include' then
        v_inc := array(select distinct x from unnest(v_inc || v_set) x);
      else
        v_exc := array(select distinct x from unnest(v_exc || v_set) x);
      end if;
    end loop;
  end loop;

  v_final := array(select x from unnest(v_inc) x where not (x = any (v_exc)));

  select coalesce(jsonb_agg(jsonb_build_object(
           'resource_id', r.id, 'name', r.name, 'type', r.type,
           'reasons', coalesce((
             select to_jsonb(array_agg(distinct t.txt))
             from unnest(v_r_ids, v_r_txt) t(id, txt) where t.id = r.id), '[]'::jsonb))
         order by r.name), '[]'::jsonb)
    into v_rows
  from public.resource r
  where r.id = any (v_final);

  return jsonb_build_object(
    'rows', v_rows, 'groups', v_groups,
    'included', cardinality(v_inc), 'excluded', cardinality(v_inc) - cardinality(v_final));
end;
$$;


ALTER FUNCTION "public"."resolve_faculty_rule"("p_rule" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_faculty_rule"("p_rule" "jsonb") IS '조건으로 교직원 고르기 — 규칙 {include:[{all:[조건…]}…], exclude} (묶음 안 AND · 묶음끼리 OR). 조건 하나의 의미는 resolve_audience(사람 축)를 그대로 쓴다. 교직원 전용.';



CREATE OR REPLACE FUNCTION "public"."resolve_profile_name"("p_email" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT r.name
  FROM public.resource r
  WHERE r.name IS NOT NULL
    AND (
      (r.type = 'student' AND r.meta->>'id' = split_part(p_email, '@', 1))
      OR (r.type IN ('teacher', 'staff') AND lower(r.meta->>'email') = lower(p_email))
    )
  ORDER BY (r.status = 'active') DESC NULLS LAST
  LIMIT 1;
$$;


ALTER FUNCTION "public"."resolve_profile_name"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_student_audience"("p_rule" "jsonb", "p_academic_year" integer DEFAULT NULL::integer, "p_semester" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_year    int := p_academic_year;
  v_sem     int := p_semester;
  v_side    text;
  v_grp     jsonb;
  v_idx     bigint;
  v_crits   jsonb;
  v_crit    jsonb;
  v_set     uuid[];
  v_ids     uuid[];
  v_all_ids uuid[];
  v_all_rs  text[];
  v_inc     uuid[] := '{}';
  v_exc     uuid[] := '{}';
  v_r_ids   uuid[] := '{}';
  v_r_txt   text[] := '{}';
  v_info    jsonb;
  v_cinfo   jsonb;
  v_groups  jsonb := '[]'::jsonb;
  v_final   uuid[];
  v_rows    jsonb;
  v_g       int;
  v_unknown jsonb;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;
  if not public.is_teacher_or_admin(auth.uid()) then
    raise exception '교사만 조건으로 학생을 고를 수 있습니다' using errcode = '42501';
  end if;
  if p_rule is null or jsonb_typeof(p_rule) <> 'object' then
    raise exception '규칙 형식이 아닙니다' using errcode = '22023';
  end if;
  if v_year is null or v_sem is null then
    select t.academic_year, t.semester into v_year, v_sem from public.current_academic_term() t;
  end if;

  foreach v_side in array array['include', 'exclude'] loop
    if p_rule ? v_side and jsonb_typeof(p_rule->v_side) <> 'array' then
      raise exception '% 는 배열이어야 합니다', v_side using errcode = '22023';
    end if;

    for v_grp, v_idx in
      select g.value, g.ord - 1
      from jsonb_array_elements(coalesce(p_rule->v_side, '[]'::jsonb)) with ordinality g(value, ord)
    loop
      v_crits := case
        when jsonb_typeof(v_grp->'all') = 'array' then v_grp->'all'
        when v_grp ? 'type' then jsonb_build_array(v_grp)
        else null end;
      if v_crits is null or jsonb_array_length(v_crits) = 0 then
        raise exception '비어 있는 조건 묶음이 있습니다' using errcode = '22023';
      end if;

      v_set := null;
      v_cinfo := '[]'::jsonb;
      for v_crit in select value from jsonb_array_elements(v_crits) loop
        select coalesce(array_agg(distinct m.resource_id), '{}'),
               coalesce(array_agg(m.resource_id), '{}'),
               coalesce(array_agg(m.reason), '{}')
          into v_ids, v_all_ids, v_all_rs
        from public.student_audience_matches(v_crit, v_year, v_sem) m;

        v_info := jsonb_build_object('type', v_crit->>'type', 'count', cardinality(v_ids));

        -- 기록 없음: 그 학년을 지났는데 snumN 이 없는 학생(전입생 등) — 오류 없이 빠지므로 따로 센다
        -- 끝난 학기 수강: 그 학기를 이미 지났는데 성적 기록이 없는 학생(전입·미적재) — 오류 없이 빠지므로 센다
        if v_crit->>'type' = 'past_course' then
          v_g := (v_crit->>'grade')::int;
          v_info := v_info || jsonb_build_object('no_record', (
            select count(*) from public.student_audience_pool() p
            where (p.grade > v_g
                   or (p.grade = v_g and v_sem = 2 and coalesce(v_crit->>'semester', '1') = '1'))
              and not exists (
                select 1 from public.student_academic_flat f
                where f.student_code = p.student_code and f.grade = v_g
                  and (v_crit->>'semester' is null or f.semester::text = v_crit->>'semester'))));
        end if;
        if v_crit->>'type' = 'past_class' then
          v_g := (v_crit->>'grade')::int;
          v_info := v_info || jsonb_build_object('no_record', (
            select count(*) from public.student_audience_pool() p
            where p.grade >= v_g and coalesce(p.meta->>('snum' || v_g), '') !~ '^[1-3][0-9]{4}$'));
        end if;

        -- 어휘에 없는 이름: 오타·표기 흔들림은 0명이 되는데 오류가 아니다 → 무엇이 없었는지 돌려준다
        if v_crit->>'type' = 'club' then
          select coalesce(jsonb_agg(n), '[]'::jsonb) into v_unknown
          from jsonb_array_elements_text(coalesce(v_crit->'names', '[]'::jsonb)) n
          where not exists (select 1 from public.club_info c
                            where c.academic_year = v_year and c.name = n
                              and coalesce(c.meta->>'status', 'active') = 'active');
          v_info := v_info || jsonb_build_object('unknown', v_unknown);
        elsif v_crit->>'type' = 'past_course' then
          select coalesce(jsonb_agg(n), '[]'::jsonb) into v_unknown
          from jsonb_array_elements_text(coalesce(v_crit->'subjects', '[]'::jsonb)) n
          where not exists (select 1 from public.student_academic_flat f where f.subject = n);
          v_info := v_info || jsonb_build_object('unknown', v_unknown);
        elsif v_crit->>'type' in ('course', 'slot', 'my_students', 'teacher_students') then
          select coalesce(jsonb_agg(n), '[]'::jsonb) into v_unknown
          from jsonb_array_elements_text(coalesce(v_crit->'subjects', '[]'::jsonb)) n
          where not exists (select 1 from public.student_timetable t
                            where t.academic_year = v_year and t.semester = v_sem and t.subject = n);
          v_info := v_info || jsonb_build_object('unknown', v_unknown);
        end if;

        v_cinfo := v_cinfo || jsonb_build_array(v_info);
        v_set := case when v_set is null then v_ids
                      else array(select x from unnest(v_set) x where x = any (v_ids)) end;
        if v_side = 'include' then
          v_r_ids := v_r_ids || v_all_ids;
          v_r_txt := v_r_txt || v_all_rs;
        end if;
      end loop;

      v_groups := v_groups || jsonb_build_array(jsonb_build_object(
        'side', v_side, 'index', v_idx, 'count', cardinality(v_set), 'criteria', v_cinfo));
      if v_side = 'include' then
        v_inc := array(select distinct x from unnest(v_inc || v_set) x);
      else
        v_exc := array(select distinct x from unnest(v_exc || v_set) x);
      end if;
    end loop;
  end loop;

  v_final := array(select x from unnest(v_inc) x where not (x = any (v_exc)));

  select coalesce(jsonb_agg(jsonb_build_object(
           'resource_id', p.resource_id, 'name', p.name, 'student_code', p.student_code,
           'grade', p.grade, 'class', p.class, 'number', p.number,
           'reasons', coalesce((
             select to_jsonb(array_agg(distinct r.txt))
             from unnest(v_r_ids, v_r_txt) r(id, txt)
             where r.id = p.resource_id), '[]'::jsonb))
         order by p.grade, p.class, p.number, p.name), '[]'::jsonb)
    into v_rows
  from public.student_audience_pool() p
  where p.resource_id = any (v_final);

  return jsonb_build_object(
    'academic_year', v_year,
    'semester', v_sem,
    'rows', v_rows,
    'groups', v_groups,
    'included', cardinality(v_inc),
    'excluded', cardinality(v_inc) - cardinality(v_final));
end;
$_$;


ALTER FUNCTION "public"."resolve_student_audience"("p_rule" "jsonb", "p_academic_year" integer, "p_semester" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_student_audience"("p_rule" "jsonb", "p_academic_year" integer, "p_semester" integer) IS '조건으로 학생 고르기 — 규칙 {include:[{all:[조건…]}…], exclude:[…]} → 재학생 명단 + 묶음·조건별 인원(0명 원인·기록 없음·모르는 이름). 교사·관리자 전용. 클라이언트 짝 = src/lib/studentAudienceRule.ts.';



CREATE OR REPLACE FUNCTION "public"."resolve_student_key"("p_key" "text", "p_key_type" "text" DEFAULT 'auto'::"text", "p_year" integer DEFAULT NULL::integer) RETURNS TABLE("student_code" "text", "profile_id" "uuid", "resource_id" "uuid", "name" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_key_type TEXT;
BEGIN
  -- Auto-detect key type if 'auto'
  IF p_key_type = 'auto' THEN
    IF p_key ~ '^\d{2}-\d{5}$' THEN
      v_key_type := 'student_code';
    ELSIF p_key ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_key_type := 'profile_id';
    ELSIF p_key ~ '^\d{5}$' THEN
      v_key_type := 'snum';
    ELSE
      v_key_type := 'student_code'; -- fallback
    END IF;
  ELSE
    v_key_type := p_key_type;
  END IF;

  -- Resolve based on key type
  CASE v_key_type
    WHEN 'student_code' THEN
      RETURN QUERY
        SELECT sim.student_code, sim.profile_id, sim.resource_id, sim.name
        FROM student_identity_map sim
        WHERE sim.student_code = p_key;

    WHEN 'profile_id' THEN
      RETURN QUERY
        SELECT sim.student_code, sim.profile_id, sim.resource_id, sim.name
        FROM student_identity_map sim
        WHERE sim.profile_id = p_key::uuid;

    WHEN 'resource_id' THEN
      RETURN QUERY
        SELECT sim.student_code, sim.profile_id, sim.resource_id, sim.name
        FROM student_identity_map sim
        WHERE sim.resource_id = p_key::uuid;

    WHEN 'snum' THEN
      -- Year-aware snum resolution
      IF p_year IS NOT NULL THEN
        -- Calculate which grade the student would be in for the given year
        -- and search the corresponding snum field
        RETURN QUERY
          SELECT sim.student_code, sim.profile_id, sim.resource_id, sim.name
          FROM student_identity_map sim
          WHERE
            (sim.snum1 = p_key AND (p_year - SPLIT_PART(sim.student_code, '-', 1)::int - 2000 + 1) = 1)
            OR (sim.snum2 = p_key AND (p_year - SPLIT_PART(sim.student_code, '-', 1)::int - 2000 + 1) = 2)
            OR (sim.snum3 = p_key AND (p_year - SPLIT_PART(sim.student_code, '-', 1)::int - 2000 + 1) = 3);
      ELSE
        -- Fallback chain: snum3 > snum2 > snum1 (most recent first)
        RETURN QUERY
          SELECT sim.student_code, sim.profile_id, sim.resource_id, sim.name
          FROM student_identity_map sim
          WHERE sim.snum3 = p_key
             OR sim.snum2 = p_key
             OR sim.snum1 = p_key
          LIMIT 1;
      END IF;

    ELSE
      -- Unknown key type, try student_code
      RETURN QUERY
        SELECT sim.student_code, sim.profile_id, sim.resource_id, sim.name
        FROM student_identity_map sim
        WHERE sim.student_code = p_key;
  END CASE;
END;
$_$;


ALTER FUNCTION "public"."resolve_student_key"("p_key" "text", "p_key_type" "text", "p_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_task_audience"("p_rule" "jsonb", "p_task_id" "uuid", "p_axis" "text" DEFAULT 'person'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  return public.resolve_audience(public.expand_task_audience(p_rule, p_task_id), p_axis);
end;
$$;


