CREATE OR REPLACE FUNCTION "public"."resource_reject_meta_accounts"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.meta is not null and jsonb_typeof(new.meta) = 'object' and new.meta ? 'accounts' then
    raise exception using
      errcode = '23514',
      message = '계정 정보는 resource.meta 가 아니라 resource_accounts 표에 저장합니다.',
      hint = 'meta.accounts 는 로그인한 모두가 읽을 수 있습니다(2026-10-13 이전).';
  end if;
  return new;
end;
$$;


