CREATE OR REPLACE FUNCTION "public"."respond_supervision_swap"("p_request" "uuid", "p_accept" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_req supervision_swap_request%rowtype;
  v_req_name text;
  v_partner_name text;
  v_mine meeting%rowtype;
  v_theirs meeting%rowtype;
  v_date_label text;
  v_head record;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다' using errcode = '42501';
  end if;

  select s.* into v_req from supervision_swap_request s where s.id = p_request for update;
  if not found then
    raise exception '교체 신청을 찾을 수 없습니다' using errcode = '22023';
  end if;
  if not (v_req.partner_resource_id in (select public.current_actor_resource_ids())) then
    raise exception '나에게 온 신청만 답할 수 있습니다' using errcode = '42501';
  end if;
  if v_req.status <> 'pending' then
    raise exception '이미 처리된 신청입니다' using errcode = '22023';
  end if;

  select name into v_req_name from resource where id = v_req.requester_resource_id;
  select name into v_partner_name from resource where id = v_req.partner_resource_id;
  select m.* into v_mine from meeting m where m.id = v_req.requester_meeting_id for update;
  v_date_label := to_char(v_mine.starts_at at time zone 'Asia/Seoul', 'FMMM/FMDD');

  if not p_accept then
    update supervision_swap_request set status = 'rejected', responded_at = now() where id = p_request;
    insert into notification_events (type, title, message, resource_id, meta, priority, is_read)
    values ('supervision_swap_result', '자습 감독 교체 거절',
      format('%s 선생님이 %s 감독 교체 요청을 거절했습니다.', v_partner_name, v_date_label),
      v_req.requester_resource_id, jsonb_build_object('swap_request_id', p_request, 'grade', v_req.grade), 'medium', false);
    return 'rejected';
  end if;

  -- 수락 — 신청 뒤에 담당자가 바뀌었으면(다른 교체·직접 수정) 맞바꾸지 않는다
  if v_mine.starts_at <= now() then
    raise exception '이미 지난 감독입니다' using errcode = '22023';
  end if;
  if not (v_req_name = any (public.supervision_assignee_names(v_mine.meta))) then
    raise exception '신청한 선생님이 더 이상 이 감독의 담당자가 아닙니다' using errcode = '22023';
  end if;
  if v_req.partner_meeting_id is not null then
    select m.* into v_theirs from meeting m where m.id = v_req.partner_meeting_id for update;
    if not found or v_theirs.starts_at <= now() then
      raise exception '맞바꿀 감독이 이미 지났거나 없습니다' using errcode = '22023';
    end if;
    if not (v_partner_name = any (public.supervision_assignee_names(v_theirs.meta))) then
      raise exception '내가 더 이상 그 감독의 담당자가 아닙니다' using errcode = '22023';
    end if;
  end if;

  -- 신청한 사람의 감독 → 받은 사람
  update meeting set
    meta = jsonb_set(
      jsonb_set(meta, '{assignee}', (meta -> 'assignee') - v_req_name || jsonb_build_object(v_partner_name, jsonb_build_object('name', v_partner_name))),
      '{title}', to_jsonb(regexp_replace(coalesce(meta ->> 'title', ''), ' · ' || v_req_name || '$', ' · ' || v_partner_name))
    ),
    updated_at = now()
  where id = v_mine.id;

  -- 받은 사람의 감독 → 신청한 사람 (맞바꾸기일 때만)
  if v_req.partner_meeting_id is not null then
    update meeting set
      meta = jsonb_set(
        jsonb_set(meta, '{assignee}', (meta -> 'assignee') - v_partner_name || jsonb_build_object(v_req_name, jsonb_build_object('name', v_req_name))),
        '{title}', to_jsonb(regexp_replace(coalesce(meta ->> 'title', ''), ' · ' || v_partner_name || '$', ' · ' || v_req_name))
      ),
      updated_at = now()
    where id = v_theirs.id;
  end if;

  update supervision_swap_request set status = 'accepted', responded_at = now() where id = p_request;
  -- 이 일정들에 걸려 있던 다른 대기 신청은 더 이상 맞지 않는다
  update supervision_swap_request set status = 'cancelled', responded_at = now()
  where status = 'pending' and id <> p_request
    and (requester_meeting_id in (v_req.requester_meeting_id, v_req.partner_meeting_id)
      or partner_meeting_id in (v_req.requester_meeting_id, v_req.partner_meeting_id));

  insert into notification_events (type, title, message, resource_id, meta, priority, is_read)
  values ('supervision_swap_result', '자습 감독 교체 완료',
    format('%s 선생님이 %s 감독 교체를 수락했습니다. 일정에 반영되었습니다.', v_partner_name, v_date_label),
    v_req.requester_resource_id, jsonb_build_object('swap_request_id', p_request, 'grade', v_req.grade), 'medium', false);

  -- 학년부장에게도 알린다(본인이 당사자면 빼고)
  for v_head in
    select distinct a.resource_id
    from resource_tag_assignments a
    join resource_tags t on t.id = a.tag_id
    -- 전 학년 아침(grade 0)은 세 학년부장 모두에게
    where t.name ~ ('^' || case when v_req.grade = 0 then '[1-3]' else v_req.grade::text end || '학년\s*부장$')
      and a.resource_id not in (v_req.requester_resource_id, v_req.partner_resource_id)
  loop
    insert into notification_events (type, title, message, resource_id, meta, priority, is_read)
    values ('supervision_swap_result', '자습 감독 교체',
      format('%s %s 감독: %s → %s%s', case when v_req.grade = 0 then '전 학년 아침' else v_req.grade || '학년' end, v_date_label, v_req_name, v_partner_name,
        case when v_req.partner_meeting_id is null then '' else
          format(' / %s 감독: %s → %s', to_char(v_theirs.starts_at at time zone 'Asia/Seoul', 'FMMM/FMDD'), v_partner_name, v_req_name) end),
      v_head.resource_id, jsonb_build_object('swap_request_id', p_request, 'grade', v_req.grade), 'medium', false);
  end loop;

  return 'accepted';
end;
$_$;


ALTER FUNCTION "public"."respond_supervision_swap"("p_request" "uuid", "p_accept" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_task_action_run"("p_run_id" "uuid", "p_decision" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  affected_rows integer;
begin
  if (select auth.uid()) is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if p_decision not in ('accepted', 'needs_changes') then
    raise exception 'invalid review decision' using errcode = '22023';
  end if;

  perform pg_catalog.set_config(
    'app.task_action_audit_writer',
    (select auth.uid())::text,
    true
  );

  update public.task_action_run
  set status = p_decision
  where id = p_run_id
    and created_by = (select auth.uid())
    and status = 'needs_review';

  get diagnostics affected_rows = row_count;
  if affected_rows <> 1 then
    raise exception 'run not found, inaccessible, or not reviewable' using errcode = '42501';
  end if;

  insert into public.task_action_review (
    run_id,
    reviewer_id,
    decision,
    comment
  )
  values (
    p_run_id,
    (select auth.uid()),
    p_decision,
    nullif(btrim(p_comment), '')
  );

  insert into public.task_action_run_log (
    run_id,
    created_by,
    log_type,
    from_status,
    to_status,
    payload
  )
  values (
    p_run_id,
    (select auth.uid()),
    'reviewed',
    'needs_review',
    p_decision,
    jsonb_build_object(
      'hasComment', nullif(btrim(p_comment), '') is not null
    )
  );
end;
$$;


ALTER FUNCTION "public"."review_task_action_run"("p_run_id" "uuid", "p_decision" "text", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_task_work_run"("p_run_id" "uuid", "p_decision" "text", "p_comment" "text") RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$ select public.review_task_action_run(p_run_id, p_decision, p_comment) $$;


ALTER FUNCTION "public"."review_task_work_run"("p_run_id" "uuid", "p_decision" "text", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_academy_prologue"("p_scene_index" integer, "p_finish" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare actor uuid := auth.uid(); result public.academy_prologues;
begin
  if actor is null or not exists (select 1 from public.profiles where id = actor and role in ('student','teacher','admin')) then
    raise exception '학생 본인의 책갈피만 저장할 수 있어요.' using errcode = '42501';
  end if;
  if p_scene_index is null or p_scene_index not between 0 and 30 or (p_finish is not null and p_finish not in ('completed', 'skipped')) then
    raise exception '이야기의 장면을 확인해 주세요.' using errcode = '22023';
  end if;
  if p_finish = 'completed' and p_scene_index <> 30 then
    raise exception '마지막 장면을 읽거나 건너뛰기를 선택해 주세요.' using errcode = '22023';
  end if;
  insert into public.academy_prologues(user_id, scene_index, completed_at, skipped)
    values (actor, p_scene_index, case when p_finish is not null then now() end, coalesce(p_finish = 'skipped', false))
  on conflict (user_id) do update set
    scene_index = greatest(academy_prologues.scene_index, excluded.scene_index),
    completed_at = coalesce(academy_prologues.completed_at, excluded.completed_at),
    skipped = case when academy_prologues.completed_at is null then excluded.skipped else academy_prologues.skipped end,
    updated_at = now()
  returning * into result;
  return to_jsonb(result);
end;
$$;


ALTER FUNCTION "public"."save_academy_prologue"("p_scene_index" integer, "p_finish" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_course_selection_group"("p_round_id" "uuid", "p_group_id" "uuid", "p_student_resource_id" "uuid", "p_student_code" "text", "p_student_name" "text", "p_student_grade" integer, "p_student_class" integer, "p_student_no" integer, "p_picks" "jsonb", "p_actor_role" "text" DEFAULT 'student'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_round public.course_selection_round%ROWTYPE;
  v_submission_id uuid;
  v_is_new boolean := false;
  v_now timestamptz := now();
  v_pick jsonb;
  v_slot public.course_selection_slot%ROWTYPE;
  v_eff_capacity integer;
  v_current_count integer;
  v_existing_items jsonb;
  v_new_items jsonb := '[]'::jsonb;
  v_privileged boolean := false;
  v_actor_role text;
  v_actor_name text;
  v_group_name text;
  v_overfilled jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_round FROM public.course_selection_round WHERE id = p_round_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'round_not_found'; END IF;

  v_privileged := public.can_manage_course_selection_student(p_student_code);

  IF NOT v_privileged THEN
    IF v_round.status NOT IN ('open') THEN RAISE EXCEPTION 'round_not_open: status=%', v_round.status; END IF;
    IF v_round.opens_at IS NOT NULL AND v_now < v_round.opens_at THEN
      RAISE EXCEPTION 'round_not_started: opens_at=%', v_round.opens_at;
    END IF;
    IF v_round.closes_at IS NOT NULL AND v_now > v_round.closes_at THEN
      RAISE EXCEPTION 'round_closed: closed_at=%', v_round.closes_at;
    END IF;
  END IF;

  v_actor_role := CASE
    WHEN COALESCE(p_actor_role, 'student') IN ('teacher', 'admin') AND NOT v_privileged THEN 'student'
    ELSE COALESCE(p_actor_role, 'student')
  END;

  v_actor_name := COALESCE(NULLIF(public.current_profile_name(), ''), p_student_name);

  SELECT id INTO v_submission_id
    FROM public.course_selection_submission
    WHERE round_id = p_round_id AND student_code = p_student_code;

  IF NOT FOUND THEN
    INSERT INTO public.course_selection_submission (
      round_id, student_resource_id, student_code, student_name,
      student_grade, student_class, student_no, status, submitted_at, last_modified_at
    ) VALUES (
      p_round_id, p_student_resource_id, p_student_code, p_student_name,
      p_student_grade, p_student_class, p_student_no, 'submitted', v_now, v_now
    ) RETURNING id INTO v_submission_id;
    v_is_new := true;
  ELSE
    UPDATE public.course_selection_submission
      SET student_name = p_student_name,
          student_grade = p_student_grade,
          student_class = p_student_class,
          student_no = p_student_no,
          student_resource_id = COALESCE(p_student_resource_id, student_resource_id),
          last_modified_at = v_now,
          updated_at = v_now,
          status = 'submitted'
      WHERE id = v_submission_id;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'slot_id', i.slot_id, 'subject_name', i.subject_name,
           'subject_id', i.selectable_subject_id, 'semester', i.semester
         )), '[]'::jsonb)
    INTO v_existing_items
    FROM public.course_selection_item i
    JOIN public.course_selection_slot s ON s.id = i.slot_id
    WHERE i.submission_id = v_submission_id AND s.group_id = p_group_id;

  DELETE FROM public.course_selection_item
    WHERE submission_id = v_submission_id
      AND slot_id IN (SELECT id FROM public.course_selection_slot WHERE group_id = p_group_id);

  FOR v_pick IN SELECT * FROM jsonb_array_elements(p_picks) LOOP
    PERFORM pg_advisory_xact_lock(hashtext((v_pick->>'slot_id')));

    SELECT * INTO v_slot FROM public.course_selection_slot WHERE id = (v_pick->>'slot_id')::uuid;
    IF NOT FOUND THEN RAISE EXCEPTION 'slot_not_found: %', v_pick->>'slot_id'; END IF;
    IF v_slot.group_id <> p_group_id THEN
      RAISE EXCEPTION 'slot_group_mismatch: slot.group=%, requested=%', v_slot.group_id, p_group_id;
    END IF;

    SELECT COALESCE(override_capacity, v_slot.capacity)
      INTO v_eff_capacity
      FROM public.course_selection_slot_subject
      WHERE slot_id = v_slot.id
        AND selectable_subject_id = (v_pick->>'selectable_subject_id')::uuid
      LIMIT 1;

    IF v_eff_capacity IS NOT NULL THEN
      SELECT COUNT(*) INTO v_current_count
        FROM public.course_selection_item
        WHERE slot_id = v_slot.id
          AND selectable_subject_id = (v_pick->>'selectable_subject_id')::uuid;

      IF v_current_count >= v_eff_capacity THEN
        IF NOT v_privileged THEN
          RAISE EXCEPTION 'capacity_exceeded: slot=%, subject=%, count=%, capacity=%',
            v_slot.id, v_pick->>'subject_name', v_current_count, v_eff_capacity;
        END IF;
        v_overfilled := v_overfilled || jsonb_build_object(
          'slot_id', v_slot.id,
          'subject_name', v_pick->>'subject_name',
          'capacity', v_eff_capacity,
          'enrolled_before', v_current_count
        );
      END IF;
    END IF;

    INSERT INTO public.course_selection_item (
      submission_id, slot_id, selectable_subject_id, subject_name,
      semester, priority, category_code
    ) VALUES (
      v_submission_id,
      v_slot.id,
      (v_pick->>'selectable_subject_id')::uuid,
      v_pick->>'subject_name',
      (v_pick->>'semester')::integer,
      (v_pick->>'priority')::integer,
      v_pick->>'category_code'
    );

    v_new_items := v_new_items || jsonb_build_object(
      'slot_id', v_slot.id,
      'subject_id', v_pick->>'selectable_subject_id',
      'subject_name', v_pick->>'subject_name',
      'semester', (v_pick->>'semester')::integer
    );
  END LOOP;

  SELECT name INTO v_group_name FROM public.course_selection_group WHERE id = p_group_id;

  INSERT INTO public.course_selection_audit_log (
    round_id, actor_id, actor_name, actor_role, action,
    target_type, target_id, target_label, diff, occurred_at
  ) VALUES (
    p_round_id,
    auth.uid(),
    v_actor_name,
    v_actor_role,
    CASE WHEN v_is_new THEN 'submission_save' ELSE 'submission_modify' END,
    'group',
    p_group_id,
    COALESCE(v_group_name || ' · ', '')
      || COALESCE(p_student_name, '?') || ' (' || p_student_code || ')',
    jsonb_build_object(
      'before', v_existing_items,
      'after', v_new_items,
      'student_code', p_student_code,
      'student_name', p_student_name,
      'round_status', v_round.status,
      'privileged', v_privileged,
      'capacity_overridden', v_overfilled
    ),
    v_now
  );

  RETURN jsonb_build_object(
    'ok', true,
    'submission_id', v_submission_id,
    'action', CASE WHEN v_is_new THEN 'created' ELSE 'updated' END,
    'group_id', p_group_id,
    'items_count', jsonb_array_length(v_new_items),
    'privileged', v_privileged,
    'capacity_overridden', v_overfilled
  );
END $$;


ALTER FUNCTION "public"."save_course_selection_group"("p_round_id" "uuid", "p_group_id" "uuid", "p_student_resource_id" "uuid", "p_student_code" "text", "p_student_name" "text", "p_student_grade" integer, "p_student_class" integer, "p_student_no" integer, "p_picks" "jsonb", "p_actor_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_inquiry_design_with_ontology"("p_design" "jsonb", "p_sources" "jsonb" DEFAULT '[]'::"jsonb", "p_entities" "jsonb" DEFAULT '[]'::"jsonb", "p_relations" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_design_id uuid;
  v_student_id text := p_design ->> 'student_id';
  v_rationale text := trim(COALESCE(p_design ->> 'student_rationale', ''));
  v_created_by uuid := (SELECT auth.uid());
  v_entity jsonb;
  v_relation jsonb;
  v_source jsonb;
  v_reuse_map jsonb := '{}'::jsonb;
  v_source_id text;
  v_target_id text;
  v_source_scope text;
  v_target_scope text;
BEGIN
  IF v_student_id IS NULL OR v_student_id = '' THEN
    RAISE EXCEPTION 'student_id is required';
  END IF;

  IF NOT public.inquiry_design_can_access_student(v_student_id) THEN
    RAISE EXCEPTION 'not allowed to save inquiry design for student %', v_student_id;
  END IF;

  INSERT INTO public.student_inquiry_designs (
    student_id, kg_version_id, title, target_kind, target_name, target_ref,
    academic_year, grade, semester, status, selected_source_snapshot,
    llm_result, student_rationale, reflection, llm_token_usage, created_by
  )
  VALUES (
    v_student_id,
    -- 빈 문자열도 NULL 로 떨어뜨린다 — 클라이언트가 '' 를 보내면 uuid 캐스팅이 터진다.
    NULLIF(p_design ->> 'kg_version_id', '')::uuid,
    NULLIF(trim(p_design ->> 'title'), ''),
    p_design ->> 'target_kind',
    NULLIF(trim(p_design ->> 'target_name'), ''),
    COALESCE(p_design -> 'target_ref', '{}'::jsonb),
    (p_design ->> 'academic_year')::integer,
    (p_design ->> 'grade')::integer,
    NULLIF(p_design ->> 'semester', '')::integer,
    COALESCE(NULLIF(p_design ->> 'status', ''), 'saved'),
    COALESCE(p_design -> 'selected_source_snapshot', '[]'::jsonb),
    p_design -> 'llm_result',
    v_rationale,
    NULLIF(p_design ->> 'reflection', ''),
    COALESCE(p_design -> 'llm_token_usage', '{}'::jsonb),
    v_created_by
  )
  RETURNING id INTO v_design_id;

  FOR v_source IN SELECT value FROM jsonb_array_elements(COALESCE(p_sources, '[]'::jsonb))
  LOOP
    INSERT INTO public.student_inquiry_design_sources (
      design_id, student_id, source_kind, kg_version_id,
      source_entity_id, source_relation_id, activity_id, snapshot
    )
    VALUES (
      v_design_id, v_student_id, v_source ->> 'source_kind',
      NULLIF(v_source ->> 'kg_version_id', '')::uuid,
      NULLIF(v_source ->> 'source_entity_id', ''),
      NULLIF(v_source ->> 'source_relation_id', '')::uuid,
      NULLIF(v_source ->> 'activity_id', '')::uuid,
      COALESCE(v_source -> 'snapshot', '{}'::jsonb)
    );
  END LOOP;

  FOR v_entity IN SELECT value FROM jsonb_array_elements(COALESCE(p_entities, '[]'::jsonb))
  LOOP
    IF NULLIF(v_entity ->> 'reuse_existing_id', '') IS NOT NULL THEN
      v_reuse_map := v_reuse_map || jsonb_build_object(v_entity ->> 'entity_id', v_entity ->> 'reuse_existing_id');
    ELSE
      INSERT INTO public.student_inquiry_design_entities (
        design_id, student_id, entity_id, label, type, properties
      )
      VALUES (
        v_design_id, v_student_id,
        v_entity ->> 'entity_id', v_entity ->> 'label', v_entity ->> 'type',
        COALESCE(v_entity -> 'properties', '{}'::jsonb)
      );
    END IF;
  END LOOP;

  FOR v_relation IN SELECT value FROM jsonb_array_elements(COALESCE(p_relations, '[]'::jsonb))
  LOOP
    v_source_id := v_relation ->> 'source_entity_id';
    v_target_id := v_relation ->> 'target_entity_id';
    v_source_scope := COALESCE(NULLIF(v_relation ->> 'source_scope', ''), 'planned');
    v_target_scope := COALESCE(NULLIF(v_relation ->> 'target_scope', ''), 'planned');

    IF v_reuse_map ? v_source_id THEN
      v_source_id := v_reuse_map ->> v_source_id;
      v_source_scope := 'existing';
    END IF;

    IF v_reuse_map ? v_target_id THEN
      v_target_id := v_reuse_map ->> v_target_id;
      v_target_scope := 'existing';
    END IF;

    INSERT INTO public.student_inquiry_design_relations (
      design_id, student_id, source_scope, source_entity_id,
      target_scope, target_entity_id, relation_type, confidence, evidence, properties
    )
    VALUES (
      v_design_id, v_student_id, v_source_scope, v_source_id,
      v_target_scope, v_target_id, v_relation ->> 'relation_type',
      NULLIF(v_relation ->> 'confidence', '')::numeric,
      NULLIF(v_relation ->> 'evidence', ''),
      COALESCE(v_relation -> 'properties', '{}'::jsonb)
    );
  END LOOP;

  RETURN v_design_id;
END;
$$;


ALTER FUNCTION "public"."save_inquiry_design_with_ontology"("p_design" "jsonb", "p_sources" "jsonb", "p_entities" "jsonb", "p_relations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_kg_version"("p_student_id" "text", "p_kg_json" "jsonb", "p_source_categories" "text"[] DEFAULT ARRAY['regular'::"text"]) RETURNS TABLE("id" "uuid", "version" integer, "student_id" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  INSERT INTO student_kg_versions (student_id, version, kg_json, source_categories, created_by)
  VALUES (
    p_student_id,
    COALESCE((SELECT MAX(v.version) FROM student_kg_versions v WHERE v.student_id = p_student_id), 0) + 1,
    p_kg_json,
    p_source_categories,
    NULL
  )
  RETURNING student_kg_versions.id, student_kg_versions.version, student_kg_versions.student_id, student_kg_versions.created_at;
END;
$$;


ALTER FUNCTION "public"."save_kg_version"("p_student_id" "text", "p_kg_json" "jsonb", "p_source_categories" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_kg_version_secure"("p_student_id" "text", "p_kg_json" "jsonb", "p_source_categories" "text"[] DEFAULT '{}'::"text"[]) RETURNS TABLE("id" "uuid", "version" integer, "student_id" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_role TEXT;
  v_caller_id UUID;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT p.role INTO v_caller_role FROM profiles p WHERE p.id = v_caller_id;
  IF v_caller_role IS NULL OR v_caller_role NOT IN ('teacher', 'admin') THEN
    RAISE EXCEPTION 'Only teachers and admins can save KG versions' USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN QUERY SELECT * FROM save_kg_version(p_student_id, p_kg_json, p_source_categories, v_caller_id);
END;
$$;


ALTER FUNCTION "public"."save_kg_version_secure"("p_student_id" "text", "p_kg_json" "jsonb", "p_source_categories" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_kg_version_secure"("p_student_id" "text", "p_kg_json" "jsonb", "p_source_categories" "text"[]) IS 'Public RPC for saving KG versions. Validates caller is teacher/admin, then delegates to save_kg_version.';



CREATE TABLE IF NOT EXISTS "public"."task_output_value" (
    "task_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "provenance" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_by" "uuid" DEFAULT "auth"."uid"(),
    "updated_by_name" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "restricted" boolean DEFAULT false NOT NULL,
    CONSTRAINT "task_output_value_kind_check" CHECK (("kind" = ANY (ARRAY['value'::"text", 'people'::"text", 'table'::"text"]))),
    CONSTRAINT "task_output_value_payload_size" CHECK (("octet_length"(("payload")::"text") <= 512000))
);


ALTER TABLE "public"."task_output_value" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_output_value" IS '업무 진행 화면 — 할 일이 사람 손으로 남긴 산출물(값·명단·표). 스냅샷. 쓰기는 save_task_output RPC 전용.';



COMMENT ON COLUMN "public"."task_output_value"."restricted" IS '비공개 수합·본인만 보는 제출에서 가져온 표 — 매니저·관리자만 연다(같은 업무 담당자에게 열면 비공개 응답이 샌다).';



CREATE OR REPLACE FUNCTION "public"."save_task_output"("p_task_id" "uuid", "p_kind" "text", "p_payload" "jsonb", "p_provenance" "jsonb" DEFAULT '{}'::"jsonb", "p_restricted" boolean DEFAULT false) RETURNS "public"."task_output_value"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_row public.task_output_value;
  v_name text;
  v_work uuid;
  v_declared text;
  v_payload jsonb := p_payload;
  v_prov jsonb := coalesce(p_provenance, '{}'::jsonb);
  v_rows jsonb := '[]'::jsonb;
  v_r jsonb;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  select t.event_id, t.meta->'output'->>'kind' into v_work, v_declared from public.task t where t.id = p_task_id;
  if v_work is null then
    raise exception '할 일을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not public.can_write_task_output(p_task_id) then
    raise exception '이 할 일의 책임자나 담당자만 산출물을 남길 수 있습니다.' using errcode = '42501';
  end if;
  if p_kind not in ('value', 'people', 'table') then
    raise exception '알 수 없는 산출물 형태입니다: %', p_kind using errcode = '22023';
  end if;
  if v_declared in ('value', 'people', 'table') and v_declared <> p_kind then
    raise exception '이 할 일은 «%»을(를) 남기도록 정해져 있습니다.', v_declared using errcode = '22023';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception '산출물 내용이 비어 있습니다.' using errcode = '22023';
  end if;

  if p_kind = 'value' then
    if jsonb_typeof(p_payload->'text') <> 'string' then
      raise exception '값 산출물에는 text 가 필요합니다.' using errcode = '22023';
    end if;
    v_payload := jsonb_build_object('text', p_payload->>'text');
  elsif p_kind = 'people' then
    if jsonb_typeof(p_payload->'people') <> 'array' then
      raise exception '명단 산출물에는 people 배열이 필요합니다.' using errcode = '22023';
    end if;
    v_payload := jsonb_build_object('people', public.normalize_output_people(p_payload->'people'));
  else
    if jsonb_typeof(p_payload->'columns') <> 'array' or jsonb_typeof(p_payload->'rows') <> 'array' then
      raise exception '표 산출물에는 columns·rows 배열이 필요합니다.' using errcode = '22023';
    end if;
    for v_r in select value from jsonb_array_elements(p_payload->'rows') loop
      if jsonb_typeof(v_r) = 'object' and jsonb_typeof(v_r->'people') = 'array' then
        v_r := jsonb_set(v_r, '{people}', public.normalize_output_people(v_r->'people'));
      end if;
      v_rows := v_rows || jsonb_build_array(v_r);
    end loop;
    v_payload := jsonb_build_object('columns', p_payload->'columns', 'rows', v_rows);
  end if;

  -- 출처 주장은 같은 업무의 할 일일 때만 남긴다
  if v_prov ? 'fromTaskId' and not exists (
    select 1 from public.task s
    where s.id::text = v_prov->>'fromTaskId' and s.event_id = v_work
  ) then
    v_prov := '{}'::jsonb;
  end if;

  select r.name into v_name
  from public.resource r
  where r.id in (select me from public.current_actor_resource_ids() me)
  order by case when r.type = 'teacher' then 0 else 1 end
  limit 1;

  insert into public.task_output_value as o
    (task_id, kind, payload, provenance, restricted, updated_by, updated_by_name, updated_at)
  values
    (p_task_id, p_kind, v_payload, v_prov, coalesce(p_restricted, false), auth.uid(), v_name, now())
  on conflict (task_id) do update
    set kind = excluded.kind,
        payload = excluded.payload,
        provenance = excluded.provenance,
        restricted = excluded.restricted,
        updated_by = excluded.updated_by,
        updated_by_name = excluded.updated_by_name,
        updated_at = now()
  returning o.* into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."save_task_output"("p_task_id" "uuid", "p_kind" "text", "p_payload" "jsonb", "p_provenance" "jsonb", "p_restricted" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_task_workflow_graph"("p_workflow_id" "uuid", "p_name" "text", "p_description" "text", "p_viewport" "jsonb", "p_nodes" "jsonb", "p_edges" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (
    select 1
    from public.task_workflow
    where id = p_workflow_id
      and (owner_id = (select auth.uid()) or public.is_admin())
  ) then
    raise exception 'workflow not found or access denied' using errcode = '42501';
  end if;

  if jsonb_typeof(coalesce(p_nodes, '[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(p_edges, '[]'::jsonb)) <> 'array'
  then
    raise exception 'nodes and edges must be JSON arrays' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.task_workflow_node existing_node
    join jsonb_array_elements(coalesce(p_nodes, '[]'::jsonb)) node_item
      on existing_node.id = (node_item->>'id')::uuid
    where existing_node.workflow_id <> p_workflow_id
  ) then
    raise exception 'node id belongs to another workflow' using errcode = '23505';
  end if;

  if exists (
    select 1
    from public.task_workflow_edge existing_edge
    join jsonb_array_elements(coalesce(p_edges, '[]'::jsonb)) edge_item
      on existing_edge.id = (edge_item->>'id')::uuid
    where existing_edge.workflow_id <> p_workflow_id
  ) then
    raise exception 'edge id belongs to another workflow' using errcode = '23505';
  end if;

  update public.task_workflow
  set
    name = p_name,
    description = p_description,
    viewport = coalesce(p_viewport, '{"x":0,"y":0,"zoom":1}'::jsonb)
  where id = p_workflow_id;

  delete from public.task_workflow_edge edge_row
  where edge_row.workflow_id = p_workflow_id
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(p_edges, '[]'::jsonb)) edge_item
      where (edge_item->>'id')::uuid = edge_row.id
    );

  delete from public.task_workflow_node node_row
  where node_row.workflow_id = p_workflow_id
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(p_nodes, '[]'::jsonb)) node_item
      where (node_item->>'id')::uuid = node_row.id
    );

  insert into public.task_workflow_node (
    id,
    workflow_id,
    node_kind,
    event_id,
    task_id,
    action_id,
    label,
    position_x,
    position_y,
    metadata
  )
  select
    (node_item->>'id')::uuid,
    p_workflow_id,
    node_item->>'node_kind',
    nullif(node_item->>'event_id', '')::uuid,
    nullif(node_item->>'task_id', '')::uuid,
    nullif(node_item->>'action_id', '')::uuid,
    node_item->>'label',
    coalesce((node_item->>'position_x')::double precision, 0),
    coalesce((node_item->>'position_y')::double precision, 0),
    coalesce(node_item->'metadata', '{}'::jsonb)
  from jsonb_array_elements(coalesce(p_nodes, '[]'::jsonb)) node_item
  on conflict (id) do update
  set
    node_kind = excluded.node_kind,
    event_id = excluded.event_id,
    task_id = excluded.task_id,
    action_id = excluded.action_id,
    label = excluded.label,
    position_x = excluded.position_x,
    position_y = excluded.position_y,
    metadata = excluded.metadata;

  insert into public.task_workflow_edge (
    id,
    workflow_id,
    source_node_id,
    target_node_id,
    relation_type,
    label,
    metadata
  )
  select
    (edge_item->>'id')::uuid,
    p_workflow_id,
    (edge_item->>'source_node_id')::uuid,
    (edge_item->>'target_node_id')::uuid,
    coalesce(edge_item->>'relation_type', 'flow'),
    nullif(edge_item->>'label', ''),
    coalesce(edge_item->'metadata', '{}'::jsonb)
  from jsonb_array_elements(coalesce(p_edges, '[]'::jsonb)) edge_item
  on conflict (id) do update
  set
    source_node_id = excluded.source_node_id,
    target_node_id = excluded.target_node_id,
    relation_type = excluded.relation_type,
    label = excluded.label,
    metadata = excluded.metadata;
end;
$$;


ALTER FUNCTION "public"."save_task_workflow_graph"("p_workflow_id" "uuid", "p_name" "text", "p_description" "text", "p_viewport" "jsonb", "p_nodes" "jsonb", "p_edges" "jsonb") OWNER TO "postgres";


