CREATE OR REPLACE FUNCTION "public"."school_exam_subject_sync"("p_academic_year" integer, "p_semester" integer, "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare v_deleted int; v_inserted int; r jsonb;
begin
  if not (select public.is_admin()) then
    raise exception using errcode = '42501', message = '관리자만 정기시험 과목 계획을 올릴 수 있습니다.';
  end if;
  if p_academic_year is null or p_academic_year < 2020 or p_academic_year > 2100 or p_semester not in (1, 2) then
    raise exception using errcode = '22023', message = '학년도·학기가 올바르지 않습니다.';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception using errcode = '22023', message = '올릴 과목이 없습니다 — 빈 목록으로 학기 자료를 지우지 않습니다.';
  end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    if coalesce(r->>'exam_name', '') = '' or coalesce(r->>'subject_section', '') = ''
       or (r->>'grade') !~ '^[1-3]$' then
      raise exception using errcode = '22023', message = format('과목 한 줄의 고사·학년·과목이 비었습니다: %s', r);
    end if;
  end loop;

  delete from public.school_exam_subject where academic_year = p_academic_year and semester = p_semester;
  get diagnostics v_deleted = row_count;

  insert into public.school_exam_subject (academic_year, semester, exam_name, exam_round, grade, subject_section, subject_name,
                                          subject_code, credits, reflect_ratio, full_score, closed, applicants, average, std_dev)
  select p_academic_year, p_semester, btrim(x->>'exam_name'),
         nullif(substring(x->>'exam_name' from '([1-4])차'), '')::int,
         (x->>'grade')::int, btrim(x->>'subject_section'),
         btrim(regexp_replace(x->>'subject_section', '\(\s*\d+\s*\)\s*$', '')),
         nullif(btrim(x->>'subject_code'), ''),
         coalesce(nullif(x->>'credits', '')::int, nullif(substring(x->>'subject_section' from '\((\d+)\)\s*$'), '')::int),
         nullif(x->>'reflect_ratio', '')::numeric, nullif(x->>'full_score', '')::numeric,
         case upper(coalesce(x->>'closed', '')) when 'Y' then true when 'TRUE' then true when 'N' then false when 'FALSE' then false end,
         nullif(x->>'applicants', '')::int, nullif(x->>'average', '')::numeric, nullif(x->>'std_dev', '')::numeric
  from jsonb_array_elements(p_rows) x;
  get diagnostics v_inserted = row_count;

  return jsonb_build_object('academic_year', p_academic_year, 'semester', p_semester, 'deleted', v_deleted, 'inserted', v_inserted);
end $_$;


ALTER FUNCTION "public"."school_exam_subject_sync"("p_academic_year" integer, "p_semester" integer, "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_admission_majors"("p_track" "text", "p_query" "text", "p_limit" integer DEFAULT 40, "p_offset" integer DEFAULT 0, "p_regions" "text"[] DEFAULT NULL::"text"[], "p_cut_min" numeric DEFAULT NULL::numeric, "p_cut_max" numeric DEFAULT NULL::numeric, "p_sort" "text" DEFAULT 'grade70'::"text", "p_recruit_min" integer DEFAULT NULL::integer) RETURNS TABLE("adiga_id" "text", "university" "text", "major" "text", "program" "text", "field" "text", "domain" "text", "region" "text", "grade50" numeric, "grade70" numeric, "competition_2026" numeric, "recruit_2026" integer, "has_csat" boolean, "csat" "text", "csat_status" "text", "score" real)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH tokens AS (
    SELECT array_agg(t) AS arr
    FROM (
      SELECT NULLIF(trim(tok), '') AS t
      FROM regexp_split_to_table(COALESCE(p_query, ''), '\s+') AS tok
    ) s
    WHERE t IS NOT NULL
  ),
  page AS (
    SELECT a.id, a.university, a.major, a.program, a.field, a.domain, a.region,
           a.grade50, a.grade70, a.competition_2026, a.recruit_2026,
           GREATEST(
             similarity(a.university, p_query),
             similarity(COALESCE(a.major,''), p_query),
             similarity(COALESCE(a.search_text,''), p_query)
           ) AS score,
           -- 정렬 키: 작을수록 위. 미정의(NULL) 값은 큰 수로 밀어 NULLS LAST 효과.
           CASE p_sort
             WHEN 'score'       THEN -1 * GREATEST(
                                      similarity(a.university, p_query),
                                      similarity(COALESCE(a.major,''), p_query),
                                      similarity(COALESCE(a.search_text,''), p_query))::numeric
             WHEN 'recruit'     THEN COALESCE(-1 * a.recruit_2026::numeric, 1e9)
             WHEN 'competition' THEN COALESCE(a.competition_2026, 1e9)
             ELSE                    COALESCE(a.grade70, 1e9)   -- grade70 기본
           END AS sort_key
    FROM public.admission_adiga_results a, tokens
    WHERE a.track = CASE p_track WHEN 'gyogwa' THEN '교과' WHEN 'jonghap' THEN '종합' END
      AND (p_regions IS NULL OR array_length(p_regions, 1) IS NULL OR a.region = ANY(p_regions))
      AND (p_cut_min IS NULL OR a.grade70 >= p_cut_min)
      AND (p_cut_max IS NULL OR a.grade70 <= p_cut_max)
      AND (p_recruit_min IS NULL OR a.recruit_2026 >= p_recruit_min)
      AND (
        tokens.arr IS NULL
        OR (
          SELECT bool_and(
            a.university ILIKE '%'||tk||'%'
            OR a.major ILIKE '%'||tk||'%'
            OR a.search_text ILIKE '%'||tk||'%'
          )
          FROM unnest(tokens.arr) AS tk
        )
      )
    ORDER BY sort_key ASC, a.grade70 ASC NULLS LAST, a.id
    LIMIT p_limit OFFSET p_offset
  )
  SELECT p.id, p.university, p.major, p.program, p.field, p.domain, p.region,
         p.grade50, p.grade70, p.competition_2026, p.recruit_2026,
         g.has_csat, g.csat, g.csat_status,
         p.score
  FROM page p
  LEFT JOIN LATERAL (
    SELECT gg.has_csat, gg.csat, gg.csat_status
    FROM public.admission_gyogwa_criteria gg
    WHERE p_track = 'gyogwa' AND gg.university % p.university
    ORDER BY
      similarity(gg.university, p.university) DESC,
      (CASE WHEN p.major IS NOT NULL AND gg.unit IS NOT NULL
            AND similarity(gg.unit, p.major) >= 0.3 THEN 1 ELSE 0 END) DESC,
      (gg.has_csat)::int DESC,
      (CASE WHEN p.major IS NOT NULL AND gg.unit IS NOT NULL
            THEN similarity(gg.unit, p.major) ELSE 0 END) DESC
    LIMIT 1
  ) g ON true
  ORDER BY p.sort_key ASC, p.grade70 ASC NULLS LAST, p.id;
$$;


ALTER FUNCTION "public"."search_admission_majors"("p_track" "text", "p_query" "text", "p_limit" integer, "p_offset" integer, "p_regions" "text"[], "p_cut_min" numeric, "p_cut_max" numeric, "p_sort" "text", "p_recruit_min" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_admission_programs"("p_track" "text", "p_query" "text", "p_limit" integer DEFAULT 30) RETURNS TABLE("track" "text", "ref_id" "text", "university" "text", "department" "text", "admission_name" "text", "region" "text", "extra" "jsonb", "score" real)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  -- 교과
  SELECT 'gyogwa'::text, g.id, g.university, g.unit, g.admission, g.region,
    jsonb_build_object('method_tags', to_jsonb(g.method_tags), 'has_csat', g.has_csat,
                       'unit_tags', to_jsonb(g.unit_tags), 'quota', g.quota) AS extra,
    GREATEST(similarity(g.university, p_query), similarity(COALESCE(g.search_blob,''), p_query)) AS score
  FROM public.admission_gyogwa_criteria g
  WHERE p_track = 'gyogwa'
    AND (g.university ILIKE '%'||p_query||'%' OR g.search_blob ILIKE '%'||p_query||'%'
         OR g.search_blob % p_query)

  UNION ALL

  -- 종합 (jonghap은 모집단위 단위가 아니라 대학 단위 → department NULL)
  SELECT 'jonghap'::text, j.code, j.name, NULL::text, NULL::text, j.region,
    jsonb_build_object('has_doc_eval', j.has_doc_eval, 'has_interview', j.has_interview,
                       'interview_status', j.interview_status, 'recruitment', j.recruitment) AS extra,
    similarity(j.name, p_query) AS score
  FROM public.admission_jonghap_criteria j
  WHERE p_track = 'jonghap'
    AND (j.name ILIKE '%'||p_query||'%' OR j.name % p_query)

  ORDER BY score DESC NULLS LAST
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."search_admission_programs"("p_track" "text", "p_query" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_admission_programs"("p_track" "text", "p_query" "text", "p_limit" integer) IS '입력 화면 검색. p_track=gyogwa→교과 모집단위, jonghap→종합 대학. 대학명/검색blob ILIKE + pg_trgm 유사도 순.';



CREATE TABLE IF NOT EXISTS "public"."inquiry_activity" (
    "id" "text" NOT NULL,
    "record_id" "uuid" NOT NULL,
    "student_code" "text" NOT NULL,
    "cohort" integer NOT NULL,
    "grade" integer,
    "semester" integer,
    "academic_year" integer,
    "area" "text" NOT NULL,
    "subject_name" "text",
    "title" "text" NOT NULL,
    "did" "text" NOT NULL,
    "sentence_ids" integer[] DEFAULT '{}'::integer[] NOT NULL,
    "concepts" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "sources" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "usefulness" integer,
    "n_sentences" integer,
    "is_inquiry" boolean,
    "level" integer,
    "strength" integer,
    "breadth" integer,
    "research_question" "text",
    "method_types" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "output_types" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "career_fields" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "extension_hint" "text",
    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "thinking" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "seg_model" "text",
    "grader" "text",
    "prompt_version" "text",
    "graded_at" timestamp with time zone,
    "embedding" "extensions"."vector"(1536),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "club_name" "text",
    "hours" numeric,
    "did_overlap" numeric,
    CONSTRAINT "inquiry_activity_level_check" CHECK ((("level" >= 0) AND ("level" <= 4)))
);


ALTER TABLE "public"."inquiry_activity" OWNER TO "postgres";


COMMENT ON TABLE "public"."inquiry_activity" IS '생기부에서 분절·판정한 탐구 활동. 학생 참조는 student_code 뿐이고 화면에는 inquiry_activity_public 뷰로만 나간다.';



COMMENT ON COLUMN "public"."inquiry_activity"."n_sentences" IS '활동의 문장 수. 탐구 인정률이 1문장 26% → 4문장 이상 78% 로 갈리므로 수준과 반드시 함께 읽는다.';



COMMENT ON COLUMN "public"."inquiry_activity"."level" IS '0 비탐구 · 1 수행보고 · 2 이해적용 · 3 분석해석 · 4 설계확장 — 코드가 strength/breadth 에서 유도한다(모델이 매기지 않는다).';



COMMENT ON COLUMN "public"."inquiry_activity"."seg_model" IS 'S0 분절 모델. 같은 문장 수에서도 모델에 따라 판정이 갈려 코호트 비교의 교란원이 된다.';



COMMENT ON COLUMN "public"."inquiry_activity"."club_name" IS '동아리명. 원문 `(동아리명)(N시간)` 서식에서 뽑는다 — 동아리활동에만 값이 있다. 개념(concepts)에 섞지 말 것.';



COMMENT ON COLUMN "public"."inquiry_activity"."hours" IS '해당 기록의 이수 시수. 동아리활동 원문에 함께 적혀 있다.';



COMMENT ON COLUMN "public"."inquiry_activity"."did_overlap" IS '생기부 원문 대비 did 의 문자 5-gram 겹침 비율(0~1). >= 0.7 이면 공개 뷰가 did 를 가린다.';



CREATE OR REPLACE VIEW "public"."inquiry_activity_public" WITH ("security_invoker"='false') AS
 SELECT "a"."id",
    "a"."area",
    "a"."subject_name",
    "a"."grade",
    "a"."academic_year",
    "a"."title",
    "a"."concepts",
    "a"."sources",
    "a"."n_sentences",
    "a"."club_name",
    "a"."hours",
    "a"."is_inquiry",
    "a"."level",
    "a"."strength",
    "a"."breadth",
    "a"."research_question",
    "a"."method_types",
    "a"."output_types",
    "a"."career_fields",
    "a"."extension_hint",
    ("a"."student_code" = "public"."current_student_code"()) AS "is_mine"
   FROM "public"."inquiry_activity" "a"
  WHERE (("a"."is_inquiry" IS TRUE) AND ("public"."is_teacher_or_admin"("auth"."uid"()) OR ("public"."current_student_code"() IS NOT NULL)));


ALTER VIEW "public"."inquiry_activity_public" OWNER TO "postgres";


COMMENT ON VIEW "public"."inquiry_activity_public" IS '탐구 탐색용 공개 뷰. student_code 와 did("한 일") 를 주지 않는다 — did 는 생기부 원문에 가까워 화면에 내보내지 않기로 했다(표에는 남아 있다).';



CREATE OR REPLACE FUNCTION "public"."search_inquiry_activities"("p_q" "text", "p_limit" integer DEFAULT 40) RETURNS SETOF "public"."inquiry_activity_public"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select v.*
    from public.inquiry_activity a
    join public.inquiry_activity_public v on v.id = a.id
   where char_length(btrim(coalesce(p_q, ''))) >= 2
     and a.is_inquiry is true
     and public.inquiry_search_text(a.title, a.research_question, a.concepts)
         ilike '%' || btrim(p_q) || '%'
   -- 제목이 걸린 것을 먼저 — 개념 하나가 스친 활동보다 제목이 맞은 활동이 찾던 것일 확률이 높다.
   order by (a.title ilike '%' || btrim(p_q) || '%') desc,
            (a.research_question ilike '%' || btrim(p_q) || '%') desc,
            a.level desc nulls last,
            a.n_sentences desc nulls last
   limit least(greatest(coalesce(p_limit, 40), 1), 200);
$$;


ALTER FUNCTION "public"."search_inquiry_activities"("p_q" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_inquiry_activities"("p_q" "text", "p_limit" integer) IS '탐구 탐색 검색 — 제목·연구질문·개념(키워드)을 함께 본다. inquiry_activity_public 에서 고르므로 역할 판정과 did 비노출이 그대로 적용된다.';



CREATE OR REPLACE FUNCTION "public"."search_tasks"("p_query" "text", "p_limit" integer DEFAULT 50) RETURNS TABLE("type" "text", "id" "uuid", "title" "text", "description" "text", "status" "text", "keywords" "text"[], "relevance" double precision, "context" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 'event'::TEXT, e.id, e.name, e.description, e.status, e.keywords,
        (CASE WHEN e.name ILIKE '%' || p_query || '%' THEN 1.0 ELSE 0.5 END +
         CASE WHEN e.description ILIKE '%' || p_query || '%' THEN 0.5 ELSE 0.0 END +
         CASE WHEN p_query = ANY(e.keywords) THEN 0.3 ELSE 0.0 END)::FLOAT,
        jsonb_build_object('manager_id', e.manager_id, 'managers', e.meta->'managers', 'created_at', e.created_at, 'updated_at', e.updated_at)
    FROM work e
    WHERE e.name ILIKE '%' || p_query || '%' OR e.description ILIKE '%' || p_query || '%' OR p_query = ANY(e.keywords)
    UNION ALL
    SELECT 'task'::TEXT, t.id, t.title, t.description, t.status, t.keywords,
        (CASE WHEN t.title ILIKE '%' || p_query || '%' THEN 1.0 ELSE 0.5 END +
         CASE WHEN t.description ILIKE '%' || p_query || '%' THEN 0.5 ELSE 0.0 END +
         CASE WHEN p_query = ANY(t.keywords) THEN 0.3 ELSE 0.0 END)::FLOAT,
        jsonb_build_object('event_id', t.event_id, 'type', t.type, 'order_index', t.order_index, 'assignees', t.meta->'assignees', 'due_date', t.due_date, 'created_at', t.created_at, 'updated_at', t.updated_at)
    FROM task t
    WHERE t.title ILIKE '%' || p_query || '%' OR t.description ILIKE '%' || p_query || '%' OR p_query = ANY(t.keywords)
    ORDER BY relevance DESC LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_tasks"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_tasks"("p_query" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("type" "text", "id" "uuid", "title" "text", "description" "text", "status" "text", "keywords" "text"[], "relevance" real, "context" "json")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN QUERY
    -- 이벤트 검색 (키워드 포함)
    SELECT 
        'event'::text as type,
        te.id,
        te.name as title,
        te.description,
        te.status,
        te.keywords,
        -- Simple relevance scoring
        (CASE 
            WHEN te.name ILIKE '%' || p_query || '%' THEN 1.0
            WHEN te.description ILIKE '%' || p_query || '%' THEN 0.8
            WHEN array_to_string(te.keywords, ' ') ILIKE '%' || p_query || '%' THEN 0.6
            ELSE 0.3
        END) as relevance,
        json_build_object(
            'manager_name', r.name,
            'total_tasks', COUNT(t.id),
            'completed_tasks', COUNT(CASE WHEN t.status = 'completed' THEN 1 END),
            'keywords', te.keywords
        ) as context
    FROM task_event te
    LEFT JOIN resource r ON te.manager_id = r.id
    LEFT JOIN task t ON te.id = t.event_id
    WHERE (
        te.name ILIKE '%' || p_query || '%' OR
        te.description ILIKE '%' || p_query || '%' OR
        array_to_string(te.keywords, ' ') ILIKE '%' || p_query || '%' OR
        te.keywords && string_to_array(p_query, ' ')
    )
    GROUP BY te.id, te.name, te.description, te.status, te.keywords, r.name
    
    UNION ALL
    
    -- 업무 검색 (키워드 포함)
    SELECT 
        'task'::text as type,
        t.id,
        t.title,
        t.description,
        t.status,
        t.keywords,
        -- Simple relevance scoring
        (CASE 
            WHEN t.title ILIKE '%' || p_query || '%' THEN 1.0
            WHEN t.description ILIKE '%' || p_query || '%' THEN 0.8
            WHEN array_to_string(t.keywords, ' ') ILIKE '%' || p_query || '%' THEN 0.6
            ELSE 0.3
        END) as relevance,
        json_build_object(
            'event_name', te.name,
            'assigned_name', ar.name,
            'due_date', t.due_date,
            'type', t.type,
            'keywords', t.keywords
        ) as context
    FROM task t
    JOIN task_event te ON t.event_id = te.id
    LEFT JOIN resource ar ON t.assigned_to = ar.id
    WHERE (
        t.title ILIKE '%' || p_query || '%' OR
        t.description ILIKE '%' || p_query || '%' OR
        array_to_string(t.keywords, ' ') ILIKE '%' || p_query || '%' OR
        t.keywords && string_to_array(p_query, ' ')
    )
    
    ORDER BY relevance DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_tasks"("p_query" "text", "p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_day_attendance_rows"("p_date" "date") RETURNS TABLE("room_id" "uuid", "is_attended" boolean, "attendance_status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or not coalesce(public.is_staff_teacher_or_admin(auth.uid()), false) then
    raise exception '교직원만 볼 수 있습니다.' using errcode = '42501';
  end if;
  return query
    select sr.room_id, sr.is_attended, sr.attendance_status
    from public.seat_reservations sr
    where sr.reservation_date = p_date;
end $$;


ALTER FUNCTION "public"."seaton_day_attendance_rows"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_focus_finish"("p_id" "uuid", "p_give_up" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  r public.seaton_focus_runs;
  due timestamptz;
  result text;
  got integer := 0;
begin
  if u is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  select * into r from public.seaton_focus_runs where id = p_id and owner = u for update;
  if not found then raise exception '집중 기록을 찾을 수 없습니다.' using errcode = '42501'; end if;
  if r.ended_at is not null then
    return jsonb_build_object('outcome', r.outcome, 'credit', 0, 'server_now', (extract(epoch from now()) * 1000)::bigint);
  end if;
  due := r.started_at + make_interval(secs => r.planned_seconds);
  if p_give_up then
    result := 'gave_up';
  elsif now() < due then
    return jsonb_build_object('outcome', 'running', 'remaining', ceil(extract(epoch from due - now()))::integer,
      'server_now', (extract(epoch from now()) * 1000)::bigint);
  elsif now() > due + interval '15 minutes' then
    result := 'expired';
  else
    result := 'completed';
  end if;
  if result = 'completed' then got := wallet_private.focus_grant(u, r.id); end if;
  update public.seaton_focus_runs set ended_at = now(), outcome = result, credit = got where id = r.id;
  return jsonb_build_object('outcome', result, 'credit', got,
    'coins', (select coins from public.academy_user_stats where user_id = u),
    'server_now', (extract(epoch from now()) * 1000)::bigint);
end $$;


ALTER FUNCTION "public"."seaton_focus_finish"("p_id" "uuid", "p_give_up" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_focus_start"("p_minutes" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  r public.seaton_focus_runs;
begin
  if u is null or not exists (select 1 from public.profiles where id = u and role = 'student') then
    raise exception '학생 본인만 집중 기록을 시작할 수 있습니다.' using errcode = '42501';
  end if;
  if p_minutes not in (25, 50, 90) then raise exception '25 · 50 · 90분 중에서 골라 주세요.'; end if;
  update public.seaton_focus_runs set ended_at = now(), outcome = 'replaced' where owner = u and ended_at is null;
  insert into public.seaton_focus_runs(owner, planned_seconds) values (u, p_minutes * 60) returning * into r;
  return jsonb_build_object('run', to_jsonb(r) - 'owner', 'server_now', (extract(epoch from now()) * 1000)::bigint);
end $$;


ALTER FUNCTION "public"."seaton_focus_start"("p_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_puzzle_quote"("p_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  cost integer;
  points integer;
  coins integer;
  pay_points integer;
  pay_coins integer;
  staff boolean;
begin
  if u is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  select piece_cost into cost from public.puzzle_events where id = p_event_id;
  if cost is null then raise exception '퍼즐 이벤트를 찾을 수 없습니다.'; end if;
  staff := exists(select 1 from public.profiles where id = u and role in ('teacher', 'admin'));
  select coalesce(sum(amount), 0) into points from public.point_transactions where student_id = u;
  select coalesce((select s.coins from public.academy_user_stats s where s.user_id = u), 100) into coins;
  pay_points := case when staff then 0 else least(greatest(points, 0), cost) end;
  pay_coins := case when staff then 0 else wallet_private.puzzle_coin_cost(cost - pay_points) end;
  return jsonb_build_object(
    'cost_points', cost, 'points', points, 'coins', coins,
    'pay_points', pay_points, 'pay_coins', pay_coins,
    'affordable', staff or pay_coins <= coins, 'free', staff
  );
end $$;


ALTER FUNCTION "public"."seaton_puzzle_quote"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_room_seat_counts"("p_start" "date", "p_end" "date") RETURNS TABLE("room_id" "uuid", "unique_seats" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  if p_start is null or p_end is null or p_start > p_end or p_end - p_start > 400 then
    raise exception '기간을 확인해 주세요.' using errcode = '22023';
  end if;
  return query
    select sr.room_id, count(distinct sr.seat_number)::int
    from public.seat_reservations sr
    where sr.reservation_date between p_start and p_end
    group by sr.room_id;
end $$;


ALTER FUNCTION "public"."seaton_room_seat_counts"("p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_seat_occupancy"("p_room" "uuid", "p_start" "date", "p_end" "date", "p_seat" "text" DEFAULT NULL::"text") RETURNS TABLE("seat_number" "text", "reservation_date" "date", "period_id" integer, "is_mine" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  if p_room is null or p_start is null or p_end is null or p_start > p_end or p_end - p_start > 400 then
    raise exception '열람실과 기간을 확인해 주세요.' using errcode = '22023';
  end if;
  return query
    select sr.seat_number, sr.reservation_date, sr.period_id, (sr.student_id = auth.uid())
    from public.seat_reservations sr
    where sr.room_id = p_room
      and sr.reservation_date between p_start and p_end
      and (p_seat is null or sr.seat_number = p_seat)
    order by sr.reservation_date, sr.seat_number, sr.period_id;
end $$;


ALTER FUNCTION "public"."seaton_seat_occupancy"("p_room" "uuid", "p_start" "date", "p_end" "date", "p_seat" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_stats_students"("p_start" "date", "p_end" "date", "p_grade" integer DEFAULT NULL::integer, "p_room" "uuid" DEFAULT NULL::"uuid", "p_include_future" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c record;
  v_end date;
  v_result jsonb;
begin
  perform seaton_private.require_teacher();
  perform seaton_private.check_range(p_start, p_end);
  select * into c from seaton_private.clock(now());
  v_end := case when p_include_future then p_end else least(p_end, c.today) end;

  with t as (select * from seaton_private.temperature_rule()),
  f as materialized (
    select * from seaton_private.facts(p_start, v_end, p_grade, p_room, c.today, c.past_closing)
  ),
  rooms as (
    select f.room_id, max(f.room_name) as name, bool_or(f.is_morning) as is_morning,
           (row_number() over (order by max(f.room_name), f.room_id)) - 1 as idx
    from f group by f.room_id
  ),
  per_student as (
    select f.student_id, max(f.name) as name, max(f.grade) as grade, max(f.class) as class,
           max(f.number) as number, max(f.sid) as sid,
           count(*) as total, count(*) filter (where f.attended) as attended,
           count(*) filter (where f.absent) as absent, count(*) filter (where f.status = 'pending') as pending,
           round(sum(case when f.attended then t.attend / f.day_n when f.absent then -t.absent / f.day_n else 0 end)
                 + t.feedback * count(*) filter (where f.has_feedback), 1) as temp
    from f cross join t
    group by f.student_id, t.feedback
  ),
  wr as (
    select x.student_id, jsonb_object_agg(x.dow::text, x.idxs) as wr
    from (
      select f.student_id, extract(isodow from f.d)::int as dow, jsonb_agg(distinct rm.idx) as idxs
      from f join rooms rm on rm.room_id = f.room_id
      where extract(isodow from f.d) between 1 and 5
      group by 1, 2
    ) x group by x.student_id
  ),
  per_day as (
    select f.student_id, f.d,
           jsonb_agg(jsonb_build_array(f.period_id, f.status, f.checker_name, rm.idx) order by f.period_id, f.id) as entries
    from f join rooms rm on rm.room_id = f.room_id
    group by f.student_id, f.d
  ),
  att as (
    select pd.student_id, jsonb_object_agg(pd.d::text, pd.entries) as att from per_day pd group by pd.student_id
  )
  select jsonb_build_object(
    'range', jsonb_build_object('start', p_start, 'end', v_end, 'today', c.today, 'past_closing', c.past_closing),
    'rooms', coalesce((select jsonb_agg(jsonb_build_array(rm.room_id, rm.name, rm.is_morning) order by rm.idx) from rooms rm), '[]'::jsonb),
    'students', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.student_id, 'name', s.name, 'grade', s.grade, 'class', s.class, 'number', s.number, 'sid', s.sid,
        'total', s.total, 'attended', s.attended, 'absent', s.absent, 'pending', s.pending,
        'rate', seaton_private.rate(s.attended, s.absent), 'temp', s.temp,
        'wr', '{"1":[],"2":[],"3":[],"4":[],"5":[]}'::jsonb || coalesce(w.wr, '{}'::jsonb),
        'att', coalesce(a.att, '{}'::jsonb)
      ) order by s.grade nulls last, s.class nulls last, s.number nulls last, s.name)
      from per_student s
      left join wr w on w.student_id = s.student_id
      left join att a on a.student_id = s.student_id
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end $$;


ALTER FUNCTION "public"."seaton_stats_students"("p_start" "date", "p_end" "date", "p_grade" integer, "p_room" "uuid", "p_include_future" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_stats_summary"("p_start" "date", "p_end" "date", "p_grade" integer DEFAULT NULL::integer, "p_room" "uuid" DEFAULT NULL::"uuid", "p_include_future" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c record;
  v_end date;
  v_mstart date;
  v_wstart date;
  v_result jsonb;
begin
  perform seaton_private.require_teacher();
  perform seaton_private.check_range(p_start, p_end);
  select * into c from seaton_private.clock(now());
  v_end := case when p_include_future then p_end else least(p_end, c.today) end;
  -- 추이는 기간 필터와 별개로 «끝 날»에서 거꾸로 6개월 · 12주 (seaton 화면과 같은 뜻)
  v_mstart := (date_trunc('month', v_end) - interval '5 months')::date;
  v_wstart := (date_trunc('week', v_end) - interval '11 weeks')::date;

  with f as materialized (
    select * from seaton_private.facts(least(p_start, v_mstart, v_wstart), v_end, p_grade, p_room, c.today, c.past_closing)
  ),
  p as (select * from f where f.d >= p_start),
  months as (
    select generate_series(v_mstart, date_trunc('month', v_end)::date, interval '1 month')::date as m
  ),
  weeks as (
    select generate_series(v_wstart, date_trunc('week', v_end)::date, interval '1 week')::date as w
  ),
  month_agg as (
    select date_trunc('month', f.d)::date as m, f.grade,
           count(*) as total, count(*) filter (where f.attended) as attended, count(*) filter (where f.absent) as absent
    from f group by 1, 2
  ),
  week_agg as (
    select date_trunc('week', f.d)::date as w, f.grade,
           count(*) as total, count(*) filter (where f.attended) as attended, count(*) filter (where f.absent) as absent
    from f where f.d >= v_wstart group by 1, 2
  )
  select jsonb_build_object(
    'range', jsonb_build_object('start', p_start, 'end', v_end, 'today', c.today, 'past_closing', c.past_closing),
    'cards', (
      select jsonb_build_object(
        'total', count(*), 'attended', count(*) filter (where p.attended),
        'absent', count(*) filter (where p.absent), 'pending', count(*) filter (where p.status = 'pending'),
        'rate', seaton_private.rate(count(*) filter (where p.attended), count(*) filter (where p.absent)),
        'students', count(distinct p.student_id), 'rooms', count(distinct p.room_id)
      ) from p
    ),
    'status', (
      select jsonb_build_object(
        'attended', count(*) filter (where p.status = 'attended'),
        'excused', count(*) filter (where p.status = 'excused'),
        'supplement', count(*) filter (where p.status = 'supplement'),
        'absent', count(*) filter (where p.status = 'absent'),
        'pending', count(*) filter (where p.status = 'pending')
      ) from p
    ),
    'by_grade', coalesce((
      select jsonb_agg(g order by g->>'grade') from (
        select jsonb_build_object(
          'grade', p.grade, 'total', count(*), 'attended', count(*) filter (where p.attended),
          'absent', count(*) filter (where p.absent), 'students', count(distinct p.student_id),
          'rate', seaton_private.rate(count(*) filter (where p.attended), count(*) filter (where p.absent))
        ) as g
        from p group by p.grade
      ) x
    ), '[]'::jsonb),
    'monthly', (
      select jsonb_agg(jsonb_build_object(
        'month', to_char(ms.m, 'YYYY-MM'),
        'total', coalesce((select sum(a.total) from month_agg a where a.m = ms.m), 0),
        'attended', coalesce((select sum(a.attended) from month_agg a where a.m = ms.m), 0),
        'absent', coalesce((select sum(a.absent) from month_agg a where a.m = ms.m), 0),
        'rate', seaton_private.rate(
          coalesce((select sum(a.attended) from month_agg a where a.m = ms.m), 0)::bigint,
          coalesce((select sum(a.absent) from month_agg a where a.m = ms.m), 0)::bigint),
        'grades', coalesce((
          select jsonb_object_agg(a.grade::text, jsonb_build_object(
            'total', a.total, 'attended', a.attended, 'absent', a.absent,
            'rate', seaton_private.rate(a.attended, a.absent)))
          from month_agg a where a.m = ms.m and a.grade is not null
        ), '{}'::jsonb)
      ) order by ms.m) from months ms
    ),
    'weekly', (
      select jsonb_agg(jsonb_build_object(
        'week_start', ws.w,
        'total', coalesce((select sum(a.total) from week_agg a where a.w = ws.w), 0),
        'attended', coalesce((select sum(a.attended) from week_agg a where a.w = ws.w), 0),
        'absent', coalesce((select sum(a.absent) from week_agg a where a.w = ws.w), 0),
        'rate', seaton_private.rate(
          coalesce((select sum(a.attended) from week_agg a where a.w = ws.w), 0)::bigint,
          coalesce((select sum(a.absent) from week_agg a where a.w = ws.w), 0)::bigint),
        'grades', coalesce((
          select jsonb_object_agg(a.grade::text, jsonb_build_object(
            'total', a.total, 'attended', a.attended, 'absent', a.absent,
            'rate', seaton_private.rate(a.attended, a.absent)))
          from week_agg a where a.w = ws.w and a.grade is not null
        ), '{}'::jsonb)
      ) order by ws.w) from weeks ws
    ),
    'rooms', coalesce((
      select jsonb_agg(r order by r->>'name') from (
        select jsonb_build_object(
          'room_id', p.room_id, 'name', coalesce(max(p.room_name), '알 수 없음'),
          'room_grade', max(sr.grade), 'room_grades', to_jsonb(max(sr.grades)),
          'total', count(*), 'attended', count(*) filter (where p.attended),
          'absent', count(*) filter (where p.absent), 'pending', count(*) filter (where p.status = 'pending'),
          'students', count(distinct p.student_id),
          'rate', seaton_private.rate(count(*) filter (where p.attended), count(*) filter (where p.absent))
        ) as r
        from p left join public.study_rooms sr on sr.id = p.room_id
        group by p.room_id
      ) x
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end $$;


ALTER FUNCTION "public"."seaton_stats_summary"("p_start" "date", "p_end" "date", "p_grade" integer, "p_room" "uuid", "p_include_future" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_stats_temperature"("p_month" "date" DEFAULT NULL::"date", "p_grade" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c record;
  v_month date;
  v_result jsonb;
begin
  perform seaton_private.require_teacher();
  select * into c from seaton_private.clock(now());
  v_month := date_trunc('month', coalesce(p_month, c.today))::date;

  with t as (select * from seaton_private.temperature_rule()),
  f as materialized (
    select * from seaton_private.facts(date '2000-01-01', c.today, p_grade, null, c.today, c.past_closing)
    where is_student and is_active
  ),
  s as (
    select f.student_id, max(f.name) as name, max(f.grade) as grade, max(f.class) as class, max(f.number) as number,
           sum(case when f.attended then t.attend / f.day_n when f.absent then -t.absent / f.day_n else 0 end)
             + t.feedback * count(*) filter (where f.has_feedback) as score,
           coalesce(sum(case when f.attended then t.attend / f.day_n when f.absent then -t.absent / f.day_n else 0 end)
             filter (where date_trunc('month', f.d) = v_month), 0)
             + t.feedback * count(*) filter (where f.has_feedback and date_trunc('month', f.d) = v_month) as month_score,
           count(distinct f.d) filter (where f.attended and date_trunc('month', f.d) = v_month) as month_days,
           count(*) filter (where date_trunc('month', f.d) = v_month) as month_rows
    from f cross join t
    group by f.student_id, t.feedback
  ),
  ranked as (
    select s.*, round(t.base + s.score, 1) as temperature, round(s.month_score, 1) as month_change,
           rank() over (order by round(t.base + s.score, 1) desc) as rank
    from s cross join t
  )
  select jsonb_build_object(
    'rule', (select to_jsonb(t) from t),
    'today', c.today,
    'month', to_char(v_month, 'YYYY-MM'),
    'cumulative', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rank', r.rank, 'id', r.student_id, 'name', r.name, 'grade', r.grade, 'class', r.class, 'number', r.number,
        'temperature', r.temperature, 'month_change', r.month_change
      ) order by r.rank, r.name) from ranked r
    ), '[]'::jsonb),
    'monthly', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rank', m.rk, 'id', m.student_id, 'name', m.name, 'grade', m.grade, 'class', m.class, 'number', m.number,
        'change', m.month_change, 'attended_days', m.month_days
      ) order by m.rk, m.name)
      from (
        select r.*, rank() over (order by r.month_change desc) as rk from ranked r where r.month_rows > 0
      ) m
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end $$;


ALTER FUNCTION "public"."seaton_stats_temperature"("p_month" "date", "p_grade" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_stats_weekday"("p_start" "date", "p_end" "date", "p_grade" integer DEFAULT NULL::integer, "p_room" "uuid" DEFAULT NULL::"uuid", "p_include_future" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c record;
  v_end date;
  v_result jsonb;
begin
  perform seaton_private.require_teacher();
  perform seaton_private.check_range(p_start, p_end);
  select * into c from seaton_private.clock(now());
  v_end := case when p_include_future then p_end else least(p_end, c.today) end;

  with f as materialized (
    select * from seaton_private.facts(p_start, v_end, p_grade, p_room, c.today, c.past_closing)
  ),
  b as (
    select distinct f.room_id, f.d, f.student_id, extract(isodow from f.d)::int as dow
    from f
  ),
  who as (
    select distinct on (f.student_id) f.student_id, f.name, f.grade, f.class, f.number
    from f order by f.student_id
  ),
  rn as (
    select f.room_id, coalesce(max(f.room_name), '알 수 없음') as name from f group by f.room_id
  )
  select jsonb_build_object(
    'range', jsonb_build_object('start', p_start, 'end', v_end, 'today', c.today),
    'crosstab', coalesce((
      select jsonb_agg(x.row order by x.name) from (
        select rn.name, jsonb_build_object(
          'room_id', b.room_id, 'name', rn.name,
          'by_day', jsonb_build_object(
            '1', count(*) filter (where b.dow = 1), '2', count(*) filter (where b.dow = 2),
            '3', count(*) filter (where b.dow = 3), '4', count(*) filter (where b.dow = 4),
            '5', count(*) filter (where b.dow = 5), '6', count(*) filter (where b.dow = 6),
            '7', count(*) filter (where b.dow = 7)),
          'total', count(*),
          'weekday_total', count(*) filter (where b.dow between 1 and 5),
          'unique_students', count(distinct b.student_id) filter (where b.dow between 1 and 5)
        ) as row
        from b join rn on rn.room_id = b.room_id
        group by b.room_id, rn.name
      ) x
    ), '[]'::jsonb),
    'applicants', (
      select jsonb_object_agg(dd.dow::text, coalesce((
        select jsonb_agg(jsonb_build_object(
          'room_id', y.room_id, 'name', y.name, 'students', y.students) order by y.name)
        from (
          select b.room_id, rn.name,
                 jsonb_agg(jsonb_build_object('id', w.student_id, 'name', w.name, 'grade', w.grade, 'class', w.class, 'number', w.number)
                           order by w.grade nulls last, w.class nulls last, w.number nulls last, w.name) as students
          from (select distinct b2.room_id, b2.student_id from b b2 where b2.dow = dd.dow) b
          join rn on rn.room_id = b.room_id
          join who w on w.student_id = b.student_id
          group by b.room_id, rn.name
        ) y
      ), '[]'::jsonb))
      from generate_series(1, 5) as dd(dow)
    )
  ) into v_result;

  return v_result;
end $$;


ALTER FUNCTION "public"."seaton_stats_weekday"("p_start" "date", "p_end" "date", "p_grade" integer, "p_room" "uuid", "p_include_future" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seaton_wallet_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  today date := (now() at time zone 'Asia/Seoul')::date;
  focus_cap integer := (select daily_cap from tama_private.credit_rule('focus'));
begin
  if u is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  return jsonb_build_object(
    'coins', coalesce((select coins from public.academy_user_stats where user_id = u), 100),
    'legacy_points', coalesce((select sum(amount) from public.point_transactions where student_id = u), 0),
    'review_left', case when exists (select 1 from public.wallet_ledger where user_id = u and earned_on = today and kind = 'seaton_review') then 0 else 1 end,
    'focus_left', greatest(0, focus_cap - (select count(*) from public.tama_credit_ledger where user_id = u and earned_on = today and kind = 'focus')),
    'recent', coalesce((
      select jsonb_agg(jsonb_build_object('delta', l.delta, 'kind', l.kind, 'note', l.note, 'at', l.created_at, 'balance', l.balance_after) order by l.id desc)
      from (select * from public.wallet_ledger where user_id = u order by id desc limit 30) l
    ), '[]'::jsonb),
    'server_now', (extract(epoch from now()) * 1000)::bigint
  );
end $$;


ALTER FUNCTION "public"."seaton_wallet_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_desk_message"("p_recipient_resource_id" "uuid", "p_body" "text", "p_reply_to_notification_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select public.send_desk_message_v2(p_recipient_resource_id, p_body, p_reply_to_notification_id, null);
$$;


ALTER FUNCTION "public"."send_desk_message"("p_recipient_resource_id" "uuid", "p_body" "text", "p_reply_to_notification_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_desk_message_v2"("p_recipient_resource_id" "uuid", "p_body" "text", "p_reply_to_notification_id" "uuid" DEFAULT NULL::"uuid", "p_images" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_me jsonb;
  v_body text := btrim(coalesce(p_body, ''));
  v_recipient public.resource%rowtype;
  v_sent int;
  v_limit int;
  v_original_id uuid;
  v_original_message text;
  v_meta jsonb;
  v_new_id uuid;
  v_linked boolean;
  v_count int := 0;
  v_item jsonb;
  v_data bytea;
  v_mime text;
  v_pics jsonb := '[]'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_total bigint := 0;
  v_recent bigint;
  v_image_id uuid;
  v_status text;
begin
  if v_uid is null then
    raise exception '로그인이 필요합니다' using errcode = '28000';
  end if;

  v_me := public.desk_message_who(v_uid);
  if v_me is null then
    raise exception '학생 또는 선생님으로 연결된 계정만 메시지를 보낼 수 있습니다' using errcode = '42501';
  end if;

  if p_images is not null and jsonb_typeof(p_images) <> 'null' then
    if jsonb_typeof(p_images) <> 'array' then
      raise exception '사진 형식이 올바르지 않습니다' using errcode = '22023';
    end if;
    v_count := jsonb_array_length(p_images);
  end if;
  if v_count > 4 then
    raise exception '사진은 한 번에 4장까지 보낼 수 있습니다' using errcode = '22023';
  end if;

  if v_body = '' and v_count = 0 then
    raise exception '메시지 내용이 비어 있습니다' using errcode = '22023';
  end if;
  if char_length(v_body) > 1000 then
    raise exception '메시지는 1000자까지 보낼 수 있습니다 (지금 %자)', char_length(v_body) using errcode = '22001';
  end if;

  select * into v_recipient
  from public.resource r
  where r.id = p_recipient_resource_id
    and coalesce(r.status, 'active') = 'active'
    and r.type = case when v_me->>'role' = 'student' then 'teacher' else 'student' end;
  if v_recipient.id is null then
    raise exception '받는 사람을 찾을 수 없습니다' using errcode = 'P0002';
  end if;

  -- 학생은 그 선생님과 대화가 진행 중일 때만 보낸다. 선생님이 보내면 아래에서 대화가 열린다.
  if v_me->>'role' = 'student' then
    select s.status into v_status
    from public.desk_message_session s
    where s.student_resource_id = (v_me->>'resource_id')::uuid and s.teacher_resource_id = v_recipient.id;
    if v_status is distinct from 'active' then
      raise exception '%', case when v_status = 'pending' then '선생님이 메시지 요청을 허락하면 보낼 수 있습니다'
                                else '이 선생님께 메시지를 보내려면 먼저 허락을 받아야 합니다. 스페이스기전을 최신 판으로 업데이트한 뒤 용건을 보내 주세요' end
        using errcode = '42501';
    end if;
  end if;

  v_limit := case when v_me->>'role' = 'student' then 30 else 200 end;
  select count(*) into v_sent
  from public.notification_events n
  where n.type = 'desk_message'
    and n.created_at > now() - interval '1 hour'
    and n.meta->>'sender_resource_id' = v_me->>'resource_id';
  if v_sent >= v_limit then
    raise exception '한 시간에 %건까지 보낼 수 있습니다. 잠시 뒤에 다시 보내 주세요', v_limit using errcode = '54000';
  end if;

  -- 사진: 형식(첫 바이트로 확인)·크기. 아직 넣지 않고 id 만 정해 둔다 — 알림 meta 에 함께 적으려고
  for v_item in select value from jsonb_array_elements(coalesce(p_images, '[]'::jsonb)) loop
    v_mime := v_item->>'mime';
    begin
      v_data := decode(coalesce(v_item->>'data', ''), 'base64');
    exception when others then
      raise exception '사진 파일이 올바르지 않습니다' using errcode = '22023';
    end;
    if octet_length(v_data) < 16 or octet_length(v_data) > 1572864 then
      raise exception '사진 한 장은 1.5MB 까지 보낼 수 있습니다' using errcode = '22023';
    end if;
    if not ((v_mime = 'image/jpeg' and substring(v_data from 1 for 3) = '\xffd8ff'::bytea)
         or (v_mime = 'image/png' and substring(v_data from 1 for 8) = '\x89504e470d0a1a0a'::bytea)
         or (v_mime = 'image/webp' and substring(v_data from 1 for 4) = '\x52494646'::bytea
             and substring(v_data from 9 for 4) = '\x57454250'::bytea)) then
      raise exception '사진은 JPEG·PNG·WebP 만 보낼 수 있습니다' using errcode = '22023';
    end if;
    if coalesce((v_item->>'width')::int, 0) not between 1 and 8000
       or coalesce((v_item->>'height')::int, 0) not between 1 and 8000 then
      raise exception '사진 크기가 올바르지 않습니다' using errcode = '22023';
    end if;
    v_total := v_total + octet_length(v_data);
    v_image_id := gen_random_uuid();
    v_pics := v_pics || jsonb_build_array(jsonb_build_object(
      'id', v_image_id, 'w', (v_item->>'width')::int, 'h', (v_item->>'height')::int));
    v_rows := v_rows || jsonb_build_array(jsonb_build_object('id', v_image_id, 'mime', v_mime,
      'width', (v_item->>'width')::int, 'height', (v_item->>'height')::int, 'data', v_item->>'data'));
  end loop;

  -- 사진 하루 한도 (학생 30MB, 교직원 150MB) — 서버에 7일 쌓이는 양을 묶는다
  if v_count > 0 then
    select coalesce(sum(i.bytes), 0) into v_recent
    from public.desk_message_images i
    where i.sender_resource_id = (v_me->>'resource_id')::uuid
      and i.created_at > now() - interval '1 day';
    if v_recent + v_total > (case when v_me->>'role' = 'student' then 31457280 else 157286400 end) then
      raise exception '오늘 보낼 수 있는 사진 양을 넘었습니다. 내일 다시 보내 주세요' using errcode = '54000';
    end if;
  end if;

  if p_reply_to_notification_id is not null then
    select n.id, n.message into v_original_id, v_original_message
    from public.notification_events n
    where n.id = p_reply_to_notification_id
      and public.owns_notification_resource(n.resource_id);
  end if;

  v_meta := jsonb_build_object(
    'source', 'spacekijun_desk',
    'sender_resource_id', v_me->>'resource_id',
    'sender_name', v_me->>'name',
    'sender_role', v_me->>'role',
    'sender_label', v_me->>'label');
  if v_count > 0 then
    v_meta := v_meta || jsonb_build_object('images', v_pics, 'photo_only', v_body = '');
  end if;
  if v_original_id is not null then
    v_meta := v_meta || jsonb_build_object('reply_to_notification_id', v_original_id,
                                           'quote', left(coalesce(v_original_message, ''), 300));
  end if;

  -- 사진만 보내면 알림 글은 '사진 N장' (스페이스기전 알림함에도 그렇게 보인다)
  insert into public.notification_events (resource_id, type, title, message, meta, priority)
  values (v_recipient.id, 'desk_message', '[메시지] ' || (v_me->>'label'),
          case when v_body = '' then format('사진 %s장', v_count) else v_body end, v_meta, 'medium')
  returning id into v_new_id;

  insert into public.desk_message_images (id, notification_id, sender_resource_id, recipient_resource_id,
                                          mime, width, height, bytes, data)
  select (r->>'id')::uuid, v_new_id, (v_me->>'resource_id')::uuid, v_recipient.id, r->>'mime',
         (r->>'width')::int, (r->>'height')::int, octet_length(decode(r->>'data', 'base64')), decode(r->>'data', 'base64')
  from jsonb_array_elements(v_rows) r;

  if v_original_id is not null then
    update public.notification_events
       set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('replied_at', now()),
           is_read = true
     where id = v_original_id;
  end if;

  if v_me->>'role' = 'teacher' then
    insert into public.desk_message_session (student_resource_id, teacher_resource_id, status, decided_at)
    values (v_recipient.id, (v_me->>'resource_id')::uuid, 'active', now())
    on conflict (student_resource_id, teacher_resource_id)
    do update set status = 'active', decided_at = now()
      where public.desk_message_session.status <> 'active';
  end if;

  if v_recipient.type = 'student' then
    select exists (select 1 from public.profiles p
                   where p.role = 'student' and split_part(p.email, '@', 1) = v_recipient.meta->>'id')
      into v_linked;
  else
    select exists (select 1 from public.user_resource ur where ur.resource_id = v_recipient.id) into v_linked;
  end if;

  return jsonb_build_object('notification_id', v_new_id, 'recipient_resource_id', v_recipient.id,
                            'recipient_name', v_recipient.name, 'recipient_linked', v_linked,
                            'images', v_pics);
end;
$$;


ALTER FUNCTION "public"."send_desk_message_v2"("p_recipient_resource_id" "uuid", "p_body" "text", "p_reply_to_notification_id" "uuid", "p_images" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_notification_reply"("p_recipient_resource_id" "uuid", "p_body" "text", "p_reply_to_notification_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_body text := btrim(coalesce(p_body, ''));
  v_sender_id uuid;
  v_sender_name text;
  v_recipient_id uuid;
  v_recipient_name text;
  v_original_id uuid;
  v_original_type text;
  v_original_message text;
  v_meta jsonb;
  v_new_id uuid;
  v_linked boolean;
begin
  -- 3값 논리 함정: auth.uid() 가 NULL 이면 아래 비교가 NULL 이 되어 가드를 통과한다 → 맨 앞에서 끊는다
  if v_uid is null then
    raise exception '로그인이 필요합니다' using errcode = '28000';
  end if;

  if not public.is_staff_teacher_or_admin(v_uid) then
    raise exception '교직원만 답장을 보낼 수 있습니다' using errcode = '42501';
  end if;

  if v_body = '' then
    raise exception '답장 내용이 비어 있습니다' using errcode = '22023';
  end if;

  if char_length(v_body) > 2000 then
    raise exception '답장은 2000자까지 보낼 수 있습니다 (현재 %자)', char_length(v_body)
      using errcode = '22001';
  end if;

  -- 보낸 사람: 내 계정에 연결된 교직원 리소스 (교사 우선 → 이름순, 결정적)
  select r.id, r.name
    into v_sender_id, v_sender_name
  from public.user_resource ur
  join public.resource r on r.id = ur.resource_id
  where ur.user_id = v_uid
    and r.type in ('teacher', 'staff')
  order by (r.type = 'teacher') desc, r.name
  limit 1;

  if v_sender_id is null then
    raise exception '내 계정에 교직원 정보가 연결되어 있지 않아 보낸 사람을 표시할 수 없습니다'
      using errcode = 'P0002';
  end if;

  -- 받는 사람: 재직 중인 교직원
  select r.id, r.name
    into v_recipient_id, v_recipient_name
  from public.resource r
  where r.id = p_recipient_resource_id
    and r.type in ('teacher', 'staff')
    and coalesce(r.status, 'active') = 'active';

  if v_recipient_id is null then
    raise exception '받는 사람을 교직원 명단에서 찾을 수 없습니다' using errcode = 'P0002';
  end if;

  -- 답장 대상(원래 알림): **내 알림일 때만** 인용한다. 남의 알림 id 를 주면 조용히 인용을 생략한다
  -- (존재 여부를 알려 주는 오라클이 되지 않게 오류를 내지 않는다).
  if p_reply_to_notification_id is not null then
    select n.id, n.type, n.message
      into v_original_id, v_original_type, v_original_message
    from public.notification_events n
    where n.id = p_reply_to_notification_id
      and public.owns_notification_resource(n.resource_id);
  end if;

  v_meta := jsonb_build_object(
    'source', 'spacekijun_reply',
    'sender_resource_id', v_sender_id,
    'sender_name', v_sender_name
  );
  if v_original_id is not null then
    v_meta := v_meta || jsonb_build_object(
      'reply_to_notification_id', v_original_id,
      'reply_to_type', v_original_type,
      'quote', left(coalesce(v_original_message, ''), 300)
    );
  end if;

  insert into public.notification_events (resource_id, type, title, message, meta, priority)
  values (v_recipient_id, 'direct_reply', '[답장] ' || v_sender_name, v_body, v_meta, 'medium')
  returning id into v_new_id;

  -- 원래 알림에 "답장함" 흔적 — 같은 쪽지에 두 번 답하는 일을 줄인다. 답했으면 읽은 것이다.
  if v_original_id is not null then
    update public.notification_events
       set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object(
             'replied_at', now(),
             'replied_to_resource_id', v_recipient_id,
             'replied_to_name', v_recipient_name
           ),
           is_read = true
     where id = v_original_id;
  end if;

  -- 받는 사람이 SPACEKIJUN 에 한 번도 로그인하지 않았으면(연결 없음) 알림은 저장되지만
  -- 로그인해서 연결하기 전까지는 아무도 못 본다 → 화면이 그 사실을 말할 수 있게 돌려준다.
  select exists (select 1 from public.user_resource ur where ur.resource_id = v_recipient_id)
    into v_linked;

  return jsonb_build_object(
    'notification_id', v_new_id,
    'recipient_resource_id', v_recipient_id,
    'recipient_name', v_recipient_name,
    'recipient_linked', v_linked
  );
end;
$$;


ALTER FUNCTION "public"."send_notification_reply"("p_recipient_resource_id" "uuid", "p_body" "text", "p_reply_to_notification_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."send_notification_reply"("p_recipient_resource_id" "uuid", "p_body" "text", "p_reply_to_notification_id" "uuid") IS '알림 [답장] — 교직원이 교직원에게 SPACEKIJUN 알림(type=direct_reply)으로 답한다. 보낸 사람·인용은 서버가 유도';



CREATE OR REPLACE FUNCTION "public"."send_task_message"("p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_action   public.task_action;
  v_cfg      jsonb;
  v_title    text;
  v_body     text;
  v_task     text;
  v_res      jsonb;
  v_ids      uuid[];
  v_names    text[];
  v_unlinked text[];
  v_sender   uuid;
  v_sender_n text;
  v_n        int := 0;
  v_send_id  uuid;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into v_action from public.task_action where id = p_action_id;
  if not found or v_action.action_type <> 'message.send' then
    raise exception '메시지 보내기 작업이 아닙니다' using errcode = 'P0002';
  end if;
  if not public.can_manage_task_action(p_action_id) then
    raise exception '이 작업을 만든 사람과 업무 책임자만 보낼 수 있습니다' using errcode = '42501';
  end if;

  v_cfg   := coalesce(v_action.config->'message', '{}'::jsonb);
  v_body  := btrim(coalesce(v_cfg->>'body', ''));
  select title into v_task from public.task where id = v_action.task_id;
  v_title := coalesce(nullif(btrim(v_cfg->>'title'), ''), v_task, '메시지');
  if v_body = '' then raise exception '보낼 본문이 없습니다' using errcode = '22023'; end if;

  v_res := public.resolve_audience(public.expand_task_audience(coalesce(v_cfg->'audience', '{}'::jsonb), v_action.task_id), 'person', null, null);

  select array_agg(distinct (r.value->>'resource_id')::uuid),
         array_agg(distinct r.value->>'name') filter (where r.value->>'resource_id' is not null)
    into v_ids, v_names
  from jsonb_array_elements(v_res->'rows') r
  where r.value->>'resource_id' is not null;

  select array_agg(distinct r.value->>'name')
    into v_unlinked
  from jsonb_array_elements(v_res->'rows') r
  where r.value->>'resource_id' is null;

  if coalesce(cardinality(v_ids), 0) = 0 then
    raise exception '받을 사람이 없습니다' using errcode = '22023';
  end if;

  select me, r.name into v_sender, v_sender_n
  from public.current_actor_resource_ids() me join public.resource r on r.id = me limit 1;

  insert into public.task_message_send (action_id, task_id, sender_resource_id, sender_name, title, body,
                                        rule_snapshot, recipient_ids, recipient_names, unlinked_names)
  values (p_action_id, v_action.task_id, v_sender, v_sender_n, v_title, v_body,
          coalesce(v_cfg->'audience', '{}'::jsonb), v_ids, coalesce(v_names, '{}'), coalesce(v_unlinked, '{}'))
  returning id into v_send_id;

  insert into public.notification_events (type, title, message, resource_id, is_read, meta)
  select 'task_message', v_title, v_body, rid, false,
         jsonb_build_object('action_id', p_action_id, 'task_id', v_action.task_id, 'task_title', v_task,
                            'send_id', v_send_id, 'sender_name', v_sender_n)
  from unnest(v_ids) rid;
  get diagnostics v_n = row_count;

  return jsonb_build_object('send_id', v_send_id, 'notified', v_n,
                            'recipient_names', to_jsonb(coalesce(v_names, '{}')),
                            'unlinked_names', to_jsonb(coalesce(v_unlinked, '{}')));
end;
$$;


ALTER FUNCTION "public"."send_task_message"("p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_collect_request_status"("p_action_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not public.can_manage_collect(p_action_id) then
    raise exception '작업을 만든 사람과 업무 책임자만 마감할 수 있습니다' using errcode = '42501';
  end if;
  if p_status not in ('open', 'closed') then raise exception '알 수 없는 상태' using errcode = '22023'; end if;
  update public.collect_request
     set status = p_status,
         closed_at = case when p_status = 'closed' then now() end,
         closed_reason = case when p_status = 'closed' then 'manual' end
   where action_id = p_action_id;
  if not found then raise exception '아직 보내지 않은 요청입니다' using errcode = 'P0002'; end if;
end;
$$;


ALTER FUNCTION "public"."set_collect_request_status"("p_action_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_department_members"("p_department_id" "uuid", "p_academic_year" integer, "p_resource_ids" "uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_count int;
begin
  if auth.uid() is null or not public.is_admin() then
    raise exception '관리자만 부서원을 바꿀 수 있습니다' using errcode = '42501';
  end if;
  if p_academic_year is null or p_academic_year < 2000 then
    raise exception '학년도가 필요합니다' using errcode = '22023';
  end if;

  delete from public.department_member
   where department_id = p_department_id
     and academic_year = p_academic_year
     and not (resource_id = any (coalesce(p_resource_ids, '{}'::uuid[])));

  insert into public.department_member (department_id, resource_id, academic_year)
  select p_department_id, rid, p_academic_year
  from unnest(coalesce(p_resource_ids, '{}'::uuid[])) as rid
  on conflict (department_id, resource_id, academic_year) do nothing;

  select count(*) into v_count
  from public.department_member
  where department_id = p_department_id and academic_year = p_academic_year;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."set_department_members"("p_department_id" "uuid", "p_academic_year" integer, "p_resource_ids" "uuid"[]) OWNER TO "postgres";


