CREATE OR REPLACE FUNCTION "public"."set_inquiry_recommendation_generated"("p_id" "uuid", "p_selected_weakness_ids" "jsonb", "p_selected_anchor_subjects" "jsonb", "p_user_notes" "text", "p_recommendations" "jsonb", "p_ai_provider" "text", "p_ai_model" "text", "p_token_usage" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_student_id text;
BEGIN
  SELECT student_id INTO v_student_id
    FROM public.student_inquiry_recommendations
   WHERE id = p_id;
  IF v_student_id IS NULL THEN
    RAISE EXCEPTION 'recommendation % not found', p_id;
  END IF;
  IF NOT public.inquiry_design_can_access_student(v_student_id) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  UPDATE public.student_inquiry_recommendations
     SET selected_weakness_ids = p_selected_weakness_ids,
         selected_anchor_subjects = p_selected_anchor_subjects,
         user_notes = p_user_notes,
         recommendations = p_recommendations,
         ai_provider = p_ai_provider,
         ai_model = p_ai_model,
         token_usage = COALESCE(p_token_usage, '{}'::jsonb),
         generated_at = now()
   WHERE id = p_id;
END;
$$;


