CREATE OR REPLACE FUNCTION "public"."set_purchase_order_batch_status"("p_batch_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_batch   public.purchase_order_batches%rowtype;
  v_target  text;
  v_group   record;
  v_updated integer := 0;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;

  select * into v_batch from public.purchase_order_batches where id = p_batch_id for update;
  if not found then
    raise exception '품의 차수를 찾을 수 없습니다.' using errcode = 'P0002';
  end if;

  if not public.is_purchase_page_manager(v_batch.page_id) then
    raise exception '품의 차수는 페이지 작성자·공동 작업자만 바꿀 수 있습니다.' using errcode = '42501';
  end if;

  if p_status is null or p_status not in ('draft', 'submitted', 'purchased') then
    raise exception '알 수 없는 품의 상태: %', coalesce(p_status, '(null)') using errcode = '22023';
  end if;

  update public.purchase_order_batches
     set status = p_status,
         status_updated_at = now()
   where id = p_batch_id;

  v_target := case p_status when 'submitted' then 'approved'
                            when 'purchased' then 'completed'
                            else null end;

  if v_target is not null then
    for v_group in
      with linked as (
        select li.request_id, li.row_id,
               coalesce(r.meta -> 'itemStatus' -> li.row_id ->> 'status', r.status) as cur_status,
               case when r.meta -> 'itemStatus' -> li.row_id is not null
                    then r.meta -> 'itemStatus' -> li.row_id ->> 'reason'
                    else r.status_reason end as cur_reason
          from public.purchase_order_line_items li
          join public.purchase_order_lines l on l.id = li.line_id
          join public.purchase_requests r on r.id = li.request_id
         where l.batch_id = p_batch_id
           -- 신청자가 지운 행은 건너뛴다(고아 연결)
           and exists (
             select 1 from jsonb_array_elements(coalesce(r.items, '[]'::jsonb)) it
              where it ->> 'id' = li.row_id
           )
      )
      select request_id, cur_reason, array_agg(row_id) as row_ids
        from linked
       where (v_target = 'approved'  and cur_status in ('submitted', 'pending'))
          or (v_target = 'completed' and cur_status not in ('completed', 'rejected'))
       group by request_id, cur_reason
    loop
      perform public.set_purchase_request_item_status(
        v_group.request_id, v_target, v_group.row_ids, v_group.cur_reason
      );
      v_updated := v_updated + coalesce(array_length(v_group.row_ids, 1), 0);
    end loop;
  end if;

  return jsonb_build_object('status', p_status, 'updatedItems', v_updated);
end;
$$;


ALTER FUNCTION "public"."set_purchase_order_batch_status"("p_batch_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_purchase_request_item_status"("p_request_id" "uuid", "p_status" "text", "p_row_ids" "text"[] DEFAULT NULL::"text"[], "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_req      public.purchase_requests%rowtype;
  v_map      jsonb;
  v_targets  text[];
  v_row      text;
  v_reason   text := nullif(btrim(coalesce(p_reason, '')), '');
  v_now      timestamptz := now();
  v_actor    text;
  v_rowcount int;
  v_whole    boolean;
  v_status   text;
BEGIN
  SELECT * INTO v_req FROM public.purchase_requests WHERE id = p_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '신청을 찾을 수 없습니다.' USING ERRCODE = 'P0002';
  END IF;

  IF NOT is_purchase_page_manager(v_req.page_id) THEN
    RAISE EXCEPTION '품목 상태는 페이지 작성자·공동 작업자만 변경할 수 있습니다.' USING ERRCODE = '42501';
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('submitted', 'pending', 'approved', 'completed', 'rejected') THEN
    RAISE EXCEPTION '알 수 없는 상태: %', coalesce(p_status, '(null)') USING ERRCODE = '22023';
  END IF;

  v_actor := current_profile_name();

  SELECT count(*) INTO v_rowcount
  FROM jsonb_array_elements(coalesce(v_req.items, '[]'::jsonb)) it
  WHERE coalesce(it->>'id', '') <> '';

  -- 품목이 없는 신청(방어) — 종전처럼 신청 상태만 바꾼다
  IF v_rowcount = 0 THEN
    UPDATE public.purchase_requests
       SET status = p_status,
           status_reason = v_reason,
           status_updated_at = v_now
     WHERE id = p_request_id;
    RETURN jsonb_build_object('status', p_status, 'itemStatus', '{}'::jsonb);
  END IF;

  -- 기준선: 품목 상태가 아직 없으면 현재 신청 상태로 전 품목을 채운다.
  -- 이걸 안 하면 "설정 안 된 품목은 신청 상태를 따른다" 폴백과 파생이 서로를 참조해 순환한다.
  v_map := coalesce(v_req.meta -> 'itemStatus', '{}'::jsonb);
  IF v_map = '{}'::jsonb THEN
    SELECT coalesce(jsonb_object_agg(
             it->>'id',
             jsonb_strip_nulls(jsonb_build_object(
               'status', v_req.status,
               'reason', v_req.status_reason,
               'at', to_char(coalesce(v_req.status_updated_at, v_req.updated_at) AT TIME ZONE 'UTC',
                             'YYYY-MM-DD"T"HH24:MI:SS"Z"')
             ))
           ), '{}'::jsonb)
      INTO v_map
      FROM jsonb_array_elements(coalesce(v_req.items, '[]'::jsonb)) it
     WHERE coalesce(it->>'id', '') <> '';
  END IF;

  IF p_row_ids IS NULL THEN
    SELECT coalesce(array_agg(it->>'id'), '{}'::text[]) INTO v_targets
    FROM jsonb_array_elements(coalesce(v_req.items, '[]'::jsonb)) it
    WHERE coalesce(it->>'id', '') <> '';
  ELSE
    -- 신청자가 그 사이 지운 행은 조용히 무시한다
    SELECT coalesce(array_agg(it->>'id'), '{}'::text[]) INTO v_targets
    FROM jsonb_array_elements(coalesce(v_req.items, '[]'::jsonb)) it
    WHERE it->>'id' = ANY (p_row_ids);
  END IF;

  IF coalesce(array_length(v_targets, 1), 0) = 0 THEN
    RAISE EXCEPTION '대상 품목을 찾을 수 없습니다.' USING ERRCODE = 'P0002';
  END IF;

  v_whole := array_length(v_targets, 1) = v_rowcount;

  FOREACH v_row IN ARRAY v_targets LOOP
    v_map := v_map || jsonb_build_object(v_row, jsonb_strip_nulls(jsonb_build_object(
      'status', p_status,
      'reason', v_reason,
      'at', to_char(v_now AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'by', v_actor
    )));
  END LOOP;

  -- 삭제된 품목의 잔재 정리
  SELECT coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) INTO v_map
  FROM jsonb_each(v_map) e
  WHERE EXISTS (
    SELECT 1 FROM jsonb_array_elements(coalesce(v_req.items, '[]'::jsonb)) it
    WHERE it->>'id' = e.key
  );

  v_status := public.purchase_derive_request_status(v_map, v_req.status);

  UPDATE public.purchase_requests
     SET meta = jsonb_set(coalesce(meta, '{}'::jsonb), '{itemStatus}', v_map, true),
         status = v_status,
         -- 일부 품목만 바꾸면 신청건 전체를 설명하던 사유는 더 이상 맞지 않는다.
         -- (기준선에서 각 품목이 그 사유를 이미 복사해 갔으므로 정보는 사라지지 않는다)
         status_reason = CASE WHEN v_whole THEN v_reason ELSE NULL END,
         status_updated_at = v_now
   WHERE id = p_request_id;

  RETURN jsonb_build_object('status', v_status, 'itemStatus', v_map);
END;
$$;


ALTER FUNCTION "public"."set_purchase_request_item_status"("p_request_id" "uuid", "p_status" "text", "p_row_ids" "text"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_purchase_request_item_status"("p_request_id" "uuid", "p_status" "text", "p_row_ids" "text"[], "p_reason" "text") IS '구매 신청 품목 단위 승인. p_row_ids NULL 또는 전 품목이면 신청건 전체 변경. 매니저만 호출 가능하고 신청 status 를 품목 상태에서 파생한다.';



CREATE OR REPLACE FUNCTION "public"."set_rescue_status"("p_student_code" "text", "p_status" "public"."rescue_status", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT can_care_student(p_student_code) THEN
    RAISE EXCEPTION 'access denied for student %', p_student_code USING ERRCODE = '42501';
  END IF;
  INSERT INTO rescue_student_status (student_code, status, updated_by, reason)
  VALUES (p_student_code, p_status, auth.uid(), p_reason)
  ON CONFLICT (student_code) DO UPDATE
  SET status = EXCLUDED.status,
      updated_by = EXCLUDED.updated_by,
      updated_at = now(),
      reason = EXCLUDED.reason;
END;
$$;


ALTER FUNCTION "public"."set_rescue_status"("p_student_code" "text", "p_status" "public"."rescue_status", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_signature_drive_file"("p_request_id" "uuid", "p_file_id" "text", "p_link" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_request public.signature_request;
begin
  select * into v_request from public.signature_request where id = p_request_id for update;
  if not found then
    raise exception '서명 요청을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not public.can_view_signature_request(p_request_id) then
    raise exception '권한이 없습니다.' using errcode = '42501';
  end if;
  if v_request.status <> 'completed' then
    raise exception '완료된 요청만 보관할 수 있습니다.' using errcode = '22023';
  end if;
  if coalesce(btrim(p_file_id), '') = '' then
    raise exception 'Drive 파일 id 가 비어 있습니다.' using errcode = '22023';
  end if;

  update public.signature_request
     set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object(
           'drive', jsonb_build_object(
             'file_id', p_file_id,
             'link', p_link,
             'uploaded_at', now(),
             -- 누가 올렸는지 — 사용자 OAuth 라 파일 소유자가 그 사람이 된다
             'uploaded_by', public.current_profile_name()
           )
         ),
         -- 옮겼으므로 Storage 완성본은 더 이상 정본이 아니다
         signed_path = null,
         updated_at = now()
   where id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."set_signature_drive_file"("p_request_id" "uuid", "p_file_id" "text", "p_link" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_signature_due"("p_request_id" "uuid", "p_due_at" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  r   record;
  v_max timestamptz;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  select id, requester_user_id, status, purged_at, created_at, meta into r
    from public.signature_request where id = p_request_id for update;
  if r.id is null then
    raise exception '요청을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not coalesce(r.requester_user_id = auth.uid(), false) and not public.is_admin() then
    raise exception '요청한 사람만 마감일을 바꿀 수 있습니다.' using errcode = '42501';
  end if;
  if r.status <> 'pending' or r.purged_at is not null then
    raise exception '진행 중인 요청만 마감일을 바꿀 수 있습니다.' using errcode = '22023';
  end if;
  if p_due_at is null or p_due_at < now() + interval '1 hour' then
    raise exception '마감은 지금부터 1시간 뒤 이후로 정해 주세요.' using errcode = '22023';
  end if;
  v_max := r.created_at + make_interval(days => public.signature_due_max_days());
  if p_due_at > v_max then
    raise exception '마감은 요청한 날부터 %일 안으로 정해 주세요.', public.signature_due_max_days() using errcode = '22023';
  end if;

  update public.signature_request
     set due_at = p_due_at,
         -- 마감을 늦췄으면 «곧 정리» 경고를 다시 보낼 수 있게
         meta = case when p_due_at > now() + interval '3 days' then coalesce(meta, '{}'::jsonb) - 'purge_warned_at' else meta end,
         updated_at = now()
   where id = p_request_id;
  return p_due_at;
end;
$$;


ALTER FUNCTION "public"."set_signature_due"("p_request_id" "uuid", "p_due_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_signature_request_signed_path"("p_request_id" "uuid", "p_signed_path" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_request public.signature_request;
begin
  select * into v_request from public.signature_request where id = p_request_id for update;
  if not found then
    raise exception '서명 요청을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not public.can_view_signature_request(p_request_id) then
    raise exception '권한이 없습니다.' using errcode = '42501';
  end if;
  if v_request.status <> 'completed' then
    raise exception '아직 모든 서명이 끝나지 않았습니다.' using errcode = '22023';
  end if;

  update public.signature_request
     set signed_path = p_signed_path, updated_at = now()
   where id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."set_signature_request_signed_path"("p_request_id" "uuid", "p_signed_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_signature_source_path"("p_request_id" "uuid", "p_source_path" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_request public.signature_request;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '28000';
  end if;

  select * into v_request from public.signature_request where id = p_request_id for update;
  if not found then
    raise exception '서명 요청을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not coalesce(v_request.requester_user_id = auth.uid(), false) then
    raise exception '요청자만 원본을 등록할 수 있습니다.' using errcode = '42501';
  end if;
  if v_request.source_path <> 'pending' then
    raise exception '원본 문서는 다시 바꿀 수 없습니다.' using errcode = '22023';
  end if;
  if coalesce(btrim(p_source_path), '') = '' then
    raise exception '원본 경로가 비어 있습니다.' using errcode = '22023';
  end if;

  update public.signature_request
     set source_path = p_source_path, updated_at = now()
   where id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."set_signature_source_path"("p_request_id" "uuid", "p_source_path" "text") OWNER TO "postgres";


