CREATE OR REPLACE FUNCTION "public"."set_task_assignee_status"("p_task_id" "uuid", "p_assignee_resource_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  actor_resource_id UUID;
  task_event_id UUID;
  current_meta JSONB;
  current_assignees JSONB;
  updated_assignees JSONB := '[]'::JSONB;
  event_meta JSONB;
  event_manager_id UUID;
  assignee JSONB;
  updated_assignee JSONB;
  old_status TEXT;
  actor_is_manager BOOLEAN := FALSE;
  assignee_found BOOLEAN := FALSE;
  all_completed BOOLEAN := FALSE;
  aggregate_task_status TEXT;
  submission_required BOOLEAN := FALSE;
  submission_count INT := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('pending', 'completed', 'cancelled') THEN
    RAISE EXCEPTION 'Invalid assignee status: %', p_status USING ERRCODE = '22023';
  END IF;

  SELECT ur.resource_id
  INTO actor_resource_id
  FROM public.user_resource ur
  WHERE ur.user_id = auth.uid()
  ORDER BY ur.created_at
  LIMIT 1;

  -- Student accounts created from roster imports may not have a user_resource
  -- row. Match the same email-prefix identity fallback used by unifiedAuth.
  IF actor_resource_id IS NULL THEN
    SELECT r.id
    INTO actor_resource_id
    FROM public.profiles p
    JOIN public.resource r
      ON r.type = 'student'
      AND r.meta->>'id' = SPLIT_PART(p.email, '@', 1)
    WHERE p.id = auth.uid()
    LIMIT 1;
  END IF;

  IF actor_resource_id IS NULL THEN
    RAISE EXCEPTION 'User resource not found' USING ERRCODE = '42501';
  END IF;

  SELECT t.event_id, COALESCE(t.meta, '{}'::JSONB), COALESCE(e.meta, '{}'::JSONB), e.manager_id
  INTO task_event_id, current_meta, event_meta, event_manager_id
  FROM public.task t
  JOIN public.work e ON e.id = t.event_id
  WHERE t.id = p_task_id
  FOR UPDATE OF t;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Task not found: %', p_task_id USING ERRCODE = 'P0002';
  END IF;

  -- 과제 단위 업무: 완료는 단위별 체크(set_task_unit_status)로만 관리한다.
  IF jsonb_typeof(current_meta->'units') = 'array'
     AND jsonb_array_length(current_meta->'units') > 0 THEN
    RAISE EXCEPTION 'This task is managed by units. Use set_task_unit_status instead.'
      USING ERRCODE = '0A000';
  END IF;

  -- 제출 업무 가드: "완료인데 제출물 없음" 을 만들지 못하게 한다.
  submission_required := COALESCE((current_meta->'submission'->>'required')::BOOLEAN, FALSE);
  IF submission_required AND p_status = 'completed' THEN
    SELECT COUNT(*) INTO submission_count
    FROM public.task_submission s
    WHERE s.task_id = p_task_id
      AND s.assignee_resource_id = p_assignee_resource_id;

    IF submission_count = 0 THEN
      RAISE EXCEPTION 'This task requires a submission. Complete it by submitting, not by toggling status.'
        USING ERRCODE = '0A000';
    END IF;
  END IF;

  current_assignees := CASE
    WHEN jsonb_typeof(current_meta->'assignees') = 'array'
      THEN current_meta->'assignees'
    ELSE '[]'::JSONB
  END;

  -- Support both the retained manager_id and the multi-manager metadata.
  actor_is_manager :=
    COALESCE(event_manager_id = actor_resource_id, FALSE)
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(event_meta->'managers') = 'array'
            THEN event_meta->'managers'
          ELSE '[]'::JSONB
        END
      ) AS manager(value)
      WHERE CASE
        WHEN jsonb_typeof(value) = 'object' THEN value->>'id'
        ELSE TRIM(BOTH '"' FROM value::TEXT)
      END = actor_resource_id::TEXT
    );

  FOR assignee IN
    SELECT value FROM jsonb_array_elements(current_assignees)
  LOOP
    IF assignee->>'id' = p_assignee_resource_id::TEXT THEN
      assignee_found := TRUE;
      old_status := COALESCE(assignee->>'status', 'pending');

      IF actor_resource_id <> p_assignee_resource_id AND NOT actor_is_manager THEN
        RAISE EXCEPTION 'Only the assignee or an work manager can update this status'
          USING ERRCODE = '42501';
      END IF;

      updated_assignee := jsonb_set(
        assignee,
        '{status}',
        to_jsonb(p_status),
        TRUE
      );
      updated_assignee := jsonb_set(
        updated_assignee,
        '{completed_at}',
        CASE
          WHEN p_status = 'completed' THEN to_jsonb(NOW())
          ELSE 'null'::JSONB
        END,
        TRUE
      );
      updated_assignees := updated_assignees || jsonb_build_array(updated_assignee);
    ELSE
      updated_assignees := updated_assignees || jsonb_build_array(assignee);
    END IF;
  END LOOP;

  IF NOT assignee_found THEN
    RAISE EXCEPTION 'Assignee % is not assigned to task %', p_assignee_resource_id, p_task_id
      USING ERRCODE = 'P0002';
  END IF;

  SELECT NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(updated_assignees) AS item(value)
    WHERE COALESCE(value->>'status', 'pending') <> 'completed'
  )
  INTO all_completed;

  aggregate_task_status := CASE
    WHEN all_completed AND jsonb_array_length(updated_assignees) > 0 THEN 'completed'
    ELSE 'pending'
  END;

  UPDATE public.task
  SET
    meta = jsonb_set(current_meta, '{assignees}', updated_assignees, TRUE),
    status = CASE
      WHEN status = 'cancelled' THEN status
      ELSE aggregate_task_status
    END,
    updated_at = NOW()
  WHERE id = p_task_id;

  INSERT INTO public.task_status_history (
    task_id,
    changed_by,
    old_status,
    new_status,
    comment
  )
  VALUES (
    p_task_id,
    actor_resource_id,
    old_status,
    p_status,
    CASE
      WHEN actor_resource_id = p_assignee_resource_id
        THEN 'Assignee updated own status from integrated view'
      ELSE 'Event manager updated assignee status from integrated view'
    END
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'task_id', p_task_id,
    'event_id', task_event_id,
    'assignee_id', p_assignee_resource_id,
    'old_status', old_status,
    'new_status', p_status,
    'task_status', aggregate_task_status,
    'assignees', updated_assignees,
    'updated_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."set_task_assignee_status"("p_task_id" "uuid", "p_assignee_resource_id" "uuid", "p_status" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_task_assignee_status"("p_task_id" "uuid", "p_assignee_resource_id" "uuid", "p_status" "text") IS 'Updates one task assignee status. Caller must be that assignee or a manager of the parent event.';



CREATE OR REPLACE FUNCTION "public"."set_task_deadline_status"("p_task_id" "uuid", "p_assignee_resource_id" "uuid", "p_deadline" "text", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  actor_resource_id UUID;
  task_event_id UUID;
  current_meta JSONB;
  current_assignees JSONB;
  updated_assignees JSONB := '[]'::JSONB;
  deadlines JSONB;
  progress JSONB;
  assignee_progress JSONB;
  event_meta JSONB;
  event_manager_id UUID;
  assignee JSONB;
  updated_assignee JSONB;
  old_round_status TEXT;
  derived_status TEXT;
  actor_is_manager BOOLEAN := FALSE;
  assignee_found BOOLEAN := FALSE;
  all_rounds_completed BOOLEAN;
  all_completed BOOLEAN := FALSE;
  aggregate_task_status TEXT;
  d JSONB;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  -- 회차 상태는 pending/completed 2종(회차 단위 취소 개념은 없음)
  IF p_status IS NULL OR p_status NOT IN ('pending', 'completed') THEN
    RAISE EXCEPTION 'Invalid deadline status: %', p_status USING ERRCODE = '22023';
  END IF;

  SELECT ur.resource_id
  INTO actor_resource_id
  FROM public.user_resource ur
  WHERE ur.user_id = auth.uid()
  ORDER BY ur.created_at
  LIMIT 1;

  IF actor_resource_id IS NULL THEN
    SELECT r.id
    INTO actor_resource_id
    FROM public.profiles p
    JOIN public.resource r
      ON r.type = 'student'
      AND r.meta->>'id' = SPLIT_PART(p.email, '@', 1)
    WHERE p.id = auth.uid()
    LIMIT 1;
  END IF;

  IF actor_resource_id IS NULL THEN
    RAISE EXCEPTION 'User resource not found' USING ERRCODE = '42501';
  END IF;

  SELECT t.event_id, COALESCE(t.meta, '{}'::JSONB), COALESCE(e.meta, '{}'::JSONB), e.manager_id
  INTO task_event_id, current_meta, event_meta, event_manager_id
  FROM public.task t
  JOIN public.work e ON e.id = t.event_id
  WHERE t.id = p_task_id
  FOR UPDATE OF t;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Task not found: %', p_task_id USING ERRCODE = 'P0002';
  END IF;

  deadlines := CASE
    WHEN jsonb_typeof(current_meta->'deadlines') = 'array' THEN current_meta->'deadlines'
    ELSE '[]'::JSONB
  END;

  IF NOT deadlines ? p_deadline THEN
    RAISE EXCEPTION 'Deadline % is not a round of task %', p_deadline, p_task_id
      USING ERRCODE = '22023';
  END IF;

  current_assignees := CASE
    WHEN jsonb_typeof(current_meta->'assignees') = 'array' THEN current_meta->'assignees'
    ELSE '[]'::JSONB
  END;

  actor_is_manager :=
    COALESCE(event_manager_id = actor_resource_id, FALSE)
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(event_meta->'managers') = 'array' THEN event_meta->'managers'
          ELSE '[]'::JSONB
        END
      ) AS manager(value)
      WHERE CASE
        WHEN jsonb_typeof(value) = 'object' THEN value->>'id'
        ELSE TRIM(BOTH '"' FROM value::TEXT)
      END = actor_resource_id::TEXT
    );

  IF actor_resource_id <> p_assignee_resource_id AND NOT actor_is_manager THEN
    RAISE EXCEPTION 'Only the assignee or an work manager can update this status'
      USING ERRCODE = '42501';
  END IF;

  progress := CASE
    WHEN jsonb_typeof(current_meta->'deadlineProgress') = 'object' THEN current_meta->'deadlineProgress'
    ELSE '{}'::JSONB
  END;

  old_round_status := COALESCE(
    progress->p_deadline->(p_assignee_resource_id::TEXT)->>'status', 'pending');

  -- 회차 기록 갱신
  progress := jsonb_set(
    progress,
    ARRAY[p_deadline],
    COALESCE(progress->p_deadline, '{}'::JSONB) || jsonb_build_object(
      p_assignee_resource_id::TEXT,
      jsonb_build_object(
        'status', p_status,
        'completed_at', CASE WHEN p_status = 'completed' THEN to_jsonb(NOW()) ELSE 'null'::JSONB END
      )
    ),
    TRUE
  );

  -- 이 담당자의 전체 회차 완료 여부 → 담당자 전체 상태 파생
  all_rounds_completed := TRUE;
  FOR d IN SELECT value FROM jsonb_array_elements(deadlines)
  LOOP
    IF COALESCE(
      progress->(d #>> '{}')->(p_assignee_resource_id::TEXT)->>'status', 'pending'
    ) <> 'completed' THEN
      all_rounds_completed := FALSE;
    END IF;
  END LOOP;
  derived_status := CASE WHEN all_rounds_completed THEN 'completed' ELSE 'pending' END;

  FOR assignee IN SELECT value FROM jsonb_array_elements(current_assignees)
  LOOP
    IF assignee->>'id' = p_assignee_resource_id::TEXT THEN
      assignee_found := TRUE;
      IF COALESCE(assignee->>'status', 'pending') = 'cancelled' THEN
        RAISE EXCEPTION 'Cancelled assignee cannot update deadline rounds' USING ERRCODE = '42501';
      END IF;
      updated_assignee := jsonb_set(assignee, '{status}', to_jsonb(derived_status), TRUE);
      updated_assignee := jsonb_set(
        updated_assignee,
        '{completed_at}',
        CASE WHEN derived_status = 'completed' THEN to_jsonb(NOW()) ELSE 'null'::JSONB END,
        TRUE
      );
      updated_assignees := updated_assignees || jsonb_build_array(updated_assignee);
    ELSE
      updated_assignees := updated_assignees || jsonb_build_array(assignee);
    END IF;
  END LOOP;

  IF NOT assignee_found THEN
    RAISE EXCEPTION 'Assignee % is not assigned to task %', p_assignee_resource_id, p_task_id
      USING ERRCODE = 'P0002';
  END IF;

  SELECT NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(updated_assignees) AS item(value)
    WHERE COALESCE(value->>'status', 'pending') <> 'completed'
  )
  INTO all_completed;

  aggregate_task_status := CASE
    WHEN all_completed AND jsonb_array_length(updated_assignees) > 0 THEN 'completed'
    ELSE 'pending'
  END;

  UPDATE public.task
  SET
    meta = jsonb_set(
      jsonb_set(current_meta, '{assignees}', updated_assignees, TRUE),
      '{deadlineProgress}', progress, TRUE
    ),
    status = CASE WHEN status = 'cancelled' THEN status ELSE aggregate_task_status END,
    updated_at = NOW()
  WHERE id = p_task_id;

  INSERT INTO public.task_status_history (task_id, changed_by, old_status, new_status, comment)
  VALUES (
    p_task_id,
    actor_resource_id,
    old_round_status,
    p_status,
    CASE
      WHEN actor_resource_id = p_assignee_resource_id
        THEN '담당자가 회차(' || p_deadline || ') 상태 변경'
      ELSE '업무 책임자가 회차(' || p_deadline || ') 상태 변경'
    END
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'task_id', p_task_id,
    'event_id', task_event_id,
    'assignee_id', p_assignee_resource_id,
    'deadline', p_deadline,
    'old_round_status', old_round_status,
    'new_round_status', p_status,
    'assignee_status', derived_status,
    'task_status', aggregate_task_status,
    'updated_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."set_task_deadline_status"("p_task_id" "uuid", "p_assignee_resource_id" "uuid", "p_deadline" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_task_output_decl"("p_task_id" "uuid", "p_decl" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_work uuid;
  v_kind text;
  v_label text;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.' using errcode = '42501';
  end if;
  select event_id into v_work from public.task where id = p_task_id;
  if v_work is null then
    raise exception '할 일을 찾을 수 없습니다.' using errcode = 'P0002';
  end if;
  if not public.can_manage_work_structure(v_work) then
    raise exception '이 업무의 책임자만 «남기는 것»을 정할 수 있습니다.' using errcode = '42501';
  end if;

  if p_decl is null or jsonb_typeof(p_decl) <> 'object' then
    update public.task set meta = coalesce(meta, '{}'::jsonb) - 'output' where id = p_task_id;
    return;
  end if;
  v_kind := p_decl->>'kind';
  if v_kind not in ('signal', 'value', 'people', 'table', 'spec_document', 'file') then
    raise exception '알 수 없는 산출물 형태입니다: %', v_kind using errcode = '22023';
  end if;
  v_label := nullif(left(trim(coalesce(p_decl->>'label', '')), 60), '');
  update public.task
     set meta = jsonb_set(
       coalesce(meta, '{}'::jsonb), '{output}',
       case when v_label is null then jsonb_build_object('kind', v_kind)
            else jsonb_build_object('kind', v_kind, 'label', v_label) end)
   where id = p_task_id;
end;
$$;


ALTER FUNCTION "public"."set_task_output_decl"("p_task_id" "uuid", "p_decl" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_task_unit_status"("p_task_id" "uuid", "p_unit_key" "text", "p_assignee_resource_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  actor_resource_id UUID;
  task_event_id UUID;
  current_meta JSONB;
  current_assignees JSONB;
  updated_assignees JSONB := '[]'::JSONB;
  units JSONB;
  progress JSONB;
  unit_holders JSONB;
  event_meta JSONB;
  event_manager_id UUID;
  assignee JSONB;
  updated_assignee JSONB;
  old_unit_status TEXT;
  derived_status TEXT;
  actor_is_manager BOOLEAN := FALSE;
  assignee_found BOOLEAN := FALSE;
  unit_found BOOLEAN := FALSE;
  my_unit_count INT := 0;
  my_done_count INT := 0;
  all_units_done BOOLEAN := TRUE;
  aggregate_task_status TEXT;
  u JSONB;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  IF p_status IS NOT NULL AND p_status NOT IN ('pending', 'completed') THEN
    RAISE EXCEPTION 'Invalid unit status: %', p_status USING ERRCODE = '22023';
  END IF;

  SELECT ur.resource_id INTO actor_resource_id
  FROM public.user_resource ur
  WHERE ur.user_id = auth.uid()
  ORDER BY ur.created_at
  LIMIT 1;

  IF actor_resource_id IS NULL THEN
    SELECT r.id INTO actor_resource_id
    FROM public.profiles p
    JOIN public.resource r
      ON r.type = 'student'
      AND r.meta->>'id' = SPLIT_PART(p.email, '@', 1)
    WHERE p.id = auth.uid()
    LIMIT 1;
  END IF;

  IF actor_resource_id IS NULL THEN
    RAISE EXCEPTION 'User resource not found' USING ERRCODE = '42501';
  END IF;

  SELECT t.event_id, COALESCE(t.meta, '{}'::JSONB), COALESCE(e.meta, '{}'::JSONB), e.manager_id
  INTO task_event_id, current_meta, event_meta, event_manager_id
  FROM public.task t
  JOIN public.work e ON e.id = t.event_id
  WHERE t.id = p_task_id
  FOR UPDATE OF t;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Task not found: %', p_task_id USING ERRCODE = 'P0002';
  END IF;

  units := CASE
    WHEN jsonb_typeof(current_meta->'units') = 'array' THEN current_meta->'units'
    ELSE '[]'::JSONB
  END;

  SELECT EXISTS (
    SELECT 1 FROM jsonb_array_elements(units) AS unit(value)
    WHERE value->>'key' = p_unit_key
  ) INTO unit_found;
  IF NOT unit_found THEN
    RAISE EXCEPTION 'Unit % is not defined on task %', p_unit_key, p_task_id
      USING ERRCODE = '22023';
  END IF;

  current_assignees := CASE
    WHEN jsonb_typeof(current_meta->'assignees') = 'array' THEN current_meta->'assignees'
    ELSE '[]'::JSONB
  END;

  actor_is_manager :=
    COALESCE(event_manager_id = actor_resource_id, FALSE)
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(event_meta->'managers') = 'array' THEN event_meta->'managers'
          ELSE '[]'::JSONB
        END
      ) AS manager(value)
      WHERE CASE
        WHEN jsonb_typeof(value) = 'object' THEN value->>'id'
        ELSE TRIM(BOTH '"' FROM value::TEXT)
      END = actor_resource_id::TEXT
    );

  IF actor_resource_id <> p_assignee_resource_id AND NOT actor_is_manager THEN
    RAISE EXCEPTION 'Only the assignee or an work manager can update unit status'
      USING ERRCODE = '42501';
  END IF;

  progress := CASE
    WHEN jsonb_typeof(current_meta->'unitProgress') = 'object' THEN current_meta->'unitProgress'
    ELSE '{}'::JSONB
  END;

  IF COALESCE(progress->p_unit_key, '{}'::JSONB) ? (p_assignee_resource_id::TEXT) THEN
    old_unit_status := COALESCE(
      progress->p_unit_key->(p_assignee_resource_id::TEXT)->>'status', 'pending');
  ELSE
    old_unit_status := 'none';
  END IF;

  IF p_status IS NULL THEN
    -- 선택 해제: 기록 자체를 제거(없으면 no-op)
    progress := jsonb_set(
      progress,
      ARRAY[p_unit_key],
      COALESCE(progress->p_unit_key, '{}'::JSONB) - (p_assignee_resource_id::TEXT),
      TRUE
    );
  ELSE
    progress := jsonb_set(
      progress,
      ARRAY[p_unit_key],
      COALESCE(progress->p_unit_key, '{}'::JSONB) || jsonb_build_object(
        p_assignee_resource_id::TEXT,
        jsonb_build_object(
          'status', p_status,
          'completed_at',
          CASE WHEN p_status = 'completed' THEN to_jsonb(NOW()) ELSE 'null'::JSONB END
        )
      ),
      TRUE
    );
  END IF;

  -- 담당자 개인 상태 파생: 내 단위 ≥1 && 전부 완료 → completed
  FOR u IN SELECT value FROM jsonb_array_elements(units)
  LOOP
    IF COALESCE(progress->(u->>'key'), '{}'::JSONB) ? (p_assignee_resource_id::TEXT) THEN
      my_unit_count := my_unit_count + 1;
      IF COALESCE(
        progress->(u->>'key')->(p_assignee_resource_id::TEXT)->>'status', 'pending'
      ) = 'completed' THEN
        my_done_count := my_done_count + 1;
      END IF;
    END IF;
  END LOOP;
  derived_status := CASE
    WHEN my_unit_count > 0 AND my_done_count = my_unit_count THEN 'completed'
    ELSE 'pending'
  END;

  -- 대상 담당자는 범주(meta.assignees) 안에 있어야 한다(선택은 범주 담당자만).
  FOR assignee IN SELECT value FROM jsonb_array_elements(current_assignees)
  LOOP
    IF assignee->>'id' = p_assignee_resource_id::TEXT THEN
      assignee_found := TRUE;
      IF COALESCE(assignee->>'status', 'pending') = 'cancelled' THEN
        RAISE EXCEPTION 'Cancelled assignee cannot update units' USING ERRCODE = '42501';
      END IF;
      updated_assignee := jsonb_set(assignee, '{status}', to_jsonb(derived_status), TRUE);
      updated_assignee := jsonb_set(
        updated_assignee,
        '{completed_at}',
        CASE WHEN derived_status = 'completed' THEN to_jsonb(NOW()) ELSE 'null'::JSONB END,
        TRUE
      );
      updated_assignees := updated_assignees || jsonb_build_array(updated_assignee);
    ELSE
      updated_assignees := updated_assignees || jsonb_build_array(assignee);
    END IF;
  END LOOP;

  IF NOT assignee_found THEN
    RAISE EXCEPTION 'Assignee % is not in the assignee pool of task %',
      p_assignee_resource_id, p_task_id USING ERRCODE = 'P0002';
  END IF;

  -- task 집계: 모든 단위가 담당자 1명 이상을 갖고 전원 완료 → completed
  -- (범주에만 있고 단위를 안 가진 사람은 완료를 막지 않는다 — 사람 기준 집계와 다른 점)
  FOR u IN SELECT value FROM jsonb_array_elements(units)
  LOOP
    unit_holders := COALESCE(progress->(u->>'key'), '{}'::JSONB);
    IF unit_holders = '{}'::JSONB THEN
      all_units_done := FALSE;
    ELSIF EXISTS (
      SELECT 1 FROM jsonb_each(unit_holders) AS kv(key, value)
      WHERE COALESCE(kv.value->>'status', 'pending') <> 'completed'
    ) THEN
      all_units_done := FALSE;
    END IF;
  END LOOP;
  aggregate_task_status := CASE WHEN all_units_done THEN 'completed' ELSE 'pending' END;

  UPDATE public.task
  SET
    meta = jsonb_set(
      jsonb_set(current_meta, '{assignees}', updated_assignees, TRUE),
      '{unitProgress}', progress, TRUE
    ),
    status = CASE WHEN status = 'cancelled' THEN status ELSE aggregate_task_status END,
    updated_at = NOW()
  WHERE id = p_task_id;

  INSERT INTO public.task_status_history (task_id, changed_by, old_status, new_status, comment)
  VALUES (
    p_task_id,
    actor_resource_id,
    old_unit_status,
    COALESCE(p_status, 'none'),
    CASE
      WHEN actor_resource_id = p_assignee_resource_id
        THEN '담당자가 과제 단위(' || p_unit_key || ') ' ||
          CASE WHEN p_status IS NULL THEN '선택 해제' ELSE '상태 변경' END
      ELSE '업무 책임자가 과제 단위(' || p_unit_key || ') ' ||
        CASE WHEN p_status IS NULL THEN '선택 해제' ELSE '상태 변경' END
    END
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'task_id', p_task_id,
    'event_id', task_event_id,
    'assignee_id', p_assignee_resource_id,
    'unit_key', p_unit_key,
    'old_unit_status', old_unit_status,
    'new_unit_status', COALESCE(p_status, 'none'),
    'assignee_status', derived_status,
    'task_status', aggregate_task_status,
    'updated_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."set_task_unit_status"("p_task_id" "uuid", "p_unit_key" "text", "p_assignee_resource_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_training_sign_link_expiry"("p_meeting_id" "uuid", "p_expires_at" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  m record;
  v_exp timestamptz;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  select id, kind, ends_at, created_by, creator into m from public.meeting where id = p_meeting_id for update;
  if m.id is null or m.kind <> 'training' then raise exception '연수 일정을 찾을 수 없습니다.' using errcode = 'P0002'; end if;
  if not (public.is_training_creator(m.id) or public.is_admin()) then
    raise exception '연수를 만든 사람만 서명 링크 기한을 바꿀 수 있습니다.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.training_sign_link where meeting_id = m.id) then
    raise exception '이 연수는 서명 링크가 없습니다(기능 도입 전에 만든 연수).' using errcode = '22023';
  end if;
  if p_expires_at is not null and (p_expires_at < now() + interval '1 hour' or p_expires_at > now() + interval '90 days') then
    raise exception '기한은 지금부터 1시간 뒤 ~ 90일 안으로 정해 주세요.' using errcode = '22023';
  end if;
  v_exp := coalesce(p_expires_at, public.training_sign_default_expiry(m.ends_at));
  update public.training_sign_link
     set expires_at = v_exp, expires_custom = p_expires_at is not null, updated_at = now()
   where meeting_id = m.id;
  return v_exp;
end;
$$;


ALTER FUNCTION "public"."set_training_sign_link_expiry"("p_meeting_id" "uuid", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


