CREATE OR REPLACE FUNCTION "public"."sign_signature_with_token"("p_token" "text", "p_action" "text", "p_signature" "jsonb" DEFAULT NULL::"jsonb", "p_comment" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_tok       public.signature_sign_token;
  v_signer    public.signature_signer;
  v_request   public.signature_request;
  v_active    int;
  v_remaining int;
  v_next      int;
begin
  if p_action not in ('sign', 'reject') then
    raise exception '알 수 없는 동작입니다: %', p_action using errcode = '22023';
  end if;

  select * into v_tok from public.signature_sign_token where token = p_token for update;
  if not found then
    raise exception '유효하지 않은 서명 링크입니다.' using errcode = '42501';
  end if;
  if v_tok.expires_at < now() then
    raise exception '서명 링크가 만료됐습니다. 요청자에게 다시 요청하세요.' using errcode = '42501';
  end if;

  -- 요청 행을 잠근다 — 같은 그룹의 두 사람이 동시에 서명해도 차례 계산이 어긋나지 않게
  select * into v_request from public.signature_request where id = v_tok.request_id for update;
  if v_request.status <> 'pending' then
    raise exception '이미 종료된 요청입니다(상태: %).', v_request.status using errcode = '22023';
  end if;

  select * into v_signer from public.signature_signer where id = v_tok.signer_id;
  -- **한 번 쓰면 죽는다** — 이 검사가 토큰 재사용을 막는 유일한 장치다
  if v_signer.status <> 'pending' then
    raise exception '이미 처리한 서명입니다.' using errcode = '22023';
  end if;

  select min(order_index) into v_active
  from public.signature_signer
  where request_id = v_tok.request_id and status = 'pending';

  if v_signer.order_index <> v_active then
    raise exception '아직 서명할 차례가 아닙니다.' using errcode = '42501';
  end if;

  if p_action = 'sign' then
    if p_signature is null or jsonb_typeof(p_signature -> 's') <> 'array' then
      raise exception '서명이 필요합니다.' using errcode = '22023';
    end if;

    update public.signature_signer
       set status = 'signed', signature = p_signature, comment = p_comment,
           acted_at = now(),
           -- 로그인 서명과 구분해 남긴다(증거력이 다르다)
           auth_method = 'token'
     where id = v_signer.id;

    select count(*) into v_remaining
    from public.signature_signer
    where request_id = v_tok.request_id
      and order_index = v_signer.order_index and status = 'pending';

    if v_remaining = 0 then
      select min(order_index) into v_next
      from public.signature_signer
      where request_id = v_tok.request_id and order_index > v_signer.order_index;

      if v_next is null then
        update public.signature_request
           set status = 'completed', decided_at = now(), updated_at = now()
         where id = v_tok.request_id;
      else
        update public.signature_request
           set current_order = v_next, updated_at = now()
         where id = v_tok.request_id;
      end if;
    else
      update public.signature_request set updated_at = now() where id = v_tok.request_id;
    end if;
  else
    update public.signature_signer
       set status = 'rejected', comment = p_comment, acted_at = now(), auth_method = 'token'
     where id = v_signer.id;
    update public.signature_request
       set status = 'rejected', decided_at = now(), updated_at = now()
     where id = v_tok.request_id;
  end if;

  -- 감사 흔적
  update public.signature_sign_token
     set used_at = now(), used_user_agent = left(coalesce(p_user_agent, ''), 300)
   where signer_id = v_signer.id;

  select * into v_request from public.signature_request where id = v_tok.request_id;
  return jsonb_build_object('status', v_request.status, 'signer_name', v_signer.signer_name);
end;
$$;


ALTER FUNCTION "public"."sign_signature_with_token"("p_token" "text", "p_action" "text", "p_signature" "jsonb", "p_comment" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sign_training_with_token"("p_token" "text", "p_strokes" "jsonb", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  t record;
  m record;
  v_exp timestamptz;
  v_rid uuid;
begin
  select * into t from public.training_sign_token where token = p_token for update;
  if t.token is null then raise exception '유효하지 않은 링크입니다.' using errcode = 'P0002'; end if;
  select id, kind, meta into m from public.meeting where id = t.meeting_id;
  if m.id is null or m.kind <> 'training' or not coalesce((m.meta->'assignee') ? t.signer_name, false) then
    raise exception '이 연수의 참석자 명단에 없습니다.' using errcode = 'P0002';
  end if;
  select expires_at into v_exp from public.training_sign_link where meeting_id = m.id;
  if v_exp is null or v_exp < now() then
    raise exception '서명 링크 기한이 지났습니다. 연수를 만든 분께 알려 주세요.' using errcode = '22023';
  end if;
  if exists (select 1 from public.training_signature s where s.meeting_id = m.id and s.signer_name = t.signer_name) then
    raise exception '이미 서명하셨습니다.' using errcode = '22023';
  end if;
  if p_strokes is null or jsonb_typeof(p_strokes) <> 'object' or jsonb_typeof(p_strokes->'s') <> 'array' then
    raise exception '서명을 그려 주세요.' using errcode = '22023';
  end if;

  -- 같은 이름의 교직원이 정확히 한 명일 때만 resource 를 잇는다(동명이인이면 비워 둔다 — 이름이 서명 키다)
  select case when count(*) = 1 then min(r.id::text)::uuid end into v_rid
    from public.resource r where r.name = t.signer_name and r.type in ('teacher', 'staff');

  -- 표 CHECK(획 수·크기)가 서명 모양을 다시 검사한다. 서명 표시(meta.assignee[이름].signature)는 기존 트리거가 맞춘다
  insert into public.training_signature (meeting_id, signer_name, resource_id, user_id, strokes, source)
  values (m.id, t.signer_name, v_rid, null, p_strokes, 'link');

  update public.training_sign_token
     set used_at = now(), used_user_agent = left(nullif(btrim(coalesce(p_user_agent, '')), ''), 300)
   where token = p_token;
  return jsonb_build_object('ok', true, 'signer_name', t.signer_name);
end;
$$;


ALTER FUNCTION "public"."sign_training_with_token"("p_token" "text", "p_strokes" "jsonb", "p_user_agent" "text") OWNER TO "postgres";


