CREATE TABLE IF NOT EXISTS "public"."signature_signer" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "request_id" "uuid" NOT NULL,
    "order_index" integer DEFAULT 0 NOT NULL,
    "role_label" "text",
    "signer_user_id" "uuid",
    "signer_resource_id" "uuid",
    "signer_name" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "signature" "jsonb",
    "comment" "text",
    "acted_at" timestamp with time zone,
    "fields" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "auth_method" "text",
    CONSTRAINT "signature_signer_auth_method_check" CHECK (("auth_method" = ANY (ARRAY['session'::"text", 'token'::"text"]))),
    CONSTRAINT "signature_signer_fields_is_array" CHECK (("jsonb_typeof"("fields") = 'array'::"text")),
    CONSTRAINT "signature_signer_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'signed'::"text", 'rejected'::"text"])))
);


ALTER TABLE "public"."signature_signer" OWNER TO "postgres";


COMMENT ON TABLE "public"."signature_signer" IS '서명자 1명. order_index 가 같으면 동시 서명 그룹. fields = 서명이 찍힐 자리(정규화 좌표).';



COMMENT ON COLUMN "public"."signature_signer"."auth_method" IS '서명 시 신원을 무엇으로 확인했나. session=로그인 사용자, token=QR 링크(로그인 없음). 증거력이 다르므로 반드시 남긴다.';



CREATE OR REPLACE FUNCTION "public"."signature_signer_resource"("p_signer" "public"."signature_signer") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    p_signer.signer_resource_id,
    (select r.id from public.resource r
      where r.name = p_signer.signer_name
        and r.type in ('teacher', 'staff')
        and r.status = 'active'
      -- 동명이인이 두 종류에 있으면 교사를 먼저(셀프 연결 규칙과 같은 결정)
      order by case when r.type = 'teacher' then 0 else 1 end
      limit 1)
  );
$$;


ALTER FUNCTION "public"."signature_signer_resource"("p_signer" "public"."signature_signer") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_achievement_claim"("p_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := public.isekai3d_require_player();
  rule record;
  have integer;
  paid integer;
begin
  select * into rule from isekai3d_private.achievement_rule(p_id);
  if rule.goal is null then raise exception '모르는 업적이에요.'; end if;
  if isekai3d_private.is_admin(u) then
    raise exception '관리자 계정(테스트용)은 업적 코인을 받을 수 없어요.' using errcode = 'P0001';
  end if;
  -- 같은 사람의 받기를 줄 세운다(원장 유일 키가 두 번째를 0으로 만들지만 판정도 같은 순간에)
  perform pg_advisory_xact_lock(hashtextextended('isekai3d-achievement:' || u::text, 0));
  have := coalesce((isekai3d_private.achievement_progress(u)->>p_id)::integer, 0);
  if have < rule.goal then raise exception '아직 달성하지 않았어요. (%/%)', have, rule.goal using errcode = 'P0001'; end if;
  paid := wallet_private.apply(u, rule.reward, 'isekai3d_achievement', 'isekai3d', p_id, false, '이세계 사회인 업적 ' || p_id);
  return jsonb_build_object('id', p_id, 'granted', paid > 0, 'amount', paid,
    'coins', (select coins from public.academy_user_stats where user_id = u));
end $$;


ALTER FUNCTION "public"."isekai3d_achievement_claim"("p_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_achievements"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := public.isekai3d_require_player();
begin
  return jsonb_build_object(
    'progress', isekai3d_private.achievement_progress(u),
    'claimed', coalesce((select jsonb_agg(source_id) from public.wallet_ledger
                         where user_id = u and source_app = 'isekai3d' and kind = 'isekai3d_achievement'), '[]'::jsonb),
    'rewards', (select jsonb_object_agg(a.id, economy_private.num('isekai3d.achievement.' || a.id)) from isekai3d_private.achievement_table() a),
    'admin', isekai3d_private.is_admin(u)
  );
end $$;


