CREATE OR REPLACE FUNCTION "public"."isekai3d_admin_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  today date := public.isekai3d_korea_today();
  rule record;
begin
  if auth.uid() is null or not public.isekai3d_is_admin(auth.uid()) then
    raise exception '관리자만 볼 수 있어요.' using errcode = '42501';
  end if;
  select * into rule from public.isekai3d_play_rule();
  return (
    with everyone as (
      select user_id from public.isekai3d_player
      union select user_id from public.isekai3d_play_day
      union select user_id from public.isekai3d_saves
      union select user_id from public.isekai3d_questions
    ), players as (
      select e.user_id, coalesce(p.role, '?') as role, p.name
      from everyone e left join public.profiles p on p.id = e.user_id
      where coalesce(p.role, '?') <> 'admin'
    ), days as (
      select d.* from public.isekai3d_play_day d where d.user_id in (select user_id from players) and d.coins > 0
    ), qs as (
      select q.* from public.isekai3d_questions q where q.user_id in (select user_id from players)
    ), saves as (
      select s.user_id, s.slot, s.updated_at,
        case when (s.summary->>'day') ~ '^[0-9]{1,6}$' then (s.summary->>'day')::integer end as game_day,
        case when (s.summary->>'money') ~ '^-?[0-9]{1,12}$' then (s.summary->>'money')::bigint end as money
      from public.isekai3d_saves s where s.user_id in (select user_id from players)
    )
    select jsonb_build_object(
      'generated_at', now(),
      'today', today,
      'rule', jsonb_build_object('per_coin', rule.per_coin, 'max_coins', rule.max_coins, 'price', rule.price),
      'admins_excluded', (select count(*) from everyone e join public.profiles p on p.id = e.user_id and p.role = 'admin'),
      'players', jsonb_build_object(
        'total', (select count(*) from players),
        'by_role', coalesce((select jsonb_object_agg(role, n) from (select role, count(*) n from players group by role) x), '{}'::jsonb),
        'played_ever', (select count(distinct user_id) from days),
        'active_7d', (select count(distinct user_id) from days where day > today - 7),
        'active_today', (select count(distinct user_id) from days where day = today),
        'with_saves', (select count(distinct user_id) from saves),
        'memory_off', (select count(*) from public.isekai3d_player sp where sp.user_id in (select user_id from players) and not sp.memory_enabled)),
      'play', jsonb_build_object(
        'days', (select count(*) from days),
        'coins', (select coalesce(sum(coins), 0) from days),
        'paid_coins', (select coalesce(sum(paid), 0) from days),
        'minutes', (select coalesce(sum(used), 0) from days),
        -- 그날 넣은 동전 수(1·2·3번)별 날 수 — 첫 동전만 무료라 2번째부터가 «코인을 써서 더 한 날»
        'coins_hist', (select jsonb_agg(coalesce(n, 0) order by c) from generate_series(1, rule.max_coins) c
            left join (select least(coins, rule.max_coins) k, count(*) n from days group by 1) x on x.k = c),
        -- 넣은 분량을 얼마나 썼나(그날 쓴 분 / 넣은 동전 × 하루) — 10%씩
        'use_hist', (select jsonb_agg(coalesce(n, 0) order by b) from generate_series(0, 9) b
            left join (select least(9, floor(used::numeric * 10 / nullif(coins * rule.per_coin, 0)))::integer k, count(*) n
                       from days group by 1) x on x.k = b)),
      'daily', (select jsonb_agg(jsonb_build_object('day', d,
            'people', (select count(*) from days where day = d),
            'coins', (select coalesce(sum(coins), 0) from days where day = d),
            'minutes', (select coalesce(sum(used), 0) from days where day = d)) order by d)
          from generate_series((today - 20)::timestamp, today::timestamp, interval '1 day') g(d0), lateral (select d0::date d) dd),
      'questions', jsonb_build_object(
        'made', (select count(*) from qs),
        'delivered', (select count(*) from qs where delivered_at is not null),
        'answered', (select count(*) from qs where answered_at is not null),
        'by_kind', coalesce((select jsonb_object_agg(kind, jsonb_build_object('made', made, 'delivered', delivered, 'answered', answered)) from (
            select kind, count(*) made, count(*) filter (where delivered_at is not null) delivered,
                   count(*) filter (where answered_at is not null) answered
            from qs group by kind) x), '{}'::jsonb),
        'careers', coalesce((select jsonb_agg(jsonb_build_object('id', career_id, 'label', label, 'made', made, 'answered', answered,
              'junior', junior, 'expert', expert, 'leader', leader) order by made desc, career_id) from (
            select career_id,
                   max(prompt_context #>> '{career,label}') label,
                   count(*) made, count(*) filter (where answered_at is not null) answered,
                   count(*) filter (where career_stage = 'junior') junior,
                   count(*) filter (where career_stage = 'expert') expert,
                   count(*) filter (where career_stage = 'leader') leader
            from qs where kind = 'career' group by career_id) x), '[]'::jsonb),
        'life_events', coalesce((select jsonb_object_agg(coalesce(life_event, '?'), jsonb_build_object('made', made, 'answered', answered)) from (
            select life_event, count(*) made, count(*) filter (where answered_at is not null) answered
            from qs where kind = 'life' group by life_event) x), '{}'::jsonb)),
      'saves', jsonb_build_object(
        'slots', (select count(*) from saves),
        'by_slot', (select jsonb_agg(coalesce(n, 0) order by c) from generate_series(1, 3) c
            left join (select slot k, count(*) n from saves group by 1) x on x.k = c),
        -- 저장 칸마다 «며칠째» — 가장 멀리 간 칸을 사람마다 하나
        'day_hist', (select jsonb_agg(jsonb_build_object('label', label, 'n', coalesce(n, 0)) order by o) from (values
              (1, '1~3일째', 1, 3), (2, '4~7일째', 4, 7), (3, '8~14일째', 8, 14), (4, '15~30일째', 15, 30), (5, '31일째~', 31, 2147483647)) b(o, label, lo, hi)
            left join lateral (select count(*) n from (select max(game_day) m from saves group by user_id) t where t.m between b.lo and b.hi) x on true)),
      'list', coalesce((select jsonb_agg(r order by r->>'last_day' desc nulls last, r->>'name') from (
          select jsonb_build_object('name', coalesce(p.name, '이름 없음'), 'role', p.role,
            'days', (select count(*) from days d where d.user_id = p.user_id),
            'coins', (select coalesce(sum(d.coins), 0) from days d where d.user_id = p.user_id),
            'paid', (select coalesce(sum(d.paid), 0) from days d where d.user_id = p.user_id),
            'minutes', (select coalesce(sum(d.used), 0) from days d where d.user_id = p.user_id),
            'last_day', (select max(d.day) from days d where d.user_id = p.user_id),
            'saves', (select count(*) from saves s where s.user_id = p.user_id),
            'game_day', (select max(s.game_day) from saves s where s.user_id = p.user_id),
            'questions', (select count(*) from qs q where q.user_id = p.user_id and q.delivered_at is not null),
            'answered', (select count(*) from qs q where q.user_id = p.user_id and q.answered_at is not null)) r
          from players p limit 500) x), '[]'::jsonb)
    )
  );
end $_$;


ALTER FUNCTION "public"."isekai3d_admin_stats"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."isekai3d_admin_stats"() IS '이세계 사회인 관리자 통계 — 숫자만(학생의 답·지식·저장 내용은 싣지 않는다), 관리자 계정은 뺀다.';



CREATE OR REPLACE FUNCTION "public"."isekai3d_can_view"("p_student" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare g int; c int;
begin
  if auth.uid() is null then return false; end if;
  select grade, class into g, c from public.isekai3d_student_class(p_student);
  if g is null then return false; end if;
  -- 관리자: 학생 전체 (2026-10-22 정책 변경)
  if exists (select 1 from public.profiles where id = auth.uid() and role = 'admin') then return true; end if;
  return exists (
    select 1
      from public.profiles pr
      join public.resource r on r.name = pr.name and r.type = 'teacher' and r.status = 'active'
      join public.resource_tag_assignments a on a.resource_id = r.id
      join public.resource_tags t on t.id = a.tag_id
     where pr.id = auth.uid() and pr.role in ('teacher', 'admin')
       and regexp_replace(t.name, '\s', '', 'g') in (g::text || '학년' || c::text || '반', g::text || '학년부장'));
end $$;


ALTER FUNCTION "public"."isekai3d_can_view"("p_student" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_dev_questions"("p_limit" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player();
begin
  if not public.isekai3d_is_admin(u) then
    raise exception '관리자만 쓸 수 있어요.' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', id, 'kind', kind, 'contextKey', context_key, 'careerId', career_id,
                                        'careerLevel', career_level, 'careerStage', career_stage, 'careerBranch', career_branch,
                                        'lifeEvent', life_event, 'model', model,
                                        'batch', batch, 'card', card, 'createdAt', created_at, 'deliveredAt', delivered_at,
                                        'answeredAt', answered_at, 'choice', answer_choice, 'text', answer_text)
                     order by created_at desc, id)
      from (select * from public.isekai3d_questions where user_id = u
             order by created_at desc limit least(greatest(coalesce(p_limit, 60), 1), 300)) q), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."isekai3d_dev_questions"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_episode_add"("p_user" "uuid", "p_game_key" "text", "p_career" "text", "p_outline" "jsonb", "p_scene" "jsonb", "p_model" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e public.isekai3d_episodes; n smallint; sid uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('isekai3d-episode:' || p_user::text, 0));
  if not public.isekai3d_is_admin(p_user) and (select count(*) from public.isekai3d_episode_scenes
        where user_id = p_user and (created_at at time zone 'Asia/Seoul')::date = public.isekai3d_korea_today()) >= 3 then
    return jsonb_build_object('status', 'limit');
  end if;
  if p_outline is not null then
    update public.isekai3d_episodes set status = 'dropped', updated_at = now()
     where user_id = p_user and game_key = p_game_key and career_id = p_career and status = 'active';
    insert into public.isekai3d_episodes (user_id, game_key, career_id, outline, model)
    values (p_user, p_game_key, p_career, p_outline, p_model) returning * into e;
  else
    select * into e from public.isekai3d_episodes
     where user_id = p_user and game_key = p_game_key and career_id = p_career and status = 'active' for update;
    if e.id is null then return jsonb_build_object('status', 'no_season'); end if;
  end if;
  select coalesce(max(idx) + 1, 0) into n from public.isekai3d_episode_scenes where episode_id = e.id;
  if n > 9 then return jsonb_build_object('status', 'full'); end if;
  insert into public.isekai3d_episode_scenes (episode_id, user_id, idx, scene) values (e.id, p_user, n, p_scene) returning id into sid;
  update public.isekai3d_episodes set updated_at = now() where id = e.id;
  return jsonb_build_object('status', 'added', 'episodeId', e.id, 'sceneId', sid, 'idx', n);
end $$;


ALTER FUNCTION "public"."isekai3d_episode_add"("p_user" "uuid", "p_game_key" "text", "p_career" "text", "p_outline" "jsonb", "p_scene" "jsonb", "p_model" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_episode_answer"("p_scene_id" "uuid", "p_choice" smallint, "p_text" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); s public.isekai3d_episode_scenes; t text := nullif(btrim(coalesce(p_text, '')), '');
begin
  if p_choice is not null and p_choice not in (0, 1) then raise exception '고른 것을 확인해 주세요.' using errcode = '22023'; end if;
  if t is not null and char_length(t) > 200 then raise exception '직접 쓴 답은 200자까지예요.' using errcode = '22023'; end if;
  if p_choice is null and t is null then raise exception '고르거나 써 주세요.' using errcode = '22023'; end if;
  select * into s from public.isekai3d_episode_scenes where id = p_scene_id and user_id = u for update;
  if s.id is null or s.delivered_at is null then return jsonb_build_object('status', 'missing'); end if;
  if s.answered_at is not null then return jsonb_build_object('status', 'already'); end if;
  update public.isekai3d_episode_scenes set answered_at = now(), answer_choice = case when t is null then p_choice end, answer_text = t
   where id = s.id;
  if coalesce((s.scene->>'final')::boolean, false) then
    update public.isekai3d_episodes set status = 'done', updated_at = now() where id = s.episode_id;
    return jsonb_build_object('status', 'answered', 'seasonDone', true);
  end if;
  update public.isekai3d_episodes set updated_at = now() where id = s.episode_id;
  return jsonb_build_object('status', 'answered', 'seasonDone', false);
end $$;


ALTER FUNCTION "public"."isekai3d_episode_answer"("p_scene_id" "uuid", "p_choice" smallint, "p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_episode_status"("p_game_key" "text", "p_career" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); e public.isekai3d_episodes;
begin
  select * into e from public.isekai3d_episodes
   where user_id = u and game_key = p_game_key and career_id = p_career and status = 'active';
  return jsonb_build_object(
    'consent', exists (
      select 1 from public.user_privacy_consents c
        join public.privacy_policy_versions v on v.version = c.policy_version and v.is_active
       where c.user_id = u),
    'dev', public.isekai3d_is_admin(u),
    'generatedToday', (select count(*) from public.isekai3d_episode_scenes
                        where user_id = u and (created_at at time zone 'Asia/Seoul')::date = public.isekai3d_korea_today()),
    'deliveredToday', (select count(*) from public.isekai3d_episode_scenes
                        where user_id = u and delivered_at is not null
                          and (delivered_at at time zone 'Asia/Seoul')::date = public.isekai3d_korea_today()),
    'season', case when e.id is null then null else jsonb_build_object(
      'id', e.id, 'outline', e.outline,
      'scenes', coalesce((select jsonb_agg(jsonb_build_object(
          'id', s.id, 'idx', s.idx, 'scene', s.scene, 'delivered', s.delivered_at is not null,
          'answered', s.answered_at is not null, 'choice', s.answer_choice, 'text', s.answer_text) order by s.idx)
        from public.isekai3d_episode_scenes s where s.episode_id = e.id), '[]'::jsonb)) end,
    'pastTitles', coalesce((select jsonb_agg(t) from (
        select outline->>'title' as t from public.isekai3d_episodes
         where user_id = u and game_key = p_game_key and status <> 'active'
         order by created_at desc limit 8) x), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."isekai3d_episode_status"("p_game_key" "text", "p_career" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_episode_take"("p_game_key" "text", "p_career" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); e public.isekai3d_episodes; s public.isekai3d_episode_scenes;
begin
  perform pg_advisory_xact_lock(hashtextextended('isekai3d-episode:' || u::text, 0));
  select * into e from public.isekai3d_episodes
   where user_id = u and game_key = p_game_key and career_id = p_career and status = 'active';
  if e.id is null then return jsonb_build_object('status', 'empty'); end if;
  select * into s from public.isekai3d_episode_scenes
   where episode_id = e.id and delivered_at is not null and answered_at is null order by idx limit 1;
  if s.id is null then
    if not public.isekai3d_is_admin(u) and (select count(*) from public.isekai3d_episode_scenes
          where user_id = u and delivered_at is not null
            and (delivered_at at time zone 'Asia/Seoul')::date = public.isekai3d_korea_today()) >= 2 then
      return jsonb_build_object('status', 'daily_done');
    end if;
    select * into s from public.isekai3d_episode_scenes
     where episode_id = e.id and delivered_at is null order by idx limit 1 for update;
    if s.id is null then return jsonb_build_object('status', 'empty'); end if;
    update public.isekai3d_episode_scenes set delivered_at = now() where id = s.id;
  end if;
  return jsonb_build_object('status', 'scene', 'episodeId', e.id, 'sceneId', s.id, 'idx', s.idx, 'scene', s.scene, 'outline', e.outline);
end $$;


ALTER FUNCTION "public"."isekai3d_episode_take"("p_game_key" "text", "p_career" "text") OWNER TO "postgres";


