CREATE OR REPLACE FUNCTION "public"."isekai3d_knowledge_get"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); row public.isekai3d_player;
begin
  insert into public.isekai3d_player (user_id) values (u) on conflict (user_id) do nothing;
  select * into row from public.isekai3d_player where user_id = u;
  return jsonb_build_object('knowledge', row.knowledge, 'version', row.version, 'memory', row.memory_enabled);
end $$;


ALTER FUNCTION "public"."isekai3d_knowledge_get"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_knowledge_save"("p_version" integer, "p_knowledge" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); row public.isekai3d_player;
begin
  if p_knowledge is null or jsonb_typeof(p_knowledge) <> 'object' or octet_length(p_knowledge::text) > 65536 then
    raise exception '지식 정보가 올바르지 않아요.';
  end if;
  insert into public.isekai3d_player (user_id) values (u) on conflict (user_id) do nothing;
  if not (select memory_enabled from public.isekai3d_player where user_id = u) then
    return jsonb_build_object('memory', false);
  end if;
  update public.isekai3d_player set knowledge = p_knowledge, version = version + 1, updated_at = now()
   where user_id = u and version = p_version
   returning * into row;
  if row.user_id is null then
    select * into row from public.isekai3d_player where user_id = u;
    return jsonb_build_object('conflict', true, 'knowledge', row.knowledge, 'version', row.version, 'memory', true);
  end if;
  return jsonb_build_object('conflict', false, 'version', row.version, 'memory', true);
end $$;


