CREATE OR REPLACE FUNCTION "public"."isekai3d_my_record"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := public.isekai3d_require_player();
begin
  return jsonb_build_object(
    'saves', coalesce((select jsonb_agg(jsonb_build_object(
        'slot', s.slot,
        'day', case when jsonb_typeof(s.summary->'day') = 'number' then (s.summary->>'day')::numeric end,
        'money', case when jsonb_typeof(s.summary->'money') = 'number' then (s.summary->>'money')::numeric end,
        'people', case when jsonb_typeof(s.summary->'people') = 'array' then s.summary->'people' else '[]'::jsonb end,
        'saved_at', s.saved_at) order by s.slot)
      from public.isekai3d_saves s where s.user_id = u), '[]'::jsonb),
    'days', coalesce((select jsonb_agg(jsonb_build_object('day', d.day, 'used', d.used, 'coins', d.coins, 'paid', d.paid) order by d.day)
      from public.isekai3d_play_day d where d.user_id = u), '[]'::jsonb),
    'best_streak', isekai3d_private.best_streak(u),
    'answers', coalesce((select jsonb_agg(a.j order by a.at desc) from (
        select q.answered_at at, jsonb_build_object(
          'id', q.id, 'kind', q.kind, 'career', q.career_id, 'level', q.career_level, 'event', q.life_event,
          'ask', coalesce(q.card->>'ask', q.card->>'text'),
          'picked', case when q.answer_choice is null then null
                         when jsonb_typeof(q.card->'options') = 'array' then q.card->'options'->>q.answer_choice
                         when jsonb_typeof(q.card->'choices') = 'array' then q.card->'choices'->c.stored->>'label' end,
          'approach', case when jsonb_typeof(q.card->'choices') = 'array' then q.card->'choices'->c.stored->>'approach' end,
          'text', q.answer_text, 'at', q.answered_at) j
        from public.isekai3d_questions q
        cross join lateral (select case when jsonb_typeof(q.card->'choices') = 'array'
          then isekai3d_private.card_choice_stored(q.id::text, jsonb_array_length(q.card->'choices'), q.answer_choice) end stored) c
        where q.user_id = u and q.answered_at is not null
        order by q.answered_at desc limit 200) a), '[]'::jsonb),
    'asked', (select count(*) from public.isekai3d_questions where user_id = u),
    'episodes', coalesce((select jsonb_agg(jsonb_build_object(
        'id', e.id, 'title', e.outline->>'title', 'genre', e.outline->>'genre', 'logline', e.outline->>'logline',
        'status', e.status, 'career', e.career_id, 'created_at', e.created_at, 'updated_at', e.updated_at,
        'cast', coalesce((select jsonb_agg(c->>'name') from jsonb_array_elements(case when jsonb_typeof(e.outline->'cast') = 'array' then e.outline->'cast' else '[]'::jsonb end) c), '[]'::jsonb),
        'scenes', (select count(*) from public.isekai3d_episode_scenes sc where sc.episode_id = e.id),
        'answered', (select count(*) from public.isekai3d_episode_scenes sc where sc.episode_id = e.id and sc.answered_at is not null),
        'picks', coalesce((select jsonb_agg(sc.scene->'choices'->sc.answer_choice->>'text' order by sc.idx) from public.isekai3d_episode_scenes sc
                  where sc.episode_id = e.id and sc.answer_choice is not null), '[]'::jsonb)
      ) order by e.created_at desc)
      from public.isekai3d_episodes e where e.user_id = u), '[]'::jsonb),
    'tally', coalesce((select case when jsonb_typeof(p.knowledge->'tally') = 'object' then p.knowledge->'tally' end
      from public.isekai3d_player p where p.user_id = u), '{}'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."isekai3d_my_record"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_my_students"() RETURNS TABLE("user_id" "uuid", "grade" integer, "class" integer, "number" integer, "name" "text", "answered" integer, "last_answered" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;
  return query
    select p.id, (r.meta->>'grade')::int, (r.meta->>'class')::int, nullif(r.meta->>'number', '')::int, r.name,
           (select count(*)::int from public.isekai3d_questions q where q.user_id = p.id and q.answered_at is not null),
           (select max(q.answered_at) from public.isekai3d_questions q where q.user_id = p.id)
      from public.profiles p
      join public.resource r on r.type = 'student' and r.status = 'active' and r.meta->>'id' = split_part(p.email, '@', 1)
     where p.role = 'student'
       and (exists (select 1 from public.isekai3d_player s where s.user_id = p.id)
            or exists (select 1 from public.isekai3d_questions q where q.user_id = p.id))
       and public.isekai3d_can_view(p.id)
     order by 2, 3, 4;
end $$;


ALTER FUNCTION "public"."isekai3d_my_students"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_play_insert"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := public.isekai3d_require_player();
  r record;
  today date := public.isekai3d_korea_today();
  admin boolean := public.isekai3d_is_admin(u);
  c integer;
  cost integer;
begin
  select * into r from public.isekai3d_play_rule();
  -- 이 기능의 잠금 먼저, 지갑 줄은 나중 (wallet_private.apply 의 잠금 순서)
  perform pg_advisory_xact_lock(hashtextextended('isekai3d-play:' || u, 0));
  insert into public.isekai3d_play_day(user_id, day) values (u, today) on conflict do nothing;
  select coins into c from public.isekai3d_play_day where user_id = u and day = today;
  if not admin and c >= r.max_coins then
    raise exception '오늘은 동전을 %번 모두 넣었어요. 내일 다시 만나요!', r.max_coins using errcode = 'P0001';
  end if;
  cost := case when admin or c = 0 then 0 else r.price end;
  if cost > 0 then
    -- 모자라면 '코인이 부족합니다.' (P0001) 로 멈추고 아무것도 바뀌지 않는다
    perform wallet_private.apply(u, -cost, 'isekai3d_coin', 'isekai3d', today::text || ':' || (c + 1)::text);
  end if;
  update public.isekai3d_play_day set coins = coins + 1, paid = paid + cost, updated_at = now()
   where user_id = u and day = today;
  return public.isekai3d_play_state(u);
end $$;


ALTER FUNCTION "public"."isekai3d_play_insert"() OWNER TO "postgres";


