CREATE OR REPLACE FUNCTION "public"."isekai3d_play_state"("p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r record;
  today date := public.isekai3d_korea_today();
  admin boolean := public.isekai3d_is_admin(p_user);
  c integer := 0; spent integer := 0;
begin
  select * into r from public.isekai3d_play_rule();
  select d.coins, d.used into c, spent from public.isekai3d_play_day d where d.user_id = p_user and d.day = today;
  c := coalesce(c, 0); spent := coalesce(spent, 0);
  return jsonb_build_object(
    'day', today,
    'coins', c,
    'maxCoins', r.max_coins,
    'perCoin', r.per_coin,
    'used', spent,
    'budget', c * r.per_coin,
    -- 다음 동전값: null = 오늘은 더 못 넣음
    'nextPrice', case when admin then 0 when c >= r.max_coins then null when c = 0 then 0 else r.price end,
    'wallet', coalesce((select s.coins from public.academy_user_stats s where s.user_id = p_user), 100),
    'admin', admin);
end $$;


