CREATE OR REPLACE FUNCTION "public"."isekai3d_play_use"("p_used" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := public.isekai3d_require_player();
  r record;
begin
  select * into r from public.isekai3d_play_rule();
  if p_used is null or p_used < 0 then raise exception '쓴 시간이 이상해요.' using errcode = '22023'; end if;
  update public.isekai3d_play_day
     set used = greatest(used, least(p_used, coins * r.per_coin)), updated_at = now()
   where user_id = u and day = public.isekai3d_korea_today();
  return public.isekai3d_play_state(u);
end $$;


