    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); n int;
begin
  update public.isekai3d_questions
     set answered_at = now(), answer_choice = p_choice,
         answer_text = nullif(left(btrim(coalesce(p_text, '')), 300), '')
   where id = p_id and user_id = u and delivered_at is not null and answered_at is null;
  get diagnostics n = row_count;
  return jsonb_build_object('saved', n = 1);
end $$;


