CREATE OR REPLACE FUNCTION "public"."isekai3d_question_take"("p_context_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); q public.isekai3d_questions; admin boolean := public.isekai3d_is_admin(u);
begin
  perform pg_advisory_xact_lock(hashtextextended('isekai3d:' || u::text, 0));
  if not admin then
    if exists (select 1 from public.isekai3d_questions
                where user_id = u and delivered_at is not null
                  and (delivered_at at time zone 'Asia/Seoul')::date = public.isekai3d_korea_today()) then
      return jsonb_build_object('status', 'daily_done');
    end if;
    select * into q from public.isekai3d_questions
     where user_id = u and context_key = p_context_key and delivered_at is null
       and created_at > now() - interval '30 days'
     order by created_at limit 1 for update;
  else
    -- 관리자: 방금 만든 묶음의 첫 질문 (안 받은 옛 질문은 목록에 남는다)
    select * into q from public.isekai3d_questions
     where user_id = u and context_key = p_context_key and delivered_at is null
       and batch = (select batch from public.isekai3d_questions
                     where user_id = u and context_key = p_context_key and delivered_at is null
                     order by created_at desc limit 1)
     order by created_at limit 1 for update;
  end if;
  if q.id is null then return jsonb_build_object('status', 'empty'); end if;
  update public.isekai3d_questions set delivered_at = now() where id = q.id;
  return jsonb_build_object('status', 'card', 'id', q.id, 'kind', q.kind, 'card', q.card);
end $$;


ALTER FUNCTION "public"."isekai3d_question_take"("p_context_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_questions_add"("p_user" "uuid", "p_kind" "text", "p_context_key" "text", "p_cards" "jsonb", "p_model" "text" DEFAULT NULL::"text", "p_context" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare b uuid := gen_random_uuid(); card jsonb; n int := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('isekai3d:' || p_user::text, 0));
  if jsonb_typeof(p_cards) <> 'array' or jsonb_array_length(p_cards) not between 1 and 3 then
    raise exception '질문은 1–3개씩 넣어요.';
  end if;
  if not public.isekai3d_is_admin(p_user) then
    if exists (select 1 from public.isekai3d_questions
                where user_id = p_user and context_key = p_context_key and delivered_at is null
                  and created_at > now() - interval '30 days') then
      return jsonb_build_object('status', 'pending_exists');
    end if;
    if (select count(distinct batch) from public.isekai3d_questions
         where user_id = p_user and (created_at at time zone 'Asia/Seoul')::date = public.isekai3d_korea_today()) >= 3 then
      return jsonb_build_object('status', 'limit');
    end if;
  end if;
  for card in select * from jsonb_array_elements(p_cards) loop
    insert into public.isekai3d_questions (user_id, kind, context_key, card, batch, created_at, model, prompt_context)
    values (p_user, p_kind, p_context_key, card, b, clock_timestamp(), p_model, p_context);
    n := n + 1;
  end loop;
  return jsonb_build_object('status', 'filled', 'count', n);
end $$;


ALTER FUNCTION "public"."isekai3d_questions_add"("p_user" "uuid", "p_kind" "text", "p_context_key" "text", "p_cards" "jsonb", "p_model" "text", "p_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_require_player"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := auth.uid();
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;
  if not exists (select 1 from public.profiles where id = u and role in ('student', 'teacher', 'admin')) then
    raise exception '이세계 3D 질문은 학생·선생님 본인만 쓸 수 있어요.' using errcode = '42501';
  end if;
  return u;
end $$;


ALTER FUNCTION "public"."isekai3d_require_player"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_save_delete"("p_slot" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player();
begin
  if p_slot is null or p_slot not between 1 and 3 then raise exception '없는 저장 칸이에요.' using errcode = '22023'; end if;
  delete from public.isekai3d_saves where user_id = u and slot = p_slot;
  return jsonb_build_object('ok', true, 'slot', p_slot);
end $$;


ALTER FUNCTION "public"."isekai3d_save_delete"("p_slot" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_save_get"("p_slot" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); r record;
begin
  if p_slot is null or p_slot not between 1 and 3 then raise exception '없는 저장 칸이에요.' using errcode = '22023'; end if;
  select s.state, s.saved_at, s.version into r from public.isekai3d_saves s where s.user_id = u and s.slot = p_slot;
  if not found then return jsonb_build_object('slot', p_slot, 'empty', true); end if;
  return jsonb_build_object('slot', p_slot, 'empty', false, 'state', r.state, 'savedAt', r.saved_at, 'version', r.version);
end $$;


ALTER FUNCTION "public"."isekai3d_save_get"("p_slot" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_save_list"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'slot', s.slot, 'savedAt', s.saved_at, 'version', s.version,
      'size', octet_length(s.state::text), 'summary', s.summary) order by s.slot)
      from public.isekai3d_saves s where s.user_id = u), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."isekai3d_save_list"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_save_put"("p_slot" integer, "p_state" "jsonb", "p_summary" "jsonb", "p_saved_at" bigint, "p_base_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); cur record; v integer;
begin
  if p_slot is null or p_slot not between 1 and 3 then raise exception '없는 저장 칸이에요.' using errcode = '22023'; end if;
  if p_state is null or jsonb_typeof(p_state) <> 'object' then raise exception '저장이 비어 있어요.' using errcode = '22023'; end if;
  if p_saved_at is null or p_saved_at <= 0 then raise exception '저장한 때가 이상해요.' using errcode = '22023'; end if;
  if octet_length(p_state::text) > 524288 then raise exception '저장이 너무 커요(512KB까지).' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('isekai3d-save:' || u || ':' || p_slot, 0));
  select s.version, s.saved_at into cur from public.isekai3d_saves s where s.user_id = u and s.slot = p_slot;
  if found and p_base_version is not null and cur.version <> p_base_version then
    return jsonb_build_object('ok', false, 'conflict', true, 'version', cur.version, 'savedAt', cur.saved_at);
  end if;
  insert into public.isekai3d_saves(user_id, slot, state, summary, saved_at, version)
    values (u, p_slot, p_state, coalesce(p_summary, '{}'::jsonb), p_saved_at, 1)
    on conflict (user_id, slot) do update
      set state = excluded.state, summary = excluded.summary, saved_at = excluded.saved_at,
          version = public.isekai3d_saves.version + 1, updated_at = now()
    returning version into v;
  return jsonb_build_object('ok', true, 'version', v, 'savedAt', p_saved_at);
end $$;


ALTER FUNCTION "public"."isekai3d_save_put"("p_slot" integer, "p_state" "jsonb", "p_summary" "jsonb", "p_saved_at" bigint, "p_base_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_status"("p_context_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public.isekai3d_require_player(); admin boolean := public.isekai3d_is_admin(u);
begin
  return jsonb_build_object(
    'consent', exists (
      select 1 from public.user_privacy_consents c
        join public.privacy_policy_versions v on v.version = c.policy_version and v.is_active
       where c.user_id = u),
    'memory', coalesce((select memory_enabled from public.isekai3d_player where user_id = u), true),
    -- 관리자에게만 게임의 🛠 시험 단추가 보인다 (학생은 모른다)
    'dev', admin,
    'deliveredToday', not admin and exists (
      select 1 from public.isekai3d_questions
       where user_id = u and delivered_at is not null
         and (delivered_at at time zone 'Asia/Seoul')::date = public.isekai3d_korea_today()),
    'pending', case when p_context_key is null then null else (
      select count(*) from public.isekai3d_questions
       where user_id = u and context_key = p_context_key and delivered_at is null
         and created_at > now() - interval '30 days') end);
end $$;


ALTER FUNCTION "public"."isekai3d_status"("p_context_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_stock_closes"("p_asks" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform invest_private.reader();
  if jsonb_typeof(p_asks) <> 'array' or jsonb_array_length(p_asks) > 100 then raise exception '주문은 한 번에 100개까지예요.'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('key', k.key, 'asset_id', k.asset_id,
      'fill', case when q.day is null or (a.currency = 'USD' and invest_private.fx_on(q.day) is null) then null
                   else jsonb_build_object('day', q.day, 'close', q.close, 'close_at', q.close_at,
                                           'usd_krw', case when a.currency = 'USD' then invest_private.fx_on(q.day) end) end))
    from jsonb_to_recordset(p_asks) as k(key text, asset_id text, after timestamptz)
    left join public.invest_asset a on a.id = k.asset_id
    left join lateral (select day, close, close_at from public.invest_quote
                        where asset_id = k.asset_id and close_at > k.after and close_at <= now() order by day limit 1) q on true), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."isekai3d_stock_closes"("p_asks" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_stock_history"("p_asset" "text", "p_days" integer DEFAULT 130) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform invest_private.reader();
  return coalesce((select jsonb_agg(jsonb_build_object('day', x.day, 'open', x.open, 'high', x.high, 'low', x.low, 'close', x.close,
      'volume', x.volume, 'close_at', x.close_at, 'usd_krw', x.fx) order by x.day) from (
    select q.*, case when a.currency = 'USD' then invest_private.fx_on(q.day) end as fx
      from public.invest_quote q join public.invest_asset a on a.id = q.asset_id
     where q.asset_id = p_asset order by q.day desc limit least(greatest(coalesce(p_days, 130), 5), 400)) x), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."isekai3d_stock_history"("p_asset" "text", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_stock_market"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform invest_private.reader();
  return jsonb_build_object(
    'as_of', now(),
    'fx', (select jsonb_build_object('day', day, 'usd_krw', usd_krw) from public.invest_fx order by day desc limit 1),
    'assets', coalesce((select jsonb_agg(jsonb_build_object(
        'id', a.id, 'market', a.market, 'source', a.source, 'symbol', a.symbol, 'currency', a.currency, 'name', a.name,
        'sector', a.sector, 'blurb', a.blurb,
        'day', q1.day, 'close_at', q1.close_at, 'open', q1.open, 'high', q1.high, 'low', q1.low, 'close', q1.close, 'volume', q1.volume,
        'prev', q2.close
      ) order by a.sort, a.name)
      from public.invest_asset a
      left join lateral (select * from public.invest_quote where asset_id = a.id order by day desc limit 1) q1 on true
      left join lateral (select close from public.invest_quote where asset_id = a.id and day < q1.day order by day desc limit 1) q2 on true
      where a.active), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."isekai3d_stock_market"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."isekai3d_student_class"("p_user" "uuid", OUT "grade" integer, OUT "class" integer) RETURNS "record"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select (r.meta->>'grade')::int, (r.meta->>'class')::int
    from public.profiles p
    join public.resource r on r.type = 'student' and r.status = 'active' and r.meta->>'id' = split_part(p.email, '@', 1)
   where p.id = p_user and p.role = 'student'
   limit 1
$$;


