CREATE OR REPLACE FUNCTION "public"."isekai3d_student_overview"("p_student" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not public.isekai3d_can_view(p_student) then
    raise exception '담임·학년부장 선생님과 관리자만 볼 수 있어요.' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'knowledge', (select knowledge from public.isekai3d_player where user_id = p_student),
    'memory', (select memory_enabled from public.isekai3d_player where user_id = p_student),
    'answers', coalesce((
      select jsonb_agg(jsonb_build_object('kind', kind, 'contextKey', context_key, 'card', card, 'choice', answer_choice,
                                          'text', answer_text, 'deliveredAt', delivered_at, 'answeredAt', answered_at)
                       order by delivered_at desc)
        from (select * from public.isekai3d_questions
               where user_id = p_student and delivered_at is not null
               order by delivered_at desc limit 100) q), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."isekai3d_student_overview"("p_student" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."solar_bump_usage"("p_client_id" "text", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  d date := (now() at time zone 'Asia/Seoul')::date;
  n int;
begin
  if p_client_id is null or length(p_client_id) < 8 then
    return jsonb_build_object('allowed', false, 'calls', 0, 'reason', 'bad_client');
  end if;

  insert into public.solar_usage (client_id, day, calls)
  values (p_client_id, d, 1)
  on conflict (client_id, day)
  do update set calls = public.solar_usage.calls + 1
  returning calls into n;

  return jsonb_build_object('allowed', n <= p_limit, 'calls', n, 'limit', p_limit);
end;
$$;


ALTER FUNCTION "public"."solar_bump_usage"("p_client_id" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."srs_on_session_complete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_today date;
  v_session_seconds int;
  v_yesterday_active boolean;
BEGIN
  -- 세션이 완료된 경우만 처리 (ended_at이 NULL에서 값으로 변경)
  IF OLD.ended_at IS NOT NULL OR NEW.ended_at IS NULL THEN
    RETURN NEW;
  END IF;

  v_today := (NEW.ended_at AT TIME ZONE 'Asia/Seoul')::date;
  v_session_seconds := EXTRACT(EPOCH FROM (NEW.ended_at - NEW.started_at))::int;

  -- daily_activity upsert
  INSERT INTO public.srs_daily_activity (user_id, activity_date, cards_reviewed, time_seconds, retention_rate)
  VALUES (
    NEW.user_id,
    v_today,
    NEW.cards_reviewed,
    v_session_seconds,
    CASE WHEN NEW.cards_reviewed > 0
      THEN ROUND((NEW.cards_correct::double precision / NEW.cards_reviewed) * 100, 1)
      ELSE NULL
    END
  )
  ON CONFLICT (user_id, activity_date) DO UPDATE SET
    cards_reviewed = srs_daily_activity.cards_reviewed + EXCLUDED.cards_reviewed,
    time_seconds = srs_daily_activity.time_seconds + EXCLUDED.time_seconds,
    retention_rate = CASE
      WHEN (srs_daily_activity.cards_reviewed + EXCLUDED.cards_reviewed) > 0
      THEN ROUND(
        ((srs_daily_activity.retention_rate * srs_daily_activity.cards_reviewed +
          COALESCE(EXCLUDED.retention_rate, 0) * EXCLUDED.cards_reviewed)
          / (srs_daily_activity.cards_reviewed + EXCLUDED.cards_reviewed)), 1)
      ELSE NULL
    END;

  -- 어제 활동 여부 확인 (스트릭 계산용)
  SELECT EXISTS (
    SELECT 1 FROM public.srs_daily_activity
    WHERE user_id = NEW.user_id AND activity_date = v_today - 1
  ) INTO v_yesterday_active;

  -- user_stats upsert
  INSERT INTO public.srs_user_stats (user_id, current_streak, best_streak, last_active_at, total_reviews, total_time_seconds, retention_rate, level)
  VALUES (
    NEW.user_id,
    1,
    1,
    NEW.ended_at,
    NEW.cards_reviewed,
    v_session_seconds,
    CASE WHEN NEW.cards_reviewed > 0
      THEN ROUND((NEW.cards_correct::double precision / NEW.cards_reviewed) * 100, 1)
      ELSE NULL
    END,
    1
  )
  ON CONFLICT (user_id) DO UPDATE SET
    current_streak = CASE
      WHEN v_yesterday_active OR srs_user_stats.last_active_at::date = v_today
      THEN srs_user_stats.current_streak + (CASE WHEN srs_user_stats.last_active_at::date < v_today THEN 1 ELSE 0 END)
      ELSE 1
    END,
    best_streak = GREATEST(
      srs_user_stats.best_streak,
      CASE
        WHEN v_yesterday_active OR srs_user_stats.last_active_at::date = v_today
        THEN srs_user_stats.current_streak + (CASE WHEN srs_user_stats.last_active_at::date < v_today THEN 1 ELSE 0 END)
        ELSE 1
      END
    ),
    last_active_at = NEW.ended_at,
    total_reviews = srs_user_stats.total_reviews + NEW.cards_reviewed,
    total_time_seconds = srs_user_stats.total_time_seconds + v_session_seconds,
    retention_rate = CASE
      WHEN (srs_user_stats.total_reviews + NEW.cards_reviewed) > 0
      THEN ROUND(
        ((COALESCE(srs_user_stats.retention_rate, 0) * srs_user_stats.total_reviews +
          CASE WHEN NEW.cards_reviewed > 0 THEN (NEW.cards_correct::double precision / NEW.cards_reviewed) * 100 ELSE 0 END * NEW.cards_reviewed)
          / (srs_user_stats.total_reviews + NEW.cards_reviewed)), 1)
      ELSE NULL
    END,
    level = GREATEST(1, floor(sqrt((srs_user_stats.total_reviews + NEW.cards_reviewed)::double precision / 50)) + 1)::int;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."srs_on_session_complete"() OWNER TO "postgres";


