CREATE OR REPLACE FUNCTION "public"."start_collect_request"("p_action_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not exists (select 1 from public.task_action where id = p_action_id
                 and public.request_kind_of(action_type) is not null) then
    raise exception '요청을 보낼 수 있는 작업이 아닙니다' using errcode = 'P0002';
  end if;
  if not public.can_manage_collect(p_action_id) then
    raise exception '작업을 만든 사람과 업무 책임자만 요청을 보낼 수 있습니다' using errcode = '42501';
  end if;
  return public._start_action_request(p_action_id, false);
end;
$$;


ALTER FUNCTION "public"."start_collect_request"("p_action_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_task_action_run"("p_action_id" "uuid", "p_idempotency_key" "text", "p_workflow_id" "uuid" DEFAULT NULL::"uuid", "p_input_snapshot" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  created_run_id uuid;
  action_type_value text;
  shared_runnable boolean;
begin
  if (select auth.uid()) is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if jsonb_typeof(coalesce(p_input_snapshot, '{}'::jsonb)) <> 'object' then
    raise exception 'input snapshot must be a JSON object' using errcode = '22023';
  end if;

  select work_row.action_type
  into action_type_value
  from public.task_action work_row
  where work_row.id = p_action_id
    and work_row.archived_at is null
    and (
      work_row.created_by = (select auth.uid())
      -- 공유 실행 허용 종류: 문서 생성만. 산출물은 실행자 소유로 남는다.
      -- staff 포함(2026-08-16 정렬) — RLS 관문들과 같은 판정 함수를 쓴다.
      or (work_row.action_type = 'document.spec_fill'
          and public.is_staff_teacher_or_admin((select auth.uid())))
    );

  if action_type_value is null then
    raise exception 'WORK not found or access denied' using errcode = '42501';
  end if;

  shared_runnable := action_type_value = 'document.spec_fill';

  if p_workflow_id is not null
    and not exists (
      select 1
      from public.task_workflow workflow_row
      where workflow_row.id = p_workflow_id
        and (
          workflow_row.owner_id = (select auth.uid())
          -- 남의 워크플로에서 실행할 수 있는 종류만 워크플로 소유 검사를 완화
          or (shared_runnable and public.is_staff_teacher_or_admin((select auth.uid())))
        )
    )
  then
    raise exception 'workflow not found or access denied' using errcode = '42501';
  end if;

  perform pg_catalog.set_config(
    'app.task_action_audit_writer',
    (select auth.uid())::text,
    true
  );

  insert into public.task_action_run (
    action_id, workflow_id, created_by, idempotency_key, status, input_snapshot
  )
  values (
    p_action_id, p_workflow_id, (select auth.uid()), p_idempotency_key, 'running',
    coalesce(p_input_snapshot, '{}'::jsonb)
  )
  returning id into created_run_id;

  insert into public.task_action_run_log (
    run_id, created_by, log_type, from_status, to_status, payload
  )
  values (
    created_run_id, (select auth.uid()), 'started', null, 'running',
    jsonb_build_object('workflowId', p_workflow_id, 'idempotencyKey', p_idempotency_key)
  );

  return created_run_id;
end;
$$;


ALTER FUNCTION "public"."start_task_action_run"("p_action_id" "uuid", "p_idempotency_key" "text", "p_workflow_id" "uuid", "p_input_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_task_work_run"("p_work_id" "uuid", "p_idempotency_key" "text", "p_workflow_id" "uuid", "p_input_snapshot" "jsonb") RETURNS "uuid"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$ select public.start_task_action_run(p_work_id, p_idempotency_key, p_workflow_id, p_input_snapshot) $$;


ALTER FUNCTION "public"."start_task_work_run"("p_work_id" "uuid", "p_idempotency_key" "text", "p_workflow_id" "uuid", "p_input_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_user_token"("p_user_id" "uuid", "p_access_token" "text", "p_refresh_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_access_key text := 'google_access_token:' || p_user_id::text;
  v_refresh_key text := 'google_refresh_token:' || p_user_id::text;
BEGIN
  DELETE FROM vault.secrets WHERE name = v_access_key;
  DELETE FROM vault.secrets WHERE name = v_refresh_key;
  INSERT INTO vault.secrets (name, secret) VALUES (v_access_key, p_access_token);
  INSERT INTO vault.secrets (name, secret) VALUES (v_refresh_key, p_refresh_token);
END;
$$;


ALTER FUNCTION "public"."store_user_token"("p_user_id" "uuid", "p_access_token" "text", "p_refresh_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."student_audience_matches"("p_crit" "jsonb", "p_academic_year" integer, "p_semester" integer) RETURNS TABLE("resource_id" "uuid", "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_type     text := p_crit->>'type';
  v_grades   int[];
  v_classes  int[];
  v_days     int[];
  v_periods  int[];
  v_names    text[];
  v_subjects text[];
  v_ids      uuid[];
  v_teachers uuid[];
  v_grade    int;
  v_semester int;
  c_days constant text[] := array['월', '화', '수', '목', '금', '토', '일'];
begin
  select array_agg(x::int) into v_grades from jsonb_array_elements_text(
    case when jsonb_typeof(p_crit->'grades') = 'array' then p_crit->'grades' else '[]'::jsonb end) x where x ~ '^[0-9]+$';
  select array_agg(x::int) into v_classes from jsonb_array_elements_text(
    case when jsonb_typeof(p_crit->'classes') = 'array' then p_crit->'classes' else '[]'::jsonb end) x where x ~ '^[0-9]+$';
  select array_agg(x::int) into v_days from jsonb_array_elements_text(
    case when jsonb_typeof(p_crit->'days') = 'array' then p_crit->'days' else '[]'::jsonb end) x where x ~ '^[0-9]+$';
  select array_agg(x::int) into v_periods from jsonb_array_elements_text(
    case when jsonb_typeof(p_crit->'periods') = 'array' then p_crit->'periods' else '[]'::jsonb end) x where x ~ '^[0-9]+$';
  select array_agg(btrim(x)) into v_names from jsonb_array_elements_text(
    case when jsonb_typeof(p_crit->'names') = 'array' then p_crit->'names' else '[]'::jsonb end) x where btrim(x) <> '';
  select array_agg(btrim(x)) into v_subjects from jsonb_array_elements_text(
    case when jsonb_typeof(p_crit->'subjects') = 'array' then p_crit->'subjects' else '[]'::jsonb end) x where btrim(x) <> '';
  select array_agg(x::uuid) into v_ids from jsonb_array_elements_text(
    case when jsonb_typeof(p_crit->'ids') = 'array' then p_crit->'ids' else '[]'::jsonb end) x where x ~ '^[0-9a-fA-F-]{36}$';
  select array_agg(x::uuid) into v_teachers from jsonb_array_elements_text(
    case when jsonb_typeof(p_crit->'teacher_ids') = 'array' then p_crit->'teacher_ids' else '[]'::jsonb end) x where x ~ '^[0-9a-fA-F-]{36}$';
  if p_crit->>'grade' ~ '^[0-9]+$' then v_grade := (p_crit->>'grade')::int; end if;
  if p_crit->>'semester' ~ '^[12]$' then v_semester := (p_crit->>'semester')::int; end if;

  if v_type = 'all_students' then
    return query select p.resource_id, '재학생'::text from public.student_audience_pool() p;

  elsif v_type = 'current_class' then
    if v_grades is null and v_classes is null then
      raise exception '현재 학년·반 조건에 학년이나 반이 없습니다' using errcode = '22023';
    end if;
    return query
      select p.resource_id,
             case when v_classes is null then p.grade || '학년'
                  else p.grade || '학년 ' || p.class || '반' end
      from public.student_audience_pool() p
      where (v_grades is null or p.grade = any (v_grades))
        and (v_classes is null or p.class = any (v_classes));

  elsif v_type = 'past_class' then
    if v_grade is null or v_grade not between 1 and 3 or v_classes is null then
      raise exception '「N학년 때 반」 조건에는 학년(1~3)과 반이 필요합니다' using errcode = '22023';
    end if;
    -- snumN = 그 학년 때 학번 5자리(학년 1 + 반 2 + 번호 2)
    return query
      select p.resource_id, v_grade || '학년 때 ' || substr(p.meta->>('snum' || v_grade), 2, 2)::int || '반'
      from public.student_audience_pool() p
      where p.meta->>('snum' || v_grade) ~ '^[1-3][0-9]{4}$'
        and substr(p.meta->>('snum' || v_grade), 1, 1)::int = v_grade
        and substr(p.meta->>('snum' || v_grade), 2, 2)::int = any (v_classes);

  elsif v_type = 'club' then
    if v_names is null then
      raise exception '동아리 조건에 동아리 이름이 없습니다' using errcode = '22023';
    end if;
    -- 올해 활동 중인 동아리만(지금은 없는 동아리는 고르지 않는다 — 2026-10-01 사용자 결정)
    return query
      select distinct p.resource_id, '동아리 · ' || c.name
      from public.club_info c
      cross join lateral jsonb_array_elements(coalesce(c.students, '[]'::jsonb)) s
      join public.student_audience_pool() p on p.resource_id::text = s->>'resource_id'
      where c.academic_year = p_academic_year
        and coalesce(c.meta->>'status', 'active') = 'active'
        and c.name = any (v_names);

  elsif v_type = 'course' then
    if v_subjects is null then
      raise exception '수강 과목 조건에 과목이 없습니다' using errcode = '22023';
    end if;
    return query
      select distinct p.resource_id, '수강 · ' || t.subject
      from public.student_timetable t
      join public.student_audience_pool() p on p.resource_id = t.resource_id
      where t.academic_year = p_academic_year and t.semester = p_semester
        and t.subject = any (v_subjects)
        and (v_teachers is null or t.teacher_resource_id = any (v_teachers));

  elsif v_type = 'slot' then
    if v_days is null and v_periods is null then
      raise exception '요일·교시 조건에 요일이나 교시가 없습니다' using errcode = '22023';
    end if;
    return query
      select distinct p.resource_id,
             coalesce(c_days[t.day_of_week], t.day_of_week::text) || ' ' || t.period || '교시 · ' || t.subject
      from public.student_timetable t
      join public.student_audience_pool() p on p.resource_id = t.resource_id
      where t.academic_year = p_academic_year and t.semester = p_semester
        and (v_days is null or t.day_of_week = any (v_days))
        and (v_periods is null or t.period = any (v_periods))
        and (v_subjects is null or t.subject = any (v_subjects));

  elsif v_type = 'my_students' then
    return query
      select distinct p.resource_id, '내 수업 · ' || t.subject
      from public.student_timetable t
      join public.student_audience_pool() p on p.resource_id = t.resource_id
      where t.academic_year = p_academic_year and t.semester = p_semester
        and t.teacher_resource_id in (select public.current_actor_resource_ids())
        and (v_subjects is null or t.subject = any (v_subjects));

  elsif v_type = 'my_homeroom' then
    -- 담임 = 태그 'N학년 M반'(resource.meta 의 grade/class_number 는 라이브 0건)
    return query
      select p.resource_id, '내 반 · ' || p.grade || '학년 ' || p.class || '반'
      from public.resource_tag_assignments a
      join public.resource_tags tg on tg.id = a.tag_id
      cross join lateral regexp_match(tg.name, '^([0-9])학년 ([0-9]+)반$') m
      join public.student_audience_pool() p on p.grade = m[1]::int and p.class = m[2]::int
      where a.resource_id in (select public.current_actor_resource_ids())
        and m is not null;

  elsif v_type = 'past_course' then
    -- 끝난 학기의 수강 = 생기부 성적 기록(student_academic_flat). 그 학생이 N학년(·M학기)였을 때.
    -- 이번 학기는 성적이 아직 없다 → 지금 듣는 과목은 course 조건(시간표)으로.
    if v_grade is null or v_grade not between 1 and 3 or v_subjects is null then
      raise exception '「N학년 때 들은 과목」 조건에는 학년(1~3)과 과목이 필요합니다' using errcode = '22023';
    end if;
    return query
      select distinct p.resource_id,
             v_grade || '학년' || coalesce(' ' || f.semester || '학기', '') || ' · ' || f.subject
      from public.student_academic_flat f
      join public.student_audience_pool() p on p.student_code = f.student_code
      where f.grade = v_grade
        and (v_semester is null or f.semester = v_semester)
        and f.subject = any (v_subjects);

  elsif v_type = 'teacher_students' then
    -- 그 선생님 수업을 듣는 학생(이번 학기 시간표). 과목을 주면 그 과목만.
    if v_teachers is null then
      raise exception '「선생님 수업」 조건에 선생님이 없습니다' using errcode = '22023';
    end if;
    return query
      select distinct p.resource_id, coalesce(r.name, '?') || ' 선생님 · ' || t.subject
      from public.student_timetable t
      join public.student_audience_pool() p on p.resource_id = t.resource_id
      left join public.resource r on r.id = t.teacher_resource_id
      where t.academic_year = p_academic_year and t.semester = p_semester
        and t.teacher_resource_id = any (v_teachers)
        and (v_subjects is null or t.subject = any (v_subjects));

  elsif v_type = 'people' then
    return query
      select p.resource_id, '직접 지정'::text
      from public.student_audience_pool() p
      where p.resource_id = any (coalesce(v_ids, '{}'));

  else
    raise exception '알 수 없는 학생 조건: %', coalesce(v_type, '(없음)') using errcode = '22023';
  end if;
end;
$_$;


ALTER FUNCTION "public"."student_audience_matches"("p_crit" "jsonb", "p_academic_year" integer, "p_semester" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."student_audience_matches"("p_crit" "jsonb", "p_academic_year" integer, "p_semester" integer) IS '학생 대상 조건 하나의 해석. type = all_students|current_class|past_class|past_course|club|course|teacher_students|slot|my_students|my_homeroom|people. 모르는 type 은 거부.';



CREATE OR REPLACE FUNCTION "public"."student_audience_pool"() RETURNS TABLE("resource_id" "uuid", "name" "text", "student_code" "text", "grade" integer, "class" integer, "number" integer, "meta" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  select r.id, r.name, r.meta->>'id',
         case when r.meta->>'grade' ~ '^[0-9]+$' then (r.meta->>'grade')::int end,
         case when r.meta->>'class' ~ '^[0-9]+$' then (r.meta->>'class')::int end,
         case when r.meta->>'number' ~ '^[0-9]+$' then (r.meta->>'number')::int end,
         r.meta
  from public.resource r
  where r.type = 'student'
    and r.status = 'active'
    and coalesce(r.meta->>'test_account', 'false') <> 'true';   -- 면접 준비 체험용 테스트 학생 제외
$_$;


ALTER FUNCTION "public"."student_audience_pool"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."student_audience_pool"() IS '학생 대상 규칙의 모집단 — 재학생(status=active), 테스트 계정 제외. 학생 조건은 전부 여기에 조인한다.';



CREATE OR REPLACE FUNCTION "public"."subject_cluster_names"() RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select array['어문학과', '영어', '수학', '사회(역사/도덕 포함)', '과학', '예체능', '교양']::text[];
$$;


ALTER FUNCTION "public"."subject_cluster_names"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."subject_cluster_names"() IS '교과 묶음 7종. 순서 = 표시 순서. 클라이언트 짝 = src/lib/subjectClassification.ts SUBJECT_CLUSTERS.';



CREATE OR REPLACE FUNCTION "public"."subject_cluster_of"("p_subject" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select sc.cluster_override from public.subject_classification sc where sc.subject_name = btrim(p_subject)),
    public.subject_cluster_of_group(public.subject_group_of(p_subject))
  );
$$;


ALTER FUNCTION "public"."subject_cluster_of"("p_subject" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."subject_cluster_of"("p_subject" "text") IS '과목의 교과 묶음 — 과목 예외(cluster_override) 우선, 없으면 교과(군)에서 유도.';



CREATE OR REPLACE FUNCTION "public"."subject_cluster_of_group"("p_group" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case p_group
    when '국어'                 then '어문학과'
    when '제2외국어/한문'       then '어문학과'
    when '영어'                 then '영어'
    when '수학'                 then '수학'
    when '사회(역사/도덕 포함)' then '사회(역사/도덕 포함)'
    when '과학'                 then '과학'
    when '기술·가정/정보'       then '예체능'
    when '체육'                 then '예체능'
    when '예술'                 then '예체능'
    when '교양'                 then '예체능'
    else null
  end;
$$;


ALTER FUNCTION "public"."subject_cluster_of_group"("p_group" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."subject_cluster_of_group"("p_group" "text") IS '교과(군) → 교과 묶음. 과목 단위 예외는 subject_classification.cluster_override. 클라이언트 짝 = GROUP_TO_CLUSTER.';



CREATE OR REPLACE FUNCTION "public"."subject_group_catalog"("p_academic_year" integer DEFAULT NULL::integer) RETURNS TABLE("subject_name" "text", "subject_group" "text", "subject_cluster" "text", "cluster_override" "text", "source" "text", "taught_grades" integer[], "teacher_count" integer, "curriculum_labels" "text"[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with yr as (
    select coalesce(p_academic_year, (select academic_year from public.current_academic_term())) y
  ),
  taught as (
    select tt.subject_name,
           array_agg(distinct tt.grade order by tt.grade) grades,
           count(distinct coalesce(tt.teacher_resource_id::text, tt.teacher_name))::int teachers
    from public.teacher_timetable tt, yr
    where tt.activity_type = 'subject' and tt.academic_year = yr.y
    group by 1
  ),
  labels as (
    select c.subject, array_agg(distinct c.category order by c.category) cats
    from public.school_curriculum c
    group by 1
  ),
  names as (
    select subject_name from public.subject_classification
    union select subject_name from taught
  )
  select n.subject_name,
         public.subject_group_of(n.subject_name),
         public.subject_cluster_of(n.subject_name),
         sc.cluster_override,
         case
           when sc.subject_name is not null then sc.source
           when public.subject_group_of(n.subject_name) is not null then 'fallback'
           else 'none'
         end,
         coalesce(t.grades, '{}'::int[]),
         coalesce(t.teachers, 0),
         coalesce(l.cats, '{}'::text[])
  from names n
  left join public.subject_classification sc on sc.subject_name = n.subject_name
  left join taught t on t.subject_name = n.subject_name
  left join labels l on l.subject = n.subject_name
  order by (t.subject_name is null), n.subject_name;
$$;


ALTER FUNCTION "public"."subject_group_catalog"("p_academic_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."subject_group_catalog"("p_academic_year" integer) IS '교과 분류 관리 화면용. 분류 표 ∪ 그 학년도 개설 과목, 교과(군)·묶음 판정은 subject_group_of·subject_cluster_of 단일 출처.';



CREATE OR REPLACE FUNCTION "public"."subject_group_names"() RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select array[
    '국어', '수학', '영어', '사회(역사/도덕 포함)', '과학',
    '체육', '예술', '기술·가정/정보', '제2외국어/한문', '교양'
  ]::text[];
$$;


ALTER FUNCTION "public"."subject_group_names"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."subject_group_names"() IS '교과(군) 10종(2022 개정). 순서가 곧 표시 순서다. 클라이언트 짝 = src/lib/subjectClassification.ts SUBJECT_GROUPS.';



CREATE OR REPLACE FUNCTION "public"."subject_group_of"("p_subject" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select sc.subject_group from public.subject_classification sc
      where sc.subject_name = btrim(p_subject)),
    (select g from (
       select public.normalize_subject_group(c.category) g, count(*) n
       from public.school_curriculum c
       where c.subject = btrim(p_subject)
       group by 1
     ) x where g is not null order by n desc, g limit 1)
  );
$$;


ALTER FUNCTION "public"."subject_group_of"("p_subject" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."subject_group_of"("p_subject" "text") IS '과목의 교과(군). subject_classification 우선, 없으면 school_curriculum 원본 라벨 정규화. 둘 다 없으면 NULL(미분류).';



CREATE OR REPLACE FUNCTION "public"."submission_held_units"("p_task_id" "uuid", "p_resource_id" "uuid") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(u.key order by u.key), '{}')
  from public.task t,
       lateral jsonb_each(case when jsonb_typeof(t.meta->'unitProgress') = 'object' then t.meta->'unitProgress' else '{}'::jsonb end) u
  where t.id = p_task_id and jsonb_typeof(u.value) = 'object' and u.value ? p_resource_id::text;
$$;


ALTER FUNCTION "public"."submission_held_units"("p_task_id" "uuid", "p_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submission_sync_assignee"("p_task_id" "uuid", "p_resource_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_meta jsonb;
  v_status text;
begin
  select coalesce(meta, '{}'::jsonb) into v_meta from public.task where id = p_task_id;
  if not found then return; end if;
  if jsonb_typeof(v_meta->'units') = 'array' and jsonb_array_length(v_meta->'units') > 0 then return; end if;
  select coalesce(a.value->>'status', 'pending') into v_status
  from jsonb_array_elements(case when jsonb_typeof(v_meta->'assignees') = 'array'
                                 then v_meta->'assignees' else '[]'::jsonb end) a(value)
  where a.value->>'id' = p_resource_id::text
  limit 1;
  if v_status is null or v_status = 'cancelled' then return; end if;

  if public.assignee_has_pending_submission(p_task_id, p_resource_id) then
    if v_status = 'completed' then
      perform public.set_task_assignee_status(p_task_id, p_resource_id, 'pending');
    end if;
  elsif v_status <> 'completed' then
    perform public.set_task_assignee_status(p_task_id, p_resource_id, 'completed');
  end if;
end;
$$;


ALTER FUNCTION "public"."submission_sync_assignee"("p_task_id" "uuid", "p_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submission_target_complete"("p_action_id" "uuid", "p_resource_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.collect_request;
begin
  select * into v_req from public.collect_request where action_id = p_action_id;
  if not found then return false; end if;
  if v_req.axis = 'unit' then
    return cardinality(public.submission_held_units(v_req.task_id, p_resource_id)) > 0
       and not public.submission_target_pending(p_action_id, p_resource_id);
  end if;
  return exists (select 1 from public.action_submission s where s.action_id = p_action_id and s.resource_id = p_resource_id);
end;
$$;


ALTER FUNCTION "public"."submission_target_complete"("p_action_id" "uuid", "p_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submission_target_pending"("p_action_id" "uuid", "p_resource_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.collect_request;
begin
  select * into v_req from public.collect_request where action_id = p_action_id;
  if not found then return false; end if;
  if v_req.axis = 'unit' then
    return exists (
      select 1 from unnest(public.submission_held_units(v_req.task_id, p_resource_id)) h(key)
      where not exists (select 1 from public.action_submission s
                        where s.action_id = p_action_id and s.resource_id = p_resource_id and s.unit_key = h.key));
  end if;
  return not exists (select 1 from public.action_submission s where s.action_id = p_action_id and s.resource_id = p_resource_id);
end;
$$;


ALTER FUNCTION "public"."submission_target_pending"("p_action_id" "uuid", "p_resource_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_action_document"("p_action_id" "uuid", "p_document_id" "uuid", "p_unit_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.collect_request;
  v_me  uuid := public.current_actor_resource_id();
  v_doc public.task_action_document;
  v_unit text;
  v_existing uuid;
  v_id  uuid;
begin
  v_req := public._submission_open_for_me(p_action_id, 'document');
  v_unit := public._submission_check_unit(v_req, p_unit_key);
  select * into v_doc from public.task_action_document where id = p_document_id for update;
  if not found or v_doc.archived_at is not null then raise exception '문서를 찾을 수 없습니다' using errcode = 'P0002'; end if;
  if v_doc.created_by <> auth.uid() then raise exception '직접 쓴 문서만 낼 수 있습니다' using errcode = '42501'; end if;
  if v_doc.action_id is distinct from p_action_id then
    raise exception '이 요청의 양식으로 쓴 문서가 아닙니다' using errcode = '0A000';
  end if;
  if v_doc.status = 'draft' then
    update public.task_action_document set status = 'final' where id = p_document_id;
  end if;
  select id into v_existing from public.action_submission
   where action_id = p_action_id and resource_id = v_me and coalesce(unit_key, '') = coalesce(v_unit, '') for update;
  if v_existing is not null then
    update public.action_submission set document_id = p_document_id, file_name = v_doc.title, updated_at = now()
     where id = v_existing;
    v_id := v_existing;
  else
    insert into public.action_submission (action_id, resource_id, kind, unit_key, document_id, file_name, submitted_by)
    values (p_action_id, v_me, 'document', v_unit, p_document_id, v_doc.title, auth.uid())
    returning id into v_id;
  end if;
  perform public._submission_sync_unit(v_req, v_me, v_unit);
  perform public.submission_sync_assignee(v_req.task_id, v_me);
  return jsonb_build_object('success', true, 'submission_id', v_id, 'resubmitted', v_existing is not null);
end;
$$;


ALTER FUNCTION "public"."submit_action_document"("p_action_id" "uuid", "p_document_id" "uuid", "p_unit_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_action_file"("p_action_id" "uuid", "p_file_name" "text", "p_file_url" "text", "p_google_drive_id" "text" DEFAULT NULL::"text", "p_mime_type" "text" DEFAULT NULL::"text", "p_file_size" bigint DEFAULT NULL::bigint, "p_unit_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req public.collect_request;
  v_me  uuid := public.current_actor_resource_id();
  v_unit text;
  v_id  uuid;
begin
  v_req := public._submission_open_for_me(p_action_id, 'file');
  v_unit := public._submission_check_unit(v_req, p_unit_key);
  if coalesce(btrim(p_file_name), '') = '' or coalesce(btrim(p_file_url), '') = '' then
    raise exception '파일 이름과 주소가 필요합니다' using errcode = '22023';
  end if;
  insert into public.action_submission (action_id, resource_id, kind, unit_key, file_name, file_url, google_drive_id, mime_type, file_size, submitted_by)
  values (p_action_id, v_me, 'file', v_unit, p_file_name, p_file_url, p_google_drive_id, p_mime_type, p_file_size, auth.uid())
  returning id into v_id;
  perform public._submission_sync_unit(v_req, v_me, v_unit);
  perform public.submission_sync_assignee(v_req.task_id, v_me);
  return jsonb_build_object('success', true, 'submission_id', v_id);
end;
$$;


ALTER FUNCTION "public"."submit_action_file"("p_action_id" "uuid", "p_file_name" "text", "p_file_url" "text", "p_google_drive_id" "text", "p_mime_type" "text", "p_file_size" bigint, "p_unit_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_cfg_of"("p_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object('audience', '{"include":[{"type":"task_assignees"}],"exclude":[]}'::jsonb)
         || coalesce(case when jsonb_typeof(p_config->'submit') = 'object' then p_config->'submit' end, '{}'::jsonb);
$$;


ALTER FUNCTION "public"."submit_cfg_of"("p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_collect_response"("p_action_id" "uuid", "p_unit_key" "text", "p_dimension_key" "text", "p_values" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_req     public.collect_request;
  v_cfg     jsonb;
  v_actor   uuid;
  v_clean   jsonb;
  v_owner   text;
  v_dim     text := coalesce(p_dimension_key, '');
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into v_req from public.collect_request where action_id = p_action_id;
  if not found then raise exception '요청을 찾을 수 없습니다' using errcode = 'P0002'; end if;
  if v_req.status <> 'open' then raise exception '마감된 요청입니다' using errcode = '22023'; end if;

  -- 내가 그 단위의 대상인가
  select t.resource_id into v_actor
  from public.collect_target t
  join public.current_actor_resource_ids() me on me = t.resource_id
  where t.action_id = p_action_id and t.unit_key = p_unit_key and t.removed_at is null
  limit 1;
  if v_actor is null then raise exception '이 줄에 입력할 대상이 아닙니다' using errcode = '42501'; end if;

  select config->'collect' into v_cfg from public.task_action where id = p_action_id;
  if jsonb_array_length(coalesce(v_cfg->'dimensions', '[]'::jsonb)) = 0 then
    if v_dim <> '' then raise exception '구분이 없는 요청입니다' using errcode = '22023'; end if;
  elsif not exists (select 1 from jsonb_array_elements(v_cfg->'dimensions') d where d.value->>'key' = v_dim) then
    raise exception '알 수 없는 구분입니다' using errcode = '22023';
  end if;

  v_clean := public.collect_clean_values(coalesce(p_values, '{}'::jsonb), v_cfg->'fields');
  v_owner := case when v_req.answer_mode = 'shared' then '' else v_actor::text end;

  if v_clean = '{}'::jsonb then
    delete from public.collect_response
     where action_id = p_action_id and unit_key = p_unit_key and dimension_key = v_dim and owner_key = v_owner;
  else
    insert into public.collect_response (action_id, unit_key, dimension_key, owner_key, responder_resource_id, "values")
    values (p_action_id, p_unit_key, v_dim, v_owner, v_actor, v_clean)
    on conflict (action_id, unit_key, dimension_key, owner_key)
    do update set "values" = excluded."values", responder_resource_id = excluded.responder_resource_id, updated_at = now();
  end if;

  return jsonb_build_object('values', v_clean, 'complete', public.collect_cell_complete(v_clean, v_cfg->'fields'));
end;
$$;


ALTER FUNCTION "public"."submit_collect_response"("p_action_id" "uuid", "p_unit_key" "text", "p_dimension_key" "text", "p_values" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_config_error"("p_type" "text", "p_cfg" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when jsonb_typeof(p_cfg->'audience'->'include') is distinct from 'array'
      or jsonb_array_length(p_cfg->'audience'->'include') = 0 then '대상을 정하세요.'
    when p_type = 'submit.document' and coalesce(p_cfg->'template'->>'id', '') = '' then '양식을 고르세요.'
  end;
$$;


ALTER FUNCTION "public"."submit_config_error"("p_type" "text", "p_cfg" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_task_spec_submission"("p_task_id" "uuid", "p_document_id" "uuid", "p_unit_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  actor uuid := public.current_actor_resource_id();
  t_meta jsonb;
  sub jsonb;
  v_action_id uuid;
  d_created_by uuid;
  d_title text;
  d_status text;
  d_action_id uuid;
  d_archived timestamptz;
  existing_id uuid;
  new_id uuid;
  deadline_count int := 0;
  units jsonb;
begin
  if auth.uid() is null or actor is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select coalesce(meta, '{}'::jsonb) into t_meta from public.task where id = p_task_id;
  if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;

  if not public.is_task_assignee(p_task_id, actor) then
    raise exception 'Only an assignee can submit' using errcode = '42501';
  end if;

  sub := t_meta -> 'submission';
  -- 방식 배타(D3): 이 업무가 값 제출을 받도록 설정돼 있어야 한다
  if coalesce(sub ->> 'required', 'false') <> 'true'
     or coalesce(sub ->> 'mode', 'file') <> 'spec' then
    raise exception 'This task does not accept spec submissions' using errcode = '0A000';
  end if;
  v_action_id := nullif(sub ->> 'workId', '')::uuid;

  -- 다중 마감과 상호 배타 — 회차별 완료가 meta.deadlineProgress 에 따로 있어
  -- "제출=완료" 한 줄로 표현되지 않는다(파일 제출과 같은 이유)
  if jsonb_typeof(t_meta -> 'deadlines') = 'array' then
    deadline_count := jsonb_array_length(t_meta -> 'deadlines');
  end if;
  if deadline_count > 1 then
    raise exception 'Not supported for tasks with multiple deadlines' using errcode = '0A000';
  end if;

  -- 과제 단위: 단위 업무면 필수·실재 검증, 아니면 null 강제(파일 RPC 와 동일)
  units := t_meta -> 'units';
  if jsonb_typeof(units) = 'array' and jsonb_array_length(units) > 0 then
    if p_unit_key is null then raise exception 'unit_key required' using errcode = '22023'; end if;
    if not exists (select 1 from jsonb_array_elements(units) u where u ->> 'key' = p_unit_key) then
      raise exception 'Unknown unit' using errcode = '22023';
    end if;
  else
    p_unit_key := null;
  end if;

  select created_by, title, status, action_id, archived_at
    into d_created_by, d_title, d_status, d_action_id, d_archived
    from public.task_action_document where id = p_document_id for update;
  if not found or d_archived is not null then
    raise exception 'Document not found' using errcode = 'P0002';
  end if;
  if d_created_by <> auth.uid() then
    raise exception 'Only the author can submit this document' using errcode = '42501';
  end if;
  -- 이 업무의 제출용 WORK 에서 만든 문서여야 한다(= 매니저가 정한 양식으로 쓴 것)
  if v_action_id is null or d_action_id is distinct from v_action_id then
    raise exception 'Document was not created for this task''s template' using errcode = '0A000';
  end if;

  -- 제출 시점 고정: draft → final (계보 트리거가 이 전이만 허용한다)
  if d_status = 'draft' then
    update public.task_action_document set status = 'final' where id = p_document_id;
  end if;

  -- 재제출 = 같은 (업무, 담당자, 단위) 행의 참조를 새 버전으로 **옮긴다**.
  -- 삭제 후 삽입이면 완료 상태가 잠깐 pending 으로 흔들리고 이력이 2건 남는다.
  select id into existing_id from public.task_submission
   where task_id = p_task_id and assignee_resource_id = actor and kind = 'spec'
     and coalesce(unit_key, '') = coalesce(p_unit_key, '')
   for update;

  if existing_id is not null then
    update public.task_submission
       set spec_document_id = p_document_id,
           file_name = d_title,
           meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('resubmitted_at', now())
     where id = existing_id;
    new_id := existing_id;
  else
    insert into public.task_submission
      (task_id, assignee_resource_id, submitted_by, kind, spec_document_id, file_name, file_url, unit_key, meta)
    values
      (p_task_id, actor, auth.uid(), 'spec', p_document_id, d_title, null, p_unit_key, '{}'::jsonb)
    returning id into new_id;
  end if;

  -- 제출이 곧 완료 — 파일 RPC 와 같은 분기
  if p_unit_key is not null then
    perform public.set_task_unit_status(p_task_id, p_unit_key, actor, 'completed');
  else
    perform public.set_task_assignee_status(p_task_id, actor, 'completed');
  end if;

  return jsonb_build_object(
    'success', true, 'submission_id', new_id,
    'document_id', p_document_id, 'resubmitted', existing_id is not null
  );
end $$;


ALTER FUNCTION "public"."submit_task_spec_submission"("p_task_id" "uuid", "p_document_id" "uuid", "p_unit_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_task_spreadsheet_submission"("p_task_id" "uuid", "p_rows" "jsonb", "p_columns" "jsonb", "p_unit_key" "text" DEFAULT NULL::"text", "p_expected_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor uuid := public.current_actor_resource_id(); t_meta jsonb; s jsonb;
  existing public.task_submission%rowtype; result_id uuid; r jsonb; cell jsonb;
  has_units boolean; column_count integer;
begin
  if auth.uid() is null or actor is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  select meta into t_meta from public.task where id = p_task_id for update;
  if not found then raise exception '할 일을 찾을 수 없습니다.' using errcode = 'P0002'; end if;
  if not public.is_task_assignee(p_task_id, actor) then raise exception '담당자만 제출할 수 있습니다.' using errcode = '42501'; end if;
  s := t_meta->'submission';
  if coalesce(s->>'required', 'false') <> 'true' or coalesce(s->>'mode', 'file') <> 'spreadsheet' then
    raise exception '스프레드시트 제출 할 일이 아닙니다.' using errcode = '22023';
  end if;
  if p_columns is distinct from s->'columns' then raise exception '컬럼 설정이 변경되었습니다. 화면을 다시 열어 주세요.' using errcode = '40001'; end if;
  if jsonb_array_length(case when jsonb_typeof(t_meta->'deadlines') = 'array' then t_meta->'deadlines' else '[]'::jsonb end) > 1 then raise exception '다중 마감 할 일에는 제출할 수 없습니다.' using errcode = '22023'; end if;
  has_units := jsonb_array_length(case when jsonb_typeof(t_meta->'units') = 'array' then t_meta->'units' else '[]'::jsonb end) > 0;
  if has_units then
    if p_unit_key is null or not exists (select 1 from jsonb_array_elements(t_meta->'units') u where u->>'key' = p_unit_key) then
      raise exception '제출할 과제 단위를 선택해 주세요.' using errcode = '22023';
    end if;
  elsif p_unit_key is not null then raise exception '과제 단위가 없는 할 일입니다.' using errcode = '22023'; end if;
  column_count := jsonb_array_length(s->'columns');
  if jsonb_typeof(p_rows) is distinct from 'array' then raise exception '표 데이터를 입력해 주세요.' using errcode = '22023'; end if;
  if column_count not between 1 and 30 or jsonb_array_length(p_rows) not between 1 and 500 or pg_column_size(p_rows) > 2000000 then
    raise exception '표 입력 한도를 초과했습니다. 최대 500행, 2MB입니다.' using errcode = '22023';
  end if;
  for r in select value from jsonb_array_elements(p_rows) loop
    if jsonb_typeof(r) <> 'array' then raise exception '행 형식이 올바르지 않습니다.' using errcode = '22023'; end if;
    if jsonb_array_length(r) <> column_count then raise exception '컬럼 수가 일치하지 않습니다.' using errcode = '22023'; end if;
    for cell in select value from jsonb_array_elements(r) loop
      if jsonb_typeof(cell) <> 'string' or length(cell #>> '{}') > 5000 then raise exception '셀은 5,000자 이내의 텍스트여야 합니다.' using errcode = '22023'; end if;
    end loop;
    if not exists (select 1 from jsonb_array_elements_text(r) v where btrim(v) <> '') then raise exception '빈 행을 채우거나 삭제해 주세요.' using errcode = '22023'; end if;
  end loop;
  select * into existing from public.task_submission where task_id = p_task_id and assignee_resource_id = actor
    and kind = 'spreadsheet' and unit_key is not distinct from p_unit_key for update;
  if existing.created_at is distinct from p_expected_updated_at then
    raise exception '제출 데이터가 다른 창에서 변경되었습니다. 작성 내용을 복사한 뒤 화면을 다시 열어 주세요.' using errcode = '40001';
  end if;
  if existing.id is null then
    insert into public.task_submission(task_id, assignee_resource_id, submitted_by, kind, file_name, unit_key, spreadsheet_data)
    values (p_task_id, actor, auth.uid(), 'spreadsheet', '스프레드시트 제출', p_unit_key, jsonb_build_object('columns', s->'columns', 'rows', p_rows)) returning id into result_id;
  else
    update public.task_submission set spreadsheet_data = jsonb_build_object('columns', s->'columns', 'rows', p_rows), created_at = clock_timestamp()
      where id = existing.id returning id into result_id;
  end if;
  if has_units then perform public.set_task_unit_status(p_task_id, p_unit_key, actor, 'completed');
  else perform public.set_task_assignee_status(p_task_id, actor, 'completed'); end if;
  return jsonb_build_object('submission_id', result_id);
end;
$$;


ALTER FUNCTION "public"."submit_task_spreadsheet_submission"("p_task_id" "uuid", "p_rows" "jsonb", "p_columns" "jsonb", "p_unit_key" "text", "p_expected_updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_task_submission"("p_task_id" "uuid", "p_file_name" "text", "p_file_url" "text", "p_edit_url" "text" DEFAULT NULL::"text", "p_google_drive_id" "text" DEFAULT NULL::"text", "p_mime_type" "text" DEFAULT NULL::"text", "p_file_size" bigint DEFAULT NULL::bigint, "p_meta" "jsonb" DEFAULT '{}'::"jsonb", "p_unit_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  actor_resource_id uuid;
  task_meta jsonb;
  deadline_count int := 0;
  has_units boolean := FALSE;
  unit_found boolean := FALSE;
  new_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  IF p_file_name IS NULL OR LENGTH(TRIM(p_file_name)) = 0
     OR p_file_url IS NULL OR LENGTH(TRIM(p_file_url)) = 0 THEN
    RAISE EXCEPTION 'File name and url are required' USING ERRCODE = '22023';
  END IF;

  actor_resource_id := public.current_actor_resource_id();
  IF actor_resource_id IS NULL THEN
    RAISE EXCEPTION 'User resource not found' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(t.meta, '{}'::jsonb) INTO task_meta
  FROM public.task t WHERE t.id = p_task_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Task not found: %', p_task_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.is_task_assignee(p_task_id, actor_resource_id) THEN
    RAISE EXCEPTION 'Only an assignee of this task can submit files' USING ERRCODE = '42501';
  END IF;

  -- 방식 배타(2026-09-03): 값 제출로 설정된 업무에는 파일을 올릴 수 없다.
  -- 한 업무에 두 방식이 섞이면 매니저 현황·"표로 보기"·분석 뷰가 이종 행을 섞는다.
  IF COALESCE(task_meta->'submission'->>'mode', 'file') = 'spec' THEN
    RAISE EXCEPTION 'This task accepts document submissions, not files'
      USING ERRCODE = '0A000';
  END IF;

  -- 회차별 제출(다중 마감)은 지원하지 않는다. 회차 기록은 meta.deadlineProgress 에
  -- 따로 있어 "제출=완료" 한 줄로 표현할 수 없으므로, 조용히 잘못 완료시키느니 막는다.
  IF jsonb_typeof(task_meta->'deadlines') = 'array' THEN
    deadline_count := jsonb_array_length(task_meta->'deadlines');
  END IF;
  IF deadline_count > 1 THEN
    RAISE EXCEPTION 'File submission is not supported for tasks with multiple deadlines yet'
      USING ERRCODE = '0A000';
  END IF;

  -- 과제 단위 업무: 어느 단위의 제출인지 필수. 제출이 곧 그 단위의 선택+완료다.
  has_units := jsonb_typeof(task_meta->'units') = 'array'
    AND jsonb_array_length(task_meta->'units') > 0;

  IF has_units THEN
    IF p_unit_key IS NULL THEN
      RAISE EXCEPTION 'A unit must be selected for this task' USING ERRCODE = '22023';
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM jsonb_array_elements(task_meta->'units') AS unit(value)
      WHERE value->>'key' = p_unit_key
    ) INTO unit_found;
    IF NOT unit_found THEN
      RAISE EXCEPTION 'Unit % is not defined on task %', p_unit_key, p_task_id
        USING ERRCODE = '22023';
    END IF;
  ELSIF p_unit_key IS NOT NULL THEN
    RAISE EXCEPTION 'This task has no units' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.task_submission (
    task_id, assignee_resource_id, submitted_by,
    file_name, file_url, edit_url, google_drive_id, mime_type, file_size, meta, unit_key
  )
  VALUES (
    p_task_id, actor_resource_id, auth.uid(),
    p_file_name, p_file_url, p_edit_url, p_google_drive_id, p_mime_type, p_file_size,
    COALESCE(p_meta, '{}'::jsonb), p_unit_key
  )
  RETURNING id INTO new_id;

  -- 제출이 곧 완료다. 단위 업무는 그 단위만, 일반 업무는 담당자 상태를 완료로.
  IF has_units THEN
    PERFORM public.set_task_unit_status(p_task_id, p_unit_key, actor_resource_id, 'completed');
  ELSE
    PERFORM public.set_task_assignee_status(p_task_id, actor_resource_id, 'completed');
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'submission_id', new_id,
    'task_id', p_task_id,
    'assignee_id', actor_resource_id,
    'unit_key', p_unit_key
  );
END;
$$;


ALTER FUNCTION "public"."submit_task_submission"("p_task_id" "uuid", "p_file_name" "text", "p_file_url" "text", "p_edit_url" "text", "p_google_drive_id" "text", "p_mime_type" "text", "p_file_size" bigint, "p_meta" "jsonb", "p_unit_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supervision_assignee_names"("p_meta" "jsonb") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select coalesce(array(
    select k from jsonb_object_keys(
      case when jsonb_typeof(p_meta -> 'assignee') = 'object' then p_meta -> 'assignee' else '{}'::jsonb end
    ) k order by k
  ), '{}');
$$;


ALTER FUNCTION "public"."supervision_assignee_names"("p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_collect_targets"("p_action_id" "uuid", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  if not public.can_manage_collect(p_action_id) then
    raise exception '작업을 만든 사람과 업무 책임자만 명단을 바꿀 수 있습니다' using errcode = '42501';
  end if;
  return public._sync_action_targets(p_action_id, p_apply);
end;
$$;


ALTER FUNCTION "public"."sync_collect_targets"("p_action_id" "uuid", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_training_signature_flag"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_meeting_id uuid;
  v_name       text;
  v_signed     boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_meeting_id := OLD.meeting_id;
    v_name       := OLD.signer_name;
    v_signed     := false;
  ELSE
    v_meeting_id := NEW.meeting_id;
    v_name       := NEW.signer_name;
    v_signed     := true;
  END IF;

  UPDATE public.meeting
     SET meta = jsonb_set(
           meta,
           ARRAY['assignee', v_name, 'signature'],
           to_jsonb(CASE WHEN v_signed THEN 1 ELSE 0 END),
           true
         )
   WHERE id = v_meeting_id
     AND jsonb_typeof(meta -> 'assignee') = 'object'
     AND jsonb_typeof(meta -> 'assignee' -> v_name) = 'object';

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_training_signature_flag"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_achievement_claim"("p_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  rule record;
  have integer;
  paid integer;
begin
  select * into rule from tama_private.achievement_rule(p_id);
  if rule.goal is null then raise exception '모르는 업적이에요.'; end if;
  perform tama_private.lock_user(u);
  have := coalesce((tama_private.achievement_progress(u)->>p_id)::integer, 0);
  if have < rule.goal then raise exception '아직 달성하지 않았어요. (%/%)', have, rule.goal; end if;
  paid := wallet_private.apply(u, rule.reward, 'tama_achievement', 'tamagotchi', p_id, false, '다마고찌 업적 ' || p_id);
  return jsonb_build_object('id', p_id, 'granted', paid > 0, 'amount', paid,
    'coins', (select coins from public.academy_user_stats where user_id = u));
end $$;


ALTER FUNCTION "public"."tama_achievement_claim"("p_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_achievements"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  prog jsonb := tama_private.achievement_progress(u);
  rp jsonb := tama_private.repeat_progress(u);
begin
  return jsonb_build_object(
    'progress', prog - '_deaths',
    'deaths', prog->'_deaths',
    'claimed', coalesce((select jsonb_agg(source_id) from public.wallet_ledger
                         where user_id = u and source_app = 'tamagotchi' and kind = 'tama_achievement'), '[]'::jsonb),
    -- 업적 보상 값(관리자 설정) — 화면이 서버 값을 그린다
    'rewards', (select jsonb_object_agg(s.id, (tama_private.achievement_rule(s.id)).reward) from jsonb_object_keys(prog - '_deaths') s(id)),
    'repeat', (select jsonb_object_agg(r.id, jsonb_build_object(
                  'progress', coalesce((rp->>r.id)::integer, 0), 'step', tama_private.repeat_step(r.id),
                  'claimed', tama_private.repeat_claimed(u, r.id), 'reward', economy_private.num('tama.repeat.' || r.id)))
               from unnest(array['focus', 'diary', 'heal', 'days', 'plan']) r(id))
  );
end $$;


ALTER FUNCTION "public"."tama_achievements"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_admin_metrics"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  today date := (now() at time zone 'Asia/Seoul')::date;
begin
  if not tama_private.is_admin() then raise exception '관리자만 볼 수 있어요.' using errcode = '42501'; end if;
  return (
    with people as (
      select pr.id, pr.role, pr.name from public.profiles pr
      where pr.role <> 'admin' and exists (select 1 from public.tama_pet p where p.owner = pr.id)
    ), pets as (
      select p.* from public.tama_pet p where p.owner in (select id from people)
    ), care as (
      select c.* from public.tama_care_day c where c.owner in (select id from people)
    ), care_n as (
      select owner, count(*) n, max(day) last_day from care group by owner
    ), stage_rank as (
      select p.id, p.owner, p.state->>'stage' as stage, p.state->>'branch' as branch,
        case p.state->>'stage' when 'egg' then 0 when 'baby' then 1 when 'child' then 2 when 'teen' then 3 when 'adult' then 4 else 0 end as r
      from pets p
    )
    select jsonb_build_object(
      'generated_at', now(),
      'admins_excluded', (select count(distinct p.owner) from public.tama_pet p join public.profiles pr on pr.id = p.owner and pr.role = 'admin'),
      'owners', coalesce((select jsonb_object_agg(coalesce(role, '?'), n) from (select role, count(*) n from people group by role) x), '{}'::jsonb),
      'pets', (select count(*) from pets),
      'resting', (select count(*) from pets where rested_at is not null),
      'sick_now', (select count(*) from pets where coalesce((state->>'sick')::boolean, false)),
      'active_7d', (select count(distinct owner) from care where day > today - 7),
      'active_today', (select count(distinct owner) from care where day = today),
      'students_cared_3days', (select count(*) from care_n c join people p on p.id = c.owner and p.role = 'student' where c.n >= 3),
      -- 돌본 날 수 분포(사람) — 1 · 2 · 3~6 · 7~13 · 14+
      'care_days_hist', jsonb_build_object(
        'd1', (select count(*) from care_n where n = 1), 'd2', (select count(*) from care_n where n = 2),
        'd3_6', (select count(*) from care_n where n between 3 and 6), 'd7_13', (select count(*) from care_n where n between 7 and 13),
        'd14', (select count(*) from care_n where n >= 14),
        'never', (select count(*) from people where id not in (select owner from care_n))),
      -- 단계 = 마지막 저장 기준, «그 단계 이상»으로 누적(깔때기)
      'stages', jsonb_build_object(
        'egg', (select count(*) from stage_rank), 'baby', (select count(*) from stage_rank where r >= 1),
        'child', (select count(*) from stage_rank where r >= 2), 'teen', (select count(*) from stage_rank where r >= 3),
        'adult', (select count(*) from stage_rank where r >= 4)),
      'branches', coalesce((select jsonb_object_agg(coalesce(branch, 'basic'), n) from (
          select branch, count(*) n from stage_rank where r = 4 group by branch) x), '{}'::jsonb),
      'daily', (select jsonb_agg(jsonb_build_object('day', d,
            'owners', (select count(*) from care c where c.day = d),
            'adopted', (select count(*) from people pe where (select min((p.created_at at time zone 'Asia/Seoul')::date) from pets p where p.owner = pe.id) = d)) order by d)
          from generate_series((today - 20)::timestamp, today::timestamp, interval '1 day') g(d0), lateral (select d0::date d) dd),
      'habits', (
        with starters as (
          select p.owner, min((p.created_at at time zone 'Asia/Seoul')::date) as start
          from pets p join people pe on pe.id = p.owner and pe.role = 'student'
          where p.owner in (select owner from care_n where n >= 3)
          group by p.owner
        ), win as (
          select s.owner, s.start, least(14, today - s.start) as after_days from starters s where today - s.start >= 3
        ), per as (
          select w.owner, w.after_days,
            (select count(*) from public.academy_tasks t where t.user_id = w.owner
               and (t.created_at at time zone 'Asia/Seoul')::date >= w.start - 14 and (t.created_at at time zone 'Asia/Seoul')::date < w.start)::numeric / 14 as plan_before,
            (select count(*) from public.academy_tasks t where t.user_id = w.owner
               and (t.created_at at time zone 'Asia/Seoul')::date >= w.start and (t.created_at at time zone 'Asia/Seoul')::date < w.start + w.after_days)::numeric / w.after_days as plan_after,
            (select count(*) from public.academy_task_feedback f where f.user_id = w.owner and char_length(btrim(coalesce(f.comment, ''))) >= 10
               and (f.created_at at time zone 'Asia/Seoul')::date >= w.start - 14 and (f.created_at at time zone 'Asia/Seoul')::date < w.start)::numeric / 14 as reflect_before,
            (select count(*) from public.academy_task_feedback f where f.user_id = w.owner and char_length(btrim(coalesce(f.comment, ''))) >= 10
               and (f.created_at at time zone 'Asia/Seoul')::date >= w.start and (f.created_at at time zone 'Asia/Seoul')::date < w.start + w.after_days)::numeric / w.after_days as reflect_after
          from win w
        )
        select jsonb_build_object('n', count(*),
          'plan_before', round(coalesce(avg(plan_before), 0), 2), 'plan_after', round(coalesce(avg(plan_after), 0), 2),
          'reflect_before', round(coalesce(avg(reflect_before), 0), 2), 'reflect_after', round(coalesce(avg(reflect_after), 0), 2),
          'plan_up', count(*) filter (where plan_after > plan_before), 'reflect_up', count(*) filter (where reflect_after > reflect_before))
        from per),
      'economy', jsonb_build_object(
        'credits_30d', coalesce((select jsonb_object_agg(kind, n) from (select kind, sum(amount) n from public.tama_credit_ledger
                       where earned_on > today - 30 and user_id in (select id from people) group by kind) x), '{}'::jsonb),
        'gacha_pulls_30d', (select count(*) from public.tama_gacha_log where created_at >= now() - interval '30 days' and owner in (select id from people)),
        'gacha_30d', (select jsonb_build_object(
            'by_machine', coalesce((select jsonb_object_agg(machine, n) from (select machine, count(*) n from public.tama_gacha_log
                where created_at >= now() - interval '30 days' and owner in (select id from people) group by machine) x), '{}'::jsonb),
            'spent', coalesce(sum(price), 0), 'refunded', coalesce(sum(refund), 0),
            'new_items', count(*) filter (where is_new), 'pity', count(*) filter (where pity), 'people', count(distinct owner))
          from public.tama_gacha_log where created_at >= now() - interval '30 days' and owner in (select id from people)),
        'trades_accepted_30d', (select count(*) from public.tama_trade where status = 'accepted' and responded_at >= now() - interval '30 days'),
        'diary_30d', (select count(*) from public.tama_diary where created_at >= now() - interval '30 days' and owner in (select id from people)),
        'diary_kinds_30d', coalesce((select jsonb_object_agg(kind, n) from (select kind, count(*) n from public.tama_diary
            where created_at >= now() - interval '30 days' and owner in (select id from people) group by kind) x), '{}'::jsonb),
        'focus_30d', coalesce((select jsonb_object_agg(coalesce(outcome, 'open'), n) from (select outcome, count(*) n from public.tama_focus
            where started_at >= now() - interval '30 days' and owner in (select id from people) group by outcome) x), '{}'::jsonb),
        'debt', jsonb_build_object('people', (select count(*) from public.tama_wallet where debt > 0 and owner in (select id from people)),
                                   'coins', (select coalesce(sum(debt), 0) from public.tama_wallet where owner in (select id from people))),
        'bought_slots', (select coalesce(sum(bought_slots), 0) from public.tama_wallet where owner in (select id from people)),
        'characters', coalesce((select jsonb_object_agg(status, n) from (select status, count(*) n from public.tama_character_order group by status) x), '{}'::jsonb),
        'decor', coalesce((select jsonb_object_agg(status, n) from (select status, count(*) n from public.tama_decor_order group by status) x), '{}'::jsonb)),
      'social', jsonb_build_object(
        'trades', coalesce((select jsonb_object_agg(status, n) from (select status, count(*) n from public.tama_trade group by status) x), '{}'::jsonb),
        'visits', (select count(*) from public.tama_visit),
        'visitors', (select count(distinct visitor) from public.tama_visit),
        'push_people', (select count(distinct s.user_id) from public.push_subscriptions s where s.user_id in (select id from people))),
      -- 가장 많은 사람이 가진 물건(나만의 꾸미기 제외) — 가챠에서 무엇이 퍼졌나
      'top_items', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'name', name, 'slot', slot, 'rarity', rarity, 'people', n) order by n desc, sort) from (
          select i.id, i.name, i.slot, i.rarity, i.sort, count(distinct v.owner) n
          from public.tama_inventory v join public.tama_item i on i.id = v.item_id and i.custom_owner is null
          where v.owner in (select id from people) group by i.id, i.name, i.slot, i.rarity, i.sort order by n desc, i.sort limit 12) x), '[]'::jsonb),
      'list', coalesce((select jsonb_agg(r order by (r->>'last_care') desc nulls last, r->>'name') from (
          select jsonb_build_object('name', coalesce(pe.name, '이름 없음'), 'role', pe.role,
            'pets', (select count(*) from pets p where p.owner = pe.id),
            'pet', (select jsonb_build_object('name', p.name, 'stage', p.state->>'stage', 'branch', p.state->>'branch', 'sick', coalesce((p.state->>'sick')::boolean, false))
                    from pets p where p.owner = pe.id order by p.is_primary desc, p.updated_at desc limit 1),
            'care_days', coalesce(cn.n, 0), 'last_care', cn.last_day,
            'first_pet', (select min((p.created_at at time zone 'Asia/Seoul')::date) from pets p where p.owner = pe.id),
            'diary', (select count(*) from public.tama_diary d where d.owner = pe.id),
            'gacha', (select count(*) from public.tama_gacha_log g where g.owner = pe.id),
            'items', (select count(*) from public.tama_inventory v where v.owner = pe.id),
            'coins', (select s.coins from public.academy_user_stats s where s.user_id = pe.id)) r
          from people pe left join care_n cn on cn.owner = pe.id
          order by cn.last_day desc nulls last limit 300) x), '[]'::jsonb)
    )
  );
end $$;


ALTER FUNCTION "public"."tama_admin_metrics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_character_read"("p_scope" "text" DEFAULT 'mine'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := auth.uid();
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;
  if p_scope = 'admin' then
    if not tama_private.is_admin() then raise exception '관리자만 볼 수 있어요.' using errcode = '42501'; end if;
    return coalesce((select jsonb_agg(to_jsonb(o) || jsonb_build_object('owner_name', academy_private.friend_name(o.owner))
      order by (o.status in ('submitted', 'crafting')) desc, o.created_at desc)
      from (select * from public.tama_character_order order by created_at desc limit 200) o), '[]'::jsonb);
  end if;
  return jsonb_build_object(
    'orders', coalesce((select jsonb_agg(to_jsonb(o) order by o.created_at desc) from public.tama_character_order o where o.owner = u), '[]'::jsonb),
    'equipped', (select p.skin_order_id from public.tama_pet p where p.owner = u and p.is_primary));
end $$;


ALTER FUNCTION "public"."tama_character_read"("p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_character_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  u uuid := auth.uid();
  o public.tama_character_order;
  price constant integer := economy_private.num('tama.character_order');
  balance integer;
  refund integer;
  admin_id uuid;
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;

  if p_action = 'submit' then
    perform tama_private.require_owner();
    perform tama_private.lock_user(u);
    select * into o from public.tama_character_order where owner = u and client_token = (p_payload->>'client_token')::uuid;
    if o.id is not null then return to_jsonb(o); end if; -- 같은 요청의 재시도
    if exists (select 1 from public.tama_character_order where owner = u and status in ('submitted', 'crafting')) then
      raise exception '진행 중인 의뢰가 있어요. 답을 받은 뒤 다시 의뢰해 주세요.';
    end if;
    if coalesce(p_payload->>'confirm_cost', '') <> price::text then raise exception '의뢰 값(%코인)을 확인해 주세요.', price; end if;
    insert into public.academy_user_stats(user_id) values (u) on conflict (user_id) do nothing;
    update public.academy_user_stats set coins = coins - price, updated_at = now() where user_id = u and coins >= price returning coins into balance;
    if not found then raise exception '코인이 모자라요(의뢰 %코인).', price using errcode = 'P0001'; end if;
    insert into public.tama_character_order(owner, client_token, title, prompt, charged_coins)
      values (u, (p_payload->>'client_token')::uuid, btrim(p_payload->>'title'), btrim(p_payload->>'prompt'), price) returning * into o;
    for admin_id in select p.id from public.profiles p where p.role = 'admin' loop
      perform tama_private.notify(admin_id, 'tama_character_submitted', '새 다마고찌 캐릭터 의뢰', o.title, jsonb_build_object('order_id', o.id));
    end loop;
    return to_jsonb(o) || jsonb_build_object('coins', balance);
  end if;

  select * into o from public.tama_character_order where id = (p_payload->>'id')::uuid for update;
  if o.id is null then raise exception '의뢰를 찾지 못했어요.'; end if;

  if p_action = 'cancel' then
    if o.owner <> u then raise exception '내 의뢰만 거둘 수 있어요.' using errcode = '42501'; end if;
    if o.status <> 'submitted' then raise exception '관리자가 만들기 시작한 의뢰는 거둘 수 없어요.'; end if;
    refund := o.charged_coins - o.refunded_coins;
    update public.academy_user_stats set coins = coins + refund, updated_at = now() where user_id = u;
    update public.tama_character_order set status = 'cancelled', refunded_coins = refunded_coins + refund, updated_at = now() where id = o.id returning * into o;
    return to_jsonb(o);
  elsif p_action = 'equip' then
    perform tama_private.require_owner();
    if o.owner <> u then raise exception '내 캐릭터만 입힐 수 있어요.' using errcode = '42501'; end if;
    insert into public.tama_wallet(owner) values (u) on conflict (owner) do nothing;
    if coalesce((p_payload->>'on')::boolean, true) then
      if o.status <> 'delivered' then raise exception '받은 캐릭터만 입힐 수 있어요.'; end if;
      if not tama_private.pet_grown(u) then raise exception '다 자란 펫만 캐릭터를 입을 수 있어요.'; end if;
      update public.tama_pet set skin_order_id = o.id where owner = u and is_primary;
    else
      update public.tama_pet set skin_order_id = null where owner = u and is_primary and skin_order_id = o.id;
    end if;
    return jsonb_build_object('equipped', (select p.skin_order_id from public.tama_pet p where p.owner = u and p.is_primary));
  end if;

  -- 이 아래는 관리자
  if not tama_private.is_admin() then raise exception '관리자만 할 수 있어요.' using errcode = '42501'; end if;
  if o.status in ('delivered', 'declined', 'cancelled') then
    if (p_action = 'deliver' and o.status = 'delivered') or (p_action = 'decline' and o.status = 'declined') then return to_jsonb(o); end if;
    raise exception '이미 끝난 의뢰예요.';
  end if;
  if p_action = 'start' then
    update public.tama_character_order set status = 'crafting', updated_at = now() where id = o.id returning * into o;
    return to_jsonb(o);
  elsif p_action = 'decline' then
    if char_length(btrim(coalesce(p_payload->>'note', ''))) < 2 then raise exception '학생에게 남길 답장을 적어 주세요.'; end if;
    refund := o.charged_coins - o.refunded_coins;
    update public.academy_user_stats set coins = coins + refund, updated_at = now() where user_id = o.owner;
    update public.tama_character_order set status = 'declined', admin_note = btrim(p_payload->>'note'),
      refunded_coins = refunded_coins + refund, updated_at = now() where id = o.id returning * into o;
    perform tama_private.notify(o.owner, 'tama_character_declined', '캐릭터 의뢰에 답장이 왔어요', o.title || E'\n' || o.admin_note,
      jsonb_build_object('order_id', o.id));
    return to_jsonb(o);
  elsif p_action = 'deliver' then
    if (p_payload->>'image_path') !~ ('^' || o.id::text || '/[0-9a-f-]{36}\.png$') then raise exception '그림 경로가 올바르지 않아요.'; end if;
    if not exists (select 1 from storage.objects s where s.bucket_id = 'tama-character' and s.name = p_payload->>'image_path') then
      raise exception '그림을 먼저 올려 주세요.';
    end if;
    update public.tama_character_order set status = 'delivered', image_path = p_payload->>'image_path',
      admin_note = nullif(btrim(coalesce(p_payload->>'note', '')), ''), delivered_by = u, delivered_at = now(), updated_at = now()
      where id = o.id returning * into o;
    perform tama_private.notify(o.owner, 'tama_character_delivered', '새 캐릭터가 도착했어요', o.title || coalesce(E'\n' || o.admin_note, ''),
      jsonb_build_object('order_id', o.id));
    return to_jsonb(o);
  end if;
  raise exception '할 일을 선택해 주세요.';
end $_$;


ALTER FUNCTION "public"."tama_character_write"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_credit_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  today date := (now() at time zone 'Asia/Seoul')::date;
  born timestamptz;
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;
  select created_at into born from public.tama_pet where owner = u and is_primary;
  return jsonb_build_object(
    'coins', coalesce((select coins from public.academy_user_stats where user_id = u), 100),
    'debt', coalesce((select debt from public.tama_wallet where owner = u), 0),
    'rules', (select jsonb_object_agg(k, jsonb_build_object('amount', r.amount, 'cap', r.daily_cap,
                'taken', (select count(*) from public.tama_credit_ledger l where l.user_id = u and l.earned_on = today and l.kind = k)))
              from unnest(array['plan', 'reflect', 'focus', 'diary']) k, lateral tama_private.credit_rule(k) r),
    'lifetime', (select jsonb_object_agg(k, (select count(*) from public.tama_credit_ledger l
                   where l.user_id = u and l.kind = k and born is not null and l.created_at >= born))
                 from unnest(array['plan', 'reflect', 'focus', 'diary']) k),
    'planning_reward_today', exists (select 1 from public.academy_planning_rewards where user_id = u and reward_date = today),
    'recent', coalesce((select jsonb_agg(jsonb_build_object('kind', kind, 'amount', amount, 'earned_on', earned_on, 'at', created_at) order by created_at desc)
                from (select * from public.tama_credit_ledger where user_id = u order by created_at desc limit 20) l), '[]'::jsonb),
    'focus', (select to_jsonb(f) - 'owner' from public.tama_focus f where f.owner = u and f.ended_at is null),
    'server_now', (extract(epoch from now()) * 1000)::bigint
  );
end $$;


ALTER FUNCTION "public"."tama_credit_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_debt_pay"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  owe integer;
  have integer;
  pay integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('tama-credit:' || u::text, 0));
  select debt into owe from public.tama_wallet where owner = u for update;
  select coins into have from public.academy_user_stats where user_id = u for update;
  pay := least(coalesce(owe, 0), coalesce(have, 0));
  if pay > 0 then
    update public.tama_wallet set debt = debt - pay where owner = u;
    update public.academy_user_stats set coins = coins - pay, updated_at = now() where user_id = u;
  end if;
  return jsonb_build_object('paid', pay, 'debt', coalesce(owe, 0) - pay, 'coins', coalesce(have, 0) - pay);
end $$;


ALTER FUNCTION "public"."tama_debt_pay"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_decor_read"("p_scope" "text" DEFAULT 'mine'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := auth.uid();
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;
  if p_scope = 'admin' then
    if not tama_private.is_admin() then raise exception '관리자만 볼 수 있어요.' using errcode = '42501'; end if;
    return coalesce((select jsonb_agg(to_jsonb(o) || jsonb_build_object('owner_name', academy_private.friend_name(o.owner))
      order by (o.status in ('submitted', 'crafting')) desc, o.created_at desc)
      from (select * from public.tama_decor_order order by created_at desc limit 200) o), '[]'::jsonb);
  end if;
  return coalesce((select jsonb_agg(to_jsonb(o) order by o.created_at desc) from public.tama_decor_order o where o.owner = u), '[]'::jsonb);
end $$;


