CREATE OR REPLACE FUNCTION "public"."tama_decor_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  u uuid := auth.uid();
  o public.tama_decor_order;
  price integer := 0;
  balance integer;
  refund integer;
  admin_id uuid;
  new_id text;
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;

  if p_action = 'submit' then
    perform tama_private.require_owner();
    perform tama_private.lock_user(u);
    select * into o from public.tama_decor_order where owner = u and client_token = (p_payload->>'client_token')::uuid;
    if o.id is not null then return to_jsonb(o); end if; -- 같은 요청의 재시도
    if exists (select 1 from public.tama_decor_order where owner = u and status in ('submitted', 'crafting')) then
      raise exception '진행 중인 꾸미기 의뢰가 있어요. 답을 받은 뒤 다시 의뢰해 주세요.';
    end if;
    if coalesce(p_payload->>'slot', '') not in ('shell', 'wallpaper', 'rug', 'floor', 'shelf', 'wall', 'device') then
      raise exception '꾸밀 자리를 골라 주세요.';
    end if;
    price := economy_private.num('tama.decor.' || case when p_payload->>'slot' in ('device', 'shell', 'wallpaper', 'rug') then p_payload->>'slot' else 'other' end);
    if coalesce(p_payload->>'confirm_cost', '') <> price::text then raise exception '의뢰 값(%코인)을 확인해 주세요.', price; end if;
    insert into public.academy_user_stats(user_id) values (u) on conflict (user_id) do nothing;
    update public.academy_user_stats set coins = coins - price, updated_at = now() where user_id = u and coins >= price returning coins into balance;
    if not found then raise exception '코인이 모자라요(의뢰 %코인).', price using errcode = 'P0001'; end if;
    insert into public.tama_decor_order(owner, client_token, slot, title, prompt, charged_coins)
      values (u, (p_payload->>'client_token')::uuid, p_payload->>'slot', btrim(p_payload->>'title'), btrim(p_payload->>'prompt'), price)
      returning * into o;
    for admin_id in select p.id from public.profiles p where p.role = 'admin' loop
      perform tama_private.notify(admin_id, 'tama_decor_submitted', '새 다마고찌 꾸미기 의뢰', o.title, jsonb_build_object('order_id', o.id));
    end loop;
    return to_jsonb(o) || jsonb_build_object('coins', balance);
  end if;

  select * into o from public.tama_decor_order where id = (p_payload->>'id')::uuid for update;
  if o.id is null then raise exception '의뢰를 찾지 못했어요.'; end if;

  if p_action = 'cancel' then
    if o.owner <> u then raise exception '내 의뢰만 거둘 수 있어요.' using errcode = '42501'; end if;
    if o.status <> 'submitted' then raise exception '관리자가 만들기 시작한 의뢰는 거둘 수 없어요.'; end if;
    refund := o.charged_coins - o.refunded_coins;
    update public.academy_user_stats set coins = coins + refund, updated_at = now() where user_id = u;
    update public.tama_decor_order set status = 'cancelled', refunded_coins = refunded_coins + refund, updated_at = now() where id = o.id returning * into o;
    return to_jsonb(o);
  end if;

  -- 이 아래는 관리자
  if not tama_private.is_admin() then raise exception '관리자만 할 수 있어요.' using errcode = '42501'; end if;
  if o.status in ('delivered', 'declined', 'cancelled') then
    if (p_action = 'deliver' and o.status = 'delivered') or (p_action = 'decline' and o.status = 'declined') then return to_jsonb(o); end if;
    raise exception '이미 끝난 의뢰예요.';
  end if;
  if p_action = 'start' then
    update public.tama_decor_order set status = 'crafting', updated_at = now() where id = o.id returning * into o;
    return to_jsonb(o);
  elsif p_action = 'decline' then
    if char_length(btrim(coalesce(p_payload->>'note', ''))) < 2 then raise exception '학생에게 남길 답장을 적어 주세요.'; end if;
    refund := o.charged_coins - o.refunded_coins;
    update public.academy_user_stats set coins = coins + refund, updated_at = now() where user_id = o.owner;
    update public.tama_decor_order set status = 'declined', admin_note = btrim(p_payload->>'note'),
      refunded_coins = refunded_coins + refund, updated_at = now() where id = o.id returning * into o;
    perform tama_private.notify(o.owner, 'tama_decor_declined', '꾸미기 의뢰에 답장이 왔어요', o.title || E'\n' || o.admin_note,
      jsonb_build_object('order_id', o.id));
    return to_jsonb(o);
  elsif p_action = 'deliver' then
    new_id := 'c_' || left(replace(o.id::text, '-', ''), 20);
    if o.slot in ('shell', 'wallpaper', 'rug', 'device') then
      if not tama_private.decor_design_ok(o.slot, p_payload->'design') then raise exception '색·무늬를 확인해 주세요.'; end if;
      insert into public.tama_item(id, slot, rarity, name, sort, active, custom_owner, design)
        values (new_id, o.slot, 'legendary', btrim(o.title), 1000, true, o.owner, p_payload->'design');
    else
      if (p_payload->>'image_path') !~ ('^' || o.id::text || '/[0-9a-f-]{36}\.png$') then raise exception '그림 경로가 올바르지 않아요.'; end if;
      if not exists (select 1 from storage.objects s where s.bucket_id = 'tama-decor' and s.name = p_payload->>'image_path') then
        raise exception '그림을 먼저 올려 주세요.';
      end if;
      insert into public.tama_item(id, slot, rarity, name, sort, active, custom_owner, image_path)
        values (new_id, o.slot, 'legendary', btrim(o.title), 1000, true, o.owner, p_payload->>'image_path');
    end if;
    insert into public.tama_inventory(owner, item_id) values (o.owner, new_id) on conflict (owner, item_id) do nothing;
    update public.tama_decor_order set status = 'delivered', item_id = new_id,
      admin_note = nullif(btrim(coalesce(p_payload->>'note', '')), ''), delivered_by = u, delivered_at = now(), updated_at = now()
      where id = o.id returning * into o;
    perform tama_private.notify(o.owner, 'tama_decor_delivered', '나만의 꾸미기가 도착했어요', o.title || coalesce(E'\n' || o.admin_note, ''),
      jsonb_build_object('order_id', o.id));
    return to_jsonb(o);
  end if;
  raise exception '할 일을 선택해 주세요.';
end $_$;


ALTER FUNCTION "public"."tama_decor_write"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_diary_delete"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := auth.uid();
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;
  delete from public.tama_diary where id = p_id and owner = u;
  if not found then raise exception '일기를 찾을 수 없어요.' using errcode = '42501'; end if;
  -- 코인은 되돌리지 않는다(이미 썼을 수 있다). 상한이 하루 1 이라 지웠다 다시 써도 더 받지 못한다.
  return jsonb_build_object('ok', true);
end $$;


ALTER FUNCTION "public"."tama_diary_delete"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_diary_write"("p_kind" "text", "p_body" "text", "p_prompt" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  row public.tama_diary;
  got integer;
begin
  if u is null or not exists (select 1 from public.profiles where id = u and role in ('student', 'teacher', 'admin')) then
    raise exception '펫 일기는 본인만 쓸 수 있어요.' using errcode = '42501';
  end if;
  if p_kind not in ('good', 'hard', 'praise', 'question') then raise exception '일기 종류를 골라 주세요.'; end if;
  if char_length(btrim(coalesce(p_body, ''))) not between 1 and 500 then raise exception '한 줄(500자 이내)을 써 주세요.'; end if;
  if (p_kind = 'question') <> (nullif(btrim(coalesce(p_prompt, '')), '') is not null) then raise exception '오늘의 질문을 확인해 주세요.'; end if;
  insert into public.tama_diary(owner, kind, body, prompt)
    values (u, p_kind, btrim(p_body), case when p_kind = 'question' then left(btrim(p_prompt), 120) end) returning * into row;
  got := tama_private.grant_credit(u, 'diary', row.id::text);
  return jsonb_build_object('entry', to_jsonb(row) - 'owner', 'credit', got,
    'coins', (select coins from public.academy_user_stats where user_id = u));
end $$;


ALTER FUNCTION "public"."tama_diary_write"("p_kind" "text", "p_body" "text", "p_prompt" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_equip_set"("p_slot" "text", "p_item" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := tama_private.require_owner();
begin
  if p_slot not in ('shell', 'wallpaper', 'rug', 'floor', 'shelf', 'wall', 'device', 'character') then raise exception '자리를 확인해 주세요.'; end if;
  if p_slot = 'character' and p_item is not null then if not tama_private.pet_grown(u) then raise exception '다 자란 펫만 캐릭터를 입을 수 있어요.'; end if; end if;
  if p_item is not null then
    if not exists (select 1 from public.tama_item i where i.id = p_item and i.slot = p_slot and i.active
                   and (i.custom_owner is null or i.custom_owner = u)) then
      raise exception '자리를 확인해 주세요.';
    end if;
    if not tama_private.user_is_admin(u) and not exists (
        select 1 from public.tama_inventory v where v.owner = u and v.item_id = p_item) then
      raise exception '가진 물건만 쓸 수 있어요.' using errcode = '42501';
    end if;
  end if;
  if p_slot = 'character' then
    update public.tama_pet set skin_item_id = p_item where owner = u and is_primary;
  elsif p_item is null then
    delete from public.tama_equip where owner = u and slot = p_slot;
  else
    insert into public.tama_equip(owner, slot, item_id) values (u, p_slot, p_item)
      on conflict (owner, slot) do update set item_id = excluded.item_id;
  end if;
  return tama_private.equipped_of(u);
end $$;


ALTER FUNCTION "public"."tama_equip_set"("p_slot" "text", "p_item" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_event_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.tama_event;
  items text[] := coalesce(array(select jsonb_array_elements_text(p_payload->'item_ids')), '{}');
  picks text[] := coalesce(array(select jsonb_array_elements_text(p_payload->'pickup_ids')), '{}');
  n integer := 0;
  owner_id uuid;
begin
  if not tama_private.is_admin() then raise exception '관리자만 할 수 있어요.' using errcode = '42501'; end if;
  if p_action = 'delete' then
    delete from public.tama_event where id = (p_payload->>'id')::uuid;
    return jsonb_build_object('status', 'deleted');
  end if;
  if p_action <> 'save' then raise exception '할 일을 선택해 주세요.'; end if;
  if exists (select 1 from unnest(items) x where not exists (select 1 from public.tama_item i where i.id = x and i.event_only and i.active)) then
    raise exception '이벤트 물건은 «이벤트 전용» 물건에서만 고를 수 있어요.';
  end if;
  if exists (select 1 from unnest(picks) x where not exists (select 1 from public.tama_item i where i.id = x and i.active and (not i.event_only or x = any(items)))) then
    raise exception '픽업은 가챠에 나오는 물건에서만 고를 수 있어요.';
  end if;
  if (p_payload->>'id') is null then
    insert into public.tama_event(title, body, starts_at, ends_at, item_ids, pickup_ids, created_by)
      values (btrim(p_payload->>'title'), coalesce(p_payload->>'body', ''), (p_payload->>'starts_at')::timestamptz, (p_payload->>'ends_at')::timestamptz, items, picks, auth.uid())
      returning * into e;
  else
    update public.tama_event set title = btrim(p_payload->>'title'), body = coalesce(p_payload->>'body', ''),
        starts_at = (p_payload->>'starts_at')::timestamptz, ends_at = (p_payload->>'ends_at')::timestamptz,
        item_ids = items, pickup_ids = picks, updated_at = now()
      where id = (p_payload->>'id')::uuid returning * into e;
    if e.id is null then raise exception '이벤트를 찾지 못했어요.'; end if;
  end if;
  if coalesce((p_payload->>'notify')::boolean, false) then
    for owner_id in select distinct p.owner from public.tama_pet p where p.is_primary loop
      perform tama_private.notify(owner_id, 'tama_event', '펫 이벤트: ' || e.title,
        coalesce(nullif(e.body, ''), '가챠에 이벤트 물건이 나와요.'), jsonb_build_object('event_id', e.id));
      n := n + 1;
    end loop;
  end if;
  return to_jsonb(e) || jsonb_build_object('notified', n);
end $$;


ALTER FUNCTION "public"."tama_event_write"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_focus_finish"("p_id" "uuid", "p_give_up" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  row public.tama_focus;
  due timestamptz;
  got integer := 0;
  result text;
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;
  select * into row from public.tama_focus where id = p_id and owner = u for update;
  if not found then raise exception '집중 기록을 찾을 수 없어요.' using errcode = '42501'; end if;
  if row.ended_at is not null then
    return jsonb_build_object('outcome', row.outcome, 'credit', 0, 'server_now', (extract(epoch from now()) * 1000)::bigint);
  end if;
  due := row.started_at + make_interval(secs => row.planned_seconds);
  if p_give_up then
    result := 'gave_up';
  elsif now() < due then
    return jsonb_build_object('outcome', 'running', 'remaining', ceil(extract(epoch from due - now()))::integer,
      'server_now', (extract(epoch from now()) * 1000)::bigint);
  elsif now() > due + interval '15 minutes' then
    result := 'expired';
  else
    result := 'completed';
  end if;
  update public.tama_focus set ended_at = now(), outcome = result where id = row.id;
  if result = 'completed' then
    if row.task_id is not null and exists (select 1 from public.academy_tasks where id = row.task_id and user_id = u) then
      -- 플래너의 집중 기록에도 남긴다(같은 id — 서버 시각이라 검증 제약을 그대로 통과한다)
      insert into public.planner_focus_sessions(id, user_id, task_id, started_at, ended_at, focus_seconds, planned_seconds, completed)
        values (row.id, u, row.task_id, row.started_at, now(), row.planned_seconds, row.planned_seconds, true)
        on conflict (id) do nothing;
    end if;
    got := tama_private.grant_credit(u, 'focus', row.id::text);
  end if;
  return jsonb_build_object('outcome', result, 'credit', got,
    'coins', (select coins from public.academy_user_stats where user_id = u),
    'server_now', (extract(epoch from now()) * 1000)::bigint);
end $$;


ALTER FUNCTION "public"."tama_focus_finish"("p_id" "uuid", "p_give_up" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_focus_start"("p_minutes" integer, "p_task_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  row public.tama_focus;
begin
  if u is null or not exists (select 1 from public.profiles where id = u and role in ('student', 'teacher', 'admin')) then
    raise exception '본인만 집중을 시작할 수 있어요.' using errcode = '42501';
  end if;
  if p_minutes not in (15, 25, 45) then raise exception '15 · 25 · 45분 중에서 골라 주세요.'; end if;
  if p_task_id is not null and not exists (select 1 from public.academy_tasks where id = p_task_id and user_id = u) then
    raise exception '계획을 찾을 수 없어요.' using errcode = '42501';
  end if;
  -- 열린 집중이 있으면 닫고 새로 연다(한 사람에 하나)
  update public.tama_focus set ended_at = now(), outcome = 'replaced' where owner = u and ended_at is null;
  insert into public.tama_focus(owner, task_id, planned_seconds) values (u, p_task_id, p_minutes * 60) returning * into row;
  return jsonb_build_object('focus', to_jsonb(row) - 'owner', 'server_now', (extract(epoch from now()) * 1000)::bigint);
end $$;


ALTER FUNCTION "public"."tama_focus_start"("p_minutes" integer, "p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_friend_pat"("p_friend" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := tama_private.require_owner(); pet_name text; n integer;
begin
  if not academy_private.are_friends(u, p_friend) then raise exception '별빛 친구의 펫만 쓰다듬을 수 있어요.' using errcode = '42501'; end if;
  select name into pet_name from public.tama_pet where owner = p_friend and is_primary;
  if pet_name is null then raise exception '친구가 아직 펫을 키우지 않아요.'; end if;
  insert into public.tama_visit(owner, visitor, day) values (p_friend, u, (now() at time zone 'Asia/Seoul')::date)
    on conflict do nothing;
  get diagnostics n = row_count;
  if n > 0 then
    perform tama_private.notify(p_friend, 'tama_visit', academy_private.friend_name(u) || '이(가) 놀러 왔어요',
      pet_name || '을(를) 쓰다듬어 주고 갔어요.', '{}'::jsonb);
  end if;
  return jsonb_build_object('fresh', n > 0);
end $$;


ALTER FUNCTION "public"."tama_friend_pat"("p_friend" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_friend_pet"("p_friend" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare u uuid := tama_private.require_owner(); p public.tama_pet; c public.tama_character_order;

begin

  if not academy_private.are_friends(u, p_friend) then raise exception '별빛 친구의 펫만 볼 수 있어요.' using errcode = '42501'; end if;

  select * into p from public.tama_pet where owner = p_friend and is_primary;

  if p.skin_order_id is not null then select o.* into c from public.tama_character_order o where o.id = p.skin_order_id; end if;

  return jsonb_build_object(

    'name', academy_private.friend_name(p_friend),

    'pet', case when p.id is null then null else jsonb_build_object('name', p.name, 'stage', p.state->>'stage', 'branch', p.state->>'branch', 'dead', coalesce((p.state->>'dead')::boolean, false), 'species', p.state->>'species') end,

    'equipped', tama_private.equipped_of(p_friend),

    'items', coalesce((select jsonb_object_agg(v.item_id, v.count) from public.tama_inventory v

                 join public.tama_item ti on ti.id = v.item_id and ti.custom_owner is null where v.owner = p_friend), '{}'::jsonb),

    'custom', coalesce((select jsonb_agg(jsonb_build_object('id', ti.id, 'slot', ti.slot, 'name', ti.name, 'design', ti.design, 'image_path', ti.image_path))

                 from public.tama_equip e join public.tama_item ti on ti.id = e.item_id and ti.custom_owner = p_friend where e.owner = p_friend), '[]'::jsonb),

    'character', case when c.id is null then null else jsonb_build_object('id', c.id, 'title', c.title, 'image_path', c.image_path) end,

    'patted_today', exists (select 1 from public.tama_visit v where v.owner = p_friend and v.visitor = u and v.day = (now() at time zone 'Asia/Seoul')::date));

end $$;


ALTER FUNCTION "public"."tama_friend_pet"("p_friend" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_friends_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := tama_private.require_owner(); today date := (now() at time zone 'Asia/Seoul')::date;
begin
  if not academy_private.friend_student(u) then return jsonb_build_object('eligible', false); end if;
  return jsonb_build_object('eligible', true,
    'friends', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'name', coalesce(nullif(btrim(o.name), ''), '학생'),
        'pet', case when p.id is null then null else jsonb_build_object('name', p.name, 'stage', p.state->>'stage', 'branch', p.state->>'branch', 'species', p.state->>'species') end,
        'patted_today', exists (select 1 from public.tama_visit v where v.owner = o.id and v.visitor = u and v.day = today)) order by o.name)
      from public.academy_friendships f
      join public.profiles o on o.id = case when f.requester_id = u then f.addressee_id else f.requester_id end
      left join public.tama_pet p on p.owner = o.id and p.is_primary
      where f.status = 'accepted' and u in (f.requester_id, f.addressee_id)), '[]'::jsonb),
    'trades', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'from_user', t.from_user, 'to_user', t.to_user,
        'from_name', academy_private.friend_name(t.from_user), 'to_name', academy_private.friend_name(t.to_user),
        'give_item', t.give_item, 'want_item', t.want_item, 'status', t.status, 'detail', t.detail,
        'created_at', t.created_at, 'responded_at', t.responded_at,
        'expired', t.status = 'pending' and t.created_at < now() - interval '7 days') order by t.created_at desc)
      from (select * from public.tama_trade x where u in (x.from_user, x.to_user) order by x.created_at desc limit 30) t), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."tama_friends_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_gacha_draw"("p_machine" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  adm boolean := tama_private.user_is_admin(u);
  mc record;
  price integer;
  refund_dup integer;
  pity_at constant integer := 5;
  w public.tama_wallet;
  pity boolean;
  pick text;
  fresh boolean;
  r numeric;
  balance integer;
  log_id bigint;
  maker uuid;
  royalty integer;
begin
  select * into mc from tama_private.gacha_machine(coalesce(p_machine, 'all'));
  if mc.price is null then raise exception '없는 가챠 기계예요.'; end if;
  price := case when adm then 0 else mc.price end;
  refund_dup := case when adm then 0 else mc.refund end;
  if not exists (select 1 from public.tama_pet where owner = u and is_primary) then
    raise exception '펫을 먼저 키워 주세요.' using errcode = '42501';
  end if;
  if not exists (select 1 from tama_private.gacha_pool_of(p_machine)) then
    raise exception '이 가챠 기계에는 지금 나올 물건이 없어요.';
  end if;
  perform tama_private.lock_user(u);
  insert into public.tama_wallet(owner) values (u) on conflict (owner) do nothing;
  select * into w from public.tama_wallet where owner = u for update;
  if w.debt > 0 and not adm then raise exception '외상(%코인)을 먼저 갚아 주세요.', w.debt using errcode = 'P0001'; end if;
  insert into public.academy_user_stats(user_id) values (u) on conflict (user_id) do nothing;
  update public.academy_user_stats set coins = coins - price, updated_at = now() where user_id = u and coins >= price returning coins into balance;
  if not found then raise exception '코인이 모자라요(한 번에 %코인).', price using errcode = 'P0001'; end if;

  -- 천장: 새 것 없이 (pity_at − 1)번 연속이면 «이 기계 풀에서» 아직 없는 것에서만
  pity := w.since_new >= pity_at - 1 and exists (
    select 1 from tama_private.gacha_pool_of(p_machine) p where not exists (select 1 from public.tama_inventory v where v.owner = u and v.item_id = p.id));
  r := random();
  with eligible as (
    select p.* from tama_private.gacha_pool_of(p_machine) p
    where not pity or not exists (select 1 from public.tama_inventory v where v.owner = u and v.item_id = p.id)
  ), cum as (
    select e.id, sum(e.weight) over (order by e.sort, e.id) / sum(e.weight) over () as upto from eligible e
  )
  select c.id into pick from cum c where c.upto >= r order by c.upto limit 1;

  fresh := not exists (select 1 from public.tama_inventory where owner = u and item_id = pick);
  insert into public.tama_inventory(owner, item_id) values (u, pick)
    on conflict (owner, item_id) do update set count = public.tama_inventory.count + 1;
  if not fresh and refund_dup > 0 then
    update public.academy_user_stats set coins = coins + refund_dup, updated_at = now() where user_id = u returning coins into balance;
  end if;
  update public.tama_wallet set pulls = pulls + 1, since_new = case when fresh then 0 else since_new + 1 end where owner = u returning * into w;
  insert into public.tama_gacha_log(owner, item_id, is_new, pity, price, refund, machine)
    values (u, pick, fresh, pity, price, case when fresh then 0 else refund_dup end, p_machine) returning id into log_id;
  -- 의뢰 작품 수익(2026-10-26 · 20261026160000) — 남이 값을 내고 뽑았을 때만
  select i.creator into maker from public.tama_item i where i.id = pick;
  if maker is not null and maker <> u and price > 0 then
    royalty := least(price * economy_private.num('tama.royalty.percent') / 100, economy_private.num('tama.royalty.max'));
    if royalty > 0 then
      perform wallet_private.apply(maker, royalty, 'tama_royalty', 'tamagotchi', 'gacha:' || log_id, false,
        '«' || coalesce((select i.name from public.tama_item i where i.id = pick), pick) || '» 뽑힘');
    end if;
  end if;
  return jsonb_build_object('item', pick, 'is_new', fresh, 'pity', pity, 'refund', case when fresh then 0 else refund_dup end,
    'coins', balance, 'since_new', w.since_new, 'pulls', w.pulls, 'admin', adm, 'machine', p_machine);
end $$;


ALTER FUNCTION "public"."tama_gacha_draw"("p_machine" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_link_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := tama_private.require_owner();
begin
  update public.tama_link set status = 'expired', responded_at = now()
   where status = 'pending' and created_at < now() - interval '2 minutes' and (from_user = u or to_user = u);
  return jsonb_build_object(
    'links', coalesce((select jsonb_agg(jsonb_build_object(
        'id', l.id, 'from_user', l.from_user, 'to_user', l.to_user, 'status', l.status, 'first_contact', l.first_contact,
        'created_at', l.created_at, 'responded_at', l.responded_at, 'mine', l.from_user = u,
        'partner', academy_private.friend_name(case when l.from_user = u then l.to_user else l.from_user end)) order by l.created_at desc)
      from public.tama_link l
     where (l.from_user = u or l.to_user = u)
       and (l.status = 'pending' or coalesce(l.responded_at, l.created_at) > now() - interval '10 minutes')), '[]'::jsonb),
    'partners', (select count(distinct case when l.from_user = u then l.to_user else l.from_user end)::integer
                   from public.tama_link l where l.status = 'accepted' and (l.from_user = u or l.to_user = u)),
    'server_now', (extract(epoch from now()) * 1000)::bigint
  );
end $$;


ALTER FUNCTION "public"."tama_link_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_link_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  f uuid;
  l public.tama_link;
  first boolean;
begin
  if p_action = 'offer' then
    f := nullif(p_payload->>'friend', '')::uuid;
    if f is null or not academy_private.are_friends(u, f) then raise exception '별빛 친구와만 통신할 수 있어요.'; end if;
    if not tama_private.link_ready(u) then raise exception '알에서 나온 함께하는 펫이 있어야 통신할 수 있어요.'; end if;
    if not tama_private.link_ready(f) then raise exception '친구의 펫이 아직 통신할 수 없어요.'; end if;
    if (select count(*) from public.tama_link where from_user = u and created_at > now() - interval '1 day') >= 30 then
      raise exception '오늘은 통신을 너무 많이 걸었어요. 내일 다시 해 주세요.';
    end if;
    update public.tama_link set status = 'cancelled', responded_at = now() where from_user = u and status = 'pending';
    insert into public.tama_link(from_user, to_user) values (u, f) returning * into l;
    return jsonb_build_object('id', l.id, 'created_at', l.created_at, 'expires_at', l.created_at + interval '2 minutes');

  elsif p_action in ('accept', 'decline', 'cancel') then
    select * into l from public.tama_link where id = nullif(p_payload->>'id', '')::uuid for update;
    if l.id is null or (p_action = 'cancel' and l.from_user <> u) or (p_action <> 'cancel' and l.to_user <> u) then
      raise exception '내 통신이 아니에요.' using errcode = '42501';
    end if;
    if l.status <> 'pending' then return jsonb_build_object('status', l.status, 'first_contact', l.first_contact); end if;
    if l.created_at < now() - interval '2 minutes' then
      update public.tama_link set status = 'expired', responded_at = now() where id = l.id;
      return jsonb_build_object('status', 'expired', 'first_contact', false);
    end if;
    if p_action <> 'accept' then
      update public.tama_link set status = case when p_action = 'decline' then 'declined' else 'cancelled' end, responded_at = now() where id = l.id;
      return jsonb_build_object('status', case when p_action = 'decline' then 'declined' else 'cancelled' end, 'first_contact', false);
    end if;
    if not academy_private.are_friends(l.from_user, l.to_user) then raise exception '이제 별빛 친구가 아니에요.'; end if;
    if not tama_private.link_ready(l.from_user) or not tama_private.link_ready(l.to_user) then raise exception '지금은 통신할 수 없어요.'; end if;
    -- 쌍마다 한 번 — 두 사람 순서와 상관없이 같은 잠금
    perform pg_advisory_xact_lock(hashtextextended('tama-link:' || least(l.from_user, l.to_user)::text || greatest(l.from_user, l.to_user)::text, 0));
    first := not exists (select 1 from public.tama_link x where x.status = 'accepted' and x.first_contact
                          and least(x.from_user, x.to_user) = least(l.from_user, l.to_user)
                          and greatest(x.from_user, x.to_user) = greatest(l.from_user, l.to_user));
    update public.tama_link set status = 'accepted', responded_at = now(), first_contact = first where id = l.id;
    if first then
      insert into public.tama_egg_ticket(owner, species, source, partner, link_id) values
        (l.from_user, 'signal', 'link', l.to_user, l.id), (l.to_user, 'signal', 'link', l.from_user, l.id);
    end if;
    return jsonb_build_object('status', 'accepted', 'first_contact', first);
  end if;
  raise exception '알 수 없는 동작이에요.';
end $$;


ALTER FUNCTION "public"."tama_link_write"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_longest_pets"("p_mode" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare

  u uuid := tama_private.require_owner();

  board constant integer := 20;

begin

  if p_mode is not null and p_mode not in ('easy', 'normal', 'hard') then

    raise exception '모드를 알 수 없어요.';

  end if;

  return jsonb_build_object(

    'size', board,

    'mode', p_mode,

    'pets', coalesce((

      select jsonb_agg(jsonb_build_object(

        'rank', l.rank,

        'name', coalesce(p.name, mm.name),

        'stage', coalesce(p.state->>'stage', mm.stage),

        'branch', coalesce(p.state->>'branch', mm.branch),
        -- 종(2026-10-26) — 살아 있는 펫은 상태, 기념 기록은 그때 남긴 종(별 가족 = null)
        'species', case when p.id is not null then p.state->>'species' else mm.species end,

        'dead', mm.id is not null or coalesce(p.state->'dead' = 'true'::jsonb, false),

        'death_cause', coalesce(p.state->>'deathCause', mm.death_cause),

        -- mode_of(null) 은 'easy' 라 coalesce 로 못 고른다

        'mode', case when p.id is not null then tama_private.mode_of(p.state) else mm.mode end,

        'ticks', l.ticks,

        -- 하드 순위 값(버텨 낸 위험)·돌봄 횟수 — 키가 생기기 전 기록은 null(«기록 전»)

        'score', case when p.id is not null then (case when jsonb_typeof(p.state->'riskScore') = 'number' then (p.state->>'riskScore')::numeric end) else mm.risk_score end,

        'cares', case when p.id is not null then (case when jsonb_typeof(p.state->'careCount') = 'number' then (p.state->>'careCount')::integer end) else mm.care_count end,

        'resting', p.id is not null and not p.is_primary,

        'mine', l.owner = u,

        'friend', l.owner <> u and academy_private.are_friends(u, l.owner),

        -- 모르는 사람의 이름은 싣지 않는다(사용자 결정) — 학년·선생님까지만

        'owner', case when l.owner = u then '나'

                      when academy_private.are_friends(u, l.owner) then academy_private.friend_name(l.owner)

                      when pr.role = 'teacher' then '선생님'

                      else coalesce(g.grade || '학년', '학생') end,

        -- 방은 주인의 지금 방(별이 된 뒤 방 모습은 남기지 않는다)

        'equipped', tama_private.equipped_of(l.owner) - 'character',

        'custom', coalesce((select jsonb_agg(jsonb_build_object('id', ti.id, 'slot', ti.slot, 'name', ti.name, 'design', ti.design, 'image_path', ti.image_path))

                   from public.tama_equip e join public.tama_item ti on ti.id = e.item_id and ti.custom_owner = l.owner where e.owner = l.owner), '[]'::jsonb),

        'skin_item', coalesce(p.skin_item_id, mm.skin_item_id),

        'character', case when o.id is null then null else jsonb_build_object('title', o.title, 'image_path', o.image_path) end

      ) order by l.rank)

      from tama_private.longest_pets(board, p_mode) l

      left join public.tama_pet p on p.id = l.pet_id

      left join public.tama_pet_memorial mm on mm.id = l.memorial_id

      join public.profiles pr on pr.id = l.owner

      left join public.tama_character_order o on o.id = coalesce(p.skin_order_id, mm.skin_order_id) and o.status = 'delivered'

      left join lateral (

        select r.meta->>'grade' as grade from public.resource r

        where pr.role = 'student' and r.type = 'student' and r.status = 'active' and r.meta->>'id' = split_part(pr.email, '@', 1)

        limit 1

      ) g on true

    ), '[]'::jsonb),

    -- 이 판에서 내 펫(별이 된 펫 포함) 중 가장 높은 자리(20위 밖이어도)

    'me', (

      select jsonb_build_object('rank', l.rank, 'name', coalesce(p.name, mm.name), 'ticks', l.ticks,

        'score', case when p.id is not null then (case when jsonb_typeof(p.state->'riskScore') = 'number' then (p.state->>'riskScore')::numeric end) else mm.risk_score end)

      from tama_private.longest_pets(100000, p_mode) l

      left join public.tama_pet p on p.id = l.pet_id

      left join public.tama_pet_memorial mm on mm.id = l.memorial_id

      where l.owner = u order by l.rank limit 1

    )

  );

end $$;


ALTER FUNCTION "public"."tama_longest_pets"("p_mode" "text") OWNER TO "postgres";


