CREATE OR REPLACE FUNCTION "public"."tama_memorial_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
begin
  return coalesce((
    select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
             'id', m.id, 'pet_id', m.pet_id, 'name', m.name, 'mode', m.mode, 'stage', m.stage, 'branch', m.branch,
             'species', m.species, 'abroad', m.death_cause = 'study_abroad', 'death_cause', m.death_cause,
             'skin_order_id', m.skin_order_id, 'skin_item_id', m.skin_item_id,
             'born_at', m.born_at, 'died_at', m.died_at, 'ticks', m.ticks))
           order by m.died_at desc, m.id desc)
      from (select * from public.tama_pet_memorial where owner = u order by died_at desc, id desc limit 200) m), '[]'::jsonb);
end $$;


