CREATE OR REPLACE FUNCTION "public"."tama_pet_adopt"("p_name" "text", "p_state" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  row public.tama_pet;
  now_tick bigint := floor(extract(epoch from now()) * 1000 / 300000);
begin
  if u is null or not exists (select 1 from public.profiles where id = u and role in ('student', 'teacher', 'admin')) then
    raise exception '펫은 학생·선생님 본인만 키울 수 있어요.' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_name, ''))) not between 1 and 8 then
    raise exception '이름은 1~8글자로 지어 주세요.';
  end if;
  if not public.tama_pet_state_ok(p_state) or (p_state->>'stage') <> 'egg' then
    raise exception '알 정보가 올바르지 않아요.';
  end if;
  if abs((p_state->>'tick')::numeric - now_tick) > 2 then
    raise exception '기기 시각이 맞지 않아요. 새로고침해 주세요.';
  end if;
  perform tama_private.check_new_species(u, p_state);
  perform pg_advisory_xact_lock(hashtextextended('tama-pet:' || u::text, 0));
  -- 별이 된 펫 · 창고의 펫은 세지 않는다
  if tama_private.slot_used(u) >= tama_private.pet_slots(u) then
    raise exception '펫 자리가 없어요. 펫이 어른이 되고 함께한 지 30일이 지나면 자리가 하나 늘어요.' using errcode = '23505';
  end if;
  update public.tama_pet set is_primary = false, rested_at = now(), next_call_at = null, next_call_reason = null
   where owner = u and is_primary;
  insert into public.tama_pet(owner, name, state)
    values (u, btrim(p_name), jsonb_set(p_state, '{name}', to_jsonb(btrim(p_name))))
    returning * into row;
  return jsonb_build_object('pet', to_jsonb(row), 'server_now', (extract(epoch from now()) * 1000)::bigint);
end $$;


ALTER FUNCTION "public"."tama_pet_adopt"("p_name" "text", "p_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_pet_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  row public.tama_pet;
begin
  if u is null then raise exception '로그인이 필요해요.' using errcode = '42501'; end if;
  select * into row from public.tama_pet where owner = u and is_primary limit 1;
  return jsonb_build_object(
    'pet', case when row.id is null then null else to_jsonb(row) end,
    'others', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'version', p.version, 'state', p.state,
                 'created_at', p.created_at, 'rested_at', p.rested_at, 'skin_order_id', p.skin_order_id, 'skin_item_id', p.skin_item_id,
                 'stored_at', p.stored_at)
                 order by p.created_at)
               from public.tama_pet p where p.owner = u and not p.is_primary), '[]'::jsonb),
    'slots', tama_private.pet_slots(u),
    'bought_slots', coalesce((select w.bought_slots from public.tama_wallet w where w.owner = u), 0),
    'next_slot_price', case when tama_private.user_is_admin(u) then 0
      else tama_private.slot_price(coalesce((select w.bought_slots from public.tama_wallet w where w.owner = u), 0)) end,
    'server_now', (extract(epoch from now()) * 1000)::bigint
  );
end $$;


ALTER FUNCTION "public"."tama_pet_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_pet_rebirth"("p_pet_id" "uuid", "p_name" "text", "p_state" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  row public.tama_pet;
  now_tick bigint := floor(extract(epoch from now()) * 1000 / 300000);
begin
  if u is null or not exists (select 1 from public.profiles where id = u and role in ('student', 'teacher', 'admin')) then
    raise exception '펫은 학생·선생님 본인만 키울 수 있어요.' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_name, ''))) not between 1 and 8 then
    raise exception '이름은 1~8글자로 지어 주세요.';
  end if;
  if not public.tama_pet_state_ok(p_state) or (p_state->>'stage') <> 'egg' then
    raise exception '알 정보가 올바르지 않아요.';
  end if;
  if abs((p_state->>'tick')::numeric - now_tick) > 2 then
    raise exception '기기 시각이 맞지 않아요. 새로고침해 주세요.';
  end if;
  perform tama_private.check_new_species(u, p_state);
  perform pg_advisory_xact_lock(hashtextextended('tama-pet:' || u::text, 0));
  select * into row from public.tama_pet where id = p_pet_id and owner = u and is_primary for update;
  if row.id is null then
    raise exception '함께하는 내 펫 자리에만 새 알을 받을 수 있어요.' using errcode = '42501';
  end if;
  if not coalesce((row.state->>'dead')::boolean, false) then
    raise exception '별이 된 펫 자리에만 새 알을 받을 수 있어요.';
  end if;
  update public.tama_pet
     set name = btrim(p_name), state = jsonb_set(p_state, '{name}', to_jsonb(btrim(p_name))),
         version = version + 1, updated_at = now(),
         skin_order_id = null, skin_item_id = null, next_call_at = null, next_call_reason = null
   where id = row.id
   returning * into row;
  insert into public.tama_album(owner, pet_id, pet_name, kind, stage) values (u, row.id, row.name, 'adopt', 'egg');
  return jsonb_build_object('pet', to_jsonb(row), 'server_now', (extract(epoch from now()) * 1000)::bigint);
end $$;


ALTER FUNCTION "public"."tama_pet_rebirth"("p_pet_id" "uuid", "p_name" "text", "p_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_pet_save"("p_pet_id" "uuid", "p_version" integer, "p_state" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  row public.tama_pet;
  now_tick bigint := floor(extract(epoch from now()) * 1000 / 300000);
begin
  if u is null or not exists (select 1 from public.profiles where id = u and role in ('student', 'teacher', 'admin')) then
    raise exception '펫은 학생·선생님 본인만 돌볼 수 있어요.' using errcode = '42501';
  end if;
  if not public.tama_pet_state_ok(p_state) then
    raise exception '펫 정보가 올바르지 않아요.';
  end if;
  if (p_state->>'tick')::numeric > now_tick + 1 then
    raise exception '기기 시각이 맞지 않아요. 새로고침해 주세요.';
  end if;
  update public.tama_pet
     set state = jsonb_set(p_state, '{name}', to_jsonb(name)), version = version + 1, updated_at = now()
   where id = p_pet_id and owner = u and version = p_version
   returning * into row;
  if row.id is null then
    select * into row from public.tama_pet where id = p_pet_id and owner = u;
    if row.id is null then raise exception '펫을 찾을 수 없어요.' using errcode = '42501'; end if;
    return jsonb_build_object('conflict', true, 'pet', to_jsonb(row), 'server_now', (extract(epoch from now()) * 1000)::bigint);
  end if;
  return jsonb_build_object('conflict', false, 'pet', to_jsonb(row), 'server_now', (extract(epoch from now()) * 1000)::bigint);
end $$;


ALTER FUNCTION "public"."tama_pet_save"("p_pet_id" "uuid", "p_version" integer, "p_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_pet_schedule_call"("p_pet_id" "uuid", "p_at" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := tama_private.require_owner();
begin
  if p_at is not null and (p_at < now() - interval '5 minutes' or p_at > now() + interval '26 hours') then
    raise exception '부를 시각이 올바르지 않아요.';
  end if;
  if p_at is not null and p_reason not in ('hungry', 'unhappy', 'sick', 'lights') then
    raise exception '부르는 까닭이 올바르지 않아요.';
  end if;
  update public.tama_pet
     set next_call_at = p_at, next_call_reason = case when p_at is null then null else p_reason end
   where id = p_pet_id and owner = u;
  if not found then raise exception '펫을 찾을 수 없어요.' using errcode = '42501'; end if;
  return jsonb_build_object('ok', true, 'next_call_at', p_at);
end $$;


ALTER FUNCTION "public"."tama_pet_schedule_call"("p_pet_id" "uuid", "p_at" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_pet_slot_buy"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  adm boolean := tama_private.user_is_admin(u);
  bought integer;
  price integer;
  balance integer;
begin
  perform tama_private.lock_user(u);
  insert into public.tama_wallet(owner) values (u) on conflict (owner) do nothing;
  select w.bought_slots into bought from public.tama_wallet w where w.owner = u for update;
  price := tama_private.slot_price(bought);
  if price is null then raise exception '펫 자리는 더 살 수 없어요(산 자리 최대 3개).'; end if;
  if adm then price := 0; end if;
  insert into public.academy_user_stats(user_id) values (u) on conflict (user_id) do nothing;
  update public.academy_user_stats set coins = coins - price, updated_at = now() where user_id = u and coins >= price returning coins into balance;
  if not found then raise exception '코인이 모자라요(펫 자리 %코인).', price using errcode = 'P0001'; end if;
  update public.tama_wallet set bought_slots = bought_slots + 1 where owner = u returning bought_slots into bought;
  return jsonb_build_object('bought_slots', bought, 'slots', tama_private.pet_slots(u), 'price', price, 'coins', balance,
    'next_price', case when adm then 0 else tama_private.slot_price(bought) end);
end $$;


ALTER FUNCTION "public"."tama_pet_slot_buy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_pet_state_ok"("p_state" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_typeof(p_state) = 'object'
     and (p_state->>'v') = '1'
     and (p_state->>'stage') in ('egg', 'baby', 'child', 'teen', 'adult')
     and jsonb_typeof(p_state->'tick') = 'number'
     and jsonb_typeof(p_state->'hunger') = 'number'
     and jsonb_typeof(p_state->'happy') = 'number'
     and jsonb_typeof(p_state->'events') = 'array'
$$;


ALTER FUNCTION "public"."tama_pet_state_ok"("p_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_pet_switch"("p_pet_id" "uuid", "p_state" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := auth.uid();
  row public.tama_pet;
  now_tick bigint := floor(extract(epoch from now()) * 1000 / 300000);
begin
  if u is null or not exists (select 1 from public.profiles where id = u and role in ('student', 'teacher', 'admin')) then
    raise exception '펫은 학생·선생님 본인만 돌볼 수 있어요.' using errcode = '42501';
  end if;
  if not public.tama_pet_state_ok(p_state) then raise exception '펫 정보가 올바르지 않아요.'; end if;
  if abs((p_state->>'tick')::numeric - now_tick) > 2 then raise exception '기기 시각이 맞지 않아요. 새로고침해 주세요.'; end if;
  perform pg_advisory_xact_lock(hashtextextended('tama-pet:' || u::text, 0));
  if not exists (select 1 from public.tama_pet where id = p_pet_id and owner = u and not is_primary) then
    raise exception '쉬고 있는 내 펫만 데려올 수 있어요.' using errcode = '42501';
  end if;
  if exists (select 1 from public.tama_pet where id = p_pet_id and stored_at is not null) then
    raise exception '창고에 있는 펫은 먼저 칸으로 꺼내 주세요.';
  end if;
  update public.tama_pet set is_primary = false, rested_at = now(), next_call_at = null, next_call_reason = null
   where owner = u and is_primary;
  update public.tama_pet set is_primary = true, rested_at = null, version = version + 1, updated_at = now(),
         state = jsonb_set(p_state, '{name}', to_jsonb(name))
   where id = p_pet_id and owner = u
   returning * into row;
  return jsonb_build_object('pet', to_jsonb(row), 'server_now', (extract(epoch from now()) * 1000)::bigint);
end $$;


ALTER FUNCTION "public"."tama_pet_switch"("p_pet_id" "uuid", "p_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_repeat_claim"("p_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  step integer := tama_private.repeat_step(p_id);
  have integer;
  done integer;
  reward integer;
  paid integer := 0;
  n integer;
  got integer := 0;
begin
  if step is null then raise exception '모르는 반복 업적이에요.'; end if;
  perform tama_private.lock_user(u);
  have := coalesce((tama_private.repeat_progress(u)->>p_id)::integer, 0);
  done := tama_private.repeat_claimed(u, p_id);
  reward := economy_private.num('tama.repeat.' || p_id);
  if reward <= 0 then raise exception '지금은 이 반복 업적에 보상이 없어요.'; end if;
  if have / step <= done then raise exception '아직 다음 단계에 닿지 않았어요. (%/%)', greatest(have - done * step, 0), step; end if;
  for n in done + 1 .. least(have / step, done + 50) loop
    paid := paid + wallet_private.apply(u, reward, 'tama_repeat', 'tamagotchi', p_id || ':' || n, false, '다마고찌 반복 업적 ' || p_id || ' ' || n || '번째');
    got := got + 1;
  end loop;
  return jsonb_build_object('id', p_id, 'times', got, 'amount', paid,
    'coins', (select coins from public.academy_user_stats where user_id = u));
end $$;


ALTER FUNCTION "public"."tama_repeat_claim"("p_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_shop_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := tama_private.require_owner(); total numeric; pool jsonb; picks text[]; adm boolean := tama_private.user_is_admin(u);
begin
  select sum(weight), jsonb_object_agg(id, weight) into total, pool from tama_private.gacha_pool();
  select coalesce(array_agg(distinct y), '{}') into picks from public.tama_event e, unnest(e.pickup_ids) y
   where now() >= e.starts_at and now() < e.ends_at;
  return jsonb_build_object(
    'admin', adm,
    'coins', coalesce((select coins from public.academy_user_stats where user_id = u), 100),
    'debt', coalesce((select debt from public.tama_wallet where owner = u), 0),
    'since_new', coalesce((select since_new from public.tama_wallet where owner = u), 0),
    'pulls', coalesce((select pulls from public.tama_wallet where owner = u), 0),
    'items', (select jsonb_agg(jsonb_build_object('id', i.id, 'slot', i.slot, 'rarity', i.rarity, 'name', i.name, 'event_only', i.event_only,
                'prob', coalesce(round((pool->>i.id)::numeric / total * 100, 2), 0), 'pickup', i.id = any(picks) and pool ? i.id)
                || case when i.custom_owner is null then '{}'::jsonb
                        else jsonb_build_object('custom', true, 'design', i.design, 'image_path', i.image_path) end
              order by i.sort, i.id) from public.tama_item i where i.active and (i.custom_owner is null or i.custom_owner = u)),
    'machines', (select jsonb_object_agg(mid, jsonb_build_object(
                    'price', case when adm then 0 else (tama_private.gacha_machine(mid)).price end,
                    'refund', case when adm then 0 else (tama_private.gacha_machine(mid)).refund end,
                    'probs', coalesce((select jsonb_object_agg(q.id, q.prob) from (
                                         select p.id, round(p.weight / sum(p.weight) over () * 100, 2) as prob
                                         from tama_private.gacha_pool_of(mid) p) q), '{}'::jsonb)))
                 from unnest(array['all', 'character', 'device', 'shell', 'deco']) mid),
    'events', coalesce((select jsonb_agg(jsonb_build_object('id', e.id, 'title', e.title, 'body', e.body, 'starts_at', e.starts_at, 'ends_at', e.ends_at,
                'item_ids', e.item_ids, 'pickup_ids', e.pickup_ids) order by e.starts_at)
              from public.tama_event e where now() >= e.starts_at and now() < e.ends_at), '[]'::jsonb),
    'owned', case when adm then
        coalesce((select jsonb_object_agg(i.id, coalesce(v.count, 1)) from public.tama_item i
                  left join public.tama_inventory v on v.owner = u and v.item_id = i.id
                  where i.active and (i.custom_owner is null or i.custom_owner = u)), '{}'::jsonb)
      else coalesce((select jsonb_object_agg(item_id, count) from public.tama_inventory where owner = u), '{}'::jsonb) end,
    'equipped', tama_private.equipped_of(u)
  );
end $$;


ALTER FUNCTION "public"."tama_shop_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_species_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  prim public.tama_pet;
  hatch_at timestamptz;
begin
  select * into prim from public.tama_pet where owner = u and is_primary limit 1;
  if prim.id is not null and prim.state->>'stage' in ('baby', 'child', 'teen', 'adult') and jsonb_typeof(prim.state->'hatchTick') = 'number' then
    hatch_at := to_timestamp((prim.state->>'hatchTick')::bigint * 300);
  end if;
  return jsonb_build_object(
    'unlocked', jsonb_build_object(
      'tide', tama_private.species_unlocked(u, 'tide'),
      'moon', tama_private.species_unlocked(u, 'moon'),
      'sprout', tama_private.species_unlocked(u, 'sprout')),
    'tickets', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'species', t.species, 'created_at', t.created_at,
                  'partner', case when t.partner is not null and academy_private.are_friends(u, t.partner) then academy_private.friend_name(t.partner) end)
                  order by t.created_at)
                from public.tama_egg_ticket t where t.owner = u and t.used_at is null), '[]'::jsonb),
    'storage', jsonb_build_object('size', economy_private.num('tama.storage.size'), 'used', tama_private.storage_used(u),
                  'move_price', case when tama_private.user_is_admin(u) then 0 else economy_private.num('tama.storage.move') end),
    -- 전파 가족 특수 어른 — 함께하는 펫이 부화한 뒤 교환을 마친 서로 다른 친구 수
    'trade_partners', case when hatch_at is null then 0 else (
      select count(distinct case when tr.from_user = u then tr.to_user else tr.from_user end)::integer
        from public.tama_trade tr
       where tr.status = 'accepted' and (tr.from_user = u or tr.to_user = u) and tr.responded_at >= hatch_at) end
  );
end $$;


ALTER FUNCTION "public"."tama_species_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_storage_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  pet public.tama_pet;
  price integer;
  now_tick bigint := floor(extract(epoch from now()) * 1000 / 300000);
  st jsonb;
  dead boolean;
begin
  perform pg_advisory_xact_lock(hashtextextended('tama-pet:' || u::text, 0));
  select * into pet from public.tama_pet where id = nullif(p_payload->>'pet_id', '')::uuid and owner = u for update;
  if pet.id is null then raise exception '내 펫이 아니에요.' using errcode = '42501'; end if;
  dead := coalesce((pet.state->>'dead')::boolean, false);

  if p_action = 'store' then
    if pet.stored_at is not null then raise exception '이미 창고에 있어요.'; end if;
    if dead then raise exception '별이 된 펫은 창고에 둘 수 없어요.'; end if;
    if tama_private.storage_used(u) >= economy_private.num('tama.storage.size') then raise exception '창고가 가득 찼어요.'; end if;
    price := case when tama_private.user_is_admin(u) then 0 else economy_private.num('tama.storage.move') end;
    if price > 0 then
      perform wallet_private.apply(u, -price, 'tama_storage', 'tamagotchi',
        'store:' || pet.id || ':' || floor(extract(epoch from clock_timestamp()) * 1000)::bigint, false, '펫을 창고로: ' || pet.name);
    end if;
    update public.tama_pet set stored_at = now(), is_primary = false, rested_at = coalesce(rested_at, now()),
           next_call_at = null, next_call_reason = null
     where id = pet.id;
    return jsonb_build_object('ok', true, 'price', price, 'coins', (select coins from public.academy_user_stats where user_id = u));

  elsif p_action = 'unstore' then
    if pet.stored_at is null then raise exception '창고에 있는 펫이 아니에요.'; end if;
    st := p_payload->'state';
    if not public.tama_pet_state_ok(st) then raise exception '펫 정보가 올바르지 않아요.'; end if;
    if abs((st->>'tick')::numeric - now_tick) > 2 then raise exception '기기 시각이 맞지 않아요. 새로고침해 주세요.'; end if;
    if tama_private.slot_used(u) >= tama_private.pet_slots(u) then
      raise exception '펫 자리가 없어요. 칸의 펫을 창고로 보내거나 유학을 보내 자리를 만들어 주세요.' using errcode = '23505';
    end if;
    -- 함께하는 펫이 없으면(대표를 창고·유학으로 보낸 뒤) 꺼낸 펫이 함께하는 펫이 된다
    update public.tama_pet set stored_at = null, state = jsonb_set(st, '{name}', to_jsonb(name)), version = version + 1, updated_at = now(),
           is_primary = not exists (select 1 from public.tama_pet q where q.owner = u and q.is_primary),
           rested_at = case when exists (select 1 from public.tama_pet q where q.owner = u and q.is_primary) then now() end
     where id = pet.id;
    return jsonb_build_object('ok', true);

  elsif p_action = 'abroad' then
    -- 순위 기념 기록 — 별이 된 펫처럼 남는다(이유 study_abroad, 별이 된 펫이면 그 이유 그대로). 알은 남기지 않는다
    if pet.state->>'stage' in ('baby', 'child', 'teen', 'adult') and jsonb_typeof(pet.state->'hatchTick') = 'number' then
      insert into public.tama_pet_memorial(owner, pet_id, name, mode, stage, branch, death_cause, ticks,
                                           skin_order_id, skin_item_id, born_at, died_at, care_count, risk_score)
      values (u, pet.id, pet.name, tama_private.mode_of(pet.state), pet.state->>'stage', nullif(pet.state->>'branch', ''),
              case when dead then pet.state->>'deathCause' else 'study_abroad' end,
              tama_private.cared_ticks(pet.state), pet.skin_order_id, pet.skin_item_id,
              to_timestamp((pet.state->>'hatchTick')::bigint * 300),
              case when dead and jsonb_typeof(pet.state->'deadTick') = 'number' then to_timestamp((pet.state->>'deadTick')::bigint * 300) else now() end,
              case when jsonb_typeof(pet.state->'careCount') = 'number' then (pet.state->>'careCount')::integer end,
              case when jsonb_typeof(pet.state->'riskScore') = 'number' then (pet.state->>'riskScore')::numeric end)
      on conflict (pet_id, died_at) do nothing;
    end if;
    insert into public.tama_album(owner, pet_id, pet_name, kind, stage, branch)
      values (u, pet.id, pet.name, 'abroad', pet.state->>'stage', nullif(pet.state->>'branch', ''));
    delete from public.tama_pet where id = pet.id;
    return jsonb_build_object('ok', true);
  end if;
  raise exception '알 수 없는 동작이에요.';
end $$;


ALTER FUNCTION "public"."tama_storage_write"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_ticket_hatch"("p_ticket" "uuid", "p_name" "text", "p_state" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  t public.tama_egg_ticket;
  row public.tama_pet;
  now_tick bigint := floor(extract(epoch from now()) * 1000 / 300000);
begin
  if char_length(btrim(coalesce(p_name, ''))) not between 1 and 8 then raise exception '이름은 1~8글자로 지어 주세요.'; end if;
  if not public.tama_pet_state_ok(p_state) or (p_state->>'stage') <> 'egg' then raise exception '알 정보가 올바르지 않아요.'; end if;
  if abs((p_state->>'tick')::numeric - now_tick) > 2 then raise exception '기기 시각이 맞지 않아요. 새로고침해 주세요.'; end if;
  perform pg_advisory_xact_lock(hashtextextended('tama-pet:' || u::text, 0));
  select * into t from public.tama_egg_ticket where id = p_ticket and owner = u and used_at is null for update;
  if t.id is null then raise exception '이미 깨운 알이거나 내 알이 아니에요.'; end if;
  if coalesce(p_state->>'species', 'star') <> t.species then raise exception '알 정보가 올바르지 않아요.'; end if;
  if tama_private.slot_used(u) >= tama_private.pet_slots(u) then
    raise exception '펫 자리가 없어요. 칸의 펫을 창고로 보내거나 유학을 보내 자리를 만들어 주세요.' using errcode = '23505';
  end if;
  update public.tama_pet set is_primary = false, rested_at = now(), next_call_at = null, next_call_reason = null
   where owner = u and is_primary;
  insert into public.tama_pet(owner, name, state)
    values (u, btrim(p_name), jsonb_set(p_state, '{name}', to_jsonb(btrim(p_name))))
    returning * into row;
  update public.tama_egg_ticket set used_at = now(), used_pet = row.id where id = t.id;
  return jsonb_build_object('pet', to_jsonb(row), 'server_now', (extract(epoch from now()) * 1000)::bigint);
end $$;


ALTER FUNCTION "public"."tama_ticket_hatch"("p_ticket" "uuid", "p_name" "text", "p_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tama_trade_write"("p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tama_private.require_owner();
  t public.tama_trade;
  target uuid;
  n integer;
  a uuid; b uuid;
begin
  if p_action = 'propose' then
    target := (p_payload->>'to')::uuid;
    if not academy_private.are_friends(u, target) then raise exception '별빛 친구와만 바꿀 수 있어요.' using errcode = '42501'; end if;
    if not exists (select 1 from public.tama_pet where owner = target and is_primary) then raise exception '친구가 아직 펫을 키우지 않아요.'; end if;
    if not tama_private.has_item(u, p_payload->>'give') then raise exception '가진 물건만 줄 수 있어요.' using errcode = '42501'; end if;
    if exists (select 1 from public.tama_item ci where ci.id in (p_payload->>'give', p_payload->>'want') and ci.custom_owner is not null) then
      raise exception '나만의 꾸미기는 주고받을 수 없어요.';
    end if;
    if nullif(p_payload->>'want', '') is not null and not tama_private.has_item(target, p_payload->>'want') then
      raise exception '친구가 가진 물건만 받을 수 있어요.';
    end if;
    select count(*) into n from public.tama_trade where from_user = u and status = 'pending' and created_at > now() - interval '7 days';
    if n >= 5 then raise exception '기다리는 교환이 5개예요. 친구의 답을 먼저 기다려 주세요.'; end if;
    insert into public.tama_trade(from_user, to_user, give_item, want_item)
      values (u, target, p_payload->>'give', nullif(p_payload->>'want', '')) returning * into t;
    perform tama_private.notify(target, 'tama_trade_offer',
      academy_private.friend_name(u) || case when t.want_item is null then '의 선물이 왔어요' else '이(가) 교환을 제안했어요' end,
      (select name from public.tama_item where id = t.give_item)
        || coalesce(' ↔ ' || (select name from public.tama_item where id = t.want_item), ''),
      jsonb_build_object('trade_id', t.id));
    return to_jsonb(t);
  end if;

  select * into t from public.tama_trade where id = (p_payload->>'id')::uuid;
  if t.id is null or u not in (t.from_user, t.to_user) then raise exception '교환을 찾지 못했어요.' using errcode = '42501'; end if;
  if t.status <> 'pending' then return to_jsonb(t); end if; -- 이미 끝난 교환은 그대로(재시도)

  if p_action = 'cancel' then
    if u <> t.from_user then raise exception '보낸 사람만 거둘 수 있어요.' using errcode = '42501'; end if;
    update public.tama_trade set status = 'cancelled', responded_at = now() where id = t.id returning * into t;
    return to_jsonb(t);
  elsif p_action = 'decline' then
    if u <> t.to_user then raise exception '받은 사람만 거절할 수 있어요.' using errcode = '42501'; end if;
    update public.tama_trade set status = 'declined', responded_at = now() where id = t.id returning * into t;
    return to_jsonb(t);
  elsif p_action = 'accept' then
    if u <> t.to_user then raise exception '받은 사람만 수락할 수 있어요.' using errcode = '42501'; end if;
    if t.created_at < now() - interval '7 days' then
      update public.tama_trade set status = 'failed', detail = 'expired', responded_at = now() where id = t.id returning * into t;
      return to_jsonb(t);
    end if;
    if not academy_private.are_friends(t.from_user, t.to_user) then
      update public.tama_trade set status = 'failed', detail = 'not_friends', responded_at = now() where id = t.id returning * into t;
      return to_jsonb(t);
    end if;
    -- 두 사람을 uuid 순서로 잠근다 — 동시에 서로의 제안을 수락해도 교착하지 않는다
    a := least(t.from_user, t.to_user); b := greatest(t.from_user, t.to_user);
    perform tama_private.lock_user(a);
    perform tama_private.lock_user(b);
    select * into t from public.tama_trade where id = t.id for update;
    if t.status <> 'pending' then return to_jsonb(t); end if;
    if not tama_private.has_item(t.from_user, t.give_item) or (t.want_item is not null and not tama_private.has_item(t.to_user, t.want_item)) then
      update public.tama_trade set status = 'failed', detail = 'item_gone', responded_at = now() where id = t.id returning * into t;
      return to_jsonb(t);
    end if;
    perform tama_private.move_item(t.from_user, t.to_user, t.give_item);
    if t.want_item is not null then perform tama_private.move_item(t.to_user, t.from_user, t.want_item); end if;
    update public.tama_trade set status = 'accepted', responded_at = now() where id = t.id returning * into t;
    perform tama_private.notify(t.from_user, 'tama_trade_done',
      academy_private.friend_name(t.to_user) || case when t.want_item is null then '이(가) 선물을 받았어요' else '와(과) 교환했어요' end,
      (select name from public.tama_item where id = t.give_item)
        || coalesce(' ↔ ' || (select name from public.tama_item where id = t.want_item), ''),
      jsonb_build_object('trade_id', t.id));
    return to_jsonb(t);
  end if;
  raise exception '할 일을 선택해 주세요.';
end $$;


ALTER FUNCTION "public"."tama_trade_write"("p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


