CREATE OR REPLACE FUNCTION "public"."teacher_timetable_effective"("p_academic_year" integer, "p_semester" integer, "p_from" "date", "p_to" "date", "p_teacher_resource_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("lesson_date" "date", "id" "uuid", "day_of_week" integer, "period" integer, "grade" integer, "subject_name" "text", "class_label" "text", "activity_type" "text", "teacher_name" "text", "teacher_resource_id" "uuid", "override_id" "uuid", "override_title" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with days as (
    select g::date as lesson_date, extract(isodow from g)::int as dow
    from generate_series(p_from, least(p_to, p_from + 62), interval '1 day') g
    where p_from is not null and p_to is not null and p_to >= p_from
  ),
  act as (
    select d.lesson_date, d.dow, o.id, o.title, o.grades
    from days d
    join public.timetable_override o
      on o.status = 'active' and o.academic_year = p_academic_year and o.semester = p_semester
     and d.lesson_date between o.start_date and o.end_date
  )
  select d.lesson_date, tt.id, tt.day_of_week::int, tt.period::int, tt.grade::int,
         tt.subject_name, tt.class_label, tt.activity_type,
         tt.teacher_name, tt.teacher_resource_id, null::uuid, null::text
  from days d
  join public.teacher_timetable tt
    on tt.day_of_week = d.dow and tt.academic_year = p_academic_year and tt.semester = p_semester
  where (p_teacher_resource_id is null or tt.teacher_resource_id = p_teacher_resource_id)
    and not exists (
      select 1 from act a
      where a.lesson_date = d.lesson_date and (a.grades is null or tt.grade = any(a.grades)))
  union all
  select a.lesson_date, s.id, s.day_of_week::int, s.period::int, s.grade::int,
         s.subject_name, s.class_label, s.activity_type,
         s.teacher_name, s.teacher_resource_id, a.id, a.title
  from act a
  join public.timetable_override_slot s on s.override_id = a.id and s.day_of_week = a.dow
  where (p_teacher_resource_id is null or s.teacher_resource_id = p_teacher_resource_id);
$$;


ALTER FUNCTION "public"."teacher_timetable_effective"("p_academic_year" integer, "p_semester" integer, "p_from" "date", "p_to" "date", "p_teacher_resource_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."teacher_timetable_effective"("p_academic_year" integer, "p_semester" integer, "p_from" "date", "p_to" "date", "p_teacher_resource_id" "uuid") IS '운영 시간표를 반영한 교사 수업(날짜별). 정규 = teacher_timetable, 운영 시간표가 기간·대상 학년을 덮는다. 단일 출처.';



CREATE OR REPLACE FUNCTION "public"."tg_code_project_file_stats"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_project uuid := coalesce(new.project_id, old.project_id);
begin
  update public.code_project p
     set file_count  = s.c,
         total_bytes = s.b
    from (
      select count(*)::integer as c, coalesce(sum(size_bytes), 0)::bigint as b
        from public.code_project_file f
       where f.project_id = v_project
    ) s
   where p.id = v_project;
  return null;
end;
$$;


