CREATE OR REPLACE FUNCTION "public"."timetable_override_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'active' and exists (
    select 1 from public.timetable_override o
    where o.id <> new.id and o.status = 'active'
      and o.academic_year = new.academic_year and o.semester = new.semester
      and daterange(o.start_date, o.end_date, '[]') && daterange(new.start_date, new.end_date, '[]')
      and (o.grades is null or new.grades is null or o.grades && new.grades)
  ) then
    raise exception using errcode = '23P01',
      message = '같은 기간·학년에 이미 적용 중인 운영 시간표가 있습니다 — 먼저 그것을 끄거나 기간을 바꾸세요.';
  end if;
  new.updated_at := now();
  return new;
end $$;


ALTER FUNCTION "public"."timetable_override_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."timetable_override_slot_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_grades smallint[];
begin
  select o.grades into v_grades from public.timetable_override o where o.id = new.override_id;
  if v_grades is not null and not (new.grade = any(v_grades)) then
    raise exception using errcode = '23514',
      message = format('%s학년 칸은 이 운영 시간표의 대상 학년(%s)이 아닙니다.', new.grade, array_to_string(v_grades, ','));
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."timetable_override_slot_guard"() OWNER TO "postgres";


