CREATE OR REPLACE FUNCTION "public"."toggle_rescue_tag"("p_student_code" "text", "p_tag_key" "text", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT can_care_student(p_student_code) THEN
    RAISE EXCEPTION 'access denied for student %', p_student_code USING ERRCODE = '42501';
  END IF;
  IF p_action = 'add' THEN
    INSERT INTO rescue_tags (student_code, tag_key, assigned_by)
    VALUES (p_student_code, p_tag_key, auth.uid())
    ON CONFLICT (student_code, tag_key) DO NOTHING;
  ELSIF p_action = 'remove' THEN
    DELETE FROM rescue_tags
    WHERE student_code = p_student_code AND tag_key = p_tag_key;
  ELSE
    RAISE EXCEPTION 'invalid action: %', p_action USING ERRCODE = '22023';
  END IF;
END;
$$;


