CREATE OR REPLACE FUNCTION "public"."tower_achievement_claim"("p_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  rule record;
  have integer;
  paid integer;
begin
  select * into rule from tower_private.achievement_rule(p_id);
  if rule.goal is null then raise exception '모르는 업적이에요.'; end if;
  if tower_private.is_admin(u) then
    raise exception '관리자 계정(테스트용)은 업적 코인을 받을 수 없어요.' using errcode = 'P0001';
  end if;
  -- 탑 행을 잠가 같은 사람의 받기를 줄 세운다(원장 유일 키가 두 번째를 0으로 만들지만, 진행도 판정도 같은 순간에)
  perform 1 from public.tower_state where owner = u for update;
  have := coalesce((tower_private.achievement_progress(u)->>p_id)::integer, 0);
  if have < rule.goal then raise exception '아직 달성하지 않았어요. (%/%)', have, rule.goal using errcode = 'P0001'; end if;
  paid := wallet_private.apply(u, rule.reward, 'tower_achievement', 'star-tower', p_id, false, '별까지 쌓기 업적 ' || p_id);
  return jsonb_build_object('id', p_id, 'granted', paid > 0, 'amount', paid,
    'coins', (select coins from public.academy_user_stats where user_id = u));
end $$;


ALTER FUNCTION "public"."tower_achievement_claim"("p_id" "text") OWNER TO "postgres";


