                         where user_id = u and source_app = 'star-tower' and kind = 'tower_achievement'), '[]'::jsonb),
    'rewards', (select jsonb_object_agg(a.id, economy_private.num('tower.achievement.' || a.id)) from tower_private.achievement_table() a),
    'admin', tower_private.is_admin(u)
  );
end $$;


