CREATE OR REPLACE FUNCTION "public"."tower_admin_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  today date := (now() at time zone 'Asia/Seoul')::date;
begin
  if not tower_private.is_admin(auth.uid()) then raise exception '관리자만 볼 수 있어요.' using errcode = '42501'; end if;
  return (
    with players as (
      select s.*, coalesce(p.role, '?') as role, p.name
      from public.tower_state s left join public.profiles p on p.id = s.owner
      where coalesce(p.role, '?') <> 'admin'
    ), focus as (
      select f.*, (f.started_at at time zone 'Asia/Seoul') as started_kst,
        case when f.ended_at is null then null
             else least(f.planned_seconds, greatest(0, floor(extract(epoch from f.ended_at - f.started_at))::integer)) end as sat
      from public.tower_focus f where f.owner in (select owner from players)
    ), catches as (
      select k from focus f, jsonb_array_elements_text(f.catches) k where f.ended_at is not null
    ), prog as (
      select p.owner, tower_private.achievement_progress(p.owner) j from players p
    ), ach_claims as (
      select l.user_id, l.source_id, l.delta from public.wallet_ledger l
      where l.source_app = 'star-tower' and l.kind = 'tower_achievement' and l.user_id in (select owner from players)
    ), bottle_sales as (
      select l.user_id, l.delta from public.wallet_ledger l
      where l.source_app = 'star-tower' and l.kind = 'tower_bottle_sale' and l.user_id in (select owner from players)
    )
    select jsonb_build_object(
      'generated_at', now(),
      'admins_excluded', (select count(*) from public.tower_state s join public.profiles p on p.id = s.owner and p.role = 'admin'),
      'players', jsonb_build_object(
        'total', (select count(*) from players),
        'by_role', coalesce((select jsonb_object_agg(role, n) from (select role, count(*) n from players group by role) x), '{}'::jsonb),
        'focused_ever', (select count(distinct owner) from focus),
        'active_7d', (select count(distinct owner) from focus where started_kst::date > today - 7),
        'active_today', (select count(distinct owner) from focus where started_kst::date = today)),
      'focus', jsonb_build_object(
        'completed', (select count(*) from focus where outcome = 'completed'),
        'gave_up', (select count(*) from focus where outcome = 'gave_up'),
        'running', (select count(*) from focus where ended_at is null and started_at + make_interval(secs => planned_seconds) > now()),
        'open_stale', (select count(*) from focus where ended_at is null and started_at + make_interval(secs => planned_seconds) <= now()),
        'seconds', (select coalesce(sum(focus_seconds), 0) from players)),
      'by_minutes', coalesce((select jsonb_agg(jsonb_build_object('minutes', m, 'n', n, 'completed', c) order by m) from (
          select planned_seconds / 60 as m, count(*) filter (where ended_at is not null) n, count(*) filter (where outcome = 'completed') c
          from focus group by 1) x), '[]'::jsonb),
      'by_hour', (select jsonb_agg(coalesce(n, 0) order by h) from generate_series(0, 23) h
          left join (select extract(hour from started_kst)::integer hr, count(*) n from focus group by 1) x on x.hr = h),
      'daily', (select jsonb_agg(jsonb_build_object('day', d,
            'people', (select count(distinct owner) from focus where started_kst::date = d),
            'sessions', (select count(*) from focus where started_kst::date = d),
            'minutes', (select coalesce(sum(sat), 0) / 60 from focus where started_kst::date = d)) order by d)
          from generate_series((today - 20)::timestamp, today::timestamp, interval '1 day') g(d0), lateral (select d0::date d) dd),
      'floors_hist', (select jsonb_agg(coalesce(n, 0) order by c) from generate_series(0, 16) c
          left join (select cardinality(floors) k, count(*) n from players group by 1) x on x.k = c),
      'reach_hist', (select jsonb_agg(coalesce(n, 0) order by c) from generate_series(0, 16) c
          left join (select case when towers > 0 then 16 else cardinality(floors) end k, count(*) n from players group by 1) x on x.k = c),
      -- 등성 별자리가 탑 8개까지라 0~8(마지막 칸 = 그 이상)
      'towers_hist', (select jsonb_agg(coalesce(n, 0) order by c) from generate_series(0, 8) c
          left join (select least(towers, 8) k, count(*) n from players group by 1) x on x.k = c),
      'floor_built', coalesce((select jsonb_object_agg(k, n) from (select k, count(*) n from players, unnest(floors) k group by k) x), '{}'::jsonb),
      'first_floor', coalesce((select jsonb_object_agg(k, n) from (select floors[1] k, count(*) n from players where cardinality(floors) > 0 group by 1) x), '{}'::jsonb),
      'catches', coalesce((select jsonb_object_agg(k, n) from (select k, count(*) n from catches group by k) x), '{}'::jsonb),
      'caught_by', coalesce((select jsonb_object_agg(k, n) from (select k, count(*) n from players, unnest(caught) k group by k) x), '{}'::jsonb),
      'visitors_by', coalesce((select jsonb_object_agg(k, n) from (select k, count(*) n from players, unnest(visitors) k group by k) x), '{}'::jsonb),
      -- 받은 편지 수 분포(0~전체) — 2026-10-23 부터 «편지 수»(종전 «주운 병 수»)
      'letters_hist', (select jsonb_agg(coalesce(n, 0) order by c) from generate_series(0, cardinality(tower_private.letter_keys())) c
          left join (select cardinality(letters) k, count(*) n from players group by 1) x on x.k = c),
      'letters_by', coalesce((select jsonb_object_agg(k, n) from (select k, count(*) n from players, unnest(letters) k group by k) x), '{}'::jsonb),
      'bottles', jsonb_build_object(
        'spare', (select coalesce(sum(bottle), 0) from players),
        'spare_people', (select count(*) from players where bottle > 0),
        'sold_coins', (select coalesce(sum(delta), 0) from bottle_sales),
        'sold_people', (select count(distinct user_id) from bottle_sales)),
      'achievements', coalesce((select jsonb_object_agg(a.id, jsonb_build_object(
          'done', (select count(*) from prog where coalesce((prog.j->>a.id)::integer, 0) >= a.goal),
          'claimed', (select count(*) from ach_claims c where c.source_id = a.id),
          'coins', (select coalesce(sum(c.delta), 0) from ach_claims c where c.source_id = a.id)))
        from tower_private.achievement_table() a), '{}'::jsonb),
      'list', coalesce((select jsonb_agg(r order by r->>'last_focus' desc nulls last) from (
          select jsonb_build_object('name', coalesce(p.name, '이름 없음'), 'role', p.role,
            'floors', cardinality(p.floors), 'towers', p.towers, 'seconds', p.focus_seconds, 'completed', p.sessions,
            'gave_up', (select count(*) from focus f where f.owner = p.owner and f.outcome = 'gave_up'),
            'caught', cardinality(p.caught), 'visitors', cardinality(p.visitors),
            'letters', cardinality(p.letters), 'bottles', p.bottle,
            'achievements', (select count(*) from ach_claims c where c.user_id = p.owner),
            'last_focus', (select max(f.started_at) from focus f where f.owner = p.owner),
            'joined', p.created_at) r
          from players p order by (select max(f.started_at) from focus f where f.owner = p.owner) desc nulls last, p.created_at desc limit 300) x), '[]'::jsonb)
    )
  );
end $$;


ALTER FUNCTION "public"."tower_admin_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tower_build"("p_floor" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  s public.tower_state;
  b record;
  n integer;
  cw integer; cs integer; cf integer; cst integer;
  free boolean := tower_private.is_admin(u);
begin
  select * into b from tower_private.floor_base() f where f.key = p_floor;
  if not found then raise exception '모르는 층이에요.'; end if;
  select * into s from public.tower_state where owner = u for update;
  if p_floor = any(s.floors) then raise exception '이미 지은 층이에요.'; end if;
  n := cardinality(s.floors);
  cw := tower_private.scaled(b.wood, n);
  cs := tower_private.scaled(b.scrap, n);
  cf := tower_private.scaled(b.fish, n);
  cst := n / 4;
  if free then
    cw := 0; cs := 0; cf := 0; cst := 0;
  elsif s.wood < cw or s.scrap < cs or s.fish < cf or s.star < cst then
    raise exception '재료가 모자라요.' using errcode = 'P0001';
  end if;
  update public.tower_state set
    wood = wood - cw, scrap = scrap - cs, fish = fish - cf, star = star - cst,
    floors = floors || p_floor,
    towers = towers + case when n + 1 = tower_private.full_floors() then 1 else 0 end,
    updated_at = now()
  where owner = u;
  return tower_private.state_json(u);
end $$;


ALTER FUNCTION "public"."tower_build"("p_floor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tower_focus_finish"("p_id" "uuid", "p_give_up" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  res jsonb;
begin
  if not exists (select 1 from public.tower_focus where id = p_id and owner = u) then
    raise exception '집중 기록을 찾을 수 없어요.' using errcode = '42501';
  end if;
  res := tower_private.close_focus(p_id, p_give_up);
  return res || jsonb_build_object('state', tower_private.state_json(u));
end $$;


