CREATE OR REPLACE FUNCTION "public"."tower_focus_start"("p_minutes" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  open_id uuid;
begin
  if p_minutes not in (15, 25, 45, 60) then raise exception '15 · 25 · 45 · 60분 중에서 골라 주세요.'; end if;
  select id into open_id from public.tower_focus where owner = u and ended_at is null for update;
  if open_id is not null then perform tower_private.close_focus(open_id, true); end if;
  insert into public.tower_focus(owner, planned_seconds) values (u, p_minutes * 60);
  return tower_private.state_json(u);
end $$;


