    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  v record;
begin
  select * into v from tower_private.visitor_table() t where t.key = p_key;
  if v.key is null then raise exception '모르는 방문자예요.'; end if;
  update public.tower_state set visitors = visitors || p_key, updated_at = now()
   where owner = u and cardinality(floors) >= v.unlock_at and towers >= v.towers_at and not (p_key = any(visitors));
  return tower_private.state_json(u);
end $$;


