CREATE OR REPLACE FUNCTION "public"."tower_new_tower"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  s public.tower_state;
begin
  select * into s from public.tower_state where owner = u for update;
  if cardinality(s.floors) < tower_private.full_floors() then
    raise exception '탑을 다 지어야(%층) 새 탑을 쌓을 수 있어요.', tower_private.full_floors() using errcode = 'P0001';
  end if;
  update public.tower_state set
    past_towers = past_towers || jsonb_build_array(jsonb_build_object('floors', to_jsonb(s.floors), 'done_at', now())),
    floors = '{}',
    updated_at = now()
  where owner = u;
  return tower_private.state_json(u);
end $$;


