CREATE OR REPLACE FUNCTION "public"."tower_ranking"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  board constant integer := 20;
begin
  return jsonb_build_object(
    'size', board,
    -- 관리자는 순위에서 빠진다 — 화면이 «관리자는 빠져요»라고 말한다
    'excluded', tower_private.is_admin(u),
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rank', r.rank,
        'towers', r.towers,
        'floors', to_jsonb(s.floors),
        'focus_seconds', r.focus_seconds,
        'mine', r.owner = u,
        'friend', r.owner <> u and academy_private.are_friends(u, r.owner),
        'owner', case when r.owner = u then '나'
                      when academy_private.are_friends(u, r.owner) then academy_private.friend_name(r.owner)
                      when pr.role = 'teacher' then '선생님'
                      else coalesce(g.grade || '학년', '학생') end
      ) order by r.rank)
      from tower_private.ranking(board) r
      join public.tower_state s on s.owner = r.owner
      join public.profiles pr on pr.id = r.owner
      left join lateral (
        select x.meta->>'grade' as grade from public.resource x
        where pr.role = 'student' and x.type = 'student' and x.status = 'active' and x.meta->>'id' = split_part(pr.email, '@', 1)
        limit 1
      ) g on true
    ), '[]'::jsonb),
    -- 내 자리(20위 밖이어도) — 아직 층이 없거나 관리자면 null
    'me', (
      select jsonb_build_object('rank', r.rank, 'towers', r.towers, 'floors', r.floor_count)
      from tower_private.ranking(1000000) r where r.owner = u
    ),
    'players', (select count(*) from tower_private.ranking(1000000))
  );
end $$;


