CREATE OR REPLACE FUNCTION "public"."tower_reorder"("p_floors" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  cur text[];
begin
  select floors into cur from public.tower_state where owner = u for update;
  if p_floors is null or cardinality(p_floors) <> cardinality(cur)
     or (select count(distinct x) from unnest(p_floors) x) <> cardinality(p_floors)
     or (select array_agg(x order by x) from unnest(p_floors) x) is distinct from (select array_agg(x order by x) from unnest(cur) x) then
    raise exception '지금 쌓은 층들의 순서만 바꿀 수 있어요.' using errcode = 'P0001';
  end if;
  update public.tower_state set floors = p_floors, updated_at = now() where owner = u;
  return tower_private.state_json(u);
end $$;


