CREATE OR REPLACE FUNCTION "public"."tower_sell_bottles"("p_times" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  r record;
  s public.tower_state;
  left_coins integer;
  got integer;
begin
  select * into r from tower_private.bottle_coin_rule();
  if p_times is null or p_times < 1 or p_times > 50 then raise exception '한 번에 1~50개까지 바꿀 수 있어요.'; end if;
  if tower_private.is_admin(u) then
    raise exception '관리자 계정(테스트용)은 병을 코인으로 바꿀 수 없어요.' using errcode = 'P0001';
  end if;
  select * into s from public.tower_state where owner = u for update;
  if cardinality(s.floors) < r.min_floors then
    raise exception '비공정 상인은 구름층(%층)부터 와요.', r.min_floors using errcode = 'P0001';
  end if;
  left_coins := r.daily_cap - tower_private.bottle_coins_today(u);
  if left_coins < r.rate then
    raise exception '오늘은 더 바꿀 수 없어요(하루 %코인까지).', r.daily_cap using errcode = 'P0001';
  end if;
  if p_times * r.rate > left_coins then
    raise exception '오늘은 병 %개까지 더 바꿀 수 있어요.', left_coins / r.rate using errcode = 'P0001';
  end if;
  if s.bottle < p_times then raise exception '남는 병이 모자라요. 병 편지를 다 모은 뒤에 걸린 병만 팔 수 있어요.' using errcode = 'P0001'; end if;
  update public.tower_state set bottle = bottle - p_times, updated_at = now() where owner = u;
  got := wallet_private.apply(u, p_times * r.rate, 'tower_bottle_sale', 'star-tower', gen_random_uuid()::text, false,
                              format('남는 병 %s개', p_times));
  return tower_private.state_json(u) || jsonb_build_object('coins_got', got);
end $$;


ALTER FUNCTION "public"."tower_sell_bottles"("p_times" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tower_sell_stars"("p_times" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  r record;
  s public.tower_state;
  left_coins integer;
  got integer;
begin
  select * into r from tower_private.star_coin_rule();
  if p_times is null or p_times < 1 or p_times > 50 then raise exception '한 번에 1~50개까지 바꿀 수 있어요.'; end if;
  if tower_private.is_admin(u) then
    raise exception '관리자의 별 조각은 테스트용(무한)이라 코인으로 바꿀 수 없어요.' using errcode = 'P0001';
  end if;
  select * into s from public.tower_state where owner = u for update;
  if cardinality(s.floors) < r.min_floors then
    raise exception '비공정 상인은 구름층(%층)부터 와요.', r.min_floors using errcode = 'P0001';
  end if;
  left_coins := r.daily_cap - tower_private.star_coins_today(u);
  if left_coins < r.rate then
    raise exception '오늘은 더 바꿀 수 없어요(하루 %코인까지).', r.daily_cap using errcode = 'P0001';
  end if;
  if p_times * r.rate > left_coins then
    raise exception '오늘은 별 조각 %개까지 더 바꿀 수 있어요.', left_coins / r.rate using errcode = 'P0001';
  end if;
  if s.star < p_times then raise exception '별 조각이 모자라요.' using errcode = 'P0001'; end if;
  update public.tower_state set star = star - p_times, updated_at = now() where owner = u;
  got := wallet_private.apply(u, p_times * r.rate, 'tower_star_sale', 'star-tower', gen_random_uuid()::text, false,
                              format('별 조각 %s개', p_times));
  return tower_private.state_json(u) || jsonb_build_object('coins_got', got);
end $$;


ALTER FUNCTION "public"."tower_sell_stars"("p_times" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tower_trade"("p_kind" "text", "p_times" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  u uuid := tower_private.actor();
  gf integer := 0; gs integer := 0;            -- 내는 것: 물고기 · 별 조각
  tw integer := 0; ts integer := 0;            -- 받는 것: 나무 · 고철
begin
  if p_times is null or p_times < 1 or p_times > 50 then raise exception '한 번에 1~50번까지 바꿀 수 있어요.'; end if;
  case p_kind
    when 'wood' then gf := 3; tw := 1;
    when 'scrap' then gf := 5; ts := 1;
    when 'merchant_scrap' then gf := 4; ts := 1;
    when 'star_bundle' then gs := 1; tw := 4; ts := 2;
    else raise exception '모르는 교환이에요.';
  end case;
  if p_kind in ('merchant_scrap', 'star_bundle')
     and (select cardinality(floors) from public.tower_state where owner = u) < 7 then
    raise exception '비공정 상인은 구름층(7층)부터 와요.' using errcode = 'P0001';
  end if;
  if tower_private.is_admin(u) then return tower_private.state_json(u); end if;
  update public.tower_state set
    fish = fish - gf * p_times, star = star - gs * p_times,
    wood = wood + tw * p_times, scrap = scrap + ts * p_times,
    updated_at = now()
  where owner = u and fish >= gf * p_times and star >= gs * p_times;
  if not found then raise exception '내줄 것이 모자라요.' using errcode = 'P0001'; end if;
  return tower_private.state_json(u);
end $$;


ALTER FUNCTION "public"."tower_trade"("p_kind" "text", "p_times" integer) OWNER TO "postgres";


