CREATE OR REPLACE FUNCTION "public"."training_sign_link_on_meeting"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.kind <> 'training' then return new; end if;

  if tg_op = 'INSERT' then
    insert into public.training_sign_link (meeting_id, expires_at)
    values (new.id, public.training_sign_default_expiry(new.ends_at))
    on conflict (meeting_id) do nothing;
    perform public.training_sign_sync_tokens(new.id, new.meta->'assignee');
    return new;
  end if;

  -- UPDATE — 이 기능 이후 만든 연수(링크 행이 있는 연수)만
  if not exists (select 1 from public.training_sign_link l where l.meeting_id = new.id) then return new; end if;
  if (new.meta->'assignee') is distinct from (old.meta->'assignee') then
    perform public.training_sign_sync_tokens(new.id, new.meta->'assignee');
  end if;
  if new.ends_at is distinct from old.ends_at then
    update public.training_sign_link
       set expires_at = public.training_sign_default_expiry(new.ends_at), updated_at = now()
     where meeting_id = new.id and not expires_custom;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."training_sign_link_on_meeting"() OWNER TO "postgres";


