CREATE OR REPLACE FUNCTION "public"."training_sign_sync_tokens"("p_meeting_id" "uuid", "p_assignee" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_names text[];
begin
  v_names := case when jsonb_typeof(p_assignee) = 'object'
                  then array(select k from jsonb_object_keys(p_assignee) k where btrim(k) <> '')
                  else '{}' end;
  insert into public.training_sign_token (token, meeting_id, signer_name)
  select public.training_sign_new_token(), p_meeting_id, n from unnest(v_names) n
  on conflict (meeting_id, signer_name) do nothing;
  delete from public.training_sign_token t
   where t.meeting_id = p_meeting_id and t.used_at is null and not (t.signer_name = any (v_names));
end;
$$;


ALTER FUNCTION "public"."training_sign_sync_tokens"("p_meeting_id" "uuid", "p_assignee" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_has_pending_submission"("p_task_id" "uuid", "p_resource_id" "uuid", "p_unit_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.collect_request q
    join public.task_action a on a.id = q.action_id and a.archived_at is null
    join public.collect_target t on t.action_id = q.action_id and t.removed_at is null and t.resource_id = p_resource_id
    where q.task_id = p_task_id and q.kind <> 'input' and q.status = 'open' and q.axis = 'unit'
      and not exists (select 1 from public.action_submission s
                      where s.action_id = q.action_id and s.resource_id = p_resource_id and s.unit_key = p_unit_key));
$$;


