CREATE OR REPLACE FUNCTION "public"."unlock_puzzle_piece"("p_event_id" "uuid", "p_piece_index" integer) RETURNS TABLE("piece_index" integer, "remaining_points" integer, "is_puzzle_completed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_student_id uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_is_staff boolean;
  v_event public.puzzle_events%rowtype;
  v_unlocked_count integer;
  v_balance integer;
  v_pay_points integer;
  v_pay_coins integer;
begin
  if v_student_id is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  -- 같은 학생의 동시 요청을 직렬화 (잔액 확인-차감 사이 이중 사용 방지)
  perform pg_advisory_xact_lock(hashtext(v_student_id::text));

  select exists(select 1 from public.profiles where id = v_student_id and role in ('teacher', 'admin')) into v_is_staff;

  select * into v_event from public.puzzle_events where id = p_event_id;
  if v_event.id is null then raise exception '퍼즐 이벤트를 찾을 수 없습니다.'; end if;

  if not v_is_staff then
    if not v_event.is_active or v_today < v_event.start_date or v_today > v_event.end_date then
      raise exception '현재 진행 중인 이벤트가 아닙니다.';
    end if;
  end if;

  if p_piece_index < 0 or p_piece_index >= v_event.total_pieces then
    raise exception '유효하지 않은 조각 번호입니다.';
  end if;

  if exists(select 1 from public.student_puzzle_progress spp
            where spp.student_id = v_student_id and spp.event_id = p_event_id and spp.piece_index = p_piece_index) then
    raise exception '이미 오픈한 조각입니다.';
  end if;

  if not v_is_staff then
    select coalesce(sum(amount), 0) into v_balance from public.point_transactions where student_id = v_student_id;
    v_pay_points := least(greatest(v_balance, 0), v_event.piece_cost);
    v_pay_coins := wallet_private.puzzle_coin_cost(v_event.piece_cost - v_pay_points);
    if v_pay_coins > 0
       and coalesce((select coins from public.academy_user_stats where user_id = v_student_id), 100) < v_pay_coins then
      raise exception '포인트가 부족합니다. (필요: %pt, 보유: %pt · 모자란 만큼 코인 %개가 필요합니다)',
        v_event.piece_cost, v_balance, v_pay_coins;
    end if;
    if v_pay_points > 0 then
      insert into public.point_transactions (student_id, amount, type, reference_id, description)
      values (v_student_id, -v_pay_points, 'puzzle_unlock', p_event_id::text || '_piece_' || p_piece_index,
              '퍼즐 조각 #' || (p_piece_index + 1) || ' 오픈');
    end if;
    if v_pay_coins > 0 then
      perform wallet_private.apply(v_student_id, -v_pay_coins, 'puzzle_unlock', 'seaton',
                                   p_event_id::text || ':' || p_piece_index, false,
                                   '퍼즐 조각 #' || (p_piece_index + 1));
    end if;
  end if;

  insert into public.student_puzzle_progress (student_id, event_id, piece_index)
  values (v_student_id, p_event_id, p_piece_index);

  select count(*) into v_unlocked_count from public.student_puzzle_progress spp
  where spp.student_id = v_student_id and spp.event_id = p_event_id;

  if v_unlocked_count >= v_event.total_pieces then
    insert into public.student_puzzle_collection (student_id, event_id)
    values (v_student_id, p_event_id)
    on conflict (student_id, event_id) do nothing;
  end if;

  select coalesce(sum(amount), 0) into v_balance from public.point_transactions where student_id = v_student_id;
  return query select p_piece_index, v_balance, (v_unlocked_count >= v_event.total_pieces);
end $$;


ALTER FUNCTION "public"."unlock_puzzle_piece"("p_event_id" "uuid", "p_piece_index" integer) OWNER TO "postgres";


