CREATE OR REPLACE FUNCTION "public"."update_assignee_status_meta"("p_task_id" "uuid", "p_user_id" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    user_resource_id UUID;
    current_meta JSONB;
    current_assignees JSONB;
    updated_assignees JSONB;
    assignee_found BOOLEAN := FALSE;
    assignee JSONB;
    new_assignee JSONB;
    old_status TEXT;
BEGIN
    -- Get user's resource ID
    SELECT ur.resource_id INTO user_resource_id
    FROM user_resource ur
    WHERE ur.user_id = p_user_id
    LIMIT 1;

    IF user_resource_id IS NULL THEN
        RAISE EXCEPTION 'User resource not found for user %', p_user_id;
    END IF;

    -- Get current meta and assignees
    SELECT meta INTO current_meta
    FROM task
    WHERE id = p_task_id;

    IF current_meta IS NULL THEN
        RAISE EXCEPTION 'Task not found: %', p_task_id;
    END IF;

    current_assignees := current_meta->'assignees';
    IF current_assignees IS NULL THEN
        RAISE EXCEPTION 'No assignees found for task: %', p_task_id;
    END IF;

    -- Initialize updated assignees as empty array
    updated_assignees := '[]'::JSONB;

    -- Process each assignee
    FOR assignee IN SELECT * FROM jsonb_array_elements(current_assignees)
    LOOP
        IF (assignee->>'id')::UUID = user_resource_id THEN
            assignee_found := TRUE;
            old_status := assignee->>'status';

            -- Update this assignee's status
            new_assignee := jsonb_build_object(
                'id', user_resource_id,
                'name', assignee->>'name',
                'status', p_status,
                'assigned_at', assignee->>'assigned_at',
                'completed_at', CASE
                    WHEN p_status = 'completed' THEN to_jsonb(NOW()::TEXT)
                    ELSE assignee->'completed_at'
                END
            );

            updated_assignees := updated_assignees || new_assignee;
        ELSE
            -- Keep other assignees unchanged
            updated_assignees := updated_assignees || assignee;
        END IF;
    END LOOP;

    IF NOT assignee_found THEN
        RAISE EXCEPTION 'User % is not assigned to task %', user_resource_id, p_task_id;
    END IF;

    -- Update the task meta with new assignees
    UPDATE task
    SET meta = jsonb_set(current_meta, '{assignees}', updated_assignees),
        updated_at = NOW()
    WHERE id = p_task_id;

    -- Record status change in history
    INSERT INTO task_status_history (task_id, changed_by, old_status, new_status, comment)
    VALUES (
        p_task_id,
        user_resource_id,
        old_status,
        p_status,
        'Assignee status updated via meta.assignees'
    );

    -- Return success result
    RETURN jsonb_build_object(
        'success', TRUE,
        'task_id', p_task_id,
        'user_id', p_user_id,
        'old_status', old_status,
        'new_status', p_status,
        'updated_at', NOW()
    );
END;
$$;


ALTER FUNCTION "public"."update_assignee_status_meta"("p_task_id" "uuid", "p_user_id" "uuid", "p_status" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."update_assignee_status_meta"("p_task_id" "uuid", "p_user_id" "uuid", "p_status" "text") IS 'Update individual assignee status in task.meta.assignees';



