CREATE OR REPLACE FUNCTION "public"."update_club_activities"("p_issue_id" "uuid", "p_club_id" "text", "p_activities" "jsonb") RETURNS "public"."document_issue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row      document_issue;
  v_is_admin boolean;
  v_name     text;
  v_my_res   uuid[];
  v_allowed  boolean;
  v_new      jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM document_issue WHERE id = p_issue_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '발급 기록을 찾을 수 없습니다'; END IF;
  IF v_row.doc_type <> 'volunteer_club' THEN
    RAISE EXCEPTION '동아리 봉사 기록만 수정 가능';
  END IF;
  IF NOT (v_row.form_data ? 'clubs')
     OR NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_row.form_data->'clubs') c
       WHERE c->>'club_id' = p_club_id) THEN
    RAISE EXCEPTION '해당 동아리를 찾을 수 없습니다';
  END IF;

  SELECT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin') INTO v_is_admin;
  SELECT name INTO v_name FROM profiles WHERE id = auth.uid();
  SELECT array_agg(r.id) INTO v_my_res
  FROM resource r WHERE r.type = 'teacher' AND r.name = v_name;

  v_allowed := v_is_admin OR v_row.created_by = auth.uid();
  IF NOT v_allowed THEN
    SELECT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_row.form_data->'clubs') c
      WHERE c->>'club_id' = p_club_id
        AND (
          (v_name IS NOT NULL AND c->>'teacher_name' = v_name)
          OR (c->>'teacher_resource_id' IS NOT NULL
              AND v_my_res IS NOT NULL
              AND (c->>'teacher_resource_id')::uuid = ANY (v_my_res))
        )
    ) INTO v_allowed;
  END IF;
  IF NOT v_allowed THEN
    RAISE EXCEPTION '이 동아리의 활동 내용을 수정할 권한이 없습니다' USING ERRCODE = '42501';
  END IF;

  -- 대상 동아리의 activities만 교체, 나머지 동아리 보존
  SELECT jsonb_agg(
    CASE WHEN c->>'club_id' = p_club_id
         THEN jsonb_set(c, '{activities}', COALESCE(p_activities, '[]'::jsonb))
         ELSE c END)
  INTO v_new
  FROM jsonb_array_elements(v_row.form_data->'clubs') c;

  UPDATE document_issue
  SET form_data = jsonb_set(form_data, '{clubs}', COALESCE(v_new, '[]'::jsonb)),
      updated_at = now()
  WHERE id = p_issue_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."update_club_activities"("p_issue_id" "uuid", "p_club_id" "text", "p_activities" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_club_attendance"("p_issue_id" "uuid", "p_club_id" "text", "p_attendance" "jsonb", "p_excluded" "jsonb") RETURNS "public"."document_issue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row      document_issue;
  v_is_admin boolean;
  v_name     text;
  v_my_res   uuid[];
  v_allowed  boolean;
  v_new      jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM document_issue WHERE id = p_issue_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '발급 기록을 찾을 수 없습니다'; END IF;
  IF v_row.doc_type <> 'volunteer_club' THEN
    RAISE EXCEPTION '동아리 봉사 기록만 수정 가능';
  END IF;
  IF NOT (v_row.form_data ? 'clubs')
     OR NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_row.form_data->'clubs') c
       WHERE c->>'club_id' = p_club_id) THEN
    RAISE EXCEPTION '해당 동아리를 찾을 수 없습니다';
  END IF;

  SELECT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin') INTO v_is_admin;
  SELECT name INTO v_name FROM profiles WHERE id = auth.uid();
  SELECT array_agg(r.id) INTO v_my_res
  FROM resource r WHERE r.type = 'teacher' AND r.name = v_name;

  v_allowed := v_is_admin OR v_row.created_by = auth.uid();
  IF NOT v_allowed THEN
    SELECT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_row.form_data->'clubs') c
      WHERE c->>'club_id' = p_club_id
        AND (
          (v_name IS NOT NULL AND c->>'teacher_name' = v_name)
          OR (c->>'teacher_resource_id' IS NOT NULL
              AND v_my_res IS NOT NULL
              AND (c->>'teacher_resource_id')::uuid = ANY (v_my_res))
        )
    ) INTO v_allowed;
  END IF;
  IF NOT v_allowed THEN
    RAISE EXCEPTION '이 동아리의 출력 설정을 수정할 권한이 없습니다' USING ERRCODE = '42501';
  END IF;

  -- 대상 동아리의 attendance·excludedResourceIds만 교체
  SELECT jsonb_agg(
    CASE WHEN c->>'club_id' = p_club_id
         THEN jsonb_set(
                jsonb_set(c, '{attendance}', COALESCE(p_attendance, '{}'::jsonb)),
                '{excludedResourceIds}', COALESCE(p_excluded, '[]'::jsonb))
         ELSE c END)
  INTO v_new
  FROM jsonb_array_elements(v_row.form_data->'clubs') c;

  UPDATE document_issue
  SET form_data = jsonb_set(form_data, '{clubs}', COALESCE(v_new, '[]'::jsonb)),
      updated_at = now()
  WHERE id = p_issue_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."update_club_attendance"("p_issue_id" "uuid", "p_club_id" "text", "p_attendance" "jsonb", "p_excluded" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_collect_config"("p_action_id" "uuid", "p_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_action public.task_action;
  v_req    public.collect_request;
  v_err    text;
  v_old    jsonb;
  v_title  text;
  v_submit boolean;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select * into v_action from public.task_action where id = p_action_id for update;
  if not found or public.request_kind_of(v_action.action_type) is null then
    raise exception '요청 설정이 있는 작업이 아닙니다' using errcode = 'P0002';
  end if;
  v_submit := public.is_submit_action_type(v_action.action_type);
  if not public.can_manage_collect(p_action_id) then
    raise exception '이 작업을 만든 사람과 업무 책임자만 설정을 바꿀 수 있습니다' using errcode = '42501';
  end if;
  if jsonb_typeof(p_config) <> 'object' then raise exception '설정 형식이 올바르지 않습니다' using errcode = '22023'; end if;

  select * into v_req from public.collect_request where action_id = p_action_id;
  if found and not v_submit then
    -- 입력 받기: 시작 후 잠금(종전 그대로)
    v_old := v_action.config->'collect';
    if coalesce(p_config->>'axis', 'person') <> v_req.axis
       or coalesce(p_config->>'answerMode', 'each') <> v_req.answer_mode
       or coalesce(p_config->>'mode', 'private') <> v_req.visibility then
      raise exception '요청을 보낸 뒤에는 줄 단위·응답 방식·공개 방식을 바꿀 수 없습니다' using errcode = '22023';
    end if;
    if coalesce(p_config->'dimensions', '[]'::jsonb) is distinct from coalesce(v_old->'dimensions', '[]'::jsonb) then
      raise exception '요청을 보낸 뒤에는 구분을 바꿀 수 없습니다' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_array_elements(coalesce(v_old->'fields', '[]'::jsonb)) o
      where not exists (
        select 1 from jsonb_array_elements(coalesce(p_config->'fields', '[]'::jsonb)) n
        where n.value->>'key' = o.value->>'key' and n.value->>'type' = o.value->>'type')
    ) then
      raise exception '요청을 보낸 뒤에는 기존 입력 항목을 지우거나 형식을 바꿀 수 없습니다(새 항목 추가·이름 변경은 됩니다)' using errcode = '22023';
    end if;
  elsif found and v_submit and v_action.action_type = 'submit.document'
        and coalesce(p_config->'template'->>'id', '') is distinct from coalesce(v_action.config->'submit'->'template'->>'id', '')
        and exists (select 1 from public.action_submission where action_id = p_action_id) then
    -- 이미 낸 사람과 앞으로 낼 사람이 다른 양식을 쓰게 된다
    raise exception '이미 제출된 문서가 있어 양식을 바꿀 수 없습니다' using errcode = '22023';
  end if;

  v_title := nullif(btrim(coalesce(p_config->>'title', '')), '');
  update public.task_action
     set config = jsonb_set(coalesce(config, '{}'::jsonb), case when v_submit then '{submit}'::text[] else '{collect}'::text[] end, p_config),
         title = coalesce(v_title, case v_action.action_type
                                     when 'submit.file' then '파일 제출 받기'
                                     when 'submit.document' then '양식 문서 제출 받기'
                                     when 'submit.physical' then '실물 제출 받기'
                                     else '입력 받기' end),
         updated_at = now()
   where id = p_action_id;

  v_err := case when v_submit then public.submit_config_error(v_action.action_type, public.submit_cfg_of(jsonb_build_object('submit', p_config)))
                else public.collect_config_error(p_config) end;
  return jsonb_build_object('ok', true, 'warning', v_err);
end;
$$;


