CREATE OR REPLACE FUNCTION "public"."update_message_config"("p_action_id" "uuid", "p_config" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_type text;
begin
  if auth.uid() is null then raise exception '로그인이 필요합니다' using errcode = '42501'; end if;
  select action_type into v_type from public.task_action where id = p_action_id;
  if v_type is distinct from 'message.send' then
    raise exception '메시지 보내기 작업이 아닙니다' using errcode = 'P0002';
  end if;
  if not public.can_manage_task_action(p_action_id) then
    raise exception '이 작업을 만든 사람과 업무 책임자만 메시지를 고칠 수 있습니다' using errcode = '42501';
  end if;
  if jsonb_typeof(p_config) <> 'object' then
    raise exception '설정 형식이 올바르지 않습니다' using errcode = '22023';
  end if;
  if length(coalesce(p_config->>'body', '')) > 4000 then
    raise exception '본문은 4,000자까지입니다' using errcode = '22023';
  end if;

  update public.task_action
     set config = jsonb_set(coalesce(config, '{}'::jsonb), '{message}', p_config),
         title = coalesce(nullif(btrim(p_config->>'title'), ''), '메시지 보내기'),
         updated_at = now()
   where id = p_action_id;
end;
$$;


