CREATE OR REPLACE FUNCTION "public"."update_profile_stats_on_problem_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Increment problems_registered count
    UPDATE public.profiles 
    SET problems_registered = problems_registered + 1,
        updated_at = NOW()
    WHERE id = NEW.user_id;
    
  ELSIF TG_OP = 'DELETE' THEN
    -- Decrement problems_registered count
    UPDATE public.profiles 
    SET problems_registered = GREATEST(problems_registered - 1, 0),
        updated_at = NOW()
    WHERE id = OLD.user_id;
  END IF;
  
  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."update_profile_stats_on_problem_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_profile_stats_on_solution_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$BEGIN
  IF TG_OP = 'INSERT' THEN
    -- profiles 솔루션 등록 카운트만 증가
    UPDATE public.profiles
      SET solutions_registered = solutions_registered + 1
    WHERE id = NEW.user_id;

    -- 문제의 updated_at 갱신
    UPDATE public.problems
      SET updated_at = clock_timestamp()
    WHERE id = NEW.problem_id;

  ELSIF TG_OP = 'DELETE' THEN
    -- profiles 솔루션 등록 카운트만 감소
    UPDATE public.profiles
      SET solutions_registered = GREATEST(solutions_registered - 1, 0)
    WHERE id = OLD.user_id;

    -- 문제의 updated_at 갱신
    UPDATE public.problems
      SET updated_at = clock_timestamp()
    WHERE id = OLD.problem_id;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;$$;


ALTER FUNCTION "public"."update_profile_stats_on_solution_change"() OWNER TO "postgres";


