CREATE OR REPLACE FUNCTION "public"."update_task_status"("p_task_id" "uuid", "p_new_status" "text", "p_changed_by" "uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    old_status text;
BEGIN
    -- 현재 상태 조회
    SELECT status INTO old_status FROM task WHERE id = p_task_id;
    
    IF old_status IS NULL THEN
        RAISE EXCEPTION 'Task not found';
    END IF;
    
    -- 상태 업데이트
    UPDATE task 
    SET status = p_new_status, 
        updated_at = NOW()
    WHERE id = p_task_id;
    
    -- 이력 저장
    INSERT INTO task_status_history (task_id, changed_by, old_status, new_status, comment)
    VALUES (p_task_id, p_changed_by, old_status, p_new_status, p_comment);
    
    RETURN true;
END;
$$;


