CREATE OR REPLACE FUNCTION "public"."update_user_achievement_progress"("_user_id" "uuid", "_achievement_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  current_progress INTEGER;
  target_count INTEGER;
  is_completed BOOLEAN := false;
BEGIN
  -- Calculate current progress
  current_progress := public.calculate_problem_solving_progress(_user_id, _achievement_id);
  
  -- Get target count
  SELECT achievements.target_count INTO target_count
  FROM public.achievements 
  WHERE id = _achievement_id;
  
  -- Check if completed
  IF current_progress >= target_count THEN
    is_completed := true;
  END IF;
  
  -- Insert or update user achievement
  INSERT INTO public.user_achievements (user_id, achievement_id, current_progress, is_completed, completed_at)
  VALUES (_user_id, _achievement_id, current_progress, is_completed, 
          CASE WHEN is_completed THEN now() ELSE NULL END)
  ON CONFLICT (user_id, achievement_id) 
  DO UPDATE SET 
    current_progress = EXCLUDED.current_progress,
    is_completed = EXCLUDED.is_completed,
    completed_at = CASE 
      WHEN NOT user_achievements.is_completed AND EXCLUDED.is_completed THEN now()
      WHEN NOT EXCLUDED.is_completed THEN NULL
      ELSE user_achievements.completed_at
    END,
    updated_at = now();
END;
$$;


