CREATE OR REPLACE FUNCTION "public"."update_volunteer_class_roster"("p_issue_id" "uuid", "p_grade" integer, "p_class" integer, "p_students" "jsonb") RETURNS "public"."document_issue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row document_issue;
  v_is_admin boolean;
  v_others jsonb;
  v_merged jsonb;
  v_grades int[];
  v_rep_grade int;
BEGIN
  SELECT * INTO v_row FROM document_issue WHERE id = p_issue_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '발급 기록을 찾을 수 없습니다'; END IF;
  IF v_row.doc_type <> 'volunteer_class' THEN
    RAISE EXCEPTION '반별 봉사 기록만 반별 수정 가능';
  END IF;

  SELECT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin') INTO v_is_admin;

  -- 권한 게이트
  IF NOT (v_is_admin OR v_row.created_by = auth.uid()
          OR public.is_homeroom_teacher(p_grade, p_class)) THEN
    RAISE EXCEPTION '이 반을 수정할 권한이 없습니다';
  END IF;

  -- 다른 반 학생 보존 + 이 반만 교체
  SELECT coalesce(jsonb_agg(e), '[]'::jsonb) INTO v_others
  FROM jsonb_array_elements(v_row.students) e
  WHERE NOT ((e->>'grade')::int = p_grade AND (e->>'class')::int = p_class);

  v_merged := v_others || coalesce(p_students, '[]'::jsonb);

  -- 대표 학년/반 재계산 (단일 학년이면 그 학년, 아니면 null)
  SELECT array_agg(DISTINCT (e->>'grade')::int) INTO v_grades
  FROM jsonb_array_elements(v_merged) e WHERE e->>'grade' IS NOT NULL;
  v_rep_grade := CASE WHEN array_length(v_grades,1) = 1 THEN v_grades[1] ELSE NULL END;

  UPDATE document_issue
  SET students = v_merged,
      grade = v_rep_grade,
      class_number = NULL,
      updated_at = now()
  WHERE id = p_issue_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."update_volunteer_class_roster"("p_issue_id" "uuid", "p_grade" integer, "p_class" integer, "p_students" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_inquiry_analysis_cache"("p_cache_key" "text", "p_student_id" "text", "p_result" "jsonb", "p_model" "text", "p_prompt_tokens" integer DEFAULT 0, "p_completion_tokens" integer DEFAULT 0, "p_expires_at" timestamp with time zone DEFAULT ("now"() + '24:00:00'::interval)) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.inquiry_design_can_access_student(p_student_id) THEN
    RAISE EXCEPTION 'not allowed to write inquiry cache for student %', p_student_id;
  END IF;

  INSERT INTO public.inquiry_design_llm_cache (
    cache_key,
    student_id,
    result,
    model,
    prompt_tokens,
    completion_tokens,
    created_at,
    expires_at
  )
  VALUES (
    p_cache_key,
    p_student_id,
    p_result,
    p_model,
    COALESCE(p_prompt_tokens, 0),
    COALESCE(p_completion_tokens, 0),
    now(),
    p_expires_at
  )
  ON CONFLICT (cache_key)
  DO UPDATE SET
    student_id = EXCLUDED.student_id,
    result = EXCLUDED.result,
    model = EXCLUDED.model,
    prompt_tokens = EXCLUDED.prompt_tokens,
    completion_tokens = EXCLUDED.completion_tokens,
    created_at = EXCLUDED.created_at,
    expires_at = EXCLUDED.expires_at;
END;
$$;


