CREATE OR REPLACE FUNCTION "public"."user_can_access_meeting"("user_uuid" "uuid", "meeting_uuid" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  BEGIN
    -- Check if user has access to the meeting
    RETURN EXISTS (
      SELECT 1
      FROM meeting m
      JOIN user_resource ur ON ur.user_id = user_uuid
      JOIN profiles p ON p.id = user_uuid
      WHERE m.id = meeting_uuid
      AND (
        -- User is the creator (both old and new field names)
        m.creator = ur.resource_id
        OR m.created_by = ur.resource_id
        -- Personal schedules are only accessible to the creator
        OR (m.kind = 'personal' AND m.created_by = ur.resource_id)
        -- For duty, document_submission, training: check assignee list
        OR (m.kind IN ('duty', 'document_submission', 'training')
            AND m.meta ? 'assignee'
            AND m.meta->'assignee' ? p.name)
        -- User is in the participants list in meta.participants JSON array (legacy)
        OR (m.meta ? 'participants'
            AND m.meta->'participants' @> jsonb_build_array(
              jsonb_build_object('resource_id', ur.resource_id::text)
            ))
        -- All authenticated users can access schedule and event type meetings
        OR (m.kind IN ('schedule', 'event'))
      )
    );
  END;
$$;


ALTER FUNCTION "public"."user_can_access_meeting"("user_uuid" "uuid", "meeting_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_can_access_section"("user_uuid" "uuid", "section_uuid" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  DECLARE
    section_name text;
  BEGIN
    -- Get section name from section table
    SELECT name INTO section_name FROM section WHERE id = section_uuid;

    -- Check if user has access to any resource that has this section in their meta.section array
    RETURN EXISTS (
      SELECT 1
      FROM resource r
      JOIN user_resource ur ON ur.resource_id = r.id
      WHERE ur.user_id = user_uuid
        AND r.meta ? 'section'
        AND r.meta->'section' ? section_name
    );
  END;
  $$;


ALTER FUNCTION "public"."user_can_access_section"("user_uuid" "uuid", "section_uuid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_assignees_jsonb"("assignees" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Check if it's an array
    IF jsonb_typeof(assignees) != 'array' THEN
        RETURN FALSE;
    END IF;
    
    -- Check each assignee object structure
    FOR i IN 0..(jsonb_array_length(assignees) - 1) LOOP
        DECLARE
            assignee JSONB := assignees -> i;
        BEGIN
            -- Check required fields
            IF NOT (assignee ? 'id' AND assignee ? 'status') THEN
                RETURN FALSE;
            END IF;
            
            -- Check status values (removed in_progress)
            IF assignee ->> 'status' NOT IN ('pending', 'completed', 'cancelled') THEN
                RETURN FALSE;
            END IF;
        END;
    END LOOP;
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."validate_assignees_jsonb"("assignees" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_migration_integrity"() RETURNS TABLE("validation_name" "text", "expected_count" bigint, "actual_count" bigint, "status" "text", "details" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH validations AS (
    -- Check student section assignments
    SELECT 
      'student_sections' as validation_name,
      (SELECT COUNT(*) FROM backup_section_member WHERE role = 'student') as expected,
      (SELECT SUM(jsonb_array_length(meta->'section')) FROM resource WHERE type = 'student' AND meta ? 'section') as actual,
      'Student section assignments' as details
    
    UNION ALL
    
    -- Check teacher section assignments  
    SELECT
      'teacher_sections',
      (SELECT COUNT(*) FROM backup_section_member WHERE role = 'teacher'),
      (SELECT SUM(jsonb_array_length(meta->'section')) FROM resource WHERE type = 'teacher' AND meta ? 'section'),
      'Teacher section assignments'
      
    UNION ALL
    
    -- Check meeting participants
    SELECT
      'meeting_participants',
      (SELECT COUNT(*) FROM backup_meeting_allocation),
      (SELECT SUM(jsonb_array_length(meta->'participants')) FROM meeting WHERE meta ? 'participants'),
      'Meeting participant assignments'
      
    UNION ALL
    
    -- Check section grade migration
    SELECT
      'section_grades',
      (SELECT COUNT(*) FROM backup_section WHERE grade IS NOT NULL),
      (SELECT COUNT(*) FROM section WHERE meta->>'grade' IS NOT NULL),
      'Section grade migrations'
  )
  SELECT 
    v.validation_name,
    v.expected,
    v.actual,
    CASE 
      WHEN v.expected = v.actual THEN 'PASS'
      WHEN abs(v.expected - v.actual) <= (v.expected * 0.05) THEN 'WARNING' -- 5% tolerance
      ELSE 'FAIL'
    END as status,
    v.details
  FROM validations v;
END;
$$;


ALTER FUNCTION "public"."validate_migration_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_kg_version_integrity"("p_student_id" "text") RETURNS TABLE("total_versions" integer, "max_version" integer, "min_version" integer, "versions_contiguous" boolean, "min_created_at" timestamp with time zone, "max_created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_total INTEGER; v_max INTEGER; v_min INTEGER;
  v_min_ts TIMESTAMPTZ; v_max_ts TIMESTAMPTZ; v_contiguous BOOLEAN;
  v_caller_id UUID; v_caller_role TEXT;
BEGIN
  IF p_student_id IS NULL OR p_student_id = '' THEN
    RAISE EXCEPTION 'student_id is required' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT p.role INTO v_caller_role FROM profiles p WHERE p.id = v_caller_id;
  IF v_caller_role IS NULL OR v_caller_role NOT IN ('teacher', 'admin') THEN
    RAISE EXCEPTION 'Only teachers and admins can verify version integrity' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT COUNT(*)::INTEGER, COALESCE(MAX(skv.version), 0), COALESCE(MIN(skv.version), 0), MIN(skv.created_at), MAX(skv.created_at)
  INTO v_total, v_max, v_min, v_min_ts, v_max_ts FROM student_kg_versions skv WHERE skv.student_id = p_student_id;
  v_contiguous := (v_total = 0) OR (v_min = 1 AND v_max = v_total);
  RETURN QUERY SELECT v_total, v_max, v_min, v_contiguous, v_min_ts, v_max_ts;
END;
$$;


ALTER FUNCTION "public"."verify_kg_version_integrity"("p_student_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."verify_kg_version_integrity"("p_student_id" "text") IS 'Verifies KG version integrity: contiguous numbering, no gaps or deletions.';



CREATE OR REPLACE FUNCTION "public"."warn_signature_purge"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_days int := public.signature_purge_days();
  v_req  record;
  v_n    int := 0;
begin
  for v_req in
    select r.id, r.title, r.status, r.requester_resource_id
    from public.signature_request r
    where r.purged_at is null
      and r.status in ('pending', 'completed')
      and not (r.meta ? 'drive')
      and not (r.meta ? 'purge_warned_at')
      and r.requester_resource_id is not null
      and (
        (r.status = 'completed'
         and coalesce(r.decided_at, r.created_at) < now() - make_interval(days => greatest(1, v_days - 3)))
        or (r.status = 'pending'
            and now() > r.due_at - least(interval '3 days', (r.due_at - r.created_at) / 2))
      )
  loop
    insert into public.notification_events (type, title, message, resource_id, meta)
    values (
      'signature_request',
      '서명 문서가 곧 정리됩니다',
      case when v_req.status = 'pending'
           then format('«%s» 요청의 서명 마감이 다가옵니다. 마감까지 서명이 끝나지 않으면 문서가 정리됩니다(마감일은 요청 화면에서 늦출 수 있습니다).', v_req.title)
           else format('«%s» 문서를 곧 서버에서 지웁니다. Google Drive로 옮기지 않으면 다시 받을 수 없습니다.', v_req.title)
      end,
      v_req.requester_resource_id,
      jsonb_build_object('signature_request_id', v_req.id, 'link', '/signatures')
    );
    update public.signature_request
       set meta = coalesce(meta,'{}'::jsonb) || jsonb_build_object('purge_warned_at', now())
     where id = v_req.id;
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."warn_signature_purge"() OWNER TO "postgres";


