CREATE OR REPLACE FUNCTION "public"."world_news_interest_suggestions"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  uid uuid := auth.uid();
  code text;
begin
  if uid is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  select split_part(p.email, '@', 1) into code from public.profiles p where p.id = uid and p.role = 'student';
  if code is null then return jsonb_build_object('departments', '[]'::jsonb, 'interests', '[]'::jsonb); end if;
  return jsonb_build_object(
    'departments', coalesce((
      select jsonb_agg(d order by first_order) from (
        select department as d, min(sort_order) as first_order
          from public.admission_wishlist
         where student_code = code and coalesce(department, '') <> ''
         group by department order by min(sort_order) limit 10) w), '[]'::jsonb),
    'interests', coalesce((
      select jsonb_agg(distinct e.label)
        from public.student_kg_entities e
       where e.student_id = code and e.type = 'Interest'
         and e.kg_version_id = (
           select e2.kg_version_id from public.student_kg_entities e2
             join public.student_kg_versions v on v.id = e2.kg_version_id
            where e2.student_id = code and e2.type = 'Interest'
            order by v.created_at desc limit 1)), '[]'::jsonb)
  );
end $$;


