CREATE OR REPLACE FUNCTION "push_private"."on_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c push_private.config;
begin
  if new.type = 'coolmessenger' or new.resource_id is null then return new; end if;
  if not exists (
    select 1 from public.push_subscriptions s
     where s.user_id in (select push_private.users_of_resource(new.resource_id))
  ) then return new; end if;
  select * into c from push_private.config where singleton;
  if c.url is null then return new; end if;
  -- 비동기(큐) — 알림 INSERT 를 늦추지 않는다. 실패해도 알림 행은 남는다(예외를 삼킨다).
  begin
    perform net.http_post(
      url := c.url,
      body := jsonb_build_object('notification_id', new.id),
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', c.secret),
      timeout_milliseconds := 10000
    );
  exception when others then
    raise warning 'push wake failed: %', sqlerrm;
  end;
  return new;
end $$;


