CREATE OR REPLACE FUNCTION "ranch_private"."in_class"("p_user" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  at_ timestamp := coalesce(nullif(current_setting('ranch.test_now', true), '')::timestamptz, now()) at time zone 'Asia/Seoul';
  code text; year_ int; sem int; term jsonb; p int;
begin
  if not exists (select 1 from public.profiles where id = p_user and role = 'student') then return false; end if;
  select split_part(email, '@', 1) into code from public.profiles where id = p_user;
  p := case
    when at_::time >= '09:00' and at_::time < '09:50' then 1 when at_::time >= '10:00' and at_::time < '10:50' then 2
    when at_::time >= '11:00' and at_::time < '11:50' then 3 when at_::time >= '12:50' and at_::time < '13:40' then 4
    when at_::time >= '13:50' and at_::time < '14:40' then 5 when at_::time >= '14:50' and at_::time < '15:40' then 6
    when at_::time >= '15:50' and at_::time < '16:40' then 7 end;
  if p is null or extract(isodow from at_) > 5 then return false; end if;
  select setting_value into term from public.system_settings where setting_key = 'academic_term' limit 1;
  year_ := nullif(term->>'year', '')::int; sem := nullif(term->>'semester', '')::int;
  if year_ is null or sem not in (1, 2) then
    select t.academic_year, t.semester into year_, sem from public.get_latest_timetable_term() t limit 1;
  end if;
  return exists (select 1 from public.student_timetable s join public.resource r on r.id = s.resource_id
    where r.type = 'student' and r.meta->>'id' = code and s.academic_year = year_ and s.semester = sem
      and s.day_of_week = extract(isodow from at_)::int and s.period = p);
end $$;


ALTER FUNCTION "ranch_private"."in_class"("p_user" "uuid") OWNER TO "postgres";


