CREATE OR REPLACE FUNCTION "school_life_private"."current_context"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  actor_id uuid := auth.uid();
  actor_role text;
  actor_email text;
  classes jsonb := '[]'::jsonb;
  year_number integer := extract(year from (now() at time zone 'Asia/Seoul') - interval '2 months');
begin
  if actor_id is null then return null; end if;
  select p.role, u.email into actor_role, actor_email
  from public.profiles p join auth.users u on u.id = p.id where p.id = actor_id;
  if actor_role = 'student' then
    select coalesce(jsonb_agg(jsonb_build_object('grade', s.grade, 'class_num', s.class_num)), '[]'::jsonb)
    into classes from public.student_basic_info s
    where s.id = split_part(actor_email, '@', 1) and s.grade between 1 and 3 and s.class_num > 0;
  elsif actor_role in ('teacher', 'admin') then
    select coalesce(jsonb_agg(jsonb_build_object('grade', x.grade, 'class_num', x.class_num)), '[]'::jsonb)
    into classes from (
      select distinct (m.parts)[1]::integer as grade, (m.parts)[2]::integer as class_num
      from public.resource r
      join public.resource_tag_assignments a on a.resource_id = r.id
      join public.resource_tags t on t.id = a.tag_id
      cross join lateral regexp_match(btrim(t.name), '^([1-3])학년[[:space:]]*([0-9]{1,2})반$') as m(parts)
      where r.type = 'teacher' and (m.parts)[2]::integer > 0
        and (lower(r.meta->>'email') = lower(actor_email)
          or exists (select 1 from school_life_private.legacy_teacher_identity l where l.user_id = actor_id and l.resource_id = r.id))
    ) x;
  end if;
  return jsonb_build_object('user_id', actor_id, 'role', actor_role, 'academic_year', year_number,
    'can_create', coalesce(actor_role in ('student', 'teacher', 'admin'), false), 'classes', classes);
end;
$_$;


ALTER FUNCTION "school_life_private"."current_context"() OWNER TO "postgres";


