CREATE OR REPLACE FUNCTION "seaton_private"."facts"("p_start" "date", "p_end" "date", "p_grade" integer, "p_room" "uuid", "p_today" "date", "p_past_closing" boolean) RETURNS TABLE("id" "uuid", "student_id" "uuid", "room_id" "uuid", "room_name" "text", "d" "date", "period_id" integer, "status" "text", "attended" boolean, "absent" boolean, "day_n" integer, "is_morning" boolean, "has_feedback" boolean, "checker_name" "text", "name" "text", "grade" integer, "class" integer, "number" integer, "sid" "text", "is_student" boolean, "is_active" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "work_mem" TO '16MB'
    AS $_$
declare
  v_filters text := '';
begin
  if p_grade is not null then v_filters := v_filters || ' and i.grade = $3'; end if;
  if p_room is not null then v_filters := v_filters || ' and b.room_id = $4'; end if;

  return query execute $q$
    with base as (
      select sr.id, sr.student_id, sr.room_id, sr.reservation_date as d, sr.period_id,
             coalesce(sr.is_attended, false) as att, sr.attendance_status, sr.checked_by,
             (sr.feedback_rating is not null) as has_feedback,
             count(*) over (partition by sr.student_id, sr.reservation_date)::int as day_n
      from public.seat_reservations sr
      where sr.reservation_date between $1 and $2
    ),
    who as (
      select distinct b.student_id from base b
    ),
    i as (
      select w.student_id,
             coalesce(nullif(p.name, ''), r.name) as name,
             case when r.meta->>'grade' ~ '^[0-9]+$' then (r.meta->>'grade')::int end as grade,
             case when r.meta->>'class' ~ '^[0-9]+$' then (r.meta->>'class')::int end as class,
             case when r.meta->>'number' ~ '^[0-9]+$' then (r.meta->>'number')::int end as number,
             coalesce(r.meta->>'id', split_part(p.email, '@', 1)) as sid,
             (p.role = 'student') as is_student,
             coalesce(r.status = 'active', true) as is_active
      from who w
      left join public.profiles p on p.id = w.student_id
      left join lateral (
        select res.name, res.meta, res.status
        from public.resource res
        where res.type = 'student' and res.meta->>'id' = split_part(p.email, '@', 1)
        order by (res.status = 'active') desc, res.updated_at desc nulls last
        limit 1
      ) r on true
    )
    select b.id, b.student_id, b.room_id, rm.name, b.d, b.period_id,
           case
             when b.att then case when b.attendance_status in ('excused', 'supplement') then b.attendance_status else 'attended' end
             when b.d < $5 or (b.d = $5 and $6) then 'absent'
             else 'pending'
           end,
           b.att,
           (not b.att and (b.d < $5 or (b.d = $5 and $6))),
           b.day_n,
           coalesce(rm.name like '%아침%', false),
           b.has_feedback,
           c.name,
           i.name, i.grade, i.class, i.number, i.sid, coalesce(i.is_student, false), i.is_active
    from base b
    join i on i.student_id = b.student_id
    left join public.study_rooms rm on rm.id = b.room_id
    left join public.profiles c on c.id = b.checked_by
    where true
  $q$ || v_filters
  using p_start, p_end, p_grade, p_room, p_today, p_past_closing;
end $_$;


ALTER FUNCTION "seaton_private"."facts"("p_start" "date", "p_end" "date", "p_grade" integer, "p_room" "uuid", "p_today" "date", "p_past_closing" boolean) OWNER TO "postgres";


