CREATE OR REPLACE FUNCTION "isekai3d_private"."achievement_progress"("u" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with pd as (select count(*)::integer days, coalesce(sum(coins), 0)::integer coins from public.isekai3d_play_day where user_id = u),
  sv as (
    select coalesce(max(case when jsonb_typeof(summary->'day') = 'number' then (summary->>'day')::numeric end), 0) d,
           coalesce(max(case when jsonb_typeof(summary->'money') = 'number' then (summary->>'money')::numeric end), 0) m,
           coalesce(max(case when jsonb_typeof(summary->'people') = 'array' then jsonb_array_length(summary->'people') end), 0) p
    from public.isekai3d_saves where user_id = u),
  qa as (select count(*)::integer n, count(distinct career_id)::integer careers, count(*) filter (where kind = 'life')::integer life
         from public.isekai3d_questions where user_id = u and answered_at is not null),
  ep as (select count(*) filter (where status = 'done')::integer done from public.isekai3d_episodes where user_id = u),
  sc as (select count(*)::integer n from public.isekai3d_episode_scenes where user_id = u and answered_at is not null),
  -- 근무 카드에서 고른 방식(서버 기록 · 섞인 번호를 되돌려 읽는다)
  ap as (
    select count(*) filter (where a = 'together')::integer together, count(*) filter (where a = 'self')::integer self_,
           count(*) filter (where a = 'safe')::integer safe
    from (select q.card->'choices'->isekai3d_private.card_choice_stored(q.id::text, jsonb_array_length(q.card->'choices'), q.answer_choice)->>'approach' a
          from public.isekai3d_questions q
          where q.user_id = u and q.kind = 'career' and q.answered_at is not null and q.answer_choice is not null
            and jsonb_typeof(q.card->'choices') = 'array') x),
  saves as (select s.slot, s.state from public.isekai3d_saves s where s.user_id = u and jsonb_typeof(s.state) = 'object'),
  dwellers as (
    select v.slot, x.n, x.dweller from saves v
    cross join lateral jsonb_array_elements(case when jsonb_typeof(v.state->'dwellers') = 'array' then v.state->'dwellers' else '[]'::jsonb end) with ordinality x(dweller, n)
    where jsonb_typeof(x.dweller) = 'object'),
  jb as (
    select coalesce(max(isekai3d_private.jnum(dweller->'job'->'level')) filter (where dweller->'job'->>'careerId' is not null), -1) lvl,
           count(*) filter (where jsonb_typeof(dweller->'job') = 'object' and dweller->'job'->>'careerId' is not null)::integer jobs
    from dwellers),
  wd as (
    select coalesce(max(isekai3d_private.jnum(w.value)), 0) days from dwellers
    cross join lateral jsonb_each(case when jsonb_typeof(dweller->'workDays') = 'object' then dweller->'workDays' else '{}'::jsonb end) w),
  rel as (
    select coalesce(max(n), 0)::integer friends from (
      select count(*) n from saves v
      cross join lateral jsonb_each(case when jsonb_typeof(v.state->'relationships') = 'object' then v.state->'relationships' else '{}'::jsonb end) r
      where r.value->>'stage' in ('friend', 'goodFriend') group by v.slot) z),
  sk as (
    select s.slot, s.n, k.key, floor(isekai3d_private.jnum(k.value)) lv from dwellers s
    cross join lateral jsonb_each(case when jsonb_typeof(s.dweller->'skills') = 'object' then s.dweller->'skills' else '{}'::jsonb end) k
    where k.key = any (array['cooking', 'logic', 'charisma', 'fitness', 'painting', 'guitar', 'writing', 'handiness', 'gardening', 'comedy',
      'piano', 'mixology', 'mischief', 'videoGaming', 'fishing', 'rocketScience', 'programming', 'violin', 'gourmet', 'photography',
      'dancing', 'singing', 'djMixing', 'empathy', 'leadership', 'medicine', 'science', 'law', 'business', 'language', 'driving',
      'selfControl', 'persistence', 'resilience', 'curiosity'])
      and isekai3d_private.jnum(k.value) is not null),
  skx as (
    select coalesce(max(lv), 0) top,
           coalesce(max(lv) filter (where key = 'charisma'), 0) comm, coalesce(max(lv) filter (where key = 'empathy'), 0) empathy,
           coalesce(max(lv) filter (where key = 'leadership'), 0) leader, coalesce(max(lv) filter (where key = 'logic'), 0) logic,
           coalesce(max(lv) filter (where key = 'programming'), 0) digital
    from sk),
  skp as (
    select coalesce(max(wide), 0)::integer wide, coalesce(max(mind), 0)::integer mind from (
      select count(*) filter (where lv >= 3) wide,
             count(*) filter (where lv >= 3 and key in ('persistence', 'resilience', 'selfControl', 'curiosity')) mind
      from sk group by slot, n) z),
  -- 열망: 지금 열망 + 바꾸기 전 열망(aspirationLog, 지금 것도 같은 id 로 들어 있을 수 있어 id 로 겹침 제거)
  ae as (
    select slot, n, e.key id, e.value v from dwellers
    cross join lateral jsonb_each(case when jsonb_typeof(dweller->'aspirationLog') = 'object' then dweller->'aspirationLog' else '{}'::jsonb end) e
    union all
    select slot, n, dweller->'aspiration'->>'id', dweller->'aspiration' from dwellers
    where jsonb_typeof(dweller->'aspiration') = 'object' and dweller->'aspiration'->>'id' is not null
      and not coalesce(case when jsonb_typeof(dweller->'aspirationLog') = 'object' then dweller->'aspirationLog' ? (dweller->'aspiration'->>'id') end, false)),
  asx as (
    select (select count(*) from dwellers where jsonb_typeof(dweller->'aspiration') = 'object')::integer picked,
           (select count(distinct id) from ae)::integer tried,
           (select coalesce(max(st), 0) from (select sum(coalesce(isekai3d_private.jnum(v->'milestone'), 0)) st from ae group by slot) z)::integer steps),
  done as (
    select array_agg(distinct t) traits from dwellers
    cross join lateral jsonb_array_elements_text(case when jsonb_typeof(dweller->'traits') = 'array' then dweller->'traits' else '[]'::jsonb end) t
    where t in ('aspKnowSelf', 'aspSharer', 'aspCraftsman', 'aspLastingBonds', 'aspKindHands', 'aspSteady', 'aspCalmNature', 'aspFulfilled'))
  select jsonb_build_object(
    'first_day', least(1, pd.days), 'days_7', least(7, pd.days), 'days_30', least(30, pd.days),
    'streak_5', least(5, isekai3d_private.best_streak(u)), 'coins_10', least(10, pd.coins),
    'game_day_30', least(30, floor(sv.d))::integer, 'game_day_100', least(100, floor(sv.d))::integer,
    'money_10k', least(10000, floor(sv.m))::integer, 'money_50k', least(50000, floor(sv.m))::integer, 'family_3', least(3, sv.p),
    'answer_1', least(1, qa.n), 'answer_10', least(10, qa.n), 'answer_30', least(30, qa.n),
    'careers_3', least(3, qa.careers), 'life_5', least(5, qa.life),
    'episode_1', least(1, ep.done), 'episode_5', least(5, ep.done), 'scenes_20', least(20, sc.n),
    -- 사회생활
    'job_first', least(1, jb.jobs), 'promo_3', greatest(0, least(3, floor(jb.lvl)))::integer, 'promo_7', greatest(0, least(7, floor(jb.lvl)))::integer,
    'workdays_30', least(30, floor(wd.days))::integer, 'friends_5', least(5, rel.friends),
    'team_10', least(10, ap.together), 'self_10', least(10, ap.self_), 'safe_5', least(5, ap.safe),
    'balance_3', least(3, ap.together, ap.self_, ap.safe),
    -- 역량
    'skill_any_5', least(5, skx.top)::integer, 'skill_any_10', least(10, skx.top)::integer, 'skill_wide_5', least(5, skp.wide),
    'skill_comm', least(5, skx.comm)::integer, 'skill_empathy', least(5, skx.empathy)::integer, 'skill_leader', least(5, skx.leader)::integer,
    'skill_logic', least(5, skx.logic)::integer, 'skill_digital', least(5, skx.digital)::integer, 'skill_mind', least(4, skp.mind),
    -- 열망
    'asp_pick', least(1, asx.picked), 'asp_try_3', least(3, asx.tried), 'asp_step_5', least(5, asx.steps),
    'asp_done_1', least(1, coalesce(cardinality(done.traits), 0)), 'asp_areas_3', least(3, coalesce(cardinality(done.traits), 0)),
    'asp_self', case when 'aspKnowSelf' = any (coalesce(done.traits, '{}')) then 1 else 0 end,
    'asp_work', case when 'aspFulfilled' = any (coalesce(done.traits, '{}')) then 1 else 0 end,
    'asp_bond', case when coalesce(done.traits, '{}') && array['aspLastingBonds', 'aspKindHands'] then 1 else 0 end)
  from pd, sv, qa, ep, sc, ap, jb, wd, rel, skx, skp, asx, done
$$;


