CREATE OR REPLACE FUNCTION "isekai3d_private"."best_streak"("u" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(max(n), 0)::integer from (
    select count(*) n from (select day, day - (row_number() over (order by day))::integer g from public.isekai3d_play_day where user_id = u) d group by g
  ) s
$$;


