CREATE OR REPLACE FUNCTION "isekai3d_private"."card_choice_stored"("p_id" "text", "p_n" integer, "p_shown" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  seed bigint := 7;
  ch text;
  idx integer[];
  i integer;
  j integer;
  t integer;
begin
  if p_shown is null or p_n is null or p_shown < 0 or p_shown >= p_n then return null; end if;
  foreach ch in array regexp_split_to_array(p_id, '') loop
    seed := isekai3d_private.i32(seed * 31 + ascii(ch));
  end loop;
  idx := array(select generate_series(0, p_n - 1));
  for i in reverse p_n - 1 .. 1 loop
    seed := isekai3d_private.i32(seed * 1103515245 + 12345);
    j := abs(seed) % (i + 1);
    t := idx[i + 1]; idx[i + 1] := idx[j + 1]; idx[j + 1] := t;
  end loop;
  return idx[p_shown + 1];
end $$;


