CREATE OR REPLACE FUNCTION "tama_private"."achievement_progress"("p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with a as (select kind, stage, branch, note, species from public.tama_album where owner = p_user),
  pets as (
    select tama_private.mode_of(p.state) as mode, p.state->>'stage' as stage,
           case when p.state->>'stage' in ('baby', 'child', 'teen', 'adult')
                 and jsonb_typeof(p.state->'tick') = 'number' and jsonb_typeof(p.state->'hatchTick') = 'number'
                then greatest(0, ((case when jsonb_typeof(p.state->'deadTick') = 'number' then (p.state->>'deadTick')::bigint
                                        else (p.state->>'tick')::bigint end) - (p.state->>'hatchTick')::bigint) / 288)
                else 0 end as days
    from public.tama_pet p where p.owner = p_user
  ),
  dex as (
    select 'baby' as k from a where kind = 'hatch' and species is null
    union select stage from a where kind = 'evolve' and stage in ('child', 'teen') and species is null
    union select case when branch = 'basic' then 'adult' else branch end from a
      where kind = 'branch' and branch in ('basic', 'planner', 'thinker', 'focus', 'heart') and species is null
  ),
  deaths as (select distinct coalesce(note, 'sick') as id from a where kind = 'death' and coalesce(note, 'sick') = any (tama_private.death_dex()))
  select jsonb_build_object(
    'first_egg', (select count(*) from a where kind = 'adopt'),
    'first_hatch', (select count(*) from a where kind = 'hatch'),
    'grown', least(1, (select count(*) from a where kind = 'evolve' and stage = 'adult') + (select count(*) from pets where stage = 'adult')),
    'week', least(7, coalesce((select max(days) from pets), 0)),
    'month', least(30, coalesce((select max(days) from pets), 0)),
    'healer', least(10, (select count(*) from a where kind = 'healed')),
    'branches', (select count(distinct branch) from a where kind = 'branch' and branch in ('planner', 'thinker', 'focus', 'heart')),
    'dex', (select count(*) from dex),
    'character', least(1, (select count(*) from a where kind = 'character')),
    'first_star', least(1, (select count(*) from a where kind = 'death')),
    'sunfish_adult', case when exists (select 1 from pets where mode = 'hard' and stage = 'adult') then 1 else 0 end,
    'dex_death_10', least(10, (select count(*) from deaths)),
    'dex_death_30', least(30, (select count(*) from deaths)),
    'dex_death_all', (select count(*) from deaths),
    '_deaths', coalesce((select jsonb_agg(id) from deaths), '[]'::jsonb)
  )
$$;


ALTER FUNCTION "tama_private"."achievement_progress"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."achievement_rule"("p_id" "text", OUT "goal" integer, OUT "reward" integer) RETURNS "record"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select r.goal, economy_private.num('tama.achievement.' || r.id) from (values
    ('first_egg', 1), ('first_hatch', 1), ('grown', 1), ('week', 7), ('month', 30), ('healer', 10),
    ('branches', 4), ('dex', 8), ('character', 1), ('first_star', 1), ('sunfish_adult', 1),
    ('dex_death_10', 10), ('dex_death_30', 30), ('dex_death_all', 77)
  ) as r(id, goal) where r.id = p_id
$$;


