CREATE OR REPLACE FUNCTION "tama_private"."board_pets"() RETURNS TABLE("pet_id" "uuid", "owner" "uuid", "skin_order_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select l.pet_id, l.owner, coalesce(p.skin_order_id, mm.skin_order_id)
  from unnest(array['easy', 'normal', 'hard']) m, tama_private.longest_pets(20, m) l
  left join public.tama_pet p on p.id = l.pet_id
  left join public.tama_pet_memorial mm on mm.id = l.memorial_id
$$;


ALTER FUNCTION "tama_private"."board_pets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."can_read_character"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select tama_private.is_admin() or exists (
    select 1 from public.tama_character_order o
    where o.image_path = p_name and o.status = 'delivered'
      and (o.owner = auth.uid()
           or (exists (select 1 from public.tama_pet p where p.owner = o.owner and p.is_primary and p.skin_order_id = o.id)
               and academy_private.are_friends(auth.uid(), o.owner))
           -- 오래 함께한 펫 — 세 판 20위 안의 줄이 입은 캐릭터
           or (auth.uid() is not null and exists (
                 select 1 from tama_private.board_pets() b where b.skin_order_id = o.id))))
$$;


ALTER FUNCTION "tama_private"."can_read_character"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."can_read_decor"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select tama_private.is_admin() or exists (
    select 1 from public.tama_item i
    where i.image_path = p_name and i.custom_owner is not null
      and (i.custom_owner = auth.uid() or academy_private.are_friends(auth.uid(), i.custom_owner)
           -- 오래 함께한 펫 — 세 판 20위 안의 줄 주인이 지금 방에 놓은 것
           or (auth.uid() is not null
               and exists (select 1 from public.tama_equip e where e.owner = i.custom_owner and e.item_id = i.id)
               and exists (select 1 from tama_private.board_pets() b where b.owner = i.custom_owner))))
$$;


