CREATE OR REPLACE FUNCTION "tama_private"."cared_ticks"("p_state" "jsonb") RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when jsonb_typeof(p_state->'caredTicks') = 'number' then greatest(0, (p_state->>'caredTicks')::bigint)
    when p_state->>'stage' in ('baby', 'child', 'teen', 'adult') and jsonb_typeof(p_state->'tick') = 'number' and jsonb_typeof(p_state->'hatchTick') = 'number'
      then greatest(0, (case when jsonb_typeof(p_state->'deadTick') = 'number' then (p_state->>'deadTick')::bigint
                             else (p_state->>'tick')::bigint end) - (p_state->>'hatchTick')::bigint)
    else 0 end
$$;


ALTER FUNCTION "tama_private"."cared_ticks"("p_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."check_new_species"("p_user" "uuid", "p_state" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s text := coalesce(p_state->>'species', 'star');
begin
  if s not in ('star', 'signal', 'tide', 'moon', 'sprout') then raise exception '알 정보가 올바르지 않아요.'; end if;
  if s = 'signal' then raise exception '전파 가족의 알은 친구와 통신해야 받을 수 있어요.'; end if;
  if not tama_private.species_unlocked(p_user, s) then raise exception '아직 만날 수 없는 알이에요.'; end if;
end $$;


