CREATE OR REPLACE FUNCTION "tama_private"."decor_design_ok"("p_slot" "text", "p_design" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case when p_slot = 'device' then
      jsonb_typeof(p_design) = 'object'
      and coalesce(p_design->>'model', '') ~ '^[a-z][a-z0-9_]{1,30}$'
      and (select count(*) from jsonb_object_keys(p_design)) = 1
    when p_slot = 'shell' and jsonb_typeof(p_design) = 'object' and p_design ? 'theme' then
      coalesce(p_design->>'theme', '') ~ '^shell_[a-z0-9_]{1,25}$'
      and (select count(*) from jsonb_object_keys(p_design)) = 1
    else
      jsonb_typeof(p_design) = 'object'
      and coalesce(p_design->>'main', '') ~ '^#[0-9a-fA-F]{6}$'
      and coalesce(p_design->>'accent', '') ~ '^#[0-9a-fA-F]{6}$'
      and case p_slot
            when 'shell' then coalesce(p_design->>'pattern', '') in ('heart', 'star', 'dot', 'flower', 'diamond')
            when 'wallpaper' then coalesce(p_design->>'pattern', '') in ('stripes', 'checks', 'leaves', 'stars')
            when 'rug' then true
            else false end
      and (select count(*) from jsonb_object_keys(p_design)) <= 3
    end
$_$;


