CREATE OR REPLACE FUNCTION "tama_private"."dispatch_calls"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p record; rid uuid; n integer := 0;
  msg constant jsonb := jsonb_build_object(
    'hungry', '배고파요! 밥을 주세요.', 'unhappy', '심심해요… 놀아 주세요.',
    'sick', '아파요. 약이 필요해요.', 'lights', '졸려요. 불을 꺼 주세요.');
begin
  for p in
    update public.tama_pet t set next_call_at = null, last_called_at = now()
     where t.next_call_at <= now() and t.is_primary
    returning t.id, t.owner, t.name, t.next_call_reason as reason
  loop
    if push_private.is_quiet(now()) then continue; end if;
    if not exists (select 1 from public.push_subscriptions s where s.user_id = p.owner) then continue; end if;
    rid := push_private.resource_of_user(p.owner);
    if rid is null then continue; end if;
    insert into public.notification_events(resource_id, type, title, message, priority, meta)
      values (rid, 'tama_call', p.name || '이(가) 불러요', coalesce(msg->>p.reason, '돌봐 주세요.'), 'low',
              jsonb_build_object('pet_id', p.id, 'reason', p.reason));
    n := n + 1;
  end loop;
  delete from public.push_delivery_log where created_at < now() - interval '30 days';
  return n;
end $$;


ALTER FUNCTION "tama_private"."dispatch_calls"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."dispatch_focus_invites"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  local_now timestamp := now() at time zone 'Asia/Seoul';
  today date := local_now::date;
  nowt time := local_now::time;
  c record;
  rid uuid;
  n integer := 0;
begin
  if push_private.is_quiet(now()) then return 0; end if;
  for c in
    with blocks as (
      select r.student_id as owner, 'study:' || r.id::text as source_key, 'study'::text as kind,
             coalesce(s.name, '자습실') as title,
             (p.value->>'start_time')::time as st, (p.value->>'end_time')::time as et, null::uuid as task_id
        from public.seat_reservations r
        join public.study_rooms s on s.id = r.room_id
        cross join lateral (
          select value from jsonb_array_elements(case when jsonb_typeof(s.operating_periods) = 'array' then s.operating_periods else '[]'::jsonb end)
           where value->>'id' = r.period_id::text limit 1) p
       where r.reservation_date = today
         and p.value->>'start_time' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
         and p.value->>'end_time' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      union all
      select t.user_id, 'plan:' || t.id::text || ':' || t.task_date::text || ':' || to_char(t.start_time, 'HH24:MI'), 'plan',
             t.title, t.start_time, t.end_time, t.id
        from public.academy_tasks t
       where t.task_date = today and not t.completed and t.start_time is not null and t.end_time is not null
    )
    select distinct on (b.owner) b.*, pet.name as pet_name
      from blocks b
      join public.tama_pet pet on pet.owner = b.owner and pet.is_primary
     where b.st <= nowt and b.st > nowt - interval '10 minutes'
       and b.et > b.st
       and b.et - nowt >= interval '15 minutes'
       and exists (select 1 from public.push_subscriptions s where s.user_id = b.owner)
       and not exists (select 1 from public.tama_focus f
                        where f.owner = b.owner and f.ended_at is null
                          and f.started_at + make_interval(secs => f.planned_seconds) + interval '15 minutes' > now())
       and not exists (select 1 from public.tama_focus_invite_sent x where x.owner = b.owner and x.source_key = b.source_key)
     order by b.owner, (b.kind = 'plan') desc, b.st desc
  loop
    insert into public.tama_focus_invite_sent(owner, source_key) values (c.owner, c.source_key) on conflict do nothing;
    if not found then continue; end if;
    rid := push_private.resource_of_user(c.owner);
    if rid is null then continue; end if;
    insert into public.notification_events(resource_id, type, title, message, priority, meta)
    values (rid, 'tama_focus_invite', c.pet_name || '이(가) 같이 집중하재요',
            case when c.kind = 'study'
              then '자습 시간이에요 — ' || c.title || ' ' || to_char(c.st, 'HH24:MI') || '~' || to_char(c.et, 'HH24:MI') || '. 함께 집중할까요?'
              else '계획 «' || left(c.title, 40) || '» 시간이에요(' || to_char(c.st, 'HH24:MI') || '~' || to_char(c.et, 'HH24:MI') || '). 함께 집중할까요?'
            end,
            'low', jsonb_build_object('kind', c.kind, 'source_key', c.source_key, 'task_id', c.task_id));
    n := n + 1;
  end loop;
  delete from public.tama_focus_invite_sent where sent_at < now() - interval '7 days';
  return n;
end $_$;


ALTER FUNCTION "tama_private"."dispatch_focus_invites"() OWNER TO "postgres";


