CREATE OR REPLACE FUNCTION "tama_private"."gacha_pool"() RETURNS TABLE("id" "text", "rarity" "text", "sort" integer, "weight" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with live as (
    select coalesce((select array_agg(distinct x) from public.tama_event e, unnest(e.item_ids) x
                     where now() >= e.starts_at and now() < e.ends_at), '{}') as items,
           coalesce((select array_agg(distinct y) from public.tama_event e, unnest(e.pickup_ids) y
                     where now() >= e.starts_at and now() < e.ends_at), '{}') as pickups
  ), pool as (
    select i.id, i.rarity, i.sort, case when i.id = any(l.pickups) then 2 else 1 end::numeric as mult
    from public.tama_item i, live l
    where i.active and i.custom_owner is null and (not i.event_only or i.id = any(l.items))
  )
  select p.id, p.rarity, p.sort,
         tama_private.rarity_weight(p.rarity) * p.mult / sum(p.mult) over (partition by p.rarity) as weight
  from pool p
$$;


ALTER FUNCTION "tama_private"."gacha_pool"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."gacha_pool_of"("p_machine" "text") RETURNS TABLE("id" "text", "rarity" "text", "sort" integer, "weight" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with m as (select * from tama_private.gacha_machine(p_machine)),
  live as (
    select coalesce((select array_agg(distinct x) from public.tama_event e, unnest(e.item_ids) x
                     where now() >= e.starts_at and now() < e.ends_at), '{}') as items,
           coalesce((select array_agg(distinct y) from public.tama_event e, unnest(e.pickup_ids) y
                     where now() >= e.starts_at and now() < e.ends_at), '{}') as pickups
  ), pool as (
    select i.id, i.rarity, i.sort, case when i.id = any(l.pickups) then 2 else 1 end::numeric as mult
    from public.tama_item i, live l, m
    where i.active and i.custom_owner is null and (not i.event_only or i.id = any(l.items))
      and (m.slots is null or i.slot = any(m.slots))
  )
  select p.id, p.rarity, p.sort,
         tama_private.rarity_weight(p.rarity) * p.mult / sum(p.mult) over (partition by p.rarity) as weight
  from pool p
$$;


ALTER FUNCTION "tama_private"."gacha_pool_of"("p_machine" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."grant_credit"("p_user" "uuid", "p_kind" "text", "p_source" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  today date := (now() at time zone 'Asia/Seoul')::date;
  rule record;
  taken integer;
  inserted integer;
  repay integer := 0;
begin
  select * into rule from tama_private.credit_rule(p_kind);
  if p_user is null or rule.amount is null or p_source is null then return 0; end if;
  if not exists (select 1 from public.tama_pet where owner = p_user and is_primary)
     or not exists (select 1 from public.profiles where id = p_user and role in ('student', 'teacher', 'admin')) then
    return 0;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('tama-credit:' || p_user::text, 0));
  select count(*) into taken from public.tama_credit_ledger where user_id = p_user and earned_on = today and kind = p_kind;
  if taken >= rule.daily_cap then return 0; end if;
  insert into public.tama_credit_ledger(user_id, earned_on, kind, source_id, amount)
    values (p_user, today, p_kind, left(p_source, 80), rule.amount)
    on conflict do nothing;
  get diagnostics inserted = row_count;
  if inserted = 0 then return 0; end if;
  -- 외상부터 갚는다: 갚은 만큼은 지갑에 들어가지 않는다
  select least(debt, rule.amount) into repay from public.tama_wallet where owner = p_user for update;
  repay := coalesce(repay, 0);
  if repay > 0 then update public.tama_wallet set debt = debt - repay where owner = p_user; end if;
  insert into public.academy_user_stats(user_id) values (p_user) on conflict (user_id) do nothing;
  update public.academy_user_stats set coins = coins + (rule.amount - repay), updated_at = now() where user_id = p_user;
  return rule.amount;
exception when others then
  raise warning 'tama credit skipped (% %): %', p_kind, p_source, sqlerrm;
  return 0;
end $$;


