CREATE OR REPLACE FUNCTION "tama_private"."keep_pet_memorial"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(old.state->'dead' = 'true'::jsonb, false)
     and not coalesce(new.state->'dead' = 'true'::jsonb, false)
     and old.state->>'stage' in ('baby', 'child', 'teen', 'adult')
     and jsonb_typeof(old.state->'hatchTick') = 'number'
     and jsonb_typeof(old.state->'deadTick') = 'number' then
    insert into public.tama_pet_memorial(owner, pet_id, name, mode, stage, branch, death_cause, ticks,
                                         skin_order_id, skin_item_id, born_at, died_at, care_count, risk_score, species)
    values (old.owner, old.id, old.name, tama_private.mode_of(old.state), old.state->>'stage',
            nullif(old.state->>'branch', ''), old.state->>'deathCause',
            case when jsonb_typeof(old.state->'caredTicks') = 'number' then greatest(0, (old.state->>'caredTicks')::bigint)
                 else greatest(0, (old.state->>'deadTick')::bigint - (old.state->>'hatchTick')::bigint) end,
            old.skin_order_id, old.skin_item_id,
            to_timestamp((old.state->>'hatchTick')::bigint * 300), to_timestamp((old.state->>'deadTick')::bigint * 300),
            case when jsonb_typeof(old.state->'careCount') = 'number' then (old.state->>'careCount')::integer end,
            case when jsonb_typeof(old.state->'riskScore') = 'number' then (old.state->>'riskScore')::numeric end,
            nullif(old.state->>'species', ''))
    on conflict (pet_id, died_at) do nothing;
  end if;
  return new;
end $$;


ALTER FUNCTION "tama_private"."keep_pet_memorial"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."keep_pet_mode"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  was text := tama_private.mode_of(old.state);
begin
  if tama_private.mode_of(new.state) = was then return new; end if;
  if coalesce(old.state->'dead' = 'true'::jsonb, false) and new.state->>'stage' = 'egg' then return new; end if;
  new.state := (new.state - 'mode' - 'mortal') || case when was = 'easy' then '{}'::jsonb else jsonb_build_object('mode', was) end;
  return new;
end $$;


ALTER FUNCTION "tama_private"."keep_pet_mode"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."keep_pet_species"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o text := old.state->>'species'; n text := new.state->>'species';
begin
  if coalesce(o, '') is distinct from coalesce(n, '') then
    if coalesce(old.state->'dead' = 'true'::jsonb, false) and new.state->>'stage' = 'egg' then
      return new;
    end if;
    new.state := case when o is null then new.state - 'species' else jsonb_set(new.state, '{species}', to_jsonb(o)) end;
  end if;
  return new;
end $$;


ALTER FUNCTION "tama_private"."keep_pet_species"() OWNER TO "postgres";


