CREATE OR REPLACE FUNCTION "tama_private"."longest_pets"("p_limit" integer, "p_mode" "text") RETURNS TABLE("pet_id" "uuid", "memorial_id" bigint, "owner" "uuid", "ticks" bigint, "rank" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select x.pet_id, x.memorial_id, x.owner, x.ticks,
         row_number() over (order by case when p_mode = 'hard' then x.score end desc nulls last, x.ticks desc, x.born asc)
  from (
    select p.id as pet_id, null::bigint as memorial_id, p.owner, p.created_at as born,
           case when jsonb_typeof(p.state->'caredTicks') = 'number' then greatest(0, (p.state->>'caredTicks')::bigint)
                else greatest(0, (case when jsonb_typeof(p.state->'deadTick') = 'number' then (p.state->>'deadTick')::bigint
                                       else (p.state->>'tick')::bigint end) - (p.state->>'hatchTick')::bigint) end as ticks,
           case when jsonb_typeof(p.state->'riskScore') = 'number' then (p.state->>'riskScore')::numeric else 0 end as score
    from public.tama_pet p
    join public.profiles pr on pr.id = p.owner and pr.role in ('student', 'teacher')
    where p.state->>'stage' in ('baby', 'child', 'teen', 'adult')
      and jsonb_typeof(p.state->'tick') = 'number' and jsonb_typeof(p.state->'hatchTick') = 'number'
      and (p_mode is null or tama_private.mode_of(p.state) = p_mode)
    union all
    select null::uuid, m.id, m.owner, m.born_at, m.ticks, coalesce(m.risk_score, 0)
    from public.tama_pet_memorial m
    join public.profiles pr on pr.id = m.owner and pr.role in ('student', 'teacher')
    where p_mode is null or m.mode = p_mode
  ) x
  order by case when p_mode = 'hard' then x.score end desc nulls last, x.ticks desc, x.born asc
  limit p_limit
$$;


ALTER FUNCTION "tama_private"."longest_pets"("p_limit" integer, "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tama_private"."memorial_species"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.species is null and new.pet_id is not null then
    select case when p.state->>'species' in ('signal', 'tide', 'moon', 'sprout') then p.state->>'species' end
      into new.species from public.tama_pet p where p.id = new.pet_id;
  end if;
  return new;
end $$;


