CREATE OR REPLACE FUNCTION "tama_private"."move_item"("p_from" "uuid", "p_to" "uuid", "p_item" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare have integer;
begin
  select count into have from public.tama_inventory where owner = p_from and item_id = p_item for update;
  if have is null or have < 1 then return false; end if;
  if have = 1 then
    delete from public.tama_inventory where owner = p_from and item_id = p_item;
    delete from public.tama_equip where owner = p_from and item_id = p_item;
    update public.tama_pet set skin_item_id = null where owner = p_from and skin_item_id = p_item;
  else
    update public.tama_inventory set count = count - 1 where owner = p_from and item_id = p_item;
  end if;
  insert into public.tama_inventory(owner, item_id) values (p_to, p_item)
    on conflict (owner, item_id) do update set count = public.tama_inventory.count + 1;
  return true;
end $$;


ALTER FUNCTION "tama_private"."move_item"("p_from" "uuid", "p_to" "uuid", "p_item" "text") OWNER TO "postgres";


