CREATE OR REPLACE FUNCTION "tama_private"."on_pet_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  ev jsonb;
  old_tick bigint;
  was_dead boolean;
begin
  insert into public.tama_care_day(owner, day) values (new.owner, (now() at time zone 'Asia/Seoul')::date) on conflict do nothing;
  if tg_op = 'INSERT' then
    insert into public.tama_album(owner, pet_id, pet_name, kind, stage, at) values (new.owner, new.id, new.name, 'adopt', 'egg', new.created_at);
    return null;
  end if;
  old_tick := coalesce((old.state->>'tick')::bigint, 0);
  was_dead := coalesce((old.state->>'dead')::boolean, false);
  for ev in select * from jsonb_array_elements(coalesce(new.state->'events', '[]'::jsonb)) loop
    if (ev->>'kind') in ('hatch', 'evolve', 'sick', 'healed', 'death')
       and ((ev->>'tick')::bigint > old_tick or ((ev->>'kind') = 'death' and not was_dead)) then
      insert into public.tama_album(owner, pet_id, pet_name, kind, stage, note, at)
        values (new.owner, new.id, new.name, ev->>'kind', ev->>'stage',
                case when ev->>'kind' = 'death' then ev->>'cause' end,
                to_timestamp((ev->>'tick')::bigint * 300));
    end if;
  end loop;
  if coalesce(old.state->>'branch', '') = '' and coalesce(new.state->>'branch', '') <> '' then
    insert into public.tama_album(owner, pet_id, pet_name, kind, stage, branch) values (new.owner, new.id, new.name, 'branch', 'adult', new.state->>'branch');
  end if;
  return null;
end $$;


ALTER FUNCTION "tama_private"."on_pet_write"() OWNER TO "postgres";


