CREATE OR REPLACE FUNCTION "tama_private"."species_unlocked"("p_user" "uuid", "p_species" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case p_species
    when 'star' then true
    when 'signal' then false  -- 통신으로 받은 알 표로만
    when 'tide' then tama_private.user_is_admin(p_user)
      or exists (select 1 from public.tama_pet p where p.owner = p_user and tama_private.mode_of(p.state) = 'hard' and p.state->>'stage' = 'adult')
      or exists (select 1 from public.tama_pet_memorial m where m.owner = p_user and m.mode = 'hard' and m.stage = 'adult')
    when 'moon' then tama_private.user_is_admin(p_user)
      or exists (select 1 from public.tama_pet p where p.owner = p_user and tama_private.cared_ticks(p.state) >= 30 * 288)
      or exists (select 1 from public.tama_pet_memorial m where m.owner = p_user and m.ticks >= 30 * 288)
    when 'sprout' then tama_private.user_is_admin(p_user)
      or (select count(distinct a.branch) from public.tama_album a
           where a.owner = p_user and a.kind = 'branch' and a.branch in ('planner', 'thinker', 'focus', 'heart')) = 4
    else false end
$$;


