CREATE OR REPLACE FUNCTION "tower_private"."achievement_progress"("u" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (
    select t.*, case when t.towers > 0 then tower_private.full_floors() else cardinality(t.floors) end as reach
    from public.tower_state t where t.owner = u
  ),
  rare as (select count(*) n from s, unnest(s.caught) k where k in (select r.key from tower_private.rare_table() r)),
  fish as (select count(*) n from s, unnest(s.caught) k
           where k in (select c.key from tower_private.catch_table() c
                       union select r.key from tower_private.rare_table() r
                       union select d.key from tower_private.deep_table() d)),
  vis as (select count(*) n from s, unnest(s.visitors) k where k in (select v.key from tower_private.visitor_table() v)),
  let as (select k from s, unnest(s.letters) k where k = any (tower_private.letter_keys()))
  select coalesce((select jsonb_build_object(
    'first_floor', least(1, s.reach),
    'clouds', least(7, s.reach),
    'first_tower', least(1, s.towers),
    'tower_3', least(3, s.towers),
    'tower_6', least(6, s.towers),
    'tower_8', least(8, s.towers),
    'focus_10h', least(10, s.focus_seconds / 3600),
    'focus_50h', least(50, s.focus_seconds / 3600),
    'focus_100h', least(100, s.focus_seconds / 3600),
    'sessions_50', least(50, s.sessions),
    'rare_4', least(4, (select n from rare)),
    'rare_all', (select n from rare),
    'fish_all', (select n from fish),
    'visitors_all', (select n from vis),
    'letters_story', (select count(*) from let where k like 'story-%'),
    'letters_love', (select count(*) from let where k like 'love-%'),
    'letters_prank', (select count(*) from let where k like 'prank-%'),
    'letters_far', (select count(*) from let where k like 'far-%'),
    'letters_all', (select count(*) from let)
  ) from s), '{}'::jsonb)
$$;


ALTER FUNCTION "tower_private"."achievement_progress"("u" "uuid") OWNER TO "postgres";


