CREATE OR REPLACE FUNCTION "tower_private"."close_focus"("p_id" "uuid", "p_give_up" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  row public.tower_focus;
  due timestamptz;
  result text;
  rolls integer;
  elapsed integer;
  keys text[] := '{}';
  d record;
  i integer;
  seed text;
  at timestamptz;
  got text[];
  tw integer;
  bonus integer := 0;
begin
  select * into row from public.tower_focus where id = p_id for update;
  if row.ended_at is not null then
    return jsonb_build_object('outcome', row.outcome, 'catches', row.catches, 'already', true);
  end if;
  due := row.started_at + make_interval(secs => row.planned_seconds);
  elapsed := least(row.planned_seconds, greatest(0, floor(extract(epoch from now() - row.started_at))::integer));
  if now() >= due then
    result := 'completed';
    rolls := row.planned_seconds / 300 + 1;
    -- 완주 별 조각 = 15분마다 하나(반올림 — 15분 1 · 25분 2 · 45분 3 · 60분 4). ⚠️ TS completionStars 와 두 벌(회귀가 대조)
    bonus := greatest(1, round(row.planned_seconds / 900.0)::integer);
  elsif p_give_up then
    result := 'gave_up';
    rolls := elapsed / 300;
  else
    return jsonb_build_object('outcome', 'running', 'remaining', ceil(extract(epoch from due - now()))::integer);
  end if;
  select s.towers into tw from public.tower_state s where s.owner = row.owner;
  for i in 0 .. rolls - 1 loop
    seed := row.id::text || ':' || i;
    -- 그 굴림의 순간: 다 찬 5분 칸의 끝(완주 보너스는 끝 시각)
    at := least(due, row.started_at + make_interval(secs => (i + 1) * 300));
    keys := keys || coalesce(tower_private.deep_roll(seed, tw), tower_private.rare_roll(seed, at), tower_private.roll(seed));
  end loop;
  select coalesce(sum(t.fish), 0) as fish, coalesce(sum(t.wood), 0) as wood, coalesce(sum(t.scrap), 0) as scrap,
         coalesce(sum(t.bottle), 0) as bottle, coalesce(sum(t.star), 0) as star
    into d
    from unnest(keys) k, lateral tower_private.catch_gives(k) t;
  update public.tower_state set
    fish = fish + d.fish, wood = wood + d.wood, scrap = scrap + d.scrap,
    star = star + d.star + bonus,
    focus_seconds = focus_seconds + elapsed,
    sessions = sessions + case when result = 'completed' then 1 else 0 end,
    caught = (select coalesce(array_agg(distinct x order by x), '{}') from unnest(caught || keys) x),
    updated_at = now()
  where owner = row.owner;
  got := tower_private.give_bottles(row.owner, d.bottle::integer);
  update public.tower_focus set ended_at = now(), outcome = result, catches = to_jsonb(keys) where id = row.id;
  return jsonb_build_object('outcome', result, 'catches', to_jsonb(keys), 'bonus_star', result = 'completed', 'bonus_stars', bonus, 'letters', to_jsonb(got));
end $$;


ALTER FUNCTION "tower_private"."close_focus"("p_id" "uuid", "p_give_up" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tower_private"."deep_roll"("p_seed" "text", "p_towers" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  keys text[];
begin
  if coalesce(p_towers, 0) <= 0 then return null; end if;
  if (('x' || substr(md5(p_seed || ':deep'), 1, 7))::bit(28)::integer % 100) >= 5 then return null; end if;
  select array_agg(d.key order by d.ord) into keys from tower_private.deep_table() d where d.towers_at <= p_towers;
  if keys is null then return null; end if;
  return keys[1 + (('x' || substr(md5(p_seed || ':deeppick'), 1, 7))::bit(28)::integer % cardinality(keys))];
end $$;


