CREATE OR REPLACE FUNCTION "tower_private"."give_bottles"("u" "uuid", "n" integer) RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  have text[];
  pool text[];
  pick text;
  got text[] := '{}';
  spare integer := 0;
  i integer;
begin
  if coalesce(n, 0) <= 0 then return got; end if;
  select letters into have from public.tower_state where owner = u for update;
  for i in 1 .. n loop
    pool := array(select k from unnest(tower_private.letter_keys()) k where not (k = any (have)));
    if cardinality(pool) = 0 then
      spare := spare + 1;
      continue;
    end if;
    pick := pool[1 + floor(random() * cardinality(pool))::integer];
    -- 이야기 편지는 «다음 이야기»로 — 오는 때만 무작위, 순서는 지킨다
    if pick like 'story-%' then
      select k into pick from unnest(tower_private.letter_keys()) with ordinality t(k, o)
       where k like 'story-%' and not (k = any (have)) order by o limit 1;
    end if;
    have := have || pick;
    got := got || pick;
  end loop;
  update public.tower_state set letters = have, bottle = bottle + spare, updated_at = now() where owner = u;
  return got;
end $$;


