CREATE OR REPLACE FUNCTION "tower_private"."rain_at"("p_ts" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  k timestamp := p_ts at time zone 'Asia/Seoul';
  key text := format('%s-%s-%s-%s', extract(year from k)::int, extract(month from k)::int - 1, extract(day from k)::int, floor(extract(hour from k) / 3)::int);
  h bigint := 2166136261;
  i integer;
begin
  for i in 1 .. length(key) loop
    h := ((h # ascii(substr(key, i, 1))) * 16777619) & 4294967295;
  end loop;
  return h % 100 < 12;
end $$;


