CREATE OR REPLACE FUNCTION "tower_private"."ranking"("p_limit" integer) RETURNS TABLE("owner" "uuid", "towers" integer, "floor_count" integer, "focus_seconds" bigint, "rank" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with base as (
    select s.owner, s.towers, cardinality(s.floors) as floor_count, s.focus_seconds, s.created_at,
           case when cardinality(s.floors) >= tower_private.full_floors() then 0 else cardinality(s.floors) end as progress
    from public.tower_state s
    join public.profiles p on p.id = s.owner and p.role in ('student', 'teacher')
    where s.towers > 0 or cardinality(s.floors) > 0
  )
  select b.owner, b.towers, b.floor_count, b.focus_seconds,
         row_number() over (order by b.towers desc, b.progress desc, b.focus_seconds desc, b.created_at asc)
  from base b
  order by b.towers desc, b.progress desc, b.focus_seconds desc, b.created_at asc
  limit p_limit
$$;


