CREATE OR REPLACE FUNCTION "tower_private"."rare_ok"("p_cond" "text", "p_ts" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  k timestamp := p_ts at time zone 'Asia/Seoul';
  h integer := extract(hour from k)::int;
  m integer := extract(month from k)::int;
begin
  return case p_cond
    when 'night' then h >= 20 or h < 4
    when 'dusk' then h >= 17 and h < 20
    when 'dawn' then h >= 5 and h < 8
    when 'rain' then tower_private.rain_at(p_ts)
    when 'spring' then m between 3 and 5
    when 'summer' then m between 6 and 8
    when 'autumn' then m between 9 and 11
    when 'winter' then m in (12, 1, 2)
    else false end;
end $$;


ALTER FUNCTION "tower_private"."rare_ok"("p_cond" "text", "p_ts" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tower_private"."rare_roll"("p_seed" "text", "p_ts" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
