    AS $$
declare
  keys text[];
begin
  if (('x' || substr(md5(p_seed || ':rare'), 1, 7))::bit(28)::integer % 100) >= 8 then return null; end if;
  select array_agg(r.key order by r.ord) into keys from tower_private.rare_table() r where tower_private.rare_ok(r.cond, p_ts);
  if keys is null then return null; end if;
  return keys[1 + (('x' || substr(md5(p_seed || ':pick'), 1, 7))::bit(28)::integer % cardinality(keys))];
end $$;


