CREATE OR REPLACE FUNCTION "wallet_private"."apply"("p_user" "uuid", "p_delta" integer, "p_kind" "text", "p_source_app" "text", "p_source_id" "text", "p_clamp" boolean DEFAULT false, "p_note" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  have integer;
  moved integer;
  inserted integer;
begin
  if p_user is null or p_delta is null or p_delta = 0 then return 0; end if;
  insert into public.academy_user_stats(user_id) values (p_user) on conflict (user_id) do nothing;
  select coins into have from public.academy_user_stats where user_id = p_user for update;
  moved := p_delta;
  if have + p_delta < 0 then
    if not p_clamp then
      raise exception '코인이 부족합니다. (필요: %, 보유: %)', -p_delta, have using errcode = 'P0001';
    end if;
    moved := -have;
  end if;
  insert into public.wallet_ledger(user_id, delta, kind, source_app, source_id, balance_after, note)
    values (p_user, moved, p_kind, p_source_app, left(p_source_id, 120), have + moved, p_note)
    on conflict (user_id, source_app, kind, source_id) do nothing;
  get diagnostics inserted = row_count;
  if inserted = 0 then return 0; end if;
  if moved <> 0 then
    update public.academy_user_stats set coins = coins + moved, updated_at = now() where user_id = p_user;
  end if;
  return moved;
end $$;


ALTER FUNCTION "wallet_private"."apply"("p_user" "uuid", "p_delta" integer, "p_kind" "text", "p_source_app" "text", "p_source_id" "text", "p_clamp" boolean, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "wallet_private"."focus_grant"("p_user" "uuid", "p_run" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  today date := (now() at time zone 'Asia/Seoul')::date;
  rule record;
  taken integer;
  inserted integer;
begin
  select * into rule from tama_private.credit_rule('focus');
  -- 다마고찌 grant_credit 과 같은 잠금 · 같은 원장 kind → 하루 2번 상한을 자동으로 공유한다
  perform pg_advisory_xact_lock(hashtextextended('tama-credit:' || p_user::text, 0));
  select count(*) into taken from public.tama_credit_ledger where user_id = p_user and earned_on = today and kind = 'focus';
  if taken >= rule.daily_cap then return 0; end if;
  insert into public.tama_credit_ledger(user_id, earned_on, kind, source_id, amount)
    values (p_user, today, 'focus', 'forest:' || p_run::text, rule.amount)
    on conflict do nothing;
  get diagnostics inserted = row_count;
  if inserted = 0 then return 0; end if;
  return wallet_private.apply(p_user, rule.amount, 'seaton_focus', 'seaton', p_run::text, false, '집중의 숲');
end $$;


