CREATE OR REPLACE FUNCTION "wallet_private"."grant_daily"("p_user" "uuid", "p_kind" "text", "p_app" "text", "p_source" "text", "p_amount_key" "text", "p_cap_key" "text", "p_note" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare today date := (now() at time zone 'Asia/Seoul')::date;
begin
  if p_user is null or not exists (select 1 from public.profiles where id = p_user and role in ('student', 'teacher', 'admin')) then return 0; end if;
  perform pg_advisory_xact_lock(hashtextextended('wallet-daily:' || p_kind || ':' || p_user::text, 0));
  if exists (select 1 from public.wallet_ledger where user_id = p_user and source_app = p_app and kind = p_kind and source_id = p_source) then return 0; end if;
  if (select count(*) from public.wallet_ledger where user_id = p_user and kind = p_kind and earned_on = today) >= economy_private.num(p_cap_key) then return 0; end if;
  return wallet_private.apply(p_user, economy_private.num(p_amount_key), p_kind, p_app, p_source, false, p_note);
end $$;


