CREATE OR REPLACE FUNCTION "wallet_private"."on_attendance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  today date := (now() at time zone 'Asia/Seoul')::date;
  eligible boolean;
  had_receipt boolean;
  inserted integer;
  version integer;
  amt integer;
begin
  if not exists (select 1 from public.profiles where id = new.student_id and role = 'student') then return null; end if;
  eligible := wallet_private.is_study_reward(new.attendance_status, new.is_attended)
              and new.reservation_date between date '2026-09-07' and today;
  -- advisory 잠금을 잡지 않는다: 아카데미 청구는 «예약 행 → 잠금» 순서라, 여기서 잠금을 잡으면
  -- 교사의 일괄 출석 체크와 교착할 수 있다. 같은 예약의 동시 갱신은 행 잠금이 이미 줄 세우고,
  -- 이중 지급은 영수증 PK 가, 잔액은 지갑 행 잠금(apply)이 막는다.
  had_receipt := exists (select 1 from public.academy_study_rewards where reservation_id = new.id);
  select count(*) into version from public.wallet_ledger
    where user_id = new.student_id and source_app = 'seaton'
      and kind in ('seaton_attendance', 'seaton_attendance_reversal') and source_id like new.id::text || '#%';
  if eligible and not had_receipt
     and (select count(*) from public.academy_study_rewards
          where user_id = new.student_id and reservation_date = new.reservation_date) < economy_private.num('study.daily_receipts') then
    insert into public.academy_study_rewards(reservation_id, user_id, reservation_date, source, amount)
      values (new.id, new.student_id, new.reservation_date, 'auto', economy_private.num('study.attendance_reward'))
      on conflict (reservation_id) do nothing
      returning amount into amt;
    get diagnostics inserted = row_count;
    if inserted > 0 then
      perform wallet_private.apply(new.student_id, amt, 'seaton_attendance', 'seaton', new.id::text || '#' || version,
                                   false, '자습실 출석 ' || new.reservation_date);
    end if;
  elsif not eligible and had_receipt then
    -- 회수 = 그 영수증에 적힌 값(지급 뒤 설정이 바뀌어도 준 만큼만 되돌린다)
    delete from public.academy_study_rewards where reservation_id = new.id returning amount into amt;
    perform wallet_private.apply(new.student_id, -coalesce(amt, 0), 'seaton_attendance_reversal', 'seaton', new.id::text || '#' || version,
                                 true, '출석 취소 ' || new.reservation_date);
  end if;
  return null;
exception when others then
  -- 출석 체크(교사의 일)를 보상 실패로 막지 않는다. 빠진 보상은 아카데미 [받기] 버튼이 메운다.
  raise warning 'wallet attendance skipped (%): %', new.id, sqlerrm;
  return null;
end $$;


ALTER FUNCTION "wallet_private"."on_attendance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "wallet_private"."on_interview_answer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status = 'ready' and old.status is distinct from 'ready' and new.evaluation is not null
     and char_length(btrim(coalesce(new.answer, ''))) >= 10 then
    perform wallet_private.grant_daily(new.user_id, 'interview_answer', 'interview', new.question_id::text,
      'interview.answer_reward', 'interview.answer_cap', '면접 준비 답');
  end if;
  return null;
exception when others then
  raise warning 'interview coin skipped (%): %', new.id, sqlerrm;
  return null;
end $$;


ALTER FUNCTION "wallet_private"."on_interview_answer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "wallet_private"."on_review"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  today date := (now() at time zone 'Asia/Seoul')::date;
begin
  if old.feedback_rating is not null or new.feedback_rating is null then return null; end if;
  if not exists (select 1 from public.profiles where id = new.student_id and role = 'student') then return null; end if;
  perform pg_advisory_xact_lock(hashtextextended('wallet-review:' || new.student_id::text, 0));
  if exists (select 1 from public.wallet_ledger where user_id = new.student_id and earned_on = today and kind = 'seaton_review') then
    return null;
  end if;
  perform wallet_private.apply(new.student_id, economy_private.num('study.review_reward'), 'seaton_review', 'seaton', new.id::text, false, '자습실 피드백');
  return null;
exception when others then
  raise warning 'wallet review skipped (%): %', new.id, sqlerrm;
  return null;
end $$;


ALTER FUNCTION "wallet_private"."on_review"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "wallet_private"."on_world_inquiry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if char_length(btrim(coalesce(new.question, ''))) >= 10 then
    perform wallet_private.grant_daily(new.user_id, 'world_inquiry', 'world-today', new.news_id::text,
      'world.inquiry_reward', 'world.inquiry_cap', '요즘 세상 탐구 질문');
  end if;
  if char_length(btrim(coalesce(new.reflection, ''))) >= 20 then
    perform wallet_private.grant_daily(new.user_id, 'world_reflection', 'world-today', new.news_id::text,
      'world.reflection_reward', 'world.reflection_cap', '요즘 세상 돌아보기');
  end if;
  return null;
exception when others then
  raise warning 'world coin skipped (% %): %', new.user_id, new.news_id, sqlerrm;
  return null;
end $$;


ALTER FUNCTION "wallet_private"."on_world_inquiry"() OWNER TO "postgres";


