CREATE OR REPLACE FUNCTION "world_news_private"."dispatch_picks"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i record;
  a record;
  rid uuid;
  n integer := 0;
  day0 timestamptz := date_trunc('day', now() at time zone 'Asia/Seoul') at time zone 'Asia/Seoul';
begin
  for i in select w.user_id, w.fields from public.world_news_interests w
            where w.notify and cardinality(w.fields) > 0 loop
    -- 하루 1건(한국 날짜) — 수동 재실행에도 겹치지 않는다
    if exists (select 1 from world_news_private.pick_log l where l.user_id = i.user_id and l.sent_at >= day0) then continue; end if;
    select x.id, x.title, x.classroom_hook, x.fields into a
      from public.ai_news x
     where x.keep and x.fields && i.fields
       and coalesce(x.collected_at, x.created_at) >= now() - interval '36 hours'
       and not exists (select 1 from world_news_private.pick_log l where l.user_id = i.user_id and l.news_id = x.id)
     order by (x.fields[1] = any(i.fields)) desc, x.impact desc, x.published_at desc nulls last, x.id desc
     limit 1;
    if not found then continue; end if;
    rid := push_private.resource_of_user(i.user_id);
    if rid is null then continue; end if;
    insert into public.notification_events(resource_id, type, title, message, priority, meta)
      values (rid, 'world_news_pick',
              '요즘 세상 · ' || (select f from unnest(a.fields) f where f = any(i.fields) limit 1) || ' 소식',
              left(coalesce(nullif(a.classroom_hook, ''), a.title), 200), 'low',
              jsonb_build_object('news_id', a.id,
                'fields', (select coalesce(jsonb_agg(f), '[]'::jsonb) from unnest(a.fields) f where f = any(i.fields))));
    insert into world_news_private.pick_log(user_id, news_id) values (i.user_id, a.id);
    n := n + 1;
  end loop;
  delete from world_news_private.pick_log where sent_at < now() - interval '120 days';
  return n;
end $$;


ALTER FUNCTION "world_news_private"."dispatch_picks"() OWNER TO "postgres";


