CREATE OR REPLACE FUNCTION "world_news_private"."wake_tagger"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c world_news_private.config;
begin
  if not exists (select 1 from public.ai_news where keep and fields is null) then return false; end if;
  select * into c from world_news_private.config where singleton;
  perform net.http_post(
    url := c.url,
    body := jsonb_build_object('limit', 40),
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-world-secret', c.secret),
    timeout_milliseconds := 120000
  );
  return true;
end $$;


