    CONSTRAINT "academy_chapters_revision_check" CHECK (("revision" >= 0)),
    CONSTRAINT "academy_chapters_step_check" CHECK ((("step" >= 0) AND ("step" <=
CASE "chapter"
    WHEN 'first_star'::"text" THEN 16
    WHEN 'library_questions'::"text" THEN 18
    WHEN 'dorm_first_plan'::"text" THEN 36
    WHEN 'post_first_letter'::"text" THEN 30
    WHEN 'sky_first_light'::"text" THEN 29
    ELSE 17
END)))
);


