CREATE TABLE IF NOT EXISTS "public"."ai_news" (
    "id" bigint NOT NULL,
    "url" "text" NOT NULL,
    "source" "text" NOT NULL,
    "title" "text" NOT NULL,
    "published_at" timestamp with time zone,
    "summary" "text",
    "category" "text" NOT NULL,
    "keep" boolean DEFAULT false NOT NULL,
    "classroom_hook" "text",
    "why_it_matters" "text",
    "subjects" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "difficulty" "text",
    "impact" smallint DEFAULT 0 NOT NULL,
    "model" "text",
    "classified_at" timestamp with time zone,
    "collected_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "inquiry_questions" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "comic_path" "text",
    "comic_panels" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "keywords" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "fields" "text"[],
    CONSTRAINT "ai_news_category_chk" CHECK (("category" = ANY (ARRAY['연구성과'::"text", '응용사례'::"text", '산업뉴스'::"text", '정책'::"text"]))),
    CONSTRAINT "ai_news_comic_panels_chk" CHECK ((("jsonb_typeof"("comic_panels") = 'array'::"text") AND ("jsonb_array_length"("comic_panels") = ANY (ARRAY[0, 4])))),
    CONSTRAINT "ai_news_fields_chk" CHECK ((("fields" IS NULL) OR (("fields" <@ "world_news_private"."field_list"()) AND ("cardinality"("fields") <= 3)))),
    CONSTRAINT "ai_news_impact_chk" CHECK ((("impact" >= 0) AND ("impact" <= 5))),
    CONSTRAINT "ai_news_inquiry_questions_chk" CHECK ((COALESCE("array_length"("inquiry_questions", 1), 0) <= 5)),
    CONSTRAINT "ai_news_keywords_chk" CHECK ((COALESCE("array_length"("keywords", 1), 0) <= 8))
);


ALTER TABLE "public"."ai_news" OWNER TO "postgres";


COMMENT ON COLUMN "public"."ai_news"."summary" IS '기사 전문을 읽고 만든 요약. 2026-09-12 이전 행은 RSS 발췌일 수 있다.';



COMMENT ON COLUMN "public"."ai_news"."inquiry_questions" IS '수집 단계에서 기사 내용으로 생성한 학생용 탐구 질문(최대 5개, 수집기는 3개). 답이 본문에 그대로 있는 확인 질문은 넣지 않는다.';



COMMENT ON COLUMN "public"."ai_news"."comic_path" IS 'world-today-comics 버킷 내 경로(예: 2026/09/41858.webp). null 이면 만화 없음.';



COMMENT ON COLUMN "public"."ai_news"."comic_panels" IS '4컷 대사 텍스트 대체본 [{title, dialogue[]}] × 4. 이미지 로딩 실패·스크린리더 대비.';



COMMENT ON COLUMN "public"."ai_news"."keywords" IS '요약 단계에서 기사 전문으로 뽑은 핵심 키워드 3~5개. 기관·기술·대상 이름 위주이며 "AI" 같은 일반어는 제외된다.';



COMMENT ON COLUMN "public"."ai_news"."fields" IS '관심 분야 맞춤용 분야(닫힌 14종, 최대 3, 첫째 = 주된 분야). null = 미분류, {} = 맞는 분야 없음. 엣지 함수 world-news-fields 가 채운다.';



ALTER TABLE "public"."ai_news" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."ai_news_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



