CREATE OR REPLACE VIEW "public"."course_selection_round_for_grade" WITH ("security_invoker"='true') AS
 SELECT DISTINCT "r"."id",
    "r"."academic_year",
    "r"."target_grade",
    "r"."round_number",
    "r"."opens_at",
    "r"."closes_at",
    "r"."status",
    "r"."title",
    "r"."description",
    "r"."capacity_overrides",
    "r"."meta",
    "r"."created_at",
    "r"."updated_at",
    COALESCE("g"."target_grade", "r"."target_grade") AS "effective_grade"
   FROM ("public"."course_selection_round" "r"
     LEFT JOIN "public"."course_selection_group" "g" ON (("g"."round_id" = "r"."id")));


ALTER VIEW "public"."course_selection_round_for_grade" OWNER TO "postgres";


