    "semester" integer,
    CONSTRAINT "course_selection_slot_capacity_check" CHECK ((("capacity" IS NULL) OR ("capacity" > 0))),
    CONSTRAINT "course_selection_slot_pick_count_check" CHECK (("pick_count" >= 1)),
    CONSTRAINT "course_selection_slot_semester_check" CHECK ((("semester" IS NULL) OR ("semester" = ANY (ARRAY[1, 2]))))
