CREATE OR REPLACE VIEW "public"."course_selection_slot_capacity" WITH ("security_invoker"='true') AS
 SELECT "s"."id" AS "slot_id",
    "s"."group_id",
    "g"."round_id",
    "ss"."selectable_subject_id",
    "ss"."semester",
    COALESCE("ss"."override_capacity", "s"."capacity") AS "capacity",
    "count"("i"."id") FILTER (WHERE (("i"."slot_id" = "s"."id") AND ("i"."selectable_subject_id" = "ss"."selectable_subject_id"))) AS "enrolled"
   FROM ((("public"."course_selection_slot" "s"
     JOIN "public"."course_selection_group" "g" ON (("g"."id" = "s"."group_id")))
     JOIN "public"."course_selection_slot_subject" "ss" ON (("ss"."slot_id" = "s"."id")))
     LEFT JOIN "public"."course_selection_item" "i" ON ((("i"."slot_id" = "s"."id") AND ("i"."selectable_subject_id" = "ss"."selectable_subject_id"))))
  GROUP BY "s"."id", "s"."capacity", "s"."group_id", "g"."round_id", "ss"."selectable_subject_id", "ss"."semester", "ss"."override_capacity";


ALTER VIEW "public"."course_selection_slot_capacity" OWNER TO "postgres";


