CREATE OR REPLACE VIEW "public"."ipsi_hub_feed" WITH ("security_invoker"='true') AS
 SELECT "v"."id",
    'video'::"text" AS "kind",
    "v"."title",
    "v"."url",
    COALESCE("v"."article_date", "v"."collected_at", "v"."created_at") AS "sort_date",
    "v"."category",
    "v"."headline_summary",
    "v"."meta",
    "v"."created_at",
    "v"."thumbnail",
    "v"."likes",
    "v"."created_by",
    "v"."channel_label",
    "v"."duration_seconds",
    "v"."analyzed_at",
    NULL::"text" AS "source",
    NULL::"text"[] AS "core_points",
    NULL::"text"[] AS "strategy_implications",
    NULL::"text"[] AS "data_points",
    NULL::"text"[] AS "cautions",
    NULL::"text" AS "academic_year",
    NULL::"text" AS "analysis_status"
   FROM "public"."educational_videos" "v"
UNION ALL
 SELECT "n"."id",
    'news'::"text" AS "kind",
    "n"."title",
    "n"."url",
    COALESCE(("n"."article_date")::timestamp with time zone, "n"."collected_at", "n"."created_at") AS "sort_date",
    "n"."category",
    "n"."headline_summary",
    "n"."meta",
    "n"."created_at",
    NULL::"text" AS "thumbnail",
    NULL::integer AS "likes",
    NULL::"uuid" AS "created_by",
    NULL::"text" AS "channel_label",
    NULL::integer AS "duration_seconds",
    "n"."analyzed_at",
    "n"."source",
    "n"."core_points",
    "n"."strategy_implications",
    "n"."data_points",
    "n"."cautions",
    NULL::"text" AS "academic_year",
    NULL::"text" AS "analysis_status"
   FROM "public"."educational_news" "n";


