CREATE MATERIALIZED VIEW "public"."mock_school_stats" AS
 WITH "marking_flat" AS (
         SELECT "sbi"."id" AS "student_code",
            (("entry"."value" ->> 'academic_year'::"text"))::integer AS "year",
            (("entry"."value" ->> 'exam_month'::"text"))::integer AS "month",
            (("entry"."value" ->> 'exam_grade'::"text"))::integer AS "student_grade",
            "subj"."key" AS "subject",
            "ans"."ordinality" AS "problem_number",
                CASE
                    WHEN ("ans"."value" ~ '^\d+$'::"text") THEN ("ans"."value")::integer
                    ELSE NULL::integer
                END AS "student_answer",
                CASE
                    WHEN (("corr"."value" IS NOT NULL) AND ("corr"."value" = 'true'::"text")) THEN true
                    WHEN (("corr"."value" IS NOT NULL) AND ("corr"."value" = 'false'::"text")) THEN false
                    ELSE NULL::boolean
                END AS "is_correct"
           FROM (((("public"."student_basic_info" "sbi"
             CROSS JOIN LATERAL "jsonb_array_elements"("sbi"."mock_marking") "entry"("value"))
             CROSS JOIN LATERAL "jsonb_each"(("entry"."value" -> 'subjects'::"text")) "subj"("key", "value"))
             CROSS JOIN LATERAL "jsonb_array_elements_text"(("subj"."value" -> 'answers'::"text")) WITH ORDINALITY "ans"("value", "ordinality"))
             LEFT JOIN LATERAL ( SELECT "c"."elem" AS "value"
                   FROM "jsonb_array_elements_text"(("subj"."value" -> 'correct'::"text")) WITH ORDINALITY "c"("elem", "ord")
                  WHERE ("c"."ord" = "ans"."ordinality")) "corr" ON (true))
          WHERE (("sbi"."mock_marking" IS NOT NULL) AND ("jsonb_typeof"("sbi"."mock_marking") = 'array'::"text") AND ("jsonb_array_length"("sbi"."mock_marking") > 0) AND ("ans"."value" IS NOT NULL))
        )
 SELECT "mf"."year",
    "mf"."month",
    "mf"."student_grade",
    "mf"."subject",
    "mf"."problem_number",
    "count"(DISTINCT "mf"."student_code") AS "total_students",
    "count"(DISTINCT
        CASE
            WHEN "mf"."is_correct" THEN "mf"."student_code"
            ELSE NULL::"text"
        END) AS "correct_count",
    "round"(((("count"(DISTINCT
        CASE
            WHEN "mf"."is_correct" THEN "mf"."student_code"
            ELSE NULL::"text"
        END))::numeric * 100.0) / (NULLIF("count"(DISTINCT "mf"."student_code"), 0))::numeric), 2) AS "school_correct_rate",
    "max"(
        CASE
            WHEN ((COALESCE("mp"."correct_rate", "mp_common"."correct_rate") IS NOT NULL) AND ("regexp_replace"(COALESCE("mp"."correct_rate", "mp_common"."correct_rate"), '[^0-9.]'::"text", ''::"text", 'g'::"text") ~ '^\d+\.?\d*$'::"text")) THEN ("regexp_replace"(COALESCE("mp"."correct_rate", "mp_common"."correct_rate"), '[^0-9.]'::"text", ''::"text", 'g'::"text"))::numeric(5,2)
            ELSE NULL::numeric
        END) AS "national_correct_rate",
    "jsonb_build_object"('1', "count"(
        CASE
            WHEN ("mf"."student_answer" = 1) THEN 1
            ELSE NULL::integer
        END), '2', "count"(
        CASE
            WHEN ("mf"."student_answer" = 2) THEN 1
            ELSE NULL::integer
        END), '3', "count"(
        CASE
            WHEN ("mf"."student_answer" = 3) THEN 1
            ELSE NULL::integer
        END), '4', "count"(
        CASE
            WHEN ("mf"."student_answer" = 4) THEN 1
            ELSE NULL::integer
        END), '5', "count"(
        CASE
            WHEN ("mf"."student_answer" = 5) THEN 1
            ELSE NULL::integer
        END)) AS "answer_distribution"
   FROM (("marking_flat" "mf"
     LEFT JOIN "public"."mock_problems" "mp" ON ((("mp"."year" = "mf"."year") AND ("mp"."month" = "mf"."month") AND ("mp"."student_grade" = "mf"."student_grade") AND ("mp"."subject" = "mf"."subject") AND ("mp"."problem_number" = "mf"."problem_number"))))
     LEFT JOIN "public"."mock_problems" "mp_common" ON ((("mf"."student_grade" = 3) AND ("mf"."subject" = ANY (ARRAY['확률과통계'::"text", '미적분'::"text", '기하'::"text"])) AND ("mf"."problem_number" <= 22) AND ("mp_common"."year" = "mf"."year") AND ("mp_common"."month" = "mf"."month") AND ("mp_common"."student_grade" = "mf"."student_grade") AND ("mp_common"."subject" = '공통'::"text") AND ("mp_common"."problem_number" = "mf"."problem_number") AND ("mp_common"."major_category" ~~ '수학%'::"text"))))
  WHERE ("mf"."student_answer" IS NOT NULL)
  GROUP BY "mf"."year", "mf"."month", "mf"."student_grade", "mf"."subject", "mf"."problem_number"
  ORDER BY "mf"."year", "mf"."month", "mf"."student_grade", "mf"."subject", "mf"."problem_number"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mock_school_stats" OWNER TO "postgres";


