CREATE TABLE IF NOT EXISTS "public"."planner_focus_sessions" (
    "id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "task_id" "uuid" NOT NULL,
    "started_at" timestamp with time zone NOT NULL,
    "ended_at" timestamp with time zone NOT NULL,
    "focus_seconds" integer NOT NULL,
    "planned_seconds" integer NOT NULL,
    "completed" boolean NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "planner_focus_sessions_check" CHECK (("ended_at" >= "started_at")),
    CONSTRAINT "planner_focus_sessions_check1" CHECK (("focus_seconds" <= "planned_seconds")),
    CONSTRAINT "planner_focus_sessions_check2" CHECK ((EXTRACT(epoch FROM ("ended_at" - "started_at")) >= ("focus_seconds")::numeric)),
    CONSTRAINT "planner_focus_sessions_check3" CHECK (("completed" = ("focus_seconds" = "planned_seconds"))),
    CONSTRAINT "planner_focus_sessions_focus_seconds_check" CHECK ((("focus_seconds" >= 1) AND ("focus_seconds" <= 7200))),
    CONSTRAINT "planner_focus_sessions_planned_seconds_check" CHECK ((("planned_seconds" >= 60) AND ("planned_seconds" <= 7200)))
);


