CREATE TABLE IF NOT EXISTS "public"."resource" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "type" "text" NOT NULL,
    "name" "text" NOT NULL,
    "meta" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    CONSTRAINT "resource_graduated_student_privacy" CHECK ((("type" <> 'student'::"text") OR ("status" <> 'graduated'::"text") OR (("name" ~ '^[0-9]{4}입학[0-9]{3}$'::"text") AND (NOT (COALESCE("meta", '{}'::"jsonb") ?| ARRAY['grade'::"text", 'picture'::"text", 'birthday'::"text"]))))),
    CONSTRAINT "resource_meta_no_personal_phone" CHECK ((("meta" IS NULL) OR ((NOT ("meta" ? 'phone'::"text")) AND (NOT ("meta" ? 'hp'::"text"))))),
    CONSTRAINT "resource_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'graduated'::"text", 'transferred'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "resource_type_check" CHECK (("type" = ANY (ARRAY['teacher'::"text", 'student'::"text", 'room'::"text", 'device'::"text", 'group'::"text", 'classroom'::"text", 'iframe'::"text", 'link'::"text", 'staff'::"text", 'graduated'::"text", 'inactive'::"text"])))
);


ALTER TABLE "public"."resource" OWNER TO "postgres";


COMMENT ON CONSTRAINT "resource_graduated_student_privacy" ON "public"."resource" IS 'Graduated students use a cohort alias and cannot retain current grade, picture, or birthday metadata.';



COMMENT ON CONSTRAINT "resource_meta_no_personal_phone" ON "public"."resource" IS 'Personal phone numbers must not be stored in resource metadata.';



