    CONSTRAINT "school_curriculum_subject_type_check" CHECK (("subject_type" = ANY (ARRAY['공통 과목'::"text", '일반 선택'::"text", '진로 선택'::"text", '융합 선택'::"text"])))
);


ALTER TABLE "public"."school_curriculum_archive" OWNER TO "postgres";


COMMENT ON TABLE "public"."school_curriculum_archive" IS '학교 교육과정 편성 데이터 (입학년도별 3개년 과목 편성)';



COMMENT ON COLUMN "public"."school_curriculum_archive"."admission_year" IS '입학년도 (예: 2025 = 2025학년도 입학생)';



COMMENT ON COLUMN "public"."school_curriculum_archive"."credits_by_semester" IS '학기별 학점 배분 JSONB {"1-1": 3, "2-1": 4, ...}';



CREATE TABLE IF NOT EXISTS "public"."school_exam_question" (
