    "semester" integer NOT NULL,
    "exam_round" integer NOT NULL,
    "grade" integer NOT NULL,
    "subject_section" "text" NOT NULL,
    "subject_name" "text" NOT NULL,
    "class_label" "text",
    "student_number" integer,
    "is_cross_class" boolean DEFAULT false NOT NULL,
    "attendance" "text",
    "selective_score" numeric(6,2),
    "descriptive_score" numeric(6,2),
    "etc_score" numeric(6,2),
    "total_score" numeric(6,2),
    "answers" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "correct" boolean[] DEFAULT '{}'::boolean[] NOT NULL,
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "exam_name" "text",
    CONSTRAINT "school_exam_result_answers_aligned" CHECK ((NOT ("array_length"("answers", 1) IS DISTINCT FROM "array_length"("correct", 1)))),
    CONSTRAINT "school_exam_result_exam_round_check" CHECK ((("exam_round" >= 1) AND ("exam_round" <= 4))),
    CONSTRAINT "school_exam_result_grade_check" CHECK ((("grade" >= 1) AND ("grade" <= 3)))
);


ALTER TABLE "public"."school_exam_result" OWNER TO "postgres";


COMMENT ON TABLE "public"."school_exam_result" IS '학교 정기고사 학생별 응시 결과. answers/correct는 선택형 문항만 담는다(NEIS가 서답형 문항별 정오를 제공하지 않음).';



