CREATE TABLE IF NOT EXISTS "public"."school_life_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "description" "text" DEFAULT ''::"text" NOT NULL,
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone NOT NULL,
    "date_only" boolean DEFAULT false NOT NULL,
    "visibility" "text" NOT NULL,
    "academic_year" integer NOT NULL,
    "grade" integer,
    "class_num" integer,
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "course_offering_id" "uuid",
    CONSTRAINT "school_life_events_check" CHECK (("ends_at" >= "starts_at")),
    CONSTRAINT "school_life_events_description_check" CHECK (("length"("description") <= 4000)),
    CONSTRAINT "school_life_events_title_check" CHECK ((("length"("btrim"("title")) >= 1) AND ("length"("btrim"("title")) <= 120))),
    CONSTRAINT "school_life_events_visibility_check" CHECK (("visibility" = ANY (ARRAY['personal'::"text", 'homeroom'::"text", 'assignment'::"text"]))),
    CONSTRAINT "school_life_scope_check" CHECK (((("visibility" = 'personal'::"text") AND ("grade" IS NULL) AND ("class_num" IS NULL) AND ("course_offering_id" IS NULL)) OR (("visibility" = 'homeroom'::"text") AND (("grade" >= 1) AND ("grade" <= 3)) AND (("class_num" >= 1) AND ("class_num" <= 99)) AND ("grade" IS NOT NULL) AND ("class_num" IS NOT NULL) AND ("course_offering_id" IS NULL)) OR (("visibility" = 'assignment'::"text") AND ("grade" IS NULL) AND ("class_num" IS NULL) AND ("course_offering_id" IS NOT NULL))))
);


