CREATE TABLE IF NOT EXISTS "public"."signature_request" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "message" "text",
    "subject_type" "text",
    "subject_id" "text",
    "source_kind" "text" NOT NULL,
    "source_path" "text" NOT NULL,
    "source_name" "text" NOT NULL,
    "source_mime" "text",
    "page_count" integer,
    "signed_path" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "current_order" integer DEFAULT 0 NOT NULL,
    "requester_user_id" "uuid" NOT NULL,
    "requester_resource_id" "uuid",
    "requester_name" "text" NOT NULL,
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "decided_at" timestamp with time zone,
    "purged_at" timestamp with time zone,
    "due_at" timestamp with time zone DEFAULT ("now"() + '7 days'::interval) NOT NULL,
    CONSTRAINT "signature_request_source_kind_check" CHECK (("source_kind" = ANY (ARRAY['hwpx'::"text", 'pdf'::"text", 'image'::"text"]))),
    CONSTRAINT "signature_request_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'completed'::"text", 'rejected'::"text", 'cancelled'::"text", 'expired'::"text"])))
);


ALTER TABLE "public"."signature_request" OWNER TO "postgres";


COMMENT ON TABLE "public"."signature_request" IS '전자서명 요청 1건 = 문서 1개. 쓰기는 RPC 전용(직접 UPDATE 금지 — 차례·신원 검증을 우회하게 된다).';



COMMENT ON COLUMN "public"."signature_request"."status" IS 'pending=서명 중 · completed=완료 · rejected=거절 · cancelled=요청자 취소 · expired=기한 경과로 파일이 정리돼 종료(서명 미완료)';



COMMENT ON COLUMN "public"."signature_request"."purged_at" IS '원본·완성본을 Storage 에서 지운 시각. 설정돼 있으면 파일이 없으므로 화면이 내려받기를 막고 이유를 설명한다.';



COMMENT ON COLUMN "public"."signature_request"."due_at" IS '서명 마감 — 이때까지 끝나지 않으면 만료되고 파일이 정리된다. 완료된 문서는 완료 후 signature_purge_days() 일에 정리(마감과 무관).';



