CREATE TABLE IF NOT EXISTS "public"."isekai3d_questions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "context_key" "text" NOT NULL,
    "card" "jsonb" NOT NULL,
    "batch" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "delivered_at" timestamp with time zone,
    "answered_at" timestamp with time zone,
    "answer_choice" smallint,
    "answer_text" "text",
    "career_id" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("kind" = 'career'::"text") THEN "split_part"("context_key", ':'::"text", 2)
    ELSE NULL::"text"
END) STORED,
    "career_level" integer GENERATED ALWAYS AS (
CASE
    WHEN (("kind" = 'career'::"text") AND ("split_part"("context_key", ':'::"text", 3) ~ '^[0-9]{1,2}$'::"text")) THEN ("split_part"("context_key", ':'::"text", 3))::integer
    ELSE NULL::integer
END) STORED,
    "life_event" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("kind" = 'life'::"text") THEN "split_part"("context_key", ':'::"text", 2)
    ELSE NULL::"text"
END) STORED,
    "model" "text",
    "prompt_context" "jsonb",
    "career_stage" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("kind" = 'career'::"text") THEN ("prompt_context" #>> '{career,stage,key}'::"text"[])
    ELSE NULL::"text"
END) STORED,
    "career_branch" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("kind" = 'career'::"text") THEN ("prompt_context" #>> '{career,branch}'::"text"[])
    ELSE NULL::"text"
END) STORED,
    CONSTRAINT "isekai3d_questions_answer_choice_check" CHECK ((("answer_choice" >= 0) AND ("answer_choice" <= 3))),
    CONSTRAINT "isekai3d_questions_answer_text_check" CHECK (("char_length"("answer_text") <= 300)),
    CONSTRAINT "isekai3d_questions_card_check" CHECK (("octet_length"(("card")::"text") <= 8192)),
    CONSTRAINT "isekai3d_questions_context_key_check" CHECK ((("char_length"("context_key") >= 1) AND ("char_length"("context_key") <= 80))),
    CONSTRAINT "isekai3d_questions_kind_check" CHECK (("kind" = ANY (ARRAY['career'::"text", 'life'::"text", 'explore'::"text"]))),
    CONSTRAINT "isekai3d_questions_model_check" CHECK (("char_length"("model") <= 60)),
    CONSTRAINT "isekai3d_questions_prompt_context_check" CHECK ((("prompt_context" IS NULL) OR ("octet_length"(("prompt_context")::"text") <= 12288)))
);


ALTER TABLE "public"."isekai3d_questions" OWNER TO "postgres";


COMMENT ON TABLE "public"."isekai3d_questions" IS '이세계 3D AI 질문 대기열과 답. 엣지 함수 isekai3d-question 이 3개씩 만들고, isekai3d_question_take 가 하루 1개(한국 시간)만 내준다.';



COMMENT ON COLUMN "public"."isekai3d_questions"."kind" IS 'career = 근무 중 질문 카드, life = 인생의 큰 사건 성찰, explore = 진로 탐색 질문';



COMMENT ON COLUMN "public"."isekai3d_questions"."career_id" IS '근무 카드의 직업 id (isekai3d careers.ts) — context_key 에서 저절로';



COMMENT ON COLUMN "public"."isekai3d_questions"."career_level" IS '근무 카드의 직업 단계(0부터) — context_key 에서 저절로';



COMMENT ON COLUMN "public"."isekai3d_questions"."life_event" IS '성찰 질문의 사건: firstJob · childBorn · parentDied · retired — context_key 에서 저절로';



COMMENT ON COLUMN "public"."isekai3d_questions"."model" IS '질문을 만든 AI 모델';



COMMENT ON COLUMN "public"."isekai3d_questions"."prompt_context" IS 'AI 에 보낸 맥락 그대로(isekai3dPayload) — 학생 이름·학번·학생이 쓴 글은 들어 있지 않다';



COMMENT ON COLUMN "public"."isekai3d_questions"."career_stage" IS '근무 카드의 직업 단계: junior 입문 · expert 전문 · leader 리더 (isekai3d workStages.ts) — prompt_context 에서 저절로';



COMMENT ON COLUMN "public"."isekai3d_questions"."career_branch" IS '근무 카드의 직업 갈래 이름(전문·리더) — prompt_context 에서 저절로';



