CREATE MATERIALIZED VIEW "public"."student_academic_flat" AS
 SELECT "sbi"."id" AS "student_code",
    "sbi"."name",
    (("elem"."value" ->> 'grade'::"text"))::integer AS "grade",
    (("elem"."value" ->> 'semester'::"text"))::integer AS "semester",
    ("elem"."value" ->> 'category'::"text") AS "category",
    ("elem"."value" ->> 'subject_group'::"text") AS "subject_group",
    ("elem"."value" ->> 'subject'::"text") AS "subject",
    (("elem"."value" ->> 'units'::"text"))::numeric AS "units",
    (("elem"."value" ->> 'rank'::"text"))::numeric AS "rank",
    (("elem"."value" ->> 'score'::"text"))::numeric AS "score",
    (("elem"."value" ->> 'average'::"text"))::numeric AS "average",
    (("elem"."value" ->> 'stdDev'::"text"))::numeric AS "std_dev",
    ("elem"."value" ->> 'achievement'::"text") AS "achievement",
    (("elem"."value" ->> 'students'::"text"))::integer AS "students_in_class",
    ("elem"."value" ->> 'content'::"text") AS "content"
   FROM "public"."student_basic_info" "sbi",
    LATERAL "jsonb_array_elements"(COALESCE("sbi"."academic_development", '[]'::"jsonb")) "elem"("value")
  WHERE (("sbi"."academic_development" IS NOT NULL) AND ("jsonb_array_length"("sbi"."academic_development") > 0))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."student_academic_flat" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."student_audience_saved_rule" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "rule" "jsonb" NOT NULL,
    "rule_key" "text" NOT NULL,
    "label" "text" NOT NULL,
    "title" "text",
    "sentence" "text",
    "pinned" boolean DEFAULT false NOT NULL,
    "use_count" integer DEFAULT 1 NOT NULL,
    "last_used_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "target" "text" DEFAULT 'student'::"text" NOT NULL,
    CONSTRAINT "student_audience_saved_rule_label_check" CHECK ((("length"("label") >= 1) AND ("length"("label") <= 500))),
    CONSTRAINT "student_audience_saved_rule_rule_check" CHECK (("jsonb_typeof"("rule") = 'object'::"text")),
    CONSTRAINT "student_audience_saved_rule_rule_key_check" CHECK ((("length"("rule_key") >= 2) AND ("length"("rule_key") <= 8000))),
    CONSTRAINT "student_audience_saved_rule_sentence_check" CHECK ((("sentence" IS NULL) OR ("length"("sentence") <= 500))),
    CONSTRAINT "student_audience_saved_rule_target_check" CHECK (("target" = ANY (ARRAY['student'::"text", 'faculty'::"text"]))),
    CONSTRAINT "student_audience_saved_rule_title_check" CHECK ((("title" IS NULL) OR (("length"("title") >= 1) AND ("length"("title") <= 100))))
);


ALTER TABLE "public"."student_audience_saved_rule" OWNER TO "postgres";


COMMENT ON TABLE "public"."student_audience_saved_rule" IS '조건으로 학생 고르기 — 본인의 최근(별표 없는 것은 최근 8개만)·즐겨찾기 규칙. 명단이 아니라 규칙이라 학기가 바뀌어도 낡지 않는다. 쓰기는 record_student_audience_rule 권장(정리까지 한 번에).';



COMMENT ON COLUMN "public"."student_audience_saved_rule"."target" IS 'student = 학생 규칙(resolve_student_audience) · faculty = 교직원 규칙(resolve_faculty_rule). 모양이 달라 섞어 풀면 안 된다.';



CREATE TABLE IF NOT EXISTS "public"."student_career_submissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "my_id" "text" NOT NULL,
    "student_name" "text",
    "assignment_name" "text" NOT NULL,
    "board_name" "text",
    "teacher_in_charge" "text",
    "deadline" "text",
    "submission_datetime" "text",
    "material_link_url" "text",
    "collected_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "is_self_evaluation" boolean DEFAULT false NOT NULL,
    "self_eval_keyword" "text",
    "self_eval_type" "text" GENERATED ALWAYS AS (
CASE
    WHEN (NOT "is_self_evaluation") THEN NULL::"text"
    WHEN ("self_eval_keyword" ~ '자기|자평|board:'::"text") THEN '자기평가'::"text"
    ELSE '성찰·소감'::"text"
END) STORED
);


ALTER TABLE "public"."student_career_submissions" OWNER TO "postgres";


COMMENT ON TABLE "public"."student_career_submissions" IS '학생 진로 과제 제출. RLS: 학생 본인(my_id=email_prefix) read만, 교사/admin 전권.';



CREATE OR REPLACE VIEW "public"."student_dashboard_view" WITH ("security_invoker"='true') AS
 SELECT "sbi"."id" AS "student_code",
    "r"."id" AS "resource_id",
    "sbi"."name",
    "sbi"."grade",
    "sbi"."class_num",
    "sbi"."number",
    "sbi"."student_no",
    ("r"."meta" ->> 'picture'::"text") AS "picture",
    NULL::"text" AS "phone",
    ("r"."meta" ->> 'career'::"text") AS "career",
    ("r"."meta" ->> 'major'::"text") AS "major",
    ("r"."meta" ->> 'birthday'::"text") AS "birthday",
    "sbi"."section1_personal_info",
    "sbi"."grade_info",
    "sbi"."attendance",
    "sbi"."volunteer",
    "sbi"."reading",
    "sbi"."academic_development",
    "sbi"."created_at",
    "sbi"."updated_at"
   FROM ("public"."student_basic_info" "sbi"
     LEFT JOIN "public"."resource" "r" ON (((("r"."meta" ->> 'id'::"text") = "sbi"."id") AND ("r"."type" = 'student'::"text"))));


ALTER VIEW "public"."student_dashboard_view" OWNER TO "postgres";


COMMENT ON VIEW "public"."student_dashboard_view" IS '학생 통합 정보 뷰 - student_basic_info와 resource를 학번 코드로 연결. 개인 전화번호는 저장하거나 노출하지 않는다.';



