);


ALTER TABLE "public"."student_detailed_activities" OWNER TO "postgres";


COMMENT ON TABLE "public"."student_detailed_activities" IS '학생 세특 데이터. RLS: 학생 본인(student_id=email_prefix) read만, 교사/admin 전권. anon 차단.';



COMMENT ON COLUMN "public"."student_detailed_activities"."segmentation" IS 'S0 활동 분절 결과. { version, generated_at, model, sentences[], activities[], record_level[] }. 한 기록 안의 여러 탐구 활동을 문장 단위로 나눈 것. analysis 컬럼(AI 요약)과는 별개.';



CREATE MATERIALIZED VIEW "public"."student_identity_map" AS
 SELECT "sdv"."student_code",
    "p"."id" AS "profile_id",
    "sdv"."resource_id",
    "sdv"."name",
    "sdv"."grade" AS "current_grade",
    "sdv"."class_num" AS "current_class",
    "sdv"."number" AS "current_number",
    ("r"."meta" ->> 'snum1'::"text") AS "snum1",
    ("r"."meta" ->> 'snum2'::"text") AS "snum2",
    ("r"."meta" ->> 'snum3'::"text") AS "snum3"
   FROM (("public"."student_dashboard_view" "sdv"
     LEFT JOIN "public"."resource" "r" ON (("r"."id" = "sdv"."resource_id")))
     LEFT JOIN "public"."profiles" "p" ON ((("split_part"("p"."email", '@'::"text", 1) = "sdv"."student_code") AND ("p"."role" = 'student'::"text"))))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."student_identity_map" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."student_mock_flat" AS
 SELECT "sbi"."id" AS "student_code",
    "sbi"."name",
    "sim"."current_grade",
    "sim"."current_class",
    (("exam"."value" ->> 'academic_year'::"text"))::integer AS "academic_year",
    (("exam"."value" ->> 'exam_grade'::"text"))::integer AS "exam_grade",
    (("exam"."value" ->> 'exam_month'::"text"))::integer AS "exam_month",
    "subj"."key" AS "subject",
    (("subj"."value" ->> 'raw_score'::"text"))::numeric AS "raw_score",
    (("subj"."value" ->> 'standard_score'::"text"))::numeric AS "standard_score",
    (("subj"."value" ->> 'percentile'::"text"))::numeric AS "percentile",
    (("subj"."value" ->> 'grade'::"text"))::integer AS "grade"
   FROM ((("public"."student_basic_info" "sbi"
     JOIN "public"."student_identity_map" "sim" ON (("sim"."student_code" = "sbi"."id")))
     CROSS JOIN LATERAL "jsonb_array_elements"(COALESCE("sbi"."mock_result", '[]'::"jsonb")) "exam"("value"))
     CROSS JOIN LATERAL "jsonb_each"(("exam"."value" -> 'subjects'::"text")) "subj"("key", "value"))
  WHERE (("sbi"."mock_result" IS NOT NULL) AND ("jsonb_array_length"("sbi"."mock_result") > 0))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."student_mock_flat" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."student_cross_domain_stats" AS
 WITH "academic" AS (
         SELECT "student_academic_flat"."student_code",
                CASE
                    WHEN ("sum"("student_academic_flat"."units") > (0)::numeric) THEN "round"(("sum"(("student_academic_flat"."rank" * "student_academic_flat"."units")) / "sum"("student_academic_flat"."units")), 2)
                    ELSE NULL::numeric
                END AS "academic_avg"
           FROM "public"."student_academic_flat"
          WHERE (("student_academic_flat"."category" = 'regular'::"text") AND ("student_academic_flat"."rank" IS NOT NULL) AND ("student_academic_flat"."units" IS NOT NULL) AND ("student_academic_flat"."units" > (0)::numeric))
          GROUP BY "student_academic_flat"."student_code"
        ), "mock_latest_exam" AS (
         SELECT DISTINCT ON ("student_mock_flat"."student_code") "student_mock_flat"."student_code",
            "student_mock_flat"."academic_year",
            "student_mock_flat"."exam_month"
           FROM "public"."student_mock_flat"
          ORDER BY "student_mock_flat"."student_code", "student_mock_flat"."academic_year" DESC, "student_mock_flat"."exam_month" DESC
        ), "mock_latest" AS (
         SELECT "mle"."student_code",
            "mle"."academic_year" AS "mock_academic_year",
            "mle"."exam_month" AS "mock_exam_month",
            "round"("avg"("smf"."grade"), 1) AS "mock_avg_grade",
            ("count"(*))::integer AS "mock_subject_count"
           FROM ("mock_latest_exam" "mle"
             JOIN "public"."student_mock_flat" "smf" ON ((("smf"."student_code" = "mle"."student_code") AND ("smf"."academic_year" = "mle"."academic_year") AND ("smf"."exam_month" = "mle"."exam_month"))))
          GROUP BY "mle"."student_code", "mle"."academic_year", "mle"."exam_month"
        ), "study_room" AS (
         SELECT "sim_1"."student_code",
            ("count"(*))::integer AS "sr_total",
            ("count"(*) FILTER (WHERE ("sr_1"."is_attended" = true)))::integer AS "sr_attended",
                CASE
                    WHEN ("count"(*) > 0) THEN "round"(((("count"(*) FILTER (WHERE ("sr_1"."is_attended" = true)))::numeric / ("count"(*))::numeric) * (100)::numeric), 1)
                    ELSE (0)::numeric
                END AS "sr_rate"
           FROM ("public"."seat_reservations" "sr_1"
             JOIN "public"."student_identity_map" "sim_1" ON (("sim_1"."profile_id" = "sr_1"."student_id")))
          WHERE (EXTRACT(year FROM "sr_1"."reservation_date") = EXTRACT(year FROM CURRENT_DATE))
          GROUP BY "sim_1"."student_code"
        ), "reading" AS (
         SELECT "sbi"."id" AS "student_code",
                CASE
                    WHEN ("jsonb_typeof"("sbi"."reading") = 'array'::"text") THEN "jsonb_array_length"("sbi"."reading")
                    ELSE 0
                END AS "reading_count"
           FROM "public"."student_basic_info" "sbi"
          WHERE (("sbi"."reading" IS NOT NULL) AND ("jsonb_typeof"("sbi"."reading") = 'array'::"text"))
        ), "activity" AS (
         SELECT "sda"."student_id" AS "student_code",
            ("count"(*))::integer AS "activity_total",
            ("count"(*) FILTER (WHERE ("sda"."category" = 'regular'::"text")))::integer AS "activity_regular",
            (COALESCE("sum"((("sda"."data" ->> '시간'::"text"))::integer) FILTER (WHERE ("sda"."category" = ANY (ARRAY['자율활동'::"text", '동아리활동'::"text", '진로활동'::"text"]))), (0)::bigint))::integer AS "creative_hours"
           FROM "public"."student_detailed_activities" "sda"
          GROUP BY "sda"."student_id"
        ), "att_rows" AS (
         SELECT "sbi"."id" AS "student_code",
            "jsonb_array_elements"("sbi"."attendance") AS "att"
           FROM "public"."student_basic_info" "sbi"
          WHERE (("sbi"."attendance" IS NOT NULL) AND ("jsonb_typeof"("sbi"."attendance") = 'array'::"text"))
        ), "att_parsed" AS (
         SELECT "att_rows"."student_code",
            (("att_rows"."att" ->> 'grade'::"text"))::integer AS "grade",
            (("att_rows"."att" ->> 'schoolDays'::"text"))::integer AS "school_days",
            ((COALESCE(((("att_rows"."att" -> 'absence'::"text") ->> 'disease'::"text"))::integer, 0) + COALESCE(((("att_rows"."att" -> 'absence'::"text") ->> 'unapproved'::"text"))::integer, 0)) + COALESCE(((("att_rows"."att" -> 'absence'::"text") ->> 'other'::"text"))::integer, 0)) AS "total_absence",
            ((COALESCE(((("att_rows"."att" -> 'tardiness'::"text") ->> 'disease'::"text"))::integer, 0) + COALESCE(((("att_rows"."att" -> 'tardiness'::"text") ->> 'unapproved'::"text"))::integer, 0)) + COALESCE(((("att_rows"."att" -> 'tardiness'::"text") ->> 'other'::"text"))::integer, 0)) AS "total_tardiness"
           FROM "att_rows"
        ), "attendance" AS (
         SELECT DISTINCT ON ("att_parsed"."student_code") "att_parsed"."student_code",
            "att_parsed"."grade" AS "att_grade",
            "att_parsed"."school_days",
            "att_parsed"."total_absence",
            "att_parsed"."total_tardiness",
                CASE
                    WHEN ("att_parsed"."school_days" > 0) THEN "round"((((("att_parsed"."school_days" - "att_parsed"."total_absence"))::numeric / ("att_parsed"."school_days")::numeric) * (100)::numeric), 1)
                    ELSE NULL::numeric
                END AS "attendance_rate"
           FROM "att_parsed"
          ORDER BY "att_parsed"."student_code", "att_parsed"."grade" DESC
        ), "vol_rows" AS (
         SELECT "sbi"."id" AS "student_code",
            "jsonb_array_elements"("sbi"."volunteer") AS "vol"
           FROM "public"."student_basic_info" "sbi"
          WHERE (("sbi"."volunteer" IS NOT NULL) AND ("jsonb_typeof"("sbi"."volunteer") = 'array'::"text"))
        ), "volunteer" AS (
         SELECT "vol_rows"."student_code",
            (COALESCE("sum"(COALESCE((("vol_rows"."vol" ->> 'hours'::"text"))::integer, 0)), (0)::bigint))::integer AS "volunteer_hours",
            ("count"(*))::integer AS "volunteer_count",
            COALESCE("max"(COALESCE((("vol_rows"."vol" ->> 'cumulativeHours'::"text"))::integer, 0)), 0) AS "volunteer_cumulative"
           FROM "vol_rows"
          GROUP BY "vol_rows"."student_code"
        ), "engagement" AS (
         SELECT "sbi"."id" AS "student_code",
            (COALESCE("ae_agg"."total", (0)::bigint))::integer AS "afterschool_total",
            (COALESCE("cs_agg"."total", (0)::bigint))::integer AS "career_submissions_total",
            (COALESCE("cs_agg"."on_time", (0)::bigint))::integer AS "career_on_time"
           FROM (("public"."student_basic_info" "sbi"
             LEFT JOIN ( SELECT "afterschool_enrollments"."student_id",
                    "count"(*) AS "total"
                   FROM "public"."afterschool_enrollments"
                  GROUP BY "afterschool_enrollments"."student_id") "ae_agg" ON (("ae_agg"."student_id" = "sbi"."id")))
             LEFT JOIN ( SELECT "student_career_submissions"."my_id",
                    "count"(*) AS "total",
                    "count"(*) FILTER (WHERE (("student_career_submissions"."submission_datetime" IS NOT NULL) AND ("student_career_submissions"."submission_datetime" <> ''::"text") AND ("student_career_submissions"."deadline" IS NOT NULL) AND ("student_career_submissions"."submission_datetime" <= "student_career_submissions"."deadline"))) AS "on_time"
                   FROM "public"."student_career_submissions"
                  GROUP BY "student_career_submissions"."my_id") "cs_agg" ON (("cs_agg"."my_id" = "sbi"."id")))
          WHERE (("ae_agg"."total" IS NOT NULL) OR ("cs_agg"."total" IS NOT NULL))
        )
 SELECT "sim"."student_code",
    "sim"."name",
    "sim"."current_grade",
    "sim"."current_class",
    "sim"."current_number",
    "a"."academic_avg",
    "ml"."mock_avg_grade",
    "ml"."mock_academic_year",
    "ml"."mock_exam_month",
    "ml"."mock_subject_count",
    COALESCE("sr"."sr_total", 0) AS "study_room_total",
    COALESCE("sr"."sr_attended", 0) AS "study_room_attended",
    COALESCE("sr"."sr_rate", (0)::numeric) AS "study_room_rate",
    COALESCE("r"."reading_count", 0) AS "reading_count",
    COALESCE("act"."activity_total", 0) AS "activity_total",
    COALESCE("act"."activity_regular", 0) AS "activity_regular",
    COALESCE("act"."creative_hours", 0) AS "creative_hours",
    "att"."att_grade",
    "att"."school_days",
    "att"."total_absence",
    "att"."total_tardiness",
    "att"."attendance_rate",
    COALESCE("v"."volunteer_hours", 0) AS "volunteer_hours",
    COALESCE("v"."volunteer_count", 0) AS "volunteer_count",
    COALESCE("v"."volunteer_cumulative", 0) AS "volunteer_cumulative",
    COALESCE("e"."afterschool_total", 0) AS "afterschool_total",
    COALESCE("e"."career_submissions_total", 0) AS "career_submissions_total",
    COALESCE("e"."career_on_time", 0) AS "career_on_time"
   FROM (((((((("public"."student_identity_map" "sim"
     LEFT JOIN "academic" "a" ON (("a"."student_code" = "sim"."student_code")))
     LEFT JOIN "mock_latest" "ml" ON (("ml"."student_code" = "sim"."student_code")))
     LEFT JOIN "study_room" "sr" ON (("sr"."student_code" = "sim"."student_code")))
     LEFT JOIN "reading" "r" ON (("r"."student_code" = "sim"."student_code")))
     LEFT JOIN "activity" "act" ON (("act"."student_code" = "sim"."student_code")))
     LEFT JOIN "attendance" "att" ON (("att"."student_code" = "sim"."student_code")))
     LEFT JOIN "volunteer" "v" ON (("v"."student_code" = "sim"."student_code")))
     LEFT JOIN "engagement" "e" ON (("e"."student_code" = "sim"."student_code")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."student_cross_domain_stats" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."student_cross_domain_stats" IS '10-domain pre-computed stats. Replaces N+1 get_student_cross_domain_stats() calls. Refresh: SELECT refresh_student_cross_domain_stats();';



CREATE TABLE IF NOT EXISTS "public"."student_enrollment" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "academic_year" integer NOT NULL,
    "semester" integer NOT NULL,
    "subject_name" "text" NOT NULL,
    "credits" integer,
    "classroom" "text",
