CREATE MATERIALIZED VIEW "public"."student_timetable_flat" AS
 SELECT "st"."resource_id",
    "r"."name" AS "student_name",
    ("r"."meta" ->> 'id'::"text") AS "student_code",
    "st"."student_grade" AS "grade",
    "st"."student_class" AS "class_num",
    "st"."student_no" AS "number",
    ("r"."meta" ->> 'picture'::"text") AS "picture",
    "st"."day_of_week",
    "st"."period",
    "st"."subject",
    "st"."teacher_name",
    "st"."academic_year",
    "st"."semester"
   FROM ("public"."student_timetable" "st"
     JOIN "public"."resource" "r" ON (("r"."id" = "st"."resource_id")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."student_timetable_flat" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."student_timetable_flat" IS 'student_timetable 평탄화(학생 인적사항 조인). MV 는 RLS 를 가질 수 없어 authenticated 에 GRANT 하지 않고 get_section_students DEFINER RPC 로만 읽는다.';



