    CONSTRAINT "task_action_check_evidence_check" CHECK (("jsonb_typeof"("evidence") = 'object'::"text")),
    CONSTRAINT "task_action_check_label_check" CHECK ((("length"("btrim"("label")) >= 1) AND ("length"("btrim"("label")) <= 160))),
    CONSTRAINT "task_action_check_status_check" CHECK (("status" = ANY (ARRAY['pass'::"text", 'warn'::"text", 'fail'::"text"])))
);

ALTER TABLE ONLY "public"."task_action_check" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."task_action_check" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_action_check" IS 'WORK 실행 종료 시 생성되는 기계 검증 결과. 실행당 check_key는 한 번만 기록된다.';



CREATE TABLE IF NOT EXISTS "public"."task_action_review" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_id" "uuid" NOT NULL,
    "reviewer_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "decision" "text" NOT NULL,
    "comment" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "task_action_review_decision_check" CHECK (("decision" = ANY (ARRAY['accepted'::"text", 'needs_changes'::"text"])))
);

ALTER TABLE ONLY "public"."task_action_review" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."task_action_review" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_action_review" IS '사용자가 WORK 실행 결과를 승인하거나 보완 요청한 감사 이력.';



CREATE TABLE IF NOT EXISTS "public"."task_action_run" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "action_id" "uuid" NOT NULL,
    "workflow_id" "uuid",
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "status" "text" DEFAULT 'running'::"text" NOT NULL,
    "input_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "output_summary" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "error_summary" "text",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "task_action_run_idempotency_key_check" CHECK ((("length"("btrim"("idempotency_key")) >= 1) AND ("length"("btrim"("idempotency_key")) <= 160))),
    CONSTRAINT "task_action_run_input_snapshot_check" CHECK (("jsonb_typeof"("input_snapshot") = 'object'::"text")),
    CONSTRAINT "task_action_run_output_summary_check" CHECK (("jsonb_typeof"("output_summary") = 'object'::"text")),
    CONSTRAINT "task_action_run_status_check" CHECK (("status" = ANY (ARRAY['created'::"text", 'running'::"text", 'needs_review'::"text", 'accepted'::"text", 'needs_changes'::"text", 'failed'::"text", 'cancelled'::"text"])))
);

ALTER TABLE ONLY "public"."task_action_run" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."task_action_run" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_action_run" IS 'WORK 실행 시도와 입력 스냅샷, 결과 요약 및 현재 검수 상태.';



CREATE TABLE IF NOT EXISTS "public"."task_action_run_log" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "run_id" "uuid" NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "log_type" "text" NOT NULL,
    "from_status" "text",
    "to_status" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sequence_no" integer NOT NULL,
    CONSTRAINT "task_action_run_log_from_status_check" CHECK ((("from_status" IS NULL) OR ("from_status" = ANY (ARRAY['created'::"text", 'running'::"text", 'needs_review'::"text", 'accepted'::"text", 'needs_changes'::"text", 'failed'::"text", 'cancelled'::"text"])))),
    CONSTRAINT "task_action_run_log_log_type_check" CHECK (("log_type" = ANY (ARRAY['started'::"text", 'finalized'::"text", 'reviewed'::"text"]))),
    CONSTRAINT "task_action_run_log_payload_check" CHECK (("jsonb_typeof"("payload") = 'object'::"text")),
    CONSTRAINT "task_action_run_log_sequence_positive" CHECK (("sequence_no" > 0)),
    CONSTRAINT "task_action_run_log_to_status_check" CHECK (("to_status" = ANY (ARRAY['created'::"text", 'running'::"text", 'needs_review'::"text", 'accepted'::"text", 'needs_changes'::"text", 'failed'::"text", 'cancelled'::"text"])))
);

ALTER TABLE ONLY "public"."task_action_run_log" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."task_action_run_log" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_action_run_log" IS 'WORK RUN의 시작, 종료, 검수 상태 전이를 보존하는 append-only 이벤트 이력.';



COMMENT ON COLUMN "public"."task_action_run_log"."sequence_no" IS 'RUN 안에서 이벤트가 발생한 의미 순서를 보장하는 1부터 시작하는 순번.';



CREATE TABLE IF NOT EXISTS "public"."task_ai_suggestion" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "work_id" "uuid" NOT NULL,
    "task_id" "uuid",
    "kind" "text" NOT NULL,
    "input_hash" "text" NOT NULL,
    "model" "text",
    "result" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "usage" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "decisions" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "task_ai_suggestion_kind_check" CHECK (("kind" = ANY (ARRAY['work_check'::"text", 'table_tidy'::"text", 'table_to_text'::"text"]))),
    CONSTRAINT "task_ai_suggestion_result_size" CHECK (("octet_length"(("result")::"text") <= 256000))
);


ALTER TABLE "public"."task_ai_suggestion" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_ai_suggestion" IS '업무 진행 화면의 AI 버튼 결과 — 같은 입력 재호출을 막는 캐시이자 [적용]/[무시] 기록(수락률).';



CREATE TABLE IF NOT EXISTS "public"."task_document_analysis" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    "file_name" "text" NOT NULL,
    "file_size" bigint NOT NULL,
    "mime_type" "text" DEFAULT ''::"text" NOT NULL,
    "format" "text" NOT NULL,
    "file_sha256" "text" NOT NULL,
    "document_key" "text" NOT NULL,
    "parser_version" "text" NOT NULL,
    "prompt_version" "text" NOT NULL,
    "model" "text" NOT NULL,
    "analysis_result" "jsonb" NOT NULL,
    "status" "text" DEFAULT 'analyzed'::"text" NOT NULL,
    "revision_of" "uuid",
    "applied_event_id" "uuid",
    "applied_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "task_document_analysis_analysis_result_check" CHECK (("jsonb_typeof"("analysis_result") = 'object'::"text")),
    CONSTRAINT "task_document_analysis_file_sha256_check" CHECK (("file_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "task_document_analysis_file_size_check" CHECK (("file_size" >= 0)),
    CONSTRAINT "task_document_analysis_format_check" CHECK (("format" = ANY (ARRAY['hwpx'::"text", 'pdf'::"text", 'text'::"text", 'hwp'::"text", 'unknown'::"text"]))),
    CONSTRAINT "task_document_analysis_status_check" CHECK (("status" = ANY (ARRAY['analyzed'::"text", 'reviewed'::"text", 'applied'::"text"])))
);

ALTER TABLE ONLY "public"."task_document_analysis" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."task_document_analysis" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_document_analysis" IS '업무 관리에서 실행한 문서 분석 결과. 원문 파일은 저장하지 않고 해시와 구조화 결과만 보관한다.';



CREATE TABLE IF NOT EXISTS "public"."task_document_analysis_decision" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "analysis_id" "uuid" NOT NULL,
    "candidate_local_id" "text" NOT NULL,
    "decision" "text" NOT NULL,
    "linked_event_id" "uuid",
    "linked_task_id" "uuid",
    "created_task_id" "uuid",
    "decided_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "task_document_analysis_decision_check" CHECK (((("decision" = 'link_event'::"text") AND ("linked_event_id" IS NOT NULL) AND ("linked_task_id" IS NULL)) OR (("decision" = 'link_task'::"text") AND ("linked_task_id" IS NOT NULL)) OR (("decision" = ANY (ARRAY['create'::"text", 'exclude'::"text"])) AND ("linked_event_id" IS NULL) AND ("linked_task_id" IS NULL)))),
    CONSTRAINT "task_document_analysis_decision_decision_check" CHECK (("decision" = ANY (ARRAY['create'::"text", 'exclude'::"text", 'link_event'::"text", 'link_task'::"text"])))
);

ALTER TABLE ONLY "public"."task_document_analysis_decision" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."task_document_analysis_decision" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_document_analysis_decision" IS '문서 분석 후보별 사용자 검토 결정과 기존 event/task 연결 이력.';



CREATE TABLE IF NOT EXISTS "public"."task_message_send" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
