    "unlinked_names" "text"[] DEFAULT '{}'::"text"[] NOT NULL
);


ALTER TABLE "public"."task_message_send" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_message_send" IS '할 일 작업 「메시지 보내기」의 발송 기록. 알림은 notification_events(type task_message), 쿨메신저는 사람이 직접 보낸다.';



CREATE TABLE IF NOT EXISTS "public"."task_submission" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "task_id" "uuid" NOT NULL,
    "assignee_resource_id" "uuid" NOT NULL,
    "submitted_by" "uuid" NOT NULL,
    "file_name" "text" NOT NULL,
    "file_url" "text",
    "edit_url" "text",
    "google_drive_id" "text",
    "mime_type" "text",
    "file_size" bigint,
    "meta" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "unit_key" "text",
    "kind" "text" DEFAULT 'file'::"text" NOT NULL,
    "spec_document_id" "uuid",
    "spreadsheet_data" "jsonb",
    CONSTRAINT "task_submission_kind_check" CHECK (("kind" = ANY (ARRAY['file'::"text", 'spec'::"text", 'spreadsheet'::"text", 'physical'::"text"]))),
    CONSTRAINT "task_submission_kind_shape" CHECK (((("kind" = 'file'::"text") AND ("file_url" IS NOT NULL) AND ("spec_document_id" IS NULL) AND ("spreadsheet_data" IS NULL)) OR (("kind" = 'spec'::"text") AND ("spec_document_id" IS NOT NULL) AND ("spreadsheet_data" IS NULL)) OR (("kind" = 'spreadsheet'::"text") AND ("file_url" IS NULL) AND ("spec_document_id" IS NULL) AND ("spreadsheet_data" IS NOT NULL) AND ("jsonb_typeof"("spreadsheet_data") = 'object'::"text") AND ("jsonb_typeof"(("spreadsheet_data" -> 'columns'::"text")) = 'array'::"text") AND ("jsonb_typeof"(("spreadsheet_data" -> 'rows'::"text")) = 'array'::"text")) OR (("kind" = 'physical'::"text") AND ("file_url" IS NULL) AND ("spec_document_id" IS NULL) AND ("spreadsheet_data" IS NULL))))
);

ALTER TABLE ONLY "public"."task_submission" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."task_submission" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_submission" IS '업무 담당자별 파일 제출 기록. 파일 실체는 Google 공용 드라이브. 제출 유무가 담당자 완료 상태를 결정한다(submit_task_submission / delete_task_submission RPC).';



COMMENT ON COLUMN "public"."task_submission"."kind" IS '제출 방식: file=파일 업로드(Drive), spec=스펙 기반 값 제출(task_work_document 참조)';



COMMENT ON COLUMN "public"."task_submission"."spec_document_id" IS 'kind=spec 일 때 제출된 값 문서. on delete restrict — 제출 행을 먼저 지워야 문서를 지울 수 있다';



CREATE OR REPLACE VIEW "public"."task_spec_submission_view" WITH ("security_invoker"='true') AS
 SELECT "s"."id" AS "submission_id",
    "s"."task_id",
    "s"."assignee_resource_id",
    "r"."name" AS "assignee_name",
    "s"."unit_key",
    "s"."created_at" AS "submitted_at",
    (("s"."meta" ->> 'resubmitted_at'::"text"))::timestamp with time zone AS "resubmitted_at",
    "d"."id" AS "document_id",
    "d"."title",
    "d"."version",
    "d"."template_version_id",
    "d"."plan",
    "d"."field_values",
    "d"."row_values"
   FROM (("public"."task_submission" "s"
     JOIN "public"."task_action_document" "d" ON (("d"."id" = "s"."spec_document_id")))
     LEFT JOIN "public"."resource" "r" ON (("r"."id" = "s"."assignee_resource_id")))
  WHERE ("s"."kind" = 'spec'::"text");


ALTER VIEW "public"."task_spec_submission_view" OWNER TO "postgres";


COMMENT ON VIEW "public"."task_spec_submission_view" IS '스펙 기반 값 제출 평탄화 — security_invoker 로 하부 RLS 계승. knowledge 는 개인정보 우려로 제외';



