CREATE TABLE IF NOT EXISTS "public"."task_workflow_edge" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workflow_id" "uuid" NOT NULL,
    "source_node_id" "uuid" NOT NULL,
    "target_node_id" "uuid" NOT NULL,
    "relation_type" "text" DEFAULT 'flow'::"text" NOT NULL,
    "label" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "task_workflow_edge_not_self" CHECK (("source_node_id" <> "target_node_id")),
    CONSTRAINT "task_workflow_edge_relation_type_check" CHECK (("relation_type" = ANY (ARRAY['flow'::"text", 'contains'::"text", 'depends_on'::"text", 'handoff'::"text", 'related'::"text", 'action'::"text"])))
);


ALTER TABLE "public"."task_workflow_edge" OWNER TO "postgres";


COMMENT ON TABLE "public"."task_workflow_edge" IS 'Typed relationships between nodes in a task workflow.';



CREATE TABLE IF NOT EXISTS "public"."task_workflow_node" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workflow_id" "uuid" NOT NULL,
    "node_kind" "text" NOT NULL,
    "event_id" "uuid",
    "task_id" "uuid",
    "label" "text" NOT NULL,
    "position_x" double precision DEFAULT 0 NOT NULL,
    "position_y" double precision DEFAULT 0 NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "action_id" "uuid",
    CONSTRAINT "task_workflow_node_kind_reference_check" CHECK (((("node_kind" = 'event'::"text") AND ("task_id" IS NULL) AND ("action_id" IS NULL)) OR (("node_kind" = 'task'::"text") AND ("event_id" IS NULL) AND ("action_id" IS NULL)) OR (("node_kind" = 'action'::"text") AND ("event_id" IS NULL) AND ("task_id" IS NULL) AND ("action_id" IS NOT NULL)) OR (("node_kind" = ANY (ARRAY['note'::"text", 'region'::"text"])) AND ("event_id" IS NULL) AND ("task_id" IS NULL) AND ("action_id" IS NULL)))),
    CONSTRAINT "task_workflow_node_label_check" CHECK ((("length"("btrim"("label")) >= 1) AND ("length"("btrim"("label")) <= 200))),
    CONSTRAINT "task_workflow_node_node_kind_check" CHECK (("node_kind" = ANY (ARRAY['event'::"text", 'task'::"text", 'note'::"text", 'region'::"text", 'action'::"text"])))
