CREATE MATERIALIZED VIEW "public"."temperature_rankings_mv" AS
 WITH "daily_stats" AS (
         SELECT "seat_reservations"."student_id",
            "seat_reservations"."reservation_date",
            "count"(*) AS "total_daily_reservations",
            "count"(*) FILTER (WHERE ("seat_reservations"."is_attended" = true)) AS "attended_daily_reservations",
            "count"(*) FILTER (WHERE (("seat_reservations"."is_attended" = false) AND ("seat_reservations"."reservation_date" < CURRENT_DATE))) AS "absent_daily_reservations"
           FROM "public"."seat_reservations"
          GROUP BY "seat_reservations"."student_id", "seat_reservations"."reservation_date"
        ), "student_scores" AS (
         SELECT "daily_stats"."student_id",
            "sum"((((("daily_stats"."attended_daily_reservations")::double precision * (0.5)::double precision) / ("daily_stats"."total_daily_reservations")::double precision) - ((("daily_stats"."absent_daily_reservations")::double precision * (1.0)::double precision) / ("daily_stats"."total_daily_reservations")::double precision))) AS "total_score_change",
            "sum"(
                CASE
                    WHEN ("to_char"(("daily_stats"."reservation_date")::timestamp with time zone, 'YYYY-MM'::"text") = "to_char"((CURRENT_DATE)::timestamp with time zone, 'YYYY-MM'::"text")) THEN (((("daily_stats"."attended_daily_reservations")::double precision * (0.5)::double precision) / ("daily_stats"."total_daily_reservations")::double precision) - ((("daily_stats"."absent_daily_reservations")::double precision * (1.0)::double precision) / ("daily_stats"."total_daily_reservations")::double precision))
                    ELSE (0)::double precision
                END) AS "monthly_score_change"
           FROM "daily_stats"
          GROUP BY "daily_stats"."student_id"
        ), "feedback_bonus" AS (
         SELECT "seat_reservations"."student_id",
            (("count"(*) FILTER (WHERE ("seat_reservations"."feedback_rating" IS NOT NULL)))::numeric * 0.1) AS "total_feedback_bonus",
            (("count"(*) FILTER (WHERE (("seat_reservations"."feedback_rating" IS NOT NULL) AND ("to_char"(("seat_reservations"."reservation_date")::timestamp with time zone, 'YYYY-MM'::"text") = "to_char"((CURRENT_DATE)::timestamp with time zone, 'YYYY-MM'::"text")))))::numeric * 0.1) AS "monthly_feedback_bonus"
           FROM "public"."seat_reservations"
          GROUP BY "seat_reservations"."student_id"
        )
 SELECT "rank"() OVER (ORDER BY (((28.0)::double precision + COALESCE("ss"."total_score_change", (0)::double precision)) + (COALESCE("fb"."total_feedback_bonus", (0)::numeric))::double precision) DESC, "p"."name") AS "rank",
    "p"."id" AS "student_id",
    "p"."name",
    "sbi"."grade",
    "sbi"."class_num" AS "class",
    "round"(((((28.0)::double precision + COALESCE("ss"."total_score_change", (0)::double precision)) + (COALESCE("fb"."total_feedback_bonus", (0)::numeric))::double precision))::numeric, 1) AS "temperature",
    "round"(((COALESCE("ss"."monthly_score_change", (0)::double precision) + (COALESCE("fb"."monthly_feedback_bonus", (0)::numeric))::double precision))::numeric, 1) AS "monthly_change"
   FROM ((("public"."profiles" "p"
     JOIN "student_scores" "ss" ON (("p"."id" = "ss"."student_id")))
     LEFT JOIN "feedback_bonus" "fb" ON (("p"."id" = "fb"."student_id")))
     LEFT JOIN "public"."student_basic_info" "sbi" ON (("sbi"."id" = "split_part"("p"."email", '@'::"text", 1))))
  WHERE ("p"."role" = 'student'::"text")
  ORDER BY ("round"(((((28.0)::double precision + COALESCE("ss"."total_score_change", (0)::double precision)) + (COALESCE("fb"."total_feedback_bonus", (0)::numeric))::double precision))::numeric, 1)) DESC, "p"."name"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."temperature_rankings_mv" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."timetable_override" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "kind" "text" DEFAULT 'other'::"text" NOT NULL,
    "academic_year" integer NOT NULL,
    "semester" integer NOT NULL,
    "start_date" "date" NOT NULL,
    "end_date" "date" NOT NULL,
    "grades" smallint[],
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "note" "text",
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "timetable_override_dates" CHECK ((("end_date" >= "start_date") AND (("end_date" - "start_date") <= 366))),
    CONSTRAINT "timetable_override_grades" CHECK ((("grades" IS NULL) OR ((("cardinality"("grades") >= 1) AND ("cardinality"("grades") <= 3)) AND ("grades" <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint])))),
    CONSTRAINT "timetable_override_kind_check" CHECK (("kind" = ANY (ARRAY['exam'::"text", 'csat'::"text", 'special'::"text", 'other'::"text"]))),
    CONSTRAINT "timetable_override_note_check" CHECK ((("note" IS NULL) OR ("char_length"("note") <= 1000))),
    CONSTRAINT "timetable_override_semester_check" CHECK (("semester" = ANY (ARRAY[1, 2]))),
    CONSTRAINT "timetable_override_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"]))),
    CONSTRAINT "timetable_override_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 100)))
);


