CREATE OR REPLACE VIEW "public"."training_progress_view" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "resource_id",
    "r"."name" AS "teacher_name",
    "tt"."id" AS "training_type_id",
    "tt"."code" AS "training_code",
    "tt"."name" AS "training_name",
    "tt"."category",
    "tt"."required_hours",
    (COALESCE("sum"("tc"."hours"), (0)::numeric))::numeric(7,1) AS "completed_hours",
    "count"("tc"."id") AS "entries"
   FROM (("public"."resource" "r"
     CROSS JOIN "public"."training_types" "tt")
     LEFT JOIN "public"."training_certificates" "tc" ON ((("tc"."resource_id" = "r"."id") AND ("tc"."training_type_id" = "tt"."id"))))
  WHERE (("r"."type" = 'teacher'::"text") AND ("tt"."is_active" = true))
  GROUP BY "r"."id", "r"."name", "tt"."id", "tt"."code", "tt"."name", "tt"."category", "tt"."required_hours";


ALTER VIEW "public"."training_progress_view" OWNER TO "postgres";


COMMENT ON VIEW "public"."training_progress_view" IS '교사 × 연수종류별 이수 시간/건수 집계 (승인 개념 없음)';



