CREATE TABLE IF NOT EXISTS "public"."work_knowledge" (
    "id" bigint NOT NULL,
    "work_id" "uuid" NOT NULL,
    "task_id" "uuid",
    "action_type" "text",
    "kind" "text" NOT NULL,
    "title" "text" NOT NULL,
    "body" "text" NOT NULL,
    "basis" "text",
    "suggestions" "jsonb",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "author_resource_id" "uuid",
    "author_role" "text" DEFAULT 'other'::"text" NOT NULL,
    "via" "text" DEFAULT 'web'::"text" NOT NULL,
    "archived_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "action_id" "uuid",
    CONSTRAINT "work_knowledge_archived_reason_check" CHECK ((("archived_reason" IS NULL) OR ("length"("archived_reason") <= 500))),
    CONSTRAINT "work_knowledge_author_role_check" CHECK (("author_role" = ANY (ARRAY['manager'::"text", 'assignee'::"text", 'admin'::"text", 'other'::"text", 'system'::"text"]))),
    CONSTRAINT "work_knowledge_basis_check" CHECK ((("basis" IS NULL) OR ("length"("basis") <= 1000))),
    CONSTRAINT "work_knowledge_body_check" CHECK ((("length"("btrim"("body")) >= 1) AND ("length"("btrim"("body")) <= 4000))),
    CONSTRAINT "work_knowledge_kind_check" CHECK (("kind" = ANY (ARRAY['procedure'::"text", 'tip'::"text", 'caution'::"text", 'reference'::"text", 'insight'::"text"]))),
    CONSTRAINT "work_knowledge_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'archived'::"text"]))),
    CONSTRAINT "work_knowledge_suggestions_check" CHECK ((("suggestions" IS NULL) OR ("jsonb_typeof"("suggestions") = 'array'::"text"))),
    CONSTRAINT "work_knowledge_title_check" CHECK ((("length"("btrim"("title")) >= 1) AND ("length"("btrim"("title")) <= 200))),
    CONSTRAINT "work_knowledge_via_check" CHECK (("via" = ANY (ARRAY['web'::"text", 'mcp'::"text", 'system'::"text"])))
);


ALTER TABLE "public"."work_knowledge" OWNER TO "postgres";


COMMENT ON TABLE "public"."work_knowledge" IS '업무 수행 지식(2026-10-24) — 절차·요령·주의·참고·인사이트. 읽기 = 그 업무 또는 이어받은 업무(«지난 업무 가져오기» 계보)의 책임자, 쓰기 = 책임자. 지우지 않고 보관한다.';



