CREATE POLICY "Admins can do everything on profiles" ON "contest"."profiles" TO "authenticated" USING ("contest"."is_admin"()) WITH CHECK ("contest"."is_admin"());



CREATE POLICY "Authenticated users can view profiles" ON "contest"."profiles" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "Public read system_settings" ON "contest"."system_settings" FOR SELECT USING (true);



CREATE POLICY "System can create notifications" ON "contest"."notification_events" FOR INSERT WITH CHECK (true);



CREATE POLICY "Users can delete notifications for their resource" ON "contest"."notification_events" FOR DELETE USING ("contest"."owns_notification_resource"("resource_id"));



CREATE POLICY "Users can insert their own profile" ON "contest"."profiles" FOR INSERT TO "authenticated" WITH CHECK ((( SELECT "auth"."uid"() AS "uid") = "id"));



CREATE POLICY "Users can manage their own resource" ON "contest"."resource" USING ((EXISTS ( SELECT 1
   FROM "contest"."user_resource" "ur"
  WHERE (("ur"."resource_id" = "resource"."id") AND ("ur"."user_id" = ( SELECT "auth"."uid"() AS "uid"))))));



CREATE POLICY "Users can update notifications for their resource" ON "contest"."notification_events" FOR UPDATE USING ("contest"."owns_notification_resource"("resource_id"));



CREATE POLICY "Users can update their own profile" ON "contest"."profiles" FOR UPDATE TO "authenticated" USING (("email" = ("auth"."jwt"() ->> 'email'::"text"))) WITH CHECK (("email" = ("auth"."jwt"() ->> 'email'::"text")));



CREATE POLICY "Users can view notifications for their resource" ON "contest"."notification_events" FOR SELECT USING ("contest"."owns_notification_resource"("resource_id"));



ALTER TABLE "contest"."academy_book_recommendations" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "academy_book_recommendations_read" ON "contest"."academy_book_recommendations" FOR SELECT TO "authenticated" USING (true);



CREATE POLICY "academy_catalog_read" ON "contest"."academy_shop_items" FOR SELECT TO "authenticated" USING ((("academy_owner" IS NULL) OR "is_active" OR ("academy_owner" = ( SELECT "auth"."uid"() AS "uid")) OR ( SELECT "contest_private"."workshop_admin"() AS "workshop_admin") OR (EXISTS ( SELECT 1
   FROM "contest"."academy_user_items" "owned"
  WHERE (("owned"."item_id" = "academy_shop_items"."id") AND ("owned"."user_id" = ( SELECT "auth"."uid"() AS "uid")))))));



ALTER TABLE "contest"."academy_chapter_rewards" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "academy_chapter_rewards_owner_read" ON "contest"."academy_chapter_rewards" FOR SELECT TO "authenticated" USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



ALTER TABLE "contest"."academy_chapters" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "academy_chapters_owner_read" ON "contest"."academy_chapters" FOR SELECT TO "authenticated" USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



CREATE POLICY "academy_commission_read" ON "contest"."academy_workshop_commissions" FOR SELECT TO "authenticated" USING ((("recipient_id" = ( SELECT "auth"."uid"() AS "uid")) OR ( SELECT "contest_private"."workshop_admin"() AS "workshop_admin")));



ALTER TABLE "contest"."academy_daily_conversations" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "academy_daily_owner_read" ON "contest"."academy_daily_conversations" FOR SELECT TO "authenticated" USING ((( SELECT "auth"."uid"() AS "uid") = "user_id"));



ALTER TABLE "contest"."academy_daily_reviews" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "academy_discovery_owner_read" ON "contest"."academy_self_discoveries" FOR SELECT TO "authenticated" USING ((( SELECT "auth"."uid"() AS "uid") = "user_id"));



CREATE POLICY "academy_encouragement_owner_read" ON "contest"."academy_luon_encouragements" FOR SELECT TO "authenticated" USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



CREATE POLICY "academy_experience_owner" ON "contest"."academy_experience_records" FOR SELECT TO "authenticated" USING ((("owner_id" = ( SELECT "auth"."uid"() AS "uid")) AND (EXISTS ( SELECT 1
   FROM "contest"."profiles"
  WHERE (("profiles"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("profiles"."role" = ANY (ARRAY['teacher'::"text", 'admin'::"text"])))))));



