CREATE POLICY "All authenticated users can view schedules" ON "public"."meeting" FOR SELECT TO "authenticated" USING (
CASE
    WHEN ("kind" = 'schedule'::"text") THEN true
    WHEN ("kind" = 'event'::"text") THEN true
    WHEN ("kind" = 'personal'::"text") THEN (EXISTS ( SELECT 1
       FROM "public"."user_resource" "ur"
      WHERE (("ur"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("ur"."resource_id" = "meeting"."created_by"))))
    WHEN ("kind" = ANY (ARRAY['duty'::"text", 'document_submission'::"text", 'training'::"text"])) THEN ((EXISTS ( SELECT 1
       FROM "public"."user_resource" "ur"
      WHERE (("ur"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("ur"."resource_id" = "meeting"."created_by")))) OR (EXISTS ( SELECT 1
       FROM ("public"."user_resource" "ur"
         JOIN "public"."profiles" "p" ON (("p"."id" = "ur"."user_id")))
      WHERE (("ur"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("meeting"."meta" ? 'assignee'::"text") AND (("meeting"."meta" -> 'assignee'::"text") ? "p"."name")))))
    ELSE true
END);



