   FROM "public"."profiles" "p"
  WHERE (("p"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("p"."role" = ANY (ARRAY['teacher'::"text", 'admin'::"text"]))))));



CREATE POLICY "exam_schedule_student_read_finalized" ON "public"."exam_schedule" FOR SELECT TO "authenticated" USING ((("status" = 'finalized'::"text") AND (EXISTS ( SELECT 1
   FROM ("public"."resource" "r"
     JOIN "public"."user_resource" "ur" ON (("ur"."resource_id" = "r"."id")))
  WHERE (("ur"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("r"."type" = 'student'::"text") AND (COALESCE((("r"."meta" ->> 'grade'::"text"))::integer, '-1'::integer) = "exam_schedule"."grade"))))));



CREATE POLICY "exam_schedule_update_owner_or_admin" ON "public"."exam_schedule" FOR UPDATE TO "authenticated" USING (((EXISTS ( SELECT 1
   FROM "public"."profiles" "p"
  WHERE (("p"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("p"."role" = 'admin'::"text")))) OR (EXISTS ( SELECT 1
   FROM "public"."user_resource" "ur"
  WHERE (("ur"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("ur"."resource_id" = "exam_schedule"."created_by")))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM "public"."profiles" "p"
  WHERE (("p"."id" = ( SELECT "auth"."uid"() AS "uid")) AND ("p"."role" = 'admin'::"text")))) OR (EXISTS ( SELECT 1
   FROM "public"."user_resource" "ur"
  WHERE (("ur"."user_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("ur"."resource_id" = "exam_schedule"."created_by"))))));



COMMENT ON POLICY "exam_schedule_update_owner_or_admin" ON "public"."exam_schedule" IS '소유 교사 또는 admin만 update 가능. 임의 교사가 다른 교사의 시간표를 finalized로 바꿀 수 없도록 제한.';



